package com.follower;

import java.util.*;
import java.util.List;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.api.Model;
import net.runelite.api.kit.KitType;
import lombok.RequiredArgsConstructor;
import java.util.Set;

/**
 * Rebuilds a player model from its parts, the same way the game does: load each
 * worn model and body kit model from the cache, apply that part's colour and
 * texture replacements, merge everything, then light it.
 *
 * <p>Must be called on the client thread.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
class AppearanceComposer
{

	final Client client;
	final ModelRepository repository;

	/**
	 * Women's worn models that Jagex rigged to the wrong arm, by item id, with
	 * how far the woman's model sits from the man's.
	 *
	 * <p>An animation moves a model by the labels on its vertices, so a model
	 * labelled for one arm goes wherever that arm goes. The charting quill's
	 * woman's model (59225) is the man's (59224) moved by (0, 7, -1), vertex
	 * for vertex, but labelled for the right hand (27) where the man's is
	 * labelled for the left hand (161). Writing with a quill (13302) writes
	 * with the left hand and holds the scroll still in the right, so on a woman
	 * the quill stayed by the scroll while the empty hand wrote; a woman in the
	 * game gets the same. The man's model is drawn instead, moved to where the
	 * woman's sits, which is her quill on his labels. Every other item a pose
	 * puts in a hand was checked against the cache: none has its two models on
	 * different arms. Both models of the quill sit at offset 0.
	 */
	static final java.util.Map<Integer, int[]> FEMALE_FROM_MALE =
		java.util.Collections.singletonMap(31829, new int[]{0, 7, -1});

	/**
	 * @return a composed model, or null if the dump is missing or has no data for
	 * any of the outfit's slots (caller should fall back to capture).
	 */
	Model compose(Outfit outfit)
	{
		return compose(outfit, null);
	}

	/**
	 * As {@link #compose(Outfit)}, noting in {@code downloading} each model it
	 * went without because the client does not have it yet. A model the client
	 * has never drawn is fetched from the game's servers: the first ask starts
	 * the download and gets nothing, and an ask once it has landed gets it.
	 */
	Model compose(Outfit outfit, List<Integer> downloading)
	{
		if (!repository.isLoaded())
			return null;

		var resolved = outfit.withDefaultBody();
		List<ModelData> parts = new ArrayList<>();

		// Body kits hidden by the gear on top of them.
		var hidden = hiddenSlots(resolved);

		for (var slot : KitType.values())
		{
			int raw = resolved.getRaw(slot);
			if (raw == 0)
				continue;

			// Skip whatever the gear covers: the arms under a platebody, the hair and
			// beard under a full helm, the shield behind a two-hander. Drawing both is
			// what pushes one through the other.
			if (hidden.contains(slot))
				continue;

			boolean item = raw >= Outfit.ITEM_OFFSET;
			int id = item ? raw - Outfit.ITEM_OFFSET : raw - Outfit.KIT_OFFSET;
			var entry = item ? repository.item(id) : repository.kit(id);

			if (entry == null)
				continue;

			// Parts stay in their authored source colours; body colouring happens
			// post-merge via the palette tables, exactly as the client does it.
			int before = parts.size();
			// A woman's model rigged to the wrong arm is drawn from the man's.
			int[] rerig = item && resolved.getGender() == 1 ? FEMALE_FROM_MALE.get(id) : null;
			addPart(parts, entry, rerig != null ? 0 : resolved.getGender(), downloading);
			if (rerig != null)
			{
				for (int i = before; i < parts.size(); i++)
					parts.set(i, parts.get(i).cloneVertices().translate(rerig[0], rerig[1], rerig[2]));
			}
		}

		// The ground clearance offset is applied when positioning, not baked into the
		// vertices - it belongs in world space alongside the terrain height, and this
		// keeps the composed model reusable across positions.
		return mergeAndLight(parts, resolved, 850 /* CONTRAST */, -30 /* LIGHT_X */, -50 /* LIGHT_Y */, -30 /* LIGHT_Z */);
	}

	/**
	 * Merges the parts, colours the body through the palette tables and lights
	 * the result; null when there is nothing to merge.
	 */
	Model mergeAndLight(List<ModelData> parts, Outfit resolved, int contrast, int x, int y, int z)
	{
		var merged = parts.isEmpty() ? null : client.mergeModels(parts.toArray(new ModelData[0]));
		if (merged == null)
			return null;
		// AMBIENT: Lighting applied to the composed model. Verified 2026-08-02 against the
		// deobfuscated client: PlayerComposition builds the player with
		// {@code toModel(64, 850, -30, -50, -30)}, matching these exactly.
		return applyBodyColors(merged, resolved.getColors()).light(64 /* AMBIENT */, contrast, x, y, z);
	}

	/**
	 * Composes the outfit's dialogue chathead: the game's own separate head models
	 * (helm head variant, hair chathead, jaw chathead), coloured through the same
	 * palette as the body and lit the same way. These models carry the skeletons
	 * that talk animations are authored for, which the body model does not.
	 *
	 * <p>Notes in {@code downloading}, as {@link #compose(Outfit, List)} does,
	 * each head model it went without because the client is still fetching it.
	 *
	 * @return the lit chathead, or null when the dump has no head data for this
	 * outfit (caller should fall back to cropping the body model)
	 */
	Model composeChathead(Outfit outfit, List<Integer> downloading)
	{
		if (!repository.isLoaded() || outfit == null)
			return null;

		var resolved = outfit.withDefaultBody();
		var hidden = hiddenSlots(resolved);
		List<ModelData> parts = new ArrayList<>();

		// Same wearPos rules as the body: a full helm hides hair and jaw in the
		// dialogue head too; a med helm hides hair but keeps the beard.
		if (resolved.isItem(KitType.HEAD))
			addHeadPart(parts, repository.item(resolved.itemId(KitType.HEAD)), resolved.getGender(), downloading);
		for (var slot : new KitType[]{KitType.HAIR, KitType.JAW})
		{
			if (!hidden.contains(slot) && resolved.isKit(slot))
				addHeadPart(parts, repository.kit(resolved.kitId(slot)), resolved.getGender(), downloading);
		}

		// WIDGET_CONTRAST: Interface models are lit DIFFERENTLY from actors - verified in the client:
		// widget models get {@code calculateNormals(64, 768, -50, -10, -50)}, a softer
		// contrast and a front-left light, where actors get {@code (64, 850, -30,
		// -50, -30)}. Lighting a chathead with the actor constants is what made it
		// shade differently from a real dialog's head.
		return mergeAndLight(parts, resolved, 768 /* WIDGET_CONTRAST */, -50 /* WIDGET_LIGHT_X */, -10 /* WIDGET_LIGHT_Y */, -50 /* WIDGET_LIGHT_Z */);
	}

	/** Loads an entry's dialogue-head models with its authored recolours applied. */
	void addHeadPart(List<ModelData> parts, ModelRepository.Entry entry, int gender,
		List<Integer> downloading)
	{
		int[] modelIds = entry == null ? null : entry.headModels(gender);
		if (modelIds == null)
			return;

		for (int modelId : modelIds)
		{
			var data = modelId < 0 ? null : client.loadModelData(modelId);
			if (data != null)
				parts.add(entry.recolour(data));
			else if (modelId >= 0 && downloading != null)
				downloading.add(modelId);
		}
	}


	/**
	 * Body-kit slots covered by the equipped gear, taken from each item's wearPos data.
	 *
	 * <p>This is how the game itself decides what to draw. An item declares the slot it
	 * occupies plus up to two more that it <em>hides</em>: a platebody hides the arms
	 * kit, a full helm hides both hair and jaw. Around 2,200 of the 6,300 wearable items
	 * hide something.
	 *
	 * <p>This replaces a single hardcoded rule - "a torso item hides the arms" - which
	 * covered one case out of many and left helmets rendering hair straight through
	 * themselves.
	 *
	 * <p>An animation's hand prop ({@link Outfit#isProp}) is outside the rule: the
	 * game lays it over the gear after the gear has decided what it covers. A felling
	 * axe declares the shield slot hidden, and the axe of a two-handed chop is drawn
	 * in that very slot; the banana a follower eats goes in the shield slot its own
	 * godsword hides.
	 */
	Set<KitType> hiddenSlots(Outfit outfit)
	{
		Set<KitType> hidden = java.util.EnumSet.noneOf(KitType.class);
		var slots = KitType.values();

		for (var slot : slots)
		{
			if (!outfit.isItem(slot) || outfit.isProp(slot))
				continue;

			var entry = repository.item(outfit.itemId(slot));
			if (entry == null)
				continue;

			for (var covered : new Integer[]{entry.wp2, entry.wp3})
			{
				if (covered != null && covered >= 0 && covered < slots.length)
					hidden.add(slots[covered]);
			}
		}

		hidden.removeIf(outfit::isProp);
		return hidden;
	}

	void addPart(List<ModelData> parts, ModelRepository.Entry entry, int gender, List<Integer> downloading)
	{
		int[] modelIds = entry.models(gender);
		if (modelIds == null)
			return;

		for (int modelId : modelIds)
		{
			if (modelId < 0)
				continue;

			var data = client.loadModelData(modelId);
			if (data == null)
			{
				if (downloading != null)
					downloading.add(modelId);
				continue;
			}

			data = entry.recolour(data);

			// Each worn model carries a vertical offset that positions it against the
			// body. Merging without it leaves every piece at its raw origin, so
			// neighbouring pieces sit slightly wrong and clip into one another.
			int offset = entry.offset(gender);
			if (offset != 0)
			{
				data = data.cloneVertices();
				data.translate(0, offset, 0);
			}

			parts.add(data);
		}
	}

	/** Whether any of these models, missing from an earlier build, has landed since. */
	boolean anyArrived(List<Integer> modelIds)
	{
		for (int modelId : modelIds)
		{
			if (client.loadModelData(modelId) != null)
				return true;
		}
		return false;
	}

	/** Applies the five body-colour indices through the game's own palette tables. */
	ModelData applyBodyColors(ModelData merged, int[] colorIndices)
	{
		if (colorIndices == null)
			return merged;

		merged = merged.cloneColors();
		for (int slot = 0; slot < colorIndices.length && slot < 5; slot++)
		{
			short[] table = GamePalette.table(slot);
			int index = colorIndices[slot];
			if (table == null || index < 0 || index >= table.length)
				continue;

			// Each table replaces its own first entry, the default colour.
			merged.recolor(table[0], table[index]);
			if (slot == 0 && index < GamePalette.HAIR_HIGHLIGHT.length)
				// The highlight is its own authored colour with its own table entry,
				// never derived from the base - deriving it is what kept hair
				// almost-but-not-quite right for months.
				merged.recolor(GamePalette.HAIR_HIGHLIGHT_FIND, GamePalette.HAIR_HIGHLIGHT[index]);
		}

		return merged;
	}
}

package com.follower;

import java.util.*;
import java.util.List;
import java.util.function.Consumer;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Model;

/**
 * Turns an {@link Outfit} into a {@link ComposedAppearance}, preferring the cache
 * dump and falling back to live capture. Results are memoised on the outfit, so
 * an unchanged outfit costs nothing per frame.
 *
 * <p>Client thread only.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
class AppearanceService
{
	/**
	 * How long a look watches for the models it went without, in game ticks:
	 * a minute, well past a slow first download. An id that never loads is
	 * given up on then.
	 */
	static final int WAIT_TICKS = 100;

	final AppearanceComposer composer;

	@Getter
	ComposedAppearance current;

	/**
	 * The models the last build went without because the client was still
	 * fetching them, the look that wait is for, and the ticks left of it.
	 */
	List<Integer> downloading = Collections.emptyList();
	Outfit waitingFor;
	int waitTicks;

	/**
	 * Requests an appearance for {@code outfit}. The callback fires immediately for
	 * the cached and dump paths, or a frame later for the capture path. It may
	 * receive null if neither path could produce a model. It does not fire while
	 * every model the outfit needs is still downloading: the follower stays as it
	 * is until {@link #partsArrived} says one has landed.
	 */
	void request(Outfit outfit, Consumer<ComposedAppearance> onReady)
	{
		// A look built without some of its models is not reused: building it
		// again is what puts them on once they have landed.
		if (current != null && downloading.isEmpty() && current.getOutfit().equals(outfit))
		{
			onReady.accept(current);
			return;
		}
		List<Integer> missing = new ArrayList<>();
		var model = composer.compose(outfit, missing);
		downloading = missing;
		if (!missing.isEmpty() && !outfit.equals(waitingFor))
		{
			// One wait per look: building the same look again does not start it over.
			waitingFor = new Outfit(outfit);
			waitTicks = WAIT_TICKS;
		}
		if (model != null)
		{
			publish(new ComposedAppearance(model, outfit), onReady);
			return;
		}
		if (!missing.isEmpty())
			return;
		log.warn("No model data for outfit {} and fallback is disabled", outfit);
		onReady.accept(null);
	}

	/**
	 * Whether a model the last build went without has landed since, so the look
	 * should be built again. Asked once a tick; a look is watched for
	 * {@link #WAIT_TICKS} at most.
	 */
	boolean partsArrived()
	{
		if (downloading.isEmpty() || waitTicks <= 0)
			return false;
		waitTicks--;
		return composer.anyArrived(downloading);
	}

	void publish(ComposedAppearance appearance, Consumer<ComposedAppearance> onReady)
	{
		current = appearance;
		onReady.accept(appearance);
	}

	void invalidate()
	{
		current = null;
		downloading = Collections.emptyList();
		waitingFor = null;
	}
}

package com.follower;

import java.util.*;
import java.util.Set;
import net.runelite.api.PlayerComposition;
import lombok.RequiredArgsConstructor;

/**
 * The follower borrowing one of the player's tools for a work session, and
 * giving it back.
 *
 * <p>One item at a time, through the same transient-prop path the scroll
 * uses ({@link ErrandController.Hands}): the item is overlaid on the outfit
 * at compose time and never persisted, so the stance follows whatever is in
 * the hand for free. Because the scroll and a tool share the weapon slot, a
 * borrow refuses to start over a held scroll and the scroll flourish refuses
 * to start over a held tool - see {@link PropFlourish#start}.
 *
 * <p>Two ways out. A session that ran long enough earns a beat on the way
 * out - a bow, or a salute for a hat - and the item goes back on the same
 * frame, since a rebuild mid-emote is safe. Every abort path releases
 * silently, and {@link #abort} is idempotent because it runs from all of
 * them whether or not anything is held.
 */
@RequiredArgsConstructor
class Borrow
{
	/** Proven on the follower: two rules already play it. */
	static final int BOW_ANIMATION = 858;

	/** Whether an animation is farming work: the patch's own, not a bite to eat. */
	static boolean farmingWork(int animationId)
	{
		return SkillingController.values("tool.farming." + animationId) != null;
	}

	/** The tool for a farming animation; secateurs when it is not one we know. */
	static int farmingTool(int animationId)
	{
		return toolFor("farming", animationId, null);
	}

	/**
	 * Every harpoon swing and every rod cast the cache names, the tables' own
	 * and the rest, a dragon harpoon's or a pearl rod's: skilling.properties.
	 */
	static final Set<Integer> HARPOONING = SkillingController.idSet("harpooning"),
		ROD_FISHING = SkillingController.idSet("rodFishing");

	final FollowerEntity follower;
	final ErrandController.Hands hands;

	int held;

	/** The hat worn alongside, or 0: the second prop, which is not the hand. */
	int hat;

	/** True while the borrowed item is out of the hands, but still on loan. */
	boolean aside;

	/** Whether the hand has a tool in it; a hat alone is not holding. */
	boolean isHolding()
	{
		return held != 0;
	}

	int heldItem()
	{
		return held;
	}

	boolean hasHat()
	{
		return hat != 0;
	}

	/** Whether anything at all is on loan, in the hand or on the head. */
	boolean isBorrowing()
	{
		return held != 0 || hat != 0;
	}

	/**
	 * Puts the hat on. Its own slot, so it goes over a held tool and never
	 * argues with the scroll.
	 *
	 * @return whether it is now worn; false when the hands decline it
	 */
	boolean wearHat(int itemId)
	{
		if (itemId <= 0 || hat != 0 || hands.isWearing())
			return false;
		hands.wear(itemId);
		if (!hands.isWearing())
			return false;
		hat = itemId;
		return true;
	}

	/**
	 * Takes the item, unless the hands are already full - a tool already
	 * borrowed, or the scroll out for something else.
	 *
	 * @return whether it is now held. False also covers an item the cache has
	 * no wear position for, which the hands quietly decline
	 */
	boolean start(int itemId)
	{
		if (itemId <= 0 || held != 0 || hands.isHolding())
			return false;
		hands.hold(itemId);
		if (!hands.isHolding())
			return false;
		held = itemId;
		return true;
	}

	/**
	 * Gives the item back.
	 *
	 * @param withBeat whether the session was long enough to be worth a bow -
	 * a salute when only a hat was borrowed. The release lands on the same
	 * frame as the emote starts; the caller keeps the feet still while it plays
	 */
	void giveBack(boolean withBeat)
	{
		giveBack(withBeat, 0);
	}

	/**
	 * As {@link #giveBack(boolean)}, with something to play first.
	 *
	 * @param leadIn an animation the beat follows on from - the stand-up,
	 * when the follower was sitting - or 0 for none
	 */
	void giveBack(boolean withBeat, int leadIn)
	{
		if (held == 0 && hat == 0)
			return;
		if (withBeat)
		{
			// A tool is handed back with a bow; a hat on its own is saluted.
			// SALUTE_ANIMATION: Proven by the mirror rules, which copy it onto the follower.
			int beat = held == 0 ? 2112 /* SALUTE_ANIMATION */ : BOW_ANIMATION;
			if (leadIn > 0)
			{
				follower.playAnimations(new int[]{leadIn, beat});
			}
			else
				follower.playAnimation(beat);
		}
		if (hat != 0)
		{
			hat = 0;
			hands.takeOff();
		}
		boolean hadTool = held != 0;
		held = 0;
		if (aside)
		{
			// Set aside: what is in the hands belongs to somebody else, and
			// releasing it here would take their scroll away.
			aside = false;
			return;
		}
		if (hadTool)
			hands.release();
	}

	/**
	 * Puts the borrowed item down for a moment so the hands can hold
	 * something else - the scroll, for a read of the notes - without giving
	 * it back. The session still has it on loan, and {@link #takeBack}
	 * returns it to the hand.
	 *
	 * @return whether there was something in the hands to put down
	 */
	boolean setAside()
	{
		if (held == 0 || aside)
			return false;
		aside = true;
		hands.release();
		return true;
	}

	/**
	 * Changes the tool in the hand to another - the rake for the dibber as
	 * the work at the patch moves on - or empties the hand for 0. While it is
	 * set aside the hand is somebody else's, so only the loan changes, and
	 * the right tool - or none - comes back with {@link #takeBack}.
	 */
	void swap(int itemId)
	{
		if (held == itemId)
			return;
		if (aside)
		{
			held = Math.max(itemId, 0);
			aside = held != 0;
			return;
		}
		if (held != 0)
		{
			held = 0;
			hands.release();
		}
		if (itemId > 0)
			start(itemId);
	}

	/** Takes a set-aside item back, once whatever borrowed the hands is done. */
	void takeBack()
	{
		if (held == 0 || !aside)
			return;
		aside = false;
		hands.hold(held);
		if (!hands.isHolding())
			// Refused on the way back, which the outward hold makes unlikely;
			// the loan is over rather than pending forever.
			held = 0;
	}

	/** The silent release, for every abort path. Safe with nothing held. */
	void abort()
	{
		giveBack(false);
	}

	/**
	 * Which of the player's tools a session would borrow, or 0 for none,
	 * preferring whatever is actually in their weapon hand.
	 *
	 * <p>The id tables below cannot help but fall behind the game: a dragon
	 * felling axe was borrowed as a bronze one for exactly that reason. So
	 * the hand is asked first, by NAME, which no update can invalidate, and
	 * the tables are what answers when the tool is in the bag rather than
	 * the hand. A battleaxe is not a felling axe, whatever it ends in.
	 *
	 * @param wornWeapon the item in the player's weapon slot, or 0
	 * @param wornWeaponName that item's name, or null when it cannot be read
	 */
	static int toolFor(String activity, int animationId, Set<Integer> worn,
		int wornWeapon, String wornWeaponName)
	{
		if (wornWeapon > 0 && wornWeaponName != null && activity != null)
		{
			String name = wornWeaponName.toLowerCase(Locale.ROOT);
			boolean pickaxe = name.contains("pickaxe");
			boolean fighting = name.contains("battleaxe") || name.contains("greataxe")
				|| name.contains("thrownaxe") || name.contains("poleaxe");
			switch (activity)
			{
				case "woodcutting":
					if (name.endsWith("axe") && !pickaxe && !fighting)
						return wornWeapon;
					break;
				case "mining":
					if (pickaxe)
						return wornWeapon;
					break;
				case "fishing":
					// A harpoon left on through a cage or a net is still called
					// a harpoon, so the name answers only for its own kind of
					// swing, or for one nothing here knows at all. A weapon
					// called a rod, the rod of ivandis, is no fishing rod.
					boolean rod = name.contains("fishing rod") || name.contains("barbarian rod");
					boolean unknown = toolFor(activity, animationId, worn) == 0
						&& !HARPOONING.contains(animationId) && !ROD_FISHING.contains(animationId);
					if ((name.contains("harpoon") && (unknown || HARPOONING.contains(animationId)))
						|| (rod && (unknown || ROD_FISHING.contains(animationId))))
						return wornWeapon;
					break;
				default:
					break;
			}
		}
		return toolFor(activity, animationId, worn);
	}

	/**
	 * The same question with nothing known about the hand: skilling.properties'
	 * tool row, the one worn when it is worn, the first, the bronze one, when
	 * it is not. Where the work alone cannot say - "Fish" says nothing about
	 * the hand - the row for the animation picks it; 0 is bare hands.
	 */
	static int toolFor(String activity, int animationId, Set<Integer> worn)
	{
		int[] tiers = SkillingController.ids("tool." + activity + "." + animationId);
		if (tiers == null)
			tiers = SkillingController.ids("tool." + activity);
		return tiers == null ? 0 : wornOr(worn, tiers);
	}

	/**
	 * The hat a session would borrow, or 0: the hat of the skilling outfit
	 * for that work, when the player has the whole set on - skilling.properties'
	 * outfit row, the hat first, then the body, the legs and the boots. Only
	 * the hat - the rest stays where it is - and it takes the place of the
	 * tool, since the hands hold one thing.
	 */
	static int hatFor(String activity, Set<Integer> worn)
	{
		int[] outfit = SkillingController.ids("outfit." + activity);
		if (outfit == null || worn == null)
			return 0;
		for (int piece : outfit)
		{
			if (!worn.contains(piece))
				return 0;
		}
		return outfit[0];
	}

	/** The first of the tiers that is worn, or the first tier, the bronze one, when none is. */
	static int wornOr(Set<Integer> worn, int[] tiers)
	{
		if (worn != null)
		{
			for (int id : tiers)
			{
				if (worn.contains(id))
					return id;
			}
		}
		return tiers[0];
	}

	/**
	 * The item in the player's weapon hand, or 0 when the hand is empty or
	 * the composition is not there to ask.
	 */
	static int wornWeapon(PlayerComposition composition)
	{
		if (composition == null)
			return 0;
		int raw = composition.getEquipmentId(net.runelite.api.kit.KitType.WEAPON);
		// getEquipmentId already takes the offset off; a kit id or an empty
		// hand comes back as 0 or -1.
		return raw > 0 ? raw : 0;
	}

	/** Worn item ids off a composition, the way the trigger context reads them. */
	static Set<Integer> wornItems(PlayerComposition composition)
	{
		Set<Integer> worn = new HashSet<>();
		int[] ids = composition == null ? null : composition.getEquipmentIds();
		if (ids != null)
		{
			for (int raw : ids)
			{
				if (raw >= PlayerComposition.ITEM_OFFSET)
					worn.add(raw - PlayerComposition.ITEM_OFFSET);
			}
		}
		return worn;
	}
}

package com.follower;

import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import net.runelite.api.Model;
import static java.lang.Math.*;

/**
 * Renders a model to an image, in software.
 *
 * <p>Chathead widgets can only show models the cache already holds - a widget
 * takes a model ID, and there is no way to hand it a composed one - so the
 * follower's own head is unreachable through the game's dialog interface. It is
 * reachable this way: the model exposes its vertices, faces and already-lit face
 * colours, so projecting and filling the triangles here produces a real picture
 * of the actual follower rather than a stand-in.
 *
 * <p>Uses the client's own widget-model camera - perspective, orbited to the
 * dialog's pitch at its zoom - with painter's-algorithm depth sorting, and fills
 * triangles through {@link GouraudRasterizer}, a faithful port of the client's
 * integer scanline rasterizer, so the pixels come out the way the game's own
 * renderer produces them - down to which pixels a two-pixel pupil covers. */
class ChatheadRenderer
{

	/**
	 * The client's own chathead camera, read off live dialog widgets.
	 *
	 * <p>The head's angle arrives as the widget's rotationZ, but it drives THIS
	 * renderer's yaw: RuneLite's rotationZ is the axis that turns a chathead in
	 * the client's widget pipeline. NPC dialogs use 1882 and player dialogs 166 -
	 * exact mirrors (1882 = 2048 - 166), which is why an NPC and your own
	 * character face opposite ways. Applying it as a true Z-roll instead tilts the
	 * head sideways in the image plane, which is visibly wrong.
	 */
	static final int GAME_PITCH = 40,
		GAME_TURN_NPC = 1882,
		GAME_TURN_PLAYER = 166,
		GAME_ZOOM = 796;

	/** The client's projection: screen = model * 512 / depth. */
	static final double FOCAL_LENGTH = 512;

	/**
	 * @param model        the (possibly posed) model to draw
	 * @param boundsFrom   model to compute framing from, or null to use
	 *                     {@code model}. An animated head is framed by its UNPOSED
	 *                     base so the picture doesn't rescale as the jaw moves.
	 * @param yaw          model rotation about the vertical axis, in JAU - the
	 *                     widget's rotationY
	 * @param cameraPitch  the widget's rotationX. NOT a model tilt: the client
	 *                     orbits the CAMERA to this pitch at {@code zoom} distance
	 * @param zoom         camera distance, the widget's modelZoom
	 * @param headFraction share of the model's height, from the top, to include;
	 *                     1.0 draws the whole model (a real chathead model)
	 * @param anchorX      pixel where the model's ORIGIN projects, or -1 for centre.
	 *                     The client anchors widget models at the widget's centre and
	 *                     lets geometry overflow, clipped by the interface surface -
	 *                     which is how tall hair gets cut at the dialog's top edge.
	 * @return the rendered image, or null if the model cannot be drawn
	 */
	static BufferedImage render(Model model, Model boundsFrom, int width, int height,
		int yaw, int cameraPitch, int zoom, double headFraction, int anchorX, int anchorY)
	{
		if (model == null || width <= 0 || height <= 0)
			return null;
		var frame = boundsFrom == null ? model : boundsFrom;

		float[] vx = model.getVerticesX(),
			vy = model.getVerticesY(),
			vz = model.getVerticesZ(),
			fx = frame.getVerticesX(),
			fy = frame.getVerticesY();
		int[] fa = model.getFaceIndices1(),
			fb = model.getFaceIndices2(),
			fc = model.getFaceIndices3(),
			colors = model.getFaceColors1();

		if (vx == null || vy == null || vz == null || fx == null || fy == null
			|| fa == null || fb == null || fc == null || colors == null)
			return null;

		int verts = min(model.getVerticesCount(), vx.length);
		if (min(frame.getVerticesCount(), fx.length) != verts)
			// A frame reference must be the same geometry (the unposed original).
			return null;

		// The client's exact widget-model camera, from its drawInterface:
		//     eyeY = sin(rotationX) * zoom;  eyeZ = cos(rotationX) * zoom
		//     objRender(0, rotationY, 0, rotationX, 0, eyeY, eyeZ)
		// So the model is yawed, pushed out to `zoom`, and viewed by a camera
		// ORBITED to pitch rotationX - with a perspective divide. Approximating
		// that as a model-space tilt with an orthographic projection is what made
		// the framing need a fudged yaw to look right.
		double yawAngle = yaw / 2048.0 * 2.0 * PI,
			yawSin = sin(yawAngle),
			yawCos = cos(yawAngle),
			pitchAngle = cameraPitch / 2048.0 * 2.0 * PI,
			pitchSin = sin(pitchAngle),
			pitchCos = cos(pitchAngle),
			eyeY = pitchSin * zoom,
			eyeZ = pitchCos * zoom;

		// The client's own projection scale, not a fit-to-box. Widget models are
		// drawn at a fixed focal length about the model's ORIGIN, and they
		// overflow their widget rectangle freely - the real chathead widget is
		// 32x32 while the head it draws is far bigger. Fitting to a box instead
		// made size a guess; this makes it a consequence of zoom, exactly as in
		// game.
		int offsetX = anchorX < 0 ? width / 2 : anchorX,
			offsetY = anchorY < 0 ? height / 2 : anchorY;
		// vertexScreenZ, the client's convention: camera depth relative to the
		// model origin's depth (midZ), an INTEGER per vertex.
		double midZ = eyeY * pitchSin + eyeZ * pitchCos;

		float[] rz = new float[verts];
		int[] sx = new int[verts],
			sy = new int[verts],
			sz = new int[verts];
		float minY = Float.MAX_VALUE,
			maxY = -Float.MAX_VALUE;
		// The client's calculateBoundsCylinder, for the depth-bucket range.
		double boundMaxY = 0,
			boundMinY = 0,
			radiusSqr = 0;
		for (int i = 0; i < verts; i++)
		{
			// One vertex through the client's widget-model transform: yaw the
			// model, push it to the camera distance, orbit the camera to its
			// pitch, then divide by depth.
			double x = vz[i] * yawSin + vx[i] * yawCos,
				z = vz[i] * yawCos - vx[i] * yawSin + eyeZ,
				y = vy[i] + eyeY,
				cy = y * pitchCos - z * pitchSin,
				cz = y * pitchSin + z * pitchCos;
			// Behind or level with the camera: park it far away rather than
			// divide by zero; such faces are dropped by the depth guard below.
			boolean behind = cz < 1;
			rz[i] = behind ? -1 : (float) cz;
			// Screen coordinates the client's way: vertexScreenX = centerX +
			// (x << 9) / z, truncated to an INTEGER per vertex before any face
			// is drawn. The rasterizer walks scanlines between these ints;
			// feeding it float pixel centres instead dropped the sub-pixel eye
			// faces.
			sx[i] = offsetX + (int) ((behind ? 0 : (float) (x / cz)) * FOCAL_LENGTH);
			sy[i] = offsetY + (int) ((behind ? 0 : (float) (cy / cz)) * FOCAL_LENGTH);
			sz[i] = (int) (rz[i] - midZ);

			minY = min(minY, fy[i]);
			maxY = max(maxY, fy[i]);
			boundMaxY = max(boundMaxY, -vy[i]);
			boundMinY = max(boundMinY, vy[i]);
			radiusSqr = max(radiusSqr, vx[i] * vx[i] + vz[i] * vz[i]);
		}
		float cutoff = minY + (maxY - minY) * (float) headFraction;
		int radius = (int) (sqrt(radiusSqr) + 0.99),
			minDepth = (int) (sqrt(radius * radius + boundMaxY * boundMaxY) + 0.99),
			maxDepth = minDepth + (int) (sqrt(radius * radius + boundMinY * boundMinY) + 0.99);

		// Gouraud shading, the way the game itself draws models: each face carries
		// three per-corner lit colours (faceColors1/2/3), blended across the
		// triangle. Flat-filling with colours1 alone is what made every triangle
		// edge visible and the lighting angular. No antialiasing either - the
		// game's rasterizer has none, and crisp edges are part of the look.
		int[] colors2 = model.getFaceColors2(),
			colors3 = model.getFaceColors3();

		// Faces wholly inside the head region OF THE FRAME model, skipping ones
		// the client hides. Using the frame keeps face selection stable across
		// animation frames.
		//
		// The client's draw2 ordering, not a painter's sort. Faces get INTEGER
		// average depths ((zA+zB+zC)/3 + minDepth) and draw far to near, in
		// face-index order within one depth. Model authors rely on that: a pupil
		// sits coplanar ON the eye-white face and is authored LATER in face order
		// so the same depth draws it on top. Sorting by exact float depth instead
		// let the eye-white face land on top of the pupil on some animation
		// frames - the stray white pixels in the eyes.
		//
		// Backface culling happens before that, with the client's own test on the
		// same INTEGER screen coordinates it rasterises with. Without it the BACK
		// of the head - lit from behind, darker - bled through along cheeks and
		// brow as triangular patches.
		boolean anyInHead = false;
		int[] depth = new int[fa.length];
		List<Integer> faces = new ArrayList<>();
		for (int i = 0; i < fa.length; i++)
		{
			int a = fa[i],
				b = fb[i],
				c = fc[i];
			if ((colors3 != null && i < colors3.length && colors3[i] == -2)
				|| a >= verts || b >= verts || c >= verts || a < 0 || b < 0 || c < 0
				|| !(fy[a] <= cutoff && fy[b] <= cutoff && fy[c] <= cutoff))
				continue;
			anyInHead = true;
			if (rz[a] < 0 || rz[b] < 0 || rz[c] < 0
				|| (sx[a] - sx[b]) * (sy[c] - sy[b]) - (sy[a] - sy[b]) * (sx[c] - sx[b]) <= 0)
				continue;
			depth[i] = max(0, min(maxDepth, (sz[a] + sz[b] + sz[c]) / 3 + minDepth));
			faces.add(i);
		}
		if (!anyInHead)
			return null;
		// Stable, so faces at one depth keep their face-index order.
		faces.sort((p, q) -> depth[q] - depth[p]);

		int[] pixels = new int[width * height];
		var raster = new GouraudRasterizer(pixels, width, height);

		for (int face : resolveDrawOrder(model.getFaceRenderPriorities(), faces, depth))
		{
			int a = fa[face],
				b = fb[face],
				c = fc[face];

			// colours3 == -1 flags a flat-shaded face: all corners take colours1.
			// Corners stay PACKED - the client interpolates the palette index
			// across the triangle and looks the table up per pixel, and matching
			// its colours means doing the same. Corner colours pair with vertices
			// A/B/C directly, exactly as the client's drawFace passes them.
			boolean flat = colors3 == null || colors3[face] == -1;
			int colourA = colors[face] & 0xFFFF,
				colourB = flat || colors2 == null ? colourA : colors2[face] & 0xFFFF,
				colourC = flat ? colourA : colors3[face] & 0xFFFF;

			raster.gouraudTriangle(sx[a], sx[b], sx[c], sy[a], sy[b], sy[c],
				colourA, colourB, colourC);
		}

		var image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		image.setRGB(0, 0, width, height, pixels, 0, width);
		return image;
	}

	/**
	 * The client's draw2 emission order. Without per-face render priorities:
	 * far to near, as sorted. With priorities: the client's 12-class algorithm
	 * - faces collect into priority classes in depth order, classes 0..9 emit
	 * in class order, and the special classes 10 and 11 (all of 10, then all of
	 * 11) cut into the stream whenever their next face is deeper than the
	 * running depth averages of classes 1+2 (checked before class 0), 3+4
	 * (before class 3), and 6+8 (before class 5), with the leftovers emitted at
	 * the end. Player and NPC models rely on this to layer coplanar detail
	 * correctly.
	 */
	static List<Integer> resolveDrawOrder(byte[] priorities, List<Integer> faces, int[] depth)
	{
		if (priorities == null)
			return faces;

		int[][] classes = new int[12][faces.size()];
		int[] counts = new int[12],
			depthSums = new int[12];
		for (int face : faces)
		{
			int priorityClass = max(0, min(11, priorities[face]));
			classes[priorityClass][counts[priorityClass]++] = face;
			depthSums[priorityClass] += depth[face];
		}
		int[] special = Arrays.copyOf(classes[10], counts[10] + counts[11]);
		System.arraycopy(classes[11], 0, special, counts[10], counts[11]);

		List<Integer> order = new ArrayList<>(faces.size());
		int next = 0;
		for (int priority = 0; priority <= 10; priority++)
		{
			int deeperThan = priority == 0 ? average(counts, depthSums, 1, 2)
				: priority == 3 ? average(counts, depthSums, 3, 4)
				: priority == 5 ? average(counts, depthSums, 6, 8)
				: priority == 10 ? -1 : Integer.MAX_VALUE;
			while (next < special.length && depth[special[next]] > deeperThan)
				order.add(special[next++]);
			for (int i = 0; priority < 10 && i < counts[priority]; i++)
				order.add(classes[priority][i]);
		}
		return order;
	}

	/** The running depth average of two priority classes, 0 when both are empty. */
	static int average(int[] counts, int[] depthSums, int first, int second)
	{
		int count = counts[first] + counts[second];
		return count > 0 ? (depthSums[first] + depthSums[second]) / count : 0;
	}

}

package com.follower;

import lombok.*;

/**
 * How much the follower talks, as a thing a player can choose.
 *
 * <p>This was a box asking for a number of milliseconds, which is a question
 * about the implementation rather than about the follower. The setting worth
 * having is the one Forspoken shipped and was widely praised for - a named
 * frequency, from barely to constantly - because "how chatty should my
 * companion be" is a preference and not a measurement.
 *
 * <p>The value is the floor between any two spoken lines. The mood scaling in
 * {@link SpeechEngine} still applies on top, so a quiet setting and a bad day
 * compound rather than fight.
 *
 * <p>Minimal exists because Quiet was not quiet enough for some people. Twelve
 * seconds between lines still allows five a minute, which reads as constant
 * to anybody who wanted the follower mostly for the company. Forty-five
 * seconds is about one remark a minute at most, and the idle wind-down scales
 * with it, so a long AFK on Minimal goes properly silent.
 */
@RequiredArgsConstructor
public enum Chattiness
{
	MINIMAL("Minimal", 45_000L),
	QUIET("Quiet", 12_000L),
	OCCASIONAL("Occasional", 6_000L),
	NORMAL("Normal", 3_000L),
	CHATTY("Chatty", 1_500L);

	final String label;
	@Getter
	final long gapMs;

	@Override
	public String toString()
	{
		return label;
	}
}

package com.follower;

import net.runelite.api.Model;
import lombok.Getter;

/**
 * A finished follower model plus what we know about it.
 *
 * <p>{@link #animatable} matters: a model composed from the cache dump is unposed,
 * so pose/idle/walk animations apply cleanly. A model captured from the local
 * player is already posed at whatever frame the client rendered, so applying a
 * second animation on top compounds the transform — those followers stand still.
 */
class ComposedAppearance
{
	@Getter
	final Model model;
	@Getter
	final Outfit outfit;

	ComposedAppearance(Model model, Outfit outfit)
	{
		this.model = model;
		this.outfit = new Outfit(outfit);
	}
}

