 *   <tr><td>xpDrop</td><td>optional {@code names} (skill names) and {@code every} - the tick of a drop; {@code {skill}} {@code {count}}</td></tr>
 *   <tr><td>workEnded</td><td>optional {@code names} (activities) - the tick a session ends; {@code {activity}} {@code {target}}</td></tr>
 *   <tr><td>targetDepleted</td><td>no fields - the session's target changed id or went; {@code {target}}</td></tr>
 *   <tr><td>bagFull / bagHalf</td><td>no fields - the last slot went, or fourteen were left (once per fill)</td></tr>
 *   <tr><td>questWitnessed</td><td>{@code quest}, optional {@code minimum} days since - the follower saw that quest finish, or its quest page has a date</td></tr>
 *   <tr><td>daysSinceSaid</td><td>{@code rule} (a once rule's id), {@code minimum} / {@code maximum} days - false until that rule has been said</td></tr>
 * </table>
 *
 * <p>{@code npcNearby} also takes {@code minimum}/{@code maximum} combat level,
 * which on their own match any NPC in that bracket, and {@code visible}, which
 * additionally requires line of sight to the player - for lines that invite
 * the player to look at the thing.
 *
 * <p>{@code chatMessage} also takes {@code from} (player|others) and {@code is}
 * (a {@link net.runelite.api.ChatMessageType} name).
 */
@Slf4j
class Condition
{
	String type;

	List<Condition> conditions;

	List<String> names;
	List<Integer> ids,
		regions;

	Integer percent,
		minimum;

	/**
	 * Whether the NPC has to be a BOSS, or has to NOT be one.
	 *
	 * <p>Three states. Left out, it does not care. True, only bosses.
	 * False, only things that are not, which is how the generic "well fought"
	 * stands aside for a boss's own send-off instead of talking over it.
	 *
	 * <p>A bigger question than any combat level, and the reason this is not
	 * just {@code minimum: 100}.
	 *
	 * <p>The level is only a proxy, and it is wrong in both directions. It was
	 * wrong for Brutus, who fights at thirty and is unmistakably a boss, so
	 * the follower neither stood clear of him nor said anything when he went
	 * down. The names the boss rules already list are the other half of the
	 * answer, and this consults both.
	 */
	Boolean boss;
	/**
	 * npcKill only: named in the boss rules, whatever its level. A level-100
	 * Slayer demon is big enough for {@code boss} but no occasion; play test,
	 * 14 Oct, the boss celebration had worn out on every demon of a task.
	 */
	Boolean namedBoss;
	Integer maximum,
		within,
		ticks,
		varbit;
	/** questVar: a varplayer, for the older quests that keep their progress in one. */
	Integer varp;
	/** questDone / questWitnessed: the quest, by its {@link net.runelite.api.Quest} constant name. */
	String quest;
	/** daysSinceSaid: the id of the one-time rule counted from. */
	String rule;
	Integer value;

	/** Fire on every Nth occurrence rather than on each one. */
	Integer every;

	/** dateIs: the day on the player's own calendar, optionally through a range. */
	Integer month,
		day,
		untilMonth,
		untilDay;

	Integer x1,
		y1,
		x2,
		y2,
		plane;

	String contains,
		regex;

	/** A named band, for conditions that read better as a word than a number. */
	String is;

	/** Which counter a tally or record condition is asking about. */
	String of;

	/** Who said it: "player" for the local player's own chat, "others" for the rest. */
	String from;

	Boolean requirePrayerActive,
		anyLoadedRegion;

	/**
	 * On {@code npcNearby}: the NPC must also have line of sight to the
	 * player, by the game's own collision rules. For lines that invite the
	 * player to LOOK - a callout at something behind a wall is worse than no
	 * callout, because one bad one teaches the player to stop checking.
	 * Opt-in per rule rather than a change to what npcNearby means, since
	 * plenty of uses are atmosphere rather than assertion.
	 */
	Boolean visible;

	transient Pattern compiledRegex;
	transient List<Pattern> compiledNames;

	/**
	 * {@link #ids} and {@link #regions} unboxed, built on first use.
	 *
	 * <p>These two carry the bulk of the rule set - most rules are "wearing
	 * this" or "standing here" - and every rule is evaluated against every
	 * event, so a {@code List<Integer>.contains(int)} here means boxing the
	 * needle and walking a chain of Integers, hundreds of times per event.
	 */
	transient int[] idsUnboxed,
		regionsUnboxed;

	static int[] unbox(List<Integer> boxed)
	{
		int[] out = new int[boxed.size()];
		for (int i = 0; i < out.length; i++)
		{
			var value = boxed.get(i);
			out[i] = value == null ? Integer.MIN_VALUE : value;
		}
		return out;
	}


	/**
	 * Matches of this condition so far, for {@link #every} on the conditions
	 * that have no count of their own to read - a chat message, an animation.
	 * Transient, so it is the rule's lifetime and not the file's.
	 */
	transient int seen;

	/**
	 * Whether this match is the every-nth one. Counted only when it is
	 * reached, so under an "all" the conditions before it gate the count.
	 */
	boolean everyNth()
	{
		if (every == null || every <= 0)
			return true;
		return ++seen % every == 0;
	}

	boolean idsContain(int wanted)
	{
		return ids != null && Ints.contains(unboxedIds(), wanted);
	}

	int[] unboxedIds()
	{
		if (idsUnboxed == null)
			idsUnboxed = unbox(ids);
		return idsUnboxed;
	}

	/**
	 * The lowercased {@link #type}, cached: every rule is evaluated on every
	 * event, and re-lowercasing the discriminator allocated a string per
	 * evaluation across hundreds of rules.
	 */
	transient String normalizedType;

	/**
	 * npcNearby scans the whole NPC list; its answer cannot change within a
	 * tick, so it is cached per {@link TriggerContext#getRefreshGeneration()}.
	 * A chance roll is kept the same way (a condition has one type, so the
	 * two never share these).
	 */
	transient int nearbyGeneration = -1;
	transient boolean nearbyCached;

	// The public build leaves features out, and a player's own phrases.json
	// can still hold rules of theirs. Their condition types are unknown there:
	// such a condition is false, and its type is warned about once a session,
	// not on every evaluation.
	static final Set<String> UNKNOWN_TYPES = java.util.concurrent.ConcurrentHashMap.newKeySet();

	boolean matches(TriggerContext ctx, TriggerEvent event)
	{
		if (type == null)
			return false;
		if (normalizedType == null)
			normalizedType = type.toLowerCase(Locale.ROOT);

		switch (normalizedType)
		{
			case "all":
				return allOf(ctx, event);
			case "any":
				return anyOf(ctx, event);
			case "none":
				return !anyOf(ctx, event);

			case "always":
				return true;

			// Rolled once a tick, not once a pass. QA, 15 Oct: with npcSpawn
			// rules loaded every NPC spawn is a pass, so a chunk load re-rolled
			// a 4 percent fidget dozens of times in one tick.
			case "chance":
			{
				int generation = ctx.getRefreshGeneration();
				if (nearbyGeneration != generation)
				{
					nearbyGeneration = generation;
					nearbyCached = ThreadLocalRandom.current().nextInt(100) < orDefault(percent, 100);
				}
				return nearbyCached;
			}

			case "npcspawn":
				return event.getType() == NPC_SPAWN && matchesNpc(event);
			case "npcdespawn":
				return event.getType() == NPC_DESPAWN && matchesNpc(event);

			case "npcnearby":
			{
				int generation = ctx.getRefreshGeneration();
				if (nearbyGeneration != generation)
				{
					nearbyGeneration = generation;
					nearbyCached = ctx.isNpcNearby(this::isNearbyCandidate,
						orDefault(within, 15), Boolean.TRUE.equals(visible));
				}
				return nearbyCached;
			}

			// Any NPC the game itself flags as a follower - every pet in the
			// game, and every one added later, without naming any of them.
			// Cached per tick like npcNearby, and for the same reason.
			case "petnearby":
			{
				int generation = ctx.getRefreshGeneration();
				if (nearbyGeneration != generation)
				{
					nearbyGeneration = generation;
					nearbyCached = ctx.isNpcNearby(
						npc -> npc.getComposition() != null && npc.getComposition().isFollower(),
						orDefault(within, 5));
				}
				return nearbyCached;
			}

			case "healthbelow":
				return ctx.getHitpointsPercent() < orDefault(percent, 50);
			case "healthabove":
				return ctx.getHitpointsPercent() > orDefault(percent, 50);

			case "prayerbelow":
				return ctx.getPrayerPercent() < orDefault(percent, 20)
					&& (!Boolean.TRUE.equals(requirePrayerActive) || ctx.isPrayerActive());
			case "prayerabove":
				return ctx.getPrayerPercent() > orDefault(percent, 20);

			case "inregion":
				return matchesRegion(ctx, ctx.getRegionId());
			case "regionenter":
				return event.getType() == REGION_CHANGE && matchesRegion(ctx, event.getValue());

			case "inarea":
				return matchesArea(ctx);

			// "every" counts this condition's own matches, for life: 3 fires
			// on the third burn message and every third after, the way the
			// skilling company shakes its head at a run of them, not each.
			case "chatmessage":
				return event.getType() == CHAT
					&& matchesChatType(event)
					&& matchesSpeaker(ctx, event)
					&& matchesText(event.getMessage())
					&& everyNth();

			// The player answering something the follower asked, by picking a
			// branch in the conversation it opened. The options ARE the
			// vocabulary, so there is nothing to misread: yes and no from the
			// question trees, and the handful of named acts the everyday
			// script can perform - "gift" being the first.
			// "of" names the tree the answer belongs to, so a yes to the
			// nickname is not a yes to the outing.
			case "answered":
				return event.getType() == ANSWERED
					&& isAny(event.getName())
					&& (of == null || of.equalsIgnoreCase(event.getMessage()));

			// No player, no answer: at client start a chat message can arrive
			// before the game has loaded its varbits, the client's own lookup
			// throws, and a rule that throws is disabled for the session - the
			// two Wilderness rules were, in five logs.
			case "varbitequals":
				return varbit != null && ctx.getClient().getLocalPlayer() != null
					&& ctx.getClient().getVarbitValue(varbit) == orDefault(value, 1);
			case "varbitchanged":
				return event.getType() == VARBIT
					&& varbit != null && event.getId() == varbit
					&& (value == null || event.getValue() == value);

			// A quest's progress inside a band of steps. State, so the rule
			// rises on entering the band: a jump from 1 to 13 still enters
			// 11-20. Newer quests keep progress in a varbit, older ones in a
			// varp. Same guard as varbitEquals, for the same reason.
			case "questvar":
				return (varbit != null || varp != null) && ctx.getClient().getLocalPlayer() != null
					&& inRange(varbit != null
						? ctx.getClient().getVarbitValue(varbit)
						: ctx.getClient().getVarpValue(varp), Integer.MIN_VALUE);

			// An NPC dialogue box is up, or was a moment ago: page flips drop
			// it for a beat. Used negated, inside an "all", so a rule whose
			// state changes mid-conversation rises as the box closes.
			case "dialogueopen":
				return ctx.isDialogueOpen();

			// Another quest already finished, for a line that calls back to
			// it. State; read the way the chronicle reads it, and false with
			// no player or a name the game does not know.
			case "questdone":
				return ctx.isQuestDone(quest);

			// The follower was there for that quest: saw it finish, or wrote
			// its page at the time. For a callback that claims a shared
			// memory; minimum is days since, so a "still" waits a day.
			case "questwitnessed":
			{
				var on = ctx.questWitnessedOn(quest);
				return on != null
					&& java.time.LocalDate.now().toEpochDay() - on >= orDefault(minimum, 0);
			}

			case "animationself":
				return event.getType() == ANIMATION && idsContain(event.getId())
					&& everyNth();

			case "levelup":
				return event.getType() == LEVEL_UP && matchesText(event.getName())
					&& inRange(event.getValue(), 1);

			// A level that means something beyond being the next one. "is"
			// picks which: halfway (92, half the experience to 99), round (a
			// multiple of ten, from "minimum" up, fifty by default), mastery
			// (99, with "minimum"/"maximum" on how many that makes), total
			// (the total level crossing a multiple of "every", a hundred by
			// default, from "minimum" up) and base (every skill now at
			// "minimum" or better, the tick that became true).
			case "milestone":
			{
				if (event.getType() != LEVEL_UP || is == null)
					return false;
				int level = event.getValue();
				switch (is.toLowerCase(Locale.ROOT))
				{
					case "halfway":
						return level == 92;
					case "round":
						return level % 10 == 0 && inRange(level, 50);
					case "mastery":
						return level == 99 && inRange(event.getCount(), 1);
					case "total":
					{
						int step = Math.max(1, orDefault(every, 100));
						return event.getTotal() >= orDefault(minimum, 0)
							&& event.getTotal() / step > event.getPreviousTotal() / step;
					}
					case "base":
						return minimum != null && event.getBase() >= minimum
							&& event.getPreviousBase() < minimum;
					default:
						return false;
				}
			}

			// How long it had been since the last level in that skill, in
			// minutes - the gap the {sinceLast} placeholder says. Only when the
			// follower has a stamp to measure from: a first level in a skill
			// since it started keeping them is not a gap of any size.
			case "levelgap":
				return event.getType() == LEVEL_UP && event.getSinceMs() >= 0
					&& inRange(event.getSinceMs() / 60_000L, 0);

			// The game announcing a kill count - the account's own number, not
			// the follower's tally, which is why it can say "your forty-first"
			// on the first day they met. "names" narrows the boss, "every"
			// fires on multiples, and is: round fires on the counts a person
			// would say out loud (1, 5, 10, 25, 50, 75, the hundreds, then
			// every five hundred).
			case "killcount":
			{
				int n = event.getCount();
				return event.getType() == KILL_COUNT
					&& namesAny(event.getName())
					&& inRange(n, 1)
					&& (every == null || every <= 0 || n % every == 0)
					&& (is == null || !"round".equalsIgnoreCase(is) || isRoundCount(n));
			}

			// The half hour after the player did something the follower asked
			// for. Reciprocity: a favour is owed, and the body pays it back
			// (closer attention, quicker gestures); this is the rules' share.
			case "grateful":
				return ctx.isGrateful();

			// The player is addressing the follower: within a tile and turned
			// toward it. What makes an emote a reply rather than an echo.
			case "addressed":
				return ctx.isAddressingFollower();

			// What the two of them were doing when the last session ended, for
			// the greeting. Login only, and only when there is something to
			// say; {lastTime} says it.
			case "lasttime":
				return event.getType() == LOGIN && !ctx.getLastTime().isEmpty();

			case "damagetaken":
				return event.getType() == DAMAGE_TAKEN
					&& event.getValue() >= orDefault(minimum, 1);

			case "itemequipped":
				for (int id : ids == null ? new int[0] : unboxedIds())
				{
					if (ctx.isEquipped(id))
						return true;
				}
				return false;

			case "poisoned":
			{
				int poison = ctx.getClient().getVarpValue(VarPlayerID.POISON);
				return poison > 0 && poison < VENOM_THRESHOLD;
			}
			case "venomed":
				return ctx.getClient().getVarpValue(VarPlayerID.POISON) >= VENOM_THRESHOLD;

			case "skulled":
				return ctx.isSkulled();

			case "energybelow":
				return ctx.getEnergyPercent() < orDefault(percent, 20);

			case "idle":
				return ctx.getIdleTicks() >= orDefault(ticks, 50);

			// The other bound, so a fidget can be told apart from a full rest:
			// "been still a while" AND "not settled in for the night".
			case "idlebelow":
				return ctx.getIdleTicks() < orDefault(ticks, 500);

			// Standing where the last death happened, well after the fact.
			case "neardeathspot":
				return ctx.isNearDeathSpot(orDefault(within, 5));

			case "lootworth":
				return event.getType() == LOOT
					&& event.getValue() >= orDefault(minimum, 100_000);

			// Entering a region the session has already seen a few times.
			case "returnvisit":
				return event.getType() == REGION_CHANGE
					&& ctx.getRegionVisits() >= orDefault(minimum, 5);

			// True through a whole fight, including the short gaps between a
			// target dying and the next being clicked, so a rule using this
			// does not flicker on and off mid-kill.
			case "combat":
				return ctx.isInCombat();

			// The same, but only for something big. "minimum" overrides the
			// default combat level for anyone who wants a different bar.
			case "bossfight":
				return ctx.isInCombat()
					&& ctx.getCombatTargetLevel() >= orDefault(minimum, 100);

			// The moment a fight ends, as opposed to "combat", which stays
			// true throughout one. Optional names match what was fought.
			case "combatend":
				return event.getType() == COMBAT_END
					// The level comes from the context rather than the event,
					// which carries only the name: the target's level is still
					// the one the fight was fought at when this fires.
					&& (boss == null
						|| boss == ctx.isBoss(event.getName(), ctx.getCombatTargetLevel()))
					&& namesAny(event.getName());

			// How the follower is feeling. "is" names a band (low, down, even,
			// good, high); minimum and maximum bracket the raw 0..100 for
			// anything that wants a finer edge than the bands give.
			case "mood":
				// The mood is held to 0..100, so with no maximum it is at most 100.
				return is != null ? is.equalsIgnoreCase(ctx.getMoodBand()) : inRange(ctx.getMood(), 0);

			// Something the player killed. "minimum"/"maximum" bracket the
			// victim's COMBAT LEVEL, which is how one rule celebrates a boss
			// and another shrugs at a chicken; "names"/"ids" narrow it further.
			case "npckill":
				return event.getType() == NPC_KILL
					&& (boss == null
						|| boss == ctx.isBoss(event.getName(), event.getValue()))
					&& (namedBoss == null || namedBoss == ctx.isNamedBoss(event.getName()))
					&& inRange(event.getValue(), 0)
					&& (names == null && ids == null || matchesNpc(event))
					// "every": 50 fires on the fiftieth of THIS npc and every
					// fiftieth after, which is what makes a tally a remark.
					&& (every == null || every <= 0
						|| (event.getCount() > 0 && event.getCount() % every == 0));

			// True for the whole thieving session, unlike the two edges. Speech
			// is muted throughout, so this is really for animation-only rules -
			// which skip the mute, being movement rather than chatter.
			case "thieving":
				return ctx.isInThievingSession();

			// How long the follower went without seeing the player, in minutes.
			// Only meaningful on the login event, which is when it is worked
			// out; -1 means it has no idea, and must never read as "just now".
			case "awayfor":
				return event.getType() == LOGIN
					&& ctx.getMinutesAway() >= 0
					&& inRange(ctx.getMinutesAway(), 60);

			// The incident the follower is still thinking about. "is" names a
			// particular one; without it, any incident will do - which is what
			// a generic "I still think about {memory}" line wants. A maximum
			// holds a line to the counts it is true for: "That's three".
			case "remembers":
				return ctx.hasIncident()
					&& isAny(ctx.getIncidentKey())
					&& inRange(ctx.getIncidentCount(), 1);

			// Standing where the incident happened, and the thing it was with
			// being nearby again: the two moments a memory is worth jogging.
			case "memoryhere":
				return ctx.isAtTheIncident();
			case "memoryfoenearby":
				return ctx.isIncidentFoeNearby(orDefault(within, 12));

			// Nobody has touched the camera for this long. Distinct from idle,
			// which a player working a furnace also satisfies.
			case "unattended":
				return ctx.getUnattendedTicks() >= orDefault(ticks, 200);

			// A player-commanded Stay: watched, parked, and free to have a
			// little life of its own.
			case "staying":
				return ctx.isFollowerStaying();

			// Standing in the Wilderness, as a state rather than the crossing.
			case "inwilderness":
				return ctx.isInWilderness();

			// A few ticks of breather after something ENDS - combat, a level,
			// an arrival, thieving, the bank. "is" names which ending; left
			// out, any ending counts.
			case "boundary":
				return ctx.isAtBoundary() && isAny(ctx.getBoundaryKind());

			// How long the follower has known you, in days, and the day of
			// the year it met you coming round again.
			case "daysknown":
				return inRange(ctx.getDaysKnown(), 1);
			// Days since a one-time rule was heard: a running bit's stages
			// count from its opener, and stay quiet until it has been said.
			case "dayssincesaid":
			{
				int days = ctx.daysSinceSaid(rule);
				return days >= 0 && inRange(days, 0);
			}
			case "anniversary":
				return ctx.isAnniversary();

			// The player is "minimum" times better dressed than the day they
			// met. Needs a first-meeting figure to compare against, so it stays
			// quiet for a follower that has only ever known you rich.
			case "outgrew":
				return ctx.getTimesBetterDressed() >= orDefault(minimum, 10);

			// Something happened HERE that the follower has not let go of.
			// {here} says it. Distinct from "remembers", which holds one
			// incident wherever you are; this one is the place's, and waits
			// for you to come back to it.
			case "happenedhere":
				return ctx.hasPlaceMemory();

			// A question is already on the table. Used NEGATED, and every rule
			// with an "asks" needs it: opening a second question replaces the
			// first, so without the guard a follower that asks to go somewhere
			// and then offers a game has silently withdrawn the outing, and the
			// player answers a question nobody is listening for.
			case "asking":
				return ctx.isAwaitingAnswer() && isAny(ctx.getAskedTree());

			// The hour on the player's own wall, not the game's. "minimum" and
			// "maximum" bound it, wrapping past midnight so a late-night window
			// can be written the way a person would say it: 23 to 5.
			case "timeofday":
				return between(ctx.getHourOfDay(), orDefault(minimum, 0), orDefault(maximum, 23));

			// How long today has run, in minutes.
			case "sessionminutes":
				return inRange(ctx.getSessionMinutes(), 60);

			// The date on the player's own calendar, like timeOfDay is the
			// player's own clock. A single day, or a range that may wrap past
			// new year the way a late-night window wraps past midnight - the
			// scribe dates its entries, so this is the most in-character
			// knowledge it could have. Rising-edge, so a matching day fires
			// once per session, same as anniversary.
			case "dateis":
			{
				if (day == null)
					return false;
				int today = ctx.getMonthDay();
				// Day alone means that day of EVERY month - the first of the
				// month is the scribe's favourite day of it.
				if (month == null)
					return today % 100 == day;
				int from = month * 100 + day;
				return between(today, from, untilMonth == null || untilDay == null
					? from : untilMonth * 100 + untilDay);
			}

			// The follower is hoping for something. Mostly used NEGATED, to stop
			// a second want being asked for while one is still open.
			case "wanting":
				return ctx.isWanting();

			// One of these items is in the bag now: state, so a rule rises when
			// it arrives - the golden key in Priest in Peril, picked up off the
			// right monk.
			case "inventoryhas":
				return ctx.isInInventory(ids);

			// Room left in the bag. The point of this one is the WARNING - set
			// maximum to 2 and the follower speaks up while there is still
			// somewhere to put the next log, which is a companion paying
			// attention rather than a companion narrating a full inventory.
			case "inventoryfree":
			{
				int free = ctx.getFreeInventorySlots();
				return free <= orDefault(maximum, 2) && free >= orDefault(minimum, 0);
			}

			// How busy it is here. "within" is the radius, "minimum" how many
			// other players it takes before that counts as a crowd.
			case "playersnearby":
				return ctx.countPlayersNearby(orDefault(within, 10))
					>= orDefault(minimum, 5);

			// Somebody is looking at the follower. "ticks" is how long the mouse
			// has to rest on it: a cursor crossing the screen is not attention.
			case "hovered":
				return ctx.getHoverTicks() >= orDefault(ticks, 5);

			// A lifetime count, as against npcKill's "every" which fires on the
			// moment. This is state: it stays true once passed, so it belongs
			// alongside something that picks the moment to say it.
			case "tally":
				return of != null && inRange(ctx.getTally(of), 1);

			// How many times the follower has been started up with this player.
			// Login only, which is the one moment it changes and the one moment
			// remarking on it is not out of nowhere.
			case "sessioncount":
			{
				int sessions = ctx.getSessionCount();
				return event.getType() == LOGIN
					&& inRange(sessions, 1)
					&& (every == null || every <= 0 || sessions % every == 0);
			}

			// How long the player has been doing the same thing. Knows nothing
			// about trees or rocks: an animation running for minutes IS the
			// activity, so this covers every skill at once.
			case "repeating":
				return ctx.getRepeatingTicks() >= orDefault(ticks, 100)
					&& (ids == null || idsContain(ctx.getRepeatingAnimation()));

			// The player is working something - a tree, a rock, a spot - as
			// the skilling company sees it. "is" names the skill, "contains"
			// a piece of the target's name, so a yew can have its own line.
			case "working":
				return ctx.isWorking()
					&& isAny(ctx.getWorkActivity())
					&& containsAny(ctx.getWorkTargetName());

			// The tick of an XP drop. "every" counts within the work session,
			// the way npcKill's counts within the fight: 8 fires on the
			// eighth drop and every eighth after.
			case "xpdrop":
				return event.getType() == XP_DROP
					&& namesAny(event.getName())
					&& (every == null || every <= 0
						|| (event.getCount() > 0 && event.getCount() % every == 0));

			// Every other type is an event and nothing more, listed with what
			// narrows it in event-conditions.properties.
			default:
			{
				if (eventSpec == null)
				{
					eventSpec = Arrays.asList(EVENT_CONDITIONS.getProperty(normalizedType, "").split(" "));
					eventType = eventSpec.get(0).isEmpty() ? null : Type.valueOf(eventSpec.get(0));
				}
				if (eventType == null)
				{
					if (UNKNOWN_TYPES.add(type))
						log.warn("Unknown condition type '{}'", type);
					return false;
				}
				return event.getType() == eventType
					&& (!eventSpec.contains("is") || isAny(event.getName()))
					&& (!eventSpec.contains("names") || namesAny(event.getName()))
					&& (!eventSpec.contains("contains") || containsAny(event.getMessage()));
			}
		}
	}

	/**
	 * The condition types that are an event and nothing more, by type: each
	 * names the event it is true on, then the fields that narrow it. See
	 * event-conditions.properties.
	 */
	static final Properties EVENT_CONDITIONS = Resources.properties("event-conditions.properties");

	static
	{
		// A line whose event type is gone stops the class loading here, rather
		// than leaving the rules that use it silently never true.
		EVENT_CONDITIONS.values().forEach(spec -> Type.valueOf(spec.toString().split(" ")[0]));
	}

	/** This condition's line of event-conditions.properties, split, and its event, once looked up. */
	transient List<String> eventSpec;
	transient Type eventType;

	/** Absent, any; present, the value named, whatever its case. */
	boolean isAny(String value)
	{
		return is == null || is.equalsIgnoreCase(value);
	}

	/** Absent, any; present, one of the names (wildcards ok). */
	boolean namesAny(String value)
	{
		return names == null || matchesAnyName(value);
	}

	/** Absent, any; present, a piece of the text, whatever its case. */
	boolean containsAny(String text)
	{
		return contains == null || text.toLowerCase(Locale.ROOT).contains(contains.toLowerCase(Locale.ROOT));
	}

	/** At least {@link #minimum} (or the fallback) and at most {@link #maximum}, if given. */
	boolean inRange(long value, int fallbackMinimum)
	{
		return value >= orDefault(minimum, fallbackMinimum) && (maximum == null || value <= maximum);
	}

	/** Between the two, inclusive, wrapping round when from is past to: 23 to 5. */
	static boolean between(int value, int from, int to)
	{
		return from <= to ? value >= from && value <= to : value >= from || value <= to;
	}

	boolean allOf(TriggerContext ctx, TriggerEvent event)
	{
		if (conditions == null || conditions.isEmpty())
			return true;
		for (var child : conditions)
		{
			if (!child.matches(ctx, event))
				return false;
		}
		return true;
	}

	boolean anyOf(TriggerContext ctx, TriggerEvent event)
	{
		if (conditions == null)
			return false;
		for (var child : conditions)
		{
			if (child.matches(ctx, event))
				return true;
		}
		return false;
	}

	boolean matchesNpc(TriggerEvent event)
	{
		return idsContain(event.getId()) || matchesAnyName(event.getName());
	}

	/**
	 * Whether an NPC in the scene is one this rule cares about.
	 *
	 * <p>{@code minimum} and {@code maximum} bracket its COMBAT LEVEL, which is
	 * what turns npcNearby into "something big is standing near us" without
	 * naming a single monster - and keeps covering everything the game adds
	 * later. With no names or ids given, that bracket is the whole test.
	 */
	boolean isNearbyCandidate(NPC npc)
	{
		if (minimum != null && npc.getCombatLevel() < minimum)
			return false;
		if (maximum != null && npc.getCombatLevel() > maximum)
			return false;
		if (names == null && ids == null)
			return minimum != null || maximum != null;
		return matchesNpcObject(npc);
	}

	boolean matchesNpcObject(NPC npc)
	{
		return idsContain(npc.getId()) || matchesAnyName(npc.getName());
	}

	boolean matchesRegion(TriggerContext ctx, int currentRegion)
	{
		if (regions == null || regions.isEmpty())
			return false;
		if (regionsUnboxed == null)
			regionsUnboxed = unbox(regions);
		if (Boolean.TRUE.equals(anyLoadedRegion))
		{
			for (int region : regionsUnboxed)
			{
				if (ctx.isRegionLoaded(region))
					return true;
			}
			return false;
		}
		return Ints.contains(regionsUnboxed, currentRegion);
	}

	boolean matchesArea(TriggerContext ctx)
	{
		if (ctx.getLocation() == null || x1 == null || y1 == null || x2 == null || y2 == null)
			return false;
		int px = ctx.getLocation().getX(),
			py = ctx.getLocation().getY();
		if (plane != null && ctx.getLocation().getPlane() != plane)
			return false;
		return px >= Math.min(x1, x2) && px <= Math.max(x1, x2)
			&& py >= Math.min(y1, y2) && py <= Math.max(y1, y2);
	}

	/**
	 * Narrows a chat rule to one kind of message. {@code is} takes the
	 * {@link net.runelite.api.ChatMessageType} name exactly as {@code ::follower
	 * chatwatch} prints it, so the way to write one of these is to watch the
	 * real message go past and copy what it says. No table of friendly aliases,
	 * because a table is a thing that drifts out of date silently.
	 */
	boolean matchesChatType(TriggerEvent event)
	{
		if (is == null)
			return true;
		if (wantedChatType == Integer.MIN_VALUE)
		{
			int resolved = -1;
			try
			{
				resolved = net.runelite.api.ChatMessageType
					.valueOf(is.toUpperCase(Locale.ROOT)).getType();
			}
			catch (IllegalArgumentException e)
			{
				log.warn("Unknown chat type '{}'", is);
			}
			wantedChatType = resolved;
		}
		return wantedChatType >= 0 && event.getChatTypeId() == wantedChatType;
	}

	transient int wantedChatType = Integer.MIN_VALUE;

	/**
	 * {@code from} is "player" for the local player's own lines and "others"
	 * for everybody else's. Absent means either.
	 */
	boolean matchesSpeaker(TriggerContext ctx, TriggerEvent event)
	{
		if (from == null)
			return true;
		boolean mine = isFromPlayer(ctx, event);
		return "player".equalsIgnoreCase(from) ? mine : !mine;
	}

	static boolean isFromPlayer(TriggerContext ctx, TriggerEvent event)
	{
		// Read straight off the client rather than through getPlayerName(),
		// which substitutes "you" when there is no player - a placeholder
		// fallback that would be a wrong ANSWER here.
		var local = ctx.getClient().getLocalPlayer();
		String player = local == null || local.getName() == null ? "" : local.getName();
		if (player.isEmpty() || event.getName().isEmpty())
			return false;
		// The game pads display names with non-breaking spaces.
		return player.replace(' ', ' ').trim()
			.equalsIgnoreCase(event.getName().replace(' ', ' ').trim());
	}

	/** Matches against {@code contains} (case-insensitive), {@code regex}, or {@code names}. */
	boolean matchesText(String text)
	{
		if (text == null)
			return false;
		if (contains != null && text.toLowerCase(Locale.ROOT).contains(contains.toLowerCase(Locale.ROOT)))
			return true;
		if (regex != null)
		{
			if (compiledRegex == null)
				compiledRegex = Pattern.compile(regex, Pattern.CASE_INSENSITIVE);
			if (compiledRegex.matcher(text).find())
				return true;
		}
		return matchesAnyName(text);
	}

	/** Name matching is case-insensitive and supports {@code *} wildcards. */
	/**
	 * Compiles one name pattern the way every {@code names} list here is
	 * matched: literal, case-insensitive, with {@code *} standing for any run
	 * of characters.
	 */
	static Pattern compileName(String name)
	{
		var pattern = new StringBuilder();
		for (String literal : name.split("\\*", -1))
		{
			if (pattern.length() > 0)
				pattern.append(".*");
			pattern.append(Pattern.quote(literal));
		}
		return Pattern.compile(pattern.toString(), Pattern.CASE_INSENSITIVE);
	}

	/** The game pads names with non-breaking spaces in places. */
	static String normaliseName(String candidate)
	{
		return candidate == null ? "" : candidate.replace('\u00A0', ' ').trim();
	}

	boolean matchesAnyName(String candidate)
	{
		if (candidate == null || names == null)
			return false;
		if (compiledNames == null)
		{
			compiledNames = new java.util.ArrayList<>(names.size());
			for (String name : names)
				compiledNames.add(compileName(name));
		}
		String normalised = normaliseName(candidate);
		for (var pattern : compiledNames)
		{
			if (pattern.matcher(normalised).matches())
				return true;
		}
		return false;
	}

	/** Whether this condition tree contains the given type (case-insensitive). */
	/** Whether this is, or holds, an npcSpawn condition this spawn would make true. */
	boolean answersSpawn(TriggerEvent spawn)
	{
		if ("npcSpawn".equalsIgnoreCase(type) && matchesNpc(spawn))
			return true;
		if (conditions != null)
		{
			for (var child : conditions)
			{
				if (child != null && child.answersSpawn(spawn))
					return true;
			}
		}
		return false;
	}

	boolean usesType(String wanted)
	{
		if (wanted.equalsIgnoreCase(type))
			return true;
		if (conditions != null)
		{
			for (var child : conditions)
			{
				if (child != null && child.usesType(wanted))
					return true;
			}
		}
		return false;
	}

	/**
	 * Whether the quest steps this condition requires - its questVar, alone
	 * or inside an "all" - still hold. True when it reads none. For a line
	 * kept waiting, which can outlive the step it was about.
	 */
	boolean questStepHolds(TriggerContext ctx, TriggerEvent event)
	{
		return holds(ctx, event, QUEST_STEP);
	}

	static final Set<String> QUEST_STEP = Set.of("questvar");

	/**
	 * The conditions that say how things stand rather than what just
	 * happened, and read nothing else: no roll, no count, no event.
	 */
	static final Set<String> STANDING = Set.of(
		"healthbelow", "prayerbelow", "poisoned", "venomed", "npcnearby");

	/**
	 * Whether how things stood when the line won - its health, prayer,
	 * poison or the person near, alone or inside an "all" - still holds.
	 * True when it reads none. For a line kept waiting: behaviour QA, 16 Oct,
	 * "49 HP! Get out!" said at 70 percent after the player had eaten, and a
	 * passer-by announced after he had gone.
	 *
	 * <p>The person the player has just been talking to still counts as near:
	 * a line about them is held through that talk, and the player has often
	 * walked a few tiles on by the time the box closes. Behaviour QA4, 16
	 * Oct: Sergeant Tobyn was never introduced.
	 */
	boolean standingHolds(TriggerContext ctx, TriggerEvent event)
	{
		return holds(ctx, event, STANDING);
	}

	/** Whether this condition's parts of these types, alone or inside an "all", still match. */
	boolean holds(TriggerContext ctx, TriggerEvent event, Set<String> types)
	{
		if (type != null && types.contains(type.toLowerCase(Locale.ROOT)))
			return matches(ctx, event)
				|| ("npcnearby".equalsIgnoreCase(type) && matchesAnyName(ctx.getRecentSpeaker()));
		if ("all".equalsIgnoreCase(type) && conditions != null)
		{
			for (var child : conditions)
			{
				if (child != null && !child.holds(ctx, event, types))
					return false;
			}
		}
		// A quest step the line stands aside at is how things stand too: met
		// before it and kept waiting, the line is let go once the quest is
		// there. Quests QA5 #57: the mage's introduction, kept through his
		// box, came straight after the moment that speaks for him at that step.
		if ("none".equalsIgnoreCase(type) && conditions != null)
		{
			for (var child : conditions)
			{
				if (child != null && "questvar".equalsIgnoreCase(child.type) && child.matches(ctx, event))
					return false;
			}
		}
		return true;
	}

	/** The counts a person says out loud, rather than every one. */
	static boolean isRoundCount(int n)
	{
		if (n <= 0)
			return false;
		if (n == 1 || n == 5 || n == 10 || n == 25 || n == 50 || n == 75)
			return true;
		return n < 1000 ? n % 100 == 0 : n % 500 == 0;
	}

	static int orDefault(Integer boxed, int fallback)
	{
		return boxed == null ? fallback : boxed;
	}

	/**
	 * The poison varp holds small cycle values while poisoned; venom is encoded
	 * as the same varp pushed above a million. Same scheme RuneLite's own
	 * poison plugin decodes.
	 */
	static final int VENOM_THRESHOLD = 1_000_000;
}

package com.follower;

import java.util.*;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import lombok.*;

/**
 * One agility obstacle or shortcut as the player took it: where they were,
 * which way they faced and what they were doing, frame by frame, from the
 * first odd step to the moment they were walking normally again.
 *
 * <p>Positions are fine WORLD units (tile x 128, the centre of a tile at 64),
 * the same space the follower's own fine position lives in, so a recording
 * made before a scene rebuild plays back the same after it. Times are
 * milliseconds from the first frame.
 *
 * <p>Nothing here knows which obstacle it was. That is the point: the
 * follower plays back what it saw, not what a table says the obstacle does.
 *
 * <p>A recording is handed over while it is still being made, so the
 * follower can set off a couple of ticks after the player rather than
 * waiting for them to finish: {@link CrossingWatch} appends a frame at a
 * time, then {@link #end ends} it, or {@link #cut cuts} it short. The watch
 * writes and the follower reads on the client thread alone (BeforeRender,
 * StatChanged, HitsplatApplied and GameTick are all posted there), so there
 * is no lock: frames are only ever appended, and the one trim, at the end,
 * removes frames the reader clamps itself away from.
 */
@Getter
class Crossing
{
	/** One sample of the player. */
	@RequiredArgsConstructor
	@Getter
	static class Frame
	{
		final long atMs,
			fineX,
			fineY;
		final int plane,
			orientation,
			pose,
			poseFrame,
			action,
			actionFrame;

		WorldPoint tile()
		{
			return new WorldPoint((int) (fineX >> 7), (int) (fineY >> 7), plane);
		}
	}

	final List<Frame> frames,
		readOnly;
	/** The recording clock's time at the first frame, which every frame is rebased against. */
	final long zero;
	boolean fell;
	/** No more frames are coming: ended, cut or dropped. */
	boolean complete;
	/** Let go as not an obstacle at all: skipped if the follower has not begun it. */
	boolean dropped;

	/**
	 * The player's own stand, walk, run and turns while they were not
	 * crossing anything, in {@link StanceLibrary.Stance} order: idle, walk,
	 * run, back, left, right, turn left, turn right. A frame showing one of
	 * these is played with the follower's own version of it, so it stands
	 * and walks like itself between the odd parts.
	 */
	final int[] normal;

	/** A finished recording. */
	Crossing(List<Frame> frames, int[] normal, boolean fell)
	{
		this(frames, normal);
		this.fell = fell;
		complete = true;
	}

	Crossing(List<Frame> frames, int[] normal)
	{
		if (frames == null || frames.isEmpty())
			throw new IllegalArgumentException("a crossing has at least one frame");
		// Rebased so the first frame is time zero whatever clock recorded it.
		zero = frames.get(0).atMs;
		this.frames = new ArrayList<>(frames.size());
		for (var f : frames)
			append(f);
		readOnly = Collections.unmodifiableList(this.frames);
		this.normal = normal == null ? new int[0] : normal.clone();
	}

	/** A recording still being made: the watch appends to it and then ends it. */
	static Crossing live(List<Frame> frames, int[] normal)
	{
		return new Crossing(frames, normal);
	}

	/** The next frame, on the recording clock. */
	void append(Frame f)
	{
		frames.add(new Frame(f.atMs - zero, f.fineX, f.fineY, f.plane, f.orientation,
			f.pose, f.poseFrame, f.action, f.actionFrame));
	}

	/** Over: only the first {@code keep} frames were the crossing, the rest the walk away. */
	void end(int keep, boolean fell)
	{
		while (frames.size() > Math.max(1, keep))
			frames.remove(frames.size() - 1);
		this.fell = fell;
		complete = true;
	}

	/** Ended early, where it got to: played that far and no further. */
	void cut()
	{
		complete = true;
	}

	/** Not an obstacle after all: what has been played ends, and an unbegun one is skipped. */
	void drop()
	{
		complete = true;
		dropped = true;
	}

	/** When it began on the recording clock, which orders crossings made at different times. */
	long getStartedAtMs()
	{
		return zero;
	}

	List<Frame> getFrames()
	{
		return readOnly;
	}

	/** Where the player stood as it began: the tile the follower walks to first. */
	WorldPoint getStart()
	{
		return frames.get(0).tile();
	}

	/** Where they stood when it was over, fall or no fall. */
	WorldPoint getEnd()
	{
		return frames.get(frames.size() - 1).tile();
	}

	/** As long as it is so far: the whole of it once {@link #isComplete complete}. */
	long getDurationMs()
	{
		return frames.get(frames.size() - 1).atMs;
	}

	/** Which of the normal poses this is (an index into the stance order), or -1 for an odd one. */
	int normalIndex(int pose)
	{
		for (int i = 0; i < normal.length; i++)
		{
			if (normal[i] == pose)
				return i;
		}
		return -1;
	}

	/** The frame showing at {@code t} ms in: the last one at or before it. */
	Frame frameAt(long t)
	{
		return frames.get(indexAt(t));
	}

	int indexAt(long t)
	{
		int lo = 0,
			hi = frames.size() - 1;
		while (lo < hi)
		{
			int mid = (lo + hi + 1) >>> 1;
			if (frames.get(mid).atMs <= t)
				lo = mid;
			else
				hi = mid - 1;
		}
		return lo;
	}

	/**
	 * The fine position at {@code t} ms in, {x, y}: between two frames on the
	 * same plane and within two tiles of each other it glides, as the player
	 * did between samples; across a plane change or a bigger hop it holds the
	 * earlier frame and moves on the later one, as they did.
	 */
	long[] fineAt(long t)
	{
		int i = indexAt(t);
		var a = frames.get(i);
		if (i + 1 >= frames.size() || t <= a.atMs)
		{
			return new long[]{a.fineX, a.fineY};
		}
		var b = frames.get(i + 1);
		if (b.plane != a.plane || Math.abs(b.fineX - a.fineX) > 256 || Math.abs(b.fineY - a.fineY) > 256
			|| b.atMs <= a.atMs)
		{
			return new long[]{a.fineX, a.fineY};
		}
		double k = (t - a.atMs) / (double) (b.atMs - a.atMs);
		return new long[]{
			a.fineX + Math.round((b.fineX - a.fineX) * k),
			a.fineY + Math.round((b.fineY - a.fineY) * k)};
	}
}

package com.follower;

import com.google.common.primitives.Ints;
import java.util.*;
import java.util.Deque;
import java.util.List;
import net.runelite.api.*;
import net.runelite.api.HitsplatID;
import net.runelite.api.Player;
import net.runelite.api.coords.*;
import net.runelite.api.kit.KitType;
import lombok.RequiredArgsConstructor;

/**
 * Watches the player for agility obstacles and shortcuts, and records each
 * one for the follower to do after them.
 *
 * <p>Nothing here knows any obstacle. A crossing is recognised by how the
 * player moves, measured against how they move the rest of the time:
 *
 * <ul>
 * <li><b>An odd pose.</b> The player's pose leaves their own stand, walk,
 * run and turn set - the log balance, the ledge shimmy, the monkey bars.
 * The game does these by swapping the player's base animations, so the set
 * the pose is measured against is the one they had BEFORE the swap: the
 * normal set is only re-taken when the weapon changes, which is the one
 * thing that legitimately changes it.</li>
 * <li><b>A glide.</b> The fine position moving while the pose is not a
 * walking pose. Ordinary steps always show a walk or a run; the game's
 * forced movement (a jump, a squeeze, a vault) shows the stand, or an odd
 * pose. Counted only over consecutive frames, so the one frame where a walk
 * ends on the stand can never add up to one; a frame that only repeats the
 * last (more frames drawn than game cycles) neither counts nor breaks it.
 * A running jump counts at once: the server puts them further than their
 * walk goes, with a clip on, while the client still draws the walk.</li>
 * <li><b>An action with a hop.</b> An animation, then the player put down a
 * tile or more away or on another floor: a climb, a jump across a gap. A
 * ladder looks exactly the same, so this one needs agility XP, or damage (a
 * fall), to count.</li>
 * <li><b>Agility XP after something moved them.</b> Every course obstacle
 * pays XP as it completes. XP while an unconfirmed run has moved the player
 * confirms it; XP with nothing open, or for movement before what is open,
 * rebuilds the crossing from the last few seconds of the player (see
 * {@link #BUFFER_MS}), so an obstacle none of the above caught is late but
 * never skipped.</li>
 * </ul>
 *
 * <p>An animation alone - an emote, a swing, a skilling loop, eating on the
 * run - never counts: nothing moved, or it moved them on an ordinary walk
 * with no XP. Walking on normally ends a run that has not counted yet. A
 * fight or a conversation (the player interacting with an actor) is never a
 * crossing, and nor is anything while the player is transformed into an NPC
 * or aboard a boat; the plugin also stops watching in a cutscene. A jump
 * further than the follower's own snap distance is a teleport: whatever was
 * being watched is dropped and the follower's queue with it.
 *
 * <p>A crossing is handed to the follower the moment it is recognised, still
 * recording, so the follower can begin it a couple of ticks behind the
 * player. It ends once the player has been back to normal for a while:
 * {@link #SETTLE_MS} standing, or {@link #WALK_OFF_MS} walking on. It is cut
 * where the drawn player reaches the tile the server stepped them off to
 * as their own set came back, so the follower does not copy the walk away,
 * nor stop short of the end of a rope.
 */
@RequiredArgsConstructor
class CrossingWatch
{
	/** Where the crossings go; {@link FollowerEntity} is the one that copies them. */
	interface Listener
	{
		/** Something has begun at this tile that may be a crossing (a climb awaiting its XP): hold, do not snap. */
		void expectCrossing(WorldPoint start);

		/** A crossing, recognised: still recording unless {@link Crossing#isComplete}. */
		void queueCrossing(Crossing crossing);

		/** What was expected was not a crossing after all. */
		void cancelExpectedCrossing();

		/** The player is gone (a teleport): whatever is queued is let go. */
		void clearCrossings();
	}

	/** Back to standing normally this long and the crossing is over: two ticks, so a climb's pause before the hop is not its end. */
	static final long SETTLE_MS = 1200;

	/** Walking on normally this long and it is over: half a tick, so the next obstacle is a crossing of its own. */
	static final long WALK_OFF_MS = 300;

	/** How long a climb's hop waits for the XP drop (or the fall's damage) that says it was agility: two ticks. */
	static final long CONFIRM_WAIT_MS = 1200;

	/**
	 * The same wait on a course - agility XP in the last {@link #ON_COURSE_MS}
	 * - where a hop is far more likely an obstacle than a ladder: five ticks,
	 * so XP that comes a tick or two late still confirms it in place.
	 */
	static final long CONFIRM_WAIT_ON_COURSE_MS = 3000;

	/** A hop further than this is a teleport: the follower's own snap distance. */
	static final int MAX_HOP_TILES = FollowerEntity.SNAP_DISTANCE;

	/**
	 * One reading of the player, taken each frame: the frame a crossing is
	 * recorded from, with what the watch judges it by. A crossing copies
	 * every frame it is given, so a reading is never shared beyond the watch.
	 */
	static class Sample extends Crossing.Frame
	{
		/** Idle, walk, run, back, left, right, turn left, turn right: the base animations now. */
		final int[] base;
		final int weapon;
		final boolean interacting;
		/** The tile the server has them on, which leads the drawn one on a walk. */
		final WorldPoint server;

		Sample(long atMs, long fineX, long fineY, int plane, int orientation,
			int pose, int poseFrame, int action, int actionFrame, int[] base, int weapon,
			boolean interacting, WorldPoint server)
		{
			super(atMs, fineX, fineY, plane, orientation, pose, poseFrame, action, actionFrame);
			this.server = server;
			this.base = base;
			this.weapon = weapon;
			this.interacting = interacting;
		}

		/**
		 * The player now, or null when there is nothing worth watching: no
		 * position yet, aboard a boat (its own world view, its own moves), or
		 * transformed into an NPC, whose walk is not theirs.
		 *
		 * <p>The fine position is the RENDERED one, taken in world units: the
		 * scene's base plus the local position, which survives a rebuild where
		 * the local position alone does not.
		 */
		static Sample read(Player local, long nowMs)
		{
			if (local == null)
				return null;
			var at = local.getLocalLocation();
			var tile = local.getWorldLocation();
			var view = local.getWorldView();
			var composition = local.getPlayerComposition();
			if (at == null || tile == null || view == null || !view.isTopLevel()
				|| composition == null || composition.getTransformedNpcId() != -1)
				return null;
			return new Sample(nowMs,
				view.getBaseX() * 128L + at.getX(), view.getBaseY() * 128L + at.getY(),
				tile.getPlane(), local.getOrientation(),
				local.getPoseAnimation(), local.getPoseAnimationFrame(),
				local.getAnimation(), local.getAnimationFrame(),
				StanceLibrary.posesOf(local), composition.getEquipmentId(KitType.WEAPON),
				local.getInteracting() != null, tile);
		}
	}

	/** Damage that can come from a fall: a hit, not poison, venom, disease or a drain. */
	static boolean isFallDamage(int hitsplatType)
	{
		return hitsplatType == HitsplatID.DAMAGE_ME || hitsplatType == HitsplatID.DAMAGE_OTHER
			|| hitsplatType == HitsplatID.DAMAGE_MAX_ME;
	}

	/** What is being watched: the frames since something odd began. */
	static class Run
	{
		final List<Crossing.Frame> frames = new ArrayList<>();
		final long startMs;
		long glided;
		boolean lastGlided,
			confirmed;
		/** Handed to the follower once confirmed, and grown frame by frame after. */
		Crossing crossing;
		/** The listener was told to expect it. */
		boolean announced;
		/** When the player was put down somewhere new, or -1. */
		long hopMs = -1;
		/** Since when the player has been back to normal, and the frame it began, or -1. */
		long calmSinceMs = -1;
		int calmIndex = -1;
		boolean calmWalked;
		/** The server's tile on the first normal frame: the calm counts from the drawn player's reaching it. */
		WorldPoint steppedOffTo;

		Run(Sample first)
		{
			startMs = first.atMs;
			frames.add(first);
		}

		WorldPoint start()
		{
			return frames.get(0).tile();
		}

		/** Whether the player is on another tile or floor than it began on. */
		boolean displaced()
		{
			return !frames.get(frames.size() - 1).tile().equals(start());
		}
	}

	/** One remembered frame, with what the watch made of it. */
	static class Seen
	{
		final Crossing.Frame frame;
		/** Their own stand or walk, with nothing playing. */
		final boolean calm,
			walking;
		/** Moved by something other than their own walk: a glide, a hop, an odd pose or an animation on the move. */
		final boolean unusual;
		final WorldPoint server;

		Seen(Crossing.Frame frame, boolean calm, boolean walking, boolean unusual, WorldPoint server)
		{
			this.server = server;
			this.frame = frame;
			this.calm = calm;
			this.walking = walking;
			this.unusual = unusual;
		}
	}

	final Listener listener;

	/** The player's own set and the weapon it goes with; null until the first reading. */
	int[] normal;
	int normalWeapon;

	/**
	 * The player's own set while a long swapped one (swimming, a carpet)
	 * stands in for it, to go back to the moment it is on them again.
	 */
	int[] ownSet;

	Sample previous;
	Run run;
	long lastXpMs = Long.MIN_VALUE,
		lastDamageMs = Long.MIN_VALUE;

	/** After a run too long to be an obstacle: nothing new starts until the player looks normal. */
	boolean cooling;

	/** The last few seconds of the player, oldest first. */
	final Deque<Seen> recent = new ArrayDeque<>();

	/** Frames up to this time are in a crossing already handed over, or are past caring about. */
	long coveredToMs = Long.MIN_VALUE;

	/** Agility XP has landed and the next frame looks for what it paid for. */
	boolean xpToCheck;

	/** Agility XP landed: the hop being watched, if any, was an obstacle, and anything missed is rebuilt. */
	void noteAgilityXp(long atMs)
	{
		lastXpMs = atMs;
		xpToCheck = true;
	}

	/** The player was hurt: on a crossing, that is a fall. */
	void noteDamage(long atMs)
	{
		lastDamageMs = atMs;
	}

	/** Whether a crossing is being watched or recorded right now. */
	boolean isWatching()
	{
		return run != null;
	}

	/** Whether what is being watched has moved the player: a skilling loop or an emote has not. */
	boolean isWatchingMovement()
	{
		return run != null && (run.displaced() || run.glided > 0 || run.hopMs >= 0);
	}

	/**
	 * The follower was put beside the player: whatever the player did before
	 * now is behind it, and XP arriving for it must not send it back there.
	 */
	void forgetMissed()
	{
		recent.clear();
		if (previous != null)
			coveredToMs = previous.atMs;
	}

	/**
	 * Stops watching: a logout, a hop, the setting turned off, a cutscene.
	 * Whatever was half-recorded is dropped. The player's normal set is
	 * kept, since it is the thing a half-way reading would get wrong.
	 */
	void reset()
	{
		discard("watching stopped");
		previous = null;
		cooling = false;
		recent.clear();
		xpToCheck = false;
	}

	/** One frame of the player, or null when there is nothing to read. */
	void sample(Sample s)
	{
		if (s == null)
		{
			reset();
			return;
		}
		if (normal == null || (s.weapon != normalWeapon && run == null))
		{
			normal = s.base.clone();
			normalWeapon = s.weapon;
			ownSet = null;
		}
		else if (ownSet != null && java.util.Arrays.equals(s.base, ownSet))
		{
			// Out of the water: their own walk is not a glide.
			normal = ownSet;
			ownSet = null;
		}

		var prev = previous;
		previous = s;
		if (prev == null)
		{
			remember(new Seen(s, true, false, false, s.server));
			return;
		}

		long dx = Math.abs(s.fineX - prev.fineX),
			dy = Math.abs(s.fineY - prev.fineY),
			moved = Math.max(dx, dy);
		if (moved > MAX_HOP_TILES * 128L)
		{
			// A teleport. Nothing of this is copied, and nothing queued
			// either: the follower catches up the way it always has.
			discard("teleport");
			recent.clear();
			coveredToMs = s.atMs;
			xpToCheck = false;
			listener.clearCrossings();
			return;
		}

		boolean planeChanged = s.plane != prev.plane,
			walkingPose = isWalkingPose(s.pose),
			oddPose = s.pose != -1 && !Ints.contains(normal, s.pose),
			animating = s.action != -1 || prev.action != -1;
		// A running jump: the server puts them further than their walk or run
		// goes, with a clip on, while the client still draws the walk. Moved
		// by the game, as a glide is, though it looks like walking.
		boolean leapt = !planeChanged && s.action != -1
			&& s.server.distanceTo2D(prev.server)
			> (s.pose == normal[1] ? 1 : 2);
		// A walking pose with a big step is a slow frame of ordinary steps;
		// a tile in one frame off a walking pose, with a clip on, is a hop.
		boolean hop = planeChanged || (moved > 256 && !walkingPose)
			// HOP_UNITS: A whole tile in one frame, off a walking pose, with an animation on:
			// a hop. A jump across a gap can put the player down one tile over with
			// nothing between; ordinary steps never cover a tile in a frame.
			|| (moved >= 128L /* HOP_UNITS */ && !walkingPose && (animating || oddPose));
		boolean walking = !planeChanged && !leapt && moved > 0 && walkingPose,
			glide = !planeChanged && moved > 0 && moved <= 256 && !walkingPose,
			odd = oddPose || s.action != -1 || glide;
		boolean unusual = (moved > 0 || planeChanged)
			&& (planeChanged || !walkingPose || oddPose || s.action != -1);
		remember(new Seen(s, !odd && !hop, walking, unusual, s.server));

		if (xpToCheck)
		{
			// Before this frame's run is handled, so anything rebuilt is
			// queued ahead of a crossing this frame confirms.
			xpToCheck = false;
			rebuildMissed(s.atMs);
		}

		if (cooling)
		{
			if (oddPose || s.action != -1)
				return;
			cooling = false;
		}

		if (run == null)
		{
			if (!odd || walking || s.interacting)
				return;
			// Begun from where they stood a frame ago: a glide has already left it.
			run = new Run(prev);
		}
		run.frames.add(s);
		if (run.crossing != null)
			run.crossing.append(s);

		if (s.interacting)
		{
			// A knock-back in a fight, a scripted step in a conversation.
			discard("interacting");
			return;
		}

		// A frame that repeats the last (more frames than game cycles) is
		// neither a glide nor a break in one, unless it shows a walk.
		if (moved > 0 || planeChanged || walkingPose)
		{
			run.glided += glide && run.lastGlided ? moved : 0;
			run.lastGlided = glide;
		}
		if (hop)
			run.hopMs = s.atMs;

		if (!run.confirmed)
		{
			boolean xp = lastXpMs >= run.startMs,
				hurt = lastDamageMs >= run.startMs;
			// GLIDE_UNITS: Fine units of gliding, past the first glide frame, before a glide
			// counts: three eighths of a tile. A forced move covers tiles.
			if (run.glided >= 48L /* GLIDE_UNITS */ || leapt)
				confirm();
			else if (run.hopMs >= 0 && (xp || hurt))
				confirm();
			else if (xp && run.displaced())
				confirm();
			else if (run.hopMs >= 0)
			{
				// Possibly a climb: the follower holds where it is rather than
				// snapping after the player while the XP is awaited.
				if (!run.announced)
				{
					run.announced = true;
					listener.expectCrossing(run.start());
				}
				long wait = onCourse(s.atMs) ? CONFIRM_WAIT_ON_COURSE_MS : CONFIRM_WAIT_MS;
				if (s.atMs - run.hopMs > wait)
				{
					// No XP and no fall: a ladder, a trapdoor, stairs.
					discard("no xp after the hop");
					return;
				}
			}
			else if (walking)
			{
				// Walked on: whatever played, it was not an obstacle.
				discard("walked on");
				return;
			}
		}

		if (odd || hop)
		{
			run.calmSinceMs = -1;
			run.calmWalked = false;
			run.steppedOffTo = null;
		}
		else if (run.calmSinceMs < 0)
		{
			// Back to normal as the server steps them off, with the drawn
			// player still a tile or two along the rope: calm from where it
			// put them down, once they are drawn there.
			if (run.steppedOffTo == null)
				run.steppedOffTo = s.server;
			if (s.tile().equals(run.steppedOffTo))
			{
				run.calmSinceMs = s.atMs;
				run.calmIndex = run.frames.size() - 1;
				run.calmWalked = walking;
			}
		}
		else
			run.calmWalked |= walking;

		// MAX_CROSSING_MS: The longest a crossing may run. Every obstacle and shortcut takes
		// seconds; a recording past half a minute is something else wearing an
		// odd pose - a carpet ride, swimming, carrying something in a minigame -
		// and is dropped, with that pose taken as normal until the player's own
		// set is back on them.
		// MAX_FRAMES: Frames kept for one crossing, a safety cap past MAX_CROSSING_MS: half a minute at three hundred a second.
		if (s.atMs - run.startMs > 30_000L /* MAX_CROSSING_MS */ || run.frames.size() > 9000 /* MAX_FRAMES */)
		{
			discard("ran past");
			cooling = true;
			if (s.weapon == normalWeapon)
			{
				// Whatever this is, it is how they move now, until their own
				// set is back.
				if (ownSet == null)
					ownSet = normal;
				normal = s.base.clone();
			}
			return;
		}

		if (run.calmSinceMs >= 0
			&& s.atMs - run.calmSinceMs >= (run.calmWalked ? WALK_OFF_MS : SETTLE_MS))
		{
			if (run.confirmed)
				finish();
			else if (run.hopMs < 0)
				// Stood still again with nothing moved: an emote, a swing.
				discard("nothing moved");
		}
	}

	boolean onCourse(long nowMs)
	{
		// ON_COURSE_MS: Agility XP this recently means the player is on a course. A lap of the longest takes about a minute.
		return lastXpMs != Long.MIN_VALUE && nowMs - lastXpMs <= 60_000L /* ON_COURSE_MS */;
	}

	void confirm()
	{
		run.confirmed = true;
		run.announced = true;
		run.crossing = Crossing.live(run.frames, normal);
		listener.queueCrossing(run.crossing);
	}

	void finish()
	{
		var done = run;
		run = null;
		done.crossing.end(done.calmIndex + 1, lastDamageMs >= done.startMs);
		coveredToMs = done.frames.get(done.calmIndex).atMs;
	}

	void discard(String why)
	{
		var dropped = run;
		run = null;
		if (dropped == null)
			return;
		if (dropped.crossing != null)
		{
			// Already handed over. Ended where it got to; and if it was not an
			// obstacle at all, one the follower has not begun is skipped.
			if (why.startsWith("ran past") || why.equals("interacting"))
				dropped.crossing.drop();
			else
				dropped.crossing.cut();
			coveredToMs = dropped.frames.get(dropped.frames.size() - 1).atMs;
		}
		else if (dropped.announced)
			listener.cancelExpectedCrossing();
	}

	void remember(Seen seen)
	{
		recent.addLast(seen);
		// BUFFER_MS: How much of the player is remembered for rebuilding a crossing the
		// signals missed when its XP arrives: ten seconds, longer than any one
		// obstacle of a rooftop course, at most {@link #BUFFER_FRAMES} frames.
		long oldest = seen.frame.atMs - 10_000L /* BUFFER_MS */;
		while (recent.size() > 3000 /* BUFFER_FRAMES */ || recent.peekFirst().frame.atMs < oldest)
			recent.removeFirst();
	}

	/**
	 * Agility XP arrived: if the player was moved oddly since the last
	 * crossing handed over, and before whatever is being watched now, that
	 * movement was an obstacle the signals missed. It is rebuilt from the
	 * remembered frames and queued like any other, late but not skipped.
	 *
	 * <p>It starts on the last frame of the player's own stand or walk before
	 * the odd movement, and ends on the first after it - or now, if they
	 * are still at it - as a crossing seen live would.
	 */
	void rebuildMissed(long nowMs)
	{
		// Odd frames that run straight into what is being watched lead into
		// it, a clip begun on the last step towards a climb: not a crossing
		// of their own.
		long until = run == null ? Long.MAX_VALUE : run.startMs;
		for (java.util.Iterator<Seen> back = recent.descendingIterator(); run != null && back.hasNext(); )
		{
			var seen = back.next();
			if (seen.frame.atMs >= run.startMs)
				continue;
			if (!seen.unusual)
				break;
			until = seen.frame.atMs;
		}
		List<Seen> window = new ArrayList<>();
		for (var seen : recent)
		{
			long at = seen.frame.atMs;
			if (at > coveredToMs && at < until)
				window.add(seen);
		}
		int last = -1;
		for (int i = window.size() - 1; i >= 0; i--)
		{
			if (window.get(i).unusual)
			{
				last = i;
				break;
			}
		}
		// REBUILD_RECENT_MS: XP rebuilds a crossing only from movement that ended this recently.
		// An obstacle pays as it completes; XP from a lamp, a book or a quest
		// comes long after any walk, and so rebuilds nothing.
		if (last < 0 || nowMs - window.get(last).frame.atMs > 3000L /* REBUILD_RECENT_MS */)
			return;

		// Back to the last stretch of their own stand or walk long enough to
		// have ended a crossing: the odd movement began after it.
		int first = last;
		boolean walked = false;
		for (int i = last - 1; i >= 0; i--)
		{
			var seen = window.get(i);
			if (!seen.calm)
			{
				first = i;
				walked = false;
				continue;
			}
			walked |= seen.walking;
			long stretch = window.get(first).frame.atMs - seen.frame.atMs;
			if (stretch >= (walked ? WALK_OFF_MS : SETTLE_MS))
				break;
		}
		int start = Math.max(0, first - 1);
		// As a crossing seen live ends: where the drawn player reaches the
		// tile the server stepped them off to.
		int end = window.size() - 1;
		WorldPoint steppedOffTo = null;
		for (int i = last + 1; i < window.size(); i++)
		{
			var seen = window.get(i);
			if (!seen.calm)
			{
				steppedOffTo = null;
				continue;
			}
			if (steppedOffTo == null)
				steppedOffTo = seen.server;
			if (seen.frame.tile().equals(steppedOffTo))
			{
				end = i;
				break;
			}
		}

		List<Crossing.Frame> frames = new ArrayList<>();
		for (int i = start; i <= end; i++)
			frames.add(window.get(i).frame);
		var rebuilt = new Crossing(frames, normal,
			lastDamageMs >= frames.get(0).atMs);
		if (rebuilt.getStart().equals(rebuilt.getEnd()))
			return;
		coveredToMs = window.get(end).frame.atMs;
		listener.queueCrossing(rebuilt);
	}

	/** Walk, run, back-pedal and the side-steps of the player's own set. */
	boolean isWalkingPose(int pose)
	{
		for (int i = 1; i <= 5 && i < normal.length; i++)
		{
			if (normal[i] == pose)
				return true;
		}
		return false;
	}

}

package com.follower;

import com.google.gson.*;
import java.io.IOException;
import java.nio.file.Files;
import java.util.*;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.*;

/**
 * Loads dialogs.json and reloads it when it changes, exactly as
 * {@link RuleLoader} does for phrases.json - same poll, same defaults-on-first-
 * run, same refusal to replace good content with nothing on a bad read; the
 * plumbing is {@link MergingLoader}'s.
 */
@Singleton
class DialogLoader extends MergingLoader<DialogLoader.DialogFile>
{
	/** Read from default-dialogs.json in the jar when it is missing. */
	static final String FILE_NAME = "dialogs.json";

	/** The bundled trees as of the last merge, for the three-way. */
	static final String BASE_FILE = "dialogs-seen.json";

	/** Handled by the node pass rather than as a field of the tree. */
	static final Set<String> TREE_FIELDS = Set.of("nodes", "id");

	/** Lines have their own pass; the id is what we matched on. */
	static final Set<String> NODE_FIELDS = Set.of("says", "id");

	/** The trees 1.4.0 shipped, the base for a file that has none; see RuleLoader. */
	static final String UNRECORDED_BASE = "/com/follower/seen/1.4.0-dialogs.json";

	static final int SUPPORTED_VERSION = 1;

	Map<String, DialogTree> trees = Collections.emptyMap();

	@Inject
	DialogLoader(Gson gson)
	{
		super(gson, DialogFile.class, FILE_NAME, BASE_FILE, "trees", "conversations");
	}

	/**
	 * Folds bundled conversation changes into the player's file, three ways.
	 *
	 * <p>The same upgrade gap {@code phrases.json} had, and fixed the same way -
	 * see {@link MergingLoader}. Appending only whole new trees meant a reworded
	 * node, an added choice or a fixed dead end reached nobody who already had
	 * the plugin.
	 *
	 * <p>Trees merge at two levels because that is how they are built: the tree
	 * carries its own fields and a list of nodes, and each node carries its own
	 * fields and its lines. A node the update added arrives, a node it removed
	 * goes unless the player had already changed it, and a node they have
	 * rewritten is theirs.
	 */
	@Override
	void merge(JsonObject bundled, JsonObject ours, JsonObject base) throws IOException
	{
		var mine = byId(array(ours, "trees"));
		var was = byId(array(base, "trees"));
		var trees = ours.getAsJsonArray("trees");
		int added = 0,
			updated = 0;
		for (var element : bundled.getAsJsonArray("trees"))
		{
			String id = idOf(element);
			if (id == null)
				continue;
			var held = mine.get(id);
			if (held == null)
			{
				trees.add(element);
				added++;
			}
			else if (mergeTree(held, was.get(id), element.getAsJsonObject()) > 0)
				updated++;
		}

		if (added + updated > 0)
			save(ours);
	}

	/** For a file that never merged, the trees 1.4.0 wrote; null only if even that cannot be read. */
	@Override
	JsonObject unrecordedBase(JsonObject ours)
	{
		return Files.exists(baseFile) ? null : resource(UNRECORDED_BASE);
	}

	/** One bundled tree, folded into the player's copy of it. */
	static int mergeTree(JsonObject held, JsonObject base, JsonObject bundled)
	{
		if (base == null)
			return bootstrap(held, bundled);

		int changes = fields(held, base, bundled, TREE_FIELDS);

		JsonArray nodes = array(held, "nodes"),
			shipped = array(bundled, "nodes");
		if (nodes == null || shipped == null)
			return changes;
		var wasNodes = byId(array(base, "nodes"));
		var shippedIds = byId(shipped).keySet();

		// Rebuilt rather than edited in place, because a node can leave.
		var kept = new JsonArray();
		Map<String, JsonObject> keptById = new HashMap<>();
		for (var element : nodes)
		{
			if (!element.isJsonObject())
				continue;
			var node = element.getAsJsonObject();
			String id = idOf(element);
			var before = wasNodes.get(id);
			if (before != null && !shippedIds.contains(id) && before.equals(node))
			{
				// The update removed it and the player never touched it.
				changes++;
				continue;
			}
			kept.add(node);
			if (id != null)
				keptById.putIfAbsent(id, node);
		}

		for (var element : shipped)
		{
			String id = idOf(element);
			if (id == null)
				continue;
			JsonObject now = element.getAsJsonObject(),
				node = keptById.get(id);
			if (node == null)
			{
				// Absent here: new upstream unless the player deleted it, and
				// the base is what tells the two apart.
				if (!wasNodes.containsKey(id))
				{
					kept.add(now);
					changes++;
				}
				continue;
			}
			// A node the base never had is one the player wrote; comparing it
			// with itself leaves it alone, which is the intent.
			var before = wasNodes.getOrDefault(id, node);
			changes += fields(node, before, now, NODE_FIELDS) + strings(node, "says", before, now);
		}

		if (changes > 0)
			held.add("nodes", kept);
		return changes;
	}

	/**
	 * The first run, with no record of what shipped before. As with the rules,
	 * the only honest question left is whether the player has written into
	 * this tree at all: a tree holding nothing but shipped lines has not been,
	 * and can be brought up to date without taking anything from anybody.
	 */
	static int bootstrap(JsonObject held, JsonObject bundled)
	{
		if (!untouched(allSays(held), allSays(bundled)) || held.equals(bundled))
			return 0;
		replace(held, bundled);
		return 1;
	}

	/** Every line the tree can speak, for the bootstrap's one question. */
	static List<String> allSays(JsonObject tree)
	{
		List<String> out = new ArrayList<>();
		var nodes = array(tree, "nodes");
		if (nodes != null)
		{
			for (var element : nodes)
			{
				if (element.isJsonObject())
					out.addAll(strings(element.getAsJsonObject(), "says"));
			}
		}
		return out;
	}

	DialogTree get(String id)
	{
		return id == null ? null : trees.get(id);
	}

	/** Every tree, in file order. */
	List<DialogTree> getTrees()
	{
		return new ArrayList<>(trees.values());
	}

	@Override
	int size()
	{
		return trees.size();
	}

	@Override
	void unreadable(List<String> problems)
	{
		errors = problems;
		status = "read error";
	}

	@Override
	void load(DialogFile parsed, List<String> problems)
	{
		if (parsed.version != SUPPORTED_VERSION)
			problems.add("version is " + parsed.version
				+ ", plugin expects " + SUPPORTED_VERSION);

		Map<String, DialogTree> valid = new LinkedHashMap<>();
		for (var tree : parsed.trees == null
			? Collections.<DialogTree>emptyList() : parsed.trees)
		{
			if (tree == null)
				continue;
			var found = tree.problems();
			problems.addAll(found);
			// A broken tree is left out rather than half-loaded: a
			// conversation that dead-ends mid-branch is worse than one
			// that never opens, because the player is already in it.
			if (found.isEmpty() && valid.put(tree.id, tree) != null)
				problems.add("Duplicate tree id '" + tree.id + "'");
		}

		trees = valid;
		loaded(problems, valid.size() + " conversations");
	}

	static class DialogFile
	{
		int version;
		List<DialogTree> trees;
	}
}

package com.follower;

import java.util.*;
import java.util.List;
import java.util.Map;

/**
 * A conversation, as data.
 *
 * <p>The follower's everyday talk script is bundled (talk.json) and never
 * changes, so it is no one's to edit. These are different: they are the conversations
 * the follower STARTS, they replace the everyday one while they are open, and
 * they are where the player's answer to a question actually comes from. That
 * makes them content rather than plumbing, and content belongs in a file
 * somebody can edit without a compiler.
 *
 * <p>Nodes are a list rather than a map so their order survives a round trip
 * through the file, which is what lets the editor show them as a table in the
 * order they were written rather than in whatever order a hash gives back.
 */
class DialogTree
{
	String id;

	/** Free text, ignored by the plugin. */
	String note;

	/** Which node the conversation opens on. Defaults to the first one. */
	String start;

	List<DialogNode> nodes;

	static class DialogNode
	{
		String id;

		/** Pages the FOLLOWER speaks, with its chathead. */
		List<String> says;

		/** Pages the PLAYER speaks, with theirs. */
		List<String> you;

		/** Where to go once the pages are done. Absent ends the conversation. */
		String next;

		List<DialogChoice> choices;

		/**
		 * Reaching this node answers the question the follower asked.
		 *
		 * <p>Any single plain word; {@code answered} rules match on it. This is
		 * the whole reason these trees exist: the answer used to be a word
		 * typed into public chat, which meant the follower was listening to the
		 * whole street and the player had to know the magic word. Picking an
		 * option cannot be misheard, cannot be ambiguous, and shows the player
		 * what their choices are - which is also why the vocabulary is not
		 * limited to yes and no. A menu offering "left" and "right" is exactly
		 * as unmistakable as one offering yes and no, and it can be a game.
		 */
		String answer;

		List<String> pages()
		{
			List<String> spoken = you != null && !you.isEmpty() ? you : says;
			return spoken == null ? new ArrayList<>() : spoken;
		}

		boolean isPlayerSpeaking()
		{
			return you != null && !you.isEmpty();
		}
	}

	static class DialogChoice
	{
		String label,
			next;
	}

	/**
	 * Every problem that would stop this tree working, as sentences.
	 *
	 * <p>A dialog fails silently in the worst possible way - the box opens and
	 * closes again, or a branch dead-ends on a node id with a typo in it - so
	 * the checks are done once at load and reported, rather than discovered by
	 * a player halfway through a conversation.
	 */
	List<String> problems()
	{
		List<String> found = new ArrayList<>();
		if (id == null || id.trim().isEmpty())
		{
			found.add("a tree with no id");
			return found;
		}
		if (nodes == null || nodes.isEmpty())
		{
			found.add(id + ": no nodes");
			return found;
		}

		Map<String, DialogNode> byId = new LinkedHashMap<>();
		for (var node : nodes)
		{
			if (node == null || node.id == null || node.id.trim().isEmpty())
			{
				found.add(id + ": a node with no id");
				continue;
			}
			if (byId.put(node.id, node) != null)
				found.add(id + ": two nodes called '" + node.id + "'");
		}

		String entry = startId();
		if (entry == null || !byId.containsKey(entry))
			found.add(id + ": starts at '" + entry + "', which is not a node");

		for (var node : byId.values())
		{
			if (node.next != null && !byId.containsKey(node.next))
				found.add(id + ": '" + node.id + "' continues to '" + node.next
					+ "', which is not a node");
			if (node.choices != null)
			{
				for (var choice : node.choices)
				{
					if (choice == null || choice.label == null || choice.label.trim().isEmpty())
					{
						found.add(id + ": '" + node.id + "' has a choice with no label");
						continue;
					}
					if (choice.next == null || !byId.containsKey(choice.next))
						found.add(id + ": '" + node.id + "' offers \"" + choice.label
							+ "\" leading to '" + choice.next + "', which is not a node");
				}
			}
			if (node.answer != null && !node.answer.matches("[a-zA-Z0-9-]+"))
				found.add(id + ": '" + node.id + "' answers '" + node.answer
					+ Resources.text("answerOneWord"));
			if (node.pages().isEmpty() && node.choices == null && node.next == null)
				found.add(id + ": '" + node.id + "' says nothing and goes nowhere");
		}

		// A tree the follower opens to ask something, that the player cannot
		// answer, is a tree that wastes the one moment it had.
		boolean answerable = false;
		for (var node : byId.values())
		{
			if (node.answer != null)
			{
				answerable = true;
				break;
			}
		}
		if (!answerable)
			found.add(id + Resources.text("noAnswers"));

		return found;
	}

	String startId()
	{
		if (start != null && !start.trim().isEmpty())
			return start;
		return nodes == null || nodes.isEmpty() || nodes.get(0) == null
			? null : nodes.get(0).id;
	}

	Map<String, DialogNode> byId()
	{
		Map<String, DialogNode> map = new LinkedHashMap<>();
		if (nodes != null)
		{
			for (var node : nodes)
			{
				if (node != null && node.id != null)
					map.put(node.id, node);
			}
		}
		return map;
	}
}

package com.follower;

import net.runelite.api.*;
import net.runelite.api.Model;

/**
 * A one-shot that starts and ends somewhere other than standing, eased in
 * from the standing pose and back out to it.
 *
 * <p>The client never blends one animation into the next: a new clip shows
 * its first frame at once. That is invisible for a real emote, which Jagex
 * authors to start and end on the idle, and plain for the HUMAN_*_IDLE mood
 * clips, which are standing stances in their own right and sit up to 104
 * units from the idle at both ends. Played as an emote, the body jumped into
 * the mood and jumped back out (QA, 15 Oct).
 *
 * <p>So for the first and last {@link #EASE_CYCLES} client cycles each vertex
 * is blended between where the idle's first frame puts it and where the clip
 * does, the same vertex lerp {@link WrapLerpController} uses across a loop's
 * seam, written into the client's per-frame temp the same way and under the
 * same guard.
 */
class EaseInOutController extends AnimationController
{
	/** A quarter of a second each way: a few frames of any clip, short of a gesture of its own. */
	static final int EASE_CYCLES = 12;

	final Client client;
	final int standingPose;

	/** Client cycles since the clip began. */
	int elapsed;

	/** The standing pose's vertices, snapshot on the first frame drawn. */
	float[] standingXyz;
	boolean unsafe;

	EaseInOutController(Client client, Animation animation, int standingPose)
	{
		super(client, animation);
		this.client = client;
		this.standingPose = standingPose;
	}

	@Override
	public void tick(int ticks)
	{
		super.tick(ticks);
		elapsed += ticks;
	}

	/** How much of the clip shows, 0 standing to 1 the clip itself. */
	static float weight(int elapsed, int duration)
	{
		int remaining = duration - elapsed;
		return Math.max(0f, Math.min(1f, Math.min(elapsed, remaining) / (float) EASE_CYCLES));
	}

	@Override
	public Model animate(Model model, AnimationController other)
	{
		var animation = getAnimation();
		if (animation == null || other != null || unsafe || animation.isMayaAnim()
			|| animation.getFrameLengths() == null)
			return super.animate(model, other);
		float weight = weight(elapsed, duration(animation));
		if (weight >= 1f)
			return super.animate(model, other);

		// Snapshot BEFORE the clip's own frame: applyTransformations hands back
		// the client's shared scratch buffer, which the next call overwrites.
		if (standingXyz == null)
		{
			var standing = client.loadAnimation(standingPose);
			standingXyz = standing == null ? null
				: WrapLerpController.snapshot(client.applyTransformations(model, standing, 0, null, 0));
			if (standingXyz == null)
			{
				unsafe = true;
				return super.animate(model, other);
			}
		}

		var temp = super.animate(model, other);
		if (temp == null)
			return null;
		if (!WrapLerpController.separate(temp, model) || temp.getVerticesCount() * 3 != standingXyz.length)
		{
			unsafe = true;
			return temp;
		}

		WrapLerpController.lerpInto(temp, standingXyz, null, weight);
		return temp;
	}

	static int duration(Animation animation)
	{
		int total = 0;
		for (int length : animation.getFrameLengths())
			total += length;
		return total;
	}
}

package com.follower;

import com.google.gson.Gson;
import java.awt.*;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.Files;
import java.nio.file.Path;
import javax.swing.*;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;

/**
 * What the two file editors - Messages (phrases.json) and Conversations
 * (dialogs.json) - have in common: the file and a pretty-printing Gson for it,
 * the guard that gives unsaved edits a say on every road out of the window,
 * the scrolling list, the status line, Reload and Save, and the atomic write.
 * Each editor supplies its own top strip, its rows, and refresh() and save().
 */
abstract class EditorDialog extends JDialog
{
	final Gson gson;
	final Path file;

	/** The rows; a vertical box inside {@link #scroll}. */
	final JPanel list;
	final JScrollPane scroll;
	final JLabel status = Ui.label(" ", ColorScheme.MEDIUM_GRAY_COLOR);

	/** The right-hand buttons; an editor puts its own in front of Reload and Save. */
	final JPanel buttons = Ui.panel(new FlowLayout(FlowLayout.RIGHT, 6, 0));

	/** An error status's wrap width, in the HTML renderer's px (x1.3 on screen). */
	final int statusWrap;

	/**
	 * Whether anything on screen differs from the file. Guards every road out
	 * of the window - closing, reopening, switching category or tree - because
	 * the first design lost ten typed lines to a stray click on the X.
	 */
	boolean dirty;

	final DocumentListener dirtyMarker = Ui.onChange(() -> dirty = true);

	EditorDialog(String title, Gson gson, Path file, JPanel list, int statusWrap)
	{
		super((java.awt.Frame) null, title, false);
		this.gson = gson.newBuilder().setPrettyPrinting().disableHtmlEscaping().create();
		this.file = file;
		this.list = Ui.column(list);
		this.statusWrap = statusWrap;
		scroll = Ui.scroller(list);
	}

	/**
	 * Reload and Save, after the editor's own buttons, and the guard that
	 * gives unsaved edits a say when the window is closed.
	 */
	void addReloadAndSave()
	{
		setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
		addWindowListener(new java.awt.event.WindowAdapter()
		{
			@Override
			public void windowClosing(java.awt.event.WindowEvent e)
			{
				if (confirmDirty())
					setVisible(false);
			}
		});

		var reload = new JButton("Reload");
		reload.setToolTipText("Discard unsaved edits and reload from disk");
		reload.addActionListener(e -> refresh());
		buttons.add(reload);
		var save = new JButton("Save");
		save.addActionListener(e -> save());
		buttons.add(save);
	}

	/**
	 * Lays the window out - the editor's own strip on top, the list, then the
	 * status and buttons - and sizes it. Narrower than {@code width}, the
	 * fixed-width hints are cut mid-word (QA3).
	 */
	void layOut(JComponent top, int width, int height)
	{
		var root = Ui.panel(new BorderLayout(0, 6));
		root.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		root.add(top, BorderLayout.NORTH);
		root.add(scroll, BorderLayout.CENTER);

		var bottom = Ui.panel(new BorderLayout());
		bottom.add(status, BorderLayout.CENTER);
		bottom.add(buttons, BorderLayout.EAST);
		root.add(bottom, BorderLayout.SOUTH);

		setContentPane(root);
		setPreferredSize(new Dimension(width, height));
		pack();
		setMinimumSize(new Dimension(width, 400));
	}

	/** Reads the file into the window, dropping any unsaved edits. */
	abstract void refresh();

	/** @return whether the file was written */
	abstract boolean save();

	/**
	 * Shows the window, fronting it if already open. Fresh file contents
	 * unless there are edits in progress - alt-tabbing away and clicking the
	 * panel button again must not wipe half-typed lines.
	 */
	void open()
	{
		if (!dirty)
			refresh();
		setVisible(true);
		toFront();
	}

	/**
	 * Gives unsaved edits a say before they would be lost.
	 *
	 * @return true when the action may proceed - nothing was pending, the
	 * edits were saved, or the user chose to discard them
	 */
	boolean confirmDirty()
	{
		if (!dirty)
			return true;
		int choice = JOptionPane.showOptionDialog(this,
			"There are unsaved changes.", "Save changes?",
			JOptionPane.YES_NO_CANCEL_OPTION, JOptionPane.QUESTION_MESSAGE, null,
			new Object[]{"Save", "Discard", "Cancel"}, "Save");
		if (choice == 0)
			return save();
		if (choice == 1)
		{
			dirty = false;
			return true;
		}
		return false;
	}

	/**
	 * Replaces the file in one step, via a sibling temp file.
	 *
	 * <p>The plugin polls this same file every game tick and reloads it when it
	 * changes, which is what makes editing feel live. Writing in place truncates
	 * it first, so a poll landing mid-write reads half a file; a rename is a
	 * single step - the poller sees the old file or the new one, never a torn
	 * one.
	 *
	 * <p>Windows will not rename over a file another handle has open, and the
	 * plugin's poller opens this one every couple of ticks, so the rename can
	 * lose that race. When it does, write in place rather than lose the edit:
	 * the loader keeps its previous rules if a poll catches the file
	 * half-written, and picks the finished file up on the following poll. (A
	 * sleep-and-retry between move attempts would spare that one-in-a-thousand
	 * poll, but the Hub forbids Thread.sleep; this is the surviving tradeoff.)
	 */
	void writeAtomically(String contents) throws IOException
	{
		var temp = file.resolveSibling(file.getFileName() + ".tmp");
		byte[] bytes = contents.getBytes(StandardCharsets.UTF_8);
		Files.write(temp, bytes);

		try
		{
			Files.move(temp, file,
				StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (AtomicMoveNotSupportedException e)
		{
			// Some filesystems cannot promise it; a plain replace is still
			// one call rather than a truncate followed by a write.
			Files.move(temp, file, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (FileSystemException e)
		{
			Files.write(file, bytes);
			Files.deleteIfExists(temp);
		}
	}

	void setStatus(String text, boolean error)
	{
		// An error can run long, and a plain label clips it mid-sentence;
		// wrapped, it is read whole.
		status.setText(error ? Ui.html(statusWrap, text) : text);
		status.setForeground(error ? ColorScheme.PROGRESS_ERROR_COLOR : ColorScheme.MEDIUM_GRAY_COLOR);
	}
}

package com.follower;

import java.util.*;
import java.util.List;
import java.util.Random;
import java.util.function.*;
import java.util.function.Consumer;
import net.runelite.api.*;
import net.runelite.api.Player;
import net.runelite.api.coords.*;
import lombok.*;
import java.util.Map;
import java.util.function.Predicate;
import static com.follower.ErrandController.Errand.*;
import static com.follower.ErrandController.State.*;

/**
 * Little life errands: now and then the follower notices something nearby - a
 * bank, an altar, a fire, a cat - announces itself, walks over, has its
 * moment, and comes back. Everything is assembled from existing machinery:
 * {@link FollowerEntity#stayAt} for the trip (BFS, closest-approach),
 * {@link FollowerEntity#teleportToPlayer} for the way home, and the rules
 * engine for every line (group "errand", so the words stay editable).
 *
 * <p>Errands must never cost the player anything: combat, dialogs, thrall
 * mode, the Wilderness, or the player simply leaving all abort or suppress.
 */
class ErrandController
{
	/**
	 * The errand types; the lower-case names are the keys the rule
	 * {@code names} lists match. Each comes with its setting, and a roll
	 * offers them in this order.
	 */
	@RequiredArgsConstructor
	enum Errand
	{
		BANK("Bank visits", FollowerConfig::errandBank),
		ALTAR("Altar visits", FollowerConfig::errandAltar),
		FIRE("Warming up", FollowerConfig::errandFire),
		/** The 10% fire variant: walks INTO it. Announces itself as FIRE, and
		 * a roll never offers it on its own. */
		FIREDEATH("Warming up, too close", config -> false),
		CAT("Cats", FollowerConfig::errandCat),
		BOOTLACE("Bootlaces", FollowerConfig::errandBootlace),
		GLANCE("Did you see that?", FollowerConfig::errandGlance),
		/** Stops where it stands and writes something up in its scroll. */
		DOCUMENT("Field notes", FollowerConfig::errandDocument),
		/** Walks to something notable, looks at it, and writes THAT up. */
		STUDY("Field study", FollowerConfig::errandStudy),
		/** Plain nosiness: walks to something curious, looks, then notes it
		 * down in the scroll - everything explored is for posterity. Also
		 * the one errand with an arrival trigger - see noticeArrival. */
		EXPLORE("Exploring", FollowerConfig::errandExplore);

		final String key = name().toLowerCase(Locale.ROOT);
		/** What the side panel calls it; the settings use the same words. */
		final String label;
		/** Whether its setting is on. */
		final Predicate<FollowerConfig> enabled;
	}

	enum State
	{
		IDLE, TRAVELING, DOING, RETURNING
	}

	/**
	 * Writing in a scroll with a quill, the pose the Advanced posing window
	 * shows as Write with a quill. The animation is authored to play once,
	 * with no restart frame; held as a pose override it lifts the scroll once
	 * and writes on over its writing frames for as long as the pose is held,
	 * and lowers it when let go of (FollowerEntity's holdTheWriting and
	 * WRITE_PUT_AWAY).
	 */
	// Public: the minutes-taking borrows the same stance and props, so the
	// documenting look has exactly one definition.
	static final int WRITE_SCROLL_POSE = 13302;

	/**
	 * The two things the writing pose names for its hands, as the game draws
	 * them: the charting quill in the left hand (the shield slot) and the
	 * scroll it writes in in the right (the weapon slot). Held together
	 * through {@link Hands#hold(int, int)}.
	 */
	static final int QUILL_PROP = 31829,
		SCROLL_PROP = 31830;

	/**
	 * What the scribe considers worth walking over to.
	 *
	 * <p>Matched by exact name against the loaded scene, the same way the bank
	 * and altar errands find their targets. A name that never matches costs
	 * nothing - that study simply never fires - so the honest verification is
	 * in game: {@code ::follower errandscan} lists what the scene actually
	 * calls things. Every name here must have its study-<slug> start and end
	 * rules in phrases.json; a lint holds the two lists together.
	 *
	 * <p>Deliberately the mundane fixtures of the world rather than its
	 * wonders. The follower already has area lines for the famous things; the
	 * joke of the field study is the seriousness applied to a crate.
	 */
	static final String[] STUDY_TARGETS = {
		"Anvil", "Furnace", "Well", "Fountain", "Statue", "Bookcase", "Crate",
	};

	/**
	 * The errand-event key a studied or explored thing announces itself
	 * under, e.g. "study-anvil".
	 *
	 * @param kind the errand's own key, "study" or "explore"
	 */
	static String siteKey(String kind, String objectName)
	{
		return kind + "-" + objectName.toLowerCase(Locale.ROOT).replace(' ', '-');
	}

	/**
	 * What plain curiosity considers worth a look.
	 *
	 * <p>The study list is the mundane fixtures, deadpan; this is the other
	 * register - the things a person new to a place actually noses at: what's
	 * in the chest, where the trapdoor goes, what the noticeboard says. Same
	 * contract as the study list: matched by exact scene name, a name that
	 * never matches costs nothing, {@code ::follower errandscan} is the
	 * verification, and the lint holds every entry to its explore-<slug>
	 * start and end rules in phrases.json.
	 */
	static final String[] EXPLORE_TARGETS = {
		"Chest", "Trapdoor", "Signpost", "Noticeboard", "Gravestone",
		"Scarecrow", "Web",
	};

	/**
	 * Every errand key the force command accepts, straight from the enum so
	 * the chat command's validation can never drift from what exists.
	 */
	static List<String> keys()
	{
		return new ArrayList<>(displayNames().keySet());
	}

	/** Every errand key with its display name, in the order keys() gives them. */
	static Map<String, String> displayNames()
	{
		Map<String, String> names = new java.util.LinkedHashMap<>();
		for (var errand : Errand.values())
			names.put(errand.key, errand.label);
		return names;
	}

	/**
	 * What holds the prop. Implemented by the plugin, which owns the follower's
	 * composed appearance; the errand only says when the scroll comes out and
	 * when it goes away. Release must be idempotent - it is also called from
	 * the abort and reset paths, where nothing may be held.
	 */
	interface Hands
	{
		void hold(int itemId);

		/**
		 * Puts a thing in each hand, as an animation names them: the left in
		 * the shield slot, the right in the weapon slot - the quill and the
		 * scroll of the writing pose. One {@link #release} lets go of both,
		 * and {@link #isHolding} is true while they are out. Hands that only
		 * know one hand hold the right-hand thing.
		 */
		default void hold(int leftItemId, int rightItemId)
		{
			hold(rightItemId);
		}

		void release();

		/**
		 * Whether something is held right now. The scroll and a borrowed
		 * tool share the weapon slot, so whichever is out first keeps it:
		 * the flourish skips its scroll over a tool, the borrow skips its
		 * tool over a scroll. Default false for hands that never say.
		 */
		/**
		 * Puts something on, in a slot other than the hand: the hat of a
		 * skilling outfit while the tool stays in the hand. Hands that only
		 * know the hand wear nothing, and say so through {@link #isWearing}.
		 */
		default void wear(int itemId)
		{
		}

		/** Takes off whatever {@link #wear} put on. Idempotent. */
		default void takeOff()
		{
		}

		default boolean isWearing()
		{
			return false;
		}

		default boolean isHolding()
		{
			return false;
		}
	}

	/**
	 * Praying at an altar: HUMAN_PRAY_LOOP held as a pose, which kneels and
	 * stays kneeling (frame step 5), then the rise from the one-shot kneel to
	 * stand. That one-shot, 645, played alone is 3.9 ticks and ends almost
	 * upright, so the follower knelt once and stood idle at the altar for the
	 * rest of the visit (QA, 15 Oct).
	 */
	static final int PRAY_LOOP = 179,
		GET_UP = FollowerEntity.PRAY_STAND_UP;

	/** Bending down: petting the cat, seeing to the bootlace. */
	static final int BEND_ANIMATION = 827;

	/**
	 * AnimationID.HUMAN_FIRECOOKING: kneeling at the flames, hands toward
	 * them. The cache has no dedicated warming animation; this reads right.
	 * (FORESTRY_CAMPFIRE 10082 turned out to be the campfire's own animation.)
	 */
	static final int WARM_ANIMATION = 897;

	/**
	 * The warming replayed this often, as the fireside seat does: the clip is
	 * 3.1 ticks, and played once the follower knelt and then stood about at
	 * the fire for four seconds (QA, 15 Oct). Three times over the visit.
	 */
	static final int WARM_EVERY_TICKS = 4;

	static final int TELEPORT_ARRIVE_ANIMATION = 715;

	/** SpotanimID.TELEPORT_CASTING and TELEPORT_REVERSE: swirl out, swirl back in. */
	static final int TELEPORT_CAST_SPOTANIM = 111;

	static final int SEARCH_RADIUS = 12,
		TRAVEL_TIMEOUT_TICKS = 25,
		RETRY_TICKS = 200;

	final Client client;
	final FollowerEntity follower;
	final FollowerConfig config;
	final Consumer<TriggerEvent> dispatch;
	final SpotAnimRepository spotAnims;

	/** True while the follower is otherwise engaged (dialog open, thrall mode). */
	final BooleanSupplier busy;

	State state = IDLE;

	/** True while an errand owns the follower's feet, so nothing else moves it. */
	boolean isBusy()
	{
		return state != IDLE;
	}

	Errand current;
	WorldPoint targetTile,
		errandSite;
	int waitTicks,
		nextRollTicks;
	String forceKey;

	/** The look phase of a study or explore: facing the thing before the
	 * scroll comes out. */
	int studyLookTicks;

	/** What the current study or explore announced itself as, e.g. "study-anvil". */
	String currentSiteKey;

	/** True from a region change until the follower has had its look around. */
	boolean arrivalWatched;

	/** Ticks the player has to hold still before the arrival look begins. */
	int arrivalSettleTicks;

	/** Ticks until the next arrival may trigger an explore; the schedule is
	 * untouched by this - a shopping trip through four regions must not
	 * become four inspections. */
	int arrivalCooldownTicks;

	/** Where the player stood last idle tick, for the settle watch. */
	WorldPoint lastPlayerTile;

	static final int ARRIVAL_SETTLE_TICKS = 8;

	/**
	 * The player has arrived somewhere new. Once they settle - hold still for
	 * a few ticks - the follower goes and noses at something nearby, if the
	 * scene offers anything from the explore list and the cooldown allows.
	 * The scheduled roll is the follower on its own time; this is curiosity
	 * about THIS place, which is the half that reads as a companion relating
	 * to the world rather than running a timer.
	 */
	void noticeArrival()
	{
		// An instance's region id names a slot, not a place: a quest scene, a house
		// or a raid is "somewhere new" on every visit. Play test, 9 Oct: tailing the
		// guard in Children of the Sun, the follower went off to a chest. A look
		// still pending from the region left goes with it.
		var view = client.getTopLevelWorldView();
		arrivalWatched = view == null || !view.isInstance();
		arrivalSettleTicks = ARRIVAL_SETTLE_TICKS;
	}

	/** Test hook: run an errand now - a specific one by name, or any ("*"). */
	void force(String key)
	{
		force(key, false);
	}

	/**
	 * As {@link #force(String)}, with the option of nobody hearing of it.
	 *
	 * @param silent whether the errand's start and end lines are skipped.
	 * The skilling company sends the follower to kneel beside a player
	 * praying at an altar, and that is company, not an errand worth a remark
	 */
	void force(String key, boolean silent)
	{
		forceKey = key == null || key.isEmpty() ? "*" : key.toLowerCase(Locale.ROOT);
		forceSilently = silent;
	}

	/** Whether the forced errand waiting to run keeps its lines to itself. */
	boolean forceSilently;

	/**
	 * Told the key of a forced errand that could not start where the follower
	 * is. The command that asked for it promised a run, so the player hears
	 * why there was none; a silent force tells nobody.
	 */
	@Setter
	Consumer<String> onForcedMiss = key -> { };

	/**
	 * Whether a work session is on. Errands do not start during one; the
	 * exception is the errand the session itself asks for through
	 * {@link #force(String, boolean)}, which is company rather than a
	 * wander, so only the unforced starts read this.
	 */
	@Setter
	BooleanSupplier session = () -> false;

	/** Whether the errand under way says nothing at either end. */
	boolean silent;

	/** The errand's start or end, unless this run was asked to keep quiet. */
	void announce(TriggerEvent event)
	{
		if (!silent)
			dispatch.accept(event);
	}

	final Hands hands;

	/** Every roll the errands make: the schedule, the order, the details. */
	final Random random;

	ErrandController(Client client, FollowerEntity follower, FollowerConfig config,
		Consumer<TriggerEvent> dispatch, SpotAnimRepository spotAnims,
		BooleanSupplier busy, Hands hands)
	{
		this(client, follower, config, dispatch, spotAnims, busy, hands, new Random());
	}

	/** As above, with the rolls seeded, so a long simulation plays out the same every run. */
	ErrandController(Client client, FollowerEntity follower, FollowerConfig config,
		Consumer<TriggerEvent> dispatch, SpotAnimRepository spotAnims,
		BooleanSupplier busy, Hands hands, Random random)
	{
		this.client = client;
		this.follower = follower;
		this.config = config;
		this.dispatch = dispatch;
		this.spotAnims = spotAnims;
		this.busy = busy;
		this.hands = hands;
		this.random = random;
		reset();
	}

	/** Logout/shutdown: clean slate, fresh schedule. */
	void reset()
	{
		putTheScrollAway();
		state = IDLE;
		current = null;
		targetTile = null;
		errandSite = null;
		// Unlike clearErrand, this is the logout path. A forced errand that
		// never got to run is not owed to the next session - the chat command
		// asking for it was in the one before.
		forceKey = null;
		arrivalWatched = false;
		arrivalSettleTicks = 0;
		arrivalCooldownTicks = 0;
		lastPlayerTile = null;
		nextRollTicks = scheduleTicks();
	}

	/** Call once per game tick, on the client thread. */
	void tick()
	{
		if (!config.errandsEnabled())
		{
			if (state != IDLE)
				abort();
			// One asked for before errands were switched off is not owed
			// whenever they next come back on.
			forceKey = null;
			forceSilently = false;
			return;
		}

		if (arrivalCooldownTicks > 0)
			arrivalCooldownTicks--;

		if (state == IDLE)
		{
			idleTick();
			return;
		}

		// An active errand must never inconvenience the player.
		if (!safeToContinue())
		{
			abort();
			return;
		}

		if (state == TRAVELING)
		{
			var at = follower.getWorldLocation();
			// Fully settled, not merely close: an animation started while the
			// last steps play out is cancelled by the movement system.
			boolean arrived = at != null && targetTile != null
				&& at.distanceTo(targetTile) <= 2 && follower.isSettled();
			if (arrived || --waitTicks <= 0)
				beginDoing();
		}
		else if (state == DOING)
		{
			// The study looks BEFORE it writes: a few ticks facing the thing,
			// and only then the scroll. Reversing that order reads as a scribe
			// deciding the conclusion before the evidence.
			if (studyLookTicks > 0 && --studyLookTicks == 0)
				takeOutTheScroll();
			if (--waitTicks <= 0)
				finish();
			else if (current == FIRE && waitTicks % WARM_EVERY_TICKS == 0)
				follower.playAnimation(WARM_ANIMATION);
			else if (current == ALTAR && waitTicks == 1)
			{
				// Up off the knees a tick before the walk home, which would
				// cancel the get-up on its first frame.
				follower.clearPoseOverride(PRAY_LOOP);
				follower.playAnimation(GET_UP);
			}
		}
		else if (state == RETURNING)
		{
			if (--waitTicks <= 0)
				completeReturn();
		}
	}

	// ------------------------------------------------------------------ idle

	void idleTick()
	{
		if (forceKey != null)
		{
			String key = forceKey;
			forceKey = null;
			// Set before the start, since the start is what announces it.
			silent = forceSilently;
			forceSilently = false;
			if (clearToStart())
			{
				for (var errand : Errand.values())
				{
					if (("*".equals(key) || errand.key.equals(key)) && tryStart(errand))
						return;
				}
			}
			boolean quiet = silent;
			silent = false;
			if (!quiet)
				onForcedMiss.accept(key);
			return;
		}

		// The arrival look: the player entered a new region and has now held
		// still long enough to count as settled. Watching stillness rather
		// than the region edge matters - regions change constantly mid-run,
		// and a follower that peels off while the player is still moving is
		// aborted three ticks later by the distance check, which reads as a
		// glitch rather than a character.
		if (arrivalWatched)
		{
			var walker = client.getLocalPlayer();
			var here = walker == null ? null : walker.getWorldLocation();
			// A tool kept between trees is still in the hand, and every errand
			// lets go of the hand when it ends. It goes back within the minute,
			// so the look waits for it, and for the bow, rather than being lost
			// to it. A session's own tool is no such pause: that look is lost
			// to the work, as ever.
			if (here == null || !here.equals(lastPlayerTile)
				|| (hands.isHolding() && !session.getAsBoolean()))
				arrivalSettleTicks = ARRIVAL_SETTLE_TICKS;
			else if (--arrivalSettleTicks <= 0)
			{
				arrivalWatched = false;
				if (arrivalCooldownTicks == 0 && config.errandExplore()
					&& safeToStart() && tryStart(EXPLORE))
				{
					arrivalCooldownTicks = 700 /* ARRIVAL_COOLDOWN_TICKS */;
					// Counts as its turn, or the roll could offer another
					// explore straight after this one.
					lastRun.put(EXPLORE, client.getTickCount());
					lastPlayerTile = here;
					return;
				}
			}
			lastPlayerTile = here;
		}

		if (--nextRollTicks > 0)
			return;
		if (!safeToStart())
		{
			nextRollTicks = RETRY_TICKS;
			return;
		}

		// An errand that has just run stands aside entirely; the rest are
		// offered stalest first. Between them, the errands that need
		// something in the world get their turn when that something is
		// there, instead of losing every roll to the three that never fail.
		List<Errand> candidates = new ArrayList<>();
		for (var errand : Errand.values())
		{
			if (errand.enabled.test(config) && offAgainCooldown(errand))
				candidates.add(errand);
		}
		orderByStaleness(candidates);

		for (var errand : candidates)
		{
			if (tryStart(errand))
			{
				lastRun.put(errand, client.getTickCount());
				return;
			}
		}
		nextRollTicks = RETRY_TICKS;
	}

	boolean tryStart(Errand errand)
	{
		switch (errand)
		{
			case BANK:
			{
				// Most banks have booth/chest OBJECTS; the Grand Exchange has
				// only banker NPCs (measured by scan - no booth object there).
				var bank = findObject(
					name -> SkillingController.BANK_NAMES.test(name)
						|| name.equals("Grand Exchange booth"));
				if (bank == null)
					bank = findNpc(name -> name.equals("Banker")
						|| name.equals("Grand Exchange Clerk"));
				// Closest approach stops the walk in front of a booth, but one
				// the map calls open floor is walked into, and the feet refuse
				// to stop in that: the tile beside it then, as at a fire.
				return startTravelErrand(errand, bank) || startAdjacentErrand(errand, bank);
			}
			case ALTAR:
				return startTravelErrand(errand, findObject(name -> name.equals("Altar")));
			case FIRE:
			{
				var fire = findObject(HotGround::isFire);
				if (fire == null)
					return false;
				// FIRE_DEATH_PERCENT: Chance the fire errand goes catastrophically wrong.
				if (random.nextInt(100) < 10 /* FIRE_DEATH_PERCENT */)
					// The rare version, in which warming the hands goes
					// catastrophically wrong.
					return startTravelErrand(FIREDEATH, fire);
				// Fires are walkable: BESIDE the flames, never in them.
				return startAdjacentErrand(errand, fire);
			}
			case FIREDEATH:
				// Only rolled from FIRE naturally; reachable directly by the
				// force command for testing. Walks straight INTO the flames.
				return startTravelErrand(errand, findObject(HotGround::isFire));
			case CAT:
				// NPCs don't block either; standing ON the cat ruins the moment.
				return startAdjacentErrand(errand, findNpc(
					name -> name.equals("Cat") || name.equals("Kitten") || name.equals("Stray dog")));
			case BOOTLACE:
			case DOCUMENT:
			{
				// No trip at all: stop where it stands and see to the boot, or
				// - something here is worth the record, apparently - scroll and
				// pose together, the read running long enough to look deliberate.
				current = errand;
				errandSite = follower.getWorldLocation();
				follower.stayHere();
				if (errand == BOOTLACE)
					follower.playAnimation(BEND_ANIMATION);
				else
					takeOutTheScroll();
				announce(TriggerEvent.errand(TriggerEvent.Type.ERRAND_START, errand.key));
				state = DOING;
				waitTicks = errand == BOOTLACE ? 6 : 12 + random.nextInt(8);
				return true;
			}
			case STUDY:
			case EXPLORE:
			{
				// Whatever notable fixture the scene has closest, or for the
				// explore the same hunt in the other register: whatever
				// curiosity it offers. A scene with none of them simply
				// produces no study, or no exploring, today.
				List<String> names = new ArrayList<>(java.util.Arrays.asList(
					errand == STUDY ? STUDY_TARGETS : EXPLORE_TARGETS));
				Collections.shuffle(names, random);
				for (String name : names)
				{
					var found = findObject(name::equals);
					if (found != null && beginSiteVisit(errand, found, siteKey(errand.key, name)))
						return true;
				}
				return false;
			}
			case GLANCE:
			{
				var local = client.getLocalPlayer();
				if (local == null || local.getWorldLocation() == null)
					return false;
				var p = local.getWorldLocation();
				int[][] dirs = {{3, 0}, {-3, 0}, {0, 3}, {0, -3}};
				int[] dir = dirs[random.nextInt(dirs.length)];
				return startTravelErrand(errand,
					p.dx(dir[0]).dy(dir[1]));
			}
			default:
				return false;
		}
	}

	/**
	 * Starts a study of a specific named thing. Package-private as the test
	 * seam: the find half needs a real scene, but everything after the find -
	 * the walk, the look, the scroll, the write-up, the return - is the part
	 * with lifecycle promises, and this is where a test can inject the thing
	 * the fake scene cannot provide.
	 */
	boolean beginStudyAt(WorldPoint target, String objectName)
	{
		return beginSiteVisit(STUDY, target, siteKey("study", objectName));
	}

	/** The explore twin of {@link #beginStudyAt}, and a test seam for the same reason. */
	boolean beginExploreAt(WorldPoint target, String objectName)
	{
		return beginSiteVisit(EXPLORE, target, siteKey("explore", objectName));
	}

	/**
	 * The shared trip to a named thing: beside it, facing it, announced by
	 * name. The walkable targets (fires, cats) come this way too, under
	 * their errand's own key.
	 */
	boolean beginSiteVisit(Errand errand, WorldPoint target, String siteKey)
	{
		List<WorldPoint> besides = new ArrayList<>(List.of(
			target.dx(1),
			target.dx(-1),
			target.dy(1),
			target.dy(-1)));
		var from = follower.getWorldLocation();
		if (from != null)
			besides.sort(Comparator.comparingInt(p -> p.distanceTo(from)));
		for (var beside : besides)
		{
			if (follower.stayAt(beside))
			{
				follower.setStayFaceTile(target);
				current = errand;
				currentSiteKey = siteKey;
				targetTile = beside;
				errandSite = target;
				announce(TriggerEvent.errand(
					TriggerEvent.Type.ERRAND_START, currentSiteKey));
				state = TRAVELING;
				waitTicks = TRAVEL_TIMEOUT_TICKS;
				return true;
			}
		}
		return false;
	}

	/** For walkable targets (fires, cats): aim at a free tile BESIDE them. */
	boolean startAdjacentErrand(Errand errand, WorldPoint target)
	{
		return target != null && beginSiteVisit(errand, target, errand.key);
	}

	boolean startTravelErrand(Errand errand, WorldPoint target)
	{
		// The one thing in the plugin that walks INTO a fire on purpose is
		// the gag that does it for the laugh. The feet refuse every other
		// route onto one, so this trip has to say so outright.
		if (target == null || !(errand == FIREDEATH
			? follower.insistOn(target) : follower.stayAt(target)))
			return false;
		// Once arrived, face the business itself - not the player. For the
		// glance the target IS where it stands, so the facing helper no-ops
		// and the follower keeps staring the way it walked. Also right.
		follower.setStayFaceTile(target);
		current = errand;
		targetTile = target;
		errandSite = target;
		// The doomed fire trip announces itself as an innocent warm-up: the
		// joke needs the audience not to see it coming.
		String announce = errand == FIREDEATH ? FIRE.key : errand.key;
		announce(TriggerEvent.errand(TriggerEvent.Type.ERRAND_START, announce));
		state = TRAVELING;
		waitTicks = TRAVEL_TIMEOUT_TICKS;
		return true;
	}

	// ---------------------------------------------------------------- active

	void beginDoing()
	{
		state = DOING;
		switch (current)
		{
			case STUDY:
				// Look, then write. The whole visit runs about twelve seconds:
				// four of honest looking, the rest with the scroll out.
				studyLookTicks = 4;
				waitTicks = 18 + random.nextInt(5);
				break;
			case EXPLORE:
				// Look, then note it down - everything explored is for
				// posterity. Same beat as the study, a touch brisker: the
				// scribe writes a report, the explorer jots an entry.
				studyLookTicks = 4;
				waitTicks = 14 + random.nextInt(5);
				break;
			case ALTAR:
				follower.setPoseOverride(PRAY_LOOP);
				waitTicks = 8;
				break;
			case FIRE:
				follower.playAnimation(WARM_ANIMATION);
				waitTicks = 12 /* WARM_TICKS */;
				break;
			case FIREDEATH:
				// Standing IN the fire now. The pain is immediate and vocal.
				// The disappearance is armed on the death animation's final
				// frame, so the corpse never stands back up first.
				announce(TriggerEvent.errand(TriggerEvent.Type.ERRAND_START, current.key));
				// FIRE_DEATH_ANIMATION: AnimationID.TRAILBLAZER_DEATH_PLAYER_01: the comedy fire death.
				follower.playAnimation(10629 /* FIRE_DEATH_ANIMATION */);
				// FIRE_DEATH_SPOTANIM: SpotanimID.TRAILBLAZER_DEATH_SPOTANIM: the flames that consume it.
				follower.playSpotAnim(spotAnims.get(2610 /* FIRE_DEATH_SPOTANIM */));
				// Generous window; the return home ends the hide exactly.
				follower.hideAfterEmote(3600);
				waitTicks = 6;
				break;
			case CAT:
				follower.playAnimation(BEND_ANIMATION);
				waitTicks = 7;
				break;
			case GLANCE:
				waitTicks = 4;
				break;
			default:
				waitTicks = 8;
				break;
		}
	}

	void finish()
	{
		putTheScrollAway();
		if (current == FIREDEATH)
		{
			// The vanish already happened on the death animation's last frame
			// (hideAfterEmote); this stage just times the reappearance.
			follower.resumeFollowing();
			state = RETURNING;
			waitTicks = 2;
			return;
		}
		boolean walkedAway = current != BOOTLACE && current != GLANCE
			&& current != DOCUMENT;
		// RETURN_ON_FOOT_DISTANCE: At or under this distance the follower comes back on foot - the
		// catch-up pathing walks a short gap and runs a longer one on its own.
		if (walkedAway && distanceToPlayer() > 10 /* RETURN_ON_FOOT_DISTANCE */)
		{
			// Too far to jog: a proper teleport home. Cast the spell where it
			// stands, swirl and all, then vanish to the player a beat later.
			// TELEPORT_ANIMATION: The standard teleport cast (measured by the mirror-teleport work) and its landing.
			follower.playAnimation(714 /* TELEPORT_ANIMATION */);
			follower.playSpotAnim(spotAnims.get(TELEPORT_CAST_SPOTANIM),
				FollowerEntity.TELEPORT_GRAPHIC_HEIGHT);
			// Gone on the cast's last frame. The cast runs 1.58s and the
			// landing is three ticks out at 1.80s, so without this the
			// follower drops back to its idle pose for a fifth of a second
			// mid-teleport - brief, and quite visible. Cleared by
			// teleportToPlayer on arrival.
			follower.hideAfterEmote(1200);
			state = RETURNING;
			waitTicks = 3;
			return;
		}
		// Close enough to come back on foot: releasing the pose lets the
		// catch-up pathing bring it home - walking a short gap, running a
		// longer one - which is what a person would do.
		follower.resumeFollowing();
		home();
	}

	int distanceToPlayer()
	{
		WorldPoint at = follower.getWorldLocation(),
			pt = FollowerEntity.playerTile(client);
		// Another floor is infinitely far, as distanceTo has it.
		return at != null && pt != null ? at.distanceTo(pt) : Integer.MAX_VALUE;
	}

	/** Stage two of the teleport home: land beside the player, swirl in, report. */
	void completeReturn()
	{
		follower.resumeFollowing();
		follower.teleportToPlayer();
		follower.playAnimation(TELEPORT_ARRIVE_ANIMATION);
		// Raised to mid-body: at ground height the swirl sat in the ankles.
		follower.playSpotAnim(spotAnims.get(1299 /* TELEPORT_REVERSE_SPOTANIM */),
			FollowerEntity.TELEPORT_GRAPHIC_HEIGHT);
		home();
	}

	/**
	 * Back with the player, on foot or by teleport: the end is reported as
	 * what the errand announced itself as - a study or explore names the
	 * thing itself - and the slate is cleared for the next one.
	 */
	void home()
	{
		String key = (current == STUDY || current == EXPLORE) && currentSiteKey != null
			? currentSiteKey : current.key;
		announce(TriggerEvent.errand(TriggerEvent.Type.ERRAND_END, key));
		clearErrand();
	}

	/**
	 * The scroll and the writing pose, on the same tick and therefore the
	 * same rendered frame.
	 *
	 * <p>They can be simultaneous because the dump path of the appearance
	 * service is synchronous: the composed model with the scroll in it is
	 * applied before {@code hold} returns. The first version put two "settle"
	 * ticks between them out of caution about a rebuild delay that does not
	 * exist on this path - and those two ticks were exactly the window in
	 * which the follower stood in its idle pose holding a scroll, which is
	 * the wrong order to ever show. Measured by eye in game: prop-then-wait
	 * reads wrong, together reads right.
	 */
	void takeOutTheScroll()
	{
		hands.hold(QUILL_PROP, SCROLL_PROP);
		follower.setPoseOverride(WRITE_SCROLL_POSE);
	}

	/**
	 * Ends the documenting stance, wherever the errand went from here.
	 *
	 * <p>Idempotent on purpose: it runs on the finish, abort AND reset paths,
	 * and on most of those nothing is held. The alternative - remembering
	 * which paths can be reached with the scroll out - is exactly the kind of
	 * bookkeeping that left a floor held by a rule that no longer existed.
	 */
	void putTheScrollAway()
	{
		studyLookTicks = 0;
		if (current == ALTAR)
			follower.clearPoseOverride(PRAY_LOOP);
		if (current == DOCUMENT || current == STUDY
			|| current == EXPLORE)
			follower.setPoseOverride(0);
		hands.release();
	}

	void abort()
	{
		putTheScrollAway();
		follower.resumeFollowing();
		var local = client.getLocalPlayer();
		var at = follower.getWorldLocation();
		// A death interrupted mid-vanish must not stay invisible; the
		// teleport home also clears any staged hide.
		boolean mustClearHide = current == FIREDEATH || state == RETURNING;
		if (mustClearHide
			|| (local != null && local.getWorldLocation() != null && at != null
				&& at.distanceTo(local.getWorldLocation()) > 8))
			follower.teleportToPlayer();
		clearErrand();
	}

	void clearErrand()
	{
		state = IDLE;
		current = null;
		currentSiteKey = null;
		silent = false;
		targetTile = null;
		errandSite = null;
		nextRollTicks = scheduleTicks();
	}

	// ------------------------------------------------------------ conditions

	/** An errand of the follower's own choosing: not during a session. */
	boolean safeToStart()
	{
		return clearToStart() && !session.getAsBoolean();
	}

	/** What any errand needs before it sets off, forced or not: free feet as well. */
	boolean clearToStart()
	{
		return quiet(client.getLocalPlayer()) && !follower.isStaying();
	}

	/**
	 * What an errand needs throughout: the player about, not fighting or
	 * talking, and out of the Wilderness; the follower out and not wanted.
	 */
	boolean quiet(Player local)
	{
		return local != null
			&& local.getWorldLocation() != null
			&& follower.isSpawned()
			&& !busy.getAsBoolean()
			&& local.getInteracting() == null
			&& client.getVarbitValue(WILDERNESS_VARBIT) != 1;
	}

	boolean safeToContinue()
	{
		var local = client.getLocalPlayer();
		// The player leaving - walked off, teleported, changed plane (which
		// distanceTo counts as infinitely far) - ends it.
		return quiet(local) && errandSite != null
			&& local.getWorldLocation().distanceTo(errandSite) <= 16;
	}

	static final int WILDERNESS_VARBIT = 5963;

	// -------------------------------------------------------------- scanning

	/** The nearest matching scene object's tile within the search radius, or null. */
	WorldPoint findObject(Predicate<String> nameMatch)
	{
		var local = client.getLocalPlayer();
		var lp = local == null ? null : local.getLocalLocation();
		var view = client.getTopLevelWorldView();
		// Between worlds, or mid-login, there is no scene to search. The
		// skilling company's scan does the rest: the square round where the
		// player is drawn, the nearest measured from where the server has them.
		return lp == null || local.getWorldLocation() == null || view == null ? null
			: SkillingController.nearestObject(client,
				WorldPoint.fromScene(view, lp.getSceneX(), lp.getSceneY(), view.getPlane()),
				local.getWorldLocation(), SEARCH_RADIUS, name -> name != null && nameMatch.test(name),
				null, null);
	}

	/**
	 * An object's real name, resolving multilocs.
	 *
	 * <p>Public and static because the examine echo needs exactly this and had
	 * its own naive version: most scenery is a multiloc whose base definition
	 * is called "null" until its impostor is asked, so reading getName() alone
	 * silently answers nothing for a large share of the world.
	 */
	static String objectName(Client client, int objectId)
	{
		var comp = client.getObjectDefinition(objectId);
		if (comp == null)
			return null;
		String name = comp.getName();
		if ((name == null || name.equals("null")) && comp.getImpostorIds() != null)
		{
			try
			{
				var impostor = comp.getImpostor();
				name = impostor == null ? null : impostor.getName();
			}
			catch (RuntimeException e)
			{
				return null;
			}
		}
		return name == null || name.equals("null") ? null : name;
	}

	/** The nearest matching NPC's tile within the search radius, or null. */
	WorldPoint findNpc(Predicate<String> nameMatch)
	{
		var npc = SkillingController.nearestNpc(client, FollowerEntity.playerTile(client),
			SEARCH_RADIUS, nameMatch);
		return npc == null ? null : npc.getWorldLocation();
	}

	// ------------------------------------------------------------- schedule

	/**
	 * When each errand last set off, by tick.
	 *
	 * <p>Measured over fifteen days of play: three errands accounted for 84%
	 * of every one that ran. Not because they were preferred - the roll
	 * shuffles fairly - but because they are the three that need nothing in
	 * the world to work. A bank errand needs a booth in sight and an altar
	 * needs an altar, so most rolls they simply cannot start; the bootlace,
	 * the glance and the note-taking can always start, so they won every
	 * roll the others could not. The bank ran 24 times in that fortnight.
	 * The altar ran twice. The bootlace ran 189 times, on five lines.
	 */
	final Map<Errand, Integer> lastRun = new java.util.EnumMap<>(Errand.class);

	/** Whether this errand has rested long enough to be offered again. */
	boolean offAgainCooldown(Errand errand)
	{
		var last = lastRun.get(errand);
		return last == null
			// REPEAT_GAPS: How long an errand waits before it may come round again, as a multiple
			// of the ordinary gap between errands. Scaled rather than fixed so the
			// frequency setting keeps its meaning: whatever pace was chosen, an
			// errand does not repeat until roughly three others could have happened.
			|| client.getTickCount() - last >= baseScheduleTicks() * 3 /* REPEAT_GAPS */;
	}

	/**
	 * Puts the least recently run errands first, so a roll offers variety
	 * before it offers convenience. Ties are shuffled, so equally stale
	 * errands do not fall into a fixed order.
	 */
	void orderByStaleness(List<Errand> candidates)
	{
		Collections.shuffle(candidates, random);
		candidates.sort(Comparator.comparingInt(
			errand -> lastRun.getOrDefault(errand, Integer.MIN_VALUE)));
	}

	int scheduleTicks()
	{
		// 60%..140% of the base, so errands never feel metronomic.
		return (int) (baseScheduleTicks()
			* (0.6 + random.nextDouble() * 0.8));
	}

	int baseScheduleTicks()
	{
		return config.errandFrequency().ticks;
	}
}

