package com.follower;

import java.util.*;
import java.util.List;
import java.util.Random;
import java.util.function.*;
import java.util.function.Supplier;
import net.runelite.api.*;
import net.runelite.api.Actor;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import lombok.RequiredArgsConstructor;
import static java.lang.Math.*;

/**
 * Where the follower looks when nothing else owns its head.
 *
 * <p>Joint attention is the cheapest sign of company there is, and the one
 * with the best evidence behind it: a robot that followed people's gaze was
 * rated more likeable and preferred three times out of four, without anybody
 * being able to say why. OSRS has no gaze to follow, but it has two things
 * that stand in for it - where the cursor rests, and where the camera is
 * turned - and the follower turns its head to both. Gaze only: the feet stay
 * with whatever owns them, and a real facing (a seat, a goal, an errand at
 * its business) outranks a glance, so none of this applies while the body is
 * spoken for.
 *
 * <p>The third source is the follower's own: standing about, it looks round
 * at what is nearby every so often and then back at the player, which is what
 * a companion that is present rather than parked looks like. How it looks
 * round depends on where it is. Somewhere it likes, the looks are slow and
 * long; somewhere it dislikes, quick and often and always at the nearest
 * thing that moves.
 *
 * <p>Nothing here is memoised as a refusal: a glance that cannot be aimed is
 * simply skipped, and nothing speaks. All three sources pace themselves, so
 * the head does not flick.
 */
@RequiredArgsConstructor
class Gaze
{
	static final int HOVER_GLANCE_MS = 1800,
		HOVER_COOLDOWN_TICKS = 5;

	static final int CAMERA_SETTLE_TICKS = 2,
		CAMERA_COOLDOWN_TICKS = 15,
		CAMERA_LOOK_TILES = 4;

	/** The look round: after this much standing about, this often, for this long. */
	static final int IDLE_BEFORE_AROUND_TICKS = 10,
		AROUND_MIN_TICKS = 33,
		AROUND_MAX_TICKS = 66,
		AROUND_MS = 1500,
		AROUND_NEAR = 3,
		AROUND_FAR = 6;

	/** What the cursor is resting on: an actor, or a tile with something on it. */
	@RequiredArgsConstructor
	static class Hover
	{
		final String key;
		final Actor actor;
		final WorldPoint tile;

		WorldPoint where()
		{
			return actor != null ? actor.getWorldLocation() : tile;
		}
	}

	final Client client;
	final FollowerEntity follower;
	final FollowerConfig config;
	final IntSupplier cameraYaw,
		idleTicks;
	/** Something else has the head or the feet: nothing here applies. */
	final BooleanSupplier busy;
	/** Tiles of the things nearby worth a look, nearest first. */
	final Supplier<List<WorldPoint>> nearby;
	final Random random;

	Hover hoverNow;
	String hoverKey;
	int hoverTicks;
	String glancedKey;
	int hoverCooldownUntil;

	int lastYaw = Integer.MIN_VALUE,
		settledYaw = Integer.MIN_VALUE,
		stillTicks;
	boolean swung;
	int cameraCooldownUntil;

	int aroundIn = -1;

	// ------------------------------------------------------------- the cursor

	/**
	 * What the cursor is resting on right now, read off the menu the client
	 * would open: the top entry is what a left click would do, and its
	 * target is the thing under the mouse. Nothing for bare ground, for
	 * interfaces, for the player themselves or for the follower's own
	 * injected entries.
	 */
	static Hover read(Client client, FollowerEntity follower)
	{
		if (client.isMenuOpen())
			return null;
		var entries = client.getMenu().getMenuEntries();
		if (entries == null || entries.length == 0)
			return null;
		var top = entries[entries.length - 1];
		var type = top.getType();
		if (type == null || type == MenuAction.WALK || type == MenuAction.CANCEL
			|| type == MenuAction.RUNELITE || type == MenuAction.RUNELITE_HIGH_PRIORITY
			|| type == MenuAction.RUNELITE_WIDGET)
			return null;
		var npc = top.getNpc();
		if (npc != null)
			return new Hover("npc:" + npc.getIndex(), npc, null);
		var player = top.getPlayer();
		if (player != null)
			return player == client.getLocalPlayer() ? null
				: new Hover("player:" + player.getName(), player, null);
		String name = type.name();
		if (name.startsWith("GAME_OBJECT") || name.startsWith("GROUND_ITEM")
			|| type == MenuAction.EXAMINE_OBJECT || type == MenuAction.EXAMINE_ITEM_GROUND
			|| type == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT
			|| type == MenuAction.WIDGET_TARGET_ON_GROUND_ITEM)
		{
			var view = client.getTopLevelWorldView();
			if (view == null)
				return null;
			var tile = WorldPoint.fromScene(view, top.getParam0(), top.getParam1(),
				view.getPlane());
			return new Hover("tile:" + tile.getX() + "," + tile.getY() + ":" + top.getIdentifier(),
				null, tile);
		}
		return null;
	}

	/** Once per client tick: what the cursor is on, or null. */
	void noteHover(Hover hover)
	{
		hoverNow = hover;
	}

	// --------------------------------------------------------------- the tick

	/** Call once per game tick, on the client thread, after the wander. */
	void tick()
	{
		int now = client.getTickCount();
		boolean allowed = config.paysAttention() && follower.isSpawned() && !busy.getAsBoolean();
		var from = follower.getWorldLocation();
		if (!allowed || from == null)
		{
			hoverKey = null;
			hoverTicks = 0;
			aroundIn = -1;
			lastYaw = Integer.MIN_VALUE;
			return;
		}
		if (watchTheCursor(now, from) || watchTheCamera(now, from))
		{
			// A shared look pushes the look round back, so the two never stack.
			aroundIn = -1;
			return;
		}
		lookRound(now, from);
	}

	boolean watchTheCursor(int now, WorldPoint from)
	{
		var hover = hoverNow;
		if (hover == null)
		{
			hoverKey = null;
			hoverTicks = 0;
			glancedKey = null;
			return false;
		}
		if (hover.key.equals(hoverKey))
			hoverTicks++;
		else
		{
			hoverKey = hover.key;
			hoverTicks = 1;
		}
		// HOVER_TICKS: Ticks the cursor rests on a thing before the head turns to it.
		if (hoverTicks != 2 /* HOVER_TICKS */ || hover.key.equals(glancedKey) || now < hoverCooldownUntil)
			return false;
		var at = hover.where();
		if (at == null || at.getPlane() != from.getPlane() || at.equals(from))
			return false;
		glancedKey = hover.key;
		hoverCooldownUntil = now + HOVER_COOLDOWN_TICKS;
		follower.glanceAt(at, HOVER_GLANCE_MS);
		return true;
	}

	boolean watchTheCamera(int now, WorldPoint from)
	{
		int yaw = cameraYaw.getAsInt() & 0x7ff;
		if (lastYaw == Integer.MIN_VALUE)
		{
			lastYaw = yaw;
			settledYaw = yaw;
			return false;
		}
		boolean moving = angle(yaw, lastYaw) > 12 /* CAMERA_JITTER */;
		lastYaw = yaw;
		if (moving)
		{
			stillTicks = 0;
			// CAMERA_SWING: A camera swing this big, then two still ticks, is a look worth sharing.
			if (angle(yaw, settledYaw) > 200 /* CAMERA_SWING */)
				swung = true;
			return false;
		}
		if (++stillTicks < CAMERA_SETTLE_TICKS)
			return false;
		boolean look = swung && now >= cameraCooldownUntil && idleTicks.getAsInt() > 0;
		swung = false;
		settledYaw = yaw;
		if (!look)
			return false;
		cameraCooldownUntil = now + CAMERA_COOLDOWN_TICKS;
		follower.glanceAt(lookTile(from, yaw, CAMERA_LOOK_TILES), 1500 /* CAMERA_GLANCE_MS */);
		return true;
	}

	/**
	 * A tile so many steps from {@code from} in the direction the camera is
	 * looking. Camera yaw 0 looks north; an actor's orientation 0 faces
	 * south, so the two differ by a half turn and share the rest.
	 */
	static WorldPoint lookTile(WorldPoint from, int cameraYaw, int tiles)
	{
		int orientation = (cameraYaw + 1024) & 0x7ff;
		double radians = (orientation / 2048.0) * 2.0 * PI;
		int dx = (int) round(-sin(radians) * tiles),
			dy = (int) round(-cos(radians) * tiles);
		return from.dx(dx).dy(dy);
	}

	/** The smaller angle between two yaws, in JAU. */
	static int angle(int a, int b)
	{
		int d = (a - b) & 0x7ff;
		return d > 1024 ? 2048 - d : d;
	}

	void lookRound(int now, WorldPoint from)
	{
		if (idleTicks.getAsInt() < IDLE_BEFORE_AROUND_TICKS)
		{
			aroundIn = -1;
			return;
		}
		if (aroundIn < 0)
		{
			aroundIn = between(AROUND_MIN_TICKS, AROUND_MAX_TICKS);
			return;
		}
		if (--aroundIn > 0)
			return;
		aroundIn = -1;
		lookRoundNow(from);
	}

	/** The look round itself, at something nearby or nothing in particular: where, or null. */
	WorldPoint lookRoundNow(WorldPoint from)
	{
		var things = nearby.get();
		WorldPoint at = null;
		if (things != null && !things.isEmpty())
			at = things.get(random.nextInt(things.size()));
		if (at == null)
		{
			double heading = random.nextDouble() * PI * 2;
			int distance = between(AROUND_NEAR, AROUND_FAR);
			at = from.dx((int) round(cos(heading) * distance))
				.dy((int) round(sin(heading) * distance));
		}
		if (at.equals(from))
			return null;
		follower.glanceAt(at, AROUND_MS);
		return at;
	}

	int between(int min, int max)
	{
		return min + random.nextInt(max(1, max - min + 1));
	}

	/** Logout, hop: nothing carried over. */
	void reset()
	{
		hoverNow = null;
		hoverKey = null;
		hoverTicks = 0;
		glancedKey = null;
		lastYaw = Integer.MIN_VALUE;
		settledYaw = Integer.MIN_VALUE;
		stillTicks = 0;
		swung = false;
		aroundIn = -1;
	}
}

package com.follower;

import java.util.*;
import java.util.Map;
import java.util.function.*;
import lombok.RequiredArgsConstructor;

/**
 * The ledger of body beats, so the same one cannot appear twice in a
 * stretch.
 *
 * <p>The lines have had this for a long time: a rule carries its own
 * cooldown, and the engine will not say the same sentence twice in a
 * session. The body had nothing of the kind, and a gesture that repeats is
 * worse than a line that does - when Ellie handed the player ammo every
 * minute "it devalued the act of gifting", and the fix was to put every
 * buddy behaviour behind really big timers. So every gesture the moments
 * make goes through here first, each with a cooldown of its own, and the
 * ones that are meant to be rare stay rare.
 *
 * <p>Goodwill shortens the wait. For the half hour after the player did
 * what the follower asked, every cooldown is halved: the favour is paid
 * back in attentiveness, which is the currency a companion actually has.
 */
@RequiredArgsConstructor
class Gestures
{
	/** What the body can do, and how long it waits before doing it again. */
	@RequiredArgsConstructor
	enum Gesture
	{
		/** A turn of the head toward something. */
		GLANCE(30),
		/** EMOTE_YES at the player. */
		NOD(100),
		/** The scroll out and a few lines written. */
		NOTES(500),
		/** Walking over to something to have a look at it. */
		WALK_OVER(900),
		/** Standing off and peering at something. */
		PEER(400),
		/** The wave at the logout tab. */
		WAVE(500),
		/** The check-in: a look at the player for no reason, while idle. */
		CHECK_IN(30);

		final int cooldownTicks;
	}

	final IntSupplier tick;
	final BooleanSupplier grateful;
	final Map<Gesture, Integer> lastAt = new EnumMap<>(Gesture.class);

	/** Whether the gesture is off cooldown. Does not spend it. */
	boolean may(Gesture gesture)
	{
		var last = lastAt.get(gesture);
		if (last == null)
			return true;
		int wait = gesture.cooldownTicks;
		if (grateful.getAsBoolean())
			wait /= 2;
		return tick.getAsInt() - last >= wait;
	}

	/** Marks the gesture as made now. */
	void spent(Gesture gesture)
	{
		lastAt.put(gesture, tick.getAsInt());
	}

	/** Logout, hop: the ledger belongs to the session. */
	void reset()
	{
		lastAt.clear();
	}
}

package com.follower;

/**
 * The client's own triangle rasterizer, ported from {@code Pix3D.gouraudTriangle}
 * and {@code Pix3D.gouraudRaster}.
 *
 * <p>This replaces a float barycentric fill that sampled pixel centres. On
 * triangles a few pixels across - the pupils of a chathead's eyes - the two
 * disagree visibly: a sub-pixel face can miss every pixel-centre sample and
 * vanish entirely, and adjacent faces can leave one-pixel cracks along shared
 * edges, letting the parchment behind show through as stray light pixels. The
 * game's rasterizer is an integer scanline walker with its own fill convention;
 * only running the same algorithm produces the same pixels.
 *
 * <p>Faithfulness notes:
 * <ul>
 * <li>x steps are 16.16 fixed point ({@code ((dx << 16) / dy)}), colour steps
 *     15-bit ({@code ((dc << 15) / dy)}); scanline endpoints are handed to the
 *     raster as {@code x >> 16} / {@code colour >> 7}, and the raster indexes
 *     the colour table with {@code colour >> 8} per pixel. Java's int division
 *     and shifts truncate exactly like the client's {@code | 0} arithmetic.</li>
 * <li>The client spells out three top-level cases, one per vertex that can be
 *     topmost, and they are the same code with the vertices rotated. Each edge
 *     step is the same value whichever way round it is computed, so rotating
 *     the arguments and running the first case reproduces the other two
 *     exactly. Inside that case the client splits on which vertex is in the
 *     middle and, for each, on which edge is on the left; the two orders of
 *     each pair differ only in the order the span ends are passed, which is
 *     {@link #span}'s flag. The left/right tests are the client's own, ties
 *     included.</li>
 * <li>Only the paths this plugin exercises are ported: high detail
 *     ({@code lowDetail = false}), opaque ({@code trans = 0}), with horizontal
 *     clipping always on - the client's {@code hclip = false} path is a
 *     speed-up that skips clamping, not a different fill.</li>
 * <li>Colours interpolate as PACKED palette indices and resolve through
 *     {@link GameColourTable}, the same gamma table the game uses.</li>
 * </ul>
 */
class GouraudRasterizer
{
	final int[] pixels;
	final int width,
		clipMaxY;

	GouraudRasterizer(int[] pixels, int width, int height)
	{
		this.pixels = pixels;
		this.width = width;
		this.clipMaxY = height;
	}

	void gouraudTriangle(int xA, int xB, int xC, int yA, int yB, int yC,
		int colourA, int colourB, int colourC)
	{
		if (yA <= yB && yA <= yC)
			fromTop(0, xA, xB, xC, yA, yB, yC, colourA, colourB, colourC);
		else if (yB <= yC)
			fromTop(1, xB, xC, xA, yB, yC, yA, colourB, colourC, colourA);
		else
			fromTop(2, xC, xA, xB, yC, yA, yB, colourC, colourA, colourB);
	}

	/**
	 * The client's first case, vertex A topmost, run on the vertices rotated
	 * {@code rotation} places. The client's other two cases are this code
	 * rotated, except that they leave out the tie tests that cannot fire on
	 * their unclipped rows - and so skip them on clipped rows too, which can
	 * tie. {@code tieTest} keeps that difference.
	 */
	void fromTop(int rotation, int xA, int xB, int xC, int yA, int yB, int yC,
		int colourA, int colourB, int colourC)
	{
		int xStepAB = 0,
			colourStepAB = 0;
		if (yB != yA)
		{
			xStepAB = ((xB - xA) << 16) / (yB - yA);
			colourStepAB = ((colourB - colourA) << 15) / (yB - yA);
		}

		int xStepBC = 0,
			colourStepBC = 0;
		if (yC != yB)
		{
			xStepBC = ((xC - xB) << 16) / (yC - yB);
			colourStepBC = ((colourC - colourB) << 15) / (yC - yB);
		}

		int xStepAC = 0,
			colourStepAC = 0;
		if (yC != yA)
		{
			xStepAC = ((xA - xC) << 16) / (yA - yC);
			colourStepAC = ((colourA - colourC) << 15) / (yA - yC);
		}

		if (yA >= clipMaxY)
			return;
		yB = Math.min(yB, clipMaxY);
		yC = Math.min(yC, clipMaxY);

		if (yB < yC)
			walk(xA, xB, yA, yB, yC, colourA, colourB, xStepAB, colourStepAB,
				xStepBC, colourStepBC, xStepAC, colourStepAC, false, rotation < 2);
		else
			walk(xA, xC, yA, yC, yB, colourA, colourC, xStepAC, colourStepAC,
				xStepBC, colourStepBC, xStepAB, colourStepAB, true, rotation == 0);
	}

	/**
	 * Fills from the top vertex down: the long edge runs top to bottom, the
	 * short edges top to middle and middle to bottom. {@code midIsC} is the
	 * client's second sub-case, where C is the middle vertex; it only changes
	 * which way an exact tie of slopes falls.
	 */
	void walk(int xTop, int xMid, int yTop, int yMid, int yBottom, int colourTop, int colourMid,
		int xStepShort, int colourStepShort, int xStepLower, int colourStepLower,
		int xStepLong, int colourStepLong, boolean midIsC, boolean tieTest)
	{
		int xLong = xTop << 16,
			xShort = xLong,
			colourLong = colourTop << 15,
			colourShort = colourLong;
		if (yTop < 0)
		{
			xLong -= xStepLong * yTop;
			xShort -= xStepShort * yTop;
			colourLong -= colourStepLong * yTop;
			colourShort -= colourStepShort * yTop;
			yTop = 0;
		}
		xMid <<= 16;
		colourMid <<= 15;
		if (yMid < 0)
		{
			xMid -= xStepLower * yMid;
			colourMid -= colourStepLower * yMid;
			yMid = 0;
		}

		// The client's left/right test, made on the clipped rows.
		boolean longLeft = !tieTest || yTop != yMid
			? xStepLong < xStepShort || (midIsC && xStepLong == xStepShort)
			: xStepLong > xStepLower || (midIsC && xStepLong == xStepLower);
		int off = width * yTop;
		for (int rows = yMid - yTop; rows-- > 0; off += width)
		{
			span(longLeft, xLong, xShort, colourLong, colourShort, off);
			xLong += xStepLong;
			xShort += xStepShort;
			colourLong += colourStepLong;
			colourShort += colourStepShort;
		}
		for (int rows = yBottom - yMid; rows-- > 0; off += width)
		{
			span(longLeft, xLong, xMid, colourLong, colourMid, off);
			xLong += xStepLong;
			xMid += xStepLower;
			colourLong += colourStepLong;
			colourMid += colourStepLower;
		}
	}

	/** One scanline between the long edge and a short one, in left-to-right order. */
	void span(boolean longLeft, int xLong, int xShort, int colourLong, int colourShort, int off)
	{
		if (longLeft)
			gouraudRaster(xLong >> 16, xShort >> 16, colourLong >> 7, colourShort >> 7, off);
		else
			gouraudRaster(xShort >> 16, xLong >> 16, colourShort >> 7, colourLong >> 7, off);
	}

	/**
	 * One scanline, the client's high-detail opaque path: interpolate the packed
	 * palette index from {@code xA} (inclusive) to {@code xB} (exclusive) and
	 * resolve each pixel through the colour table. {@code off} is the row's base
	 * offset. Alpha is forced opaque for the ARGB output image - the client's
	 * canvas has no alpha channel to set.
	 */
	void gouraudRaster(int xA, int xB, int colourA, int colourB, int off)
	{
		if (xA >= xB)
			return;
		int colourStep = (colourB - colourA) / (xB - xA);
		if (xB > width)
			xB = width;
		if (xA < 0)
		{
			colourA -= xA * colourStep;
			xA = 0;
		}
		for (off += xA; xA < xB; xA++)
		{
			pixels[off++] = 0xFF000000 | GameColourTable.rgb(colourA >> 8);
			colourA += colourStep;
		}
	}
}

package com.follower;

import java.util.*;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import lombok.RequiredArgsConstructor;

/**
 * The tiles the map calls walkable that nobody walks on: a lit fire, chiefly.
 *
 * <p>Collision is the only thing the follower's feet have ever consulted, and
 * a fire has none - a player walks straight over one, and so, until now, did
 * the follower. Play report: light a campfire, cook on it, and the follower
 * stands IN the fire while it copies the cooking. The map is not wrong; it
 * simply does not describe the one thing a person would take account of.
 *
 * <p>Kept as a set of tiles rather than a scan, because the client already
 * announces every object that comes and goes - including one event per object
 * when a scene loads - so the set maintains itself and an answer costs a hash
 * lookup. That matters: the pathfinder asks per tile, thousands of times per
 * route.
 *
 * <p>Matched by NAME rather than by id, for the reason the borrowed tools
 * learned the hard way: a table of ids cannot keep up with the game, and the
 * names here are the ones the plugin already looks for when it sends the
 * follower to warm its hands.
 */
@RequiredArgsConstructor
class HotGround
{
	/**
	 * What counts. Every one of these is walkable ground with something on it
	 * that a person steps round; {@code ::follower errandscan} prints what the
	 * scene actually calls things, which is the honest way to extend this.
	 */
	static final List<String> NAMES = Arrays.asList(
		"fire", "campfire", "forester's campfire", "bonfire");

	/** A footprint wider than this is not a fire; nothing is read off it. */
	static final int BIGGEST = 4;

	final Client client;
	final Set<WorldPoint> tiles = new HashSet<>();
	final Map<Integer, Boolean> known = new HashMap<>();

	/** Whether the name is one of the fires, however the game capitalises it. */
	static boolean isFire(String name)
	{
		return name != null && NAMES.contains(name.toLowerCase(Locale.ROOT));
	}

	/**
	 * Scenery arrived. A fire's tiles go on the list; everything else is
	 * ignored, and the answer is remembered against the id so a scene load
	 * does not resolve the same object a hundred times.
	 */
	void objectSpawned(int id, WorldPoint min, WorldPoint max)
	{
		if (!fireId(id))
			return;
		forEachTile(min, max, tiles::add);
	}

	/** And went: burnt out, or the scene rebuilt around it. */
	void objectDespawned(int id, WorldPoint min, WorldPoint max)
	{
		if (!fireId(id))
			return;
		forEachTile(min, max, tiles::remove);
	}

	/**
	 * Whether the follower would walk round this tile rather than onto it.
	 * Null is cold: an unknown tile is not a fire.
	 */
	boolean hot(WorldPoint at)
	{
		return at != null && !tiles.isEmpty() && tiles.contains(at);
	}

	/** How many tiles are alight, for {@code ::follower status}. */
	int count()
	{
		return tiles.size();
	}

	/** A hop, a logout, a shutdown: the scene is gone and so is what was in it. */
	void clear()
	{
		tiles.clear();
	}

	boolean fireId(int id)
	{
		var answer = known.get(id);
		if (answer == null)
		{
			answer = isFire(ErrandController.objectName(client, id));
			// CACHE_CAP: Ids resolved so far, so a scene load is one lookup per distinct object.
			if (known.size() >= 4000 /* CACHE_CAP */)
				// Bounded rather than clever: the ids in one scene number in
				// the hundreds, and a fresh start costs one lookup each.
				known.clear();
			known.put(id, answer);
		}
		return answer;
	}

	void forEachTile(WorldPoint min, WorldPoint max, java.util.function.Consumer<WorldPoint> each)
	{
		if (min == null)
			return;
		var far = max == null ? min : max;
		if (far.getX() - min.getX() >= BIGGEST || far.getY() - min.getY() >= BIGGEST
			|| far.getPlane() != min.getPlane())
		{
			each.accept(min);
			return;
		}
		for (int x = min.getX(); x <= far.getX(); x++)
		{
			for (int y = min.getY(); y <= far.getY(); y++)
				each.accept(new WorldPoint(x, y, min.getPlane()));
		}
	}
}

package com.follower;

import java.awt.Color;
import net.runelite.api.JagexColor;

/**
 * Conversions for the game's packed colour format.
 *
 * <p>Model face colours are 16-bit HSL: hue in bits 10-15, saturation in bits 7-9,
 * luminance in bits 0-6, unpacked by RuneLite's {@link JagexColor}. Lighting
 * rewrites only the luminance bits, which is why hue and saturation read off a
 * lit model are the authored values.
 */
class HslColor
{

	/**
	 * Approximates a packed game colour as RGB, for showing swatches in the panel.
	 * The game's own conversion table is internal to the client, so this is a plain
	 * HSL conversion over the same ranges - close enough to pick a colour by eye.
	 * The stored value is always the packed colour itself, never this RGB.
	 */
	static int toRgb(short packed)
	{
		float h = JagexColor.unpackHue(packed) / 63f,
			s = JagexColor.unpackSaturation(packed) / 7f,
			l = JagexColor.unpackLuminance(packed) / 127f;

		// HSL to RGB via HSB, which java.awt provides directly.
		float brightness = l + s * Math.min(l, 1f - l),
			saturationHsb = brightness == 0f ? 0f : 2f * (1f - l / brightness);
		return Color.HSBtoRGB(h, Math.max(0f, Math.min(1f, saturationHsb)),
			Math.max(0f, Math.min(1f, brightness))) & 0xFFFFFF;
	}
}

package com.follower;

import java.util.*;
import java.util.List;
import java.util.Random;
