	 */
	static final int PEER = 6840,
		PEER_TICKS = 6;

	/** Three to five minutes between looks over the shoulder. */
	static final int SHOULDER_AFTER_TICKS = 400,
		SHOULDER_SPREAD = 100;

	/** The kneel, proven on the follower by the altar errand. */
	static final int KNEEL = 645;

	/** A guard stirring earns a glance at the player, not more than this often. */
	static final int GUARD_GLANCE_GAP_TICKS = 30;

	/** EMOTE_YES, proven by the mirror rules: the foreman's nod. */
	static final int NOD = 855;

	/** EMOTE_STAMPFEET, proven by the cold-stamp-feet rule; every thirty seconds. */
	static final int STAMP_FEET = 4278,
		STAMP_EVERY_TICKS = 50,
		STAMP_SPREAD = 10;

	/**
	 * How a seat is kept, shaped to the work. The controller reads it off the
	 * session ({@link SkillingController#modeFor}); the geometry and the
	 * habits both follow from it.
	 */
	enum Mode
	{
		/** The flank seat and the universal habits, nothing more. */
		NONE,
		/** Across the fire from the cook, hands to the flames. */
		FIRESIDE,
		/** One tile along the range's side. */
		RANGE,
		/** The anvil's far side, the notes out for the whole session. */
		ANVIL,
		/** Beside a wheel or a loom, sat down at once. */
		WHEEL,
		/** Work with nothing to click: a look over the shoulder now and then. */
		STANDING,
		/** The runecraft altar: one kneel, facing it. */
		ALTAR,
		/** The stall watch: off between the player and the guard, facing the guard. */
		STALL,
		/**
		 * A farming patch: kept like a gatherer's seat - not a step taken,
		 * working the patch alongside the player when there is room at it,
		 * reading otherwise - and the notes at the end of the visit.
		 */
		PATCH,
		/** The foreman: three tiles off the hotspot, notes out, a nod per hammer. */
		FOREMAN,
		/** The brazier in the cold: three tiles off, stamping the feet. */
		BRAZIER,
		/**
		 * Mining, woodcutting, fishing, hunting: not a step taken. Working
		 * alongside the player when the seat is a work tile - the work pose
		 * most of the time, the scroll now and then - and parked with the
		 * scroll out when it is only a seat.
		 */
		GATHERING,
	}

	/** One tile to look at for so many ticks; the reactions are queues of these. */
	@RequiredArgsConstructor
	static class Look
	{
		final WorldPoint tile;
		final int ticks;
	}

	final Client client;
	final FollowerEntity follower;
	final FollowerConfig config;
	final ErrandController.Hands hands;
	final Borrow borrow;
	final Random random;

	int startTick;
	WorldPoint seat;

	/** The seat's own facing: the middle of the target. */
	WorldPoint target,
		facing;

	int lastTallyDrop,
		tallyJitter;
	/** Whether the scroll is out, and the ticks it has left. */
	boolean scrollOut;

	/** Whether a borrowed tool was put down to free the hand for the scroll. */
	boolean toolAside;
	int scrollTicks,
		lastDropTick;
	boolean fast;

	int lastNodDrop,
		nodGap,
		lookTicks;

	WorldPoint lastHere;
	int stillTicks;
	boolean stopped;
	int stopWait,
		stopCooldownUntil;

	int paceAt,
		sitAt,
		stretchAt,
		stretchAgainAt;
	boolean paced,
		stretched,
		stretchedAgain;
	@Getter
	boolean sitting;

	/** The legs of a walk still to be taken, and the pause before the next. */
	final List<WorldPoint> legs = new ArrayList<>();
	int legWait;
	boolean walking,
		sitAfterWalk;

	int playerLookTicks;
	WorldPoint step;
	int stepTicks;
	WorldPoint seatMoved;

	/** The looks still to be taken, the one being taken, and its ticks left. */
	final List<Look> looks = new ArrayList<>();
	WorldPoint currentLook;
	int currentLookTicks;

	int lastDepletionTick,
		waterLookAt;

	/** The footprint the follower works, or null when the seat is only a seat. */
	WorldPoint workMin,
		workMax;

	/** The work pose it holds now, or 0. */
	int working;

	/** Its work went - felled, emptied, moved on - until it is chosen again. */
	boolean workGone;

	/** Whether it was last turned to its work, and the tick it was. */
	boolean facingTheWork;
	int facedAt;

	/** Ticks worked since the last break, and the stretch's length (0: not drawn yet). */
	int workTicks,
		stretch;

	Mode mode = Mode.NONE;
	String activity = "";

	/** The guard the stall watch faces, or null. */
	NPC guard;
	int guardGlanceAt;

	int warmAt;

	/** The anvil study: ticks until the scroll goes down, and until it comes back. */
	int studyTicks,
		studyResume;

	int shoulderAt;

	/** Ticks the peer over the shoulder has left; the seat is retaken after. */
	int peerTicks;

	int fumesDrops;
	boolean wasAnimating;
	int stampAt;

	/**
	 * A session began. The controller makes a fresh company for every
	 * session, so everything else starts over as it was made; here the
	 * counters each draw their own jitter.
	 */
	void begin(int now)
	{
		startTick = now;
		tallyJitter = random.nextInt(3) - 1;
		lastDropTick = -1;
		nodGap = nextNodGap();
		paceAt = jitter(PACE_AFTER_TICKS, 50);
		sitAt = jitter(SIT_AFTER_TICKS, 60);
		stretchAt = jitter(STRETCH_AFTER_TICKS, 300);
		stretchAgainAt = jitter(STRETCH_AGAIN_TICKS, 300);
		lastDepletionTick = -1;
	}

	/**
	 * The controller took, or retook, the seat. A walk in progress is
	 * dropped, and the seat's own opening plays: the notes come out at an
	 * anvil or a hotspot, the follower sits at a wheel, kneels at an altar.
	 */
	void seated(WorldPoint seat, WorldPoint target)
	{
		letGoOfTheWork();
		workMin = null;
		workMax = null;
		workGone = false;
		facingTheWork = false;
		this.seat = seat;
		this.target = target;
		this.facing = target;
		legs.clear();
		walking = false;
		legWait = 0;
		switch (mode)
		{
			case ANVIL:
			case FOREMAN:
				study();
				break;
			case WHEEL:
				sit();
				break;
			case ALTAR:
				gesture(KNEEL);
				break;
			default:
				break;
		}
	}

	void unseated()
	{
		// Not reading on the move: the parked scroll goes with the seat, and
		// the swing with the work.
		putScrollAway();
		letGoOfTheWork();
		workMin = null;
		workMax = null;
		seat = null;
		facing = null;
		legs.clear();
		walking = false;
	}

	/**
	 * The seat is a work tile: the follower works its own tree, rock or spot
	 * from it, alongside the player - the player's own when there was room,
	 * the next one along when there was not - and faces its middle.
	 */
	void seatedAtWork(WorldPoint seat, WorldPoint target, WorldPoint min, WorldPoint max, int now)
	{
		seated(seat, target);
		workMin = min;
		workMax = max;
		faceTheWork(now);
	}

	boolean isAtWork()
	{
		return workMin != null;
	}

	/**
	 * Its own work went: the swing stops, and a look at where it was - unless
	 * the depletion that took it has had its looks this tick already.
	 */
	void workGone(int now)
	{
		if (workMin == null || workGone)
			return;
		workGone = true;
		letGoOfTheWork();
		if (lastDepletionTick != now)
			look(workMin, EMPTY_LOOK_TICKS);
	}

	/**
	 * A moment has the feet: a gatherer's scroll and swing both stop, and
	 * come back when the seat is handed back.
	 */
	void excuse()
	{
		if (!parked())
			return;
		putScrollAway();
		letGoOfTheWork();
		facingTheWork = false;
	}

	/** The stall watch's guard; the seat faces it and watches it stir. */
	void watch(NPC guard)
	{
		this.guard = guard;
	}

	/** Whether the follower is off the seat on purpose, peering over the shoulder. */
	boolean isAway()
	{
		return peerTicks > 0;
	}

	/** Where the seat looks when nothing else claims it: the guard, or the work. */
	WorldPoint watched()
	{
		var at = mode == Mode.STALL && guard != null ? guard.getWorldLocation() : null;
		return at != null ? at : target;
	}

	/** Where the seat went of its own accord - the step toward the bank - once. */
	WorldPoint seatMoved()
	{
		var moved = seatMoved;
		seatMoved = null;
		return moved;
	}

	// ----------------------------------------------------------------- drops

	/**
	 * A drop landed: the tally scroll comes out somewhere around every eighth
	 * one (twelfth, when they come fast), and about every third earns a look
	 * at the work. Never two looks in a row; the gap is two at the least.
	 */
	void drop(int drops, int now)
	{
		if (lastDropTick >= 0)
			// FAST_DROP_GAP: Drops closer together than this are a fast skill.
			fast = now - lastDropTick < 4 /* FAST_DROP_GAP */;
		lastDropTick = now;

		// TALLY_EVERY: Drops between tallies; the count for a fast skill.
		int every = fast ? 12 /* TALLY_EVERY_FAST */ : 8 /* TALLY_EVERY */;
		if (drops - lastTallyDrop >= every + tallyJitter)
		{
			lastTallyDrop = drops;
			tallyJitter = random.nextInt(3) - 1;
			// The patch inspector keeps its notes for the end.
			if (mode != Mode.PATCH)
				takeOutTheScroll(TALLY_TICKS);
		}

		// FUMES_EVERY: Every seventh potion, two seconds facing away from the fumes.
		if ("herblore".equals(activity) && ++fumesDrops % 7 /* FUMES_EVERY */ == 0)
			look(awayTile(), 3 /* FUMES_TICKS */);

		if (workMin != null)
			// Working alongside: eyes on its own work, not a look at theirs.
			return;
		if (drops - lastNodDrop >= nodGap)
		{
			lastNodDrop = drops;
			nodGap = nextNodGap();
			if (scrollOut || walking)
				return;
			if (seat != null)
				lookTicks = 2 /* NOD_TICKS */;
			else if (target != null)
				follower.glanceAt(target, 1200 /* NOD_GLANCE_MS */);
		}
	}

	int nextNodGap()
	{
		// NOD_EVERY: A look at the work about every third drop; two, three or four.
		return 3 /* NOD_EVERY */ - 1 + random.nextInt(3);
	}

	/**
	 * A target, the session's first or the next one over, and the shape of
	 * the work at it. The seat is not needed for the nod's glance, only for
	 * its aim; the per-target clocks (the notes, the water, the look over
	 * the shoulder) start over, and looks about the old one go.
	 */
	void aimAt(WorldPoint target, String activity, Mode mode, int now)
	{
		this.target = target;
		this.activity = activity == null ? "" : activity;
		this.mode = mode == null ? Mode.NONE : mode;
		waterLookAt = now + jitter(WATER_LOOK_TICKS, WATER_LOOK_SPREAD);
		shoulderAt = now + jitter(SHOULDER_AFTER_TICKS, SHOULDER_SPREAD);
		stampAt = now + jitter(STAMP_EVERY_TICKS, STAMP_SPREAD);
		guardGlanceAt = 0;
		fumesDrops = 0;
		forgetLooks();
	}

	/** The notes out for the whole session, put down for a shrug now and then. */
	void study()
	{
		takeOutTheScroll(0);
		studyTicks = jitter(STUDY_SHRUG_EVERY, 5);
	}

	void forgetLooks()
	{
		looks.clear();
		currentLook = null;
		currentLookTicks = 0;
	}

	// ------------------------------------------------------------------ tick

	/**
	 * Once a tick during a session, after the controller has settled that the
	 * session goes on and the seat is what it is.
	 *
	 * @param animating whether the player is mid-animation this tick
	 */
	/**
	 * @param workPose the work to hold when working alongside, or 0
	 * @param bareHanded whether that work is done with nothing in the hand
	 */
	void tick(int now, WorldPoint here, boolean animating, String activity, int workPose,
		boolean bareHanded)
	{
		lookOn();
		if (seat == null)
		{
			lastHere = here;
			stillTicks = 0;
			return;
		}
		if (walking)
		{
			walk();
			return;
		}

		if (scrollTicks > 0 && --scrollTicks == 0)
			putScrollAway();
		if (lookTicks > 0)
			lookTicks--;
		if (playerLookTicks > 0)
			playerLookTicks--;
		if (stepTicks > 0 && --stepTicks == 0 && step != null)
		{
			if (follower.stayAt(step))
			{
				seat = step;
				seatMoved = step;
			}
			step = null;
		}

		watchForTheStop(now, here, animating);

		int worked = now - startTick;
		// Not while the follower is off the seat peering over the shoulder:
		// a walk begun from the player's front tile wins over the peer's
		// return, and the seat is then wherever the walk ended. The walks are
		// not lost, only late; their flags stay down until the peer is over.
		boolean onTheSeat = peerTicks == 0;
		if (parked())
		{
			// Play report: walking between the tile at the player's side and
			// the one behind them "looks off". Gathering takes no step: at a
			// work tile it works alongside, and on a plain seat it reads.
			if (workMin != null)
				keepAtTheWork(now, workPose, bareHanded);
			else
				parkTheScroll(0);
		}
		else if (onTheSeat && !paced && worked >= paceAt)
		{
			paced = true;
			pace();
		}
		else if (onTheSeat && !stretched && worked >= stretchAt)
		{
			stretched = true;
			stretch(here, false);
		}
		else if (onTheSeat && !stretchedAgain && worked >= stretchAgainAt)
		{
			stretchedAgain = true;
			stretch(here, true);
		}
		else if (!sitting && !stretched && worked >= sitAt)
			sit();
		else if (sitting && follower.getPoseOverride() == 0
			&& seat.equals(follower.getWorldLocation()))
			// Something else put its pose over the sit - a copy of the work
			// made from the seat, an emote loop copied - and let go of it:
			// back down, rather than stood while it still counts as sitting.
			sit();

		if ("fishing".equals(activity) && workMin == null && now >= waterLookAt)
		{
			waterLookAt = now + jitter(WATER_LOOK_TICKS, WATER_LOOK_SPREAD);
			look(waterTile(), 4 /* WATER_GAZE_TICKS */);
		}

		keepTheSeatItsWay(now, here, animating);
		if (peerTicks > 0)
			// Off the seat, in front of the player: the seat's facing is theirs.
			return;
		var wanted = wantedFace(here);
		if (workMin != null && (wanted == null || wanted.equals(target)))
		{
			// "The work", at a work tile, is its own: the middle of it.
			if (!facingTheWork)
				faceTheWork(now);
		}
		else
			face(wanted);
	}

	/**
	 * The habits of the particular seat, once a tick. Each is a small thing
	 * that says the follower knows what this work is: hands to a fire, a
	 * shrug over the notes at the anvil, a look over the shoulder at a
	 * fletcher, a glance at the mark when the guard stirs, a nod per hammer,
	 * feet stamped in the cold.
	 */
	void keepTheSeatItsWay(int now, WorldPoint here, boolean animating)
	{
		switch (mode)
		{
			case FIRESIDE:
				if (animating && !sitting && !scrollOut && now >= warmAt)
				{
					warmAt = now + WARM_EVERY_TICKS;
					follower.playAnimation(WARM_HANDS);
				}
				break;
			case ANVIL:
				if (scrollOut && --studyTicks <= 0)
				{
					putScrollAway();
					gesture(SHRUG);
					studyResume = 3 /* STUDY_RESUME_TICKS */;
				}
				else if (!scrollOut && studyResume > 0 && --studyResume == 0)
					study();
				break;
			case STANDING:
				overTheShoulder(now);
				break;
			case STALL:
				if (guard != null && now >= guardGlanceAt
					&& guard.getPoseAnimation() != guard.getIdlePoseAnimation())
				{
					guardGlanceAt = now + GUARD_GLANCE_GAP_TICKS;
					lookNow(here, 2 /* GUARD_GLANCE_TICKS */);
				}
				break;
			case FOREMAN:
				if (wasAnimating && !animating)
					gesture(NOD);
				break;
			case BRAZIER:
				if (now >= stampAt && !sitting)
				{
					stampAt = now + jitter(STAMP_EVERY_TICKS, STAMP_SPREAD);
					gesture(STAMP_FEET);
				}
				break;
			default:
				break;
		}
		wasAnimating = animating;
	}

	/**
	 * Every few minutes at work with nothing to click, a look over the
	 * shoulder: to the tile in front of the player, the peer held for a few
	 * ticks, and back to the seat. The front tile the pathing refuses is no
	 * look, and the next is a few minutes off again.
	 */
	void overTheShoulder(int now)
	{
		if (peerTicks > 0)
		{
			if (--peerTicks == 0)
			{
				if (follower.stayAt(seat))
				{
					follower.setStayFaceTile(target);
					facing = target;
				}
			}
			return;
		}
		if (now < shoulderAt)
			return;
		var local = client.getLocalPlayer();
		// Walking is only seen here on the tick a walk begins; a look then
		// would go to the front tile and the walk set off from there with the
		// peer held.
		if (sitting || scrollOut || walking || local == null)
			// Busy with something; the next tick, not the next five minutes.
			return;
		shoulderAt = now + jitter(SHOULDER_AFTER_TICKS, SHOULDER_SPREAD);
		if (!follower.moveToFront(local))
			return;
		peerTicks = PEER_TICKS;
		facing = null;
		// On arrival at the front tile: on the way, moving would drop it.
		follower.playWhenStill(PEER, PEER_TICKS);
	}

	/**
	 * What the seat looks at right now, in order of claim: a look being
	 * taken, the player while the scroll is out (the anvil and the hotspot
	 * excepted: the notes are about the work) or the bag is full, the work
	 * for a nod, the player when sitting or when they have stopped, the work
	 * otherwise - or the guard, on the stall watch.
	 */
	WorldPoint wantedFace(WorldPoint here)
	{
		if (currentLook != null)
			return currentLook;
		boolean studying = mode == Mode.ANVIL || mode == Mode.FOREMAN || parked();
		if ((scrollOut && !studying) || playerLookTicks > 0)
			return here;
		if (lookTicks > 0)
			return target;
		return sitting || stopped ? here : watched();
	}

	/** One tile past the seat, away from the work: where a turned back looks. */
	WorldPoint awayTile()
	{
		var base = seat != null ? seat : follower.getWorldLocation();
		if (base == null || target == null)
			return null;
		int dx = Integer.signum(base.getX() - target.getX()),
			dy = Integer.signum(base.getY() - target.getY());
		if (dx == 0 && dy == 0)
			dy = -1;
		return base.dx(dx).dy(dy);
	}

	/** The compost went on: two seconds facing the other way, where it stands. */
	void compost()
	{
		if (walking)
			return;
		// COMPOST_TICKS: The compost: a step back and two seconds facing the other way.
		look(awayTile(), 3 /* COMPOST_TICKS */);
	}

	/** The same for a chain - the level-up's send-off - stood up first when sitting. */
	void gesture(int[] animationIds)
	{
		if (!sitting)
		{
			follower.playAnimations(animationIds);
			return;
		}
		int[] chain = new int[animationIds.length + 1];
		chain[0] = STAND_UP;
		System.arraycopy(animationIds, 0, chain, 1, animationIds.length);
		follower.playAnimations(chain);
	}

	/**
	 * A look at a tile for the controller's own reactions: the face on the
	 * seat, or a glance straight away off it - the queue only runs during a
	 * session, and the out-of-runes think happens outside one.
	 */
	void lookAt(WorldPoint tile, int ticks)
	{
		if (seat == null && tile != null)
			follower.glanceAt(tile, ticks * 600);
		else
			look(tile, ticks);
	}

	/**
	 * The patch inspector's notes, after the session has ended: the scroll
	 * out over free hands while the controller keeps the feet a moment.
	 *
	 * @return the ticks to keep the feet, or 0 when there was no note to take
	 */
	int endNote()
	{
		return borrow.isHolding() || hands.isHolding() || !holdTheScroll(0) ? 0 : NOTE_TICKS;
	}

	void face(WorldPoint tile)
	{
		if (tile != null && !tile.equals(facing))
		{
			follower.setStayFaceTile(tile);
			facing = tile;
			facingTheWork = false;
		}
	}

	/** Turned to the middle of its own work, exactly, as the player is to theirs. */
	void faceTheWork(int now)
	{
		follower.setStayFaceArea(workMin, workMax);
		facing = null;
		facingTheWork = true;
		facedAt = now;
	}

	/**
	 * At work: the work pose held most of the time, a break with the scroll
	 * now and then. The swing waits until the follower stands on its tile,
	 * turned to the work, a tick after the turn began; it stops for a look,
	 * for the player stopping, and for the work going. Somebody else's pose
	 * over it - a stranger's peer, a held emote copied - is waited out rather
	 * than fought.
	 */
	void keepAtTheWork(int now, int pose, boolean bareHanded)
	{
		if (scrollOut && scrollTicks > 0)
		{
			// On a break; puts the reading pose back if it was let go of.
			parkTheScroll(0);
			return;
		}
		if (scrollOut)
			// A plain seat's scroll, carried onto a work tile: the work now.
			// Left out, it was read at the vein for the rest of the session.
			putScrollAway();
		boolean ready = pose > 0 && !workGone && !stopped && !sitting && currentLook == null
			&& playerLookTicks == 0 && (bareHanded || borrow.isHolding() && !toolAside)
			&& seat.equals(follower.getWorldLocation()) && follower.isSettled()
			&& follower.isTurned() && facingTheWork && now > facedAt;
		if (!ready)
		{
			letGoOfTheWork();
			return;
		}
		int held = follower.getPoseOverride();
		if (held != 0 && held != working)
			return;
		if (held != pose)
		{
			follower.setPoseOverride(pose);
			working = pose;
		}
		if (stretch == 0)
			stretch = jitter(WORK_STRETCH_TICKS, WORK_STRETCH_SPREAD);
		if (++workTicks >= stretch)
		{
			letGoOfTheWork();
			workTicks = 0;
			stretch = 0;
			parkTheScroll(jitter(WORK_BREAK_TICKS, WORK_BREAK_SPREAD));
		}
	}

	/** A gatherer's seat or a patch's: kept without a step, working or reading. */
	boolean parked()
	{
		return mode == Mode.GATHERING || mode == Mode.PATCH;
	}

	/** The swing stops; only its own pose is cleared. */
	void letGoOfTheWork()
	{
		if (working != 0)
		{
			follower.clearPoseOverride(working);
			working = 0;
		}
	}

	// ------------------------------------------------------------------ stop

	/**
	 * The repeat ends and the player stands still: after five ticks the
	 * follower turns to them, waits a moment, and if they are still at
	 * nothing, scratches its head. Then not again for a couple of minutes.
	 */
	void watchForTheStop(int now, WorldPoint here, boolean animating)
	{
		boolean still = here.equals(lastHere);
		lastHere = here;
		if (animating || !still)
		{
			stillTicks = 0;
			stopped = false;
			stopWait = 0;
			return;
		}
		stillTicks++;
		if (!stopped && stillTicks >= STOP_AFTER_TICKS && now >= stopCooldownUntil)
		{
			stopped = true;
			stopWait = jitter(STOP_WAIT_TICKS, 2);
		}
		if (stopped && stopWait > 0 && --stopWait == 0)
		{
			gesture(SCRATCH_HEAD);
			stopCooldownUntil = now + jitter(200 /* STOP_COOLDOWN_TICKS */, 30);
		}
	}

	// ----------------------------------------------------------------- walks

	/** Out three tiles on the far side of the seat from the work, and back. */
	void pace()
	{
		int dx = Integer.signum(seat.getX() - target.getX()),
			dy = Integer.signum(seat.getY() - target.getY());
		if (dx == 0 && dy == 0)
			return;
		var away = seat.dx(PACE_TILES * dx).dy(PACE_TILES * dy);
		walk(Arrays.asList(away, seat), false);
	}

	/**
	 * A slow half circle behind the player: to the tile behind them, to the
	 * other flank, back behind, and home to the seat.
	 */
	void stretch(WorldPoint here, boolean thenSit)
	{
		int dx = Integer.signum(target.getX() - here.getX()),
			dy = Integer.signum(target.getY() - here.getY());
		if (dx == 0 && dy == 0)
			dy = 1;
		WorldPoint behind = here.dx(-2 * dx).dy(-2 * dy),
			flankA = here.dx(-2 * dy).dy(2 * dx),
			flankB = here.dx(2 * dy).dy(-2 * dx),
			other = flankA.distanceTo(seat) >= flankB.distanceTo(seat) ? flankA : flankB;
		walk(Arrays.asList(behind, other, behind, seat), thenSit);
	}

	void walk(List<WorldPoint> route, boolean thenSit)
	{
		putScrollAway();
		legs.clear();
		legs.addAll(route);
		walking = true;
		sitAfterWalk = thenSit;
		stopped = false;
		lookTicks = 0;
		forgetLooks();
		// Up first, and the walk waits for it.
		legWait = standUp() ? STAND_UP_TICKS : 0;
	}

	/** One leg at a time, with a pause at each; the last leg is the seat. */
	void walk()
	{
		if (legWait > 0)
		{
			legWait--;
			return;
		}
		if (legs.isEmpty())
		{
			walking = false;
			face(target);
			if (sitAfterWalk)
				sit();
			return;
		}
		WorldPoint next = legs.remove(0),
			from = follower.getWorldLocation();
		if (!follower.stayAt(next))
		{
			// The ground refused a leg: straight home, and the controller's
			// retake covers a refused seat too.
			legs.clear();
			walking = false;
			if (follower.stayAt(seat))
				face(target);
			return;
		}
		// Face whoever is there while stood at a waypoint, the work once home.
		follower.setStayFaceTile(legs.isEmpty() ? target : null);
		facing = legs.isEmpty() ? target : null;
		int distance = from == null ? PACE_TILES : from.distanceTo(next);
		legWait = distance + 3 + random.nextInt(3);
	}

	// ------------------------------------------------------------------- sit

	void sit()
	{
		int pose = config.restAnimation();
		if (pose <= 0)
			return;
		putScrollAway();
		sitting = true;
		follower.setPoseOverride(pose);
	}

	/** @return whether there was a sit to stand from */
	boolean standUp()
	{
		if (!sitting)
			return false;
		sitting = false;
		follower.setPoseOverride(0);
		follower.playAnimation(STAND_UP);
		return true;
	}

	/**
	 * A one-shot, the controller's own reactions among them, stood up first
	 * when sitting; the pose sits it back down after.
	 */
	void gesture(int animationId)
	{
		if (sitting)
		{
			follower.playAnimations(new int[]{STAND_UP, animationId});
		}
		else
			follower.playAnimation(animationId);
	}

	// ---------------------------------------------------------------- scroll

	/**
	 * The scroll, through the same hands as the errand's, for a few ticks -
	 * or until put away, for none. Skipped over a borrowed tool (they share
	 * the weapon slot), over a scroll already out for something else, while
	 * sitting, off the seat, and over the player's shoulder: a tally due on
	 * the tick of a look took the scroll out in front of the player and read
	 * it for the whole look, which was never seen.
	 */
	void takeOutTheScroll(int ticks)
	{
		if (seat == null || sitting || walking || scrollOut || peerTicks > 0
			|| borrow.isHolding() || hands.isHolding())
			return;
		holdTheScroll(ticks);
	}

	/**
	 * The scroll and quill into the errand's hands and the writing pose on,
	 * out for so many ticks, or until put away for none.
	 *
	 * @return false when the hands decline them
	 */
	boolean holdTheScroll(int ticks)
	{
		hands.hold(ErrandController.QUILL_PROP, ErrandController.SCROLL_PROP);
		if (!hands.isHolding())
			return false;
		follower.setPoseOverride(ErrandController.WRITE_SCROLL_POSE);
		scrollOut = true;
		scrollTicks = ticks;
		return true;
	}

	/**
	 * The gatherer's company, parked: the scroll out and left out, over a
	 * borrowed tool set down for it. Put away to join in - the copy swings
	 * the tool - and out again once back on the seat.
	 */
	void parkTheScroll(int ticks)
	{
		if (seat == null || sitting || walking || peerTicks > 0 || playerLookTicks > 0)
			return;
		if (scrollOut)
		{
			// Something else let go of the pose over it - a held emote
			// copied and done - and left the scroll in the hand:
			// back to reading it, rather than holding it at the side.
			if (follower.getPoseOverride() == 0)
				follower.setPoseOverride(ErrandController.WRITE_SCROLL_POSE);
			return;
		}
		if (borrow.isHolding() && !toolAside)
			toolAside = borrow.setAside();
		// Something else in the hand is not the scroll's to take.
		if (!hands.isHolding())
			holdTheScroll(ticks);
	}

	void putScrollAway()
	{
		if (scrollOut)
		{
			scrollOut = false;
			scrollTicks = 0;
			follower.setPoseOverride(0);
			hands.release();
		}
		if (toolAside)
		{
			// Whatever the hands were freed for has finished with them.
			toolAside = false;
			borrow.takeBack();
		}
	}

	// ------------------------------------------------------------- gathering

	/**
	 * A look at a tile for so many ticks, queued after any in progress. On
	 * the seat it is the face; off it, a glance. Nothing to look at is no look.
	 */
	void look(WorldPoint tile, int ticks)
	{
		if (tile != null)
			looks.add(new Look(tile, ticks));
	}

	/**
	 * A look that starts this tick when nothing is being looked at, rather
	 * than the next: a glance at a guard stirring is late a tick later.
	 */
	void lookNow(WorldPoint tile, int ticks)
	{
		if (tile == null || currentLook != null)
		{
			look(tile, ticks);
			return;
		}
		currentLook = tile;
		currentLookTicks = ticks;
		if (seat == null)
			follower.glanceAt(tile, ticks * 600);
	}

	/** The look in progress runs down and the next begins. */
	void lookOn()
	{
		if (currentLookTicks > 0 && --currentLookTicks == 0)
			currentLook = null;
		if (currentLook == null && !looks.isEmpty())
		{
			var next = looks.remove(0);
			currentLook = next.tile;
			currentLookTicks = next.ticks;
			if (seat == null)
				follower.glanceAt(next.tile, next.ticks * 600);
		}
	}

	/** A moved fishing spot turned up: a look at it before the player clicks. */
	void lookNext(WorldPoint at)
	{
		look(at, NEXT_LOOK_TICKS);
	}

	/**
	 * The target went. A tree worked long enough falls, and the follower
	 * flinches before looking at the player; a rock worked long enough
	 * empties, and the follower looks at the empty rock, at the next full
	 * one, then at the player. No step clear: a gatherer's company stays
	 * parked where it is. Anything
	 * quicker is a look at the player and then at where the next one is -
	 * unless the last depletion was moments ago, when once was enough.
	 *
	 * @param worked ticks this target was worked
	 * @param next the nearest same-name target, or null when there is none
	 */
	void depleted(String activity, int worked, WorldPoint next, WorldPoint here, int now)
	{
		// NEXT_LOOK_GAP_TICKS: Two depletions closer than this share the one look for the next.
		boolean recent = lastDepletionTick >= 0 && now - lastDepletionTick < 15 /* NEXT_LOOK_GAP_TICKS */;
		lastDepletionTick = now;
		if (walking)
			return;
		if ("woodcutting".equals(activity) && worked >= TIMBER_AFTER_TICKS)
		{
			gesture(FLINCH);
			look(here, PLAYER_BEAT_TICKS);
			look(next, NEXT_LOOK_TICKS);
			return;
		}
		if ("mining".equals(activity) && worked >= ROCK_AFTER_TICKS)
		{
			look(target, EMPTY_LOOK_TICKS);
			look(next, NEXT_LOOK_TICKS);
			look(here, PLAYER_BEAT_TICKS);
			return;
		}
		if (recent)
			return;
		look(here, PLAYER_BEAT_TICKS);
		look(next, NEXT_LOOK_TICKS);
	}

	/**
	 * A bird's nest at the player's feet: a look at it, and the bend to it
	 * when a player has been seen doing it.
	 */
	void nest(WorldPoint tile, boolean peerProven)
	{
		look(tile, NEXT_LOOK_TICKS);
		if (peerProven && !walking)
			gesture(NEST_LOOK);
	}

	/**
	 * A bit of water that is not the spot: out past it from the seat, a tile
	 * or two, a little to one side.
	 */
	WorldPoint waterTile()
	{
		int dx = Integer.signum(target.getX() - seat.getX()),
			dy = Integer.signum(target.getY() - seat.getY());
		if (dx == 0 && dy == 0)
			dy = 1;
		int reach = 1 + random.nextInt(2),
			side = random.nextInt(3) - 1;
		return target.dx(dx * reach - dy * side).dy(dy * reach + dx * side);
	}

	// ------------------------------------------------------------------- bag

	/** Fourteen slots left: a note. Not for a player dropping as they go. */
	void bagHalf(String lastOption)
	{
		if (!"Drop".equalsIgnoreCase(lastOption))
			takeOutTheScroll(NOTE_TICKS);
	}

	/**
	 * The last slot gone: up, a look at the player, a shrug, and one step
	 * toward the nearest bank booth if there is one close and the ground
	 * allows it - not from a gathering seat, which stays parked. Not for a
	 * player dropping as they go.
	 */
	void bagFull(String lastOption, WorldPoint here)
	{
		if ("Drop".equalsIgnoreCase(lastOption) || seat == null || walking)
			return;
		putScrollAway();
		playerLookTicks = 8 /* PLAYER_LOOK_TICKS */;
		face(here);
		gesture(SHRUG);
		sitting = false;
		follower.setPoseOverride(0);

		var bank = SkillingController.nearestObject(client, here, 15 /* BANK_TILES */,
			SkillingController.BANK_NAMES);
		if (bank != null && !parked())
		{
			step = seat.dx(Integer.signum(bank.getX() - seat.getX()))
				.dy(Integer.signum(bank.getY() - seat.getY()));
			stepTicks = 3 /* SHRUG_TICKS */;
		}
	}

	// ------------------------------------------------------------------- end

	/**
	 * The session is over: the scroll away, the walk dropped, the sit ended.
	 *
	 * @param natural a proper end rather than an abort, which earns the
	 * stand-up; an abort simply lets the pose go
	 * @return the stand-up to play before whatever the ending plays, or 0
	 */
	int end(boolean natural)
	{
		putScrollAway();
		letGoOfTheWork();
		workMin = null;
		workMax = null;
		legs.clear();
		walking = false;
		peerTicks = 0;
		guard = null;
		int leadIn = 0;
		if (sitting)
		{
			sitting = false;
			follower.setPoseOverride(0);
			leadIn = natural ? STAND_UP : 0;
		}
		seat = null;
		facing = null;
		step = null;
		stepTicks = 0;
		forgetLooks();
		return leadIn;
	}

	int jitter(int base, int spread)
	{
		return base + random.nextInt(2 * spread + 1) - spread;
	}
}

package com.follower;

import net.runelite.api.kit.KitType;

/**
 * Labels for body kits.
 *
 * <p><b>Body kits have no names anywhere in the game.</b> The identkit config
 * carries a body part id, model ids, chathead models, recolours and a
 * non-selectable flag - and nothing else; the game's own character creation
 * shows styles as a model with arrows either side, never a name.
 *
 * <p>This class previously showed names taken from the wiki's
 * character-creation lists, matched by position. That was a guess, and a
 * wrong one: after filtering out the styles the cache flags non-selectable
 * and collapsing byte-identical duplicates, the cache still holds 71 male
 * hair styles against the wiki's 57 names, so 14 unnamed styles sit at
 * unknown positions and everything after the first of them is mislabelled.
 * A wrong name is worse than no name, so styles are numbered - exactly what
 * the game shows - and the follower rebuilds live as its own preview.
 */
class KitNames
{

	/**
	 * @param index position of this kit within its body part's offered list
	 * @param total how many styles that body part offers
	 * @return a label such as "Style 2 of 71", or "-" when nothing is set
	 */
	static String label(KitType part, int index, int total)
	{
		if (index < 0)
			return "Default";
		return "Style " + (index + 1) + " of " + total;
	}
}

package com.follower;

import java.io.*;
import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import java.util.*;
import java.util.Map;
import java.util.Set;
import java.util.function.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import com.follower.ModelRepository.Entry;

/**
 * Parses item, kit and spotanim definitions straight out of the client's own
 * loaded cache ({@link Client#getIndexConfig()}), so the plugin needs no
 * offline dumps: Hub users get the full outfit catalogue and graphic
 * repository the moment the client is running.
 *
 * <p>The opcode layouts are data, in {@code cache-opcodes.txt}: a faithful
 * port of runelite-cache's ItemLoader, KitLoader and SpotAnimLoader,
 * transcribed from the library's bytecode and validated in game by diffing
 * every entry against the offline dumper's output
 * ({@code ::follower cachecheck}). This class walks a definition by that
 * table and keeps the named fields. Output shapes mirror the dump files
 * exactly, defaults included, so the repositories cannot tell the difference.
 *
 * <p>Every definition parses independently: a malformed or future-format
 * entry is skipped with a note rather than failing the whole catalogue.
 */
@Slf4j
class LiveCacheParser
{
	/** Config-index archive ids (net.runelite.cache.ConfigType). */
	static final int CONFIG_IDENTKIT = 3,
		CONFIG_ITEM = 10,
		CONFIG_SPOTANIM = 13;

	/**
	 * The cache's text encoding. Windows-1252 leaves five bytes unassigned,
	 * which the cache library reads as '?'.
	 */
	static final Charset CP1252 = Charset.forName("windows-1252");

	/** Per definition type, each opcode's payload fields (null: an unknown opcode). */
	static final Map<String, String[][]> LAYOUTS = new HashMap<>();

	static
	{
		try (BufferedReader reader = Resources.reader("cache-opcodes.txt"))
		{
			for (String line = reader.readLine(); line != null; line = reader.readLine())
			{
				var words = line.split("#", 2)[0].trim().split("\\s+");
				if (words.length < 2)
					continue;
				var fields = Arrays.copyOfRange(words, 2, words.length);
				for (String run : words[1].split(","))
				{
					var ends = run.split("-");
					for (int op = Integer.parseInt(ends[0]); op <= Integer.parseInt(ends[ends.length - 1]); op++)
						LAYOUTS.computeIfAbsent(words[0], type -> new String[256][])[op] = fields;
				}
			}
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
	}


	/** Wearable items keyed by id, matching equipment-models.json's items map. */
	static Map<String, Entry> parseItems(Client client)
	{
		return parse(client, CONFIG_ITEM, (id, data) -> decodeItem(data), "item",
			(id, e) -> log.warn("Item {} failed to parse (further failures counted silently)", id, e));
	}

	/**
	 * Body kits keyed by id, matching equipment-models.json's kits map.
	 *
	 * @param nonSelectableOut when non-null, receives the ids of kits flagged
	 * non-selectable - the styles character creation does not offer, which is
	 * how the NPC-only and unreleased extras are told apart from real player
	 * styles. Collected on the side so {@link ModelRepository.Entry} keeps the
	 * dump file's exact shape and {@code ::follower cachecheck} stays honest.
	 */
	static Map<String, Entry> parseKits(Client client, Set<Integer> nonSelectableOut)
	{
		return parse(client, CONFIG_IDENTKIT, (id, data) ->
		{
			boolean[] nonSelectable = new boolean[1];
			var entry = decodeKit(data, nonSelectable);
			if (entry != null && nonSelectable[0] && nonSelectableOut != null)
				nonSelectableOut.add(id);
			return entry;
		}, null,
			(id, e) -> { });
	}

	/** Spotanims keyed by id, matching spotanims.json. */
	static Map<String, SpotAnimRepository.Entry> parseSpotAnims(Client client)
	{
		return parse(client, CONFIG_SPOTANIM, (id, data) -> decodeSpotAnim(data), "spotanim",
			(id, e) -> log.warn("Spotanim {} failed to parse: {}", id, e.getMessage()));
	}

	/**
	 * Every definition in one config archive, keyed by id. One that fails to
	 * parse is skipped and handed to {@code failed}: every one when
	 * {@code counted} is null, otherwise the first, with a count of them all
	 * at the end under that name.
	 */
	static <E> Map<String, E> parse(Client client, int archive, BiFunction<Integer, byte[], E> decoder,
		String counted, BiConsumer<Integer, RuntimeException> failed)
	{
		var configs = client.getIndexConfig();
		Map<String, E> entries = new LinkedHashMap<>();
		if (configs == null)
			return entries;
		int failures = 0;
		for (int id : configs.getFileIds(archive))
		{
			byte[] data = configs.loadData(archive, id);
			if (data == null)
				continue;
			try
			{
				var entry = decoder.apply(id, data);
				if (entry != null)
					entries.put(Integer.toString(id), entry);
			}
			catch (RuntimeException e)
			{
				if (failures++ == 0 || counted == null)
					failed.accept(id, e);
			}
		}
		if (failures > 0 && counted != null)
			log.warn("{} {} definitions failed to parse", failures, counted);
		return entries;
	}

	static Entry decodeItem(byte[] data)
	{
		var v = decode("item", data);
		int[] male = ids(v, "male0", "male1", "male2"),
			female = ids(v, "female0", "female1", "female2");
		// Mirror the dumper's wearable filter: only items with a worn model.
		if (male[0] == -1 && female[0] == -1)
			return null;

		var entry = new ModelRepository.Entry();
		// The cache's convention for an unnamed item is the literal string
		// "null" (the definition's constructor default), and the dumper
		// preserved it - so the live parse must too.
		entry.n = (String) v.getOrDefault("name", "null");
		entry.mo = (Integer) v.getOrDefault("maleOffset", 0);
		entry.fo = (Integer) v.getOrDefault("femaleOffset", 0);
		entry.wp1 = (Integer) v.getOrDefault("wearPos1", -1);
		entry.wp2 = (Integer) v.getOrDefault("wearPos2", -1);
		entry.wp3 = (Integer) v.getOrDefault("wearPos3", -1);
		entry.m = male;
		entry.f = female;
		entry.hm = anySet(ids(v, "maleHead0", "maleHead1"));
		entry.hf = anySet(ids(v, "femaleHead0", "femaleHead1"));
		return recoloured(entry, v);
	}

	static Entry decodeKit(byte[] data, boolean[] nonSelectableOut)
	{
		var v = decode("kit", data);
		nonSelectableOut[0] |= v.containsKey("nonSelectable");
		int[] models = (int[]) v.get("models");
		// Mirror the dumper's filter: kits without models are unusable.
		if (models == null || models.length == 0)
			return null;

		var entry = new ModelRepository.Entry();
		entry.bp = (Integer) v.get("bodyPart");
		entry.m = models;
		entry.f = models;
		entry.ch = anySet(ids(v, "head0", "head1", "head2", "head3", "head4"));
		return recoloured(entry, v);
	}

	static SpotAnimRepository.Entry decodeSpotAnim(byte[] data)
	{
		var v = decode("spotanim", data);
		var entry = new SpotAnimRepository.Entry();
		entry.m = (Integer) v.getOrDefault("model", 0);
		// Mirror the dumper's filter: a spotanim without a model shows nothing.
		if (entry.m <= 0)
			return null;
		entry.a = (Integer) v.getOrDefault("animation", -1);
		entry.rx = unlessDefault(v, "resizeX", 128);
		entry.ry = unlessDefault(v, "resizeY", 128);
		entry.rot = unlessDefault(v, "rotation", 0);
		entry.am = unlessDefault(v, "ambient", 0);
		entry.co = unlessDefault(v, "contrast", 0);
		return recoloured(entry, v);
	}

	/**
	 * Walks one definition by its type's layouts; the named fields come back
	 * by name. EVERY opcode is consumed at its exact width, or the stream
	 * would desynchronise and the rest parse as garbage.
	 */
	static Map<String, Object> decode(String type, byte[] data)
	{
		var layouts = LAYOUTS.get(type);
		var in = ByteBuffer.wrap(data);
		Map<String, Object> values = new HashMap<>();
		for (int opcode = in.get() & 0xFF; opcode != 0; opcode = in.get() & 0xFF)
		{
			if (layouts[opcode] == null)
				throw new IllegalStateException("unknown " + type + " opcode " + opcode);
			for (String field : layouts[opcode])
			{
				Object value = read(in, field.charAt(0));
				if (field.length() > 2)
					values.put(field.substring(2), value);
			}
		}
		return values;
	}

	/** One payload field; cache-opcodes.txt lists the kinds. */
	static Object read(ByteBuffer in, char kind)
	{
		switch (kind)
		{
			case 'b':
				return (int) in.get();
			case 'B':
				return in.get() & 0xFF;
			case 'h':
				return in.getShort() & 0xFFFF;
			case 'i':
				return in.getInt();
			case 's':
				int start = in.position();
				while (in.get() != 0)
				{
					// to the terminator
				}
				return new String(in.array(), start, in.position() - start - 1, CP1252).replace('\uFFFD', '?');
			case 'f':
				return true;
			case 'c':
				short[][] pairs = new short[2][in.get() & 0xFF];
				for (int i = 0; i < pairs[0].length; i++)
				{
					pairs[0][i] = in.getShort();
					pairs[1][i] = in.getShort();
				}
				return pairs;
			case 'H':
			case 'I':
			case 'L':
				int[] list = new int[kind == 'L' ? in.getShort() & 0xFFFF : in.get() & 0xFF];
				for (int i = 0; i < list.length; i++)
					list[i] = kind == 'I' ? in.getInt() : in.getShort() & 0xFFFF;
				return list;
			case 'o':
				in.get();
				while (in.get() != 0)
					read(in, 's');
				return null;
			case 'p':
				for (int count = in.get() & 0xFF; count > 0; count--)
				{
					boolean isString = in.get() == 1;
					in.position(in.position() + 3);
					read(in, isString ? 's' : 'i');
				}
				return null;
			default:
				throw new IllegalStateException("unknown field kind " + kind);
		}
	}

	/** The named ids, -1 for any the definition did not set. */
	static int[] ids(Map<String, Object> values, String... names)
	{
		int[] ids = new int[names.length];
		for (int i = 0; i < names.length; i++)
			ids[i] = (Integer) values.getOrDefault(names[i], -1);
		return ids;
	}

	/** The dump leaves out an id array that is all -1 rather than writing it. */
	static int[] anySet(int[] ids)
	{
		return Arrays.stream(ids).allMatch(id -> id == -1) ? null : ids;
	}

	/** The definition's find/replace pairs onto its entry; null where it has none. */
	static <E extends Recolours> E recoloured(E entry, Map<String, Object> values)
	{
		short[][] colours = (short[][]) values.getOrDefault("colours", new short[2][]),
			textures = (short[][]) values.getOrDefault("textures", new short[2][]);
		entry.cf = colours[0];
		entry.cr = colours[1];
		entry.tf = textures[0];
		entry.tr = textures[1];
		return entry;
	}

	/** The dump leaves out a value at its default. */
	static Integer unlessDefault(Map<String, Object> values, String name, int defaultValue)
	{
		var value = (Integer) values.get(name);
		return value == null || value == defaultValue ? null : value;
	}
}

package com.follower;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.Map;
import java.util.function.UnaryOperator;
import javax.swing.*;
import net.runelite.client.ui.*;

/**
 * The memory surface (R20): everything the follower currently knows about
 * you, in one window, with the eraser underneath.
 *
 * <p>Three rounds of features built hidden machinery - tallies, bests, the
 * incident, place feelings, the date it met you - and machinery a player
 * cannot see is machinery they cannot trust. This makes it legible, and the
 * "Forget everything" button is the named mitigation for the invasiveness of
 * remembering anything at all: the memory is a gift the player can decline.
 * It doubles as a debugging window, which is why a region no rule names
 * still shows its id.
 *
 * <p>The window renders a snapshot handed to it (taken on the client thread)
 * rather than reading live state from the event thread.
 */
class MemoryDialog extends JDialog
{
	final JPanel list = Ui.column();

	/** The counts with names of their own, in the order the window lists them. */
	static final List<String> NAMED_COUNTS = java.util.Arrays.asList(
		"kills", "kills" + TriggerContext.TODAY, "deaths", "deaths" + TriggerContext.TODAY,
		"levels", "levels" + TriggerContext.TODAY, "quests", "music", "collections",
		"want:kept", "want:missed");

	MemoryDialog(Runnable onForget)
	{
		super((java.awt.Frame) null, "Follower Buddy - Memory", false);

		setDefaultCloseOperation(HIDE_ON_CLOSE);

		var root = Ui.panel(new BorderLayout(0, 6));
		root.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		var hint = Ui.label(wrapped(Resources.text("memoryHint")), ColorScheme.MEDIUM_GRAY_COLOR);

		var where = Ui.label(wrapped(Resources.text("memoryWhere")), ColorScheme.MEDIUM_GRAY_COLOR);
		where.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));

		var top = Ui.panel(new BorderLayout());
		top.add(hint, BorderLayout.NORTH);
		top.add(where, BorderLayout.SOUTH);
		root.add(top, BorderLayout.NORTH);

		root.add(Ui.scroller(list), BorderLayout.CENTER);

		var forget = new JButton("Forget everything");
		forget.setToolTipText(Resources.text("forgetTip"));
		forget.setFocusPainted(false);
		forget.addActionListener(e ->
		{
			int sure = JOptionPane.showConfirmDialog(this,
				Resources.text("forgetConfirm"),
				"Forget everything?",
				JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
			if (sure == JOptionPane.YES_OPTION)
				onForget.run();
		});
		root.add(forget, BorderLayout.SOUTH);

		setContentPane(root);
		setMinimumSize(new Dimension(380, 460));
		// Narrow and tall: the rows wrap at the width below, and the summary
		// is a list read downwards. QA, 15 Oct: it opened at 743x460.
		setPreferredSize(new Dimension(420, 640));
		pack();
		setLocationRelativeTo(null);
	}

	/** Renders a snapshot and fronts the window. */
	void show(List<String[]> rows)
	{
		list.removeAll();
		for (var row : rows)
		{
			if (row[1] == null)
			{
				var section = new JLabel(row[0]);
				section.setFont(FontManager.getRunescapeBoldFont());
				section.setForeground(ColorScheme.BRAND_ORANGE);
				section.setBorder(BorderFactory.createEmptyBorder(10, 0, 2, 0));
				section.setAlignmentX(LEFT_ALIGNMENT);
				list.add(section);
			}
			else
			{
				// Wrapped, since a label never wraps by itself and the window
				// scrolls only downwards: long rows were cut off.
				var line = Ui.label(wrapped(row[1].isEmpty()
					? row[0] : row[0] + ":  " + row[1]),
					row[1].isEmpty() ? ColorScheme.MEDIUM_GRAY_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
				line.setAlignmentX(LEFT_ALIGNMENT);
				list.add(line);
			}
		}
		Ui.relayout(list);
		setVisible(true);
		toFront();
	}

	// ------------------------------------------------------------- the summary

	/**
	 * Everything worth showing, as (label, value) rows; a null value marks a
	 * section header and an empty one a plain remark. Static and pure so the
	 * shape of what the player is told stays testable without a window.
	 *
	 * @param regionNames place names by region id, from the Locations rules;
	 * an id with no name is shown bare
	 * @param accountKey the key a kill count is kept under for this account
	 * (ChronicleProgress.accountKey); only this account's counts are shown
	 */
	static List<String[]> summarise(TriggerContext c, Map<Integer, String> regionNames,
		UnaryOperator<String> accountKey)
	{
		List<String[]> rows = new ArrayList<>();

		rows.add(header("THE BASICS"));
		rows.add(row("First met", c.getMetOnDay() > 0
			? java.time.LocalDate.ofEpochDay(c.getMetOnDay())
				+ " (" + daysAgo(c.getDaysKnown()) + ")"
			: "not recorded yet"));
		rows.add(row("Sessions together", c.getSessionCount()));
		rows.add(row("Mood right now", c.getMoodBand()));

		rows.add(header("COUNTS"));
		if (c.getTallies().isEmpty())
			rows.add(remark("Nothing counted yet."));
		// The named counts always show, in one order, each day's under its
		// lifetime row: only the kills by creature are ever many, and they
		// alone are capped, so they never push the rest out (qa5 #28).
		List<Map.Entry<String, Integer>> tallies = new ArrayList<>();
		for (var tally : c.getTallies().entrySet())
		{
			if (!NAMED_COUNTS.contains(tally.getKey()))
				tallies.add(tally);
		}
		for (String key : NAMED_COUNTS)
		{
			var value = c.getTallies().get(key);
			if (value != null)
				rows.add(row(keyLabel(key), value));
		}
		tallies.sort(Map.Entry.<String, Integer>comparingByValue().reversed());
		for (var tally : tallies.subList(0, Math.min(10, tallies.size())))
			rows.add(row(keyLabel(tally.getKey()), tally.getValue()));
		if (tallies.size() > 10)
			rows.add(remark("...and " + (tallies.size() - 10) + " more."));

		rows.add(header("BESTS"));
		List<String[]> bests = new ArrayList<>();
		c.getRecords().forEach((what, value) ->
		{
			if (isShown(what, c.getRecords(), accountKey))
				bests.add(row(keyLabel(what, c.getKillCountNames()), value));
		});
		if (bests.isEmpty())
			rows.add(remark("No records held yet."));
		rows.addAll(bests);

		// The phrase is written for the middle of a sentence - "I keep
		// thinking about {memory}" - so bare in a window it reads as a
		// riddle ("the way that went"?). Quoting it as its words is what makes
		// it legible out of context. The file key is left out: QA, 15 Oct.
		rows.add(header("THE INCIDENT"));
		rows.add(c.hasIncident()
			? row("Keeps bringing up", "\"" + c.getIncidentPhrase() + c.getMemoryWhere()
				+ ", " + c.getMemoryWhen(System.currentTimeMillis()) + "\" (x"
				+ c.getIncidentCount() + ")")
			: remark("Nothing has stuck yet."));


		rows.add(header("RIGHT NOW"));
		int before = rows.size();
		if (!c.getAskedTree().isEmpty())
			rows.add(row("Waiting on an answer", askedAbout(c.getAskedTree())));
		if (rows.size() == before)
			rows.add(remark("Nothing in hand."));

		rows.add(header("BOOKKEEPING"));
		rows.add(row("One-time lines already said", c.getSpokenOnce().size()));
		rows.add(row("Lines counted, to vary them", c.getLineWear().size()));

		return rows;
	}

	/**
	 * What the follower asked, in words, for the three trees it ships with;
	 * a tree of the player's own shows its id. Text sweep, 14 Oct: the raw
	 * id was shown for all of them.
	 */
	static String askedAbout(String tree)
	{
		switch (tree)
		{
			case "want-outing":
				return "Whether you'll take it somewhere";
			case "game-hands":
				return "Which hand it's hiding something in";
			default:
				return tree;
		}
	}

	/**
	 * A count's or a best's key in words: the keys are what the plugin files
	 * them under, and the window showed them raw ("kill:goblin",
	 * "kills:today", "session: 187"). A key with no words here is shown as
	 * it is.
	 */
	static String keyLabel(String key)
	{
		return keyLabel(key, java.util.Collections.emptyMap());
	}

	/** @param killCountNames each boss's name as the game writes it, by its lower-case name */
	static String keyLabel(String key, Map<String, String> killCountNames)
	{
		boolean today = key.endsWith(TriggerContext.TODAY);
		String base = today ? key.substring(0, key.length() - TriggerContext.TODAY.length()) : key,
			label;
		if (base.startsWith("kill:") && base.length() > "kill:".length())
			label = capitalised(base.substring("kill:".length())) + " kills";
		else if (base.startsWith("kc:") && base.length() > "kc:".length())
		{
			// Per account: the account's key is not for showing.
			String boss = base.substring("kc:".length());
			boss = boss.contains("@") ? boss.substring(0, boss.indexOf('@')) : boss;
			label = killCountNames.getOrDefault(boss, capitalised(boss)) + " kill count";
		}
		else
		{
			switch (base)
			{
				case "kills":
					label = "Kills";
					break;
				case "deaths":
					label = "Deaths";
					break;
				case "levels":
					label = "Levels gained";
					break;
				case "quests":
					label = "Quests completed";
					break;
				case "music":
					label = "Music tracks unlocked";
					break;
				case "collections":
					label = "Collection log items";
					break;
				case "want:kept":
					label = "Outings taken";
					break;
				case "want:missed":
					label = "Outings missed";
					break;
				case "hit":
					label = "Biggest hit";
					break;
				case "session":
					label = "Longest session (minutes)";
					break;
				default:
					return key;
			}
		}
		return today ? label + " today" : label;
	}

	/**
	 * Whether a best belongs in this account's window. Kill counts are kept
	 * per account, so another account's on the same profile is left out, and
	 * the one kept before counts were per account is shown only while this
	 * account has none of its own, as the book's page reads it.
	 */
	static boolean isShown(String key, Map<String, Integer> records,
		UnaryOperator<String> accountKey)
	{
		if (!key.startsWith("kc:"))
			return true;
		String bare = key.contains("@") ? key.substring(0, key.indexOf('@')) : key,
			mine = accountKey.apply(bare);
		return key.equals(mine) || (key.equals(bare) && !records.containsKey(mine));
	}

	static String capitalised(String s)
	{
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	/** Text that wraps at the window's narrowest, in the HTML renderer's px (x1.3 on screen). */
	static String wrapped(String text)
	{
		return Ui.html(260, text);
	}

	/** "today", "1 day ago" or "N days ago". */
	static String daysAgo(int days)
	{
		if (days <= 0)
			return "today";
		return days == 1 ? "1 day ago" : days + " days ago";
	}

	static String[] header(String text)
	{
		return new String[]{text, null};
	}

	static String[] row(String label, String value)
	{
		return new String[]{label, value};
	}

	static String[] row(String label, int count)
	{
		return row(label, Integer.toString(count));
	}

	static String[] remark(String text)
	{
		return new String[]{text, ""};
	}
}

package com.follower;

import com.google.gson.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import lombok.*;
import org.slf4j.*;
import org.slf4j.Logger;

/**
 * A JSON file that ships with defaults and that the player may edit:
 * phrases.json and dialogs.json. Written from the jar when it is missing,
 * folded three ways into the player's copy when an update ships new defaults,
 * and reloaded when it changes on disk. Change detection is a lastModified/size
 * poll driven from the game tick - a WatchService buys nothing here and brings
 * its own platform quirks.
 *
 * <p>Folding an update into a file somebody has been editing needs three
 * copies rather than two, because from the player's file alone a line the
 * update ADDED and a line the player DELETED look identical - both are lines
 * the bundled file has and theirs does not. Keep the defaults as they stood at
 * the last merge and the question becomes answerable: bundled against base is
 * what the update did, theirs against base is what the player did.
 *
 * <p>The rule throughout is that upstream wins where the player has not touched
 * something, and the player wins everywhere they have. This is one class
 * rather than a copy per loader because the two drifting apart on a question
 * this subtle would be a bug nobody would find by reading either one.
 *
 * @param <T> the file's root object, as Gson reads it
 */
@RequiredArgsConstructor
@Getter
abstract class MergingLoader<T>
{
	/** Under each loader's own name, as before the two shared this class. */
	final Logger log = LoggerFactory.getLogger(getClass());

	final Gson gson;
	final Class<T> type;

	/** The player's file in the data directory; the jar's copy is default-{fileName}. */
	final String fileName;

	/** The bundled defaults as of the last merge, for the three-way. */
	final String baseName;

	/**
	 * The array the merge works on: a file without one is left alone. It is
	 * also what the client log calls the content when a read comes back empty.
	 */
	final String listName;

	/** What the status line and the client log call the loaded content. */
	final String noun;

	Path file,
		baseFile;
	long lastModified = -1L,
		lastSize = -1L;

	/** Built at the start of each merge; the merge's reads and writes go through it. */
	Gson pretty;

	String status = "not loaded";

	List<String> errors = Collections.emptyList();

	/** Takes a freshly parsed file: validates it and makes it current. */
	abstract void load(T parsed, List<String> problems);

	/** The file could not be read at all. */
	abstract void unreadable(List<String> problems);

	/** How many things are loaded now, for "keeping N previous ...". */
	abstract int size();

	/**
	 * Folds the bundled defaults into the player's copy, and {@link #save}s it
	 * when anything moved.
	 *
	 * @param base the defaults as they shipped at the last merge, or null
	 */
	abstract void merge(JsonObject bundled, JsonObject ours, JsonObject base) throws IOException;

	/** A base for a file that has no record of the last merge, or null. */
	abstract JsonObject unrecordedBase(JsonObject ours);

	/** Whether the last merge already saw exactly these defaults and this file. */
	boolean upToDate(byte[] shipped) throws IOException
	{
		return false;
	}

	/** Called once the merge, and its record, are written. */
	void merged(byte[] shipped) throws IOException
	{
	}

	/**
	 * Points the loader at the data directory, writing the bundled defaults if
	 * no file exists yet, then loads.
	 */
	void initialise(Path dataDir)
	{
		initialise(dataDir, false);
	}

	/**
	 * @param mergeDefaults whether to fold newly bundled defaults into an
	 * existing file first. The plugin passes true; the test harnesses supply
	 * exact files and pass false through the plain overload.
	 */
	void initialise(Path dataDir, boolean mergeDefaults)
	{
		file = dataDir.resolve(fileName);
		baseFile = dataDir.resolve(baseName);
		if (!Files.exists(file))
			writeDefaults();
		else if (mergeDefaults)
			mergeNewDefaults();
		reload();
	}

	InputStream bundled()
	{
		return MergingLoader.class.getResourceAsStream("/com/follower/default-" + fileName);
	}

	JsonObject json(byte[] bytes)
	{
		return pretty.fromJson(new String(bytes, StandardCharsets.UTF_8), JsonObject.class);
	}

	void mergeNewDefaults()
	{
		try (InputStream in = bundled())
		{
			if (in == null)
				return;
			byte[] shipped = in.readAllBytes();
			if (upToDate(shipped))
				return;
			pretty = gson.newBuilder().setPrettyPrinting().disableHtmlEscaping().create();
			JsonObject bundled = json(shipped),
				ours = json(Files.readAllBytes(file));
			if (bundled == null || ours == null || !bundled.has(listName) || !ours.has(listName))
				return;

			// The record of what shipped last time, or for a file that never
			// merged, what can be told of where it came from.
			var base = readBase();
			if (base == null)
				base = unrecordedBase(ours);
			merge(bundled, ours, base);

			// Written whether or not anything moved, and last, so a merge that
			// half-happened is retried rather than recorded as done. From here
			// on there is a base and the guessing above never runs again.
			if (writeBase(bundled))
				merged(shipped);
		}
		catch (Exception e)
		{
			// A file that cannot be merged is one reload() will complain about
			// in its own words; do not block startup over it.
			log.warn("Could not merge new defaults into {}", file, e);
		}
	}

	/** Writes the merged file, with the file as it stood kept beside it. */
	void save(JsonObject ours) throws IOException
	{
		Files.copy(file, file.resolveSibling(fileName + ".bak"), StandardCopyOption.REPLACE_EXISTING);
		Files.write(file, (pretty.toJson(ours) + "\n").getBytes(StandardCharsets.UTF_8));
	}

	/** A bundled file, or null when it is missing or unreadable. */
	JsonObject resource(String path)
	{
		try (InputStream in = MergingLoader.class.getResourceAsStream(path))
		{
			return in == null ? null : pretty.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), JsonObject.class);
		}
		catch (Exception e)
		{
			log.warn("Could not read {}, merging without a base", path, e);
			return null;
		}
	}

	/** The defaults as they stood at the last merge, or null if never written. */
	JsonObject readBase()
	{
		if (!Files.exists(baseFile))
			return null;
		try
		{
			return json(Files.readAllBytes(baseFile));
		}
		catch (Exception e)
		{
			// Unreadable is the same as absent: fall back to the bootstrap
			// rather than refusing to merge at all.
			log.warn("Could not read {}, merging without a base", baseFile, e);
			return null;
		}
	}

	boolean writeBase(JsonObject bundled)
	{
		try
		{
			Files.write(baseFile, (pretty.toJson(bundled) + "\n").getBytes(StandardCharsets.UTF_8));
			return true;
		}
		catch (Exception e)
		{
			// Only costs a repeat of the bootstrap next start, which is
			// idempotent, so it is not worth failing the merge over.
			log.warn("Could not record the merged defaults in {}", baseFile, e);
			return false;
		}
	}

	void writeDefaults()
	{
		try (InputStream in = bundled())
		{
			if (in == null)
			{
				// The jar lacks its own defaults: a broken build.
				log.warn("Bundled /com/follower/default-{} is missing", fileName);
				return;
			}
			Files.createDirectories(file.getParent());
			Files.copy(in, file);
		}
		catch (IOException e)
		{
			log.warn("Could not write default {} to {}", noun, file, e);
			return;
		}
		// Recorded at once, so the first update merges against what was
		// written rather than against a guess.
		try (InputStream in = bundled())
		{
			if (in != null)
				Files.copy(in, baseFile, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException e)
		{
			// Only costs the first update a merge against 1.4.0's defaults.
			log.warn("Could not record the starter {} in {}", noun, baseFile, e);
		}
	}

	/** Reloads if the file changed since last check. Returns true if it was re-read. */
	boolean reloadIfChanged()
	{
		if (file == null || !Files.isRegularFile(file))
			return false;
		try
		{
			long modified = Files.getLastModifiedTime(file).toMillis(),
				size = Files.size(file);
			if (modified == lastModified && size == lastSize)
				return false;
		}
		catch (IOException e)
		{
			return false;
		}
		reload();
		return true;
	}

	void reload()
	{
		if (file == null)
			return;

		List<String> problems = new ArrayList<>();

		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			T parsed = gson.fromJson(reader, type);

			if (parsed == null)
			{
				// An empty read is almost never an empty file on purpose. It is
				// what a poll sees in the instant between an editor truncating
				// the file and writing it back, and it is what a failed save
				// leaves behind. Treating it as "nothing" replaced the whole
				// personality with silence, which is exactly what the syntax
				// error path below is careful NOT to do. Keep what we had, say
				// so, and do not record this read as current - the next poll
				// then picks up the finished file.
				problems.add("File is empty; keeping " + size() + " previous " + noun);
				errors = problems;
				status = "empty file, keeping " + size() + " previous " + noun;
				log.warn("{} read as empty; keeping the previous {}", fileName, listName);
				return;
			}

			lastModified = Files.getLastModifiedTime(file).toMillis();
			lastSize = Files.size(file);
			load(parsed, problems);
		}
		catch (IOException e)
		{
			problems.add("Could not read " + file + ": " + e.getMessage());
			unreadable(problems);
		}
		catch (JsonParseException e)
		{
			// Keep what loaded last time on a syntax error; losing your
			// follower's whole personality over a trailing comma is worse
			// than running stale content.
			problems.add("JSON error: " + e.getMessage());
			errors = problems;
			status = "syntax error, keeping " + size() + " previous " + noun;
			log.warn("{} failed to parse", fileName, e);
		}
	}

	/** Makes what was loaded current, with a status line that counts its problems. */
	void loaded(List<String> problems, String summary)
	{
		errors = problems;
		status = summary + (problems.isEmpty() ? "" : ", " + problems.size() + " warning(s)");
		// At INFO: when a rule never fires or a conversation does not open,
		// the first thing worth knowing is whether it loaded at all.
	}

	/** Makes {@code held} a copy of {@code with}, in place: it is the object the file holds. */
	static void replace(JsonObject held, JsonObject with)
	{
		for (String key : new ArrayList<>(held.keySet()))
			held.remove(key);
		for (var entry : with.entrySet())
			held.add(entry.getKey(), entry.getValue());
	}

	/**
	 * Every field except the named ones. A field the update did not change is
	 * left alone; one the player changed is theirs; the rest take the update's
	 * value, or go if the update dropped them.
	 *
	 * @return how many fields moved
	 */
	static int fields(JsonObject held, JsonObject base, JsonObject bundled, Set<String> except)
	{
		int changes = 0;
		Set<String> keys = new LinkedHashSet<>(bundled.keySet());
		keys.addAll(base.keySet());
		for (String key : keys)
		{
			JsonElement before = base.get(key),
				now = bundled.get(key);
			// Skipped when the update has nothing to offer here, or when the
			// player moved it: a tuned cooldown or a reworded note is a
			// decision, not a stale copy.
			if (except.contains(key) || Objects.equals(before, now) || !Objects.equals(held.get(key), before))
				continue;
			if (now == null)
				held.remove(key);
			else
				held.add(key, now);
			changes++;
		}
		return changes;
	}

	/**
	 * An array of strings, merged as a set with a history. What the update
	 * added arrives; what it removed goes, unless the player had already
	 * removed it; everything else - their own lines, their own rewordings - is
	 * left exactly where it is. A list the player never touched takes the
	 * update's whole, in the update's order: a dialog node's lines are said in
	 * order, and a reworded first line appended at the end had the follower
	 * say "Lead on." before its answer (dialogue check, 14 Oct).
	 *
	 * @return more than 0 when anything moved
	 */
	static int strings(JsonObject held, String key, JsonObject base, JsonObject bundled)
	{
		if (!held.has(key) || !held.get(key).isJsonArray())
			return 0;
		var shipped = strings(bundled, key);
		var mine = strings(held, key);
		var kept = shipped;
		int changes = 1;
		if (base == null || !mine.equals(strings(base, key)) || mine.equals(shipped))
		{
			Set<String> was = new HashSet<>(strings(base, key));
			kept = new ArrayList<>();
			changes = 0;
			for (String line : mine)
			{
				if (was.contains(line) && !shipped.contains(line))
				{
					changes++;
					continue;
				}
				kept.add(line);
			}
			for (String line : shipped)
			{
				if (!was.contains(line) && !kept.contains(line))
				{
					kept.add(line);
					changes++;
				}
			}
		}
		if (changes > 0)
		{
			var out = new JsonArray();
			kept.forEach(out::add);
			held.add(key, out);
		}
		return changes;
	}

	/** The strings under a key, or empty. */
	static List<String> strings(JsonObject object, String key)
	{
		List<String> out = new ArrayList<>();
		var array = array(object, key);
		if (array != null)
		{
			for (var element : array)
			{
				if (element.isJsonPrimitive())
					out.add(element.getAsString());
			}
		}
		return out;
	}

	/**
	 * Whether the player has written anything of their own here.
	 *
	 * <p>The only question the first run can honestly ask. With no base there
	 * is no way to tell a deletion from an addition, but a file holding
	 * nothing but shipped lines has plainly not been written into, and can be
	 * brought up to date without taking anything away from anybody.
	 */
	static boolean untouched(List<String> theirs, List<String> shipped)
	{
		return new HashSet<>(shipped).containsAll(theirs);
	}

	/** The objects of an array, by their {@code id}. */
	static Map<String, JsonObject> byId(JsonArray array)
	{
		Map<String, JsonObject> map = new HashMap<>();
		if (array != null)
		{
			for (var element : array)
			{
				String id = idOf(element);
				if (id != null)
					map.put(id, element.getAsJsonObject());
			}
		}
		return map;
	}

	static JsonArray array(JsonObject object, String key)
	{
		return object != null && object.has(key) && object.get(key).isJsonArray()
			? object.getAsJsonArray(key) : null;
	}

	static String idOf(JsonElement element)
	{
		if (element == null || !element.isJsonObject())
			return null;
		var id = element.getAsJsonObject().get("id");
		return id != null && id.isJsonPrimitive() ? id.getAsString() : null;
	}
}

package com.follower;

import com.google.gson.Gson;
import java.util.*;
import java.util.List;
import java.util.Map;
import javax.inject.*;
import lombok.*;
import net.runelite.api.kit.KitType;
import java.util.Set;

/**
 * Holds the item -> worn model mapping produced by tools/cache-dumper.
 *
 * <p>The RuneLite API's {@code ItemComposition} only exposes {@code getInventoryModel()};
 * the worn model ids ({@code maleModel0..2} / {@code femaleModel0..2}) and body kit models
 * live in the cache definitions and are not reachable at runtime. This class loads the
 * dump so {@link AppearanceComposer} can rebuild a player model from parts.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
class ModelRepository
{
	/** An item the follower can wear, for the outfit picker. */
	@RequiredArgsConstructor
	static class WearableItem
	{
		final int id;
		final String name;

		@Override
		public String toString()
		{
			return name;
		}
	}

	static class Entry extends Recolours
	{
		/** Item name; present in dumps produced by the current dumper. */
		String n;
		/** Kits only: KitDefinition.bodyPartId, encoding both body part and gender. */
		Integer bp;
		/** Vertical offsets the client applies to a worn model before merging. */
		Integer mo,
			fo;

		/**
		 * Equipment slots this item occupies. wp1 is where it goes; wp2 and wp3 are
		 * further slots it HIDES - a platebody hides the arms kit, a full helm hides
		 * hair and jaw. Indices match KitType.
		 */
		Integer wp1,
			wp2,
			wp3;

		int offset(int gender)
		{
			var chosen = gender == 1 ? fo : mo;
			return chosen == null ? 0 : chosen;
		}
		/** Male worn model ids, -1 for unused. */
		int[] m;
		/** Female worn model ids, -1 for unused. */
		int[] f;

		int[] models(int gender)
		{
			int[] chosen = gender == 1 ? f : m;
			if (chosen == null || chosen.length == 0)
				chosen = gender == 1 ? m : f;
			return chosen;
		}

		/**
		 * Chathead models: items carry male/female dialogue-head variants, kits
		 * carry KitDefinition.chatheadModels. These are the separate models real
		 * dialogs animate, with their own talk-animation skeletons.
		 */
		int[] hm,
			hf,
			ch;

		/** The dialogue-head models for this entry, or null if it has none. */
		int[] headModels(int gender)
		{
			if (ch != null)
				return ch;
			int[] chosen = gender == 1 ? hf : hm;
			if (chosen == null)
				chosen = gender == 1 ? hm : hf;
			return chosen;
		}
	}

	final Gson gson;

	@Getter
	volatile boolean loaded;

	@Getter
	volatile String status = "not loaded";

	volatile Map<String, Entry> items = Collections.emptyMap(),
		kits = Collections.emptyMap();

	/**
	 * Builds the catalogue from the client's own loaded cache - the no-dump
	 * path every Hub install uses. A dump file, when present, wins for the
	 * ids it has: it is the development override and the validation baseline
	 * for the live parser. No-op while the cache indexes are not available
	 * yet; callers retry.
	 */
	void loadFromClient(net.runelite.api.Client client)
	{
		var liveItems = LiveCacheParser.parseItems(client);
		if (liveItems.isEmpty())
			return;
		addLive(liveItems, LiveCacheParser.parseKits(client, null));
	}

	/**
	 * The live cache's items and kits, under a dump's: the items newer than
	 * the dump are in the catalogue too, where a dump from August left them
	 * out on the development client (qa5 #75).
	 */
	void addLive(Map<String, Entry> liveItems, Map<String, Entry> liveKits)
	{
		items = liveItems;
		kits = liveKits;
		loaded = true;
			status = items.size() + " items, " + kits.size() + " kits (live cache)";
	}

	/** Whether the client's own cache has been read in yet, under a dump or not. */
	boolean hasReadTheLiveCache()
	{
		return loaded;
	}

	void unload()
	{
		items = Collections.emptyMap();
		kits = Collections.emptyMap();
		loaded = false;
		status = "not loaded";
	}

	Entry item(int itemId)
	{
		return items.get(Integer.toString(itemId));
	}

	/** Name of a dumped item, or null if this dump predates name support. */
	String itemName(int itemId)
	{
		var entry = item(itemId);
		return entry == null ? null : entry.n;
	}

	/**
	 * Every wearable item whose name matches {@code query}, sorted by name. The dump
	 * contains exactly the items that have worn models, so this is the complete set
	 * of things the follower can actually be dressed in.
	 */
	List<WearableItem> search(String query, int limit)
	{
		String needle = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
		List<WearableItem> matches = new ArrayList<>();

		for (var entry : items.entrySet())
		{
			String name = entry.getValue().n;
			if (name == null || name.isEmpty() || "null".equals(name))
				continue;
			if (!needle.isEmpty() && !name.toLowerCase(Locale.ROOT).contains(needle))
				continue;

				matches.add(new WearableItem(Integer.parseInt(entry.getKey()), name));

			if (matches.size() >= limit * 4)
				break;
		}

		matches.sort((a, b) ->
		{
			// Exact and prefix matches first, then alphabetical.
			boolean ap = a.name.toLowerCase(Locale.ROOT).startsWith(needle),
				bp = b.name.toLowerCase(Locale.ROOT).startsWith(needle);
			if (ap != bp)
				return ap ? -1 : 1;
			return a.name.compareToIgnoreCase(b.name);
		});

		return matches.size() > limit ? matches.subList(0, limit) : matches;
	}

	/**
	 * The body kits, the parts whose kit ids are gender-specific, in bodyPartId
	 * order. The id is this index for a male kit, and this index + 7 for a
	 * female one - verified against the whole dump, which is symmetric across
	 * the two halves. The side panel edits them in this order too.
	 */
	static final KitType[] BODY_PARTS = {
		KitType.HAIR, KitType.JAW, KitType.TORSO, KitType.ARMS,
		KitType.HANDS, KitType.LEGS, KitType.BOOTS,
	};

	static final int PARTS_PER_GENDER = BODY_PARTS.length;

	/** @return the bodyPartId a kit must have to belong to this slot and gender. */
	static int bodyPartId(KitType part, int gender)
	{
		for (int i = 0; i < BODY_PARTS.length; i++)
		{
			if (BODY_PARTS[i] == part)
				return i + (gender == 1 ? PARTS_PER_GENDER : 0);
		}
		return -1;
	}

	/**
	 * Kit ids the cache flags non-selectable - the styles character creation
	 * never offers. Read from the live cache; empty until that lands.
	 */
	volatile Set<Integer> nonSelectableKits = Collections.emptySet();

	void setNonSelectableKits(Set<Integer> ids)
	{
		nonSelectableKits = ids == null ? Collections.emptySet() : ids;
	}

	/**
	 * Every kit the picker should offer for one body part and gender, sorted
	 * by id. Two filters make this the list a player recognises rather than a
	 * raw cache listing:
	 *
	 * <ul>
	 *   <li>kits flagged non-selectable are dropped - those are the NPC-only
	 *   and unreleased styles character creation hides;</li>
	 *   <li>kits whose models and chatheads are byte-identical to an earlier
	 *   one are dropped - the cache holds several such pairs (33/35 hands,
	 *   43/44 boots, 141/142/152 female hair, ...) which rendered as
	 *   duplicate entries that looked and behaved identically.</li>
	 * </ul>
	 */
	List<Integer> kitsFor(KitType part, int gender)
	{
		int wanted = bodyPartId(part, gender);
		List<Integer> ids = new ArrayList<>();
		if (wanted < 0)
			return ids;

		for (var entry : kits.entrySet())
		{
			var bodyPart = entry.getValue().bp;
			if (bodyPart == null || bodyPart != wanted)
				continue;
				int id = Integer.parseInt(entry.getKey());
				if (!nonSelectableKits.contains(id))
					ids.add(id);
		}

		ids.sort(Integer::compareTo);

		List<Integer> distinct = new ArrayList<>(ids.size());
		Set<String> seen = new java.util.HashSet<>();
		for (int id : ids)
		{
			if (seen.add(appearanceSignature(kits.get(Integer.toString(id)))))
				distinct.add(id);
		}
		return distinct;
	}

	/** What the kit actually looks like: identical signatures render identically. */
	static String appearanceSignature(Entry entry)
	{
		if (entry == null)
			return "null";
		return Arrays.toString(entry.m)
			+ Arrays.toString(entry.ch)
			+ Arrays.toString(entry.cf)
			+ Arrays.toString(entry.cr)
			+ Arrays.toString(entry.tf)
			+ Arrays.toString(entry.tr);
	}

	/** Every wearable item id in the dump. */
	List<Integer> allItemIds()
	{
		List<Integer> ids = new ArrayList<>(items.size());
		for (String key : items.keySet())
				ids.add(Integer.parseInt(key));
		return ids;
	}

	boolean hasNames()
	{
		for (var e : items.values())
			return e.n != null;
		return false;
	}

	Entry kit(int kitId)
	{
		return kits.get(Integer.toString(kitId));
	}
}

package com.follower;

import java.util.*;
import java.util.List;
import java.util.Map;
import java.util.function.*;
import net.runelite.api.*;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarPlayerID;
import com.follower.Gestures.Gesture;
import static com.follower.Moments.Doing.*;

/**
 * The moments: the small occasions outside any work session that the
 * company marks with its body rather than a line. A level, the pet, the
 * player's legs giving out, a stranger turning up to talk to them.
 *
 * <p>One at a time, because each takes the feet. A seat held by
 * {@link SkillingController} is not a reason to miss one - most levels land
 * mid-session, and every skilling pet does - so the seat is excused for the
 * moment and retaken after. Anything else that owns the feet (thrall work,
 * the spectator, an errand under way) beats a moment, which then happens in
 * place or not at all - and so does the seat once it has the follower sitting
 * in for the long haul, since walking off would leave the rest pose to sit it
 * back down wherever it arrived. Silent throughout; the level-up and pet-drop
 * lines are the rules' and stay theirs.
 *
 * <p>Every gesture goes through the {@link Gestures} ledger, so no body
 * beat repeats within its own cooldown whatever the rules are doing, and
 * the ones that are meant to be rare (the walk over, the notes) stay rare.
 */
class Moments implements Noticing.Looker
{
	/** EMOTE_CLAP and EMOTE_BOW, both proven on the follower by the rules. */
	static final int CLAP = 865,
		BOW = 858;

	/** The boss send-off's own chain: cheer, dance, jump for joy. */
	static final int[] CELEBRATION = {862, 866, 2109};

	/** The pet is looked for this long after the message. */
	static final int PET_HUNT_TICKS = 20;

	/** The bend, proven on the follower by the cat errand. */
	static final int BEND = 827;

	/** EMOTE_YES: the look up from the notes. EMOTE_WAVE: the farewell. */
	static final int NOD = KeepingCompany.NOD,
		WAVE = 863;

	/** Ticks the notes stay out for a write-up, in place and on the spot. */
	static final int NOTES_TICKS = 5,
		NOTES_ON_THE_SPOT_TICKS = 7,
		LOOK_UP_MS = 1800;

	/** How much of an occasion something is. */
	enum Tier
	{
		/** A glance at it. */
		SMALL,
		/** The notes out, from where it stands. */
		MEDIUM,
		/** Walked over to and written up on the spot, then a look up and a nod. */
		BIG
	}

	/** The tier a drop of this value earns, or null for nothing at all. */
	static Tier tierFor(long value)
	{
		// BIG_DROP: The rarity ladder for a drop, in gp. The research point is that a
		// response only counts as one when it is proportionate to the news: a
		// routine drop gets a glance, a good one gets the scroll out, a great
		// one is walked over to and written up on the spot. The same numbers as
		// the loot rules use, so the words and the body agree about what is big.
		if (value >= 1_000_000 /* BIG_DROP */)
			return Tier.BIG;
		if (value >= 100_000 /* NICE_DROP */)
			return Tier.MEDIUM;
		return value >= 10_000 /* SMALL_DROP */ ? Tier.SMALL : null;
	}

	/** Ten minutes of keeping close after the pet. */
	static final int PET_CLOSE_TICKS = 1000;

	static final int WIND_COOLDOWN_TICKS = 1000;

	/** The peer at a stranger who has the player's ear, then a watch on them. */
	static final int PEER = KeepingCompany.PEER;

	/** A spawn this fresh that turns to the player is one that came for them. */
	static final int STRANGER_WINDOW_TICKS = 5;

	/** Which moment has the feet, if any. */
	enum Doing
	{
		NOTHING, LEVEL, PET, WIND, STRANGER,
		/** Gone to look at something: a drop, a nest, a signpost. */
		LOOK
	}

	final Client client;
	final FollowerEntity follower;
	final SkillingController skilling;

	/** Thrall work, the spectator or an errand: they all beat a moment. */
	final BooleanSupplier feetTaken;
	/**
	 * A park the player gave. It beats every moment that walks or plants
	 * the follower, as the above do; the wave at the logout tab moves
	 * nothing, and is waved from the post.
	 */
	final BooleanSupplier parked,
		inCombat;
	final IntSupplier daysKnown;
	/** The scroll and the pose, for a write-up; null in a harness without hands. */
	final PropFlourish flourish;
	final Gestures gestures;

	boolean lookWrites;
	int lookHoldTicks,
		lookUpAt;

	Doing doing = NOTHING;
	int arriveAt,
		leaveAt;

	int levels;
	int[] beat;

	int petHuntUntil = -1;
	NPC lastFollower;
	int lastFollowerTick = -1000;
	NPC pet;
	int closeUntil;

	boolean wasRunning,
		windArmed;
	int windCooldownUntil;

	/** Level-less NPCs that just spawned, and when, until they show their business. */
	final Map<NPC, Integer> newcomers = new LinkedHashMap<>();
	NPC stranger;

	/**
	 * @param flourish the scroll-and-pose flourish for a write-up, or null
	 * @param grateful whether the follower owes the player one just now,
	 * which halves every gesture's cooldown
	 * @param parked whether the player has parked the follower
	 */
	Moments(Client client, FollowerEntity follower,
		SkillingController skilling, BooleanSupplier feetTaken, BooleanSupplier inCombat,
		IntSupplier daysKnown, PropFlourish flourish, BooleanSupplier grateful,
		BooleanSupplier parked)
	{
		this.client = client;
		this.follower = follower;
		this.skilling = skilling;
		this.feetTaken = feetTaken;
		this.parked = parked;
		this.inCombat = inCombat;
		this.daysKnown = daysKnown;
		this.flourish = flourish;
		this.gestures = new Gestures(client::getTickCount, grateful);
	}

	/**
	 * Whether a moment owns the follower's feet. Registered beside the seat
	 * and the errands, so none of this reads as a Stay the player asked for.
	 */
	boolean holdsTheFeet()
	{
		return doing != NOTHING;
	}

	/** Whether the wander should stay in close - the ten minutes after the pet. */
	boolean keepsClose()
	{
		return client.getTickCount() < closeUntil;
	}

	// --------------------------------------------------------------- level up

	/**
	 * A level. A clap, or a bow while the follower is still being polite
	 * about it; every third one is worth walking over for, and the
	 * ninety-ninth gets the send-off a boss does. Facing the player either
	 * way, and up off the sit first when the seat has it sitting.
	 */
	void levelUp(int level)
	{
		var local = client.getLocalPlayer();
		var here = local == null ? null : local.getWorldLocation();
		if (here == null)
			return;
		levels++;
		int[] play = level >= 99 /* MASTERY */ ? CELEBRATION.clone()
			// NEW_DAYS: The formal era: the first two days bow rather than clap.
			: new int[]{daysKnown.getAsInt() <= 2 /* NEW_DAYS */ ? BOW : CLAP};
		int now = client.getTickCount();
		if (follower.isDoingAgility())
		{
			// An Agility level lands as the player finishes an obstacle, with
			// the follower still on it, and the crossing would cancel the clap
			// on its first frame: owed, and clapped once the feet are free.
			owed = play;
			owedUntil = now + OWED_TICKS;
			return;
		}
		// WALK_EVERY: Every third level walks over to do it; the others clap in place.
		if (levels % 3 /* WALK_EVERY */ == 0 && free() && follower.moveToFront(local))
		{
			clap(play, here);
			return;
		}
		// In place, but a level gained on the move (an Agility course) had its
		// clap cancelled on the first frame: moving drops an emote (QA, 15
		// Oct). So on the move it stops where it is, finishes the step, and
		// claps on the next tick, planted for it as the walk over is.
		if (follower.isMoving() && free())
		{
			clap(play, null);
			return;
		}
		skilling.gesture(play, here);
	}

	/**
	 * The level's own moment: the seat excused, and the clap played on
	 * arrival.
	 *
	 * @param walkTo the player's tile to walk over to, or null to stop where
	 * it stands and clap on the next tick
	 */
	void clap(int[] play, WorldPoint walkTo)
	{
		skilling.setExcused(true);
		if (walkTo == null)
			follower.stayHere();
		doing = LEVEL;
		beat = play;
		arriveAt = client.getTickCount() + (walkTo == null ? 1 : walkTicks(walkTo));
		leaveAt = 0;
	}

	/** A clap owed from a level gained on an obstacle, and the tick it is let go. */
	int[] owed;
	int owedUntil;

	/** About ten seconds: past that, the moment has gone. */
	static final int OWED_TICKS = 17;

	/** The owed clap, as a level gained on the move is clapped: stopped, then clapped. */
	void clapOwed(int now)
	{
		int[] play = owed;
		owed = null;
		if (now <= owedUntil)
			clap(play, null);
	}

	// -------------------------------------------------------------------- pet

	/**
	 * A game message. The one the moments read is the pet drop's: the new
	 * pet is whichever follower-flagged NPC turns up within twenty ticks of
	 * it - or turned up a tick or two before, since the two arrive together.
	 */
	void noteChatMessage(String message, ChatMessageType type)
	{
		if (message == null
			|| (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM))
			return;
		String plain = message.replaceAll("<[^>]*>", "").toLowerCase(Locale.ROOT);
		// PET_MESSAGE: The pet-drop message, in the smallest certain fragment of it.
		if (!plain.contains("funny feeling" /* PET_MESSAGE */))
			return;
		int now = client.getTickCount();
		if (lastFollower != null && now - lastFollowerTick <= 2)
			goToThePet(lastFollower);
		else
			petHuntUntil = now + PET_HUNT_TICKS;
	}

	/**
	 * An NPC appeared. A follower-flagged one is the pet, if one is being
	 * looked for; one with no combat level is a newcomer to watch, in case
	 * it came for the player.
	 */
	void npcSpawned(NPC npc)
	{
		if (npc == null)
			return;
		int now = client.getTickCount();
		var composition = npc.getComposition();
		if (composition != null && composition.isFollower())
		{
			if (now <= petHuntUntil)
				goToThePet(npc);
			else
			{
				lastFollower = npc;
				lastFollowerTick = now;
			}
			return;
		}
		if (npc.getCombatLevel() == 0)
			newcomers.put(npc, now);
	}

	/** An NPC went. The stranger leaving is the end of the peer; so is the pet's. */
	void npcDespawned(NPC npc)
	{
		if (npc == null)
			return;
		newcomers.remove(npc);
		if (npc == lastFollower)
			lastFollower = null;
		if ((doing == STRANGER && npc == stranger) || (doing == PET && npc == pet))
			letGo(true);
	}

	/**
	 * Over to the pet: a tile beside it, a bend to look, and back - and the
	 * wander keeps in close for ten minutes after, whether or not the walk
	 * could be taken.
	 */
	void goToThePet(NPC npc)
	{
		int now = client.getTickCount();
		petHuntUntil = -1;
		lastFollower = null;
		closeUntil = now + PET_CLOSE_TICKS;
		WorldPoint at = npc.getWorldLocation(),
			from = follower.getWorldLocation();
		if (at == null || from == null || !free() || at.getPlane() != from.getPlane()
			|| at.distanceTo(from) > 15 /* PET_REACH_TILES */)
			return;
		if (goBeside(at, 1, PET))
			pet = npc;
	}

	/**
	 * Over to the nearest tile so many steps off a thing that the follower
	 * will stand on, faced at it, as the moment given.
	 *
	 * @return whether it set off; false leaves the seat as it was
	 */
	boolean goBeside(WorldPoint at, int steps, Doing what)
	{
		var from = follower.getWorldLocation();
		var spots = SkillingController.ring(at, at, steps, at.getPlane());
		spots.sort(SkillingController.stepsFrom(from));
		skilling.setExcused(true);
		for (var spot : spots)
		{
			if (follower.stayAt(spot))
			{
				doing = what;
				follower.setStayFaceTile(at);
				arriveAt = client.getTickCount() + from.distanceTo(spot) + 2;
				leaveAt = 0;
				return true;
			}
		}
		skilling.setExcused(false);
		return false;
	}

	// ------------------------------------------------------------ the news

	/**
	 * Something worth a reaction: a drop, a first-ever item. The tier says
	 * how much of one. Big news with a tile is walked over to and written
	 * up on the spot, then a look up at the player and a nod - the scribe's
	 * clap; in character, a great thing is written down, not cheered.
	 * Medium news gets the notes out where it stands, facing the thing;
	 * small news a glance. Each through the ledger, so the notes cannot come
	 * out for every drop in a good hour: once they are spent the tier below
	 * stands in.
	 *
	 * @param at where the thing is, or null for something in the bag, which
	 * is reacted to facing the player
	 * @return what the body did, or null for nothing
	 */
	String noteworthy(Tier tier, WorldPoint at)
	{
		if (tier == null)
			return null;
		var here = FollowerEntity.playerTile(client);
		if (here == null || !follower.isSpawned())
			return null;
		var from = follower.getWorldLocation();
		boolean reachable = at != null && from != null && at.getPlane() == from.getPlane()
			&& at.distanceTo(from) <= 12 /* LOOT_REACH_TILES */;
		var facing = at == null ? here : at;

		if (tier == Tier.BIG && reachable && free()
			&& gestures.may(Gesture.WALK_OVER) && gestures.may(Gesture.NOTES)
			&& goAndLook(at, 1, true, NOTES_ON_THE_SPOT_TICKS))
		{
			gestures.spent(Gesture.WALK_OVER);
			gestures.spent(Gesture.NOTES);
			return "the walk over to write it up";
		}
		String wrote = tier != Tier.SMALL ? writeUpInPlace(facing) : null;
		if (wrote != null)
			return wrote;
		if (gestures.may(Gesture.GLANCE))
		{
			gestures.spent(Gesture.GLANCE);
			follower.glanceAt(facing, 2400 /* GLANCE_MS */);
			return "a glance";
		}
		return null;
	}

	/**
	 * The notes out where it stands, facing the thing, a beat of writing,
	 * then the look up at the player with a nod. With the hands full (a
	 * borrowed tool) or the follower sat down for the long haul the scroll
	 * cannot come out, and it is the look and the nod on their own.
	 *
	 * @return what the body did, or null when the notes are not due
	 */
	String writeUpInPlace(WorldPoint facing)
	{
		if (!gestures.may(Gesture.NOTES))
			return null;
		gestures.spent(Gesture.NOTES);
		int now = client.getTickCount();
		boolean canWrite = flourish != null && doing == NOTHING && !skilling.isSitting()
			&& !feetTakenOrParked() && !inCombat.getAsBoolean()
			&& follower.isSettled();
		if (canWrite && flourish.start(ErrandController.QUILL_PROP, ErrandController.SCROLL_PROP,
			ErrandController.WRITE_SCROLL_POSE, NOTES_TICKS))
		{
			follower.glanceAt(facing, NOTES_TICKS * 600);
			lookUpAt = now + NOTES_TICKS - 1;
			return "the notes out where it stands";
		}
		skilling.gesture(new int[]{NOD}, FollowerEntity.playerTile(client));
		return "a nod";
	}

	/**
	 * The player opened the logout tab. The last thing on screen before a
	 * session ends is the thing that gets remembered, so it is a turn to
	 * face them and a wave - from the seat, the seat's way. Not twice in
	 * five minutes, for the player who keeps the tab open.
	 *
	 * @return whether it waved
	 */
	boolean farewell()
	{
		var here = FollowerEntity.playerTile(client);
		if (here == null || !follower.isSpawned() || feetTaken.getAsBoolean()
			|| inCombat.getAsBoolean()
			|| !gestures.may(Gesture.WAVE)
			)
			return false;
		gestures.spent(Gesture.WAVE);
		skilling.gesture(new int[]{WAVE}, here);
		return true;
	}

	/**
	 * Goes to look at something: a tile so many steps from it, the nearest
	 * the follower can reach, faced at it, held for a while, and the feet
	 * handed back. With {@code writes} the notes come out on arrival and
	 * the hold ends with a look up at the player and a nod.
	 *
	 * @return whether it set off; false leaves nothing changed
	 */
	@Override
	public boolean goAndLook(WorldPoint at, int steps, boolean writes, int holdTicks)
	{
		var from = follower.getWorldLocation();
		if (at == null || from == null || !free() || at.getPlane() != from.getPlane()
			|| !goBeside(at, Math.max(1, steps), LOOK))
			return false;
		lookWrites = writes;
		lookHoldTicks = Math.max(1, holdTicks);
		lookUpAt = 0;
		return true;
	}

	/** Whether the follower is off looking at something, or writing it up. */
	@Override
	public boolean isLooking()
	{
		return doing == LOOK;
	}

	// ------------------------------------------------------------------ tick

	/** Call once per game tick, on the client thread, after the seat's own tick. */
	void tick()
	{
		int now = client.getTickCount();
		var local = client.getLocalPlayer();
		var here = local == null ? null : local.getWorldLocation();
		if (here == null)
		{
			letGo(true);
			newcomers.clear();
			petHuntUntil = -1;
			return;
		}
		watchTheWind(now, here, local);
		watchForStrangers(now, local);
		if (owed != null && (now > owedUntil || free()))
			clapOwed(now);
		// The look up from an in-place write-up: the notes are still out,
		// and the nod goes to the player. Not once something has taken the
		// feet since: a scene being filmed puts the notes away as it starts,
		// and the nod would come into the take.
		if (lookUpAt > 0 && now >= lookUpAt && doing == NOTHING)
		{
			lookUpAt = 0;
			if (!feetTaken.getAsBoolean())
			{
				follower.glanceAt(here, LOOK_UP_MS);
				follower.playAnimation(NOD);
			}
		}
		// Every moment but the level and the wind is let go of when its stay
		// is; then the arrival, the look up from the notes, and the leaving.
		if (doing == NOTHING)
			return;
		if (interrupted() || (doing != LEVEL && doing != WIND && !follower.isStaying()))
			letGo(false);
		else if (doing == STRANGER)
		{
			// It may wander as it talks; the peer follows it.
			var at = stranger.getWorldLocation();
			if (at != null)
				follower.setStayFaceTile(at);
		}
		else if (arriveAt > 0 && now >= arriveAt)
		{
			arriveAt = 0;
			arrived(now);
		}
		else if (doing == LOOK && lookUpAt > 0 && now >= lookUpAt)
		{
			lookUpAt = 0;
			follower.glanceAt(here, LOOK_UP_MS);
			follower.playAnimation(NOD);
		}
		else if (leaveAt > 0 && now >= leaveAt)
			letGo(true);
	}

	/** There: what each moment does on arrival, and how long it holds. */
	void arrived(int now)
	{
		switch (doing)
		{
			case LEVEL:
				follower.playAnimations(beat);
				// BEAT_TICKS: Ticks the feet are kept for a clap, and for the chain (7.4 seconds).
				leaveAt = now + (beat.length > 1 ? 13 /* CELEBRATION_TICKS */ : 3 /* BEAT_TICKS */);
				break;
			case WIND:
				// Already facing them, from the front: a second of it.
				leaveAt = now + 2 /* LOOK_BACK_TICKS */;
				break;
			case PET:
				follower.playAnimation(BEND);
				leaveAt = now + 3 /* BEND_TICKS */;
				break;
			default:
				// A look: the notes out on arrival when it writes.
				if (lookWrites && flourish != null && flourish.start(
					ErrandController.QUILL_PROP, ErrandController.SCROLL_PROP,
					ErrandController.WRITE_SCROLL_POSE, lookHoldTicks))
					// The flourish planted it where it stands, which is the
					// spot; the look up comes a beat before the notes go away.
					lookUpAt = now + lookHoldTicks - 1;
				leaveAt = now + lookHoldTicks;
				break;
		}
	}

	/**
	 * Second wind: run going off with the energy under ten percent. The
	 * follower goes ahead, looks back at them for a second, and falls in
	 * behind again. Once per low stretch - re-armed when the energy is
	 * back over the line - and not twice in ten minutes.
	 */
	void watchTheWind(int now, WorldPoint here, Player local)
	{
		boolean running = client.getVarpValue(VarPlayerID.OPTION_RUN) == 1;
		int energy = client.getEnergy() / 100;
		boolean edge = wasRunning && !running;
		wasRunning = running;
		// LOW_ENERGY: Second wind: run going off under this much energy, once per stretch.
		if (energy >= 10 /* LOW_ENERGY */)
		{
			windArmed = true;
			return;
		}
		if (!edge || !windArmed || now < windCooldownUntil)
			return;
		windArmed = false;
		windCooldownUntil = now + WIND_COOLDOWN_TICKS;
		if (free() && follower.moveToFront(local))
		{
			skilling.setExcused(true);
			doing = WIND;
			arriveAt = now + walkTicks(here);
			leaveAt = 0;
		}
	}

	/**
	 * Who are you: a newcomer with no combat level that turns to the player
	 * within a few ticks of appearing came to talk to them. The follower
	 * faces it, takes one step off, and peers at it until it goes.
	 */
	void watchForStrangers(int now, Player local)
	{
		var it = newcomers.entrySet().iterator();
		while (it.hasNext())
		{
			var entry = it.next();
			if (now - entry.getValue() > STRANGER_WINDOW_TICKS)
				it.remove();
			else if (entry.getKey().getInteracting() == local)
			{
				var npc = entry.getKey();
				newcomers.clear();
				whoAreYou(npc);
				return;
			}
		}
	}

	void whoAreYou(NPC npc)
	{
		WorldPoint at = npc.getWorldLocation(),
			from = follower.getWorldLocation();
		if (at == null || from == null || !free() || at.getPlane() != from.getPlane())
			return;
		int dx = Integer.signum(from.getX() - at.getX()),
			dy = Integer.signum(from.getY() - at.getY());
		if (dx == 0 && dy == 0)
			dy = -1;
		var step = from.dx(dx).dy(dy);
		skilling.setExcused(true);
		if (!follower.stayAt(step))
			follower.stayHere();
		if (!follower.isStaying())
		{
			skilling.setExcused(false);
			return;
		}
		doing = STRANGER;
		stranger = npc;
		follower.setStayFaceTile(at);
		// PEER_WAIT_TICKS: How long the peer waits for the step towards the stranger to finish.
		follower.playWhenStill(PEER, 3 /* PEER_WAIT_TICKS */);
	}

	// ------------------------------------------------------------------- ends

	/** Logout, hop, shutdown: the feet let go of, nothing said. */
	void reset()
	{
		letGo(false);
		newcomers.clear();
		petHuntUntil = -1;
		lastFollower = null;
		wasRunning = false;
		windArmed = false;
		closeUntil = 0;
		lookUpAt = 0;
		gestures.reset();
	}

	/**
	 * Whether nothing has the feet, ours or anybody's, and the follower is
	 * there - and not sitting in at the seat, which no moment gets it up
	 * from: a level is clapped from the sit (the gesture stands it first),
	 * the others pass.
	 */
	boolean free()
	{
		return doing == NOTHING && !feetTakenOrParked() && !inCombat.getAsBoolean()
			&& follower.isSpawned() && !skilling.isSitting();
	}

	/** Somebody else took the feet mid-moment, or the follower went. */
	boolean interrupted()
	{
		return feetTakenOrParked() || inCombat.getAsBoolean() || !follower.isSpawned();
	}

	/** Whether the feet are not the moments' to take: somebody else has them, or the player. */
	boolean feetTakenOrParked()
	{
		return feetTaken.getAsBoolean() || parked.getAsBoolean();
	}

	/**
	 * The moment is over, however it ended.
	 *
	 * @param release whether to hand the feet back, when they are still ours;
	 * not when somebody else has just taken them
	 */
	void letGo(boolean release)
	{
		var was = doing;
		doing = NOTHING;
		beat = null;
		pet = null;
		stranger = null;
		arriveAt = 0;
		leaveAt = 0;
		if (was == LOOK)
		{
			lookUpAt = 0;
			if (flourish != null && flourish.isActive())
				flourish.abort();
		}
		if (was != NOTHING)
		{
			if (release && follower.isStaying() && !feetTakenOrParked())
				follower.resumeFollowing();
			skilling.setExcused(false);
		}
	}

	/** Ticks for the follower to reach a tile by the player, and a beat to settle. */
	int walkTicks(WorldPoint to)
	{
		var from = follower.getWorldLocation();
		return (from == null ? 3 : from.distanceTo(to)) + 2;
	}
}

package com.follower;

import java.util.*;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.*;
import java.util.function.Consumer;
import java.util.function.Supplier;
import net.runelite.api.*;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import lombok.RequiredArgsConstructor;
import java.util.Map.Entry;

/**
 * What the follower notices that the player has not: the drop they walked
 * away from, the nest under the tree, an impling, a star in the ground, the
 * signpost they are standing next to. It goes and looks, and the rules get
 * one line about it.
 *
 * <p>Being useful without cheating. Naughty Dog's rule for Ellie's callouts
 * is the whole design: when she called out an enemy the player could not
 * see, it reflected badly on her, so a callout is only ever made about a
 * thing that is there for the player to see. Everything here is checked to
 * still be there, and close enough to be on screen, on the tick the follower
 * sets off - and if it is gone by the time the follower arrives, the look is
 * simply over.
 *
 * <p>Each kind keeps its own cooldown and each thing is noticed once, so a
 * pile of drops in a good hour is one remark, not a commentary. The walk
 * itself belongs to the moments, which own the feet for it.
 */
class Noticing
{
	/** What was noticed; {@code key}, the name in lower case, is what the rules match on. */
	@RequiredArgsConstructor
	enum Kind
	{
		/** A drop of the player's, worth having, that they walked away from. */
		VALUABLE(150),
		/** A bird's nest on the ground. */
		NEST(100),
		/** An impling within reach. */
		IMPLING(300),
		/** A crashed star. */
		STAR(1500),
		/** A signpost, a statue, a plaque the player stopped beside. */
		LANDMARK(400);

		final String key = name().toLowerCase(Locale.ROOT);
		final int cooldownTicks;
	}

	/** The walk over, and whether it is still under way. Implemented by the moments. */
	interface Looker
	{
		boolean goAndLook(WorldPoint at, int steps, boolean writes, int holdTicks);

		boolean isLooking();
	}

	/** The player is "walking away" from a drop once this far from it. */
	static final int WALKED_AWAY_TILES = 5;

	/** Nothing further off than this is on the player's screen to be seen. */
	static final int VISIBLE_TILES = 10;

	/** Ticks a drop lies before it counts as left, so looting is not interrupted. */
	static final int LEFT_AFTER_TICKS = 3;

	/** How long the player stands beside a landmark before it is read. */
	static final int LANDMARK_AFTER_IDLE_TICKS = 15,
		LANDMARK_WITHIN = 2;

	/** The scans that walk lists run this often. */
	static final int SCAN_EVERY_TICKS = 5;

	/**
	 * The things the scribe stops to read when the player stops beside one.
	 * Game objects only, since that is what the scan looks at: the game's
	 * "Noticeboard" and "Portrait" are wall decorations, and it has no
	 * sundial, so none of those are here.
	 */
	static final String[] LANDMARKS = {
		"Signpost", "Notice board", "Statue", "Painting", "Plaque", "Monument",
		"Memorial", "Map",
	};

	/** A drop lying on the ground that might be worth a look. */
	@RequiredArgsConstructor
	static class Drop
	{
		final int id;
		final String name;
		final long value;
		final int since;
		final boolean nest;
	}

	final Client client;
	final FollowerEntity follower;
	final FollowerConfig config;
	final Looker looker;
	final Consumer<TriggerEvent> events;
	/** Anything that owns the feet, or would make a walk wrong: a fight, thrall work. */
	final BooleanSupplier busy;
	final IntSupplier idleTicks;
	/** The landmarks within reach of the player, name and tile. */
	final Supplier<List<Entry<String, WorldPoint>>> landmarksNearby;

	final Map<WorldPoint, List<Drop>> drops = new HashMap<>();
	final Map<Kind, Integer> lastAt = new EnumMap<>(Kind.class);
	final Set<String> seen = new HashSet<>();
	final List<Entry<String, WorldPoint>> stars = new ArrayList<>();

	Noticing(Client client, FollowerEntity follower, FollowerConfig config, Looker looker,
		Consumer<TriggerEvent> events, BooleanSupplier busy, IntSupplier idleTicks,
		Supplier<List<Entry<String, WorldPoint>>> landmarksNearby)
	{
		this.client = client;
		this.follower = follower;
		this.config = config;
		this.looker = looker;
		this.events = events;
		this.busy = busy;
		this.idleTicks = idleTicks;
		this.landmarksNearby = landmarksNearby;
	}

	// ---------------------------------------------------------------- inputs

	/**
	 * A ground item appeared. Kept only when it is the player's own and
	 * worth having, or a nest; everything else is somebody else's business.
	 *
	 * @param value the stack's worth in gp, already priced by the caller
	 */
	void itemSpawned(TileItem item, WorldPoint tile, String name, long value)
	{
		if (item == null || tile == null || name == null)
			return;
		boolean nest = name.toLowerCase(Locale.ROOT).startsWith("bird nest");
		boolean mine = item.getOwnership() == TileItem.OWNERSHIP_SELF
			|| item.getOwnership() == TileItem.OWNERSHIP_GROUP;
		// VALUABLE_GP: A drop is worth going back for from this much.
		if (!nest && !(mine && value >= 20_000 /* VALUABLE_GP */))
			return;
		drops.computeIfAbsent(tile, t -> new ArrayList<>())
			.add(new Drop(item.getId(), name, value, client.getTickCount(), nest));
	}

	/** A ground item went: picked up, or despawned. Either way, not there to look at. */
	void itemDespawned(TileItem item, WorldPoint tile)
	{
		if (item == null || tile == null)
			return;
		var here = drops.get(tile);
		if (here == null)
			return;
		here.removeIf(drop -> drop.id == item.getId());
		if (here.isEmpty())
			drops.remove(tile);
	}

	/** Scenery appeared, by name. The one the follower cares about is a star. */
	void objectSpawned(String name, WorldPoint tile)
	{
		if (name != null && tile != null && name.toLowerCase(Locale.ROOT).contains("crashed star"))
			stars.add(new java.util.AbstractMap.SimpleImmutableEntry<>(name, tile));
	}

	void objectDespawned(String name, WorldPoint tile)
	{
		if (tile != null)
			stars.removeIf(star -> star.getValue().equals(tile));
	}

	// ------------------------------------------------------------------ tick

	/** Call once per game tick, on the client thread, after the moments. */
	void tick()
	{
		if (!config.noticesThings())
		{
			drops.clear();
			stars.clear();
			return;
		}
		int now = client.getTickCount();
		var local = client.getLocalPlayer();
		WorldPoint here = local == null ? null : local.getWorldLocation(),
			from = follower.getWorldLocation();
		if (here == null || from == null || !follower.isSpawned() || looker.isLooking()
			|| busy.getAsBoolean())
			return;
		if (noticeADrop(now, here, from)
			|| (now % SCAN_EVERY_TICKS == 0
				&& (noticeAnImpling(now, local, here, from) || noticeAStar(now, from)
					|| noticeALandmark(now, here, from))))
			return;
	}

	boolean off(Kind kind, int now)
	{
		var last = lastAt.get(kind);
		return last == null || now - last >= kind.cooldownTicks;
	}

	boolean look(Kind kind, String what, WorldPoint at, WorldPoint from, int now,
		int steps, boolean writes, int holdTicks)
	{
		String key = kind.key + ":" + at.getX() + "," + at.getY() + ":" + what;
		// Another floor is infinitely far, as distanceTo has it.
		if (seen.contains(key) || at.distanceTo(from) > VISIBLE_TILES)
			return false;
		if (!looker.goAndLook(at, steps, writes, holdTicks))
			return false;
		seen.add(key);
		lastAt.put(kind, now);
		events.accept(TriggerEvent.noticed(kind.key, what));
		return true;
	}

	/** The player's own drop, worth having, that they have walked away from. */
	boolean noticeADrop(int now, WorldPoint here, WorldPoint from)
	{
		var it = drops.entrySet().iterator();
		while (it.hasNext())
		{
			var entry = it.next();
			var tile = entry.getKey();
			// Another floor is infinitely far, as distanceTo has it.
			if (tile.distanceTo(here) > 40)
			{
				// Out of the picture; forgotten with the rest of the scene.
				it.remove();
				continue;
			}
			if (tile.distanceTo(here) < WALKED_AWAY_TILES)
				continue;
			for (var drop : entry.getValue())
			{
				if (now - drop.since < LEFT_AFTER_TICKS)
					continue;
				var kind = drop.nest ? Kind.NEST : Kind.VALUABLE;
				if (off(kind, now) && look(kind, drop.name, tile, from, now, 1, false, 4))
					return true;
			}
		}
		return false;
	}

	/** An impling near enough to be seen, that the player is not already on. */
	boolean noticeAnImpling(int now, Player local, WorldPoint here, WorldPoint from)
	{
		if (!off(Kind.IMPLING, now))
			return false;
		var view = client.getTopLevelWorldView();
		if (view == null)
			return false;
		for (var npc : view.npcs())
		{
			String name = npc == null ? null : npc.getName();
			var at = npc == null ? null : npc.getWorldLocation();
			if (name == null || at == null || !name.toLowerCase(Locale.ROOT).contains("impling")
				|| local.getInteracting() == npc || at.distanceTo(here) > VISIBLE_TILES)
				continue;
			if (look(Kind.IMPLING, name, at, from, now, 2, false, 3))
				return true;
		}
		return false;
	}

	/** A crashed star: walked over to and written up, since it is a date worth having. */
	boolean noticeAStar(int now, WorldPoint from)
	{
		if (!off(Kind.STAR, now))
			return false;
		for (var star : stars)
		{
			if (look(Kind.STAR, star.getKey(), star.getValue(), from, now, 2, true, 8))
				return true;
		}
		return false;
	}

	/**
	 * The player has stood beside a signpost, a statue, a plaque for a while:
	 * the scribe goes and reads it, notes out. Elizabeth's points of
	 * interest, driven by where the player stops rather than by a roll.
	 */
	boolean noticeALandmark(int now, WorldPoint here, WorldPoint from)
	{
		if (!off(Kind.LANDMARK, now)
			|| idleTicks.getAsInt() < LANDMARK_AFTER_IDLE_TICKS)
			return false;
		var found = landmarksNearby.get();
		if (found == null)
			return false;
		for (var landmark : found)
		{
			var at = landmark.getValue();
			if (at != null && at.distanceTo(here) <= LANDMARK_WITHIN
				&& look(Kind.LANDMARK, landmark.getKey(), at, from, now, 1, true, 8))
				return true;
		}
		return false;
	}

	/** Whether the name is one of the landmarks the scribe reads. */
	static boolean isLandmark(String name)
	{
		return name != null && java.util.Arrays.stream(LANDMARKS).anyMatch(name::equalsIgnoreCase);
	}

	/** Logout, hop: the scene is gone, and so is everything noticed in it. */
	void reset()
	{
		drops.clear();
		stars.clear();
		seen.clear();
		lastAt.clear();
	}
}

package com.follower;

import java.util.Arrays;
import java.util.stream.Collectors;
import lombok.*;
import net.runelite.api.PlayerComposition;
import net.runelite.api.kit.KitType;
import static net.runelite.api.kit.KitType.*;

/**
 * The follower's appearance, stored in the same encoding the game uses for
 * {@link PlayerComposition#getEquipmentIds()}:
 *
 * <pre>
 *   0                     empty slot
 *   {@value #KIT_OFFSET} + kitId    a body kit (torso, arms, hair, ...)
 *   {@value #ITEM_OFFSET} + itemId  an equipped item
 * </pre>
 *
 * Slot order is {@link KitType#getIndex()}: HEAD, CAPE, AMULET, WEAPON, TORSO,
 * SHIELD, ARMS, LEGS, HAIR, HANDS, BOOTS, JAW.
 *
 * <p>Two outfits are equal when every field is: a prop shows where the same
 * item worn might be hidden, so it is another model. The fields are compared
 * as they are, not through getColors' copy.
 */
@EqualsAndHashCode(doNotUseGetters = true)
final class Outfit
{
	/**
	 * Internal encoding offsets, spaced so the kit and item ranges cannot collide.
	 * The game encoding is produced and consumed only at the boundary, in
	 * {@link #toGameEquipmentIds()} and {@link #from(PlayerComposition)}.
	 */
	static final int KIT_OFFSET = 1 << 20,
		ITEM_OFFSET = 1 << 21,
		SLOTS = 12;

	/**
	 * The game's own offsets, used only when talking to PlayerComposition: a slot
	 * holds {@code 0} for empty, {@code 256 + kitId} for a kit, and
	 * {@code 2048 + itemId} for an item.
	 *
	 * <p>The item offset is 2048, not 512. That leaves kit ids room to run up to
	 * 1791, which they need - hair and jaw kits are past 300. With 512 here, kit 305
	 * encoded to 561, which reads back as item 49, and every kit above 255 was
	 * silently corrupted in both directions: live compositions decoded into
	 * nonexistent items, and the capture path swapped garbage into the player.
	 */
	static final int GAME_KIT_OFFSET = PlayerComposition.KIT_OFFSET,
		GAME_ITEM_OFFSET = PlayerComposition.ITEM_OFFSET;

	/**
	 * Default identikit ids, used to fill body slots the outfit leaves empty so
	 * the follower isn't a floating head. These are the standard character
	 * creation kits; if your dump shows different ids, adjust here.
	 */
	static final int[][] DEFAULT_KITS_MALE = {
		{HAIR.getIndex(), 0},
		// The jaw kit is facial geometry, not merely a beard - without one the head
		// renders incomplete, so both genders always get a default.
		{JAW.getIndex(), 10},
		{TORSO.getIndex(), 18},
		{ARMS.getIndex(), 26},
		{HANDS.getIndex(), 33},
		{LEGS.getIndex(), 36},
		{BOOTS.getIndex(), 42},
	};

	static final int[][] DEFAULT_KITS_FEMALE = {
		{HAIR.getIndex(), 45},
		// Female jaw kits are 292-306 with their own distinct models. They only ever
		// looked broken because ids above 255 overflowed the old slot encoding.
		{JAW.getIndex(), 292},
		{TORSO.getIndex(), 56},
		{ARMS.getIndex(), 61},
		{HANDS.getIndex(), 67},
		{LEGS.getIndex(), 70},
		{BOOTS.getIndex(), 79},
	};

	final int[] equipment = new int[SLOTS],
		colors = new int[5];
	@Getter
	int gender;

	/**
	 * The slots that hold an animation's own hand props, a bit per slot index.
	 * The game lays an animation's hand items over the gear once the gear has
	 * settled what it covers, so nothing hides them and they hide nothing.
	 */
	int props;

	Outfit()
	{
	}

	Outfit(Outfit other)
	{
		System.arraycopy(other.equipment, 0, equipment, 0, SLOTS);
		System.arraycopy(other.colors, 0, colors, 0, colors.length);
		gender = other.gender;
		props = other.props;
	}

	static Outfit from(PlayerComposition composition)
	{
		var outfit = new Outfit();
		if (composition == null)
			return outfit;

		int[] ids = composition.getEquipmentIds();
		if (ids != null)
		{
			for (int i = 0; i < Math.min(ids.length, SLOTS); i++)
			{
				int raw = ids[i];
				if (raw >= GAME_ITEM_OFFSET)
					outfit.equipment[i] = ITEM_OFFSET + (raw - GAME_ITEM_OFFSET);
				else if (raw >= GAME_KIT_OFFSET)
					outfit.equipment[i] = KIT_OFFSET + (raw - GAME_KIT_OFFSET);
			}
		}
		outfit.setColors(composition.getColors());
		outfit.setGender(composition.getGender());
		return outfit;
	}

	int getRaw(KitType slot)
	{
		return equipment[slot.getIndex()];
	}

	void setItem(KitType slot, int itemId)
	{
		equipment[slot.getIndex()] = itemId <= 0 ? 0 : ITEM_OFFSET + itemId;
	}

	void setKit(KitType slot, int kitId)
	{
		equipment[slot.getIndex()] = kitId < 0 ? 0 : KIT_OFFSET + kitId;
	}

	void clear(KitType slot)
	{
		equipment[slot.getIndex()] = 0;
	}

	/**
	 * An animation's hand prop in a slot, drawn as the game draws one: over the
	 * gear, whatever the gear covers, and covering nothing itself.
	 */
	void setProp(KitType slot, int itemId)
	{
		setItem(slot, itemId);
		props |= 1 << slot.getIndex();
	}

	/** Whether the slot holds an animation's hand prop. */
	boolean isProp(KitType slot)
	{
		return (props & 1 << slot.getIndex()) != 0;
	}

	boolean isItem(KitType slot)
	{
		return equipment[slot.getIndex()] >= ITEM_OFFSET;
	}

	boolean isKit(KitType slot)
	{
		int v = equipment[slot.getIndex()];
		return v >= KIT_OFFSET && v < ITEM_OFFSET;
	}

	int itemId(KitType slot)
	{
		return equipment[slot.getIndex()] - ITEM_OFFSET;
	}

	int kitId(KitType slot)
	{
		return equipment[slot.getIndex()] - KIT_OFFSET;
	}

	void setGender(int gender)
	{
		this.gender = gender == 1 ? 1 : 0;
	}

	int[] getColors()
	{
		return colors.clone();
	}

	void setColors(int[] source)
	{
		if (source != null)
			System.arraycopy(source, 0, colors, 0, Math.min(source.length, colors.length));
	}

	/**
	 * Returns a copy with empty body slots filled by default kits. Item slots and
	 * already-populated kit slots are untouched, so gear always wins.
	 */
	Outfit withDefaultBody()
	{
		var filled = new Outfit(this);

		// Every body kit is filled here, including ones the gear will cover. Which of
		// them actually render is decided at compose time from each item's wearPos
		// data, the same way the game does it - a platebody hides the arms but a
		// chainbody does not, and only the item itself knows which it is. Deciding
		// that here, by slot type alone, stripped the arms under every torso item.
		for (int[] pair : (gender == 1 ? DEFAULT_KITS_FEMALE : DEFAULT_KITS_MALE))
		{
			if (pair[1] >= 0 && filled.equipment[pair[0]] == 0)
				filled.equipment[pair[0]] = KIT_OFFSET + pair[1];
		}
		return filled;
	}

	boolean isEmpty()
	{
		return Arrays.stream(equipment).allMatch(v -> v == 0);
	}

	@Override
	public String toString()
	{
		var sb = new StringBuilder();
		for (var slot : KitType.values())
		{
			int v = getRaw(slot);
			if (v == 0)
				continue;
			if (sb.length() > 0)
				sb.append(',');
			sb.append(slot.name()).append('=')
				.append(v >= ITEM_OFFSET ? "item:" + (v - ITEM_OFFSET) : "kit:" + (v - KIT_OFFSET));
		}

		if (gender == 1)
			sb.append(sb.length() > 0 ? "," : "").append("gender=female");

		// Body-colour indices into the game's palette tables; the parser already
		// reads this key, but until 2026-08-02 nothing wrote it, so panel-chosen
		// indices silently vanished on every save.
		if (Arrays.stream(colors).anyMatch(c -> c != 0))
			sb.append(sb.length() > 0 ? "," : "").append("colors=")
				.append(Arrays.stream(colors).mapToObj(String::valueOf).collect(Collectors.joining("/")));

		return sb.toString();
	}
}

package com.follower;

import java.util.*;
import java.util.List;
import net.runelite.api.kit.KitType;

/**
 * Parses the human-editable outfit string from the config panel.
 *
 * <p>Format: comma or newline separated {@code SLOT=item:ID} / {@code SLOT=kit:ID}
 * entries, plus optional {@code gender=male|female} and {@code colors=a/b/c/d/e}.
 * Slot names are {@link KitType} names, case-insensitive. Lines starting with
 * {@code #} are comments.
 *
 * <pre>
 *   # Bandos melee
 *   gender=male
 *   HEAD=item:11826, TORSO=item:11832, LEGS=item:11834
 *   WEAPON=item:4151, SHIELD=item:8850, CAPE=item:6570
 *   HANDS=item:7462, BOOTS=item:11840, AMULET=item:6585
 * </pre>
 */
class OutfitParser
{

	static Outfit parse(String text, List<String> errorsOut)
	{
		var outfit = new Outfit();
		if (text == null || text.trim().isEmpty())
			return outfit;

		for (String rawToken : text.split("[,\\r\\n]+"))
		{
			String token = rawToken.trim();
			if (token.isEmpty() || token.startsWith("#") || token.startsWith("//"))
				continue;

			int eq = token.indexOf('=');
			if (eq < 0)
			{
				addError(errorsOut, "Missing '=' in: " + token);
				continue;
			}

			String key = token.substring(0, eq).trim(),
				value = token.substring(eq + 1).trim();

			if (key.equalsIgnoreCase("gender"))
			{
				outfit.setGender(value.toLowerCase().startsWith("f") || value.equals("1") ? 1 : 0);
				continue;
			}

			if (key.equalsIgnoreCase("colors") || key.equalsIgnoreCase("colours"))
			{
				parseColors(value, outfit, errorsOut);
				continue;
			}

			var slot = slotByName(key);
			if (slot == null)
			{
				addError(errorsOut, "Unknown slot '" + key + "'");
				continue;
			}

			if (value.equalsIgnoreCase("none") || value.equals("-1") || value.equals("0"))
			{
				outfit.clear(slot);
				continue;
			}

			int colon = value.indexOf(':');
			String kind = colon < 0 ? "item" : value.substring(0, colon).trim(),
				idText = colon < 0 ? value : value.substring(colon + 1).trim();

			int id;
			try
			{
				id = Integer.parseInt(idText);
			}
			catch (NumberFormatException e)
			{
				addError(errorsOut, "'" + idText + "' is not a number (slot " + key + ")");
				continue;
			}

			if (kind.equalsIgnoreCase("kit"))
				outfit.setKit(slot, id);
			else if (kind.equalsIgnoreCase("item"))
				outfit.setItem(slot, id);
			else
				addError(errorsOut, "Expected 'item' or 'kit', got '" + kind + "'");
		}

		return outfit;
	}

	static Outfit parse(String text)
	{
		return parse(text, new ArrayList<>());
	}

	static void parseColors(String value, Outfit outfit, List<String> errorsOut)
	{
		var parts = value.split("[/ ]+");
		int[] colors = new int[5];
		for (int i = 0; i < Math.min(parts.length, 5); i++)
		{
			try
			{
				colors[i] = Integer.parseInt(parts[i].trim());
			}
			catch (NumberFormatException e)
			{
				addError(errorsOut, "Bad colour index '" + parts[i] + "'");
			}
		}
		outfit.setColors(colors);
	}

	static KitType slotByName(String name)
	{
		for (var slot : KitType.values())
		{
			if (slot.name().equalsIgnoreCase(name))
				return slot;
		}
		return null;
	}

	static void addError(List<String> errors, String message)
	{
		if (errors != null)
			errors.add(message);
	}
}

package com.follower;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.List;
import java.util.Map;
import javax.inject.*;
import lombok.extern.slf4j.Slf4j;
import lombok.RequiredArgsConstructor;
import java.util.function.Consumer;

/**
 * Named outfit profiles: profile name -> the same outfit string the config
 * panel edits. Kept in each RuneLite profile's own settings, saved on every
 * mutation, insertion order preserved so the dropdown lists profiles in the
 * order they were created. The outfit-profiles.json earlier versions shared
 * between profiles is only read, as where a profile's list starts.
 *
 * <p>Synchronized: the panel's New profile and Delete run on the event
 * thread, the autosave after an outfit edit on the client thread (QA3).
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
class OutfitProfileStore
{
	static final String FILE_NAME = "outfit-profiles.json";

	final Gson gson;

	/** Where the list is kept: the RuneLite profile's own setting. */
	Consumer<String> writer = json -> { };
	Map<String, String> profiles = new LinkedHashMap<>();

	/** The bare body every install starts from, and the fallback selection. */
	static final String DEFAULT_PROFILE = "Default follower";

	/**
	 * The three combat-style looks, which double as the thrall-mode outfits,
	 * plus the bare body. These are complete characters - gear, body kits,
	 * body type and colours - so a first install has three finished thralls to
	 * summon rather than three sets of armour on a default mannequin.
	 */
	static final Map<String, String> DEFAULTS = new LinkedHashMap<>();
	static
	{
		// An empty outfit is the plain default body with no clothing.
		DEFAULTS.put(DEFAULT_PROFILE, "");
		for (var row : Resources.rows("outfits.tsv"))
			DEFAULTS.put(row[0], row[1]);
	}

	/** Without a RuneLite profile to keep them in: the shared list and the defaults, nothing written. */
	void load(Path dataDir)
	{
		load(dataDir, null, null, null, null);
	}

	/**
	 * Loads this RuneLite profile's own outfit profiles.
	 *
	 * <p>Each RuneLite profile keeps its list in its own settings,
	 * {@code stored}, written back through {@code writer}. Up to this version
	 * one list in outfit-profiles.json was shared by every profile, every
	 * outfit change saved into the selected name, and two profiles on the same
	 * name wrote over each other's outfit. A profile the old version ran, with
	 * no list of its own yet, starts from that shared file as it stands, which
	 * from then on is only read, and the entry it has selected takes the outfit
	 * it is wearing: another profile may already have written over the shared
	 * one. Any other profile with no list starts from the defaults.
	 */
	synchronized void load(Path dataDir, String stored, String active, String worn,
		Consumer<String> writer)
	{
		this.writer = writer == null ? json -> { } : writer;
		profiles = new LinkedHashMap<>();
		Map<String, String> own = stored == null || stored.trim().isEmpty() ? null : parse(stored, "the profile's own list");
		boolean first = own == null;
		// Only a profile the old version ran has the shared list to start
		// from: that version always recorded the outfit it had selected. One
		// reset to defaults, or made since, starts from the defaults rather
		// than from the shared list as it stood on the day of the upgrade.
		boolean ranTheOldVersion = active != null && !active.trim().isEmpty();
		Map<String, String> read = !first ? own : ranTheOldVersion ? readShared(dataDir) : null;
		boolean fromShared = first && read != null;
		if (read != null)
			profiles = read;
		boolean changed = first;
		if (first && active != null && worn != null && profiles.containsKey(active.trim()))
			profiles.put(active.trim(), worn);

		// The style profiles double as the thrall-mode outfits, so a missing
		// one is restored on load. Same-name edits are kept; only absence heals.
		for (var entry : DEFAULTS.entrySet())
		{
			if (!profiles.containsKey(entry.getKey()))
			{
				profiles.put(entry.getKey(), entry.getValue());
				changed = true;
			}
		}
		if (changed)
			save();
	}

	/** The list every profile shared before this version, or null. */
	Map<String, String> readShared(Path dataDir)
	{
		var file = dataDir == null ? null : dataDir.resolve(FILE_NAME);
		if (file == null || !Files.isRegularFile(file))
			return null;
		try
		{
			return parse(new String(Files.readAllBytes(file), StandardCharsets.UTF_8), file.toString());
		}
		catch (IOException e)
		{
			log.warn("Could not read {}", file, e);
			return null;
		}
	}

	Map<String, String> parse(String json, String what)
	{
		try
		{
			return gson.fromJson(json, new TypeToken<LinkedHashMap<String, String>>() { }.getType());
		}
		catch (RuntimeException e)
		{
			log.warn("Could not read {}", what, e);
			return null;
		}
	}

	synchronized List<String> names()
	{
		return new ArrayList<>(profiles.keySet());
	}

	/**
	 * Whether this profile is one of the seeded combat-style looks. Those
	 * double as the thrall-mode outfits, which are configured BY NAME, so
	 * deleting one would silently break thrall dress; they stay editable.
	 */
	boolean isProtected(String name)
	{
		return name != null && DEFAULTS.containsKey(name.trim());
	}

	/**
	 * The first profile the user made themselves, or {@link #DEFAULT_PROFILE}
	 * when they have not made any - what a fresh session should be wearing.
	 */
	synchronized String firstUserProfile()
	{
		for (String name : profiles.keySet())
		{
			if (!DEFAULTS.containsKey(name))
				return name;
		}
		return DEFAULT_PROFILE;
	}

	/** The stored outfit string, or null when no profile has that name. */
	synchronized String get(String name)
	{
		return name == null ? null : profiles.get(name.trim());
	}

	synchronized void put(String name, String outfit)
	{
		profiles.put(name.trim(), outfit == null ? "" : outfit);
		save();
	}

	/** Returns true when a profile existed and was removed. */
	synchronized boolean remove(String name)
	{
		boolean removed = name != null && profiles.remove(name.trim()) != null;
		if (removed)
			save();
		return removed;
	}

	void save()
	{
		writer.accept(gson.newBuilder().disableHtmlEscaping().create().toJson(profiles));
	}
}

package com.follower;

import com.google.gson.*;
import java.awt.*;
import java.awt.Color;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.List;
import java.util.Set;
import javax.swing.*;
import javax.swing.text.JTextComponent;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.*;
import java.util.function.IntSupplier;

/**
 * The message editor: one window for every category of message rule in
 * phrases.json, picked from a dropdown, with what triggers each rule, an
 * on/off tick and its message lines (one per line) free to edit. Save writes
 * straight back to phrases.json, which the plugin hot-reloads within a second
 * — no restart, no rebuild.
 *
 * <p>One window rather than seven buttons because the split by rule group is
 * an implementation detail; a user looking for "the thing it says about
 * bosses" should not have to know which of nine doors it lives behind.
 *
 * <p>In the structural category (Locations) each rule's region ids are
 * editable too, rules can be deleted outright and new ones added — the
 * "Use my current location" button fills the id in for you.
 *
 * <p>Deliberately a plain window rather than a sidebar panel: message lines
 * are sentences, and editing sentences in a 225px column is misery.
 */
@Slf4j
class PhrasesDialog extends EditorDialog
{
	/**
	 * One entry of the category dropdown: a set of rule groups shown under one
	 * user-facing name. Usually one group, but related groups can be shown
	 * together - idle chatter belongs with the status lines as far as anyone
	 * looking for "things the follower says about itself" is concerned, even
	 * though the engine keeps them separate so they can be toggled apart.
	 */
	static class Category
	{
		final String name;
		final List<String> groups;
		final String hint;
		final boolean structural;

		/**
		 * @param groups one or more rule groups, comma separated; the first
		 * receives any rules added from this window
		 */
		Category(String name, String groups, String hint, boolean structural)
		{
			this.name = name;
			this.groups = java.util.Arrays.asList(groups.split("\\s*,\\s*"));
			this.hint = hint;
			this.structural = structural;
		}
	}

	/** The categories, in the dropdown's order, from message-categories.tsv. */
	static List<Category> categories()
	{
		List<Category> categories = new ArrayList<>();
		for (var row : Resources.rows("message-categories.tsv"))
			categories.add(new Category(row[0], row[1], row[3], Boolean.parseBoolean(row[2])));
		return categories;
	}

	/** Where "Use my current location" gets its region id; may be null. */
	final IntSupplier currentRegion;

	Category category;

	/** What every category has in common; each category adds one line of its own. */
	static final String HOW_TO = Resources.text("messagesHowTo");

	final JComboBox<String> categoryPicker = new JComboBox<>();
	final JLabel hint = Ui.label("", ColorScheme.LIGHT_GRAY_COLOR);

	/** Hides rows that do not mention the text, within the current category. */
	final JTextField find = new JTextField(14);
	final JButton addLocation = new JButton("Add location");
	/** The loaded count, put back once Find matches something again. */
	String loadedStatus = " ";
	boolean findMatchedNothing;
	final List<Row> rows = new ArrayList<>(),
		added = new ArrayList<>();
	final Set<String> deleted = new HashSet<>();

	/** True while the category picker is being set programmatically. */
	boolean switching;

	static class Row
	{
		String id;
		final JTextField name;
		final JCheckBox enabled;
		final JTextField regions;
		final JTextArea say;
		JPanel panel;

		/** The rule's title and note, so Find can look through them. */
		String title = "",
			note = "";

		Row(String id, JTextField name, JCheckBox enabled, JTextField regions, JTextArea say)
		{
			this.id = id;
			this.name = name;
			this.enabled = enabled;
			this.regions = regions;
			this.say = say;
		}
	}

	PhrasesDialog(Gson gson, Path file, List<Category> categories,
		IntSupplier currentRegion)
	{
		super("Follower Buddy - Messages", gson, file, new Ui.WidthTrackingPanel(), 170);
		this.currentRegion = currentRegion;
		this.category = categories.get(0);

		for (var c : categories)
			categoryPicker.addItem(c.name);
		categoryPicker.addActionListener(e ->
		{
			if (switching || categoryPicker.getSelectedIndex() < 0)
				return;
			if (!confirmDirty())
			{
				// Cancelled: put the picker back without re-entering this.
				switching = true;
				categoryPicker.setSelectedItem(category.name);
				switching = false;
				return;
			}
			category = categories.get(categoryPicker.getSelectedIndex());
			showCategory();
		});

		find.setToolTipText(Resources.text("findTip"));
		find.getDocument().addDocumentListener(Ui.onChange(this::applyFind));
		var pickerRow = Ui.panel(new BorderLayout(6, 0));
		pickerRow.add(categoryPicker, BorderLayout.CENTER);
		pickerRow.add(labelledField("Find:", find), BorderLayout.EAST);

		var top = Ui.panel(new BorderLayout(6, 6));
		top.add(pickerRow, BorderLayout.NORTH);
		top.add(hint, BorderLayout.CENTER);

		addLocation.setToolTipText("A new place for the follower to comment on");
		addLocation.addActionListener(e -> addBlankRow());
		// Only the structural category can add rules; showCategory() keeps the
		// button's visibility in step with the picked category.
		addLocation.setVisible(category.structural);
		buttons.add(addLocation);
		addReloadAndSave();

		layOut(top, 620, 640);
		setLocationRelativeTo(null);
	}

	/**
	 * The file as last read, by open(), Reload or a save, or null when it
	 * would not read. A switch of category lists from it: reading the whole
	 * file again each time held the event thread for most of half a second
	 * (qa5 #71).
	 */
	JsonObject loaded;

	@Override
	void refresh()
	{
		try
		{
			loaded = readFile();
		}
		catch (Exception e)
		{
			log.warn("Could not read {}", file, e);
			loaded = null;
		}
		showCategory();
	}

	void showCategory()
	{
		rows.clear();
		added.clear();
		deleted.clear();
		list.removeAll();

		if (loaded == null)
		{
			setStatus(Resources.text("messagesUnreadable"), true);
			Ui.relayout(list);
			return;
		}

		int count = 0;
		for (var element : loaded.getAsJsonArray("rules"))
		{
			var rule = element.getAsJsonObject();
			if (!category.groups.contains(optString(rule, "group")) || optString(rule, "id") == null)
				continue;
			list.add(buildRow(rule));
			count++;
		}

		hint.setText("<html><body style='width:440px'>" + HOW_TO + "<br>" + category.hint + "</body></html>");
		addLocation.setVisible(category.structural);
		loadedStatus = count + " rules loaded";
		findMatchedNothing = false;
		setStatus(loadedStatus, false);
		applyFind();
		Ui.relayout(list);
		dirty = false;
		// Every say area moves its caret as its text goes in, and each queues
		// a scroll to bring that caret into view, so the last of them decided
		// where the list opened. QA, 15 Oct: Messages opened near the bottom.
		// Queued behind them, this puts the list back at its top.
		javax.swing.SwingUtilities.invokeLater(() -> scroll.getViewport().setViewPosition(new java.awt.Point(0, 0)));
	}

	/**
	 * Shows only the rows that mention the Find text, in their title, id, note
	 * or lines. Rows stay in the rows list either way, so Save is unaffected;
	 * a row added from this window is always shown.
	 */
	void applyFind()
	{
		String wanted = find.getText().trim().toLowerCase(Locale.ROOT);
		boolean any = false;
		for (var row : rows)
		{
			boolean shown = wanted.isEmpty()
				|| row.title.toLowerCase(Locale.ROOT).contains(wanted)
				|| row.id.toLowerCase(Locale.ROOT).contains(wanted)
				|| row.note.toLowerCase(Locale.ROOT).contains(wanted)
				|| row.say.getText().toLowerCase(Locale.ROOT).contains(wanted);
			row.panel.setVisible(shown);
			any |= shown;
		}
		// With nothing shown the window said nothing, and the status still
		// counted what was loaded.
		if (!wanted.isEmpty() && !any)
		{
			setStatus("No rules here mention \"" + find.getText().trim() + "\".", false);
			findMatchedNothing = true;
		}
		else if (findMatchedNothing)
		{
			setStatus(loadedStatus, false);
			findMatchedNothing = false;
		}
		Ui.relayout(list);
	}

	JPanel buildRow(JsonObject rule)
	{
		String id = optString(rule, "id"),
			ruleTitle = titleOf(rule);

		var row = rowShell();

		var title = title(ruleTitle);
		// The id beside the title is what the settings' silence-by-name box
		// wants typed into it.
		var idLabel = Ui.label(id, ColorScheme.MEDIUM_GRAY_COLOR);
		// A long title or id is cut short with "..." rather than widening the
		// row: the list is as wide as the window, and the controls on the
		// right have to stay on it. QA2, 15 Oct: Quest NPCs and Locations
		// pushed On and Sounds past the edge. The id gives way first: the
		// title's end is what tells a callback from its plain rule (QA3).
		title.setMinimumSize(title.getPreferredSize());
		idLabel.setMinimumSize(new Dimension(0, idLabel.getPreferredSize().height));
		title.setToolTipText(ruleTitle + "  " + id);
		idLabel.setToolTipText(id);
		var titles = new JPanel();
		titles.setLayout(new BoxLayout(titles, BoxLayout.X_AXIS));
		titles.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 0));
		titles.setBackground(ColorScheme.DARK_GRAY_COLOR);
		titles.add(title);
		titles.add(javax.swing.Box.createHorizontalStrut(6));
		titles.add(idLabel);
		var controls = header(row, titles);

		var enabled = onTick(!rule.has("enabled") || rule.get("enabled").getAsBoolean());
		enabled.setToolTipText("Untick to silence just this rule");
		controls.add(enabled);
		if (category.structural)
		{
			var delete = new JButton("Delete");
			delete.setToolTipText("Remove this rule entirely on Save");
			delete.addActionListener(e ->
			{
				deleted.add(id);
				rows.removeIf(r -> id.equals(r.id));
				list.remove(row);
				Ui.relayout(list);
				setStatus("'" + ruleTitle + "' will be removed on Save", false);
				dirty = true;
			});
			controls.add(delete);
		}

		String shownNote = aboutOf(rule);
		if (shownNote != null && !shownNote.isEmpty())
		{
			var items = Ui.label(Ui.html(430, shownNote), ColorScheme.MEDIUM_GRAY_COLOR);
			items.setAlignmentX(LEFT_ALIGNMENT);
			items.setBorder(BorderFactory.createEmptyBorder(2, 0, 4, 0));
			row.add(items);
		}

		JTextField regionsField = null;
		if (category.structural)
		{
			var regions = regionsOf(rule);
			if (regions != null)
			{
				List<String> ids = new ArrayList<>();
				for (var r : regions)
					ids.add(r.getAsString());
				regionsField = new JTextField(String.join(", ", ids));
				regionsField.getDocument().addDocumentListener(dirtyMarker);
				row.add(labelledField("Regions:", regionsField));
			}
			else
			{
				var special = Ui.label(Resources.text("notAPlace"), ColorScheme.MEDIUM_GRAY_COLOR);
				special.setAlignmentX(LEFT_ALIGNMENT);
				row.add(special);
			}
		}

		var text = new StringBuilder();
		var say = rule.has("say") ? rule.getAsJsonArray("say") : new JsonArray();
		for (var line : say)
		{
			if (text.length() > 0)
				text.append('\n');
			text.append(line.getAsString());
		}
		var area = sayArea(text.toString(), Math.max(2, say.size()));
		area.getDocument().addDocumentListener(dirtyMarker);
		row.add(area);

		var r = new Row(id, null, enabled, regionsField, area);
		r.panel = row;
		r.title = ruleTitle;
		// Find looks through what is shown, not the hidden note.
		r.note = shownNote == null ? "" : shownNote;
		rows.add(r);
		return row;
	}

	void addBlankRow()
	{
		JPanel row = rowShell(),
			controls = header(row, title("New location"));
		var delete = new JButton("Delete");

		var name = new JTextField();
		name.getDocument().addDocumentListener(dirtyMarker);
		row.add(labelledField("Name:", name));
		var regions = new JTextField();
		regions.setToolTipText("Comma separated region ids");
		regions.getDocument().addDocumentListener(dirtyMarker);
		var regionsLine = labelledField("Regions:", regions);
		if (currentRegion != null)
		{
			// The first design taught the user a chat command in a tooltip and
			// had them carry the id back by hand. The plugin knows where you
			// are standing; the button just asks it.
			var here = new JButton("Use my current location");
			here.setToolTipText("Fill in the region you are standing in right now");
			here.addActionListener(e ->
			{
				int region = currentRegion.getAsInt();
				if (region <= 0)
				{
					setStatus(Resources.text("whereUnknown"), true);
					return;
				}
				String existing = regions.getText().trim();
				regions.setText(existing.isEmpty() ? String.valueOf(region)
					: existing + ", " + region);
			});
			regionsLine.add(here, BorderLayout.EAST);
		}
		row.add(regionsLine);
		var area = sayArea("", 3);
		area.getDocument().addDocumentListener(dirtyMarker);
		row.add(area);

		var enabled = onTick(true);
		controls.add(enabled);
		controls.add(delete);

		var r = new Row(null, name, enabled, regions, area);
		r.panel = row;
		added.add(r);
		dirty = true;
		delete.addActionListener(e ->
		{
			added.remove(r);
			list.remove(row);
			Ui.relayout(list);
		});

		list.add(row);
		Ui.relayout(list);
		name.requestFocusInWindow();
	}

	/**
	 * Applies the edits to a FRESH parse of the file, so hand edits made while
	 * the window sat open are kept rather than clobbered with stale contents.
	 *
	 * @return whether the file was written
	 */
	@Override
	boolean save()
	{
		try
		{
			var parsed = readFile();
			JsonArray rules = parsed.getAsJsonArray("rules"),
				kept = new JsonArray();
			List<String> warnings = new ArrayList<>();

			for (var element : rules)
			{
				var rule = element.getAsJsonObject();
				String id = optString(rule, "id");
				if (id != null && deleted.contains(id))
					continue;
				var row = rows.stream().filter(r -> r.id.equals(id)).findFirst().orElse(null);
				if (row != null)
					applyRow(rule, row, warnings);
				kept.add(rule);
			}

			Set<String> ids = new HashSet<>();
			for (var element : kept)
			{
				String id = optString(element.getAsJsonObject(), "id");
				if (id != null)
					ids.add(id);
			}
			for (var row : added)
			{
				var rule = buildAddedRule(row, ids, warnings);
				if (rule != null)
					kept.add(rule);
			}

			// Rules deleted here must STAY deleted across updates: the loader
			// merges newly bundled rules in by id at startup, and without a
			// record it would politely resurrect these on the next client.
			if (!deleted.isEmpty())
			{
				var removed = parsed.has("removed") && parsed.get("removed").isJsonArray()
					? parsed.getAsJsonArray("removed") : new JsonArray();
				Set<String> already = new HashSet<>();
				for (var element : removed)
				{
					if (element.isJsonPrimitive())
						already.add(element.getAsString());
				}
				for (String id : deleted)
				{
					if (!already.contains(id))
						removed.add(id);
				}
				parsed.add("removed", removed);
			}

			parsed.add("rules", kept);
			writeAtomically(gson.toJson(parsed) + "\n");

			if (warnings.isEmpty())
				setStatus("Saved - the follower picks it up within a second", false);
			else if (warnings.size() == 1)
				setStatus("Saved with a warning: " + warnings.get(0), true);
			else
			{
				// A status line clips past one warning; a list does not.
				setStatus("Saved with warnings", true);
				JOptionPane.showMessageDialog(this,
					"Saved, but:\n\n- " + String.join("\n- ", warnings),
					"Saved with warnings", JOptionPane.WARNING_MESSAGE);
			}
			refresh();
			return true;
		}
		catch (Exception e)
		{
			log.warn("Could not save {}", file, e);
			setStatus("Save failed: " + e.getMessage(), true);
			return false;
		}
	}

	void applyRow(JsonObject rule, Row row, List<String> warnings)
	{
		var say = parseSay(row.say.getText());

		// An emptied rule keeps its old lines but goes quiet: deleting all
		// text reads as "shut this one up", not "make the rule invalid".
		boolean empty = say.size() == 0;
		if (!empty)
			rule.add("say", say);
		if (row.enabled.isSelected() && !empty)
			rule.remove("enabled");
		else
			rule.addProperty("enabled", false);

		if (row.regions != null)
		{
			var regions = parseRegions(row.regions.getText(), warnings);
			var place = placeOf(rule);
			if (regions.size() > 0 && place != null)
				place.add("regions", regions);
			else
				warnings.add(row.title + " kept its old regions (none given)");
		}
	}

	JsonObject buildAddedRule(Row row, Set<String> existingIds, List<String> warnings)
	{
		String name = row.name.getText().trim();
		JsonArray regions = parseRegions(row.regions.getText(), warnings),
			say = parseSay(row.say.getText());
		if (name.isEmpty() || regions.size() == 0 || say.size() == 0)
		{
			warnings.add(Resources.text("newLocationIncomplete"));
			return null;
		}

		String base = "area-" + name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "-")
			.replaceAll("(^-|-$)", "");
		String id = base;
		for (int n = 2; existingIds.contains(id); n++)
			id = base + "-" + n;
		existingIds.add(id);

		var when = new JsonObject();
		when.addProperty("type", "inRegion");
		when.add("regions", regions);

		var rule = new JsonObject();
		rule.addProperty("id", id);
		rule.addProperty("note", name + ". Added from the editor.");
		rule.addProperty("group", category.groups.get(0));
		rule.addProperty("priority", 40);
		rule.addProperty("output", "overhead");
		rule.addProperty("delayTicks", 2);
		rule.addProperty("cooldownMs", 180000);
		rule.add("when", when);
		rule.add("say", say);
		if (!row.enabled.isSelected())
			rule.addProperty("enabled", false);
		return rule;
	}

	// ------------------------------------------------------------------ helpers

	/** A row's top line: {@code left} and, returned for filling, the controls on the right. */
	static JPanel header(JPanel row, JComponent left)
	{
		var header = Ui.panel(new BorderLayout());
		header.setAlignmentX(LEFT_ALIGNMENT);
		header.add(left, BorderLayout.CENTER);
		var controls = Ui.panel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
		header.add(controls, BorderLayout.EAST);
		row.add(header);
		return controls;
	}

	static JLabel title(String text)
	{
		var title = new JLabel(text);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		return title;
	}

	/** A rule's On tick; changing it marks the window dirty. */
	JCheckBox onTick(boolean on)
	{
		var enabled = new JCheckBox("On", on);
		enabled.setBackground(ColorScheme.DARK_GRAY_COLOR);
		enabled.addItemListener(e -> dirty = true);
		return enabled;
	}

	JPanel rowShell()
	{
		// Never taller than it needs: the list is a vertical box, which shares
		// any spare height out between rows that allow it, so a Find leaving
		// two rows pulled each one's title, controls and lines far apart.
		JPanel row = Ui.column(new JPanel()
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		});
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARKER_GRAY_COLOR),
			BorderFactory.createEmptyBorder(8, 0, 8, 8)));
		return row;
	}

	JPanel labelledField(String label, JTextField field)
	{
		var line = Ui.panel(new BorderLayout(6, 0));
		line.setAlignmentX(LEFT_ALIGNMENT);
		line.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		line.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		line.add(Ui.label(label, ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.WEST);
		line.add(editable(field), BorderLayout.CENTER);
		return line;
	}

	/** White game-font text on the darker grey, for the boxes a player types in. */
	static <T extends JTextComponent> T editable(T field)
	{
		field.setFont(FontManager.getRunescapeFont());
		field.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		field.setForeground(Color.WHITE);
		field.setCaretColor(Color.WHITE);
		return field;
	}

	JTextArea sayArea(String text, int rows)
	{
		var area = editable(new JTextArea(text, rows, 40));
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		area.setAlignmentX(LEFT_ALIGNMENT);
		return area;
	}

	static JsonArray parseSay(String text)
	{
		var say = new JsonArray();
		for (String line : text.split("\n"))
		{
			String trimmed = line.trim();
			if (!trimmed.isEmpty())
				say.add(trimmed);
		}
		return say;
	}

	static JsonArray parseRegions(String text, List<String> warnings)
	{
		var regions = new JsonArray();
		for (String token : text.split("[^0-9]+"))
		{
			if (token.isEmpty())
				continue;
			try
			{
				regions.add(Integer.parseInt(token));
			}
			catch (NumberFormatException e)
			{
				// An 11-digit paste used to abort the whole save with a raw
				// "For input string" - name the token and carry on instead.
				warnings.add("'" + token + Resources.text("notARegion"));
			}
		}
		return regions;
	}

	static JsonArray regionsOf(JsonObject rule)
	{
		var place = placeOf(rule);
		return place == null ? null : place.getAsJsonArray("regions");
	}

	/**
	 * The condition that holds a rule's regions: its when, or the one place
	 * in an "all" that also asks for a chance or a quest, as the fun- place
	 * lines do. QA2, 15 Oct: those read as "triggered by something other
	 * than a place". Null for a rule that is not about a place.
	 */
	static JsonObject placeOf(JsonObject rule)
	{
		var when = rule.has("when") && rule.get("when").isJsonObject()
			? rule.getAsJsonObject("when") : null;
		if (when == null)
			return null;
		if (isPlace(when))
			return when;
		JsonObject found = null;
		if ("all".equalsIgnoreCase(optString(when, "type")) && when.has("conditions")
			&& when.get("conditions").isJsonArray())
		{
			for (var each : when.getAsJsonArray("conditions"))
			{
				if (each.isJsonObject() && isPlace(each.getAsJsonObject()))
				{
					if (found != null)
						return null;
					found = each.getAsJsonObject();
				}
			}
		}
		return found;
	}

	static boolean isPlace(JsonObject condition)
	{
		String type = optString(condition, "type");
		return ("inRegion".equalsIgnoreCase(type) || "regionEnter".equalsIgnoreCase(type))
			&& condition.has("regions") && condition.get("regions").isJsonArray();
	}

	JsonObject readFile() throws IOException
	{
		return gson.fromJson(new String(Files.readAllBytes(file), StandardCharsets.UTF_8), JsonObject.class);
	}

	static String optString(JsonObject object, String key)
	{
		return object.has(key) && object.get(key).isJsonPrimitive() ? object.get(key).getAsString() : null;
	}

	/** The rule's own title when it has one, otherwise one made from its id. */
	static String titleOf(JsonObject rule)
	{
		String title = optString(rule, "title");
		return title == null || title.trim().isEmpty() ? prettyName(optString(rule, "id")) : title.trim();
	}

	/**
	 * What the window says about a rule: its "about", written for players,
	 * or nothing. The note is the authors' own and never shown: QA2, 15 Oct,
	 * the quest moments' notes put varp numbers and quest steps in front of
	 * players.
	 */
	static String aboutOf(JsonObject rule)
	{
		String about = optString(rule, "about");
		return about == null || about.trim().isEmpty() ? null : about.trim();
	}

	static String prettyName(String id)
	{
		if (id == null)
			return "(new)";
		String s = id;
		boolean set = id.startsWith("gear-set-");
		// The category says it already: Items, Locations, Bosses.
		for (String prefix : new String[]{"gear-set-", "gear-", "area-", "enter-", "boss-"})
		{
			if (s.startsWith(prefix))
			{
				s = s.substring(prefix.length());
				break;
			}
		}
		s = s.replace('-', ' ');
		s = Character.toUpperCase(s.charAt(0)) + s.substring(1);
		return set ? "Full " + s + " (set)" : s;
	}
}

package com.follower;

import lombok.*;

/**
 * A rule-sized version of the documenting errand: the follower stops, holds a
 * prop, plays a pose over it for a few seconds, and puts everything back.
 *
 * <p>The errand is the scheduler's moment; this is the RULE's. A line like
 * "That's going in the book" claims an act the player never sees, and the
 * whole point of the prop work is that the claim and the act can now happen
 * together. Which rules get one, with what prop and pose and for how long, is
 * authored in phrases.json - the engine stays ignorant of scrolls.
 *
 * <p>Same shape as the errand's scroll handling, and deliberately so: prop
 * and pose together on one tick, and the cleanup path is idempotent because
 * it runs from finish, abort and shutdown alike. One flourish at a time; a
 * second request while one is playing is dropped rather than queued, because
 * a follower that files a backlog of gestures stops reading as spontaneous.
 */
@RequiredArgsConstructor
class PropFlourish
{
	final FollowerEntity follower;
	final ErrandController.Hands hands;

	int holdTicks;
	@Getter
	boolean active;
	/** The pose it put on, the only one it takes off. */
	int poseId;

	/**
	 * Starts the flourish, unless one is already playing.
	 *
	 * @param leftItemId a thing for the other hand too - the quill of the
	 *                   writing pose - or 0 for the one prop alone
	 * @return whether it started - a false means the line still says its
	 * words, just without the gesture, which is the right degradation
	 */
	boolean start(int leftItemId, int itemId, int poseId, int ticks)
	{
		// Hands already full - a borrowed tool, most likely - and the scroll
		// would take the same slot: the gesture is skipped, the line still lands.
		if (active || itemId <= 0 || poseId <= 0 || hands.isHolding())
			return false;
		active = true;
		holdTicks = Math.max(1, ticks);
		this.poseId = poseId;
		follower.stayHere();
		// Prop and pose on the same tick, and so the same rendered frame: the
		// appearance service's dump path is synchronous, so the model with the
		// prop in it is applied before hold() returns. A settle delay here
		// only ever produced the wrong order - idle hands holding a scroll.
		if (leftItemId > 0)
			hands.hold(leftItemId, itemId);
		else
			hands.hold(itemId);
		follower.setPoseOverride(poseId);
		return true;
	}

	/** Call once per game tick, on the client thread. */
	void tick()
	{
		if (!active)
			return;
		if (--holdTicks <= 0)
			putEverythingBack();
	}

	/**
	 * The interruption path: a scene change or the plugin shutting down. Same
	 * cleanup as finishing - releasing the follower to walk is harmless even
	 * when the interrupter is about to despawn it, and a path that leaves it
	 * planted is a stuck follower waiting to happen.
	 */
	void abort()
	{
		if (!active)
			return;
		putEverythingBack();
	}

	void putEverythingBack()
	{
		active = false;
		holdTicks = 0;
		// Only its own: a rest's sit or a held emote's copy put on since
		// stays, or the follower stands while it is still meant to be at it.
		follower.clearPoseOverride(poseId);
		hands.release();
		follower.resumeFollowing();
	}
}

package com.follower;

import net.runelite.api.ModelData;

/**
 * The colour and texture replacements a cache definition applies to its
 * models, under the dump files' field names. Shared by worn items, body kits
 * and spotanims, which all carry them the same way.
 */
class Recolours
{
	/** Colours to find / replace with. */
	short[] cf,
		cr;
	/** Textures to find / replace with. */
	short[] tf,
		tr;

	/**
	 * The model with these replacements applied. loadModelData shares its
	 * arrays between callers, so whatever is changed is cloned first.
	 */
	ModelData recolour(ModelData data)
	{
		if (cf != null && cr != null && cf.length > 0 && cr.length > 0)
		{
			data = data.cloneColors();
			for (int i = 0; i < cf.length && i < cr.length; i++)
				data.recolor(cf[i], cr[i]);
		}
		if (tf != null && tr != null && tf.length > 0 && tr.length > 0)
		{
			data = data.cloneTextures();
			for (int i = 0; i < tf.length && i < tr.length; i++)
				data.retexture(tf[i], tr[i]);
		}
		return data;
	}
}

package com.follower;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.List;
import java.util.Set;

/**
 * The data files bundled in the jar beside the code, under /com/follower/:
 * the tables and scripts the plugin reads as it loads them. One that is
 * missing or cannot be read is a broken jar, and fails where it is read.
 */
class Resources
{
	/** lists.properties: the small word and id lists, each comma separated. */
	static final Properties LISTS = properties("lists.properties");

	/** strings.properties: the longer captions, tooltips and status lines, word for word. */
	static final Properties TEXT = properties("strings.properties");


	/** A bundled file's text, as UTF-8. */
	static BufferedReader reader(String name)
	{
		return new BufferedReader(new InputStreamReader(
			Resources.class.getResourceAsStream("/com/follower/" + name), StandardCharsets.UTF_8));
	}

	/** A bundled properties file. */
	static Properties properties(String name)
	{
		var properties = new Properties();
		try (InputStream in = Resources.class.getResourceAsStream("/com/follower/" + name))
		{
			properties.load(in);
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
		return properties;
	}

	/**
	 * A bundled table (.tsv): its rows in order, each split at its tabs.
	 * Blank lines and lines that start with # are not rows.
	 */
	static List<String[]> rows(String name)
	{
		List<String[]> rows = new ArrayList<>();
		try (BufferedReader in = reader(name))
		{
			for (String line = in.readLine(); line != null; line = in.readLine())
			{
				if (!line.isEmpty() && !line.startsWith("#"))
					rows.add(line.split("\t", -1));
			}
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
		return rows;
	}

	/** One of strings.properties' texts. */
	static String text(String key)
	{
		return TEXT.getProperty(key);
	}

	/** One of lists.properties' lists, in its order. */
	static String[] list(String key)
	{
		return LISTS.getProperty(key).split(",");
	}

	/** One of lists.properties' lists, as a set of its words. */
	static Set<String> words(String key)
	{
		return new HashSet<>(Arrays.asList(list(key)));
	}

	/** One of lists.properties' lists, as a set of its ids. */
	static Set<Integer> ids(String key)
	{
		Set<Integer> ids = new HashSet<>();
		for (String id : list(key))
			ids.add(Integer.valueOf(id));
		return ids;
	}
}

