import static java.lang.Math.*;

/**
 * Keeps the follower company while the player works: notices a work session
 * beginning from the click, the animation and the XP, takes a seat off the
 * player's flank facing the target, borrows the tool, and lets everything go
 * when the session ends.
 *
 * <p>This is about the body and position, not words: nothing here speaks.
 * What it knows is handed to the rules through {@link TriggerContext} and a
 * few events, so a line can be written against it if one is ever wanted.
 *
 * <p>Cheap by construction. Nothing scans the scene per tick: the one scan
 * (the target's same-name neighbours, for the seat) runs once per seat, and
 * object and NPC events are dropped unless they touch the target's tile.
 */
@Getter
class SkillingController
{
	/**
	 * The skilling company's tables - the work options, the tools, the
	 * outfits and the like - read once from skilling.properties: each a key
	 * and its values, comma separated.
	 */
	static final Properties DATA = Resources.properties("skilling.properties");

	/** The option words that start work, lowercased, and the skill each points at. */
	static final Map<String, String> WORK = new HashMap<>();

	static
	{
		for (String key : DATA.stringPropertyNames())
		{
			if (key.startsWith("option."))
			{
				for (String word : values(key))
					WORK.put(word.toLowerCase(Locale.ROOT), key.substring("option.".length()));
			}
		}
	}

	/**
	 * The work the game lets a player do from one side only: every object
	 * with a work option whose cache definition carries an access mask. The
	 * client drops that mask when it loads the definition, so it cannot be
	 * read at run time; skilling.properties has it, read off the cache.
	 * Everything else is worked from any side a fence does not close.
	 */
	static final Set<Integer> ONE_SIDED = idSet("oneSided");

	/** Ticks the player has to be at it before the seat is taken. */
	static final int SEAT_AFTER_TICKS = 6;

	/** While a favour is owed the seat is taken in half the time. */
	static final int GRATEFUL_SEAT_AFTER_TICKS = SEAT_AFTER_TICKS / 2;

	/** A session with no animation and no drop for this long is over. */
	static final int QUIET_END_TICKS = 25;

	/** Walking this far from the working spot ends it. */
	static final int WALK_OFF_TILES = 3;

	/** How long a click waits for proof that it turned into work. */
	static final int PENDING_TICKS = 50;

	/** A session this long earns the return beat; two minutes. */
	static final int BEAT_AFTER_TICKS = 200;

	/** Object and NPC events this soon after a load are the scene shuffling. */
	static final int LOAD_SETTLE_TICKS = 2;

	/** Same-name neighbours this close are the player's likely next click. */
	static final int NEIGHBOUR_TILES = 2;

	/** How far off the player the follower looks for something of its own to work. */
	static final int ALONGSIDE_TILES = 6;

	/** Its own work gone, a look at where it was before it chooses again. */
	static final int WORK_GONE_TICKS = 3;

	/** A moved fishing spot turns up about this far from the old one. */
	static final int NEW_SPOT_TILES = 8;

	/** Free slots at which the bag counts as half full. */
	static final int HALF_BAG_FREE = 14;

	/** The seat is kept this long for the bank to open; the walk there. */
	static final int BANK_WALK_TICKS = 30;

	/** Three minutes: the most a bank trip holds the seat once the bank opened. */
	static final int BANK_TRIP_CAP_TICKS = 300;

	/** Back from the bank, a gatherer's seat waits this long for the first swing. */
	static final int BANK_BACK_TICKS = 10;

	/**
	 * Which scenery counts as the bank, for the trip and the bag's step. In
	 * any case: the game capitalises a few of its own, "Bank Booth" at Burgh
	 * de Rott and "Bank Chest" on Fossil Island among them.
	 */
	static final Predicate<String> BANK_NAMES =
		name -> "Bank booth".equalsIgnoreCase(name) || "Bank chest".equalsIgnoreCase(name);

	/** The stall watch stands this far off the player, toward the guard. */
	static final int STALL_WATCH_TILES = 5;

	/** Who counts as the guard a stall is watched against, in one place. */
	static final String[] GUARD_NAMES = {"Guard", "Market Guard", "Knight of Ardougne", "Paladin"};

	/** SpotanimID.STUNNED_THIEVING: the stars over a failed pickpocket. */
	static final int STUN_GRAPHIC = 245;

	/** A stun earns a head shake one time in three, and not again for twenty seconds. */
	static final int STUN_COOLDOWN_TICKS = 33;

	/** HUMAN_LAYTRAP, the player's own; the trap object follows it onto their tile. */
	static final int LAY_TRAP = 5208;

	/** The trap watcher stands two tiles off the trap, for two minutes at most. */
	static final int TRAP_WATCH_TILES = 2,
		TRAP_WATCH_TICKS = 200;

	/** A trap run is over once the player is this far from its first trap. */
	static final int TRAP_RUN_TILES = 10;

	/** A fire lit within this of where the player just stood is theirs. */
	static final int FIRE_LINE_TILES = 3,
		FIRE_LINE_EVERY = 4;

	/** Three seconds at the fire once there. */
	static final int FIRE_WARM_TICKS = 5;

	/** The cold-stamp-feet rule's regions: the Wintertodt camp and the snows. */
	static final Set<Integer> COLD_REGIONS = idSet("coldRegions");

	/**
	 * How long a borrowed tool stays in the hand once a session ends. One
	 * tree is not the work; the walk to the next one is part of it, and
	 * handing an axe back twice a minute to take it straight out again
	 * reads as a fault rather than as company.
	 */
	static final int TOOL_GRACE_TICKS = 50;

	/**
	 * How much longer than the grace a send-off will wait for the player to
	 * stand still. Movement cancels an emote, and a player who has just
	 * walked away from a tree is usually still walking, so a bow played the
	 * instant the grace lapsed was a bow nobody saw.
	 */
	static final int BEAT_WAIT_TICKS = 100;

	/** EMOTE_CLAP, proven by the mirror rules: the task ledger's applause. */
	static final int CLAP = 865,
		CLAP_TICKS = 3;

	/** Ticks the ledger's scroll is out after the clap. */
	static final int LEDGER_TICKS = 8,
		LEDGER_COOLDOWN_TICKS = 20;

	/** Out of runes: a think, and not again for half a minute. */
	static final int RUNES_COOLDOWN_TICKS = 50;

	static final String TASK_DONE_MESSAGE = "return to a slayer master";
	static final String[] NEW_TASK_MESSAGES = {"new task is to kill", "now assigned to"};

	/** The skills worked with nothing in the world to click; a drop opens them. */
	static final Set<Skill> STANDING_SKILLS = new HashSet<>(Arrays.asList(
		Skill.FLETCHING, Skill.HERBLORE, Skill.CRAFTING));

	final Client client;
	final FollowerEntity follower;
	final FollowerConfig config;
	final Consumer<TriggerEvent> dispatch;
	final BooleanSupplier inCombat;

	/** True when thrall work or the spectator owns the feet; both beat the seat. */
	final BooleanSupplier feetTaken,
		bankOpen;
	final Borrow borrow;
	final ErrandController.Hands hands;

	/** Every counter's jitter comes from here; a test may seed it. */
	final Random random = new Random();

	/** What the follower does in the seat, made afresh for each session; see {@link KeepingCompany}. */
	KeepingCompany company;

	/** The last menu option the player clicked, tags off, work or not. */
	String lastOption = "";

	/** The bag edge seen this tick, handed to the company after the session checks. */
	Type bagEdge;

	WorkSession session;

	/** A work click waiting for its proof, and the tick it was made. */
	WorkSession pending;
	int pendingTick;

	WorldPoint seat;

	/** The tick from which the seat may be (re)taken; retries space out from it. */
	int seatDueTick;

	/** Set by a shift to a neighbouring target: the seat is chosen again. */
	boolean reseat;

	int releaseTicks;

	/** A tool the hands declined this session, so it is not asked for on every drop. */
	int refusedTool,
		refusedHat;

	/** Ticks a borrowed tool is kept between sessions, and the work it is for. */
	int graceTicks;
	String graceActivity;

	/** Ticks already spent waiting for a still moment to bow in. */
	int beatWait;

	/**
	 * When the current run of one kind of work began. The send-off is for
	 * the whole stint, so an hour of chopping earns its bow even though no
	 * single tree lasted two minutes.
	 */
	int stintStart,
		ticksSinceLoading = 1000;

	/**
	 * The seat excused for a moment of the follower's own - a level, the
	 * pet - by {@link Moments}: not retaken, and the company's habits paused,
	 * until the moment hands the feet back.
	 */
	boolean excused;

	int lastFreeSlots = -1;
	boolean halfArmed = true;

	/**
	 * The seat kept through a bank trip after the session ended: from the
	 * walk-off, and confirmed when the bank opens. Until then the tick it
	 * lapses is the walk's; after, the cap's.
	 */
	boolean bankTrip,
		bankTripConfirmed;
	int bankTripUntil;

	/** Whether the player has been away from the seat, so that coming back counts. */
	boolean bankTripAway;

	/** Whether the seat kept for the trip is a gatherer's, carried into the next session. */
	boolean bankTripGathering;

	/** Whether a player has been seen playing the nest look, so it is safe to. */
	boolean nestLookProven;

	/** The player's tile at the last tick; a fire lit near it is theirs. */
	WorldPoint previousHere;

	/**
	 * The trap watch, outside any session: the tick the lay animation
	 * played, the trap that followed it onto the player's tile, and the
	 * seat two tiles off it.
	 */
	int layTick = -1000;
	/** Where the player stood to lay it: the trap turns up there, after they step off. */
	WorldPoint layTile,
		trapTile;
	int trapId;
	WorldPoint trapSeat;
	int trapUntil,
		trapLookTicks;

	/** The trap watcher's notes: out now and then over a run, and when next. */
	boolean trapReading;
	int trapReadAt,
		trapReadUntil;

	/** The fire line: fires counted, and the visit to every fourth. */
	int fires,
		lastFireTick = -1000;
	WorldPoint fireSeat;
	int fireWarmAt,
		fireLeaveAt;

	/** The task ledger's scroll, and the tick the clap hands over to it. */
	final PropFlourish ledger;
	int ledgerAt,
		ledgerCooldownUntil,
		runesCooldownUntil,
		stunSeenTick = -1000,
		stunCooldownUntil;

	/** Ticks the feet are kept after a session for the patch inspector's notes. */
	boolean endNoteOut;

	/**
	 * A way to start an errand by key, silently or not: the prayer at the
	 * altar borrows the altar errand, the fire line the too-close gag. Null
	 * when nothing offered one.
	 */
	@Setter
	BiConsumer<String, Boolean> errands;

	SkillingController(Client client, FollowerEntity follower, FollowerConfig config,
		ErrandController.Hands hands, Consumer<TriggerEvent> dispatch,
		BooleanSupplier inCombat, BooleanSupplier feetTaken, BooleanSupplier bankOpen)
	{
		this.client = client;
		this.follower = follower;
		this.config = config;
		this.dispatch = dispatch;
		this.inCombat = inCombat;
		this.feetTaken = feetTaken;
		this.bankOpen = bankOpen;
		this.borrow = new Borrow(follower, hands);
		this.hands = hands;
		this.company = new KeepingCompany(client, follower, config, hands, borrow, random);
		this.ledger = new PropFlourish(follower, hands);
	}

	boolean isWorking()
	{
		return session != null;
	}

	/**
	 * Whether the company owns the follower's feet: seated, or holding still
	 * through the return beat. Registered beside the errand and spectate
	 * owners so a seat never reads as a Stay the player asked for.
	 */
	/**
	 * One line of what the company is doing, for {@code ::follower status}:
	 * enough to tell a session that never opened from one that opened on
	 * the wrong thing, which is the difference between the follower doing
	 * nothing and the follower doing nothing yet.
	 */
	/** An item's name off the live cache, or null when it cannot be read. */
	String itemName(int itemId)
	{
		if (itemId <= 0)
			return null;
		try
		{
			var item = client.getItemDefinition(itemId);
			return item == null ? null : item.getName();
		}
		catch (RuntimeException notInTheCache)
		{
			return null;
		}
	}

	/** Where the player stands, or null while there is no player. */
	WorldPoint playerTile()
	{
		return FollowerEntity.playerTile(client);
	}

	/** Whether the follower is somebody else's just now, fighting, or not out at all. */
	boolean elsewhere()
	{
		return feetTaken.getAsBoolean() || inCombat.getAsBoolean() || !follower.isSpawned();
	}

	/** Hands the feet back, when they are still the company's to give. */
	void letGo()
	{
		if (follower.isStaying() && !feetTaken.getAsBoolean())
			follower.resumeFollowing();
	}

	/**
	 * Whether a mirrored pose may play from where the follower stands. During
	 * a session the answer is only from the seat: a cast copied while the
	 * follower is still trailing the player lands on dry ground, which is the
	 * fishing-the-grass the mimic was seen doing. With no session on, the
	 * mimic keeps its old freedom.
	 */
	boolean mirrorsFromHere()
	{
		return session == null || seat != null;
	}

	boolean holdsTheFeet()
	{
		return seat != null || releaseTicks > 0 || trapSeat != null || fireSeat != null
			|| joinTile != null || ledger.isActive();
	}

	/**
	 * Whether the errands must stand aside: the feet are held, or a session
	 * is on - except a prayer at an altar, which is the one session that
	 * borrows an errand rather than a seat. This is the busy gate an errand
	 * under way must also pass; the errands' own session gate keeps every
	 * unforced start out of the prayer session too.
	 */
	/**
	 * Excuses the seat for a moment, or hands it back. Excused, the seat is
	 * kept in mind but not retaken - the moment has the feet - and the
	 * company's habits wait; handed back, the next tick retakes it.
	 */
	void setExcused(boolean excused)
	{
		if (excused && !this.excused && session != null)
			// The moment has the feet: a gatherer's scroll and swing stop too.
			company.excuse();
		this.excused = excused;
	}

	/**
	 * A one-shot of somebody else's - the level-up's clap - played the
	 * seat's way: a look at the player first, and up off the sit before it.
	 * Off the seat it is a glance and the emote, which is all it would be.
	 */
	void gesture(int[] animationIds, WorldPoint player)
	{
		company.lookAt(player, CLAP_TICKS);
		company.gesture(animationIds);
	}

	/** Whether the follower owes the player one just now; null means never. */
	@Setter
	BooleanSupplier grateful;

	/** Ticks into the work before the seat is taken: fewer while a favour is owed. */
	int seatAfter()
	{
		return grateful != null && grateful.getAsBoolean() ? GRATEFUL_SEAT_AFTER_TICKS : SEAT_AFTER_TICKS;
	}

	boolean blocksErrands()
	{
		// A tool kept between trees is still in the hand, and every errand
		// lets go of the hand when it ends.
		return holdsTheFeet() || borrow.isHolding()
			|| (session != null && !"prayer".equals(session.activity));
	}

	/** Whether the follower is sitting in for the long haul. */
	boolean isSitting()
	{
		return company.isSitting();
	}

	// ---------------------------------------------------------------- inputs

	/**
	 * Any menu option the player clicked, with the option's target, tags off;
	 * the bag reads it. Compost goes on a patch
	 * as "Use" with the compost named in the target, and the follower turns
	 * away from it where it stands.
	 */
	void noteMenuOption(String plain, String target)
	{
		lastOption = plain == null ? "" : plain;
		if (session != null && "farming".equals(session.activity)
			&& "Use".equalsIgnoreCase(lastOption) && target != null
			&& target.toLowerCase(Locale.ROOT).contains("compost"))
			company.compost();
	}

	/** Whether a menu option is one of the words that start work. */
	static boolean isWorkOption(String option)
	{
		return WORK.keySet().stream().anyMatch(plainOption(option)::equalsIgnoreCase);
	}

	/** The option with the game's colour tags off it. */
	static String plainOption(String option)
	{
		return option == null ? "" : option.replaceAll("<[^>]*>", "").trim();
	}

	/**
	 * The skill an option word points at, as a lowercased skill name, or
	 * empty for a word that could be anything ("Use"). The first XP drop has
	 * the last word either way.
	 */
	static String activityFor(String option)
	{
		return WORK.getOrDefault(plainOption(option).toLowerCase(Locale.ROOT), "");
	}

	/**
	 * The player clicked a work option on something.
	 *
	 * <p>A click alone opens nothing; it waits for the animation or the drop
	 * that proves it turned into work. A click on a same-name neighbour of the
	 * current target during a session moves the session over rather than
	 * ending it: that is the player shifting to the next tree, and the seat
	 * follows once they are at it.
	 *
	 * @param min the footprint's south-west tile, which is the target tile
	 * @param max the footprint's far corner, or null for a single tile
	 * @param npc the interacted NPC, or null for scenery
	 */
	void noteClick(String option, String targetName, int targetId,
		WorldPoint min, WorldPoint max, NPC npc)
	{
		if (!config.keepsCompany() || !isWorkOption(option) || min == null)
			return;
		var here = playerTile();
		if (here == null)
			return;
		String plain = plainOption(option),
			name = targetName == null ? "" : targetName;
		int now = client.getTickCount();

		// The same patch whatever its crop is called now and whatever is done to
		// it; anything else is the same work only by the same option - a net
		// at a spot where the player harpooned is new work, with its own tool.
		boolean samePatch = session != null && targetId == session.targetId
			&& min.equals(session.targetTile);
		if (session != null && !session.standing
			&& (name.equals(session.targetName) && plain.equalsIgnoreCase(session.option)
				|| samePatch)
			&& min.getPlane() == session.targetTile.getPlane()
			&& (min.distanceTo(session.targetTile) <= WALK_OFF_TILES
				|| (session.depleted && "fishing".equals(session.activity)
					&& min.distanceTo(session.targetTile) <= NEW_SPOT_TILES)))
		{
			boolean moved = !min.equals(session.targetTile);
			session.targetId = targetId;
			session.targetName = name;
			session.targetTile = min;
			session.targetMax = max == null ? min : max;
			session.targetNpc = npc;
			session.depleted = false;
			session.newSpot = null;
			session.targetSinceTick = now;
			session.lastEvidenceTick = now;
			// The player may have a walk ahead of them - a moved spot is
			// yards off - so where they work from is read at the next swing,
			// and the old seat, which may now be on the line to the new
			// target or on it, is chosen again from scratch once they are at it.
			session.settling = true;
			reseat = true;
			seatDueTick = now + seatAfter();
			if (moved)
				// Not for the same target: the compost's turn away, queued a
				// moment ago by the same click, would be wiped with the looks.
				company.aimAt(faceTile(), session.activity, modeFor(here), now);
			return;
		}

		pending = new WorkSession(plain, activityFor(plain), name, targetId, min, max, npc,
			here, now);
		pendingTick = now;
	}

	/** The local player's animation changed; anything but -1 is work. */
	void noteAnimation(int animationId)
	{
		if (animationId == -1)
			return;
		if (animationId == LAY_TRAP)
		{
			// The trap object turns up on the player's tile a moment later.
			layTick = client.getTickCount();
			layTile = playerTile();
		}
		// A click parked during a session is the player moving on to
		// something else; the swing that follows is its proof, and the old
		// session ends inside startPending.
		if (pending != null)
		{
			pending.lastAnimation = animationId;
			startPending();
			return;
		}
		if (session != null)
		{
			session.lastAnimation = animationId;
			session.lastEvidenceTick = client.getTickCount();
		}
	}

	/**
	 * Any player's animation, the local one included. The nest look is
	 * played on the follower only once a player skeleton has been seen
	 * playing it; until then the nest gets a look and no more.
	 */
	void notePlayerAnimation(int animationId)
	{
		if (animationId == NEST_LOOK)
			nestLookProven = true;
	}

	/**
	 * A ground item appeared. A bird's nest landing at the feet of a player
	 * who is chopping is worth a look down, and the peer once that is known
	 * to be safe on the follower.
	 */
	void itemSpawned(String name, WorldPoint tile)
	{
		if (session == null || !"woodcutting".equals(session.activity) || name == null
			|| tile == null || !name.toLowerCase(Locale.ROOT).startsWith("bird nest"))
			return;
		if (tile.equals(playerTile()))
			company.nest(tile, nestLookProven);
	}

	/**
	 * An XP drop landed. The skill is the truth about what the work is, so
	 * it overrides the guess the option word made.
	 *
	 * @return the drops this session including this one, or 0 outside one
	 */
	int noteXpDrop(Skill skill)
	{
		int now = client.getTickCount();
		if (skill == Skill.HUNTER && trapSeat != null)
			// A catch: the run is still on.
			trapUntil = now + TRAP_WATCH_TICKS;
		if (pending != null)
			startPending();
		if (session == null && skill != null && STANDING_SKILLS.contains(skill))
			startStanding(skill, now);
		if (session == null)
			return 0;
		// The FIRST drop names the work, and only the first. A cook at a
		// fire lights the next one between batches, and firemaking experience
		// landing mid-session renamed the work, re-shaped the seat and moved
		// the follower - then the next fish renamed it back and moved it
		// again. Play report: "moves erratically to try and cook with the
		// player". One naming was always the intent; the code simply did not
		// say so.
		if (skill != null && session.xpDrops == 0)
		{
			String named = skill.getName().toLowerCase(Locale.ROOT);
			if (!named.equals(session.activity))
			{
				// A "Use" click said nothing; the drop names the work, and the
				// seat may be the wrong shape for it: across a fire, not on
				// its flank. Chosen again, once the player is at it.
				session.activity = named;
				company.aimAt(faceTile(), named, modeFor(playerTile()), now);
				if (seat != null)
				{
					reseat = true;
					seatDueTick = now;
				}
			}
		}
		session.xpDrops++;
		session.lastDropTick = now;
		session.lastEvidenceTick = now;
		if (now - session.startTick >= seatAfter())
			// The drop may be what named the activity, and so the tool.
			maybeBorrow();
		if (joinTile == null)
			// Not the tally scroll into the hand mid-swing.
			company.drop(session.xpDrops, now);
		return session.xpDrops;
	}

	/**
	 * A scenery object appeared. During a session only the target's tile
	 * matters: a different id there is the stump, the empty rock, the used
	 * patch. Outside one, the trap the player just laid and the fire they
	 * just lit are the two things worth noticing.
	 */
	void objectSpawned(int id, WorldPoint min, WorldPoint max)
	{
		if (ticksSinceLoading <= LOAD_SETTLE_TICKS || min == null || !config.keepsCompany())
			return;
		if (watchingObjects() && id != session.targetId && covers(min, max, session.targetTile))
		{
			depleted();
			return;
		}
		if (trapTile != null)
		{
			if (!covers(min, max, trapTile))
				// The next trap of the run: it goes on, the follower where it is.
				maybeTheTrap(id, min, max);
			else if (id != trapId)
			{
				// The trap sprang, or fell: a glance at the player.
				trapId = id;
				var here = playerTile();
				if (trapSeat != null && here != null)
				{
					follower.setStayFaceTile(here);
					trapLookTicks = 3 /* TRAP_LOOK_TICKS */;
				}
			}
			return;
		}
		if (session != null)
			return;
		if (!maybeTheTrap(id, min, max))
			maybeTheFire(id, min, max);
	}

	/** A scenery object went. The target going is the depletion. */
	void objectDespawned(int id, WorldPoint min, WorldPoint max)
	{
		if (watchingObjects() && id == session.targetId && covers(min, max, session.targetTile))
			depleted();
	}

	boolean watchingObjects()
	{
		// Standing work has no target in the world; nothing can deplete it.
		return session != null && session.targetNpc == null && !session.standing
			&& ticksSinceLoading > LOAD_SETTLE_TICKS;
	}

	/** The interacted NPC going - a fishing spot moving - is its depletion. */
	void npcDespawned(NPC npc)
	{
		if (alongside != null && npc != null && npc == alongside.npc
			&& ticksSinceLoading > LOAD_SETTLE_TICKS)
			// The spot it was fishing moved on.
			loseTheWork(client.getTickCount());
		if (session == null || npc == null || npc != session.targetNpc
			|| ticksSinceLoading <= LOAD_SETTLE_TICKS)
			return;
		session.targetNpc = null;
		depleted();
	}

	/** A same-name NPC turning up near a gone target is where it moved to. */
	void npcSpawned(NPC npc)
	{
		if (session == null || npc == null || session.targetNpc != null || !session.depleted
			|| ticksSinceLoading <= LOAD_SETTLE_TICKS)
			return;
		var at = npc.getWorldLocation();
		if (at != null && session.targetName.equals(npc.getName())
			&& at.getPlane() == session.targetTile.getPlane()
			&& at.distanceTo(session.targetTile) <= NEW_SPOT_TILES)
		{
			boolean first = session.newSpot == null;
			session.newSpot = at;
			if (first)
				// Before the player clicks it, if the spawn came after the
				// despawn; the depletion's own look covers the other order.
				company.lookNext(at);
		}
	}

	/** The nearest same-name spot other than the target, or null. */
	WorldPoint nearestSpot()
	{
		var view = client.getTopLevelWorldView();
		if (view == null)
			return null;
		WorldPoint best = null;
		for (var npc : sameNameNpcs(view, session.targetTile, NEW_SPOT_TILES))
		{
			var at = npc.getWorldLocation();
			// The one on the target's own tile is the target, or what is
			// left of it in the list this tick.
			if (!at.equals(session.targetTile) && (best == null
				|| at.distanceTo(session.targetTile) < best.distanceTo(session.targetTile)))
				best = at;
		}
		return best;
	}

	/**
	 * The NPCs named as the target, other than the target itself, on a tile's
	 * plane and within so many tiles of it.
	 */
	List<NPC> sameNameNpcs(WorldView view, WorldPoint near, int reach)
	{
		List<NPC> found = new ArrayList<>();
		for (var npc : view.npcs())
		{
			var at = npc == null ? null : npc.getWorldLocation();
			if (at != null && npc != session.targetNpc && session.targetName.equals(npc.getName())
				&& at.getPlane() == near.getPlane() && at.distanceTo(near) <= reach)
				found.add(npc);
		}
		return found;
	}

	/** The far corner of an NPC's footprint, from its south-west tile. */
	static WorldPoint farCorner(NPC npc, WorldPoint at)
	{
		int size = npc.getComposition() == null ? 1 : max(1, npc.getComposition().getSize());
		return at.dx(size - 1).dy(size - 1);
	}

	/** A scene load began: what despawns around it is shuffling, not change. */
	void sceneLoading()
	{
		ticksSinceLoading = 0;
	}

	/**
	 * The session, the kept seat, the trap, the fire and the kept tool, all
	 * let go of silently.
	 *
	 * @param announce whether the rules hear the session end
	 * @param notes whether the notes, the ledger and a parked click go too
	 */
	void dropEverything(boolean announce, boolean notes)
	{
		if (session != null)
			end(true, false, announce);
		dropTheBankTrip(true);
		dropTheTrap(true);
		dropTheFireLine(true);
		dropTheGrace(false);
		if (notes)
		{
			letGoOfTheNotes();
			ledger.abort();
			ledgerAt = 0;
			pending = null;
		}
	}

	/** Logout, hop, shutdown: everything let go of, nothing said. */
	void reset()
	{
		dropEverything(false, true);
		releaseTicks = 0;
		excused = false;
		alongside = null;
		lastFreeSlots = -1;
		halfArmed = true;
		ticksSinceLoading = 1000;
		previousHere = null;
		layTick = -1000;
		layTile = null;
	}

	// ---------------------------------------------------------------- words

	/**
	 * A game message. The company reads four: the thieving stun, the empty
	 * rune pouch, the slayer task ending and the next one being set. Each is
	 * a small silent reaction with its own cooldown; nothing is said back.
	 */
	void noteChatMessage(String message, ChatMessageType type)
	{
		if (!config.keepsCompany() || message == null)
			return;
		String plain = message.replaceAll("<[^>]*>", "").toLowerCase(Locale.ROOT);
		int now = client.getTickCount();
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM
			&& type != ChatMessageType.DIALOG)
			return;
		// STUNNED_MESSAGE: The game's own words, as the smallest certain fragment of each, matched
		// without case. The thieving stun ("You have been stunned!"), an empty
		// rune pouch ("You do not have enough ... to cast this spell."), the
		// slayer task ending ("... return to a Slayer master.") and the next one
		// being set ("Your new task is to kill ..." in the master's dialog, or
		// "... you're now assigned to kill ..." for a boss task).
		if (session != null && "thieving".equals(session.activity) && plain.contains("stunned" /* STUNNED_MESSAGE */))
			stunned(now);
		else if (plain.contains("do not have enough" /* NO_RUNES_MESSAGE */))
			outOfRunes(now);
		else if (plain.contains(TASK_DONE_MESSAGE)
			|| Arrays.stream(NEW_TASK_MESSAGES).anyMatch(plain::contains))
			ledgerBeat(now, plain.contains(TASK_DONE_MESSAGE));
	}

	/** A graphic on the local player. The thieving stun is the one that matters. */
	void noteGraphic(int graphicId)
	{
		if (graphicId == STUN_GRAPHIC && session != null && "thieving".equals(session.activity)
			&& config.keepsCompany())
			stunned(client.getTickCount());
	}

	/**
	 * Stunned: a shake of the head, one time in three, and not again for
	 * twenty seconds. The graphic and the message of the one stun arrive
	 * together, and count once.
	 */
	void stunned(int now)
	{
		// STUN_SAME_TICKS: The stun's graphic and its message inside this many ticks are the one stun.
		if (now - stunSeenTick <= 2 /* STUN_SAME_TICKS */)
			return;
		stunSeenTick = now;
		if (now < stunCooldownUntil || random.nextInt(3 /* STUN_ONE_IN */) != 0)
			return;
		stunCooldownUntil = now + STUN_COOLDOWN_TICKS;
		company.gesture(HEAD_SHAKE);
	}

	/** Out of runes: a look at the player and a think. */
	void outOfRunes(int now)
	{
		if (now < runesCooldownUntil)
			return;
		runesCooldownUntil = now + RUNES_COOLDOWN_TICKS;
		company.lookAt(playerTile(), CLAP_TICKS);
		company.gesture(SCRATCH_HEAD);
	}

	/**
	 * The task ledger. A task done: applause, then the scroll for the entry.
	 * The scroll goes through its own flourish, which holds the feet, so it
	 * is skipped while something else has them. A new task: a shrug -
	 * whatever it is, it is a lot of them.
	 */
	void ledgerBeat(int now, boolean done)
	{
		if (now < ledgerCooldownUntil)
			return;
		ledgerCooldownUntil = now + LEDGER_COOLDOWN_TICKS;
		company.gesture(done ? CLAP : SHRUG);
		if (done && !holdsTheFeet() && !feetTaken.getAsBoolean())
			ledgerAt = now + CLAP_TICKS;
	}

	// ------------------------------------------------------------------ tick

	/** Call once per game tick, on the client thread. */
	void tick()
	{
		if (ticksSinceLoading < 1000)
			ticksSinceLoading++;
		watchBag();

		if (!config.keepsCompany())
		{
			dropEverything(true, true);
			return;
		}

		if (releaseTicks > 0 && --releaseTicks == 0)
		{
			letGoOfTheNotes();
			// Only when the seat is still ours: a thrall or the spectator
			// that took the feet during the bow must not be released by us.
			letGo();
		}

		var local = client.getLocalPlayer();
		var here = local == null ? null : local.getWorldLocation();
		if (here == null)
		{
			dropEverything(true, false);
			previousHere = null;
			return;
		}

		int now = client.getTickCount();
		if (graceTicks > 0)
			watchTheGrace();
		watchTheGroundUnderfoot(now);
		if (bankTrip)
			watchTheBankTrip(now, here);
		watchTheTrap(now, here);
		watchTheFireLine(now, here);
		watchTheJoin(now);
		ledger.tick();
		if (ledgerAt > 0 && now >= ledgerAt)
		{
			ledgerAt = 0;
			if (!holdsTheFeet() && !feetTaken.getAsBoolean())
				ledger.start(ErrandController.QUILL_PROP, ErrandController.SCROLL_PROP,
					ErrandController.WRITE_SCROLL_POSE, LEDGER_TICKS);
		}
		previousHere = here;

		// A parked click, with or without a session running: forgotten when
		// it goes stale, promoted by an animation. During a session that is
		// the player moving on, and startPending closes the old one.
		if (pending != null)
		{
			if (now - pendingTick > PENDING_TICKS)
				pending = null;
			else if (local.getAnimation() != -1)
			{
				pending.lastAnimation = local.getAnimation();
				startPending();
			}
		}
		if (session == null)
			return;
		// Stood at the trap or the fire when the work began: that is over.
		dropTheTrap(true);
		dropTheFireLine(true);

		// The abort paths: something else owns the follower, or the world
		// changed under the session. Silent, tool straight back.
		if (elsewhere() || here.getPlane() != session.workSpot.getPlane())
		{
			end(true, false, true);
			return;
		}

		if (local.getAnimation() != -1)
		{
			session.lastAnimation = local.getAnimation();
			session.lastEvidenceTick = now;
			noteTheWorkPose(local.getAnimation(), now);
			if (session.settling)
			{
				// The first swing at the moved target: this is where they
				// work from now, and if it took a walk to get there the seat
				// waits its six ticks from here, as it did at the start.
				session.settling = false;
				if (!here.equals(session.workSpot))
					seatDueTick = now + seatAfter();
				session.workSpot = here;
			}
		}

		// The natural ends: walked off, gone quiet, gone to the bank. A walk
		// off toward a bank, or the bank opening, keeps the seat a while.
		boolean walkedOff = !session.settling
			&& here.distanceTo(session.workSpot) > WALK_OFF_TILES;
		boolean banking = bankOpen.getAsBoolean();
		if (walkedOff || banking || now - session.lastEvidenceTick > QUIET_END_TICKS)
		{
			if (seat != null && (walkedOff || banking)
				// BANK_TRIP_TILES: A bank this close to the work makes a walk-off a bank trip, maybe.
				&& nearestObject(client, session.workSpot, 40 /* BANK_TRIP_TILES */, BANK_NAMES) != null)
				holdForTheBankTrip(now, here, banking);
			end(false, now - session.startTick >= BEAT_AFTER_TICKS, true);
			return;
		}

		if (excused)
		{
			// Off on a moment of its own: the seat waits, and so do the habits.
			syncTheSeat();
			return;
		}
		if (seat == null || reseat)
		{
			// Not before the player has been at it, and not every tick when
			// the ground keeps refusing.
			if (now >= seatDueTick && !session.settling)
			{
				reseat = false;
				// SEAT_RETRY_TICKS: How often an unseated session looks again for somewhere to stand.
				seatDueTick = now + 10 /* SEAT_RETRY_TICKS */;
				if (gathering())
					// Whether it can work alongside is whether it has the tool.
					maybeBorrow();
				takeSeat(here);
				maybeBorrow();
			}
		}
		else if (!follower.isStaying() && !company.isAway())
		{
			// Un-seated by somebody else's release - a held emote ending, a
			// leash snap - and the session is still on: take the seat again.
			// Not while the company is off it on purpose, peering.
			if (follower.stayAt(seat))
				seatTheCompany(now);
			else
			{
				seat = null;
				company.unseated();
			}
		}

		// Working alongside: the player coming to work from its tile moves it
		// over, and its own tree, rock or spot going is a look and a choice.
		var at = work();
		if (at != null && farmingPatch())
			// The rake to rake, the dibber to plant, bare hands to pick.
			borrow.swap(Borrow.farmingTool(session.workPose));
		if (at != null && here.equals(seat) && local.getAnimation() != -1 && !session.settling)
		{
			// Now, not when the retarget that brought them here would have
			// re-seated it: the two stood on one tile for six ticks.
			reseat = true;
			seatDueTick = min(seatDueTick, now);
		}
		else if (at != null && !reseat && !stillLive(at))
			loseTheWork(now);

		// The company, last: the session goes on and the seat is settled.
		if (joinTile != null)
		{
			// Over at the work copying it: a look round, a pace, the notes
			// or a stretch would turn the swing away from it or walk off
			// mid-swing.
			bagEdge = null;
			return;
		}
		if (bagEdge == Type.BAG_HALF)
			company.bagHalf(lastOption);
		else if (bagEdge == Type.BAG_FULL)
			company.bagFull(lastOption, here);
		bagEdge = null;
		company.tick(now, here, local.getAnimation() != -1, session.activity, session.workPose,
			farmingPatch() && Borrow.farmingTool(session.workPose) == 0);
		syncTheSeat();
	}

	/** The company moved the seat of its own accord; the controller keeps up. */
	void syncTheSeat()
	{
		var moved = company.seatMoved();
		if (moved != null)
			seat = moved;
	}

	void startPending()
	{
		if (pending == null || elsewhere())
			return;
		int now = client.getTickCount();
		// Where they work is where they stand at the first swing, not where
		// they clicked from: a click from across the clearing, as every one
		// back from the bank is, read as having walked off on the swing.
		var at = playerTile();
		if (at == null)
			at = pending.workSpot;
		var opened = new WorkSession(pending.option, pending.activity,
			pending.targetName, pending.targetId, pending.targetTile, pending.targetMax,
			pending.targetNpc, at, now);
		opened.lastAnimation = pending.lastAnimation;
		pending = null;
		open(opened, now);
		// A prayer at an altar takes no seat: the follower goes and kneels
		// beside the player through the altar errand, with its lines skipped.
		if ("Pray-at".equalsIgnoreCase(session.option) && errands != null)
			errands.accept("altar", true);
	}

	/**
	 * Work with nothing clicked - a knife on logs, a pestle on a herb - opens
	 * on its first drop. The target is the tile in front of the player, for
	 * the seat to stand off; nothing in the world can deplete it.
	 */
	void startStanding(Skill skill, int now)
	{
		var local = client.getLocalPlayer();
		var here = local == null ? null : local.getWorldLocation();
		if (here == null || !config.keepsCompany() || elsewhere())
			return;
		double radians = (local.getCurrentOrientation() / 2048.0) * 2.0 * PI;
		var front = here.dx((int) round(-sin(radians)))
			.dy((int) round(-cos(radians)));
		var opened = new WorkSession("", skill.getName().toLowerCase(Locale.ROOT), "", 0,
			front, front, null, here, now);
		opened.standing = true;
		open(opened, now);
	}

	/** The session begins: whatever else had the feet lets go. */
	void open(WorkSession opened, int now)
	{
		if (session != null)
			end(false, now - session.startTick >= BEAT_AFTER_TICKS, true);
		// A seat kept for a bank trip, a trap watched, a fire visited: let go,
		// the new work seats itself - except a gatherer's seat that is still a
		// seat for the new work, which is carried over and re-seated where it
		// is, without a step.
		var carried = bankTrip ? seat : null;
		dropTheTrap(true);
		dropTheFireLine(true);
		letGoOfTheNotes();
		session = opened;
		boolean workCarried = carried != null && alongside != null && alongside.from.equals(carried)
			&& !carried.equals(opened.workSpot) && stillLive(alongside);
		boolean carry = carried != null && modeFor(opened.workSpot) == GATHERING
			&& carried.equals(follower.getStayTile())
			&& (workCarried || stillASeat(opened.workSpot, opened.targetTile, opened.targetMax,
				reservedTiles(), carried));
		if (carry)
		{
			bankTrip = false;
			bankTripConfirmed = false;
			if (!workCarried)
				alongside = null;
		}
		else
			dropTheBankTrip(true);
		if (graceTicks > 0)
		{
			if (graceActivity != null && opened.activity != null
				&& !graceActivity.equals(opened.activity))
				// Different work: the old tool goes back before the new one.
				dropTheGrace(true);
			else
			{
				// The next tree along: the tool simply stays in the hand.
				graceTicks = 0;
				graceActivity = null;
			}
		}
		seat = carry ? carried : null;
		reseat = carry;
		refusedTool = 0;
		refusedHat = 0;
		seatDueTick = now + seatAfter();
		company = new KeepingCompany(client, follower, config, hands, borrow, random);
		company.begin(now);
		company.aimAt(faceTile(), session.activity, modeFor(session.workSpot), now);
	}

	/**
	 * Ends the session, however it ended.
	 *
	 * @param silent an abort: nothing played, the tool straight back
	 * @param withBeat a long session's send-off, when not silent
	 * @param announce whether the rules hear of it; a logout has nobody to tell
	 */
	void end(boolean silent, boolean withBeat, boolean announce)
	{
		dropTheJoin();
		var done = session;
		session = null;
		reseat = false;
		bagEdge = null;
		// A sitting follower stands first, on a proper end; an abort simply
		// lets the pose go.
		int standUp = company.end(!silent);
		// Walking to the next tree is not the end of the work, so the tool
		// stays in the hand while the player repositions and the send-off
		// waits to see whether they start again. Only an abort - a fight, a
		// plane change, somebody else taking the follower - puts it straight
		// back, because then there is nobody to hand it to.
		// The patch inspector writes its notes at the end, and the scroll and
		// a tool share the one hand, so that end really is the end.
		boolean notes = !silent && "farming".equals(done.activity)
			&& seat != null && !bankTrip && follower.isStaying();
		boolean carry = !silent && !notes && borrow.isBorrowing();
		if (carry)
		{
			graceTicks = TOOL_GRACE_TICKS;
			graceActivity = done.activity;
			beatWait = 0;
		}
		boolean beat = !silent && !carry && withBeat && borrow.isBorrowing();
		if (beat)
		{
			// The bow is to the player, not to the tree.
			var here = playerTile();
			if (seat != null && here != null)
				follower.setStayFaceTile(here);
			borrow.giveBack(true, standUp);
		}
		else
		{
			if (!carry)
				borrow.abort();
			if (standUp > 0)
				follower.playAnimation(standUp);
		}
		if (seat != null && !bankTrip)
		{
			seat = null;
			alongside = null;
			// The patch inspector's notes, at the end and only then.
			int note = notes ? company.endNote() : 0;
			endNoteOut = note > 0;
			if (beat || standUp > 0 || note > 0)
				// Movement would cut the bow off; the feet stay a few ticks,
				// and a few more when the stand-up comes first.
				// RELEASE_HOLD_TICKS: Ticks the seat is kept after the beat so walking does not cut it.
				releaseTicks = 3 /* RELEASE_HOLD_TICKS */ + note
					+ (standUp > 0 ? STAND_UP_TICKS : 0);
			else
				// Only when the seat is still ours: a thrall or the spectator
				// that just took the feet must not be released by us.
				letGo();
		}
		if (announce)
			dispatch.accept(TriggerEvent.workEnd(done.activity, done.targetName));
	}

	/**
	 * The kept tool, between sessions. It goes back when the player turns
	 * out to have finished rather than moved along, and straight back if
	 * anything else claims the follower first.
	 */
	void watchTheGrace()
	{
		if (elsewhere())
		{
			dropTheGrace(false);
			return;
		}
		if (bankTrip)
			// A trip to the bank is the most obvious not-finished there is:
			// the seat is being kept, and so is what is in the hand.
			return;
		if (--graceTicks > 0)
			return;
		// A send-off that is owed waits for somewhere to land: a player still
		// on the move would cancel the bow and be handed the tool back with
		// nothing to see. It does not wait for ever.
		if (owedTheSendOff() && !follower.isSettled() && beatWait < BEAT_WAIT_TICKS)
		{
			beatWait++;
			graceTicks = 1;
			return;
		}
		dropTheGrace(true);
	}

	/**
	 * Ground that has turned into scenery under a parked follower. Lighting
	 * a line of fires is the way to see it: the follower is given a tile, a
	 * fire goes up on it, and nothing moves it off, because a stay persists
	 * by design and the follower is not the one who lit it. Only the spots
	 * the company chose are second-guessed here; a follower standing
	 * somewhere odd of its own accord is usually there on purpose.
	 */
	void watchTheGroundUnderfoot(int now)
	{
		if (fireSeat != null && !follower.goodGround(fireSeat))
			dropTheFireLine(true);
		if (trapSeat != null && !follower.goodGround(trapSeat))
			dropTheTrap(true);
		if (seat == null || follower.goodGround(seat))
			return;
		// Chosen again from scratch rather than nudged one tile: whatever went
		// up there - a wall, a fire - may well have taken the neighbours too.
		seat = null;
		reseat = false;
		seatDueTick = now + 1;
		// Off it now, in case there is nowhere better to be given.
		letGo();
	}

	/** Whether a kept tool has earned its bow on the way back. */
	boolean owedTheSendOff()
	{
		return borrow.isBorrowing()
			&& client.getTickCount() - stintStart >= BEAT_AFTER_TICKS;
	}

	/**
	 * Gives a kept tool back.
	 *
	 * @param earned whether the send-off is allowed: the work really
	 * finished, rather than being interrupted. It still only plays for a
	 * stint long enough to deserve it, and only when the follower is
	 * standing still enough for it to be seen.
	 */
	void dropTheGrace(boolean earned)
	{
		graceTicks = 0;
		graceActivity = null;
		if (!borrow.isBorrowing())
			return;
		var here = playerTile();
		if (earned && owedTheSendOff() && follower.isSettled() && here != null)
		{
			// BEAT_GLANCE_MS: The look at the player that goes with the send-off, off the seat.
			follower.glanceAt(here, 1800 /* BEAT_GLANCE_MS */);
			borrow.giveBack(true);
		}
		else
			borrow.abort();
	}

	void depleted()
	{
		if (session.depleted)
			return;
		session.depleted = true;
		dispatch.accept(TriggerEvent.targetDepleted(session.targetName));

		// Where the next one is: the nearest of the same name that is not
		// this one. A moved spot may not have turned up yet; npcSpawned
		// hands it over when it does.
		WorldPoint next;
		if ("fishing".equals(session.activity))
			next = nearestSpot();
		else
			// NEXT_TARGET_TILES: How far the next same-name target is looked for after a depletion.
			next = nearestObject(client, session.targetTile, session.targetTile, 10 /* NEXT_TARGET_TILES */,
				session.targetName::equals, session.targetTile, session.targetMax);
		var here = playerTile();
		var at = work();
		if (at != null && !at.min.equals(session.targetTile))
			// Working its own, next along: it keeps at it.
			return;
		company.depleted(session.activity, client.getTickCount() - session.targetSinceTick,
			next, here, client.getTickCount());
	}

	/** The notes taken at a session's end, put away once the feet are let go. */
	void letGoOfTheNotes()
	{
		if (endNoteOut)
		{
			endNoteOut = false;
			company.putScrollAway();
		}
	}

	// ------------------------------------------------------------------ trap

	/**
	 * An object on the player's tile a moment after the lay animation is the
	 * trap. The follower stands two tiles off it, facing it, and stays while
	 * the player goes about their other traps - the first laid, only.
	 */
	boolean maybeTheTrap(int id, WorldPoint min, WorldPoint max)
	{
		int now = client.getTickCount();
		WorldPoint here = playerTile(),
			laidAt = layTile != null ? layTile : here;
		if (now - layTick > 3 /* LAY_SETTLE_TICKS */ || here == null || laidAt == null
			|| !covers(min, max, laidAt))
			return false;
		layTick = -1000;
		if (trapSeat != null)
		{
			// Another trap of the run: the run goes on. Only a trap laid where
			// the follower stands moves it, and then once, still by the first.
			trapUntil = now + TRAP_WATCH_TICKS;
			if (covers(min, max, trapSeat))
			{
				// Not reading on the move, and not across the traps: the nearest.
				putTheTrapNotesAway();
				var from = follower.getWorldLocation();
				var ring = ring(trapTile, trapTile, TRAP_WATCH_TILES, here.getPlane());
				if (from != null)
					ring.sort(nearestTo(from));
				for (var candidate : ring)
				{
					if (!candidate.equals(here) && !covers(min, max, candidate)
						&& follower.goodGround(candidate) && follower.arrivesAt(candidate)
						&& follower.stayAt(candidate))
					{
						trapSeat = candidate;
						follower.setStayFaceTile(trapTile);
						break;
					}
				}
			}
			return true;
		}
		if (bankTrip || fireSeat != null || elsewhere())
			return true;
		var from = follower.getWorldLocation();
		var ring = ring(min, max, TRAP_WATCH_TILES, here.getPlane());
		ring.removeIf(here::equals);
		if (from != null)
			ring.sort(stepsFrom(from));
		for (var candidate : ring)
		{
			if (follower.goodGround(candidate) && follower.stayAt(candidate))
			{
				trapTile = min;
				trapId = id;
				trapSeat = candidate;
				trapUntil = now + TRAP_WATCH_TICKS;
				trapLookTicks = 0;
				trapReading = false;
				trapReadAt = now + jitter(WORK_STRETCH_TICKS,
					WORK_STRETCH_SPREAD);
				follower.setStayFaceTile(min);
				return true;
			}
		}
		return true;
	}

	/**
	 * Every tick the trap run is watched, from the one seat by its first
	 * trap: the player more than ten tiles off it, two minutes with no trap
	 * laid and no catch, a fight, or the leash snapping (the stay is simply
	 * gone) end it. Play request: park it, not a walk from trap to trap. The
	 * glance at the player when the trap changes runs down here, back to the
	 * trap, and now and then the notes come out.
	 */
	void watchTheTrap(int now, WorldPoint here)
	{
		if (trapSeat == null)
			return;
		if (!follower.isStaying() || !follower.isSpawned() || feetTaken.getAsBoolean())
		{
			dropTheTrap(false);
			return;
		}
		if (inCombat.getAsBoolean() || here.getPlane() != trapTile.getPlane())
		{
			dropTheTrap(true);
			return;
		}
		if (now >= trapUntil || here.distanceTo(trapTile) > TRAP_RUN_TILES)
		{
			dropTheTrap(true);
			return;
		}
		if (trapLookTicks > 0 && --trapLookTicks == 0)
			follower.setStayFaceTile(trapTile);
		readAtTheTraps(now);
	}

	/** Mostly watching the traps; now and then the notes, where it stands. */
	void readAtTheTraps(int now)
	{
		if (excused)
		{
			// A moment has the follower: not reading through it.
			putTheTrapNotesAway();
			return;
		}
		if (trapReading)
		{
			if (now >= trapReadUntil)
			{
				putTheTrapNotesAway();
				trapReadAt = now + jitter(WORK_STRETCH_TICKS,
					WORK_STRETCH_SPREAD);
			}
			return;
		}
		if (now < trapReadAt || trapLookTicks > 0 || hands.isHolding() || !follower.isSettled()
			|| !trapSeat.equals(follower.getWorldLocation()) || follower.getPoseOverride() != 0)
			return;
		hands.hold(ErrandController.QUILL_PROP, ErrandController.SCROLL_PROP);
		if (hands.isHolding())
		{
			follower.setPoseOverride(ErrandController.WRITE_SCROLL_POSE);
			trapReading = true;
			trapReadUntil = now + jitter(WORK_BREAK_TICKS,
				WORK_BREAK_SPREAD);
		}
	}

	void putTheTrapNotesAway()
	{
		if (!trapReading)
			return;
		trapReading = false;
		follower.clearPoseOverride(ErrandController.WRITE_SCROLL_POSE);
		hands.release();
	}

	int jitter(int base, int spread)
	{
		return base + random.nextInt(2 * spread + 1) - spread;
	}

	/** @param release whether to hand the feet back, when they are still ours */
	void dropTheTrap(boolean release)
	{
		if (trapSeat == null)
			return;
		putTheTrapNotesAway();
		trapSeat = null;
		trapTile = null;
		trapLookTicks = 0;
		if (release)
			letGo();
	}

	// ------------------------------------------------------------ joining in

	/** Where the follower went so it could copy the work from arm's reach. */
	WorldPoint joinTile;

	/** The tick the walk over is given until before the copy is given up. */
	int joinBy;

	/** How long the walk over to copy the work is given. */
	static final int JOIN_ARRIVAL_PATIENCE = 10;

	/**
	 * The follower wants to copy what the player is doing. Whether it may
	 * start now, and a walk over so that it can when it may not.
	 *
	 * <p>The seat is placed against the PLAYER - two tiles off their flank
	 * and off the line to the work - so a copy made from the seat is an axe
	 * swung at open air two tiles from the trunk. Play report: "sometimes
	 * the follower will chop a tree but not be up against the tree". The
	 * copying is done from arm's reach of the work or not at all, and the
	 * way to get there is the same short trip it already makes to warm its
	 * hands at a fire.
	 *
	 * <p>With no session there is nothing to stand against, so there is no
	 * copy: a swing with no tree in front of it is the very thing this is
	 * here to stop.
	 *
	 * @return true to copy now, false to wait for {@link #joinedIn()}
	 */
	boolean joinIn()
	{
		// A stump or an emptied rock is not the work any more; and a moment
		// that has excused the seat has the feet, and the facing, for now.
		if (session == null || !mirrorsFromHere() || session.depleted || excused
			|| work() != null)
			// Working alongside already: the copy is its own, not a walk over.
			return false;
		var at = follower.getWorldLocation();
		if (joinTile == null && at != null && at.equals(follower.getStayTile())
			&& workableFrom(at))
		{
			// The seat is square on to the work already, as an anvil's is:
			// the copy is made from it, once it has turned to the work. Not
			// straight away - the new facing is only taken up on the next
			// frame - so the copy waits a tick for joinedIn like any other.
			joinTile = at;
			joinBy = client.getTickCount() + JOIN_ARRIVAL_PATIENCE;
			faceTheWork();
			putTheParkedScrollAway();
			return false;
		}
		startTheJoin();
		return false;
	}

	/**
	 * Whether the copy may be made from this tile. Standing work - a knife
	 * on logs - has nothing in the world to stand against, so from the seat
	 * and nowhere else; everything else from a tile the work could be done
	 * from.
	 */
	boolean workableFrom(WorldPoint at)
	{
		return session.standing ? at.equals(seat) : againstTheWork(at);
	}

	/** Whether the follower is on its way over to copy the work. */
	boolean joiningIn()
	{
		return joinTile != null;
	}

	/**
	 * Whether it has got there, so the copying may start: stopped dead on
	 * the tile it was sent to, not wherever closest approach left it, and
	 * turned to the work.
	 */
	boolean joinedIn()
	{
		return stillJoined() && follower.isSettled() && follower.isTurned();
	}

	/**
	 * Whether the follower is still where the copy is made from. Anything
	 * that has moved it since - a moment, a nudge, the session ending - and
	 * the copy is being made from somewhere else.
	 */
	boolean stillJoined()
	{
		return joinTile != null && session != null
			&& joinTile.equals(follower.getWorldLocation())
			&& joinTile.equals(follower.getStayTile());
	}

	/**
	 * The copy is over, or was never going to happen: back to the seat, which
	 * is still on the books and is retaken on the next tick.
	 */
	void dropTheJoin()
	{
		if (joinTile == null)
			return;
		boolean ours = joinTile.equals(follower.getStayTile());
		joinTile = null;
		joinBy = 0;
		if (!ours || feetTaken.getAsBoolean() || excused)
			// Somebody else moved it on: their feet now, not ours to let go.
			return;
		// Straight back to the seat. Let go instead, the follower set off
		// after the player for the tick before the seat was retaken.
		if (seat != null && follower.stayAt(seat))
			follower.setStayFaceTile(faceTile());
		else
			follower.resumeFollowing();
	}

	/**
	 * Off to the work. Refused quietly when anything else has the feet: the
	 * copying is a flourish, and a flourish does not interrupt an errand, a
	 * trap, a fire visit or a bank trip.
	 */
	void startTheJoin()
	{
		if (joinTile != null || seat == null || bankTrip || fireSeat != null
			|| trapSeat != null || elsewhere() || session.targetTile == null || session.standing)
			return;
		WorldPoint player = playerTile(),
			from = follower.getWorldLocation();
		// Square on, as the player works it: a corner is not within reach
		// of anything in the game, so a swing from one misses the trunk.
		var beside = ring(session.targetTile, session.targetMax, 1,
			session.targetTile.getPlane());
		beside.removeIf(c -> c.equals(player) || !againstTheWork(c));
		if (from != null)
			beside.sort(nearestTo(from));
		for (var candidate : beside)
		{
			// Closest approach stops short - water, a wall - and a copy from
			// short of the tile is a copy from the wrong one. Asked before
			// the walk, so a tile turned down is not walked to.
			if (!follower.goodGround(candidate) || !follower.arrivesAt(candidate)
				|| !follower.stayAt(candidate))
				continue;
			joinTile = candidate;
			faceTheWork();
			putTheParkedScrollAway();
			int walk = from == null ? JOIN_ARRIVAL_PATIENCE : from.distanceTo(candidate);
			joinBy = client.getTickCount() + walk + JOIN_ARRIVAL_PATIENCE;
			return;
		}
	}

	/**
	 * A gatherer's parked scroll down and the tool back in the hand: the copy
	 * swings the tool. Only a gatherer's - the anvil's notes are the seat's
	 * for the whole session, and put away they did not come back.
	 */
	void putTheParkedScrollAway()
	{
		if (modeFor(session.workSpot) == GATHERING)
			company.putScrollAway();
	}

	/** Faces the middle of the work's footprint, exactly, as the player does. */
	void faceTheWork()
	{
		follower.setStayFaceArea(session.targetTile, session.targetMax);
	}

	/** Gave up on the walk over, or something took the feet while it walked. */
	void watchTheJoin(int now)
	{
		if (joinTile == null)
			return;
		if (joinedIn())
			// Got there: the walk's patience is spent, and the copy runs on.
			joinBy = 0;
		if (session == null || elsewhere() || excused || session.depleted
			|| !joinTile.equals(follower.getStayTile())
			|| !follower.goodGround(joinTile) || !workableFrom(joinTile)
			|| (joinBy > 0 && now > joinBy && !joinedIn()))
			dropTheJoin();
	}

	/**
	 * Whether the work could be done from this tile: square on to the
	 * footprint, with no fence along the edge between. A range worked from
	 * one side only (see {@link #ONE_SIDED}) is worked from the player's
	 * side, the side that is open, as a second cook would stand.
	 */
	boolean againstTheWork(WorldPoint at)
	{
		if (at == null || session == null || session.targetTile == null)
			return false;
		WorldPoint min = session.targetTile,
			max = session.targetMax;
		if (at.getPlane() != min.getPlane() || !squareOn(min, max, at) || fenced(min, max, at))
			return false;
		boolean xIn = at.getX() >= min.getX() && at.getX() <= max.getX();
		var player = session.workSpot;
		return !ONE_SIDED.contains(session.targetId)
			|| (at.getX() == player.getX() && !xIn) || (at.getY() == player.getY() && xIn);
	}

	/**
	 * Whether a tile touches one edge of a footprint square on: beside it,
	 * not on it and not off a corner. The game works everything from these
	 * tiles and no others - a tree, a rock, an anvil, a range.
	 */
	static boolean squareOn(WorldPoint min, WorldPoint max, WorldPoint at)
	{
		boolean xIn = at.getX() >= min.getX() && at.getX() <= max.getX(),
			yIn = at.getY() >= min.getY() && at.getY() <= max.getY(),
			xNext = at.getX() == min.getX() - 1 || at.getX() == max.getX() + 1,
			yNext = at.getY() == min.getY() - 1 || at.getY() == max.getY() + 1;
		return (xIn && yNext) || (yIn && xNext);
	}

	// -------------------------------------------------------- work alongside

	/**
	 * What the follower works, alongside the player: the player's own tree,
	 * rock or spot when there is room at it, else the next one along of the
	 * same kind. Play request: at Motherlode, where the player's vein leaves
	 * no room, "look like they are harvesting some other ore vein". A vein
	 * is a wall, worked from the one tile across it.
	 */
	@RequiredArgsConstructor
	static class Alongside
	{
		final int id;
		/** The fishing spot, or null for scenery. */
		final NPC npc;
		final boolean wall;
		final WorldPoint min,
			max;
		/** The tile it works from, which is its seat. */
		final WorldPoint from;
		/** A patch: the same patch while it stands, whatever its crop is called now. */
		final boolean anyState;
	}

	Alongside alongside;

	/** The id last seen and found not to loop, so it is not asked about every tick. */
	int notAWorkPose;

	/** Its work, while it is seated at it; null when the seat is only a seat. */
	Alongside work()
	{
		return alongside != null && seat != null && alongside.from.equals(seat) ? alongside : null;
	}

	boolean gathering()
	{
		return session != null && ("mining".equals(session.activity)
			|| "woodcutting".equals(session.activity) || "fishing".equals(session.activity));
	}

	/**
	 * Whether it works alongside rather than sits: gathering, with the work
	 * seen and the tool in hand. A target called just "Rocks" is an emptied
	 * rock, which keeps its "Mine" in the cache; nothing to work there.
	 */
	boolean worksAlongside()
	{
		if (session == null || session.standing || session.workPose <= 0)
			return false;
		if (farmingPatch())
			// Bare hands or the tool the work wants; borrowed as it goes.
			return config.borrowsTools();
		return gathering() && !"Rocks".equals(session.targetName) && borrow.isHolding();
	}

	/**
	 * Whether it is working the patch with bare hands just now - picking - so
	 * its own weapon and shield are not left on through the arms.
	 */
	boolean worksBareHanded()
	{
		return work() != null && farmingPatch() && Borrow.farmingTool(session.workPose) == 0;
	}

	/** A visit to a patch, which is worked alongside at the patch itself. */
	boolean farmingPatch()
	{
		return session != null && "farming".equals(session.activity)
			&& modeFor(session.workSpot) == PATCH;
	}

	/**
	 * The work is the player's LOOPING animation - a swing of the axe, a cast -
	 * not whatever they played last, which can be a bite to eat. The first
	 * one seen while only seated moves it to the work.
	 */
	void noteTheWorkPose(int animationId, int now)
	{
		boolean farming = "farming".equals(session.activity);
		if (!gathering() && !farming || animationId == session.workPose
			|| animationId == notAWorkPose)
			return;
		if (farming ? !Borrow.farmingWork(animationId) : !loops(animationId))
		{
			notAWorkPose = animationId;
			return;
		}
		boolean first = session.workPose == 0;
		session.workPose = animationId;
		if (first && seat != null && work() == null)
		{
			reseat = true;
			seatDueTick = now;
		}
	}

	/** Whether an animation is an authored loop: the work, not a one-off. */
	boolean loops(int animationId)
	{
		var animation = client.loadAnimation(animationId);
		return animation != null && animation.getFrameStep() >= 0;
	}

	/** The company seated the work's way when it has work, the seat's way when not. */
	void seatTheCompany(int now)
	{
		var at = work();
		if (at != null)
		{
			follower.setStayFaceArea(at.min, at.max);
			company.seatedAtWork(seat, faceTile(), at.min, at.max, now);
		}
		else
		{
			follower.setStayFaceTile(faceTile());
			company.seated(seat, faceTile());
		}
	}

	/** Its work went: the swing stops, a look, and a choice again a moment later. */
	void loseTheWork(int now)
	{
		alongside = null;
		company.workGone(now);
		reseat = true;
		seatDueTick = now + WORK_GONE_TICKS;
	}

	/**
	 * Somewhere to work from: the player's own target first, then the next
	 * one along, near the player and best two tiles off them, a tile it is
	 * already on before any it would walk to. Only a few are asked of the
	 * pathing, and only one it arrives on without a long way round.
	 */
	Alongside chooseAlongside(WorldPoint player)
	{
		var view = client.getTopLevelWorldView();
		var at = follower.getWorldLocation();
		if (view == null || at == null)
			return null;
		Comparator<Alongside> byPlace = Comparator
			.comparingInt((Alongside a) -> alongsideRank(a.from, player))
			.thenComparingInt(a -> square(a.from, at));
		var ranked = ownWork();
		ranked.sort(byPlace);
		List<Alongside> others = farmingPatch() ? new ArrayList<>() : neighbours(view, player);
		others.sort(byPlace);
		ranked.addAll(others);
		var taken = othersTiles(view);
		ranked.removeIf(a -> a.from.equals(player) || taken.contains(a.from)
			|| a.from.getPlane() != player.getPlane() || a.from.distanceTo(player) > ALONGSIDE_TILES);
		// A stable sort: one it already stands on first, the order otherwise kept.
		ranked.sort(Comparator.comparingInt(a -> a.from.equals(at) ? 0 : 1));
		Set<WorldPoint> asked = new HashSet<>();
		for (var a : ranked)
		{
			if (!asked.add(a.from))
				continue;
			// ALONGSIDE_PATH_ASKS: Work tiles asked of the pathing, best first, before it settles for a seat.
			if (asked.size() > 6 /* ALONGSIDE_PATH_ASKS */)
				break;
			int steps = follower.stepsTo(a.from);
			// ALONGSIDE_DETOUR_STEPS: Steps beyond the straight line it will walk to reach one.
			if (steps >= 0 && steps <= at.distanceTo(a.from) + 4 /* ALONGSIDE_DETOUR_STEPS */
				&& follower.stayAt(a.from))
				return a;
		}
		return null;
	}

	/** Best two tiles off the player, then further; beside them last of all. */
	static int alongsideRank(WorldPoint tile, WorldPoint player)
	{
		int distance = tile.distanceTo(player);
		return distance >= 2 ? distance : ALONGSIDE_TILES + 1;
	}

	/**
	 * The work tiles of the player's own target, while it stands. Never a
	 * vein's: its one work tile, across its wall, is the player's own.
	 */
	List<Alongside> ownWork()
	{
		List<Alongside> found = new ArrayList<>();
		if (session.depleted || session.targetTile == null)
			return found;
		WorldPoint min = session.targetTile,
			max = session.targetMax;
		boolean patch = farmingPatch();
		if (!stillLive(new Alongside(session.targetId, session.targetNpc, false, min, max, min,
			patch)))
			// Felled, emptied or moved on before any event said so - or a
			// wall, which this is not asked about.
			return found;
		for (var c : ring(min, max, 1, min.getPlane()))
		{
			if (follower.goodGround(c) && againstTheWork(c))
				found.add(new Alongside(session.targetId, session.targetNpc, false, min, max, c,
					patch));
		}
		return found;
	}

	/**
	 * The live ones of the same kind near the player, and the tiles each is
	 * worked from: trees and rocks by their footprint, veins across their
	 * wall, spots by the NPC. Not the player's own target.
	 */
	List<Alongside> neighbours(WorldView view, WorldPoint player)
	{
		List<Alongside> found = new ArrayList<>();
		int reach = ALONGSIDE_TILES + 1;
		if (session.targetNpc != null)
		{
			for (var npc : sameNameNpcs(view, player, reach))
			{
				var at = npc.getWorldLocation();
				if (!liveNpc(npc))
					continue;
				var far = farCorner(npc, at);
				for (var c : workTilesOf(at, far, npc.getId()))
					found.add(new Alongside(npc.getId(), npc, false, at, far, c, false));
			}
			return found;
		}
		int plane = player.getPlane();
		WorldPoint min = session.targetTile,
			max = session.targetMax;
		for (int x = player.getX() - reach; x <= player.getX() + reach; x++)
		{
			for (int y = player.getY() - reach; y <= player.getY() + reach; y++)
			{
				var tile = sceneTile(view, x, y, plane);
				if (tile == null)
					continue;
				var here = new WorldPoint(x, y, plane);
				var wall = tile.getWallObject();
				if (wall != null && !covers(min, max, here) && liveKind(resolved(wall.getId())))
				{
					var from = acrossTheWall(here, wall.getOrientationA());
					if (from != null && follower.goodGround(from))
						found.add(new Alongside(wall.getId(), null, true, here, here, from, false));
				}
				for (var object : tile.getGameObjects())
				{
					if (object == null)
						continue;
					var footprint = footprintOf(view, object);
					// Once per object, on its south-west tile; never the player's own.
					if (footprint[0] == null || !footprint[0].equals(here)
						|| covers(footprint[0], footprint[1], min)
						|| !liveKind(resolved(object.getId())))
						continue;
					for (var c : workTilesOf(footprint[0], footprint[1], object.getId()))
						found.add(new Alongside(object.getId(), null, false, footprint[0],
							footprint[1], c, false));
				}
			}
		}
		return found;
	}

	/** Square on to a footprint, ground to stand on, no fence between. */
	List<WorldPoint> workTilesOf(WorldPoint min, WorldPoint max, int id)
	{
		List<WorldPoint> tiles = new ArrayList<>();
		if (ONE_SIDED.contains(id))
			// Worked from one side the client cannot tell: not a neighbour's.
			return tiles;
		for (var c : ring(min, max, 1, min.getPlane()))
		{
			if (squareOn(min, max, c) && follower.goodGround(c) && !fenced(min, max, c))
				tiles.add(c);
		}
		return tiles;
	}

	/** Whether a fence runs along the edge between a square-on tile and the footprint. */
	boolean fenced(WorldPoint min, WorldPoint max, WorldPoint c)
	{
		boolean xIn = c.getX() >= min.getX() && c.getX() <= max.getX();
		int dx = xIn ? 0 : c.getX() < min.getX() ? 1 : -1,
			dy = !xIn ? 0 : c.getY() < min.getY() ? 1 : -1;
		return follower.walledToward(c, dx, dy);
	}

	/**
	 * The tile a wall is worked from: across the edge it stands on. The wall's
	 * own edge flag is the vein itself, so it is not a fence here.
	 *
	 * @param orientationA 1 west, 2 north, 4 east, 8 south; anything else, none
	 */
	static WorldPoint acrossTheWall(WorldPoint wallTile, int orientationA)
	{
		switch (orientationA)
		{
			case 1:
				return wallTile.dx(-1);
			case 2:
				return wallTile.dy(1);
			case 4:
				return wallTile.dx(1);
			case 8:
				return wallTile.dy(-1);
			default:
				return null;
		}
	}

	/**
	 * The same kind as the player's work, and still to be worked: the same
	 * name AND the clicked option on offer. The name alone lets in a tree
	 * that is only scenery; the option alone lets in an emptied rock.
	 */
	boolean liveKind(ObjectComposition composition)
	{
		return composition != null && liveKind(composition.getName(), composition.getActions(),
			session.targetName, session.option);
	}

	static boolean liveKind(String name, String[] actions, String targetName, String option)
	{
		return name != null && !"Rocks".equals(targetName) && name.equals(targetName)
			&& offers(actions, option);
	}

	boolean liveNpc(NPC npc)
	{
		var composition = npc.getTransformedComposition() != null
			? npc.getTransformedComposition() : npc.getComposition();
		return composition != null && session.targetName.equals(npc.getName())
			&& offers(composition.getActions(), session.option);
	}

	static boolean offers(String[] actions, String option)
	{
		if (actions == null || option == null)
			return false;
		for (String action : actions)
		{
			if (action != null && plainOption(action).equalsIgnoreCase(option))
				return true;
		}
		return false;
	}

	/** A definition as it stands now: a multiloc's current state, not its base. */
	ObjectComposition resolved(int id)
	{
		var composition = client.getObjectDefinition(id);
		if (composition != null && composition.getImpostorIds() != null)
		{
			try
			{
				return composition.getImpostor();
			}
			catch (RuntimeException e)
			{
				return null;
			}
		}
		return composition;
	}

	/** Whether what it works is still there, and still to be worked. */
	boolean stillLive(Alongside a)
	{
		if (a.npc != null)
			return a.min.equals(a.npc.getWorldLocation()) && liveNpc(a.npc);
		var tile = sceneTile(client.getTopLevelWorldView(), a.min.getX(), a.min.getY(),
			a.min.getPlane());
		if (tile == null)
			return false;
		if (a.wall)
		{
			var wall = tile.getWallObject();
			return wall != null && wall.getId() == a.id && liveKind(resolved(a.id));
		}
		for (var object : tile.getGameObjects())
		{
			if (object != null && object.getId() == a.id)
				return a.anyState || liveKind(resolved(a.id));
		}
		return false;
	}

	/** The scene's tile at a world tile, or null off the loaded scene. */
	static Tile sceneTile(WorldView view, int x, int y, int plane)
	{
		Tile[][][] tiles = view == null || view.getScene() == null ? null : view.getScene().getTiles();
		if (tiles == null || plane < 0 || plane >= tiles.length)
			return null;
		int sx = x - view.getBaseX(),
			sy = y - view.getBaseY();
		return sx < 0 || sy < 0 || sx >= tiles[plane].length || sy >= tiles[plane][sx].length
			? null : tiles[plane][sx][sy];
	}

	/** Where the other players stand: their tiles are theirs. */
	Set<WorldPoint> othersTiles(WorldView view)
	{
		Set<WorldPoint> tiles = new HashSet<>();
		var local = client.getLocalPlayer();
		for (var other : view.players())
		{
			if (other != null && other != local && other.getWorldLocation() != null)
				tiles.add(other.getWorldLocation());
		}
		return tiles;
	}

	// ------------------------------------------------------------- fire line

	/**
	 * A fire lit within three tiles of where the player just stood is one
	 * of theirs. Every fourth, the follower walks over, warms its hands and
	 * catches up on foot - and one time in fifty, the errand's too-close gag
	 * instead. A brazier is not one of these, and neither is a campfire:
	 * this is the player's own line of fires, and that is what it is for.
	 * Where the follower may STAND is a separate question, and a campfire
	 * counts there - see {@link HotGround}.
	 */
	void maybeTheFire(int id, WorldPoint min, WorldPoint max)
	{
		if (previousHere == null || min.getPlane() != previousHere.getPlane()
			|| min.distanceTo(previousHere) > FIRE_LINE_TILES
			|| !"Fire".equals(ErrandController.objectName(client, id)))
			return;
		int now = client.getTickCount();
		// FIRE_LINE_LAPSE_TICKS: A fire this long after the last starts the count over.
		if (now - lastFireTick > 100 /* FIRE_LINE_LAPSE_TICKS */)
			fires = 0;
		lastFireTick = now;
		fires++;
		if (fires % FIRE_LINE_EVERY != 0 || fireSeat != null || trapSeat != null || bankTrip
			|| elsewhere())
			return;
		if (errands != null && random.nextInt(50 /* FIRE_GAG_ONE_IN */) == 0)
		{
			errands.accept("firedeath", false);
			return;
		}
		var from = follower.getWorldLocation();
		var beside = ring(min, max, 1, min.getPlane());
		beside.removeIf(c -> c.getX() != min.getX() && c.getY() != min.getY());
		if (from != null)
			beside.sort(stepsFrom(from));
		for (var candidate : beside)
		{
			// A line of fires is lit along a row, so the tile beside the new
			// one is very often the last one - and the nearest, which is how
			// the follower came to warm its hands from inside a fire.
			if (!follower.hot(candidate) && follower.stayAt(candidate))
			{
				fireSeat = candidate;
				follower.setStayFaceTile(min);
				int walk = from == null ? FIRE_LINE_TILES : from.distanceTo(candidate);
				fireWarmAt = now + walk + 2;
				fireLeaveAt = 0;
				return;
			}
		}
	}

	/** Once there, the hands to the flames; three seconds later, back on foot. */
	void watchTheFireLine(int now, WorldPoint here)
	{
		if (fireSeat == null)
			return;
		if (!follower.isStaying() || !follower.isSpawned() || feetTaken.getAsBoolean())
		{
			dropTheFireLine(false);
			return;
		}
		if (inCombat.getAsBoolean() || here.getPlane() != fireSeat.getPlane())
		{
			dropTheFireLine(true);
			return;
		}
		if (fireWarmAt > 0 && now >= fireWarmAt)
		{
			// Arrived, or near enough. The walk was timed by counting tiles,
			// which is a guess: a corner to round or a tile refused and the
			// hands went to the flames from halfway there. Waits for the
			// follower to actually stop, and gives up if it never does.
			// FIRE_ARRIVAL_PATIENCE: How long the walk to it is given before the visit is written off.
			if (!follower.isSettled() && now < fireWarmAt + 10 /* FIRE_ARRIVAL_PATIENCE */)
				return;
			fireWarmAt = 0;
			if (!follower.isSettled())
			{
				dropTheFireLine(true);
				return;
			}
			fireLeaveAt = now + FIRE_WARM_TICKS;
			follower.playAnimation(WARM_HANDS);
		}
		else if (fireLeaveAt > 0 && now >= fireLeaveAt)
			dropTheFireLine(true);
	}

	/** @param release whether to hand the feet back, when they are still ours */
	void dropTheFireLine(boolean release)
	{
		if (fireSeat == null)
			return;
		fireSeat = null;
		fireWarmAt = 0;
		fireLeaveAt = 0;
		if (release)
			letGo();
	}

	/** The tiles exactly so far from a footprint, nearest corner first. */
	static List<WorldPoint> ring(WorldPoint min, WorldPoint max, int radius, int plane)
	{
		var far = max == null ? min : max;
		List<WorldPoint> ring = new ArrayList<>();
		for (int x = min.getX() - radius; x <= far.getX() + radius; x++)
		{
			for (int y = min.getY() - radius; y <= far.getY() + radius; y++)
			{
				int cx = max(min.getX(), min(far.getX(), x)),
					cy = max(min.getY(), min(far.getY(), y));
				if (max(abs(x - cx), abs(y - cy)) == radius)
					ring.add(new WorldPoint(x, y, plane));
			}
		}
		return ring;
	}

	// ------------------------------------------------------------- bank trip

	/**
	 * The player has left the work with a bank near: the seat is kept, facing
	 * the way they went, for the walk there and - once the bank opens - for
	 * the trip, under a cap. No stay lines: the seat is still the company's.
	 *
	 * @param banking whether the bank is already open, which confirms it
	 */
	void holdForTheBankTrip(int now, WorldPoint here, boolean banking)
	{
		bankTrip = true;
		bankTripConfirmed = banking;
		bankTripAway = false;
		bankTripGathering = modeFor(here) == GATHERING;
		bankTripUntil = now + (banking ? BANK_TRIP_CAP_TICKS : BANK_WALK_TICKS);
		follower.setStayFaceTile(here);
	}

	/**
	 * Every tick the seat is kept without a session: the bank opening confirms
	 * the trip and starts the cap; the player back within three tiles, the
	 * cap, the walk lapsing unconfirmed, a fight, or the leash snapping (the
	 * stay is simply gone) all let it go.
	 */
	void watchTheBankTrip(int now, WorldPoint here)
	{
		if (!follower.isStaying() || !follower.isSpawned() || feetTaken.getAsBoolean()
			|| seat == null)
		{
			dropTheBankTrip(false);
			return;
		}
		if (inCombat.getAsBoolean())
		{
			dropTheBankTrip(true);
			return;
		}
		if (!bankTripConfirmed && bankOpen.getAsBoolean())
		{
			bankTripConfirmed = true;
			bankTripUntil = now + BANK_TRIP_CAP_TICKS;
			return;
		}
		boolean near = here.getPlane() == seat.getPlane()
			&& here.distanceTo(seat) <= WALK_OFF_TILES;
		if (!near)
			// A bank chest by the work: the player may never leave the
			// seat's side, and then there is no coming back to end it on.
			bankTripAway = true;
		if (near && bankTripAway && bankTripGathering)
			// Back from the bank to the same rock or tree: kept a moment for
			// the first swing, which carries the seat into the new session
			// (see open), rather than walked off to meet the player and
			// straight back to it six ticks later.
			bankTripUntil = min(bankTripUntil, now + BANK_BACK_TICKS);
		else if (near && bankTripAway)
		{
			dropTheBankTrip(true);
			return;
		}
		if (now >= bankTripUntil)
			dropTheBankTrip(true);
	}

	/** @param release whether to hand the feet back, when they are still ours */
	void dropTheBankTrip(boolean release)
	{
		if (!bankTrip)
			return;
		bankTrip = false;
		bankTripConfirmed = false;
		seat = null;
		alongside = null;
		if (release)
			letGo();
	}

	// ------------------------------------------------------------------ seat

	/**
	 * Takes the seat: two tiles off the player's flank, never on the line to
	 * the target, never on its footprint or a same-name neighbour's, facing
	 * the target. A tile the pathing refuses is skipped; when every candidate
	 * is refused the follower simply keeps following, and tries again later.
	 */
	void takeSeat(WorldPoint player)
	{
		var mode = modeFor(player);
		if ("prayer".equals(session.activity))
			// The kneel at the altar is the altar errand's; no seat.
			return;
		if ("thieving".equals(session.activity) && mode != STALL)
			// The thieving session already keeps the follower off at a
			// distance, and a seat at the mark's elbow is the opposite of
			// what that was tuned for. Only a stall earns the watch.
			return;
		if (worksAlongside())
		{
			// Keep at what it has while it is still there and near.
			var kept = work();
			if (kept != null && seat.equals(follower.getStayTile()) && follower.goodGround(seat)
				&& !seat.equals(player) && seat.distanceTo(player) <= ALONGSIDE_TILES
				&& stillLive(kept) && (!kept.anyState || kept.min.equals(session.targetTile)))
			{
				if (!company.isAtWork())
					seatTheCompany(client.getTickCount());
				return;
			}
			var chosen = chooseAlongside(player);
			if (chosen != null)
			{
				alongside = chosen;
				seat = chosen.from;
				company.watch(null);
				seatTheCompany(client.getTickCount());
				return;
			}
		}
		alongside = null;
		List<WorldPoint> candidates;
		// The nearest guard by name within the watch's reach.
		NPC guard = mode == STALL
			? nearestNpc(client, player, 15 /* GUARD_TILES */, Arrays.asList(GUARD_NAMES)::contains) : null;
		WorldPoint post = guard == null ? null : guard.getWorldLocation(),
			face = faceTile();
		if (post != null)
		{
			candidates = stallCandidates(player, post, session.targetTile, session.targetMax);
			face = post;
		}
		else
			// A stall with no guard worth watching still takes a seat: with
			// none taken the thieving drift owns the feet, and that was
			// written to keep moving rather than to settle anywhere.
			candidates = seatCandidates(player, session.targetTile, session.targetMax,
				reservedTiles(), variantFor(mode, session.activity));
		// The seat already held stays while it is still a seat for the next
		// rock or tree: the next one clicked from the same spot, or a step
		// along the wall to the next vein, is no reason to get up. Only for
		// the same kind of work - a seat taken before the drop named it is
		// the wrong shape for the work it turned out to be.
		var held = seat;
		if (mode == GATHERING && held != null
			&& held.equals(follower.getStayTile()) && follower.goodGround(held)
			&& stillASeat(player, session.targetTile, session.targetMax, reservedTiles(), held))
		{
			follower.setStayFaceTile(face);
			company.seated(seat, faceTile());
			return;
		}
		for (var candidate : candidates)
		{
			// The ground is asked BEFORE the walk, and so is whether the walk
			// arrives: the seat is written down here, and a seat recorded on
			// a tile the follower will not stand on is one it gets dropped
			// from and re-takes, tick after tick. Closest approach calls
			// stopping beside a rock, or at the water's edge, arriving - and
			// that was the follower walking between two tiles at the player's
			// side for as long as they mined. Asked without setting off, so a
			// tile turned down is not walked to either.
			if (!follower.goodGround(candidate) || !follower.arrivesAt(candidate)
				|| !follower.stayAt(candidate))
				continue;
			seat = candidate;
			follower.setStayFaceTile(face);
			company.watch(guard);
			company.seated(seat, faceTile());
			return;
		}
		if (held != null && held.equals(follower.getStayTile()) && !feetTaken.getAsBoolean())
			// The seat it had is no seat for this: off it, rather than left
			// standing there with nothing to say whose the stay is.
			follower.resumeFollowing();
		seat = null;
		company.unseated();
	}

	/**
	 * Whether a seat already held is still a fair one for new work: the
	 * rules a fresh seat is chosen by - off the footprint, off the player's
	 * tile and the straight line to the work, off a same-name neighbour -
	 * and near the player, no more than three tiles off. A tile beside them
	 * will do: the player stepping along the wall to the next vein is no
	 * reason to get up.
	 */
	static boolean stillASeat(WorldPoint player, WorldPoint min, WorldPoint max,
		Collection<WorldPoint> reserved, WorldPoint seat)
	{
		var far = max == null ? min : max;
		int nx = max(min.getX(), min(far.getX(), player.getX())),
			ny = max(min.getY(), min(far.getY(), player.getY())),
			distance = seat.distanceTo(player);
		return seat.getPlane() == player.getPlane() && distance >= 1
			// SEAT_KEEP_TILES: A gathering seat kept for the next target is no further than this from the player.
			&& distance <= 3 /* SEAT_KEEP_TILES */ && !covers(min, far, seat) && !reserved.contains(seat)
			&& !onTheLine(player, nx, ny, seat);
	}

	/**
	 * The shape of the seat the session's work wants; see the modes. A
	 * cook at a fire and a cook at a range sit differently, and so on.
	 */
	Mode modeFor(WorldPoint here)
	{
		if (session == null)
			return NONE;
		String name = session.targetName.toLowerCase(Locale.ROOT);
		switch (session.activity)
		{
			case "mining":
			case "woodcutting":
			case "fishing":
			case "hunter":
				return GATHERING;
			case "cooking":
				// Any of the fires, not just the one named "Fire": a Forestry
				// campfire is cooked at exactly the same way, and sitting it on
				// a range's flank instead was simply wrong.
				return HotGround.isFire(name) ? FIRESIDE
					: RANGE;
			case "smithing":
				return "anvil".equals(name) ? ANVIL : NONE;
			case "crafting":
				if (session.standing)
					return STANDING;
				return name.contains("wheel") || name.contains("loom")
					? WHEEL : NONE;
			case "fletching":
			case "herblore":
				return session.standing ? STANDING : NONE;
			case "runecraft":
				return ALTAR;
			case "thieving":
				return "Steal-from".equalsIgnoreCase(session.option)
					? STALL : NONE;
			case "farming":
				// A grown patch is named for its crop - "Ranarr weed", "Potato"
				// - so the patch is known by being a multiloc, which a crop in
				// a field is not.
				return name.contains("patch") || multiloc() ? PATCH
					: NONE;
			case "construction":
			{
				var view = client.getTopLevelWorldView();
				return view != null && view.isInstance()
					? FOREMAN : NONE;
			}
			case "firemaking":
				return here != null && COLD_REGIONS.contains(here.getRegionID())
					? BRAZIER : NONE;
			default:
				return NONE;
		}
	}

	/** Whether the target is scenery that changes as it grows: a patch. */
	boolean multiloc()
	{
		if (session.targetNpc != null)
			return false;
		var composition = client.getObjectDefinition(session.targetId);
		return composition != null && composition.getImpostorIds() != null;
	}

	/** The geometry {@link #seatCandidates} is asked for, by mode. */
	static String variantFor(Mode mode, String activity)
	{
		switch (mode)
		{
			case FIRESIDE:
			case ANVIL:
			case PATCH:
				return "across";
			case RANGE:
			case WHEEL:
				return "beside";
			case FOREMAN:
			case BRAZIER:
				return "ring";
			default:
				return activity;
		}
	}

	/**
	 * The stall watch: five tiles off the player toward the guard - four or
	 * six when five is refused, and one to either side of the five - never
	 * on the stall, never past the guard.
	 */
	static List<WorldPoint> stallCandidates(WorldPoint player, WorldPoint guard,
		WorldPoint min, WorldPoint max)
	{
		List<WorldPoint> candidates = new ArrayList<>();
		int gx = guard.getX() - player.getX(),
			gy = guard.getY() - player.getY(),
			length = max(abs(gx), abs(gy));
		if (length < 2)
			return candidates;
		int px = -Integer.signum(gy),
			py = Integer.signum(gx);
		for (int reach : new int[]{STALL_WATCH_TILES, STALL_WATCH_TILES - 1, STALL_WATCH_TILES + 1})
		{
			int along = min(reach, length - 1),
				x = player.getX() + (int) round(along * (double) gx / length),
				y = player.getY() + (int) round(along * (double) gy / length);
			int[][] offsets = reach == STALL_WATCH_TILES
				? new int[][]{{0, 0}, {px, py}, {-px, -py}} : new int[][]{{0, 0}};
			for (int[] offset : offsets)
			{
				var c = new WorldPoint(x + offset[0], y + offset[1], player.getPlane());
				if (!candidates.contains(c) && !covers(min, max, c) && !c.equals(player)
					&& !c.equals(guard) && c.distanceTo(player) >= 2
					&& c.distanceTo(player) < length)
					candidates.add(c);
			}
		}
		return candidates;
	}

	/** The middle of the footprint, so a big tree is looked at, not past. */
	WorldPoint faceTile()
	{
		WorldPoint min = session.targetTile,
			max = session.targetMax;
		return new WorldPoint((min.getX() + max.getX()) / 2, (min.getY() + max.getY()) / 2,
			min.getPlane());
	}

	/**
	 * The tiles a seat may take, in order of preference, from the pure
	 * geometry: the flank first, then a step back or forward off it, then
	 * behind the player. Never the footprint, never a reserved tile, never
	 * the player's own tile, never on the straight line to the target.
	 *
	 * <p>Shaped to the work: a miner's company sits diagonal-behind,
	 * two back, where the swing is in view and the rock is not; an angler's
	 * on the bank beside the spot, the nearest bank tile that is not the
	 * player's, so it looks at the water rather than at a back. Three more
	 * shapes by name: "across" (the far side of a fire, an anvil, a patch),
	 * "beside" (one tile along the side of a range or a wheel) and "ring"
	 * (three tiles off a hotspot or a brazier). Every shape falls back to
	 * the flank when the ground refuses it.
	 *
	 * @param min the target footprint's south-west tile
	 * @param max its far corner
	 * @param reserved tiles of the same-name neighbours the player may click next
	 */
	static List<WorldPoint> seatCandidates(WorldPoint player, WorldPoint min, WorldPoint max,
		Collection<WorldPoint> reserved, String activity)
	{
		// The direction to the nearest point of the footprint. A player
		// standing on it (a fire, a patch) has no direction; north will do.
		int nx = max(min.getX(), min(max.getX(), player.getX())),
			ny = max(min.getY(), min(max.getY(), player.getY())),
			dx = Integer.signum(nx - player.getX()),
			dy = Integer.signum(ny - player.getY());
		if (dx == 0 && dy == 0)
			dy = 1;
		int px = -dy,
			py = dx;

		Set<WorldPoint> avoid = new HashSet<>(reserved);
		List<WorldPoint> candidates = new ArrayList<>();
		Predicate<WorldPoint> allowed = c -> !candidates.contains(c) && !avoid.contains(c)
			&& !covers(min, max, c) && !c.equals(player) && !onTheLine(player, nx, ny, c)
			&& c.distanceTo(player) >= 2;

		if ("across".equals(activity))
		{
			// The player mirrored through the footprint: the tile just past
			// its far edge, then the two along that edge, then one further.
			int fx = player.getX() < min.getX() ? max.getX() + 1
				: player.getX() > max.getX() ? min.getX() - 1 : player.getX();
			int fy = player.getY() < min.getY() ? max.getY() + 1
				: player.getY() > max.getY() ? min.getY() - 1 : player.getY();
			if (fx == player.getX() && fy == player.getY())
				fy = max.getY() + 1;
			int[][] far = {{fx, fy}, {fx + px, fy + py}, {fx - px, fy - py}, {fx + dx, fy + dy}};
			for (int[] at : far)
			{
				var c = new WorldPoint(at[0], at[1], player.getPlane());
				if (allowed.test(c))
					candidates.add(c);
			}
		}
		else if ("beside".equals(activity) || "ring".equals(activity))
		{
			// Beside: the tiles that touch one of the footprint's edges square
			// on, not at a corner. Ring: three tiles off it. Nearest the player
			// first.
			boolean beside = "beside".equals(activity);
			for (var c : ring(min, max, beside ? 1 : 3, player.getPlane()))
			{
				if ((!beside || squareOn(min, max, c)) && allowed.test(c))
					candidates.add(c);
			}
			candidates.sort(nearestTo(player));
		}

		if ("fishing".equals(activity))
		{
			for (int x = min.getX() - 1; x <= max.getX() + 1; x++)
			{
				for (int y = min.getY() - 1; y <= max.getY() + 1; y++)
				{
					var c = new WorldPoint(x, y, player.getPlane());
					if (!avoid.contains(c) && !covers(min, max, c) && !c.equals(player)
						&& !onTheLine(player, nx, ny, c))
						candidates.add(c);
				}
			}
			// The bank tile nearest the player is the bank; the water side
			// of the spot is the ground's to refuse.
			candidates.sort(nearestTo(player));
			return candidates;
		}

		int[][] flank = {
			{2 * px, 2 * py}, {-2 * px, -2 * py},
			{2 * px - dx, 2 * py - dy}, {-2 * px - dx, -2 * py - dy},
			{2 * px + dx, 2 * py + dy}, {-2 * px + dx, -2 * py + dy},
		};
		int[][] behind = {
			{-2 * dx + px, -2 * dy + py}, {-2 * dx - px, -2 * dy - py}, {-2 * dx, -2 * dy},
		};
		boolean mining = "mining".equals(activity);
		int[][][] order = mining ? new int[][][]{behind, flank} : new int[][][]{flank, behind};
		for (int[][] group : order)
		{
			for (int[] offset : group)
			{
				// Every one of these is two tiles off the player or more.
				var c = player.dx(offset[0]).dy(offset[1]);
				if (allowed.test(c))
					candidates.add(c);
			}
		}
		return candidates;
	}

	/** Nearest a tile first, as the crow flies. */
	static Comparator<WorldPoint> nearestTo(WorldPoint to)
	{
		return Comparator.comparingInt(a -> square(a, to));
	}

	/** Nearest a tile first, in steps. */
	static Comparator<WorldPoint> stepsFrom(WorldPoint to)
	{
		return Comparator.comparingInt(a -> a.distanceTo(to));
	}

	static int square(WorldPoint a, WorldPoint b)
	{
		int dx = a.getX() - b.getX(),
			dy = a.getY() - b.getY();
		return dx * dx + dy * dy;
	}

	/** Whether the tile sits on the straight line from the player to the target. */
	static boolean onTheLine(WorldPoint player, int tx, int ty, WorldPoint c)
	{
		int ax = tx - player.getX(),
			ay = ty - player.getY(),
			bx = c.getX() - player.getX(),
			by = c.getY() - player.getY();
		boolean collinear = ax * by - ay * bx == 0;
		boolean between = bx * ax + by * ay >= 0
			&& bx * bx + by * by <= ax * ax + ay * ay;
		return collinear && between;
	}

	static boolean covers(WorldPoint min, WorldPoint max, WorldPoint tile)
	{
		if (min == null || tile == null)
			return false;
		var far = max == null ? min : max;
		return tile.getPlane() == min.getPlane()
			&& tile.getX() >= min.getX() && tile.getX() <= far.getX()
			&& tile.getY() >= min.getY() && tile.getY() <= far.getY();
	}

	/**
	 * The footprints of the target's same-name neighbours within two tiles:
	 * the next tree, the next rock, the next spot. One bounded look at the
	 * scene per seat, not per tick.
	 */
	List<WorldPoint> reservedTiles()
	{
		List<WorldPoint> reserved = new ArrayList<>();
		WorldPoint min = session.targetTile,
			max = session.targetMax;
		var view = client.getTopLevelWorldView();
		if (view == null || session.standing)
			return reserved;
		if (session.targetNpc != null)
		{
			for (var npc : sameNameNpcs(view, min, NEIGHBOUR_TILES))
			{
				var at = npc.getWorldLocation();
				addFootprint(reserved, at, farCorner(npc, at));
			}
			return reserved;
		}

		int plane = view.getPlane();
		for (int x = min.getX() - NEIGHBOUR_TILES; x <= max.getX() + NEIGHBOUR_TILES; x++)
		{
			for (int y = min.getY() - NEIGHBOUR_TILES; y <= max.getY() + NEIGHBOUR_TILES; y++)
			{
				var tile = sceneTile(view, x, y, plane);
				if (tile == null)
					continue;
				for (var object : tile.getGameObjects())
				{
					if (object == null)
						continue;
					var footprint = footprintOf(view, object);
					if (object.getId() == session.targetId
						&& covers(footprint[0], footprint[1], min))
						continue;
					String name = ErrandController.objectName(client, object.getId());
					if (session.targetName.equals(name))
						addFootprint(reserved, footprint[0], footprint[1]);
				}
			}
		}
		return reserved;
	}

	/** An object's tiles from its scene corners, or its own tile when it has none. */
	static WorldPoint[] footprintOf(WorldView view, GameObject object)
	{
		Point lo = object.getSceneMinLocation(),
			hi = object.getSceneMaxLocation();
		if (lo != null && hi != null)
		{
			return new WorldPoint[]{
				WorldPoint.fromScene(view, lo.getX(), lo.getY(), object.getPlane()),
				WorldPoint.fromScene(view, hi.getX(), hi.getY(), object.getPlane()),
			};
		}
		var at = object.getWorldLocation();
		return new WorldPoint[]{at, at};
	}

	static void addFootprint(List<WorldPoint> into, WorldPoint min, WorldPoint max)
	{
		if (min == null)
			return;
		var far = max == null ? min : max;
		for (int x = min.getX(); x <= far.getX(); x++)
		{
			for (int y = min.getY(); y <= far.getY(); y++)
				into.add(new WorldPoint(x, y, min.getPlane()));
		}
	}

	// ---------------------------------------------------------------- borrow

	/**
	 * Borrows the session's tool once the work is settled - at seat time, and
	 * again on a drop, since the drop may be what named the activity.
	 */
	void maybeBorrow()
	{
		if (session == null || !config.borrowsTools())
			return;
		var local = client.getLocalPlayer();
		if (local == null)
			return;
		// The tool in the hand and the outfit's hat on the head, both, since
		// they are different slots; that is what the player looks like. A hand
		// that is busy with the scroll is not a refusal and is asked again on
		// the next drop; a thing the hands decline outright is not.
		var worn = Borrow.wornItems(local.getPlayerComposition());
		int inHand = Borrow.wornWeapon(local.getPlayerComposition());
		boolean fresh = !borrow.isBorrowing();
		int tool = Borrow.toolFor(session.activity, session.lastAnimation, worn, inHand,
			itemName(inHand));
		if (tool > 0 && "fishing".equals(session.activity) && borrow.isHolding()
			&& borrow.heldItem() != tool)
			// The harpoon kept from the last spot is no net for this one.
			borrow.swap(tool);
		if (tool > 0 && tool != refusedTool && !borrow.isHolding()
			&& !borrow.start(tool) && !hands.isHolding())
			refusedTool = tool;
		int hat = Borrow.hatFor(session.activity, worn);
		if (hat > 0 && hat != refusedHat && !borrow.hasHat() && !borrow.wearHat(hat))
			refusedHat = hat;
		if (fresh && borrow.isBorrowing())
			// A fresh borrow starts the stint the send-off is measured on; one
			// carried from the last tree keeps the one it had.
			stintStart = client.getTickCount();
	}

	// ------------------------------------------------------------------- bag

	/**
	 * The two bag edges, as events: full when the last slot goes, half when
	 * fourteen are left - once per fill, re-armed when the bag empties past it.
	 */
	void watchBag()
	{
		bagEdge = null;
		int free = freeSlots();
		if (free < 0)
			return;
		var edge = bagEdge(lastFreeSlots, free, halfArmed);
		if (edge == Type.BAG_HALF)
			halfArmed = false;
		if (free > HALF_BAG_FREE)
			halfArmed = true;
		lastFreeSlots = free;
		// Cleared at the top and set here, so an edge seen outside a session
		// never waits for the next one.
		bagEdge = edge;
		if (edge != null)
			dispatch.accept(TriggerEvent.simple(edge));
	}

	/**
	 * The nearest scene object by name within a radius of a tile, or null.
	 * One bounded look, taken on an edge rather than on a tick.
	 */
	static WorldPoint nearestObject(Client client, WorldPoint centre, int radius,
		Predicate<String> nameMatch)
	{
		return nearestObject(client, centre, centre, radius, nameMatch, null, null);
	}

	/**
	 * The same, skipping anything standing on a footprint - the depleted
	 * target itself, which an empty rock shares its name with - and with the
	 * square searched round {@code centre} but the nearest measured from
	 * {@code from}, which the errands need: they search round where the
	 * player is drawn and measure from where the server has them.
	 */
	static WorldPoint nearestObject(Client client, WorldPoint centre, WorldPoint from, int radius,
		Predicate<String> nameMatch, WorldPoint skipMin, WorldPoint skipMax)
	{
		var view = client.getTopLevelWorldView();
		if (view == null || centre == null)
			return null;
		int plane = view.getPlane();
		WorldPoint best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (int x = centre.getX() - radius; x <= centre.getX() + radius; x++)
		{
			for (int y = centre.getY() - radius; y <= centre.getY() + radius; y++)
			{
				var tile = sceneTile(view, x, y, plane);
				if (tile == null)
					continue;
				for (var object : tile.getGameObjects())
				{
					if (object == null || object.getWorldLocation() == null
						|| covers(skipMin, skipMax, object.getWorldLocation())
						|| !nameMatch.test(ErrandController.objectName(client, object.getId())))
						continue;
					int distance = object.getWorldLocation().distanceTo(from);
					if (distance < bestDistance)
					{
						bestDistance = distance;
						best = object.getWorldLocation();
					}
				}
			}
		}
		return best;
	}

	/**
	 * The nearest NPC by name within a radius of a tile, or null: a stall's
	 * guard, and the errands' banker and cat. The name is tested before
	 * anything else, so the errands' scan sees every name in the scene.
	 */
	static NPC nearestNpc(Client client, WorldPoint centre, int radius, Predicate<String> nameMatch)
	{
		var view = client.getTopLevelWorldView();
		if (centre == null || view == null)
			return null;
		NPC best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (var npc : view.npcs())
		{
			var at = npc == null || npc.getName() == null || !nameMatch.test(npc.getName())
				? null : npc.getWorldLocation();
			// Another floor is infinitely far, as distanceTo has it.
			int distance = at == null ? Integer.MAX_VALUE : at.distanceTo(centre);
			if (distance <= radius && distance < bestDistance)
			{
				bestDistance = distance;
				best = npc;
			}
		}
		return best;
	}

	/** The edge between two readings, or null; pure so it can be tested. */
	static Type bagEdge(int previousFree, int free, boolean halfArmed)
	{
		if (previousFree < 0)
			return null;
		if (free == 0 && previousFree > 0)
			return Type.BAG_FULL;
		if (halfArmed && free <= HALF_BAG_FREE && previousFree > HALF_BAG_FREE)
			return Type.BAG_HALF;
		return null;
	}

	/** Empty inventory slots, or -1 while the container has not loaded. */
	int freeSlots()
	{
		var inventory =
			client.getItemContainer(net.runelite.api.gameval.InventoryID.INV);
		if (inventory == null)
			return -1;
		int used = 0;
		for (var item : inventory.getItems())
		{
			if (item != null && item.getId() > 0)
				used++;
		}
		return max(0, 28 - used);
	}

	// --------------------------------------------------------------- context

	/** Hands the rules what the company knows, once a tick. */
	void describeTo(TriggerContext context)
	{
		if (session == null)
		{
			context.setWork(false, "", "", null, 0, 0, Integer.MAX_VALUE);
			return;
		}
		int now = client.getTickCount();
		context.setWork(true, session.activity, session.targetName, session.targetTile,
			now - session.startTick, session.xpDrops,
			session.lastDropTick < 0 ? Integer.MAX_VALUE : now - session.lastDropTick);
	}

	/** A row of skilling.properties, or null when there is none. */
	static String[] values(String key)
	{
		String row = DATA.getProperty(key);
		return row == null ? null : row.split(",");
	}

	/** A row of skilling.properties as ids - items, objects, regions, animations - or null. */
	static int[] ids(String key)
	{
		var cells = values(key);
		return cells == null ? null : Arrays.stream(cells).mapToInt(Integer::parseInt).toArray();
	}

	/** A row of skilling.properties as a set of ids. */
	static Set<Integer> idSet(String key)
	{
		return Arrays.stream(ids(key)).boxed().collect(Collectors.toSet());
	}
}

package com.follower;

import java.util.function.Consumer;
import net.runelite.api.*;
import net.runelite.api.Actor;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.AnimationID;
import lombok.*;
import java.util.*;
import java.util.List;

/**
 * Gets the follower out of the way when a fight starts, and gives it something
 * to do while it waits.
 *
 * <p>A following follower stands where a player wants to look: on the boss, on
 * the tile they are about to click, in the middle of the fight. It cannot
 * actually block anything - it is a client-side object with no collision - but
 * being visually in the way is enough of a problem during a kill. So when a
 * fight starts it walks clear and watches from a few tiles off.
 *
 * <p>Thrall mode is deliberately exempt. A possessed thrall is IN the fight by
 * definition, and sending it away would undo the whole feature.
 *
 * <p>Speech is not handled here beyond announcing the start and end of a fight.
 * Encouragement and the health and prayer warnings come from the ordinary rule
 * system, which never stopped running - the {@code combat} and {@code bossFight}
 * conditions exist so a rule can ask about a fight the same way it asks about
 * anything else.
 */
@RequiredArgsConstructor
class SpectateController
{

	/**
	 * The superior slayer monsters, by name, in one place. The spectator
	 * stands {@link #SUPERIOR_EXTRA_TILES} further from one of these than
	 * from anything else, and panics once at the sight of it.
	 *
	 * <p>Matched exactly, capitals and all, and the capitals are the game's
	 * own, which it does not keep straight: the superior warped jelly (7400)
	 * is "Vitreous Warped Jelly" and a stronger copy of it (12457) "Vitreous
	 * warped Jelly", so both are here. The other way round, the superior
	 * basilisk (7395) is "Monstrous basilisk", while 9287 and 9288, "Monstrous
	 * Basilisk", are filed with the ordinary basilisks, not the superiors -
	 * which is why this stays exact. The Bloodthirsty ones are the game's
	 * category of superiors too (980), one of them spelled "Bloodthirst
	 * rockslug" by the game itself. runTargetAudit checks every name here
	 * against the cache.
	 */
	static final java.util.Set<String> SUPERIOR_NAMES = new java.util.HashSet<>(
		java.util.Arrays.asList(
			"Crushing hand", "Chasm Crawler", "Screaming banshee",
			"Screaming twisted banshee", "Giant rockslug", "Cockathrice",
			"Flaming pyrelord", "Monstrous basilisk", "Malevolent Mage",
			"Insatiable Bloodveld", "Insatiable mutated Bloodveld", "Vitreous Jelly",
			"Vitreous Warped Jelly", "Vitreous warped Jelly", "Cave abomination", "Abhorrent spectre",
			"Repugnant spectre", "Basilisk Sentinel", "Choke devil", "King kurask",
			"Marble gargoyle", "Nechryarch", "Greater abyssal demon", "Night beast",
			"Nuclear smoke devil", "Shadow Wyrm", "Guardian Drake", "Colossal Hydra",
			"Infernal pyrelord", "Spiked Turoth", "Mutated Terrorbird", "Mutated Tortoise",
			"Dreadborn Araxyte", "Ancient Custodian", "Dire gryphon", "Vitreous Chilled Jelly",
			"Elder aquanite", "Magma strykewyrm", "Blood-starved venator",
			"Bloodthirsty hand", "Bloodthirsty Crawler", "Bloodthirsty banshee",
			"Bloodthirsty twisted banshee", "Bloodthirst rockslug", "Bloodthirsty Cockathrice",
			"Bloodthirsty pyrelord", "Bloodthirsty Infernal pyrelord", "Bloodthirsty basilisk",
			"Bloodthirsty Basilisk Sentinel", "Bloodthirsty Mage", "Bloodthirsty Bloodveld",
			"Bloodthirsty mutated Bloodveld", "Bloodthirsty Jelly", "Bloodthirsty Warped Jelly",
			"Bloodthirsty abomination", "Bloodthirsty spectre", "Bloodthirsty Repugnant spectre",
			"Bloodthirsty choke devil", "Bloodthirsty kurask", "Bloodthirsty smoke devil",
			"Bloodthirsty gargoyle", "Bloodthirsty Night beast", "Bloodthirsty abyssal demon",
			"Bloodthirsty Nechryarch", "Bloodthirsty Turoth", "Bloodthirsty Shadow Wyrm",
			"Bloodthirsty Drake", "Bloodthirsty Hydra"));

	/** EMOTE_PANIC, proven on the follower by the mirror rules. */
	static final int PANIC = 2105;

	/**
	 * A superior is being fought and the panic has not played: it waits for
	 * the follower to be settled at its seat, since movement would cut it off.
	 */
	boolean panicDue,
		panicked;

	/**
	 * Whether the seat was chosen for a superior, two tiles further out: the
	 * one that spawns mid-task is attacked from the ordinary seat, which is
	 * then the wrong distance.
	 */
	boolean seatedForSuperior;

	/**
	 * The superior is part of the skilling company, so the Skilling master
	 * switch turns it off along with the rest: with it off a superior is
	 * watched like any other fight.
	 */
	boolean isSuperior(Actor target)
	{
		return config.keepsCompany() && target != null && target.getName() != null
			&& SUPERIOR_NAMES.contains(target.getName());
	}

	/**
	 * How often the channelled graphic is renewed, in game ticks.
	 *
	 * <p>Two ticks is 1.2 seconds against a 1.34-second effect, so each renewal
	 * starts just before the last has faded and the ward looks continuous
	 * rather than blinking once in a while.
	 */
	static final int SHIELD_MAINTAIN_TICKS = 2;

	final Client client;
	final FollowerEntity follower;
	final FollowerConfig config;

	/**
	 * Read fresh on every use, never held. The engine REPLACES its context on
	 * every reset - each login screen, the memory eraser, a plugin toggle -
	 * and a controller holding the original object was reading a context
	 * that had stopped being refreshed: its isInCombat was false forever, so
	 * spectating never started again after the first relog. Cheers still
	 * fired (the rules read the live context), which is what made the boss
	 * fights look detected while the follower stood glued to the player.
	 */
	final java.util.function.Supplier<TriggerContext> contextSource;
	final SpotAnimRepository spotAnims;
	final Consumer<TriggerEvent> speech;

	TriggerContext context()
	{
		return contextSource.get();
	}

	/** Puts the follower's weapon and shield away while it channels. */
	final Consumer<Boolean> disarm;

	/** Whether the follower is currently standing aside for a fight. */
	@Getter
	boolean spectating;

	/**
	 * Whether the player has parked the follower themselves. A fight is then
	 * announced at both ends as ever, but watched from the post: nothing here
	 * moves it, casts at it or lets it go, and the feet are not held.
	 */
	boolean parked;

	WorldPoint watchTile;

	/**
	 * The shield is a three-part spell rather than a repeating effect: it is
	 * summoned once, channelled for as long as the follower stands and fights
	 * are still going, and finished off deliberately at the end.
	 */
	enum Shield
	{
		NONE, SUMMONING, CHANNELLING
	}

	Shield shield = Shield.NONE;
	int ticksSinceShield;

	/** Counts down after a dispel; the follower walks back when it reaches zero. */
	int releaseTicks;

	int ticksSettled;

	int ticksUnsettled;

	/**
	 * Whether the spectate logic owns the follower's feet right now, which is
	 * a longer window than {@link #isSpectating()}.
	 *
	 * <p>stop() clears the flag at once but leaves the follower standing where
	 * it is for a few ticks, so the closing cast is not cut off by walking
	 * away. Through that gap the follower is parked and no longer counted as
	 * spectating, which is indistinguishable from a Stay the player asked for
	 * unless somebody asks this instead. A fight watched from the player's
	 * park holds nothing: the feet are theirs.
	 */
	boolean holdsTheFeet()
	{
		return spectateOwnsTheFeet(spectating && !parked, releaseTicks);
	}

	/** The above as a decision, so it can be tested without a controller. */
	static boolean spectateOwnsTheFeet(boolean spectating, int releaseTicks)
	{
		return spectating || releaseTicks > 0;
	}

	/**
	 * @param busy true when something else owns the follower's feet - thrall
	 * mode or an errand - in which case spectating stays out of the way
	 * @param parked true when the player has parked the follower
	 */
	void tick(boolean busy, boolean parked)
	{
		this.parked = parked;
		// A dispel in progress owns the feet until its animation has played.
		// The weapon comes back at the same moment, for the same reason: the
		// rebuild that returns it would otherwise cut the closing cast short.
		if (releaseTicks > 0 && --releaseTicks == 0)
		{
			disarm.accept(false);
			follower.resumeFollowing();
		}

		// Thieving is not a fight and is not spectated. Standing clear was tried
		// and is the wrong shape: it holds one spot facing the action, which
		// reads as an audience. A player picking pockets wants the follower
		// gone, not watching - so the thieving session suppresses this outright
		// and the wandering takes over instead.
		if (!config.spectateCombat() || busy || !follower.isSpawned()
			|| !context().isInCombat() || context().isInThievingSession())
		{
			if (spectating)
				stop();
			return;
		}

		if (!spectating)
			start(true);
		else if (parked)
			letTheSeatGo();
		else
			holdPosition();
		if (parked)
			// Watched from the post: no panic and no ward there.
			return;

		// The panic, once stood still at the seat: an emote begun while the
		// feet are still moving is cancelled by the very next movement frame.
		if (panicDue && follower.isStaying() && follower.isSettled())
		{
			panicDue = false;
			panicked = true;
			follower.playAnimation(PANIC);
		}

		maybeCastShield();
	}

	/**
	 * @param announce whether this is a fight, which is worth saying something
	 * about. Thieving is not: it steps clear and keeps quiet.
	 */
	void start(boolean announce)
	{
		spectating = true;
		announced = announce;
		releaseTicks = 0;
		unseatedTicks = 0;
		if (parked)
		{
		}
		else if (!moveClear())
		{
			// Nowhere to go is not a reason to keep announcing a fight; the
			// follower simply carries on following.
		}
		if (!announce)
			return;
		speech.accept(TriggerEvent.combat(TriggerEvent.Type.COMBAT_START,
			context().getCombatTarget()));
	}

	/**
	 * Whether the current stand-clear was announced as a fight, so that only
	 * the ones that said hello say goodbye.
	 */
	boolean announced;

	void stop()
	{
		spectating = false;
		watchTile = null;
		unseatedTicks = 0;
		panicDue = false;
		panicked = false;

		// Finishing the spell is its own moment: drop the channelled pose, play
		// the closing animation where it stands, and only walk back once it has
		// had time to play - movement would cut it off otherwise.
		boolean wasCasting = dropChannel("fight over", false);
		// Stand, then cast: it gets to its feet before releasing the spell, so
		// the sequence closes the way it opened.
		if (wasCasting && castChain(
			new int[]{channelEnd(config.spectateShieldChannelAnimation(), config.spectateShieldChannelEnd()),
				config.spectateShieldEndAnimation()},
			new int[]{config.spectateShieldEndGraphic(), config.spectateShieldEndGraphic()}))
			// The weapon stays away until the closing cast has played: taking
			// it back rebuilds the model, and a rebuild would cut the animation
			// off mid-flourish.
			// DISPEL_HOLD_TICKS: How long the follower stays put after dispelling, so the closing
			// animation is not cut off by it walking back. Movement always wins over an
			// emote, so releasing on the same tick would kill the flourish outright.
			releaseTicks = 4 /* DISPEL_HOLD_TICKS */;
		else
		{
			if (wasCasting)
				disarm.accept(false);
			// A park the player gave is theirs to end, not the fight's.
			if (!parked)
				follower.resumeFollowing();
		}

		// Only a fight says goodbye. A thieving stand-clear ended is the
		// follower simply coming back, which needs no remark.
		if (announced)
			speech.accept(TriggerEvent.combat(TriggerEvent.Type.COMBAT_END,
				context().getCombatTarget()));
		announced = false;
	}

	/**
	 * The player parked the follower mid-fight, where it stands, and the post
	 * is theirs now: the seat is forgotten without being let go, and a ward
	 * held on it is dropped, weapon back, since nothing is cast at the post.
	 */
	void letTheSeatGo()
	{
		dropChannel("parked", true);
		watchTile = null;
		panicDue = false;
	}

	/** Re-seats the follower only once it has been left well behind. */
	void holdPosition()
	{
		var local = client.getLocalPlayer();
		if (local == null || local.getWorldLocation() == null)
			return;
		// Unseated - the first moveClear found nowhere to stand. That used to
		// be final: this method returned on a null watchTile, so a follower
		// that failed once in a cramped arena stood glued to the player for
		// the whole fight. Play report: a boss fight where it never stepped
		// clear. Fights move; tiles open up; try again every few ticks.
		if (watchTile == null)
		{
			// RESEAT_RETRY_TICKS: How often an unseated spectator looks again for somewhere to stand.
			if (++unseatedTicks % 5 /* RESEAT_RETRY_TICKS */ == 0)
				moveClear();
			return;
		}
		// The seat is HELD through FollowerEntity's stayTile, and plenty of
		// hands can release that without telling this controller: the thrall
		// exit's stayHere/resumeFollowing/snapBeside chain, the leash snap,
		// scene recovery. Measuring watchTile against the PLAYER missed all
		// of them - the tile was still nearby, so the spectator stood glued
		// to the player casting wards while never stepping away. Play report:
		// "out of thrall mode they don't step away, but still do the magic
		// barrier animations." If the follower no longer holds ANY stay, it
		// was un-seated, whoever did it: take the seat again.
		// Another floor is infinitely far, as distanceTo has it.
		if (!follower.isStaying()
			// RESEAT_DISTANCE: How far the follower may drift from its watching spot before it is moved
			// again. Without this it would re-path every tick as the player shuffles.
			// <p>Generous on purpose. Every re-seat ends the channelled spell, so a
			// tight leash meant a boss that moves the player around - Scurrius was the
			// case that showed it - reduced the whole sequence to repeated casting and
			// sitting. A watcher standing well back is the point, so it only follows
			// once genuinely left behind.
			|| watchTile.distanceTo(local.getWorldLocation()) > 12 /* RESEAT_DISTANCE */
			|| isSuperior(local.getInteracting()) != seatedForSuperior)
			moveClear();
	}

	/** Ticks spent spectating without a tile to stand on. */
	int unseatedTicks;

	/**
	 * Puts the follower behind the player, away from whatever is being fought.
	 *
	 * <p>The direction is the one that matters: standing "near the player" is no
	 * good if that happens to be between them and the boss. The vector from the
	 * target to the player, continued past the player, is the one place
	 * guaranteed not to be in the line of the fight. Tiles are tried outward
	 * from there, so a wall or a corner degrades to the next best angle rather
	 * than giving up.
	 */
	boolean moveClear()
	{
		var local = client.getLocalPlayer();
		if (local == null || local.getWorldLocation() == null)
			return false;
		var player = local.getWorldLocation();

		var target = local.getInteracting();
		var threat = target == null ? null : target.getWorldLocation();

		// A superior is worth two more tiles of distance, and a panic once
		// the follower has stopped where it is going.
		boolean superior = isSuperior(target);
		seatedForSuperior = superior;
		// WATCH_DISTANCE: How far the follower tries to stand from the player while watching. Close
		// enough to still read as a companion, far enough not to sit on top of the
		// fight.
		int watch = 4 /* WATCH_DISTANCE */ + (superior ? 2 /* SUPERIOR_EXTRA_TILES */ : 0);
		if (superior && !panicked)
			panicDue = true;

		int dx,
			dy;
		if (threat == null || threat.equals(player))
		{
			// Nothing to stand clear OF; just get out of arm's reach.
			dx = 0;
			dy = -1;
		}
		else
		{
			dx = Integer.signum(player.getX() - threat.getX());
			dy = Integer.signum(player.getY() - threat.getY());
			if (dx == 0 && dy == 0)
				dy = -1;
		}

		// Straight back first, then fanned out to either side, then the sides
		// themselves - a corner or a wall behind the player should not end with
		// the follower standing in the fight.
		int[][] offsets = {
			{dx, dy},
			{dx == 0 ? 1 : dx, dy == 0 ? 1 : dy},
			{dx == 0 ? -1 : dx, dy == 0 ? -1 : dy},
			{dy, dx},
			{-dy, -dx},
		};

		for (int[] direction : offsets)
		{
			for (int distance = watch; distance >= 2; distance--)
			{
				if (seat(player.dx(direction[0] * distance).dy(direction[1] * distance), threat))
					return true;
			}
		}

		// The away-from-the-threat fan is walled - a boss arena is exactly the
		// place where "behind the player" is stone. In a fight the goal is not
		// underfoot, and any tile at a distance that is not next to the threat
		// serves it. The full ring, nearest first, before giving up.
		for (int distance = 2; distance <= watch; distance++)
		{
			for (int ox = -distance; ox <= distance; ox++)
			{
				for (int oy = -distance; oy <= distance; oy++)
				{
					if (Math.max(Math.abs(ox), Math.abs(oy)) == distance && seat(player.dx(ox).dy(oy), threat))
						return true;
				}
			}
		}
		return false;
	}

	/** Takes a seat on this tile, unless it is next to the threat or cannot be held. */
	boolean seat(WorldPoint candidate, WorldPoint threat)
	{
		if ((threat == null || candidate.distanceTo(threat) >= 3) && follower.stayAt(candidate))
		{
			watchTile = candidate;
			return true;
		}
		return false;
	}

	/**
	 * The protective-shield flourish: a cast animation with a graphic on top,
	 * played on the follower itself while it watches a boss fight.
	 *
	 * <p>Both ids are settings rather than constants. Unlike a weapon's swing,
	 * which the game answers definitively, "what a protective shield looks
	 * like" has no correct answer to measure - so the honest thing is to pick a
	 * reasonable pair and let it be changed, with {@code ::follower gfx} to
	 * audition alternatives.
	 */
	void maybeCastShield()
	{
		if (!config.spectateShield() || !context().isBossFight())
			return;
		// An emote started while the feet are still moving is cancelled by the
		// very next movement frame - movement always wins over an emote, which
		// is what stops a dancing follower gliding along behind you. The first
		// cast used to fire on the same tick the follower set off to stand
		// clear, so it was killed before a single particle appeared. Nothing is
		// cast until it has actually stopped at its watching spot.
		//
		// The same rule ends a channel: a follower that has to move cannot go
		// on channelling, so the pose is dropped and the spell begins again
		// once it has settled somewhere new.
		// Settled is not seated. A follower glued to the player - un-seated
		// by the thrall exit, a failed moveClear in a cramped arena, a leash
		// snap - is perfectly still and used to pass this gate, which is how
		// the ward got cast at the player's elbow instead of from the seat.
		// No stay held means no seat, and no seat means no spell.
		if (!follower.isSettled() || !follower.isStaying())
		{
			ticksSettled = 0;
			// One unsettled tick is not a journey. The fine position can leave
			// the tile centre for a moment without the follower going
			// anywhere, and dropping on that alone made the spell restart -
			// standing up out of the kneel and casting it again - while it was
			// supposed to be holding still.
			// UNSETTLED_DROP_TICKS: Consecutive unsettled ticks before the channel is considered broken. A
			// real walk lasts many ticks; a momentary wobble should not end a spell.
			if (++ticksUnsettled >= 3 /* UNSETTLED_DROP_TICKS */)
				// Broken by movement, so there is no closing animation to
				// protect: the weapon can come straight back.
				dropChannel("moved", true);
			return;
		}
		ticksUnsettled = 0;
		ticksSettled++;

		switch (shield)
		{
			case NONE:
				// Only begin once it has genuinely stopped, or the spell is
				// abandoned a second later when it has to re-seat.
				// SETTLE_DWELL_TICKS: How long the follower must have stood still before it starts the spell.
				// <p>Observed in a Scurrius fight: a summon began and was abandoned a second
				// later because the player moved and the follower had to re-seat, which
				// reads as a cast that goes nowhere. Waiting a couple of ticks costs
				// nothing and means a spell is only started when there is a reasonable
				// chance of holding it.
				if (ticksSettled < 3 /* SETTLE_DWELL_TICKS */)
					break;
				// Cast, then sit, as one chain: the follower raises the ward
				// and settles into holding it without a gap between the two.
				// Nothing to play is not a reason to skip the channel.
				// The particle rides every stage, not just the cast: the ward is
				// meant to be visibly up from the moment it is raised.
				// Weapon and shield go away as the spell is raised, while the
				// cast covers the rebuild, rather than when the kneel starts.
				disarm.accept(true);
				if (castChain(
					new int[]{config.spectateShieldAnimation(), config.spectateShieldChannelStart()},
					new int[]{config.spectateShieldGraphic(), config.spectateShieldGraphic()}))
					shield = Shield.SUMMONING;
				else
					startChannel();
				break;

			case SUMMONING:
				// The summon is a one-shot; the channelled pose takes over the
				// moment it has played out, so the two read as one spell.
				if (!follower.isEmotePlaying())
					startChannel();
				break;

			case CHANNELLING:
				// A looping pose shows no particles of its own, so the graphic
				// is renewed on its own timer to keep the ward alive.
				if (++ticksSinceShield >= SHIELD_MAINTAIN_TICKS)
				{
					ticksSinceShield = 0;
					var renew =
						spotAnims.get(config.spectateShieldChannelGraphic());
					if (renew != null)
						follower.playSpotAnim(renew);
				}
				break;

			default:
				break;
		}
	}

	/**
	 * Starts the channelled pose. A pose override loops until it is cleared,
	 * unlike an emote, which is what "until it moves or the fight ends" needs.
	 */
	void startChannel()
	{
		int channel = config.spectateShieldChannelAnimation();
		if (channel > 0)
			follower.setPoseOverride(channel);
		shield = Shield.CHANNELLING;
		// Renew on the very next tick rather than after a full interval, so the
		// ward does not go dark between the summon and the first top-up.
		ticksSinceShield = SHIELD_MAINTAIN_TICKS;
	}

	/**
	 * The rise that ends a channel. Off the held prayer, HUMAN_PRAY_LOOP, the
	 * kneel's own rise: HUMAN_GETUP starts from the floor, 97-103 units from
	 * that kneel, and the body jumped into it (cache, 15 Oct), as it did at
	 * the altar.
	 */
	static int channelEnd(int channel, int end)
	{
		return channel == AnimationID.HUMAN_PRAY_LOOP && end == AnimationID.HUMAN_GETUP
			? FollowerEntity.PRAY_STAND_UP : end;
	}

	/**
	 * Ends the channel and hands the follower's pose back to normal.
	 *
	 * @param rearm whether a ward that was up gives the weapon straight back,
	 * there being no closing cast for a rebuild to cut short
	 * @return whether a ward was up
	 */
	boolean dropChannel(String reason, boolean rearm)
	{
		boolean wasCasting = shield != Shield.NONE;
		if (wasCasting)
		{
		}
		if (shield == Shield.CHANNELLING)
			follower.setPoseOverride(0);
		shield = Shield.NONE;
		if (wasCasting && rearm)
			disarm.accept(false);
		return wasCasting;
	}

	/**
	 * Plays one stage of the shield.
	 *
	 * @return false when the stage has nothing configured, so a caller can tell
	 * a skipped stage from a played one
	 */
	/**
	 * Plays several stages back to back, each with its own optional graphic.
	 *
	 * <p>A zero animation is dropped from the chain rather than played, but its
	 * graphic is not: a stage may legitimately be particles alone.
	 *
	 * @return false only when the whole chain had nothing to show
	 */
	boolean castChain(int[] animations, int[] graphicIds)
	{
		List<Integer> ids = new ArrayList<>();
		List<SpotAnimRepository.Entry> graphics = new ArrayList<>();
		boolean played = false;

		for (int i = 0; i < animations.length; i++)
		{
			var fx = spotAnims.get(graphicIds[i]);
			if (animations[i] > 0)
			{
				ids.add(animations[i]);
				graphics.add(fx);
			}
			else if (fx != null)
			{
				follower.playSpotAnim(fx);
				played = true;
			}
		}

		if (!ids.isEmpty())
		{
			int[] chain = ids.stream().mapToInt(Integer::intValue).toArray();
			// Kept, at debug: this is what showed the sit and stand were
			// running all along and the ids were the problem. ::follower
			// spectate reports the same state on demand without it.
			follower.playAnimations(chain,
				graphics.toArray(new SpotAnimRepository.Entry[0]));
			played = true;
		}
		return played;
	}

}

package com.follower;

import java.util.concurrent.ThreadLocalRandom;
import lombok.*;

/**
 * Decides when the follower has said enough for now.
 *
 * <p>The speech gap already stops two lines landing on top of each other, but a
 * gap is a floor and nothing more: at three seconds apart, a follower with
 * plenty to react to will talk for as long as things keep happening, and every
 * line lands in the same flat stream as the one before it. Nothing is ever
 * quiet, so nothing is ever loud.
 *
 * <p>This is the survival-horror director model, which exists for exactly that
 * problem. A running intensity rises with each thing said and decays with time;
 * crossing a peak forces a RELAX period during which only an occasion gets
 * through. The relax is the point. Contrast is not something a line can have on
 * its own - it is the silence either side of it - and the only way to make a
 * good line land is to have said less shortly before it.
 *
 * <p>The same object holds the settling-in damper, because it is the same
 * question asked about a longer span of time: how much should be said, given
 * what has been said lately.
 */
class SpeechDirector
{

	/**
	 * How long a peak buys, in milliseconds, as a range.
	 *
	 * <p>Randomised because a constant is a metronome: a player who notices the
	 * follower goes quiet for exactly thirty seconds has found the machinery,
	 * and from then on hears a timer rather than someone choosing not to speak.
	 */
	static final long RELAX_MIN_MS = 30_000L;

	/** Groups that recite what the world is, rather than react to what happened in it. */
	static final java.util.Set<String> LORE_GROUPS =
		new java.util.HashSet<>(java.util.Arrays.asList("area", "gear"));

	@Getter
	double intensity;
	long lastDecayMs,
		relaxUntilMs,
		lastLoreMs;

	/**
	 * The base speech gap, in milliseconds. Everything here is expressed as a
	 * multiple of it, so the chattiness setting moves the whole model at once.
	 *
	 * <p>Zero switches the director off entirely, which falls out of the same
	 * fact rather than being a special case bolted on: every window here is a
	 * multiple of the gap, so a gap of nothing makes all of them nothing. The
	 * chattiness setting has no such level - this is for the test harness,
	 * which wants rules evaluated without pacing in the way.
	 */
	long baseGapMs = 3_000L;

	void setBaseGapMs(long baseGapMs)
	{
		this.baseGapMs = Math.max(0L, baseGapMs);
	}

	boolean isPacing()
	{
		return baseGapMs > 0L;
	}

	/**
	 * Sessions so far, this one included. Drives the settling-in damper only.
	 *
	 * <p>Zero means nobody has said yet, which is treated as NOT settling in.
	 * The damper is a claim that the follower is new, and an unanswered
	 * question is not evidence for it - defaulting the other way would have
	 * every fresh engine start out quiet about the scenery until something got
	 * round to correcting it.
	 */
	@Setter
	int sessionCount;

	boolean isSettlingIn()
	{
		// SETTLING_SESSIONS: Sessions during which the follower is still settling in. The first
		// evening and the first return.
		return sessionCount >= 1 && sessionCount <= 2 /* SETTLING_SESSIONS */;
	}

	boolean isRelaxing(long now)
	{
		return now < relaxUntilMs;
	}

	long relaxRemainingMs(long now)
	{
		return Math.max(0L, relaxUntilMs - now);
	}

	/**
	 * Why this rule should stay quiet right now, or null to let it speak.
	 *
	 * <p>Only ever consulted for rules that actually say something; an
	 * animation-only firing is movement rather than chatter and never reaches
	 * here.
	 */
	String blocks(SpeechRule rule, long now)
	{
		if (!isPacing())
			return null;

		// An occasion is exempt from EVERYTHING this class does, and that has to
		// be said once at the top rather than repeated per damper. It was not,
		// and the settling check below quietly acquired the power to swallow
		// enter-wilderness - a line whose whole job is to reach a player who has
		// never seen the place, from a follower that is only settling in
		// because the player is new. The two conditions peak together.
		if (rule.isOccasion())
			return null;

		if (isRelaxing(now))
			return "relax";
		// SETTLING_LORE_GAPS: Gaps a settling-in follower leaves between two lore lines.
		if (isLore(rule) && isSettlingIn() && now - lastLoreMs < baseGapMs * 4 /* SETTLING_LORE_GAPS */)
			return "settling";
		return null;
	}

	/**
	 * Whether this rule recites what the world IS, rather than reacting to
	 * what happened in it. Public so a test can assert the other way round -
	 * that nothing which must always be heard has been left in a group the
	 * damper thins.
	 */
	static boolean isLore(SpeechRule rule)
	{
		return rule.group != null
			&& LORE_GROUPS.contains(rule.group.toLowerCase(java.util.Locale.ROOT));
	}

	/**
	 * Records that a line was actually said, and starts a relax period if that
	 * was one line too many.
	 *
	 * <p>Counted at the point of SPEAKING rather than of winning, for the same
	 * reason the mood is: a line the mute swallowed cost the player no
	 * attention, and resting afterwards would be resting from nothing.
	 */
	void noteSpoke(SpeechRule rule, long now)
	{
		if (!isPacing())
			return;
		decayTo(now);

		if (isLore(rule))
			lastLoreMs = now;

		// An occasion is the thing the quiet was being saved for. Letting it
		// also build towards the next quiet would have the follower punish
		// itself for the one line it most wanted to say.
		if (rule.isOccasion())
			return;

		// RISE_PER_LINE: What one spoken line adds to the running intensity.
		intensity += 1.0 /* RISE_PER_LINE */;
		// PEAK_AT: Intensity at which the follower has had its say and stops for a bit.
		// <p>Three lines close together, and not the 3.0 that implies: the third
		// arrives two gaps after the first and the decay has already taken a slice
		// off the two before it. Asking for a full three units would quietly mean
		// four lines, which is a different and much longer burst.
		if (intensity >= 2.5 /* PEAK_AT */)
		{
			intensity = 0.0;
			relaxUntilMs = now + RELAX_MIN_MS
				+ (long) ThreadLocalRandom.current().nextInt((int) (45_000L /* RELAX_MAX_MS */ - RELAX_MIN_MS) + 1);
		}
	}

	void decayTo(long now)
	{
		if (lastDecayMs == 0L)
		{
			lastDecayMs = now;
			return;
		}
		long elapsed = now - lastDecayMs;
		lastDecayMs = now;
		if (elapsed <= 0L)
			return;
		// DECAY_GAPS: Intensity decays one unit per this many speech gaps.
		// <p>Expressed in gaps rather than seconds so the whole model scales with
		// the chattiness setting instead of fighting it. At Normal, three lines
		// inside forty-five seconds is a burst worth resting after; at Quiet, where
		// the floor between lines is already twelve seconds, the same three lines
		// are spread far enough that they never peak - which is correct, because a
		// player who asked for quiet has already been given the contrast.
		intensity = Math.max(0.0, intensity - elapsed / (5.0 /* DECAY_GAPS */ * baseGapMs));
	}

	void reset()
	{
		intensity = 0.0;
		lastDecayMs = 0L;
		relaxUntilMs = 0L;
		lastLoreMs = 0L;
	}
}

package com.follower;

import com.google.common.base.Strings;
import java.util.*;
import java.util.Map;
import java.util.Set;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import java.util.List;
import java.util.function.*;
import java.util.function.Function;
import java.util.regex.Pattern;
import com.follower.TriggerEvent.Type;
import static com.follower.TriggerEvent.Type.*;

/**
 * Evaluates every rule against every incoming event and speaks the winner.
 *
 * <p>The model is deliberately uniform: there is no separate notion of "event
 * rules" and "state rules". Every rule is evaluated on every event (including the
 * synthetic per-tick event) and fires on the rising edge of its condition. Event
 * conditions such as {@code npcSpawn} are only true while that event is being
 * processed, so they behave as edges naturally; state conditions such as
 * {@code healthBelow} stay true and therefore fire once per crossing.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
@Setter
@Getter
class SpeechEngine
{
	/**
	 * Callback for delivering a firing. Implemented by the plugin. {@code text}
	 * may be empty (an animation-only rule) and {@code animationId} is -1 when
	 * the rule plays nothing.
	 *
	 * <p>{@code onSaid} is the moment the line actually reaches the player. A
	 * sink that shows lines immediately runs it before returning; a sink that
	 * queues them runs it when the line takes the floor, and never for a line
	 * it drops. The engine hangs the states that OPEN something - a question,
	 * a want, a wish - on this, because each of those later puts an
	 * interaction in front of the player that only makes sense if the opening
	 * line was seen. Everything else a line leaves behind hangs here too: a
	 * first spent, a souvenir, a bet, a dare, advice, a granted wish.
	 */
	interface Sink
	{
		void speak(String text, SpeechOutput output, SpeechRule rule, int animationId,
			Runnable onSaid);
	}

	final Client client;
	final RuleLoader loader;

	TriggerContext context;

	Sink sink;

	/** Groups the config has switched off. Rule ids are matched too, for one-offs. */
	Set<String> disabledGroups = Collections.emptySet();

	SpeechOutput defaultOutput = SpeechOutput.OVERHEAD;

	/** Nothing speaks within this window of the previous line, whatever the rule. */
	long globalCooldownMs = 3_000L;

	/**
	 * How wide a line is drawn over the head, in pixels: the game's bold
	 * font, set by the plugin once the fonts are read. Null measures in
	 * characters only.
	 */
	java.util.function.ToIntFunction<String> overheadWidth;

	void setGlobalCooldownMs(long globalCooldownMs)
	{
		this.globalCooldownMs = globalCooldownMs;
		director.setBaseGapMs(globalCooldownMs);
	}

	/**
	 * How much has been said lately, and whether it is time to stop for a bit.
	 * The gap above is a floor between two lines; this is a budget across many.
	 */
	final SpeechDirector director = new SpeechDirector();

	/**
	 * How many unprompted idle remarks the current stretch of standing still
	 * has already produced, and when the last one was.
	 *
	 * <p>The director cannot see this problem. It handles BURSTS - intensity
	 * that rises faster than it decays - and a line every forty-five seconds
	 * decays completely between lines, so an idle afternoon sails under its
	 * peak forever while still producing eighty lines an hour. Measured, that
	 * is what a long AFK sounded like: the longest silence in forty minutes
	 * was two.
	 *
	 * <p>A companion does not drip at a fixed rate. It chats when you first
	 * stop, and then it runs out of things to say about standing still. So the
	 * first few remarks of a stretch are free, and each one after that needs a
	 * longer wait than the one before - the follower audibly winding down -
	 * until anything at all happens and the count starts over.
	 *
	 * <p>"Unprompted" is precise: a rule whose condition mentions {@code idle}
	 * is speaking because you are standing still, and is throttled. A reaction
	 * to something real - a cat, a passer-by, an errand - is not, because
	 * answering the world is not chatter. Occasions are exempt as everywhere.
	 */
	int idleStretchSpoken;
	long lastIdleRemarkMs;

	/** Idle remarks per stretch before the winding-down starts. */
	static final int IDLE_FREE_REMARKS = 4;

	/** The placeholders that hold a player's name: the player's own, whoever came or went, whoever spoke. */
	static final Set<String> PLAYER_NAMES = Resources.words("playerNames");

	/** Someone's own name or words: the article step leaves them as written, "The" and all. */
	static final Set<String> AS_WRITTEN = Resources.words("asWritten");

	/** Placeholders that always name a creature or a boss, whatever the event. */
	static final Set<String> CREATURE_NAMES = Resources.words("creatureNames");

	/** Words that already point at the thing, so a name's own "The" goes: that Leviathan, the first Leviathan. */
	static final Set<String> POINTING = Resources.words("pointing");

	/**
	 * A unit the template wrote in the plural, after a number: "{prayer}
	 * points left". A count of one takes it singular - 1 point, 1 prayer
	 * point - since a close call or a nearly dry prayer is often exactly one.
	 */
	static final Pattern PLURAL_UNIT = Pattern.compile(
		" ((?:prayer )?(?:hit)?point|day|minute|hour|time|kill|level)s\\b");

	/**
	 * Nouns a boss's name can stand in front of, the article belonging to
	 * the noun: the Vorkath population, the Zulrah column.
	 */
	static final Set<String> NAME_MODIFIES = Resources.words("nameModifies");

	/**
	 * Away from the keys is standing still too. Behaviour QA5, 20 Oct:
	 * gone-away, on "unattended" rather than "idle", never trailed off, and
	 * was said every twenty minutes for as long as the player was away.
	 */
	boolean isIdleRemark(SpeechRule rule)
	{
		return (rule.uses("idle") || rule.uses("unattended")) && !rule.isOccasion();
	}

	/** Whether a rule's lines tell the incident, by its {memory}. */
	static boolean tellsTheIncident(SpeechRule rule)
	{
		return saysAnyOf(rule, "{memory}");
	}

	/**
	 * Whether a rule brings up something remembered: the incident, what a
	 * place holds ({here}), or the spot of the last death. Text QA5, 17 Oct:
	 * "This is where I wrote down the time you died, yesterday." and, 6 s
	 * later, "Same spot. This is where it went wrong for you."
	 */
	static boolean bringsUpAMemory(SpeechRule rule)
	{
		return saysAnyOf(rule, "{memory}", "{here}")
			|| rule.uses("nearDeathSpot");
	}

	static boolean saysAnyOf(SpeechRule rule, String... placeholders)
	{
		if (rule.say != null)
		{
			for (String line : rule.say)
			{
				for (String placeholder : placeholders)
				{
					if (line.contains(placeholder))
						return true;
				}
			}
		}
		return false;
	}

	/**
	 * The events that end an idle stretch.
	 *
	 * <p>NOT movement. The first version reset when the idle counter did, and
	 * that would have made the whole mechanism a no-op in exactly the session
	 * it was built from: a player pottering about a bank moves every few
	 * seconds, and each little stop re-arms the idle rules' rising edges -
	 * that is precisely HOW an "idle" session produces a line every forty-five
	 * seconds. Shuffling two tiles is not doing something. Fighting, stealing,
	 * skilling, killing, arriving somewhere new, or dying is.
	 */
	static final Set<Type> REAL_ACTIVITY =
		java.util.EnumSet.of(
			ANIMATION,
			COMBAT_START,
			THIEVING_START,
			NPC_KILL,
			LOOT,
			LEVEL_UP,
			REGION_CHANGE,
			PLAYER_DEATH,
			WANT_FULFILLED,
			// Answering is the most direct evidence of a person there is:
			// somebody read a question and chose. Without it the damper could
			// silence the follower MID-CONVERSATION - the guessing game asks
			// you to stand still, so a player who then only clicks dialog
			// options never moves camera or feet, and the reveal of which
			// hand it was went to an "empty chair" that was answering it.
			ANSWERED);

	/** How long the NEXT idle remark has to wait, given the stretch so far. */
	long trailWaitMs()
	{
		if (idleStretchSpoken < IDLE_FREE_REMARKS)
			return 0L;
		long steps = idleStretchSpoken - IDLE_FREE_REMARKS + 1;
		// TRAIL_STEP_GAPS: Each remark past the free ones waits this many gaps longer than the last.
		// TRAIL_CAP_GAPS: The wind-down stops growing here: never rarer than one per this many gaps.
		return Math.min(200L /* TRAIL_CAP_GAPS */, steps * 30L /* TRAIL_STEP_GAPS */) * globalCooldownMs;
	}

	boolean muted;

	/**
	 * A cutscene, or the quiet after one, set by the plugin each tick. Lines
	 * are held as under the mute, but an occasion waits it out rather than
	 * being lost to it (SCENE_WAIT_TICKS).
	 */
	boolean sceneQuiet;

	/**
	 * The cutscene itself, without the quiet after it: what can move a
	 * quest's step on under a line kept waiting (see the moved-on check).
	 */
	boolean inCutscene;

	/**
	 * Where "now" comes from.
	 *
	 * <p>Every window in this class is wall-clock - the speech gap, the held
	 * floor, each rule's cooldown, the director's rest - which made all of them
	 * untestable together. A simulation runs ten thousand ticks a second, so it
	 * sits inside the first rest period for its entire length and proves
	 * nothing about what happens after one. Real seconds cannot be spent
	 * waiting and a fake clock is the only honest way to walk hours of them.
	 *
	 * <p>Defaults to the real one and is only ever replaced by tests.
	 */
	LongSupplier clock = System::currentTimeMillis;

	void setClock(LongSupplier clock)
	{
		this.clock = clock == null ? System::currentTimeMillis : clock;
	}

	long now()
	{
		return clock.getAsLong();
	}

	long lastSpokeMs;

	String lastSpokenText = "";

	/**
	 * The last {@link #RECENT_LINES} things said, as TEMPLATES rather than as
	 * finished text. "{count}. I've been keeping track" is one line however
	 * many different numbers it has carried, and keying on the rendered version
	 * would let it through every time the count changed - which is every time.
	 */
	final ArrayDeque<String> recentLines = new ArrayDeque<>();
	final Set<String> recentLineSet = new HashSet<>();

	void noteRecentLine(String template)
	{
		if (Strings.isNullOrEmpty(template) || !recentLineSet.add(template))
		{
			// Already in the window: move it to the front by dropping the old
			// entry, or a line said twice would leave the window early.
			if (!Strings.isNullOrEmpty(template))
			{
				recentLines.remove(template);
				recentLines.addLast(template);
			}
			return;
		}
		recentLines.addLast(template);
		// RECENT_LINES: How many lines back the follower remembers having said, across every rule.
		// <p>A shuffle bag can only keep one rule honest about itself. It cannot
		// stop two rules that were written about the same thing - and there are
		// plenty, since a companion notices standing still in several different
		// ways - from handing the same observation back and forth. This is the
		// window that does.
		// <p>Twelve is a compromise with a real cost either way: too short and the
		// ping-pong survives, too long and a rule with two variants finds both of
		// them blocked and simply repeats anyway, having spent the effort.
		while (recentLines.size() > 12 /* RECENT_LINES */)
			recentLineSet.remove(recentLines.removeFirst());
	}

	Function<String, Long> questWitness;

	/**
	 * Asks the book whether the follower was there for a quest. Kept here and
	 * not only on the context, which every reset throws away.
	 */
	void setQuestWitness(Function<String, Long> lookup)
	{
		questWitness = lookup;
		getContext().setQuestWitness(lookup);
	}

	TriggerContext getContext()
	{
		if (context == null)
		{
			context = new TriggerContext(client);
			context.setQuestWitness(questWitness);
		}
		return context;
	}

	/** Refreshes the state snapshot. Call once per game tick, before dispatching. */
	void refreshContext()
	{
		var context = getContext();
		context.refresh();

		// Cheap, and it has to survive a reload: the rules are the source of
		// the boss list, so the context follows them rather than being told
		// once at startup and going stale the next time the file is saved.
		context.setBossNames(loader.getBossNames());

		// Synced here rather than pushed from wherever the count is loaded or
		// bumped, because there are several such places and the settling-in
		// damper being right depends on all of them remembering.
		director.setSessionCount(context.getSessionCount());


		// A want resolving is state becoming an event. It happens here rather
		// than in the plugin so the rules see it wherever the engine is driven
		// from, and exactly once - the poll consumes it.
		var want = context.poll("want");
		if (want != null)
		{
			// Counted as well as announced. A grudge then needs no machinery of
			// its own: "you have ignored me three times" is a tally condition,
			// and lives in phrases.json with everything else.
			boolean kept = want == WANT_FULFILLED;
			context.tally(kept ? "want:kept" : "want:missed");
			if (kept)
				// A favour done is a favour owed.
				context.noteFavour();
			dispatch(TriggerEvent.want(want, context.getWantLabel()));
		}

		if (context.poll("underfoot") != null)
			dispatch(TriggerEvent.simple(UNDERFOOT));
	}

	/**
	 * Drops the held floor.
	 *
	 * <p>Must happen on a rule reload. The exemption that lets the holder speak
	 * through its own hush is identity-based, and a reload parses every rule
	 * afresh - so the holder becomes an object nothing points at any more, and
	 * the hush it left behind silences the whole file until it times out.
	 */
	void clearFloor()
	{
		hushUntilMs = 0L;
		hushOwner = null;
	}

	/** Holds the floor for the rule's {@code hushMs}, if it says something and has one. */
	void takeFloor(SpeechRule rule, long now)
	{
		if (rule.hushMs != null && rule.hushMs > 0 && rule.hasSpeech())
		{
			hushUntilMs = now + rule.hushMs;
			hushOwner = rule;
		}
	}

	/**
	 * Clears everything mid-flight but KEEPS the state snapshot.
	 *
	 * <p>For a world hop, where the scene goes and the player does not. What
	 * the follower is feeling, hoping for and counting are facts about the
	 * session rather than about the scene, and throwing them away because the
	 * world number changed is how a want quietly disappears on the way
	 * somewhere.
	 */
	void resetForNewScene()
	{
		lastSpokeMs = 0L;
		// A line still waiting is let go unsaid, its cooldown given back, as a
		// line whose moment passed is: behaviour QA4, 16 Oct, Sergeant Tobyn's
		// line waited its gap across a hop and was gone for the hour, with him
		// still beside the player.
		for (var delayed : pending)
		{
			delayed.rule.markFired(delayed.firedBefore);
			givenBack.add(delayed.rule);
		}
		pending.clear();
		// The plugin clears its queue with the scene, so those lines never land.
		unlanded.clear();
		// An announcement waiting on the old scene's prime window belongs to
		// that scene, not to the one arriving.
		afterPriming.clear();
		clearFloor();
		for (var rule : loader.getRules())
			// Edges only. The scene changed; what the follower has already said
			// did not, and neither did the player's memory of hearing it.
			rule.resetEdges();
	}

	void reset()
	{
		context = null;
		lastSpokeMs = 0L;
		afterPriming.clear();
		givenBack.clear();
		director.reset();
		recentLines.clear();
		recentLineSet.clear();
		idleStretchSpoken = 0;
		lastIdleRemarkMs = 0L;
		pending.clear();
		unlanded.clear();
		// A held floor must not outlive the thing that held it: toggling the
		// plugin mid-hush would otherwise leave the follower mute for it.
		clearFloor();
		// Edges only, as at a hop: what was said is kept through a logout,
		// cooldowns and bags. Text QA5, 17-18 Oct: every relog wiped the
		// cooldowns, so the two-hour fence book came back twelve minutes on,
		// and the nickname was asked again either side of a relog.
		for (var rule : loader.getRules())
			rule.resetEdges();
	}

	/**
	 * {@link #reset}, and every rule's cooldown and bag too: for a follower
	 * whose memory is not the one these were spent in - a profile switch,
	 * Forget everything, another account logging in.
	 */
	void forget()
	{
		reset();
		forgetWhatWasSaid();
	}

	void forgetWhatWasSaid()
	{
		for (var rule : loader.getRules())
			rule.reset();
	}

	/** The account whose cooldowns the rules hold. */
	long account = -1L;

	/** A login: another account than the last starts its cooldowns over. */
	void loggedInAs(long accountHash)
	{
		if (accountHash != account)
		{
			account = accountHash;
			forgetWhatWasSaid();
		}
	}

	/** Whether what a waiting line advises was done while it waited: the teleport before "Get out!". */
	boolean answered(PendingSpeech delayed)
	{
		var advice = delayed.rule.advise;
		return advice != null && advice.ids != null && getContext().actedSince(advice.ids, delayed.wonTick);
	}

	/** A won rule waiting out its delayTicks before speaking. */
	static class PendingSpeech
	{
		final SpeechRule rule;
		final TriggerEvent event;
		/** The wait as drawn at the win - kept for the log, since a ranged delay is not on the rule. */
		final int delay;
		int ticksLeft;
		/** Ticks an occasion has spent waiting out the gap after another line. */
		int waited;
		/** The line that gap is after: a new line said starts the count again. */
		long gapAfterMs;
		/** Ticks an occasion has spent waiting out a scene, its quiet and the gap after, apart from the gap's ten. */
		int sceneWaited;
		/** Ticks a waits line has spent waiting out the director's rest. */
		int rested;
		/** Held by a conversation, and not yet given its beat after it. */
		boolean heardTheBox;
		/** The rule's last firing before this win, given back if the line is let go unsaid. */
		final long firedBefore;
		/** The game tick it won on. */
		final int wonTick;
		/** A callback about the same person won meanwhile: the plain line stands aside. */
		boolean stoodAside;

		PendingSpeech(SpeechRule rule, TriggerEvent event, int ticksLeft, long firedBefore, int wonTick)
		{
			this.rule = rule;
			this.event = event;
			this.delay = ticksLeft;
			this.ticksLeft = ticksLeft;
			this.firedBefore = firedBefore;
			this.wonTick = wonTick;
		}
	}

	final List<PendingSpeech> pending = new ArrayList<>();

	/**
	 * How long a line that waits its turn waits for the gap now, in ticks:
	 * its gap and two more. The gap stretches with mood and chattiness - 15
	 * seconds at a low mood on Occasional, nearly two minutes on Minimal - and
	 * a fixed six seconds dropped the quest's line again in every one of those.
	 */
	int occasionWaitTicks(SpeechRule rule)
	{
		// OCCASION_WAIT_TICKS: How long an occasion waits for the gap after another line, in ticks:
		// six seconds. Play test, 7 Oct: Waterfall Quest's reward levelled
		// Attack, the level line went first, and the quest-complete line two
		// seconds behind it met the gap and was dropped. The gap is there to keep
		// chatter apart, not to cost a quest its one line. The least it waits:
		// see {@link #occasionWaitTicks}.
		return Math.max(10 /* OCCASION_WAIT_TICKS */, (int) (gapFor(rule) / 600L) + 2);
	}

	/**
	 * The gap this rule keeps after the last line. A quest person's line - it
	 * waits its turn, and is about someone near - keeps an occasion's: quests
	 * QA4, 16 Oct, at Minimal the 45 s gap outlasted the first talk, and the
	 * boy's intro came as he got his ball back. The user's call.
	 */
	long gapFor(SpeechRule rule)
	{
		boolean person = Boolean.TRUE.equals(rule.waits) && rule.uses("npcNearby");
		// OCCASION_GAP_MS: The longest gap an occasion keeps after another line: eight seconds.
		// Quests QA, 16 Oct, at Minimal (45 s, the user's own setting): every
		// quest moment waited the full gap behind any line, the sketch prompt
		// included, and they landed a stage late, out of order or after the
		// scroll. The user's call: the moments break through. The gap still
		// thins out everything else.
		return rule.isOccasion() || person ? Math.min(moodScaledGap(), 8_000L /* OCCASION_GAP_MS */) : moodScaledGap();
	}

	/** Whether a firing held up for this reason waits a tick and tries again rather than being dropped. */
	static boolean waitsOutTheGap(SpeechRule rule, String held, int waited, int limit)
	{
		return "gap".equals(held) && rule.waitsItsTurn() && waited < limit;
	}

	/**
	 * How long an occasion waits out a cutscene and the quiet after it, in
	 * ticks: five minutes. Play test, 9 Oct: a line was said over the
	 * opening of Children of the Sun's cutscene. Everything is held there
	 * now, and an occasion - a quest's end, a boss - is said once the scene
	 * is over rather than lost to it. Past this it is old news.
	 */
	static final int SCENE_WAIT_TICKS = 500;

	/**
	 * Whether a firing held up by a scene waits a tick and tries again rather
	 * than being dropped, and the gap or the floor after another line once
	 * the scene is over: two occasions held by one scene are said one after
	 * the other at any chattiness, where the ten-tick wait lost the second to
	 * a gap of 45 seconds. An NPC conversation holds it the same way, inside
	 * the same five minutes, and so does the empty chair: QA, 15 Oct, a line
	 * with one chance that came while the player was away from the keys was
	 * dropped by the damper, where it can wait for them to be back.
	 */
	static boolean waitsOutTheScene(SpeechRule rule, String held, int waited)
	{
		return rule.waitsItsTurn() && waited < SCENE_WAIT_TICKS
			&& ("scene".equals(held) || "dialogue".equals(held) || "unattended".equals(held)
				|| (waited > 0 && ("gap".equals(held) || "hush".equals(held))));
	}

	/**
	 * How long a line that waits will wait out the director's rest, in
	 * ticks: the longest rest. One rest, not a queue through every one: the
	 * rest still happens, and the line comes after it. Behaviour QA, 15 Oct:
	 * Alina and Noah's line met a rest in a busy square and was gone for good.
	 */
	static final int REST_WAIT_TICKS = 75;

	/** Whether a line held by the director's rest waits it out rather than being dropped. Not an occasion: no rest holds one. */
	static boolean waitsOutTheRest(SpeechRule rule, String held, int rested)
	{
		return "relax".equals(held) && Boolean.TRUE.equals(rule.waits) && rested < REST_WAIT_TICKS;
	}

	/**
	 * A line handed to the sink that leaves something behind when it lands,
	 * and has not landed yet. The states it will set are named by the
	 * conditions that read them.
	 */
	@RequiredArgsConstructor
	static class Unlanded
	{
		final Set<String> states;
		final long handedOverMs;
	}

	final List<Unlanded> unlanded = new ArrayList<>();

	/**
	 * The longest a line handed to the plugin can wait before it lands or is
	 * dropped as stale. Past this it never lands, so nothing waits on it. A
	 * test holds it above the plugin queue's stale window.
	 */
	static final long LONGEST_WAIT_MS = 16_000L;

	/**
	 * Set at login: evaluations record every rule's edge state without firing
	 * until a couple of ticks have passed WITH the player's composition
	 * actually readable. The world as found at spawn is baseline, not news - a
	 * rule should react to what CHANGES afterwards (gear equipped mid-session),
	 * not to whatever the player logged in wearing.
	 *
	 * <p>Two subtleties bought by bugs: the composition can lag several ticks
	 * behind login, so the countdown only consumes ticks the context reports
	 * ready; and edges rise on ANY dispatch (the login welcome chat message,
	 * an animation), so priming gates every event, not just the tick
	 * heartbeat. Delayed firings already queued (the login greeting) ride the
	 * pending path and are unaffected.
	 */
	int primeTicksLeft;

	void primeEdgesOnNextTick()
	{
		primeTicksLeft = 2;
	}

	/** Announcements waiting for the prime window to drain. */
	final List<TriggerEvent> afterPriming = new ArrayList<>();

	/** Lines let go at a hop, to rise again once its baseline is taken. */
	final List<SpeechRule> givenBack = new ArrayList<>();

	/**
	 * Raises an event the plugin MEANT to raise - a world hop, an edited
	 * notebook - once the prime window has drained, or immediately if none is
	 * open.
	 *
	 * <p>These cannot simply be dispatched around the priming, and both ways
	 * of trying were wrong. Dispatched inside the window, the winner is
	 * discarded with everything else and the rule is silently dead. Dispatched
	 * just BEFORE arming it, the announcement lands on a rule set whose edges
	 * were cleared with the scene, so every piece of worn gear and the region
	 * underfoot rise on that same pass - and since one event has one winner
	 * and those rules outrank the announcement, the follower remarks on your
	 * gear as though you had just put it on and the hop goes unmentioned.
	 * Play report, exactly that.
	 *
	 * <p>Waiting is what makes it correct: the window baselines the state
	 * first, so by the time this lands, nothing else is rising and the
	 * announcement wins the pass it deserves to win.
	 */
	void dispatchAfterPriming(TriggerEvent event)
	{
		if (primeTicksLeft <= 0)
		{
			dispatch(event);
			return;
		}
		afterPriming.add(event);
	}

	/**
	 * When the floor is held, and by whom.
	 *
	 * <p>A handful of moments are worth more than whatever else the follower
	 * was about to say. Walking into the place it asked to be taken is the
	 * clearest: the region change raises an area line at the same instant, and
	 * two lines about the same arrival is one line too many - the wrong one
	 * usually winning, since the area rule has no delay and gets there first.
	 */
	long hushUntilMs;
	SpeechRule hushOwner;

	/**
	 * Told when a rule won its event and was held back anyway. Set by the
	 * plugin so the transcript can see the half of the story the player never
	 * does; left null everywhere else, including in tests.
	 */
	java.util.function.BiConsumer<SpeechRule, String> onSuppressed;

	void noteSuppressed(SpeechRule rule, String reason)
	{
		if (onSuppressed != null)
			onSuppressed.accept(rule, reason);
	}

	/**
	 * Whether a line that waits its turn is held for an NPC conversation:
	 * the box is up, or went under three ticks ago (the context rides out a
	 * page flip). Anything else said there is dropped by the plugin, and a
	 * line with one chance was lost with it. QA, 15 Oct (Children of the
	 * Sun): a quest's people were met by talking to them, so their lines came
	 * up as the box opened, and the moments held over a scene were released
	 * into the conversation the scene ran on into. Held, they are said once
	 * it is over.
	 *
	 * <p>Every other line is held back there too, as under the mute, rather
	 * than handed over to be hushed. Quests QA, 16 Oct: an idle line hushed
	 * in a long quest conversation still charged the gap, so at Minimal the
	 * quest's end waited 45 s behind a line nobody saw.
	 */
	boolean heldForTheBox()
	{
		return getContext().isDialogueOpen();
	}

	/**
	 * WHY this rule cannot speak, or null if it can.
	 *
	 * <p>Same decision as {@link #cannotSpeak}, phrased so the transcript can
	 * record the reason. A held-back line never reaches the player and so never
	 * reaches an impression, which makes it exactly the evidence needed to tell
	 * a follower with little to say from one that is being throttled.
	 */
	String blockedBy(SpeechRule rule, long now)
	{
		if (!rule.hasSpeech())
			return null;
		String quiet = muted ? "muted" : sceneQuiet ? "scene" : heldForTheBox() ? "dialogue" : null;
		if (quiet != null || (rule == hushOwner && now < hushUntilMs))
			return quiet;
		// Before the gap, because when both apply the director is the honest
		// answer: the gap is three seconds and would be gone by the next tick,
		// where a relax period is most of a minute and is the reason nothing
		// else got through either.
		String directed = director.blocks(rule, now);
		if (directed != null)
			return directed;
		// R15: speech scales to attention. With camera, feet and hands all
		// untouched this long, the world is playing to an empty chair -
		// reactions included, not just idle chatter. Occasions still land
		// (a warning matters the moment they glance back), and the rules
		// ABOUT the absence are exactly the ones that should speak into it.
		// Any input at all clears the state instantly.
		// UNATTENDED_DAMPER_TICKS: Three minutes with camera, feet and hands all untouched before the
		// damper (R15) decides nobody is watching. Deliberately past the
		// gone-away jokes' own threshold, so the follower notices the absence
		// out loud before it stops performing to it.
		if (getContext().getUnattendedTicks() >= 300 /* UNATTENDED_DAMPER_TICKS */
			&& !rule.isOccasion()
			&& !rule.uses("unattended"))
			return "unattended";
		// Ignored overtures rest. A question that lapsed unanswered is not
		// followed by another for a long while, and two ignored in one
		// session end the asking - a polite companion drops a hint twice and
		// lets it go, where re-asking at every cooldown reads as nagging.
		// A wish that lapsed unfulfilled rests more gently. Answering any
		// question, or granting any wish, clears the respective ledger.
		if (!Strings.isNullOrEmpty(rule.asks) && getContext().isAskBackedOff())
			return "ignored";
		if (isIdleRemark(rule) && now - lastIdleRemarkMs < trailWaitMs())
			return "trailing";
		if (now - lastSpokeMs < gapFor(rule))
			return "gap";
		if (now < hushUntilMs)
			return "hush";
		// An occasion still in its beat has the floor already: anything else
		// waits behind it, as behind a line just said, or goes. Quests QA5
		// #54: Traiborn's intro, kept through the puzzle's boxes, and another
		// time a wish, went in the beat before the thingummywut the last box
		// raised, which then waited its gap into Persten's box and was lost.
		if (!rule.isOccasion() && pending.stream().anyMatch(waiting -> waiting.rule.isOccasion()))
			return "gap";
		return null;
	}

	/**
	 * The speech gap, stretched or shortened by how the follower feels.
	 *
	 * <p>Mood already decides WHAT it says. Until now it had no say in HOW MUCH,
	 * so a follower having a bad day recited sad lines at exactly the rate it
	 * recited cheerful ones - which reads as a costume rather than a mood.
	 * Somebody in a bad way talks less. Somebody in a good one talks over you.
	 *
	 * <p>Applied to the shared gap rather than to any rule, so it thins out
	 * everything evenly instead of silencing particular things: the follower
	 * still says what matters, just with more room around it.
	 */
	long moodScaledGap()
	{
		return gapForMood(globalCooldownMs, getContext().getMoodBand());
	}

	/**
	 * The mapping itself, as a function of the band rather than of the engine,
	 * so a test can walk every band without having to make real seconds pass.
	 */
	static long gapForMood(long base, String band)
	{
		switch (Strings.nullToEmpty(band))
		{
			case "low":
				return base * 5 / 2;
			case "down":
				return base * 3 / 2;
			case "good":
				return base * 4 / 5;
			case "high":
				return base * 3 / 5;
			default:
				return base;
		}
	}

	/**
	 * Runs one evaluation pass. Every rule's edge state is updated regardless of
	 * whether it can speak, so cooldowns and mutes never desynchronise the edges.
	 */
	void dispatch(TriggerEvent event)
	{
		long now = now();

		// A memory restored in the old vague words is said again from its
		// particulars before anything can bring it up. Here rather than at
		// the restore, which runs before the rules and place names are in.
		if (getContext().isIncidentToRetell())
		{
			var retold = retold(false);
			getContext().retellIncident(retold.isEmpty() ? null : retold.get(0));
		}

		// An animation the player played may be them doing the thing they were
		// just told to. Offered before the rules run, so the settling and the
		// reaction land on the same tick rather than a tick apart.
		if (event.getType() == ANIMATION && event.getId() != -1)
			getContext().offerAct(event.getId());

		// Doing something real ends the idle stretch, and the follower perks
		// back up. Checked on the event rather than on movement - see the note
		// on REAL_ACTIVITY for why a step is not enough. It is also evidence
		// of presence: you cannot level up from the kettle.
		if (REAL_ACTIVITY.contains(event.getType()))
		{
			idleStretchSpoken = 0;
			getContext().noteAttention();
		}

		// Delayed firings count down on the tick heartbeat and speak through
		// the same guarded path as everything else when their beat arrives.
		if (event.getType() == TICK && !pending.isEmpty())
		{
			// Most important first, when several come free on one tick; level
			// ones keep the order they won in. Quests QA, 16 Oct: Prince
			// Itzla's line went ahead of the bag moment it was held with.
			// Occasions go before the rest, in the order they won: quests
			// QA4, 16 Oct, the scroll's line went ahead of a moment held
			// through the hand-in, and "It's stopped. I'm giving it a moment
			// to be sure." came after "Witch's House. Nice scroll."
			pending.sort(java.util.Comparator.comparing((PendingSpeech p) -> !p.rule.isOccasion())
				.thenComparingInt(p -> p.rule.isOccasion() ? p.wonTick : -p.rule.priority));
			var it = pending.iterator();
			while (it.hasNext())
			{
				var delayed = it.next();
				if (delayed.stoodAside)
				{
					it.remove();
					noteSuppressed(delayed.rule, "callback");
					continue;
				}
				if (--delayed.ticksLeft <= 0)
				{
					// A cutscene that moves its quest's step on makes a line
					// about the step before old news: two scenes stale, and
					// "Questioning" said after the questioning. Let go
					// unspent. A pan that leaves the step alone does not do
					// it, nor a conversation alone: that is usually the very
					// step it moves on, and the line is still about what came
					// just before. Behaviour QA, 16 Oct: "a scene began since
					// the win" lost a line to an unrelated pan, and missed a
					// second scene that started inside the first one's quiet.
					if (inCutscene && !delayed.rule.when.questStepHolds(getContext(), delayed.event))
					{
						it.remove();
						noteSuppressed(delayed.rule, "moved-on");
						continue;
					}
					String held = blockedBy(delayed.rule, now);
					// The beat after a conversation is for the tick the box
					// goes. Held by anything else first, it waits its gap
					// like any other line, rather than jumping a moment
					// that came up since.
					if (held != null && !"dialogue".equals(held))
						delayed.heardTheBox = false;
					if (waitsOutTheScene(delayed.rule, held, delayed.sceneWaited))
					{
						delayed.sceneWaited++;
						delayed.heardTheBox |= "dialogue".equals(held);
						delayed.ticksLeft = 1;
						continue;
					}
					// A beat after the conversation: what its end raises - the
					// quest's step, moved on in it - goes first, and a line
					// held from before waits its gap behind it. Not a moment:
					// it came before the box, and the scroll its close raises
					// comes after it (quests QA5, Witch's House: "It's
					// stopped." 8 s after the scroll's line).
					if (held == null && delayed.heardTheBox && !delayed.rule.isOccasion())
					{
						delayed.heardTheBox = false;
						delayed.ticksLeft = 1;
						continue;
					}
					// The gap counted from the line it is behind: one said
					// while it waits starts the count again (QA, 15 Oct: the
					// second of two moments behind an area line was dropped a
					// tick before its gap ran out).
					if (delayed.gapAfterMs != lastSpokeMs)
					{
						delayed.gapAfterMs = lastSpokeMs;
						delayed.waited = 0;
					}
					if (waitsOutTheGap(delayed.rule, held, delayed.waited, occasionWaitTicks(delayed.rule)))
					{
						delayed.waited++;
						delayed.ticksLeft = 1;
						continue;
					}
					if (waitsOutTheRest(delayed.rule, held, delayed.rested))
					{
						delayed.rested++;
						delayed.ticksLeft = 1;
						continue;
					}
					it.remove();
					// Kept waiting, the moment it was about can pass: the
					// player ate, or the person walked off, or did what a
					// warning was about to advise. Let go unsaid, with its
					// cooldown given back, so it rises the next time it is true.
					if (held == null && (!delayed.rule.when.standingHolds(getContext(), delayed.event)
						|| answered(delayed)))
					{
						delayed.rule.markFired(delayed.firedBefore);
						noteSuppressed(delayed.rule, "passed");
						continue;
					}
					if (held == null)
					{
						// Won in a scene's quiet, it took no floor then (see
						// the win), so it takes it now, as it is said. Quests
						// QA5 #53: the grave Persten moment comes out of a scene.
						if (!(hushOwner == delayed.rule && now < hushUntilMs))
							takeFloor(delayed.rule, now);
						speak(delayed.rule, delayed.event, now);
					}
					else
						noteSuppressed(delayed.rule, held);
				}
			}
		}

		SpeechRule winner = null;

		for (var rule : loader.getRules())
		{
			boolean matching;
			try
			{
				matching = rule.when.matches(getContext(), event);
			}
			catch (RuntimeException e)
			{
				log.warn("Rule '{}' threw while evaluating; disabling it", rule.describe(), e);
				rule.enabled = Boolean.FALSE;
				continue;
			}

			boolean rising = rule.risingEdge(matching);

			// A memory is filed by every rule that rose, not only the one that
			// gets to speak: the remember rules sit under the reaction lines
			// on purpose (the reaction is the line worth hearing), and filing
			// only from the winner meant the drop and the boss were almost
			// never remembered. Not while primed, when nothing is news yet.
			// And whatever is silenced: turning a group off quietens what the
			// follower says, as the Reminiscing setting promises, not what it
			// remembers - the Memory window is where remembering is undone.
			if (rising && rule.isEnabled() && primeTicksLeft == 0)
				file(rule, event);

			if (!rising || !isActive(rule) || !rule.offCooldown(now) || isWaiting(rule)
				|| awaitsALanding(rule, now))
				continue;

			// Belt and braces: the loader already hands rules over sorted by
			// priority descending, so the comparison can never actually differ
			// from "first match wins". Both are kept deliberately - the sort is
			// what makes this loop cheap, the comparison is what makes the
			// invariant true independently of it. Mutating either alone leaves
			// the behaviour correct, which is worth knowing before anyone
			// "simplifies" one of them away.
			if (winner == null || rule.priority > winner.priority)
				winner = rule;
			// Level with the winner, a line that waits lost on file order
			// alone. It rises again on the next pass and is said behind it.
			// Behaviour QA, 15 Oct: Prince Itzla and Sergeant Tobyn came into
			// view on one tick, and Itzla's line was never said. Not one a
			// point below, which is outranked on purpose (a callback over its
			// base), nor an occasion: two of those level on one event are
			// each other's alternatives (the third death and "again").
			else if (rule.priority == winner.priority && Boolean.TRUE.equals(rule.waits))
				rule.riseAgain();
		}

		// Something just ENDED: open the breather window (R6). Noted AFTER the
		// evaluation loop on purpose - a boundary rule should rise on the NEXT
		// pass rather than competing with the ending's own reaction on this
		// event, where losing would consume its edge for the whole window. The
		// breather comes after the reaction, which is also the right order to
		// hear them in.
		switch (event.getType())
		{
			case COMBAT_END:
				getContext().noteBoundary("combat");
				break;
			case LEVEL_UP:
				getContext().noteBoundary("level");
				break;
			case REGION_CHANGE:
				getContext().noteBoundary("arrival");
				break;
			case THIEVING_END:
				getContext().noteBoundary("thieving");
				break;
			default:
				break;
		}

		// While primed (just after login), edges have been recorded above but
		// nothing fires from ANY event: worn gear and standing state register
		// as already-true instead of as fresh rising edges. The countdown only
		// consumes ticks where the player composition is actually readable -
		// before that, "no equipment" is an artefact of loading, not a state.
		if (primeTicksLeft > 0)
		{
			if (event.getType() == TICK && getContext().isPlayerReady()
				&& --primeTicksLeft == 0)
			{
				// The baseline is taken; anything held back now lands on a rule
				// set where only it is rising. Drained into a copy first, so a
				// re-entrant dispatch cannot see the queue twice.
				List<TriggerEvent> held = new ArrayList<>(afterPriming);
				afterPriming.clear();
				for (var announcement : held)
					dispatch(announcement);
				// Then a line let go at a hop rises on the next pass, if what it
				// was about is still so: behaviour QA5, the hop's baseline took
				// Tobyn beside the player as given, and his line waited for him
				// to leave and come back.
				for (var rule : givenBack)
					rule.riseAgain();
				givenBack.clear();
			}
			return;
		}

		if (winner == null)
			return;

		// A callback about a quest's person: a plain line about them already
		// waiting is let go now, at the win, since the two are one line.
		// Behaviour QA, 16 Oct: the person came by with a box up, the plain
		// line was held for it, the callback rose as it closed, and both
		// were said 6 s apart.
		String plain = winner.plainLineId();
		if (plain != null)
		{
			for (var waiting : pending)
				waiting.stoodAside |= plain.equals(waiting.rule.id);
		}

		// Taking the floor happens at the WIN, not when the line finally comes
		// out. A rule with a delay would otherwise leave its own gap open: the
		// want-fulfilled line waits a few ticks, and the region-change line
		// that arrives later in the same tick would walk straight into it.
		// Not at a win the scene holds: the floor of a line never said would
		// outlast the quiet and cost the occasions waiting it out.
		if (!sceneQuiet)
			takeFloor(winner, now);

		// A delayed rule queues instead of speaking now; the cooldown is
		// charged at the win so re-triggers don't stack up more firings. The
		// wait is drawn HERE, once, so a ranged delay stays put while pending.
		int delay = winner.rollDelayTicks();
		long firedBefore = winner.lastFiredMs();
		if (delay > 0)
		{
			winner.markFired(now);
			pending.add(new PendingSpeech(winner, event, delay, firedBefore, client.getTickCount()));
			return;
		}

		String blocked = blockedBy(winner, now);
		if (waitsOutTheGap(winner, blocked, 0, occasionWaitTicks(winner)) || waitsOutTheScene(winner, blocked, 0)
			|| waitsOutTheRest(winner, blocked, 0))
		{
			winner.markFired(now);
			var held = new PendingSpeech(winner, event, 1, firedBefore, client.getTickCount());
			held.gapAfterMs = lastSpokeMs;
			held.heardTheBox = "dialogue".equals(blocked);
			pending.add(held);
			return;
		}
		if (blocked != null)
		{
			// Still charge the cooldown so a suppressed rule doesn't fire the instant
			// the global window opens.
			noteSuppressed(winner, blocked);
			winner.markFired(now);
			return;
		}

		speak(winner, event, now);
	}

	/** Speaks an arbitrary line, bypassing rules — used by the chat commands. */
	void say(String text, SpeechOutput output)
	{
		if (sink == null || Strings.isNullOrEmpty(text))
			return;
		lastSpokeMs = now();
		lastSpokenText = text;
		sink.speak(text, output == null ? defaultOutput : output, null, -1, () -> { });
	}

	/**
	 * Says a line of the follower's own that no rule wrote - the remark after
	 * a sketch - where the settings put speech, and not at all under the
	 * mute, or in a scene and the quiet after it. {@link #say} is the
	 * player's own command and speaks through the mute on purpose; a line
	 * nobody asked for has no such excuse, and went straight to the
	 * overhead, muted or not. Nor while a line holds the floor: behaviour
	 * QA5, 17 Oct, the sketch invite went out three ticks into a login, and
	 * the hello was lost to the gap behind it.
	 */
	void remark(String text)
	{
		if (!muted && !sceneQuiet && now() >= hushUntilMs)
			say(text, null);
	}

	/**
	 * Says a rule this instant, whatever its conditions, cooldown and the mute
	 * have to say about it.
	 *
	 * <p>For testing a rule you cannot conveniently provoke. Several of them
	 * only happen on a five percent roll after a minute of standing still, or
	 * on the hundredth login, and waiting for one of those in a live client is
	 * not testing, it is hoping.
	 *
	 * <p>Everything the rule carries still happens - the animation, the mood
	 * nudge, {@code asks}, {@code want} - because the point is to exercise the
	 * whole path rather than only the words. Placeholders that come from an
	 * event ({npc}, {want}, {value}) have no event to come from here and will
	 * print literally; that is the honest cost of firing something out of
	 * nowhere.
	 *
	 * @return whether a rule by that id exists
	 */
	boolean force(String ruleId)
	{
		for (var rule : loader.getRules())
		{
			if (ruleId.equalsIgnoreCase(rule.id))
			{
				long now = now();
				// Including the floor, so what you see when testing is what the
				// rule really does rather than a quieter version of it.
				takeFloor(rule, now);
				speak(rule, TriggerEvent.simple(MANUAL), now);
				return true;
			}
		}
		return false;
	}

	void speak(SpeechRule rule, TriggerEvent event, long now)
	{
		String drawn = rule.pickPhrase(recentLineSet,
			line -> getContext().lineWear(line));
		String filled = spokenText(drawn, event);
		// Filled too long to fit over the head, a line gives way to the
		// rule's first that fits: a place's memory has one way of being
		// said, and one that will not fit "You may not remember. This is
		// where ..." still fits "Same spot. This is where ..." (behaviour
		// QA5, measured).
		if (!fitsOverhead(filled) && rule.say != null)
		{
			for (String other : rule.say)
			{
				String fits = spokenText(other, event);
				if (fitsOverhead(fits))
				{
					drawn = other;
					filled = fits;
					break;
				}
			}
		}
		String template = drawn,
			text = filled;
		var animation = rule.resolveAnimation(event);

		// A mirroring rule triggered by something OTHER than an animation event
		// - the repeating condition, which is how the follower joins in with
		// what the player is doing - has no id on the event to copy. The
		// player's current repeating animation is the thing being copied, and
		// only the state snapshot knows it.
		//
		// Which of the two the rule asks for matters, and the cache decides it:
		// mining, woodcutting, fishing and fletching are authored loops
		// (frameStep >= 0) and have to be held as a POSE, because playing one
		// as an emote waits forever for an end that never comes and leaves the
		// follower stuck mid-swing. Cooking, smithing, herblore and firemaking
		// are one-shots the server restarts each cycle, and mirrorAnimation
		// gives those a single honest go.
		if (animation == null
			&& (Boolean.TRUE.equals(rule.mirrorPose) || Boolean.TRUE.equals(rule.mirrorAnimation)))
		{
			int repeating = getContext().getRepeatingAnimation();
			animation = repeating > 0 ? repeating : null;
		}
		if (text.isEmpty() && animation == null && !rule.hasAnimationChain())
			return;

		rule.markFired(now);

		// A callback about a quest's person stands aside the plain line about
		// them for that line's own while. QA, 15 Oct: two Duke callbacks, then
		// "Duke Horacio himself" as if they had never met, in six minutes.
		// Its fellow callbacks about the same person stand aside too: Text
		// QA 3, the Duke's two callbacks came two minutes apart.
		String plain = rule.plainLineId();
		if (plain != null)
		{
			String fellows = rule.id.substring(0, rule.id.indexOf("-after-") + 7);
			for (var other : loader.getRules())
			{
				if (plain.equals(other.id) || (other.id != null && other.id.startsWith(fellows)))
					other.markFired(now);
			}
		}

		// One thing remembered at a time: text QA4, 16 Oct, "My mind goes back
		// to the guard with the very large bag" and, 16 s later, "The notes on
		// the guard with the very large bag start here." The other rules that
		// bring up a memory wait ten minutes, or their own while if it is left.
		if (bringsUpAMemory(rule))
		{
			for (var other : loader.getRules())
			{
				if (other != rule && bringsUpAMemory(other))
					// MEMORY_APART_MS: How long after one rule brings up a memory the others wait: ten minutes.
					other.markFired(Math.max(other.lastFiredMs(), now - other.cooldownMs + 600_000L /* MEMORY_APART_MS */));
			}
		}

		// Mood moves with what the follower ACTUALLY did. Applying it here
		// rather than at the win means a rule held back by a cooldown, a
		// disabled group or the mute does not quietly move the mood while
		// saying nothing - the state and the words stay one story.
		if (rule.mood != null && rule.mood != 0)
			getContext().adjustMood(rule.mood);

		// A question only counts as asked once it has actually been said - a
		// rule silenced by the mute must not leave the follower waiting for an
		// answer to something nobody heard. The same goes for the want and the
		// wish, and "said" is the sink's moment, not this method's: the plugin
		// queues lines behind the overhead box, and a queued line can still be
		// dropped - aged out, displaced by a full queue, cleared with the
		// scene, hushed by an NPC dialogue. Each of these three later puts an
		// interaction in front of the player (a conversation, a thank-you, a
		// gift option in the Talk-to box), so opening them on a line nobody saw
		// leaves that interaction unexplained. They latch when the sink says the
		// line landed, and so does everything else a line leaves behind.
		//
		// Until it lands, a rule reading what it leaves behind waits for it.
		Set<String> leaves = text.isEmpty()
			? Collections.emptySet() : leavesBehind(rule);
		var landing = leaves.isEmpty() ? null : new Unlanded(leaves, now);
		Runnable onSaid = () ->
		{
			unlanded.remove(landing);
			// The wear ledger counts what was HEARD, not what was queued -
			// a line the queue dropped has not worn out its welcome.
			if (!text.isEmpty())
				getContext().noteLineSaid(template);
			if (leaves.contains("asking"))
				getContext().noteQuestion(rule.asks);
			if (leaves.contains("wanting"))
				getContext().setWant(rule.want.region, rule.want.label,
					rule.want.minutes == null ? 15 : rule.want.minutes);

			// A first is only spent once it has been heard. A line the mute,
			// the queue or the dialogue hush swallowed was never said, and
			// burning the one chance the follower had to say it would be the
			// worst possible place to be strict. While a copy waits in the
			// queue, the rule's cooldown keeps it from winning again; a lint
			// holds every first's cooldown longer than the queue's wait.
			if (rule.isOnce() && !text.isEmpty())
				getContext().noteSaidOnce(rule.onceKey());
			if (isIdleRemark(rule) && tellsTheIncident(rule) && !text.isEmpty())
				getContext().noteIncidentRecalled(now());
		};

		// The pacing is charged at the hand-over, heard or not: it only spaces
		// the lines out. A line the plugin then drops still costs its gap, so
		// what a conversation would hush is held back above instead (QA3 #10:
		// at Minimal that gap cost the quest's end 45 s).
		if (!text.isEmpty())
		{
			// Only actual speech resets the global window; an animation-only
			// firing should not push back the next spoken line.
			lastSpokeMs = now;
			lastSpokenText = text;
			director.noteSpoke(rule, now);
			noteRecentLine(template);
			if (isIdleRemark(rule))
			{
				idleStretchSpoken++;
				lastIdleRemarkMs = now;
			}
		}

		var output = SpeechOutput.parse(rule.output, defaultOutput);
		if (sink != null)
		{
			// Before the hand-over, since a sink with the floor free lands it at once.
			if (landing != null)
				unlanded.add(landing);
			sink.speak(text, output, rule, animation == null ? -1 : animation, onSaid);
		}
	}

	/** How recent a fight has to be for a memory filed now to be about it, in ticks: six seconds. */
	static final int RECENT_FIGHT_TICKS = 10;

	/** What a rule writes down when it rises: the incident, and the place. */
	void file(SpeechRule rule, TriggerEvent event)
	{
		boolean marks = !Strings.isNullOrEmpty(rule.markHere);
		if ((rule.remember == null || rule.remember.key == null) && !marks)
			return;
		// The particulars are filled in NOW, while the event and the moment
		// still know them; a placeholder with nothing to say drops the phrase
		// back to a plainer form rather than filing a hole. The last thing
		// fought is never forgotten by the context, so only a fight going on,
		// or just over, is this memory's. QA, 15 Oct: a quest finished an
		// hour after a ram fight was filed "with the Ram", and the next Ram
		// brought the quest up.
		boolean fighting = getContext().foughtWithin(RECENT_FIGHT_TICKS);
		// Chased rather than fighting, what was hitting the player is the
		// foe: behaviour QA5, run down in the Abyss with nothing targeted.
		String attacker = fighting ? "" : getContext().getRecentAttacker(RECENT_FIGHT_TICKS);
		if (!attacker.isEmpty())
			event.getPlaceholders().putIfAbsent("foe", attacker);
		boolean foeKnown = fighting || !attacker.isEmpty();

		// An incident is filed whether or not the line was heard: the chicken
		// killed you regardless of whether the follower got a word in.
		if (rule.remember != null && rule.remember.key != null)
		{
			String phrase = firstFilled(rule.remember.forms(), event, foeKnown),
				who = event.getPlaceholders().getOrDefault("npc", "");
			if (who.isEmpty() && foeKnown)
				who = fighting ? getContext().getCombatTarget() : attacker;
			getContext().noteIncident(rule.remember.key, phrase, who,
				event.getPlaceholders().getOrDefault("item", ""), getContext().getHitpoints(),
				System.currentTimeMillis());
		}

		// And the same moment against the place, when the rule says so, in
		// the same way: text QA5, 17 Oct, "This is where it went wrong for
		// you." said what happened nowhere in it.
		if (marks)
		{
			List<String> forms = new ArrayList<>();
			forms.add(rule.markHere);
			if (rule.markHereOr != null)
				forms.addAll(rule.markHereOr);
			getContext().notePlaceMemory(firstFilled(forms, event, foeKnown));
		}
	}

	/** Each form in turn, filled: the first with nothing missing, or the last whatever it has. */
	String firstFilled(List<String> forms, TriggerEvent event, boolean foeKnown)
	{
		String phrase = "";
		for (int i = 0; i < forms.size(); i++)
		{
			String form = forms.get(i);
			boolean[] incomplete = {false};
			phrase = substitute(form, event, incomplete, false);
			if (i == forms.size() - 1
				|| (!incomplete[0] && (foeKnown || !form.contains("{foe}"))))
				break;
		}
		return phrase;
	}

	boolean isActive(SpeechRule rule)
	{
		if (!rule.isEnabled() || (rule.isOnce()
			&& (getContext().hasSaidOnce(rule.id) || getContext().hasSaidOnce(rule.onceKey()))))
			return false;
		// A memory that would only come out vague is not brought up at all:
		// "I was rereading the entry on the way that went" tells the player
		// nothing about which moment it was. Nor one too fresh to be a memory
		// yet, nor brought up unprompted twice in a day.
		if (tellsTheIncident(rule) && (memoryPhrases().isEmpty() || getContext().isIncidentFresh(now())
			|| (isIdleRemark(rule) && getContext().wasIncidentRecalledToday(now()))))
			return false;
		String group = rule.group == null ? "misc" : rule.group.toLowerCase(Locale.ROOT);
		return !disabledGroups.contains(group)
			&& !(rule.id != null && disabledGroups.contains(rule.id.toLowerCase(Locale.ROOT)));
	}

	/**
	 * Whether a firing of this rule is already waiting its turn. A hold can
	 * outlast a short cooldown - a low-health warning kept through a long
	 * conversation - and a second copy queued behind the first was said
	 * straight after it once both were let go.
	 */
	boolean isWaiting(SpeechRule rule)
	{
		for (var waiting : pending)
		{
			if (waiting.rule == rule)
				return true;
		}
		return false;
	}

	/**
	 * Whether the rule reads a state that a line still on its way will set.
	 * Those states latch when the line lands, so judged now, "none advising"
	 * would open a dare over advice waiting in the queue. The rule is held
	 * back until the line lands or can no longer land, and gets its turn when
	 * its trigger comes round again. The gift's never does, so it is not held.
	 */
	boolean awaitsALanding(SpeechRule rule, long now)
	{
		unlanded.removeIf(line -> now - line.handedOverMs > LONGEST_WAIT_MS);
		for (var line : unlanded)
		{
			for (String state : line.states)
			{
				if (rule.when.usesType(state))
					return true;
			}
		}
		return false;
	}

	/**
	 * What a line latches when it lands, named as the conditions that read
	 * it. Not the gift's pocket and wish: those are spent at the win.
	 */
	static Set<String> leavesBehind(SpeechRule rule)
	{
		Set<String> states = new HashSet<>();
		if (!Strings.isNullOrEmpty(rule.asks))
			states.add("asking");
		if (rule.want != null && rule.want.region != null)
			states.add("wanting");
		return states;
	}

	/**
	 * The longest line said over a head: the game's own limit for anything
	 * a player or NPC says there. QA, 15 Oct: a memory with its where and
	 * when ran to 92-151 characters, and fixed mode clips both ends of it.
	 */
	static final int OVERHEAD_MAX_CHARS = 80;

	/** The widest line said over a head, in pixels: wider is clipped in fixed mode. */
	static final int OVERHEAD_MAX_PX = 480;

	/** "That was {memoryWhen}." and the like: a sentence that only says when. */
	static final Pattern WHEN_SENTENCE =
		Pattern.compile("\\s*[^.?!]*\\{memory(?:When|Ago)\\}[^.?!]*[.?!]");

	/** The memory being tried while a line is fitted, in place of the one filed. */
	String memoryOverride;

	/**
	 * A template filled for saying. Over the limit, a line that tells a
	 * memory is filled again with less: first without its when, then
	 * without its where, then with the memory said a shorter way, from its
	 * rule's other forms. The fullest that fits is said; the moment itself
	 * is the point, and the particulars are what there may be no room for.
	 */
	String spokenText(String template, TriggerEvent event)
	{
		// A line that names the creature itself says the memory without it:
		// "A Hill Giant. I remember your death in Edgeville", never "... your
		// death to the Hill Giant".
		List<String> phrases = template != null && template.contains("{memory}")
			? memoryPhrases(template.contains("{memoryWho}")) : new ArrayList<>();
		if (phrases.isEmpty())
			phrases.add(null);
		String text = "";
		try
		{
			for (String phrase : phrases)
			{
				memoryOverride = phrase;
				for (String variant : shortenings(template))
				{
					text = substitute(variant, event, null, true);
					if (fitsOverhead(text))
						return text;
				}
			}
			return text;
		}
		finally
		{
			memoryOverride = null;
		}
	}

	boolean fitsOverhead(String text)
	{
		return text.length() <= OVERHEAD_MAX_CHARS
			&& (overheadWidth == null || overheadWidth.applyAsInt(text) <= OVERHEAD_MAX_PX);
	}

	/** The template, then without its memory's when, then without its where too. */
	static List<String> shortenings(String template)
	{
		List<String> out = new ArrayList<>();
		out.add(template);
		for (String shorter : new String[]{withoutMemoryWhen(template), withoutMemoryParticulars(template)})
		{
			if (shorter != null && !out.contains(shorter))
				out.add(shorter);
		}
		return out;
	}

	/**
	 * Every way the incident can be said, most particular first: as it was
	 * filed, then as its rule's forms say it from the particulars kept with
	 * it. Never a vague one, so empty when there is nothing specific to say.
	 */
	List<String> memoryPhrases()
	{
		return memoryPhrases(false);
	}

	/**
	 * @param withoutCreature only the ways that leave out who it was with:
	 * no form with a {foe} or an {npc} in it, and not the filed phrase if it
	 * names them
	 */
	List<String> memoryPhrases(boolean withoutCreature)
	{
		List<String> phrases = new ArrayList<>();
		var ctx = getContext();
		if (!ctx.hasIncident() || TriggerContext.isPlain(ctx.getIncidentPhrase()))
			return phrases;
		String filed = ctx.getIncidentPhrase(),
			who = ctx.getIncidentWho().toLowerCase(Locale.ROOT);
		if (!TriggerContext.isVague(filed)
			&& !(withoutCreature && !who.isEmpty() && filed.toLowerCase(Locale.ROOT).contains(who)))
			phrases.add(filed);
		for (String phrase : retold(withoutCreature))
		{
			if (!phrases.contains(phrase))
				phrases.add(phrase);
		}
		return phrases;
	}

	/**
	 * The incident in its rule's words, filled from the particulars kept
	 * with it: each form that has everything it needs, and is not vague.
	 */
	List<String> retold(boolean withoutCreature)
	{
		List<String> phrases = new ArrayList<>();
		var ctx = getContext();
		var remember = rememberFor(ctx.getIncidentKey());
		if (remember == null)
			return phrases;
		var particulars = TriggerEvent.combat(MANUAL, ctx.getIncidentWho());
		var values = particulars.getPlaceholders();
		values.put("foe", ctx.getIncidentWho());
		values.put("item", ctx.getIncidentItem());
		values.put("hp", ctx.getIncidentHp() < 0 ? "" : Integer.toString(ctx.getIncidentHp()));
		values.put("place", ctx.getIncidentPlace());
		values.put("where", ctx.getIncidentWhereSaid());
		for (String form : remember.forms())
		{
			if (withoutCreature && (form.contains("{foe}") || form.contains("{npc}")))
				continue;
			boolean[] incomplete = {false};
			String phrase = substitute(form, particulars, incomplete, false);
			if (!incomplete[0] && !TriggerContext.isVague(phrase) && !phrases.contains(phrase))
				phrases.add(phrase);
		}
		return phrases;
	}

	/** The remember block that files incidents under this key, or null. */
	SpeechRule.Incident rememberFor(String key)
	{
		for (var rule : loader.getRules())
		{
			if (rule.remember != null && key.equals(rule.remember.key))
				return rule.remember;
		}
		return null;
	}

	/** A page of a conversation tree, filled from the state like a spoken line: {candidate} and the rest. */
	String fill(String template)
	{
		return substitute(template, TriggerEvent.simple(MANUAL), null, true);
	}

	/**
	 * The template with {memoryWhere}, {memoryWhen} and {memoryAgo} taken
	 * out, or null when it has none or would lose the memory with them. The
	 * where brings its own " in", so it goes alone; the when goes with its
	 * comma, or with the sentence it has to itself.
	 */
	static String withoutMemoryParticulars(String template)
	{
		if (template == null || !template.contains("{memoryWhere}"))
			return withoutMemoryWhen(template);
		String shorter = template.replace("{memoryWhere}", "");
		if (saysWhen(shorter))
			shorter = withoutMemoryWhen(shorter);
		return shorter;
	}

	/** The template with only its when taken out, or null as above. */
	static String withoutMemoryWhen(String template)
	{
		if (template == null || !saysWhen(template))
			return null;
		String shorter = template.replace(", {memoryWhen}", "").replace(", {memoryAgo}", "");
		shorter = WHEN_SENTENCE.matcher(shorter).replaceAll("").trim();
		if (saysWhen(shorter) || (template.contains("{memory}") && !shorter.contains("{memory}")))
			return null;
		return shorter;
	}

	static boolean saysWhen(String template)
	{
		return template.contains("{memoryWhen}") || template.contains("{memoryAgo}");
	}

	/**
	 * Replaces {@code {placeholder}} tokens from the event and the state snapshot.
	 *
	 * @param incomplete set to true at [0] when a known placeholder resolved to nothing
	 * @param spoken whether this is a line to be said, whose sentences open on a capital
	 */
	String substitute(String template, TriggerEvent event, boolean[] incomplete, boolean spoken)
	{
		if (template == null || template.indexOf('{') < 0)
			return Strings.nullToEmpty(template);

		Map<String, String> values = new HashMap<>(event.getPlaceholders());
		var ctx = getContext();
		// Available wherever the state is: a callback line wants {memory}
		// whatever event happened to trigger it.
		String memory = memoryOverride != null ? memoryOverride : ctx.getIncidentPhrase();
		values.putIfAbsent("memory", memory);
		values.putIfAbsent("memoryWhere", ctx.memoryWhereFor(memory));
		values.putIfAbsent("memoryWhen", ctx.getMemoryWhen(System.currentTimeMillis()));
		values.putIfAbsent("memoryAgo", ctx.getMemoryAgo(System.currentTimeMillis()));
		values.putIfAbsent("memoryWho", ctx.getIncidentWho());
		// Where a memory filed now happened: "Edgeville", and "in Edgeville"
		// or "near Lumbridge" ready to follow it.
		values.putIfAbsent("place", ctx.getPlaceHere());
		values.putIfAbsent("where", ctx.getWhereHere());
		values.putIfAbsent("foe", ctx.getCombatTarget());
		values.putIfAbsent("here", ctx.getPlaceMemory());
		values.putIfAbsent("nickname", "");
		values.putIfAbsent("candidate", "");
		values.putIfAbsent("lastTime", ctx.getLastTime());
		values.putIfAbsent("days", Integer.toString(ctx.getDaysKnown()));
		values.putIfAbsent("hp", Integer.toString(ctx.getHitpoints()));
		values.putIfAbsent("maxHp", Integer.toString(ctx.getMaxHitpoints()));
		values.putIfAbsent("hpPercent", Integer.toString(ctx.getHitpointsPercent()));
		values.putIfAbsent("prayer", Integer.toString(ctx.getPrayerPoints()));
		values.putIfAbsent("maxPrayer", Integer.toString(ctx.getMaxPrayerPoints()));
		values.putIfAbsent("prayerPercent", Integer.toString(ctx.getPrayerPercent()));
		values.putIfAbsent("player", ctx.getPlayerName());
		values.putIfAbsent("region", Integer.toString(ctx.getRegionId()));

		var out = new StringBuilder(template.length() + 16);
		int i = 0;
		while (i < template.length())
		{
			char c = template.charAt(i);
			if (c != '{')
			{
				out.append(c);
				i++;
				continue;
			}

			int close = template.indexOf('}', i);
			if (close < 0)
			{
				out.append(template.substring(i));
				break;
			}

			String key = template.substring(i + 1, close),
				replacement = values.get(key);
			if (incomplete != null && (Strings.isNullOrEmpty(replacement)))
				incomplete[0] = true;
			if (!Strings.isNullOrEmpty(replacement) && !AS_WRITTEN.contains(key))
			{
				// "a {x} level" describes the level; "a {x}." is the x itself.
				boolean endsPhrase = close + 2 >= template.length()
					|| template.charAt(close + 1) != ' '
					|| !Character.isLetter(template.charAt(close + 2));
				// A name that brings its own "The" is a proper one.
				boolean named = replacement.regionMatches(true, 0, "the ", 0, 4);
				// Vorkath is somebody, not a kind of thing: never the Vorkath,
				// unless the article is for a noun after it.
				if (Words.isPersonalName(replacement) && !modifiesNoun(template, close))
					dropArticle(out);
				// The memory's own boss is the one there is: "That's the
				// Kraken", never "That's a Kraken" (text QA5).
				if ("memoryWho".equals(key) && ctx.isNamedBoss(replacement))
					definiteArticle(out);
				replacement = agreeArticle(out, replacement, endsPhrase);
				// After a pointing word a creature is a common noun: the guard,
				// a goblin, that monk of Zamorak. Bosses keep their capitals.
				if ((event.getCreatureKeys().contains(key) || "foe".equals(key) || "memoryWho".equals(key))
					&& !named
					&& afterAnArticle(out) && !ctx.isBoss(replacement,
						event.getType() == NPC_KILL ? event.getValue() : 0))
					replacement = Words.asCommonNoun(replacement);
				// A creature's own "The", or a page's, with nothing pointing at
				// it, is lower case mid-sentence: you beat the Leviathan, a page
				// on the Abyss (quests QA5 #56).
				if ((event.getCreatureKeys().contains(key) || CREATURE_NAMES.contains(key) || "page".equals(key))
					&& replacement.startsWith("The ") && !opensSentence(template, i))
					replacement = "t" + replacement.substring(1);
			}
			// The values are written for the middle of a sentence - "a feather",
			// "the local menace", "two minutes" - so one that opens a sentence
			// takes the capital the template left for it. A player's name is
			// spelled as its owner chose, so it keeps its own case.
			if (spoken && !Strings.isNullOrEmpty(replacement)
				&& !PLAYER_NAMES.contains(key) && opensSentence(template, i))
				replacement = Character.toUpperCase(replacement.charAt(0)) + replacement.substring(1);
			out.append(replacement == null ? template.substring(i, close + 1) : replacement);
			i = close + 1;
			if ("1".equals(replacement))
			{
				var unit = PLURAL_UNIT.matcher(template).region(i, template.length());
				if (unit.lookingAt())
				{
					out.append(' ').append(unit.group(1));
					i = unit.end();
				}
			}
		}

		return out.toString();
	}

	/** Whether the template follows the placeholder ending at {@code close} with a noun it describes. */
	static boolean modifiesNoun(String template, int close)
	{
		int start = close + 2;
		if (start >= template.length() || template.charAt(close + 1) != ' ')
			return false;
		int end = start;
		while (end < template.length() && Character.isLetter(template.charAt(end)))
			end++;
		return NAME_MODIFIES.contains(template.substring(start, end).toLowerCase(Locale.ROOT));
	}

	/** Makes an "a" or "an" at the end of the text so far a "the", keeping its capital. */
	static void definiteArticle(StringBuilder out)
	{
		String word = lastWord(out);
		if (isAOrAn(word))
			replaceLastWord(out, word, Character.isUpperCase(word.charAt(0)) ? "The" : "the");
	}

	/** The word the text so far ends on, before its space; null when it does not end on a space. */
	static String lastWord(StringBuilder out)
	{
		int space = out.length() - 1;
		if (space < 1 || out.charAt(space) != ' ')
			return null;
		int start = space;
		while (start > 0 && Character.isLetter(out.charAt(start - 1)))
			start--;
		return out.substring(start, space);
	}

	/** Puts {@code with} in place of the last word, which is {@code word}, keeping the space after it. */
	static void replaceLastWord(StringBuilder out, String word, String with)
	{
		int space = out.length() - 1;
		out.replace(space - word.length(), space, with);
	}

	static boolean isAOrAn(String word)
	{
		return "a".equalsIgnoreCase(word) || "an".equalsIgnoreCase(word);
	}

	/** Takes a "the", "a" or "an" off the end of the text so far, keeping the space before it. */
	static void dropArticle(StringBuilder out)
	{
		String word = lastWord(out);
		if (isAOrAn(word) || "the".equalsIgnoreCase(word))
			out.setLength(out.length() - 1 - word.length());
	}

	/**
	 * Makes the word the template wrote before a placeholder fit what filled
	 * it. An "a" goes by sound: an Eclectic impling, an 80. When the value
	 * ends the phrase and takes no article at all - Coins, soft clay - the
	 * article goes, and its capital moves onto the value. And a name that
	 * brings its own "The" gives it up to the word already pointing at it -
	 * the Leviathan, that Leviathan, the first Leviathan, never the The
	 * Leviathan - an "a" becoming that "the". Returns the value to append.
	 */
	static String agreeArticle(StringBuilder out, String value, boolean endsPhrase)
	{
		String written = lastWord(out);
		boolean article = isAOrAn(written);
		if (!article && (written == null || !POINTING.contains(written.toLowerCase(Locale.ROOT))))
			return value;
		boolean capital = Character.isUpperCase(written.charAt(0));
		if (value.length() > 4 && value.regionMatches(true, 0, "the ", 0, 4))
		{
			if (article)
				replaceLastWord(out, written, capital ? "The" : "the");
			return value.substring(4);
		}
		if (!article)
			return value;
		if (endsPhrase && Words.takesNoArticle(value))
		{
			out.setLength(out.length() - 1 - written.length());
			return capital ? Character.toUpperCase(value.charAt(0)) + value.substring(1) : value;
		}
		String fits = Words.article(value);
		replaceLastWord(out, written, capital ? Character.toUpperCase(fits.charAt(0)) + fits.substring(1) : fits);
		return value;
	}

	/** Whether the text so far ends on a word that points at a thing: a, the, that and the rest. */
	static boolean afterAnArticle(StringBuilder out)
	{
		String word = lastWord(out);
		return isAOrAn(word) || (word != null && POINTING.contains(word.toLowerCase(Locale.ROOT)));
	}

	/**
	 * Whether the placeholder at {@code at} opens a sentence: the start of the
	 * line, or after a full stop, a question or an exclamation. Not after an
	 * ellipsis, which trails a sentence off rather than ending it.
	 */
	static boolean opensSentence(String template, int at)
	{
		if (at == 0)
			return true;
		if (at < 2 || template.charAt(at - 1) != ' ')
			return false;
		char end = template.charAt(at - 2);
		return end == '!' || end == '?' || (end == '.' && (at < 3 || template.charAt(at - 3) != '.'));
	}
}

package com.follower;

import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public enum SpeechOutput
{
	/** Text bubble drawn above the follower. */
	OVERHEAD("Overhead"),
	/** Coloured message in the game chatbox. */
	CHATBOX("Chatbox"),
	/** Both at once. */
	BOTH("Both");

	final String label;

	static SpeechOutput parse(String text, SpeechOutput fallback)
	{
		if (text == null)
			return fallback;
		for (var value : values())
		{
			if (value.name().equalsIgnoreCase(text.trim()))
				return value;
		}
		return fallback;
	}

	boolean showsOverhead()
	{
		return this == OVERHEAD || this == BOTH;
	}

	boolean showsChatbox()
	{
		return this == CHATBOX || this == BOTH;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.follower;

import java.util.*;
import java.util.List;
import java.util.concurrent.ThreadLocalRandom;
import java.util.Set;
import java.util.function.ToIntFunction;

/**
 * One trigger -> phrase rule, as authored in phrases.json.
 *
 * <p>A rule fires on the <em>rising edge</em> of its {@code when} block: the tick it
 * becomes true having been false. That means {@code healthBelow: 30} speaks once
 * when you drop under 30%, not every tick you spend there.
 */
class SpeechRule
{
	/** Stable identifier; used for cooldown bookkeeping and log messages. */
	String id;

	/** Free text for your own benefit. Ignored by the plugin. */
	String note;

	/** The rule's name in the panel; an area rule's names its place, before the comma. */
	String title;

	/** Group name, so the config panel can switch whole categories off. */
	String group = "misc";

	Boolean enabled = Boolean.TRUE;

	/** Highest priority wins when several rules fire on the same event. */
	int priority = 50;

	/** Minimum gap between firings of this rule. */
	long cooldownMs = 10_000L;

	/**
	 * Game ticks to wait between the trigger and the line - a companion
	 * NOTICING something has a beat before the comment, where an instant
	 * reaction reads as scripted. The suppression checks (mute, global speech
	 * window) apply when the delay expires, not when it is queued.
	 */
	Integer delayTicks;

	/**
	 * Upper bound for a VARIABLE delay: when set, each firing waits a fresh
	 * number of ticks drawn between {@link #delayTicks} and this, inclusive.
	 *
	 * <p>A fixed delay still lands on the same beat every time, which reads as
	 * machinery once you have seen it twice - most obvious when the follower
	 * copies an emote, where a constant offset looks like a delay line rather
	 * than someone joining in. Leave it unset for a fixed wait.
	 */
	Integer delayTicksMax;

	/** Overrides the config default. One of overhead / chatbox / both. */
	String output;

	/** Optional emote animation id to play alongside the phrase. */
	Integer animation;

	/**
	 * Replay the PLAYER'S animation on the follower instead of a fixed id. Only
	 * meaningful when the rule triggers on an animation event ({@code animationSelf});
	 * with it, one rule mirrors every teleport in its id list without hardcoding
	 * which animation the follower answers with.
	 */
	Boolean mirrorAnimation;

	/**
	 * Copy the graphic the player's cast puts on them as well - a teleport's
	 * swirl, an alchemy's flash: the first one within a few ticks of the rule
	 * firing, and only the one. Off, a rule leaves the player's graphics alone,
	 * so a bite of food mid-fight does not have the follower wear the next
	 * spell that lands on the player.
	 */
	Boolean copiesGraphics;

	/**
	 * Mirror the player's animation as a held POSE rather than a one-shot, for
	 * the emotes you can keep doing until you stop.
	 *
	 * <p>The game splits those in two: clicking Dance plays an entry clip and
	 * then loops a second animation for as long as you hold it. The entry is a
	 * one-shot and {@link #mirrorAnimation} handles it; the loop never ends, so
	 * playing it as an emote would wait forever for a finish that never comes
	 * and leave the follower stuck. A pose override loops by nature and is
	 * released when the player's animation changes, which is what "until I am
	 * done" actually means.
	 */
	Boolean mirrorPose;

	/**
	 * A CHAIN of animation ids played back to back - for sequences authored as
	 * separate clips, like the home teleport's five stages. Takes precedence
	 * over {@link #animation} and {@link #mirrorAnimation}.
	 */
	List<Integer> animations;

	/**
	 * Spotanim (graphic) ids paired stage-for-stage with {@link #animations}:
	 * each fires as its stage begins. -1 skips a stage. The home teleport pairs
	 * its rune-circle pieces this way.
	 */
	List<Integer> graphics;

	/**
	 * Chain pacing: {@code true} advances each stage when the PLAYER's animation
	 * steps to its next stage - the server's own schedule - instead of when the
	 * follower's clip runs out. Teleport clips end in long hold frames the
	 * server always cuts short, so clip-length pacing freezes between stages.
	 */
	Boolean syncToPlayer;

	/**
	 * Teleport exit: when the follower's mirrored animation ends, it VANISHES -
	 * as the player does at the end of their cast - and reappears beside them
	 * once they land. An interrupted cast (the animation gets cancelled)
	 * disarms it, keeping the follower where it stands.
	 */
	Boolean vanishAfter;

	/**
	 * Plant the follower where it stands for the length of the animation, and
	 * let it follow again once the animation ends.
	 *
	 * <p>Movement always wins over an emote, so an animation played while the
	 * follower is walking is cut off the moment it starts. That is most of the
	 * time for anything triggered by a fight: it walks back to you the instant
	 * the fight is over. Without this, a celebration is a celebration nobody
	 * ever sees.
	 */
	Boolean holdStill;

	/**
	 * A copy of the player's WORK - a chop, a swing of the pick, a hammer at
	 * the anvil - made from beside the thing being worked and facing it, or
	 * not made at all. The follower first walks to a tile the game would let
	 * the player work from, and the copy stops the moment it is moved off
	 * it. With no work on there is nothing to stand against, so no copy: an
	 * axe swung at open air is what this is here to stop.
	 */
	Boolean atTheWork;

	/**
	 * How much this firing moves the follower's mood, positive or negative.
	 *
	 * <p>This is the whole mechanism by which anything affects mood: there is
	 * no list of significant events in the code. A rule that already knows how
	 * to notice a boss dying or a death or a good drop is exactly the thing
	 * that should say how much it mattered, and a new influence is a line in
	 * this file rather than a change to the engine.
	 *
	 * <p>Applied when the rule actually fires, so a rule suppressed by its
	 * cooldown or a disabled group does not move the mood either - the
	 * follower's state and what it says stay the same story.
	 */
	Integer mood;

	/**
	 * Marks this line as a question, and names the dialog tree that answers it.
	 *
	 * <p>The value is a tree id from dialogs.json. While the question is open,
	 * right-clicking Talk-to opens THAT conversation instead of the everyday
	 * one, and picking the branch marked with an answer is what replies.
	 *
	 * <p>The answer used to be a word typed into public chat. That asked the
	 * player to know a magic word, and it asked the follower to listen to
	 * everything said near it - in a crowd, somebody else's "yes" was
	 * indistinguishable from yours. A menu of options can be neither misheard
	 * nor guessed at.
	 *
	 * <p>The window is opened by SAYING it, not by winning: a question the mute
	 * swallowed is one the player never heard.
	 */
	String asks;

	/**
	 * Takes the floor: nothing else speaks for this many milliseconds.
	 *
	 * <p>For the handful of moments worth more than whatever the follower was
	 * otherwise about to say. Arriving where it asked to be taken is the clear
	 * case - the region change raises an area line at the same instant, and two
	 * lines about one arrival is one too many.
	 *
	 * <p>The floor is taken when the rule WINS rather than when it speaks, or a
	 * rule with a delay would leave its own gap open for exactly the line it
	 * meant to displace. The holder is also exempt from the global speech gap,
	 * since being held back by whatever spoke a second earlier is the same
	 * failure from the other end.
	 *
	 * <p>Only speech is hushed. An animation-only rule is movement rather than
	 * chatter and carries on regardless.
	 */
	Integer hushMs;

	/**
	 * A line the follower must not be too busy to say.
	 *
	 * <p>Distinct from {@link #priority}, which only decides who wins when
	 * several rules fire at once. This decides whether the winner gets through
	 * a RELAX period - the director stops ordinary chatter after a burst, and
	 * this is what the stopping was for. An occasion also spends no intensity
	 * of its own, so the moment does not cost the follower the next thing it
	 * wanted to say.
	 *
	 * <p>Two kinds of line qualify, and they are not the same kind. One is the
	 * moment worth marking - the pet, the anniversary, the place it asked to be
	 * taken. The other is the warning that has to land: if the player is about
	 * to die and the director has just told the follower to be quiet, silence
	 * is a worse failure than repetition could ever be.
	 *
	 * <p>Reserve it anyway, and judge it by how often the player HEARS one
	 * rather than by how many rules carry the flag. Forty-seven boss lines look
	 * like a lot in the file and amount to one a session in play.
	 */
	Boolean occasion;

	/**
	 * Waits its turn as an occasion does - out a cutscene and the quiet after
	 * it, an NPC conversation, and the gap after another line - rather than
	 * being dropped. It also waits out one of the director's rests, where an
	 * occasion goes through, and it counts towards the next rest when said;
	 * the empty-chair damper still drops it. For a line with one chance: the
	 * meeting of a quest's people, the payoff of something the follower set
	 * up. Play test, 15 Oct (Children of the Sun): Prince Itzla's line came up
	 * as the cutscene opened and Sergeant Tobyn's six seconds after a cat, and
	 * neither was heard.
	 */
	Boolean waits;

	/**
	 * Said once, ever, and then never again.
	 *
	 * <p>For firsts. A line that only has to hold up on a single hearing can be
	 * specific in a way no repeating line can afford to be - it can name the
	 * moment, admit something, or land a joke that would be unbearable the
	 * fourth time. That makes it the highest value per word in the file, and
	 * the only kind of line that never wears out.
	 *
	 * <p>What was spent is remembered by ID, alongside the tallies and the
	 * places, rather than on this object - so it survives both a restart and a
	 * rule reload, which throws every rule away and parses the file afresh.
	 */
	Boolean once;

	/**
	 * A held prop and a pose to play over it, for the length of the line's
	 * moment: the writing flourish.
	 *
	 * <p>{@code {"left": 31829, "item": 31830, "pose": 13302, "ticks": 8}} -
	 * the follower stops, the quill and the scroll come out, the writing pose
	 * holds for the ticks given, and everything goes back where it was. For
	 * the lines that CLAIM the notebook - "That's going in the book" - so the
	 * claim and the act finally happen together. {@code left} is optional: a
	 * second thing for the left hand (the shield slot), with {@code item} then
	 * in the right (the weapon slot), as the pose names them.
	 *
	 * <p>The item must be wearable (the prop is equipment, transiently). The
	 * pose is held as a pose override, which starts a one-shot again from its
	 * first frame each time it ends, so it repeats for the ticks given. The
	 * shipped pairing is the one the Advanced posing window dresses Write with
	 * a quill in; see docs/prop-and-animation-catalogue.md before inventing
	 * new ones. Best effort by design: if the follower is mid-errand or otherwise
	 * spoken for, the line still says its words and the gesture is dropped.
	 */
	Flourish prop;

	static class Flourish
	{
		Integer left,
			item,
			pose,
			ticks;
	}

	/**
	 * Somewhere the follower would like to go, expressed as part of saying so.
	 *
	 * <p>{@code {"region": 10553, "label": "the fishing guild", "minutes": 20}}.
	 * Going there before the deadline fulfils it; the deadline passing expires
	 * it. Either way a rule gets to react, and the {want} placeholder carries
	 * the label - so the follower can be pleased about the specific thing it
	 * asked for rather than pleased in general.
	 */
	Want want;

	static class Want
	{
		Integer region;
		String label;
		Integer minutes;
	}

	/**
	 * Files what just happened as the incident worth bringing up again.
	 *
	 * <p>{@code {"key": "chicken-death", "as": "that chicken"}}. The key is what
	 * a later rule recognises; the phrase is how the follower says it out loud,
	 * via {memory}.
	 *
	 * <p>This is the difference between counting and remembering. A tally makes
	 * "your four hundredth yew" possible, which is data delivered well. An
	 * incident makes "careful, I've seen what a chicken can do to you"
	 * possible, which is a shared history - and only one of those sounds like
	 * somebody who was there.
	 */
	Incident remember;

	static class Incident
	{
		String key;
		/**
		 * How to refer to it, with the event's and the moment's placeholders
		 * filled in when it is filed: "how close that was with the {foe}".
		 */
		String as;
		/**
		 * Fallbacks tried in turn when {@link #as} cannot be filled, before
		 * {@link #plain}: "your death {where}" when there was no foe.
		 */
		List<String> or;
		/** What to file instead when a placeholder in {@link #as} has nothing to say. */
		String plain;

		/** Every way of saying it, most particular first: as, each or, then plain. */
		List<String> forms()
		{
			List<String> forms = new java.util.ArrayList<>();
			if (as != null)
				forms.add(as);
			if (or != null)
			{
				for (String form : or)
				{
					if (form != null)
						forms.add(form);
				}
			}
			if (plain != null)
				forms.add(plain);
			return forms;
		}
	}

	/**
	 * Marks this line as ADVICE, and says what taking it would look like.
	 *
	 * <p>{@code {"about": "food", "ids": [829, 1191], "minutes": 1}} - the
	 * follower says eat something, and eating inside the minute settles it.
	 * {@code "room": true} settles instead on the inventory getting emptier,
	 * which covers banking, dropping, and eating the thing in the way.
	 *
	 * <p>What counts is named HERE rather than known by the engine, so adding a
	 * new piece of advice is a rule and not a code change.
	 *
	 * <p>Like a question, it only opens if the line was actually said: advice
	 * the mute swallowed is advice the player was never given, and holding it
	 * against them would be unfair as well as wrong.
	 */
	Advice advise;

	static class Advice
	{
		String about;
		List<Integer> ids;
		Boolean room;
		Integer minutes;
	}

	/**
	 * Files this moment against the PLACE, for a rule to bring up next time you
	 * are standing here.
	 *
	 * <p>{@code "markHere": "the drop"} - said later via {here}, as in "this is
	 * where you got the drop". The incident in {@link #remember} is one thing
	 * anywhere; this is one thing per place, and waits for you to come back.
	 */
	String markHere;

	/**
	 * Fallbacks for {@link #markHere}, tried in turn when a placeholder in it
	 * has nothing to say, as a remember block's {@code or}: "you died to the
	 * {foe}", then "you died".
	 */
	List<String> markHereOr;

	Condition when;

	/**
	 * Phrases to choose from, drawn without replacement. Optional when the rule
	 * plays an animation: an animation-only rule is a valid rule with no speech
	 * at all.
	 */
	List<String> say;

	// ---- runtime state, not serialised ----
	transient boolean lastState;
	transient long lastFiredMs;
	transient int lastPhraseIndex = -1;

	/**
	 * The shuffle bag: a shuffled run of every index, drawn through in order
	 * and refilled when it empties.
	 *
	 * <p>Uniform random with an anti-immediate-repeat guard sounds like the
	 * right thing and is not, because a player does not hear "random" - they
	 * hear the second time. With thirty variants, uniform draws start repeating
	 * after about eight, which is a quarter of the value of the writing. A bag
	 * gives all thirty first, every time.
	 */
	transient int[] bag;
	transient int bagPos;

	/** How long the say list was when the bag was built, so a hot-reloaded
	 * rule gets a fresh bag; the bag itself may be shorter than the list
	 * when worn lines are standing aside. */
	transient int bagSaySize;

	/**
	 * Says past which a line is worn out: with anything fresher in the same
	 * rule, a line heard this many times stands aside at the next refill
	 * (R17). Relative rather than absolute - when every line in a rule is
	 * this worn, all of them come back, because retiring the lot would
	 * retire the rule.
	 */
	static final int TIRED_AFTER = 20;

	boolean isEnabled()
	{
		return enabled == null || enabled;
	}

	boolean isOccasion()
	{
		return Boolean.TRUE.equals(occasion);
	}

	/** Whether it waits out a scene and the gap rather than being dropped: an occasion, or {@link #waits}. */
	boolean waitsItsTurn()
	{
		return isOccasion() || Boolean.TRUE.equals(waits);
	}

	boolean isOnce()
	{
		return Boolean.TRUE.equals(once);
	}

	/**
	 * What a once rule is spent under. A callback - a moment's other version
	 * for a player who has done the quest it names, "-after-" in its id - is
	 * spent with its base: they are one moment, and only one of them is ever
	 * said. QA, 15 Oct: the mugger on Rune Mysteries' street was said, the
	 * player finished Children of the Sun next door, and the callback said
	 * the mugger again at the same step.
	 */
	String onceKey()
	{
		int cut = id == null ? -1 : id.indexOf("-after-");
		return cut > 0 ? id.substring(0, cut) : id;
	}

	/**
	 * The plain line a quest person's callback stands in for: quest-duke-horacio
	 * for fun-duke-horacio-after-cooks-assistant. Null for any other rule.
	 */
	String plainLineId()
	{
		int cut = id == null ? -1 : id.indexOf("-after-");
		return cut > 4 && id.startsWith("fun-") ? "quest-" + id.substring(4, cut) : null;
	}

	/** Whether its condition is, or holds, one of this type. */
	boolean uses(String type)
	{
		return when != null && when.usesType(type);
	}

	boolean isValid()
	{
		return when != null && (hasSpeech() || hasAnimationAction());
	}

	boolean hasSpeech()
	{
		return say != null && !say.isEmpty();
	}

	/**
	 * How many ticks THIS firing waits: {@link #delayTicks}, or a fresh draw
	 * between it and {@link #delayTicksMax} when that is set. Rolled once per
	 * firing, so the wait is decided at the win and not re-rolled while the
	 * firing sits pending.
	 */
	int rollDelayTicks()
	{
		int min = delayTicks == null ? 0 : Math.max(0, delayTicks),
			max = delayTicksMax == null ? min : Math.max(min, delayTicksMax);
		return max > min
			? min + ThreadLocalRandom.current().nextInt(max - min + 1)
			: min;
	}

	boolean hasAnimationAction()
	{
		return animation != null
			|| Boolean.TRUE.equals(mirrorAnimation)
			|| Boolean.TRUE.equals(mirrorPose)
			|| hasAnimationChain();
	}

	boolean hasAnimationChain()
	{
		return animations != null && !animations.isEmpty();
	}

	/**
	 * The animation this firing should play, or null for none: the fixed
	 * {@link #animation} id, unless {@link #mirrorAnimation} is set and the
	 * triggering event carries the player's animation to copy.
	 */
	Integer resolveAnimation(TriggerEvent event)
	{
		if ((Boolean.TRUE.equals(mirrorAnimation) || Boolean.TRUE.equals(mirrorPose))
			&& event != null
			&& event.getType() == TriggerEvent.Type.ANIMATION
			&& event.getId() != -1)
			return event.getId();
		return animation;
	}

	/**
	 * Updates the stored edge state and reports whether this evaluation is a rising
	 * edge. Always call exactly once per evaluation pass, even when the rule is
	 * going to be skipped for cooldown, or the edge tracking drifts.
	 */
	boolean risingEdge(boolean nowMatching)
	{
		boolean rising = nowMatching && !lastState;
		lastState = nowMatching;
		return rising;
	}

	/** Leaves this pass's edge unspent, so a condition still true rises again on the next pass. */
	void riseAgain()
	{
		lastState = false;
	}

	boolean offCooldown(long nowMs)
	{
		return nowMs - lastFiredMs >= cooldownMs;
	}

	void markFired(long nowMs)
	{
		lastFiredMs = nowMs;
	}

	/** When it last fired, so a line let go unsaid can give its cooldown back. */
	long lastFiredMs()
	{
		return lastFiredMs;
	}

	/**
	 * Forgets the edge, so a condition still true rises again. Deliberately
	 * leaves the cooldown and the shuffle bag alone: what the follower has
	 * already said is not scene state. Behaviour QA, 16 Oct: a hop that
	 * cleared the cooldown too had Callisto's intro said again a minute
	 * later, and crowded-here again after every GE hop. And a player who hops
	 * worlds often would otherwise be handed the front of a fresh bag every
	 * time and hear the same few lines for it.
	 */
	void resetEdges()
	{
		lastState = false;
	}

	/** The full clear, cooldown and bag included. For starting the follower over. */
	void reset()
	{
		resetEdges();
		lastFiredMs = 0L;
		lastPhraseIndex = -1;
		bag = null;
		bagPos = 0;
	}

	String pickPhrase(Set<String> recentlySaid)
	{
		return pickPhrase(recentlySaid, line -> 0);
	}

	/**
	 * The next line, drawn without replacement.
	 *
	 * @param recentlySaid lines the follower has used lately, ACROSS every
	 * rule. Skipped when there is an alternative, which is what stops two
	 * neighbouring rules from ping-ponging the same observation at each other -
	 * a bag can only keep one rule honest about itself. Never allowed to
	 * produce silence: if everything in the bag has been heard lately, the
	 * draw stands, because a repeated line beats no line.
	 * @param wear how many times a line has been said across every session;
	 * lines at {@link #TIRED_AFTER} or beyond stand aside at the refill while
	 * anything fresher exists.
	 */
	String pickPhrase(Set<String> recentlySaid,
		ToIntFunction<String> wear)
	{
		if (say == null || say.isEmpty())
			return "";
		if (say.size() == 1)
			return say.get(0);

		int index = draw(wear);

		// One pass over what is left in the bag, in bag order, looking for
		// something unheard. Bounded deliberately: the alternative is
		// reshuffling until something fits, which never terminates for a rule
		// whose every line is already in the window.
		if (recentlySaid.contains(say.get(index)))
		{
			int drawnAt = bagPos - 1;
			for (int i = bagPos; i < bag.length; i++)
			{
				if (!recentlySaid.contains(say.get(bag[i])))
				{
					// The rejected line goes back into the un-drawn part of the
					// bag, so it still gets its turn later in this cycle.
					//
					// The second assignment is dead and kept on purpose. Slots
					// below bagPos are never read again before the array is
					// rebuilt, so writing the fresher index there changes
					// nothing - but it keeps the array a true permutation at
					// every instant, which is the invariant this is easiest to
					// reason about and to assert. A mutation sweep flagged it
					// as unreachable, which is correct and not a defect.
					int fresher = bag[i];
					bag[i] = bag[drawnAt];
					bag[drawnAt] = fresher;
					index = fresher;
					break;
				}
			}
		}

		lastPhraseIndex = index;
		return say.get(index);
	}

	/** The next index out of the bag, refilling it when it runs dry. */
	int draw(ToIntFunction<String> wear)
	{
		if (bag == null || bagSaySize != say.size() || bagPos >= bag.length)
			refill(wear);
		return bag[bagPos++];
	}

	void refill(ToIntFunction<String> wear)
	{
		// Worn lines stand aside here, which keeps the bag's guarantee intact
		// for what remains: a cycle is still a cycle, just of fresher lines.
		// Wear is checked at the refill rather than the draw, so a line
		// crossing the threshold mid-cycle still finishes its turn.
		int fresh = 0;
		boolean[] tired = new boolean[say.size()];
		for (int i = 0; i < say.size(); i++)
		{
			tired[i] = wear.applyAsInt(say.get(i)) >= TIRED_AFTER;
			if (!tired[i])
				fresh++;
		}
		boolean everyoneWorn = fresh == 0;

		bag = new int[everyoneWorn ? say.size() : fresh];
		int at = 0;
		for (int i = 0; i < say.size(); i++)
		{
			if (everyoneWorn || !tired[i])
				bag[at++] = i;
		}
		for (int i = bag.length - 1; i > 0; i--)
		{
			int j = ThreadLocalRandom.current().nextInt(i + 1),
				swap = bag[i];
			bag[i] = bag[j];
			bag[j] = swap;
		}

		// The one seam a bag has: the last line of one bag and the first of the
		// next are adjacent draws with nothing stopping them being the same
		// line. That is the exact back-to-back repeat the old code existed to
		// prevent, and it would happen once per bag rather than at random.
		if (bag.length > 1 && bag[0] == lastPhraseIndex)
		{
			int j = 1 + ThreadLocalRandom.current().nextInt(bag.length - 1);
			bag[0] = bag[j];
			bag[j] = lastPhraseIndex;
		}
		bagSaySize = say.size();
		bagPos = 0;
	}

	String describe()
	{
		return id == null ? "(unnamed rule in group " + group + ")" : id;
	}
}

package com.follower;

import com.google.gson.Gson;
import java.util.*;
import java.util.Map;
import javax.inject.*;
import lombok.*;
/**
 * The spotanim ("graphic") catalogue, dumped from the cache by
 * tools/cache-dumper. A spotanim is how the game shows teleport swirls, spell
 * impacts and the home teleport's rune circle: a model, the animation that
 * plays it once, scaling, rotation, recolours and lighting tweaks.
 *
 * <p>Dumped rather than read live because the client API exposes ids only -
 * {@code Actor.getGraphic()} says WHICH graphic is on the player, but nothing
 * maps that id to a model the follower could wear.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
class SpotAnimRepository
{
	/** One spotanim definition. Field names mirror the dumper's. */
	static class Entry extends Recolours
	{
		int m,
			a;
		Integer rx,
			ry,
			rot,
			am,
			co;

		int modelId()
		{
			return m;
		}

		int animationId()
		{
			return a;
		}

		int resizeX()
		{
			return rx == null ? 128 : rx;
		}

		int resizeY()
		{
			return ry == null ? 128 : ry;
		}

		int rotation()
		{
			return rot == null ? 0 : rot;
		}

		int ambient()
		{
			return am == null ? 0 : am;
		}

		int contrast()
		{
			return co == null ? 0 : co;
		}
	}

	final Gson gson;

	Map<String, Entry> spotanims = Collections.emptyMap();
	boolean liveRead;

	@Getter
	String status = "not loaded";

	/**
	 * Builds the catalogue from the client's own loaded cache - the no-dump
	 * path every Hub install uses. A dump file, when present, wins for the
	 * ids it has. No-op while the cache indexes are not available yet;
	 * callers retry.
	 */
	void loadFromClient(net.runelite.api.Client client)
	{
		addLive(LiveCacheParser.parseSpotAnims(client));
	}

	/**
	 * The live cache's graphics, under a dump's: the game's graphics newer
	 * than the dump are there too. A dump from August hid 426 of them on
	 * the development client (qa5 #75).
	 */
	void addLive(Map<String, Entry> live)
	{
		if (live.isEmpty())
			return;
		spotanims = live;
		liveRead = true;
			status = spotanims.size() + " spotanims (live cache)";
	}

	/** Whether the client's own cache has been read in yet, under a dump or not. */
	boolean hasReadTheLiveCache()
	{
		return liveRead;
	}

	/** The definition for a graphic id, or null if unknown or not loaded. */
	Entry get(int graphicId)
	{
		return spotanims.get(Integer.toString(graphicId));
	}

	boolean isLoaded()
	{
		return !spotanims.isEmpty();
	}

	/** Lets the catalogue go while the plugin is off; startUp and the next login load it again. */
	void unload()
	{
		spotanims = Collections.emptyMap();
		liveRead = false;
		status = "not loaded";
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.Map;
import java.util.Set;
import javax.inject.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.Player;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.kit.KitType;
import lombok.Setter;
import java.util.regex.Pattern;
import java.util.Map.Entry;

/**
 * Learns which stand/walk/run animation set goes with which wielded weapon, by
 * watching real players.
 *
 * <p>A weapon's pose set lives in the game's weapon-stance data, which neither the
 * runtime API nor the cache's {@code ItemDefinition} exposes per item. But every
 * {@link net.runelite.api.Actor} reports its <em>resolved</em> pose ids, and every
 * player's wielded weapon is readable from their composition. Pairing the two gives
 * real, correct data rather than a hardcoded guess.
 *
 * <p>Your own character is the main teacher: equip a weapon and its stances are
 * learned immediately. Crowded areas fill the library quickly. Results persist to
 * {@code stances.json}.
 *
 * <p>What ships with the plugin and what this install learned are kept apart.
 * The shipped library is rebuilt by {@code tools/cache-dumper} from learned
 * stances, Weapon Animation Replacer's data and the game cache; only what was
 * learned here is ever written back, so a fix to the shipped data reaches every
 * install instead of hiding behind an old copy of itself.
 */
@Slf4j
@Singleton
class StanceLibrary
{
	static final String FILE_NAME = "stances.json";

	/** Where {@link #backUp} keeps the learned file as it was before the first trim. */
	static final String BACKUP_NAME = FILE_NAME + ".pre-split";

	/** Weapon item id used for "nothing wielded". */
	static final int UNARMED = 0;

	static class Stance
	{
		int idle,
			walk,
			run;

		/**
		 * The directional poses: back-pedal, side-steps, and turn-in-place -
		 * used when the follower moves while FACING something, the way an
		 * interacting player does. Entries saved before these fields existed
		 * deserialize them as 0; the pose selector falls back to {@code walk}
		 * (the client's own -1 fallback) until the weapon is observed again.
		 */
		int walkBack,
			walkLeft,
			walkRight,
			turnLeft,
			turnRight;

		/**
		 * The weapon's attack animation, learned from players seen swinging it.
		 * Unlike the poses above an actor does not advertise this - it is a
		 * one-shot animation - so it is captured when a player animates while
		 * interacting with something. 0 until observed.
		 */
		int attack;

		/**
		 * The swing for each attack style, indexed by the game's own style
		 * number (COM_MODE, 0-3). 0 in a slot means that style has not been
		 * seen; null means none have.
		 *
		 * <p>Only the LOCAL player can fill these. Which style anyone else has
		 * selected is not readable - varps are the local player's - so every
		 * other player in the scene can still only teach the generic swing
		 * above. That asymmetry is the whole reason this is a separate field
		 * rather than a replacement: the crowd teaches breadth, your own play
		 * teaches depth, and a weapon ends up with both.
		 *
		 * <p>Deliberately indexed by style NUMBER rather than named stab,
		 * slash or crush. What a style means depends on the weapon type, which
		 * would need a table the cache does not carry - and the follower never
		 * needs to know the name. It needs the animation that goes with the
		 * style the player has selected, and that is exactly what the index is.
		 */
		int[] attackByStyle;

		/**
		 * The swing for each KIND of blow, in {@link StanceLibrary#STAB},
		 * {@link StanceLibrary#SLASH}, {@link StanceLibrary#CRUSH} order, 0 where
		 * the weapon deals no blow of that kind.
		 *
		 * <p>Shipped only. It comes from Weapon Animation Replacer's sets, which
		 * name a weapon's swings by kind rather than by style button, and which
		 * button deals which kind depends on the weapon. The game's own combat
		 * tab table answers that for the weapon the player is holding (see
		 * {@link StanceLibrary#attackKind}), so the follower throws the same kind of blow the
		 * player has chosen, with its own weapon's swing for it.
		 */
		int[] attackByType;

		Stance()
		{
		}

		/** The eight poses in {@link #poses} order. */
		Stance(int... poses)
		{
			idle = poses[0];
			walk = poses[1];
			run = poses[2];
			walkBack = poses[3];
			walkLeft = poses[4];
			walkRight = poses[5];
			turnLeft = poses[6];
			turnRight = poses[7];
		}

		/** Stand, walk, run, back, left, right, turn left, turn right. */
		int[] poses()
		{
			return new int[]{idle, walk, run, walkBack, walkLeft, walkRight, turnLeft, turnRight};
		}

		boolean isComplete()
		{
			return idle > 0 && walk > 0 && run > 0;
		}

		/** How the weapon is carried, without anything about how it is swung. */
		Stance posesOnly()
		{
			return new Stance(poses());
		}

		/** How the weapon is swung, without anything about how it is carried. */
		Stance swingsOnly()
		{
			var swings = new Stance();
			swings.attack = attack;
			swings.attackByStyle = attackByStyle;
			return swings;
		}

		/**
		 * Whether every pose this learned record knows is the shipped one's.
		 * Such poses are a copy of an older bundle written out by an older
		 * save, and keeping them would hide every later correction to that
		 * weapon.
		 */
		boolean carriedAs(Stance shipped)
		{
			int[] mine = poses(),
				theirs = shipped.poses();
			for (int i = 0; i < mine.length; i++)
			{
				if (mine[i] != 0 && mine[i] != theirs[i])
					return false;
			}
			return true;
		}

		/** Whether this learned record knows a swing the shipped one does not. */
		boolean swingsUnlike(Stance shipped)
		{
			if (attack != 0 && attack != shipped.attack)
				return true;
			if (attackByStyle != null)
			{
				for (int styled : attackByStyle)
				{
					if (styled != 0)
						return true;
				}
			}
			return false;
		}

		boolean sameAs(Stance other)
		{
			return java.util.Arrays.equals(poses(), other.poses());
		}

		/**
		 * Same weapon CLASS: the idle/walk/run triple is what the game shares
		 * between weapons of a kind. Measured across 190 observed weapons,
		 * those triples collapse to 32 classes - every scimitar walks alike,
		 * every staff walks alike - which is what lets one weapon's attack
		 * stand in for its whole family.
		 */
		boolean sameClassAs(Stance other)
		{
			return idle == other.idle && walk == other.walk && run == other.run;
		}
	}

	/** The kinds of blow, in the order of {@link Stance#attackByType}. */
	static final int STAB = 0,
		SLASH = 1,
		CRUSH = 2;

	/** Shipped beside the stances: what is not an attack, and what each style button deals. */
	static final String KINDS_FILE = "attack-kinds.json";

	/** The shape of {@link #KINDS_FILE}, written by tools/cache-dumper. */
	static class AttackKinds
	{
		/** Blocks, defends and specials: never a weapon's ordinary swing. */
		int[] notAttacks;
		/** Spell casts, by Jagex's names for them. */
		int[] casts;
		/** Combat tab weapon category -> the kind of blow each style button deals, -1 for none. */
		Map<String, int[]> styleKinds;
	}

	final Gson gson;
	final ModelRepository models;

	/** weapon item id -> stance set, as shipped. */
	final Map<Integer, Stance> bundled = new HashMap<>();

	/** weapon item id -> stance set, as learned by this install. The only part saved. */
	final Map<Integer, Stance> learned = new HashMap<>();

	Set<Integer> notAttacks = Collections.emptySet(),
		casts = Collections.emptySet();
	Map<String, int[]> styleKinds = Collections.emptyMap();

	/** base item name -> a weapon id known to have that name's stance. */
	Map<String, Integer> byBaseName;

	/** metal-stripped item name -> a weapon id, for inheriting across tiers. */
	Map<String, Integer> byTierName;

	/** How many stances the name index was built from, so it rebuilds when they grow. */
	int indexedSize = -1;

	/** weapon id -> the weapon whose stance it inherits, or 0 for none. */
	final Map<Integer, Integer> donors = new HashMap<>();

	Path file;
	boolean dirty;

	@Inject
	StanceLibrary(Gson gson, ModelRepository models)
	{
		this.gson = gson;
		this.models = models;
		// Unarmed is known and never needs learning.
		bundled.put(UNARMED, new Stance(PlayerPose.IDLE, PlayerPose.WALK, 824 /* RUN */,
			PlayerPose.TURN_180, PlayerPose.SIDESTEP_LEFT, PlayerPose.SIDESTEP_RIGHT,
			PlayerPose.IDLE_TURN, PlayerPose.IDLE_TURN));
	}

	/**
	 * Loads the bundled starter library first, then whatever this install has
	 * observed on top of it.
	 *
	 * <p>Weapon animations cannot be read from the cache - measured, not
	 * assumed: item params hold combat stats, item category disagrees with
	 * the observed stances, and no struct carries a pose set. The client
	 * resolves them in script at equip time. Observation is therefore the
	 * only honest source, and shipping a library means a new install starts
	 * with hundreds of weapons already right instead of everything falling
	 * back to unarmed.
	 */
	void load(Path dataDir)
	{
		file = dataDir.resolve(FILE_NAME);

		try (Reader in = shipped(FILE_NAME))
		{
			if (in != null)
			{
				int added = read(in, bundled);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not read the bundled stance library", e);
		}
		loadKinds();

		if (!Files.isRegularFile(file))
			return;
		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			// Local observations win: this client saw them first-hand.
			read(reader, learned);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not read {}", file, e);
		}

		// Older saves wrote the whole library, shipped stances included, so the
		// learned file still holds copies of an older bundle, some with a swing
		// learned on top. The copied poses go, any swing of its own stays, and
		// the file is rewritten that way at the next save.
		int copies = 0;
		for (Iterator<Entry<Integer, Stance>> it = learned.entrySet().iterator(); it.hasNext(); )
		{
			var entry = it.next();
			Stance mine = entry.getValue(),
				shipped = bundled.get(entry.getKey());
			if (shipped == null || !mine.carriedAs(shipped))
				continue;
			if (!mine.swingsUnlike(shipped))
			{
				it.remove();
				copies++;
			}
			else if (mine.isComplete())
			{
				entry.setValue(mine.swingsOnly());
				copies++;
			}
		}
		if (copies > 0)
		{
			backUp();
			dirty = true;
		}
	}

	/**
	 * Keeps the learned file as it was, once, before the trim rewrites it. An
	 * older build of the plugin ships a smaller library and reads only this
	 * file, so after a rollback the weapons it knew from those copies would
	 * be gone, and its own next save would make that permanent. Renaming the
	 * backup over the file brings them back.
	 */
	void backUp()
	{
		var backup = file.resolveSibling(BACKUP_NAME);
		if (Files.exists(backup))
			return;
		try
		{
			Files.copy(file, backup);
		}
		catch (IOException e)
		{
			log.warn("Could not back up {} to {}", file, backup, e);
		}
	}

	void loadKinds()
	{
		try (Reader in = shipped(KINDS_FILE))
		{
			if (in == null)
				return;
			AttackKinds kinds = gson.fromJson(in, AttackKinds.class);
			if (kinds == null)
				return;
			notAttacks = toSet(kinds.notAttacks);
			casts = toSet(kinds.casts);
			if (kinds.styleKinds != null)
				styleKinds = kinds.styleKinds;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not read {}", KINDS_FILE, e);
		}
	}

	/** A file shipped with the plugin, or null when it is missing. */
	static Reader shipped(String name)
	{
		var in = StanceLibrary.class.getResourceAsStream("/com/follower/" + name);
		return in == null ? null
			: new java.io.BufferedReader(new java.io.InputStreamReader(in, StandardCharsets.UTF_8));
	}

	static Set<Integer> toSet(int[] ids)
	{
		Set<Integer> out = new HashSet<>();
		if (ids != null)
		{
			for (int id : ids)
				out.add(id);
		}
		return out;
	}

	/** @return how many entries were taken from this source. */
	int read(Reader reader, Map<Integer, Stance> stances)
	{
		Map<String, Stance> loaded = gson.fromJson(reader,
			new com.google.gson.reflect.TypeToken<Map<String, Stance>>()
			{
			}.getType());
		if (loaded == null)
			return 0;
		int added = 0;
		for (var entry : loaded.entrySet())
		{
			try
			{
				stances.put(Integer.parseInt(entry.getKey()), entry.getValue());
				added++;
			}
			catch (NumberFormatException ignored)
			{
				// Skip malformed key.
			}
		}
		return added;
	}

	void save()
	{
		if (!dirty || file == null)
			return;

		// Only what this install learned: the shipped stances come from the
		// plugin, and a copy of them here would outlive every fix to them.
		Map<String, Stance> out = new HashMap<>();
		for (var entry : learned.entrySet())
			out.put(Integer.toString(entry.getKey()), entry.getValue());

		try
		{
			Files.createDirectories(file.getParent());
			try (Writer writer = Files.newBufferedWriter(file, StandardCharsets.UTF_8))
			{
				gson.toJson(out, writer);
			}
			dirty = false;
		}
		catch (IOException e)
		{
			log.warn("Could not write {}", file, e);
		}
	}

	/**
	 * Records the stance set of every player in the scene. Cheap enough to run each
	 * game tick; only genuinely new weapons cause a write.
	 */
	void observe(Client client)
	{
		var view = client.getTopLevelWorldView();
		if (view == null)
			// Between worlds: nobody to watch this tick.
			return;
		if (!learnedChecked)
		{
			learnedChecked = true;
			forgetObstacleSets(client);
		}
		for (var player : view.players())
		{
			if (player == null)
				continue;
			learn(client, player);
		}
	}

	/** Whether the learned file has been checked for obstacle sets, which needs the client. */
	boolean learnedChecked;

	/**
	 * Takes out of the learned file any pose set an older build learned off
	 * a player on an obstacle (see {@link #emptiesAHand}) or mid-swap (see
	 * {@link #isAPassingSwap}), keeping any swing learned with it. Unarmed
	 * ships with the plugin, so a learned unarmed set is always one of these.
	 */
	void forgetObstacleSets(Client client)
	{
		int forgotten = 0;
		for (Iterator<Entry<Integer, Stance>> it = learned.entrySet().iterator(); it.hasNext(); )
		{
			var entry = it.next();
			var mine = entry.getValue();
			if (!mine.isComplete() || (entry.getKey() != UNARMED && !emptiesAHand(client, mine)
				&& !isAPassingSwap(entry.getKey(), mine)))
				continue;
			if (mine.attack != 0 || mine.attackByStyle != null)
				entry.setValue(mine.swingsOnly());
			else
				it.remove();
			forgotten++;
		}
		if (forgotten > 0)
			dirty = true;
	}

	/**
	 * Whether a set keeps a shipped weapon's own stand but walks or runs
	 * otherwise. Seen once, it overrode the shipped carry for good: the
	 * learned file held seven, two-handers and godswords on their own
	 * stand and the plain walk and run (qa5 #31). A weapon's stand comes
	 * with its walk and run, so a set like that is the game, or another
	 * plugin, swapping the moves for a moment, never a new way to carry it.
	 */
	boolean isAPassingSwap(int weaponId, Stance stance)
	{
		var shipped = bundled.get(weaponId);
		return shipped != null && shipped.isComplete() && shipped.idle == stance.idle
			&& (shipped.walk != stance.walk || shipped.run != stance.run);
	}

	/**
	 * Whether the stand, walk or run of a set empties a hand. No weapon's
	 * does; the sets the game swaps in for an agility obstacle (the log
	 * balance, the ledge shimmy, the monkey bars) empty both, so a player
	 * seen on one teaches nothing.
	 */
	static boolean emptiesAHand(Client client, Stance stance)
	{
		for (int pose : new int[]{stance.idle, stance.walk, stance.run})
		{
			var animation = client.loadAnimation(pose);
			if (animation != null && (animation.getLeftHandItem() == -512
				|| animation.getRightHandItem() == -512))
				return true;
		}
		return false;
	}

	/** An actor's base animations now, in {@link Stance#poses} order. */
	static int[] posesOf(net.runelite.api.Actor actor)
	{
		return new int[]{actor.getIdlePoseAnimation(), actor.getWalkAnimation(), actor.getRunAnimation(),
			actor.getWalkRotate180(), actor.getWalkRotateLeft(), actor.getWalkRotateRight(),
			actor.getIdleRotateLeft(), actor.getIdleRotateRight()};
	}

	void learn(Client client, Player player)
	{
		var composition = player.getPlayerComposition();
		if (composition == null)
			return;

		// getEquipmentId returns the item id directly, or -1 when nothing is wielded.
		int weaponId = key(composition.getEquipmentId(KitType.WEAPON));
		if (weaponId == UNARMED)
			// Shipped, and never learned: an empty-handed player on a log
			// would teach the follower to balance on flat ground.
			return;

		var observed = new Stance(posesOf(player));

		if (!observed.isComplete() || emptiesAHand(client, observed) || isAPassingSwap(weaponId, observed))
			return;

		var known = learned.get(weaponId);
		// A learned record holding only a swing is carried as shipped.
		var reference = known != null && known.isComplete() ? known : bundled.get(weaponId);
		if (reference != null && reference.sameAs(observed))
			return;
		if (known != null)
		{
			// Poses changed but the swings did not: carry them across rather
			// than throwing away a hard-won observation.
			observed.attack = known.attack;
			observed.attackByStyle = known.attackByStyle;
		}

		learned.put(weaponId, observed);
		dirty = true;
	}

	/**
	 * Records a player's one-shot animation as their weapon's attack.
	 *
	 * <p>The gate is that they are INTERACTING with an actor: combat always
	 * has a target, while the animations that would otherwise pollute this -
	 * woodcutting, mining, cooking, emotes, eating - either target a scene
	 * object or nothing at all. Skilling with an axe therefore never gets
	 * mistaken for an axe attack.
	 *
	 * @param style the attack style the swing was performed in (COM_MODE,
	 * 0-3), or -1 when it cannot be known - which is every player but the
	 * local one
	 */
	void learnAttack(Player player, int animationId, int style)
	{
		if (animationId <= 0 || player.getInteracting() == null)
			return;
		var composition = player.getPlayerComposition();
		if (composition == null)
			return;
		int weaponId = key(composition.getEquipmentId(KitType.WEAPON));

		var stance = learned.get(weaponId);
		if (stance == null)
		{
			var shipped = bundled.get(weaponId);
			if (shipped == null || shipped.attack == animationId)
				// No pose set yet means the weapon is brand new to us; observe()
				// creates it on the next tick and the attack lands then.
				return;
			// Carried as shipped, swung as seen: the learned record holds the
			// swing alone. A copy of the shipped poses here would outlive
			// every later fix to them.
			stance = new Stance();
			learned.put(weaponId, stance);
		}
		if (stance.attack == animationId)
			return;
		if (style >= 0 && style < STYLES)
		{
			if (stance.attackByStyle == null)
				stance.attackByStyle = new int[STYLES];
			if (stance.attackByStyle[style] != animationId)
			{
				stance.attackByStyle[style] = animationId;
				dirty = true;
			}
		}

		// The generic slot is still written, and still by everyone: it is what
		// borrowing across a stance class reads, and what an unknown style
		// falls back to.
		if (stance.attack == animationId)
			return;
		stance.attack = animationId;
		dirty = true;
	}

	/**
	 * How a weapon is USED, which the pose set does not say.
	 *
	 * <p>Supplied by the plugin from the item's own equipment stats, because
	 * the pose triple describes how a weapon is CARRIED and nothing more. The
	 * 79-weapon class that walks like an unarmed player holds the Dragon
	 * harpoon and the Bow of faerdhinen side by side: identical carry, utterly
	 * different swing. Borrowing across that would put a chop on a bow.
	 *
	 * <p>Combat style alone turned out to be too coarse. That same class went
	 * on to collect a bow, a dart and a knife - all ranged, none animating
	 * remotely alike - and the follower would have shot a bow like a thrown
	 * dart. Handedness splits them cleanly, so the key carries both.
	 */
	interface StyleSource
	{
		int MELEE = 0,
			RANGED = 1,
			MAGIC = 2,
			UNKNOWN = -1;

		/** A style and handedness folded into one comparable key. */
		static int packed(int style, boolean twoHanded)
		{
			return style < 0 ? UNKNOWN : style * 2 + (twoHanded ? 1 : 0);
		}

		/** {@link #packed} for this item, or {@link #UNKNOWN}. */
		int usageOf(int itemId);
	}

	@Setter
	StyleSource styleSource;

	/**
	 * The attack animation to use for a weapon: its own if it has been seen
	 * used, otherwise one borrowed from a weapon that both carries AND fights
	 * the same way.
	 *
	 * <p>The borrow is what keeps this practical. Nobody owns every weapon, but
	 * weapons of a kind share a pose set, so seeing ONE whip swung covers every
	 * whip in the game. Not every class names a kind, though: see
	 * {@link #isPlainHuman}.
	 *
	 * <p>Matching the pose class alone is not enough, though. It groups by how
	 * a weapon is carried, and melee and ranged weapons can be carried alike,
	 * so the combat style has to agree as well. When the style of either weapon
	 * cannot be established the borrow is refused outright: a wrong animation
	 * is worse than a plain one, which is the same reason the variant matching
	 * is exact rather than fuzzy.
	 *
	 * @return 0 when nothing can be borrowed, leaving the caller to fall back
	 */
	int attackFor(int weaponItemId)
	{
		return attackFor(weaponItemId, -1, -1);
	}

	/** How many attack styles the game numbers, for the per-style slots. */
	static final int STYLES = 4;

	/**
	 * The swing for a weapon, most trusted answer first:
	 * <ol>
	 * <li>the shipped swing for the kind of blow being thrown;</li>
	 * <li>the swing this install saw in that style, unless it was really a
	 * block, a special or a spell;</li>
	 * <li>the weapon's shipped swing;</li>
	 * <li>its learned swing, unless that was really a block or special;</li>
	 * <li>the same four for the weapon it inherits by name;</li>
	 * <li>a borrow from its weapon class.</li>
	 * </ol>
	 * The shipped data goes first because what was learned includes blocks,
	 * casts and skilling swings filed as attacks, while the shipped swings
	 * were checked against Weapon Animation Replacer's sets and the cache.
	 *
	 * <p>A real weapon never gets the unarmed punch or kick. A weapon nothing is
	 * known about falls back to the unarmed stance to stand and walk with, and
	 * it used to fall back to the unarmed punch to fight with as well, so a
	 * corrupted bow punched. 0 instead lets the caller pick a plain swing for
	 * the style.
	 *
	 * @param style the style button the player has selected (COM_MODE, 0-3), or -1
	 * to take whatever the weapon is generally known to do
	 * @param kind the kind of blow that style deals, {@link #STAB}, {@link #SLASH}
	 * or {@link #CRUSH} (see {@link #attackKind}), or -1 when it is not a melee blow
	 */
	int attackFor(int weaponItemId, int style, int kind)
	{
		int id = key(weaponItemId);
		boolean realWeapon = id != UNARMED;
		int own = ownAttack(id, style, kind, realWeapon);
		if (own > 0)
			return own;
		// Then the weapon it inherits by name, even when it has a record of
		// its own: a variant seen carried but never swung knows how it stands
		// and nothing about how it fights, and its plain version may.
		int donor = realWeapon ? donorFor(id) : UNARMED;
		if (donor != UNARMED)
		{
			int inherited = ownAttack(donor, style, kind, true);
			if (inherited > 0)
				return inherited;
		}

		var stance = forWeapon(weaponItemId);
		int usage = styleSource == null
			? StyleSource.UNKNOWN : styleSource.usageOf(weaponItemId);
		if (usage == StyleSource.UNKNOWN || isPlainHuman(stance))
			return 0;

		// A class can hold several different attacks once a few of its weapons
		// have been seen: most share the generic swing for their kind, while
		// the occasional signature weapon has one all of its own. Taking the
		// first match would hand a plain battlestaff the Eye of ayak's unique
		// animation, and worse, WHICH one it took depended on hash order - the
		// same weapon could animate differently between sessions.
		//
		// So: whichever attack the most weapons of this class agree on, with
		// ties going to the lowest item id. Agreement finds the generic swing
		// as soon as two weapons share it, and the tie-break stands in until
		// then, since the plainer weapon of a kind is almost always the older
		// and lower-numbered one.
		Map<Integer, Integer> agreement = new HashMap<>(),
			lowestDonor = new HashMap<>();
		for (int other : knownIds())
		{
			int attack = genericAttack(other, true);
			if (attack <= 0 || !stanceOf(other).sameClassAs(stance)
				|| styleSource.usageOf(other) != usage)
				continue;
			agreement.merge(attack, 1, Integer::sum);
			lowestDonor.merge(attack, other, Math::min);
		}

		int best = 0;
		for (var candidate : agreement.entrySet())
		{
			if (best == 0
				|| candidate.getValue() > agreement.get(best)
				|| (candidate.getValue().equals(agreement.get(best))
					&& lowestDonor.get(candidate.getKey()) < lowestDonor.get(best)))
				best = candidate.getKey();
		}
		return best;
	}

	/** The first four steps of {@link #attackFor}, from one weapon's own records, or 0. */
	int ownAttack(int key, int style, int kind, boolean realWeapon)
	{
		Stance shipped = bundled.get(key),
			mine = learned.get(key);
		if (shipped != null && shipped.attackByType != null && kind >= 0
			&& kind < shipped.attackByType.length
			&& swingable(shipped.attackByType[kind], realWeapon))
			return shipped.attackByType[kind];
		// The style the player actually has selected, when this weapon has
		// been swung in it. Not borrowed across the class: a style number
		// means different things on different weapon types, so another
		// weapon's slot 2 is not this weapon's slot 2.
		if (mine != null && style >= 0 && mine.attackByStyle != null
			&& style < mine.attackByStyle.length)
		{
			int styled = mine.attackByStyle[style];
			if (swingable(styled, realWeapon) && !notAttacks.contains(styled)
				&& !casts.contains(styled))
				return styled;
		}
		return genericAttack(key, realWeapon);
	}

	/**
	 * A weapon's swing when nothing says which kind of blow: the shipped one,
	 * else the learned one if it is not really a block or special.
	 */
	int genericAttack(int key, boolean realWeapon)
	{
		var shipped = bundled.get(key);
		if (shipped != null && swingable(shipped.attack, realWeapon))
			return shipped.attack;
		var mine = learned.get(key);
		if (mine != null && swingable(mine.attack, realWeapon) && !notAttacks.contains(mine.attack))
			return mine.attack;
		return 0;
	}

	/** Whether an animation can be a weapon's swing at all. */
	static boolean swingable(int animation, boolean realWeapon)
	{
		return animation > 0 && !(realWeapon
			&& (animation == AnimationID.HUMAN_UNARMEDPUNCH || animation == AnimationID.HUMAN_UNARMEDKICK));
	}

	/**
	 * Whether a stance is how a person with nothing in particular stands and
	 * moves, so its class names no weapon type and must not lend a swing.
	 *
	 * <p>Decided by Jagex's own names. A class is normally named for its weapon -
	 * HUMAN_STAFFREADY, XBOWS_HUMAN_READY, SLAYER_ABYSSAL_WHIP_WALK - and borrowing
	 * inside it stays inside one kind of weapon. HUMAN_READY with HUMAN_WALK_F and
	 * HUMAN_RUNNING is the plain human stance instead, which unarmed shares with
	 * every one-handed sword, mace, axe, dagger, pickaxe, claw, bow and dart. A
	 * borrow there gave daggers, maces and warhammers a sword's slash and claws
	 * the macuahuitl's crush. Any other name in the three keeps the borrow: the
	 * whip only walks differently, and that is enough to name it.
	 */
	static boolean isPlainHuman(Stance stance)
	{
		return stance.idle == AnimationID.HUMAN_READY && stance.walk == AnimationID.HUMAN_WALK_F
			&& stance.run == AnimationID.HUMAN_RUNNING;
	}

	/**
	 * Which kind of blow a style button deals, from the game's own combat tab
	 * table.
	 *
	 * @param weaponCategory the player's weapon category (VarbitID.COMBAT_WEAPON_CATEGORY)
	 * @param style the selected style button (COM_MODE)
	 * @return {@link #STAB}, {@link #SLASH} or {@link #CRUSH}, or -1 when the
	 * button deals none of them or is not known
	 */
	int attackKind(int weaponCategory, int style)
	{
		int[] kinds = styleKinds.get(Integer.toString(weaponCategory));
		return kinds == null || style < 0 || style >= kinds.length ? -1 : kinds[style];
	}

	/**
	 * A spell cast to go with this weapon, for a follower that fights with
	 * magic: one learned with it, else its shipped swing when that is a cast,
	 * as a powered staff's is.
	 *
	 * <p>Not {@link #attackFor}: a staff's swing is its melee bash, and a
	 * caster should cast. Like a swing, a cast comes from the weapon's own
	 * records first and then from the weapon it inherits by name, never from
	 * the unarmed record for a real weapon.
	 *
	 * @return 0 when there is none, leaving the caller to cast its default
	 */
	int castFor(int weaponItemId)
	{
		int id = key(weaponItemId),
			cast = ownCast(id);
		if (cast > 0 || id == UNARMED)
			return cast;
		int donor = donorFor(id);
		return donor == UNARMED ? 0 : ownCast(donor);
	}

	int ownCast(int key)
	{
		var mine = learned.get(key);
		if (mine != null)
		{
			if (casts.contains(mine.attack))
				return mine.attack;
			if (mine.attackByStyle != null)
			{
				for (int styled : mine.attackByStyle)
				{
					if (casts.contains(styled))
						return styled;
				}
			}
		}
		var shipped = bundled.get(key);
		return shipped != null && casts.contains(shipped.attack) ? shipped.attack : 0;
	}

	/**
	 * A staff's bash as the follower should play it: without a shield the
	 * game swings with both hands, with one it uses the one-handed chop.
	 * Weapon Animation Replacer records this for both staff sets - 419, or 414
	 * for the second staff set, without a shield and 393 with one. Not yet
	 * confirmed in game: four of the five staves this plugin learned swinging
	 * used 393, which fits, but whether a shield was worn is not recorded.
	 */
	static int withShield(int attack, boolean shield)
	{
		return shield && (attack == AnimationID.HUMAN_STAFFORB_PUMMEL || attack == AnimationID.HUMAN_STAFF_PUMMEL)
			? AnimationID.HUMAN_AXE_CHOP : attack;
	}

	/**
	 * Sets a weapon's stance by hand, for weapons this account cannot wield
	 * and nobody nearby is carrying.
	 *
	 * <p>Weapon animations exist nowhere in the cache - item params hold
	 * combat stats, item category contradicts the observed stances, no struct
	 * carries a pose set, and a byte-level sweep of every archive turns up
	 * only NPC definitions and coincidence. The client assembles them at
	 * runtime. So when observation is impossible, a typed-in id from the
	 * wiki is the honest fallback: real data, just sourced by hand.
	 *
	 * @param attack 0 to leave the learned attack alone
	 */
	void setManual(int weaponItemId, int idle, int walk, int run, int attack)
	{
		int id = key(weaponItemId);
		var stance = learned.get(id);
		if (stance == null || !stance.isComplete())
		{
			// Keep any turns and side-steps the shipped stance knows, and any
			// swing already learned.
			Stance shipped = bundled.get(id),
				poses = shipped != null ? shipped.posesOnly() : new Stance();
			if (stance != null)
			{
				poses.attack = stance.attack;
				poses.attackByStyle = stance.attackByStyle;
			}
			stance = poses;
			learned.put(id, stance);
		}
		stance.idle = idle;
		stance.walk = walk;
		stance.run = run;
		// Directional poses are optional; the selector falls back to walk,
		// which is the client's own behaviour for a stance that lacks them.
		if (attack > 0)
			stance.attack = attack;
		dirty = true;
	}

	/** The library's key for a wielded item id: nothing wielded (0 or -1) is {@link #UNARMED}. */
	static int key(int weaponItemId)
	{
		return weaponItemId <= 0 ? UNARMED : weaponItemId;
	}

	/** A weapon's own stance, learned poses over shipped, or null when never seen or set. */
	Stance describe(int weaponItemId)
	{
		return stanceOf(key(weaponItemId));
	}
	/**
	 * A learned record's poses when it has them, else the shipped stance. A
	 * learned record can hold just a swing, seen with a weapon carried exactly
	 * as shipped.
	 */
	Stance stanceOf(int id)
	{
		var mine = learned.get(id);
		return mine != null && mine.isComplete() ? mine : bundled.get(id);
	}

	boolean known(int id)
	{
		return stanceOf(id) != null;
	}

	Set<Integer> knownIds()
	{
		Set<Integer> ids = new HashSet<>(bundled.keySet());
		for (var entry : learned.entrySet())
		{
			if (entry.getValue().isComplete())
				ids.add(entry.getKey());
		}
		return ids;
	}

	/**
	 * The stance for a weapon: its own if observed, else the one belonging to
	 * the same weapon under a different trim, else unarmed.
	 *
	 * <p>The inheritance is what makes the library cover far more than it has
	 * seen. An ornament kit, a trimmed or gilded version, a poisoned dagger, a
	 * charged or degraded state - all are the same weapon wearing a different
	 * name, and all animate identically. Checked before shipping: of the 13
	 * base-name groups the observed data contains, all 13 agree on their
	 * stance with no exceptions.
	 *
	 * <p>Failing that, the same weapon in a different metal: an Adamant
	 * longsword animates like a Black one. See {@link #tierBaseName(String)}
	 * for why that covers the plain tiers only.
	 *
	 * <p>Deliberately NOT a fuzzy match. Allowing one name to be a subset of
	 * another was measured at 96% - it equates "Dragon axe" with "Dragon
	 * felling axe" - and a wrong animation is worse than a plain one. Both
	 * inheritance steps above are exact matches on what is left after a known
	 * marker is removed, which is why they do not have that failure.
	 */
	Stance forWeapon(int weaponItemId)
	{
		int id = key(weaponItemId);
		var stance = stanceOf(id);
		if (stance != null)
			return stance;
		var inherited = stanceOf(donorFor(id));
		return inherited != null ? inherited : stanceOf(UNARMED);
	}

	/** The weapon this one inherits its stance from, or 0 when there is none. */
	int donorFor(int weaponItemId)
	{
		var cached = donors.get(weaponItemId);
		if (cached != null)
			return cached;

		if (byBaseName == null || indexedSize != size())
			buildNameIndex();

		String name = models.itemName(weaponItemId),
			base = baseName(name);
		int donor = match(byBaseName, base, weaponItemId);
		// The Deadman cosmetics: "Corrupted" is a prefix, not a bracket, so
		// the marker stripping never reaches it. Only when the rest names a
		// weapon the library knows: the Gauntlet's own "Corrupted sceptre"
		// has no plain form and keeps its name.
		if (donor == 0 && base != null && base.startsWith(CORRUPTED))
			donor = match(byBaseName, base.substring(CORRUPTED.length()), weaponItemId);
		// Second chance: the same weapon in a different metal.
		if (donor == 0)
			donor = match(byTierName, tierBaseName(name), weaponItemId);
		donors.put(weaponItemId, donor);
		return donor;
	}

	/**
	 * The weapon a name index holds for a name, unless it is this one; else
	 * 0. No name (null) is never in an index.
	 */
	static int match(Map<String, Integer> index, String name, int weaponItemId)
	{
		var match = index.get(name);
		return match != null && match != weaponItemId ? match : 0;
	}

	void buildNameIndex()
	{
		byBaseName = new HashMap<>();
		byTierName = new HashMap<>();
		for (var known : knownIds())
		{
			String name = models.itemName(known),
				base = baseName(name);
			if (base != null)
				// Lowest id wins: the plain version rather than a variant.
				byBaseName.merge(base, known, Math::min);
			String tierBase = tierBaseName(name);
			if (tierBase != null)
				byTierName.merge(tierBase, known, Math::min);
		}
		indexedSize = size();
		// Names may have arrived since the last resolution failed.
		donors.clear();
	}

	/**
	 * An item name with its metal tier removed, so "Adamant longsword" and
	 * "Black longsword" both become "longsword" - one weapon in two metals,
	 * which animate alike.
	 *
	 * <p>Returns null for anything that does not carry one of these tiers, so
	 * only tiered weapons ever join this index and an untiered weapon can never
	 * be pulled into a group by its noun alone.
	 *
	 * <p>Deliberately excludes dragon, crystal, gilded, 3rd age and the other
	 * ornamental tiers, which the game special-cases. That is measured, not
	 * assumed: across the observed library the plain metal tiers agree on their
	 * stance in all 5 groups that have more than one tier, with no exceptions,
	 * while including the special tiers introduces a real counterexample - the
	 * Dragon longsword stands at 809 where the Black longsword stands at 808.
	 * Admitting them would cover about 65 more weapons at the cost of being
	 * wrong about some of them, and a wrong animation is worse than a plain one.
	 */
	static String tierBaseName(String name)
	{
		String base = baseName(name);
		if (base == null)
			return null;
		var matcher = TIER_PREFIX.matcher(base);
		if (!matcher.find())
			return null;
		String stripped = base.substring(matcher.end()).trim();
		return stripped.isEmpty() ? null : stripped;
	}

	/** The Deadman cosmetic prefix: "Corrupted dragon claws" are dragon claws. */
	static final String CORRUPTED = "corrupted ";

	/** Plain metal tiers only - see {@link #tierBaseName(String)}. */
	static final Pattern TIER_PREFIX = Pattern.compile(
		"^(bronze|iron|steel|black|white|mithril|adamant|rune|runite)\\s+");

	/**
	 * An item name with its variant markers removed, so every version of a
	 * weapon collapses to one key: "Abyssal whip (or)", "Dragon dagger(p++)"
	 * and "Dharok's greataxe 25" become "abyssal whip", "dragon dagger" and
	 * "dharok's greataxe".
	 *
	 * <p>Any trailing bracket goes, rather than a list of known markers. The
	 * list was the original approach and it silently rotted: it knew (p) but
	 * not (kp), so every karambwan-poisoned spear and hasta in the game sat
	 * uncovered next to the plain ones it should have inherited from, and the
	 * same held for the Bounty Hunter (bh) weapons, the Gauntlet's basic,
	 * attuned and perfected tiers, the blackjacks' (o) and (d), and charge
	 * counts like "Enchanted lyre(2)". Every marker the game has ever put in
	 * brackets denotes a state of the same weapon, never a different one.
	 *
	 * <p>Measured before adopting: stripping every trailing bracket collapses
	 * the observed library into 16 multi-item groups, and all 16 agree on their
	 * stance with no exceptions. The match stays EXACT on what remains, which
	 * is what keeps "Toxic staff (uncharged)" away from "Toxic staff of the
	 * dead" and why this does not reintroduce the fuzzy matching that was
	 * rejected at 96%.
	 */
	static String baseName(String name)
	{
		if (name == null || name.isEmpty() || "null".equals(name))
			return null;
		String base = name.toLowerCase(java.util.Locale.ROOT).trim();
		// Some items carry two markers, "(bh)(p++)", so strip repeatedly.
		String previous;
		do
		{
			previous = base;
			base = VARIANT_SUFFIX.matcher(base).replaceAll("").trim();
		}
		while (!base.equals(previous));
		base = DEGRADE_SUFFIX.matcher(base).replaceAll("").trim();
		return base.isEmpty() ? null : base;
	}

	/** Any bracketed marker: ornament, trim, poison, charge, tier, lock. */
	static final Pattern VARIANT_SUFFIX =
		Pattern.compile("\\s*\\([^)]*\\)\\s*$");

	/** Trailing wear or charge level: "Dharok's greataxe 75". */
	static final Pattern DEGRADE_SUFFIX =
		Pattern.compile("\\s+\\d+$");

	boolean knows(int weaponItemId)
	{
		int id = key(weaponItemId);
		return known(id) || donorFor(id) > 0;
	}

	int size()
	{
		int size = bundled.size();
		for (var id : learned.keySet())
		{
			if (!bundled.containsKey(id))
				size++;
		}
		return size;
	}
}

package com.follower;

import com.google.common.base.Strings;
import java.util.*;
import java.util.Set;
import net.runelite.api.*;
import net.runelite.api.Actor;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import lombok.*;
import com.google.gson.Gson;
import java.time.*;
import java.time.ZoneId;
import java.util.List;
import java.util.Map;
import java.util.function.*;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.regex.Pattern;
import net.runelite.api.Item;
import net.runelite.api.gameval.InventoryID;
import static java.lang.Math.*;

/**
 * A snapshot of game state, refreshed once per game tick and shared by every
 * condition evaluated that tick.
 */
@lombok.extern.slf4j.Slf4j
@RequiredArgsConstructor
@Setter
@Getter
class TriggerContext
{

	final Client client;

	int hitpoints,
		maxHitpoints,
		prayerPoints,
		maxPrayerPoints,
		regionId = -1,
		idleTicks,
		ticksSincePrayerDrain = Integer.MAX_VALUE,
		lastPrayerPoints = -1;
	WorldPoint location;
	Set<Integer> loadedRegions = new HashSet<>(),
		equippedItems = new HashSet<>();

	/**
	 * Bumped every {@link #refresh()}: per-tick memoisation key for expensive
	 * state conditions (npcNearby caches its scan against it).
	 */
	int refreshGeneration;

	void refresh()
	{
		var local = client.getLocalPlayer();
		if (local == null)
			return;
		refreshGeneration++;

		if (boundaryTicksLeft > 0)
			boundaryTicksLeft--;

		inWilderness = client.getVarbitValue(WILDERNESS_VARBIT) == 1;

		hitpoints = client.getBoostedSkillLevel(Skill.HITPOINTS);
		maxHitpoints = client.getRealSkillLevel(Skill.HITPOINTS);

		prayerPoints = client.getBoostedSkillLevel(Skill.PRAYER);
		maxPrayerPoints = client.getRealSkillLevel(Skill.PRAYER);

		// getEnergy counts hundredths of a percent, 0-10000 - the same scale
		// RuneLite's own run-energy plugin measures against.
		//
		// This used to divide only when the reading was above 100, meaning to
		// tolerate an older 0-100 API. That guard was backwards where it
		// mattered: 100 hundredths is one percent left, and it was reported as
		// a hundred. Every reading under one percent - exactly the moment a
		// low-energy line is worth saying - read as nearly full.
		energyPercent = client.getEnergy() / 100;

		skulled = local.getSkullIcon() != -1;

		if (lastPrayerPoints >= 0 && prayerPoints < lastPrayerPoints)
			ticksSincePrayerDrain = 0;
		else if (ticksSincePrayerDrain < Integer.MAX_VALUE)
			ticksSincePrayerDrain++;
		lastPrayerPoints = prayerPoints;

		var previousLocation = location;
		location = local.getWorldLocation();
		if (location != null)
		{
			int newRegion = location.getRegionID();
			if (newRegion != regionId)
			{
				// Leaving is what turns a fresh memory into one worth
				// bringing up when you next come back.
				placesJustFiled.remove(regionId);
				incidentJustFiled = false;
				regionId = newRegion;
				noteRegionEntered(newRegion);
			}
			// Seen THIS tick, so pacing along a region boundary - which fires
			// the change over and over - never reads as a string of visits.
			regionLastSeenTick.put(newRegion, client.getTickCount());
		}

		if (previousLocation != null && previousLocation.equals(location) && local.getAnimation() == -1)
			idleTicks++;
		else
			idleTicks = 0;

		// Before combat, which asks whether this is thieving before deciding.
		refreshThieving(local);
		refreshCombat(local);

		refreshLoadedRegions();
		refreshEquipment(local.getPlayerComposition());
		refreshRepetition(local);
		ageQuestion();
		checkWant();
		refreshAttention();
		driftMood();
		noteWhatWeAreDoing();
	}

	// ------------------------------------------------------------------ combat

	int ticksSinceCombat = Integer.MAX_VALUE;
	String combatTarget = "";
	int combatTargetLevel;

	/** Names the boss rules watch for, and those names compiled. */
	Set<String> bossNames = Collections.emptySet();
	List<Pattern> bossPatterns =
		Collections.emptyList();

	/**
	 * Works out whether the player is fighting, from the two things that are
	 * always true of a fight: they are interacting with something that can
	 * fight back, or something is hitting them.
	 *
	 * <p>Interaction alone is not enough - talking to a banker and pickpocketing
	 * a guard are both interactions - so the target has to have a combat level.
	 * Damage is fed in separately by the plugin's hitsplat handler, which
	 * catches being attacked while doing nothing back.
	 */
	// ---------------------------------------------------------------- thieving

	/**
	 * Every stun the player can be put in for getting it wrong.
	 *
	 * <p>There is not one. Measured from the cache: 1054 STUNNED_THIEVING at
	 * 4.48s, 1874 STUNNED_BLACKJACK at 1.28s, 848 HUMAN_STUNNED at 0.64s, and
	 * a whole family sized to the stun's length - STUNNED_2CYCLE through
	 * 6CYCLE at 1.20s, 1.84s, 2.40s, 3.04s and 3.60s.
	 *
	 * <p>Recognising only STUNNED_THIEVING covered one case in seven, so any
	 * other target or method left the stun unaccounted for and the window
	 * running from the last successful attempt instead. That is the "sometimes"
	 * in "sometimes it comes back too early".
	 */
	static final Set<Integer> THIEVING_STUNS = Resources.ids("thievingStuns");

	/**
	 * How long the follower keeps its distance while the player stays put.
	 *
	 * <p>Much longer, because the cost is only that the follower stands a few
	 * tiles away. Anchored to WHERE the thieving happened rather than to a
	 * clock alone: it ends the moment the player walks off, which is the signal
	 * a person actually gives when they are done.
	 */

	int ticksSinceThieving = Integer.MAX_VALUE;
	WorldPoint thievingSpot;

	void refreshThieving(Player local)
	{
		int animation = local.getAnimation();
		// PICKPOCKET_ANIMATION: HUMAN_PICKPOCKET, 1.78s. The attempt itself.
		if (animation == 881 /* PICKPOCKET_ANIMATION */ || THIEVING_STUNS.contains(animation))
		{
			ticksSinceThieving = 0;
			thievingSpot = location;
		}
		else if (ticksSinceThieving < Integer.MAX_VALUE)
			ticksSinceThieving++;

		// Intent can arm the clock before there is anywhere to anchor it - the
		// click arrives from the menu, which does not wait for a refresh. Adopt
		// the first location seen after it, ONCE: without the latch this also
		// re-anchors a session that walking away had just ended, and walking
		// away stops working.
		if (awaitingThievingAnchor && location != null)
		{
			thievingSpot = location;
			awaitingThievingAnchor = false;
		}

		// Walking away ends the session outright, whatever the clock says.
		if (thievingSpot != null && location != null
			&& (location.getPlane() != thievingSpot.getPlane()
			// THIEVING_SESSION_RADIUS: How far the player may drift from the last attempt before the session is
			// considered over.
			// <p>Five tiles was sized for a STALL - a fixed point you stand at. Elves
			// wander and you follow them, so five tiles ended the session every time
			// the mark walked, several times a minute: the follower announced the end
			// of a theft that was still going on, and cheered on the "fight" the next
			// failed attempt looked like. The anchor moves to the player on every
			// attempt, so this only has to cover the drift BETWEEN attempts.
			|| location.distanceTo(thievingSpot) > 12 /* THIEVING_SESSION_RADIUS */
			// THIEVING_SESSION_TICKS: How long a pause can run before the session is over. Two and a half
			// minutes rather than ninety seconds: opening a run of coin pouches or
			// drinking a stamina dose ran past the old figure, which ended the session
			// mid-run and let the next failed pickpocket read as a fight.
			|| ticksSinceThieving > 250 /* THIEVING_SESSION_TICKS */))
		{
			thievingSpot = null;
			awaitingThievingAnchor = false;
		}
	}

	/**
	 * The player has said they are about to steal something.
	 *
	 * <p>Arming on the ANIMATION was too late. Clicking Pickpocket on an elf
	 * across the room sets the interaction target immediately and then the
	 * player walks over, and for every tick of that walk the follower saw an
	 * NPC with a combat level and called it a fight - so the very first attempt
	 * of a session announced a battle that was actually a theft. The click is
	 * intent and arrives first; the animation is outcome and arrives after the
	 * damage.
	 */
	void noteThievingIntent()
	{
		ticksSinceThieving = 0;
		if (location != null)
			thievingSpot = location;
		else
			awaitingThievingAnchor = true;
	}

	/** Set when intent arrived before there was a location to pin it to. */
	boolean awaitingThievingAnchor;

	/**
	 * The player has said they are about to fight something, which ends any
	 * theft outright.
	 *
	 * <p>The session deliberately outlives the gaps between attempts, and the
	 * cost of that is a window where a genuine fight goes unnoticed. An
	 * explicit Attack is the one unambiguous signal that the window should
	 * close now rather than when the player next wanders off.
	 */
	void noteFightIntent()
	{
		thievingSpot = null;
		awaitingThievingAnchor = false;
		ticksSinceThieving = Integer.MAX_VALUE;
	}

	/**
	 * Whether the player is mid-attempt, or was a moment ago. Used to keep a
	 * picked pocket from reading as a fight.
	 */
	boolean isThieving()
	{
		// THIEVING_GRACE_TICKS: How long a thieving ANIMATION counts as an attempt in progress.
		// <p>Only used to keep the session alive across the gap between attempts;
		// the session itself is what everything else asks about.
		return ticksSinceThieving <= 20 /* THIEVING_GRACE_TICKS */;
	}

	/**
	 * Whether the player is still working this spot, gaps between attempts
	 * included. Used to decide whether the follower keeps its distance.
	 */
	boolean isInThievingSession()
	{
		return thievingSpot != null;
	}

	void refreshCombat(Player local)
	{
		// Pickpocketing is not a fight, and it looks exactly like one from
		// here: the target is an NPC with a combat level, and a failed attempt
		// lands a hitsplat. Both of the signals combat is read from are
		// therefore true, and the follower flickered in and out of spectating
		// for the whole run.
		//
		// The whole SESSION is suppressed rather than the attempt, because the
		// gap between attempts is longer than any window sized to a stun, and
		// a fight registered in that gap surfaces the moment thieving ends -
		// which is the follower announcing a fight that never happened.
		//
		// The cost is real and accepted: an actual attack while working a
		// pocket goes unnoticed until the session ends, which it does as soon
		// as the player moves off - and being attacked is one of the few
		// things that makes a player move.
		if (isInThievingSession())
			return;

		var target = local.getInteracting();
		boolean facing = target instanceof NPC && target.getCombatLevel() > 0
			&& target.getHealthRatio() != 0;

		if (facing && blowsHaveBeenExchanged(local, target))
		{
			combatTarget = Strings.nullToEmpty(target.getName());
			combatTargetLevel = target.getCombatLevel();
			ticksSinceCombat = 0;
		}
		else if (ticksSinceCombat < Integer.MAX_VALUE)
			ticksSinceCombat++;
	}

	/**
	 * Whether facing this NPC is a FIGHT, as opposed to merely looking at it.
	 *
	 * <p>Interaction alone used to be enough, and interaction covers walking
	 * up to somebody, talking to them and trading with them. Any levelled NPC
	 * would do - so approaching a guard for directions read as a battle
	 * starting, and the follower announced one.
	 *
	 * <p>A fight has two sides or it has blows. Either the NPC is facing back,
	 * or damage has passed between them recently - the first hit in either
	 * direction arms this through {@link #noteDamageTaken} and
	 * {@link #noteDamageDealt}, and this then keeps it alive for as long as the
	 * two are still squared up.
	 */
	boolean blowsHaveBeenExchanged(Player local, Actor target)
	{
		return target.getInteracting() == local || isInCombat();
	}

	/**
	 * Called by the plugin when the player takes a hit.
	 *
	 * <p>A hit is combat only if the player is ENGAGED - facing a levelled
	 * NPC. Taken alone it is not: running through an aggressive area collects
	 * hits from things the player is neither fighting nor going to fight, and
	 * every combat line is written for the player's own fight ("room to
	 * swing", "you make this look easy") - which is wrong in kind, not just
	 * in volume, when they are the one being chased. Play report: a night's
	 * transcript at 57% combat that was mostly the player getting hit
	 * running past aggro. Retaliation still starts a fight instantly, since
	 * attacking back is interacting; a hit landed by the player still counts
	 * through {@link #noteDamageDealt}; and a boss whose mechanics hit the
	 * player while they are targeting it is engaged by definition.
	 */
	void noteDamageTaken()
	{
		if (isInThievingSession())
			return;
		var local = client.getLocalPlayer();
		var target = local == null ? null : local.getInteracting();
		boolean engaged = target instanceof NPC && target.getCombatLevel() > 0;
		if (engaged)
			ticksSinceCombat = 0;
		else if (local != null)
			noteAttacker(local);
	}

	/**
	 * Who hit the player last while they were not fighting back, and when:
	 * the thing chasing them. A memory filed then is about it. Behaviour
	 * QA5, 19 Oct: run down in the Abyss with nothing targeted, the death
	 * was filed as "the time you died", and said so for two days.
	 */
	String attacker = "";
	int attackerTick = Integer.MIN_VALUE / 2;

	void noteAttacker(Player local)
	{
		var view = client.getTopLevelWorldView();
		var here = local.getWorldLocation();
		if (view == null || here == null)
			return;
		NPC nearest = null;
		int best = Integer.MAX_VALUE;
		for (var npc : view.npcs())
		{
			if (npc == null || npc.getInteracting() != local || npc.getCombatLevel() <= 0
				|| npc.getName() == null || npc.getWorldLocation() == null)
				continue;
			int distance = npc.getWorldLocation().distanceTo(here);
			if (distance < best)
			{
				best = distance;
				nearest = npc;
			}
		}
		if (nearest != null)
		{
			attacker = nearest.getName();
			attackerTick = client.getTickCount();
		}
	}

	/** What hit the player within the last {@code ticks} while they were not fighting it, or empty. */
	String getRecentAttacker(int ticks)
	{
		return client != null && client.getTickCount() - attackerTick <= ticks ? attacker : "";
	}

	/**
	 * The player landed a hit on something, which is the other way a fight
	 * starts - and the only signal available when the target dies before it
	 * can turn round, or cannot reach the player at all.
	 */
	void noteDamageDealt()
	{
		if (isInThievingSession())
			return;
		ticksSinceCombat = 0;
	}

	/** Whether the player is fighting, or was a moment ago. */
	boolean isInCombat()
	{
		// COMBAT_GRACE_TICKS: How long a fight is considered to still be going after the last sign of
		// one. Monsters die, targets are re-clicked, and a boss between phases can
		// leave a tick or two with no interaction at all; without a grace window
		// the follower would bob in and out of spectating throughout a kill.
		return ticksSinceCombat <= 8 /* COMBAT_GRACE_TICKS */;
	}

	/** Whether the player has fought in the last {@code ticks} ticks, or is fighting now. */
	boolean foughtWithin(int ticks)
	{
		return ticksSinceCombat <= ticks;
	}

	/** Whether that fight is with something big enough to call a boss. */
	/**
	 * The names the boss rules list, so that "boss" means one thing.
	 *
	 * <p>It used to mean combat level 100, in two places that had to be kept
	 * agreeing by hand, and the proxy simply fails for anything that fights
	 * above its level. Taking the names from the rules rather than from a
	 * second list in here means adding a boss rule is all it takes: the
	 * follower stands clear of it and cheers it going down without anybody
	 * remembering to say so twice.
	 */
	void setBossNames(Set<String> names)
	{
		if (names == bossNames)
			return;
		bossNames = names == null ? Collections.emptySet() : names;
		List<Pattern> compiled =
			new ArrayList<>(bossNames.size());
		for (String name : bossNames)
			compiled.add(Condition.compileName(name));
		bossPatterns = compiled;
	}

	boolean isNamedBoss(String name)
	{
		if (Strings.isNullOrEmpty(name))
			return false;
		String normalised = Condition.normaliseName(name);
		for (var pattern : bossPatterns)
		{
			if (pattern.matcher(normalised).matches())
				return true;
		}
		return false;
	}

	/** Big enough to be a boss, or named as one. Either will do. */
	boolean isBoss(String name, int level)
	{
		// BOSS_COMBAT_LEVEL: A rough line between "a monster" and "a boss", by combat level.
		return level >= 100 /* BOSS_COMBAT_LEVEL */ || isNamedBoss(name);
	}

	boolean isBossFight()
	{
		return isInCombat() && isBoss(combatTarget, combatTargetLevel);
	}

	// ------------------------------------------------------------ time away

	/**
	 * Minutes between the follower last seeing the player and this login, or -1
	 * when it has no idea - a first run, or a cleared config.
	 *
	 * <p>The only thing in here that outlives a session, and the only thing
	 * that should: it is the difference between a companion that exists when
	 * you are gone and one that is created fresh each time you look at it. A
	 * quick relog is not an absence; a day is.
	 */
	long minutesAway = -1;

	// ---------------------------------------------------------------- tallies

	/**
	 * How many of each thing has happened, ever, keyed by a short label.
	 *
	 * <p>Nothing signals that someone is paying attention like a tally. The
	 * follower knowing this is the fiftieth kalphite is a different kind of
	 * remark from anything it can say about one kill, and it costs a map.
	 *
	 * <p>Keyed by string so a new thing to count needs no new field - the
	 * caller decides the label, the same way rules decide what moves the mood.
	 *
	 * <p>These outlive the session, written back to the config by the plugin.
	 * A count that resets every login is not a memory, it is a scoreboard for
	 * the current game: "your fiftieth" means nothing if the fifty were all
	 * this afternoon, and everything if they were the fifty since you met.
	 */
	final Map<String, Integer> tallies = new HashMap<>();

	/**
	 * The best of each thing seen, keyed the same way. Separate from the
	 * tallies because the operation is different: one accumulates, the other
	 * only ever moves up, and a rule wants to know the moment it moved.
	 */
	final Map<String, Integer> records = new HashMap<>();

	/**
	 * Whether anything countable has moved since the last save.
	 *
	 * <p>The save is nine kilobytes of JSON at the cap and it used to happen
	 * every minute regardless. Most minutes nothing is counted at all: no kill,
	 * no level, no death, and the longest-session record only moves on a day
	 * that beats every previous one.
	 */
	boolean countersDirty;

	/** Marks the saved blob as needing a write, for state set from outside. */
	void markCountersDirty()
	{
		countersDirty = true;
	}

	void clearCountersDirty()
	{
		countersDirty = false;
	}

	/** Counts one, and returns the new total. */
	int tally(String what)
	{
		countersDirty = true;
		return tallies.merge(what, 1, Integer::sum);
	}

	int getTally(String what)
	{
		return tallies.getOrDefault(what, 0);
	}

	/**
	 * The suffix marking a counter as belonging to THIS session.
	 *
	 * <p>They live in the same map as the lifetime ones so a rule can ask about
	 * either with the same condition - "your third death today" and "your
	 * hundredth ever" are the same question with a different key. They are
	 * dropped at login and never written out, which is what makes today mean
	 * today.
	 */
	static final String TODAY = ":today";

	/** Counts one against both the lifetime total and today's. */
	int tallyBoth(String what)
	{
		tally(what + TODAY);
		return tally(what);
	}

	/** Called at login: yesterday's session counters are not today's. */
	void clearDailyTallies()
	{
		tallies.keySet().removeIf(key -> key.endsWith(TODAY));
	}

	/**
	 * Files a value against a record.
	 *
	 * @return whether this BEAT a record that already existed. The first value
	 * ever seen seeds the record silently and returns false on purpose: the
	 * first hit of a new install is not a personal best, it is the only
	 * measurement, and announcing it would make the feature look broken to
	 * every new user at once.
	 */
	boolean noteRecord(String what, int value)
	{
		var previous = records.get(what);
		if (previous == null)
		{
			records.put(what, value);
			countersDirty = true;
			return false;
		}
		if (value <= previous)
			// The overwhelmingly common case, minute after minute: today is not
			// the longest day. Nothing changed, so nothing needs writing.
			return false;
		records.put(what, value);
		countersDirty = true;
		return true;
	}

	int getRecord(String what)
	{
		return records.getOrDefault(what, 0);
	}

	/** Drops a record that has done its job, such as a count now kept under another key. */
	void forgetRecord(String what)
	{
		if (records.remove(what) != null)
			countersDirty = true;
	}

	/**
	 * Each boss's name as the game writes it ("TzTok-Jad"), by the lower-case
	 * name its kill count is kept under, so the Memory window can show it
	 * the game's way rather than as "Tztok-jad".
	 */
	final Map<String, String> killCountNames = new HashMap<>();

	void noteKillCountName(String asWritten)
	{
		if (!asWritten.equals(killCountNames.put(asWritten.toLowerCase(Locale.ROOT), asWritten)))
			countersDirty = true;
	}

	/**
	 * How many times the follower has been started up with this player,
	 * this one included. Counted at login, so the first session is 1.
	 */
	int sessionCount;

	void setSessionCount(int sessionCount)
	{
		this.sessionCount = sessionCount;
		countersDirty = true;
	}

	/**
	 * Puts back what a previous session counted. Merged rather than replaced so
	 * a restore arriving after something has already been counted - a kill in
	 * the first ticks after login - does not throw that away.
	 */
	void restoreCounters(Map<String, Integer> savedTallies,
		Map<String, Integer> savedRecords)
	{
		if (savedTallies != null)
			savedTallies.forEach((key, value) -> tallies.merge(key, value, Integer::sum));
		if (savedRecords != null)
			savedRecords.forEach((key, value) -> records.merge(key, value, Math::max));
		// A restore merges rather than replaces, so what is now in memory is
		// not what is on disk - the next save has real work to do.
		countersDirty = true;
	}

	// -------------------------------------------------------------- wilderness

	/**
	 * Standing in the Wilderness, as a STATE - the crossing already has its
	 * occasion via the varbit event; this is what lets whole bark sets swap
	 * while we are in there (R18).
	 */
	boolean inWilderness;

	static final int WILDERNESS_VARBIT = 5963;

	// -------------------------------------------------------------- stay mode

	/**
	 * True while the follower is on a player-commanded Stay (R25) - not the
	 * stays its own machinery takes for errands, spectating or thrall work.
	 * Fed by the plugin each tick, because only the plugin can tell those
	 * apart. Stay is when the follower is most watched and least occupied,
	 * which is exactly where a little life pays best.
	 */
	boolean followerStaying;

	// ------------------------------------------------------------ npc dialogue

	/**
	 * True while an NPC dialogue box is up, and for the couple of ticks a page
	 * flip drops it. Fed by the plugin each tick, which reads the widgets and
	 * rides out the flips; a quest step that changes mid-conversation waits
	 * on this to fall, so its line arrives just after the box closes.
	 */
	boolean dialogueOpen;

	String speaker;
	int speakerTick;

	/**
	 * The NPC the player is talking to this tick, by the name the box shows.
	 * Not one speaking in a cutscene: the player did not walk up to them.
	 */
	void noteSpeaker(String name)
	{
		speaker = name;
		speakerTick = client.getTickCount();
	}

	/**
	 * Who the player was talking to in the last minute, or null. A line
	 * about them held through that talk is still about someone just met,
	 * though they are a few tiles off by the time it is said.
	 */
	String getRecentSpeaker()
	{
		// SPEAKER_TICKS: A minute: how long after the box the person in it still counts as just
		// talked to. Long enough for a line about them to wait out the gap and a
		// rest behind whatever the box's close raised, a quest's moment most often.
		return speaker != null && client.getTickCount() - speakerTick <= 100 /* SPEAKER_TICKS */ ? speaker : null;
	}

	// ------------------------------------------------------------ quest states

	/** Quest states read this tick, by enum name; cleared when the tick moves on. */
	final Map<String, Boolean> questsDone = new HashMap<>();
	int questsDoneGeneration = -1;

	/**
	 * Whether the named quest is finished, read the way ChronicleProgress
	 * reads it: the {@link net.runelite.api.Quest} constant's own state
	 * script. Asked for only when a rule gets that far, and remembered for
	 * the rest of the tick, so the script runs at most once a tick a quest.
	 *
	 * <p>False with no player, for a name that is no quest, and when the read
	 * throws (before the scripts are ready): a condition that threw would
	 * disable its rule for the session.
	 */
	boolean isQuestDone(String name)
	{
		if (name == null || client.getLocalPlayer() == null)
			return false;
		if (questsDoneGeneration != refreshGeneration)
		{
			questsDoneGeneration = refreshGeneration;
			questsDone.clear();
		}
		var done = questsDone.get(name);
		if (done == null)
		{
			done = readQuestDone(name);
			questsDone.put(name, done);
		}
		return done;
	}

	boolean readQuestDone(String name)
	{
		Quest quest;
		try
		{
			quest = Quest.valueOf(name);
		}
		catch (IllegalArgumentException e)
		{
			return false;
		}
		try
		{
			return quest.getState(client) == net.runelite.api.QuestState.FINISHED;
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	/**
	 * Quests the follower saw finish, and the day (an epoch day), under the
	 * key the chronicle gives them: a quest belongs to the account, where the
	 * memory belongs to the profile.
	 */
	final Map<String, Long> questsSeenFinished = new HashMap<>();

	void noteQuestSeenFinished(String key, long epochDay)
	{
		if (key != null && questsSeenFinished.putIfAbsent(key, epochDay) == null)
			countersDirty = true;
	}

	Long questSeenFinishedOn(String key)
	{
		return key == null ? null : questsSeenFinished.get(key);
	}

	/**
	 * Whether the follower was there for a quest, as the chronicle answers
	 * it: the day it saw the quest through, or null for one done before it
	 * came along. A finished quest is not enough for a line that remembers
	 * doing it together; most players did the early quests years ago.
	 */
	Function<String, Long> questWitness = quest -> null;

	void setQuestWitness(Function<String, Long> lookup)
	{
		questWitness = lookup == null ? quest -> null : lookup;
	}

	Long questWitnessedOn(String quest)
	{
		return quest == null ? null : questWitness.apply(quest);
	}

	// ---------------------------------------------------------- work sessions

	/**
	 * What the player is working at, as the skilling company sees it: a
	 * session opened by a click and proven by the animation or the XP, with
	 * the target and the drops it has counted. Fed by the plugin each tick,
	 * because the controller that keeps the session lives on the follower's
	 * side and this is the rules' side.
	 */
	boolean working;
	String workActivity = "",
		workTargetName = "";
	WorldPoint workTargetTile;
	int workTicks,
		xpDropsThisSession,
		ticksSinceXpDrop = Integer.MAX_VALUE;

	void setWork(boolean working, String activity, String targetName,
		WorldPoint targetTile, int ticks, int drops, int ticksSinceDrop)
	{
		this.working = working;
		workActivity = Strings.nullToEmpty(activity);
		workTargetName = Strings.nullToEmpty(targetName);
		workTargetTile = targetTile;
		workTicks = ticks;
		xpDropsThisSession = drops;
		ticksSinceXpDrop = ticksSinceDrop;
	}

	// --------------------------------------------------------------- boundaries

	/**
	 * A few ticks of breather after something ENDS (R6): combat, a level, an
	 * arrival, a thieving session, the bank. The research is blunt about
	 * timing - a line in the middle of a task is an interruption, the same
	 * line just after the task ends is company - and this is the state that
	 * lets rules aim at the second one.
	 */
	int boundaryTicksLeft;
	String boundaryKind = "";

	void noteBoundary(String kind)
	{
		boundaryKind = Strings.nullToEmpty(kind);
		// BOUNDARY_TICKS: How long an ending stays fresh enough to remark on: about six seconds.
		boundaryTicksLeft = 10 /* BOUNDARY_TICKS */;
	}

	boolean isAtBoundary()
	{
		return boundaryTicksLeft > 0;
	}

	// ---------------------------------------------------------------- line wear

	/**
	 * How many times each line has actually been SAID, across every session -
	 * the ledger behind retiring content the player has heard to death (R17).
	 *
	 * <p>Keyed by the template's hash in hex rather than its text, so the
	 * saved blob stays small: a collision merely shares one wear count
	 * between two lines, which costs a little freshness and shows nothing.
	 * An edited line hashes fresh, which is right - new words are new
	 * content, and they arrive unheard.
	 */
	final Map<String, Integer> lineWear = new HashMap<>();

	static String wearKey(String template)
	{
		return Integer.toHexString(template.hashCode());
	}

	/**
	 * One more actual saying of this line - called at delivery, not at the win.
	 *
	 * <p>Deliberately NOT marking the counters dirty: something is said every
	 * minute or two, and wear alone would turn the every-hundred-ticks
	 * housekeeping write back on for good - the exact rewriting the dirty
	 * flag exists to stop. The ledger rides out with the next write anything
	 * else causes, and the orderly shutdown writes unconditionally; a crash
	 * costs one session's wear, which a statistical ledger can afford.
	 */
	void noteLineSaid(String template)
	{
		if (Strings.isNullOrEmpty(template))
			return;
		lineWear.merge(wearKey(template), 1, Integer::sum);
		// MAX_WORN_LINES: Entries kept. The least-worn are dropped first: they are the farthest
		// from ever standing a line aside, so forgetting them costs the least.
		while (lineWear.size() > 500 /* MAX_WORN_LINES */)
			lineWear.remove(Collections.min(lineWear.entrySet(),
				Map.Entry.comparingByValue()).getKey());
	}

	int lineWear(String template)
	{
		return Strings.isNullOrEmpty(template)
			? 0 : lineWear.getOrDefault(wearKey(template), 0);
	}

	// ------------------------------------------------------------ one-time lines

	/**
	 * Rules marked {@code once} that have already had their one time.
	 *
	 * <p>Kept here rather than on the rule for two reasons, and each one is a
	 * bug avoided. The rule file reloads whenever it changes on disk, throwing
	 * every rule object away and parsing fresh ones - a flag on the object
	 * would un-say the follower's introduction every time a phrase was edited.
	 * And this belongs with the tallies and the places anyway: what the
	 * follower has already told you is memory, and memory is kept in one place.
	 */
	final Set<String> spokenOnce = new HashSet<>();

	boolean hasSaidOnce(String ruleId)
	{
		return ruleId != null && spokenOnce.contains(ruleId);
	}

	void noteSaidOnce(String ruleId)
	{
		if (ruleId != null && spokenOnce.add(ruleId))
		{
			spokenOnceOn.put(ruleId, LocalDate.now().toEpochDay());
			countersDirty = true;
		}
	}

	/**
	 * The day (an epoch day) each one-time line was said. A running bit's
	 * later stages count from the day its opener was heard, not from the
	 * first meeting: counted from the meeting, a follower already past the
	 * last stage's day when the bit arrived would open it and close it in
	 * the same session.
	 */
	final Map<String, Long> spokenOnceOn = new HashMap<>();

	/** Days since the one-time line was said, or -1 if it has not been. */
	int daysSinceSaid(String ruleId)
	{
		var on = ruleId == null ? null : spokenOnceOn.get(ruleId);
		if (on == null)
			return -1;
		long days = LocalDate.now().toEpochDay() - on;
		return days < 0 ? 0 : (int) min(days, Integer.MAX_VALUE);
	}

	/**
	 * The lines and, where saved, their days. A line saved before the days
	 * were kept is dated today: its bit then starts again from its first
	 * stage, which is a repeat, where dating it from the meeting could jump
	 * straight to the end.
	 */
	void restoreSpokenOnce(Collection<String> saved, Map<String, Long> on)
	{
		if (saved != null)
			spokenOnce.addAll(saved);
		if (on != null)
			spokenOnceOn.putAll(on);
		long today = LocalDate.now().toEpochDay();
		for (String id : spokenOnce)
		{
			if (spokenOnceOn.putIfAbsent(id, today) == null)
				countersDirty = true;
		}
	}

	// -------------------------------------------------------------- repeating

	int repeatingAnimation = -1,
		repeatingTicks,
		ticksSinceAnimation;

	void refreshRepetition(Player local)
	{
		int animation = local.getAnimation();

		if (animation == -1)
		{
			// A pause, not necessarily a stop. Hold the count for a moment.
			// REPEAT_GAP_GRACE_TICKS: How long the player has been doing the same thing, in ticks.
			// <p>Repetition is the texture of the game, and a companion that never
			// notices it is not watching. This needs to know nothing about trees or
			// rocks or fish: an animation repeating for minutes IS the activity, so
			// counting the ticks it has been running covers every skill at once,
			// including ones added later.
			// <p>Brief gaps are tolerated. Most gathering drops to no animation for a
			// tick between swings, and treating that as stopping would keep the count
			// at zero forever.
			if (repeatingAnimation != -1 && ++ticksSinceAnimation > 4 /* REPEAT_GAP_GRACE_TICKS */)
			{
				repeatingAnimation = -1;
				repeatingTicks = 0;
			}
			return;
		}

		ticksSinceAnimation = 0;
		if (animation == repeatingAnimation)
			repeatingTicks++;
		else
		{
			repeatingAnimation = animation;
			repeatingTicks = 1;
		}
	}

	// -------------------------------------------------------------- attention

	/**
	 * How many ticks the mouse has been resting on the follower.
	 *
	 * <p>Fed by the plugin, which already projects the clickbox every client
	 * tick to draw the hover hint, so knowing this costs nothing extra.
	 */
	int hoverTicks;

	// ------------------------------------------------------------- incidents

	/**
	 * The last thing daft enough to be worth bringing up again.
	 *
	 * <p>The tallies count; this remembers. They are not the same faculty and
	 * the difference is most of what makes a companion feel like one. "Your
	 * four hundredth yew" is data delivered well. "Careful, I've seen what a
	 * chicken can do to you" is a shared history, and it only works because
	 * something specific happened and was kept.
	 *
	 * <p>One at a time on purpose. A follower with a filing cabinet of
	 * grievances is a different and much worse character than one with a
	 * favourite story.
	 */
	String incidentKey = "",
		incidentPhrase = "";
	int incidentCount;

	/**
	 * The particulars: where it happened (a region id), when (epoch ms) and
	 * who was involved (an NPC name), so a recall can jog the player's memory
	 * rather than allude to it. "How close that was" is a hint; "how close
	 * that was with the Hill Giant, in Edgeville, three days ago" is a
	 * memory two people share.
	 */
	int incidentWhere;
	long incidentWhenMs;
	String incidentWho = "";

	/**
	 * And the rest of what was there to see: the place as said ("Edgeville",
	 * "the Wilderness"), whether that is only the nearest named place, the
	 * item (a drop) and the hitpoints left. Kept apart from the phrase so the
	 * memory can be said again, longer or shorter, in words written later.
	 */
	String incidentPlace = "";
	boolean incidentNear;
	String incidentItem = "";
	int incidentHp = -1;

	/** Place names by region id, from the Locations rules; for {memoryWhere}. */
	Map<Integer, String> regionNames = Collections.emptyMap();

	void setRegionNames(Map<Integer, String> names)
	{
		regionNames = names == null ? Collections.emptyMap() : names;
	}

	/**
	 * Files an incident, or counts another of the same, with the particulars.
	 * Another of the same kind keeps the count and takes the newest
	 * particulars: the memory it brings up is the freshest one, and the count
	 * is what makes "again" honest.
	 *
	 * @param key   what happened, for a rule to recognise
	 * @param phrase how to refer to it out loud - "that chicken"
	 * @param who the NPC involved, or empty
	 */
	void noteIncident(String key, String phrase, String who, long nowMs)
	{
		noteIncident(key, phrase, who, "", -1, nowMs);
	}

	/**
	 * @param item the item involved (a drop), or empty
	 * @param hp   the hitpoints left, or -1
	 */
	void noteIncident(String key, String phrase, String who, String item, int hp, long nowMs)
	{
		if (Strings.isNullOrEmpty(key))
			return;
		if (key.equals(incidentKey))
			incidentCount++;
		else
		{
			incidentKey = key;
			incidentCount = 1;
		}
		incidentPhrase = Strings.nullToEmpty(phrase);
		incidentWhere = regionId;
		incidentJustFiled = true;
		incidentRecalledMs = 0L;
		incidentWhenMs = nowMs;
		incidentWho = Strings.nullToEmpty(who);
		incidentItem = item == null ? "" : item;
		incidentHp = hp;
		incidentPlace = getPlaceHere();
		incidentNear = isPlaceHereNear();
		incidentToRetell = false;
		countersDirty = true;
	}

	/** Whether {@link #getIncidentPlace} is only the nearest named place, not the place itself. */
	boolean isIncidentNear()
	{
		return incidentNear && !incidentPlace.isEmpty();
	}

	/**
	 * The place the incident happened as a sentence says it: "Edgeville",
	 * "the God Wars Dungeon". Filed with the incident; a memory saved before
	 * places were filed reads its region's name from the Locations rules.
	 * Empty when there is none or no incident is held.
	 */
	String getIncidentPlace()
	{
		if (!incidentPlace.isEmpty())
			return incidentPlace;
		String place = placeName(incidentWhere);
		return place.isEmpty() ? "" : shortPlace(place);
	}

	/** "in Edgeville", or "near Lumbridge" for the nearest named place; empty when unknown. */
	String getIncidentWhereSaid()
	{
		return where(getIncidentPlace(), isIncidentNear());
	}

	static String where(String place, boolean near)
	{
		return place.isEmpty() ? "" : (near ? "near " : "in ") + place;
	}

	/** The name the Wilderness goes by, where no Locations rule names the spot. */
	static final String WILDERNESS = "the Wilderness";

	/**
	 * The place here, as a memory filed now would say it: this region's name
	 * from the Locations rules; failing that the Wilderness; failing that the
	 * nearest named region next door, which {@link #isPlaceHereNear} owns up
	 * to. Empty when there is nothing better than a region id.
	 */
	String getPlaceHere()
	{
		String place = placeName(regionId);
		if (!place.isEmpty())
			return shortPlace(place);
		if (inWilderness)
			return WILDERNESS;
		int next = namedNeighbour();
		return next == 0 ? "" : shortPlace(placeName(next));
	}

	/** Whether {@link #getPlaceHere} is a neighbouring region's name rather than this one's. */
	boolean isPlaceHereNear()
	{
		return placeName(regionId).isEmpty() && !inWilderness && namedNeighbour() != 0;
	}

	/** "in Edgeville", "near Lumbridge" or "" for here: the {where} a memory files. */
	String getWhereHere()
	{
		return where(getPlaceHere(), isPlaceHereNear());
	}

	/**
	 * The named region among the eight around this one whose middle is
	 * closest to where the player stands, or 0. A region is 64 tiles a side,
	 * so this is never more than a short walk from the name it borrows.
	 */
	int namedNeighbour()
	{
		if (regionId <= 0)
			return 0;
		int rx = regionId >> 8,
			ry = regionId & 0xFF,
			best = 0;
		long bestDistance = Long.MAX_VALUE;
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				int x = rx + dx,
					y = ry + dy;
				if ((dx == 0 && dy == 0) || x < 0 || y < 0 || y > 0xFF)
					continue;
				int region = (x << 8) | y;
				if (placeName(region).isEmpty())
					continue;
				long distance = location == null ? abs(dx) + abs(dy)
					: square((x << 6) + 32 - location.getX()) + square((y << 6) + 32 - location.getY());
				if (distance < bestDistance)
				{
					bestDistance = distance;
					best = region;
				}
			}
		}
		return best;
	}

	static long square(long n)
	{
		return n * n;
	}

	String placeName(int region)
	{
		String name = region == 0 ? null : regionNames.get(region);
		if (name == null)
			return "";
		int cut = name.length();
		for (String stop : new String[]{":", ",", " - ", " ("})
		{
			int at = name.indexOf(stop);
			if (at > 0 && at < cut)
				cut = at;
		}
		return name.substring(0, cut).trim();
	}

	/**
	 * " in Edgeville", ready to follow the memory in a line; empty when
	 * unknown. The place as said in passing: "in the God Wars Dungeon",
	 * "in Lumbridge", never "in Lumbridge town and castle".
	 */
	String getMemoryWhere()
	{
		return memoryWhereFor(incidentPhrase);
	}

	/**
	 * The same, for the memory said as {@code phrase}: empty when the
	 * phrase names the place already ("your death in Edgeville").
	 */
	String memoryWhereFor(String phrase)
	{
		String place = getIncidentPlace();
		if (place.isEmpty() || (phrase != null && phrase.contains(place)))
			return "";
		return " " + getIncidentWhereSaid();
	}

	/**
	 * A place as the middle of a sentence names it. The Locations rules name
	 * places descriptively: "Lumbridge town and castle" is Lumbridge, "The
	 * Barrows mounds" is the Barrows.
	 */
	static String shortPlace(String place)
	{
		String name = place.trim();
		int and = name.indexOf(" and ");
		if (and > 0)
			name = name.substring(0, and);
		if (name.startsWith("The "))
			name = "the " + name.substring(4);
		for (String tail : new String[]{" town", " plaza", " mounds", " lobby area", " camp"})
		{
			if (name.endsWith(tail) && name.length() > tail.length() + 4)
			{
				name = name.substring(0, name.length() - tail.length());
				break;
			}
		}
		return name;
	}

	/** "just now", "three days ago", or "a while ago" for a memory with no date. */
	String getMemoryWhen(long nowMs)
	{
		if (!hasIncident())
			return "";
		if (incidentWhenMs <= 0 || incidentWhenMs > nowMs)
			return "a while ago";
		long ago = nowMs - incidentWhenMs;
		return ago < 120_000L ? "just now" : Words.duration(ago) + " ago";
	}

	/**
	 * When it happened, the way somebody would say it in passing: "earlier
	 * today", "yesterday", "three days ago", "last week", "a while back".
	 * By the calendar on your clock, so last night is yesterday. An old
	 * record with no date is a while back. Empty with no incident.
	 */
	String getMemoryAgo(long nowMs)
	{
		return getMemoryAgo(nowMs, ZoneId.systemDefault());
	}

	String getMemoryAgo(long nowMs, ZoneId zone)
	{
		if (!hasIncident())
			return "";
		if (incidentWhenMs <= 0 || incidentWhenMs > nowMs)
			return AGO_LONG;
		long days = java.time.temporal.ChronoUnit.DAYS.between(
			Instant.ofEpochMilli(incidentWhenMs).atZone(zone).toLocalDate(),
			Instant.ofEpochMilli(nowMs).atZone(zone).toLocalDate());
		if (days <= 0)
			return "earlier today" /* AGO_TODAY */;
		if (days == 1)
			return "yesterday" /* AGO_YESTERDAY */;
		if (days < 7)
			return Words.number((int) days) + " days ago" /* AGO_DAYS */;
		return days < 14 ? "last week" /* AGO_LAST_WEEK */ : AGO_LONG;
	}

	// The words {memoryAgo} says. Awaiting the player's approval, and said
	// by no shipped line until then: see the memories text review.
	static final String AGO_LONG = "a while back";

	/**
	 * Filed in this region and not left since: still the visit it happened
	 * on. QA, 15 Oct: "Here again, and I've not forgotten the orb breaking"
	 * was said twelve seconds after the orb broke, to somebody still there.
	 */
	boolean incidentJustFiled;

	/**
	 * How old a memory has to be before it is brought up: twenty minutes.
	 * Quests QA5, 20 Oct: "Persten went into the rift. I am not writing
	 * anything for a moment." and, 15 s later, "My mind goes back to Persten
	 * going into the rift, earlier today." Leaving the region was no wait at
	 * all where quest steps and boats cross borders every minute.
	 */
	static final long MEMORY_MIN_AGE_MS = 20L * 60 * 1000;

	/** The same in game ticks, for what a place holds, which is kept without a date. */
	static final int MEMORY_MIN_AGE_TICKS = (int) (MEMORY_MIN_AGE_MS / 600);

	/** Filed less than {@link #MEMORY_MIN_AGE_MS} before {@code nowMs}: too fresh to be a memory yet. */
	boolean isIncidentFresh(long nowMs)
	{
		return hasIncident() && incidentWhenMs > 0 && incidentWhenMs <= nowMs
			&& nowMs - incidentWhenMs < MEMORY_MIN_AGE_MS;
	}

	boolean isFresh(int filedTick)
	{
		return filedTick >= 0 && tickNow() - filedTick < MEMORY_MIN_AGE_TICKS;
	}

	int tickNow()
	{
		return client == null ? 0 : client.getTickCount();
	}

	/**
	 * When the incident was last brought up unprompted, as epoch millis, or
	 * 0. Kept with the memory. Text QA5, 18 Oct: the Castle Wars death was
	 * brought up eighteen times in one day, the only memory there was.
	 */
	long incidentRecalledMs;

	void noteIncidentRecalled(long nowMs)
	{
		incidentRecalledMs = nowMs;
		countersDirty = true;
	}

	/** From the stored memory, after {@link #restoreIncident}. */
	void restoreIncidentRecalled(long epochMs)
	{
		incidentRecalledMs = max(0L, epochMs);
	}

	/** Whether the incident was brought up unprompted already today, by the calendar on your clock. */
	boolean wasIncidentRecalledToday(long nowMs)
	{
		var zone = ZoneId.systemDefault();
		return incidentRecalledMs > 0
			&& Instant.ofEpochMilli(incidentRecalledMs).atZone(zone).toLocalDate()
				.equals(Instant.ofEpochMilli(nowMs).atZone(zone).toLocalDate());
	}

	/** Back in the region the incident happened in. */
	boolean isAtTheIncident()
	{
		return hasIncident() && incidentWhere != 0 && incidentWhere == regionId && !incidentJustFiled;
	}

	/**
	 * Where a death costs nothing and is given back: Castle Wars, its arena
	 * and the tunnels under it, and Last Man Standing's maps, as RuneLite's
	 * loot tracker lists them (LAST_MAN_STANDING_REGIONS, 1.13.1). The user,
	 * 20 Oct: no grief, no memory, no mark. Text QA5: a Castle Wars death was
	 * mourned, filed, and brought up 24 times.
	 */
	static final Set<Integer> SAFE_DEATH_REGIONS = Resources.ids("safeDeathRegions");

	boolean isSafeDeathHere()
	{
		return SAFE_DEATH_REGIONS.contains(regionId);
	}

	/** Whether the NPC the incident was with has one of its kind within so many tiles. */
	boolean isIncidentFoeNearby(int within)
	{
		if (!hasIncident() || incidentWho.isEmpty())
			return false;
		return isNpcNearby(npc -> npc.getName() != null && npc.getName().equalsIgnoreCase(incidentWho),
			within);
	}

	boolean hasIncident()
	{
		return !incidentKey.isEmpty();
	}

	/** Puts back the incident a previous session was still thinking about. */
	void restoreIncident(String key, String phrase, int count, int where, long whenMs,
		String who)
	{
		restoreIncident(key, phrase, count, where, whenMs, who, null, false, null, -1);
	}

	/**
	 * With every particular. A save from before places, items and hitpoints
	 * were filed brings nulls and -1: the place is then read off the region.
	 */
	void restoreIncident(String key, String phrase, int count, int where, long whenMs,
		String who, String place, boolean near, String item, int hp)
	{
		if (Strings.isNullOrEmpty(key))
			return;
		incidentKey = key;
		incidentPhrase = Strings.nullToEmpty(phrase);
		incidentCount = max(1, count);
		incidentWhere = where;
		incidentJustFiled = false;
		incidentWhenMs = whenMs;
		incidentWho = Strings.nullToEmpty(who);
		incidentPlace = Strings.nullToEmpty(place);
		incidentNear = near;
		incidentItem = item == null ? "" : item;
		incidentHp = hp;
		incidentToRetell = isLegacy(incidentPhrase);
	}

	/**
	 * Puts a better way of saying the incident in place of the old words it
	 * was saved with, once the engine has worked one out from the particulars.
	 */
	void retellIncident(String phrase)
	{
		incidentToRetell = false;
		if (!Strings.isNullOrEmpty(phrase) && !phrase.equals(incidentPhrase))
		{
			incidentPhrase = phrase;
			countersDirty = true;
		}
	}

	/** Whether the incident came back from a save in words from before memories named the moment. */
	boolean isIncidentToRetell()
	{
		return incidentToRetell && hasIncident();
	}

	boolean incidentToRetell;

	/**
	 * The fallbacks the memory rules filed before they named the moment.
	 * "I was rereading the entry on the way that went" told the player
	 * nothing. A memory in these words is never said: a restore says it
	 * again from its particulars if it can, and otherwise it waits, unsaid,
	 * to be replaced by the next incident.
	 */
	static final Set<String> VAGUE = Resources.words("vague");

	/** The old forms that named only the foe, which a restore says again in the current words. */
	static final String[] LEGACY_PREFIXES = {"how close that was with ", "the way that went with "};

	/** Whether a memory said this way would tell the player nothing about which moment it was. */
	static boolean isVague(String phrase)
	{
		return Strings.isNullOrEmpty(phrase) || VAGUE.contains(phrase);
	}

	/**
	 * The memory rules' plain forms: what is filed when nothing particular
	 * was known. A memory filed so is not brought up, though a particular
	 * one can still be said this way when nothing longer fits. Behaviour
	 * QA5, 19-20 Oct: "I was rereading the entry on the time you died." six
	 * times, about a death in the Abyss.
	 */
	static final Set<String> PLAIN = Resources.words("plain");

	/** Whether a memory filed this way was filed knowing nothing particular about the moment. */
	static boolean isPlain(String phrase)
	{
		return PLAIN.contains(phrase);
	}

	static boolean isLegacy(String phrase)
	{
		if (isVague(phrase) || isPlain(phrase))
			return true;
		for (String prefix : LEGACY_PREFIXES)
		{
			if (phrase.startsWith(prefix))
				return true;
		}
		return false;
	}

	/** What the follower brings up about a place, keyed the same way. */
	final Map<Integer, String> placeMemories = new HashMap<>();

	/**
	 * Places whose memory was filed on THIS visit, and so is not yet worth
	 * bringing up.
	 *
	 * <p>Found in a transcript: the follower set a personal best, filed the
	 * spot, and told the player about the spot five seconds later - "this is
	 * where you hit harder than you ever had", said to somebody still standing
	 * there. The whole value of a place memory is that it waits, and nothing
	 * made it wait. A region leaves this set when the player leaves the region,
	 * which is precisely what "come back to it" means.
	 */
	final Set<Integer> placesJustFiled = new HashSet<>();

	/** The tick each place's memory was filed on in this session, for {@link #MEMORY_MIN_AGE_TICKS}. */
	final Map<Integer, Integer> placeFiledTick = new HashMap<>();

	/** Records what happened here, for a rule to bring up next time. */
	void notePlaceMemory(String phrase)
	{
		if (Strings.isNullOrEmpty(phrase) || regionId == 0)
			return;
		placeMemories.put(regionId, phrase);
		placesJustFiled.add(regionId);
		placeFiledTick.put(regionId, tickNow());
		countersDirty = true;
		trimPlaces();
	}

	/**
	 * Drops the places it feels least strongly about once there are too many.
	 * A follower with an opinion about everywhere has an opinion about nowhere,
	 * and the saved blob has to stay a sensible size.
	 */
	void trimPlaces()
	{
		// MAX_PLACES: How many places it can hold an opinion about, oldest-weakest evicted.
		while (placeMemories.size() > 60 /* MAX_PLACES */)
			placeMemories.remove(placeMemories.keySet().iterator().next());
	}

	void restorePlaces(
		Map<Integer, String> memories)
	{
		placeMemories.clear();
		if (memories != null)
			placeMemories.putAll(memories);
	}

	/**
	 * Something the follower remembers about this place, or empty.
	 *
	 * <p>Empty while the memory is still fresh from this visit, or less than
	 * twenty minutes old: a thing that happened a moment ago is not a thing
	 * the place reminds you of.
	 */
	String getPlaceMemory()
	{
		if (placesJustFiled.contains(regionId) || isFresh(placeFiledTick.getOrDefault(regionId, -1)))
			return "";
		String here = placeMemories.get(regionId);
		return here == null || isVague(here) ? "" : here;
	}

	boolean hasPlaceMemory()
	{
		return !getPlaceMemory().isEmpty();
	}

	/**
	 * Whether the wished-for thing is actually in the player's bag right now.
	 * A wish with no item list is grantable on word alone.
	 */
	/**
	 * Whether any of these items is in the inventory now. False before the
	 * inventory has loaded, so a rule never rises on an empty read.
	 */
	boolean isInInventory(Collection<Integer> ids)
	{
		var inventory =
			client.getItemContainer(InventoryID.INV);
		if (inventory == null || ids == null)
			return false;
		for (var item : inventory.getItems())
		{
			if (item != null && ids.contains(item.getId()))
				return true;
		}
		return false;
	}

	// ----------------------------------------------------------------- wants

	/**
	 * Somewhere the follower has asked to go, and how long it will keep hoping.
	 *
	 * <p>This is the only thing in here that the follower WANTS rather than
	 * notices. Everything else in this class is a reaction: something happened,
	 * and a rule gets to remark on it. A want runs the other way - the follower
	 * says what it would like, and then the player either does it or does not,
	 * which makes the player's next few minutes an answer to something. A thing
	 * with desires that can be satisfied reads as alive in a way no amount of
	 * commentary manages.
	 *
	 * <p>Deliberately one at a time. Two open wants would make going anywhere
	 * satisfy something, which is the same as satisfying nothing.
	 */
	boolean wantOpen;
	int wantRegion = -1;
	String wantLabel = "";
	int wantDeadlineTick;

	/**
	 * Asks for somewhere. Ignored while a want is already open, so a rule that
	 * fires twice extends nothing and a second rule cannot quietly replace the
	 * first - the follower asked for one thing, and that is the thing.
	 */
	void setWant(int region, String label, int minutes)
	{
		if (wantOpen)
			return;
		// Asking to be taken somewhere you are already standing, and then being
		// delighted about arriving, is not a companion with a wish - it is a
		// companion that cannot see out of the window. The check has to be here
		// rather than in the rule, because a rule has no way to say "anywhere
		// except where we are".
		if (region == regionId)
			return;
		wantOpen = true;
		wantRegion = region;
		wantLabel = Strings.nullToEmpty(label);
		wantDeadlineTick = minutesFromNow(minutes);

		// Logged at INFO rather than debug, and so are both endings. A want
		// happens at most once every twenty minutes, so this is three lines a
		// session - and when one does not land the way it should, the log is
		// the only place that can say whether it opened, what it was watching
		// for, and where the player actually was.
	}

	boolean isWanting()
	{
		return wantOpen;
	}

	/** Ticks left before the open want gives up, or 0. */
	int getWantTicksLeft()
	{
		return wantOpen ? max(0, wantDeadlineTick - client.getTickCount()) : 0;
	}

	/**
	 * Takes what has just come of something, if anything: of a want, the
	 * souvenir, a challenge, advice, a bet, or the player's click underfoot.
	 * Consumed by the engine once per tick and turned into an event, so each
	 * is announced exactly once.
	 */
	TriggerEvent.Type poll(String kind)
	{
		return outcomes.remove(kind);
	}

	/**
	 * What has just come of each kind ("want", "souvenir", "challenge",
	 * "advice", "bet", "underfoot"), until polled: the latest.
	 */
	final Map<String, TriggerEvent.Type> outcomes = new HashMap<>();

	void checkWant()
	{
		if (!wantOpen)
			return;
		if (regionId == wantRegion)
		{
			wantOpen = false;
			outcomes.put("want", TriggerEvent.Type.WANT_FULFILLED);
			return;
		}
		if (client.getTickCount() >= wantDeadlineTick)
		{
			wantOpen = false;
			outcomes.put("want", TriggerEvent.Type.WANT_EXPIRED);
		}
	}

	// ---------------------------------------------------- how long we have known each other

	/**
	 * The day the follower first met this player, as an epoch day.
	 *
	 * <p>The session count already says a hundred logins. It cannot say a
	 * hundred DAYS, and those are different claims about a friendship: one is a
	 * number of visits, the other is a stretch of somebody's life. Only a date
	 * can tell you it has been a year, and only a date can notice that today is
	 * the anniversary of the first one.
	 */
	long metOnDay;

	/** Days since the first meeting, or 0 if it has not been recorded yet. */
	int getDaysKnown()
	{
		if (metOnDay <= 0)
			return 0;
		long days = LocalDate.now().toEpochDay() - metOnDay;
		return days < 0 ? 0 : (int) min(days, Integer.MAX_VALUE);
	}

	/**
	 * Whether today is the same day of the year as the first meeting - and not
	 * the first meeting itself, which is not an anniversary of anything.
	 */
	boolean isAnniversary()
	{
		if (metOnDay <= 0 || getDaysKnown() < 300)
			return false;
		LocalDate met = LocalDate.ofEpochDay(metOnDay),
			today = LocalDate.now();
		return met.getMonthValue() == today.getMonthValue()
			&& met.getDayOfMonth() == today.getDayOfMonth();
	}

	/**
	 * What the player is wearing now, and what they were wearing the day the
	 * follower met them, both in gp.
	 *
	 * <p>Priced by the plugin, which has the item manager; kept here so a
	 * condition can compare them. The comparison is the whole point - a number
	 * on its own is a wealth tracker, and there are better ones. "You were in
	 * bronze when I met you" is only available to something that was there.
	 */
	int wornValue,
		metWearingValue = -1;

	/**
	 * How many times better dressed the player is than the day they met,
	 * or 0 while there is nothing to compare against.
	 */
	int getTimesBetterDressed()
	{
		if (metWearingValue <= 0 || wornValue <= 0)
			return 0;
		return wornValue / max(1, metWearingValue);
	}

	// ---------------------------------------------------------- the levels

	/**
	 * When each skill last went up, as epoch milliseconds keyed by the skill
	 * name in lower case. Kept between sessions, because the gap is the
	 * point: "eleven days since the last one" is something only somebody
	 * who was there for the last one can say.
	 */
	final Map<String, Long> levelStamps = new HashMap<>();

	/**
	 * Files a level and returns how long it had been since the last one in
	 * that skill, or -1 when there is no stamp to measure from.
	 */
	long noteLevel(String skill, int level, long nowMs)
	{
		if (Strings.isNullOrEmpty(skill))
			return -1;
		var previous = levelStamps.put(skill.toLowerCase(Locale.ROOT), nowMs);
		countersDirty = true;
		noteDoing("getting " + skill + " to " + level);
		return previous == null || previous > nowMs ? -1 : nowMs - previous;
	}

	/** How long since any skill went up, or -1 with nothing on record. */
	long sinceAnyLevel(long nowMs)
	{
		long latest = -1;
		for (long stamp : levelStamps.values())
			latest = max(latest, stamp);
		return latest < 0 || latest > nowMs ? -1 : nowMs - latest;
	}

	// ------------------------------------------------------------- goodwill

	/** Half an hour of owing the player one. */
	static final int FAVOUR_TICKS = 3000;

	int favourUntilTick;

	/**
	 * The player did the thing the follower asked for - went where it wanted,
	 * handed over what it wished for. People expect a favour returned, from
	 * software as readily as from anybody, and feel it when it is; so for a
	 * while after, the follower is visibly more attentive. The body reads
	 * {@link #isGrateful} for that; the rules read it as a condition.
	 */
	void noteFavour()
	{
		favourUntilTick = client.getTickCount() + FAVOUR_TICKS;
	}

	boolean isGrateful()
	{
		return client.getTickCount() < favourUntilTick;
	}

	// ------------------------------------------------------------ last time

	/**
	 * The last thing the two of them were doing, in words a greeting can use:
	 * "the woodcutting", "fighting Vorkath", "getting Fishing to 70". The
	 * current session's goes to disk; the previous session's comes back at
	 * login as {@link #getLastTime}, which is what makes the greeting about
	 * last time rather than about the clock.
	 */
	String lastThing = "",
		lastTime = "";

	void noteDoing(String what)
	{
		if (Strings.isNullOrEmpty(what) || what.equals(lastThing))
			return;
		lastThing = what;
		countersDirty = true;
	}

	void restoreLastThing(String saved)
	{
		if (saved == null || saved.isEmpty())
			return;
		lastTime = saved;
		// Carried forward too, so a session in which nothing nameable
		// happens does not wipe the memory on its way out.
		if (lastThing.isEmpty())
			lastThing = saved;
	}

	/** The two things the context can see for itself: the work, and a boss. */
	void noteWhatWeAreDoing()
	{
		if (isWorking() && !workActivity.isEmpty())
			noteDoing("the " + workActivity);
		else if (isInCombat() && isBossFight() && !combatTarget.isEmpty())
			noteDoing("fighting " + combatTarget);
	}

	// ------------------------------------------------------------ addressed

	/**
	 * Where the follower is standing, fed by the plugin each tick, so a
	 * condition can ask whether the player is addressing it: within a tile
	 * and turned toward it. An emote done AT the follower is a different
	 * thing from an emote done near it, and the difference is the difference
	 * between an echo and a reply.
	 */
	WorldPoint followerLocation;

	boolean isAddressingFollower()
	{
		var local = client.getLocalPlayer();
		var here = local == null ? null : local.getWorldLocation();
		if (here == null || followerLocation == null || here.getPlane() != followerLocation.getPlane()
			|| here.distanceTo(followerLocation) != 1)
			return false;
		int toward = bearing(followerLocation.getX() - here.getX(),
			followerLocation.getY() - here.getY());
		int d = (local.getOrientation() - toward) & 0x7ff;
		// FACING_TOLERANCE: Within this much of the exact bearing counts as facing it.
		return min(d, 2048 - d) <= 300 /* FACING_TOLERANCE */;
	}

	/**
	 * The orientation that faces (dx, dy), on the actor circle: 0 south, 512
	 * west, 1024 north, 1536 east - the inverse of the facing vector
	 * (-sin, -cos) the entity uses.
	 */
	static int bearing(int dx, int dy)
	{
		return (int) round(atan2(-dx, -dy) / (2.0 * PI) * 2048.0) & 0x7ff;
	}

	// ------------------------------------------------------------- underfoot

	/**
	 * The player clicked the tile the follower happened to be standing on.
	 *
	 * <p>The one nuisance of a companion that nothing in here acknowledged. It
	 * keeps clear of fights and it walks behind you, and then every so often it
	 * is simply in the way, and a follower that never notices that is a follower
	 * you are managing rather than travelling with.
	 *
	 * <p>Consumed on read, because it is a moment rather than a state: the tile
	 * is walked to a second later and the fact stops being true.
	 */
	void noteUnderfoot()
	{
		outcomes.put("underfoot", TriggerEvent.Type.UNDERFOOT);
	}

	// ------------------------------------------------------- gone, or just still

	/**
	 * Whether the player has stopped touching the controls, as distinct from
	 * standing still on purpose.
	 *
	 * <p>{@code idle} cannot tell those apart: a player at a furnace and a
	 * player who has gone to make tea look identical to it, and the follower
	 * saying "still here, still standing" to an empty chair is only funny by
	 * accident. The camera is one tell; the feet and hands are the others -
	 * a player who just moved or animated is at the keyboard whatever the
	 * camera is doing, which matters because plenty of real play (and every
	 * simulation) runs minutes at a time on an untouched camera.
	 */
	int cameraX = Integer.MIN_VALUE,
		cameraY,
		cameraPitch,
		stillTicks;

	/** Evidence of presence from outside the snapshot: a real event arrived. */
	void noteAttention()
	{
		stillTicks = 0;
	}

	void refreshAttention()
	{
		int x = client.getCameraX(),
			y = client.getCameraY(),
			pitch = client.getCameraPitch();
		if (cameraX == Integer.MIN_VALUE)
		{
			cameraX = x;
			cameraY = y;
			cameraPitch = pitch;
			return;
		}
		boolean cameraMoved = x != cameraX || y != cameraY || pitch != cameraPitch;
		if (cameraMoved)
		{
			cameraX = x;
			cameraY = y;
			cameraPitch = pitch;
		}
		// Runs after the idle update on purpose: idleTicks at zero means the
		// player moved or animated THIS tick, which is presence too.
		if (cameraMoved || idleTicks == 0)
		{
			stillTicks = 0;
			return;
		}
		if (stillTicks < Integer.MAX_VALUE)
			stillTicks++;
	}

	/** Ticks since the camera last moved. */
	int getUnattendedTicks()
	{
		return stillTicks;
	}

	/** The tick each animation the player played was last played. */
	final Map<Integer, Integer> actTicks = new HashMap<>();

	/**
	 * Whether the player has played any of these since that tick: for a
	 * warning kept waiting, already answered. Behaviour QA, 16 Oct: "Get
	 * out!" was said after the teleport, and a minute later the advice was
	 * called ignored.
	 */
	boolean actedSince(Collection<Integer> ids, int tick)
	{
		for (var id : ids)
		{
			var at = actTicks.get(id);
			if (at != null && at >= tick)
				return true;
		}
		return false;
	}

	/** Offered every animation the player plays, and settles advice outstanding. */
	void offerAct(int animationId)
	{
		actTicks.put(animationId, client.getTickCount());
	}
	// ----------------------------------------------------------- the clock

	/**
	 * The hour on the player's own wall, 0-23.
	 *
	 * <p>Nothing else in the game acknowledges the room the player is sitting
	 * in, which is exactly why a follower noticing it lands the way it does.
	 */
	int getHourOfDay()
	{
		return java.time.LocalTime.now().getHour();
	}

	/** The tick so many minutes from now, one at least: a hundred ticks to the minute. */
	int minutesFromNow(int minutes)
	{
		return client.getTickCount() + max(1, minutes) * 100;
	}

	/**
	 * Today's date on the same wall, packed month*100+day so a range compare
	 * can wrap past new year the way timeOfDay wraps past midnight.
	 */
	int getMonthDay()
	{
		var today = LocalDate.now();
		return today.getMonthValue() * 100 + today.getDayOfMonth();
	}

	/** Minutes this session has run, fed by the plugin's own timer. */
	int sessionMinutes;

	// ----------------------------------------------------------- conversation

	/**
	 * How long the follower keeps hoping for an answer.
	 *
	 * <p>Two minutes. It was twelve seconds when the answer was a word typed
	 * into public chat, which is about how long typing "yes" takes. Answering
	 * now means walking over and right-clicking Talk-to, and a window sized for
	 * typing would have expired somewhere around the second click.
	 */
	static final int ANSWER_WINDOW_TICKS = 200;

	int ticksSinceQuestion = Integer.MAX_VALUE;

	/**
	 * The dialog tree that answers the open question, or empty.
	 *
	 * <p>This is what makes Talk-to mean something different for a minute or
	 * two: the follower asked, so the conversation it opens is the one about
	 * what it asked, and the everyday script waits its turn.
	 */
	String askedTree = "";

	/** Called when a rule carrying {@code asks} speaks. */
	void noteQuestion(String treeId)
	{
		ticksSinceQuestion = 0;
		askedTree = Strings.nullToEmpty(treeId);
	}

	/** Called once the player has answered, or declined to. */
	void noteAnswered()
	{
		ticksSinceQuestion = Integer.MAX_VALUE;
		askedTree = "";
		// Engaging with a question clears the ignored ledger: the back-off
		// exists for a player who is not answering, not one who just did.
		ignoredAsks = 0;
		askBackoffUntilTick = 0;
	}

	boolean isAwaitingAnswer()
	{
		return ticksSinceQuestion <= ANSWER_WINDOW_TICKS;
	}

	/** The tree Talk-to should open right now, or empty for the everyday one. */
	String getAskedTree()
	{
		return isAwaitingAnswer() ? askedTree : "";
	}

	void ageQuestion()
	{
		if (ticksSinceQuestion < Integer.MAX_VALUE)
			ticksSinceQuestion++;
		// The question just lapsed with nobody answering. That is a signal,
		// not a non-event: a transcript showed fifteen outings asked into one
		// AFK afternoon, each politely expiring and each politely re-asked at
		// the next cooldown, which added up to nagging. A hint dropped and
		// ignored earns a long pause; two of them end the asking for the day.
		if (ticksSinceQuestion == ANSWER_WINDOW_TICKS + 1 && !askedTree.isEmpty())
		{
			askedTree = "";
			ignoredAsks++;
			// ASK_BACKOFF_TICKS: Two hours before an ignored question may be followed by another.
			askBackoffUntilTick = client.getTickCount() + 12_000 /* ASK_BACKOFF_TICKS */;
		}
	}

	// ------------------------------------------------------- ignored overtures


	int ignoredAsks,
		askBackoffUntilTick;

	/**
	 * Whether rules that ASK something should hold their tongue: a question
	 * was ignored recently, or two have been ignored this session. Answering
	 * any question resets both.
	 */
	boolean isAskBackedOff()
	{
		// MAX_IGNORED_ASKS: Ignored questions per session before the asking stops altogether.
		return ignoredAsks >= 2 /* MAX_IGNORED_ASKS */
			|| client.getTickCount() < askBackoffUntilTick;
	}

	// ------------------------------------------------------------------- mood

	/**
	 * How the follower is feeling, 0 (flat) to 100 (delighted), starting even.
	 *
	 * <p>One number rather than several axes, because the point is not to model
	 * an emotion - it is to give the lines already written a STATE to be said
	 * from. A rule that only fires when the follower is low turns the same
	 * event into a different moment depending on how the session has gone,
	 * which is most of what makes a companion feel like it is present rather
	 * than reacting.
	 *
	 * <p>Nothing here decides what moves it. Rules do, by carrying a {@code
	 * mood} nudge, which means every trigger the engine already understands can
	 * affect it and a new influence is an edit to phrases.json rather than to
	 * this file.
	 *
	 * <p>Session-scoped on purpose. A follower that remembered last night's bad
	 * run would be strange, and a fresh start each login is also the honest
	 * default for something that cannot see what you did while it was gone.
	 */
	static final int MOOD_NEUTRAL = 50;

	int mood = MOOD_NEUTRAL,
		ticksSinceMoodDrift;

	/**
	 * Nudges the mood and clamps it. Called when a rule carrying a nudge fires.
	 *
	 * @return the mood after the nudge
	 */
	int adjustMood(int delta)
	{
		int before = mood;
		mood = max(0 /* MOOD_MIN */, min(100 /* MOOD_MAX */, mood + delta));
		if (mood != before)
		{
		}
		return mood;
	}

	/**
	 * The band the mood falls in, which is what rules should normally ask for -
	 * a name reads better in a rule file than a number, and the boundaries can
	 * move without every rule having to.
	 */
	String getMoodBand()
	{
		if (mood <= 20)
			return "low";
		if (mood <= 40)
			return "down";
		if (mood < 60)
			return "even";
		if (mood < 80)
			return "good";
		return "high";
	}

	/**
	 * Pulls the mood back toward neutral a point at a time, so nothing that
	 * happens is permanent and a bad stretch is recovered from by carrying on.
	 */
	void driftMood()
	{
		if (mood == MOOD_NEUTRAL)
		{
			ticksSinceMoodDrift = 0;
			return;
		}
		// MOOD_DRIFT_TICKS: Ticks between one point of drift back toward neutral: about 30 seconds.
		if (++ticksSinceMoodDrift < 50 /* MOOD_DRIFT_TICKS */)
			return;
		ticksSinceMoodDrift = 0;
		mood += mood > MOOD_NEUTRAL ? -1 : 1;
	}

	// ----------------------------------------------------------------- memory

	final Map<Integer, Integer> regionVisits = new HashMap<>(),
		regionLastSeenTick = new HashMap<>();

	WorldPoint deathLocation;
	int deathTick = -1;

	void noteRegionEntered(int region)
	{
		var lastSeen = regionLastSeenTick.get(region);
		// REVISIT_GAP_TICKS: How long a region has to go unvisited before coming back counts as a
		// RETURN rather than a wander along its edge. Region boundaries run through
		// the middle of towns, so without this a trip across Varrock square would
		// tally half a dozen visits.
		if (lastSeen == null || client.getTickCount() - lastSeen > 250 /* REVISIT_GAP_TICKS */)
			regionVisits.merge(region, 1, Integer::sum);
	}

	/** Session visits to the CURRENT region, for the returnVisit condition. */
	int getRegionVisits()
	{
		return regionVisits.getOrDefault(regionId, 0);
	}

	/**
	 * Called by the plugin when the player dies.
	 *
	 * <p>This used to be session memory, on the reasoning that a companion
	 * remembering last week's death forever would wear thin. That was the
	 * wrong call: within a session the only time you are near the spot is the
	 * walk back for your gravestone, which is the one moment the line must NOT
	 * fire - hence the arming delay. Kept between sessions it becomes what it
	 * was always trying to be, which is an anniversary.
	 */
	void noteDeath(WorldPoint where)
	{
		deathLocation = where;
		deathTick = client.getTickCount();
		countersDirty = true;
	}

	/**
	 * Puts back a death from a previous session. The arming delay is spent:
	 * whenever it was, it was not this walk back.
	 */
	void restoreDeathSpot(WorldPoint where)
	{
		deathLocation = where;
		deathTick = Integer.MIN_VALUE / 2;
	}

	/**
	 * Whether the player is standing near where they last died - and long
	 * enough after the death that being there again is a RETURN, not the
	 * dying itself or the walk back for the gravestone.
	 */
	boolean isNearDeathSpot(int within)
	{
		return deathLocation != null && location != null
			// DEATH_SPOT_ARM_TICKS: Death-site lines stay quiet this long after the death itself, since the
			// first person at the spot is the dying player.
			&& client.getTickCount() - deathTick > 200 /* DEATH_SPOT_ARM_TICKS */
			&& location.getPlane() == deathLocation.getPlane()
			&& location.distanceTo(deathLocation) <= within;
	}

	/**
	 * Worn item ids taken from the player's composition. Note this covers only
	 * slots with a visible model: rings and ammo never appear here.
	 */
	/**
	 * Whether a refresh has actually seen the local player's composition yet.
	 * False for the first ticks after login, while the player entity is still
	 * materialising - state read before this is empty, not truth.
	 */
	boolean playerReady;

	/** Run energy as a whole percentage, 0-100. */
	int energyPercent = 100;

	boolean skulled;

	/** The raw arrays behind the two sets, kept so an unchanged tick costs nothing. */
	int[] lastRegionIds,
		lastEquipmentIds;

	/**
	 * The loaded map regions, rebuilt only when they actually change.
	 *
	 * <p>They change on a chunk load and are identical on every other tick, so
	 * boxing the array into a fresh set each time was allocating for no reason
	 * several times a second for the whole session.
	 */
	void refreshLoadedRegions()
	{
		var view = client.getTopLevelWorldView();
		if (view == null)
			// Between worlds: the regions we last knew about still stand.
			return;
		int[] regions = view.getMapRegions();
		if (Arrays.equals(regions, lastRegionIds))
			return;
		lastRegionIds = regions == null ? null : regions.clone();

		Set<Integer> rebuilt = new HashSet<>();
		if (regions != null)
		{
			for (int region : regions)
				rebuilt.add(region);
		}
		loadedRegions = rebuilt;
	}

	void refreshEquipment(PlayerComposition composition)
	{
		playerReady = composition != null;
		int[] ids = composition == null ? null : composition.getEquipmentIds();

		// Same reasoning as the regions: worn gear is the same array tick after
		// tick, and the old code rebuilt a set and compared it just to decide
		// whether to log.
		if (Arrays.equals(ids, lastEquipmentIds))
			return;
		lastEquipmentIds = ids == null ? null : ids.clone();

		Set<Integer> worn = new HashSet<>();
		if (ids != null)
		{
			for (int raw : ids)
			{
				// Items start at 2048; 256..2047 is the kit range. Using 512 here
				// meant every body kit was reported as a worn item, so an
				// equippedItem rule could fire on a hairstyle.
				if (raw >= PlayerComposition.ITEM_OFFSET)
					worn.add(raw - PlayerComposition.ITEM_OFFSET);
			}
		}
		equippedItems = worn;
	}

	int getHitpointsPercent()
	{
		return maxHitpoints <= 0 ? 100 : (hitpoints * 100) / maxHitpoints;
	}

	int getPrayerPercent()
	{
		return maxPrayerPoints <= 0 ? 100 : (prayerPoints * 100) / maxPrayerPoints;
	}

	boolean isPrayerActive()
	{
		// PRAYER_DRAIN_MEMORY_TICKS: Prayer counts as "active" if points have dropped within this many ticks.
		return ticksSincePrayerDrain <= 5 /* PRAYER_DRAIN_MEMORY_TICKS */;
	}

	boolean isRegionLoaded(int region)
	{
		return loadedRegions.contains(region);
	}

	boolean isEquipped(int itemId)
	{
		return equippedItems.contains(itemId);
	}

	boolean isNpcNearby(Predicate<NPC> predicate, int within)
	{
		return isNpcNearby(predicate, within, false);
	}

	/**
	 * @param requireVisible the NPC must also have line of sight to the
	 * player. For rules whose line invites the player to LOOK at something:
	 * "that thing is very large and very close" pointing at a wall with a
	 * kalphite behind it is worse than silence, because a bad callout teaches
	 * the player to stop checking. Distance alone was the whole test before
	 * this, and a different plane was only excluded by accident of
	 * {@code distanceTo} returning MAX_VALUE across planes.
	 */
	boolean isNpcNearby(Predicate<NPC> predicate, int within,
		boolean requireVisible)
	{
		var view = client.getTopLevelWorldView();
		if (view == null)
			// Mid-login the scene is not there to search, and a rule that
			// throws here is disabled for the session - an expensive way to
			// answer a question whose honest answer is no.
			return false;
		for (var npc : view.npcs())
		{
			if (npc == null)
				continue;
			// Distance first: it is cheap, and the predicate is a name match
			// per pattern, which over a whole loaded scene once a tick per
			// rule cost milliseconds in a crowd (perf audit, Oct 2026).
			var npcLocation = npc.getWorldLocation();
			if (location == null || npcLocation == null)
				continue;
			if (npcLocation.distanceTo(location) > within || !predicate.test(npc))
				continue;
			if (!requireVisible || canSee(npcLocation, npcSize(npc)))
				return true;
		}
		return false;
	}

	static int npcSize(NPC npc)
	{
		return npc.getComposition() == null ? 1
			: max(1, npc.getComposition().getSize());
	}

	/**
	 * Line of sight from an NPC's area to the player, by the game's own
	 * algorithm - {@link net.runelite.api.coords.WorldArea#hasLineOfSightTo}
	 * reads the scene's sight-blocking collision flags, which is exactly what
	 * the game consults to decide the same question.
	 *
	 * <p>The area is built from location and size rather than asked of the
	 * actor, and no collision data reads as visible: during loading there is
	 * nothing to consult, and refusing to speak about a boss because the map
	 * has not finished arriving would be the wrong kind of caution.
	 */
	boolean canSee(WorldPoint from, int size)
	{
		var wv = client.getTopLevelWorldView();
		if (wv == null || wv.getCollisionMaps() == null)
			return true;
		return new net.runelite.api.coords.WorldArea(from, size, size)
			.hasLineOfSightTo(wv, location);
	}

	/**
	 * How many other players are standing within {@code within} tiles.
	 *
	 * <p>Memoised per tick against the refresh generation, like the NPC scan:
	 * a busy bank holds a couple of hundred players and the answer cannot
	 * change between two conditions evaluated on the same tick.
	 */
	int countPlayersNearby(int within)
	{
		if (crowdGeneration == refreshGeneration && crowdWithin == within)
			return crowdCached;
		crowdGeneration = refreshGeneration;
		crowdWithin = within;

		int found = 0;
		var local = client.getLocalPlayer();
		var view = client.getTopLevelWorldView();
		if (location != null && view != null)
		{
			for (var other : view.players())
			{
				if (other == null || other == local)
					continue;
				var where = other.getWorldLocation();
				if (where != null && where.distanceTo(location) <= within)
					found++;
			}
		}
		crowdCached = found;
		return found;
	}

	int crowdGeneration = -1,
		crowdWithin = -1,
		crowdCached;

	/** An inventory holds twenty-eight things and always has. */
	static final int INVENTORY_SIZE = 28;

	int freeSlotsGeneration = -1,
		freeSlots = INVENTORY_SIZE;

	/**
	 * Empty inventory slots.
	 *
	 * <p>Counted by walking the container and counting what is IN it, rather
	 * than trusting {@code size()} or {@code count()}: one of those is the
	 * container's capacity and the other the number of items, and which is
	 * which is not worth betting a wrong warning on. Everything with an id
	 * above zero occupies a slot under either reading, so counting those and
	 * subtracting is right whichever way round it is.
	 *
	 * <p>Worked out on demand and memoised per tick, so a rule set with no
	 * inventory rule in it never pays for this at all.
	 */
	int getFreeInventorySlots()
	{
		if (freeSlotsGeneration == refreshGeneration)
			return freeSlots;
		freeSlotsGeneration = refreshGeneration;

		var inventory =
			client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			// Not loaded yet. Reporting a full inventory here would have the
			// follower warning about a bag it has not seen.
			freeSlots = INVENTORY_SIZE;
			return freeSlots;
		}

		int used = 0;
		for (var item : inventory.getItems())
		{
			if (item != null && item.getId() > 0)
				used++;
		}
		freeSlots = max(0, INVENTORY_SIZE - used);
		return freeSlots;
	}

	String getPlayerName()
	{
		var local = client.getLocalPlayer();
		return local == null || local.getName() == null ? "you" : local.getName();
	}

	// ----------------------------------------------------------- saved memory

	/**
	 * What the follower has counted, kept between sessions.
	 *
	 * <p>The counts themselves are the point of the feature: "your fiftieth"
	 * means nothing if the fifty were all this afternoon, and everything if
	 * they were the fifty since you met. A session-scoped tally is a scoreboard;
	 * this is a memory.
	 *
	 * <p>One config value holding one JSON object, for the same reason the
	 * last-seen stamp is a config value: RuneLite already persists config per
	 * profile, and a file of our own would be more machinery than this deserves.
	 */
	static class SavedCounters
	{
		Map<String, Integer> tallies,
			records;
		/** Each boss's name as the game writes it, by its lower-case kill count key. */
		Map<String, String> killCountNames;
		int sessions;

		/** The incident the follower is still thinking about, and how to say it. */
		String incidentKey,
			incidentPhrase;
		int incidentCount;
		/** Where (a region id), when (epoch ms) and who it was with. */
		int incidentWhere;
		long incidentWhenMs;
		String incidentWho;
		/**
		 * The place as said, whether that is only the nearest named place,
		 * the item and the hitpoints left. Absent from older saves, which
		 * read the place off the region and know no item or hitpoints.
		 */
		String incidentPlace;
		Boolean incidentNear;
		String incidentItem;
		Integer incidentHp;
		/** When it was last brought up unprompted, so that is once a day. */
		long incidentRecalledMs;

		/**
		 * Where the last death happened. Session-scoped memory made
		 * nearDeathSpot a thing that could only fire on the walk back; kept
		 * between sessions it becomes an anniversary, which is a much better
		 * line - "this is the spot" six weeks later.
		 */
		int deathX,
			deathY,
			deathPlane = -1;

		/**
		 * What each place has come to mean, and the one thing worth bringing up
		 * about it. Keyed by region id. Earned rather than rolled, so unlike the
		 * traits blob this one is never regenerated - losing it would have the
		 * follower forget which places it has reason to feel anything about.
		 */
		Map<Integer, String> placeMemories;

		/**
		 * Ids of the one-time lines already said. Small and slow-growing: there
		 * are only ever as many entries as there are firsts worth marking.
		 */
		List<String> spokenOnce;
		/** And the day (an epoch day) each was said; missing from older saves. */
		Map<String, Long> spokenOnceOn;
		/** Quests the follower saw finish, by quest and account, and the day. */
		Map<String, Long> questsSeenFinished;

		/**
		 * How worn each line is - times actually said, keyed by the template's
		 * hash so the blob stays small. Capped at 500 entries by the context,
		 * least-worn dropped first.
		 */
		Map<String, Integer> lineWear;

		/**
		 * The day the follower first met this player, as an epoch day. Written
		 * once and never again: it is the only thing here that would be a lie
		 * if it were ever recalculated.
		 */
		long metOnDay;

		/** What the player was wearing then, so an upgrade has something to beat. */
		int metWearingValue = -1;

		/** When each skill last went up, so the next level knows how long it took. */
		Map<String, Long> levelStamps;

		/** What the two of them were doing when the session ended, for the greeting. */
		String lastThing;
	}

	/**
	 * How many counters are kept. Every distinct NPC name the player has ever
	 * killed earns an entry, so this grows for as long as the plugin is used;
	 * without a bound it would grow into the config file forever. The rarest
	 * counts go first, since a count of one is the least likely to be the
	 * subject of a milestone rule.
	 */
	static final int MAX_COUNTERS = 300;

	/**
	 * Puts a saved blob back, and returns the gear value the follower first
	 * met the player wearing. FollowerPlugin.restoreMemory is the seam, and
	 * reads a blob that is not JSON as no memory at all.
	 */
	int restoreMemory(String stored, Gson gson, int fallbackMetWearing)
	{
		if (Strings.isNullOrEmpty(stored))
			return fallbackMetWearing;
		SavedCounters saved = gson.fromJson(stored, SavedCounters.class);
		if (saved == null)
			return fallbackMetWearing;
		restoreCounters(saved.tallies, saved.records);
		if (saved.killCountNames != null)
			saved.killCountNames.forEach(killCountNames::putIfAbsent);
		setSessionCount(saved.sessions);
		restoreIncident(saved.incidentKey, saved.incidentPhrase,
			saved.incidentCount, saved.incidentWhere, saved.incidentWhenMs, saved.incidentWho,
			saved.incidentPlace, Boolean.TRUE.equals(saved.incidentNear), saved.incidentItem,
			saved.incidentHp == null ? -1 : saved.incidentHp);
		restoreIncidentRecalled(saved.incidentRecalledMs);
		restorePlaces(saved.placeMemories);
		restoreSpokenOnce(saved.spokenOnce, saved.spokenOnceOn);
		if (saved.questsSeenFinished != null)
			questsSeenFinished.putAll(saved.questsSeenFinished);
		if (saved.lineWear != null)
		{
			saved.lineWear.forEach((key, value) -> lineWear.merge(key, value, Integer::sum));
			countersDirty = true;
		}
		setMetOnDay(saved.metOnDay);
		setMetWearingValue(saved.metWearingValue);
		if (saved.levelStamps != null)
			saved.levelStamps.forEach((skill, stamp) -> levelStamps.merge(skill, stamp, Math::max));
		restoreLastThing(saved.lastThing);
		if (saved.deathPlane >= 0)
			restoreDeathSpot(new WorldPoint(
				saved.deathX, saved.deathY, saved.deathPlane));
		return saved.metWearingValue;
	}

	/** Everything the follower remembers, as it goes to disk. */
	String snapshotMemory(Gson gson, int metWearing)
	{
		var saved = new SavedCounters();
		saved.tallies = trimCounters(tallies);
		saved.records = trimCounters(records);
		saved.killCountNames = copyOrNull(killCountNames);
		saved.sessions = sessionCount;
		saved.incidentKey = incidentKey;
		saved.incidentPhrase = incidentPhrase;
		saved.incidentCount = incidentCount;
		saved.incidentWhere = incidentWhere;
		saved.incidentWhenMs = incidentWhenMs;
		saved.incidentWho = orNull(incidentWho);
		saved.incidentPlace = orNull(getIncidentPlace());
		saved.incidentNear = isIncidentNear() ? Boolean.TRUE : null;
		saved.incidentItem = orNull(incidentItem);
		saved.incidentHp = incidentHp < 0 ? null : incidentHp;
		saved.incidentRecalledMs = incidentRecalledMs;
		saved.placeMemories = placeMemories;
		saved.spokenOnce = new ArrayList<>(spokenOnce);
		saved.spokenOnceOn = copyOrNull(spokenOnceOn);
		saved.questsSeenFinished = copyOrNull(questsSeenFinished);
		saved.lineWear = lineWear;
		saved.metOnDay = metOnDay;
		saved.metWearingValue = metWearing;
		saved.levelStamps = copyOrNull(levelStamps);
		saved.lastThing = orNull(lastThing);
		var died = deathLocation;
		if (died != null)
		{
			saved.deathX = died.getX();
			saved.deathY = died.getY();
			saved.deathPlane = died.getPlane();
		}
		return gson.toJson(saved);
	}

	/** Nothing is written as absent. */
	static String orNull(String text)
	{
		return text.isEmpty() ? null : text;
	}

	/** A copy to write, or absent for an empty map. */
	static <K, V> Map<K, V> copyOrNull(Map<K, V> map)
	{
		return map.isEmpty() ? null : new HashMap<>(map);
	}

	static Map<String, Integer> trimCounters(Map<String, Integer> counters)
	{
		// Today's counters are for today. Writing them out would have the
		// follower's summary open with yesterday's afternoon still in it.
		Map<String, Integer> lasting = new LinkedHashMap<>();
		counters.forEach((key, value) ->
		{
			if (!key.endsWith(TODAY))
				lasting.put(key, value);
		});
		counters = lasting;

		if (counters.size() <= MAX_COUNTERS)
			return counters;
		return counters.entrySet().stream()
			.sorted(Map.Entry.<String, Integer>comparingByValue().reversed())
			.limit(MAX_COUNTERS)
			.collect(java.util.stream.Collectors.toMap(
				Map.Entry::getKey, Map.Entry::getValue,
				(a, b) -> a, LinkedHashMap::new));
	}
}

package com.follower;

import java.util.*;
import java.util.Map;
import lombok.*;
import java.util.Set;
import static com.follower.TriggerEvent.Type.*;

/**
 * One thing that happened, handed to {@link SpeechEngine}. A synthetic
 * {@link Type#TICK} event is raised every game tick so that purely state-based
 * rules (low HP, low prayer) get a chance to fire.
 */
@RequiredArgsConstructor
@Getter
class TriggerEvent
{
	enum Type
	{
		TICK,
		NPC_SPAWN,
		NPC_DESPAWN,
		CHAT,
		VARBIT,
		ANIMATION,
		LEVEL_UP,
		REGION_CHANGE,
		LOGIN,
		DAMAGE_TAKEN,
		EQUIPMENT_CHANGE,
		THRALL_START,
		THRALL_SWITCH,
		THRALL_END,
		ERRAND_START,
		ERRAND_END,
		COMBAT_START,
		COMBAT_END,
		THIEVING_START,
		THIEVING_END,
		NPC_KILL,
		PLAYER_DEATH,
		LOOT,
		RECORD,
		EXAMINED,
		WANT_FULFILLED,
		WANT_EXPIRED,
		ANSWERED,
		UNDERFOOT,
		MANUAL,
		WORLD_HOP,
		GAME_UPDATE,
		NOTES_EDITED,
		MUSIC_UNLOCK,
		COLLECTION_ADD,
		QUEST_COMPLETE,
		GE_OFFER,
		CHANNEL_JOIN,
		CHANNEL_LEAVE,
		NPC_SHOUT,
		TRACK_CHANGE,
		EXAMINED_THING,
		ATTENDED_AGAIN,
		MINUTES_TAKEN,
		XP_DROP,
		WORK_END,
		TARGET_DEPLETED,
		BAG_FULL,
		BAG_HALF,
		/** A boss kill count the game reported in chat. */
		KILL_COUNT,
		/** The logout tab opened. */
		FAREWELL,
		/** The follower noticed something and went to look. */
		NOTICED,
		/** A Send with a misgiving in it: the follower stopped at the edge first. */
		HESITATED,
		/** The player walked straight at the parked follower and it stepped aside. */
		STEPPED_ASIDE,
		/** The follower did an agility obstacle after the player. */
		CROSSED,
	}

	/**
	 * An XP drop landed. {skill} names it; {@code count} is how many the
	 * current work session has seen, this one included, so a rule can fire
	 * on every eighth the way npcKill fires on every fiftieth. Zero outside
	 * a session.
	 */
	static TriggerEvent xpDrop(String skill, int count)
	{
		var event = named(XP_DROP, "skill", skill).put("count", count);
		event.count = count;
		return event;
	}

	/**
	 * A work session ended. The name is the activity, for {@code names}
	 * lists; {activity} and {target} say what it was and on what.
	 */
	static TriggerEvent workEnd(String activity, String target)
	{
		return named(WORK_END, "activity", activity).put("target", target == null ? "" : target);
	}

	/** The thing being worked changed id or went. {target} names it. */
	static TriggerEvent targetDepleted(String target)
	{
		return named(TARGET_DEPLETED, "target", target);
	}

	/**
	 * The PLAYER examined something - the reverse direction of
	 * {@link Type#EXAMINED}, which is somebody examining the follower.
	 * {target} names what was looked at.
	 */
	static TriggerEvent examinedThing(String target)
	{
		return named(EXAMINED_THING, "target", target);
	}

	/**
	 * As {@link #examinedThing}, for a creature, or anything else standing in
	 * the scene: {target} is a common noun after "the" or "this" - the guard,
	 * this statue (text QA5: "this Statue", "One more Crate").
	 */
	static TriggerEvent examinedCreature(String target)
	{
		var event = examinedThing(target);
		event.creatures.add("target");
		return event;
	}

	/**
	 * The game's music changed to another track - the local song, as against
	 * {@link Type#MUSIC_UNLOCK}, which is hearing one for the first time ever.
	 */
	static TriggerEvent trackChange(String track)
	{
		return named(TRACK_CHANGE, "track", track);
	}

	/** A world hop landed. {world} is the number on the new door. */
	static TriggerEvent worldHop(int world)
	{
		var event = new TriggerEvent(WORLD_HOP).put("world", world);
		event.value = world;
		return event;
	}

	/** A music track just unlocked. {track} names it for the catalogue. */
	static TriggerEvent musicUnlock(String track)
	{
		return named(MUSIC_UNLOCK, "track", track);
	}

	/** The other ledger gained a line. {item} is what went in it. */
	static TriggerEvent collectionAdd(String item)
	{
		return named(COLLECTION_ADD, "item", item);
	}

	/** A quest reward scroll was handed over. {quest} names the quest. */
	static TriggerEvent questComplete(String quest)
	{
		return named(QUEST_COMPLETE, "quest", quest);
	}

	/**
	 * A Grand Exchange offer finished. The name carries "bought" or "sold"
	 * for the condition's {@code is}; {item} and {value} land as placeholders
	 * so the line can read like a clerk's telegram rather than a receipt.
	 */
	static TriggerEvent geOffer(boolean bought, String item, long spent)
	{
		var event = new TriggerEvent(GE_OFFER).put("item", item == null ? "" : item)
			.put("value", formatGp(spent));
		event.name = bought ? "bought" : "sold";
		return event;
	}

	/** Somebody arrived in or left the player's chat channel. {name} says who. */
	static TriggerEvent channel(Type type, String who)
	{
		return named(type, "name", who);
	}

	/**
	 * A named NPC said something overhead. The name matches like npcSpawn's,
	 * the message like chatMessage's, and both land as placeholders - NPC
	 * overheads never reach the chatbox, so no chat rule can see these.
	 */
	static TriggerEvent npcShout(String npc, String message)
	{
		return named(NPC_SHOUT, "npc", npc).message("message", message);
	}

	/**
	 * The player answered a question, by picking a branch in the conversation
	 * the follower opened. {@code yes} or {@code no}, and never anything else -
	 * an option cannot be misheard the way a typed word could.
	 */
	static TriggerEvent answered(String answer)
	{
		return answered(answer, "");
	}

	/** The same, naming the tree that was answered, for a rule's {@code of}. */
	static TriggerEvent answered(String answer, String tree)
	{
		var event = named(ANSWERED, "answer", answer);
		event.message = tree == null ? "" : tree;
		return event;
	}

	/** A want got its answer, one way or the other. {want} names what it was. */
	static TriggerEvent want(Type type, String label)
	{
		return named(type, "want", label);
	}

	/**
	 * A personal best was just beaten. {record} names it, {value} is the new
	 * mark and {previous} the one it replaced - which is what makes the line
	 * land, since a record without the old number is just a number.
	 */
	static TriggerEvent record(String what, int value, int previous)
	{
		var event = named(RECORD, "record", what).put("value", value).put("previous", previous);
		event.value = value;
		return event;
	}

	/** The player has died. Where it happened lives in the context, not here. */
	static TriggerEvent death()
	{
		return new TriggerEvent(PLAYER_DEATH);
	}

	/**
	 * Loot arrived. {@code value} carries the total for {@code lootWorth}
	 * conditions; {item} and {value} land as placeholders so a line can name
	 * the prize without quoting a raw number.
	 */
	static TriggerEvent loot(int totalValue, String bestItem)
	{
		var event = named(LOOT, "item", bestItem).put("value", formatGp(totalValue));
		event.value = totalValue;
		return event;
	}

	/** 1.5B / 1.2M / 3M / 214K / 950 - the way a player says an amount, not a ledger. */
	static String formatGp(long value)
	{
		if (value >= 999_950_000L)
			return tenths(value, 1_000_000_000L) + "B";
		if (value >= 1_000_000)
			return tenths(value, 1_000_000) + "M";
		if (value >= 10_000)
			return (value / 1_000) + "K";
		return Long.toString(value);
	}

	/** The amount in units to one decimal place, a round one without its ".0": 1.5, 3. */
	static String tenths(long value, long unit)
	{
		long tenths = Math.round(value * 10.0 / unit);
		return tenths % 10 == 0 ? Long.toString(tenths / 10) : (tenths / 10) + "." + (tenths % 10);
	}

	/**
	 * A fight starting or ending, with what is being fought in {npc} so a line
	 * can name it.
	 */
	static TriggerEvent combat(Type type, String npcName)
	{
		var event = named(type, "npc", npcName);
		event.creatures.add("npc");
		return event;
	}

	/**
	 * Something the PLAYER killed. {@code value} carries the combat level, which
	 * is how {@code npcKill} tells a boss from a rat; the name lands in {npc}.
	 *
	 * <p>Only raised for kills the player had a hand in - see the hitsplat
	 * attribution in the plugin - so a follower does not applaud a guard losing
	 * a fight with a dog on the other side of the street.
	 */
	static TriggerEvent kill(int npcId, String npcName, int combatLevel)
	{
		return kill(npcId, npcName, combatLevel, 0);
	}

	/**
	 * @param count how many of this NPC have been killed this session, which
	 * rides along so a rule can fire on the fiftieth and say which one it was
	 */
	static TriggerEvent kill(int npcId, String npcName, int combatLevel, int count)
	{
		var event = npc(NPC_KILL, npcId, npcName).put("level", combatLevel).put("count", count);
		event.value = combatLevel;
		event.count = count;
		return event;
	}

	/** Thrall-mode transitions; {@code style} lands in the {style} placeholder. */
	static TriggerEvent thrall(Type type, String style)
	{
		return named(type, "style", style);
	}

	/**
	 * A resummon while already possessed: {@code style} is the new thrall
	 * type, {@code from} the one being left behind.
	 */
	static TriggerEvent thrallSwitch(String from, String style)
	{
		return thrall(THRALL_SWITCH, style).put("from", from == null ? "" : from);
	}

	/** Errand transitions; the errand's name matches rule {@code names} lists. */
	static TriggerEvent errand(Type type, String errand)
	{
		return named(type, "errand", errand);
	}

	final Type type;
	final Map<String, String> placeholders = new HashMap<>();

	/** The placeholders that hold a creature's name, which reads lower case after an article. */
	final Set<String> creatures = new java.util.HashSet<>();

	/** Generic payload; meaning depends on {@link #type}. */
	String name = "";
	int id = -1,
		value;

	/** How many times this has happened before, where the raiser counts. */
	int count;
	/** The level-up's wider ledger: the total and the base, before and after. */
	int total,
		previousTotal,
		base,
		previousBase;
	/** Milliseconds since the last level in this skill, or -1 for none known. */
	long sinceMs = -1;
	String message = "";
	int chatTypeId = -1;

	/** An event about one thing by name, said by the placeholder {@code key}. */
	static TriggerEvent named(Type type, String key, String name)
	{
		var event = new TriggerEvent(type);
		event.name = name == null ? "" : name;
		event.placeholders.put(key, event.name);
		return event;
	}

	/** Sets the message, said by the placeholder {@code key}. */
	TriggerEvent message(String key, String text)
	{
		message = text == null ? "" : text;
		placeholders.put(key, message);
		return this;
	}

	/** Adds a placeholder; a number is written in digits. */
	TriggerEvent put(String key, Object value)
	{
		placeholders.put(key, String.valueOf(value));
		return this;
	}

	static TriggerEvent tick()
	{
		return new TriggerEvent(TICK);
	}

	static TriggerEvent npc(Type type, int npcId, String npcName)
	{
		var event = combat(type, npcName).put("npcId", npcId);
		event.id = npcId;
		return event;
	}

	/**
	 * Something was said. The sender rides along in {@link #getName()} so a rule
	 * can tell the player's own line from the rest of the street - which is the
	 * difference between a follower that answers you and one that answers
	 * everybody.
	 */
	static TriggerEvent chat(String message, int chatTypeId, String sender)
	{
		var event = named(CHAT, "speaker", sender).message("message", message);
		event.chatTypeId = chatTypeId;
		return event;
	}

	static TriggerEvent varbit(int varbitId, int newValue, int oldValue)
	{
		var event = new TriggerEvent(VARBIT).put("value", newValue);
		event.id = varbitId;
		event.value = newValue;
		return event;
	}

	static TriggerEvent animation(int animationId)
	{
		var event = new TriggerEvent(ANIMATION);
		event.id = animationId;
		return event;
	}

	static TriggerEvent levelUp(String skill, int level)
	{
		return levelUp(skill, level, 0, 0, 0, 0, 0, -1, -1);
	}

	/**
	 * A level, with everything a milestone rule wants to know beside the
	 * number: the total level before and after, the lowest skill before and
	 * after, how many skills are at ninety-nine now (this one included, if
	 * it is), and how long it has been - since the last level in this
	 * skill, and since the last level at all. Either gap is -1 when the
	 * follower has no record to measure from.
	 *
	 * <p>{skill}, {level}, {total}, {base}, {nines}, {ninesOrdinal},
	 * {sinceLast} and {sinceAny}. The two gaps are empty strings rather
	 * than a number when unknown, so a rule that prints them guards with
	 * levelGap.
	 */
	static TriggerEvent levelUp(String skill, int level, int total, int previousTotal,
		int base, int previousBase, int masteries, long sinceLastMs, long sinceAnyMs)
	{
		var event = named(LEVEL_UP, "skill", skill).put("level", level).put("total", total)
			.put("base", base).put("nines", Words.number(masteries)).put("ninesOrdinal", Words.ordinal(masteries))
			.put("sinceLast", sinceLastMs < 0 ? "" : Words.duration(sinceLastMs))
			.put("sinceAny", sinceAnyMs < 0 ? "" : Words.duration(sinceAnyMs));
		event.value = level;
		event.total = total;
		event.previousTotal = previousTotal;
		event.base = base;
		event.previousBase = previousBase;
		event.count = masteries;
		event.sinceMs = sinceLastMs;
		return event;
	}

	/**
	 * The follower noticed something the player had not, and set off to look
	 * at it. {kind} is what sort of thing (valuable, nest, impling, star,
	 * landmark) and {thing} names it.
	 */
	static TriggerEvent noticed(String kind, String thing)
	{
		var event = named(NOTICED, "kind", kind).message("thing", thing);
		// A landmark's name is a common noun after "this": text QA5, 17 Oct,
		// "the wording of this Statue". An item keeps the game's spelling.
		if ("landmark".equals(event.name))
			event.creatures.add("thing");
		return event;
	}

	/**
	 * Sent somewhere with a misgiving about it. {misgiving} is the kind
	 * (wilderness, monster) and {thing} what it is about: "the Wilderness",
	 * or the monster's name.
	 */
	static TriggerEvent hesitated(String misgiving, String thing)
	{
		var event = named(HESITATED, "misgiving", misgiving).message("thing", thing);
		if ("monster".equals(event.name))
			event.creatures.add("thing");
		return event;
	}

	/**
	 * The game said what the kill count is. {boss} names it, {count} is
	 * the number, {ordinal} says it ("forty-first"), and {lastCount} is the
	 * highest count the follower had seen before - zero for a boss it has
	 * never heard the number for.
	 */
	static TriggerEvent killCount(String boss, int count, int lastCount)
	{
		var event = named(KILL_COUNT, "boss", boss).put("count", count)
			.put("ordinal", Words.ordinal(count)).put("lastCount", lastCount);
		event.count = count;
		event.value = count;
		return event;
	}

	static TriggerEvent regionChange(int newRegion, int oldRegion)
	{
		var event = new TriggerEvent(REGION_CHANGE).put("region", newRegion);
		event.id = newRegion;
		event.value = newRegion;
		return event;
	}

	/**
	 * The follower has done an agility obstacle or shortcut after the player.
	 * The name is "fell" where the player fell, and so the follower with
	 * them, and "crossed" otherwise.
	 */
	static TriggerEvent crossed(boolean fell)
	{
		var event = new TriggerEvent(CROSSED);
		event.name = fell ? "fell" : "crossed";
		return event;
	}


	static TriggerEvent damageTaken(int amount)
	{
		var event = new TriggerEvent(DAMAGE_TAKEN).put("damage", amount);
		event.value = amount;
		return event;
	}

	static TriggerEvent simple(Type type)
	{
		return new TriggerEvent(type);
	}

	Set<String> getCreatureKeys()
	{
		return creatures;
	}
}

package com.follower;

import java.awt.*;
import java.awt.Color;
import java.awt.Component;
import java.awt.Rectangle;
import javax.swing.*;
import javax.swing.event.*;
import net.runelite.client.ui.*;

/**
 * The few component recipes the sidebar panel and the three windows all
 * repeat: small grey text, dark panels and columns, wrapped HTML labels, a
 * vertical-only scroller and a document listener that just runs something.
 */
class Ui
{

	/** The component in RuneLite's small font, in the given colour. */
	static <T extends JComponent> T small(T component, Color colour)
	{
		component.setFont(FontManager.getRunescapeSmallFont());
		component.setForeground(colour);
		return component;
	}

	/** A small-font label. */
	static JLabel label(String text, Color colour)
	{
		return small(new JLabel(text), colour);
	}

	/** A panel on the dark grey every window here is painted in. */
	static JPanel panel(LayoutManager layout)
	{
		var panel = new JPanel(layout);
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		return panel;
	}

	/** A dark vertical box that sits flush left in its parent column. */
	static JPanel column()
	{
		return column(new JPanel());
	}

	static JPanel column(JPanel panel)
	{
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	/**
	 * Text that wraps at {@code width}, in the HTML renderer's px (x1.3 on
	 * screen). A label's preferred width is otherwise one unwrapped line, and
	 * one wide child pushes a whole column past its edge.
	 */
	static String html(int width, String text)
	{
		return "<html><body style='width:" + width + "px'>" + escape(text) + "</body></html>";
	}

	/** Cache and file text must not be able to inject markup. */
	static String escape(String text)
	{
		return text == null ? "" : text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Scrolls up and down only, borderless, at a usable wheel speed. */
	static JScrollPane scroller(Component view)
	{
		var scroll = new JScrollPane(view,
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		return scroll;
	}

	/** Lays the component out again after its children changed, and repaints it. */
	static void relayout(JComponent component)
	{
		component.revalidate();
		component.repaint();
	}

	/** Runs the action on every edit of a document. */
	static DocumentListener onChange(Runnable action)
	{
		return new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				action.run();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				action.run();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				action.run();
			}
		};
	}

	/**
	 * A scroll view that is always exactly as wide as its viewport, whatever
	 * the viewport is once the vertical scrollbar takes its share. A wide child
	 * is squeezed to fit instead of pushing the content past the right edge,
	 * where a view that never scrolls sideways would leave it unreachable.
	 */
	static class WidthTrackingPanel extends JPanel implements Scrollable
	{
		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction)
		{
			return orientation == SwingConstants.VERTICAL ? visible.height : visible.width;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package com.follower;

import java.util.*;
import java.util.Set;
import java.util.function.*;
import java.util.function.Consumer;
import net.runelite.api.*;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import lombok.RequiredArgsConstructor;

/**
 * A will of its own, aimed at the player.
 *
 * <p>The companions people love are the ones that are not quite puppets:
 * the Fable II dog that "you don't control, which makes him feel real",
 * Trico's beat of reluctance before it does what it is asked, Agro not
 * turning on a dime. And Ellie, who was given the right not to move out of
 * the player's way until the last second - "with a vocalization admonishing
 * the player for encroaching on her personal space" - which the studio
 * credits with making players respect her. None of it is refusal. A
 * companion that refuses is an escort quest; this is the beat before yes.
 *
 * <p>Two things live here. A Send with a misgiving in it - across the
 * Wilderness ditch, or to a spot beside something that could kill the
 * follower - is walked to its edge first, where the follower turns to look
 * at the player for a couple of ticks and says so, and then goes on if it
 * can. And a parked follower that the player walks straight at steps aside
 * at the last tick, not before, with a word about it.
 */
@RequiredArgsConstructor
class Will
{
	/** What the follower has misgivings about. */
	@RequiredArgsConstructor
	enum Misgiving
	{
		/** The other side of the ditch. */
		WILDERNESS("wilderness"),
		/** Something beside the spot that outclasses the player by a margin. */
		MONSTER("monster");

		final String key;
	}

	/** Ticks the follower stands at the edge, looking back, before going on. */
	static final int HESITATE_TICKS = 3;

	/** The ditch's own two rows; the edge is the row south of them. */
	static final int DITCH_SOUTH_Y = 3519;

	final Client client;
	final FollowerEntity follower;
	final Consumer<TriggerEvent> events;
	/** Whether the follower's park is its own, or the player's: a wander, a Stay. */
	final BooleanSupplier parkedPlainly;

	/** The Send under way with a misgiving: where it was asked to go, and the pause. */
	WorldPoint pending;
	Misgiving misgiving;
	int goOnAt;
	final Set<String> hesitatedAt = new HashSet<>();

	WorldPoint lastPlayerTile;
	int steppedAsideAt = -1000;

	// ------------------------------------------------------------- the send

	/**
	 * The player sent the follower somewhere. With no misgiving it simply
	 * goes; with one, it goes to the edge, turns to the player, and the
	 * rules hear of it.
	 *
	 * @return false when nothing near the target is reachable at all, as
	 * {@link FollowerEntity#stayAt} would say
	 */
	boolean send(WorldPoint target)
	{
		pending = null;
		misgiving = null;
		// A tile with a fire on it, or a booth or table in it that the map
		// calls open floor: the player means over there, not into that, so
		// the Send lands beside it rather than being refused.
		target = beside(target);
		var from = follower.getWorldLocation();
		var local = client.getLocalPlayer();
		var here = local == null ? null : local.getWorldLocation();
		if (target == null || from == null || here == null)
			return follower.stayAt(target);
		Misgiving about = null;
		WorldPoint edge = null;
		String thing = "",
			key = null;
		if (isWilderness(target) && !isWilderness(here) && !isWilderness(from))
		{
			about = Misgiving.WILDERNESS;
			edge = new WorldPoint(target.getX(), Math.min(target.getY(), DITCH_SOUTH_Y), target.getPlane());
			thing = "the Wilderness";
			key = "wilderness";
		}
		else
		{
			var monster = monsterBeside(target, local);
			// A monster with no name gives the line nothing to say: "Next to
			// the that?" So it simply goes.
			if (monster != null && monster.getName() != null)
			{
				about = Misgiving.MONSTER;
				// MONSTER_EDGE: The edge it stops at, short of a monster.
				edge = edgeShortOf(target, from, 3 /* MONSTER_EDGE */);
				thing = monster.getName();
				key = "monster:" + monster.getIndex();
			}
		}
		if (about == null || edge == null || hesitatedAt.contains(key)
			|| !follower.stayAt(edge))
			return follower.stayAt(target);
		hesitatedAt.add(key);
		pending = target;
		misgiving = about;
		follower.setStayFaceTile(here);
		goOnAt = client.getTickCount() + from.distanceTo(edge) + HESITATE_TICKS;
		events.accept(TriggerEvent.hesitated(about.key, thing));
		return true;
	}

	/**
	 * The tile itself when the follower would stand on it, and the nearest
	 * tile round it that it would when it would not. Unchanged when there
	 * is nowhere better: refusing outright is the caller's business.
	 */
	WorldPoint beside(WorldPoint target)
	{
		var from = follower.getWorldLocation();
		if (target == null || (follower.goodGround(target) && !follower.furnished(target)))
			return target;
		var best = target;
		int nearest = Integer.MAX_VALUE;
		for (var spot : SkillingController.ring(target, target, 1, target.getPlane()))
		{
			int away = from == null ? 0 : spot.distanceTo(from);
			if (follower.goodGround(spot) && !follower.furnished(spot) && away < nearest)
			{
				nearest = away;
				best = spot;
			}
		}
		return best;
	}

	/** Whether the tile is on the surface Wilderness's side of the ditch. */
	static boolean isWilderness(WorldPoint tile)
	{
		return tile != null && tile.getPlane() == 0
			// WILDERNESS_MIN_X: The surface Wilderness: north of the ditch, between the walls.
			&& tile.getX() >= 2944 /* WILDERNESS_MIN_X */ && tile.getX() < 3392 /* WILDERNESS_MAX_X */
			&& tile.getY() >= 3520 /* WILDERNESS_MIN_Y */ && tile.getY() < 4000 /* WILDERNESS_MAX_Y */;
	}

	/**
	 * An NPC beside the target that outclasses the player, or null; with
	 * {@code anyLevel}, any NPC beside it, as the force-path asks.
	 */
	NPC monsterBeside(WorldPoint target, Player local)
	{
		var view = client.getTopLevelWorldView();
		if (view == null || local == null)
			return null;
		int level = local.getCombatLevel();
		for (var npc : view.npcs())
		{
			var at = npc == null ? null : npc.getWorldLocation();
			// Another floor is infinitely far, as distanceTo has it.
			if (at == null || npc == local.getInteracting()
				// MONSTER_MARGIN: A monster is one this much above the player's combat level, this close to the spot.
				|| npc.getCombatLevel() < level + 20 /* MONSTER_MARGIN */
				|| at.distanceTo(target) > 2 /* MONSTER_WITHIN */)
				continue;
			return npc;
		}
		return null;
	}

	/**
	 * A tile so many steps short of the target, on the follower's side: the
	 * ring at that distance, nearest the follower, straightest first.
	 */
	static WorldPoint edgeShortOf(WorldPoint target, WorldPoint from, int steps)
	{
		if (from.distanceTo(target) <= steps)
			return null;
		WorldPoint best = null;
		long bestScore = Long.MAX_VALUE;
		for (var spot : SkillingController.ring(target, target, steps, target.getPlane()))
		{
			long ddx = spot.getX() - from.getX(),
				ddy = spot.getY() - from.getY(),
				score = spot.distanceTo(from) * 1_000_000L + ddx * ddx + ddy * ddy;
			if (score < bestScore)
			{
				bestScore = score;
				best = spot;
			}
		}
		return best;
	}

	/** Whether a Send is paused at its edge. */
	boolean isHesitating()
	{
		return pending != null;
	}

	/**
	 * Where the Send just given ends: the spot itself past a monster, which
	 * the pause at the edge only delays, and the edge at the ditch, which it
	 * does not go on from.
	 */
	WorldPoint endsAt()
	{
		return pending != null && misgiving == Misgiving.MONSTER ? pending : follower.getStayTile();
	}

	// ------------------------------------------------------------- the tick

	/** Call once per game tick, on the client thread. */
	void tick()
	{
		int now = client.getTickCount();
		var here = FollowerEntity.playerTile(client);
		if (pending != null)
		{
			if (!follower.isStaying())
			{
				// Released by something else - a Follow, a leash snap.
				pending = null;
				misgiving = null;
			}
			else if (now >= goOnAt)
			{
				var target = pending;
				var about = misgiving;
				pending = null;
				misgiving = null;
				follower.setStayFaceTile(null);
				if (about == Misgiving.MONSTER)
					// The beat is over; it goes, not hurrying.
					follower.stayAt(target);
				// Across the ditch there is no going on: it waits at the edge.
			}
		}
		stepAsideIfWalkedAt(now, here);
		lastPlayerTile = here;
	}

	/**
	 * The player walking straight at a parked follower. Not preemptively:
	 * only when their next step would land on it, the same as a friend who
	 * was standing there first. One tile to the side, and a word.
	 */
	void stepAsideIfWalkedAt(int now, WorldPoint here)
	{
		var tile = follower.getWorldLocation();
		if (here == null || lastPlayerTile == null || tile == null || !follower.isStaying()
			|| !parkedPlainly.getAsBoolean() || !follower.isSettled()
			|| here.getPlane() != tile.getPlane() || here.equals(lastPlayerTile)
			// STEP_ASIDE_COOLDOWN_TICKS: Not two steps aside inside this many ticks.
			|| now - steppedAsideAt < 20 /* STEP_ASIDE_COOLDOWN_TICKS */)
			return;
		int vx = Integer.signum(here.getX() - lastPlayerTile.getX()),
			vy = Integer.signum(here.getY() - lastPlayerTile.getY());
		boolean running = lastPlayerTile.distanceTo(here) >= 2;
		WorldPoint next = here.dx(vx).dy(vy),
			after = here.dx(2 * vx).dy(2 * vy);
		if (!tile.equals(next) && !(running && tile.equals(after)))
			return;
		// The two tiles to either side of the line they are walking, then
		// the one behind the follower along it.
		WorldPoint[] aside = {
			tile.dx(-vy).dy(vx),
			tile.dx(vy).dy(-vx),
			tile.dx(vx).dy(vy),
		};
		for (var spot : aside)
		{
			if (follower.standable(spot) && follower.canStep(tile, spot.getX() - tile.getX(),
				spot.getY() - tile.getY()) && follower.stayAt(spot))
			{
				steppedAsideAt = now;
				events.accept(TriggerEvent.simple(TriggerEvent.Type.STEPPED_ASIDE));
				return;
			}
		}
	}

	/** Logout, hop: the scene and the Send with it. */
	void reset()
	{
		pending = null;
		misgiving = null;
		hesitatedAt.clear();
		lastPlayerTile = null;
		steppedAsideAt = -1000;
	}
}

package com.follower;

import java.util.*;
import java.util.Set;

/**
 * Numbers the way a scribe writes them in a sentence.
 *
 * <p>A line that says "41 Vorkath" is a counter with a face; one that says
 * "your forty-first Vorkath" is somebody keeping count. The same goes for
 * time: "eleven days since the last one" is a memory, "15840 minutes" is a
 * log. Everything here is words up to where words stop reading naturally,
 * and digits after.
 */
class Words
{
	static final String[] ONES = Resources.list("ones");

	static final String[] TENS = Resources.list("tens");

	static final String[] ORDINAL_ONES = Resources.list("ordinalOnes");

	static final String[] ORDINAL_TENS = Resources.list("ordinalTens");

	/** Vowel letters said with a consonant: a unicorn, a one-eyed rat, a useful thing. */
	static final String[] SAID_WITH_A = Resources.list("saidWithA");

	/** And the h that is not said: an hour, an honest mistake. */
	static final String[] SAID_WITH_AN = Resources.list("saidWithAn");

	/** Things had by the heap, not the piece: soft clay, never a soft clay. */
	static final Set<String> HEAPS = Resources.words("heaps");

	/** Endings of words that end in s and still mean one: Cerberus, a Nylocas Hagios, a Cyclops. */
	static final String[] ONE_DESPITE_THE_S = Resources.list("oneDespiteTheS");

	/**
	 * Bosses whose name is who they are, not what: Vorkath, never the
	 * Vorkath. The Corporeal Beast and the Leviathan are kinds of thing,
	 * and keep their article.
	 */
	static final Set<String> PERSONAL_NAMES = Resources.words("personalNames");


	/** Whether the name is a boss's own name, which takes no article: Vorkath, General Graardor. */
	static boolean isPersonalName(String name)
	{
		return name != null && PERSONAL_NAMES.contains(name.trim().toLowerCase(Locale.ROOT));
	}

	/** One to ninety-nine in words; anything else as digits. */
	static String number(int n)
	{
		if (n < 0 || n >= 100)
			return Integer.toString(n);
		if (n < 20)
			return ONES[n];
		return n % 10 == 0 ? TENS[n / 10] : TENS[n / 10] + "-" + ONES[n % 10];
	}

	/**
	 * "first", "forty-first", and "101st" past where the words stop. A
	 * hundredth or a thousandth is worth its word, being the kind of count
	 * that gets said out loud.
	 */
	static String ordinal(int n)
	{
		if (n < 0)
			return Integer.toString(n);
		if (n < 20)
			return ORDINAL_ONES[n];
		if (n < 100)
			return n % 10 == 0 ? ORDINAL_TENS[n / 10] : TENS[n / 10] + "-" + ORDINAL_ONES[n % 10];
		if (n == 100)
			return "hundredth";
		if (n == 1000)
			return "thousandth";
		int last = n % 100;
		String suffix = "th";
		if (last < 11 || last > 13)
		{
			switch (n % 10)
			{
				case 1:
					suffix = "st";
					break;
				case 2:
					suffix = "nd";
					break;
				case 3:
					suffix = "rd";
					break;
				default:
					break;
			}
		}
		return n + suffix;
	}

	/**
	 * A stretch of time as somebody would say it: "a minute", "forty
	 * minutes", "an hour", "eleven days", "three weeks", "a year". Never more
	 * precise than the unit it picks, because "eleven days" is the memory and
	 * "eleven days and four hours" is the log.
	 */
	static String duration(long ms)
	{
		long minutes = Math.max(0, ms) / 60_000L;
		if (minutes < 2)
			return "a minute";
		if (minutes < 60)
			return number((int) minutes) + " minutes";
		long hours = minutes / 60;
		if (hours < 2)
			return "an hour";
		if (hours < 36)
			return number((int) hours) + " hours";
		long days = hours / 24;
		if (days < 2)
			return "a day";
		if (days < 14)
			return number((int) days) + " days";
		if (days < 56)
			return number((int) (days / 7)) + " weeks";
		if (days < 365)
		{
			long months = days / 30;
			return months < 2 ? "a month" : number((int) months) + " months";
		}
		long years = days / 365;
		return years < 2 ? "a year" : number((int) years) + " years";
	}

	/**
	 * "a" or "an", by how the name sounds said aloud: an Eclectic impling, a
	 * unicorn, an hour, an 80, an 18. The vowel letters and a few known
	 * exceptions, not a pronouncing dictionary.
	 */
	static String article(String name)
	{
		String s = name.trim().toLowerCase(Locale.ROOT);
		if (s.isEmpty())
			return "a";
		char first = s.charAt(0);
		if (Character.isDigit(first))
		{
			String digits = s.replaceAll("\\D.*", "");
			return first == '8' || digits.equals("11") || digits.equals("18") ? "an" : "a";
		}
		for (String h : SAID_WITH_AN)
		{
			if (s.startsWith(h))
				return "an";
		}
		if ("aeiou".indexOf(first) < 0)
			return "a";
		for (String y : SAID_WITH_A)
		{
			if (s.startsWith(y))
				return "a";
		}
		return "an";
	}

	/**
	 * A creature's name as the middle of a sentence has it: the guard, a
	 * goblin, a monk of Zamorak. The game capitalises every name's first
	 * letter; one shaped like a plain noun, a capital to open it and none
	 * after until any "of", gives it up. One with more capitals is a name in
	 * its own right and keeps them: Hill Giant, King Black Dragon, TzHaar-Ket.
	 */
	static String asCommonNoun(String name)
	{
		if (name == null || name.length() < 2 || !Character.isUpperCase(name.charAt(0)))
			return name;
		String head = name.replaceAll("\\s*\\(.*\\)$", "");
		int of = head.indexOf(" of ");
		if (of > 0)
			head = head.substring(0, of);
		for (int i = 1; i < head.length(); i++)
		{
			if (Character.isUpperCase(head.charAt(i)))
				return name;
		}
		return Character.toLowerCase(name.charAt(0)) + name.substring(1);
	}

	/**
	 * Whether the name takes no "a" at all: Coins, Dragon bones, soft clay,
	 * The Leviathan. Judged on the head word - the one before "of" when there
	 * is one, so a Jar of souls keeps its article - with a trailing "(e)"
	 * ignored. A word ending in s is plural unless its ending says otherwise,
	 * which keeps Cerberus, Venenatis, the Nylocas and a Cyclops singular.
	 */
	static boolean takesNoArticle(String name)
	{
		String s = name.trim().toLowerCase(Locale.ROOT);
		if (s.startsWith("the "))
			return true;
		s = s.replaceAll("\\s*\\(.*\\)$", "");
		int of = s.indexOf(" of ");
		if (of > 0)
			s = s.substring(0, of);
		String head = s.substring(s.lastIndexOf(' ') + 1);
		if (HEAPS.contains(head))
			return true;
		if (!head.endsWith("s"))
			return false;
		for (String one : ONE_DESPITE_THE_S)
		{
			if (head.endsWith(one))
				return false;
		}
		return true;
	}
}

package com.follower;

import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import lombok.Getter;

/**
 * One stretch of the player working a thing: what they clicked, where it
 * stands, when it began and how the experience has been coming in.
 *
 * <p>Three signals make one of these. The click is the earliest and the most
 * honest - it names the target before a single swing - and the repeating
 * animation and the XP drops are the proof that the click turned into work.
 * {@link SkillingController} opens a session on the first proof after a
 * click and closes it by the rules in the spec; everything the company does
 * during a session reads from here.
 */
@Getter
class WorkSession
{
	/** The option word that started it, tags stripped: "Chop down", "Mine". */
	final String option;

	/**
	 * A guess at the skill, as the lowercased skill name ("woodcutting"), or
	 * empty while nothing has said. The option word makes the first guess and
	 * the first XP drop corrects it, since a "Use" click could be anything.
	 */
	String activity;

	String targetName;
	int targetId;

	/** The footprint's south-west tile; the seat and the events key on it. */
	WorldPoint targetTile,
		targetMax;

	/** The interacted NPC, for a fishing spot; null for scenery. */
	NPC targetNpc;

	/**
	 * Work with nothing in the world to click - fletching, herblore, gems -
	 * opened by its first XP drop rather than a click. The target is the tile
	 * in front of the player, so the seat has something to stand off, and no
	 * object event can deplete it.
	 */
	boolean standing;

	final int startTick;

	/**
	 * The tick this particular target was clicked: the session's start, or
	 * the shift to the next tree. How long a target has been worked decides
	 * whether its going is a fall or a twig.
	 */
	int targetSinceTick;

	/** Where the player stood when the work began; walking off ends it. */
	WorldPoint workSpot;

	/**
	 * Between a click on a moved spot and the swing at it: the player is on
	 * their way, so their walk is not a walk-off and the seat waits.
	 */
	boolean settling;

	int xpDrops,
		lastDropTick = -1;

	/** The last tick that showed work: an animation, or a drop. */
	int lastEvidenceTick;

	/** The last animation the player played during it, or -1. */
	int lastAnimation = -1;

	/**
	 * The last LOOPING animation seen: the work itself, which the follower
	 * holds when it works alongside. Not {@link #lastAnimation}, which is
	 * whatever the player played last - a bite to eat, a special attack.
	 */
	int workPose;

	/** The target has changed id or gone, and that has been said once. */
	boolean depleted;

	/** Where a same-name spawn turned up after the target went, or null. */
	WorldPoint newSpot;

	WorkSession(String option, String activity, String targetName, int targetId,
		WorldPoint targetTile, WorldPoint targetMax, NPC targetNpc, WorldPoint workSpot,
		int startTick)
	{
		this.option = option;
		this.activity = activity == null ? "" : activity;
		this.targetName = targetName == null ? "" : targetName;
		this.targetId = targetId;
		this.targetTile = targetTile;
		this.targetMax = targetMax == null ? targetTile : targetMax;
		this.targetNpc = targetNpc;
		this.workSpot = workSpot;
		this.startTick = startTick;
		this.targetSinceTick = startTick;
		this.lastEvidenceTick = startTick;
	}
}

package com.follower;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.Model;

/**
 * An AnimationController that interpolates ACROSS the loop boundary.
 *
 * <p>The client's own smoothing glides every frame toward the next one - except
 * the last. RSSequenceDefinition sets {@code nextFrame = -1} when
 * {@code frame + 1} runs off the end ("the last frame is not interpolated"), so
 * the final frame of every looping animation is held statically for its full
 * duration and then snaps to the loop target. That hold is the skip. It exists
 * for real players too, but Jagex authors loops so the last pose sits close to
 * the first, which keeps it invisible on actors; the follower's poses showed it
 * plainly.
 *
 * <p>The fix: let the client do what it already does correctly - every frame
 * except the last - and take over only the final segment. Both endpoints of the
 * missing transition are obtainable as exact static poses
 * ({@code applyTransformations} with an unpacked frame index), so the wrap
 * becomes a vertex lerp between the true last pose and the true loop-target
 * pose, advanced by the same elapsed-tick clock the client uses. Adjacent
 * animation frames are small deltas, where a linear vertex blend and the
 * client's transform-level blend are visually indistinguishable.
 *
 * <p>Only active while animation smoothing accepts this animation id; with
 * smoothing off, nothing interpolates anywhere and the wrap is no different
 * from any other frame boundary.
 */
@Slf4j
class WrapLerpController extends AnimationController
{
	final Client client;

	/** Ticks elapsed within the current frame, approximated by observation. */
	int elapsedInFrame;

	/**
	 * Endpoint poses snapshotted as flat xyz arrays. applyTransformations returns a
	 * model backed by the client's shared animation scratch buffer - the same arrays
	 * every call, overwritten - so holding Model references meant all "endpoints"
	 * aliased one buffer. Copying the floats out immediately sidesteps that.
	 */
	float[] lastXyz,
		targetXyz;

	int cachedAnimationId = -1;

	/**
	 * Set when the render temp is not safe to write; the lerp disables rather than
	 * corrupt models, and the measured trim takes over. Leaving just that frame to
	 * the client would not do: the same last frame comes round every loop, and it
	 * would hold and snap each time with no trim to hide it.
	 */
	boolean unsafe;

	WrapLerpController(Client client, Animation animation)
	{
		super(client, animation);
		this.client = client;
	}

	@Override
	public void tick(int ticks)
	{
		int before = getFrame();
		super.tick(ticks);

		// Track progress within the frame by observation rather than mirroring the
		// stepping algorithm: external setFrame calls and onFinished handlers can
		// move the frame in ways a mirror would drift from. The reset loses the
		// consumed remainder (a tick or two of 20+), invisible in a lerp fraction.
		if (getFrame() != before)
			elapsedInFrame = 0;
		else
			elapsedInFrame += ticks;
	}

	@Override
	public Model animate(Model model, AnimationController other)
	{
		var animation = getAnimation();
		if (animation == null || other != null || unsafe
			|| animation.isMayaAnim() || !smoothingAccepts(animation))
			return super.animate(model, other);

		int[] lengths = animation.getFrameLengths();
		int frame = getFrame();
		if (lengths == null || lengths.length < 2 || frame != lengths.length - 1)
			return super.animate(model, other);

		ensureEndpoints(model, animation, lengths.length);
		if (lastXyz == null || targetXyz == null)
			return super.animate(model, other);

		// The blend is written into the model the base controller returns: the
		// client's shared per-frame temp, which the client itself hands straight to
		// the renderer for every animated frame. Never into the base, though - a
		// frame with no transform can come back as the base itself, or sharing its
		// vertex arrays, and writing there would bend the follower's model for good.
		var temp = super.animate(model, other);
		if (temp == null)
			return null;

		boolean separate = separate(temp, model);
		boolean sized = temp.getVerticesCount() * 3 == lastXyz.length
			&& lastXyz.length == targetXyz.length;
		if (!separate || !sized)
		{
			log.warn("Render temp is not safe to write (separate={}, sized={}); wrap interpolation disabled for this session", separate, sized);
			unsafe = true;
			lastXyz = null;
			targetXyz = null;
			return temp;
		}

		float t = Math.min(1f, elapsedInFrame / (float) Math.max(1, lengths[frame]));
		lerpInto(temp, lastXyz, targetXyz, t);
		return temp;
	}

	/** True when the safety guard has switched the lerp off for this session. */
	boolean isDisabled()
	{
		return unsafe;
	}

	boolean smoothingAccepts(Animation animation)
	{
		var filter = client.getAnimationInterpolationFilter();
		return filter != null && filter.test(animation.getId());
	}

	/**
	 * The frame the default loop lands on, replicating AnimationController.loop():
	 * step back frameStep from the end, falling back to 0 when out of range.
	 */
	int loopTargetFrame(Animation animation, int frames)
	{
		int target = frames - animation.getFrameStep();
		return target < 0 || target >= animation.getDuration() ? 0 : target;
	}

	void ensureEndpoints(Model base, Animation animation, int frames)
	{
		if (cachedAnimationId == animation.getId())
			return;
		cachedAnimationId = animation.getId();
		lastXyz = null;
		targetXyz = null;

		// Snapshot each endpoint IMMEDIATELY - the next applyTransformations call
		// (ours or any animating actor's) overwrites the shared scratch buffer.
		lastXyz = snapshot(client.applyTransformations(base, animation, frames - 1, null, 0));
		targetXyz = snapshot(client.applyTransformations(base, animation,
			loopTargetFrame(animation, frames), null, 0));
	}

	/**
	 * Whether the client's per-frame temp is its own model, safe to write:
	 * never the base, nor sharing its vertex arrays.
	 */
	static boolean separate(Model temp, Model model)
	{
		return temp != model
			&& temp.getVerticesX() != model.getVerticesX()
			&& temp.getVerticesY() != model.getVerticesY()
			&& temp.getVerticesZ() != model.getVerticesZ();
	}

	/** Flattens a posed model's vertices into an owned xyz array, or null. */
	static float[] snapshot(Model posed)
	{
		if (posed == null || posed.getVerticesX() == null)
			return null;
		float[] outXyz = new float[posed.getVerticesCount() * 3];
		float[][] xyz = {posed.getVerticesX(), posed.getVerticesY(), posed.getVerticesZ()};
		for (int i = 0; i < outXyz.length; i++)
			outXyz[i] = xyz[i % 3][i / 3];
		return outXyz;
	}

	/**
	 * Blends each vertex from one xyz snapshot toward another, or toward
	 * where the model already has it when {@code to} is null.
	 */
	static void lerpInto(Model dest, float[] from, float[] to, float t)
	{
		float[][] xyz = {dest.getVerticesX(), dest.getVerticesY(), dest.getVerticesZ()};
		for (int i = 0; i < dest.getVerticesCount() * 3; i++)
		{
			float a = from[i];
			xyz[i % 3][i / 3] = a + ((to == null ? xyz[i % 3][i / 3] : to[i]) - a) * t;
		}
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.Map;
import javax.inject.*;
import lombok.extern.slf4j.Slf4j;
import lombok.RequiredArgsConstructor;

/**
 * Persists the per-animation wrap trims.
 *
 * <p>Measured values are cheap to recompute but deterministic, so saving them just
 * avoids redoing the work each session. Hand-tuned overrides are the ones that
 * genuinely must survive a restart.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
class WrapTrimStore
{
	static final String FILE_NAME = "wrap-trims.json";

	static class Saved
	{
		Map<String, Integer> manual = new HashMap<>(),
			measured = new HashMap<>();
	}

	final Gson gson;
	Path file;

	void load(Path dataDir, FollowerEntity follower)
	{
		file = dataDir.resolve(FILE_NAME);
		if (!Files.isRegularFile(file))
			return;

		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			Saved saved = gson.fromJson(reader, Saved.class);

			if (saved != null)
				follower.restoreTrims(toIntKeys(saved.manual), toIntKeys(saved.measured));
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not read {}", file, e);
		}
	}

	void save(FollowerEntity follower)
	{
		if (file == null)
			return;

		var saved = new Saved();
		saved.manual = toStringKeys(follower.getWrapTrims());
		saved.measured = toStringKeys(follower.getMeasuredTrims());

		if (saved.manual.isEmpty() && saved.measured.isEmpty())
			return;

		try
		{
			Files.createDirectories(file.getParent());
			try (Writer writer = Files.newBufferedWriter(file, StandardCharsets.UTF_8))
			{
				gson.toJson(saved, writer);
			}
		}
		catch (IOException e)
		{
			log.warn("Could not write {}", file, e);
		}
	}

	static Map<String, Integer> toStringKeys(Map<Integer, Integer> source)
	{
		Map<String, Integer> out = new HashMap<>();
		for (var entry : source.entrySet())
			out.put(Integer.toString(entry.getKey()), entry.getValue());
		return out;
	}

	static Map<Integer, Integer> toIntKeys(Map<String, Integer> source)
	{
		Map<Integer, Integer> out = new HashMap<>();
		if (source == null)
			return out;
		for (var entry : source.entrySet())
		{
			try
			{
				out.put(Integer.parseInt(entry.getKey()), entry.getValue());
			}
			catch (NumberFormatException ignored)
			{
				// Skip malformed key.
			}
		}
		return out;
	}
}

package com.follower;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.Quest;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Enter the Abyss and Temple of the Eye walked stage by stage on the shipped
 * rules, at Occasional (6 s) and Minimal (45 s). Stage values from Quest
 * Helper (BSD), master 06da90f: EnterTheAbyss.java and TempleOfTheEye.java
 * loadSteps; end states from the cache's quest table (4 and 130).
 */
public class AbyssTempleWalksTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final long[] GAPS = {6000, 45000};

	private QuestSim sim(long gap) throws Exception
	{
		return new QuestSim(folder.newFolder().toPath(), gap);
	}

	/** The quest moments heard, in order. */
	private static List<String> moments(QuestSim s)
	{
		List<String> out = new ArrayList<>();
		for (String id : s.heardIds)
		{
			if (id.startsWith("qm-"))
			{
				out.add(id);
			}
		}
		return out;
	}

	// ------------------------------------------------------------ Enter the Abyss

	/** Enter the Abyss, the usual way: Aubury, Sedridor, Cromperty. */
	private QuestSim abyss(long gap, boolean runeMysteriesSeen) throws Exception
	{
		QuestSim s = sim(gap);
		if (runeMysteriesSeen)
		{
			s.witnessed(Quest.RUNE_MYSTERIES);
		}
		else
		{
			s.done(Quest.RUNE_MYSTERIES);
		}
		s.started(Quest.ENTER_THE_ABYSS);
		s.at(3100, 3550, 0);
		s.npc("Mage of Zamorak", 3104, 3558, 0);
		s.walkTo(3103, 3556, 0, 1);
		s.ticks(6);
		s.talk("Mage of Zamorak", 8, () -> s.varp(492, 1));
		s.ticks(20);
		s.removeNpc("Mage of Zamorak");
		s.at(3212, 3424, 0);
		s.ticks(4);
		s.npc("Mage of Zamorak", 3259, 3386, 0);
		s.walkTo(3258, 3384, 0, 1);
		s.ticks(4);
		s.talk("Mage of Zamorak", 40, () ->
		{
			s.varp(492, 2);
			s.bag(5519);
		});
		s.ticks(20);
		s.at(3253, 3400, 0);
		s.ticks(4);
		s.at(2911, 4832, 0);
		s.varbit(2315, 1);
		s.ticks(20);
		s.at(3104, 9572, 0);
		s.ticks(10);
		s.at(2911, 4832, 0);
		s.varbit(2314, 1);
		s.ticks(20);
		s.at(2683, 3321, 0);
		s.ticks(10);
		s.at(2911, 4832, 0);
		s.varbit(2316, 1);
		s.bag(5518);
		s.ticks(30);
		s.at(3258, 3384, 0);
		s.ticks(10);
		s.dialogue("Mage of Zamorak");
		s.ticks(20);
		s.varp(492, 3);
		s.bag();
		s.ticks(20);
		s.varp(492, 4);
		// No scroll: the plugin hears of it as the page is written.
		s.miniquestComplete(Quest.ENTER_THE_ABYSS, "Enter the Abyss");
		s.ticks(2);
		s.dialogue(false);
		s.ticks(120);
		s.summary();
		return s;
	}

	@Test
	public void enterTheAbyssHasEachMomentOnceAndInOrder() throws Exception
	{
		for (long gap : GAPS)
		{
			for (boolean seen : new boolean[]{false, true})
			{
				QuestSim s = abyss(gap, seen);
				assertEquals(s.transcript(), Arrays.asList(
					"qm-enter-the-abyss-not-here",
					seen ? "qm-enter-the-abyss-the-orb-after-rune-mysteries" : "qm-enter-the-abyss-the-orb",
					"qm-enter-the-abyss-the-orb-full",
					"qm-enter-the-abyss-done"), moments(s));
				assertTrue(s.transcript(), s.lost.isEmpty());
			}
		}
	}

	@Test
	public void aMiniquestsEndIsSaidWithNoScrollAndItsPageIsNews() throws Exception
	{
		QuestSim s = abyss(6000, false);
		assertFalse("a miniquest has no scroll to answer", s.heardIds.contains("quest-complete"));
		assertTrue("its page is the witness", s.h.engine.getContext().questWitnessedOn("ENTER_THE_ABYSS") != null);
	}

	/** The first two readings pass in silence; the orb filling at the third is the moment. */
	@Test
	public void theOrbIsMarkedWhenItFillsNotBefore() throws Exception
	{
		QuestSim s = sim(6000);
		s.started(Quest.ENTER_THE_ABYSS);
		s.varp(492, 2);
		s.bag(5519);
		s.at(3253, 3400, 0);
		s.ticks(10);
		s.at(2911, 4832, 0);
		s.varbit(2315, 1);
		s.ticks(20);
		assertFalse("not at the first reading\n" + s.transcript(),
			s.heardIds.contains("qm-enter-the-abyss-the-orb-full"));
		s.at(3253, 3400, 0);
		s.ticks(10);
		s.at(2911, 4832, 0);
		s.bag(5518);
		s.ticks(10);
		s.summary();
		assertTrue(s.transcript(), s.heardIds.contains("qm-enter-the-abyss-the-orb-full"));
	}

	// ---------------------------------------------------------- Temple of the Eye

	private QuestSim temple(long gap, boolean earlierQuestsSeen) throws Exception
	{
		QuestSim s = sim(gap);
		if (earlierQuestsSeen)
		{
			s.witnessed(Quest.RUNE_MYSTERIES);
			s.witnessed(Quest.ENTER_THE_ABYSS);
		}
		else
		{
			s.done(Quest.RUNE_MYSTERIES);
			s.done(Quest.ENTER_THE_ABYSS);
		}
		s.started(Quest.TEMPLE_OF_THE_EYE);
		s.at(3284, 3231, 0);
		s.ticks(4);
		s.talk("Wizard Persten", 40, () ->
		{
			s.varbit(13738, 10);
			s.bag(26903);
		});
		s.ticks(20);
		// Herbert, and the tea.
		s.at(3258, 3384, 0);
		s.ticks(6);
		s.talk("Mage of Zamorak", 30, () -> s.varbit(13738, 15));
		s.ticks(15);
		s.at(3270, 3409, 0);
		s.ticks(4);
		s.talk("Tea Seller", 8, () -> s.bag(26903, 26904, 1929));
		s.ticks(20);
		s.at(3258, 3384, 0);
		s.ticks(4);
		s.dialogue("Mage of Zamorak");
		s.ticks(10);
		s.varbit(13738, 20);
		s.ticks(10);
		s.varbit(13738, 25);
		s.at(3039, 4832, 0);
		s.ticks(1);
		s.dialogue(false);
		s.ticks(6);
		// The bath, and the energies after it.
		s.dialogue("Dark Mage");
		s.ticks(10);
		s.varbit(13738, 30);
		s.ticks(15);
		s.varbit(13738, 35);
		s.ticks(1);
		s.dialogue(false);
		s.ticks(60);
		s.varbit(13738, 40);
		s.talk("Dark Mage", 10, () -> s.varbit(13738, 45));
		s.ticks(10);
		// Persten again, and Sedridor on the incantation.
		s.at(3284, 3231, 0);
		s.ticks(4);
		s.talk("Wizard Persten", 40, () -> s.varbit(13738, 60));
