		s.ticks(40);
		s.varbit(13738, 95);
		s.ticks(20);
		s.varbit(13738, 100);
		s.scene(false);
		s.ticks(60);
		s.talk("Wizard Persten", 10, () -> s.varbit(13738, 105));
		s.scene(true);
		s.ticks(30);
		s.varbit(13738, 110);
		s.ticks(40);
		s.varbit(13738, 115);
		s.scene(false);
		s.ticks(120);
		s.scene(true);
		s.ticks(30);
		s.varbit(13738, 120);
		s.ticks(30);
		s.varbit(13738, 125);
		s.ticks(20);
		s.varbit(13738, 130);
		s.scene(false);
		s.questComplete(Quest.TEMPLE_OF_THE_EYE, "Temple of the Eye");
