		return s;
	}

	@Test
	public void templeOfTheEyeHasEachMomentOnceAndInOrder() throws Exception
	{
		for (long gap : GAPS)
		{
			for (boolean seen : new boolean[]{false, true})
			{
				QuestSim s = temple(gap, seen);
				assertEquals(s.transcript(), Arrays.asList(
