	/** The tea moment waits for the cup: Herbert asking for it is a moment of its own. */
	@Test
	public void theStrongTeaWaitsForTheCup() throws Exception
	{
		QuestSim s = sim(6000);
		s.started(Quest.TEMPLE_OF_THE_EYE);
		s.bag(26903);
		s.at(3258, 3384, 0);
		s.ticks(4);
		s.talk("Mage of Zamorak", 20, () -> s.varbit(13738, 15));
		s.ticks(30);
		assertFalse("not before the cup\n" + s.transcript(), s.heardIds.contains("qm-temple-of-the-eye-strong-tea"));
		s.bag(26903, 26904);
		s.ticks(10);
		s.summary();
		assertTrue(s.transcript(), s.heardIds.contains("qm-temple-of-the-eye-strong-tea"));
	}

	/** Persten's moment is grave: no contractions, as the death lines have none. */
	@Test
	public void perstensMomentKeepsTheGraveRegister() throws Exception
	{
		QuestSim s = sim(6000);
		SpeechRule persten = s.h.rule("qm-temple-of-the-eye-persten");
		for (String line : persten.say)
		{
			assertFalse(line, line.matches(".*\\w'\\w.*"));
		}
		assertTrue("a sad moment lowers the mood", persten.mood != null && persten.mood < 0);
	}
}

package com.follower;

import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.nio.file.Files;
import java.util.List;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * When the plugin lets the follower do agility at all. A Stay the player
 * gave means no agility; thrall work, a film, and the setting turned off
 * let the queue go; a logout or a hop too. A cutscene only stops the
 * watching, and what is queued waits for it. A scene rebuild is neither:
 * the recording carries on after it. And while agility has the follower,
 * the seat, the moments and the spectator stand aside.
 *
 * <p>Plugin glue no harness drives, so it goes through a bare plugin as
 * StayHoldsTest does, with a stand-in for the follower that only counts.
 * The agility trace is plugin glue too, and is here: written only with
 * Developer commands on, and only with agility about.
 */
public class AgilityGateTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final int[] NORMAL = {808, 819, 824, 820, 821, 822, 823, 823};

	/** Counts what the plugin asks of the follower's agility. */
	private static final class Agile extends FollowerEntity
	{
		boolean doing;
		boolean holding;
		int held;
		int cleared;
		int strandedCleared;

		Agile()
		{
			super(null, null);
		}

		@Override
		public boolean isSpawned()
		{
			return true;
		}

		@Override
		public boolean isDoingAgility()
		{
			return doing;
		}

		@Override
		public boolean isHoldingForAgility()
		{
			return holding;
		}

		@Override
		public int getStrandedTicks()
		{
			return 10;
		}

		@Override
		public void clearStranded()
		{
			strandedCleared++;
		}

		@Override
		public void clearCrossings()
		{
			cleared++;
		}

		@Override
		public void holdForAgility()
		{
			held++;
		}

		@Override
		public void expectCrossing(WorldPoint start)
		{
		}

		@Override
		public void queueCrossing(Crossing crossing)
		{
		}

		@Override
		public void cancelExpectedCrossing()
		{
		}
	}

	private final FakeGame game = new FakeGame();
	private final Agile follower = new Agile();
	private final CrossingWatch watch = new CrossingWatch(follower);
	private final FollowerPlugin plugin = new FollowerPlugin();
	private boolean settingOn = true;

	@Before
	public void setUp() throws ReflectiveOperationException
	{
		set("client", game.client);
		set("follower", follower);
		set("crossingWatch", watch);
		set("config", new FollowerConfig()
		{
			@Override
			public boolean copiesAgility()
			{
				return settingOn;
			}
		});
		IdleControllers.fill(plugin);
		game.at(50, 50, 0).basePoses(NORMAL).posing(808);
		frame();
	}

	@Test
	public void theSettingIsOnOutOfTheBox()
	{
		assertTrue(new FollowerConfig()
		{
		}.copiesAgility());
	}

	@Test
	public void somethingOddIsWatchedWhenNothingStandsInTheWay() throws ReflectiveOperationException
	{
		somethingOdd();
		assertTrue(watch.isWatching());
		assertEquals(0, follower.cleared);
	}

	@Test
	public void aStayTheyGaveMeansNoAgility() throws ReflectiveOperationException
	{
		set("parkedByPlayer", true);
		lettingGo();
	}

	@Test
	public void thrallWorkLetsItGo() throws ReflectiveOperationException
	{
		set("thrallLimbo", true);
		lettingGo();
	}

	@Test
	public void theSettingOffLetsItGo() throws ReflectiveOperationException
	{
		settingOn = false;
		lettingGo();
	}

	@Test
	public void aLogoutOrAHopLetsItGo() throws ReflectiveOperationException
	{
		somethingOdd();
		follower.doing = true;
		game.gameState(GameState.HOPPING);
		frame();
		assertFalse(watch.isWatching());
		assertEquals(1, follower.cleared);
	}

	@Test
	public void aCutsceneHoldsTheQueueAndWatchesNothing() throws ReflectiveOperationException
	{
		somethingOdd();
		follower.doing = true;
		set("sceneOn", true);
		frame();
		assertFalse("the scene's moves are not copied", watch.isWatching());
		assertEquals("and the queue is kept for after it", 0, follower.cleared);
	}

	@Test
	public void aRebuildIsSteppedOverNotTakenForALogout() throws ReflectiveOperationException
	{
		somethingOdd();
		follower.doing = true;
		game.gameState(GameState.LOADING);
		frame();
		assertTrue("still watching", watch.isWatching());
		assertEquals(0, follower.cleared);
	}

	@Test
	public void theFollowersOwnBusinessStandsAsideForIt() throws ReflectiveOperationException
	{
		for (String gate : new String[]{
			"seatFeetTaken",
			"momentFeetTaken",
			"spectateBusy",
		})
		{
			assertFalse(gate + " with nothing going on", (Boolean) call(gate));
		}
		follower.doing = true;
		for (String gate : new String[]{
			"seatFeetTaken",
			"momentFeetTaken",
			"spectateBusy",
		})
		{
			assertTrue(gate + " while it does agility", (Boolean) call(gate));
		}
	}

	@Test
	public void agilityIsBehindNotStrandedSoNoTeleport() throws ReflectiveOperationException
	{
		follower.doing = true;
		call("updateStrandedTeleport");
		assertEquals("no teleport set off", 0, get("strandedLandingTicks"));
		assertEquals("and the count let go", 1, follower.strandedCleared);

		follower.doing = false;
		follower.holding = true;
		call("updateStrandedTeleport");
		assertEquals("nor while it waits on the player's agility", 0, get("strandedLandingTicks"));
		assertEquals(2, follower.strandedCleared);
	}

	@Test
	public void theWaitIsLetGoWithTheQueue() throws ReflectiveOperationException
	{
		follower.holding = true;
		set("parkedByPlayer", true);
		frame();
		assertEquals("a Stay ends the wait as it ends the queue", 1, follower.cleared);
	}

	/**
	 * Ape Atoll is run as a greegree monkey, which the watch cannot read, so
	 * nothing there is copied. Its XP then holds nothing either: the follower
	 * joins the player up each tree at once, as before (QA4 #7).
	 */
	@Test
	public void xpTheWatchCannotReadHoldsNothing() throws ReflectiveOperationException, IOException
	{
		set("speechEngine", new Harness(folder.newFolder().toPath()).engine);
		game.transformedInto(1480);
		agilityXp(1000);
		agilityXp(1010);
		assertEquals("a monkey's XP", 0, follower.held);

		game.transformedInto(-1);
		agilityXp(1020);
		assertEquals("their own", 1, follower.held);
	}

	/**
	 * On a course the run back to the first obstacle is not agility, and an
	 * errand begun there turned the watch off and missed the first climb.
	 * Agility XP in the last minute keeps errands off (QA4 #24).
	 */
	@Test
	public void noErrandWithinAMinuteOfAgilityXp() throws ReflectiveOperationException, IOException
	{
		set("dialog", new FollowerDialog(null, null, null, null, null, null, null, null));
		set("speechEngine", new Harness(folder.newFolder().toPath()).engine);
		assertFalse("nothing going on", (Boolean) call("errandBusy"));
		agilityXp(1000);
		agilityXp(1010);
		assertTrue("between laps", (Boolean) call("errandBusy"));
		set("lastAgilityXpMs", System.currentTimeMillis() - 61_000);
		assertFalse("a minute on", (Boolean) call("errandBusy"));
	}

	private void agilityXp(int xp)
	{
		plugin.onStatChanged(new net.runelite.api.events.StatChanged(net.runelite.api.Skill.AGILITY, xp, 50, 50));
	}

	// ---------------------------------------------------------------- helpers

	private Object get(String name) throws ReflectiveOperationException
	{
		Field field = FollowerPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		return field.get(plugin);
	}

	private void lettingGo() throws ReflectiveOperationException
	{
		follower.doing = true;
		game.animating(866);
		frame();
		assertFalse("nothing watched", watch.isWatching());
		assertEquals("and the queue let go", 1, follower.cleared);
	}

	/** A jump: the clip, and the player put over a few units at a time on the stand. */
	private void somethingThatMoves() throws ReflectiveOperationException
	{
		game.animating(741);
		frame();
		for (int i = 1; i <= 3; i++)
		{
			game.fineAt(50 * 128 + 64 + 8 * i, 50 * 128 + 64, 0);
			frame();
		}
	}

	/** An animation begins: something the watch looks at. */
	private void somethingOdd() throws ReflectiveOperationException
	{
		game.animating(866);
		frame();
	}

	private void frame() throws ReflectiveOperationException
	{
		call("watchForAgility");
	}

	private Object call(String name) throws ReflectiveOperationException
	{
		Method method = FollowerPlugin.class.getDeclaredMethod(name);
		method.setAccessible(true);
		return method.invoke(plugin);
	}

	private void set(String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(plugin, value);
	}
}

package com.follower;

import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Set;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The follower's remarks on agility it copied: a clean crossing is an odd
 * remark, not one per obstacle, and a fall gets one line, not two.
 */
public class AgilityRemarksTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@SuppressWarnings("unchecked")
	private static Set<String> silenced(boolean copiesAgility) throws ReflectiveOperationException
	{
		FollowerPlugin plugin = new FollowerPlugin();
		Field config = FollowerPlugin.class.getDeclaredField("config");
		config.setAccessible(true);
		config.set(plugin, new FollowerConfig()
		{
			@Override
			public boolean copiesAgility()
			{
				return copiesAgility;
			}
		});
		Method collect = FollowerPlugin.class.getDeclaredMethod("collectDisabledGroups");
		collect.setAccessible(true);
		return (Set<String>) collect.invoke(plugin);
	}

	@Test
	public void theSlipStandsAsideOnlyWhileTheFollowerCopiesTheFall() throws Exception
	{
		assertTrue("copying, the fall is the follower's line", silenced(true).contains("fail-slip"));
		assertFalse("not copying, the slip keeps its line", silenced(false).contains("fail-slip"));
	}

	@Test
	public void aCleanCrossingIsAnOddRemarkAndAFallIsSaid() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		SpeechRule crossed = h.rule("agility-crossed");
		assertNotNull(crossed);
		assertTrue("a cooldown of minutes, not one line a lap", crossed.cooldownMs >= 300_000);
		assertTrue("and a roll", crossed.when.usesType("chance"));

		SpeechRule fell = h.rule("agility-fell");
		assertTrue("a fall too: minutes between, not one a fall", fell.cooldownMs >= 300_000);
		assertTrue("and a roll", fell.when.usesType("chance"));

		// Falls until one passes its roll: about one in three.
		h.gameTicks(2);
		for (int i = 0; i < 40 && h.firedBy("agility-fell").isEmpty(); i++)
		{
			h.dispatch(TriggerEvent.crossed(true));
			h.gameTicks(5);
		}
		assertEquals("a copied fall is said", 1, h.firedBy("agility-fell").size());
		assertEquals("and only that", 0, h.firedBy("agility-crossed").size());
	}
}

package com.follower;

import java.io.IOException;
import java.time.LocalDate;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The first twenty minutes, which decide whether there is a second session.
 *
 * <p>Almost everything the follower has to say about YOU is gated behind a
 * history it has not got yet, so a new player meets the encyclopaedia rather
 * than the character. Four one-time lines cover the gap, and they are the only
 * content in the file that a player can miss permanently by the plugin getting
 * it wrong.
 *
 * <p>Which is not hypothetical. The first draft of two of these rules used an
 * "all" shorthand the condition parser does not have; they loaded, evaluated
 * false forever, and would have shipped as four lines nobody ever heard. Hence
 * a test that fires each one for real rather than reading the file.
 */
public class ArrivalArcTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** The bundled rules, with the follower's memory set to a given history. */
	private Harness known(int sessions, int daysAgo) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		TriggerContext context = h.engine.getContext();
		context.setSessionCount(sessions);
		if (daysAgo >= 0)
		{
			context.setMetOnDay(LocalDate.now().toEpochDay() - daysAgo);
		}
		h.gameTicks(1);
		return h;
	}

	/** Waits out the delayTicks the login lines carry, so the words come out. */
	private static void settle(Harness h)
	{
		h.gameTicks(10);
	}

	/**
	 * Runs the session clock forward a minute at a time, as the plugin's own
	 * timer does. Jumping it straight to the number a rule wants would step
	 * over every window on the way and prove nothing about the sequence.
	 */
	private static void minutesPass(Harness h, int upTo)
	{
		for (int minute = h.engine.getContext().getSessionMinutes() + 1; minute <= upTo; minute++)
		{
			h.engine.getContext().setSessionMinutes(minute);
			h.gameTicks(1);
		}
	}

	private static Condition sessionMinutesWindow(Harness h, String ruleId)
	{
		for (Condition part : h.rule(ruleId).when.conditions)
		{
			if ("sessionMinutes".equalsIgnoreCase(part.type))
			{
				return part;
			}
		}
		throw new AssertionError(ruleId + " no longer sits on the session clock");
	}

	// ----------------------------------------------------------- the first hello

	@Test
	public void theVeryFirstLoginIsNotTheEverydayGreeting() throws IOException
	{
		Harness h = known(1, 0);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		settle(h);

		assertEquals("the first login has its own hello", 1, h.firedBy("first-meeting").size());
		assertTrue("and the everyday one stays out of its way",
			h.firedBy("login-greeting").isEmpty());
		assertTrue("in every era",
			h.firedBy("login-greeting-new").isEmpty());
	}

	@Test
	public void theSecondLoginIsTheEverydayGreetingAgain() throws IOException
	{
		// Same day, so this is a relog rather than a return - the arc's last
		// beat is about coming back TOMORROW and must not fire here. On day
		// zero the everyday hello wears its polite era (R16).
		Harness h = known(2, 0);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		settle(h);

		assertTrue(h.firedBy("first-meeting").isEmpty());
		assertTrue(h.firedBy("first-return").isEmpty());
		assertEquals(1, h.firedBy("login-greeting-new").size());
	}

	@Test
	public void comingBackTheNextDayIsWorthSaying() throws IOException
	{
		Harness h = known(2, 1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		settle(h);

		assertEquals("twice is how a habit starts", 1, h.firedBy("first-return").size());
		assertTrue(h.firedBy("login-greeting").isEmpty());
	}

	@Test
	public void aLongStandingPlayerGetsNoneOfIt() throws IOException
	{
		Harness h = known(400, 300);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		settle(h);
		minutesPass(h, 90);

		for (String id : new String[]{"first-meeting", "first-page", "first-hour", "first-return"})
		{
			assertTrue(id + " is for a follower that has just met you",
				h.firedBy(id).isEmpty());
		}
	}

	// -------------------------------------------------------- inside the session

	@Test
	public void tenMinutesInItWritesSomethingDown() throws IOException
	{
		// Scheduled on purpose. Left to the gates that already exist, a new
		// player's first characterful moment waits on a tally, a record or a
		// place score - none of which they have.
		Harness h = known(1, 0);
		minutesPass(h, 9);
		assertTrue("not yet", h.firedBy("first-page").isEmpty());

		minutesPass(h, 10);
		assertEquals(1, h.firedBy("first-page").size());
	}

	@Test
	public void anHourInItAdmitsItHasNothingOnYou() throws IOException
	{
		Harness h = known(1, 0);
		minutesPass(h, 45);

		assertEquals(1, h.firedBy("first-hour").size());
	}

	@Test
	public void theTwoInSessionLinesCannotBothWinTheSameTick() throws IOException
	{
		// They sit on the same clock, and a rule that loses an evaluation pass
		// has still had its rising edge consumed by it - so an overlap is not a
		// line that arrives late, it is a line that never arrives at all. The
		// windows are made exclusive rather than trusted to arrive in order.
		Harness h = known(1, 0);
		assertTrue("the earlier beat must close before the later one opens",
			sessionMinutesWindow(h, "first-page").maximum != null);

		minutesPass(h, 60);
		assertEquals(1, h.firedBy("first-page").size());
		assertEquals(1, h.firedBy("first-hour").size());
	}

	@Test
	public void theFirstDaysLinesStopBeingTrueAfterTheFirstDays() throws IOException
	{
		Harness h = known(9, 30);
		minutesPass(h, 60);

		assertTrue(h.firedBy("first-page").isEmpty());
		assertTrue(h.firedBy("first-hour").isEmpty());
	}

	// ------------------------------------------------------------- and only once

	@Test
	public void noneOfItHappensTwice() throws IOException
	{
		Harness h = known(1, 0);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		settle(h);
		minutesPass(h, 45);

		assertEquals(1, h.firedBy("first-meeting").size());
		assertEquals(1, h.firedBy("first-page").size());
		assertEquals(1, h.firedBy("first-hour").size());

		// A world hop, which resets every rule's edge state and would re-raise
		// each of these conditions from scratch.
		h.engine.resetForNewScene();
		h.clear();
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		settle(h);
		h.gameTicks(2);

		for (String id : new String[]{"first-meeting", "first-page", "first-hour"})
		{
			assertTrue(id + " said itself a second time", h.firedBy(id).isEmpty());
		}
	}

	@Test
	public void everyArrivalLineIsMarkedBothOnceAndAnOccasion() throws IOException
	{
		// The two go together here and nowhere else. Missing "once" turns the
		// introduction into a catchphrase; missing "occasion" lets the director
		// swallow the one hearing the player was ever going to get.
		Harness h = new Harness(folder.newFolder().toPath());
		for (String id : new String[]{"first-meeting", "first-page", "first-hour", "first-return"})
		{
			assertTrue(id + " must be said only once", h.rule(id).isOnce());
			assertTrue(id + " must survive a relax period", h.rule(id).isOccasion());
			assertFalse(id + " must actually say something", h.rule(id).say.isEmpty());
		}
	}
}

package com.follower;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Telling a swing from everything else a player does mid-interaction.
 *
 * <p>Interaction alone was the whole test, and interaction is sticky: it
 * outlives the fight that set it. Walk away from an NPC, start mining, and the
 * pickaxe's swing is filed as that weapon's attack animation. It happened - a
 * single 30-frame mining loop became the learned attack of six pickaxes and of
 * a shortbow, so the follower in ranged thrall mode shot its bow by mining
 * with it.
 *
 * <p>The fix is the rule TriggerContext already arrived at for the same
 * reason, applied to the observer that was still trusting interaction.
 */
public class AttackSightingTest
{
	@Test
	public void miningWithAStaleTargetIsNotASwing()
	{
		// The local player, interaction still pointing at a finished fight,
		// and the context reporting no combat.
		assertFalse("a pickaxe swing is not a bow shot",
			FollowerPlugin.sightingIsASwing(true, false, -1));
		assertFalse("nor is it one because something is still targeted",
			FollowerPlugin.sightingIsASwing(true, false, 30));
	}

	@Test
	public void anActualFightStillTeaches()
	{
		assertTrue("the whole point of the observer",
			FollowerPlugin.sightingIsASwing(true, true, 30));
	}

	@Test
	public void somebodyElseIsJudgedByTheirTarget()
	{
		// No varps but our own, so the evidence is the target wearing a health
		// bar - which only happens in combat.
		assertTrue("their target is in combat",
			FollowerPlugin.sightingIsASwing(false, false, 30));
		assertFalse("their target has no health bar, so this is not a fight",
			FollowerPlugin.sightingIsASwing(false, false, -1));
		assertFalse("and a dead target is not being swung at",
			FollowerPlugin.sightingIsASwing(false, false, 0));
	}

	@Test
	public void ourOwnCombatFlagDoesNotVouchForOtherPlayers()
	{
		// Being in a fight ourselves says nothing about the player mining
		// beside us, and reading it as though it did is how one bad animation
		// spreads across every weapon in sight.
		assertFalse("our fight is not their swing",
			FollowerPlugin.sightingIsASwing(false, true, -1));
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * R15: speech scales to attention. Three minutes with camera, feet and
 * hands all untouched and the world is playing to an empty chair - so the
 * follower stops performing to it, reactions included. Occasions still
 * land, the rules ABOUT the absence still speak into it, and any input at
 * all clears the state instantly.
 */
public class AttentionDamperTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final String RULES = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"reaction\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"npcSpawn\", \"names\": [\"Goblin\"]},"
		+ " \"say\": [\"a goblin arrives\"]},"
		+ "{\"id\": \"warning\", \"group\": \"t\", \"cooldownMs\": 0, \"occasion\": true,"
		+ " \"when\": {\"type\": \"npcSpawn\", \"names\": [\"Dragon\"]},"
		+ " \"say\": [\"a dragon arrives\"]},"
		+ "{\"id\": \"absence\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"unattended\", \"ticks\": 250},"
		+ " \"say\": [\"gone, then\"]}]}";

	@Test
	public void answeringIsPresence() throws IOException
	{
		// Play report: a whole hands game played out and the follower never
		// said which hand it was. The game asks you to stand still to be
		// offered at all, and a player who then only clicks dialog options
		// moves neither camera nor feet - so three minutes in, the damper
		// decided the chair was empty and silenced the reveal, while the
		// person it was talking to was answering its question.
		//
		// Reading a question and choosing is the most direct evidence of a
		// person there is, so it clears the state like any other input.
		String rules = "{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"reveal\", \"group\": \"t\", \"cooldownMs\": 0,"
			+ " \"when\": {\"type\": \"answered\", \"is\": \"left\"},"
			+ " \"say\": [\"it was the other one\"]}]}";

		Harness h = new Harness(folder.newFolder().toPath(), rules);
		h.gameTicks(320);
		assertTrue("the damper should have engaged by now",
			h.engine.getContext().getUnattendedTicks() >= 300);

		h.dispatch(TriggerEvent.answered("left"));

		assertTrue("the follower went quiet on somebody who was talking to it",
			!h.firedBy("reveal").isEmpty());
		assertEquals("answering left the follower still thinking it was alone",
			0, h.engine.getContext().getUnattendedTicks());
	}

	/** A harness left genuinely alone: no camera, no feet, no hands, no events. */
	private Harness abandoned() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.gameTicks(320);
		return h;
	}

	@Test
	public void nobodyWatchingMeansNoPerformance() throws IOException
	{
		Harness h = abandoned();
		h.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Goblin"));
		assertTrue("a reaction played to an empty chair",
			h.firedBy("reaction").isEmpty());
	}

	@Test
	public void anyInputAtAllRestoresTheAudience() throws IOException
	{
		// The camera.
		Harness h = abandoned();
		h.game.cameraMoved();
		h.gameTicks(1);
		h.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Goblin"));
		assertEquals("the camera moving is presence", 1, h.firedBy("reaction").size());

		// The hands.
		Harness busy = abandoned();
		busy.game.animating(879);
		busy.gameTicks(1);
		busy.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Goblin"));
		assertEquals("animating is presence", 1, busy.firedBy("reaction").size());

		// A real event, which cannot happen from the kettle.
		Harness fighting = abandoned();
		fighting.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_START));
		fighting.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Goblin"));
		assertEquals("a fight starting is presence", 1, fighting.firedBy("reaction").size());
	}

	@Test
	public void theWarningStillLandsOnTheEmptyChair() throws IOException
	{
		// An occasion matters the moment they glance back at the screen.
		Harness h = abandoned();
		h.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Dragon"));
		assertEquals("occasions are exempt from the damper",
			1, h.firedBy("warning").size());
	}

	@Test
	public void theAbsenceItselfMayStillBeRemarkedOn() throws IOException
	{
		// The gone-away jokes are ABOUT the empty chair; silencing them with
		// it would remove the only lines written for exactly this moment.
		Harness h = abandoned();
		assertEquals("the absence rules speak into the absence",
			1, h.firedBy("absence").size());
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The follower responding to the PLAYER rather than to the world.
 *
 * <p>The failure that matters here is a follower that answers everybody: a
 * "hello" in a crowded bank raises one chat event per person who says it, and a
 * companion that greets all of them is not a companion, it is a bot. Every case
 * below therefore checks the negative as well as the positive.
 */
public class AttentionTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void theFollowerGreetsYouAndNotTheStreet() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		h.someoneSays("Somebody Else", "hello");
		h.someoneSays("Another Person", "hi");
		// These rules carry a delayTicks, so a line that has WON is still only
		// pending. Asserting before the ticks pass would pass no matter what.
		h.gameTicks(6);
		assertTrue("a follower that greets the whole bank is not greeting you",
			h.firedBy("greet-back").isEmpty());

		h.playerSays("hello");
		h.gameTicks(8);
		assertFalse("your own hello, though", h.firedBy("greet-back").isEmpty());
	}

	@Test
	public void aGameMessageIsNotSomebodyTalking() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		// The game says plenty of things containing "hi" and "ty". None of them
		// are the player saying hello or thank you.
		h.dispatch(TriggerEvent.chat("You hit the target.",
			net.runelite.api.ChatMessageType.GAMEMESSAGE.getType(), ""));
		h.dispatch(TriggerEvent.chat("Oh dear, you are dead!",
			net.runelite.api.ChatMessageType.GAMEMESSAGE.getType(), ""));
		h.gameTicks(6);

		assertTrue("game messages must not be read as conversation",
			h.firedBy("greet-back").isEmpty() && h.firedBy("thanked").isEmpty());
	}

	@Test
	public void aWordInsideAnotherWordIsNotThatWord() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		h.playerSays("this city is huge");
		h.playerSays("pretty good drop");
		h.gameTicks(6);

		assertTrue("'hi' in 'this' and 'ty' in 'pretty' are not greetings or thanks",
			h.firedBy("greet-back").isEmpty() && h.firedBy("thanked").isEmpty());
	}

	@Test
	public void restingTheMouseOnItIsNoticedAndCrossingTheScreenIsNot() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().setHoverTicks(2);
		h.gameTicks(3);
		assertTrue("a cursor passing over is not attention",
			h.firedBy("hovered").isEmpty());

		// The rule rolls a chance, so give it a fair number of chances.
		h.engine.getContext().setHoverTicks(30);
		for (int i = 0; i < 60 && h.firedBy("hovered").isEmpty(); i++)
		{
			h.engine.getContext().setHoverTicks(30);
			h.gameTicks(1);
		}
		assertFalse("resting on it is", h.firedBy("hovered").isEmpty());
	}

	@Test
	public void beingExaminedGetsAnAnswer() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		h.gameTicks(8);
		assertFalse("being looked up is worth noticing", h.firedBy("examined").isEmpty());
	}

	@Test
	public void theFlinchIsSilent() throws IOException
	{
		// A body that reacts before the mouth does is most of what makes
		// something look like it is watching. A line here would just be one
		// more thing said during a fight that is already noisy.
		Harness h = new Harness(folder.newFolder().toPath());
		SpeechRule flinch = h.rule("flinch-big-hit");

		assertTrue("the flinch must not speak",
			flinch.say == null || flinch.say.isEmpty());
		assertFalse("but it must do something", flinch.animation == null);

		// One winner per event, so an animation-only rule is invisible for any
		// hit a higher-priority spoken rule also matches. big-hit-taken owns
		// everything from 30 up, which was the whole top of the range - the
		// biggest hits were the ones that did NOT flinch. The body language has
		// to live on whichever rule actually wins the moment.
		SpeechRule spoken = h.rule("big-hit-taken");
		assertTrue("big-hit-taken outranks the flinch and must carry it too",
			spoken.priority <= flinch.priority
				|| flinch.animation.equals(spoken.animation));
	}

	@Test
	public void anythingThatVanishesHoldsStillWhileItGoes()
	{
		// A rule that vanishes is playing a departure - a teleport cast, a
		// comedy death - and a departure has to finish where it started.
		//
		// The case that found this: the player teleports while the follower is
		// off on an idle distraction. The player animating resets the idle
		// counter, so the wander is released that same tick, and the follower
		// abandons its own cast to run back to somebody who is no longer
		// standing there. Holding still also keeps the wander logic out
		// entirely, since it treats a held emote as busy.
		Harness h;
		try
		{
			h = new Harness(folder.newFolder().toPath());
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}

		java.util.List<String> loose = new java.util.ArrayList<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			if (Boolean.TRUE.equals(rule.vanishAfter)
				&& !Boolean.TRUE.equals(rule.holdStill))
			{
				loose.add(rule.id);
			}
		}
		assertTrue("rules that vanish without planting the follower first,"
			+ " so anything that moves it mid-animation cuts the exit short: "
			+ loose, loose.isEmpty());
	}

	@Test
	public void theBagWarningComesWhileThereIsStillRoom() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());

		h.game.inventoryUsing(24);
		h.gameTicks(3);
		assertTrue("four slots left is not a warning",
			h.firedBy("bag-nearly-full").isEmpty());

		h.game.inventoryUsing(26);
		h.gameTicks(3);
		assertFalse("two slots left is the moment to say so",
			h.firedBy("bag-nearly-full").isEmpty());

		assertEquals("and the point is that it is not full yet",
			2, h.engine.getContext().getFreeInventorySlots());
	}
}

package com.follower;

/*
 * ChatheadRenderer as it stood before the chathead renderer consolidation
 * (commit c17bc04), kept verbatim as ChatheadDiffTest's reference. Only the
 * package line and this header differ. Not used by the plugin.
 */

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Model;

/**
 * Renders a model to an image, in software.
 *
 * <p>Chathead widgets can only show models the cache already holds - a widget
 * takes a model ID, and there is no way to hand it a composed one - so the
 * follower's own head is unreachable through the game's dialog interface. It is
 * reachable this way: the model exposes its vertices, faces and already-lit face
 * colours, so projecting and filling the triangles here produces a real picture
 * of the actual follower rather than a stand-in.
 *
 * <p>Uses the client's own widget-model camera - perspective, orbited to the
 * dialog's pitch at its zoom - with painter's-algorithm depth sorting, and fills
 * triangles through {@link GouraudRasterizer}, a verbatim port of the client's
 * integer scanline rasterizer, so the pixels come out the way the game's own
 * renderer produces them - down to which pixels a two-pixel pupil covers. */
public final class BeforeChatheadRenderer
{
	private BeforeChatheadRenderer()
	{
	}

	/**
	 * The client's own chathead camera, read off live dialog widgets.
	 *
	 * <p>The head's angle arrives as the widget's rotationZ, but it drives THIS
	 * renderer's yaw: RuneLite's rotationZ is the axis that turns a chathead in
	 * the client's widget pipeline. NPC dialogs use 1882 and player dialogs 166 -
	 * exact mirrors (1882 = 2048 - 166), which is why an NPC and your own
	 * character face opposite ways. Applying it as a true Z-roll instead tilts the
	 * head sideways in the image plane, which is visibly wrong.
	 */
	public static final int GAME_PITCH = 40;
	public static final int GAME_TURN_NPC = 1882;
	public static final int GAME_TURN_PLAYER = 166;
	public static final int GAME_ZOOM = 796;

	/** The client's projection: screen = model * 512 / depth. */
	private static final double FOCAL_LENGTH = 512;

	/** Convenience overload: bounds come from the model itself, game camera. */
	public static BufferedImage render(Model model, int width, int height,
		int yaw, double headFraction)
	{
		return render(model, null, width, height, yaw, GAME_PITCH, GAME_ZOOM, headFraction);
	}

	/**
	 * @param model        the (possibly posed) model to draw
	 * @param boundsFrom   model to compute framing from, or null to use
	 *                     {@code model}. An animated head is framed by its UNPOSED
	 *                     base so the picture doesn't rescale as the jaw moves.
	 * @param yaw          model rotation about the vertical axis, in JAU - the
	 *                     widget's rotationY
	 * @param cameraPitch  the widget's rotationX. NOT a model tilt: the client
	 *                     orbits the CAMERA to this pitch at {@code zoom} distance
	 * @param zoom         camera distance, the widget's modelZoom
	 * @param headFraction share of the model's height, from the top, to include;
	 *                     1.0 draws the whole model (a real chathead model)
	 * @return the rendered image, or null if the model cannot be drawn
	 */
	public static BufferedImage render(Model model, Model boundsFrom, int width, int height,
		int yaw, int cameraPitch, int zoom, double headFraction)
	{
		return render(model, boundsFrom, width, height, yaw, cameraPitch, zoom,
			headFraction, -1, -1);
	}

	/**
	 * @param anchorX pixel where the model's ORIGIN projects, or -1 for centre.
	 *                The client anchors widget models at the widget's centre and
	 *                lets geometry overflow, clipped by the interface surface -
	 *                which is how tall hair gets cut at the dialog's top edge.
	 */
	public static BufferedImage render(Model model, Model boundsFrom, int width, int height,
		int yaw, int cameraPitch, int zoom, double headFraction, int anchorX, int anchorY)
	{
		if (model == null || width <= 0 || height <= 0)
		{
			return null;
		}
		Model frame = boundsFrom == null ? model : boundsFrom;

		float[] vx = model.getVerticesX();
		float[] vy = model.getVerticesY();
		float[] vz = model.getVerticesZ();
		float[] fx = frame.getVerticesX();
		float[] fy = frame.getVerticesY();
		int[] fa = model.getFaceIndices1();
		int[] fb = model.getFaceIndices2();
		int[] fc = model.getFaceIndices3();
		int[] colors = model.getFaceColors1();
		int[] hidden = model.getFaceColors3();

		if (vx == null || vy == null || vz == null || fx == null || fy == null
			|| fa == null || fb == null || fc == null || colors == null)
		{
			return null;
		}

		int verts = Math.min(model.getVerticesCount(), vx.length);
		if (Math.min(frame.getVerticesCount(), fx.length) != verts)
		{
			// A frame reference must be the same geometry (the unposed original).
			return null;
		}

		// The client's exact widget-model camera, from its drawInterface:
		//     eyeY = sin(rotationX) * zoom;  eyeZ = cos(rotationX) * zoom
		//     objRender(0, rotationY, 0, rotationX, 0, eyeY, eyeZ)
		// So the model is yawed, pushed out to `zoom`, and viewed by a camera
		// ORBITED to pitch rotationX - with a perspective divide. Approximating
		// that as a model-space tilt with an orthographic projection is what made
		// the framing need a fudged yaw to look right.
		double yawAngle = yaw / 2048.0 * 2.0 * Math.PI;
		double yawSin = Math.sin(yawAngle);
		double yawCos = Math.cos(yawAngle);
		double pitchAngle = cameraPitch / 2048.0 * 2.0 * Math.PI;
		double pitchSin = Math.sin(pitchAngle);
		double pitchCos = Math.cos(pitchAngle);
		double eyeY = pitchSin * zoom;
		double eyeZ = pitchCos * zoom;

		float[] rx = new float[verts];
		float[] ry = new float[verts];
		float[] rz = new float[verts];

		for (int i = 0; i < verts; i++)
		{
			double[] p = project(vx[i], vy[i], vz[i], yawSin, yawCos, pitchSin, pitchCos, eyeY, eyeZ);
			rx[i] = (float) p[0];
			ry[i] = (float) p[1];
			rz[i] = (float) p[2];
		}

		float minY = Float.MAX_VALUE;
		float maxY = -Float.MAX_VALUE;
		for (int i = 0; i < verts; i++)
		{
			minY = Math.min(minY, fy[i]);
			maxY = Math.max(maxY, fy[i]);
		}
		float cutoff = minY + (maxY - minY) * (float) headFraction;

		// Faces wholly inside the head region OF THE FRAME model, skipping ones
		// the client hides. Using the frame keeps face selection stable across
		// animation frames.
		List<Integer> keep = new ArrayList<>();
		for (int i = 0; i < fa.length; i++)
		{
			if (hidden != null && i < hidden.length && hidden[i] == -2)
			{
				continue;
			}
			int a = fa[i];
			int b = fb[i];
			int c = fc[i];
			if (a >= verts || b >= verts || c >= verts || a < 0 || b < 0 || c < 0)
			{
				continue;
			}
			if (fy[a] <= cutoff && fy[b] <= cutoff && fy[c] <= cutoff)
			{
				keep.add(i);
			}
		}
		if (keep.isEmpty())
		{
			return null;
		}

		// The client's own projection scale, not a fit-to-box. Widget models are
		// drawn at a fixed focal length about the model's ORIGIN, and they
		// overflow their widget rectangle freely - the real chathead widget is
		// 32x32 while the head it draws is far bigger. Fitting to a box instead
		// made size a guess; this makes it a consequence of zoom, exactly as in
		// game.
		int offsetX = anchorX < 0 ? width / 2 : anchorX;
		int offsetY = anchorY < 0 ? height / 2 : anchorY;

		// Screen coordinates the client's way: vertexScreenX = centerX +
		// (x << 9) / z, truncated to an INTEGER per vertex before any face is
		// drawn. The rasterizer walks scanlines between these ints; feeding it
		// float pixel centres instead is what dropped the sub-pixel eye faces.
		int[] sx = new int[verts];
		int[] sy = new int[verts];
		int[] sz = new int[verts];
		// vertexScreenZ, the client's convention: camera depth relative to the
		// model origin's depth (midZ), an INTEGER per vertex.
		double midZ = eyeY * pitchSin + eyeZ * pitchCos;
		for (int i = 0; i < verts; i++)
		{
			sx[i] = offsetX + (int) (rx[i] * FOCAL_LENGTH);
			sy[i] = offsetY + (int) (ry[i] * FOCAL_LENGTH);
			sz[i] = (int) (rz[i] - midZ);
		}

		// The client's calculateBoundsCylinder, for the depth-bucket range.
		double boundMaxY = 0;
		double boundMinY = 0;
		double radiusSqr = 0;
		for (int i = 0; i < verts; i++)
		{
			if (-vy[i] > boundMaxY)
			{
				boundMaxY = -vy[i];
			}
			if (vy[i] > boundMinY)
			{
				boundMinY = vy[i];
			}
			double r = vx[i] * vx[i] + vz[i] * vz[i];
			if (r > radiusSqr)
			{
				radiusSqr = r;
			}
		}
		int radius = (int) (Math.sqrt(radiusSqr) + 0.99);
		int minDepth = (int) (Math.sqrt(radius * radius + boundMaxY * boundMaxY) + 0.99);
		int maxDepth = minDepth + (int) (Math.sqrt(radius * radius + boundMinY * boundMinY) + 0.99);

		// Gouraud shading, the way the game itself draws models: each face carries
		// three per-corner lit colours (faceColors1/2/3), blended across the
		// triangle. Flat-filling with colours1 alone is what made every triangle
		// edge visible and the lighting angular. No antialiasing either - the
		// game's rasterizer has none, and crisp edges are part of the look.
		int[] colors2 = model.getFaceColors2();
		int[] colors3 = model.getFaceColors3();

		// The client's draw2 ordering, not a painter's sort. Faces go into
		// INTEGER average-depth buckets ((zA+zB+zC)/3 + minDepth) in face-index
		// order, and buckets are emitted far to near with insertion order kept
		// inside each bucket. Model authors rely on that: a pupil sits coplanar
		// ON the eye-white face and is authored LATER in face order so the same
		// bucket draws it on top. Sorting by exact float depth instead let the
		// eye-white face land on top of the pupil on some animation frames -
		// the stray white pixels in the eyes.
		//
		// Backface culling happens here, before bucketing, with the client's own
		// test on the same INTEGER screen coordinates it rasterises with. Without
		// it the BACK of the head - lit from behind, darker - bled through along
		// cheeks and brow as triangular patches.
		int[] bucketCount = new int[maxDepth + 1];
		int[][] buckets = new int[maxDepth + 1][];
		for (int face : keep)
		{
			int a = fa[face];
			int b = fb[face];
			int c = fc[face];
			if (rz[a] < 0 || rz[b] < 0 || rz[c] < 0)
			{
				continue;
			}
			if ((sx[a] - sx[b]) * (sy[c] - sy[b]) - (sy[a] - sy[b]) * (sx[c] - sx[b]) <= 0)
			{
				continue;
			}

			int depthAverage = (sz[a] + sz[b] + sz[c]) / 3 + minDepth;
			if (depthAverage < 0)
			{
				depthAverage = 0;
			}
			else if (depthAverage > maxDepth)
			{
				depthAverage = maxDepth;
			}
			if (buckets[depthAverage] == null)
			{
				buckets[depthAverage] = new int[8];
			}
			else if (bucketCount[depthAverage] == buckets[depthAverage].length)
			{
				int[] grown = new int[buckets[depthAverage].length * 2];
				System.arraycopy(buckets[depthAverage], 0, grown, 0, bucketCount[depthAverage]);
				buckets[depthAverage] = grown;
			}
			buckets[depthAverage][bucketCount[depthAverage]++] = face;
		}

		int[] drawOrder = resolveDrawOrder(model.getFaceRenderPriorities(),
			buckets, bucketCount, maxDepth, fa.length);

		int[] pixels = new int[width * height];
		BeforeGouraudRasterizer raster = new BeforeGouraudRasterizer(pixels, width, height);

		for (int face : drawOrder)
		{
			int a = fa[face];
			int b = fb[face];
			int c = fc[face];

			// colours3 == -1 flags a flat-shaded face: all corners take colours1.
			// Corners stay PACKED - the client interpolates the palette index
			// across the triangle and looks the table up per pixel, and matching
			// its colours means doing the same. Corner colours pair with vertices
			// A/B/C directly, exactly as the client's drawFace passes them.
			boolean flat = colors3 == null || colors3[face] == -1;
			int colourA = colors[face] & 0xFFFF;
			int colourB = flat || colors2 == null ? colourA : colors2[face] & 0xFFFF;
			int colourC = flat ? colourA : colors3[face] & 0xFFFF;

			raster.gouraudTriangle(sx[a], sx[b], sx[c], sy[a], sy[b], sy[c],
				colourA, colourB, colourC);
		}

		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		image.setRGB(0, 0, width, height, pixels, 0, width);
		return image;
	}

	/**
	 * The client's draw2 emission order, ported line for line. Without per-face
	 * render priorities: buckets far to near, insertion order within each. With
	 * priorities: the client's 12-class algorithm - faces collect into priority
	 * classes in depth order, classes 0..9 emit in class order, and the special
	 * classes 10 and 11 interleave into the stream whenever their next face is
	 * deeper than the running depth averages of classes 1+2 (checked before
	 * class 0), 3+4 (before class 3), and 6+8 (before class 5), with the
	 * leftovers emitted at the end. Player and NPC models rely on this to
	 * layer coplanar detail correctly.
	 */
	private static int[] resolveDrawOrder(byte[] priorities,
		int[][] buckets, int[] bucketCount, int maxDepth, int faceTotal)
	{
		int[] order = new int[faceTotal];
		int emitted = 0;

		if (priorities == null)
		{
			for (int depth = maxDepth; depth >= 0; depth--)
			{
				int count = bucketCount[depth];
				for (int i = 0; i < count; i++)
				{
					order[emitted++] = buckets[depth][i];
				}
			}
			return java.util.Arrays.copyOf(order, emitted);
		}

		int[] priorityFaceCounts = new int[12];
		int[][] priorityFaceLists = new int[12][faceTotal];
		int[] priorityDepthSum = new int[12];
		int[] priority10FaceDepth = new int[faceTotal];
		int[] priority11FaceDepth = new int[faceTotal];

		for (int depth = maxDepth; depth >= 0; depth--)
		{
			int faceCount = bucketCount[depth];
			for (int i = 0; i < faceCount; i++)
			{
				int face = buckets[depth][i];
				int priorityClass = Math.max(0, Math.min(11, priorities[face]));
				int classCount = priorityFaceCounts[priorityClass]++;
				priorityFaceLists[priorityClass][classCount] = face;
				if (priorityClass < 10)
				{
					priorityDepthSum[priorityClass] += depth;
				}
				else if (priorityClass == 10)
				{
					priority10FaceDepth[classCount] = depth;
				}
				else
				{
					priority11FaceDepth[classCount] = depth;
				}
			}
		}

		int averagePriorityDepthSum1_2 = 0;
		if (priorityFaceCounts[1] > 0 || priorityFaceCounts[2] > 0)
		{
			averagePriorityDepthSum1_2 = (priorityDepthSum[1] + priorityDepthSum[2])
				/ (priorityFaceCounts[1] + priorityFaceCounts[2]);
		}

		int averagePriorityDepthSum3_4 = 0;
		if (priorityFaceCounts[3] > 0 || priorityFaceCounts[4] > 0)
		{
			averagePriorityDepthSum3_4 = (priorityDepthSum[3] + priorityDepthSum[4])
				/ (priorityFaceCounts[3] + priorityFaceCounts[4]);
		}

		int averagePriorityDepthSum6_8 = 0;
		if (priorityFaceCounts[6] > 0 || priorityFaceCounts[8] > 0)
		{
			averagePriorityDepthSum6_8 = (priorityDepthSum[6] + priorityDepthSum[8])
				/ (priorityFaceCounts[6] + priorityFaceCounts[8]);
		}

		int priorityFace = 0;
		int priorityFaceCount = priorityFaceCounts[10];
		int[] priorityFaces = priorityFaceLists[10];
		int[] priorityFaceDepths = priority10FaceDepth;
		if (priorityFace == priorityFaceCount)
		{
			priorityFace = 0;
			priorityFaceCount = priorityFaceCounts[11];
			priorityFaces = priorityFaceLists[11];
			priorityFaceDepths = priority11FaceDepth;
		}

		int priorityDepth;
		if (priorityFace < priorityFaceCount)
		{
			priorityDepth = priorityFaceDepths[priorityFace];
		}
		else
		{
			priorityDepth = -1000;
		}

		for (int priority = 0; priority < 10; priority++)
		{
			while (priority == 0 && priorityDepth > averagePriorityDepthSum1_2)
			{
				order[emitted++] = priorityFaces[priorityFace++];
				if (priorityFace == priorityFaceCount && priorityFaces != priorityFaceLists[11])
				{
					priorityFace = 0;
					priorityFaceCount = priorityFaceCounts[11];
					priorityFaces = priorityFaceLists[11];
					priorityFaceDepths = priority11FaceDepth;
				}
				if (priorityFace < priorityFaceCount)
				{
					priorityDepth = priorityFaceDepths[priorityFace];
				}
				else
				{
					priorityDepth = -1000;
				}
			}

			while (priority == 3 && priorityDepth > averagePriorityDepthSum3_4)
			{
				order[emitted++] = priorityFaces[priorityFace++];
				if (priorityFace == priorityFaceCount && priorityFaces != priorityFaceLists[11])
				{
					priorityFace = 0;
					priorityFaceCount = priorityFaceCounts[11];
					priorityFaces = priorityFaceLists[11];
					priorityFaceDepths = priority11FaceDepth;
				}
				if (priorityFace < priorityFaceCount)
				{
					priorityDepth = priorityFaceDepths[priorityFace];
				}
				else
				{
					priorityDepth = -1000;
				}
			}

			while (priority == 5 && priorityDepth > averagePriorityDepthSum6_8)
			{
				order[emitted++] = priorityFaces[priorityFace++];
				if (priorityFace == priorityFaceCount && priorityFaces != priorityFaceLists[11])
				{
					priorityFace = 0;
					priorityFaceCount = priorityFaceCounts[11];
					priorityFaces = priorityFaceLists[11];
					priorityFaceDepths = priority11FaceDepth;
				}
				if (priorityFace < priorityFaceCount)
				{
					priorityDepth = priorityFaceDepths[priorityFace];
				}
				else
				{
					priorityDepth = -1000;
				}
			}

			int count = priorityFaceCounts[priority];
			int[] faces = priorityFaceLists[priority];
			for (int i = 0; i < count; i++)
			{
				order[emitted++] = faces[i];
			}
		}

		while (priorityDepth != -1000)
		{
			order[emitted++] = priorityFaces[priorityFace++];
			if (priorityFace == priorityFaceCount && priorityFaces != priorityFaceLists[11])
			{
				priorityFace = 0;
				priorityFaces = priorityFaceLists[11];
				priorityFaceCount = priorityFaceCounts[11];
				priorityFaceDepths = priority11FaceDepth;
			}
			if (priorityFace < priorityFaceCount)
			{
				priorityDepth = priorityFaceDepths[priorityFace];
			}
			else
			{
				priorityDepth = -1000;
			}
		}

		return java.util.Arrays.copyOf(order, emitted);
	}

	/**
	 * One vertex through the client's widget-model transform: yaw the model, push
	 * it to the camera distance, orbit the camera to its pitch, then divide by
	 * depth. Returns screen x, screen y and camera-space depth.
	 */
	private static double[] project(double vx, double vy, double vz,
		double yawSin, double yawCos, double pitchSin, double pitchCos,
		double eyeY, double eyeZ)
	{
		double x = vz * yawSin + vx * yawCos;
		double z = vz * yawCos - vx * yawSin;
		double y = vy;

		y += eyeY;
		z += eyeZ;

		double cy = y * pitchCos - z * pitchSin;
		double cz = y * pitchSin + z * pitchCos;

		// Behind or level with the camera: park it far away rather than divide by
		// zero; such faces are dropped by the depth guard when they are drawn.
		if (cz < 1)
		{
			return new double[]{0, 0, -1};
		}
		return new double[]{x / cz, cy / cz, cz};
	}
}

package com.follower;

/*
 * The loader as it stood before MergingLoader (commit 310760e), kept verbatim as
 * LoaderDiffTest's reference: the same upgrade scenarios must leave the same
 * files, status, errors, rules, trees and log lines with either. Only the
 * package, the imports of the speech classes it shared, Lombok's @Slf4j and
 * @Getter written out (the tests are built without Lombok) and, in
 * DialogLoader, the dialogs-editor marker round getFile differ. Not used by
 * the plugin.
 */

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InputStream;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Loads dialogs.json and reloads it when it changes, exactly as
 * {@link RuleLoader} does for phrases.json - same poll, same defaults-on-first-
 * run, same refusal to replace good content with nothing on a bad read.
 */
@Singleton
public class BeforeDialogLoader
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(BeforeDialogLoader.class);

	public static final String FILE_NAME = "dialogs.json";

	/** The bundled trees as of the last merge, for the three-way. */
	public static final String BASE_FILE = "dialogs-seen.json";

	/** Handled by the node pass rather than as a field of the tree. */
	private static final java.util.Set<String> TREE_FIELDS =
		new java.util.HashSet<>(java.util.Arrays.asList("nodes", "id"));

	/** Lines have their own pass; the id is what we matched on. */
	private static final java.util.Set<String> NODE_FIELDS =
		new java.util.HashSet<>(java.util.Arrays.asList("says", "id"));
	private static final String BUNDLED_DEFAULT = "/com/follower/default-dialogs.json";

	/** The trees 1.4.0 shipped, the base for a file that has none; see RuleLoader. */
	static final String UNRECORDED_BASE = "/com/follower/seen/1.4.0-dialogs.json";

	private static final int SUPPORTED_VERSION = 1;

	private final Gson gson;

	private Map<String, DialogTree> trees = Collections.emptyMap();

	private String status = "not loaded";

	public String getStatus()
	{
		return this.status;
	}

	private List<String> errors = Collections.emptyList();

	public List<String> getErrors()
	{
		return this.errors;
	}

	private Path file;
	private Path baseFile;
	private long lastModified = -1L;
	private long lastSize = -1L;

	@Inject
	public BeforeDialogLoader(Gson gson)
	{
		this.gson = gson;
	}

	public void initialise(Path dataDir)
	{
		initialise(dataDir, false);
	}

	/**
	 * @param mergeDefaults whether to fold newly bundled trees into an
	 * existing file first. The plugin passes true; the test harnesses supply
	 * exact files and pass false through the plain overload.
	 */
	public void initialise(Path dataDir, boolean mergeDefaults)
	{
		file = dataDir.resolve(FILE_NAME);
		baseFile = dataDir.resolve(BASE_FILE);
		if (!Files.exists(file))
		{
			writeDefaults();
		}
		else if (mergeDefaults)
		{
			mergeNewDefaults();
		}
		reload();
	}

	/**
	 * Folds bundled conversation changes into the player's file, three ways.
	 *
	 * <p>The same upgrade gap {@code phrases.json} had, and fixed the same way -
	 * see {@link ThreeWay}. Appending only whole new trees meant a reworded
	 * node, an added choice or a fixed dead end reached nobody who already had
	 * the plugin.
	 *
	 * <p>Trees merge at two levels because that is how they are built: the tree
	 * carries its own fields and a list of nodes, and each node carries its own
	 * fields and its lines. A node the update added arrives, a node it removed
	 * goes unless the player had already changed it, and a node they have
	 * rewritten is theirs.
	 */
	private void mergeNewDefaults()
	{
		try (InputStream in = BeforeDialogLoader.class.getResourceAsStream(BUNDLED_DEFAULT))
		{
			if (in == null)
			{
				return;
			}
			Gson pretty = gson.newBuilder().setPrettyPrinting().disableHtmlEscaping().create();
			com.google.gson.JsonObject bundled = pretty.fromJson(
				new java.io.InputStreamReader(in, java.nio.charset.StandardCharsets.UTF_8),
				com.google.gson.JsonObject.class);
			com.google.gson.JsonObject ours = pretty.fromJson(
				new String(Files.readAllBytes(file), java.nio.charset.StandardCharsets.UTF_8),
				com.google.gson.JsonObject.class);
			if (bundled == null || ours == null
				|| !bundled.has("trees") || !ours.has("trees"))
			{
				return;
			}

			com.google.gson.JsonObject base = readBase(pretty);
			java.util.Map<String, com.google.gson.JsonObject> mine =
				BeforeThreeWay.byId(BeforeThreeWay.array(ours, "trees"));
			java.util.Map<String, com.google.gson.JsonObject> was =
				BeforeThreeWay.byId(BeforeThreeWay.array(base, "trees"));

			com.google.gson.JsonArray trees = ours.getAsJsonArray("trees");
			int added = 0;
			int updated = 0;
			for (com.google.gson.JsonElement element : bundled.getAsJsonArray("trees"))
			{
				String id = BeforeThreeWay.idOf(element);
				if (id == null)
				{
					continue;
				}
				com.google.gson.JsonObject held = mine.get(id);
				if (held == null)
				{
					trees.add(element);
					added++;
					continue;
				}
				if (mergeTree(held, was.get(id), element.getAsJsonObject()) > 0)
				{
					updated++;
				}
			}

			if (added > 0 || updated > 0)
			{
				Files.copy(file, file.resolveSibling(file.getFileName() + ".bak"),
					java.nio.file.StandardCopyOption.REPLACE_EXISTING);
				Files.write(file, (pretty.toJson(ours) + "\n")
					.getBytes(java.nio.charset.StandardCharsets.UTF_8));
			}

			// Last, and whether or not anything moved, so a merge that only
			// half-happened is retried rather than recorded as done.
			writeBase(bundled, pretty);
		}
		catch (Exception e)
		{
			log.warn("Could not merge new defaults into {}", file, e);
		}
	}

	/** One bundled tree, folded into the player's copy of it. */
	private static int mergeTree(com.google.gson.JsonObject held,
		com.google.gson.JsonObject base, com.google.gson.JsonObject bundled)
	{
		if (base == null)
		{
			return bootstrap(held, bundled);
		}

		int changes = BeforeThreeWay.fields(held, base, bundled, TREE_FIELDS);

		com.google.gson.JsonArray nodes = BeforeThreeWay.array(held, "nodes");
		com.google.gson.JsonArray shipped = BeforeThreeWay.array(bundled, "nodes");
		if (nodes == null || shipped == null)
		{
			return changes;
		}
		java.util.Map<String, com.google.gson.JsonObject> wasNodes =
			BeforeThreeWay.byId(BeforeThreeWay.array(base, "nodes"));

		java.util.Set<String> shippedIds = new java.util.HashSet<>();
		for (com.google.gson.JsonElement element : shipped)
		{
			String id = BeforeThreeWay.idOf(element);
			if (id != null)
			{
				shippedIds.add(id);
			}
		}

		// Rebuilt rather than edited in place, because a node can leave.
		java.util.List<com.google.gson.JsonObject> kept = new java.util.ArrayList<>();
		java.util.Set<String> keptIds = new java.util.HashSet<>();
		for (com.google.gson.JsonElement element : nodes)
		{
			if (!element.isJsonObject())
			{
				continue;
			}
			com.google.gson.JsonObject node = element.getAsJsonObject();
			String id = BeforeThreeWay.idOf(element);
			com.google.gson.JsonObject before = id == null ? null : wasNodes.get(id);
			if (id != null && before != null && !shippedIds.contains(id)
				&& before.equals(node))
			{
				// The update removed it and the player never touched it.
				changes++;
				continue;
			}
			kept.add(node);
			if (id != null)
			{
				keptIds.add(id);
			}
		}

		for (com.google.gson.JsonElement element : shipped)
		{
			String id = BeforeThreeWay.idOf(element);
			if (id == null)
			{
				continue;
			}
			com.google.gson.JsonObject now = element.getAsJsonObject();
			if (!keptIds.contains(id))
			{
				// Absent here: new upstream unless the player deleted it, and
				// the base is what tells the two apart.
				if (!wasNodes.containsKey(id))
				{
					kept.add(now);
					changes++;
				}
				continue;
			}
			com.google.gson.JsonObject node = null;
			for (com.google.gson.JsonObject candidate : kept)
			{
				if (id.equals(BeforeThreeWay.idOf(candidate)))
				{
					node = candidate;
					break;
				}
			}
			// A node the base never had is one the player wrote; comparing it
			// with itself leaves it alone, which is the intent.
			com.google.gson.JsonObject before = wasNodes.getOrDefault(id, node);
			changes += BeforeThreeWay.fields(node, before, now, NODE_FIELDS);
			changes += BeforeThreeWay.strings(node, "says", before, now);
		}

		if (changes > 0)
		{
			com.google.gson.JsonArray out = new com.google.gson.JsonArray();
			for (com.google.gson.JsonObject node : kept)
			{
				out.add(node);
			}
			held.add("nodes", out);
		}
		return changes;
	}

	/**
	 * The first run, with no record of what shipped before. As with the rules,
	 * the only honest question left is whether the player has written into
	 * this tree at all: a tree holding nothing but shipped lines has not been,
	 * and can be brought up to date without taking anything from anybody.
	 */
	private static int bootstrap(com.google.gson.JsonObject held,
		com.google.gson.JsonObject bundled)
	{
		if (!BeforeThreeWay.untouched(allSays(held), allSays(bundled)))
		{
			return 0;
		}
		if (held.equals(bundled))
		{
			return 0;
		}
		for (String key : new java.util.ArrayList<>(held.keySet()))
		{
			held.remove(key);
		}
		for (java.util.Map.Entry<String, com.google.gson.JsonElement> entry : bundled.entrySet())
		{
			held.add(entry.getKey(), entry.getValue());
		}
		return 1;
	}

	/** Every line the tree can speak, for the bootstrap's one question. */
	private static java.util.List<String> allSays(com.google.gson.JsonObject tree)
	{
		java.util.List<String> out = new java.util.ArrayList<>();
		com.google.gson.JsonArray nodes = BeforeThreeWay.array(tree, "nodes");
		if (nodes == null)
		{
			return out;
		}
		for (com.google.gson.JsonElement element : nodes)
		{
			if (element.isJsonObject())
			{
				out.addAll(BeforeThreeWay.strings(element.getAsJsonObject(), "says"));
			}
		}
		return out;
	}

	/**
	 * The trees as they shipped at the last merge; for a file that never
	 * merged, the ones 1.4.0 wrote; null only if even that cannot be read.
	 */
	private com.google.gson.JsonObject readBase(Gson pretty)
	{
		if (baseFile == null)
		{
			return null;
		}
		if (!Files.exists(baseFile))
		{
			try (InputStream in = BeforeDialogLoader.class.getResourceAsStream(UNRECORDED_BASE))
			{
				return in == null ? null : pretty.fromJson(
					new java.io.InputStreamReader(in, java.nio.charset.StandardCharsets.UTF_8),
					com.google.gson.JsonObject.class);
			}
			catch (Exception e)
			{
				log.warn("Could not read {}, merging without a base", UNRECORDED_BASE, e);
				return null;
			}
		}
		try
		{
			return pretty.fromJson(new String(Files.readAllBytes(baseFile),
				java.nio.charset.StandardCharsets.UTF_8), com.google.gson.JsonObject.class);
		}
		catch (Exception e)
		{
			log.warn("Could not read {}, merging without a base", baseFile, e);
			return null;
		}
	}

	private void writeBase(com.google.gson.JsonObject bundled, Gson pretty)
	{
		if (baseFile == null)
		{
			return;
		}
		try
		{
			Files.write(baseFile, (pretty.toJson(bundled) + "\n")
				.getBytes(java.nio.charset.StandardCharsets.UTF_8));
		}
		catch (Exception e)
		{
			log.warn("Could not record the merged defaults in {}", baseFile, e);
		}
	}

	public Path getFile()
	{
		return file;
	}

	public DialogTree get(String id)
	{
		return id == null ? null : trees.get(id);
	}

	/** Every tree, in file order. */
	public List<DialogTree> getTrees()
	{
		return new ArrayList<>(trees.values());
	}

	public boolean reloadIfChanged()
	{
		if (file == null || !Files.isRegularFile(file))
		{
			return false;
		}
		try
		{
			long modified = Files.getLastModifiedTime(file).toMillis();
			long size = Files.size(file);
			if (modified == lastModified && size == lastSize)
			{
				return false;
			}
		}
		catch (IOException e)
		{
			return false;
		}
		reload();
		return true;
	}

	public void reload()
	{
		if (file == null)
		{
			return;
		}

		List<String> problems = new ArrayList<>();

		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			DialogFile parsed = gson.fromJson(reader, DialogFile.class);

			if (parsed == null)
			{
				// The same reasoning as phrases.json: an empty read is almost
				// always a poll landing between an editor truncating the file
				// and writing it back. Keep what we had and try again.
				errors = Collections.singletonList(
					"File is empty; keeping " + trees.size() + " previous conversations");
				status = "empty file, keeping " + trees.size() + " previous conversations";
				log.warn("dialogs.json read as empty; keeping the previous trees");
				return;
			}

			lastModified = Files.getLastModifiedTime(file).toMillis();
			lastSize = Files.size(file);

			if (parsed.version != SUPPORTED_VERSION)
			{
				problems.add("version is " + parsed.version
					+ ", plugin expects " + SUPPORTED_VERSION);
			}

			Map<String, DialogTree> valid = new LinkedHashMap<>();
			Set<String> seen = new HashSet<>();
			for (DialogTree tree : parsed.trees == null
				? Collections.<DialogTree>emptyList() : parsed.trees)
			{
				if (tree == null)
				{
					continue;
				}
				List<String> found = tree.problems();
				problems.addAll(found);
				if (!found.isEmpty())
				{
					// A broken tree is left out rather than half-loaded: a
					// conversation that dead-ends mid-branch is worse than one
					// that never opens, because the player is already in it.
					continue;
				}
				if (!seen.add(tree.id))
				{
					problems.add("Duplicate tree id '" + tree.id + "'");
				}
				valid.put(tree.id, tree);
			}

			trees = valid;
			errors = problems;
			status = valid.size() + " conversations"
				+ (problems.isEmpty() ? "" : ", " + problems.size() + " warning(s)");
			// At INFO like the rule loader: when a conversation does not open,
			// the first thing worth knowing is whether it loaded at all.
		}
		catch (IOException e)
		{
			problems.add("Could not read " + file + ": " + e.getMessage());
			errors = problems;
			status = "read error";
		}
		catch (JsonParseException e)
		{
			// Keep the previous trees on a syntax error, as with phrases.json.
			problems.add("JSON error: " + e.getMessage());
			errors = problems;
			status = "syntax error, keeping " + trees.size() + " previous conversations";
			log.warn("dialogs.json failed to parse", e);
		}
	}

	private void writeDefaults()
	{
		try (InputStream in = BeforeDialogLoader.class.getResourceAsStream(BUNDLED_DEFAULT))
		{
			if (in == null)
			{
				log.warn("Bundled {} is missing", BUNDLED_DEFAULT);
				return;
			}
			Files.createDirectories(file.getParent());
			Files.copy(in, file);
		}
		catch (IOException e)
		{
			log.warn("Could not write default dialogs to {}", file, e);
			return;
		}
		// Recorded at once, so the first update merges against what was
		// written rather than against a guess.
		try (InputStream in = BeforeDialogLoader.class.getResourceAsStream(BUNDLED_DEFAULT))
		{
			if (in != null && baseFile != null)
			{
				Files.copy(in, baseFile, java.nio.file.StandardCopyOption.REPLACE_EXISTING);
			}
		}
		catch (IOException e)
		{
			// Only costs the first update a merge against 1.4.0's trees.
			log.warn("Could not record the starter dialogs in {}", baseFile, e);
		}
	}

	private static final class DialogFile
	{
		int version;
		List<DialogTree> trees;
	}
}

package com.follower;

/*
 * GameColourTable as it stood before the chathead renderer consolidation
 * (commit c17bc04), kept verbatim as ColourTableDiffTest and
 * ChatheadDiffTest's reference. Only the package line and this header differ.
 * Not used by the plugin.
 */

/**
 * The client's 65,536-entry colour table, ported line for line from
 * {@code Pix3D.initColourTable}.
 *
 * <p>The game never converts packed HSL to RGB with a formula at draw time: it
 * precomputes this table - a bespoke HSL-to-RGB with half-step hue/saturation
 * offsets, truncating arithmetic, and a gamma curve from the brightness setting
 * (0.8 at the default "Normal") - and rasterises by interpolating the PACKED
 * index across each triangle, looking up the table per pixel. A plain linear
 * HSL conversion produces visibly different tones, which is why the follower's
 * face never quite matched a real chathead's colours.
 *
 * <p>The client also jitters brightness by up to ±0.015 per login; that noise is
 * deliberately omitted for determinism.
 */
public final class BeforeGameColourTable
{
	private static volatile int[] table = build(0.8);
	private static volatile double currentGamma = 0.8;

	private BeforeGameColourTable()
	{
	}

	/** RGB for a packed HSL value, through the game's own table. */
	public static int rgb(int packed)
	{
		return table[packed & 0xFFFF];
	}

	/**
	 * Rebuilds for the player's brightness setting, so the follower's head is on
	 * the SAME gamma table as every real chathead on screen. The setting's varp
	 * maps 1..4 to gammas 0.9, 0.8, 0.7, 0.6 (Dark to V.Bright) in the client.
	 */
	public static void setBrightnessSetting(int varpValue)
	{
		double gamma;
		switch (varpValue)
		{
			case 1:
				gamma = 0.9;
				break;
			case 3:
				gamma = 0.7;
				break;
			case 4:
				gamma = 0.6;
				break;
			case 2:
			default:
				gamma = 0.8;
				break;
		}

		if (gamma != currentGamma)
		{
			currentGamma = gamma;
			table = build(gamma);
		}
	}

	public static double getCurrentGamma()
	{
		return currentGamma;
	}

	private static int[] build(double brightness)
	{
		int[] table = new int[65536];
		int offset = 0;

		for (int y = 0; y < 512; y++)
		{
			double hue = (y / 8) / 64.0 + 0.0078125;
			double saturation = (y & 0x7) / 8.0 + 0.0625;

			for (int x = 0; x < 128; x++)
			{
				double lightness = x / 128.0;
				double r = lightness;
				double g = lightness;
				double b = lightness;

				if (saturation != 0.0)
				{
					double q;
					if (lightness < 0.5)
					{
						q = lightness * (saturation + 1.0);
					}
					else
					{
						q = lightness + saturation - lightness * saturation;
					}

					double p = lightness * 2.0 - q;

					double t = hue + (1.0 / 3.0);
					if (t > 1.0)
					{
						t--;
					}
					double d = hue - (1.0 / 3.0);
					if (d < 0.0)
					{
						d++;
					}

					r = channel(p, q, t);
					g = channel(p, q, hue);
					b = channel(p, q, d);
				}

				int rgb = ((int) (r * 256.0) << 16)
					+ ((int) (g * 256.0) << 8)
					+ (int) (b * 256.0);
				table[offset++] = gammaCorrect(rgb, brightness);
			}
		}
		return table;
	}

	private static double channel(double p, double q, double t)
	{
		if (t * 6.0 < 1.0)
		{
			return p + (q - p) * 6.0 * t;
		}
		if (t * 2.0 < 1.0)
		{
			return q;
		}
		if (t * 3.0 < 2.0)
		{
			return p + (q - p) * ((2.0 / 3.0) - t) * 6.0;
		}
		return p;
	}

	private static int gammaCorrect(int rgb, double gamma)
	{
		double r = (rgb >> 16) / 256.0;
		double g = ((rgb >> 8) & 0xFF) / 256.0;
		double b = (rgb & 0xFF) / 256.0;

		return ((int) (Math.pow(r, gamma) * 256.0) << 16)
			+ ((int) (Math.pow(g, gamma) * 256.0) << 8)
			+ (int) (Math.pow(b, gamma) * 256.0);
	}
}

