				{
					xB -= xStepAB * yB;
					colourB -= colourStepAB * yB;
					yB = 0;
				}
				yA -= yB;
				yB -= yC;
				yC = scanline[yC];
				if (xStepBC < xStepAC)
				{
					while (true)
					{
						yB--;
						if (yB < 0)
						{
							while (true)
							{
								yA--;
								if (yA < 0)
								{
									return;
								}
								gouraudRaster(xB >> 16, xC >> 16, colourB >> 7, colourC >> 7, yC);
								xB += xStepAB;
								xC += xStepAC;
								colourB += colourStepAB;
								colourC += colourStepAC;
								yC += width;
							}
						}
						gouraudRaster(xA >> 16, xC >> 16, colourA >> 7, colourC >> 7, yC);
						xA += xStepBC;
						xC += xStepAC;
						colourA += colourStepBC;
						colourC += colourStepAC;
						yC += width;
					}
				}
				else
				{
					while (true)
					{
						yB--;
						if (yB < 0)
						{
							while (true)
							{
								yA--;
								if (yA < 0)
								{
									return;
								}
								gouraudRaster(xC >> 16, xB >> 16, colourC >> 7, colourB >> 7, yC);
								xB += xStepAB;
								xC += xStepAC;
								colourB += colourStepAB;
								colourC += colourStepAC;
								yC += width;
							}
						}
						gouraudRaster(xC >> 16, xA >> 16, colourC >> 7, colourA >> 7, yC);
						xA += xStepBC;
						xC += xStepAC;
						colourA += colourStepBC;
						colourC += colourStepAC;
						yC += width;
					}
				}
			}
		}
	}

	/**
	 * One scanline, the client's high-detail opaque path: interpolate the packed
	 * palette index from {@code xA} (inclusive) to {@code xB} (exclusive) and
	 * resolve each pixel through the colour table. {@code off} is the row's base
	 * offset (from the scanline table). Alpha is forced opaque for the ARGB
	 * output image - the client's canvas has no alpha channel to set.
	 */
	private void gouraudRaster(int xA, int xB, int colourA, int colourB, int off)
	{
		if (xA >= xB)
		{
			return;
		}
		int colourStep = (colourB - colourA) / (xB - xA);
		if (xB > sizeX)
		{
			xB = sizeX;
		}
		if (xA < 0)
		{
			colourA -= xA * colourStep;
			xA = 0;
		}
		if (xA >= xB)
		{
			return;
		}
		off += xA;
		int len = xB - xA;
		do
		{
			pixels[off++] = 0xFF000000 | BeforeGameColourTable.rgb(colourA >> 8);
			colourA += colourStep;
			len--;
		}
		while (len > 0);
	}
}

package com.follower;

/*
 * LiveCacheParser as it stood before the cache parser consolidation (commit
 * c17bc04), kept verbatim as ParserDiffTest's reference. Only the package
 * line and this header, the imports of ModelRepository and
 * SpotAnimRepository, @Slf4j written out (the tests are built without
 * Lombok), and decodeItem and decodeKit made public, differ. Not used by the
 * plugin.
 */

import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;

/**
 * Parses item, kit and spotanim definitions straight out of the client's own
 * loaded cache ({@link Client#getIndexConfig()}), so the plugin needs no
 * offline dumps: Hub users get the full outfit catalogue and graphic
 * repository the moment the client is running.
 *
 * <p>The opcode logic is a faithful port of runelite-cache's ItemLoader,
 * KitLoader and SpotAnimLoader, transcribed from the library's bytecode and
 * validated in game by diffing every entry against the offline dumper's
 * output ({@code ::follower cachecheck}). Output shapes mirror the dump files
 * exactly, defaults included, so the repositories cannot tell the difference.
 *
 * <p>Every definition parses independently: a malformed or future-format
 * entry is skipped with a note rather than failing the whole catalogue.
 */
public final class BeforeLiveCacheParser
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(BeforeLiveCacheParser.class);

	/** Config-index archive ids (net.runelite.cache.ConfigType). */
	private static final int CONFIG_IDENTKIT = 3;
	private static final int CONFIG_ITEM = 10;
	private static final int CONFIG_SPOTANIM = 13;

	private BeforeLiveCacheParser()
	{
	}

	/** Wearable items keyed by id, matching equipment-models.json's items map. */
	public static Map<String, ModelRepository.Entry> parseItems(Client client)
	{
		IndexDataBase configs = client.getIndexConfig();
		Map<String, ModelRepository.Entry> items = new LinkedHashMap<>();
		if (configs == null)
		{
			return items;
		}
		int failures = 0;
		for (int id : configs.getFileIds(CONFIG_ITEM))
		{
			byte[] data = configs.loadData(CONFIG_ITEM, id);
			if (data == null)
			{
				continue;
			}
			try
			{
				ModelRepository.Entry entry = decodeItem(data);
				if (entry != null)
				{
					items.put(Integer.toString(id), entry);
				}
			}
			catch (RuntimeException e)
			{
				if (failures++ == 0)
				{
					log.warn("Item {} failed to parse (further failures counted silently)", id, e);
				}
			}
		}
		if (failures > 0)
		{
			log.warn("{} item definitions failed to parse", failures);
		}
		return items;
	}

	/** Body kits keyed by id, matching equipment-models.json's kits map. */
	public static Map<String, ModelRepository.Entry> parseKits(Client client)
	{
		return parseKits(client, null);
	}

	/**
	 * @param nonSelectableOut when non-null, receives the ids of kits flagged
	 * non-selectable - the styles character creation does not offer, which is
	 * how the NPC-only and unreleased extras are told apart from real player
	 * styles. Collected on the side so {@link ModelRepository.Entry} keeps the
	 * dump file's exact shape and {@code ::follower cachecheck} stays honest.
	 */
	public static Map<String, ModelRepository.Entry> parseKits(Client client,
		java.util.Set<Integer> nonSelectableOut)
	{
		IndexDataBase configs = client.getIndexConfig();
		Map<String, ModelRepository.Entry> kits = new LinkedHashMap<>();
		if (configs == null)
		{
			return kits;
		}
		for (int id : configs.getFileIds(CONFIG_IDENTKIT))
		{
			byte[] data = configs.loadData(CONFIG_IDENTKIT, id);
			if (data == null)
			{
				continue;
			}
			try
			{
				boolean[] nonSelectable = new boolean[1];
				ModelRepository.Entry entry = decodeKit(data, nonSelectable);
				if (entry != null)
				{
					kits.put(Integer.toString(id), entry);
					if (nonSelectable[0] && nonSelectableOut != null)
					{
						nonSelectableOut.add(id);
					}
				}
			}
			catch (RuntimeException e)
			{
			}
		}
		return kits;
	}

	/** Spotanims keyed by id, matching spotanims.json. */
	public static Map<String, SpotAnimRepository.Entry> parseSpotAnims(Client client)
	{
		IndexDataBase configs = client.getIndexConfig();
		Map<String, SpotAnimRepository.Entry> spotAnims = new LinkedHashMap<>();
		if (configs == null)
		{
			return spotAnims;
		}
		int failures = 0;
		for (int id : configs.getFileIds(CONFIG_SPOTANIM))
		{
			byte[] data = configs.loadData(CONFIG_SPOTANIM, id);
			if (data == null)
			{
				continue;
			}
			try
			{
				SpotAnimRepository.Entry entry = decodeSpotAnim(data);
				if (entry != null)
				{
					spotAnims.put(Integer.toString(id), entry);
				}
			}
			catch (RuntimeException e)
			{
				if (failures++ == 0)
				{
					log.warn("Spotanim {} failed to parse: {}", id, e.getMessage());
				}
			}
		}
		if (failures > 0)
		{
			log.warn("{} spotanim definitions failed to parse", failures);
		}
		return spotAnims;
	}

	// ------------------------------------------------------------------ items

	/**
	 * ItemLoader's opcode walk. Only the fields the follower needs are kept,
	 * but EVERY opcode must be consumed at its exact width or the stream
	 * desynchronises and the rest of the definition parses as garbage.
	 */
	public static ModelRepository.Entry decodeItem(byte[] data)
	{
		Buffer in = new Buffer(data);
		// The cache's convention for an unnamed item is the literal string
		// "null" (the definition's constructor default), and the dumper
		// preserved it - so the live parse must too.
		String name = "null";
		int maleModel0 = -1;
		int maleModel1 = -1;
		int maleModel2 = -1;
		int femaleModel0 = -1;
		int femaleModel1 = -1;
		int femaleModel2 = -1;
		int maleOffset = 0;
		int femaleOffset = 0;
		int maleHead = -1;
		int maleHead2 = -1;
		int femaleHead = -1;
		int femaleHead2 = -1;
		int wearPos1 = -1;
		int wearPos2 = -1;
		int wearPos3 = -1;
		short[] colorFind = null;
		short[] colorReplace = null;
		short[] textureFind = null;
		short[] textureReplace = null;

		for (int opcode = in.readUnsignedByte(); opcode != 0; opcode = in.readUnsignedByte())
		{
			switch (opcode)
			{
				case 1:
					in.readUnsignedShort(); // inventory model
					break;
				case 2:
					name = in.readString();
					break;
				case 3:
				case 9:
					in.readString(); // examine / unknown1
					break;
				case 4:
				case 5:
				case 6:
				case 7:
				case 8:
					in.readUnsignedShort(); // 2d zoom/rotation/offsets
					break;
				case 11:
				case 15:
				case 16:
				case 65:
				case 160:
				case 251:
					break; // flag opcodes carry no payload
				case 12:
					in.readInt(); // cost
					break;
				case 13:
					wearPos1 = in.readByte();
					break;
				case 14:
					wearPos2 = in.readByte();
					break;
				case 23:
					maleModel0 = in.readUnsignedShort();
					maleOffset = in.readUnsignedByte();
					break;
				case 24:
					maleModel1 = in.readUnsignedShort();
					break;
				case 25:
					femaleModel0 = in.readUnsignedShort();
					femaleOffset = in.readUnsignedByte();
					break;
				case 26:
					femaleModel1 = in.readUnsignedShort();
					break;
				case 27:
					wearPos3 = in.readByte();
					break;
				case 30:
				case 31:
				case 32:
				case 33:
				case 34:
				case 35:
				case 36:
				case 37:
				case 38:
				case 39:
					in.readString(); // ground / interface actions
					break;
				case 40:
				{
					int count = in.readUnsignedByte();
					colorFind = new short[count];
					colorReplace = new short[count];
					for (int i = 0; i < count; i++)
					{
						colorFind[i] = (short) in.readUnsignedShort();
						colorReplace[i] = (short) in.readUnsignedShort();
					}
					break;
				}
				case 41:
				{
					int count = in.readUnsignedByte();
					textureFind = new short[count];
					textureReplace = new short[count];
					for (int i = 0; i < count; i++)
					{
						textureFind[i] = (short) in.readUnsignedShort();
						textureReplace[i] = (short) in.readUnsignedShort();
					}
					break;
				}
				case 42:
					in.readByte(); // shift-click drop index
					break;
				case 43:
					// Menu subops: group byte, then (index byte, string) pairs
					// terminated by a zero index byte.
					in.readUnsignedByte();
					while (in.readUnsignedByte() != 0)
					{
						in.readString();
					}
					break;
				case 44:
					in.readInt(); // large inventory model
					break;
				case 45:
					maleModel0 = in.readInt();
					maleOffset = in.readUnsignedByte();
					break;
				case 46:
					maleModel1 = in.readInt();
					break;
				case 47:
					maleModel2 = in.readInt();
					break;
				case 48:
					femaleModel0 = in.readInt();
					femaleOffset = in.readUnsignedByte();
					break;
				case 49:
					femaleModel1 = in.readInt();
					break;
				case 50:
					femaleModel2 = in.readInt();
					break;
				case 51:
					maleHead = in.readInt();
					break;
				case 52:
					maleHead2 = in.readInt();
					break;
				case 53:
					femaleHead = in.readInt();
					break;
				case 54:
					femaleHead2 = in.readInt();
					break;
				case 75:
					in.readShort(); // weight
					break;
				case 78:
					maleModel2 = in.readUnsignedShort();
					break;
				case 79:
					femaleModel2 = in.readUnsignedShort();
					break;
				case 90:
					maleHead = in.readUnsignedShort();
					break;
				case 91:
					femaleHead = in.readUnsignedShort();
					break;
				case 92:
					maleHead2 = in.readUnsignedShort();
					break;
				case 93:
					femaleHead2 = in.readUnsignedShort();
					break;
				case 94:
				case 95:
				case 97:
				case 98:
				case 99:
				case 110:
				case 111:
				case 112:
				case 139:
				case 140:
				case 148:
				case 149:
					in.readUnsignedShort(); // category/noted/resize/links
					break;
				case 100:
				case 101:
				case 102:
				case 103:
				case 104:
				case 105:
				case 106:
				case 107:
				case 108:
				case 109:
					in.readUnsignedShort(); // stack count variant
					in.readUnsignedShort();
					break;
				case 113:
				case 114:
					in.readByte(); // ambient / contrast
					break;
				case 115:
					in.readUnsignedByte(); // team
					break;
				case 161:
					for (int count = in.readUnsignedShort(); count > 0; count--)
					{
						in.readUnsignedShort(); // holding whitelist
					}
					break;
				case 200:
					// EntityOpsLoader.decodeSubOp: byte, byte, string.
					in.readUnsignedByte();
					in.readUnsignedByte();
					in.readString();
					break;
				case 201:
					// decodeConditionalOp: byte, short, short, int, int, string.
					in.readUnsignedByte();
					in.readUnsignedShort();
					in.readUnsignedShort();
					in.readInt();
					in.readInt();
					in.readString();
					break;
				case 202:
					// decodeConditionalSubOp: byte, 3x short, int, int, string.
					in.readUnsignedByte();
					in.readUnsignedShort();
					in.readUnsignedShort();
					in.readUnsignedShort();
					in.readInt();
					in.readInt();
					in.readString();
					break;
				case 249:
					in.skipParams();
					break;
				default:
					throw new IllegalStateException("unknown item opcode " + opcode);
			}
		}

		// Mirror the dumper's wearable filter: only items with a worn model.
		if (maleModel0 == -1 && femaleModel0 == -1)
		{
			return null;
		}

		ModelRepository.Entry entry = new ModelRepository.Entry();
		entry.n = name;
		entry.mo = maleOffset;
		entry.fo = femaleOffset;
		entry.wp1 = wearPos1;
		entry.wp2 = wearPos2;
		entry.wp3 = wearPos3;
		entry.m = new int[]{maleModel0, maleModel1, maleModel2};
		entry.f = new int[]{femaleModel0, femaleModel1, femaleModel2};
		if (maleHead != -1 || maleHead2 != -1)
		{
			entry.hm = new int[]{maleHead, maleHead2};
		}
		if (femaleHead != -1 || femaleHead2 != -1)
		{
			entry.hf = new int[]{femaleHead, femaleHead2};
		}
		entry.cf = colorFind;
		entry.cr = colorReplace;
		entry.tf = textureFind;
		entry.tr = textureReplace;
		return entry;
	}

	// ------------------------------------------------------------------- kits

	public static ModelRepository.Entry decodeKit(byte[] data, boolean[] nonSelectableOut)
	{
		Buffer in = new Buffer(data);
		Integer bodyPartId = null;
		int[] models = null;
		int[] chatheads = {-1, -1, -1, -1, -1};
		short[] recolorFind = null;
		short[] recolorReplace = null;
		short[] retextureFind = null;
		short[] retextureReplace = null;

		for (int opcode = in.readUnsignedByte(); opcode != 0; opcode = in.readUnsignedByte())
		{
			if (opcode == 1)
			{
				bodyPartId = in.readUnsignedByte();
			}
			else if (opcode == 2)
			{
				int count = in.readUnsignedByte();
				models = new int[count];
				for (int i = 0; i < count; i++)
				{
					models[i] = in.readUnsignedShort();
				}
			}
			else if (opcode == 3)
			{
				// Flagged non-selectable: character creation never offers this
				// style. No payload.
				nonSelectableOut[0] = true;
			}
			else if (opcode == 5)
			{
				int count = in.readUnsignedByte();
				models = new int[count];
				for (int i = 0; i < count; i++)
				{
					models[i] = in.readInt();
				}
			}
			else if (opcode == 40)
			{
				int count = in.readUnsignedByte();
				recolorFind = new short[count];
				recolorReplace = new short[count];
				for (int i = 0; i < count; i++)
				{
					// NOTE: signed shorts here, unlike items and spotanims.
					recolorFind[i] = (short) in.readShort();
					recolorReplace[i] = (short) in.readShort();
				}
			}
			else if (opcode == 41)
			{
				int count = in.readUnsignedByte();
				retextureFind = new short[count];
				retextureReplace = new short[count];
				for (int i = 0; i < count; i++)
				{
					retextureFind[i] = (short) in.readShort();
					retextureReplace[i] = (short) in.readShort();
				}
			}
			else if (opcode >= 60 && opcode < 70)
			{
				chatheads[opcode - 60] = in.readUnsignedShort();
			}
			else if (opcode >= 70 && opcode < 80)
			{
				chatheads[opcode - 70] = in.readInt();
			}
			else
			{
				throw new IllegalStateException("unknown kit opcode " + opcode);
			}
		}

		// Mirror the dumper's filter: kits without models are unusable.
		if (models == null || models.length == 0)
		{
			return null;
		}

		ModelRepository.Entry entry = new ModelRepository.Entry();
		entry.bp = bodyPartId;
		entry.m = models;
		entry.f = models;
		boolean anyHead = false;
		for (int head : chatheads)
		{
			anyHead |= head != -1;
		}
		if (anyHead)
		{
			entry.ch = chatheads;
		}
		entry.cf = recolorFind;
		entry.cr = recolorReplace;
		entry.tf = retextureFind;
		entry.tr = retextureReplace;
		return entry;
	}

	// -------------------------------------------------------------- spotanims

	private static SpotAnimRepository.Entry decodeSpotAnim(byte[] data)
	{
		Buffer in = new Buffer(data);
		int modelId = 0;
		int animationId = -1;
		int resizeX = 128;
		int resizeY = 128;
		int rotation = 0;
		int ambient = 0;
		int contrast = 0;
		short[] recolorFind = null;
		short[] recolorReplace = null;
		short[] retextureFind = null;
		short[] retextureReplace = null;

		for (int opcode = in.readUnsignedByte(); opcode != 0; opcode = in.readUnsignedByte())
		{
			switch (opcode)
			{
				case 1:
					modelId = in.readUnsignedShort();
					break;
				case 2:
					animationId = in.readUnsignedShort();
					break;
				case 3:
					modelId = in.readInt();
					break;
				case 4:
					resizeX = in.readUnsignedShort();
					break;
				case 5:
					resizeY = in.readUnsignedShort();
					break;
				case 6:
					rotation = in.readUnsignedShort();
					break;
				case 7:
					ambient = in.readUnsignedByte();
					break;
				case 8:
					contrast = in.readUnsignedByte();
					break;
				case 9:
					in.readString(); // debug name
					break;
				case 10:
					// A newer flag opcode with NO payload - proven empirically:
					// the offline dumper's library ignores unknown opcodes
					// without consuming bytes, and every affected definition
					// (39 of them, ids 3882+) still dumped perfectly clean.
					break;
				case 40:
				{
					int count = in.readUnsignedByte();
					recolorFind = new short[count];
					recolorReplace = new short[count];
					for (int i = 0; i < count; i++)
					{
						recolorFind[i] = (short) in.readUnsignedShort();
						recolorReplace[i] = (short) in.readUnsignedShort();
					}
					break;
				}
				case 41:
				{
					int count = in.readUnsignedByte();
					retextureFind = new short[count];
					retextureReplace = new short[count];
					for (int i = 0; i < count; i++)
					{
						retextureFind[i] = (short) in.readUnsignedShort();
						retextureReplace[i] = (short) in.readUnsignedShort();
					}
					break;
				}
				case 42:
					in.readUnsignedShort(); // full recolour
					break;
				default:
					throw new IllegalStateException("unknown spotanim opcode " + opcode);
			}
		}

		// Mirror the dumper's filter: a spotanim without a model shows nothing.
		if (modelId <= 0)
		{
			return null;
		}

		SpotAnimRepository.Entry entry = new SpotAnimRepository.Entry();
		entry.m = modelId;
		entry.a = animationId;
		entry.rx = resizeX == 128 ? null : resizeX;
		entry.ry = resizeY == 128 ? null : resizeY;
		entry.rot = rotation == 0 ? null : rotation;
		entry.am = ambient == 0 ? null : ambient;
		entry.co = contrast == 0 ? null : contrast;
		entry.cf = recolorFind;
		entry.cr = recolorReplace;
		entry.tf = retextureFind;
		entry.tr = retextureReplace;
		return entry;
	}

	// ----------------------------------------------------------------- buffer

	/** Minimal big-endian reader matching runelite-cache's InputStream widths. */
	private static final class Buffer
	{
		private final byte[] data;
		private int offset;

		Buffer(byte[] data)
		{
			this.data = data;
		}

		int readUnsignedByte()
		{
			return data[offset++] & 0xFF;
		}

		int readByte()
		{
			return data[offset++];
		}

		int readUnsignedShort()
		{
			return (readUnsignedByte() << 8) | readUnsignedByte();
		}

		int readShort()
		{
			return (short) readUnsignedShort();
		}

		int read24BitInt()
		{
			return (readUnsignedByte() << 16) | (readUnsignedByte() << 8) | readUnsignedByte();
		}

		int readInt()
		{
			return (readUnsignedByte() << 24) | (readUnsignedByte() << 16)
				| (readUnsignedByte() << 8) | readUnsignedByte();
		}

		/**
		 * A 0-terminated string. Only item NAMES are kept, and those are
		 * plain CP1252; the special-character remapping the cache library
		 * applies affects codepoints 128-159, which item names do not use -
		 * anything in that range maps through the same table here for parity.
		 */
		String readString()
		{
			StringBuilder sb = new StringBuilder();
			for (int b = readUnsignedByte(); b != 0; b = readUnsignedByte())
			{
				if (b >= 128 && b < 160)
				{
					char mapped = CP1252_SPECIALS[b - 128];
					sb.append(mapped == 0 ? '?' : mapped);
				}
				else
				{
					sb.append((char) b);
				}
			}
			return sb.toString();
		}

		/** Skips a params map: count, then (isString byte, 24-bit key, value). */
		void skipParams()
		{
			int count = readUnsignedByte();
			for (int i = 0; i < count; i++)
			{
				boolean isString = readUnsignedByte() == 1;
				read24BitInt();
				if (isString)
				{
					readString();
				}
				else
				{
					readInt();
				}
			}
		}
	}

	/** Windows-1252's 0x80-0x9F block, as the cache text format defines it. */
	private static final char[] CP1252_SPECIALS = {
		'€', 0, '‚', 'ƒ', '„', '…', '†', '‡',
		'ˆ', '‰', 'Š', '‹', 'Œ', 0, 'Ž', 0,
		0, '‘', '’', '“', '”', '•', '–', '—',
		'˜', '™', 'š', '›', 'œ', 0, 'ž', 'Ÿ',
	};
}

package com.follower;

/*
 * Outfit as it stood before the Outfit consolidation (commit c17bc04), kept
 * verbatim as OutfitDiffTest's reference. Only the package line and this
 * header differ. Not used by the plugin.
 */

import java.util.Arrays;
import net.runelite.api.PlayerComposition;
import net.runelite.api.kit.KitType;

/**
 * The follower's appearance, stored in the same encoding the game uses for
 * {@link PlayerComposition#getEquipmentIds()}:
 *
 * <pre>
 *   0                     empty slot
 *   {@value #KIT_OFFSET} + kitId    a body kit (torso, arms, hair, ...)
 *   {@value #ITEM_OFFSET} + itemId  an equipped item
 * </pre>
 *
 * Slot order is {@link KitType#getIndex()}: HEAD, CAPE, AMULET, WEAPON, TORSO,
 * SHIELD, ARMS, LEGS, HAIR, HANDS, BOOTS, JAW.
 */
public final class BeforeOutfit
{
	/**
	 * Internal encoding offsets, spaced so the kit and item ranges cannot collide.
	 * The game encoding is produced and consumed only at the boundary, in
	 * {@link #toGameEquipmentIds()} and {@link #from(PlayerComposition)}.
	 */
	public static final int KIT_OFFSET = 1 << 20;
	public static final int ITEM_OFFSET = 1 << 21;
	public static final int SLOTS = 12;

	/**
	 * The game's own offsets, used only when talking to PlayerComposition: a slot
	 * holds {@code 0} for empty, {@code 256 + kitId} for a kit, and
	 * {@code 2048 + itemId} for an item.
	 *
	 * <p>The item offset is 2048, not 512. That leaves kit ids room to run up to
	 * 1791, which they need - hair and jaw kits are past 300. With 512 here, kit 305
	 * encoded to 561, which reads back as item 49, and every kit above 255 was
	 * silently corrupted in both directions: live compositions decoded into
	 * nonexistent items, and the capture path swapped garbage into the player.
	 */
	private static final int GAME_KIT_OFFSET = PlayerComposition.KIT_OFFSET;
	private static final int GAME_ITEM_OFFSET = PlayerComposition.ITEM_OFFSET;

	/**
	 * Default identikit ids, used to fill body slots the outfit leaves empty so
	 * the follower isn't a floating head. These are the standard character
	 * creation kits; if your dump shows different ids, adjust here.
	 */
	private static final int[][] DEFAULT_KITS_MALE = {
		{KitType.HAIR.getIndex(), 0},
		// The jaw kit is facial geometry, not merely a beard - without one the head
		// renders incomplete, so both genders always get a default.
		{KitType.JAW.getIndex(), 10},
		{KitType.TORSO.getIndex(), 18},
		{KitType.ARMS.getIndex(), 26},
		{KitType.HANDS.getIndex(), 33},
		{KitType.LEGS.getIndex(), 36},
		{KitType.BOOTS.getIndex(), 42},
	};

	private static final int[][] DEFAULT_KITS_FEMALE = {
		{KitType.HAIR.getIndex(), 45},
		// Female jaw kits are 292-306 with their own distinct models. They only ever
		// looked broken because ids above 255 overflowed the old slot encoding.
		{KitType.JAW.getIndex(), 292},
		{KitType.TORSO.getIndex(), 56},
		{KitType.ARMS.getIndex(), 61},
		{KitType.HANDS.getIndex(), 67},
		{KitType.LEGS.getIndex(), 70},
		{KitType.BOOTS.getIndex(), 79},
	};

	private final int[] equipment = new int[SLOTS];
	private final int[] colors = new int[5];
	private int gender;

	/**
	 * The slots that hold an animation's own hand props, a bit per slot index.
	 * The game lays an animation's hand items over the gear once the gear has
	 * settled what it covers, so nothing hides them and they hide nothing.
	 */
	private int props;

	public BeforeOutfit()
	{
	}

	public BeforeOutfit(BeforeOutfit other)
	{
		copyFrom(other);
	}

	public static BeforeOutfit from(PlayerComposition composition)
	{
		BeforeOutfit outfit = new BeforeOutfit();
		if (composition == null)
		{
			return outfit;
		}

		int[] ids = composition.getEquipmentIds();
		if (ids != null)
		{
			for (int i = 0; i < Math.min(ids.length, SLOTS); i++)
			{
				int raw = ids[i];
				if (raw >= GAME_ITEM_OFFSET)
				{
					outfit.equipment[i] = ITEM_OFFSET + (raw - GAME_ITEM_OFFSET);
				}
				else if (raw >= GAME_KIT_OFFSET)
				{
					outfit.equipment[i] = KIT_OFFSET + (raw - GAME_KIT_OFFSET);
				}
				else
				{
					outfit.equipment[i] = 0;
				}
			}
		}
		outfit.setColors(composition.getColors());
		outfit.setGender(composition.getGender());
		return outfit;
	}

	public int getRaw(KitType slot)
	{
		return equipment[slot.getIndex()];
	}

	public void setItem(KitType slot, int itemId)
	{
		equipment[slot.getIndex()] = itemId <= 0 ? 0 : ITEM_OFFSET + itemId;
	}

	public void setKit(KitType slot, int kitId)
	{
		equipment[slot.getIndex()] = kitId < 0 ? 0 : KIT_OFFSET + kitId;
	}

	public void clear(KitType slot)
	{
		equipment[slot.getIndex()] = 0;
	}

	/**
	 * An animation's hand prop in a slot, drawn as the game draws one: over the
	 * gear, whatever the gear covers, and covering nothing itself.
	 */
	public void setProp(KitType slot, int itemId)
	{
		setItem(slot, itemId);
		props |= 1 << slot.getIndex();
	}

	/** Whether the slot holds an animation's hand prop. */
	public boolean isProp(KitType slot)
	{
		return (props & 1 << slot.getIndex()) != 0;
	}

	public boolean isItem(KitType slot)
	{
		return equipment[slot.getIndex()] >= ITEM_OFFSET;
	}

	public boolean isKit(KitType slot)
	{
		int v = equipment[slot.getIndex()];
		return v >= KIT_OFFSET && v < ITEM_OFFSET;
	}

	public int itemId(KitType slot)
	{
		return equipment[slot.getIndex()] - ITEM_OFFSET;
	}

	public int kitId(KitType slot)
	{
		return equipment[slot.getIndex()] - KIT_OFFSET;
	}

	public int getGender()
	{
		return gender;
	}

	public void setGender(int gender)
	{
		this.gender = gender == 1 ? 1 : 0;
	}

	public int[] getColors()
	{
		return colors.clone();
	}

	public void setColors(int[] source)
	{
		if (source != null)
		{
			System.arraycopy(source, 0, colors, 0, Math.min(source.length, colors.length));
		}
	}

	public void copyFrom(BeforeOutfit other)
	{
		System.arraycopy(other.equipment, 0, equipment, 0, SLOTS);
		System.arraycopy(other.colors, 0, colors, 0, colors.length);
		gender = other.gender;
		props = other.props;
	}

	/**
	 * Returns a copy with empty body slots filled by default kits. Item slots and
	 * already-populated kit slots are untouched, so gear always wins.
	 */
	public BeforeOutfit withDefaultBody()
	{
		BeforeOutfit filled = new BeforeOutfit(this);

		// Every body kit is filled here, including ones the gear will cover. Which of
		// them actually render is decided at compose time from each item's wearPos
		// data, the same way the game does it - a platebody hides the arms but a
		// chainbody does not, and only the item itself knows which it is. Deciding
		// that here, by slot type alone, stripped the arms under every torso item.
		for (int[] pair : (gender == 1 ? DEFAULT_KITS_FEMALE : DEFAULT_KITS_MALE))
		{
			if (pair[1] >= 0 && filled.equipment[pair[0]] == 0)
			{
				filled.equipment[pair[0]] = KIT_OFFSET + pair[1];
			}
		}
		return filled;
	}

	public boolean isEmpty()
	{
		for (int v : equipment)
		{
			if (v != 0)
			{
				return false;
			}
		}
		return true;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof BeforeOutfit))
		{
			return false;
		}
		BeforeOutfit other = (BeforeOutfit) o;
		// A prop shows where the same item worn might be hidden, so it is another model.
		return gender == other.gender
			&& props == other.props
			&& Arrays.equals(equipment, other.equipment)
			&& Arrays.equals(colors, other.colors);
	}

	@Override
	public int hashCode()
	{
		return 31 * (31 * (31 * Arrays.hashCode(equipment) + Arrays.hashCode(colors)) + gender) + props;
	}

	@Override
	public String toString()
	{
		StringBuilder sb = new StringBuilder();
		for (KitType slot : KitType.values())
		{
			int v = getRaw(slot);
			if (v == 0)
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(slot.name()).append('=')
				.append(v >= ITEM_OFFSET ? "item:" + (v - ITEM_OFFSET) : "kit:" + (v - KIT_OFFSET));
		}

		if (gender == 1)
		{
			sb.append(sb.length() > 0 ? "," : "").append("gender=female");
		}

		// Body-colour indices into the game's palette tables; the parser already
		// reads this key, but until 2026-08-02 nothing wrote it, so panel-chosen
		// indices silently vanished on every save.
		boolean anyColor = false;
		for (int c : colors)
		{
			if (c != 0)
			{
				anyColor = true;
				break;
			}
		}
		if (anyColor)
		{
			sb.append(sb.length() > 0 ? "," : "").append("colors=");
			for (int i = 0; i < colors.length; i++)
			{
				if (i > 0)
				{
					sb.append('/');
				}
				sb.append(colors[i]);
			}
		}

		return sb.toString();
	}
}

package com.follower;

/*
 * The loader as it stood before MergingLoader (commit 310760e), kept verbatim as
 * LoaderDiffTest's reference: the same upgrade scenarios must leave the same
 * files, status, errors, rules, trees and log lines with either. Only the
 * package, the imports of the speech classes it shared, Lombok's @Slf4j and
 * @Getter written out (the tests are built without Lombok) and, in
 * DialogLoader, the dialogs-editor marker round getFile differ. Not used by
 * the plugin.
 */

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InputStream;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Loads phrases.json and reloads it when the file changes on disk, so you can edit
 * rules with the client running. Change detection is a lastModified/size poll
 * driven from the game tick — a WatchService buys nothing here and brings its own
 * platform quirks.
 */
@Singleton
public class BeforeRuleLoader
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(BeforeRuleLoader.class);

	/** Fields the three-way must not touch: lines have their own pass. */
	private static final Set<String> SETTLED_BY_HAND =
		new HashSet<>(java.util.Arrays.asList("say", "id"));

	/** The bundled defaults as of the last merge, for the three-way. */
	public static final String BASE_FILE = "defaults-seen.json";

	/**
	 * Beside the base: the bundled rules' checksum and the player's file as
	 * the last merge left them. When neither has changed the merge would do
	 * nothing, and it re-read three large files and rewrote the base, 70-100
	 * ms of every start on the Swing thread (perf audit, Oct 2026).
	 */
	static final String MERGE_STAMP = "defaults-seen.stamp";

	public static final String FILE_NAME = "phrases.json";
	private static final String BUNDLED_DEFAULT = "/com/follower/default-phrases.json";

	/**
	 * The rules 1.4.0 shipped, a base for some files that have none; see
	 * {@link #unrecordedBase}.
	 */
	static final String UNRECORDED_BASE = "/com/follower/seen/1.4.0-phrases.json";

	private final Gson gson;

	private List<SpeechRule> rules = Collections.emptyList();

	public List<SpeechRule> getRules()
	{
		return this.rules;
	}
	private java.util.Set<String> bossNames = Collections.emptySet();
	private Path baseFile;

	private String status = "not loaded";

	public String getStatus()
	{
		return this.status;
	}

	private List<String> errors = Collections.emptyList();

	public List<String> getErrors()
	{
		return this.errors;
	}

	/**
	 * Whether any loaded rule uses the event-driven varbitChanged condition.
	 * Varbit changes arrive in floods (thousands at login), and dispatching
	 * each through every rule is pure waste when nothing listens - the
	 * state-based varbitEquals rules evaluate on the tick heartbeat instead.
	 */
	private boolean varbitEventRules;

	public boolean isVarbitEventRules()
	{
		return this.varbitEventRules;
	}

	private Path file;
	private long lastModified = -1L;
	private long lastSize = -1L;

	@Inject
	public BeforeRuleLoader(Gson gson)
	{
		this.gson = gson;
	}

	/**
	 * Points the loader at the data directory, writing the bundled default rules if
	 * no file exists yet, then loads.
	 */
	public void initialise(Path dataDir)
	{
		initialise(dataDir, false);
	}

	/**
	 * @param mergeDefaults whether to fold newly bundled rules into an
	 * existing file first. The plugin passes true; the test harnesses supply
	 * exact files and pass false through the plain overload.
	 */
	public void initialise(Path dataDir, boolean mergeDefaults)
	{
		file = dataDir.resolve(FILE_NAME);
		baseFile = dataDir.resolve(BASE_FILE);

		if (!Files.exists(file))
		{
			writeDefaults();
		}
		else if (mergeDefaults)
		{
			mergeNewDefaults();
		}

		reload();
	}

	/**
	 * Folds bundled changes into the player's file, three ways.
	 *
	 * <p>The old merge only ever APPENDED rules the file had never seen, which
	 * fixed the tester whose file predated the mimic rules and left a bigger
	 * hole behind it: a change to an existing rule reached nobody. Retuning the
	 * examine echo from 30% every three minutes to 70% every thirty, and
	 * writing twenty lines for it, changed nothing at all for anybody who
	 * already had the plugin - the work shipped and stayed invisible.
	 *
	 * <p>It could not be fixed by simply copying more across, because two
	 * situations look identical from the user's file alone: a line the update
	 * ADDED, and a line the player DELETED. Both are lines the bundled file has
	 * and theirs does not. Copying blindly resurrects everything anybody has
	 * ever removed.
	 *
	 * <p>So the defaults are kept as they stood at the last merge, in
	 * {@value #BASE_FILE}, and the question becomes answerable: bundled against
	 * BASE says what the update did, and theirs against base says what the
	 * player did. Upstream's changes are taken where the player has not touched
	 * that field, and the player wins everywhere they have. A line missing from
	 * theirs but present in base was deleted on purpose and stays gone; one
	 * that is in bundled but not in base is genuinely new and arrives.
	 *
	 * <p>Rules the editor deleted are recorded in the file's "removed" list and
	 * stay deleted. The file as it stood is kept beside the merged one as
	 * phrases.json.bak, and new nickname hooks arrive as before, as do new
	 * place names - existing keys are the user's to keep.
	 */
	private void mergeNewDefaults()
	{
		try (InputStream in = BeforeRuleLoader.class.getResourceAsStream(BUNDLED_DEFAULT))
		{
			if (in == null)
			{
				return;
			}
			byte[] shipped = in.readAllBytes();
			Path stampFile = file.resolveSibling(MERGE_STAMP);
			if (Files.exists(stampFile) && mergeStamp(shipped).equals(
				new String(Files.readAllBytes(stampFile), StandardCharsets.UTF_8)))
			{
				return;
			}
			Gson pretty = gson.newBuilder().setPrettyPrinting().disableHtmlEscaping().create();
			com.google.gson.JsonObject bundled = pretty.fromJson(
				new String(shipped, StandardCharsets.UTF_8),
				com.google.gson.JsonObject.class);
			com.google.gson.JsonObject ours = pretty.fromJson(
				new String(Files.readAllBytes(file), StandardCharsets.UTF_8),
				com.google.gson.JsonObject.class);
			if (bundled == null || ours == null
				|| !bundled.has("rules") || !ours.has("rules"))
			{
				return;
			}

			// The record of what shipped last time, or for a file that never
			// merged, what can be told of where it came from. A rule missing
			// from it is judged by mergeRule without one.
			com.google.gson.JsonObject base = readBase(pretty);
			if (base == null)
			{
				base = unrecordedBase(pretty, ours);
			}

			Set<String> known = new HashSet<>();
			for (com.google.gson.JsonElement element : ours.getAsJsonArray("rules"))
			{
				String id = idOf(element);
				if (id != null)
				{
					known.add(id);
				}
			}
			if (ours.has("removed") && ours.get("removed").isJsonArray())
			{
				for (com.google.gson.JsonElement element : ours.getAsJsonArray("removed"))
				{
					if (element.isJsonPrimitive())
					{
						known.add(element.getAsString());
					}
				}
			}

			Map<String, com.google.gson.JsonObject> mine = byId(ours);
			Map<String, com.google.gson.JsonObject> was = byId(base);

			com.google.gson.JsonArray rules = ours.getAsJsonArray("rules");
			int added = 0;
			int updated = 0;
			for (com.google.gson.JsonElement element : bundled.getAsJsonArray("rules"))
			{
				String id = idOf(element);
				if (id == null || !element.isJsonObject())
				{
					continue;
				}
				if (!known.contains(id))
				{
					rules.add(element);
					added++;
					continue;
				}
				com.google.gson.JsonObject held = mine.get(id);
				// Absent but known means the editor deleted it; it stays deleted.
				if (held != null
					&& mergeRule(held, was.get(id), element.getAsJsonObject()) > 0)
				{
					updated++;
				}
			}

			// A rule the update dropped goes too, as a dropped line does,
			// unless the player has changed it: then it is theirs now.
			Set<String> stillShipped = byId(bundled).keySet();
			int dropped = 0;
			for (java.util.Iterator<com.google.gson.JsonElement> it = rules.iterator(); it.hasNext(); )
			{
				com.google.gson.JsonElement element = it.next();
				String id = idOf(element);
				if (id != null && !stillShipped.contains(id) && element.equals(was.get(id)))
				{
					it.remove();
					dropped++;
				}
			}


			int placesAdded = 0;
			if (bundled.has("places") && bundled.get("places").isJsonObject())
			{
				com.google.gson.JsonObject held =
					ours.has("places") && ours.get("places").isJsonObject()
						? ours.getAsJsonObject("places") : new com.google.gson.JsonObject();
				for (Map.Entry<String, com.google.gson.JsonElement> entry
					: bundled.getAsJsonObject("places").entrySet())
				{
					if (!held.has(entry.getKey()))
					{
						held.add(entry.getKey(), entry.getValue());
						placesAdded++;
					}
				}
				ours.add("places", held);
			}

			if (added > 0 || updated > 0 || dropped > 0 || placesAdded > 0)
			{
				Files.copy(file, file.resolveSibling(file.getFileName() + ".bak"),
					java.nio.file.StandardCopyOption.REPLACE_EXISTING);
				Files.write(file,
					(pretty.toJson(ours) + "\n").getBytes(StandardCharsets.UTF_8));
			}

			// Written whether or not anything moved, and last, so a merge that
			// half-happened is retried rather than recorded as done. From here
			// on there is a base and the guessing above never runs again.
			if (writeBase(bundled, pretty))
			{
				Files.write(stampFile, mergeStamp(shipped).getBytes(StandardCharsets.UTF_8));
			}
		}
		catch (Exception e)
		{
			// A file that cannot be merged is one reload() will complain about
			// in its own words; do not block startup over it.
			log.warn("Could not merge new defaults into {}", file, e);
		}
	}

	/**
	 * Folds one bundled rule into the player's copy.
	 *
	 * @param base the rule as it was bundled at the last merge, or null when
	 * there is no record - see the bootstrap below
	 * @return how many changes were made, so the caller can count rules
	 */
	private static int mergeRule(com.google.gson.JsonObject held,
		com.google.gson.JsonObject base, com.google.gson.JsonObject bundled)
	{
		if (base == null)
		{
			return bootstrap(held, bundled);
		}

		return BeforeThreeWay.fields(held, base, bundled, SETTLED_BY_HAND)
			+ BeforeThreeWay.strings(held, "say", base, bundled);
	}

	/**
	 * A rule with no record of what shipped before: one the base does not
	 * hold, which for a file with no record is most of what
	 * {@link #unrecordedBase} leaves out.
	 *
	 * <p>Nothing can be deduced about deletions, so the only honest signal left
	 * is whether the player has written into the rule at all. If every line in
	 * their copy is one that ships, they have not - and taking the bundled rule
	 * is right, which is how a year of tuning finally reaches them. If they
	 * have added anything the rule is theirs and is left exactly alone this
	 * once; the base written afterwards makes every later merge exact.
	 *
	 * <p>{@code enabled} is the player's either way. Switching a rule off is a
	 * decision made in the editor and adopting over it would turn it back on.
	 */
	private static int bootstrap(com.google.gson.JsonObject held,
		com.google.gson.JsonObject bundled)
	{
		if (!BeforeThreeWay.untouched(BeforeThreeWay.strings(held, "say"),
			BeforeThreeWay.strings(bundled, "say")))
		{
			return 0;
		}
		com.google.gson.JsonElement enabled = held.get("enabled");
		int before = BeforeThreeWay.strings(held, "say").size();
		for (String key : new java.util.ArrayList<>(held.keySet()))
		{
			held.remove(key);
		}
		for (Map.Entry<String, com.google.gson.JsonElement> entry : bundled.entrySet())
		{
			held.add(entry.getKey(), entry.getValue());
		}
		if (enabled != null)
		{
			held.add("enabled", enabled);
		}
		return BeforeThreeWay.strings(held, "say").size() == before && before > 0 ? 0 : 1;
	}

	private static Map<String, com.google.gson.JsonObject> byId(com.google.gson.JsonObject file)
	{
		return BeforeThreeWay.byId(BeforeThreeWay.array(file, "rules"));
	}

	/**
	 * A base for a file with no record, as far as its origin can be told.
	 *
	 * <p>Up to 1.4.0 a fresh install wrote its starter file without recording
	 * it, and the record only arrived with the next start's merge, which
	 * guessed; so a file started just once reaches this version with none, and
	 * guessing puts back the lines its player deleted. A file that holds every
	 * rule 1.4.0 shipped was written by 1.4.0 or 1.3.0, which shipped the same
	 * rules, and each of its rules that still matches 1.4.0 outside its lines
	 * and its switch is judged against 1.4.0: a deleted line stays deleted. The
	 * rest are left out, to mergeRule's guess, which brings an untouched rule up
	 * to date: 1.3.0's two rules that 1.4.0 retuned, and every rule of a file
	 * older than 1.3.0, which lacks rules 1.4.0 added. Null when nothing fits.
	 */
	private com.google.gson.JsonObject unrecordedBase(Gson pretty, com.google.gson.JsonObject ours)
	{
		com.google.gson.JsonObject shipped;
		try (InputStream in = BeforeRuleLoader.class.getResourceAsStream(UNRECORDED_BASE))
		{
			if (in == null)
			{
				return null;
			}
			shipped = pretty.fromJson(new java.io.InputStreamReader(in, StandardCharsets.UTF_8),
				com.google.gson.JsonObject.class);
		}
		catch (Exception e)
		{
			log.warn("Could not read {}, merging without a base", UNRECORDED_BASE, e);
			return null;
		}

		Map<String, com.google.gson.JsonObject> mine = byId(ours);
		Set<String> known = new HashSet<>(mine.keySet());
		if (ours.has("removed") && ours.get("removed").isJsonArray())
		{
			for (com.google.gson.JsonElement element : ours.getAsJsonArray("removed"))
			{
				if (element.isJsonPrimitive())
				{
					known.add(element.getAsString());
				}
			}
		}
		com.google.gson.JsonArray kept = new com.google.gson.JsonArray();
		for (com.google.gson.JsonElement element : shipped.getAsJsonArray("rules"))
		{
			String id = idOf(element);
			if (id == null || !known.contains(id))
			{
				// Older than 1.3.0: the guess serves it as it always did.
				return null;
			}
			com.google.gson.JsonObject held = mine.get(id);
			if (held != null && sameOutsideLines(held, element.getAsJsonObject()))
			{
				kept.add(element);
			}
		}
		com.google.gson.JsonObject base = new com.google.gson.JsonObject();
		base.add("rules", kept);
		return base;
	}

	/** Whether two copies of a rule differ only in their lines and whether it is on. */
	private static boolean sameOutsideLines(com.google.gson.JsonObject a, com.google.gson.JsonObject b)
	{
		com.google.gson.JsonObject x = a.deepCopy();
		com.google.gson.JsonObject y = b.deepCopy();
		for (String key : new String[]{"say", "enabled"})
		{
			x.remove(key);
			y.remove(key);
		}
		return x.equals(y);
	}

	/** What a merge depends on: the bundled rules, the player's file, and that there is a base. */
	private String mergeStamp(byte[] shipped) throws IOException
	{
		java.util.zip.CRC32 crc = new java.util.zip.CRC32();
		crc.update(shipped);
		return crc.getValue() + " " + Files.size(file) + " " + Files.getLastModifiedTime(file)
			+ " " + Files.exists(baseFile);
	}

	/** The defaults as they stood at the last merge, or null if never written. */
	private com.google.gson.JsonObject readBase(Gson pretty)
	{
		if (baseFile == null || !Files.exists(baseFile))
		{
			return null;
		}
		try
		{
			return pretty.fromJson(
				new String(Files.readAllBytes(baseFile), StandardCharsets.UTF_8),
				com.google.gson.JsonObject.class);
		}
		catch (Exception e)
		{
			// Unreadable is the same as absent: fall back to the bootstrap
			// rather than refusing to merge at all.
			log.warn("Could not read {}, merging without a base", baseFile, e);
			return null;
		}
	}

	private boolean writeBase(com.google.gson.JsonObject bundled, Gson pretty)
	{
		if (baseFile == null)
		{
			return false;
		}
		try
		{
			Files.write(baseFile,
				(pretty.toJson(bundled) + "\n").getBytes(StandardCharsets.UTF_8));
			return true;
		}
		catch (Exception e)
		{
			// Only costs a repeat of the bootstrap next start, which is
			// idempotent, so it is not worth failing the merge over.
			log.warn("Could not record the merged defaults in {}", baseFile, e);
			return false;
		}
	}

	private static String idOf(com.google.gson.JsonElement element)
	{
		if (!element.isJsonObject())
		{
			return null;
		}
		com.google.gson.JsonElement id = element.getAsJsonObject().get("id");
		return id != null && id.isJsonPrimitive() ? id.getAsString() : null;
	}

	public Path getFile()
	{
		return file;
	}

	/** Reloads if the file changed since last check. Returns true if rules were replaced. */
	public boolean reloadIfChanged()
	{
		if (file == null || !Files.isRegularFile(file))
		{
			return false;
		}

		try
		{
			long modified = Files.getLastModifiedTime(file).toMillis();
			long size = Files.size(file);
			if (modified == lastModified && size == lastSize)
			{
				return false;
			}
		}
		catch (IOException e)
		{
			return false;
		}

		reload();
		return true;
	}

	public void reload()
	{
		if (file == null)
		{
			return;
		}

		List<String> problems = new ArrayList<>();

		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			RuleFile parsed = gson.fromJson(reader, RuleFile.class);

			if (parsed == null)
			{
				// An empty read is almost never an empty file on purpose. It is
				// what a poll sees in the instant between an editor truncating
				// the file and writing it back, and it is what a failed save
				// leaves behind. Treating it as "no rules" replaced the whole
				// personality with silence, which is exactly what the syntax
				// error path below is careful NOT to do. Keep what we had, say
				// so, and do not record this read as current - the next poll
				// then picks up the finished file.
				problems.add("File is empty; keeping " + rules.size() + " previous rules");
				errors = problems;
				status = "empty file, keeping " + rules.size() + " previous rules";
				log.warn("phrases.json read as empty; keeping the previous rules");
				return;
			}

			lastModified = Files.getLastModifiedTime(file).toMillis();
			lastSize = Files.size(file);

			if (parsed.version != RuleFile.SUPPORTED_VERSION)
			{
				problems.add("version is " + parsed.version + ", plugin expects " + RuleFile.SUPPORTED_VERSION);
			}

			List<SpeechRule> valid = new ArrayList<>();
			Set<String> seenIds = new HashSet<>();
			int index = 0;

			for (SpeechRule rule : parsed.rules == null ? Collections.<SpeechRule>emptyList() : parsed.rules)
			{
				index++;
				if (rule == null)
				{
					continue;
				}

				if (rule.id == null || rule.id.trim().isEmpty())
				{
					rule.id = "rule-" + index;
				}
				if (!seenIds.add(rule.id))
				{
					problems.add("Duplicate rule id '" + rule.id + "' - the later one wins for cooldowns");
				}
				if (!rule.isValid())
				{
					problems.add("Rule '" + rule.id + "' needs a 'when' block and at least one of"
						+ " a non-empty 'say' list, an 'animation', or 'mirrorAnimation'");
					continue;
				}
				if (rule.group == null || rule.group.trim().isEmpty())
				{
					rule.group = "misc";
				}

				rule.reset();
				valid.add(rule);
			}

			valid.sort((a, b) -> Integer.compare(b.priority, a.priority));
			filePlaces = parsed.places == null
				? Collections.<Integer, String>emptyMap() : parsed.places;
			apply(valid, problems, valid.size() + " rules");
		}
		catch (IOException e)
		{
			problems.add("Could not read " + file + ": " + e.getMessage());
			apply(Collections.emptyList(), problems, "read error");
		}
		catch (JsonParseException e)
		{
			// Keep the previous rules on a syntax error; losing your follower's whole
			// personality over a trailing comma is worse than running stale rules.
			problems.add("JSON error: " + e.getMessage());
			errors = problems;
			status = "syntax error, keeping " + rules.size() + " previous rules";
			log.warn("phrases.json failed to parse", e);
		}
	}


	/**
	 * Which condition type answers which event. Only the types that are gated
	 * on a specific event appear: a state condition (healthBelow, inRegion) can
	 * be true during ANY dispatch and so is never listed.
	 */
	private static final Map<TriggerEvent.Type, String[]> EVENT_CONDITIONS;

	static
	{
		EVENT_CONDITIONS = new EnumMap<>(TriggerEvent.Type.class);
		EVENT_CONDITIONS.put(TriggerEvent.Type.NPC_SPAWN, new String[]{"npcSpawn"});
		EVENT_CONDITIONS.put(TriggerEvent.Type.NPC_DESPAWN, new String[]{"npcDespawn"});
		EVENT_CONDITIONS.put(TriggerEvent.Type.VARBIT, new String[]{"varbitChanged"});
		// Busy scenes fire NPC overheads constantly; same economics as spawns.
		EVENT_CONDITIONS.put(TriggerEvent.Type.NPC_SHOUT, new String[]{"npcShout"});
	}

	private final Set<TriggerEvent.Type> listened = EnumSet.noneOf(TriggerEvent.Type.class);

	/**
	 * Whether any loaded rule can answer this kind of event.
	 *
	 * <p>Only meaningful for the FLOOD events - NPCs entering and leaving the
	 * scene, and varbits at login - which arrive in the hundreds within a single
	 * tick and each cost a pass over every rule. Everything else is rare enough
	 * that asking is not worth it.
	 *
	 * <p>Skipping a pass costs nothing a state rule needed: state only changes
	 * when the snapshot refreshes, once a tick, and the tick heartbeat always
	 * gets its own dispatch. It does mean a {@code chance} roll no longer
	 * happens per despawn, which is a fix rather than a loss - how talkative the
	 * follower is should not depend on how many NPCs happen to be wandering out
	 * of view.
	 */
	public boolean listensFor(TriggerEvent.Type type)
	{
		return !EVENT_CONDITIONS.containsKey(type) || listened.contains(type);
	}

	/** The rules with an npcSpawn condition somewhere in them. */
	private List<SpeechRule> spawnRules = Collections.emptyList();

	/**
	 * Whether any rule's npcSpawn names this NPC. A wave of spawns is a pass
	 * over every rule for each NPC, 5-12 ms in one frame for a busy area
	 * (perf audit, Oct 2026); a spawn no rule names can make true nothing the
	 * next tick would not, for the reason {@link #listensFor} gives.
	 */
	public boolean answersSpawn(TriggerEvent spawn)
	{
		for (SpeechRule rule : spawnRules)
		{
			if (rule.when.answersSpawn(spawn))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The NPC names the boss rules name, which is what the rest of the plugin
	 * means by "boss" - see {@link com.follower.speech.TriggerContext#isBoss}.
	 * Collected here because this is where the rules are already walked, and
	 * because the rule file is the only place the list should live.
	 */
	public java.util.Set<String> getBossNames()
	{
		return bossNames;
	}

	/**
	 * Region id to place name, read off the Locations rules: the first
	 * sentence of each area rule's note, for every region it names. The
	 * Memory window shows these beside the bare ids so "Region 12850" reads
	 * as Lumbridge. Only rules with a note contribute; an id no rule names is
	 * simply absent.
	 */
	public Map<Integer, String> getRegionNames()
	{
		return regionNames;
	}

	private Map<Integer, String> regionNames = Collections.emptyMap();

	/** The file's own place names, for regions no area rule names: its "places". */
	private Map<Integer, String> filePlaces = Collections.emptyMap();

	private static void collectRegionNames(SpeechRule rule, Map<Integer, String> into)
	{
		if (rule.when == null || rule.when.regions == null
			|| rule.note == null || rule.note.trim().isEmpty())
		{
			return;
		}
		String type = rule.when.type == null ? "" : rule.when.type.toLowerCase(java.util.Locale.ROOT);
		if (!type.equals("inregion") && !type.equals("regionenter"))
		{
			return;
		}
		String name = rule.note.trim();
		int stop = name.indexOf(". ");
		if (stop > 0)
		{
			name = name.substring(0, stop);
		}
		else if (name.endsWith("."))
		{
			name = name.substring(0, name.length() - 1);
		}
		for (Integer region : rule.when.regions)
		{
			if (region != null)
			{
				into.putIfAbsent(region, name);
			}
		}
	}

	/** Each region an area rule's "all" stands in, by the rule's title up to its comma, where nothing names it yet. */
	private static void collectTitledRegionNames(SpeechRule rule, Map<Integer, String> into)
	{
		if (rule.when == null || rule.when.conditions == null || rule.title == null
			|| !"all".equalsIgnoreCase(rule.when.type))
		{
			return;
		}
		int comma = rule.title.indexOf(',');
		String name = (comma > 0 ? rule.title.substring(0, comma) : rule.title).trim();
		for (Condition part : rule.when.conditions)
		{
			if (part != null && part.regions != null && !name.isEmpty()
				&& ("inregion".equalsIgnoreCase(part.type) || "regionenter".equalsIgnoreCase(part.type)))
			{
				for (Integer region : part.regions)
				{
					if (region != null)
					{
						into.putIfAbsent(region, name);
					}
				}
			}
		}
	}

	private void collectBossNames(Condition condition, java.util.Set<String> into)
	{
		if (condition == null)
		{
			return;
		}
		if (condition.type != null
			&& condition.type.toLowerCase(java.util.Locale.ROOT).startsWith("npc")
			&& condition.names != null)
		{
			into.addAll(condition.names);
		}
		if (condition.conditions != null)
		{
			for (Condition sub : condition.conditions)
			{
				collectBossNames(sub, into);
			}
		}
	}

	private void apply(List<SpeechRule> newRules, List<String> problems, String summary)
	{
		rules = newRules;
		errors = problems;

		java.util.Set<String> bosses = new java.util.HashSet<>();
		Map<Integer, String> places = new java.util.HashMap<>();
		for (SpeechRule rule : newRules)
		{
			if ("boss".equalsIgnoreCase(rule.group))
			{
				collectBossNames(rule.when, bosses);
			}
			else if ("area".equalsIgnoreCase(rule.group))
			{
				collectRegionNames(rule, places);
			}
		}
		// Then the places only a rule with more to it names, by its title:
		// "The Abyss, after Enter the Abyss". Behaviour QA5, 19 Oct: a death
		// in the Abyss had no place to be filed in.
		for (SpeechRule rule : newRules)
		{
			if ("area".equalsIgnoreCase(rule.group))
			{
				collectTitledRegionNames(rule, places);
			}
		}
		// And the places no rule stands in, named in the file itself: the
		// essence mine, the Wizards' Tower basement (speech QA5 #23).
		for (Map.Entry<Integer, String> place : filePlaces.entrySet())
		{
			if (place.getKey() != null && place.getValue() != null)
			{
				places.putIfAbsent(place.getKey(), place.getValue());
			}
		}
		bossNames = bosses;
		regionNames = places;

		listened.clear();
		for (Map.Entry<TriggerEvent.Type, String[]> entry : EVENT_CONDITIONS.entrySet())
		{
			for (SpeechRule rule : newRules)
			{
				if (rule.when == null)
				{
					continue;
				}
				for (String conditionType : entry.getValue())
				{
					if (rule.when.usesType(conditionType))
					{
						listened.add(entry.getKey());
						break;
					}
				}
			}
		}
		varbitEventRules = listened.contains(TriggerEvent.Type.VARBIT);
		List<SpeechRule> spawning = new ArrayList<>();
		for (SpeechRule rule : newRules)
		{
			if (rule.uses("npcSpawn"))
			{
				spawning.add(rule);
			}
		}
		spawnRules = spawning;

		status = summary + (problems.isEmpty() ? "" : ", " + problems.size() + " warning(s)");
	}

	private void writeDefaults()
	{
		try (InputStream in = BeforeRuleLoader.class.getResourceAsStream(BUNDLED_DEFAULT))
		{
			if (in == null)
			{
				log.warn("Bundled default rules missing from jar");
				return;
			}
			Files.createDirectories(file.getParent());
			Files.copy(in, file);
		}
		catch (IOException e)
		{
			log.warn("Could not write default rules to {}", file, e);
			return;
		}
		// Recorded at once, so the first update merges against what was
		// written rather than against a guess.
		try (InputStream in = BeforeRuleLoader.class.getResourceAsStream(BUNDLED_DEFAULT))
		{
			if (in != null && baseFile != null)
			{
				Files.copy(in, baseFile, java.nio.file.StandardCopyOption.REPLACE_EXISTING);
			}
		}
		catch (IOException e)
		{
			// Only costs the first update a merge against 1.4.0's defaults.
			log.warn("Could not record the starter rules in {}", baseFile, e);
		}
	}
}

package com.follower;

/*
 * The loader as it stood before MergingLoader (commit 310760e), kept verbatim as
 * LoaderDiffTest's reference: the same upgrade scenarios must leave the same
 * files, status, errors, rules, trees and log lines with either. Only the
 * package, the imports of the speech classes it shared, Lombok's @Slf4j and
 * @Getter written out (the tests are built without Lombok) and, in
 * DialogLoader, the dialogs-editor marker round getFile differ. Not used by
 * the plugin.
 */

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * Folding an update into a file somebody has been editing.
 *
 * <p>Both the rules and the conversation trees ship with defaults, get edited,
 * and then have to receive the next version without losing the editing. Doing
 * that needs three copies rather than two, because from the player's file alone
 * a line the update ADDED and a line the player DELETED look identical - both
 * are lines the bundled file has and theirs does not. Keep the defaults as they
 * stood at the last merge and the question becomes answerable: bundled against
 * base is what the update did, theirs against base is what the player did.
 *
 * <p>The rule throughout is that upstream wins where the player has not touched
 * something, and the player wins everywhere they have. This is one class rather
 * than two copies because the two loaders drifting apart on a question this
 * subtle would be a bug nobody would find by reading either one.
 */
public final class BeforeThreeWay
{
	private BeforeThreeWay()
	{
	}

	/**
	 * Every field except the named ones. A field the update did not change is
	 * left alone; one the player changed is theirs; the rest take the update's
	 * value, or go if the update dropped them.
	 *
	 * @return how many fields moved
	 */
	public static int fields(JsonObject held, JsonObject base, JsonObject bundled,
		Set<String> except)
	{
		int changes = 0;
		Set<String> keys = new LinkedHashSet<>(bundled.keySet());
		keys.addAll(base.keySet());
		for (String key : keys)
		{
			if (except.contains(key))
			{
				continue;
			}
			JsonElement before = base.get(key);
			JsonElement now = bundled.get(key);
			if (Objects.equals(before, now))
			{
				// The update has nothing to offer here.
				continue;
			}
			if (!Objects.equals(held.get(key), before))
			{
				// The player moved it. A tuned cooldown or a reworded note is
				// a decision, not a stale copy.
				continue;
			}
			if (now == null)
			{
				held.remove(key);
			}
			else
			{
				held.add(key, now);
			}
			changes++;
		}
		return changes;
	}

	/**
	 * An array of strings, merged as a set with a history. What the update
	 * added arrives; what it removed goes, unless the player had already
	 * removed it; everything else - their own lines, their own rewordings - is
	 * left exactly where it is. A list the player never touched takes the
	 * update's whole, in the update's order: a dialog node's lines are said in
	 * order, and a reworded first line appended at the end had the follower
	 * say "Lead on." before its answer (dialogue check, 14 Oct).
	 *
	 * @return how many lines moved
	 */
	public static int strings(JsonObject held, String key, JsonObject base, JsonObject bundled)
	{
		if (!held.has(key) || !held.get(key).isJsonArray())
		{
			return 0;
		}
		List<String> shipped = strings(bundled, key);
		Set<String> was = new HashSet<>(strings(base, key));
		Set<String> now = new HashSet<>(shipped);
		int changes = 0;

		List<String> mine = strings(held, key);
		if (base != null && mine.equals(strings(base, key)) && !mine.equals(shipped))
		{
			for (String line : was)
			{
				changes += now.contains(line) ? 0 : 1;
			}
			for (String line : now)
			{
				changes += was.contains(line) ? 0 : 1;
			}
			JsonArray out = new JsonArray();
			for (String line : shipped)
			{
				out.add(line);
			}
			held.add(key, out);
			return Math.max(changes, 1);
		}

		List<String> kept = new ArrayList<>();
		for (String line : strings(held, key))
		{
			if (was.contains(line) && !now.contains(line))
			{
				changes++;
				continue;
			}
			kept.add(line);
		}
		for (String line : shipped)
		{
			if (!was.contains(line) && !kept.contains(line))
			{
				kept.add(line);
				changes++;
			}
		}
		if (changes > 0)
		{
			JsonArray out = new JsonArray();
			for (String line : kept)
			{
				out.add(line);
			}
			held.add(key, out);
		}
		return changes;
	}

	/** The strings under a key, or empty. */
	public static List<String> strings(JsonObject object, String key)
	{
		List<String> out = new ArrayList<>();
		if (object != null && object.has(key) && object.get(key).isJsonArray())
		{
			for (JsonElement element : object.getAsJsonArray(key))
			{
				if (element.isJsonPrimitive())
				{
					out.add(element.getAsString());
				}
			}
		}
		return out;
	}

	/**
	 * Whether the player has written anything of their own here.
	 *
	 * <p>The only question the first run can honestly ask. With no base there
	 * is no way to tell a deletion from an addition, but a file holding
	 * nothing but shipped lines has plainly not been written into, and can be
	 * brought up to date without taking anything away from anybody.
	 */
	public static boolean untouched(List<String> theirs, List<String> shipped)
	{
		Set<String> known = new HashSet<>(shipped);
		for (String line : theirs)
		{
			if (!known.contains(line))
			{
				return false;
			}
		}
		return true;
	}

	/** The objects of an array, by their {@code id}. */
	public static Map<String, JsonObject> byId(JsonArray array)
	{
		Map<String, JsonObject> map = new HashMap<>();
		if (array == null)
		{
			return map;
		}
		for (JsonElement element : array)
		{
			String id = idOf(element);
			if (id != null)
			{
				map.put(id, element.getAsJsonObject());
			}
		}
		return map;
	}

	public static JsonArray array(JsonObject object, String key)
	{
		return object != null && object.has(key) && object.get(key).isJsonArray()
			? object.getAsJsonArray(key) : null;
	}

	public static String idOf(JsonElement element)
	{
		if (element == null || !element.isJsonObject())
		{
			return null;
		}
		JsonElement id = element.getAsJsonObject().get("id");
		return id != null && id.isJsonPrimitive() ? id.getAsString() : null;
	}
}

package com.follower;

import java.nio.file.Path;
import java.util.ArrayList;
