	/** Checkal and Marley went to Nardah with Willow; each has a line there once the quest is seen done. */
	@Test
	public void theGangInNardah() throws Exception
	{
		for (String who : new String[]{"Checkal", "Marley"})
		{
			QuestSim s = new QuestSim(folder.newFolder().toPath(), 6000);
			s.witnessed(Quest.BELOW_ICE_MOUNTAIN);
			s.at(3446, 2903, 0);
			s.npc(who, 3447, 2903, 0);
			s.ticks(20);
			assertTrue(s.transcript(), s.heardIds.contains("fun-" + who.toLowerCase() + "-after-below-ice-mountain"));
		}
	}

	/**
	 * Barronite in the ruins, once the quest is seen done: a line now and
	 * then, and none for any other rock. Only that line, and its chance a
	 * certainty, past the gap after the arrival line: the test is of what it
	 * is said for. Left to its 2%, its first rise could land in another
	 * line's gap, be held, and spend its three-hour cooldown (agility QA5's
	 * baseline run, 20 Oct).
	 */
	@Test
	public void barroniteIsMinedForTheForge() throws Exception
	{
		QuestSim seen = onlyTheBarroniteLine();
		seen.h.engine.getContext().setWork(true, "mining", "Barronite rocks", null, 20, 3, 1);
		seen.ticks(5);
		assertTrue(seen.transcript(), seen.heardIds.contains("fun-camdozaal-mining-after-below-ice-mountain"));

		QuestSim copper = onlyTheBarroniteLine();
		copper.h.engine.getContext().setWork(true, "mining", "Copper rocks", null, 20, 3, 1);
		copper.ticks(600);
		assertFalse(copper.transcript(), copper.heardIds.contains("fun-camdozaal-mining-after-below-ice-mountain"));
	}

	private QuestSim onlyTheBarroniteLine() throws Exception
	{
		QuestSim s = new QuestSim(folder.newFolder().toPath(), 6000);
		for (SpeechRule rule : s.h.loader.getRules())
		{
			if (!rule.id.equals("fun-camdozaal-mining-after-below-ice-mountain"))
			{
				rule.enabled = Boolean.FALSE;
				continue;
			}
			for (Condition condition : rule.when.conditions)
			{
				if ("chance".equals(condition.type))
				{
					assertEquals("the shipped chance", Integer.valueOf(2), condition.percent);
					condition.percent = 100;
				}
			}
		}
		s.witnessed(Quest.BELOW_ICE_MOUNTAIN);
		s.at(2924, 5814, 0);
		s.ticks(20);
		return s;
	}
}

package com.follower;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.PlayerComposition;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The borrowed tool: taken through the prop hands, given back with or
 * without a beat, never left in hand by an abort, and never fighting the
 * scroll for the weapon slot.
 */
public class BorrowTest
{
	/** Records what it was asked; does none of it. */
	private static final class RecordingFollower extends FollowerEntity
	{
		final List<Integer> animations = new ArrayList<>();
		boolean staying;
		boolean following = true;
		int poseOverride;

		RecordingFollower()
		{
			super(null, null);
		}

		@Override
		public void playAnimation(int id)
		{
			animations.add(id);
		}

		@Override
		public void stayHere()
		{
			staying = true;
			following = false;
		}

		@Override
		public void resumeFollowing()
		{
			staying = false;
			following = true;
		}

		@Override
		public void setPoseOverride(int id)
		{
			poseOverride = id;
		}

		@Override
		public WorldPoint getWorldLocation()
		{
			return new WorldPoint(3222, 3218, 0);
		}
	}

	/** The plugin's hands, in miniature: one prop slot, and honest about it. */
	private final class FakeHands implements ErrandController.Hands
	{
		int held;

		/** Items the cache has no wear position for; the real hands decline them. */
		Set<Integer> unwearable = new HashSet<>();

		@Override
		public void hold(int itemId)
		{
			if (unwearable.contains(itemId))
			{
				return;
			}
			held = itemId;
		}

		/** The left hand's thing of a pair, the quill; 0 when none. */
		int heldLeft;

		@Override
		public void hold(int leftItemId, int rightItemId)
		{
			heldLeft = leftItemId;
			held = rightItemId;
		}

		@Override
		public void release()
		{
			held = 0;
			heldLeft = 0;
		}

		@Override
		public boolean isHolding()
		{
			return held != 0;
		}

		int worn;

		@Override
		public void wear(int itemId)
		{
			if (!unwearable.contains(itemId))
			{
				worn = itemId;
			}
		}

		@Override
		public void takeOff()
		{
			worn = 0;
		}

		@Override
		public boolean isWearing()
		{
			return worn != 0;
		}
	}

	private RecordingFollower follower;
	private FakeHands hands;
	private Borrow borrow;

	@Before
	public void setUp()
	{
		follower = new RecordingFollower();
		hands = new FakeHands();
		borrow = new Borrow(follower, hands);
	}

	@Test
	public void startTakesTheToolThroughTheHands()
	{
		assertTrue(borrow.start(1351));
		assertTrue(borrow.isHolding());
		assertEquals(1351, borrow.heldItem());
		assertEquals(1351, hands.held);
	}

	@Test
	public void farmingBorrowsTheToolTheWorkWants()
	{
		Set<Integer> none = new HashSet<>();
		assertEquals("a rake to rake", 5341, Borrow.toolFor("farming", 2273, none));
		assertEquals("a dibber to plant", 5343, Borrow.toolFor("farming", 2291, none));
		assertEquals("bare hands to pick", 0, Borrow.toolFor("farming", 2282, none));
		assertEquals("secateurs when the work is not one we know", 5329,
			Borrow.toolFor("farming", -1, none));
		assertTrue(Borrow.farmingWork(2273));
		assertFalse("a bite to eat is not farming", Borrow.farmingWork(829));
	}

	@Test
	public void aSwapChangesTheToolAndNothingEmptiesTheHand()
	{
		assertTrue(borrow.start(5341));
		borrow.swap(5343);
		assertEquals(5343, hands.held);
		assertEquals(5343, borrow.heldItem());
		borrow.swap(0);
		assertEquals("bare hands", 0, hands.held);
		assertFalse(borrow.isHolding());
		borrow.swap(5341);
		assertEquals(5341, hands.held);

		// Set down under the scroll, the hand is not the swap's to change; the
		// loan is, so the right tool is the one that comes back.
		assertTrue(borrow.setAside());
		hands.hold(ErrandController.QUILL_PROP, ErrandController.SCROLL_PROP);
		borrow.swap(5343);
		assertEquals("the scroll untouched", ErrandController.SCROLL_PROP, hands.held);
		assertEquals("and the quill", ErrandController.QUILL_PROP, hands.heldLeft);
		hands.release();
		borrow.takeBack();
		assertEquals("the dibber back, not the rake", 5343, hands.held);

		// And nothing to come back when the work turned bare-handed meanwhile.
		assertTrue(borrow.setAside());
		borrow.swap(0);
		borrow.takeBack();
		assertEquals(0, hands.held);
		assertFalse(borrow.isHolding());
	}

