package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * A boss gets its own send-off, not the one every fight gets.
 *
 * <p>combat-end and kill-boss-celebrate are different EVENTS, so priority
 * never compares them and both used to fire. The celebration also carries a
 * deliberate 13 to 16 tick delay so the ward can wind down first, which meant
 * a boss was seen off with "Well fought" and then congratulated properly eight
 * seconds later, in that order. The generic line now stands aside.
 */
public class BossGetsItsOwnSendOffTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private Harness fightWith(String name) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().setBossNames(h.loader.getBossNames());
		h.dispatch(TriggerEvent.combat(TriggerEvent.Type.COMBAT_END, name));
		h.gameTicks(3);
		return h;
	}

	@Test
	public void anOrdinaryFightStillGetsTheGenericLine() throws IOException
	{
		assertEquals("the send-off every fight gets",
			1, fightWith("Guard").firedBy("combat-end").size());
	}

	@Test
	public void aBossDoesNotGetTheGenericLine() throws IOException
	{
		assertTrue("a boss has its own send-off and does not want talking over",
			fightWith("Brutus").firedBy("combat-end").isEmpty());
	}

	@Test
	public void theBossListIsWhatDecidesIt() throws IOException
	{
		// Named in a boss rule, so it counts however small it fights.
		assertTrue(fightWith("Vorkath").firedBy("combat-end").isEmpty());
		// Not named anywhere, so it is an ordinary fight.
		assertEquals(1, fightWith("Giant rat").firedBy("combat-end").size());
	}
}

package com.follower;

import com.google.gson.Gson;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * A boss is not a combat level.
 *
 * <p>It was one, in two places that had to be kept agreeing by hand: the
 * spectating shield asked whether the thing being fought was level 100, and
 * the kill celebration asked the same of the thing that died. Both are proxies
 * and both fail the same way. Brutus fights at thirty, so the follower stood
 * its ground through the whole fight and said nothing when he went down, while
 * the boss rules written for him that same day fired perfectly - two
 * definitions of one word, and only the weaker one consulted.
 *
 * <p>The names the boss rules already list are the other half of the answer,
 * so that list is now the answer and the rule file is the only place it lives.
 * These tests hold both halves: what is named counts however small, and what
 * is merely large still counts without anybody having named it.
 */
public class BossIsNotACombatLevelTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final String RULES = "{'rules':["
		+ "{'id':'boss-brutus','group':'boss','when':{'type':'npcSpawn',"
		+ "'names':['Brutus']},'say':['x']},"
		+ "{'id':'boss-inferno','group':'boss','when':{'type':'npcSpawn',"
		+ "'names':['Jal-*']},'say':['x']},"
		+ "{'id':'boss-low','group':'boss','when':{'type':'all','conditions':["
		+ "{'type':'healthBelow','percent':50},"
		+ "{'type':'npcNearby','within':12,'names':['Vorkath']}]},'say':['x']},"
		+ "{'id':'chat-rat','group':'combat','when':{'type':'npcSpawn',"
		+ "'names':['Giant rat']},'say':['x']}]}";

	private TriggerContext contextFor(String rulesJson) throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve("phrases.json"),
			rulesJson.replace('\'', '"').getBytes(StandardCharsets.UTF_8));

		RuleLoader loader = new RuleLoader(new Gson());
		loader.initialise(dir);

		TriggerContext context = new TriggerContext(null);
		context.setBossNames(loader.getBossNames());
		return context;
	}

	@Test
	public void aBossThatFightsBelowItsWeightStillCounts() throws Exception
	{
		assertTrue("Brutus fights at 30 and is still a boss",
			contextFor(RULES).isBoss("Brutus", 30));
	}

	@Test
	public void somethingMerelyLargeStillCountsWithoutBeingNamed() throws Exception
	{
		assertTrue("the level is still half the answer",
			contextFor(RULES).isBoss("Some Future Boss", 640));
	}

	@Test
	public void anOrdinaryMonsterIsStillOrdinary() throws Exception
	{
		TriggerContext context = contextFor(RULES);
		assertFalse("a rat named in a rule that is not a boss rule is not a boss",
			context.isBoss("Giant rat", 30));
		assertFalse("nor is anything else small and unlisted",
			context.isBoss("Man", 2));
	}

	@Test
	public void theNamesComeFromEveryShapeOfBossRule() throws Exception
	{
		TriggerContext context = contextFor(RULES);
		assertTrue("a wildcard boss name still matches",
			context.isBoss("Jal-Nib", 32));
		assertTrue("a name nested inside a combinator is collected too",
			context.isBoss("Vorkath", 1));
	}

	/** The game pads names with non-breaking spaces; the matcher is shared. */
	@Test
	public void paddedNamesDoNotHideABoss() throws Exception
	{
		assertTrue("padded the way the game pads it",
			contextFor(RULES).isBoss(" Brutus ", 30));
		assertEquals("Brutus", Condition.normaliseName(" Brutus "));
	}

	@Test
	public void theShippedRulesNameBrutusAsABoss() throws Exception
	{
		Harness harness = new Harness(folder.newFolder().toPath());
		TriggerContext context = new TriggerContext(null);
		context.setBossNames(harness.loader.getBossNames());

		assertTrue("Brutus, from the rules that ship",
			context.isBoss("Brutus", 30));
		assertTrue("and the form he turns into",
			context.isBoss("Demonic Brutus", 1224));
		assertFalse("while the shipped set has not swallowed everything",
			context.isBoss("Guard", 21));
		assertFalse("nor anything merely nearby in a non-boss rule",
			context.isBoss("Hans", 0));
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The font dump as a fresh install sees it.
 *
 * <p>Development machines have their own fonts.json in the data directory,
 * which takes precedence, so the bundled copy is the one path that is never
 * exercised while working on the plugin - and the one every hub user gets. The
 * dump is trimmed to the four fonts the plugin draws with, and nothing else
 * would notice if that trim took one too many.
 */
public class BundledFontsTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private GameFontRepository loadAsAFreshInstall() throws IOException
	{
		GameFontRepository fonts = new GameFontRepository(new Gson());
		// An empty directory: no override, so this is the bundled resource.
		fonts.load();
		return fonts;
	}

	@Test
	public void theBundledDumpLoads() throws IOException
	{
		GameFontRepository fonts = loadAsAFreshInstall();
		assertTrue("the bundled dump did not load: " + fonts.getStatus(), fonts.isLoaded());
	}

	@Test
	public void theFontsThePluginDrawsWithArePresent() throws IOException
	{
		GameFontRepository fonts = loadAsAFreshInstall();

		assertNotNull("font 497 is FollowerDialog's DIALOG_FONT_ID", fonts.get(497));
		assertNotNull("b12_full is what FollowerOverlay draws the overhead line with",
			fonts.getByName("b12_full"));
	}

	@Test
	public void theTrimmedDumpCarriesNothingElse() throws IOException
	{
		GameFontRepository fonts = loadAsAFreshInstall();
		// Not a correctness requirement, a size one: if a font creeps back in,
		// the jar grows by tens of kilobytes for glyphs nothing asks for.
		for (int id : new int[]{645, 646, 764, 819, 1442, 1447, 6315})
		{
			assertEquals("font " + id + " is bundled but never drawn with",
				null, fonts.get(id));
		}
	}

	@Test
	public void theFontsCanActuallyMeasureAndDrawText() throws IOException
	{
		GameFontRepository fonts = loadAsAFreshInstall();

		for (int id : new int[]{496, 497})
		{
			GameFont font = fonts.get(id);
			assertTrue("font " + id + " has no line height", font.getLineHeight() > 0);
			int width = font.stringWidth("The quick brown fox, 0123456789!");
			assertTrue("font " + id + " measured a real sentence as " + width, width > 0);
		}
	}
}

package com.follower;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * A callback about a quest's person stands aside the plain line about them.
 * QA, 15 Oct (probe P2): passing the Duke a few times in ten minutes gave
 * both callbacks and then "Duke Horacio himself. Lovely man.", as if the two
 * had never met. The callbacks keep three hours apart and the plain line one,
 * and nothing tied them together. Text QA pass 3, #70: and the two callbacks
 * themselves came about two minutes apart.
 */
public class CallbackStandsAsideTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private final long[] ms = {1_700_000_000_000L};

	private static String duke(String id, int priority, long cooldownMs)
	{
		return "{\"id\": \"" + id + "\", \"group\": \"t\", \"priority\": " + priority
			+ ", \"cooldownMs\": " + cooldownMs + ", \"waits\": true,"
			+ " \"when\": {\"type\": \"npcNearby\", \"within\": 5, \"names\": [\"Duke Horacio\"]},"
			+ " \"say\": [\"" + id + ".\"]}";
	}

	private void ticks(Harness h, int count)
	{
		for (int i = 0; i < count; i++)
		{
			ms[0] += 600;
			h.gameTick();
		}
	}

	/** Walks up to the Duke, stays a minute, and walks off again. */
	private void passTheDuke(Harness h)
	{
		h.game.cameraMoved();
		h.game.spawnNpc(815, "Duke Horacio", 0);
		ticks(h, 100);
		h.game.clearNpcs();
		ticks(h, 200);
	}

	@Test
	public void aCallbackStandsThePlainLineAsideForItsWhile() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), "{\"version\": 1, \"rules\": ["
			+ duke("fun-duke-after-rune-mysteries", 37, 10_800_000L) + ","
			+ duke("fun-duke-after-cooks-assistant", 36, 10_800_000L) + ","
			+ duke("quest-duke", 35, 3_600_000L) + "]}");
		h.engine.setClock(() -> ms[0]);
		h.engine.setGlobalCooldownMs(6000L);
		ticks(h, 1);

		passTheDuke(h);
		passTheDuke(h);
		passTheDuke(h);
		assertEquals("first meeting", 1, h.firedBy("fun-duke-after-rune-mysteries").size());
		assertTrue("not a second callback on the next pass", h.firedBy("fun-duke-after-cooks-assistant").isEmpty());
		assertTrue("not as if they had never met", h.firedBy("quest-duke").isEmpty());

		// An hour on, the callbacks are still cooling and the plain line has its turn.
		ticks(h, 6000);
		passTheDuke(h);
		assertEquals("an hour on", 1, h.firedBy("quest-duke").size());
	}

	@Test
	public void aPlainLineHeldForABoxStandsAsideForTheCallback() throws IOException
	{
		// Behaviour QA, 16 Oct (probe P8): the Duke walks up with a box open.
		// The plain line rises alone, the callback being gated off by the
		// box, and is held for it; the callback rises as it closes and wins.
		// Both were said, 6 s apart. Both wait 2 ticks, as shipped: the plain
		// line gets its beat after the box before the callback's delay is
		// out, so it stands aside at the callback's win, not its saying.
		Harness h = new Harness(folder.newFolder().toPath(), "{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"fun-duke-after-cooks-assistant\", \"group\": \"t\", \"priority\": 36, \"delayTicks\": 2,"
			+ " \"cooldownMs\": 10800000, \"waits\": true, \"when\": {\"type\": \"all\", \"conditions\": ["
			+ "{\"type\": \"npcNearby\", \"within\": 5, \"names\": [\"Duke Horacio\"]},"
			+ " {\"type\": \"none\", \"conditions\": [{\"type\": \"dialogueOpen\"}]}]},"
			+ " \"say\": [\"The Duke looks well.\"]},"
			+ duke("quest-duke", 35, 3_600_000L).replace("\"waits\": true,", "\"waits\": true, \"delayTicks\": 2,")
			+ "]}");
		h.engine.setClock(() -> ms[0]);
		h.engine.setGlobalCooldownMs(6000L);
		ticks(h, 1);
		h.engine.getContext().setDialogueOpen(true);
		h.game.cameraMoved();
		h.game.spawnNpc(815, "Duke Horacio", 0);
		ticks(h, 20);
		h.engine.getContext().setDialogueOpen(false);
		ticks(h, 30);
		assertEquals("the callback", 1, h.firedBy("fun-duke-after-cooks-assistant").size());
		assertTrue("and not the plain line too", h.firedBy("quest-duke").isEmpty());
	}

	/** The link is by name, so every shipped callback about a person has to find its plain line. */
	@Test
	public void everyShippedCallbackAboutAPersonFindsItsPlainLine() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		List<String> lost = new ArrayList<>();
		int callbacks = 0;
		for (SpeechRule rule : h.loader.getRules())
		{
			if (rule.plainLineId() != null && rule.when.usesType("npcNearby"))
			{
				callbacks++;
				if (h.loader.getRules().stream().noneMatch(r -> rule.plainLineId().equals(r.id)))
				{
					lost.add(rule.id + " -> " + rule.plainLineId());
				}
			}
		}
		assertTrue("no callbacks about people found - the scan broke", callbacks >= 9);
		assertTrue("callbacks with no plain line to stand aside: " + lost, lost.isEmpty());
	}
}

package com.follower;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * Catching up on a long walk. Play test, 18 Oct: the follower fell a little
 * behind, then flicked into the run pose for a split second and straight back
 * to the walk, again and again, because the burst switched on and off at the
 * one backlog threshold. Once begun it now runs until properly caught up.
 */
public class CatchUpPaceTest
{
	private final FakeGame game = new FakeGame().withCollision().at(80, 50, 0);
	private final FollowerEntity follower = new FollowerEntity(game.client, null);

	@Test
	public void aCatchUpIsOneSteadyJogNotAFlicker() throws Exception
	{
		WorldPoint start = new WorldPoint(50, 50, 0);
		set("tile", start);
		set("fineWX", start.getX() * 128L + 64);
		set("fineWY", start.getY() * 128L + 64);
		Deque<WorldPoint> route = deque("route");
		@SuppressWarnings("unchecked")
		Deque<Boolean> run = (Deque<Boolean>) get("routeRun");
		// Walking, and ten tiles behind: a backlog worth catching up on.
		for (int x = 51; x <= 60; x++)
		{
			route.add(new WorldPoint(x, 50, 0));
			run.add(false);
		}
		set("yaw", 1536);
		set("dstYaw", 1536);

		List<Integer> speeds = new ArrayList<>();
		Method move = FollowerEntity.class.getDeclaredMethod("moveContinuous", double.class);
		move.setAccessible(true);
		while (!route.isEmpty())
		{
			move.invoke(follower, 1.0);
			speeds.add((Integer) get("lastMoveSpeed"));
			// The player keeps walking: a tile more every 32 cycles.
			if (speeds.size() % 32 == 0)
			{
				WorldPoint last = route.peekLast();
				if (last != null && last.getX() < 70)
				{
					route.add(new WorldPoint(last.getX() + 1, 50, 0));
					run.add(false);
				}
			}
		}

		assertTrue("it did catch up at a run", speeds.contains(8));
		int firstRun = speeds.indexOf(8);
		int backToWalk = firstRun;
		while (backToWalk < speeds.size() && speeds.get(backToWalk) >= 8)
		{
			backToWalk++;
		}
		assertTrue("the run lasts more than a moment: " + speeds, backToWalk - firstRun > 64);
		for (int i = backToWalk; i < speeds.size(); i++)
		{
			assertTrue("once back to a walk it stays walking, no flick back: " + speeds.subList(backToWalk, speeds.size()),
				speeds.get(i) < 8);
		}
	}

	/**
	 * Catching up on a long run. QA5: at twice a run, the surge closed seven
	 * tiles to two in under a second every fourteen seconds, and read as a
	 * lunge. Half as fast again, and still back to its own run after.
	 */
	@Test
	public void aRunsCatchUpIsHalfAsFastAgainNotTwice() throws Exception
	{
		WorldPoint start = new WorldPoint(50, 50, 0);
		set("tile", start);
		set("fineWX", start.getX() * 128L + 64);
		set("fineWY", start.getY() * 128L + 64);
		Deque<WorldPoint> route = deque("route");
		@SuppressWarnings("unchecked")
		Deque<Boolean> run = (Deque<Boolean>) get("routeRun");
		for (int x = 51; x <= 60; x++)
		{
			route.add(new WorldPoint(x, 50, 0));
			run.add(true);
		}
		set("yaw", 1536);
		set("dstYaw", 1536);

		List<Integer> speeds = new ArrayList<>();
		Method move = FollowerEntity.class.getDeclaredMethod("moveContinuous", double.class);
		move.setAccessible(true);
		while (!route.isEmpty())
		{
			move.invoke(follower, 1.0);
			speeds.add((Integer) get("lastMoveSpeed"));
		}
		assertTrue("caught up a little faster than a run: " + speeds, speeds.contains(12));
		assertTrue("never twice a run: " + speeds, speeds.stream().allMatch(speed -> speed <= 12));
		assertTrue("and its own run once caught up: " + speeds,
			speeds.subList(speeds.lastIndexOf(12), speeds.size()).contains(8));
	}

	@SuppressWarnings("unchecked")
	private Deque<WorldPoint> deque(String name) throws Exception
	{
		return (Deque<WorldPoint>) get(name);
	}

	private Object get(String name) throws Exception
	{
		Field f = FollowerEntity.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(follower);
	}

	private void set(String name, Object value) throws Exception
	{
		Field f = FollowerEntity.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(follower, value);
	}
}

