package com.follower;

import java.lang.reflect.Field;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * commands.tsv holds the everyday commands' help, which the help printer and
 * the side panel's Commands section both list, so a slip in it must fail
 * here. The list as the code built it before it moved there is kept below as
 * it stood: the file must give the same pairs in the same order.
 */
public class CommandsFileTest
{
	private static final String LISTED_ERRAND_KEYS = listedErrandKeys();

	private static String listedErrandKeys()
	{
		try
		{
			Field field = FollowerPlugin.class.getDeclaredField("LISTED_ERRAND_KEYS");
			field.setAccessible(true);
			return (String) field.get(null);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}

	private static java.util.Map.Entry<String, String> command(String name, String effect)
	{
		return new java.util.AbstractMap.SimpleImmutableEntry<>(name, effect);
	}

	/** FollowerPlugin.EVERYDAY_COMMANDS before it moved, verbatim. */
	private static java.util.List<java.util.Map.Entry<String, String>> before()
	{
		return java.util.Collections.unmodifiableList(java.util.Arrays.asList(
			command("say <text>", "make the follower say it"),
			command("here", "place the follower at your feet"),
			command("fix", "re-attach it if it vanished"),
			command("rebuild", "rebuild its model from the outfit"),
			command("copy", "dress it in your gear (also a panel button)"),
			command("outfit <name>", "wear a saved profile (also in the panel)"),
			command("height <n>", "lift or lower it"),
			// Spaced, so the list wraps between keys rather than mid-word.
			command("errand [" + LISTED_ERRAND_KEYS.replace("|", " | ") + "]", "send it on an errand now"),
			command("reload", "re-read the phrase files"),
			command("status", "models, rules and spawn state"),
			command("where", "your region id, for Locations in the Messages window")));
	}

	@Test
	public void theFileListsWhatTheCodeListed()
	{
		assertEquals(before(), FollowerPlugin.EVERYDAY_COMMANDS);
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The rules file being read on the game thread while it is written on another.
 *
 * <p>This really happens: the plugin polls the file every game tick so edits go
 * live within a second, and the phrase editors write it from the Swing thread.
 * Nothing coordinates the two. The editor now writes to a sibling and renames,
 * which is what makes a torn read impossible - but the loader still has to hold
 * up on its own, because a user editing in Notepad gets no such courtesy.
 *
 * <p>Two things must hold whatever the interleaving: nothing thrown onto the
 * game thread, and the follower never left mute. Losing a personality file to a
 * half-written save would be far worse than running the previous rules for
 * another second.
 */
public class ConcurrentReloadTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static String rules(int count, String tag)
	{
		StringBuilder out = new StringBuilder("{\"version\": 1, \"rules\": [");
		for (int i = 0; i < count; i++)
		{
			if (i > 0)
			{
				out.append(',');
			}
			out.append("{\"id\": \"r").append(i).append("\", \"group\": \"t\","
				+ " \"when\": {\"type\": \"always\"}, \"say\": [\"").append(tag)
				.append(' ').append(i).append("\"]}");
		}
		return out.append("]}").toString();
	}

	/** In place, the way a text editor does it: truncate, then write. */
	private static void writeInPlace(Path file, String contents) throws IOException
	{
		Files.write(file, contents.getBytes(StandardCharsets.UTF_8));
	}

	/**
	 * Sibling and rename, the way the phrase editors do it - including the
	 * retry, because Windows will not replace a file another handle has open
	 * and the plugin opens this one every tick.
	 */
	private static void writeAtomically(Path file, String contents) throws IOException
	{
		Path temp = file.resolveSibling(file.getFileName() + ".tmp");
		byte[] bytes = contents.getBytes(StandardCharsets.UTF_8);
		Files.write(temp, bytes);

		for (int attempt = 0; attempt < 20; attempt++)
		{
			try
			{
				Files.move(temp, file,
					StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
				return;
			}
			catch (AtomicMoveNotSupportedException e)
			{
				Files.move(temp, file, StandardCopyOption.REPLACE_EXISTING);
				return;
			}
			catch (java.nio.file.FileSystemException e)
			{
				try
				{
					Thread.sleep(25);
				}
				catch (InterruptedException interrupted)
				{
					Thread.currentThread().interrupt();
					return;
				}
			}
		}

		Files.write(file, bytes);
		Files.deleteIfExists(temp);
	}

	private interface Writer
	{
		void write(Path file, String contents) throws IOException;
	}

	/**
	 * Hammers the file from one thread while polling it from another.
	 *
	 * @return how many polls came back with a parse error
	 */
	private int hammer(Writer writer) throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Path file = dir.resolve(RuleLoader.FILE_NAME);
		writer.write(file, rules(200, "first"));

		RuleLoader loader = new RuleLoader(new Gson());
		loader.initialise(dir);
		assertFalse("nothing loaded to begin with", loader.getRules().isEmpty());

		AtomicBoolean stop = new AtomicBoolean();
		AtomicReference<Throwable> thrown = new AtomicReference<>();

		Thread scribe = new Thread(() ->
		{
			try
			{
				for (int i = 0; !stop.get() && i < 400; i++)
				{
					writer.write(file, rules(200, "pass" + i));
				}
			}
			catch (Throwable t)
			{
				thrown.compareAndSet(null, t);
			}
		});
		scribe.setDaemon(true);
		scribe.start();

		int errors = 0;
		try
		{
			for (int i = 0; i < 4000 && scribe.isAlive(); i++)
			{
				// Exactly what the tick handler does.
				loader.reloadIfChanged();
				if (!loader.getErrors().isEmpty())
				{
					errors++;
				}
				assertFalse("the follower went mute mid-edit",
					loader.getRules().isEmpty());
			}
		}
		finally
		{
			stop.set(true);
			scribe.join(10000);
		}

		if (thrown.get() != null)
		{
			throw new AssertionError("the writer failed: " + thrown.get(), thrown.get());
		}
		return errors;
	}

	@Test
	public void anInPlaceWriterNeverSilencesTheFollower() throws Exception
	{
		// A user editing in Notepad. Torn reads are possible here and the
		// loader is allowed to complain about them - it just may not lose the
		// rules it already had, and may not throw onto the game thread.
		hammer(ConcurrentReloadTest::writeInPlace);
	}

	@Test
	public void theEditorsWriteSurvivesAReaderHoldingTheFile() throws Exception
	{
		// The rename path, which on Windows loses to an open handle. It must
		// not give up and lose the user's edits: retrying, and falling back to
		// an in-place write, is what keeps the save succeeding. Reaching the
		// fallback means a torn read is possible again, which is why the
		// loader keeping its previous rules is the test above and not an
		// afterthought.
		hammer(ConcurrentReloadTest::writeAtomically);
	}

	@Test
	public void theRuleListIsSwappedWholeNeverPartially() throws Exception
	{
		// Whatever a reader catches, it must be one complete set of rules -
		// never a list being filled in as it reads.
		Path dir = folder.newFolder().toPath();
		Path file = dir.resolve(RuleLoader.FILE_NAME);
		writeAtomically(file, rules(300, "first"));

		RuleLoader loader = new RuleLoader(new Gson());
		loader.initialise(dir);

		AtomicBoolean stop = new AtomicBoolean();
		Thread scribe = new Thread(() ->
		{
			try
			{
				for (int i = 0; !stop.get() && i < 300; i++)
				{
					writeAtomically(file, rules(300, "pass" + i));
				}
			}
			catch (IOException ignored)
			{
				// The assertion below is what matters.
			}
		});
		scribe.setDaemon(true);
		scribe.start();

		try
		{
			for (int i = 0; i < 3000 && scribe.isAlive(); i++)
			{
				loader.reloadIfChanged();
				List<SpeechRule> snapshot = loader.getRules();
				assertTrue("read a set of " + snapshot.size() + " rules, which is"
					+ " neither empty nor the full 300", snapshot.size() == 300);
				for (SpeechRule rule : snapshot)
				{
					assertFalse("a rule arrived without an id", rule.id == null);
				}
			}
		}
		finally
		{
			stop.set(true);
			scribe.join(10000);
		}
	}
}

package com.follower;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * event-conditions.properties is behaviour, so a slip in it must fail here
 * rather than leave a rule silently never true.
 *
 * <p>Every line names a real event type, only the narrowing fields the
 * interpreter knows, and a lower-case condition type, the way Condition
 * looks it up; no type is both a line and a case of Condition's switch.
 *
 * <p>And every line still means what its case in the switch meant before it
 * moved there: {@link #before} is those cases word for word, and each type
 * is evaluated both ways against every event type, with and without each
 * narrowing.
 */
public class ConditionEventsFileTest
{
	private static final List<String> NARROWING = Arrays.asList("is", "names", "contains");

	private static Properties file() throws Exception
	{
		Properties lines = new Properties();
		try (InputStream in = Condition.class.getResourceAsStream("/com/follower/event-conditions.properties"))
		{
			assertNotNull("event-conditions.properties is bundled", in);
			lines.load(in);
		}
		return lines;
	}

	@Test
	public void everyLineIsAnEventTypeAndKnownNarrowing() throws Exception
	{
		Properties lines = file();
		assertTrue("has lines", lines.size() >= 30);
		for (String type : lines.stringPropertyNames())
		{
			assertEquals(type + " is lower case", type.toLowerCase(Locale.ROOT), type);
			List<String> spec = Arrays.asList(lines.getProperty(type).split(" "));
			TriggerEvent.Type.valueOf(spec.get(0));
			assertEquals(type + " names a narrowing once", new HashSet<>(spec).size(), spec.size());
			for (String field : spec.subList(1, spec.size()))
			{
				assertTrue(type + ": unknown field '" + field + "'", NARROWING.contains(field));
			}
		}
	}

	@Test
	public void noTypeIsBothALineAndACase() throws Exception
	{
		String source = new String(Files.readAllBytes(
			Paths.get("src/main/java/com/follower/Condition.java")), StandardCharsets.UTF_8);
		Set<String> cases = new HashSet<>();
		Matcher m = Pattern.compile("case \"([a-z]+)\":").matcher(source);
		while (m.find())
		{
			cases.add(m.group(1));
		}
		Set<String> both = new TreeSet<>(file().stringPropertyNames());
		both.retainAll(cases);
		assertEquals("types that are both a line and a case", Collections.emptySet(), both);
	}

	@Test
	public void everyLineMeansWhatItsCaseMeant() throws Exception
	{
		Set<String> types = file().stringPropertyNames();
		assertEquals("the same types as the cases they replaced", BEFORE, new TreeSet<>(types));

		List<TriggerEvent> events = events();
		List<String> isValues = Arrays.asList(null, "x", "valuable", "VALUABLE", "fell", "bought", "");
		List<List<String>> nameLists = Arrays.asList(null, Collections.emptyList(),
			Collections.singletonList("Goblin"), Collections.singletonList("gob*"),
			Arrays.asList("x", "*Shanty*"), Collections.singletonList("*"));
		List<String> containsValues = Arrays.asList(null, "", "star", "STAR", "nothing at all");
		int compared = 0;
		for (String type : types)
		{
			for (String is : isValues)
			{
				for (List<String> names : nameLists)
				{
					for (String contains : containsValues)
					{
						Condition now = condition(type, is, names, contains);
						Condition then = condition(type, is, names, contains);
						for (TriggerEvent event : events)
						{
							boolean expected = before(then, event);
							if (now.matches(null, event) != expected)
							{
								fail(type + " is=" + is + " names=" + names + " contains=" + contains
									+ " on " + event.getType() + " '" + event.getName() + "' '"
									+ event.getMessage() + "': expected " + expected);
							}
							compared++;
						}
					}
				}
			}
		}
		assertTrue(compared > 100_000);
	}

	private static Condition condition(String type, String is, List<String> names, String contains)
	{
		Condition c = new Condition();
		// Written as a rule file would, in any case.
		c.type = type.toUpperCase(Locale.ROOT);
		c.is = is;
		c.names = names;
		c.contains = contains;
		return c;
	}

	/** Every event type, bare and named, and the ones that carry a message, with some. */
	private static List<TriggerEvent> events()
	{
		List<String> names = Arrays.asList("", "x", "Goblin", "goblin ", " Sea Shanty 2 ",
			"valuable", "fell", "bought", "VALUABLE");
		List<String> messages = Arrays.asList("", "A shooting STAR!", "nothing at all", "star");
		List<TriggerEvent> events = new ArrayList<>();
		for (TriggerEvent.Type type : TriggerEvent.Type.values())
		{
			events.add(TriggerEvent.simple(type));
			for (String name : names)
			{
				events.add(TriggerEvent.channel(type, name));
			}
		}
		for (String name : names)
		{
			for (String message : messages)
			{
				events.add(TriggerEvent.npcShout(name, message));
				events.add(TriggerEvent.chat(message, 0, name));
				events.add(TriggerEvent.noticed(name, message));
				events.add(TriggerEvent.hesitated(name, message));
			}
		}
		return events;
	}

	/** The types whose cases {@link #before} keeps. */
	private static final Set<String> BEFORE = new TreeSet<>(Arrays.asList(
		"noticed",
		"hesitated",
		"steppedaside",
		"crossed",
		"errandstart",
		"errandend",
		"combatstart",
		"workended",
		"targetdepleted",
		"bagfull",
		"baghalf",
		"farewell", "playerdeath", "login", "thrallstart", "thrallswitch", "thrallend",
		"thievingstart", "thievingend", "underfoot", "worldhop", "gameupdated", "notesedited",
		"musicunlock", "musictrack", "collectionadd", "questcomplete", "geoffer",
		"channeljoined", "channelleft", "npcshout", "wantfulfilled", "wantexpired", "examined",
		"examinedthing", "attendedagain", "minutestaken", "personalbest"));

	/**
	 * Condition's cases for these types as they were before the file, word
	 * for word but for reading the condition's fields through {@code c}.
	 */
	private static boolean before(Condition c, TriggerEvent event)
	{
		String is = c.is;
		List<String> names = c.names;
		String contains = c.contains;
		switch (c.type.toLowerCase(Locale.ROOT))
		{
			case "noticed":
				return event.getType() == TriggerEvent.Type.NOTICED
					&& (is == null || is.equalsIgnoreCase(event.getName()))
					&& (contains == null || event.getMessage().toLowerCase(Locale.ROOT)
						.contains(contains.toLowerCase(Locale.ROOT)));

			case "hesitated":
				return event.getType() == TriggerEvent.Type.HESITATED
					&& (is == null || is.equalsIgnoreCase(event.getName()));

			case "steppedaside":
				return event.getType() == TriggerEvent.Type.STEPPED_ASIDE;

			case "crossed":
				return event.getType() == TriggerEvent.Type.CROSSED
					&& (is == null || is.equalsIgnoreCase(event.getName()));

			case "farewell":
				return event.getType() == TriggerEvent.Type.FAREWELL;

			case "playerdeath":
				return event.getType() == TriggerEvent.Type.PLAYER_DEATH;

			case "login":
				return event.getType() == TriggerEvent.Type.LOGIN;

			case "thrallstart":
				return event.getType() == TriggerEvent.Type.THRALL_START;
			case "thrallswitch":
				return event.getType() == TriggerEvent.Type.THRALL_SWITCH;
			case "thrallend":
				return event.getType() == TriggerEvent.Type.THRALL_END;

			case "errandstart":
				return event.getType() == TriggerEvent.Type.ERRAND_START
					&& (names == null || matchesAnyName(names, event.getName()));
			case "errandend":
				return event.getType() == TriggerEvent.Type.ERRAND_END
					&& (names == null || matchesAnyName(names, event.getName()));

			case "combatstart":
				return event.getType() == TriggerEvent.Type.COMBAT_START
					&& (names == null || matchesAnyName(names, event.getName()));

			case "thievingstart":
				return event.getType() == TriggerEvent.Type.THIEVING_START;
			case "thievingend":
				return event.getType() == TriggerEvent.Type.THIEVING_END;

			case "underfoot":
				return event.getType() == TriggerEvent.Type.UNDERFOOT;

			case "worldhop":
				return event.getType() == TriggerEvent.Type.WORLD_HOP;

			case "gameupdated":
				return event.getType() == TriggerEvent.Type.GAME_UPDATE;

			case "notesedited":
				return event.getType() == TriggerEvent.Type.NOTES_EDITED;

			case "musicunlock":
				return event.getType() == TriggerEvent.Type.MUSIC_UNLOCK;

			case "musictrack":
				return event.getType() == TriggerEvent.Type.TRACK_CHANGE
					&& (names == null || matchesAnyName(names, event.getName()));

			case "collectionadd":
				return event.getType() == TriggerEvent.Type.COLLECTION_ADD;

			case "questcomplete":
				return event.getType() == TriggerEvent.Type.QUEST_COMPLETE;

			case "geoffer":
				return event.getType() == TriggerEvent.Type.GE_OFFER
					&& (is == null || is.equalsIgnoreCase(event.getName()));

			case "channeljoined":
				return event.getType() == TriggerEvent.Type.CHANNEL_JOIN;
			case "channelleft":
				return event.getType() == TriggerEvent.Type.CHANNEL_LEAVE;

			case "npcshout":
				return event.getType() == TriggerEvent.Type.NPC_SHOUT
					&& (names == null || matchesAnyName(names, event.getName()))
					&& (contains == null || event.getMessage().toLowerCase(Locale.ROOT)
						.contains(contains.toLowerCase(Locale.ROOT)));

			case "wantfulfilled":
				return event.getType() == TriggerEvent.Type.WANT_FULFILLED;
			case "wantexpired":
				return event.getType() == TriggerEvent.Type.WANT_EXPIRED;

			case "examined":
				return event.getType() == TriggerEvent.Type.EXAMINED;

			case "examinedthing":
				return event.getType() == TriggerEvent.Type.EXAMINED_THING
					&& (names == null || matchesAnyName(names, event.getName()));

			case "attendedagain":
				return event.getType() == TriggerEvent.Type.ATTENDED_AGAIN;

			case "minutestaken":
				return event.getType() == TriggerEvent.Type.MINUTES_TAKEN;

			case "personalbest":
				return event.getType() == TriggerEvent.Type.RECORD
					&& (names == null || matchesAnyName(names, event.getName()));

			case "workended":
				return event.getType() == TriggerEvent.Type.WORK_END
					&& (names == null || matchesAnyName(names, event.getName()));

			case "targetdepleted":
				return event.getType() == TriggerEvent.Type.TARGET_DEPLETED;

			case "bagfull":
				return event.getType() == TriggerEvent.Type.BAG_FULL;
			case "baghalf":
				return event.getType() == TriggerEvent.Type.BAG_HALF;

			default:
				throw new IllegalArgumentException(c.type);
		}
	}

	/** Condition's name matching as it was: case-insensitive, {@code *} wildcards. */
	private static boolean matchesAnyName(List<String> names, String candidate)
	{
		if (candidate == null || names == null)
		{
			return false;
		}
		String normalised = Condition.normaliseName(candidate);
		for (String name : names)
		{
			if (Condition.compileName(name).matcher(normalised).matches())
			{
				return true;
			}
		}
		return false;
	}
}

package com.follower;

import java.io.IOException;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The settings a player has before they touch anything.
 *
 * <p>Defaults are the one configuration almost every user runs, and the one
 * nobody tests: RuneLite writes them into the profile on first read, after
 * which changing a default in code has no effect on that install at all. So a
 * default that is wrong ships wrong and stays wrong.
 */
public class ConfigDefaultsTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private final FollowerConfig config = new FollowerConfig()
	{
	};

	// ------------------------------------------------------------- first run

	/**
	 * Asked for explicitly: a first-time user should see a plain character with
	 * no gear and the default body kit, not somebody else's costume.
	 */
	@Test
	public void aFreshInstallShowsABaseCharacter()
	{
		assertEquals("the shipped outfit must be empty", "", config.customOutfit());

		Outfit outfit = OutfitParser.parse(config.customOutfit());
		assertTrue("an empty outfit string must parse to an empty outfit",
			outfit.isEmpty());
		assertFalse("and still produce a body once the default kits are filled in",
			outfit.withDefaultBody().isEmpty());
	}

	@Test
	public void theFollowerHasANameAndItIsNotBlank()
	{
		assertNotNull(config.followerName());
		assertFalse(config.followerName().trim().isEmpty());
	}

	@Test
	public void theFollowerIsFollowingAndAudibleOutOfTheBox()
	{
		assertTrue("a follower that does not follow is not much of one",
			config.followEnabled());
		assertFalse("shipped muted would read as broken", config.muted());
		assertNotNull(config.defaultOutput());
	}

	@Test
	public void everyPhraseGroupIsOnByDefault()
	{
		assertTrue(config.groupBoss());
		assertTrue(config.groupHealth());
		assertTrue(config.groupArea());
		assertTrue(config.groupIdle());
		assertTrue(config.groupGear());
		assertTrue(config.groupQuest());
		assertTrue(config.groupCombat());
		assertTrue(config.groupMimic());
		assertEquals("nothing should be silenced before the user asks",
			"", config.disabledGroups());
	}

	@Test
	public void theSkillingCompanyIsOnByDefault()
	{
		assertTrue("the seat and everything built on it", config.keepsCompany());
		assertTrue("and the borrowed tool", config.borrowsTools());
	}


	// --------------------------------------------------------------- ranges

	@Test
	public void timingsArePositive()
	{
		assertTrue("speech that vanishes instantly cannot be read",
			config.speechDurationMs() > 0);
		assertTrue("a line has to be given some time per character",
			config.readingSpeed() > 0);

		// The raw milliseconds box became a named setting; every level still
		// has to leave a gap, and they have to run in the order they read.
		Chattiness previous = null;
		for (Chattiness level : Chattiness.values())
		{
			assertTrue(level + " must leave some gap", level.getGapMs() > 0);
			if (previous != null)
			{
				assertTrue(level + " should talk more than " + previous,
					level.getGapMs() < previous.getGapMs());
			}
			previous = level;
		}
	}

	@Test
	public void animationAndGraphicIdsAreRealNumbers()
	{
		int[] ids = {
			config.spectateShieldAnimation(),
			config.spectateShieldChannelStart(),
			config.spectateShieldChannelEnd(),
			config.spectateShieldChannelAnimation(),
			config.spectateShieldEndAnimation(),
			config.spectateShieldGraphic(),
			config.spectateShieldChannelGraphic(),
			config.spectateShieldEndGraphic(),
			config.restAnimation(),
		};
		for (int id : ids)
		{
			assertTrue("a negative id would be dropped silently: " + id, id >= 0);
		}
		assertTrue("the rest pose has to be something", config.restAnimation() > 0);
	}

	@Test
	public void theThrallProfilesPointAtProfilesThatExist() throws IOException
	{
		OutfitProfileStore store =
			new OutfitProfileStore(new com.google.gson.Gson());
		store.load(folder.newFolder().toPath());

		for (String name : new String[]{config.thrallMeleeProfile(),
			config.thrallRangedProfile(), config.thrallMagicProfile()})
		{
			assertNotNull("thrall mode points at a profile that a fresh install"
				+ " does not have: " + name, store.get(name));
		}
	}

	// ------------------------------------------------------ code and settings

	@Test
	public void everyGroupTheRulesUseHasASwitchInTheSettings() throws IOException
	{
		// Derived from the config interface rather than a hand-kept list, so
		// adding a groupX() switch is enough to cover a new group.
		Set<String> switchable = new HashSet<>();
		for (Method method : FollowerConfig.class.getMethods())
		{
			String name = method.getName();
			if (name.startsWith("group") && name.length() > 5
				&& method.getParameterCount() == 0)
			{
				switchable.add(name.substring(5).toLowerCase(java.util.Locale.ROOT));
			}
		}
		// Groups deliberately without a switch of their own.
		switchable.add("misc");
		switchable.add("errand");
		switchable.add("thrall");

		Harness h = new Harness(folder.newFolder().toPath());
		Set<String> orphans = new TreeSet<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			if (!switchable.contains(rule.group))
			{
				orphans.add(rule.group);
			}
		}
		assertTrue("rule groups a user cannot switch off: " + orphans, orphans.isEmpty());
	}

	@Test
	public void theErrandFrequencyQuotesTheScheduleTheErrandsRun() throws Exception
	{
		// The description gives minutes and the errands count ticks, in two
		// files; a comment on each asked for them to be changed together.
		String description = FollowerConfig.class.getMethod("errandFrequency")
			.getAnnotation(ConfigItem.class).description();
		Method base = ErrandController.class.getDeclaredMethod("baseScheduleTicks");
		base.setAccessible(true);
		for (FollowerConfig.ErrandFrequency frequency : FollowerConfig.ErrandFrequency.values())
		{
			FollowerConfig chosen = new FollowerConfig()
			{
				@Override
				public FollowerConfig.ErrandFrequency errandFrequency()
				{
					return frequency;
				}
			};
			ErrandController errands = new ErrandController(
				null, null, chosen, event ->
				{
				}, null, () -> false, new ErrandController.Hands()
				{
					@Override
					public void hold(int itemId)
					{
					}

					@Override
					public void release()
					{
					}
				});
			// 0.6 seconds a tick.
			long minutes = Math.round((int) base.invoke(errands) * 0.6 / 60);
			assertTrue(frequency + " runs about every " + minutes + " minutes: " + description,
				description.matches(".*\\b" + minutes + " (minutes )?on " + frequency + "\\b.*"));
		}
	}

	@Test
	public void everySettingIsInASectionAndHasSomethingToSay()
	{
		List<String> problems = new ArrayList<>();
		for (Method method : FollowerConfig.class.getDeclaredMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item == null)
			{
				continue;
			}
			if (item.name().trim().isEmpty())
			{
				problems.add(method.getName() + " has no name");
			}
			if (item.description().trim().isEmpty())
			{
				problems.add(method.getName() + " has no description");
			}
			if (item.keyName().trim().isEmpty())
			{
				problems.add(method.getName() + " has no key");
			}
		}
		assertTrue("settings a user would see as blank: " + problems, problems.isEmpty());
	}

	@Test
	public void everySettingKeyIsUnique()
	{
		Set<String> seen = new HashSet<>();
		List<String> duplicates = new ArrayList<>();
		for (Method method : FollowerConfig.class.getDeclaredMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item != null && !seen.add(item.keyName()))
			{
				// Two settings sharing a key would overwrite each other in the
				// saved profile, and the loser would silently never persist.
				duplicates.add(item.keyName());
			}
		}
		assertTrue("settings sharing a storage key: " + duplicates, duplicates.isEmpty());
	}

	@Test
	public void settingsInASectionDoNotFightOverTheSamePosition()
	{
		Set<String> seen = new HashSet<>();
		List<String> clashes = new ArrayList<>();
		for (Method method : FollowerConfig.class.getDeclaredMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item != null && !item.section().isEmpty() && item.position() >= 0
				&& !seen.add(item.section() + "@" + item.position()))
			{
				clashes.add(item.keyName());
			}
		}
		assertTrue("settings with the same position order arbitrarily: " + clashes, clashes.isEmpty());
	}

	@Test
	public void silencingByNameSitsWithTheMessagesToggles() throws Exception
	{
		// QA, 15 Oct: it was in the closed Advanced section, though it is the
		// only switch for the Messages categories with no toggle of their own.
		// The key is unchanged, so what players typed in survives the move.
		ConfigItem item = item("disabledGroups");
		assertEquals("disabledGroups", item.keyName());
		assertEquals(FollowerConfig.groupsSection, item.section());
		assertEquals("after the last toggle", position("groupReactions") + 1, item.position());
	}

	@Test
	public void movementReadsInOrder() throws Exception
	{
		// Follow distance first, then wandering and how soon, then resting.
		assertTrue(position("followDistance") < position("wanderWhenIdle"));
		assertEquals(position("wanderWhenIdle") + 1, position("wanderAfterSeconds"));
		assertTrue(position("wanderAfterSeconds") < position("restWhenIdle"));
		for (String key : new String[]{"followDistance", "wanderWhenIdle", "wanderAfterSeconds", "restWhenIdle"})
		{
			assertEquals(key, FollowerConfig.movementSection, item(key).section());
		}
	}

	private static ConfigItem item(String method) throws NoSuchMethodException
	{
		return FollowerConfig.class.getDeclaredMethod(method).getAnnotation(ConfigItem.class);
	}

	private static int position(String method) throws NoSuchMethodException
	{
		return item(method).position();
	}

	@Test
	public void sectionsDoNotFightOverTheSamePosition()
	{
		Set<Integer> seen = new HashSet<>();
		List<String> clashes = new ArrayList<>();
		for (java.lang.reflect.Field field : FollowerConfig.class.getDeclaredFields())
		{
			ConfigSection section = field.getAnnotation(ConfigSection.class);
			if (section != null && !seen.add(section.position()))
			{
				clashes.add(section.name() + " at " + section.position());
			}
		}
		assertTrue("sections with the same position order arbitrarily: " + clashes,
			clashes.isEmpty());
	}

	@Test
	public void everySettingNamedAsAPercentageIsOne()
	{
		// A percentage that ships outside 0-100 can never be reached by the
		// slider, so the setting is dead on arrival.
		assertTrue(config.speechDurationMs() > 100);
		assertEquals("the default output must be one the parser knows",
			config.defaultOutput(),
			SpeechOutput.parse(config.defaultOutput().name(), SpeechOutput.OVERHEAD));
	}

	@Test
	public void theSpawnAnimationSettingIsSomethingTheCodeCanRead()
	{
		String spawn = config.spawnAnimation();
		assertNotNull(spawn);
		assertFalse("a blank spawn setting would read as no animation at all",
			spawn.trim().isEmpty());
	}
	@Test
	public void thrallOnlyIsOptInAndAbsenceFollowsTheThrall()
	{
		// Nobody installs a follower to see nothing: the thrall-only mode is
		// something a player chooses. And in that mode the follower exists
		// exactly while a thrall has it.
		assertTrue("thrall replacement itself stays on", config.thrallMode());
		assertTrue("but thrall-only is opt in", !config.thrallOnly());
		assertTrue(FollowerPlugin.absentUntilSummoned(true, false));
		assertTrue(!FollowerPlugin.absentUntilSummoned(true, true));
		assertTrue(!FollowerPlugin.absentUntilSummoned(false, false));
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;

/**
 * A logout ends the session, not what was said in it. Text QA5, 17 Oct:
 * the fence book (two hours' cooldown) was said at 14:21 and again at 14:33,
 * either side of a relog; 18 Oct, the nickname was asked at 15:39 and 15:50
 * the same way.
 */
public class CooldownsAcrossLogoutTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private final long[] ms = {1_700_000_000_000L};

	private Harness harness() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": [{\"id\": \"book\", \"group\": \"t\", \"cooldownMs\": 7200000,"
				+ " \"when\": {\"type\": \"levelUp\", \"names\": [\"Thieving\"]}, \"say\": [\"The fence book.\"]}]}");
		h.engine.setClock(() -> ms[0]);
		h.engine.loggedInAs(1L);
		h.gameTicks(1);
		return h;
	}

	private void sayIt(Harness h)
	{
		h.dispatch(TriggerEvent.levelUp("Thieving", 50));
		h.gameTicks(1);
	}

	@Test
	public void aCooldownHoldsThroughARelog() throws IOException
	{
		Harness h = harness();
		sayIt(h);
		ms[0] += 12 * 60_000L;
		h.engine.reset();
		h.engine.loggedInAs(1L);
		sayIt(h);
		assertEquals("not again twelve minutes on, across the relog", 1, h.firedBy("book").size());

		ms[0] += 2 * 3_600_000L;
		sayIt(h);
		assertEquals("its own while still runs out", 2, h.firedBy("book").size());
	}

	@Test
	public void anotherAccountStartsOver() throws IOException
	{
		Harness h = harness();
		sayIt(h);
		h.engine.reset();
		h.engine.loggedInAs(2L);
		sayIt(h);
		assertEquals(2, h.firedBy("book").size());
	}

	@Test
	public void forgettingStartsOver() throws IOException
	{
		// A profile switch, or Forget everything: another follower's memory.
		Harness h = harness();
		sayIt(h);
		h.engine.forget();
		sayIt(h);
		assertEquals(2, h.firedBy("book").size());
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Noticing repetition: how many, and how long.
 *
 * <p>Both are the same idea from the player's side - the follower has been
 * paying attention - and they are the cheapest way to make it seem so. The
 * count is kept where the kill is raised so the tally and the event can never
 * disagree; the duration is measured off the animation, which means it covers
 * every skill at once without knowing what any of them are.
 */
public class CountingTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static String rules(String... bodies)
	{
		return "{\"version\": 1, \"rules\": [" + String.join(",", bodies) + "]}";
	}

	// ---------------------------------------------------------------- tallies

	@Test
	public void aTallyCountsEachThingSeparately() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		assertEquals(1, h.engine.getContext().tally("kill:goblin"));
		assertEquals(2, h.engine.getContext().tally("kill:goblin"));
		assertEquals("a different thing has its own count",
			1, h.engine.getContext().tally("kill:rat"));
		assertEquals(2, h.engine.getContext().getTally("kill:goblin"));
		assertEquals("something never counted is zero, not an error",
			0, h.engine.getContext().getTally("kill:dragon"));
	}

	@Test
	public void everyFiresOnTheMultiplesAndNotBetween() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"milestone\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"npcKill\", \"every\": 5},"
				+ " \"say\": [\"{count}\"]}"));

		h.gameTicks(1);
		for (int count = 1; count <= 20; count++)
		{
			h.dispatch(TriggerEvent.kill(1, "Goblin", 5, count));
			h.gameTick();
		}

		assertEquals("fifth, tenth, fifteenth, twentieth", 4, h.firedBy("milestone").size());
		assertEquals("5", h.firedBy("milestone").get(0).text);
		assertEquals("20", h.firedBy("milestone").get(3).text);
	}

	@Test
	public void aKillWithNoCountNeverTripsAMilestone() throws IOException
	{
		// count 0 is "nobody counted", which must not read as a multiple of
		// everything.
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"milestone\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"npcKill\", \"every\": 5}, \"say\": [\"a\"]}"));

		h.gameTicks(1);
		for (int i = 0; i < 10; i++)
		{
			h.dispatch(TriggerEvent.kill(1, "Goblin", 5));
			h.gameTick();
		}

		assertTrue(h.firedBy("milestone").isEmpty());
	}

	@Test
	public void aKillRuleWithNoEveryStillFiresOnEveryKill() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"each\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"npcKill\"}, \"say\": [\"a\"]}"));

		h.gameTicks(1);
		for (int count = 1; count <= 5; count++)
		{
			h.dispatch(TriggerEvent.kill(1, "Goblin", 5, count));
			h.gameTick();
		}

		assertEquals("adding every must not have changed the plain case",
			5, h.firedBy("each").size());
	}

	@Test
	public void theCountPlaceholderCarriesTheNumber() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"tally\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"npcKill\"},"
				+ " \"say\": [\"that is {count} of {npc}\"]}"));

		h.gameTicks(1);
		h.dispatch(TriggerEvent.kill(1, "Goblin", 5, 42));

		assertEquals("that is 42 of Goblin", h.spoken.get(0).text);
	}

	// -------------------------------------------------------------- repeating

	@Test
	public void doingTheSameThingClimbsTheCounter() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.animating(879);
		h.gameTicks(30);

		assertTrue("thirty ticks of one animation should have been noticed",
			h.engine.getContext().getRepeatingTicks() >= 25);
		assertEquals(879, h.engine.getContext().getRepeatingAnimation());
	}

	@Test
	public void aBriefGapDoesNotResetIt() throws IOException
	{
		// Most gathering drops to no animation for a tick between swings, and
		// treating that as stopping would hold the count at zero forever.
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.animating(879);
		h.gameTicks(20);
		int before = h.engine.getContext().getRepeatingTicks();

		h.game.animating(-1);
		h.gameTicks(2);
		h.game.animating(879);
		h.gameTicks(5);

		assertTrue("a two tick pause is a swing, not a stop: was " + before
				+ ", now " + h.engine.getContext().getRepeatingTicks(),
			h.engine.getContext().getRepeatingTicks() > before);
	}

	@Test
	public void actuallyStoppingResetsIt() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.animating(879);
		h.gameTicks(30);

		h.game.animating(-1);
		h.gameTicks(20);

		assertEquals("standing about is not doing something",
			0, h.engine.getContext().getRepeatingTicks());
	}

	@Test
	public void switchingActivityStartsTheCountAgain() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.animating(879);
		h.gameTicks(30);

		h.game.animating(624);
		h.gameTicks(3);

		assertEquals(624, h.engine.getContext().getRepeatingAnimation());
		assertTrue("a different activity is a new count, not a continuation",
			h.engine.getContext().getRepeatingTicks() <= 3);
	}

	@Test
	public void aRuleCanWaitForAWhileOfTheSameThing() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"noticed\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"repeating\", \"ticks\": 50},"
				+ " \"say\": [\"still at it\"]}"));

		h.game.animating(879);
		h.gameTicks(20);
		assertTrue("twenty ticks is not yet a while", h.firedBy("noticed").isEmpty());

		h.gameTicks(40);
		assertFalse("sixty is", h.firedBy("noticed").isEmpty());
	}

	@Test
	public void aRepeatingRuleCanNameTheAnimationsItCaresAbout() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"chopping\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"repeating\", \"ticks\": 20, \"ids\": [879]},"
				+ " \"say\": [\"timber\"]}"));

		h.game.animating(624);
		h.gameTicks(40);
		assertTrue("a different activity must not match", h.firedBy("chopping").isEmpty());

		h.game.animating(879);
		h.gameTicks(40);
		assertFalse(h.firedBy("chopping").isEmpty());
	}

	// ------------------------------------------------------------ the rule set

	@Test
	public void theShippedMilestonesRiseInOrder() throws IOException
	{
		// The hundredth must outrank the twenty-fifth, or the round number
		// loses to the smaller one when both come up on the same kill.
		Harness h = new Harness(folder.newFolder().toPath());

		assertTrue("the hundred milestone must win when they coincide",
			h.rule("kill-tally-hundred").priority > h.rule("kill-tally").priority);
		assertEquals(25, h.rule("kill-tally").when.every.intValue());
		assertEquals(100, h.rule("kill-tally-hundred").when.every.intValue());
		assertTrue("the longer wait must outrank the shorter one",
			h.rule("repeating-a-long-while").priority
				> h.rule("repeating-a-while").priority);
	}
}

package com.follower;

import java.io.IOException;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * An emote done AT the follower is answered rather than copied. The
 * difference between an echo and a reply is the difference between a mirror
 * and company, and it is the closest OSRS gets to petting the dog.
 */
public class CourtesyTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final int BOW = 858;
	private static final int CHEER = 862;
	private static final int CLAP = 865;

	/** The player a tile north of the follower, turned to face it. */
	private Harness facingIt() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.at(50, 50, 0).turned(0);
		h.engine.getContext().setFollowerLocation(new WorldPoint(50, 49, 0));
		h.gameTicks(2);
		return h;
	}

	private static void fire(Harness h, int emote)
	{
		h.dispatch(TriggerEvent.animation(emote));
		h.gameTicks(5);
	}

	@Test
	public void aBowDoneAtItGetsABowBackAndNoCopy() throws IOException
	{
		Harness h = facingIt();
		fire(h, BOW);
		List<Harness.Spoken> answered = h.firedBy("answer-bow");
		assertEquals("the answer", 1, answered.size());
		assertEquals(BOW, answered.get(0).animationId);
		assertTrue("and the mimic does not play on top", h.firedBy("mimic-emotes").isEmpty());
	}

	@Test
	public void aCheerGetsAClapWhichIsAReplyNotAnEcho() throws IOException
	{
		Harness h = facingIt();
		fire(h, CHEER);
		assertEquals(CLAP, h.firedBy("answer-cheer").get(0).animationId);
	}

	@Test
	public void anEmoteDoneNearItButNotAtItIsCopiedAsBefore() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.at(50, 50, 0).turned(1024);
		h.engine.getContext().setFollowerLocation(new WorldPoint(50, 49, 0));
		h.gameTicks(2);
		fire(h, BOW);
		assertTrue(h.firedBy("answer-bow").isEmpty());
		assertFalse("the mimic", h.firedBy("mimic-emotes").isEmpty());

		Harness far = new Harness(folder.newFolder().toPath());
		far.game.at(50, 50, 0).turned(0);
		far.engine.getContext().setFollowerLocation(new WorldPoint(50, 47, 0));
		far.gameTicks(2);
		fire(far, BOW);
		assertTrue("three tiles off is not addressing it", far.firedBy("answer-bow").isEmpty());
	}

	@Test
	public void theDiagonalsCountAsFacing()
	{
		TriggerContext context = new TriggerContext(new FakeGame()
			.at(50, 50, 0).turned(TriggerContext.bearing(1, 1)).client);
		context.setFollowerLocation(new WorldPoint(51, 51, 0));
		assertTrue("north-east, facing north-east", context.isAddressingFollower());
		context.setFollowerLocation(new WorldPoint(51, 50, 0));
		assertTrue("east is inside the tolerance", context.isAddressingFollower());
		context.setFollowerLocation(new WorldPoint(49, 49, 0));
		assertFalse("south-west is not", context.isAddressingFollower());
		// A quarter turn off is looking past it: the emote was for somebody else.
		context.setFollowerLocation(new WorldPoint(49, 51, 0));
		assertFalse("north-west is a quarter turn off", context.isAddressingFollower());
	}

	@Test
	public void theBearingIsTheActorCircle()
	{
		assertEquals("south", 0, TriggerContext.bearing(0, -1));
		assertEquals("west", 512, TriggerContext.bearing(-1, 0));
		assertEquals("north", 1024, TriggerContext.bearing(0, 1));
		assertEquals("east", 1536, TriggerContext.bearing(1, 0));
	}

	@Test
	public void everyAnswerIsForAnEmoteTheMimicKnowsAndRepliesWithOneItCanPlay()
	{
		// The mimic list is the set of one-shots proven to play on the
		// follower; an answer outside it would be a reply nobody can see.
		Harness h;
		try
		{
			h = new Harness(folder.newFolder().toPath());
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
		Set<Integer> proven = new HashSet<>(h.rule("mimic-emotes").when.ids);
		int answers = 0;
		for (SpeechRule rule : h.loader.getRules())
		{
			if (rule.id == null || !rule.id.startsWith("answer-"))
			{
				continue;
			}
			answers++;
			assertEquals("mimic", rule.group);
			assertTrue(rule.id + " outranks the mimic", rule.priority > h.rule("mimic-emotes").priority);
			assertTrue(rule.id + " answers with an unproven animation", proven.contains(rule.animation));
			assertTrue(rule.id + " must ask whether it was addressed", rule.when.usesType("addressed"));
		}
		assertTrue("the answer table looks too short: " + answers, answers >= 20);
	}
}

package com.follower;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.client.callback.ClientThread;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

/**
 * The things QA3's threading audit found shared between the event thread
 * and the client thread: the import's write of phrases.json, the sound
 * library, and the Memory window's Forget everything.
 */
public class CrossThreadTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();


	@Test
	public void forgetEverythingDoesNothingOnceThePluginIsStopped() throws Exception
	{
		// The Memory window outlived the plugin, and its button still wiped
		// the stopped plugin's memory. Here a stopped plugin has no config
		// manager at all, so anything it tried would throw.
		FollowerPlugin plugin = new FollowerPlugin();
		Field thread = FollowerPlugin.class.getDeclaredField("clientThread");
		thread.setAccessible(true);
		thread.set(plugin, new ClientThread()
		{
			@Override
			public void invoke(Runnable r)
			{
				r.run();
			}
		});
		Field started = FollowerPlugin.class.getDeclaredField("started");
		started.setAccessible(true);
		assertFalse((Boolean) started.get(plugin));
		Method forget = FollowerPlugin.class.getDeclaredMethod("forgetEverything");
		forget.setAccessible(true);
		forget.invoke(plugin);
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.lang.reflect.Field;
