	{
		List<Crossing.Frame> frames = new ArrayList<>();
		frames.add(new Crossing.Frame(500, 50 * 128 + 64, 50 * 128 + 64, 0, 1536, 808, 0, 741, 0));
		frames.add(new Crossing.Frame(1500, 52 * 128 + 64, 50 * 128 + 64, 0, 1536, 808, 0, 741, 9));
		frames.add(new Crossing.Frame(2000, 53 * 128 + 64, 51 * 128 + 64, 1, 1024, 762, 3, -1, 0));
		Crossing crossing = new Crossing(frames, NORMAL, false);

		assertEquals("rebased to its first frame", 1500, crossing.getDurationMs());
		assertEquals(new WorldPoint(50, 50, 0), crossing.getStart());
		assertEquals(new WorldPoint(53, 51, 1), crossing.getEnd());
		assertEquals("half way along the glide", 51 * 128 + 64, crossing.fineAt(500)[0]);
		assertEquals(0, crossing.frameAt(999).getPlane());
		assertEquals("a floor change is not glided across", 52 * 128 + 64, crossing.fineAt(1200)[0]);
		assertEquals(1, crossing.frameAt(1500).getPlane());
		assertEquals(762, crossing.frameAt(1500).getPose());
		assertEquals(-1, crossing.frameAt(1500).getAction());
		assertEquals(1, crossing.normalIndex(819));
		assertEquals(-1, crossing.normalIndex(762));
	}

	// ---------------------------------------------------------------- helpers

	private void frame(long ms)
	{
		for (int i = 0; i < framesPerCycle; i++)
		{
			t += ms / framesPerCycle;
			watch.sample(new CrossingWatch.Sample(t, x, y, plane, 0, pose, 0, action, 0,
				base, weapon, interacting,
				server != null ? server : new WorldPoint((int) (x >> 7), (int) (y >> 7), plane)));
		}
	}

	private void stand(long ms)
	{
		for (long i = 0; i < ms; i += 20)
		{
			frame(20);
		}
	}

	/** Steps in a walking (or swapped) pose at so many fine units a frame. */
	private void walk(int tilesX, int tilesY, int walkPose, int unitsPerFrame)
	{
		move(tilesX, tilesY, walkPose, unitsPerFrame);
	}

	/** Forced movement: the same, with whatever pose the game leaves on. */
	private void glide(int tilesX, int tilesY, int glidePose, int unitsPerFrame)
	{
		move(tilesX, tilesY, glidePose, unitsPerFrame);
	}

	private void move(int tilesX, int tilesY, int movePose, int unitsPerFrame)
	{
		long toX = x + tilesX * 128L;
		long toY = y + tilesY * 128L;
		pose = movePose;
		while (x != toX || y != toY)
		{
			x += Math.max(-unitsPerFrame, Math.min(unitsPerFrame, toX - x));
			y += Math.max(-unitsPerFrame, Math.min(unitsPerFrame, toY - y));
			frame(20);
		}
		pose = base[0];
	}

	private static List<Integer> poses(Crossing crossing)
	{
		List<Integer> out = new ArrayList<>();
		crossing.getFrames().forEach(f -> out.add(f.getPose()));
		return out;
	}

	private static List<Integer> actions(Crossing crossing)
	{
		List<Integer> out = new ArrayList<>();
		crossing.getFrames().forEach(f -> out.add(f.getAction()));
		return out;
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The files in {@code ~/.runelite/follower} on a bad day.
 *
 * <p>These are dumps and caches rather than settings, and every one of them is
 * loaded during startUp. A throw there does not degrade a feature, it aborts
 * the whole plugin: RuneLite catches it and switches Follower Buddy off. So the
 * bar for all of them is the same - a missing file, an empty file, a truncated
 * file or outright junk has to leave the plugin running, however little it can
 * do afterwards.
 */
public class DataFileRobustnessTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** The ways a file on disk actually goes wrong. */
	private static final String[] BROKEN = {
		"",
		"   ",
		"null",
		"{",
		"[]",
		"[1, 2, 3]",
		"\"a string\"",
		"{\"version\": 999}",
		"{\"version\": 1}",
		"{\"version\": 1, \"items\": null}",
		"{\"version\": 1, \"spotanims\": null}",
		"not json at all",
		"{\"truncated\": ",
	};

	private Path dir() throws IOException
	{
		return folder.newFolder().toPath();
	}

	private Path write(String name, String contents) throws IOException
	{
		Path dir = dir();
		Files.write(dir.resolve(name), contents.getBytes(StandardCharsets.UTF_8));
		return dir;
	}

	// --------------------------------------------------------------- missing

	@Test
	public void everyStoreCopesWithAnEmptyDataDirectory() throws IOException
	{
		Path empty = dir();

	}

	// -------------------------------------------------------------- corrupt

	private static String summarise(String contents)
	{
		return contents.length() > 30 ? contents.substring(0, 30) + "..." : "'" + contents + "'";
	}

	// ------------------------------------------------------------- bundled

	@Test
	public void theBundledStanceLibraryIsReadableOnAFreshInstall() throws IOException
	{
		// Not a data file the user owns, but it loads on the same path and a
		// failure here would leave every weapon animating as unarmed.
		StanceLibrary library =
			new StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		library.load(dir());

		assertTrue("the shipped stance library is empty or unreadable",
			library.size() > 100);
		assertNotNull("unarmed must always resolve", library.forWeapon(0));
	}

	@Test
	public void aCorruptLearnedStanceFileFallsBackToTheBundledOne() throws IOException
	{
		Path dir = write("stances.json", "{ this is broken");

		StanceLibrary library =
			new StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		library.load(dir);

		assertTrue("a broken learned file must not take the shipped stances"
			+ " down with it", library.size() > 100);
	}

	@Test
	public void savingWithNothingToSaveWritesNothingSurprising() throws IOException
	{
		Path dir = dir();
		StanceLibrary library =
			new StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		library.load(dir);
		library.save();

		// Whatever it wrote, reading it back has to work.
		StanceLibrary again =
			new StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		again.load(dir);
		assertTrue(again.size() > 100);
	}

	// ------------------------------------------------------ unwritable places

	@Test
	public void savingIntoAPlaceThatCannotBeWrittenIsNotACrash() throws IOException
	{
		Path dir = dir();
		StanceLibrary library =
			new StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		library.load(dir);
		library.setManual(999999, 808, 819, 824, 390);

		// Replace the target with a directory so the write cannot succeed.
		Files.deleteIfExists(dir.resolve("stances.json"));
		Files.createDirectories(dir.resolve("stances.json"));

		library.save();

		assertFalse("a failed save must not be fatal", Files.isRegularFile(
			dir.resolve("stances.json")));
	}
}

