package com.follower;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * The Blender export tools never ship. They live on the dev/model-export
 * branch and write to ~/follower-studio, apart from the plugin; a release
 * that picked them up by a careless commit or merge fails here.
 *
 * <p>A checkout that is meant to carry them says so with an untracked
 * {@code .dev-tools-allowed} file at its root. It is gitignored, so the
 * permission cannot be committed along with the tools.
 */
public class DevToolsStayOutTest
{
	private static final String[] MARKS = {
		"follower-studio", "STUDIO_EXPORTS", "exportChatbox", "ModelExporter", "AreaExporter", "follower export",
	};

	@Test
	public void theExportToolsAreNotInTheRelease() throws IOException
	{
		if (Files.exists(Paths.get(".dev-tools-allowed")))
		{
			return;
		}
		List<String> found = new ArrayList<>();
		if (Files.exists(Paths.get("src/main/java/com/follower/dev")))
		{
			found.add("src/main/java/com/follower/dev/");
		}
		if (Files.exists(Paths.get("tools/blender")))
		{
			found.add("tools/blender/");
		}
		try (Stream<Path> files = Files.walk(Paths.get("src/main")))
		{
			for (Path file : (Iterable<Path>) files.filter(Files::isRegularFile)::iterator)
			{
				String text = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
				for (String mark : MARKS)
				{
					if (text.contains(mark))
					{
						found.add(file + ": " + mark);
					}
				}
			}
		}
		assertTrue("dev export tools in the release: " + found, found.isEmpty());
	}
}

package com.follower;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The conversation trees have the same upgrade gap the rules had.
 *
 * <p>Appending only whole new trees meant a reworded node, an added choice or
 * a fixed dead end reached nobody who already had the plugin. The trees change
 * rarely, which is exactly why this would have gone unnoticed for a long time:
 * the bug only shows the day somebody finally edits one.
 *
 * <p>Trees merge at two levels, so these tests work at both - a tree's own
 * fields, and the nodes inside it.
 */
public class DialogMergeTest
{
	private static final Gson GSON = new Gson();

	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static JsonObject shipped()
	{
		try (InputStream in = DialogLoader.class
			.getResourceAsStream("/com/follower/default-dialogs.json"))
		{
			return GSON.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8),
				JsonObject.class);
		}
		catch (Exception e)
		{
			throw new AssertionError(e);
		}
	}

	private static JsonObject tree(JsonObject file, String id)
	{
		for (JsonElement e : file.getAsJsonArray("trees"))
		{
			if (id.equals(e.getAsJsonObject().get("id").getAsString()))
			{
				return e.getAsJsonObject();
			}
		}
		return null;
	}

	private static String firstTreeId(JsonObject file)
	{
		return file.getAsJsonArray("trees").get(0).getAsJsonObject().get("id").getAsString();
	}

	private static JsonObject node(JsonObject file, String treeId, String nodeId)
	{
		for (JsonElement e : tree(file, treeId).getAsJsonArray("nodes"))
		{
			if (nodeId.equals(e.getAsJsonObject().get("id").getAsString()))
			{
				return e.getAsJsonObject();
			}
		}
		return null;
	}

	private static String firstNodeId(JsonObject file, String treeId)
	{
		return tree(file, treeId).getAsJsonArray("nodes").get(0)
			.getAsJsonObject().get("id").getAsString();
	}

	private static List<String> says(JsonObject node)
	{
		List<String> out = new ArrayList<>();
		for (JsonElement e : node.getAsJsonArray("says"))
		{
			out.add(e.getAsString());
		}
		return out;
	}

	private static void setSays(JsonObject node, List<String> lines)
	{
		JsonArray says = new JsonArray();
		lines.forEach(says::add);
		node.add("says", says);
	}

	/**
	 * A previous version: the first node of the first tree short of its last
	 * line. Built from the shipped file so everything else is genuinely real.
	 */
	private static JsonObject previousVersion()
	{
		JsonObject old = shipped();
		String t = firstTreeId(old);
		JsonObject n = node(old, t, firstNodeId(old, t));
		List<String> fewer = new ArrayList<>(says(n));
		fewer.remove(fewer.size() - 1);
		setSays(n, fewer);
		return old;
	}

	private JsonObject merge(JsonObject theirs, JsonObject base) throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve(DialogLoader.FILE_NAME),
			GSON.toJson(theirs).getBytes(StandardCharsets.UTF_8));
		if (base != null)
		{
			Files.write(dir.resolve(DialogLoader.BASE_FILE),
				GSON.toJson(base).getBytes(StandardCharsets.UTF_8));
		}
		new DialogLoader(GSON).initialise(dir, true);
		return GSON.fromJson(new String(
			Files.readAllBytes(dir.resolve(DialogLoader.FILE_NAME)), StandardCharsets.UTF_8),
			JsonObject.class);
	}

	@Test
	public void aRewordedNodeReachesAnExistingInstall() throws Exception
	{
		JsonObject merged = merge(previousVersion(), previousVersion());

		String t = firstTreeId(merged);
		assertEquals("the line the update added arrives",
			says(node(shipped(), t, firstNodeId(shipped(), t))),
			says(node(merged, t, firstNodeId(merged, t))));
	}

	@Test
	public void aLineThePlayerDeletedFromANodeStaysDeleted() throws Exception
	{
		JsonObject base = previousVersion();
		JsonObject theirs = previousVersion();
		String t = firstTreeId(theirs);
		JsonObject n = node(theirs, t, firstNodeId(theirs, t));
		List<String> without = new ArrayList<>(says(n));
		String removed = without.remove(0);
		setSays(n, without);

		JsonObject merged = merge(theirs, base);

		assertFalse("their deletion is a decision",
			says(node(merged, t, firstNodeId(merged, t))).contains(removed));
	}

	@Test
	public void aNodeThePlayerRewroteIsTheirs() throws Exception
	{
		JsonObject base = previousVersion();
		JsonObject theirs = previousVersion();
		String t = firstTreeId(theirs);
		String id = firstNodeId(theirs, t);
		setSays(node(theirs, t, id), java.util.Arrays.asList("My own opening."));

		JsonObject merged = merge(theirs, base);

		assertTrue("what they wrote survives",
			says(node(merged, t, id)).contains("My own opening."));
	}

	@Test
	public void aNodeTheUpdateAddedArrives() throws Exception
	{
		// Base and theirs both lack a node the shipped file has.
		JsonObject base = previousVersion();
		JsonObject theirs = previousVersion();
		String t = firstTreeId(theirs);
		String doomed = tree(shipped(), t).getAsJsonArray("nodes")
			.get(1).getAsJsonObject().get("id").getAsString();
		for (JsonObject file : new JsonObject[]{base, theirs})
		{
			JsonArray kept = new JsonArray();
			for (JsonElement e : tree(file, t).getAsJsonArray("nodes"))
			{
				if (!doomed.equals(e.getAsJsonObject().get("id").getAsString()))
				{
					kept.add(e);
				}
			}
			tree(file, t).add("nodes", kept);
		}

		JsonObject merged = merge(theirs, base);

		assertNotNull("a node the update added arrives", node(merged, t, doomed));
	}

	@Test
	public void aNodeThePlayerDeletedStaysDeleted() throws Exception
	{
		// The base HAS the node, so its absence from theirs is a deletion.
		JsonObject base = previousVersion();
		JsonObject theirs = previousVersion();
		String t = firstTreeId(theirs);
		String gone = tree(theirs, t).getAsJsonArray("nodes")
			.get(1).getAsJsonObject().get("id").getAsString();
		JsonArray kept = new JsonArray();
		for (JsonElement e : tree(theirs, t).getAsJsonArray("nodes"))
		{
			if (!gone.equals(e.getAsJsonObject().get("id").getAsString()))
			{
				kept.add(e);
			}
		}
		tree(theirs, t).add("nodes", kept);

		JsonObject merged = merge(theirs, base);

		assertNull("a node they removed is not put back", node(merged, t, gone));
	}

	@Test
	public void mergingTwiceChangesNothingTheSecondTime() throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve(DialogLoader.FILE_NAME),
			GSON.toJson(previousVersion()).getBytes(StandardCharsets.UTF_8));
		Files.write(dir.resolve(DialogLoader.BASE_FILE),
			GSON.toJson(previousVersion()).getBytes(StandardCharsets.UTF_8));

		new DialogLoader(GSON).initialise(dir, true);
		String once = new String(Files.readAllBytes(dir.resolve(DialogLoader.FILE_NAME)),
			StandardCharsets.UTF_8);
		new DialogLoader(GSON).initialise(dir, true);
		String twice = new String(Files.readAllBytes(dir.resolve(DialogLoader.FILE_NAME)),
			StandardCharsets.UTF_8);

		assertEquals(once, twice);
	}

	/**
	 * The trees exactly as 1.4.0 wrote them on a fresh install, which recorded
	 * nothing, so its first update had no base.
	 */
	private static JsonObject freshFrom140()
	{
		try (InputStream in = DialogLoader.class
			.getResourceAsStream("/com/follower/seen/1.4.0-dialogs.json"))
		{
			return GSON.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8),
				JsonObject.class);
		}
		catch (Exception e)
		{
			throw new AssertionError(e);
		}
	}

	@Test
	public void aFreshInstallFrom140ThatNobodyEditedBecomesTheNewDefaults() throws Exception
	{
		JsonObject merged = merge(freshFrom140(), null);

		for (JsonElement e : shipped().getAsJsonArray("trees"))
		{
			String id = e.getAsJsonObject().get("id").getAsString();
			assertEquals("every tree as it ships now: " + id, e, tree(merged, id));
		}
	}

	@Test
	public void aLineDeletedOnAFreshInstallFrom140StaysDeleted() throws Exception
	{
		JsonObject theirs = freshFrom140();
		String t = firstTreeId(theirs);
		JsonObject n = node(theirs, t, firstNodeId(theirs, t));
		List<String> fewer = new ArrayList<>(says(n));
		String deleted = fewer.remove(fewer.size() - 1);
		setSays(n, fewer);

		JsonObject merged = merge(theirs, null);

		assertFalse(says(node(merged, t, firstNodeId(merged, t))).contains(deleted));
	}

	@Test
	public void aFreshInstallRecordsWhatItWrote() throws Exception
	{
		Path dir = folder.newFolder().toPath();
		new DialogLoader(GSON).initialise(dir, true);

		assertEquals(shipped(), GSON.fromJson(new String(
			Files.readAllBytes(dir.resolve(DialogLoader.BASE_FILE)), StandardCharsets.UTF_8),
			JsonObject.class));
	}

	@Test
	public void theBaseIsRecordedSoTheGuessworkHappensOnlyOnce() throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve(DialogLoader.FILE_NAME),
			GSON.toJson(previousVersion()).getBytes(StandardCharsets.UTF_8));
		assertFalse(Files.exists(dir.resolve(DialogLoader.BASE_FILE)));

		new DialogLoader(GSON).initialise(dir, true);

		assertTrue(Files.exists(dir.resolve(DialogLoader.BASE_FILE)));
	}
}

package com.follower;

import java.util.function.ToIntFunction;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

/**
 * A long line in a dialogue box goes onto more pages, four lines to a page,
 * as the game's own boxes hold; a line break typed into it starts a new line;
 * and text with no break wraps exactly as it always did.
 */
public class DialogPagingTest
{
	/** Every character six pixels wide, so a 60-pixel column holds ten. */
	private static final ToIntFunction<String> SIX = String::length;

	private static String[] wrap(String text)
	{
		return FollowerDialog.wrap(text, s -> SIX.applyAsInt(s) * 6, 60);
	}

	@Test
	public void textWithNoBreakWrapsAsItAlwaysDid()
	{
		assertArrayEquals(new String[]{"one two", "three four", "five"}, wrap("one two three four five"));
		assertArrayEquals(new String[0], wrap(""));
	}

	@Test
	public void aWordTooWideForTheColumnIsCutWhereItStopsFitting()
	{
		// QA2, 15 Oct: left whole, a pasted link ran over the chathead and
		// past both edges of the box.
		assertArrayEquals(new String[]{"a", "unbreakabl", "ething b"}, wrap("a unbreakablething b"));
		assertArrayEquals(new String[]{"aaaaaaaaaa", "aaaaaaaaaa", "aaaaa"}, wrap("a".repeat(25)));
		for (String line : wrap("see https://example.com/a/very/long/link/with/no/spaces ok"))
		{
			assertEquals(line, true, line.length() * 6 <= 60);
		}
	}

	@Test
	public void aTypedBreakStartsANewLineAndABlankOneIsKept()
	{
		assertArrayEquals(new String[]{"Hello.", "Bye."}, wrap("Hello.\nBye."));
		assertArrayEquals(new String[]{"Hello.", "", "Bye."}, wrap("Hello.\n\nBye."));
		assertArrayEquals(new String[]{"one two", "three", "four"}, wrap("one two three\nfour"));
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * WHEN a conversation delivers its answer.
 *
 * <p>Lives in the engine's own package because the seams it uses are: reaching
 * a node the real way needs a follower to face the player and a client to
 * compose a chathead from, and neither exists headlessly. The moment the answer
 * lands is worth pinning down on its own anyway - it is not a detail of
 * rendering, it is the difference between hearing the reply and missing it.
 */
public class DialogTimingTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private DialogTree shippedTree() throws IOException
	{
		DialogLoader loader = new DialogLoader(new Gson());
		loader.initialise(folder.newFolder().toPath());
		DialogTree tree = loader.get("want-outing");
		assertNotNull("the shipped question tree", tree);
		return tree;
	}

	private static String answeringNode(DialogTree tree)
	{
		for (DialogTree.DialogNode node : tree.nodes)
		{
			if (node.answer != null)
			{
				return node.id;
			}
		}
		throw new AssertionError("the tree has no answering node");
	}

	@Test
	public void theAnswerIsDeliveredWhenTheBoxCloses() throws IOException
	{
		// The follower's reply to its own question goes OVERHEAD. Delivering
		// the answer the instant the branch is picked puts that line above a
		// dialog box the player is still reading, so the one thing they were
		// waiting to hear is the one thing they miss.
		DialogTree tree = shippedTree();
		List<String> answers = new ArrayList<>();
		Map<String, FollowerDialog.Node> script = FollowerDialog.build(tree, answers::add);

		FollowerDialog dialog = new FollowerDialog(null, null, null, null, null, null, null, null);
		dialog.openForTest(script);

		dialog.reachForTest(answeringNode(tree));
		assertTrue("picking the branch must not deliver it yet", answers.isEmpty());

		dialog.close();
		assertEquals("closing the box is what delivers it", 1, answers.size());

		dialog.close();
		assertEquals("and it must not arrive twice", 1, answers.size());
	}

	@Test
	public void closingEarlyStillCounts() throws IOException
	{
		// Walking off, or being interrupted, after picking an answer. The
		// player answered; whether they read the rest of it is their business,
		// and a follower that forgot the answer because the box was dismissed
		// would look like it had not been listening.
		DialogTree tree = shippedTree();
		List<String> answers = new ArrayList<>();
		FollowerDialog dialog = new FollowerDialog(null, null, null, null, null, null, null, null);
		dialog.openForTest(FollowerDialog.build(tree, answers::add));

		dialog.reachForTest(answeringNode(tree));
		dialog.close();
		assertEquals(1, answers.size());
	}

	@Test
	public void aFreshConversationInheritsNoAnswerFromTheLastOne() throws IOException
	{
		DialogTree tree = shippedTree();
		List<String> answers = new ArrayList<>();
		Map<String, FollowerDialog.Node> script = FollowerDialog.build(tree, answers::add);

		FollowerDialog dialog = new FollowerDialog(null, null, null, null, null, null, null, null);
		dialog.openForTest(script);
		dialog.reachForTest(answeringNode(tree));

		// Talked to again before the first one ended. A latch carried across
		// would answer a question that is no longer being asked.
		dialog.openForTest(script);
		dialog.close();
		assertTrue("a new conversation must not carry the old latch", answers.isEmpty());
	}

	@Test
	public void aConversationNobodyAnsweredDeliversNothing() throws IOException
	{
		DialogTree tree = shippedTree();
		List<String> answers = new ArrayList<>();
		FollowerDialog dialog = new FollowerDialog(null, null, null, null, null, null, null, null);
		dialog.openForTest(FollowerDialog.build(tree, answers::add));

		dialog.reachForTest(tree.startId());
		dialog.close();
		assertTrue("opening and shutting the box is not an answer", answers.isEmpty());
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The conversations the follower opens, which are data rather than code.
 *
 * <p>A dialog fails in the worst way available: the box opens and shuts again,
 * or a branch dead-ends on a node id with a typo in it, and the player is
 * already inside it when that happens. Nothing about that shows up as an error
 * at runtime, so every structural check is made once at load and again here.
 */
public class DialogTreeTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private DialogLoader loaded() throws IOException
	{
		DialogLoader loader = new DialogLoader(new Gson());
		loader.initialise(folder.newFolder().toPath());
		return loader;
	}

	private DialogLoader loadedFrom(String json) throws IOException
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve(DialogLoader.FILE_NAME), json.getBytes(StandardCharsets.UTF_8));
		DialogLoader loader = new DialogLoader(new Gson());
		loader.initialise(dir);
		return loader;
	}

	@Test
	public void theShippedTreesLoadWithoutComplaint() throws IOException
	{
		DialogLoader loader = loaded();
		assertTrue("the trees the plugin ships must load clean: " + loader.getErrors(),
			loader.getErrors().isEmpty());
		assertFalse("and there has to be at least one", loader.getTrees().isEmpty());
	}

	@Test
	public void everyBranchLeadsSomewhereReal() throws IOException
	{
		// The failure this exists for: a branch pointing at a node id that does
		// not exist. The conversation simply stops, mid-sentence, with the
		// player looking at a closed box wondering what they did wrong.
		DialogLoader loader = loaded();
		for (DialogTree tree : loader.getTrees())
		{
			assertEquals(tree.id + " has structural problems", 0, tree.problems().size());
		}
	}

	@Test
	public void aTreeWithADeadBranchIsRefusedRatherThanHalfLoaded() throws IOException
	{
		// Everything else about this tree is fine - it answers, it starts
		// somewhere real - so the ONLY thing wrong is the branch pointing at a
		// node called "nowhere". Anything else here and the test would pass on
		// the strength of a different check.
		DialogLoader loader = loadedFrom("{\"version\": 1, \"trees\": [{"
			+ "\"id\": \"broken\", \"start\": \"a\", \"nodes\": ["
			+ "{\"id\": \"a\", \"says\": [\"hello\"], \"choices\": ["
			+ "{\"label\": \"fine\", \"next\": \"b\"},"
			+ "{\"label\": \"onwards\", \"next\": \"nowhere\"}]},"
			+ "{\"id\": \"b\", \"says\": [\"right\"], \"answer\": \"yes\"}]}]}");

		assertNull("a tree that can dead-end must not be offered at all",
			loader.get("broken"));
		assertTrue("and the reason has to name the branch: " + loader.getErrors(),
			loader.getErrors().toString().contains("nowhere"));
	}

	@Test
	public void aTreeNobodyCanAnswerIsRefused() throws IOException
	{
		// These trees exist to collect an answer. One with no answer in it is a
		// conversation that wastes the single moment the follower had.
		DialogLoader loader = loadedFrom("{\"version\": 1, \"trees\": [{"
			+ "\"id\": \"pointless\", \"start\": \"a\", \"nodes\": ["
			+ "{\"id\": \"a\", \"says\": [\"nice weather\"]}]}]}");

		assertNull(loader.get("pointless"));
	}

	@Test
	public void aBadReadKeepsTheTreesItAlreadyHad() throws IOException
	{
		Path dir = folder.newFolder().toPath();
		DialogLoader loader = new DialogLoader(new Gson());
		loader.initialise(dir);
		int before = loader.getTrees().size();
		assertTrue("start from something", before > 0);

		// What a poll sees between an editor truncating the file and writing it
		// back. Losing every conversation over that would be absurd.
		Files.write(dir.resolve(DialogLoader.FILE_NAME), new byte[0]);
		loader.reload();
		assertEquals("an empty read must not wipe the trees",
			before, loader.getTrees().size());

		Files.write(dir.resolve(DialogLoader.FILE_NAME),
			"{ not json at all".getBytes(StandardCharsets.UTF_8));
		loader.reload();
		assertEquals("nor must a syntax error", before, loader.getTrees().size());
		assertFalse(loader.getErrors().isEmpty());
	}

	@Test
	public void buildingATreeCarriesTheChoicesAndTheAnswerAcross() throws IOException
	{
		DialogLoader loader = loaded();
		DialogTree tree = loader.get("want-outing");
		assertNotNull("the shipped question tree", tree);

		List<String> answers = new ArrayList<>();
		Map<String, FollowerDialog.Node> script =
			FollowerDialog.build(tree, answers::add);

		assertTrue("every node has to survive the build",
			script.keySet().containsAll(tree.byId().keySet()));
		assertNotNull("and it has to start somewhere", script.get(tree.startId()));

		// Both answers have to be reachable, or the player has been offered a
		// question they can only answer one way.
		Set<String> reachable = new HashSet<>();
		for (DialogTree.DialogNode node : tree.nodes)
		{
			if (node.answer != null)
			{
				reachable.add(node.answer.toLowerCase(java.util.Locale.ROOT));
			}
		}
		assertTrue("yes has to be sayable", reachable.contains("yes"));
		assertTrue("and so does no", reachable.contains("no"));
	}

	@Test
	public void everyAskedTreeIsOneThatExists() throws IOException
	{
		// A rule naming a tree that is not there falls back to the everyday
		// script, so the follower asks a question and then has nothing to say
		// about it when you come over - which looks exactly like a bug.
		DialogLoader dialogs = loaded();
		RuleLoader rules = new RuleLoader(new Gson());
		rules.initialise(folder.newFolder().toPath());

		int asking = 0;
		for (SpeechRule rule : rules.getRules())
		{
			if (rule.asks == null || rule.asks.isEmpty())
			{
				continue;
			}
			asking++;
			assertNotNull(rule.id + " asks via '" + rule.asks
				+ "', which is not a tree in dialogs.json", dialogs.get(rule.asks));
		}
		assertTrue("something has to be asking, or none of this runs", asking > 0);
	}

	@Test
	public void everyAnswerATreeCanGiveHasARuleListeningForIt() throws IOException
	{
		// An answer is any plain word now, not just yes and no. That is what
		// lets a tree be a game, and it is also what makes this check the only
		// thing standing between "left" and a typo: an answered rule spelt
		// wrong never fires, and a tree branch nothing listens for means the
		// player picks an option and the follower stares back.
		DialogLoader dialogs = loaded();
		RuleLoader rules = new RuleLoader(new Gson());
		rules.initialise(folder.newFolder().toPath());

		Set<String> offered = new TreeSet<>();
		for (DialogTree tree : dialogs.getTrees())
		{
			for (DialogTree.DialogNode node : tree.nodes)
			{
				if (node.answer != null && !node.answer.isEmpty())
				{
					offered.add(node.answer.toLowerCase(java.util.Locale.ROOT));
				}
			}
		}

		// The everyday talk script is the second source of answers - "gift"
		// was its first. Those only exist inside finish runnables, so the
		// honest enumeration is to run every node's finish against a
		// recording consumer. Built with a wish open in BOTH bag states,
		// because the script branches on the bag and each branch answers
		// differently: gift with the thing held, bluff without - and in a
		// low band too, because "comforted" only exists behind the
		// sharpened question.
		for (boolean held : new boolean[]{true, false})
		{
			for (String band : new String[]{"even", "low"})
			{
				for (FollowerDialog.Node node : FollowerPlugin.talkScript(TalkScriptTest.talk(),
					() -> new String[]{""},
					answer -> offered.add(answer.toLowerCase(java.util.Locale.ROOT)),
					band).values())
				{
					node.runFinish();
				}
			}
		}

		Set<String> listened = new TreeSet<>();
		for (SpeechRule rule : rules.getRules())
		{
			collectAnswers(rule.when, listened);
		}

		Set<String> deaf = new TreeSet<>(offered);
		deaf.removeAll(listened);
		assertTrue("answers a tree can give that no rule reacts to, so picking"
			+ " them does nothing: " + deaf, deaf.isEmpty());

		Set<String> imagined = new TreeSet<>(listened);
		imagined.removeAll(offered);
		assertTrue("rules waiting on answers no tree can give, so they can never"
			+ " fire: " + imagined, imagined.isEmpty());
	}

	private static void collectAnswers(Condition condition, Set<String> into)
	{
		if (condition == null)
		{
			return;
		}
		if ("answered".equalsIgnoreCase(condition.type) && condition.is != null)
		{
			into.add(condition.is.toLowerCase(java.util.Locale.ROOT));
		}
		if (condition.conditions != null)
		{
			for (Condition child : condition.conditions)
			{
				collectAnswers(child, into);
			}
		}
	}

	@Test
	public void everyQuestionRefusesToTalkOverAnotherOne() throws IOException
	{
		// Opening a question REPLACES whatever was waiting for an answer. With
		// one question in the file that was harmless; with two, a follower that
		// asks to go somewhere and then offers a game has silently withdrawn
		// the outing, and the player answers a question nobody is listening
		// for. The guard is a none/asking block, and every asks rule needs it.
		RuleLoader rules = new RuleLoader(new Gson());
		rules.initialise(folder.newFolder().toPath());

		List<String> unguarded = new ArrayList<>();
		for (SpeechRule rule : rules.getRules())
		{
			if (rule.asks == null || rule.asks.isEmpty())
			{
				continue;
			}
			if (rule.when == null || !rule.when.usesType("asking"))
			{
				unguarded.add(rule.id);
			}
		}
		assertTrue("rules that ask a question without checking whether one is"
			+ " already on the table: " + unguarded, unguarded.isEmpty());
	}
}

package com.follower;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * While an NPC dialogue is up the follower's words are dropped, and nothing
 * downstream of them happens: the latch a line carries - the question it
 * asks, the want, the wish, the wear, a first spent, a souvenir, a bet -
 * never closes on a line nobody heard.
 *
 * <p>The drop happens at the plugin's one door for speech, which no harness
 * drives, so this goes through that door on a bare plugin the way the entity
 * tests reach private state. The client has only the dialogue up, and the
 * rest of the plugin is left empty on purpose: a hushed line must not get far
 * enough to need it.
 */
public class DialogueHushTest
{
	/** A client with the one interface up, or nothing up at all for -1. */
	private static Client withOpen(int group)
	{
		Widget box = (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(),
			new Class<?>[]{Widget.class}, (proxy, method, args) -> nothing(method.getReturnType()));
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				if (method.getName().equals("getWidget") && args.length == 2)
				{
					return (Integer) args[0] == group ? box : null;
				}
				return nothing(method.getReturnType());
			});
	}

	private static Object nothing(Class<?> type)
	{
		return type == int.class ? 0 : type == long.class ? 0L : type == boolean.class ? false : null;
	}

	/** Says a line with a latch on it through the plugin's door; whether the latch closed. */
	private static boolean latched(int open) throws ReflectiveOperationException
	{
		FollowerPlugin plugin = new FollowerPlugin();
		set(plugin, "client", withOpen(open));
		set(plugin, "config", new FollowerConfig()
		{
		});

		boolean[] said = {false};
		Class<?> utterance = Class.forName("com.follower.FollowerPlugin$Utterance");
		Constructor<?> line = utterance.getDeclaredConstructor(String.class, SpeechOutput.class,
			SpeechRule.class, int.class, Runnable.class);
		line.setAccessible(true);
		Method speakNow = FollowerPlugin.class.getDeclaredMethod("speakNow", utterance);
		speakNow.setAccessible(true);
		// The chatbox output, with mirroring off: a line that lands goes
		// nowhere visible, so only the latch is left to say whether it did.
		Runnable onSaid = () -> said[0] = true;
		speakNow.invoke(plugin, line.newInstance("Talk to me a minute?", SpeechOutput.CHATBOX,
			null, -1, onSaid));
		return said[0];
	}

	private static void set(Object target, String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(target, value);
	}

	@Test
	public void withNoDialogueUpTheLineLandsAndItsLatchCloses() throws ReflectiveOperationException
	{
		// The probe has to see a latch close before its silence means anything.
		assertTrue(latched(-1));
	}

	@Test
	public void aDialogueOfAnyShapeDropsTheLineAndItsLatch() throws ReflectiveOperationException
	{
		assertFalse("the NPC's head on the left", latched(InterfaceID.CHAT_LEFT));
		assertFalse("the player's own on the right", latched(InterfaceID.CHAT_RIGHT));
		assertFalse("and the options menu, which is still their conversation",
			latched(InterfaceID.CHATMENU));
	}
}

package com.follower;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Which side-step a weapon uses when its own was never observed.
 *
 * <p>The measured rule, and the one that produced the visible bug: of the 26
 * weapons using the DEFAULT walk, all 26 also use the default side-steps, so
 * the standard set is exactly right for them. Of the 41 with a weapon-specific
 * walk, only 5 use the standard side-step and not one uses the standard
 * back-pedal - so borrowing it is wrong about nine times in ten, and it shows:
 * an empty-handed strafe while carrying a bulwark.
 *
 * <p>Anything with its own walk therefore falls back to that walk instead,
 * which is the client's own behaviour for a pose resolving to -1 and keeps the
 * weapon in hand.
 */
public class DirectionalFallbackTest
{
	private static final int STANDARD_SIDESTEP = PlayerPose.SIDESTEP_LEFT;
	private static final int STANDARD_BACKPEDAL = PlayerPose.TURN_180;

	private static StanceLibrary.Stance walkingWith(int walk)
	{
		StanceLibrary.Stance stance = new StanceLibrary.Stance();
		stance.walk = walk;
		return stance;
	}

	@Test
	public void anUnarmedStanceTakesTheStandardDirectionalPoses()
	{
		StanceLibrary.Stance unarmed = walkingWith(PlayerPose.WALK);

		assertEquals("a default walk means the default side-step is right",
			STANDARD_SIDESTEP,
			FollowerEntity.directionalFallback(unarmed, STANDARD_SIDESTEP));
		assertEquals(STANDARD_BACKPEDAL,
			FollowerEntity.directionalFallback(unarmed, STANDARD_BACKPEDAL));
	}

	@Test
	public void aWeaponWithItsOwnWalkKeepsWalkingRatherThanBorrowing()
	{
		// A bulwark, a halberd, anything carried distinctively.
		int weaponWalk = 7511;
		StanceLibrary.Stance armed = walkingWith(weaponWalk);

		assertEquals("strafing must not drop into the empty-handed side-step",
			weaponWalk,
			FollowerEntity.directionalFallback(armed, STANDARD_SIDESTEP));
		assertEquals("and nor must backing away",
			weaponWalk,
			FollowerEntity.directionalFallback(armed, STANDARD_BACKPEDAL));
	}

	@Test
	public void theRuleTurnsOnTheWalkAloneNotOnTheStandardAskedFor()
	{
		// Whatever pose is asked for, the answer depends only on whether this
		// stance walks the default way.
		StanceLibrary.Stance armed = walkingWith(9999);
		for (int standard : new int[]{PlayerPose.SIDESTEP_LEFT,
			PlayerPose.SIDESTEP_RIGHT, PlayerPose.TURN_180, PlayerPose.IDLE_TURN})
		{
			assertEquals(9999, FollowerEntity.directionalFallback(armed, standard));
		}

		StanceLibrary.Stance unarmed = walkingWith(PlayerPose.WALK);
		for (int standard : new int[]{PlayerPose.SIDESTEP_LEFT,
			PlayerPose.SIDESTEP_RIGHT, PlayerPose.TURN_180, PlayerPose.IDLE_TURN})
		{
			assertEquals(standard,
				FollowerEntity.directionalFallback(unarmed, standard));
		}
	}

	@Test
	public void aStanceWithNoWalkAtAllStillAnswersSomething()
	{
		// A stance saved before the directional fields existed deserialises
		// with zeroes; it must not hand back a standard pose as though the
		// weapon had been observed walking the default way.
		StanceLibrary.Stance empty = new StanceLibrary.Stance();
		assertEquals("a missing walk is not the default walk", 0,
			FollowerEntity.directionalFallback(empty, STANDARD_SIDESTEP));
	}

	@Test
	public void theBundledUnarmedStanceUsesTheStandardSet()
	{
		// The one stance that is built in rather than learned. If it ever
		// stopped matching PlayerPose.WALK, every unarmed follower would
		// strafe with the wrong animation.
		StanceLibrary library = new StanceLibrary(new com.google.gson.Gson(),
			new ModelRepository(new com.google.gson.Gson()));
		StanceLibrary.Stance unarmed = library.forWeapon(0);

		assertEquals("unarmed must walk with the standard walk pose",
			PlayerPose.WALK, unarmed.walk);
		assertEquals(STANDARD_SIDESTEP,
			FollowerEntity.directionalFallback(unarmed, STANDARD_SIDESTEP));
	}
}

package com.follower;

import net.runelite.api.kit.KitType;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The emote disarm empties the follower's hands; a borrowed tool must
 * survive it. The two are ordered in one place, and this pins the order.
 */
public class DisarmKeepsBorrowedToolTest
{
	private static Outfit armed()
	{
		Outfit outfit = new Outfit();
		outfit.setItem(KitType.WEAPON, 4151);
		outfit.setItem(KitType.SHIELD, 1540);
		return outfit;
	}

	@Test
	public void theDisarmEmptiesBothHands()
	{
		Outfit dressed = FollowerPlugin.dressForRender(armed(), true, null, 0);
		assertFalse(dressed.isItem(KitType.WEAPON));
		assertFalse(dressed.isItem(KitType.SHIELD));
	}

	@Test
	public void leftArmedTheOutfitKeepsItsOwnWeapon()
	{
		Outfit dressed = FollowerPlugin.dressForRender(armed(), false, null, 0);
		assertEquals(4151, dressed.itemId(KitType.WEAPON));
		assertEquals(1540, dressed.itemId(KitType.SHIELD));
	}

	@Test
	public void aBorrowedToolSurvivesTheMimic()
	{
		// The mirror rule puts the sword away; the axe the follower borrowed
		// goes back into the emptied hand, because the prop is laid on after.
		Outfit dressed = FollowerPlugin.dressForRender(armed(), true, KitType.WEAPON, 1351);
		assertEquals("the axe stays in hand", 1351, dressed.itemId(KitType.WEAPON));
		assertFalse("the shield still goes", dressed.isItem(KitType.SHIELD));
		assertTrue(dressed.isItem(KitType.WEAPON));
	}

	@Test
	public void thePropOutranksTheOutfitsOwnWeaponEvenArmed()
	{
		// The stance follows the weapon read after this, so a borrowed axe
		// gives the follower an axe stance for free.
		Outfit dressed = FollowerPlugin.dressForRender(armed(), false, KitType.WEAPON, 1351);
		assertEquals(1351, dressed.itemId(KitType.WEAPON));
	}

	@Test
	public void aPropInTheWeaponHandTakesTheShieldWithIt()
	{
		// The scroll is read two-handed and a tool is swung with the arm the
		// shield is on, so the shield goes whether or not anything disarmed.
		Outfit reading = FollowerPlugin.dressForRender(armed(), false, KitType.WEAPON, 10485);
		assertEquals("the scroll is in the hand", 10485, reading.itemId(KitType.WEAPON));
		assertFalse("and the shield is off the arm", reading.isItem(KitType.SHIELD));
	}

	@Test
	public void aPropInAnotherSlotLeavesTheHandsAlone()
	{
		// A borrowed hat is not an argument with the shield.
		Outfit dressed = FollowerPlugin.dressForRender(armed(), false, KitType.HEAD, 10941);
		assertEquals(10941, dressed.itemId(KitType.HEAD));
		assertEquals("the weapon stays", 4151, dressed.itemId(KitType.WEAPON));
		assertEquals("and so does the shield", 1540, dressed.itemId(KitType.SHIELD));
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;

/**
 * What one pass over the whole rule set costs.
 *
 * <p>Every rule is evaluated against every event, and the events are not rare:
 * a tick heartbeat, plus one per NPC entering or leaving the scene, which on a
 * chunk load is hundreds at once. This is not a benchmark to tune against - the
 * numbers move with the machine - but a tripwire for a change that makes the
 * pass pathologically slow, and a place to read the real figure from.
 */
public class DispatchCostTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void aFullRulePassIsCheapEnoughToRunHundredsOfTimesATick() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		int rules = h.loader.getRules().size();

		// A busy scene: enough NPCs that the nearby scans have real work.
		for (int i = 0; i < 60; i++)
		{
			h.game.spawnNpc(3029 + i, "Goblin " + i, 5);
		}
		h.gameTicks(5);

		// Warm up, so the timing is of the code and not of the JIT.
		for (int i = 0; i < 200; i++)
		{
			h.engine.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Goblin"));
		}
		h.clear();

		int passes = 2000;
		long start = System.nanoTime();
		for (int i = 0; i < passes; i++)
		{
			h.engine.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 3029, "Goblin"));
		}
		long spawnNanos = (System.nanoTime() - start) / passes;

		start = System.nanoTime();
		for (int i = 0; i < passes; i++)
		{
			h.engine.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_DESPAWN, 3029, "Goblin"));
		}
		long despawnNanos = (System.nanoTime() - start) / passes;

		start = System.nanoTime();
		for (int i = 0; i < passes; i++)
		{
			h.engine.dispatch(TriggerEvent.tick());
		}
		long tickNanos = (System.nanoTime() - start) / passes;

		System.out.printf("%n  rule pass over %d rules:%n"
				+ "    npc spawn   %6d ns%n"
				+ "    npc despawn %6d ns%n"
				+ "    tick        %6d ns%n%n",
			rules, spawnNanos, despawnNanos, tickNanos);

		// A game tick is 600ms and a chunk load can raise a few hundred spawns
		// inside one. Anything approaching a millisecond a pass would be felt.
		assertTrue("a single rule pass took " + spawnNanos + "ns, which would stall"
			+ " the client on a busy scene", spawnNanos < 1_000_000L);
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.lang.reflect.Field;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Back-to-back laps of the Draynor rooftop course as the user's own trace
 * (16 Oct) shows the game moving the player: the server a tile a tick
 * ahead of where the player is drawn, the drawn position moving once a
 * client cycle (20 ms) whatever the frame rate, the base set swapped for the
 * ropes and the narrow wall, the XP landing as each obstacle completes, and
 * the obstacle tiles themselves closed to anyone walking. Run at 50, 58, 100
 * and 150 frames a second.
 *
 * <p>What the user asked for: every obstacle copied, in order, none
 * skipped; the follower setting off on each about two ticks after the
 * player; and never hung up and placed or teleported mid-lap.
 *
 * <p>Course tiles are the real ones, moved into the test scene by
 * {@link #OFFSET_X} and {@link #OFFSET_Y}.
 */
public class DraynorLapReplayTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final int OFFSET_X = 3040;
	private static final int OFFSET_Y = 3220;

	/** The player's own set in the trace: a weapon's stand, walk and run. */
	private static final int[] NORMAL = {813, 1205, 1210, 1206, 1207, 1208, 1209, 1209};
	private static final int[] ON_A_ROPE = {763, 762, 762, 762, 762, 762, 763, 763};
	private static final int[] SIDESTEPPING = {757, 756, 756, 756, 756, 756, 757, 757};

	private static final int REACHFORLADDER = 828;
	private static final int INTO_SIDESTEPL = 753;
	private static final int OUTOF_SIDESTEPL = 759;
	private static final int WALL_JUMP = 2583;
	private static final int WALL_JUMP2 = 2585;
	private static final int WALL_JUMPDOWN = 2586;
	private static final int WALL_JUMPDOWN2 = 2588;

	/** Where each obstacle is begun, in lap order: rough wall, two ropes, narrow wall, wall, gap, crate. */
	private static final WorldPoint[] STARTS = {
		tile(3103, 3279, 0), tile(3098, 3277, 3), tile(3092, 3276, 3), tile(3089, 3265, 3),
		tile(3088, 3257, 3), tile(3094, 3255, 3), tile(3101, 3261, 3)};

	private FakeGame game;
	private FollowerEntity follower;
	private Player player;
	private int snaps;
	private final List<Crossing> done = new ArrayList<>();
	private final List<String> trace = new ArrayList<>();
	/** The real lag at each crossing the follower begins: the player's clock then, less when they began it. */
	private final List<Long> lags = new ArrayList<>();
	/** How long after the player began each one it was handed over: the lag nothing can beat. */
	private final List<Long> handedOver = new ArrayList<>();

	private static WorldPoint tile(int x, int y, int plane)
	{
		return new WorldPoint(x - OFFSET_X, y - OFFSET_Y, plane);
	}

	@Before
	public void setUp() throws IOException, ReflectiveOperationException
	{
		game = new FakeGame().withCollision().keepsRuneLiteObjects();
		for (int id : new int[]{REACHFORLADDER, INTO_SIDESTEPL, OUTOF_SIDESTEPL, WALL_JUMP, WALL_JUMP2,
			WALL_JUMPDOWN, WALL_JUMPDOWN2})
		{
			game.animation(id, -1);
		}
		for (int[] set : new int[][]{NORMAL, ON_A_ROPE, SIDESTEPPING})
		{
			for (int pose : set)
			{
				game.animation(pose, 0);
			}
		}
		// The obstacles: nobody walks onto a rope, the narrow wall, the wall
		// or over the gap. The server puts the player there; the follower
		// has to be put there by its recording. The first tile of each rope
		// and of the narrow wall closed as well: the worst case.
		for (int x = 3091; x <= 3098; x++)
		{
			block(x, 3277);
		}
		for (int y = 3267; y <= 3276; y++)
		{
			block(3092, y);
		}
		for (int y = 3262; y <= 3265; y++)
		{
			block(3089, y);
		}
		block(3088, 3256);
		block(3095, 3255);
		block(3095, 3256);

		StanceLibrary stances = new StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		stances.load(folder.newFolder().toPath());
		follower = new FollowerEntity(game.client, stances);
		follower.setOnSnapped(() -> snaps++);
		follower.setOnCrossed(done::add);
		set("object", new RuneLiteObject(game.client));
		set("animatable", true);
		set("spawned", true);
	}

	private void block(int x, int y)
	{
		game.blockTile(x - OFFSET_X, y - OFFSET_Y);
	}

	@Test
	public void lapsAtFiftyFramesASecond() throws ReflectiveOperationException
	{
		laps(50);
	}

	@Test
	public void lapsAtFiftyEightFramesASecondAsInTheTrace() throws ReflectiveOperationException
	{
		laps(58);
	}

	@Test
	public void lapsAtAHundredFramesASecond() throws ReflectiveOperationException
	{
		laps(100);
	}

	@Test
	public void lapsAtAHundredAndFiftyFramesASecond() throws ReflectiveOperationException
	{
		laps(150);
	}

	private static final int LAPS = 4;

	private void laps(int fps) throws ReflectiveOperationException
	{
		player = new Player(fps, tile(3103, 3271, 0));
		player.idle(3);
		trace.clear();
		snaps = 0;
		for (int lap = 0; lap < LAPS; lap++)
		{
			lap();
		}
		// The follower finishes the last crate behind the player.
		for (int i = 0; i < 20 && follower.isDoingAgility(); i++)
		{
			player.idle(1);
		}

		String report = fps + " fps: lags " + lags + ", handed over " + handedOver + "\n   "
			+ String.join("\n   ", trace);
		System.out.println("Draynor at " + fps + " fps: lags " + lags + ", handed over after " + handedOver);

		List<WorldPoint> starts = new ArrayList<>();
		done.forEach(c -> starts.add(c.getStart()));
		List<WorldPoint> expected = new ArrayList<>();
		for (int lap = 0; lap < LAPS; lap++)
		{
			expected.addAll(List.of(STARTS));
		}
		assertEquals("every obstacle of every lap, in order, none skipped: " + report, expected, starts);
		assertEquals("never snapped: " + report, 0, snaps);
		assertTrue("never placed, snapped or teleported: " + report, trace.stream().noneMatch(
			l -> l.contains("placed") || l.contains("snap") || l.contains("teleport")));
		for (int i = 0; i < lags.size(); i++)
		{
			long floor = Math.max(FollowerEntity.START_LAG_MS, handedOver.get(i));
			assertTrue("obstacle " + i + " begun " + lags.get(i) + " ms after the player, where "
				+ floor + " is the soonest it could be: " + report, lags.get(i) <= floor + 600);
		}
	}

	/**
	 * One lap, the player running between obstacles, as in the trace. Each
	 * obstacle is begun a tick after the server reaches it, as the trace
	 * shows: the tick the drawn player takes to get there.
	 */
	private void lap()
	{
		// Rough wall: two ticks of the reach, then up onto the roof, the XP with it.
		player.runTo(3103, 3279).idle(1).doing(REACHFORLADDER).idle(2).doing(-1).xp().hop(3102, 3279, 3).idle(1);
		// Tightrope one: onto its first tile on their own walk, then the
		// balance from the next, and their own set back as the server steps
		// off, with the drawn player still a tile or two along the rope.
		player.runTo(3099, 3277).idle(1).walkTo(3098, 3277).onto(ON_A_ROPE).walkTo(3090, 3277)
			.onto(NORMAL).xp().walkTo(3090, 3276);
		// Tightrope two.
		player.walkTo(3091, 3276).walkTo(3092, 3276).idle(1).onto(ON_A_ROPE).walkTo(3092, 3267)
			.onto(NORMAL).xp().walkTo(3092, 3266);
		// Narrow wall: the step on, the side-step along, the step off with the XP.
		player.runTo(3089, 3265).idle(1).doing(INTO_SIDESTEPL).onto(SIDESTEPPING).walkTo(3089, 3264).doing(-1)
			.walkTo(3089, 3262).walkTo(3088, 3261).doing(OUTOF_SIDESTEPL).onto(NORMAL).xp().idle(1).doing(-1);
		// Wall: the jump up, then put over it a tile at a time.
		player.runTo(3088, 3257).idle(1).doing(WALL_JUMP).forced(3088, 3256).doing(WALL_JUMP2).idle(1)
			.forced(3088, 3255).doing(-1).xp().idle(1);
		// Gap: the crouch, then set down two tiles on, the XP a tick later.
		player.runTo(3094, 3255).idle(1).doing(WALL_JUMPDOWN).idle(1).doing(WALL_JUMPDOWN2).hop(3096, 3256, 3)
			.doing(-1).xp().idle(1);
		// Crate: down to the first floor, then the ground, the XP with the second.
		player.runTo(3101, 3261).idle(1).doing(WALL_JUMPDOWN).idle(1).doing(WALL_JUMPDOWN2).hop(3102, 3261, 1)
			.doing(-1).idle(1).doing(WALL_JUMPDOWN).idle(1).doing(WALL_JUMPDOWN2).xp().hop(3103, 3261, 0)
			.doing(-1).idle(1);
		// And back round to the rough wall.
		player.runTo(3103, 3277);
	}

	/**
	 * The player as the game moves them. The server tile moves once a tick
	 * (600 ms): a tile walking, two running, or put down somewhere new. The
	 * drawn position follows it a client cycle (20 ms) at a time: a tile in
	 * a tick walking, two running, and a forced move in a few cycles. Each
	 * frame reads whatever the last cycle left, so above 50 frames a second
	 * some frames repeat the one before.
	 */
	private final class Player
	{
		final CrossingWatch watch = new CrossingWatch(follower);
		final double frameMs;
		double clockMs = 1_000_000;
		long followerMs;
		long cycle;

		int serverX;
		int serverY;
		int plane;
		double drawnX;
		double drawnY;
		int action = -1;
		int[] base = NORMAL;
		/** Which way they face: the way they last moved, as the client turns them. */
		int orientation;

		/** Tiles the drawn player has still to move through, with their speed in units a cycle and whether forced. */
		final Deque<double[]> steps = new ArrayDeque<>();
		boolean movedThisCycle;
		boolean forcedThisCycle;
		boolean ranThisCycle;

		Player(int fps, WorldPoint at)
		{
			frameMs = 1000.0 / fps;
			serverX = at.getX();
			serverY = at.getY();
			plane = at.getPlane();
			drawnX = serverX * 128 + 64;
			drawnY = serverY * 128 + 64;
			follower.setAgilityClock(() -> (long) clockMs);
			// Started beside the player, as after any snap.
			game.fineAt((int) drawnX, (int) drawnY, plane);
			frame();
			standOn(new WorldPoint(serverX - 1, serverY - 1, plane));
		}

		/** Through the rest of this tick and the next {@code ticks} - 1, frame by frame. */
		Player idle(int ticks)
		{
			for (int i = 0; i < ticks; i++)
			{
				tick();
			}
			return this;
		}

		Player doing(int clip)
		{
			action = clip;
			return this;
		}

		Player onto(int[] set)
		{
			base = set;
			return this;
		}

		Player walkTo(int x, int y)
		{
			return moveTo(x - OFFSET_X, y - OFFSET_Y, 1);
		}

		Player runTo(int x, int y)
		{
			return moveTo(x - OFFSET_X, y - OFFSET_Y, 2);
		}

		private Player moveTo(int x, int y, int perTick)
		{
			while (serverX != x || serverY != y)
			{
				for (int i = 0; i < perTick && (serverX != x || serverY != y); i++)
				{
					serverX += Integer.signum(x - serverX);
					serverY += Integer.signum(y - serverY);
					steps.addLast(new double[]{serverX, serverY, perTick == 2 ? 8 : 4, 0});
				}
				tick();
			}
			return this;
		}

		/** Put over to the next tile by the game in a handful of cycles, standing. */
		Player forced(int x, int y)
		{
			serverX = x - OFFSET_X;
			serverY = y - OFFSET_Y;
			steps.addLast(new double[]{serverX, serverY, 16, 1});
			return tick();
		}

		/** Put down somewhere new in one frame: a jump across a gap, a climb. */
		Player hop(int x, int y, int toPlane)
		{
			steps.clear();
			serverX = x - OFFSET_X;
			serverY = y - OFFSET_Y;
			plane = toPlane;
			drawnX = serverX * 128 + 64;
			drawnY = serverY * 128 + 64;
			return tick();
		}

		/** The obstacle's XP, landing now, and what the plugin does with it. */
		Player xp()
		{
			watch.noteAgilityXp((long) clockMs);
			follower.holdForAgility();
			return this;
		}

		/** One tick's worth of frames: thirty cycles. */
		Player tick()
		{
			long until = cycle + 30;
			while (cycle < until)
			{
				frame();
			}
			return this;
		}

		void frame()
		{
			clockMs += frameMs;
			long cycles = (long) ((clockMs - 1_000_000) / 20);
			while (cycle < cycles)
			{
				cycle();
			}
			int pose = !movedThisCycle ? base[0] : forcedThisCycle ? base[0] : ranThisCycle ? base[2] : base[1];
			game.fineAt((int) Math.round(drawnX), (int) Math.round(drawnY), plane, serverX, serverY)
				.posing(pose).animating(action).basePoses(base).turned(orientation);
			watch.sample(CrossingWatch.Sample.read(game.player, (long) clockMs));
			followerFrame();
		}

		private void cycle()
		{
			cycle++;
			movedThisCycle = false;
			// The client's own pace, a little under a tile a tick walking, so
			// the drawn player falls behind the server; and its catch-up once
			// three or four steps are waiting.
			double budget = steps.isEmpty() ? 0 : steps.peekFirst()[2]
				* (steps.peekFirst()[3] > 0 ? 1 : steps.size() >= 4 ? 2 : steps.size() == 3 ? 1.5 : 1);
			while (budget > 0 && !steps.isEmpty())
			{
				double[] step = steps.peekFirst();
				double toX = step[0] * 128 + 64;
				double toY = step[1] * 128 + 64;
				double far = Math.max(Math.abs(toX - drawnX), Math.abs(toY - drawnY));
				movedThisCycle = true;
				int east = (int) Math.signum(toX - drawnX);
				int north = (int) Math.signum(toY - drawnY);
				if (east != 0 || north != 0)
				{
					// 0 south, 512 west, 1024 north, 1536 east.
					orientation = (int) Math.round(Math.atan2(-east, -north) * 1024 / Math.PI) & 0x7ff;
				}
				forcedThisCycle = step[3] > 0;
				ranThisCycle = step[2] == 8;
				if (far <= budget)
				{
					drawnX = toX;
					drawnY = toY;
					budget -= far;
					steps.pollFirst();
				}
				else
				{
					drawnX += Math.signum(toX - drawnX) * Math.min(budget, Math.abs(toX - drawnX));
					drawnY += Math.signum(toY - drawnY) * Math.min(budget, Math.abs(toY - drawnY));
					budget = 0;
				}
			}
		}

		private void followerFrame()
		{
			long now = (long) clockMs;
			long delta = now - followerMs;
			followerMs = now;
			try
			{
				set("lastFrameMs", System.currentTimeMillis() - delta);
				boolean wasPlaying = follower.isPlayingCrossing();
				Crossing next = ((Deque<Crossing>) get("crossings")).peekFirst();
				follower.updateFrame();
				if (follower.isPlayingCrossing() && (!wasPlaying || get("playing") != current))
				{
					current = (Crossing) get("playing");
					lags.add(now - current.getStartedAtMs());
					handedOver.add(queuedAt.getOrDefault(current, now) - current.getStartedAtMs());
				}
				for (Crossing c : (Deque<Crossing>) get("crossings"))
				{
					queuedAt.putIfAbsent(c, now);
				}
			}
			catch (ReflectiveOperationException e)
			{
				throw new AssertionError(e);
			}
		}

		private Crossing current;
		private final java.util.Map<Crossing, Long> queuedAt = new java.util.IdentityHashMap<>();
	}

	private void standOn(WorldPoint at)
	{
		try
		{
			set("tile", at);
			set("simTile", at);
			set("fineWX", at.getX() * 128L + 64);
			set("fineWY", at.getY() * 128L + 64);
			((Deque<?>) get("serverPath")).clear();
			((Deque<?>) get("route")).clear();
			((Deque<?>) get("routeRun")).clear();
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}

	private Object get(String name) throws ReflectiveOperationException
	{
		Field field = FollowerEntity.class.getDeclaredField(name);
		field.setAccessible(true);
		return field.get(follower);
	}

	private void set(String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerEntity.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(follower, value);
	}
}

