	@Test
	public void questVarAndDialogueOpen() throws IOException
	{
		note("questVar", "dialogueOpen");

		Harness varbit = harnessFor("{\"type\": \"questVar\", \"varbit\": 9632, \"minimum\": 6, \"maximum\": 8}");
		varbit.game.varbit(9632, 4);
