	@Test
	public void theIncidentItKeepsBringingUp() throws IOException
	{
		note("remembers", "memoryHere", "memoryFoeNearby");

		Harness here = harnessFor("{\"type\": \"memoryHere\"}");
		here.game.regions(12850).at(3222, 3218, 0);
		here.gameTicks(1);
		here.engine.getContext().noteIncident("the-death", "the way that went", "", System.currentTimeMillis());
		here.game.at(3300, 3300, 0);
		here.gameTicks(2);
		assertQuiet(here, "somewhere else");
		here.game.at(3222, 3218, 0);
		here.gameTicks(1);
		assertFired(here, "memoryHere");

		Harness foe = harnessFor("{\"type\": \"memoryFoeNearby\", \"within\": 12}");
		foe.engine.getContext().noteIncident("the-death", "the way that went with the Hill Giant",
			"Hill Giant", 1000L);
		foe.gameTicks(2);
		assertQuiet(foe, "none about");
		NPC giant = foe.game.spawnNpc(2098, "Hill Giant", 28);
		foe.game.moveNpc(giant, foe.game.player.getWorldLocation().getX() + 5,
			foe.game.player.getWorldLocation().getY(), 0);
		foe.gameTicks(1);
		assertFired(foe, "memoryFoeNearby");

		Harness any = harnessFor("{\"type\": \"remembers\"}");
		any.gameTicks(2);
		assertQuiet(any, "nothing has happened worth remembering");
		any.engine.getContext().noteIncident("chicken-death", "that chicken", "", System.currentTimeMillis());
		any.gameTicks(1);
		assertFired(any, "remembers");

		// Named: it is the RIGHT incident, not merely some incident. Without
		// this the follower brings up the chicken after drowning in the sea.
		Harness named = harnessFor(
			"{\"type\": \"remembers\", \"is\": \"chicken-death\"}");
		named.engine.getContext().noteIncident("drowned", "the swim back", "", System.currentTimeMillis());
		named.gameTicks(2);
		assertQuiet(named, "a different incident is on its mind");
		named.engine.getContext().noteIncident("chicken-death", "that chicken", "", System.currentTimeMillis());
		named.gameTicks(1);
		assertFired(named, "remembers named");

		// And the count, which is what makes "again" honest.
		Harness twice = harnessFor(
			"{\"type\": \"remembers\", \"is\": \"chicken-death\", \"minimum\": 2}");
		twice.engine.getContext().noteIncident("chicken-death", "that chicken", "", System.currentTimeMillis());
		twice.gameTicks(2);
		assertQuiet(twice, "it has only happened once");
		twice.engine.getContext().noteIncident("chicken-death", "that chicken", "", System.currentTimeMillis());
		twice.gameTicks(1);
		assertFired(twice, "remembers twice");

		// And a maximum, so "That's three" is said on the third and only then
		// (dialogue check, 14 Oct).
		String third = "{\"type\": \"remembers\", \"is\": \"chicken-death\", \"minimum\": 3, \"maximum\": 3}";
		Harness thrice = harnessFor(third);
		for (int i = 0; i < 3; i++)
		{
			thrice.engine.getContext().noteIncident("chicken-death", "that chicken", "", System.currentTimeMillis());
		}
		thrice.gameTicks(1);
		assertFired(thrice, "remembers exactly three times");
		Harness fourth = harnessFor(third);
		for (int i = 0; i < 4; i++)
		{
			fourth.engine.getContext().noteIncident("chicken-death", "that chicken", "", System.currentTimeMillis());
		}
		fourth.gameTicks(2);
		assertQuiet(fourth, "the fourth is no longer three");
	}



	@Test
	public void theHourAndHowLongWeHaveBeenAtIt() throws IOException
	{
		note("timeOfDay", "sessionMinutes");

		// The hour comes off the player's own clock, so the test cannot pick
		// it - it can only ask about the hour it actually is, and about the
		// window that excludes it.
		int hour = java.time.LocalTime.now().getHour();

		Harness now = harnessFor(
			"{\"type\": \"timeOfDay\", \"minimum\": " + hour
				+ ", \"maximum\": " + hour + "}");
		now.gameTicks(2);
		assertFired(now, "timeOfDay covering the current hour");

		int elsewhere = (hour + 6) % 24;
		Harness other = harnessFor(
			"{\"type\": \"timeOfDay\", \"minimum\": " + elsewhere
				+ ", \"maximum\": " + elsewhere + "}");
		other.gameTicks(2);
		assertQuiet(other, "a window six hours away is not now");

		// The wrap past midnight, which is the whole reason the comparison is
		// not a plain range check: 23-to-5 has to mean five hours, not none.
		Harness wrapped = harnessFor(
			"{\"type\": \"timeOfDay\", \"minimum\": " + ((hour + 23) % 24)
				+ ", \"maximum\": " + ((hour + 1) % 24) + "}");
		wrapped.gameTicks(2);
		assertFired(wrapped, "a window straddling midnight still contains now");

		Harness been = harnessFor("{\"type\": \"sessionMinutes\", \"minimum\": 90}");
		been.engine.getContext().setSessionMinutes(89);
		been.gameTicks(2);
		assertQuiet(been, "eighty-nine minutes is not ninety");
		been.engine.getContext().setSessionMinutes(90);
		been.gameTicks(1);
		assertFired(been, "sessionMinutes");
	}

