package com.follower;

import org.junit.After;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The gamma table every drawn pixel of the follower's face resolves through.
 *
 * <p>It exists so the follower's chathead sits on the SAME table as every real
 * chathead on screen - the client rebuilds its own when the brightness setting
 * changes, and a head lit differently from the one beside it is immediately
 * obvious. The table is indexed by packed HSL, and the index is masked rather
 * than checked, so the interesting questions are about its edges.
 */
public class GameColourTableTest
{
	@After
	public void restoreDefaultBrightness()
	{
		// Static state shared with every other test in the JVM.
		GameColourTable.setBrightnessSetting(2);
	}

	// ---------------------------------------------------------------- lookup

	@Test
	public void everyPackedValueResolvesToAColour()
	{
		// 16 bits of packed HSL, all of which a model can contain.
		for (int packed = 0; packed <= 0xFFFF; packed++)
		{
			int rgb = GameColourTable.rgb(packed);
			assertTrue("packed " + packed + " gave " + rgb, rgb >= 0);
			assertTrue("packed " + packed + " overflowed 24 bits", rgb <= 0xFFFFFF);
		}
	}

	@Test
	public void anOutOfRangeIndexIsMaskedNotAnException()
	{
		// The rasterizer interpolates colour endpoints and can run past the
		// range; masking is what keeps that from throwing mid-render.
		GameColourTable.rgb(-1);
		GameColourTable.rgb(Integer.MAX_VALUE);
		GameColourTable.rgb(Integer.MIN_VALUE);
		GameColourTable.rgb(0x1FFFF);

		assertEquals("the mask should wrap, not clamp",
			GameColourTable.rgb(0), GameColourTable.rgb(0x10000));
	}

	@Test
	public void theTableIsNotAllOneColour()
	{
		// A build that silently produced zeroes would draw a black face.
		int distinct = 0;
		int previous = -1;
		for (int packed = 0; packed < 4096; packed++)
		{
			int rgb = GameColourTable.rgb(packed);
			if (rgb != previous)
			{
				distinct++;
				previous = rgb;
			}
		}
		assertTrue("the table only produced " + distinct + " runs of colour",
			distinct > 100);
	}

	// ------------------------------------------------------------ brightness

	@Test
	public void theFourBrightnessSettingsMapToTheClientsGammas()
	{
		// The client's varp maps 1..4 to Dark through V.Bright.
		GameColourTable.setBrightnessSetting(1);
		assertEquals(0.9, GameColourTable.getCurrentGamma(), 0.0001);

		GameColourTable.setBrightnessSetting(2);
		assertEquals(0.8, GameColourTable.getCurrentGamma(), 0.0001);

		GameColourTable.setBrightnessSetting(3);
		assertEquals(0.7, GameColourTable.getCurrentGamma(), 0.0001);

		GameColourTable.setBrightnessSetting(4);
		assertEquals(0.6, GameColourTable.getCurrentGamma(), 0.0001);
	}

	@Test
	public void anUnknownSettingFallsBackToTheDefault()
	{
		GameColourTable.setBrightnessSetting(99);
		assertEquals(0.8, GameColourTable.getCurrentGamma(), 0.0001);

		GameColourTable.setBrightnessSetting(-5);
		assertEquals(0.8, GameColourTable.getCurrentGamma(), 0.0001);

		GameColourTable.setBrightnessSetting(0);
		assertEquals(0.8, GameColourTable.getCurrentGamma(), 0.0001);
	}

	@Test
	public void changingBrightnessActuallyChangesTheColours()
	{
		GameColourTable.setBrightnessSetting(1);
		int dark = GameColourTable.rgb(9000);

		GameColourTable.setBrightnessSetting(4);
		int bright = GameColourTable.rgb(9000);

		assertFalse("the table was not rebuilt for the new setting", dark == bright);
	}

	@Test
	public void aBrighterSettingIsActuallyBrighter()
	{
		// Lower gamma means brighter in the client's scheme, which is easy to
		// get backwards.
		GameColourTable.setBrightnessSetting(1);
		long darkTotal = luminanceOver(2000, 12000);

		GameColourTable.setBrightnessSetting(4);
		long brightTotal = luminanceOver(2000, 12000);

		assertTrue("V.Bright came out darker than Dark", brightTotal > darkTotal);
	}

	private static long luminanceOver(int from, int to)
	{
		long total = 0;
		for (int packed = from; packed < to; packed++)
		{
			int rgb = GameColourTable.rgb(packed);
			total += ((rgb >> 16) & 0xFF) + ((rgb >> 8) & 0xFF) + (rgb & 0xFF);
		}
		return total;
	}

	@Test
	public void settingTheSameBrightnessTwiceIsCheapAndStable()
	{
		GameColourTable.setBrightnessSetting(3);
		int first = GameColourTable.rgb(9000);

		for (int i = 0; i < 100; i++)
		{
			GameColourTable.setBrightnessSetting(3);
		}

		assertEquals("re-setting the same value must not disturb the table",
			first, GameColourTable.rgb(9000));
		assertEquals(0.7, GameColourTable.getCurrentGamma(), 0.0001);
	}
}

package com.follower;

import com.google.gson.Gson;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.Path;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The glyph renderer every line the follower says goes through.
 *
 * <p>Its one sharp edge is how a character becomes a glyph. It follows the
 * client: a no-break space is a space, and the rest goes through cp1252,
 * with a '?' for what has no byte there. That is pinned here so the rule
 * cannot quietly change.
 */
public class GameFontTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private GameFont overhead;
	private GameFont dialog;

	@Before
	public void setUp() throws IOException
	{
		GameFontRepository fonts = new GameFontRepository(new Gson());
		Path empty = folder.newFolder().toPath();
		fonts.load();
		overhead = fonts.getByName("b12_full");
		dialog = fonts.get(497);
		assertNotNull(overhead);
		assertNotNull(dialog);
	}

	private static Graphics2D canvas()
	{
		return new BufferedImage(400, 100, BufferedImage.TYPE_INT_ARGB).createGraphics();
	}

	// ------------------------------------------------------------- measuring

	@Test
	public void anEmptyStringHasNoWidth()
	{
		assertEquals(0, overhead.stringWidth(""));
	}

	@Test
	public void aNullStringIsNotACrash()
	{
		assertEquals(0, overhead.stringWidth(null));
		overhead.drawTop(canvas(), null, 0, 0, 0xFFFFFF, false);
	}

	@Test
	public void widthGrowsWithTheText()
	{
		int one = overhead.stringWidth("a");
		int two = overhead.stringWidth("aa");
		assertTrue("a single character should measure something", one > 0);
		assertEquals("measuring should be the sum of its advances", one * 2, two);
	}

	@Test
	public void aRealSentenceMeasuresSensibly()
	{
		int width = overhead.stringWidth("The quick brown fox jumps over the lazy dog");
		assertTrue("suspiciously narrow: " + width, width > 100);
		assertTrue("suspiciously wide: " + width, width < 1000);
	}

	@Test
	public void bothFontsHaveARealLineHeight()
	{
		assertTrue(overhead.getLineHeight() > 0);
		assertTrue(dialog.getLineHeight() > 0);
		assertTrue(overhead.getAscent() > 0);
	}

	// -------------------------------------------------------------- drawing

	@Test
	public void drawingActuallyPutsPixelsDown()
	{
		BufferedImage image = new BufferedImage(400, 100, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		overhead.drawTop(graphics, "Hello", 10, 10, 0xFF0000, false);

		boolean any = false;
		for (int x = 0; x < image.getWidth() && !any; x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				if ((image.getRGB(x, y) >>> 24) != 0)
				{
					any = true;
					break;
				}
			}
		}
		assertTrue("nothing was drawn at all", any);
	}

	@Test
	public void everyDrawEntryPointSurvivesOrdinaryText()
	{
		Graphics2D graphics = canvas();
		overhead.drawTop(graphics, "Hello", 10, 10, 0xFFFFFF, false);
		overhead.drawTop(graphics, "Hello", 10, 10, 0xFFFFFF, true);
		overhead.drawCenteredOverhead(graphics, "Hello", 200, 60, 0x00FF00);
	}

	@Test
	public void drawingOffTheEdgeOfTheCanvasIsHarmless()
	{
		Graphics2D graphics = canvas();
		overhead.drawTop(graphics, "Hello", -500, -500, 0xFFFFFF, false);
		overhead.drawTop(graphics, "Hello", 100000, 100000, 0xFFFFFF, false);
	}

	// ------------------------------------------------------ the sharp edge

	@Test
	public void everyLatin1CharacterCanBeMeasuredAndDrawn()
	{
		Graphics2D graphics = canvas();
		for (int c = 0; c <= 0xFF; c++)
		{
			String text = String.valueOf((char) c);
			assertTrue("negative width for char " + c, overhead.stringWidth(text) >= 0);
			overhead.drawTop(graphics, text, 10, 10, 0xFFFFFF, false);
			dialog.drawTop(graphics, text, 10, 10, 0xFFFFFF, false);
		}
	}

	/**
	 * Past Latin-1 a character goes through cp1252, as the client's font
	 * renderer sends it: an em-dash, U+2014, is the glyph the font holds at
	 * 0x97, a curly apostrophe the one at 0x92, and a character with no
	 * cp1252 byte is drawn as a '?'. It used to be cut to its low byte, so an
	 * em-dash was drawn as glyph 0x14. The phrase-file check still keeps them
	 * out of the shipped lines: not every font has a glyph there.
	 */
	@Test
	public void aCharacterPastLatin1IsMappedAsTheClientMapsIt()
	{
		assertEquals("an em-dash is the cp1252 em-dash", 0x97, GameFont.glyphIndex('\u2014'));
		assertEquals("a curly apostrophe is the cp1252 one", 0x92, GameFont.glyphIndex('\u2019'));
		assertEquals("the euro sign", 0x80, GameFont.glyphIndex('\u20AC'));
		assertEquals("Latin-1 is itself", 0xE9, GameFont.glyphIndex('\u00E9'));
		assertEquals("a C1 control has no glyph of its own", '?', GameFont.glyphIndex((char) 0x97));
		assertEquals("and what cp1252 has no byte for is a question mark",
			overhead.stringWidth("?"),
			overhead.stringWidth("\u4E2D"));
	}

	/**
	 * QA, 15 Oct: display names arrive with no-break spaces, and no game font
	 * has a width at 0xA0, so "Sir Zeebos" was measured and drawn as
	 * "SirZeebos" over the follower and in the Talk-to name header. The client
	 * turns one into a plain space first; so does GameFont.
	 */
	@Test
	public void aNoBreakSpaceIsAPlainSpace()
	{
		for (GameFont font : new GameFont[]{overhead, dialog})
		{
			assertEquals(font.stringWidth("Sir Zeebos"), font.stringWidth("Sir\u00A0Zeebos"));
			assertTrue(font.stringWidth("Sir\u00A0Zeebos") > font.stringWidth("SirZeebos"));
		}
	}

	@Test
	public void everyDrawPutsTheSamePixelsForANoBreakSpaceAsForASpace()
	{
		for (int style = 0; style < 4; style++)
		{
			BufferedImage plain = new BufferedImage(200, 40, BufferedImage.TYPE_INT_ARGB);
			BufferedImage nbsp = new BufferedImage(200, 40, BufferedImage.TYPE_INT_ARGB);
			draw(style, plain.createGraphics(), "Sir Zeebos");
			draw(style, nbsp.createGraphics(), "Sir\u00A0Zeebos");
			for (int x = 0; x < plain.getWidth(); x++)
			{
				for (int y = 0; y < plain.getHeight(); y++)
				{
					assertEquals("draw style " + style + " differs at " + x + "," + y,
						plain.getRGB(x, y), nbsp.getRGB(x, y));
				}
			}
		}
	}

	private void draw(int style, Graphics2D g, String text)
	{
		switch (style)
		{
			case 0:
				overhead.drawTop(g, text, 5, 5, 0xFFFFFF, false);
				break;
			case 1:
				overhead.drawTop(g, text, 5, 5, 0xFFFFFF, true);
				break;
			default:
				overhead.drawCenteredOverhead(g, text, 100, 25, 0xFFFF00);
				break;
		}
	}

	@Test
	public void charactersWayPastLatin1StillDoNotThrow()
	{
		Graphics2D graphics = canvas();
		String[] awkward = {
			"—", "’", "…", "€", "�",
			"中文", "😀",
		};
		for (String text : awkward)
		{
			assertTrue(overhead.stringWidth(text) >= 0);
			overhead.drawTop(graphics, text, 10, 10, 0xFFFFFF, false);
			overhead.drawCenteredOverhead(graphics, text, 200, 60, 0xFFFFFF);
		}
	}

	@Test
	public void aVeryLongLineDoesNotOverflowItsMeasurement()
	{
		StringBuilder text = new StringBuilder();
		for (int i = 0; i < 5000; i++)
		{
			text.append('W');
		}
		int width = overhead.stringWidth(text.toString());
		assertTrue("width overflowed to a negative: " + width, width > 0);
	}
}

package com.follower;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Random;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Where the follower looks when nothing else owns its head: the cursor, the
 * camera, and the look round while standing about.
 */
public class GazeTest
{
	private static final WorldPoint HERE = new WorldPoint(50, 50, 0);

	/** Records glances; nothing else. */
	private static final class GlancingFollower extends FollowerEntity
	{
		final List<WorldPoint> glances = new ArrayList<>();
		final List<Integer> holds = new ArrayList<>();

		GlancingFollower()
		{
			super(null, null);
		}

		@Override
		public boolean isSpawned()
		{
			return true;
		}

		@Override
		public WorldPoint getWorldLocation()
		{
			return HERE;
		}

		@Override
		public void glanceAt(WorldPoint at, int ms)
		{
			glances.add(at);
			holds.add(ms);
		}
	}

	private FakeGame game;
	private GlancingFollower follower;
	private Gaze gaze;
	private int yaw;
	private int idle;
	private boolean busy;
	private boolean attentive = true;
	private List<WorldPoint> nearby = Collections.emptyList();
	private int tick;

	@Before
	public void setUp()
	{
		game = new FakeGame().at(50, 51, 0);
		follower = new GlancingFollower();
		FollowerConfig config = new FollowerConfig()
		{
			@Override
			public boolean paysAttention()
			{
				return attentive;
			}
		};
		gaze = new Gaze(game.client, follower, config, () -> yaw, () -> idle, () -> busy,
			() -> nearby, new Random(7));
	}

	private void tick(int count)
	{
		for (int i = 0; i < count; i++)
		{
			game.tick(++tick);
			gaze.tick();
		}
	}

	private static Gaze.Hover thing(String key, int x, int y)
	{
		return new Gaze.Hover(key, null, new WorldPoint(x, y, 0));
	}

	// ------------------------------------------------------------- the cursor

	@Test
	public void theCursorRestingOnAThingTurnsTheHeadOnce()
	{
		gaze.noteHover(thing("npc:4", 55, 50));
		tick(1);
		assertTrue("one tick is a pass, not a rest", follower.glances.isEmpty());
		tick(1);
		assertEquals(Collections.singletonList(new WorldPoint(55, 50, 0)), follower.glances);
		assertEquals(Gaze.HOVER_GLANCE_MS, (int) follower.holds.get(0));

		tick(10);
		assertEquals("resting on the same thing is one look, not a stare", 1, follower.glances.size());

		// Off it and back on, and it is worth a second look.
		gaze.noteHover(null);
		tick(1);
		gaze.noteHover(thing("npc:4", 55, 50));
		tick(2);
		assertEquals(2, follower.glances.size());
	}

	@Test
	public void aNewThingUnderTheCursorStartsTheCountAgainAndTheHeadDoesNotFlick()
	{
		gaze.noteHover(thing("npc:4", 55, 50));
		tick(1);
		gaze.noteHover(thing("npc:9", 45, 50));
		tick(1);
		assertTrue("one tick on each is no rest on either", follower.glances.isEmpty());
		tick(1);
		assertEquals(Collections.singletonList(new WorldPoint(45, 50, 0)), follower.glances);

		// Straight on to a third: the cooldown holds the head where it is.
		gaze.noteHover(thing("npc:2", 50, 56));
		tick(2);
		assertEquals(1, follower.glances.size());
		tick(Gaze.HOVER_COOLDOWN_TICKS);
		gaze.noteHover(null);
		tick(1);
		gaze.noteHover(thing("npc:2", 50, 56));
		tick(2);
		assertEquals(2, follower.glances.size());
	}

	@Test
	public void theFollowersOwnTileIsNotALook()
	{
		gaze.noteHover(thing("tile:50,50:1", 50, 50));
		tick(3);
		assertTrue(follower.glances.isEmpty());
	}

	// ------------------------------------------------------------- the camera

	@Test
	public void aCameraSwingThatSettlesIsSharedAndAJitterIsNot()
	{
		idle = 1;
		tick(2);
		yaw = 512;
		tick(1);
		assertTrue("still swinging", follower.glances.isEmpty());
		tick(Gaze.CAMERA_SETTLE_TICKS);
		assertEquals("a look four tiles the way the camera looks", Collections.singletonList(
			Gaze.lookTile(HERE, 512, Gaze.CAMERA_LOOK_TILES)), follower.glances);

		yaw = 520;
		tick(3);
		assertEquals("a nudge is not a swing", 1, follower.glances.size());

		yaw = 1024;
		tick(3);
		assertEquals("and the cooldown holds the next", 1, follower.glances.size());
		tick(Gaze.CAMERA_COOLDOWN_TICKS);
		yaw = 0;
		tick(3);
		assertEquals(2, follower.glances.size());
	}

	@Test
	public void theCameraIsNotSharedWhileThePlayerIsMoving()
	{
		idle = 0;
		tick(2);
		yaw = 900;
		tick(4);
		assertTrue(follower.glances.isEmpty());
	}

	@Test
	public void theLookTileFollowsTheCamera()
	{
		// The same circle as an actor's orientation (0 south, 512 west, 1024
		// north, 1536 east), a half turn round: the camera at yaw 0 sits south
		// and looks north.
		assertEquals("north", new WorldPoint(50, 54, 0), Gaze.lookTile(HERE, 0, 4));
		assertEquals("east", new WorldPoint(54, 50, 0), Gaze.lookTile(HERE, 512, 4));
		assertEquals("south", new WorldPoint(50, 46, 0), Gaze.lookTile(HERE, 1024, 4));
		assertEquals("west", new WorldPoint(46, 50, 0), Gaze.lookTile(HERE, 1536, 4));
		assertEquals("the short way round", 16, Gaze.angle(2040, 8));
		assertEquals(16, Gaze.angle(8, 2040));
		assertEquals(1024, Gaze.angle(0, 1024));
	}

	// ---------------------------------------------------------- the look round

	@Test
	public void standingAboutItLooksRoundAndBackAgain()
	{
		nearby = Arrays.asList(new WorldPoint(53, 50, 0), new WorldPoint(50, 45, 0));
		idle = Gaze.IDLE_BEFORE_AROUND_TICKS;
		tick(Gaze.AROUND_MAX_TICKS + 2);
		assertEquals("one look in the longest wait", 1, follower.glances.size());
		assertTrue("at something nearby", nearby.contains(follower.glances.get(0)));
		assertEquals(Gaze.AROUND_MS, (int) follower.holds.get(0));
		tick(Gaze.AROUND_MAX_TICKS + 2);
		assertEquals(2, follower.glances.size());
	}

	@Test
	public void withNothingNearbyItLooksAtNothingInParticular()
	{
		idle = Gaze.IDLE_BEFORE_AROUND_TICKS;
		tick(Gaze.AROUND_MAX_TICKS + 2);
		assertEquals(1, follower.glances.size());
		int away = follower.glances.get(0).distanceTo(HERE);
		assertTrue("a few tiles off: " + away, away >= Gaze.AROUND_NEAR - 1 && away <= Gaze.AROUND_FAR + 1);
	}


	@Test
	public void aSharedLookStartsTheLookRoundsWaitAgain()
	{
		// Two turns of the head a tick apart read as a twitch, not as
		// attention. Left alone, this draw looks round on a known tick; with
		// the cursor resting on something just before it, the look round
		// starts its wait again from nothing and is a whole wait away.
		nearby = Collections.singletonList(new WorldPoint(53, 50, 0));
		idle = Gaze.IDLE_BEFORE_AROUND_TICKS;
		for (int i = 0; i < Gaze.AROUND_MAX_TICKS + 2 && follower.glances.isEmpty(); i++)
		{
			tick(1);
		}
		assertEquals("left alone, it looks round", 1, follower.glances.size());
		int due = tick;

		setUp();
		tick = 0;
		tick(due - 3);
		gaze.noteHover(thing("npc:4", 55, 50));
		tick(2);
		assertEquals("the shared look, a tick before the look round was due",
			Collections.singletonList(new WorldPoint(55, 50, 0)), follower.glances);
		gaze.noteHover(null);
		tick(Gaze.AROUND_MIN_TICKS - 1);
		assertEquals("and no look round straight after it", 1, follower.glances.size());
	}

	@Test
	public void nothingWhileBusyOrSwitchedOff()
	{
		busy = true;
		idle = 50;
		nearby = Collections.singletonList(new WorldPoint(53, 50, 0));
		gaze.noteHover(thing("npc:4", 55, 50));
		yaw = 700;
		tick(Gaze.AROUND_MAX_TICKS + 5);
		assertTrue(follower.glances.isEmpty());

		busy = false;
		attentive = false;
		tick(Gaze.AROUND_MAX_TICKS + 5);
		assertTrue(follower.glances.isEmpty());
	}
}

package com.follower;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The ledger of body beats: each on its own clock, halved while a favour is owed. */
public class GesturesTest
{
	private int tick;
	private boolean grateful;

	@Test
	public void aGestureWaitsOutItsOwnCooldownAndNobodyElses()
	{
		Gestures gestures = new Gestures(() -> tick, () -> grateful);
		assertTrue(take(gestures, Gestures.Gesture.NOTES));
		assertFalse("not twice", take(gestures, Gestures.Gesture.NOTES));
		assertTrue("a different gesture is a different clock", take(gestures, Gestures.Gesture.GLANCE));

		tick = Gestures.Gesture.NOTES.cooldownTicks - 1;
		assertFalse(gestures.may(Gestures.Gesture.NOTES));
		tick = Gestures.Gesture.NOTES.cooldownTicks;
		assertTrue(gestures.may(Gestures.Gesture.NOTES));
	}

	/**
	 * Takes the gesture if it may be made: true means go ahead, it is spent.
	 * Gestures had this as take(); only the tests used it.
	 */
	private static boolean take(Gestures gestures, Gestures.Gesture gesture)
	{
		if (!gestures.may(gesture))
		{
			return false;
		}
		gestures.spent(gesture);
		return true;
	}

	@Test
	public void goodwillHalvesTheWait()
	{
		Gestures gestures = new Gestures(() -> tick, () -> grateful);
		gestures.spent(Gestures.Gesture.WALK_OVER);
		tick = Gestures.Gesture.WALK_OVER.cooldownTicks / 2;
		assertFalse(gestures.may(Gestures.Gesture.WALK_OVER));
		grateful = true;
		assertTrue(gestures.may(Gestures.Gesture.WALK_OVER));
	}

	@Test
	public void aResetForgetsTheSession()
	{
		Gestures gestures = new Gestures(() -> tick, () -> grateful);
		gestures.spent(Gestures.Gesture.WAVE);
		gestures.reset();
		assertTrue(gestures.may(Gestures.Gesture.WAVE));
	}
}

package com.follower;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * GameFont finds a glyph through the JDK's windows-1252 table, where it once
 * had a switch of the 27 code points that table maps above Latin-1. The
 * switch is kept here as it stood, and the two agree on every char there is.
 */
public class GlyphIndexDiffTest
{
	/** GameFont.glyphIndex before it read the JDK's table, verbatim. */
	static int oldGlyphIndex(char c)
	{
		if (c == '\u00A0')
		{
			return ' ';
		}
		if ((c > 0 && c < 128) || (c >= 160 && c <= 255))
		{
			return c;
		}
		switch (c)
		{
			case '\u20AC': return 0x80;
			case '\u201A': return 0x82;
			case '\u0192': return 0x83;
			case '\u201E': return 0x84;
			case '\u2026': return 0x85;
			case '\u2020': return 0x86;
			case '\u2021': return 0x87;
			case '\u02C6': return 0x88;
			case '\u2030': return 0x89;
			case '\u0160': return 0x8A;
			case '\u2039': return 0x8B;
			case '\u0152': return 0x8C;
			case '\u017D': return 0x8E;
			case '\u2018': return 0x91;
			case '\u2019': return 0x92;
			case '\u201C': return 0x93;
			case '\u201D': return 0x94;
			case '\u2022': return 0x95;
			case '\u2013': return 0x96;
			case '\u2014': return 0x97;
			case '\u02DC': return 0x98;
			case '\u2122': return 0x99;
			case '\u0161': return 0x9A;
			case '\u203A': return 0x9B;
			case '\u0153': return 0x9C;
			case '\u017E': return 0x9E;
			case '\u0178': return 0x9F;
			default: return '?';
		}
	}

	@Test
	public void everyCharFindsTheGlyphTheSwitchFound()
	{
		int mapped = 0;
		for (int i = Character.MIN_VALUE; i <= Character.MAX_VALUE; i++)
		{
			char c = (char) i;
			assertEquals("U+" + Integer.toHexString(i), oldGlyphIndex(c), GameFont.glyphIndex(c));
			if (oldGlyphIndex(c) != '?')
			{
				mapped++;
			}
		}
		assertEquals("the chars with a glyph of their own", 249, mapped);
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;

/**
 * Being away from the keys trails off as standing still does. Behaviour
 * QA5, 20 Oct: gone-away was 11 of the day's 66 lines, every twenty minutes
 * for as long as the player was away; its condition is "unattended", which
 * the trail-off did not count.
 */
public class GoneAwayTrailsOffTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private final long[] ms = {1_700_000_000_000L};

	@Test
	public void theFifthAwayLineWaitsLongerThanTheFourth() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), "{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"gone-away\", \"group\": \"t\", \"cooldownMs\": 0, \"when\": {\"type\": \"all\","
			+ " \"conditions\": [{\"type\": \"unattended\", \"ticks\": 0}, {\"type\": \"chatMessage\", \"contains\": \"tick\"}]},"
			+ " \"say\": [\"You've gone, haven't you.\", \"Still gone.\"]}]}");
		h.engine.setClock(() -> ms[0]);
		h.engine.setGlobalCooldownMs(45_000L);
		h.gameTicks(1);
		for (int i = 0; i < 5; i++)
		{
			h.someoneSays("Clock", "tick");
			h.gameTicks(1);
			ms[0] += 20 * 60_000L;
		}
		assertEquals("four, then the fifth waits its trail", 4, h.firedBy("gone-away").size());
		ms[0] += 20 * 60_000L;
		h.someoneSays("Clock", "tick");
		assertEquals("and comes, later", 5, h.firedBy("gone-away").size());
	}
}

package com.follower;

import java.util.Random;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The client's triangle rasterizer, which draws the follower's face.
 *
 * <p>It is a verbatim port of integer scanline code, run once per triangle of a
 * chathead every frame a dialog is open. Two things can go wrong in that shape
 * of code and neither is subtle in effect: writing outside the pixel buffer,
 * which is an exception thrown from inside a render, and a degenerate triangle
 * sending the scanline walk somewhere it does not come back from.
 *
 * <p>So the tests here are mostly about what it must NOT do, driven with the
 * inputs a real model produces: sub-pixel faces, faces partly off every edge,
 * zero-area faces, and vertices in every order.
 */
public class GouraudRasterizerTest
{
	private static final int WIDTH = 64;
	private static final int HEIGHT = 64;

	/**
	 * Slack past the end of the visible buffer. The rasterizer takes its bounds
	 * from the width and height it is given rather than from the array length,
	 * so anything written past WIDTH * HEIGHT lands here instead of throwing -
	 * which is the point. An index error is loud; an off-by-one that happens to
	 * stay inside the allocation is silent, and in the real client the memory
	 * past the buffer belongs to something else.
	 */
	private static final int GUARD = 512;

	/** A canvas with a guard band after it, so an overrun is detectable. */
	private static final class Canvas
	{
		final int[] pixels = new int[WIDTH * HEIGHT + GUARD];
		final GouraudRasterizer raster = new GouraudRasterizer(pixels, WIDTH, HEIGHT);

		int painted()
		{
			int count = 0;
			for (int i = 0; i < WIDTH * HEIGHT; i++)
			{
				if (pixels[i] != 0)
				{
					count++;
				}
			}
			return count;
		}

		void assertGuardIntact(String what)
		{
			for (int i = WIDTH * HEIGHT; i < pixels.length; i++)
			{
				assertEquals(what + ": wrote " + pixels[i] + " past the end of the"
					+ " buffer, at offset " + (i - WIDTH * HEIGHT), 0, pixels[i]);
			}
		}
	}

	// ------------------------------------------------------------- it draws

	@Test
	public void anOrdinaryTriangleFillsPixels()
	{
		Canvas canvas = new Canvas();
		canvas.raster.gouraudTriangle(10, 50, 30, 10, 20, 50, 8000, 8000, 8000);

		assertTrue("nothing was drawn at all", canvas.painted() > 0);
	}

	@Test
	public void aTriangleIsDrawnWhicheverOrderItsVerticesArriveIn()
	{
		// The three top-level cases order by smallest y; a model hands them over
		// in whatever order the mesh has them.
		int[][] orders = {
			{0, 1, 2}, {0, 2, 1}, {1, 0, 2}, {1, 2, 0}, {2, 0, 1}, {2, 1, 0},
		};
		int[] xs = {10, 50, 30};
		int[] ys = {10, 20, 50};

		for (int[] order : orders)
		{
			Canvas canvas = new Canvas();
			canvas.raster.gouraudTriangle(
				xs[order[0]], xs[order[1]], xs[order[2]],
				ys[order[0]], ys[order[1]], ys[order[2]],
				8000, 8000, 8000);
			assertTrue("winding order " + java.util.Arrays.toString(order)
				+ " drew nothing", canvas.painted() > 0);
		}
	}

	/**
	 * The reason this rasterizer exists: the float fill it replaced sampled
	 * pixel centres, and the pupils of an eye are faces only a few pixels
	 * across. Measured rather than assumed - a face spanning a single pixel
	 * covers no scanline at all under the client's half-open convention and
	 * correctly paints nothing, and from two pixels up the coverage grows with
	 * the area: 1, 3, 6, 10, 15.
	 */
	@Test
	public void faceOfAFewPixelsIsFilledAndScalesWithItsArea()
	{
		int[] expected = {0, 1, 3, 6, 10, 15};
		for (int size = 1; size <= expected.length; size++)
		{
			Canvas canvas = new Canvas();
			canvas.raster.gouraudTriangle(30, 30 + size, 30, 30, 30 + size, 30 + size,
				8000, 8000, 8000);
			assertEquals("a face " + size + " pixels across",
				expected[size - 1], canvas.painted());
		}
	}

	// -------------------------------------------------------- it stays inside

	@Test
	public void nothingIsWrittenOutsideTheBufferHoweverFarOffScreen()
	{
		int[][] cases = {
			{-500, -400, -450, 10, 20, 30},
			{500, 600, 550, 10, 20, 30},
			{10, 20, 30, -500, -400, -450},
			{10, 20, 30, 500, 600, 550},
			{-1000, 1000, 0, -1000, 1000, 0},
			{Integer.MIN_VALUE / 4, Integer.MAX_VALUE / 4, 0, -10, 10, 0},
			{0, 0, 0, Integer.MIN_VALUE / 4, Integer.MAX_VALUE / 4, 0},
		};

		for (int[] c : cases)
		{
			Canvas canvas = new Canvas();
			// Two ways this fails. An ArrayIndexOutOfBounds surfaces as an
			// exception thrown from inside the client's render loop, and that
			// one announces itself. A write that lands just past the visible
			// buffer does not - so the guard band is checked as well, which is
			// what the name of this case actually claims.
			canvas.raster.gouraudTriangle(c[0], c[1], c[2], c[3], c[4], c[5],
				8000, 9000, 10000);
			canvas.assertGuardIntact(java.util.Arrays.toString(c));
		}
	}

	@Test
	public void aTriangleStraddlingAnEdgeIsClippedNotWrapped()
	{
		Canvas canvas = new Canvas();
		// Hanging off the left edge. A missing clamp would wrap the scanline
		// onto the previous row, which looks like a smear across the face.
		canvas.raster.gouraudTriangle(-20, 20, 0, 10, 10, 40, 8000, 8000, 8000);

		for (int y = 0; y < HEIGHT; y++)
		{
			// Nothing may appear on a row the triangle does not cover.
			if (y < 10 || y > 40)
			{
				for (int x = 0; x < WIDTH; x++)
				{
					assertEquals("painted row " + y + ", outside the triangle",
						0, canvas.pixels[y * WIDTH + x]);
				}
			}
		}
	}

	@Test
	public void aTriangleEntirelyBelowTheClipIsSkipped()
	{
		Canvas canvas = new Canvas();
		canvas.raster.gouraudTriangle(10, 30, 20, HEIGHT + 5, HEIGHT + 20, HEIGHT + 10,
			8000, 8000, 8000);

		assertEquals("something was drawn below the clip line", 0, canvas.painted());
	}

	// ----------------------------------------------------------- degenerate

	@Test
	public void degenerateTrianglesDoNotHangOrThrow()
	{
		int[][] degenerate = {
			{20, 20, 20, 20, 20, 20},       // a point
			{10, 40, 25, 20, 20, 20},       // flat, zero height
			{20, 20, 20, 10, 40, 25},       // a vertical line, zero width
			{10, 20, 30, 10, 10, 40},       // two vertices sharing a y
			{10, 20, 30, 40, 10, 10},       // the other two sharing a y
			{0, 0, 0, 0, 0, 0},             // the origin
		};

		for (int[] c : degenerate)
		{
			Canvas canvas = new Canvas();
			canvas.raster.gouraudTriangle(c[0], c[1], c[2], c[3], c[4], c[5],
				8000, 8000, 8000);
		}
	}

	@Test
	public void colourEndpointsAtTheExtremesDoNotThrow()
	{
		Canvas canvas = new Canvas();
		canvas.raster.gouraudTriangle(10, 50, 30, 10, 20, 50,
			0, 0xFFFF, 0x7FFF);
		canvas.raster.gouraudTriangle(10, 50, 30, 10, 20, 50,
			Integer.MAX_VALUE / 2, 0, Integer.MIN_VALUE / 2);
	}

	// ----------------------------------------------------------------- fuzz

	@Test
	public void randomTrianglesNeverEscapeTheBuffer()
	{
		// A chathead is a few hundred triangles a frame; over a session that is
		// millions of calls with whatever the model geometry produces.
		Random random = new Random(20260808L);
		Canvas canvas = new Canvas();

		for (int i = 0; i < 20000; i++)
		{
			int range = 200;
			canvas.raster.gouraudTriangle(
				random.nextInt(range) - range / 2,
				random.nextInt(range) - range / 2,
				random.nextInt(range) - range / 2,
				random.nextInt(range) - range / 2,
				random.nextInt(range) - range / 2,
				random.nextInt(range) - range / 2,
				random.nextInt(0x10000),
				random.nextInt(0x10000),
				random.nextInt(0x10000));
		}

		assertTrue("twenty thousand random faces drew nothing, so the fuzz is"
			+ " not actually exercising the fill", canvas.painted() > 0);
	}

	@Test
	public void aTallThinTriangleIsDrawnRatherThanSkipped()
	{
		// The shape a nose or a fringe of hair produces.
		Canvas canvas = new Canvas();
		canvas.raster.gouraudTriangle(30, 31, 30, 5, 30, 55, 8000, 8000, 8000);
		assertTrue(canvas.painted() > 0);
	}

	@Test
	public void aWideFlatTriangleIsDrawnRatherThanSkipped()
	{
		Canvas canvas = new Canvas();
		canvas.raster.gouraudTriangle(5, 55, 30, 30, 30, 32, 8000, 8000, 8000);
		assertTrue(canvas.painted() > 0);
	}

	@Test
	public void aOnePixelHighCanvasIsNotACrash()
	{
		int[] pixels = new int[WIDTH];
		GouraudRasterizer raster = new GouraudRasterizer(pixels, WIDTH, 1);
		raster.gouraudTriangle(0, WIDTH, WIDTH / 2, 0, 0, 1, 8000, 8000, 8000);

		boolean anyPainted = false;
		for (int pixel : pixels)
		{
			anyPainted |= pixel != 0;
		}
		assertFalse("a canvas one pixel tall has no room for a triangle,"
			+ " but it must not crash trying", anyPainted && pixels.length != WIDTH);
	}
}

package com.follower;

import com.google.gson.JsonElement;
