/**
 * Copying the player's graphics onto the follower (QA, 15 Oct): every
 * copying rule opened a twelve-tick window, eating among them, so in a fight
 * each bite had the follower wear the spells that landed on the player. Now
 * only a rule that says so opens it, and the first graphic closes it.
 */
public class GraphicCopyTest
{
	@Test
	public void oneCastCopiesOneGraphic() throws ReflectiveOperationException
	{
		FollowerPlugin plugin = new FollowerPlugin();
		assertFalse("no window open", plugin.takesMirroredGraphic(100));

		Field until = FollowerPlugin.class.getDeclaredField("mirrorGraphicsUntilTick");
		until.setAccessible(true);
		until.setInt(plugin, 112);
		assertTrue("the cast's own graphic", plugin.takesMirroredGraphic(101));
		assertFalse("and nothing after it", plugin.takesMirroredGraphic(102));

		until.setInt(plugin, 112);
		assertFalse("nor once the window has closed", plugin.takesMirroredGraphic(113));
	}

	@Test
	public void onlyTheCastsCopyGraphics() throws IOException
	{
		Set<String> copying = new HashSet<>();
		Set<String> mirroring = new HashSet<>();
		try (Reader reader = new InputStreamReader(FollowerPlugin.class.getResourceAsStream(
			"/com/follower/default-phrases.json"), StandardCharsets.UTF_8))
		{
			for (JsonElement element : new JsonParser().parse(reader).getAsJsonObject().getAsJsonArray("rules"))
			{
				JsonObject rule = element.getAsJsonObject();
				if (rule.has("copiesGraphics") && rule.get("copiesGraphics").getAsBoolean())
				{
					copying.add(rule.get("id").getAsString());
				}
				if (rule.has("mirrorAnimation") && rule.get("mirrorAnimation").getAsBoolean())
				{
					mirroring.add(rule.get("id").getAsString());
				}
			}
		}
		assertEquals(new HashSet<>(Arrays.asList("mirror-teleport", "casting-along", "mimic-emotes")), copying);
		assertTrue("eating still copies the bite", mirroring.contains("mimic-eat"));
	}

	@Test
	public void theWindowOpensOnlyForARuleThatCopiesGraphics() throws IOException
	{
		String source = PublicMarkers.strip(new String(Files.readAllBytes(
			Paths.get("src/main/java/com/follower/FollowerPlugin.java")), StandardCharsets.UTF_8)
			.replace("\r\n", "\n"));
		int opens = source.indexOf("mirrorGraphicsUntilTick = client.getTickCount() + MIRROR_GRAPHIC_WINDOW_TICKS;");
		assertTrue(opens > 0);
		String guard = source.substring(source.lastIndexOf("if (", opens), opens);
		assertTrue(guard, guard.contains("Boolean.TRUE.equals(rule.copiesGraphics)"));
		assertFalse(guard, guard.contains("mirrorAnimation"));
		assertTrue("a graphic copied closes the window",
			source.contains("if (takesMirroredGraphic(client.getTickCount()))"));
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.ModelData;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Public QA, 27 Oct, on a fresh install: the first home teleport played on
 * the follower with no circle and no book, and a later one had both. A
 * graphic's model or animation the client has never drawn is fetched from
 * the game's servers, and the first ask for it gets nothing; the graphic was
 * skipped and never asked for again. The follower is driven here through a
 * client whose models and animations land when the test says so.
 */
public class GraphicDownloadTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final int[] STAGES = {4847, 4850, 4853};
	private static final SpotAnimRepository.Entry CIRCLE = graphic(18539, 4848);
	private static final SpotAnimRepository.Entry BOOK = graphic(18537, 4854);
	private static final SpotAnimRepository.Entry GLOW = graphic(18538, 4856);

	/** The models and animations the client has; every other one is still downloading. */
	private final Set<Integer> landed = new HashSet<>();

	/** Every model asked for, landed or not. */
	private final List<Integer> asked = new ArrayList<>();

	/** Every graphic shown, in the order shown: the follower itself is not made this way. */
	private final List<RuneLiteObject> made = new ArrayList<>();
	private final Set<Object> registered = new HashSet<>();

	private FollowerEntity follower;

	private static SpotAnimRepository.Entry graphic(int model, int animation)
	{
		SpotAnimRepository.Entry entry = new SpotAnimRepository.Entry();
		entry.m = model;
		entry.a = animation;
		return entry;
	}

	@Before
	public void setUp() throws IOException, ReflectiveOperationException
	{
		Client[] client = new Client[1];
		client[0] = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "loadAnimation":
						int id = (Integer) args[0];
						boolean clip = Arrays.stream(STAGES).anyMatch(stage -> stage == id);
						return clip || landed.contains(id) ? animation(id) : null;
					case "loadModelData":
						asked.add((Integer) args[0]);
						return landed.contains(args[0]) ? modelData() : null;
					case "createRuneLiteObject":
						RuneLiteObject graphic = new RuneLiteObject(client[0]);
						made.add(graphic);
						return graphic;
					case "registerRuneLiteObject":
						registered.add(args[0]);
						return null;
					case "removeRuneLiteObject":
						registered.remove(args[0]);
						return null;
					case "isRuneLiteObjectRegistered":
						return registered.contains(args[0]);
					default:
						return zero(method.getReturnType());
				}
			});
		StanceLibrary stances = new StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		stances.load(folder.newFolder().toPath());
		follower = new FollowerEntity(client[0], stances);
		set("object", new RuneLiteObject(client[0]));
		set("animatable", true);
		set("lastRenderedLocation", new LocalPoint(6400, 6400, -1));
	}

	/** Ten frames of five client cycles. */
	private static Animation animation(int id)
	{
		return (Animation) Proxy.newProxyInstance(Animation.class.getClassLoader(),
			new Class<?>[]{Animation.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getId":
						return id;
					case "getFrameLengths":
						int[] lengths = new int[10];
						Arrays.fill(lengths, 5);
						return lengths;
					case "getFrameStep":
						return -1;
					case "hashCode":
						return System.identityHashCode(proxy);
					case "equals":
						return proxy == args[0];
					default:
						return zero(method.getReturnType());
				}
			});
	}

	/** One face held well off the ground, whose every clone and transform is itself. */
	private static ModelData modelData()
	{
		return (ModelData) Proxy.newProxyInstance(ModelData.class.getClassLoader(),
			new Class<?>[]{ModelData.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getFaceCount":
						return 1;
					case "getVerticesY":
						return new float[]{-50, -50, -50};
					case "getFaceIndices1":
						return new int[]{0};
					case "getFaceIndices2":
						return new int[]{1};
					case "getFaceIndices3":
						return new int[]{2};
					default:
						Class<?> type = method.getReturnType();
						return type.isInstance(proxy) ? proxy : zero(type);
				}
			});
	}

	/** What a proxy answers for anything it was not told about. */
	private static Object zero(Class<?> type)
	{
		if (type == boolean.class)
		{
			return false;
		}
		if (type == int.class)
		{
			return 0;
		}
		if (type == long.class)
		{
			return 0L;
		}
		if (type == short.class)
		{
			return (short) 0;
		}
		if (type == float.class)
		{
			return 0f;
		}
		return null;
	}

	private void set(String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerEntity.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(follower, value);
	}

	private void land(SpotAnimRepository.Entry graphic)
	{
		landed.add(graphic.modelId());
		landed.add(graphic.animationId());
	}

	private void cast()
	{
		follower.startSlavedChain(STAGES, new SpotAnimRepository.Entry[]{CIRCLE, BOOK, GLOW});
	}

	@Test
	public void aGraphicStillDownloadingGoesOnTheFrameItLands()
	{
		follower.playSpotAnim(CIRCLE);
		follower.placePendingGraphics();
		assertEquals("nothing to show yet", 0, made.size());

		land(CIRCLE);
		follower.placePendingGraphics();
		assertEquals("on as it lands", 1, made.size());
		assertTrue(made.get(0).isActive());

		follower.placePendingGraphics();
		assertEquals("and once", 1, made.size());
	}

	@Test
	public void aModelInWhileItsAnimationIsNotWaitsForBoth()
	{
		landed.add(CIRCLE.modelId());
		follower.playSpotAnim(CIRCLE);
		follower.placePendingGraphics();
		assertEquals(0, made.size());

		landed.add(CIRCLE.animationId());
		follower.placePendingGraphics();
		assertEquals(1, made.size());
	}

	@Test
	public void aCastAsksForEveryStagesGraphicAsItStarts()
	{
		cast();
		assertTrue("the book and its glow download while the circle is drawn",
			asked.containsAll(Arrays.asList(CIRCLE.modelId(), BOOK.modelId(), GLOW.modelId())));
	}

	@Test
	public void theFirstStagesGraphicComesOnLateInItsOwnStage()
	{
		cast();
		assertEquals(0, made.size());

		land(CIRCLE);
		follower.placePendingGraphics();
		assertEquals("the circle, while its stage plays", 1, made.size());
	}

	@Test
	public void aStagesGraphicThatLandsAfterItsStageNeverShows()
	{
		land(BOOK);
		cast();
		follower.advanceSlavedChain();
		assertEquals("the book, the second stage's", 1, made.size());

		land(CIRCLE);
		follower.placePendingGraphics();
		assertEquals("the first stage's circle is not put on over it", 1, made.size());
	}

	@Test
	public void aCancelledCastTakesItsDownloadsWithIt()
	{
		cast();
		follower.cancelEmote();

		land(CIRCLE);
		follower.placePendingGraphics();
		assertEquals(0, made.size());
	}

	@Test
	public void aLateGraphicStartsWhereItWouldHaveGotTo()
	{
		Animation animation = animation(CIRCLE.animationId());
		assertEquals(0, FollowerEntity.frameAt(animation, 0));
		assertEquals("twelve cycles in is the third frame", 2, FollowerEntity.frameAt(animation, 12));
		assertEquals("and fifty is past its end", -1, FollowerEntity.frameAt(animation, 50));
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

/**
 * Public QA, 27 Oct: mid home teleport, the chalk circle round the
 * follower's feet was drawn wholly over its legs, back half and all. The
 * game sorts a player's spotanim into the player's own model face by face;
 * the follower's graphics are objects of their own, and same-tile objects
 * draw in the order they joined the scene. A graphic's faces on the ground
 * go under the follower and the rest over it.
 */
public class GraphicLayeringTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final SpotAnimRepository.Entry GRAPHIC = new SpotAnimRepository.Entry();

	static
	{
		GRAPHIC.m = 18539;
		GRAPHIC.a = 4848;
	}

	/** The height of each face of the graphic's model, up being negative. */
	private float[] faceHeights;

	/** Every graphic object made, in order, and the face colours it was lit with. */
	private final List<RuneLiteObject> made = new ArrayList<>();
	private final List<int[]> lit = new ArrayList<>();

	/** What is in the scene, in the order it joined. */
	private final List<Object> scene = new ArrayList<>();

	private RuneLiteObject body;
	private FollowerEntity follower;

	@Before
	public void setUp() throws IOException, ReflectiveOperationException
	{
		Client[] client = new Client[1];
		client[0] = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "loadAnimation":
						return animation();
					case "loadModelData":
						return modelData();
					case "createRuneLiteObject":
						RuneLiteObject graphic = new RuneLiteObject(client[0]);
						made.add(graphic);
						return graphic;
					case "registerRuneLiteObject":
						if (!scene.contains(args[0]))
						{
							scene.add(args[0]);
						}
						return null;
					case "removeRuneLiteObject":
						scene.remove(args[0]);
						return null;
					case "isRuneLiteObjectRegistered":
						return scene.contains(args[0]);
					default:
						return zero(method.getReturnType());
				}
			});
		StanceLibrary stances = new StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		stances.load(folder.newFolder().toPath());
		follower = new FollowerEntity(client[0], stances);
		body = new RuneLiteObject(client[0]);
		body.setActive(true);
		set("object", body);
		set("animatable", true);
		set("lastRenderedLocation", new LocalPoint(6400, 6400, -1));
	}

	private static Animation animation()
	{
		return (Animation) Proxy.newProxyInstance(Animation.class.getClassLoader(),
			new Class<?>[]{Animation.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getFrameLengths":
						int[] lengths = new int[10];
						Arrays.fill(lengths, 5);
						return lengths;
					case "hashCode":
						return System.identityHashCode(proxy);
					case "equals":
						return proxy == args[0];
					default:
						return zero(method.getReturnType());
				}
			});
	}

	/** One face per height, whose every clone and transform is itself. */
	private ModelData modelData()
	{
		int faces = faceHeights.length;
		float[] ys = new float[faces * 3];
		int[][] corners = new int[3][faces];
		for (int i = 0; i < faces; i++)
		{
			for (int corner = 0; corner < 3; corner++)
			{
				ys[i * 3 + corner] = faceHeights[i];
				corners[corner][i] = i * 3 + corner;
			}
		}
		return (ModelData) Proxy.newProxyInstance(ModelData.class.getClassLoader(),
			new Class<?>[]{ModelData.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getFaceCount":
						return faces;
					case "getVerticesY":
						return ys;
					case "getFaceIndices1":
						return corners[0];
					case "getFaceIndices2":
						return corners[1];
					case "getFaceIndices3":
						return corners[2];
					case "light":
						int[] colours = new int[faces];
						lit.add(colours);
						return model(colours);
					default:
						Class<?> type = method.getReturnType();
						return type.isInstance(proxy) ? proxy : zero(type);
				}
			});
	}

	private static Model model(int[] colours)
	{
		return (Model) Proxy.newProxyInstance(Model.class.getClassLoader(),
			new Class<?>[]{Model.class}, (proxy, method, args) ->
				method.getName().equals("getFaceColors3") ? colours : zero(method.getReturnType()));
	}

	/** What a proxy answers for anything it was not told about. */
	private static Object zero(Class<?> type)
	{
		if (type == boolean.class)
		{
			return false;
		}
		if (type == int.class)
		{
			return 0;
		}
		if (type == long.class)
		{
			return 0L;
		}
		if (type == short.class)
		{
			return (short) 0;
		}
		if (type == float.class)
		{
			return 0f;
		}
		return null;
	}

	private void set(String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerEntity.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(follower, value);
	}

	@Test
	public void aCircleOnTheGroundIsDrawnUnderTheFollower()
	{
		faceHeights = new float[]{0, -2, 0};
		follower.playSpotAnim(GRAPHIC);

		assertEquals("one object", 1, made.size());
		assertEquals("joined ahead of the follower", Arrays.asList(made.get(0), body), scene);
		assertArrayEquals("with every face of it", new int[3], lit.get(0));
	}

	@Test
	public void aSwirlRoundTheBodyIsDrawnOverIt()
	{
		faceHeights = new float[]{-40, -90, -140};
		follower.playSpotAnim(GRAPHIC, FollowerEntity.TELEPORT_GRAPHIC_HEIGHT);

		assertEquals(1, made.size());
		assertEquals("joined after the follower", Arrays.asList(body, made.get(0)), scene);
	}

	@Test
	public void aGraphicOnTheGroundAndOffItIsSplitAroundTheFollower()
	{
		// The book and its glow over the circle.
		faceHeights = new float[]{0, -60, -1, -80};
		follower.playSpotAnim(GRAPHIC);

		assertEquals("two objects", 2, made.size());
		RuneLiteObject over = made.get(0);
		RuneLiteObject under = made.get(1);
		assertEquals(Arrays.asList(under, body, over), scene);
		assertArrayEquals("the over one skips the ground faces", new int[]{-2, 0, -2, 0}, lit.get(0));
		assertArrayEquals("and the under one the rest", new int[]{0, -2, 0, -2}, lit.get(1));
	}

	@Test
	public void aLaterGraphicKeepsTheEarlierOnesOnTheirSides()
	{
		faceHeights = new float[]{-40};
		follower.playSpotAnim(GRAPHIC);
		RuneLiteObject swirl = made.get(0);
		faceHeights = new float[]{0};
		follower.playSpotAnim(GRAPHIC);
		RuneLiteObject circle = made.get(1);

		assertEquals(Arrays.asList(circle, body, swirl), scene);
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * R24's guard, measured rather than believed.
 *
 * <p>What it actually does: repeating needs a hundred ticks of sustained
 * animation to count, and resets within four quiet ticks of stopping. So
 * the guard bites during a LIVE grind - the combat stretch is the case that
 * matters, since the idle gates already keep the idle-triggered openers out
 * of anything animated - and releases almost immediately after, so a wish
 * or a question lands in the calm after the work rather than never.
 */
public class GrindGuardTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** A probe with the exact guard shape the openers carry, triggered on demand. */
	private Harness guarded() throws IOException
	{
		return new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"probe\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"all\", \"conditions\": ["
				+ "{\"type\": \"none\", \"conditions\": [ {\"type\": \"repeating\"} ]},"
				+ "{\"type\": \"answered\", \"is\": \"yes\"}]},"
				+ " \"say\": [\"opened\"]}]}");
	}

	@Test
	public void theGuardBitesMidGrindAndReleasesAfter() throws IOException
	{
		Harness h = guarded();
		h.gameTicks(1);

		// A hundred and twenty ticks of the same swing: a real grind.
		h.game.animating(879);
		h.gameTicks(120);
		h.answers("yes", "want-outing");
		h.gameTicks(2);
		assertTrue("nothing demanding opens mid-grind", h.spoken.isEmpty());

		// The grind ends; the guard lets go within a few quiet ticks, so the
		// opener lands in the calm after the work rather than never.
		h.game.animating(-1);
		h.gameTicks(6);
		h.answers("yes", "want-outing");
		h.gameTicks(2);
		assertEquals("the calm after the grind is fair game",
			1, h.firedBy("probe").size());
	}

	@Test
	public void aShortTaskNeverTripsTheGuard() throws IOException
	{
		// Under a hundred ticks of activity is a task, not a grind; the
		// guard must not punish somebody who chopped three logs.
		Harness h = guarded();
		h.gameTicks(1);

		h.game.animating(879);
		h.gameTicks(40);
		h.answers("yes", "want-outing");
		h.gameTicks(2);
		assertEquals("forty ticks of work is not a grind",
			1, h.firedBy("probe").size());
	}
}

