package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * A running speech engine with nothing behind it but {@link FakeGame}.
 *
 * <p>Loads the rules the plugin actually ships - the loader writes them from the
 * bundled resource into a scratch directory - so these tests exercise the real
 * rule set rather than a hand-written stand-in that could drift from it.
 */
public final class Harness
{
	/** One thing the engine asked the plugin to say. */
	public static final class Spoken
	{
		public final String text;
		public final SpeechOutput output;
		public final SpeechRule rule;
		public final int animationId;

		Spoken(String text, SpeechOutput output, SpeechRule rule, int animationId)
		{
			this.text = text;
			this.output = output;
			this.rule = rule;
			this.animationId = animationId;
		}

		@Override
		public String toString()
		{
			return (rule == null ? "(direct)" : rule.describe())
				+ " -> \"" + text + "\" anim=" + animationId;
		}
	}

	public final FakeGame game = new FakeGame();
	public final RuleLoader loader = new RuleLoader(new Gson());
	public final SpeechEngine engine;
	public final List<Spoken> spoken = new ArrayList<>();

	private final Path scratch;
	private int tick;

	/** Loads the rules the plugin ships with. */
	public Harness(Path scratch) throws IOException
	{
		this(scratch, null);
	}

	/**
	 * @param rulesJson the body of a phrases.json to use instead of the bundled
	 * rules, or null for the bundled set. Written to disk and read back through
	 * the real loader, so a focused test still goes through parsing and
	 * validation rather than around them.
	 */
	public Harness(Path scratch, String rulesJson) throws IOException
	{
		this.scratch = scratch;
		Files.createDirectories(scratch);
		Path file = scratch.resolve(RuleLoader.FILE_NAME);
		if (rulesJson != null)
		{
			Files.write(file, rulesJson.getBytes(java.nio.charset.StandardCharsets.UTF_8));
		}
		else
		{
			Files.deleteIfExists(file);
		}

		loader.initialise(scratch);
		engine = new SpeechEngine(game.client, loader);
		// No queue in the harness: every line is delivered the moment it is
		// handed over, so the said-conditional latches run before the engine
		// call returns - same order the old immediate latching had.
		engine.setSink((text, output, rule, animationId, onSaid) ->
		{
			onSaid.run();
			spoken.add(new Spoken(text, output, rule, animationId));
		});
		// Off by default: the global window is a separate thing to test, and
		// leaving it on would silently swallow most firings in every other test.
		engine.setGlobalCooldownMs(0L);
	}

	public Path getScratch()
	{
		return scratch;
	}

	/**
	 * One game tick: advances the clock, refreshes the state snapshot and
	 * dispatches the tick heartbeat, in the order the plugin does it.
	 */
	public Harness gameTick()
	{
		game.tick(++tick);
		engine.refreshContext();
		engine.dispatch(TriggerEvent.tick());
		return this;
	}

	public Harness gameTicks(int count)
	{
		for (int i = 0; i < count; i++)
		{
			gameTick();
		}
		return this;
	}

	/** Dispatches an event mid-tick, as the plugin's own subscribers do. */
	public Harness dispatch(TriggerEvent event)
	{
		engine.dispatch(event);
		return this;
	}

	/** The local player saying something in public chat. */
	public Harness playerSays(String message)
	{
		engine.dispatch(TriggerEvent.chat(message,
			net.runelite.api.ChatMessageType.PUBLICCHAT.getType(), "Tester"));
		return this;
	}

	/**
	 * The player picking a branch that answers, as the dialog does: the
	 * question closes and the rules are told, in that order.
	 */
	public Harness answers(String yesOrNo)
	{
		return answers(yesOrNo, "");
	}

	/** The same, naming the tree the answer belongs to. */
	public Harness answers(String answer, String tree)
	{
		engine.getContext().noteAnswered();
		engine.dispatch(TriggerEvent.answered(answer, tree));
		return this;
	}

	/** Somebody else in public chat. */
	public Harness someoneSays(String who, String message)
	{
		engine.dispatch(TriggerEvent.chat(message,
			net.runelite.api.ChatMessageType.PUBLICCHAT.getType(), who));
		return this;
	}

	public List<Spoken> firedBy(String ruleId)
	{
		List<Spoken> hits = new ArrayList<>();
		for (Spoken s : spoken)
		{
			if (s.rule != null && ruleId.equals(s.rule.id))
			{
				hits.add(s);
			}
		}
		return hits;
	}

	public SpeechRule rule(String id)
	{
		for (SpeechRule rule : loader.getRules())
		{
			if (id.equals(rule.id))
			{
				return rule;
			}
		}
		throw new AssertionError("no rule '" + id + "' in the bundled set");
	}

	public void clear()
	{
		spoken.clear();
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;

/**
 * How much of the player's memory the plugin keeps.
 *
 * <p>It loads the whole equipment catalogue, every spotanim and every game font
 * and holds them for the session, inside a client that is already the largest
 * thing on most people's machines. That has never been measured - only the file
 * sizes on disk, which say almost nothing about the heap: an 865KB JSON of six
 * thousand small objects can land anywhere between a tenth and ten times that
 * once it is a Map of Entry.
 *
 * <p>The answer, measured: about six megabytes for the lot, in a client that
 * routinely holds several hundred. There is nothing to optimise here, and that
 * is worth knowing - the file sizes suggested otherwise and it would have been
 * easy to spend a day making the catalogues clever for no reason.
 *
 * <p>So these are regression budgets rather than targets. Each is roughly
 * triple what is actually used: far enough above that the measurement's own
 * noise can never fail it - four consecutive runs agreed to a tenth of a
 * megabyte - and close enough that a catalogue doubling does. If one of these
 * fails and the growth was deliberate, raise the number and say why in the
 * commit.
 */
public class HeapFootprintTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** The real dumps, if this machine has them. Skipped elsewhere. */
	private static final Path LIVE_DATA =
		Paths.get(System.getProperty("user.home"), ".runelite", "follower");

	private static long usedBytes()
	{
		Runtime runtime = Runtime.getRuntime();
		for (int i = 0; i < 4; i++)
		{
			System.gc();
			try
			{
				Thread.sleep(30);
			}
			catch (InterruptedException e)
			{
				Thread.currentThread().interrupt();
			}
		}
		return runtime.totalMemory() - runtime.freeMemory();
	}

	private static void report(String what, long bytes, long budgetMb)
	{
		double mb = bytes / (1024.0 * 1024.0);
		System.out.printf("  %-28s %6.1f MB   (budget %d MB)%n", what, mb, budgetMb);
		assertTrue(what + " holds " + String.format("%.1f", mb)
			+ " MB, over its " + budgetMb + " MB budget - if that is a deliberate"
			+ " growth, raise the budget and say why", mb < budgetMb);
	}

	@Test
	public void theGameFontsFitInTheirBudget() throws IOException
	{
		Path dump = LIVE_DATA.resolve("fonts.json");
		assumeTrue("no font dump on this machine", Files.isRegularFile(dump));

		// Twenty-one fonts of 256 glyphs each, every glyph a pixel mask. This
		// is the one most likely to surprise: the file is base64 and the heap
		// form is decoded bytes.
		long before = usedBytes();
		GameFontRepository fonts = new GameFontRepository(new Gson());
		fonts.load();
		long after = usedBytes();

		report("game fonts", after - before, 3);
	}

	@Test
	public void theRuleSetFitsInItsBudget() throws IOException
	{
		// Three hundred rules with their notes and phrase lists, plus a
		// compiled pattern per name list once they have been evaluated.
		long before = usedBytes();
		RuleLoader loader = new RuleLoader(new Gson());
		loader.initialise(folder.newFolder().toPath());
		long after = usedBytes();

		report("rules and phrases", after - before, 2);
		assertTrue("the rules did not load", loader.getRules().size() > 100);
	}
}

package com.follower;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.NPC;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * A line kept waiting is said only if what it is about still stands.
 * Behaviour QA, 16 Oct: critical-hp met the gap behind low-hp and was said
 * 4-8 s later, after the player had eaten or teleported ("49 HP! Get out!"
 * at 70 percent), and a person seen during someone else's conversation, a
 * scene or its quiet was announced after they had gone.
 *
 * <p>When the line is let go, its health, prayer, poison or person is read
 * again. Passed, it goes unsaid and gives its cooldown back, so it rises
 * the next time it is true.
 */
public class HeldLinePassesTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private final long[] ms = {1_700_000_000_000L};

	private final List<String> held = new ArrayList<>();

	private static final String LOW = "{\"id\": \"low\", \"group\": \"t\", \"occasion\": true, \"cooldownMs\": 15000,"
		+ " \"when\": {\"type\": \"healthBelow\", \"percent\": 40}, \"say\": [\"Eat something.\"]}";

	private static final String CRITICAL = "{\"id\": \"critical\", \"group\": \"t\", \"occasion\": true,"
		+ " \"cooldownMs\": 8000, \"when\": {\"type\": \"healthBelow\", \"percent\": 20}, \"say\": [\"Get out!\"]}";

	private static final String HANS = "{\"id\": \"hans\", \"group\": \"t\", \"waits\": true, \"cooldownMs\": 3600000,"
		+ " \"when\": {\"type\": \"npcNearby\", \"within\": 5, \"names\": [\"Hans\"]}, \"say\": [\"There goes Hans.\"]}";

	private Harness harness(String... bodies) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": [" + String.join(",", bodies) + "]}");
		return wire(h);
	}

	private Harness wire(Harness h)
	{
		h.engine.setClock(() -> ms[0]);
		h.engine.setGlobalCooldownMs(6000L);
		h.engine.setOnSuppressed((rule, why) -> held.add(rule.describe() + ":" + why));
		h.game.at(3222, 3218, 0);
		h.gameTicks(1);
		return h;
	}

	private void ticks(Harness h, int count)
	{
		for (int i = 0; i < count; i++)
		{
			ms[0] += 600;
			h.gameTick();
		}
	}

	@Test
	public void aWarningTheGapHeldIsLetGoOnceThePlayerHasEaten() throws IOException
	{
		// Probe P4: 37 percent, then 17, then a bite.
		Harness h = harness(LOW, CRITICAL);
		h.game.hitpoints(37, 100);
		ticks(h, 1);
		assertEquals(1, h.firedBy("low").size());

		h.game.hitpoints(17, 100);
		ticks(h, 2);
		h.game.hitpoints(60, 100);
		ticks(h, 20);
		assertTrue("not said at 60 percent: " + h.spoken, h.firedBy("critical").isEmpty());
		assertTrue(held.toString(), held.contains("critical:passed"));

		// Its cooldown given back: the next crossing, inside the old
		// cooldown's 8 s, is said.
		ms[0] += 1_000L;
		h.game.hitpoints(15, 100);
		ticks(h, 1);
		assertEquals("said on the next crossing", 1, h.firedBy("critical").size());
	}

	@Test
	public void aWarningStillTrueWhenTheGapEndsIsSaid() throws IOException
	{
		Harness h = harness(LOW, CRITICAL);
		h.game.hitpoints(37, 100);
		ticks(h, 1);
		h.game.hitpoints(17, 100);
		ticks(h, 2);
		assertTrue("waiting out the gap", h.firedBy("critical").isEmpty());
		ticks(h, 12);
		assertEquals("still at 17 percent, so said", 1, h.firedBy("critical").size());
	}

	@Test
	public void aPasserBySeenInSomeoneElsesConversationIsNotAnnouncedAfterHeHasGone() throws IOException
	{
		// Probe P2: Hans passes within 2 tiles during a 30 s conversation.
		Harness h = harness(HANS);
		NPC hans = h.game.spawnNpc(9001, "Hans", 0);
		h.game.moveNpc(hans, 3240, 3218, 0);
		h.engine.getContext().setDialogueOpen(true);
		ticks(h, 10);
		h.game.moveNpc(hans, 3224, 3218, 0);
		ticks(h, 4);
		h.game.moveNpc(hans, 3240, 3218, 0);
		ticks(h, 36);
		h.engine.getContext().setDialogueOpen(false);
		ticks(h, 10);
		assertTrue("Hans is 18 tiles off: " + h.spoken, h.firedBy("hans").isEmpty());
		assertTrue(held.toString(), held.contains("hans:passed"));

		// And the next time he comes by, he is announced: the hour's
		// cooldown went back with the line.
		h.game.moveNpc(hans, 3224, 3218, 0);
		ticks(h, 2);
		assertEquals(1, h.firedBy("hans").size());
	}

	@Test
	public void aPersonStillThereAfterTheConversationIsAnnounced() throws IOException
	{
		Harness h = harness(HANS);
		NPC hans = h.game.spawnNpc(9001, "Hans", 0);
		h.engine.getContext().setDialogueOpen(true);
		h.game.moveNpc(hans, 3224, 3218, 0);
		ticks(h, 20);
		h.engine.getContext().setDialogueOpen(false);
		ticks(h, 4);
		assertEquals(1, h.firedBy("hans").size());
	}

	@Test
	public void theShippedCriticalWarningIsLetGoAfterABite() throws IOException
	{
		// The shipped rules: low-hp at 37 percent, critical-hp a hit later,
		// then the player eats before the gap is out.
		Harness h = wire(new Harness(folder.newFolder().toPath()));
		ticks(h, 20);
		h.spoken.clear();
		h.game.hitpoints(26, 70);
		ticks(h, 1);
		assertEquals(h.spoken.toString(), 1, h.firedBy("low-hp").size());
		h.game.hitpoints(12, 70);
		ticks(h, 2);
		h.game.hitpoints(49, 70);
		ticks(h, 20);
		assertTrue("no 'Get out!' at 70 percent: " + h.spoken, h.firedBy("critical-hp").isEmpty());
		assertTrue(held.toString(), held.contains("critical-hp:passed"));
	}

	@Test
	public void aWarningAnsweredWhileItWaitedIsLetGo() throws IOException
	{
		// Probe P12: 60 damage to 14 percent just after another line, and
		// the player teleports 2 ticks later, still at 14. "Get out!" was
		// said after the teleport, and the advice was called ignored a
		// minute on. The advised act, played while it waited, answers it.
		Harness h = wire(new Harness(folder.newFolder().toPath()));
		ticks(h, 20);
		h.spoken.clear();
		h.engine.remark("That was a 60.");
		h.game.hitpoints(10, 70);
		ticks(h, 2);
		h.dispatch(TriggerEvent.animation(714));
		ticks(h, 20);
		assertTrue("not said after the teleport: " + h.spoken, h.firedBy("critical-hp").isEmpty());
		assertTrue(held.toString(), held.contains("critical-hp:passed"));
	}
}

package com.follower;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Hide in PvP areas: the setting says the Wilderness and other PvP areas,
 * and the follower goes in both. QA2, 15 Oct: only the Wilderness was read,
 * so on a PvP world it stayed out beside the player.
 */
public class HideInPvpTest
{
	@Test
	public void itGoesInTheWildernessAndEveryOtherPvpArea() throws ReflectiveOperationException
	{
		assertFalse("anywhere else it stays", hidden(new FakeGame(), true));
		assertTrue("the Wilderness", hidden(new FakeGame().varbit(VarbitID.INSIDE_WILDERNESS, 1), true));
		assertTrue("a PvP area, such as a PvP world outside its safe zones",
			hidden(new FakeGame().varbit(VarbitID.PVP_AREA_CLIENT, 1), true));
		assertFalse("and none of it with the setting off",
			hidden(new FakeGame().varbit(VarbitID.PVP_AREA_CLIENT, 1), false));
	}

	private static boolean hidden(FakeGame game, boolean hideInPvp) throws ReflectiveOperationException
	{
		FollowerPlugin plugin = new FollowerPlugin();
		set(plugin, "client", game.client);
		set(plugin, "config", new FollowerConfig()
		{
			@Override
			public boolean hideInPvp()
			{
				return hideInPvp;
			}
		});
		Method shouldHide = FollowerPlugin.class.getDeclaredMethod("shouldHide");
		shouldHide.setAccessible(true);
		return (Boolean) shouldHide.invoke(plugin);
	}

	private static void set(Object target, String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(target, value);
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;

/**
 * A world hop forgets the edges, not what was said. Behaviour QA, 16 Oct
 * (probe P1): Callisto's intro, an hour's cooldown, was said again on the
 * next approach a minute after a hop, and crowded-here (45 minutes) again
 * after every GE hop.
 */
public class HopKeepsCooldownsTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private final long[] ms = {1_700_000_000_000L};

	private Harness harness(long cooldownMs) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": [{\"id\": \"boss\", \"group\": \"t\", \"occasion\": true,"
				+ " \"cooldownMs\": " + cooldownMs + ", \"when\": {\"type\": \"healthBelow\", \"percent\": 50},"
				+ " \"say\": [\"Bears don't get this big on their own.\"]}]}");
		h.engine.setClock(() -> ms[0]);
		h.gameTicks(1);
		return h;
	}

	private void ticks(Harness h, int count)
	{
		for (int i = 0; i < count; i++)
		{
			ms[0] += 600;
			h.gameTick();
		}
	}

	@Test
	public void aLineSaidBeforeAHopKeepsItsCooldownAfterIt() throws IOException
	{
		Harness h = harness(3_600_000L);
		h.game.hitpoints(10, 99);
		ticks(h, 1);
		assertEquals(1, h.firedBy("boss").size());
		h.game.hitpoints(99, 99);
		ticks(h, 60);

		h.engine.resetForNewScene();
		h.game.hitpoints(10, 99);
		ticks(h, 5);
		assertEquals("not again a minute later", 1, h.firedBy("boss").size());
	}

	@Test
	public void theEdgeIsStillForgotten() throws IOException
	{
		// What is true in the new world is news there: a condition true
		// through the hop rises again.
		Harness h = harness(0L);
		h.game.hitpoints(10, 99);
		ticks(h, 1);
		h.engine.resetForNewScene();
		ticks(h, 1);
		assertEquals(2, h.firedBy("boss").size());
	}

	@Test
	public void aLineWaitingAtTheHopIsNotLostForItsCooldown() throws IOException
	{
		// Behaviour QA4, 16 Oct (probe Q3): Tobyn's line was waiting its gap
		// when the player hopped, and was gone for the hour with him still
		// beside the player. Its cooldown is given back, so it rises again.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": [{\"id\": \"tobyn\", \"group\": \"quest\", \"waits\": true,"
				+ " \"cooldownMs\": 3600000, \"when\": {\"type\": \"npcNearby\", \"within\": 5,"
				+ " \"names\": [\"Sergeant Tobyn\"]}, \"say\": [\"Sergeant Tobyn.\"]}]}");
		h.engine.setClock(() -> ms[0]);
		h.engine.setGlobalCooldownMs(45_000L);
		h.game.at(3222, 3218, 0);
		h.gameTicks(1);
		h.engine.remark("Hold still a moment.");
		ticks(h, 1);
		h.game.moveNpc(h.game.spawnNpc(12703, "Sergeant Tobyn", 0), 3224, 3218, 0);
		ticks(h, 5);
		assertEquals("waiting its gap", 0, h.firedBy("tobyn").size());

		// The hop as the plugin has it: the scene goes, and the new one's
		// baseline is taken (behaviour QA5: without the prime this passed
		// while the plugin never said the line).
		h.engine.resetForNewScene();
		h.engine.primeEdgesOnNextTick();
		ticks(h, 5);
		assertEquals("said after the hop, him still there", 1, h.firedBy("tobyn").size());
	}
}

package com.follower;

import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The tiles the map calls walkable that nobody walks on. Kept from the
 * objects the client announces, which is the only way the answer can be
 * exact and still cost a hash lookup per tile of a route.
 */
public class HotGroundTest
{
	private static final int FIRE = 26185;
	private static final int CAMPFIRE = 43475;
	private static final int TREE = 1276;

	private FakeGame game;
	private HotGround hot;

	@Before
	public void setUp()
	{
		game = new FakeGame();
		game.placeObject(FIRE, "Fire", 0, 0, 0);
		game.placeObject(CAMPFIRE, "Forester's Campfire", 0, 0, 0);
		game.placeObject(TREE, "Tree", 0, 0, 0);
		hot = new HotGround(game.client);
	}

	private static WorldPoint at(int x, int y)
	{
		return new WorldPoint(x, y, 0);
	}

	@Test
	public void aFireMakesItsTileHotAndBurningOutMakesItColdAgain()
	{
		assertFalse(hot.hot(at(50, 50)));
		hot.objectSpawned(FIRE, at(50, 50), at(50, 50));
		assertTrue(hot.hot(at(50, 50)));
		assertFalse("and only its own tile", hot.hot(at(51, 50)));
		assertEquals(1, hot.count());

		hot.objectDespawned(FIRE, at(50, 50), at(50, 50));
		assertFalse("burnt out", hot.hot(at(50, 50)));
		assertEquals(0, hot.count());
	}

	@Test
	public void everythingElseInTheSceneIsCold()
	{
		hot.objectSpawned(TREE, at(50, 50), at(51, 51));
		assertFalse(hot.hot(at(50, 50)));
		assertFalse(hot.hot(at(51, 51)));
		assertEquals(0, hot.count());
	}

	@Test
	public void aCampfireCountsToo()
	{
		hot.objectSpawned(CAMPFIRE, at(60, 60), null);
		assertTrue("standing in a campfire is the same silliness", hot.hot(at(60, 60)));
	}

	@Test
	public void theNamesAreMatchedHoweverTheGameCapitalisesThem()
	{
		assertTrue(HotGround.isFire("Fire"));
		assertTrue(HotGround.isFire("fire"));
		assertTrue(HotGround.isFire("Campfire"));
		assertTrue(HotGround.isFire("Forester's Campfire"));
		assertFalse(HotGround.isFire("Burning brazier"));
		assertFalse(HotGround.isFire("Firepit"));
		assertFalse(HotGround.isFire(null));
	}

	@Test
	public void aLineOfFiresIsAListOfTiles()
	{
		for (int x = 50; x < 56; x++)
		{
			hot.objectSpawned(FIRE, at(x, 50), at(x, 50));
		}
		assertEquals(6, hot.count());
		for (int x = 50; x < 56; x++)
		{
			assertTrue(hot.hot(at(x, 50)));
		}
		assertFalse(hot.hot(at(50, 51)));

		hot.clear();
		assertEquals("a hop takes the scene and its fires with it", 0, hot.count());
	}

	@Test
	public void nothingAtAllIsCold()
	{
		assertFalse(hot.hot(null));
		hot.objectSpawned(FIRE, null, null);
		assertEquals(0, hot.count());
	}

	@Test
	public void aFootprintTooBigToBeAFireIsNotWalkedRoundWholesale()
	{
		// Belt and braces: an id that resolves to a fire name on a footprint
		// the size of a building is a mistake somewhere, and answering with
		// the whole building would push the follower about the map.
		hot.objectSpawned(FIRE, at(50, 50), at(70, 70));
		assertEquals(1, hot.count());
		assertTrue(hot.hot(at(50, 50)));
		assertFalse(hot.hot(at(60, 60)));
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The bookkeeping nobody sees until it goes wrong.
 *
 * <p>Every case here is a fault that produces no error, no log line and no
 * visible symptom at the moment it happens - a follower that goes quiet for ten
 * seconds after a file save, a save that rewrites nine kilobytes of identical
 * JSON every minute for as long as the client is open. They are found by asking
 * rather than by noticing.
 */
public class HousekeepingTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void reloadingTheRulesReleasesAHeldFloor()
	{
		// The exemption that lets the floor's holder speak through its own hush
		// is by identity, and a reload parses every rule afresh. Without the
		// release the holder becomes an object nothing points at, and the hush
		// it left behind silences the entire file until it times out - so
		// saving phrases.json mid-arrival muted the follower for ten seconds.
		Harness h = harnessWithAFloorRule();
		h.gameTicks(1);

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertFalse("the floor is taken", h.firedBy("important").isEmpty());

		h.dispatch(TriggerEvent.death());
		assertTrue("and held", h.firedBy("chatter").isEmpty());

		// A tick between the two deaths, or the second is not a rising edge:
		// playerDeath is only true while that dispatch is being processed, and
		// the first one already consumed the edge on its way to being hushed.
		h.gameTicks(1);
		h.engine.clearFloor();

		h.dispatch(TriggerEvent.death());
		assertFalse("releasing it lets everything else speak again",
			h.firedBy("chatter").isEmpty());
	}

	private Harness harnessWithAFloorRule() throws AssertionError
	{
		try
		{
			return new Harness(folder.newFolder().toPath(),
				"{\"version\": 1, \"rules\": ["
					+ "{\"id\": \"important\", \"group\": \"t\", \"cooldownMs\": 0,"
					+ " \"hushMs\": 60000, \"when\": {\"type\": \"examined\"},"
					+ " \"say\": [\"listen to me\"]},"
					+ "{\"id\": \"chatter\", \"group\": \"t\", \"cooldownMs\": 0,"
					+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"unrelated\"]}]}");
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}

	@Test
	public void nothingCountedMeansNothingToSave() throws IOException
	{
		// The blob is nine kilobytes at the cap and the timer runs every hundred
		// ticks for as long as the client is open. Most of those minutes contain
		// no kill, no level and no death.
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(2);
		h.engine.getContext().clearCountersDirty();

		h.gameTicks(300);
		assertFalse("a quiet stretch must not keep rewriting the same value",
			h.engine.getContext().isCountersDirty());

		h.engine.getContext().tally("kill:rat");
		assertTrue("but a kill has to reach the disk",
			h.engine.getContext().isCountersDirty());
	}

	@Test
	public void aSessionShorterThanTheRecordChangesNothing() throws IOException
	{
		// The longest-session record is filed every minute, which would have
		// marked the counters dirty every minute on its own and undone the
		// whole saving. It only counts when today actually beats the mark.
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().noteRecord("session", 180);
		h.engine.getContext().clearCountersDirty();

		for (int minute = 1; minute <= 20; minute++)
		{
			h.engine.getContext().noteRecord("session", minute);
		}
		assertFalse("twenty minutes is not a record when the mark is three hours",
			h.engine.getContext().isCountersDirty());

		h.engine.getContext().noteRecord("session", 181);
		assertTrue("beating it is worth writing",
			h.engine.getContext().isCountersDirty());
	}

	@Test
	public void restoringFromDiskLeavesSomethingWorthWriting() throws IOException
	{
		// A restore MERGES with whatever the session already counted, so what is
		// in memory afterwards is not what is on disk. Skipping that save would
		// lose the merge on a crash.
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().tally("kill:rat");
		h.engine.getContext().clearCountersDirty();

		java.util.Map<String, Integer> saved = new java.util.HashMap<>();
		saved.put("kill:rat", 40);
		h.engine.getContext().restoreCounters(saved, null);

		assertTrue("the merged total only exists in memory until it is written",
			h.engine.getContext().isCountersDirty());
	}
}

package com.follower;

import net.runelite.api.JagexColor;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * The game's packed colour format, unpacked.
 *
 * <p>Sixteen bits: hue in 10-15, saturation in 7-9, luminance in 0-6. Three
 * shifts and three masks, which is exactly the shape of code where an off-by-one
 * produces something that still looks like a colour - the follower comes out
 * slightly the wrong shade and nothing anywhere says why.
 *
 * <p>Everything here is checked against the field layout rather than against
 * remembered values: each case builds a packed colour from known components and
 * asks for them back.
 */
public class HslColorTest
{
	/** Packs the three fields the way the client's model data does. */
	private static short pack(int hue, int saturation, int luminance)
	{
		return (short) ((hue << 10) | (saturation << 7) | luminance);
	}

	@Test
	public void eachFieldComesBackOutOfItsOwnBits()
	{
		short packed = pack(37, 5, 91);

		assertEquals("hue", 37, JagexColor.unpackHue(packed));
		assertEquals("saturation", 5, JagexColor.unpackSaturation(packed));
		assertEquals("luminance", 91, JagexColor.unpackLuminance(packed));
	}

	@Test
	public void theFieldsDoNotBleedIntoEachOther()
	{
		// The failure a wrong mask gives: a neighbouring field's bits leaking
		// in. Each of these is one field at its maximum with the others zero,
		// so anything reading past its own bits picks the extra up.
		short hueOnly = pack(63, 0, 0);
		assertEquals(63, JagexColor.unpackHue(hueOnly));
		assertEquals("saturation read hue's bits", 0, JagexColor.unpackSaturation(hueOnly));
		assertEquals("luminance read hue's bits", 0, JagexColor.unpackLuminance(hueOnly));

		short saturationOnly = pack(0, 7, 0);
		assertEquals(7, JagexColor.unpackSaturation(saturationOnly));
		assertEquals("hue read saturation's bits", 0, JagexColor.unpackHue(saturationOnly));
		assertEquals("luminance read saturation's bits", 0, JagexColor.unpackLuminance(saturationOnly));

		short luminanceOnly = pack(0, 0, 127);
		assertEquals(127, JagexColor.unpackLuminance(luminanceOnly));
		assertEquals("hue read luminance's bits", 0, JagexColor.unpackHue(luminanceOnly));
		assertEquals("saturation read luminance's bits", 0, JagexColor.unpackSaturation(luminanceOnly));
	}

	@Test
	public void aColourWithEveryBitSetStillReadsInRange()
	{
		// The top bit of a packed colour makes the short negative, so an
		// arithmetic shift drags sign bits down into the hue. Masking is what
		// stops that, and this is the value that proves it.
		short allBits = (short) 0xFFFF;

		assertEquals("hue ran past its six bits", 63, JagexColor.unpackHue(allBits));
		assertEquals("saturation ran past its three bits", 7, JagexColor.unpackSaturation(allBits));
		assertEquals("luminance ran past its seven bits", 127, JagexColor.unpackLuminance(allBits));
	}

	@Test
	public void everyFieldCoversItsWholeRangeAndNoMore()
	{
		for (int hue = 0; hue <= 63; hue++)
		{
			assertEquals(hue, JagexColor.unpackHue(pack(hue, 0, 0)));
		}
		for (int saturation = 0; saturation <= 7; saturation++)
		{
			assertEquals(saturation, JagexColor.unpackSaturation(pack(0, saturation, 0)));
		}
		for (int luminance = 0; luminance <= 127; luminance++)
		{
			assertEquals(luminance, JagexColor.unpackLuminance(pack(0, 0, luminance)));
		}
	}

	// ------------------------------------------------------------ the swatch

	@Test
	public void theSwatchStaysInsideTwentyFourBits()
	{
		// It is handed straight to a Swing colour. An alpha byte left in the
		// top would come out as a wrong colour rather than an error.
		for (int hue = 0; hue <= 63; hue += 7)
		{
			for (int saturation = 0; saturation <= 7; saturation++)
			{
				for (int luminance = 0; luminance <= 127; luminance += 13)
				{
					int rgb = HslColor.toRgb(pack(hue, saturation, luminance));
					assertEquals("alpha bits survived in " + hue + "/" + saturation
						+ "/" + luminance, 0, rgb & 0xFF000000);
				}
			}
		}
	}

	@Test
	public void luminanceRunsFromBlackToWhite()
	{
		assertEquals("the darkest colour is black", 0x000000,
			HslColor.toRgb(pack(20, 4, 0)));
		assertEquals("the lightest is white", 0xFFFFFF,
			HslColor.toRgb(pack(20, 4, 127)));
	}

	@Test
	public void noSaturationIsGreyWhateverTheHue()
	{
		// With saturation zero the hue cannot matter. If it does, the
		// conversion has its arguments crossed.
		int first = HslColor.toRgb(pack(0, 0, 64));
		int second = HslColor.toRgb(pack(63, 0, 64));

		assertEquals("hue changed a colour with no saturation in it", first, second);

		int red = (first >> 16) & 0xFF;
		int green = (first >> 8) & 0xFF;
		int blue = first & 0xFF;
		assertTrue("an unsaturated colour is grey, not " + Integer.toHexString(first),
			Math.abs(red - green) <= 1 && Math.abs(green - blue) <= 1);
	}

	@Test
	public void fullSaturationIsNotGrey()
	{
		// The other side of the same check: if saturation were ignored, every
		// swatch in the panel would be a shade of grey.
		int saturated = HslColor.toRgb(pack(0, 7, 64));

		int red = (saturated >> 16) & 0xFF;
		int blue = saturated & 0xFF;
		assertNotEquals("saturation made no difference at all", red, blue);
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * R18: the idle pool swaps by context. Exactly one of the three sets serves
 * in any state - the guards partition them the way the voice eras partition
 * the calendar - so an idle stretch in the Wilderness sounds watchful, one
 * in a crowd sounds like people-watching, and neither leaks anywhere else.
 */
public class IdleContextTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final int WILDERNESS_VARBIT = 5963;

	/** Idles long enough that the 30% flicker has fired whichever pool serves. */
	private Harness idled(java.util.function.Consumer<Harness> context) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		context.accept(h);
		h.gameTicks(400);
		return h;
	}

	@Test
	public void theWildernessIdlesWatchfully() throws IOException
	{
		Harness h = idled(g -> g.game.varbit(WILDERNESS_VARBIT, 1));
		assertFalse("the wilds pool serves here", h.firedBy("idle-chatter-wilds").isEmpty());
		assertTrue(h.firedBy("idle-chatter").isEmpty());
		assertTrue(h.firedBy("idle-chatter-town").isEmpty());
	}

	@Test
	public void aCrowdIdlesAsPeopleWatching() throws IOException
	{
		Harness h = idled(g ->
		{
			for (int i = 0; i < 8; i++)
			{
				g.game.spawnPlayer(1 + i % 3, 1 + i / 3);
			}
		});
		assertFalse("the town pool serves here", h.firedBy("idle-chatter-town").isEmpty());
		assertTrue(h.firedBy("idle-chatter").isEmpty());
		assertTrue(h.firedBy("idle-chatter-wilds").isEmpty());
	}

	@Test
	public void anEmptyFieldIdlesTheOldWay()  throws IOException
	{
		Harness h = idled(g -> { });
		assertFalse("the default pool still serves", h.firedBy("idle-chatter").isEmpty());
		assertTrue(h.firedBy("idle-chatter-wilds").isEmpty());
		assertTrue(h.firedBy("idle-chatter-town").isEmpty());
	}
}

package com.follower;

import java.lang.reflect.Field;
import net.runelite.api.Client;

/**
 * For tests that build a bare FollowerPlugin (no startUp) and drive its event
 * handlers or tick methods: the idle controllers startUp always builds before
 * RuneLite registers the handlers, so the handlers can use them without a
 * null check, as they do in the plugin. Each is built from the plugin's own
 * client, follower and config, whatever the test set, and a controller the
 * test already set is left alone.
 */
final class IdleControllers
{
	private IdleControllers()
	{
	}

	static void fill(FollowerPlugin plugin) throws ReflectiveOperationException
	{
		// A test that set no client gets an idle world's, for the controllers only.
		Client client = get(plugin, "client") != null ? (Client) get(plugin, "client")
			: new FakeGame().client;
		FollowerEntity follower = (FollowerEntity) get(plugin, "follower");
		FollowerConfig config = (FollowerConfig) get(plugin, "config");
		SpeechEngine engine = (SpeechEngine) get(plugin, "speechEngine");
		ErrandController.Hands hands = new ErrandController.Hands()
		{
			@Override
			public void hold(int itemId)
			{
			}

			@Override
			public void release()
			{
			}
		};
		fillIn(plugin, "errands", () -> new ErrandController(client, follower, config,
			event -> { }, null, () -> false, hands));
		fillIn(plugin, "spectate", () -> new SpectateController(client, follower, config,
			() -> engine == null ? null : engine.getContext(), null, event -> { }, disarm -> { }));
		fillIn(plugin, "skilling", () -> new SkillingController(client, follower, config,
			hands, event -> { }, () -> false, () -> false, () -> false));
		fillIn(plugin, "moments", () -> new Moments(client, follower,
			(SkillingController) get(plugin, "skilling"),
			() -> false, () -> false, () -> 0, null,
			() -> false,
			() -> false));
		// With no player tile to read, Will.send falls straight back to
		// follower.stayAt, which is what these fakes give it.
		fillIn(plugin, "will", () -> new Will(client, follower, event -> { }, () -> true));
	}

	private interface Idle
	{
		Object build() throws ReflectiveOperationException;
	}

	private static void fillIn(FollowerPlugin plugin, String name, Idle idle) throws ReflectiveOperationException
	{
		if (get(plugin, name) == null)
		{
			Field field = FollowerPlugin.class.getDeclaredField(name);
			field.setAccessible(true);
			field.set(plugin, idle.build());
		}
	}

	private static Object get(FollowerPlugin plugin, String name) throws ReflectiveOperationException
	{
		Field field = FollowerPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		return field.get(plugin);
	}
}

package com.follower;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The follower runs out of things to say about standing still.
 *
 * <p>The director cannot produce this behaviour. It handles bursts - intensity
 * rising faster than it decays - and an idle afternoon is the opposite shape:
 * a line every forty-five seconds decays completely between lines and sails
 * under the peak forever. Measured, a forty-one minute AFK produced eighty-two
 * lines an hour and no silence longer than two minutes, which is not a
 * companion, it is a dripping tap.
 *
 * <p>Two facts about idleness shaped the mechanism, and both were learned from
 * failures rather than foresight. Idle rules fire on a RISING edge, so a
 * player who is literally motionless hears each of them once - the eighty
 * lines an hour came from POTTERING, little moves between little stops, each
 * stop re-arming the edges. Which is why the stretch must not be ended by
 * movement: the first draft reset it on any step, and would have been a no-op
 * in exactly the session it was built from. Doing something real ends it.
 */
public class IdleTrailOffTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final long GAP = 3_000L;
	private static final long TICK_MS = 600L;

	/**
	 * One chatty idle rule, one reaction, one idle-conditioned occasion, so
	 * all three treatments are observable. The occasion needs a LATER idle
	 * threshold than the chatter - both rising on the same tick would hand the
	 * win to one and consume the other's edge, the first-page bug again - and
	 * a REAL cooldown, because occasions are exempt from the trail-off and
	 * rely on their own pacing. The first draft gave it cooldown zero and it
	 * cheerfully fired seventy-five times an hour, which said nothing about
	 * the engine and everything about writing an occasion with no cooldown.
	 */
	private static final String RULES = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"chatter\", \"group\": \"idle\", \"cooldownMs\": 30000,"
		+ " \"when\": {\"type\": \"idle\", \"ticks\": 10},"
		+ " \"say\": [\"a\",\"b\",\"c\",\"d\",\"e\",\"f\",\"g\",\"h\",\"i\",\"j\","
		+ "\"k\",\"l\",\"m\",\"n\",\"o\",\"p\",\"q\",\"r\",\"s\",\"t\"]},"
		+ "{\"id\": \"reaction\", \"group\": \"reactions\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"x\", \"y\"]},"
		+ "{\"id\": \"big-day\", \"group\": \"memory\", \"cooldownMs\": 3600000,"
		+ " \"occasion\": true,"
		+ " \"when\": {\"type\": \"idle\", \"ticks\": 25}, \"say\": [\"today matters\"]}]}";

	private final AtomicLong clock = new AtomicLong(1_700_000_000_000L);

	private Harness harness() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.engine.setClock(clock::get);
		h.engine.setGlobalCooldownMs(GAP);
		return h;
	}

	private boolean parity;

	/**
	 * What an "idle" session actually is: pottering. Stand for most of a
	 * minute, shuffle a tile, stand again. Every stop re-arms the idle rules'
	 * rising edges, which is how a real player going nowhere in particular
	 * produced a line every forty-five seconds.
	 */
	private void potterFor(Harness h, int ticks)
	{
		for (int i = 0; i < ticks; i++)
		{
			if (i % 80 == 79)
			{
				parity = !parity;
				h.game.at(3200 + (parity ? 1 : 0), 3200, 0);
			}
			clock.addAndGet(TICK_MS);
			h.gameTick();
		}
	}

	private int said(Harness h, String id)
	{
		return h.firedBy(id).size();
	}

	// ------------------------------------------------------------ the shape

	@Test
	public void aPotteredHourStartsChattyAndWindsDown() throws IOException
	{
		// The rule's cooldown alone would allow a line a minute: sixty of
		// them. The trail-off lets the early ones through at full rate and
		// stretches everything after.
		Harness h = harness();
		List<Long> spokenAt = new ArrayList<>();
		h.engine.setSink((text, output, rule, animationId, onSaid) ->
		{
			onSaid.run();
			if (!text.isEmpty())
			{
				spokenAt.add(clock.get());
			}
		});
		potterFor(h, 6000);      // one hour

		assertTrue("the first minutes should still be chatty: only "
			+ spokenAt.size() + " lines all hour", spokenAt.size() >= 5);
		assertTrue("an hour of pottering produced " + spokenAt.size()
			+ " lines, which is the dripping tap this exists to stop",
			spokenAt.size() <= 14);

		// And the gaps have to GROW, or this is a slower drip rather than a
		// wind-down.
		long firstGap = spokenAt.get(1) - spokenAt.get(0);
		long lastGap = spokenAt.get(spokenAt.size() - 1)
			- spokenAt.get(spokenAt.size() - 2);
		assertTrue("gaps should stretch as the stretch wears on: first "
			+ firstGap + "ms, last " + lastGap + "ms", lastGap >= firstGap * 3);
	}

	@Test
	public void doingSomethingRealResetsTheStretch() throws IOException
	{
		Harness h = harness();
		potterFor(h, 3000);      // half an hour: deep in the wind-down
		int wound = said(h, "chatter");

		// A fight. Not a step - steps happen constantly while pottering and
		// must not reset anything.
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_START));

		potterFor(h, 500);       // five minutes afterwards
		assertTrue("after real activity the follower should perk back up: had "
			+ wound + ", now " + said(h, "chatter"),
			said(h, "chatter") >= wound + 2);
	}

	@Test
	public void potteringItselfNeverResetsTheStretch() throws IOException
	{
		// The design error the first draft shipped: moving resets the idle
		// counter, pottering is nothing but little moves, so a movement-based
		// reset makes the trail-off a no-op in exactly the session that
		// motivated it. Half an hour of pottering must stay wound down.
		Harness h = harness();
		potterFor(h, 1500);
		int atFifteen = said(h, "chatter");
		potterFor(h, 1500);

		assertTrue("the second quarter hour should be much quieter than the"
			+ " first: " + atFifteen + " then " + said(h, "chatter"),
			said(h, "chatter") - atFifteen <= atFifteen / 2);
	}

	@Test
	public void reactionsAreNeverPartOfTheChatter() throws IOException
	{
		// Deep in the wind-down, the world still gets answered. An examine is
		// an event; responding to it is not talking for the sake of it.
		Harness h = harness();
		potterFor(h, 3000);

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertEquals("a reaction must cut straight through the trail-off",
			1, said(h, "reaction"));
	}

	@Test
	public void anIdleConditionedOccasionIsExempt() throws IOException
	{
		// The anniversary fires off the idle condition - it waits for a calm
		// moment on the right day. Winding it down because the player went AFK
		// on their anniversary would be the settling-damper bug in new clothes.
		Harness h = harness();
		potterFor(h, 3000);

		assertEquals("an occasion says its piece whatever the stretch looks like",
			1, said(h, "big-day"));
	}

	@Test
	public void theHarnessDefaultOfNoGapDisablesTheTrailOff() throws IOException
	{
		// Every window in the trail-off is a multiple of the base gap, so the
		// unpaced harness the rest of the suite runs under is untouched - the
		// same design as the director, for the same reason.
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.engine.setClock(clock::get);        // paced clock, no gap
		potterFor(h, 3000);

		assertTrue("with no gap set, the rule's own cooldown is the only pacing",
			said(h, "chatter") >= 20);
	}

	@Test
	public void theTranscriptSeesTheWindDown() throws IOException
	{
		Harness h = harness();
		List<String> reasons = new ArrayList<>();
		h.engine.setOnSuppressed((rule, why) -> reasons.add(why));

		potterFor(h, 3000);
		assertFalse("a wound-down stretch must be visible in the transcript,"
			+ " or a quiet follower and a throttled one look identical",
			reasons.stream().noneMatch("trailing"::equals));
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Ignored overtures rest.
 *
 * <p>A transcript showed fifteen outings asked into one AFK afternoon: each
 * question politely expired, and each was politely re-asked at the next
 * cooldown, which added up to nagging. Now a question that lapses unanswered
 * earns a two-hour pause, two ignored in one session end the asking, and
 * answering anything clears the ledger - a polite companion drops a hint
 * twice and lets it go. Wishes rest more gently: ninety minutes after one
 * lapses unfulfilled, and a granted wish invites the next freely.
 */
public class IgnoredOverturesTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final String RULES = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"asker\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"asks\": \"want-outing\","
		+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"a word?\"]},"
		+ "{\"id\": \"wisher\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"wish\": {\"what\": \"feather\", \"minutes\": 1, \"items\": [314]},"
		+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"a feather, maybe\"]}]}";

	private Harness fresh() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.gameTicks(1);
		return h;
	}

	private void ask(Harness h)
	{
		// A player worth asking is one who is present: long tick jumps in
		// these tests would otherwise trip the attention damper (R15), which
		// composes with this back-off and holds everything, askers included.
		h.game.cameraMoved();
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
	}

	@Test
	public void anIgnoredQuestionIsNotFollowedByAnotherSoon() throws IOException
	{
		Harness h = fresh();
		ask(h);
		assertEquals(1, h.firedBy("asker").size());
		assertEquals("want-outing", h.engine.getContext().getAskedTree());

		// Nobody answers; the question lapses.
		h.gameTicks(201);
		assertEquals("", h.engine.getContext().getAskedTree());

		ask(h);
		assertEquals("an ignored question earns a pause, not a repeat",
			1, h.firedBy("asker").size());

		// Two hours later the pause is over (one ignored is forgivable).
		h.gameTicks(12_001);
		ask(h);
		assertEquals("the pause ends", 2, h.firedBy("asker").size());
	}

	@Test
	public void twoIgnoredQuestionsEndTheAskingForTheSession() throws IOException
	{
		Harness h = fresh();
		ask(h);
		h.gameTicks(201);              // ignored once
		h.gameTicks(12_001);           // pause served
		ask(h);
		h.gameTicks(201);              // ignored twice
		assertEquals(2, h.firedBy("asker").size());

		h.gameTicks(12_001);           // even with the pause long over
		ask(h);
		assertEquals("twice ignored is the answer; the asking stops",
			2, h.firedBy("asker").size());
	}

	@Test
	public void answeringClearsTheLedger() throws IOException
	{
		Harness h = fresh();
		ask(h);
		h.gameTicks(201);              // ignored once; two-hour pause armed

		// The player answers something - the next question, say, opened
		// through Talk-to. Engagement is what the back-off was waiting for.
		h.answers("yes", "want-outing");

		ask(h);
		assertEquals("answering forgives the ignored one and lifts the pause",
			2, h.firedBy("asker").size());
	}

}

package com.follower;

import java.io.IOException;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.NPC;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The incident, with its particulars. "How close that was" is a hint; "how
 * close that was with the Hill Giant, 6 hitpoints left, in Edgeville, three
 * days ago" is a memory two people share, and the point of keeping one.
 */
public class IncidentTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static Map<Integer, String> names()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(12342, "Edgeville");
		names.put(12853, "Varrock: west bank, centre and palace");
		return names;
	}

	private static String said(Harness h, String ruleId)
	{
		List<Harness.Spoken> fired = h.firedBy(ruleId);
		assertFalse(ruleId + " never fired", fired.isEmpty());
		return fired.get(0).text;
	}

	@Test
	public void theCloseCallIsFiledWithWhoAndHowClose() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().setRegionNames(names());
		h.game.regions(12342).at(3090, 3490, 0).hitpoints(6, 99);
		NPC giant = h.game.spawnNpc(2098, "Hill Giant", 28);
		h.game.fighting(giant);
		h.gameTicks(3);
		TriggerContext context = h.engine.getContext();
		assertTrue("the close call was filed", context.hasIncident());
		assertEquals("close-call", context.getIncidentKey());
		assertEquals("the Hill Giant leaving you on 6 hitpoints",
			context.getIncidentPhrase());
		assertEquals(6, context.getIncidentHp());
		assertEquals("Hill Giant", context.getIncidentWho());
		assertEquals(12342, context.getIncidentWhere());
		assertEquals(" in Edgeville", context.getMemoryWhere());
	}

	private static final String QUEST_MEMORY = "{\"version\": 1, \"rules\": [{\"id\": \"quest-memory\","
		+ " \"group\": \"memory\", \"cooldownMs\": 0,"
		+ " \"remember\": {\"key\": \"the-quest\", \"as\": \"the sheep that wouldn't be sheared\"},"
		+ " \"when\": {\"type\": \"questComplete\"}, \"say\": [\"Filed.\"]}]}";

	/** A memory filed some ticks after a ram fight ended. */
	private String whoAfter(int ticksSinceTheFight) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), QUEST_MEMORY);
		h.game.regions(12342).at(3090, 3490, 0);
		NPC ram = h.game.spawnNpc(2800, "Ram", 2);
		h.game.fighting(ram);
		h.gameTicks(3);
		h.game.fighting(null);
		h.gameTicks(ticksSinceTheFight);
		h.dispatch(TriggerEvent.questComplete("Sheep Shearer"));
		assertEquals("the-quest", h.engine.getContext().getIncidentKey());
		return h.engine.getContext().getIncidentWho();
	}

	@Test
	public void aMemoryIsAboutTheFightOnlyWhileItIsGoingOn() throws IOException
	{
		// QA, 15 Oct: the combat target is never cleared, so a quest finished
		// long after a ram fight was filed with the Ram as its "who", and the
		// next Ram in sight brought up a quest it had nothing to do with.
		assertEquals("a fight just over is the memory's", "Ram", whoAfter(2));
		assertEquals("one long over is not", "", whoAfter(60));
	}

	@Test
	public void aDeathLongAfterAFightIsNotPutDownToIt() throws IOException
	{
		// The same stale target in the shipped death memory's own words:
		// "your death to the {foe}".
		for (int since : new int[]{2, 60})
		{
			Harness h = new Harness(folder.newFolder().toPath());
			h.game.regions(12342).at(3090, 3490, 0);
			NPC ram = h.game.spawnNpc(2800, "Ram", 2);
			h.game.fighting(ram);
			h.gameTicks(3);
			h.game.fighting(null);
			h.gameTicks(since);
			h.dispatch(TriggerEvent.death());
			TriggerContext context = h.engine.getContext();
			assertEquals("the-death", context.getIncidentKey());
			if (since == 2)
			{
				assertEquals("your death to the ram", context.getIncidentPhrase().toLowerCase());
				assertEquals("Ram", context.getIncidentWho());
			}
			else
			{
				assertEquals("the time you died", context.getIncidentPhrase());
				assertEquals("", context.getIncidentWho());
			}
		}
	}

	@Test
	public void whatIsAlreadyTrueAtLoginIsNotFiled() throws IOException
	{
		// Logging back in mid-fight at six hitpoints - after a disconnect,
		// say - is not a close call the follower saw. Just after login the
		// engine primes its edges so standing state reads as already true,
		// and a memory filed then would be about nothing that happened.
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.regions(12342).at(3090, 3490, 0).hitpoints(6, 99);
		NPC giant = h.game.spawnNpc(2098, "Hill Giant", 28);
		h.game.fighting(giant);
		h.engine.primeEdgesOnNextTick();
		h.gameTicks(3);
		assertFalse(h.engine.getContext().hasIncident());
	}

	@Test
	public void aPlaceholderWithNothingToSayFilesThePlainForm() throws IOException
	{
		// A death with no combat target and no named place on record: "your
		// death to the " would be a hole, and so would "your death ", so the
		// plain form is filed instead.
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.dispatch(TriggerEvent.death());
		TriggerContext context = h.engine.getContext();
		assertEquals("the-death", context.getIncidentKey());
		assertEquals("the time you died", context.getIncidentPhrase());
		assertEquals("", context.getIncidentWho());
	}

	@Test
	public void thatsThreeIsSaidOnTheThirdDeathOnly() throws IOException
	{
		// Dialogue check, 14 Oct: "That's three" was said from the fourth
		// death on - the death is filed after its line is chosen, so the
		// count read was one behind. It has the third to itself now.
		//
		// QA, 15 Oct: and it was never heard. It waited 10-16 ticks, and the
		// game's "Oh dear, you are dead!" a few ticks after the death let the
		// chat death line speak first, so the count was lost in the gap. Run
		// the way the game runs it: the default gap on a game clock, and the
		// message five ticks behind the death.
		Harness h = new Harness(folder.newFolder().toPath());
		long[] ms = {1_000_000L};
		h.engine.setClock(() -> ms[0]);
		h.engine.setGlobalCooldownMs(Chattiness.OCCASIONAL.getGapMs());
		h.gameTicks(1);
		for (int death = 1; death <= 4; death++)
		{
			int deathLinesBefore = h.firedBy("death").size();
			h.dispatch(TriggerEvent.death());
			for (int tick = 0; tick < 400; tick++)
			{
				ms[0] += 600;
				h.gameTick();
				if (tick == 4)
				{
					h.dispatch(TriggerEvent.chat("Oh dear, you are dead!",
						net.runelite.api.ChatMessageType.GAMEMESSAGE.getType(), ""));
				}
			}
			if (death == 2)
			{
				assertTrue("nothing to count yet", h.firedBy("recall-death-third").isEmpty());
			}
			if (death == 3)
			{
				assertEquals("said on the third", 1, h.firedBy("recall-death-third").size());
			}
			if (death >= 3)
			{
				assertEquals("and the chat death line does not talk over the count on death " + death,
					deathLinesBefore, h.firedBy("death").size());
			}
		}
		assertEquals("and not again on the fourth", 1, h.firedBy("recall-death-third").size());
		assertEquals("which has the other lines", 1, h.firedBy("recall-death-again").size());
	}

	@Test
	public void theCountBeatsTheLifetimeTally() throws IOException
	{
		// QA, 15 Oct: past ten lifetime deaths, deaths-many (same priority,
		// earlier in the file) took every pass from recall-death-again.
		// A game clock, so the cooldowns run out between deaths as they would.
		Harness h = new Harness(folder.newFolder().toPath());
		long[] ms = {1_000_000L};
		h.engine.setClock(() -> ms[0]);
		h.engine.getContext().restoreCounters(Collections.singletonMap("deaths", 12), null);
		h.gameTicks(1);
		for (int death = 1; death <= 4; death++)
		{
			h.engine.getContext().tallyBoth("deaths");
			h.dispatch(TriggerEvent.death());
			for (int tick = 0; tick < 400; tick++)
			{
				ms[0] += 600;
				h.gameTick();
			}
		}
		assertEquals(1, h.firedBy("recall-death-third").size());
		assertEquals(1, h.firedBy("recall-death-again").size());
	}

	@Test
	public void aDropIsRememberedByName() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.dispatch(TriggerEvent.loot(2_000_000, "Abyssal whip"));
		assertEquals("the Abyssal whip that dropped", h.engine.getContext().getIncidentPhrase());
	}

	@Test
	public void turningReminiscingOffQuietensTheTalkNotTheMemory() throws IOException
	{
		// The setting promises it "does not stop it remembering", but the
		// memory rules sit in its group and silencing the group stopped them
		// filing. Silenced by group or by id, the memory is still kept.
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.setDisabledGroups(Collections.singleton("memory"));
		h.gameTicks(1);
		h.dispatch(TriggerEvent.loot(2_000_000, "Abyssal whip"));
		assertEquals("the Abyssal whip that dropped", h.engine.getContext().getIncidentPhrase());

		Harness byId = new Harness(folder.newFolder().toPath());
		byId.engine.setDisabledGroups(Collections.singleton("memory-death"));
		byId.gameTicks(1);
		byId.dispatch(TriggerEvent.death());
		assertEquals("the time you died", byId.engine.getContext().getIncidentPhrase());
		assertTrue("and silenced means silent", byId.firedBy("memory-death").isEmpty());
	}

	@Test
	public void whenAndWhereReadAsSomebodyWouldSayThem()
	{
		TriggerContext context = new TriggerContext(new FakeGame().client);
		assertEquals("", context.getMemoryWhen(5_000L));
		context.setRegionNames(names());
		long now = 10_000_000_000L;
		context.noteIncident("the-boss", "the General Graardor going down", "General Graardor", now - 30_000L);
		assertEquals("just now", context.getMemoryWhen(now));
		context.noteIncident("the-boss", "the General Graardor going down", "General Graardor",
			now - 3L * 24 * 60 * 60_000L);
		assertEquals("three days ago", context.getMemoryWhen(now));
		assertEquals("a repeat keeps the count", 2, context.getIncidentCount());
		context.restoreIncident("the-boss", "the size of that thing", 1, 0, 0L, "");
		assertEquals("an old record with no date", "a while ago", context.getMemoryWhen(now));
		assertEquals("Varrock", context.placeName(12853));
		assertEquals("", context.placeName(999));
	}

	@Test
	public void aPlaceIsSaidAsItsNameNotItsDescription() throws IOException
	{
		// QA, 15 Oct: "in The God Wars Dungeon", "in Lumbridge town and
		// castle". The Locations notes describe; a line wants the name.
		RuleLoader rules = new RuleLoader(new com.google.gson.Gson());
		rules.initialise(folder.newFolder().toPath());
		TriggerContext context = new TriggerContext(new FakeGame().client);
		context.setRegionNames(rules.getRegionNames());
		Map<String, String> said = new java.util.TreeMap<>();
		for (Map.Entry<Integer, String> place : rules.getRegionNames().entrySet())
		{
			context.restoreIncident("the-boss", "the size of that thing", 1, place.getKey(), 0L, "");
			said.put(place.getValue(), context.getMemoryWhere());
		}
		assertEquals(" in the God Wars Dungeon", said.get("The God Wars Dungeon"));
		assertEquals(" in Lumbridge", said.get("Lumbridge town and castle"));
		assertEquals(" in Seers' Village", said.get("Seers' Village and Camelot castle"));
		assertEquals(" in East Ardougne", said.get("East Ardougne and its market"));
		assertEquals(" in Castle Wars", said.get("Castle Wars lobby area"));
		assertEquals(" in the Grand Exchange", said.get("The Grand Exchange plaza"));
		assertEquals(" in the Barrows", said.get("The Barrows mounds"));
		for (String where : said.values())
		{
			assertFalse("no capital The mid-sentence: " + where, where.contains(" The "));
			assertFalse("no description: " + where, where.contains(" and "));
		}
	}

	/**
	 * QA, 15 Oct (probe P3): a memory is filed where it happens, so the place
	 * recall could say "Here again, and I've not forgotten the orb breaking"
	 * twelve seconds after the orb broke, to somebody who never left.
	 */
	@Test
	public void aMemoryIsNotHereUntilYouComeBackToIt() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.regions(12342).at(3090, 3490, 0);
		h.gameTicks(1);
		h.engine.getContext().noteIncident("close-call",
			"how close that was with the Hill Giant", "Hill Giant", System.currentTimeMillis());
		h.gameTicks(200);
		assertTrue("not on the visit it happened", h.firedBy("recall-here").isEmpty());
		assertFalse(h.engine.getContext().isAtTheIncident());

		h.game.regions(12850).at(3222, 3218, 0);
		h.gameTicks(2);
		h.game.regions(12342).at(3090, 3490, 0);
		h.gameTicks(1);
		assertTrue("back again", h.engine.getContext().isAtTheIncident());
	}

	@Test
	public void theRecallLinesSayTheParticulars() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().setRegionNames(names());
		h.game.regions(12342).at(3090, 3490, 0);
		h.gameTicks(1);
		h.engine.getContext().noteIncident("close-call",
			"how close that was with the Hill Giant", "Hill Giant",
			System.currentTimeMillis() - 3L * 24 * 60 * 60_000L);
		// Away and back: the return is the rising edge the place recall fires on.
		h.game.regions(12850).at(3222, 3218, 0);
		h.gameTicks(2);
		h.game.regions(12342).at(3090, 3490, 0);
		// Both recalls are a coin toss each tick after a short delay, and the
		// chance draws from a random a test cannot seed, so they are given
		// long enough that missing every toss is not a thing that happens.
		// Twelve and eight ticks missed about one run in sixteen.
		h.gameTicks(40);
		String line = said(h, "recall-here");
		assertTrue("the memory in full: " + line, line.contains("Hill Giant"));

		// The giant back in sight.
		Harness foe = new Harness(folder.newFolder().toPath());
		foe.engine.getContext().setRegionNames(names());
		foe.gameTicks(1);
		foe.engine.getContext().noteIncident("close-call",
			"how close that was with the Hill Giant", "Hill Giant",
			System.currentTimeMillis() - 3L * 24 * 60 * 60_000L);
		NPC giant = foe.game.spawnNpc(2098, "Hill Giant", 28);
		foe.game.moveNpc(giant, foe.game.player.getWorldLocation().getX() + 4,
			foe.game.player.getWorldLocation().getY(), 0);
		foe.gameTicks(40);
		String seen = said(foe, "recall-foe");
		assertTrue("names the thing or the memory: " + seen,
			seen.contains("Hill Giant"));
		assertFalse("no placeholder printed literally: " + seen, seen.contains("{"));
	}

	@Test
	public void everyRememberHasAPlainFormForWhenTheParticularsAreMissing() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		for (SpeechRule rule : h.loader.getRules())
		{
			if (rule.remember == null || rule.remember.as == null || rule.remember.as.indexOf('{') < 0)
			{
				continue;
			}
			assertTrue(rule.id + " fills its memory in from placeholders and needs a plain form",
				rule.remember.plain != null && !rule.remember.plain.isEmpty());
		}
		assertEquals(Collections.emptyList(), h.firedBy("nothing"));
	}
}

package com.follower;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Every new system, interrupted while it is holding something.
 *
 * <p>All the interesting bugs in this plugin have been of one shape: a piece of
 * state outliving the thing that owned it. A held floor surviving the rule that
 * took it. An edge surviving the reload that replaced the rule. A want
 * surviving the world hop that made it unreachable. Each of the systems added
 * this week holds state across time, so each of them can fail the same way.
 */
public class InterruptedMidFlightTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final long GAP = 3_000L;
	private final AtomicLong clock = new AtomicLong(1_700_000_000_000L);

	private Harness harness(String rules) throws IOException
	{
		Harness h = rules == null
			? new Harness(folder.newFolder().toPath())
			: new Harness(folder.newFolder().toPath(), rules);
		h.engine.setClock(clock::get);
		h.engine.setGlobalCooldownMs(GAP);
		return h;
	}

	private void rest(Harness h)
	{
		SpeechRule filler = new SpeechRule();
		filler.id = "filler";
		filler.group = "reactions";
		for (int i = 0; i < 4; i++)
		{
			h.engine.getDirector().noteSpoke(filler, clock.get());
		}
		assertTrue(h.engine.getDirector().isRelaxing(clock.get()));
	}

	// ------------------------------------------------- the mute, mid-everything

	@Test
	public void unmutingDoesNotLeaveTheFollowerOwingASilence() throws IOException
	{
		// The mute is checked after the floor has already been taken, so a
		// muted rule that wins can hold the floor for a line nobody heard. It
		// costs nothing while the mute is on - everything is silent anyway -
		// but the residue must not outlive it.
		Harness h = harness("{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"big\", \"group\": \"t\", \"cooldownMs\": 0, \"hushMs\": 8000,"
			+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"listen\"]},"
			+ "{\"id\": \"small\", \"group\": \"t\", \"cooldownMs\": 0,"
			+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"unrelated\"]}]}");
		h.gameTicks(1);

		h.engine.setMuted(true);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertTrue("muted, so nothing came out", h.spoken.isEmpty());

		h.engine.setMuted(false);
		clock.addAndGet(9_000L);            // past any floor the muted win took
		h.gameTicks(1);
		h.dispatch(TriggerEvent.death());
		assertFalse("un-muting has to give the follower its voice back",
			h.firedBy("small").isEmpty());
	}

	// ------------------------------------------------ the reload, mid-anything

	@Test
	public void aReloadMidRestDoesNotStrandTheFollower() throws IOException
	{
		// A reload replaces every rule object. The director survives it, being
		// engine state rather than rule state - so a reload during a rest must
		// not extend it, and the floor must be released, or editing a phrase
		// silences the file until a timer nobody can see runs out.
		Harness h = harness(null);
		h.gameTicks(1);
		rest(h);

		long restingUntil = clock.get() + h.engine.getDirector().relaxRemainingMs(clock.get());
		h.engine.clearFloor();
		h.engine.primeEdgesOnNextTick();

		clock.set(restingUntil + 1_000L);
		assertFalse("the rest outlived its own window",
			h.engine.getDirector().isRelaxing(clock.get()));
	}

	@Test
	public void aReloadDoesNotUnsayAOneTimeLine() throws IOException
	{
		// Already covered for the file-watch path; this is the same claim for
		// the object identity itself, which is what actually changes.
		String rules = "{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"hello\", \"group\": \"t\", \"cooldownMs\": 0, \"once\": true,"
			+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"first time\"]}]}";
		Harness h = harness(rules);
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertEquals(1, h.firedBy("hello").size());

		Path file = h.getScratch().resolve(RuleLoader.FILE_NAME);
		Files.write(file, rules.replace("first time", "first time, honest")
			.getBytes(StandardCharsets.UTF_8));
		Files.setLastModifiedTime(file, java.nio.file.attribute.FileTime
			.fromMillis(System.currentTimeMillis() + 5_000L));
		assertTrue(h.loader.reloadIfChanged());

		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertEquals("a reload must not hand back a spent first",
			1, h.firedBy("hello").size());
	}

	// ------------------------------------------------- the world hop, mid-bag

	@Test
	public void aWorldHopKeepsTheBagAndTheWindowAndReleasesTheEdges()
		throws IOException
	{
		// Two things had to change for this to test anything at all.
		//
		// It ran once, and a re-dealt six-line bag avoids three already-said
		// lines about one time in twenty, so a single attempt was a coin toss a
		// mutation sweep walked straight past.
		//
		// And more interestingly, the corpus window was covering for the bag.
		// recentLineSet survives a scene change, so it still held the three
		// lines just said, and pickPhrase prefers what has not been heard - a
		// freshly dealt bag produced the same three remaining lines a preserved
		// one would have. The systems defend each other, which is good, and
		// makes each of them individually untestable, which is not. The
		// flusher rule below moves the window on so the bag is the only thing
		// left deciding.
		for (int attempt = 0; attempt < 20; attempt++)
		{
			Harness h = harness("{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"t\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"examined\"},"
				+ " \"say\": [\"a\", \"b\", \"c\", \"d\", \"e\", \"f\"]},"
				+ "{\"id\": \"flush\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"playerDeath\"},"
				+ " \"say\": [\"f1\", \"f2\", \"f3\", \"f4\", \"f5\", \"f6\","
				+ " \"f7\", \"f8\", \"f9\", \"f10\", \"f11\", \"f12\"]}]}");
			h.engine.setGlobalCooldownMs(0L);
			h.gameTicks(1);

			java.util.Set<String> before = new java.util.HashSet<>();
			for (int i = 0; i < 3; i++)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
				h.gameTicks(1);
			}
			for (Harness.Spoken s : h.spoken)
			{
				before.add(s.text);
			}
			assertEquals(3, before.size());

			// Twelve other lines, which is exactly the window, so nothing the
			// rule under test has said is still remembered corpus-wide.
			for (int i = 0; i < 12; i++)
			{
				h.dispatch(TriggerEvent.death());
				h.gameTicks(1);
			}

			h.engine.resetForNewScene();
			h.clear();
			h.gameTicks(1);

			for (int i = 0; i < 3; i++)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
				h.gameTicks(1);
			}
			for (Harness.Spoken s : h.spoken)
			{
				if (s.rule != null && "t".equals(s.rule.id))
				{
					assertTrue("the hop re-dealt \"" + s.text + "\", which this bag"
						+ " had already spent", before.add(s.text));
				}
			}
			assertEquals("all six should still have come out across the hop",
				6, before.size());
		}
	}

	// ------------------------------------ the settings, changed mid-everything

	@Test
	public void turningTheChattinessDownMidRestDoesNotStretchIt() throws IOException
	{
		// The rest is an absolute deadline and the decay is a rate. Changing the
		// gap changes the rate, and must not retroactively move a deadline
		// already set - a player switching to Quiet mid-rest should not be
		// punished with four times the silence they asked for.
		Harness h = harness(null);
		h.gameTicks(1);
		rest(h);
		long remaining = h.engine.getDirector().relaxRemainingMs(clock.get());

		h.engine.setGlobalCooldownMs(12_000L);      // Quiet
		assertEquals("the rest already running must not move",
			remaining, h.engine.getDirector().relaxRemainingMs(clock.get()));
	}

	@Test
	public void aPluginToggleClearsEverythingTheFollowerWasHolding() throws IOException
	{
		// reset() is the "start over" path. Everything with a deadline has to go
		// with it, or switching the plugin off and on again - the first thing
		// anybody tries - leaves the follower serving out a sentence.
		Harness h = harness(null);
		h.gameTicks(1);
		rest(h);

		h.engine.reset();

		assertFalse("a toggle must not leave the follower resting",
			h.engine.getDirector().isRelaxing(clock.get()));
		assertEquals("and must not leave a stale gap", 0L, h.engine.getLastSpokeMs());

		SpeechRule any = new SpeechRule();
		any.id = "x";
		any.group = "reactions";
		assertNull("nothing should be held after a toggle",
			h.engine.getDirector().blocks(any, clock.get()));
	}

	// ------------------------------------------------- the delay, interrupted

	@Test
	public void aDelayedLineDoesNotSurviveAToggle() throws IOException
	{
		// A pending firing holds a rule and an event across ticks. If the queue
		// outlived a reset, the follower would speak about something from
		// before it was switched off.
		Harness h = harness("{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"slow\", \"group\": \"t\", \"cooldownMs\": 0, \"delayTicks\": 5,"
			+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"eventually\"]}]}");
		h.gameTicks(1);

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		h.gameTicks(2);
		assertTrue("still pending", h.spoken.isEmpty());

		h.engine.reset();
		h.gameTicks(10);
		assertTrue("a line queued before the reset came out after it",
			h.spoken.isEmpty());
	}

	@Test
	public void anAnnouncementWaitsForTheBaselineInsteadOfRacingIt() throws IOException
	{
		// A world hop clears every rule's edges and then wants to say one
		// thing about the hop. Both obvious ways to arrange that are wrong,
		// and the plugin shipped each of them in turn.
		//
		// Raise it INSIDE the prime window and the winner is discarded along
		// with everything else: the rule is silently dead.
		//
		// Raise it just BEFORE arming the window and the cleared edges all
		// rise on that same pass - every piece of worn gear, the region
		// underfoot - and since one event has one winner and those rules
		// outrank it, the follower remarks on your gear as though you had
		// just put it on and says nothing about the hop. Play report, word
		// for word.
		//
		// So it waits for the baseline, which is what dispatchAfterPriming is.
		String rules = "{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"hop\", \"group\": \"t\", \"priority\": 26, \"cooldownMs\": 0,"
			+ " \"when\": {\"type\": \"worldHop\"}, \"say\": [\"a new world\"]},"
			// Stands in for the 62 gear rules, all of which outrank the hop.
			+ "{\"id\": \"gear\", \"group\": \"t\", \"priority\": 35, \"cooldownMs\": 0,"
			+ " \"when\": {\"type\": \"always\"}, \"say\": [\"nice hat\"]}]}";

		Harness swallowed = harness(rules);
		swallowed.gameTicks(1);
		swallowed.engine.primeEdgesOnNextTick();
		swallowed.dispatch(TriggerEvent.worldHop(302));
		assertTrue("raised inside the window, it is discarded like everything else",
			swallowed.firedBy("hop").isEmpty());

		Harness held = harness(rules);
		held.gameTicks(1);
		// The scene changed: every edge is cleared, exactly as a hop does.
		held.engine.resetForNewScene();
		held.engine.primeEdgesOnNextTick();
		// The stand-in speaks on the setup tick too, being unconditional; only
		// what it does from the hop onwards is the question.
		held.clear();
		held.engine.dispatchAfterPriming(TriggerEvent.worldHop(302));

		assertTrue("it must not speak before the baseline is taken",
			held.firedBy("hop").isEmpty());

		held.gameTicks(6);

		assertFalse("the announcement never arrived after the window drained",
			held.firedBy("hop").isEmpty());
		assertTrue("the re-risen gear rule stole the announcement's pass",
			held.firedBy("gear").isEmpty());
	}
}

