/**
 * The upgrade path of phrases.json and dialogs.json, against the loaders as
 * they stood before {@link MergingLoader} (kept in {@code speech.before}).
 *
 * <p>Seeded random scenarios start each loader on a data folder like the ones
 * players arrive with: no file, 1.4.0's file, the shipped file, edited copies
 * (lines and rules deleted, added, reordered, switched off, renamed or
 * duplicated, junk entries, the "removed" list, nicknames narrowed or widened,
 * places and nodes edited), or a file that is empty, cut short, null, of
 * another version, or a folder; beside a merge record that is absent, 1.4.0's,
 * an edited one, corrupt, or a folder; and now and then a data folder that
 * cannot be made. Each is started twice, with an editor-style rewrite, a poll
 * and a reload between.
 *
 * <p>Everything a player or the client log could see must match: every file
 * left in the folder (the stamp without its clock time), the status line and
 * its problems, the rules in order with group and priority, nicknames, place
 * and boss names, which flood events are listened for, the trees, and every
 * log line with its level, logger, text and exception.
 */
public class LoaderDiffTest
{
	/** Scenarios per file; {@code -Dloaderdiff.scenarios=N} for a longer run. */
	private static final int SCENARIOS = Integer.getInteger("loaderdiff.scenarios", 400);

	private static final Gson PRETTY = new GsonBuilder().setPrettyPrinting().disableHtmlEscaping().create();

	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private final ListAppender<ILoggingEvent> logged = new ListAppender<>();
	private Logger speech;
	private Level level;
	private boolean additive;

	@Before
	public void listen()
	{
		speech = (Logger) LoggerFactory.getLogger("com.follower");
		level = speech.getLevel();
		additive = speech.isAdditive();
		speech.setLevel(Level.DEBUG);
		speech.setAdditive(false);
		logged.start();
		speech.addAppender(logged);
	}

	@After
	public void stopListening()
	{
		speech.detachAppender(logged);
		speech.setLevel(level);
		speech.setAdditive(additive);
	}

	/** One loader, before or now, as the scenarios drive it. */
	private static final class Driven
	{
		final BiConsumer<Path, Boolean> initialise;
		final BooleanSupplier reloadIfChanged;
		final Runnable reload;
		final Supplier<String> state;

		Driven(BiConsumer<Path, Boolean> initialise, BooleanSupplier reloadIfChanged, Runnable reload,
			Supplier<String> state)
		{
			this.initialise = initialise;
			this.reloadIfChanged = reloadIfChanged;
			this.reload = reload;
			this.state = state;
		}
	}

	/** One of the two files: its names, its shipped copies, how it is edited and loaded. */
	private static final class Kind
	{
		final String fileName;
		final String baseName;
		final String list;
		final JsonObject bundled;
		final JsonObject seen;
		final BiFunction<JsonObject, Random, JsonObject> mutate;
		final Supplier<Driven> before;
		final Supplier<Driven> now;

		Kind(String fileName, String baseName, String list, String seen,
			BiFunction<JsonObject, Random, JsonObject> mutate, Supplier<Driven> before, Supplier<Driven> now)
			throws IOException
		{
			this.fileName = fileName;
			this.baseName = baseName;
			this.list = list;
			this.bundled = resource("/com/follower/default-" + fileName);
			this.seen = resource(seen);
			this.mutate = mutate;
			this.before = before;
			this.now = now;
		}
	}

	@Test
	public void phrasesUpgradeAsBefore() throws IOException
	{
		check(new Kind(RuleLoader.FILE_NAME, RuleLoader.BASE_FILE, "rules", RuleLoader.UNRECORDED_BASE,
			LoaderDiffTest::mutateRules,
			() ->
			{
				BeforeRuleLoader loader = new BeforeRuleLoader(new Gson());
				return new Driven(loader::initialise, loader::reloadIfChanged, loader::reload,
					() -> rules(loader.getStatus(), loader.getErrors(), loader.getRules(),
						loader.getRegionNames(), loader.getBossNames(), loader::listensFor,
						loader.isVarbitEventRules(), loader.getFile()));
			},
			() ->
			{
				RuleLoader loader = new RuleLoader(new Gson());
				return new Driven(loader::initialise, loader::reloadIfChanged, loader::reload,
					() -> rules(loader.getStatus(), loader.getErrors(), loader.getRules(),
						loader.getRegionNames(), loader.getBossNames(), loader::listensFor,
						loader.isVarbitEventRules(), loader.getFile()));
			}));
	}

	@Test
	public void dialogsUpgradeAsBefore() throws IOException
	{
		check(new Kind(DialogLoader.FILE_NAME, DialogLoader.BASE_FILE, "trees", DialogLoader.UNRECORDED_BASE,
			LoaderDiffTest::mutateDialogs,
			() ->
			{
				BeforeDialogLoader loader = new BeforeDialogLoader(new Gson());
				return new Driven(loader::initialise, loader::reloadIfChanged, loader::reload,
					() -> dialogs(loader.getStatus(), loader.getErrors(), loader.getTrees(), loader.get("greeting"),
						loader.getFile()));
			},
			() ->
			{
				DialogLoader loader = new DialogLoader(new Gson());
				return new Driven(loader::initialise, loader::reloadIfChanged, loader::reload,
					() -> dialogs(loader.getStatus(), loader.getErrors(), loader.getTrees(), loader.get("greeting"),
						loader.getFile()));
			}));
	}

	/**
	 * The 1.4.0 files a merge with no record falls back on ship whole: the
	 * new loaders read an empty one as "no base" where the old rules loader
	 * gave up on the merge, and that can only differ if they do not.
	 */
	@Test
	public void theUnrecordedBasesShip() throws IOException
	{
		assertTrue(resource(RuleLoader.UNRECORDED_BASE).get("rules").getAsJsonArray().size() > 0);
		assertTrue(resource(DialogLoader.UNRECORDED_BASE).get("trees").getAsJsonArray().size() > 0);
	}

	private void check(Kind kind) throws IOException
	{
		Path dir = folder.newFolder(kind.list).toPath();
		for (int seed = 0; seed < SCENARIOS; seed++)
		{
			String before = scenario(dir, seed, kind, kind.before);
			String now = scenario(dir, seed, kind, kind.now);
			assertEquals(kind.fileName + " scenario " + seed, before, now);
		}
	}

	/** Runs one seeded scenario in an emptied {@code dir} and says what it left. */
	private String scenario(Path dir, int seed, Kind kind, Supplier<Driven> loaders) throws IOException
	{
		wipe(dir);
		logged.list.clear();
		Random r = new Random(seed * 7919L + 13);
		Path run = dir.resolve("run");
		Path file = run.resolve(kind.fileName);
		Path base = run.resolve(kind.baseName);
		StringBuilder rec = new StringBuilder();

		// Now and then the data folder is a file, so nothing can be written there.
		boolean blocked = r.nextInt(25) == 0;
		if (blocked)
		{
			write(run, "not a folder");
		}
		else
		{
			Files.createDirectories(run);
			int user = r.nextInt(6);
			if (user == 5)
			{
				Files.createDirectories(file);
			}
			else if (user > 0)
			{
				JsonObject from = user == 1 ? kind.seen : user == 2 ? kind.bundled : kind.mutate.apply(kind.bundled, r);
				write(file, garbageOr(kind.mutate.apply(from, r), r));
			}
			int record = r.nextInt(6);
			if (record == 1)
			{
				write(base, PRETTY.toJson(kind.seen));
			}
			else if (record == 2)
			{
				write(base, PRETTY.toJson(kind.mutate.apply(kind.bundled, r)));
			}
			else if (record == 3)
			{
				write(base, r.nextBoolean() ? "{ broken" : "");
			}
			else if (record == 4)
			{
				write(base, PRETTY.toJson(kind.mutate.apply(kind.seen, r)));
			}
			else if (record == 5)
			{
				// A folder in the way, with something in it so it cannot be replaced.
				Files.createDirectories(base);
				write(base.resolve("x"), "x");
			}
			rec.append("user ").append(user).append(" base ").append(record).append('\n');
		}

		for (int pass = 0; pass < 2; pass++)
		{
			Driven loader = loaders.get();
			loader.initialise.accept(run, r.nextInt(5) > 0);
			rec.append("== pass ").append(pass).append('\n').append(loader.state.get());
			folderState(run, kind, rec);
			if (pass == 0)
			{
				// Rewrite the file the way an editor might, then poll and reload.
				int edit = r.nextInt(4);
				if (Files.isRegularFile(file))
				{
					String was = read(file);
					if (edit == 0)
					{
						write(file, "");
					}
					else if (edit == 1)
					{
						write(file, was + "  ");
					}
					else if (edit == 2)
					{
						write(file, was.substring(0, was.length() / 2));
					}
				}
				rec.append("polled ").append(loader.reloadIfChanged.getAsBoolean()).append('\n')
					.append(loader.state.get());
				loader.reload.run();
				rec.append(loader.state.get());
			}
		}
		if (Files.isDirectory(run))
		{
			try (Stream<Path> files = Files.list(run))
			{
				files.sorted().forEach(p -> rec.append("has ").append(p.getFileName()).append('\n'));
			}
		}
		for (ILoggingEvent event : logged.list)
		{
			String message = event.getFormattedMessage();
			if (event.getLoggerName().contains(".Before"))
			{
				// The words the client log has changed since: the dialogs
				// loader says conversations, as its status line does, and
				// both say a missing bundled file the same way.
				message = message
					.replaceFirst("^Bundled default rules missing from jar$",
						"Bundled /com/follower/default-phrases.json is missing")
					.replaceFirst("^Could not write default dialogs to ", "Could not write default conversations to ")
					.replaceFirst("^Could not record the starter dialogs in ",
						"Could not record the starter conversations in ")
					.replaceFirst("^Loaded dialogs: ", "Loaded conversations: ");
			}
			rec.append("log ").append(event.getLevel()).append(' ')
				.append(event.getLoggerName().replace(".Before", ".")).append(' ')
				.append(message);
			IThrowableProxy thrown = event.getThrowableProxy();
			if (thrown != null)
			{
				rec.append(" ! ").append(thrown.getClassName()).append(": ").append(thrown.getMessage());
			}
			rec.append('\n');
		}
		return rec.toString();
	}

	private static void folderState(Path run, Kind kind, StringBuilder rec) throws IOException
	{
		rec.append("file ").append(read(run.resolve(kind.fileName))).append('\n');
		rec.append("base ").append(read(run.resolve(kind.baseName))).append('\n');
		rec.append("bak ").append(read(run.resolve(kind.fileName + ".bak"))).append('\n');
		// The stamp's clock time is when this run wrote the file, so it is left out.
		String stamp = read(run.resolve(RuleLoader.MERGE_STAMP));
		String[] parts = stamp.split(" ");
		rec.append("stamp ").append(parts.length == 4 ? parts[0] + " " + parts[1] + " " + parts[3] : stamp).append('\n');
	}

	private static String rules(String status, List<String> errors, List<SpeechRule> rules,
		Map<Integer, String> regions, Set<String> bosses,
		Predicate<TriggerEvent.Type> listens, boolean varbit, Path file)
	{
		List<String> ids = new ArrayList<>();
		for (SpeechRule rule : rules)
		{
			ids.add(rule.id + ":" + rule.group + ":" + rule.priority);
		}
		StringBuilder heard = new StringBuilder();
		for (TriggerEvent.Type type : TriggerEvent.Type.values())
		{
			heard.append(type).append('=').append(listens.test(type)).append(' ');
		}
		return "status " + status + "\nerrors " + errors + "\nrules " + ids
			+ "\nregions " + new TreeMap<>(regions)
			+ "\nbosses " + new TreeSet<>(bosses) + "\nlistens " + heard + "null=" + listens.test(null)
			+ " varbit=" + varbit + "\npath " + file + "\n";
	}

	private static String dialogs(String status, List<String> errors, List<DialogTree> trees, DialogTree greeting,
		Path file)
	{
		List<String> ids = new ArrayList<>();
		for (DialogTree tree : trees)
		{
			ids.add(tree.id + ":" + tree.startId() + ":" + (tree.nodes == null ? -1 : tree.nodes.size()));
		}
		return "status " + status + "\nerrors " + errors + "\ntrees " + ids
			+ "\ngreeting " + (greeting == null ? null : greeting.id) + "\npath " + file + "\n";
	}

	private static JsonObject resource(String path) throws IOException
	{
		try (InputStream in = LoaderDiffTest.class.getResourceAsStream(path))
		{
			assertNotNull(path, in);
			return new JsonParser().parse(new String(in.readAllBytes(), StandardCharsets.UTF_8)).getAsJsonObject();
		}
	}

	private static void write(Path path, String text) throws IOException
	{
		Files.write(path, text.getBytes(StandardCharsets.UTF_8));
	}

	private static String read(Path path) throws IOException
	{
		if (Files.isDirectory(path))
		{
			return "<folder>";
		}
		return Files.exists(path) ? new String(Files.readAllBytes(path), StandardCharsets.UTF_8) : "<absent>";
	}

	private static void wipe(Path dir) throws IOException
	{
		if (Files.exists(dir))
		{
			try (Stream<Path> all = Files.walk(dir))
			{
				for (Path path : (Iterable<Path>) all.sorted(Comparator.reverseOrder())::iterator)
				{
					Files.delete(path);
				}
			}
		}
		Files.createDirectories(dir);
	}

	private static <T> T pick(List<T> list, Random r)
	{
		return list.get(r.nextInt(list.size()));
	}

	/** Random edits to a list of objects with ids and string-array lines. */
	private static void mutateList(JsonArray array, String lines, Random r, String prefix, String[] fields)
	{
		int edits = r.nextInt(6);
		for (int i = 0; i < edits && array.size() > 0; i++)
		{
			int at = r.nextInt(array.size());
			JsonElement el = array.get(at);
			switch (r.nextInt(12))
			{
				case 0:
					array.remove(at);
					break;
				case 1:
				{
					JsonObject own = new JsonObject();
					own.addProperty("id", prefix + "-own-" + r.nextInt(5));
					JsonArray say = new JsonArray();
					say.add("own line " + r.nextInt(3));
					own.add(lines, say);
					array.add(own);
					break;
				}
				case 2:
					array.add(r.nextBoolean() ? JsonNull.INSTANCE : new JsonPrimitive("junk"));
					break;
				default:
					if (!el.isJsonObject())
					{
						break;
					}
					JsonObject o = el.getAsJsonObject();
					int what = r.nextInt(9);
					JsonArray say = o.has(lines) && o.get(lines).isJsonArray() ? o.getAsJsonArray(lines) : null;
					if (what == 0 && say != null && say.size() > 0)
					{
						say.remove(r.nextInt(say.size()));
					}
					else if (what == 1 && say != null)
					{
						say.add("added " + r.nextInt(4));
					}
					else if (what == 2 && say != null && say.size() > 1)
					{
						JsonElement first = say.remove(0);
						say.add(first);
					}
					else if (what == 3)
					{
						o.addProperty(pick(List.of(fields), r), r.nextInt(3));
					}
					else if (what == 4)
					{
						o.remove(pick(List.of(fields), r));
					}
					else if (what == 5)
					{
						o.addProperty("enabled", r.nextBoolean());
					}
					else if (what == 6)
					{
						o.remove("id");
					}
					else if (what == 7)
					{
						array.add(o.deepCopy());
					}
					else
					{
						o.addProperty("id", prefix + "-renamed-" + r.nextInt(3));
					}
			}
		}
	}

	private static JsonObject mutateRules(JsonObject file, Random r)
	{
		JsonObject f = file.deepCopy();
		if (f.has("rules"))
		{
			mutateList(f.getAsJsonArray("rules"), "say", r, "rule",
				new String[]{"cooldownSeconds", "chance", "priority", "group", "note", "title"});
		}
		if (r.nextInt(4) == 0 && f.has("rules") && f.getAsJsonArray("rules").size() > 0)
		{
			JsonArray rules = f.getAsJsonArray("rules");
			JsonElement gone = rules.remove(r.nextInt(rules.size()));
			if (gone.isJsonObject() && gone.getAsJsonObject().has("id"))
			{
				JsonArray removed = f.has("removed") ? f.getAsJsonArray("removed") : new JsonArray();
				removed.add(gone.getAsJsonObject().get("id"));
				f.add("removed", removed);
			}
		}
		for (String map : new String[]{"nicknames", "places"})
		{
			if (!f.has(map) || !f.get(map).isJsonObject())
			{
				continue;
			}
			JsonObject m = f.getAsJsonObject(map);
			List<String> keys = new ArrayList<>(m.keySet());
			int what = r.nextInt(5);
			if (what == 0 && !keys.isEmpty())
			{
				m.remove(pick(keys, r));
			}
			else if (what == 1 && !keys.isEmpty())
			{
				String k = pick(keys, r);
				String v = m.get(k).getAsString();
				m.addProperty(k, v.contains("|") ? v.split("\\|")[r.nextInt(v.split("\\|").length)] : v + " own");
			}
			else if (what == 2)
			{
				f.remove(map);
			}
			else if (what == 3)
			{
				m.addProperty(map.equals("places") ? "" + (10000 + r.nextInt(3)) : "own-tally", "own");
			}
		}
		return f;
	}

	private static JsonObject mutateDialogs(JsonObject file, Random r)
	{
		JsonObject f = file.deepCopy();
		if (!f.has("trees"))
		{
			return f;
		}
		JsonArray trees = f.getAsJsonArray("trees");
		int edits = r.nextInt(5);
		for (int i = 0; i < edits && trees.size() > 0; i++)
		{
			int at = r.nextInt(trees.size());
			JsonElement el = trees.get(at);
			int what = r.nextInt(8);
			if (what == 0)
			{
				trees.remove(at);
			}
			else if (el.isJsonObject())
			{
				JsonObject t = el.getAsJsonObject();
				if (what == 1)
				{
					t.addProperty("note", "edited " + r.nextInt(3));
				}
				else if (what == 2)
				{
					t.remove("start");
				}
				else if (t.has("nodes") && t.get("nodes").isJsonArray())
				{
					mutateList(t.getAsJsonArray("nodes"), "says", r, "node", new String[]{"next", "answer", "you"});
				}
				else if (what == 3)
				{
					t.remove("nodes");
				}
			}
		}
		return f;
	}

	/** The file as written, or now and then one an editor or a failed save left behind. */
	private static String garbageOr(JsonObject o, Random r)
	{
		switch (r.nextInt(14))
		{
			case 0:
				return "";
			case 1:
				return "{ \"rules\": [ ";
			case 2:
				return "null";
			case 3:
				return "{\"version\": 2}";
			default:
				return PRETTY.toJson(o) + "\n";
		}
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The hello is heard. Behaviour QA5, 16-20 Oct: the greeting was held by
 * the gap in 11 of 26 real logins, behind crowded-here, place-remembers or
 * the sketch invite, all said in the first few seconds.
 */
public class LoginGreetingHeardTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private final long[] ms = {1_700_000_000_000L};

	private void ticks(Harness h, int count)
	{
		for (int i = 0; i < count; i++)
		{
			ms[0] += 600;
			h.gameTick();
		}
	}

	@Test
	public void theHelloHoldsTheFloorUntilItIsSaid() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), "{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"greet\", \"group\": \"t\", \"cooldownMs\": 60000, \"delayTicks\": 8, \"hushMs\": 8000,"
			+ " \"when\": {\"type\": \"login\"}, \"say\": [\"Welcome back.\"]},"
			+ "{\"id\": \"crowd\", \"group\": \"t\", \"cooldownMs\": 0,"
			+ " \"when\": {\"type\": \"idle\", \"ticks\": 3}, \"say\": [\"Busy here, isn't it.\"]}]}");
		h.engine.setClock(() -> ms[0]);
		h.engine.setGlobalCooldownMs(45_000L);
		h.game.at(3164, 3487, 0);

		// The login as the plugin raises it: the baseline first, then the hello.
		h.engine.primeEdgesOnNextTick();
		h.engine.dispatchAfterPriming(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		ticks(h, 4);
		h.engine.remark("This place wants a sketch.");
		ticks(h, 12);

		assertEquals("the hello is said", 1, h.firedBy("greet").size());
		assertTrue("and nothing went before it", h.firedBy("crowd").isEmpty());
		assertEquals(1, h.spoken.size());
	}

	@Test
	public void everyLoginHelloHoldsTheFloorForItsDelay() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		for (String id : new String[]{"login-greeting", "login-greeting-new", "login-greeting-settling",
			"away-a-while", "away-a-day", "away-a-long-time", "last-time"})
		{
			SpeechRule rule = h.rule(id);
			assertNotNull(id, rule.hushMs);
			int longest = rule.delayTicksMax != null ? rule.delayTicksMax : rule.delayTicks;
			assertTrue(id + " holds the floor until its line is due", rule.hushMs >= longest * 600);
		}
	}
}

package com.follower;

import java.io.IOException;
import java.lang.reflect.Field;
import java.util.Map;
import java.util.Random;
import net.runelite.api.coords.WorldPoint;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;

/**
 * A session long enough for slow growth to show.
 *
 * <p>The state snapshot remembers things on purpose - how often each region has
 * been visited, when each was last seen, which NPCs the player has damaged -
 * and every one of those is a map that only ever gets keys added. A player who
 * leaves the client running all day walks through a lot of regions and hits a
 * lot of monsters. None of it is freed by anything on the tick path, so the
 * question is whether the growth is bounded by something real or just by how
 * long the session is.
 *
 * <p>Nothing here asserts an exact number; the point is the shape of the curve.
 */
public class LongSessionTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@SuppressWarnings("unchecked")
	private static Map<Integer, Integer> mapField(Object target, String name)
	{
		try
		{
			Field field = target.getClass().getDeclaredField(name);
			field.setAccessible(true);
			return (Map<Integer, Integer>) field.get(target);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError("the field this test watches has been renamed: " + name, e);
		}
	}

	@Test
	public void regionMemoryIsBoundedByPlacesNotByTime() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		Random random = new Random(20260808L);

		// Twenty places, walked between for a very long time. The memory should
		// settle at twenty entries, not keep climbing with the tick count.
		WorldPoint[] places = new WorldPoint[20];
		for (int i = 0; i < places.length; i++)
		{
			places[i] = new WorldPoint(3200 + i * 64, 3200, 0);
		}

		int afterFirstLap = 0;
		for (int step = 0; step < 20000; step++)
		{
			WorldPoint place = places[random.nextInt(places.length)];
			h.game.at(place.getX(), place.getY(), 0);
			h.gameTick();

			if (step == 2000)
			{
				afterFirstLap = mapField(h.engine.getContext(), "regionLastSeenTick").size();
			}
		}

		Map<Integer, Integer> lastSeen = mapField(h.engine.getContext(), "regionLastSeenTick");
		Map<Integer, Integer> visits = mapField(h.engine.getContext(), "regionVisits");

		assertTrue("the test did not actually move between regions",
			afterFirstLap > 1);
		assertTrue("region memory grew to " + lastSeen.size() + " entries for "
				+ places.length + " places, so it is keyed by something other"
				+ " than the place", lastSeen.size() <= places.length + 2);
		assertTrue("visit counts grew to " + visits.size() + " entries",
			visits.size() <= places.length + 2);
	}

	@Test
	public void seventeenHoursOfTheNewerStateStaysBounded() throws IOException
	{
		// The soak above predates the counters, the wants, the floor and the
		// conversations - the four things added since that hold state between
		// ticks rather than within one. Anything that only ever grows shows up
		// here or nowhere.
		Harness h = new Harness(folder.newFolder().toPath());
		Random random = new Random(7L);
		h.game.at(3000, 3000, 0);

		for (int step = 0; step < 100000; step++)
		{
			switch (random.nextInt(8))
			{
				case 0:
					// A different NPC name every time: the worst case for the
					// tally map, which is keyed by name.
					h.dispatch(TriggerEvent.kill(1, "Monster " + step, 40));
					break;
				case 1:
					h.engine.getContext().noteQuestion("want-outing");
					break;
				case 2:
					h.answers(random.nextBoolean() ? "yes" : "no");
					break;
				case 3:
					h.dispatch(TriggerEvent.record("hit", random.nextInt(100), 30));
					break;
				case 4:
					h.game.at(3000 + random.nextInt(8) * 64, 3000, 0);
					break;
				case 5:
					h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
					break;
				case 6:
					h.engine.getContext().setHoverTicks(random.nextInt(40));
					break;
				default:
					break;
			}
			h.gameTick();
			if (h.spoken.size() > 500)
			{
				h.clear();
			}
		}

		// A want is one at a time and always resolves. Asking how many ticks
		// are LEFT is not the question - that clamps at zero, so a want which
		// never expires reads the same as no want at all. The question is
		// whether one is still open with its deadline behind it.
		assertTrue("a want is still open with its deadline long past, so"
				+ " nothing can ever be asked for again",
			!h.engine.getContext().isWanting()
				|| h.engine.getContext().getWantTicksLeft() > 0);

		// The counters are keyed by NPC name and a name was invented every
		// time. The live map is not the saved one - the cap applies on write -
		// but it still must not be the whole session.
		int counted = h.engine.getContext().getTallies().size();
		assertTrue("the tally map holds " + counted + " entries after 100,000"
			+ " ticks; it is keyed by name and names were invented, so this is"
			+ " the shape of the growth rather than the exact number",
			counted < 30000);

		// And it still answers.
		h.clear();
		h.game.hitpoints(1, 99);
		h.gameTicks(3);
	}

	@Test
	public void aVeryLongSessionOfEverythingDoesNotDrift() throws IOException
	{
		// Not a leak test so much as a soak: a hundred thousand ticks of the
		// whole event mix, checking it neither throws nor slows to a crawl nor
		// stops answering at the end.
		Harness h = new Harness(folder.newFolder().toPath());
		Random random = new Random(99L);
		h.game.spawnNpc(3029, "Goblin", 5);

		long start = System.nanoTime();
		for (int step = 0; step < 100000; step++)
		{
			switch (random.nextInt(12))
			{
				case 0:
					h.game.at(3200 + random.nextInt(40) * 64, 3200, 0);
					break;
				case 1:
					h.dispatch(TriggerEvent.kill(1, "Goblin", random.nextInt(900)));
					break;
				case 2:
					h.dispatch(TriggerEvent.loot(random.nextInt(300000), "Bones"));
					break;
				case 3:
					h.dispatch(TriggerEvent.damageTaken(1 + random.nextInt(40)));
					break;
				case 4:
					h.game.hitpoints(1 + random.nextInt(99), 99);
					break;
				case 5:
					h.dispatch(TriggerEvent.animation(862));
					break;
				case 6:
					h.game.energy(random.nextInt(10001));
					break;
				case 7:
					h.dispatch(TriggerEvent.death());
					break;
				default:
					break;
			}
			h.gameTick();

			// The sink would otherwise hold every line ever spoken; the plugin
			// does not keep them, so neither should the measurement.
			if (h.spoken.size() > 500)
			{
				h.clear();
			}
		}
		long elapsedMs = (System.nanoTime() - start) / 1_000_000;

		// A hundred thousand ticks is about seventeen hours of play. If that
		// takes minutes here, something is accumulating per-tick work.
		assertTrue("100,000 ticks took " + elapsedMs + "ms, which suggests the"
			+ " per-tick cost is growing with session length", elapsedMs < 60000);

		// Still working afterwards.
		h.clear();
		h.game.hitpoints(1, 99);
		h.gameTicks(3);
	}

	@Test
	public void thePendingQueueDrainsRatherThanAccumulating() throws IOException
	{
		// A delayed rule that is re-triggered constantly must not build up a
		// backlog of firings waiting to be spoken.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": [{\"id\": \"slow\", \"group\": \"t\","
				+ " \"cooldownMs\": 0, \"delayTicks\": 3,"
				+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"a\"]}]}");

		for (int i = 0; i < 5000; i++)
		{
			h.dispatch(TriggerEvent.death());
			h.gameTick();
		}

		Object engine = h.engine;
		try
		{
			Field field = engine.getClass().getDeclaredField("pending");
			field.setAccessible(true);
			java.util.List<?> pending = (java.util.List<?>) field.get(engine);
			assertTrue("the delayed-firing queue holds " + pending.size()
				+ " entries after 5000 triggers", pending.size() <= 5);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError("the pending queue has been renamed", e);
		}
	}

	@Test
	public void aSessionSpentEntirelyInOnePlaceStaysCheap() throws IOException
	{
		// The common case: standing at a bank for hours. Nothing should be
		// recorded over and over for a region already known.
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(20000);

		Map<Integer, Integer> lastSeen = mapField(h.engine.getContext(), "regionLastSeenTick");
		assertTrue("standing still recorded " + lastSeen.size() + " regions",
			lastSeen.size() <= 1);
		assertTrue("standing still counted "
				+ h.engine.getContext().getRegionVisits() + " visits to one place",
			h.engine.getContext().getRegionVisits() <= 1);
	}
}

package com.follower;

import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.coords.WorldPoint;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Hours of the shipped rules with every system live at its real setting.
 *
 * <p>{@link EngineSoakTest} explores random rule sets for engine invariants.
 * This one does the opposite: the REAL four hundred rules, real chattiness,
 * real director, real bags, driven long enough that the windows actually open
 * and close. The clock is fake, which is the only reason that is possible -
 * a relax period is thirty to forty-five seconds and a test cannot spend them.
 *
 * <p>What it is looking for is the failure no unit test can produce: something
 * that only goes wrong on the four hundredth firing, or when three windows
 * happen to line up.
 */
public class LongSoakTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** One game tick, in milliseconds. */
	private static final long TICK_MS = 600L;

	/** The shipped chattiness, Occasional: what a player who never opens the settings hears. */
	private static final long GAP = new FollowerConfig()
	{
	}.chattiness().getGapMs();

	/** A session long enough for every window in the engine to cycle many times. */
	private static final int TICKS = 20_000;      // 20,000 * 0.6s = about 3h20m

	private final AtomicLong clock = new AtomicLong(1_700_000_000_000L);

	/** Where the harness stands the player, and a region to walk off to. */
	private static final WorldPoint HOME = new WorldPoint(3222, 3218, 0);
	private static final WorldPoint AWAY = new WorldPoint(3300, 3300, 0);

	private Harness soakHarness() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.setClock(clock::get);
		h.engine.setGlobalCooldownMs(GAP);
		return h;
	}

	/** What the driver levels up in, for the level lines to name. */
	private static final String[] SKILLS = {"Attack", "Cooking", "Mining", "Woodcutting"};

	/** Drives ticks and a spread of realistic events, advancing the fake clock. */
	private void play(Harness h, int ticks, long seed)
	{
		Random random = new Random(seed);
		// The skill and level of each level-up, drawn apart so the stream of
		// events is the one every seed has always played.
		Random levels = new Random(seed + 1);
		for (int i = 0; i < ticks; i++)
		{
			clock.addAndGet(TICK_MS);
			h.gameTick();

			int roll = random.nextInt(100);
			if (roll < 4)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
			}
			else if (roll < 7)
			{
				h.dispatch(TriggerEvent.death());
			}
			else if (roll < 12)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_START));
			}
			else if (roll < 17)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_END));
			}
			else if (roll < 20)
			{
				h.dispatch(TriggerEvent.levelUp(SKILLS[levels.nextInt(SKILLS.length)],
					2 + levels.nextInt(98)));
			}
		}
	}

	// --------------------------------------------------------------- the soak

	@Test
	public void hoursOfPlayLeaveEverySystemIntact() throws IOException
	{
		Harness h = soakHarness();
		h.gameTicks(3);
		h.clear();

		play(h, TICKS, 20260810L);

		List<Harness.Spoken> spoken = new ArrayList<>(h.spoken);
		List<String> lines = new ArrayList<>();
		for (Harness.Spoken s : spoken)
		{
			if (!s.text.isEmpty())
			{
				lines.add(s.text);
			}
		}

		assertFalse("three hours and the follower never said anything", lines.isEmpty());

		// 1. Never the same line twice running, whatever combination of gap,
		//    rest, bag refill and window happened to line up.
		for (int i = 1; i < lines.size(); i++)
		{
			assertFalse("said \"" + lines.get(i) + "\" twice running at line " + i,
				lines.get(i).equals(lines.get(i - 1)));
		}

		// 2. Every rule that spoke stayed inside its own bag: no line came round
		//    again before that rule had spent its other variants.
		assertBagsDealEvenly(h, spoken);

		// 3. A one-time line is one time, across three hours and every window.
		assertOnceIsOnce(spoken);

		// 4. Memory stays bounded. The window is a fixed twelve and the spent
		//    set can only hold as many ids as there are one-time rules.
		assertTrue("the spent-line set grew past the rules that can fill it",
			h.engine.getContext().getSpokenOnce().size() <= 8);

		// 5. The level-ups were answered, the plain line and a milestone both.
		assertLevelsSpoke(rulesOf(spoken));

		// 6. The follower is still capable of speech at the end - the failure
		//    where some window latches shut and everything afterwards is silent.
		h.clear();
		play(h, 600, 7L);
		assertFalse("the follower went permanently quiet by the end", h.spoken.isEmpty());
	}

	private static void assertBagsDealEvenly(Harness h, List<Harness.Spoken> spoken)
	{
		Map<String, List<String>> byRule = new HashMap<>();
		for (Harness.Spoken s : spoken)
		{
			if (s.rule != null && !s.text.isEmpty())
			{
				byRule.computeIfAbsent(s.rule.id, k -> new ArrayList<>()).add(s.text);
			}
		}
		for (Map.Entry<String, List<String>> entry : byRule.entrySet())
		{
			SpeechRule rule = h.rule(entry.getKey());
			int variants = rule.say == null ? 1 : rule.say.size();
			if (variants < 2)
			{
				continue;
			}
			List<String> said = entry.getValue();

			// Never the same line twice in a row FOR THIS RULE. The global check
			// cannot see this: two firings of one rule are usually far apart in
			// the overall stream, with other rules in between.
			for (int i = 1; i < said.size(); i++)
			{
				assertFalse(entry.getKey() + " said \"" + said.get(i) + "\" twice running",
					said.get(i).equals(said.get(i - 1)));
			}

			// The real promise of a bag is EVEN USE, not minimum spacing. A line
			// drawn late in one bag may legitimately come early in the next, so
			// two occurrences can be close - but across many bags every variant
			// has to come out the same number of times, give or take the partly
			// spent bag at the end. That is the property that catches a bag
			// which quietly stopped dealing part of its range.
			boolean templated = false;
			for (String variant : rule.say)
			{
				templated |= variant.indexOf('{') >= 0;
			}
			if (templated || said.size() < variants * 3)
			{
				continue;
			}

			Map<String, Integer> counts = new HashMap<>();
			for (String line : said)
			{
				counts.merge(line, 1, Integer::sum);
			}
			assertEquals(entry.getKey() + " only ever used " + counts.size()
				+ " of its " + variants + " lines across " + said.size() + " firings",
				variants, counts.size());

			int most = 0;
			int fewest = Integer.MAX_VALUE;
			for (int n : counts.values())
			{
				most = Math.max(most, n);
				fewest = Math.min(fewest, n);
			}
			assertTrue(entry.getKey() + " used one line " + most + " times and another"
				+ " only " + fewest + " across " + said.size() + " firings, which is"
				+ " not a bag dealing evenly", most - fewest <= 1);
		}
	}

	/**
	 * A level-up line and a level milestone both came out. The driver once
	 * raised every level-up at level nought, which no level rule answers since
	 * levelUp asks for level one at least, and three soaks went on passing
	 * without a level line in them.
	 */
	private static void assertLevelsSpoke(List<SpeechRule> said)
	{
		boolean levelUp = false;
		boolean milestone = false;
		for (SpeechRule rule : said)
		{
			levelUp |= rule != null && rule.when.usesType("levelUp");
			milestone |= rule != null && rule.when.usesType("milestone");
		}
		assertTrue("hours of level-ups and not one level-up line", levelUp);
		assertTrue("hours of level-ups and not one level milestone", milestone);
	}

	private static List<SpeechRule> rulesOf(List<Harness.Spoken> spoken)
	{
		List<SpeechRule> rules = new ArrayList<>();
		for (Harness.Spoken s : spoken)
		{
			rules.add(s.rule);
		}
		return rules;
	}

	private static void assertOnceIsOnce(List<Harness.Spoken> spoken)
	{
		Map<String, Integer> onceCounts = new HashMap<>();
		for (Harness.Spoken s : spoken)
		{
			if (s.rule != null && s.rule.isOnce())
			{
				onceCounts.merge(s.rule.id, 1, Integer::sum);
			}
		}
		for (Map.Entry<String, Integer> entry : onceCounts.entrySet())
		{
			assertEquals(entry.getKey() + " said itself more than once",
				1, entry.getValue().intValue());
		}
	}

	@Test
	public void theNewSystemsSurviveHoursTogether() throws IOException
	{
		// Everything the last two days added, live at once for simulated
		// hours: stays with reunions, wilderness stints, boundaries from
		// every ending, era-gated greetings, wear accruing on every line,
		// the context idle pools. What this is for is the failure that only
		// shows when three of them line up - and the silent one, where a new
		// condition throws once and its rules are disabled forever.
		//
		// Since then the milestones, the companion's reactions and the
		// skilling company have joined it: kill counts, things noticed and
		// sends hesitated over, a parked follower walked into, emotes done
		// at it, pages written, walks away from an old incident and back,
		// work sessions with their drops, and the greeting that remembers
		// last time.
		Harness h = soakHarness();
		TriggerContext ctx = h.engine.getContext();
		h.game.spawnNpc(2098, "Hill Giant", 28);
		h.gameTicks(3);
		h.clear();

		Random random = new Random(20260812L);
		boolean staying = false;
		boolean away = false;
		boolean working = false;
		int total = 1450;
		int masteries = 0;
		int killCount = 0;
		for (int i = 0; i < TICKS; i++)
		{
			clock.addAndGet(TICK_MS);
			h.gameTick();

			int roll = random.nextInt(1000);
			if (roll < 30)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_START));
			}
			else if (roll < 60)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_END));
			}
			else if (roll < 75)
			{
				// With the ledger the milestones read: the total climbing one
				// at a time and the lowest skill with it, a ninety-nine now
				// and then, and a gap that is unknown, quick or over a week.
				int level = 30 + random.nextInt(70);
				masteries += level == 99 ? 1 : 0;
				total++;
				long gap = new long[]{-1L, 5 * 60_000L, 8 * 24 * 3_600_000L}[random.nextInt(3)];
				ctx.tallyBoth("levels");
				h.dispatch(TriggerEvent.levelUp("Cooking", level, total, total - 1,
					total / 30, (total - 1) / 30, masteries, gap, gap));
			}
			else if (roll < 90)
			{
				h.dispatch(TriggerEvent.regionChange(
					12850 + random.nextInt(4), 12850));
			}
			else if (roll < 100)
			{
				h.engine.getContext().noteBoundary("bank");
			}
			else if (roll < 110)
			{
				staying = !staying;
				h.engine.getContext().setFollowerStaying(staying);
			}
			else if (roll < 120 && staying)
			{
				h.engine.getContext().noteBoundary("reunion");
			}
			else if (roll < 140)
			{
				h.game.varbit(5963, random.nextBoolean() ? 1 : 0);
			}
			else if (roll < 160)
			{
				h.game.animating(roll % 2 == 0 ? 879 : -1);
			}
			else if (roll < 170)
			{
				// Where and how often, as the plugin notes a death.
				ctx.noteDeath(h.game.player.getWorldLocation());
				ctx.tallyBoth("deaths");
				h.dispatch(TriggerEvent.death());
			}
			else if (roll < 175)
			{
				killCount++;
				h.dispatch(TriggerEvent.killCount("Vorkath", killCount, killCount - 1));
			}
			else if (roll < 180)
			{
				String kind = new String[]{"valuable", "nest", "impling", "star", "landmark"}
					[random.nextInt(5)];
				h.dispatch(TriggerEvent.noticed(kind, "a " + kind));
			}
			else if (roll < 183)
			{
				h.dispatch(random.nextBoolean()
					? TriggerEvent.hesitated("monster", "Hill Giant")
					: TriggerEvent.hesitated("wilderness", "the Wilderness"));
			}
			else if (roll < 188)
			{
				// Only a parked follower can be walked into.
				if (staying)
				{
					h.dispatch(TriggerEvent.simple(TriggerEvent.Type.STEPPED_ASIDE));
				}
			}
			else if (roll < 195)
			{
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.FAREWELL));
			}
			else if (roll < 200)
			{
				// The follower a tile to the south, which the player faces, or
				// a few tiles off where an emote is not done at it.
				WorldPoint here = h.game.player.getWorldLocation();
				ctx.setFollowerLocation(random.nextBoolean()
					? new WorldPoint(here.getX(), here.getY() - 1, here.getPlane())
					: new WorldPoint(here.getX() + 4, here.getY(), here.getPlane()));
			}
			else if (roll < 205)
			{
				h.dispatch(TriggerEvent.animation(855 + random.nextInt(8)));
			}
			else if (roll < 208)
			{
				// A walk away from home and back, where the incidents are filed
				// and the Hill Giant stands.
				WorldPoint from = away ? AWAY : HOME;
				away = !away;
				WorldPoint to = away ? AWAY : HOME;
				h.game.at(to.getX(), to.getY(), to.getPlane());
				h.dispatch(TriggerEvent.regionChange(to.getRegionID(), from.getRegionID()));
			}
			else if (roll < 210)
			{
				working = !working;
				String activity = random.nextBoolean() ? "cooking" : "fletching";
				ctx.setWork(working, activity, "Range", null, 10, 0, Integer.MAX_VALUE);
			}
			else if (roll < 230)
			{
				// What a work session raises, while one is on.
				if (working)
				{
					int work = random.nextInt(10);
					if (work < 3)
					{
						h.dispatch(TriggerEvent.chat("You accidentally burn the shrimps.",
							net.runelite.api.ChatMessageType.GAMEMESSAGE.getType(), ""));
					}
					else if (work < 6)
					{
						h.dispatch(TriggerEvent.animation(1248));
					}
					else if (work < 8)
					{
						h.dispatch(TriggerEvent.xpDrop("Cooking", 1 + random.nextInt(20)));
					}
					else
					{
						h.dispatch(new TriggerEvent[]{
							TriggerEvent.workEnd("cooking", "Range"),
							TriggerEvent.targetDepleted("Range"),
							TriggerEvent.simple(TriggerEvent.Type.BAG_FULL),
							TriggerEvent.simple(TriggerEvent.Type.BAG_HALF)}[random.nextInt(4)]);
					}
				}
			}
			else if (roll == 230)
			{
				// A login after a long absence, remembering what the two of
				// them were doing.
				ctx.restoreLastThing("the mining");
				ctx.setMinutesAway(600);
				h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
			}
			else if (roll == 231)
			{
				// Filed as the death memory files it, with the foe it was with.
				ctx.noteIncident("the-death", "the way that went with the Hill Giant",
					"Hill Giant", clock.get());
			}
			else if (roll == 232)
			{
				// The player saying yes to the name on offer.
			}
			else if (roll == 233 && random.nextInt(10) == 0)
			{
				// A favour done: rare, since the debt lasts half an hour.
				ctx.noteFavour();
			}
		}

		assertFalse("hours of everything at once and nothing was said",
			h.spoken.isEmpty());

		// The silent failure: a condition that throws disables its rule for
		// good, and the only symptom is a line nobody ever hears again.
		for (SpeechRule rule : h.loader.getRules())
		{
			assertTrue("rule '" + rule.id + "' was disabled by a thrown condition",
				rule.isEnabled());
		}

		assertTrue("the wear ledger stayed bounded",
			h.engine.getContext().getLineWear().size() <= 500);

		// The bags and the one-time lines, held to the same promises as the
		// plain soak's, over everything this one drives.
		List<Harness.Spoken> spoken = new ArrayList<>(h.spoken);
		assertBagsDealEvenly(h, spoken);
		assertOnceIsOnce(spoken);

		// Never the same line twice running, whatever lined up.
		String previous = null;
		for (Harness.Spoken s : h.spoken)
		{
			if (!s.text.isEmpty())
			{
				assertFalse("said \"" + s.text + "\" twice running",
					s.text.equals(previous));
				previous = s.text;
			}
		}

		// And still capable of speech at the end.
		h.engine.getContext().setFollowerStaying(false);
		h.clear();
		play(h, 600, 7L);
		assertFalse("the follower went permanently quiet by the end",
			h.spoken.isEmpty());
	}

	@Test
	public void theDirectorRestsWithoutEverStopping() throws IOException
	{
		// The shape the whole model is for: bursts with real quiet between them,
		// rather than a flat stream or a follower that talks itself into silence.
		Harness h = soakHarness();
		h.gameTicks(3);
		h.clear();

		List<Long> spokenAt = new ArrayList<>();
		List<SpeechRule> said = new ArrayList<>();
		h.engine.setSink((text, output, rule, animationId, onSaid) ->
		{
			onSaid.run();
			if (!text.isEmpty())
			{
				spokenAt.add(clock.get());
				said.add(rule);
			}
		});

		play(h, TICKS, 99L);

		assertTrue("far too little came out of three hours: " + spokenAt.size(),
			spokenAt.size() > 20);

		long span = clock.get() - 1_700_000_000_000L;
		double perHour = spokenAt.size() * 3_600_000.0 / span;
		assertTrue("the follower talked at " + Math.round(perHour) + " lines an hour,"
			+ " which is not a companion, it is a radio", perHour < 400);

		// There must be real silences in there. A model that never actually
		// rests would show a tight cluster of gaps around the speech floor.
		int longQuiets = 0;
		for (int i = 1; i < spokenAt.size(); i++)
		{
			if (spokenAt.get(i) - spokenAt.get(i - 1) >= 25_000L)
			{
				longQuiets++;
			}
		}
		assertTrue("three hours produced " + spokenAt.size() + " lines at "
			+ Math.round(perHour) + " an hour with only " + longQuiets + " silences"
			+ " past 25 seconds; the rest period is not taking hold",
			longQuiets > 5);

		// And the level-ups were answered in among it.
		assertLevelsSpoke(said);
	}

	@Test
	public void anOccasionIsNeverTheThingThatGetsHeldBack() throws IOException
	{
		// The promise the whole occasion flag exists to keep, checked against
		// the shipped rules over hours rather than against a hand-made pair.
		Harness h = soakHarness();
		h.gameTicks(3);

		Set<String> heldOccasions = new HashSet<>();
		h.engine.setOnSuppressed((rule, why) ->
		{
			if (rule.isOccasion() && ("relax".equals(why) || "settling".equals(why)))
			{
				heldOccasions.add(rule.id + " by " + why);
			}
		});

		h.engine.getContext().setSessionCount(1);       // settling damper live too
		play(h, TICKS, 4242L);

		assertTrue("the director held back lines it must never hold: " + heldOccasions,
			heldOccasions.isEmpty());
		assertLevelsSpoke(rulesOf(h.spoken));
	}

	// ------------------------------------------------- scenes, boxes, chairs

	/** Who the driver brings into view: quest people, whose lines wait, and a passer-by. */
	private static final String[] PEOPLE = {"Hans", "Alina", "Sergeant Tobyn", "Prince Itzla Arkan",
		"Duke Horacio", "Cook", "Man"};

	/** Ticks a session of the scene soak plays: two hours. */
	private static final int SCENE_SOAK_TICKS = 12_000;

	@Test
	public void scenesConversationsAndAbsencesKeepTheirPromises() throws Exception
	{
		// QA, 15 Oct: the soaks above never drove what came in with the
		// cutscenes and the quest people - the quiet after a scene, lines
		// that wait their turn through it, through a conversation and an
		// empty chair, and two quest people met on one tick. Six seeds of two
		// hours each, the scenes, boxes and absences at random among the rest.
		java.lang.reflect.Field pendingField =
			SpeechEngine.class.getDeclaredField("pending");
		pendingField.setAccessible(true);
		List<String> problems = new ArrayList<>();
		int waitsHeard = 0;
		int occasionsHeard = 0;

		for (long seed = 1; seed <= 6; seed++)
		{
			final long run = seed;
			Harness h = soakHarness();
			TriggerContext ctx = h.engine.getContext();
			boolean[] quiet = {false};
			List<SpeechRule> said = new ArrayList<>();
			h.engine.setSink((text, output, rule, animationId, onSaid) ->
			{
				onSaid.run();
				if (text.isEmpty() || rule == null)
				{
					return;
				}
				said.add(rule);
				if (quiet[0])
				{
					problems.add(run + ": " + rule.id + " said in a scene or the quiet after it");
				}
				if (rule.waitsItsTurn() && ctx.isDialogueOpen())
				{
					problems.add(run + ": " + rule.id + " said into a conversation");
				}
				if (Boolean.TRUE.equals(rule.waits) && ctx.getUnattendedTicks() >= 300
					&& !rule.when.usesType("unattended"))
				{
					problems.add(run + ": " + rule.id + " said to the empty chair");
				}
			});
			h.gameTicks(3);

			Random r = new Random(run);
			int sceneLeft = 0;
			int quietLeft = 0;
			int boxLeft = 0;
			int boxTail = 0;
			int awayLeft = 0;
			int quest = 0;
			int maxPending = 0;
			for (int i = 0; i < SCENE_SOAK_TICKS; i++)
			{
				clock.addAndGet(TICK_MS);

				// A cutscene, then the quiet the plugin keeps after one.
				if (sceneLeft == 0 && quietLeft == 0 && r.nextInt(400) == 0)
				{
					sceneLeft = 20 + r.nextInt(80);
				}
				if (sceneLeft > 0 && --sceneLeft == 0)
				{
					quietLeft = 25;
				}
				else if (quietLeft > 0)
				{
					quietLeft--;
				}
				quiet[0] = sceneLeft > 0 || quietLeft > 0;
				h.engine.setSceneQuiet(quiet[0]);
				h.engine.setInCutscene(sceneLeft > 0);

				// A conversation, read as the plugin reads it: up, and for two
				// ticks after the box goes. A scene may run straight into one.
				if (boxLeft == 0 && boxTail == 0 && r.nextInt(80) == 0)
				{
					boxLeft = 5 + r.nextInt(35);
				}
				if (boxLeft > 0 && --boxLeft == 0)
				{
					boxTail = 2;
				}
				else if (boxTail > 0)
				{
					boxTail--;
				}
				ctx.setDialogueOpen(boxLeft > 0 || boxTail > 0);

				// Away from the keys now and then, long enough for the damper.
				if (awayLeft == 0 && r.nextInt(3000) == 0)
				{
					awayLeft = 350 + r.nextInt(400);
				}
				boolean away = awayLeft > 0;
				if (away)
				{
					awayLeft--;
				}
				else if (r.nextInt(5) == 0)
				{
					h.game.cameraMoved();
				}

				// A quest moving on, as Children of the Sun and Priest in Peril do.
				if (r.nextInt(150) == 0)
				{
					quest = Math.min(22, quest + 2);
					h.game.varbit(9632, quest);
					h.game.varp(302, Math.min(60, quest / 2));
				}

				h.gameTick();

				// Somebody comes into view, now and then two at once.
				if (r.nextInt(40) == 0)
				{
					h.game.clearNpcs();
					for (int n = r.nextInt(4) == 0 ? 2 : 1; n > 0; n--)
					{
						String who = PEOPLE[r.nextInt(PEOPLE.length)];
						h.game.spawnNpc(4000 + who.length(), who, 0);
						h.dispatch(TriggerEvent.npc(TriggerEvent.Type.NPC_SPAWN, 4000 + who.length(), who));
					}
				}

				int roll = r.nextInt(100);
				if (away)
				{
					// Nothing of the player's own while they are away.
				}
				else if (roll < 3)
				{
					h.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_START));
				}
				else if (roll < 6)
				{
					h.dispatch(TriggerEvent.simple(TriggerEvent.Type.COMBAT_END));
				}
				else if (roll < 8)
				{
					h.dispatch(TriggerEvent.levelUp(SKILLS[r.nextInt(SKILLS.length)], 2 + r.nextInt(97)));
				}
				else if (roll < 9)
				{
					h.dispatch(TriggerEvent.questComplete("Cook's Assistant"));
				}
				maxPending = Math.max(maxPending, ((List<?>) pendingField.get(h.engine)).size());
			}

			Map<String, Integer> once = new HashMap<>();
			for (SpeechRule rule : said)
			{
				waitsHeard += Boolean.TRUE.equals(rule.waits) ? 1 : 0;
				occasionsHeard += rule.isOccasion() ? 1 : 0;
				if (rule.isOnce())
				{
					once.merge(rule.onceKey(), 1, Integer::sum);
				}
			}
			for (Map.Entry<String, Integer> e : once.entrySet())
			{
				if (e.getValue() > 1)
				{
					problems.add(run + ": the first " + e.getKey() + " said " + e.getValue() + " times");
				}
			}
			if (maxPending > 8)
			{
				problems.add(run + ": " + maxPending + " lines waiting at once");
			}

			// And still capable of speech once it is all over.
			h.engine.setSceneQuiet(false);
			quiet[0] = false;
			ctx.setDialogueOpen(false);
			int before = said.size();
			play(h, 600, 7L);
			if (said.size() == before)
			{
				problems.add(run + ": the follower went permanently quiet");
			}
		}

		assertTrue(String.join("\n", problems), problems.isEmpty());
		assertTrue("no line that waits was ever heard: the path was not driven", waitsHeard > 0);
		assertTrue("no occasion was ever heard: the path was not driven", occasionsHeard > 0);
	}
}

package com.follower;

import java.io.IOException;
import java.util.HashSet;
import net.runelite.api.coords.WorldPoint;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The low-mood arc: what a bad day changes, and the way back up.
 *
 * <p>Three visible pieces. The Talk-to box sharpens "How have you been?" into
 * "You all right?" and asking it IS the comfort (that half lives in
 * {@link TalkScriptTest}). The social offers go quiet at the bottom band, so
 * a low day has friction the player can feel without anything functional
 * being withheld. And when the rolled temperament and the earned record
 * disagree about a place, the follower concedes the facts while keeping the
 * feeling, which is the one moment the temperament is visible as one.
 */
public class LowMoodTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void beingAskedAfterLandsAsALift() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.engine.getContext().adjustMood(-40);
		assertEquals("a genuinely bad day", "low",
			h.engine.getContext().getMoodBand());
		int before = h.engine.getContext().getMood();

		// What the allright-a node latches: the box closes, the rules hear it.
		h.answers("comforted");
		h.gameTicks(10);

		assertEquals("one soft coda after the box closes",
			1, h.firedBy("comforted").size());
		assertEquals("and being asked after is worth something",
			before + 6, h.engine.getContext().getMood());
	}

	@Test
	public void theOffersHoldTheirTongueOnTheWorstDay() throws IOException
	{
		// ask-outing wants idle 60..400 with a 3% roll per evaluation; over a
		// whole idle stretch it is near-certain to fire if its guard is gone.
		// With the guard present this is deterministic silence, so the test
		// can never flake in the failing direction - it is the behavioural
		// half of the structural lint in RuleSetIntegrityTest.
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.engine.getContext().adjustMood(-40);

		h.gameTicks(420);
		assertTrue("no outing is proposed from the bottom of the band",
			h.firedBy("ask-outing").isEmpty());
		assertTrue("no game either", h.firedBy("offer-game").isEmpty());
	}

}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import net.runelite.api.NPC;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * A memory said over the follower's head has to fit there. QA, 15 Oct: the
 * recall lines, once filled with the incident and its where and when, ran to
 * 92-151 characters, past the 80 any overhead in the game can carry, and in
 * fixed mode the viewport clipped both ends of every one of them. Measured
 * here as they are said: filed by the shipped rules, filled by the engine,
 * in the font the overhead is drawn in.
 */
public class MemoryLineLengthTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final long DAY_MS = 24L * 60 * 60_000L;
	private static final long THREE_DAYS_MS = 3 * DAY_MS;

	/**
	 * Over the limit with an everyday memory, and waiting for new wording,
	 * which is the player's to approve: see memories/text.json. Kept
	 * exact, so a line that is reworded comes off this list, and a line that
	 * grows past the limit cannot hide behind it.
	 */
	private static final List<String> AWAITING_WORDING = java.util.Collections.emptyList();

	/**
	 * Over the limit with the longest particulars, and waiting for the new
	 * memory wording (memories/text.json), whose shorter forms are what a
	 * line falls back to. Kept exact, as above.
	 */
	private static final List<String> AWAITING_LONGEST = java.util.Collections.emptyList();

	private GameFont overheadFont() throws IOException
	{
		GameFontRepository fonts = new GameFontRepository(new Gson());
		fonts.load();
		return fonts.getByName("b12_full");
	}

	private static boolean fits(String said, GameFont font)
	{
		return said.length() <= SpeechEngine.OVERHEAD_MAX_CHARS
			&& font.stringWidth(said) <= SpeechEngine.OVERHEAD_MAX_PX;
	}

	@Test
	public void everyRecallLineFitsOverheadWithAnEverydayMemory() throws IOException
	{
		GameFont font = overheadFont();
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.setOverheadWidth(font::stringWidth);
		Map<Integer, String> names = new HashMap<>();
		names.put(12342, "Edgeville");
		h.engine.getContext().setRegionNames(names);
		h.game.regions(12342).at(3090, 3490, 0).hitpoints(6, 99);
		NPC giant = h.game.spawnNpc(2098, "Hill Giant", 28);
		h.game.fighting(giant);
		h.gameTicks(3);
		TriggerContext context = h.engine.getContext();
		assertEquals("the close call was filed by the shipped rule", "close-call", context.getIncidentKey());
		String closeCall = context.getIncidentPhrase();

		// Each kind of memory, as its rule files it in an ordinary session.
		String[][] memories = {
			{"close-call", closeCall},
			{"the-death", "your death to the Hill Giant"},
			{"big-drop", "the Abyssal whip from the abyssal demon"},
			{"the-boss", "General Graardor going down"},
		};

		TreeSet<String> over = new TreeSet<>();
		List<String> measured = new ArrayList<>();
		for (String[] memory : memories)
		{
			context.restoreIncident(memory[0], memory[1], 1, 12342,
				System.currentTimeMillis() - THREE_DAYS_MS, "Hill Giant");
			for (SpeechRule rule : h.loader.getRules())
			{
				if (rule.say == null)
				{
					continue;
				}
				for (String template : rule.say)
				{
					if (!template.contains("{memory"))
					{
						continue;
					}
					String said = h.engine.spokenText(template, TriggerEvent.tick());
					measured.add(said);
					assertTrue("no placeholder left: " + said, !said.contains("{"));
					if (!fits(said, font))
					{
						over.add(rule.id + ": " + template);
					}
				}
			}
		}
		assertTrue("the recall lines were measured", measured.size() > 40);
		assertEquals("recall lines over " + SpeechEngine.OVERHEAD_MAX_CHARS + " characters or "
			+ SpeechEngine.OVERHEAD_MAX_PX + " px", new TreeSet<>(AWAITING_WORDING), over);
	}

	/**
	 * The same with the longest of everything: the longest foe and item
	 * {@link OverheadLineLengthTest} knows, the widest place name the
	 * Locations rules give, borrowed from next door, and the widest "when".
	 * A line that cannot carry all of it carries less, but has to fit.
	 */
	@Test
	public void everyRecallLineFitsOverheadWithTheLongestParticulars() throws IOException
	{
		GameFont font = overheadFont();
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.setOverheadWidth(font::stringWidth);
		h.gameTicks(1);
		TriggerContext context = h.engine.getContext();

		String widestPlace = "";
		for (String name : h.loader.getRegionNames().values())
		{
			String place = TriggerContext.shortPlace(name.split("[:,(]| - ")[0]);
			if (font.stringWidth(place) > font.stringWidth(widestPlace))
			{
				widestPlace = place;
			}
		}
		long now = System.currentTimeMillis();
		long widestWhen = now;
		int widestWhenPx = -1;
		for (int days = 0; days < 20; days++)
		{
			context.restoreIncident("x", "y", 1, 0, now - days * DAY_MS, "");
			int px = font.stringWidth(context.getMemoryAgo(now));
			if (px > widestWhenPx)
			{
				widestWhenPx = px;
				widestWhen = now - days * DAY_MS;
			}
		}

		TreeSet<String> over = new TreeSet<>();
		int measured = 0;
		for (SpeechRule filer : h.loader.getRules())
		{
			if (filer.remember == null || filer.remember.key == null)
			{
				continue;
			}
			String forms = String.join(" ", filer.remember.forms());
			String who = forms.contains("{foe}") || forms.contains("{npc}") ? "Thermonuclear smoke devil" : "";
			// Filed with an empty phrase, so it is said as its forms say it.
			context.restoreIncident(filer.remember.key, "", 1, 0, widestWhen, who,
				widestPlace, true, "Tumeken's shadow (uncharged)", 12);
			for (SpeechRule rule : h.loader.getRules())
			{
				if (rule.say == null || !bringsUp(rule, filer.remember.key, !who.isEmpty()))
				{
					continue;
				}
				for (String template : rule.say)
				{
					if (!template.contains("{memory"))
					{
						continue;
					}
					String said = h.engine.spokenText(template, TriggerEvent.tick());
					measured++;
					assertTrue("no placeholder left: " + said, !said.contains("{"));
					if (!fits(said, font))
					{
						over.add(rule.id + ": " + template);
					}
				}
			}
		}
		assertTrue("the recall lines were measured", measured > 100);
		assertEquals("recall lines over " + SpeechEngine.OVERHEAD_MAX_CHARS + " characters or "
				+ SpeechEngine.OVERHEAD_MAX_PX + " px with the longest particulars",
			new TreeSet<>(AWAITING_LONGEST), over);
	}

	/** Whether the rule can bring up a memory filed under this key: its remembers, and a foe to see. */
	private static boolean bringsUp(SpeechRule rule, String key, boolean hasWho)
	{
		if (rule.when == null || (!hasWho && rule.when.usesType("memoryFoeNearby")))
		{
			return false;
		}
		List<String> named = new ArrayList<>();
		namedMemories(rule.when, named);
		return named.isEmpty() || named.contains(key);
	}

	private static void namedMemories(Condition condition, List<String> into)
	{
		if ("remembers".equalsIgnoreCase(condition.type) && condition.is != null)
		{
			into.add(condition.is);
		}
		if (condition.conditions != null && !"none".equalsIgnoreCase(condition.type))
		{
			for (Condition inner : condition.conditions)
			{
				namedMemories(inner, into);
			}
		}
	}

	@Test
	public void aLongLineDropsTheWhereAndWhenAndKeepsTheMemory() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		Map<Integer, String> names = new HashMap<>();
		names.put(12342, "Edgeville");
		h.engine.getContext().setRegionNames(names);
		h.gameTicks(1);
		h.engine.getContext().restoreIncident("big-drop", "that drop", 1, 12342,
			System.currentTimeMillis() - THREE_DAYS_MS, "");
		assertEquals("a line that fits keeps them", "I keep thinking about your big drop in Edgeville.",
			h.engine.spokenText("I keep thinking about {memory}{memoryWhere}.", TriggerEvent.tick()));

		h.engine.getContext().restoreIncident("the-death",
			"the way that went with the Thermonuclear smoke devil", 1, 12342,
			System.currentTimeMillis() - THREE_DAYS_MS, "Thermonuclear smoke devil");
		String said = h.engine.spokenText(
			"Before you start. Remember {memory}? That was {memoryWhen}.", TriggerEvent.tick());
		assertEquals("Before you start. Remember the way that went with the Thermonuclear smoke devil?", said);
		assertTrue(said.length() <= SpeechEngine.OVERHEAD_MAX_CHARS);
	}

	private static final String FORMS = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"memory-death\", \"group\": \"memory\", \"cooldownMs\": 0,"
		+ " \"remember\": {\"key\": \"the-death\", \"as\": \"your death to the {foe}\","
		+ "  \"or\": [\"your death {where}\"], \"plain\": \"the time you died\"},"
		+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"Noted.\"]}]}";

	@Test
	public void aLineTooWideSaysLessWhenThenWhereThenAShorterMemory() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), FORMS);
		h.gameTicks(1);
		TriggerContext c = h.engine.getContext();
		String line = "I keep thinking about {memory}{memoryWhere}, {memoryAgo}.";
		c.restoreIncident("the-death", "your death to the Hill Giant", 1, 0,
			System.currentTimeMillis() - 2 * DAY_MS, "Hill Giant", "Edgeville", false, "", -1);
		assertEquals("all of it, while it fits",
			"I keep thinking about your death to the Hill Giant in Edgeville, two days ago.",
			h.engine.spokenText(line, TriggerEvent.tick()));

		// Wider than 480 px at seven a character: the when goes first.
		h.engine.setOverheadWidth(text -> text.length() * 7);
		assertEquals("I keep thinking about your death to the Hill Giant in Edgeville.",
			h.engine.spokenText(line, TriggerEvent.tick()));

		// Then the where; then the memory a shorter way, keeping what fits.
		c.restoreIncident("the-death", "your death to the Thermonuclear smoke devil", 1, 0,
			System.currentTimeMillis() - 2 * DAY_MS, "Thermonuclear smoke devil",
			"Tree Gnome Stronghold", true, "", -1);
		assertEquals("I keep thinking about your death to the Thermonuclear smoke devil.",
			h.engine.spokenText(line, TriggerEvent.tick()));
		h.engine.setOverheadWidth(text -> text.length() * 8);
		assertEquals("I keep thinking about your death near Tree Gnome Stronghold.",
			h.engine.spokenText(line, TriggerEvent.tick()));
		h.engine.setOverheadWidth(text -> text.length() * 9);
		assertEquals("only the kind of moment, when nothing more fits",
			"I keep thinking about the time you died.", h.engine.spokenText(line, TriggerEvent.tick()));
	}

	/**
	 * A line that names the creature itself says the memory without it.
	 * Play report, 17 Oct: "A Hill Giant. I remember your death to the Hill
	 * Giant" named it twice.
	 */
	@Test
	public void aLineThatNamesTheFoeSaysTheMemoryWithoutIt() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		Map<Integer, String> names = new HashMap<>();
		names.put(12342, "Edgeville");
		h.engine.getContext().setRegionNames(names);
		h.gameTicks(1);
		TriggerContext c = h.engine.getContext();
		long twoDays = System.currentTimeMillis() - 2 * DAY_MS;
		String line = "A {memoryWho}. I remember {memory}{memoryWhere}.";

		c.restoreIncident("the-death", "your death to the Hill Giant", 1, 12342, twoDays, "Hill Giant");
		assertEquals("A Hill Giant. I remember your death in Edgeville.",
			h.engine.spokenText(line, TriggerEvent.tick()));
		assertEquals("a line that does not name it keeps the foe",
			"I was rereading the entry on your death to the Hill Giant in Edgeville.",
			h.engine.spokenText("I was rereading the entry on {memory}{memoryWhere}.", TriggerEvent.tick()));

		c.restoreIncident("the-death", "your death to the Hill Giant", 1, 0, twoDays, "Hill Giant");
		assertEquals("with no place, the plain form", "A Hill Giant. I remember the time you died.",
			h.engine.spokenText(line, TriggerEvent.tick()));

		c.restoreIncident("big-drop", "the Abyssal whip from the abyssal demon", 1, 12342, twoDays,
			"Abyssal demon", null, false, "Abyssal whip", 40);
		assertEquals("An abyssal demon. I remember the Abyssal whip that dropped in Edgeville.",
			h.engine.spokenText(line, TriggerEvent.tick()));

		c.restoreIncident("the-boss", "General Graardor going down", 1, 12342, twoDays, "General Graardor");
		assertEquals("General Graardor. I remember your big kill in Edgeville.",
			h.engine.spokenText(line, TriggerEvent.tick()));
	}

	@Test
	public void theParticularsComeOutWithoutLeavingAHole()
	{
		assertEquals("I keep thinking about {memory}.",
			SpeechEngine.withoutMemoryParticulars("I keep thinking about {memory}{memoryWhere}."));
		assertEquals("Do you ever think about {memory}? I do.",
			SpeechEngine.withoutMemoryParticulars("Do you ever think about {memory}? I do. It was only {memoryWhen}."));
		assertEquals("A {memoryWho}. I remember {memory}.",
			SpeechEngine.withoutMemoryParticulars("A {memoryWho}. I remember {memory}, {memoryWhen}."));
		assertEquals("It was right about here. The page on {memory} is still creased.",
			SpeechEngine.withoutMemoryParticulars(
				"It was right about here, {memoryWhen}. The page on {memory} is still creased."));
		assertNull("nothing to take out", SpeechEngine.withoutMemoryParticulars("Careful. I've not forgotten {memory}."));
		assertNull("not at the cost of the memory itself",
			SpeechEngine.withoutMemoryParticulars("Back on {memoryWhen} I wrote {memory} down."));
		assertEquals("the ago goes as the when does", "Before you start. Remember {memory}?",
			SpeechEngine.withoutMemoryParticulars("Before you start. Remember {memory}? That was {memoryAgo}."));
		assertEquals("the when alone, keeping the where", "I keep thinking about {memory}{memoryWhere}.",
			SpeechEngine.withoutMemoryWhen("I keep thinking about {memory}{memoryWhere}, {memoryAgo}."));
		assertNull("no when to take", SpeechEngine.withoutMemoryWhen("I keep thinking about {memory}{memoryWhere}."));
	}
}

package com.follower;

import java.io.IOException;
import java.time.LocalDate;
import java.time.ZoneId;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;

/**
 * How often a memory comes back, and how soon. Text QA5, 18 Oct: recall-idle
 * named the Castle Wars death eighteen times in one day. Quests QA5: a quest
 * moment brought up seconds after it happened, "Persten going into the rift,
 * earlier today" fifteen seconds after Persten went.
 */
public class MemoryRecallPacingTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** Nine in the morning, so a few hours on is still the same day. */
	private final long[] ms = {LocalDate.of(2026, 10, 18).atTime(9, 0)
		.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli()};

	private static final String IDLE_RECALL = "{\"id\": \"recall-idle\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"all\", \"conditions\": [{\"type\": \"levelUp\", \"names\": [\"Attack\"]}, {\"type\": \"idle\", \"ticks\": 0}]},"
		+ " \"say\": [\"My mind goes back to {memory}.\"]}";

	private static final String HERE_RECALL = "{\"id\": \"place-remembers\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"happenedHere\"}, \"say\": [\"This is where {here}.\"]}";

	private Harness harness(String rules) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), "{\"version\": 1, \"rules\": [" + rules + "]}");
		h.engine.setClock(() -> ms[0]);
		h.gameTicks(1);
		return h;
	}

	private void ticks(Harness h, int count)
	{
		for (int i = 0; i < count; i++)
		{
			ms[0] += 600;
			h.gameTick();
		}
	}

	private void level(Harness h)
	{
		h.dispatch(TriggerEvent.levelUp("Attack", 30));
		ticks(h, 1);
	}

	@Test
	public void aMemoryIsNotBroughtUpUntilItIsTwentyMinutesOld() throws IOException
	{
		Harness h = harness(IDLE_RECALL);
		h.engine.getContext().noteIncident("rift", "Persten going into the rift", "", ms[0]);
		ticks(h, 25);
		level(h);
		assertEquals("not fifteen seconds on", 0, h.firedBy("recall-idle").size());

		ticks(h, TriggerContext.MEMORY_MIN_AGE_TICKS);
		level(h);
		assertEquals("twenty minutes on", 1, h.firedBy("recall-idle").size());
	}

	@Test
	public void oneMemoryIsBroughtUpUnpromptedOnceADay() throws IOException
	{
		Harness h = harness(IDLE_RECALL);
		h.engine.getContext().noteIncident("death", "your death near Castle Wars", "", ms[0]);
		ticks(h, TriggerContext.MEMORY_MIN_AGE_TICKS);
		level(h);
		assertEquals(1, h.firedBy("recall-idle").size());

		ms[0] += 3 * 3_600_000L;
		level(h);
		assertEquals("not again the same day", 1, h.firedBy("recall-idle").size());

		ms[0] += 24 * 3_600_000L;
		level(h);
		assertEquals("the next day", 2, h.firedBy("recall-idle").size());
	}

	@Test
	public void aNewMemoryIsNewThatDay() throws IOException
	{
		Harness h = harness(IDLE_RECALL);
		h.engine.getContext().noteIncident("death", "your death near Castle Wars", "", ms[0]);
		ticks(h, TriggerContext.MEMORY_MIN_AGE_TICKS);
		level(h);
		h.engine.getContext().noteIncident("dog", "the dog in the mausoleum", "", ms[0]);
		ticks(h, TriggerContext.MEMORY_MIN_AGE_TICKS);
		level(h);
		assertEquals(2, h.firedBy("recall-idle").size());
		assertEquals("My mind goes back to the dog in the mausoleum.", h.firedBy("recall-idle").get(1).text);
	}

	@Test
	public void theDayIsKeptWithTheMemory()
	{
		TriggerContext context = new TriggerContext(null);
		context.noteIncident("death", "your death near Castle Wars", "", ms[0]);
		context.noteIncidentRecalled(ms[0]);
		TriggerContext restored = new TriggerContext(null);
		restored.restoreIncident("death", "your death near Castle Wars", 1, 9520, ms[0], "");
		restored.restoreIncidentRecalled(context.getIncidentRecalledMs());
		assertEquals(true, restored.wasIncidentRecalledToday(ms[0] + 3_600_000L));
	}

	@Test
	public void aPlaceIsNotRememberedUntilItsMemoryIsTwentyMinutesOld() throws IOException
	{
		// Real play, 19 Oct: a record hit at sea, then a minute later and
		// back over the same border, "This is where you hit harder than you
		// ever had."
		Harness h = harness(HERE_RECALL);
		h.game.at(3222, 3218, 0);
		ticks(h, 1);
		h.engine.getContext().notePlaceMemory("you hit a 15");
		h.game.at(3222, 3290, 0);
		ticks(h, 2);
		h.game.at(3222, 3218, 0);
		ticks(h, 100);
		assertEquals("not a minute on", 0, h.firedBy("place-remembers").size());

		h.game.at(3222, 3290, 0);
		ticks(h, TriggerContext.MEMORY_MIN_AGE_TICKS);
		h.game.at(3222, 3218, 0);
		ticks(h, 2);
		assertEquals("back twenty minutes on", 1, h.firedBy("place-remembers").size());
	}

	@Test
	public void theIdleRecallIsTwoHoursApart() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		assertEquals(7_200_000L, h.rule("recall-idle").cooldownMs);
	}
}

package com.follower;

import java.time.LocalDate;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The memory surface (R20): what the window claims has to match what the
 * follower actually holds, in both directions - a fresh follower must not be
 * dressed up with history, and a lived-in one must not have its memory
 * understated. The window itself is Swing; the claims are a pure function.
 */
public class MemorySurfaceTest
{
	private static String flat(List<String[]> rows)
	{
		StringBuilder out = new StringBuilder();
		for (String[] row : rows)
		{
			out.append(row[0]);
			if (row[1] != null)
			{
				out.append(": ").append(row[1]);
			}
			out.append('\n');
		}
		return out.toString();
	}

	@Test
	public void aLivedInMemoryShowsItsContents()
	{
		TriggerContext context = new TriggerContext(new FakeGame().client);
		context.setMetOnDay(LocalDate.now().toEpochDay() - 31);
		context.setSessionCount(36);
		context.tally("kill:goblin");
		context.tally("kill:goblin");
		context.noteRecord("hit", 42);
		context.noteIncident("chicken-death", "that chicken", "", System.currentTimeMillis());
		context.notePlaceMemory("the drop");
		context.noteSaidOnce("first-meeting");
		context.noteLineSaid("a line");

		String surface = flat(MemoryDialog.summarise(context,
			java.util.Collections.singletonMap(12850, "Lumbridge town and castle"), key -> key));

		assertTrue(surface.contains("(31 days ago)"));
		assertTrue(surface.contains("Sessions together: 36"));
		assertTrue(surface.contains("Goblin kills: 2"));
		assertTrue(surface.contains("Biggest hit: 42"));
		assertTrue("the incident quoted as its words: " + surface,
			surface.contains("\"that chicken, just now\" (x1)"));
		assertFalse("and not by its file key: " + surface, surface.contains("chicken-death"));
		assertFalse("no place likes or dislikes in this build: " + surface, surface.contains("PLACES"));
		assertTrue(surface.contains("One-time lines already said: 1"));
		assertTrue(surface.contains("Lines counted, to vary them: 1"));
	}


	@Test
	public void killCountsShowThisAccountsOneRowPerBoss()
	{
		// QA pass 4, #15 and #42: the old profile-wide count, this account's
		// and an alt's all showed, under one label with three numbers.
		TriggerContext context = new TriggerContext(new FakeGame().client);
		context.noteRecord("kc:zulrah", 150);
		context.noteRecord("hit", 42);
		context.noteRecord("kc:zulrah@1234567890", 151);
		context.noteRecord("kc:zulrah@9876543210", 12);
		context.noteRecord("kc:vorkath@9876543210", 3);

		String mine = flat(MemoryDialog.summarise(context, java.util.Collections.emptyMap(),
			key -> key + "@1234567890"));
		assertTrue(mine, mine.contains("Zulrah kill count: 151\n"));
		assertEquals(mine, 1, mine.split("kill count", -1).length - 1);
		assertTrue(mine, mine.contains("Biggest hit: 42\n"));

		// An account with none of its own reads the old count, as the book does.
		String another = flat(MemoryDialog.summarise(context, java.util.Collections.emptyMap(),
			key -> key + "@5555"));
		assertTrue(another, another.contains("Zulrah kill count: 150\n"));
		assertEquals(another, 1, another.split("kill count", -1).length - 1);

		// Only another account's counts: nothing of this one's to show.
		context.getRecords().remove("hit");
		context.getRecords().remove("kc:zulrah");
		String none = flat(MemoryDialog.summarise(context, java.util.Collections.emptyMap(),
			key -> key + "@5555"));
		assertTrue(none, none.contains("No records held yet."));
	}

	@Test
	public void aBossIsNamedAsTheGameWritesIt()
	{
		// QA pass 4, #54: "Tztok-jad kill count", from the lower-case key.
		TriggerContext context = new TriggerContext(new FakeGame().client);
		context.noteRecord("kc:tztok-jad@main", 5);
		context.noteKillCountName("TzTok-Jad");
		String shown = flat(MemoryDialog.summarise(context, java.util.Collections.emptyMap(),
			key -> key + "@main"));
		assertTrue(shown, shown.contains("TzTok-Jad kill count: 5\n"));
	}

	@Test
	public void countsAndBestsAreNamedInWords()
	{
		// QA, 15 Oct: the window showed the keys the plugin files them under.
		assertEquals("Goblin kills", MemoryDialog.keyLabel("kill:goblin"));
		assertEquals("Hill giant kills", MemoryDialog.keyLabel("kill:hill giant"));
		assertEquals("Kills", MemoryDialog.keyLabel("kills"));
		assertEquals("Kills today", MemoryDialog.keyLabel("kills" + TriggerContext.TODAY));
		assertEquals("Levels gained today", MemoryDialog.keyLabel("levels:today"));
		assertEquals("Deaths today", MemoryDialog.keyLabel("deaths:today"));
		assertEquals("Outings taken", MemoryDialog.keyLabel("want:kept"));
		assertEquals("Outings missed", MemoryDialog.keyLabel("want:missed"));
		assertEquals("Zulrah kill count", MemoryDialog.keyLabel("kc:zulrah"));
		assertEquals("Zulrah kill count", MemoryDialog.keyLabel("kc:zulrah@main"));
		assertEquals("Biggest hit", MemoryDialog.keyLabel("hit"));
		assertEquals("Longest session (minutes)", MemoryDialog.keyLabel("session"));
		assertEquals("Quests completed", MemoryDialog.keyLabel("quests"));
		assertEquals("Music tracks unlocked", MemoryDialog.keyLabel("music"));
		assertEquals("Collection log items", MemoryDialog.keyLabel("collections"));
		assertEquals("a key with no words is shown as it is",
			"someone:else", MemoryDialog.keyLabel("someone:else"));
		assertEquals("kill:", MemoryDialog.keyLabel("kill:"));
	}

	@Test
	public void everyKeyThePluginFilesHasWords() throws java.io.IOException
	{
		// A new tally or record written without words here would show raw
		// again. The keys are read out of the source that writes them.
		StringBuilder source = new StringBuilder();
		for (String file : new String[]{"src/main/java/com/follower/FollowerPlugin.java",
			"src/main/java/com/follower/SpeechEngine.java"})
		{
			source.append(PublicMarkers.strip(new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(file)),
				java.nio.charset.StandardCharsets.UTF_8)));
		}
		java.util.regex.Matcher m = java.util.regex.Pattern.compile(
			"(?:\\.tally|tallyBoth|noteRecord)\\(\\s*\"([^\"]+)\"|\\? \"(\\w+:\\w+)\" : \"(\\w+:\\w+)\"")
			.matcher(source);
		int found = 0;
		while (m.find())
		{
			for (int g = 1; g <= 3; g++)
			{
				String key = m.group(g);
				if (key != null)
				{
					// A prefix ("kill:" + the name) is checked with a name on.
					key = key.endsWith(":") ? key + "goblin" : key;
					found++;
					assertFalse(key + " has no words in the Memory window",
						key.equals(MemoryDialog.keyLabel(key)));
				}
			}
		}
		assertTrue("the lint found nothing to check - the pattern has lost its place", found >= 10);
	}

	@Test
	public void firstMetCountsTodayAndOneDayPlainly()
	{
		TriggerContext context = new TriggerContext(new FakeGame().client);
		long today = LocalDate.now().toEpochDay();

		context.setMetOnDay(today);
		assertTrue(flat(MemoryDialog.summarise(context, java.util.Collections.emptyMap(), key -> key))
			.contains("First met: " + LocalDate.ofEpochDay(today) + " (today)\n"));

		context.setMetOnDay(today - 1);
		assertTrue(flat(MemoryDialog.summarise(context, java.util.Collections.emptyMap(), key -> key))
			.contains("First met: " + LocalDate.ofEpochDay(today - 1) + " (1 day ago)\n"));

		context.setMetOnDay(today - 2);
		assertTrue(flat(MemoryDialog.summarise(context, java.util.Collections.emptyMap(), key -> key))
			.contains("First met: " + LocalDate.ofEpochDay(today - 2) + " (2 days ago)\n"));
	}

	@Test
	public void aQuestionWaitingIsSaidInWordsNotByItsId()
	{
		// Text sweep, 14 Oct: the window showed "want-outing". A tree of the
		// player's own still shows its id, having nothing better to show.
		TriggerContext context = new TriggerContext(new FakeGame().client);
		context.noteQuestion("want-outing");
		String shown = flat(MemoryDialog.summarise(context, java.util.Collections.emptyMap(), key -> key));
		assertTrue(shown, shown.contains("Waiting on an answer: Whether you'll take it somewhere\n"));
		context.noteQuestion("my-own-tree");
		shown = flat(MemoryDialog.summarise(context, java.util.Collections.emptyMap(), key -> key));
		assertTrue(shown, shown.contains("Waiting on an answer: my-own-tree\n"));
	}

	@Test
	public void theNamedCountsShowHoweverManyCreaturesWereKilled()
	{
		// QA pass 5, #28: every kind of creature competed with the named
		// counts for ten rows, and the marks of grace fell off the end.
		TriggerContext context = new TriggerContext(new FakeGame().client);
		for (int kind = 0; kind < 12; kind++)
		{
			for (int n = 0; n < 50 + kind; n++)
			{
				context.tally("kill:creature" + (char) ('a' + kind));
			}
		}
		for (int n = 0; n < 600; n++)
		{
			context.tallyBoth("kills");
		}
		context.tallyBoth("levels");

		String surface = flat(MemoryDialog.summarise(context, java.util.Collections.emptyMap(), key -> key));
		assertTrue(surface, surface.contains("Kills: 600\nKills today: 600\nLevels gained: 1\nLevels gained today: 1\n"));
		assertTrue("the kills by creature, ten of them, most first: " + surface,
			surface.contains("Creaturel kills: 61\n"));
		assertFalse(surface, surface.contains("Creaturea kills"));
		assertTrue(surface, surface.contains("...and 2 more."));
	}

	@Test
	public void aStrangerHasNothingToShow()
	{
		TriggerContext context = new TriggerContext(new FakeGame().client);
		String surface = flat(MemoryDialog.summarise(context, java.util.Collections.emptyMap(), key -> key));

		assertTrue(surface.contains("First met: not recorded yet"));
		assertTrue(surface.contains("Sessions together: 0"));
		assertTrue(surface.contains("Nothing counted yet."));
		assertTrue(surface.contains("No records held yet."));
		assertTrue(surface.contains("Nothing has stuck yet."));
		assertTrue(surface.contains("Nothing in hand."));
		assertTrue(surface.contains("One-time lines already said: 0"));

		// The other direction of honesty: no leftover-looking claims.
		assertFalse(surface.contains("x1"));
		assertFalse(surface.contains("Hoping for"));
	}
}

package com.follower;

import com.google.gson.Gson;
import java.util.Arrays;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Everything the follower remembers, written out and read back.
 *
 * <p>Nothing verified this before, and the cost of a field written but never
 * read is completely silent: the follower forgets one thing forever and the
 * only symptom is behaviour that quietly resets every restart. The one-time
 * lines make it worse than it used to be - if the spent set does not survive,
 * the follower introduces itself as a stranger every single session, which is
 * the exact opposite of the thing it was added to do.
 *
 * <p>The saved shape stays private to the plugin. The seam here is a string in
 * and a string out, which is what actually crosses the disk.
 */
public class MemorySurvivesRestartTest
{
	private final Gson gson = new Gson();

	private TriggerContext fresh()
	{
		return new TriggerContext(new FakeGame().client);
	}

	/** A follower with something of every kind it can remember. */
	private TriggerContext lived()
	{
		TriggerContext context = fresh();
		context.tally("kill:goblin");
		context.tally("kill:goblin");
		context.tally("advice:taken");
		context.noteRecord("hit", 42);
		context.noteRecord("session", 238);
		context.noteKillCountName("TzTok-Jad");
		context.setSessionCount(36);
		context.noteIncident("chicken-death", "that chicken", "Chicken", 1_700_000_000_000L);
		context.notePlaceMemory("the drop");
		context.noteSaidOnce("first-meeting");
		context.noteSaidOnce("first-page");
		context.noteLineSaid("A line said twice.");
		context.noteLineSaid("A line said twice.");
		context.setMetOnDay(20_400L);
		context.setMetWearingValue(1_234);
		context.restoreDeathSpot(new WorldPoint(3200, 3200, 1));
		context.noteLevel("Fishing", 70, 1_700_000_000_000L);
		context.noteDoing("fighting Vorkath");
		return context;
	}

	@Test
	public void theIncidentKeepsWhereItHappened()
	{
		// Where is what the standing-there recall and the Memory window's
		// "in Edgeville" both read. The fixture above files its incident
		// before the context has seen a region, so it is asked here of one
		// filed somewhere.
		TriggerContext before = new TriggerContext(new FakeGame().at(3090, 3490, 0).client);
		before.refresh();
		before.noteIncident("close-call", "how close that was", "Hill Giant", 1_700_000_000_000L);
		assertEquals("filed in Edgeville", 12342, before.getIncidentWhere());

		TriggerContext after = fresh();
		FollowerPlugin.restoreMemory(after, FollowerPlugin.snapshotMemory(before, 0, gson), gson, 0);
		assertEquals("and still there after a restart", 12342, after.getIncidentWhere());
	}

	@Test
	public void everythingWrittenComesBack()
	{
		TriggerContext before = lived();
		String blob = FollowerPlugin.snapshotMemory(before, 1_234, gson);

		TriggerContext after = fresh();
		int metWearing = FollowerPlugin.restoreMemory(after, blob, gson, 0);

		assertEquals("tallies", 2, after.getTally("kill:goblin"));
		assertEquals("tallies", 1, after.getTally("advice:taken"));
		assertEquals("records", 42, after.getRecord("hit"));
		assertEquals("records", 238, after.getRecord("session"));
		assertEquals("a boss's name as the game writes it", "TzTok-Jad",
			after.getKillCountNames().get("tztok-jad"));
		assertEquals("sessions", 36, after.getSessionCount());
		assertEquals("the incident", "that chicken", after.getIncidentPhrase());
		assertEquals("who it was with", "Chicken", after.getIncidentWho());
		assertEquals("when", 1_700_000_000_000L, after.getIncidentWhenMs());
		assertEquals("the first meeting", 20_400L, after.getMetOnDay());
		assertEquals("what you were wearing when it met you", 1_234, metWearing);
		assertEquals("where you died", new WorldPoint(3200, 3200, 1),
			after.getDeathLocation());
		assertEquals("when Fishing last went up", Long.valueOf(1_700_000_000_000L),
			after.getLevelStamps().get("fishing"));
		assertEquals("what you were doing last time", "fighting Vorkath",
			after.getLastTime());

		// The one that would be silent if it broke.
		assertTrue("a spent introduction has to survive a restart",
			after.hasSaidOnce("first-meeting"));
		assertTrue(after.hasSaidOnce("first-page"));
		assertFalse("and nothing else should come back spent",
			after.hasSaidOnce("first-hour"));

		// Line wear resetting every restart would make retirement (R17) a
		// per-session mechanism, which is to say no mechanism at all.
		assertEquals("how worn a line is has to survive too",
			2, after.lineWear("A line said twice."));
		assertEquals("and unheard lines stay unheard",
			0, after.lineWear("A line never said."));
	}

	@Test
	public void theWearLedgerStaysASensibleSize()
	{
		// The blob this rides in is written every few minutes for as long as
		// the client is open; an unbounded map would grow it forever. The cap
		// drops the least-worn entries - the ones farthest from ever standing
		// a line aside.
		TriggerContext context = fresh();
		context.noteLineSaid("the favourite");
		context.noteLineSaid("the favourite");
		context.noteLineSaid("the favourite");
		for (int i = 0; i < 700; i++)
		{
			context.noteLineSaid("filler line " + i);
		}

		assertTrue("the ledger must stay capped, was " + context.getLineWear().size(),
			context.getLineWear().size() <= 500);
		assertEquals("and the most-worn entries are the ones kept",
			3, context.lineWear("the favourite"));
	}

	@Test
	public void aSecondRoundTripChangesNothing()
	{
		// Save, load, save. The two blobs have to agree, or something is being
		// dropped or duplicated on every restart rather than only on the first.
		TriggerContext before = lived();
		String first = FollowerPlugin.snapshotMemory(before, 1_234, gson);

		TriggerContext middle = fresh();
		int metWearing = FollowerPlugin.restoreMemory(middle, first, gson, 0);
		String second = FollowerPlugin.snapshotMemory(middle, metWearing, gson);

		assertEquals("the follower's memory is not stable across a restart",
			first, second);
	}

	@Test
	public void aFollowerThatHasDoneNothingSavesAndLoadsCleanly()
	{
		String blob = FollowerPlugin.snapshotMemory(fresh(), 0, gson);
		TriggerContext after = fresh();
		assertEquals(0, FollowerPlugin.restoreMemory(after, blob, gson, 0));
		assertEquals(0, after.getSessionCount());
		assertTrue(after.getSpokenOnce().isEmpty());
	}

	@Test
	public void nothingIsLostToAMissingFieldFromAnOlderVersion()
	{
		// Every user upgrading arrives with a blob written by the previous
		// build, which has no spokenOnce in it at all. That must read as "has
		// said nothing yet" rather than throwing and costing them everything
		// else in the same blob.
		String older = "{\"tallies\":{\"kill:rat\":3},\"records\":{\"hit\":9},"
			+ "\"sessions\":12,\"metOnDay\":20400,\"deathPlane\":-1}";

		TriggerContext after = fresh();
		FollowerPlugin.restoreMemory(after, older, gson, 0);

		assertEquals("the rest of an older blob still has to load", 3,
			after.getTally("kill:rat"));
		assertEquals(12, after.getSessionCount());
		assertTrue("a missing spent-set reads as nothing said yet",
			after.getSpokenOnce().isEmpty());
		assertFalse(after.hasSaidOnce("first-meeting"));
	}

	@Test
	public void aBlobWithANicknameAndPlaceOpinionsLoadsInEveryBuild()
	{
		// What the full build (and 1.4.1) writes. The public build may leave
		// the nickname and the place opinions out; the blob still has to load
		// there, the rest of it with it.
		String full = "{\"tallies\":{\"kill:rat\":3},\"sessions\":12,\"deathPlane\":-1,"
			+ "\"placeScores\":{\"12850\":45},\"placeMemories\":{\"12850\":\"the drop\"},"
			+ "\"nickname\":\"the swot\",\"refusedNicknames\":[\"the gravedigger\"],"
			+ "\"nicknameAskedMs\":1700000000000,\"nicknameAsksIgnored\":2}";

		TriggerContext after = fresh();
		FollowerPlugin.restoreMemory(after, full, gson, 0);

		assertEquals(3, after.getTally("kill:rat"));
		assertEquals(12, after.getSessionCount());
		assertEquals("the drop", after.getPlaceMemories().get(12850));
	}

	@Test
	public void ruinedMemoryCostsTheMemoryAndNotTheSession()
	{
		// A corrupt value is sad but survivable. Refusing to start over it
		// would not be.
		TriggerContext after = fresh();
		int metWearing = FollowerPlugin.restoreMemory(after, "{not json at all",
			gson, 77);

		assertEquals("a corrupt blob must fall back rather than throw", 77, metWearing);
		assertEquals(0, after.getSessionCount());
	}

	@Test
	public void anEmptyOrAbsentBlobIsNotAnError()
	{
		assertEquals(5, FollowerPlugin.restoreMemory(fresh(), null, gson, 5));
		assertEquals(5, FollowerPlugin.restoreMemory(fresh(), "", gson, 5));
		assertEquals(5, FollowerPlugin.restoreMemory(fresh(), "null", gson, 5));
	}

	@Test
	public void theSpentSetSurvivesTheOrderItWasWrittenIn()
	{
		// It is a Set in memory and a List on disk, which is exactly the shape
		// where an ordering assumption can creep in unnoticed.
		TriggerContext before = fresh();
		for (String id : Arrays.asList("first-return", "first-meeting", "first-hour"))
		{
			before.noteSaidOnce(id);
		}
		String blob = FollowerPlugin.snapshotMemory(before, 0, gson);

		TriggerContext after = fresh();
		FollowerPlugin.restoreMemory(after, blob, gson, 0);
		assertEquals(3, after.getSpokenOnce().size());
		for (String id : Arrays.asList("first-return", "first-meeting", "first-hour"))
		{
			assertTrue(id + " was lost across the restart", after.hasSaidOnce(id));
		}
	}
	@Test
	public void memoryIsOnlyEverWrittenToTheProfileItCameFrom()
	{
		// Issue #1: a RuneLite profile switch announces its changed keys with
		// the new profile already current, and every write in that window
		// filed the old profile's state under the new one. Unread state is
		// never written either: there is nothing to write.
		assertTrue(FollowerPlugin.belongsToProfile(7L, 7L));
		assertFalse("another profile is current", FollowerPlugin.belongsToProfile(7L, 8L));
		assertFalse("nothing read yet", FollowerPlugin.belongsToProfile(-1L, -1L));
		assertFalse(FollowerPlugin.belongsToProfile(-1L, 3L));
	}


	@Test
	public void theRestFromRecallingSurvives()
	{
		// Text QA5: the nickname asked again at every login, and one memory
		// brought up at every one; both rests are kept with the memory.
		TriggerContext before = lived();
		before.noteIncidentRecalled(1_700_000_100_000L);
		TriggerContext after = fresh();
		FollowerPlugin.restoreMemory(after, FollowerPlugin.snapshotMemory(before, 0, gson), gson, 0);
		assertEquals(1_700_000_100_000L, after.getIncidentRecalledMs());
	}
}

package com.follower;

import java.io.IOException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The things the follower is supposed to remember between one session and the
 * next.
 *
 * <p>A count that resets on logout is a scoreboard for the current game. The
 * whole value of "your fiftieth" is that the fifty were since you met, so the
 * parts that make that true - the merge on restore, the records that only move
 * up, the first-ever value that seeds silently - are what is checked here.
 */
public class MemoryTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void restoringCountersAddsToWhatIsAlreadyCounted() throws IOException
	{
		// The restore happens a few ticks into a login, and a kill can land
		// first. Overwriting would throw that kill away.
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().tally("kill:rat");

		Map<String, Integer> saved = new HashMap<>();
		saved.put("kill:rat", 40);
		h.engine.getContext().restoreCounters(saved, null);

		assertEquals("a restore must add to the session, not replace it",
			41, h.engine.getContext().getTally("kill:rat"));
	}

	@Test
	public void restoringRecordsKeepsTheBetterOfTheTwo() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().noteRecord("hit", 60);

		Map<String, Integer> saved = new HashMap<>();
		saved.put("hit", 42);
		h.engine.getContext().restoreCounters(null, saved);

		assertEquals("a stale saved record must not undo a better live one",
			60, h.engine.getContext().getRecord("hit"));
	}

	@Test
	public void theFirstValueEverSeenIsNotAPersonalBest() throws IOException
	{
		// Otherwise every new install announces a record on its first hit,
		// which makes the feature look broken to every new user at once.
		TriggerContext context = new Harness(folder.newFolder().toPath())
			.engine.getContext();

		assertFalse("the first measurement is the only measurement",
			context.noteRecord("hit", 30));
		assertEquals("it is still stored, though", 30, context.getRecord("hit"));
		assertFalse("and beaten is beaten, not equalled", context.noteRecord("hit", 30));
		assertTrue("beating it is the news", context.noteRecord("hit", 31));
	}

	// ------------------------------------------------------- shipped rules

	@Test
	public void theSessionMilestoneLandsOnTheExactNumber() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		// A login's hello holds the floor a few seconds: logins a day apart.
		long[] ms = {1_700_000_000_000L};
		h.engine.setClock(() -> ms[0]);
		h.gameTicks(1);

		// These carry a delayTicks, so the line lands some ticks after the win.
		h.engine.getContext().setSessionCount(99);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		h.gameTicks(20);
		assertTrue("ninety-nine is not a hundred", h.firedBy("session-100").isEmpty());
		ms[0] += 86_400_000L;

		h.engine.getContext().setSessionCount(100);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		h.gameTicks(20);
		assertFalse("the hundredth session", h.firedBy("session-100").isEmpty());
		ms[0] += 86_400_000L;

		h.clear();
		h.engine.getContext().setSessionCount(101);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		h.gameTicks(20);
		assertTrue("and never again after", h.firedBy("session-100").isEmpty());
	}

	@Test
	public void theRecordLineNamesBothNumbers() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.dispatch(TriggerEvent.record("hit", 71, 54));
		h.gameTicks(2);
		// QA3: its about says never on the first day, and the hits of a
		// first fight beat each other every few seconds.
		assertTrue("not on the day you met", h.firedBy("record-hit").isEmpty());

		h.engine.getContext().setMetOnDay(java.time.LocalDate.now().toEpochDay() - 1);
		h.dispatch(TriggerEvent.record("hit", 71, 54));

		List<Harness.Spoken> said = h.firedBy("record-hit");
		assertFalse("a new biggest hit is worth saying", said.isEmpty());
		String line = said.get(0).text;
		assertTrue("the new mark has to appear: " + line, line.contains("71"));
		assertFalse("and nothing may print as a literal placeholder: " + line,
			line.contains("{"));
	}

	@Test
	public void dyingOftenReadsDifferentlyFromDyingOnce() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		// The moment of a death holds the floor a couple of seconds.
		long[] ms = {1_700_000_000_000L};
		h.engine.setClock(() -> ms[0]);
		h.gameTicks(1);

		h.dispatch(TriggerEvent.death());
		h.gameTicks(10);
		assertTrue("the first death is not a pattern", h.firedBy("deaths-many").isEmpty());

		for (int i = 0; i < 12; i++)
		{
			h.engine.getContext().tally("deaths");
		}
		h.gameTicks(200);
		ms[0] += 120_000L;
		h.clear();
		h.dispatch(TriggerEvent.death());
		h.gameTicks(10);
		assertFalse("a dozen deaths is a pattern", h.firedBy("deaths-many").isEmpty());
	}
}

package com.follower;

import java.io.IOException;
import java.lang.reflect.Proxy;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The follower's menu belongs to the game scene, not to whatever interface is
 * drawn over it. QA, 15 Oct: its clickbox is a projection and goes on under
 * the bank, the inventory and the chatbox, so Talk-to took the left-click
 * from a bank item, the follower's options sat above the item's own, and
 * shift-click drop was swallowed. The game offers Walk here only over the
 * scene, so that is the test, as Send has always used it.
 *
 * <p>The handlers need a client and an event bus the harness does not have,
 * so, as in {@link LifecycleGlueTest}, the reading is kept as a lint.
 */
public class MenuOverTheSceneTest
{
	private static final Path PLUGIN = Paths.get("src/main/java/com/follower/FollowerPlugin.java");

	private static String source() throws IOException
	{
		assertTrue("cannot read " + PLUGIN, Files.isRegularFile(PLUGIN));
		return PublicMarkers.strip(new String(Files.readAllBytes(PLUGIN), StandardCharsets.UTF_8).replace("\r\n", "\n"));
	}

	/** The plugin's members, split where one closes at the class's own depth. */
	private static String[] members() throws IOException
	{
		return source().split("\n\t\\};?\n");
	}

	private static MenuEntry entry(MenuAction type)
	{
		return (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(),
			new Class<?>[]{MenuEntry.class},
			(proxy, method, args) -> "getType".equals(method.getName()) ? type : null);
	}

	@Test
	public void aMenuWithWalkHereIsTheScenes()
	{
		assertTrue(FollowerPlugin.offersWalkHere(new MenuEntry[]{
			entry(MenuAction.CANCEL), entry(MenuAction.WALK), entry(MenuAction.RUNELITE)}));
		assertFalse("an inventory slot's menu", FollowerPlugin.offersWalkHere(new MenuEntry[]{
			entry(MenuAction.CANCEL), entry(MenuAction.CC_OP), entry(MenuAction.CC_OP)}));
		assertFalse(FollowerPlugin.offersWalkHere(new MenuEntry[0]));
		assertFalse(FollowerPlugin.offersWalkHere(null));
	}

	/**
	 * QA, 15 Oct: the hover Talk-to goes on top of the menu, so it took the
	 * left-click from a bank booth, a tree, an NPC to attack. It is offered
	 * over bare ground only.
	 */
	@Test
	public void theHoverTalkToIsOfferedOverBareGroundOnly() throws IOException
	{
		assertTrue("bare ground", FollowerPlugin.onlyGroundUnder(new MenuEntry[]{
			entry(MenuAction.CANCEL), entry(MenuAction.WALK)}));
		assertTrue("a plugin's own entry is not the world's", FollowerPlugin.onlyGroundUnder(new MenuEntry[]{
			entry(MenuAction.CANCEL), entry(MenuAction.WALK), entry(MenuAction.RUNELITE)}));
		assertFalse("a bank booth", FollowerPlugin.onlyGroundUnder(new MenuEntry[]{
			entry(MenuAction.CANCEL), entry(MenuAction.WALK), entry(MenuAction.EXAMINE_OBJECT),
			entry(MenuAction.GAME_OBJECT_FIRST_OPTION)}));
		assertFalse("an NPC", FollowerPlugin.onlyGroundUnder(new MenuEntry[]{
			entry(MenuAction.CANCEL), entry(MenuAction.WALK), entry(MenuAction.NPC_SECOND_OPTION)}));
		assertFalse("a player", FollowerPlugin.onlyGroundUnder(new MenuEntry[]{
			entry(MenuAction.CANCEL), entry(MenuAction.WALK), entry(MenuAction.PLAYER_FIRST_OPTION)}));
		assertFalse("an item on the ground", FollowerPlugin.onlyGroundUnder(new MenuEntry[]{
			entry(MenuAction.CANCEL), entry(MenuAction.WALK), entry(MenuAction.GROUND_ITEM_THIRD_OPTION)}));
		assertFalse(FollowerPlugin.onlyGroundUnder(null));

		String tick = source().substring(source().indexOf("void onClientTick("));
		tick = tick.substring(0, tick.indexOf("\n\t}\n"));
		int added = tick.indexOf("addFollowerMenuEntry(talkOption()");
		assertTrue("the hover entry has moved - the lint has lost its place", added >= 0);
		assertTrue("the hover entry asks what else is under the mouse first",
			tick.substring(0, added).contains("onlyGroundUnder("));
	}

	@Test
	public void everyLookUnderTheMouseAsksWhetherItIsOverTheScene() throws IOException
	{
		List<String> unguarded = new ArrayList<>();
		int found = 0;
		for (String member : members())
		{
			int at = member.indexOf("follower.isUnderMouse(");
			if (at < 0)
			{
				continue;
			}
			found++;
			if (!member.substring(at).contains("offersWalkHere("))
			{
				unguarded.add(member.substring(Math.max(0, member.lastIndexOf("\n\t", at) - 200), at).trim());
			}
		}
		assertTrue("no look under the mouse found at all - the lint has lost its place", found >= 4);
		assertTrue("the follower under the mouse is not the follower clicked while an interface"
			+ " covers it:\n" + String.join("\n---\n", unguarded), unguarded.isEmpty());
	}

	@Test
	public void noEntryIsAddedBeforeTheMenuIsKnownToBeTheScenes() throws IOException
	{
		List<String> unguarded = new ArrayList<>();
		int found = 0;
		for (String member : members())
		{
			if (member.contains("void addFollowerMenuEntry("))
			{
				continue;
			}
			int first = -1;
			for (String add : new String[]{"addFollowerMenuEntry(", "createMenuEntry("})
			{
				int at = member.indexOf(add);
				if (at >= 0 && (first < 0 || at < first))
				{
					first = at;
				}
			}
			if (first < 0)
			{
				continue;
			}
			found++;
			if (!member.substring(0, first).contains("offersWalkHere("))
			{
				unguarded.add(member.substring(Math.max(0, first - 300), first).trim());
			}
		}
		assertTrue("no menu entries added at all - the lint has lost its place", found >= 3);
		assertTrue("a menu entry added without asking whether the menu is the scene's:\n"
			+ String.join("\n---\n", unguarded), unguarded.isEmpty());
	}
}

package com.follower;

import com.google.gson.Gson;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.FileTime;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

/**
 * The bundled rules are merged into the player's file only when one of the
 * two has changed since the last merge. Every start re-read three large
 * files and rewrote the 590 KB base when there was nothing to do: 70-100 ms
 * of each start on the Swing thread (perf audit, Oct 2026, #59).
 */
public class MergeOnlyWhenSomethingChangedTest
{
	private static final Gson GSON = new Gson();

	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void aStartWithNothingNewMergesNothing() throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Path base = dir.resolve(RuleLoader.BASE_FILE);
		Path phrases = dir.resolve(RuleLoader.FILE_NAME);
		new RuleLoader(GSON).initialise(dir, true);
		new RuleLoader(GSON).initialise(dir, true);
		FileTime marked = FileTime.fromMillis(1_000_000_000_000L);
		Files.setLastModifiedTime(base, marked);

		new RuleLoader(GSON).initialise(dir, true);
		assertEquals("nothing new: the base is not written again", marked, Files.getLastModifiedTime(base));

		// The player's file changed since: merged as ever.
		Files.write(phrases, (new String(Files.readAllBytes(phrases), StandardCharsets.UTF_8) + "\n")
			.getBytes(StandardCharsets.UTF_8));
		new RuleLoader(GSON).initialise(dir, true);
		assertNotEquals("the player's file changed", marked, Files.getLastModifiedTime(base));

		// And with the base gone, merged so it is written again.
		Files.setLastModifiedTime(base, marked);
		new RuleLoader(GSON).initialise(dir, true);
		assertEquals(marked, Files.getLastModifiedTime(base));
		Files.delete(base);
		new RuleLoader(GSON).initialise(dir, true);
		assertEquals("the base is written again", true, Files.exists(base));
	}
}

