package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.lang.reflect.Proxy;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.kit.KitType;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * A model the client has never drawn is fetched from the game's servers, and
 * the first ask for it gets nothing. Public QA, 27 Oct, on a fresh install: a
 * new shirt and legs left the follower without a torso or legs for a while,
 * because the look built without them was kept as if it were whole and
 * nothing asked for them again. The service is asked here through a client
 * whose models land when the test says so.
 */
public class ModelDownloadTest
{
	private static final int HAT = 101;
	private static final int SHIRT = 102;
	private static final int LEGS = 103;
	private static final int HAT_MODEL = 5001;
	private static final int SHIRT_MODEL = 5002;
	private static final int LEGS_MODEL = 5003;

	/** The models the client has; every other one is still downloading. */
	private final Set<Integer> landed = new HashSet<>();

	/** How many times a model was asked for, landed or not. */
	private int asks;

	/** What the follower was given to draw, in order. */
	private final List<String> drawn = new ArrayList<>();

	private AppearanceService service;

	@Before
	public void setUp()
	{
		ModelRepository repository = new ModelRepository(new Gson());
		Map<String, ModelRepository.Entry> items = new LinkedHashMap<>();
		items.put(String.valueOf(HAT), worn(HAT_MODEL, KitType.HEAD));
		items.put(String.valueOf(SHIRT), worn(SHIRT_MODEL, KitType.TORSO));
		items.put(String.valueOf(LEGS), worn(LEGS_MODEL, KitType.LEGS));
		repository.addLive(items, new LinkedHashMap<>());

		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "loadModelData":
						asks++;
						return landed.contains(args[0]) ? model(ModelData.class, String.valueOf(args[0])) : null;
					case "mergeModels":
						return model(ModelData.class, Arrays.toString((Object[]) args[0]));
					default:
						return null;
				}
			});
		service = new AppearanceService(new AppearanceComposer(client, repository));
	}

	private static ModelRepository.Entry worn(int model, KitType slot)
	{
		ModelRepository.Entry entry = new ModelRepository.Entry();
		entry.m = new int[]{model, -1, -1};
		entry.wp1 = slot.getIndex();
		return entry;
	}

	/** A model that names its parts when asked, lights into one that does, and copies to itself. */
	private static <T> T model(Class<T> type, String parts)
	{
		return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "toString":
						return parts;
					case "light":
						return model(Model.class, parts);
					default:
						return method.getReturnType().isInstance(proxy) ? proxy : null;
				}
			}));
	}

	private static Outfit dressed()
	{
		Outfit outfit = new Outfit();
		outfit.setItem(KitType.HEAD, HAT);
		outfit.setItem(KitType.TORSO, SHIRT);
		outfit.setItem(KitType.LEGS, LEGS);
		return outfit;
	}

	/** A rebuild, as the plugin asks for one. */
	private void rebuild(Outfit outfit)
	{
		service.request(outfit, appearance -> drawn.add(appearance.getModel().toString()));
	}

	@Test
	public void aShirtAndLegsStillDownloadingAreOnTheFollowerOnceTheyLand()
	{
		landed.add(HAT_MODEL);
		rebuild(dressed());
		assertEquals("drawn with what there was", "[" + HAT_MODEL + "]", drawn.get(0));
		assertFalse("and nothing has landed yet", service.partsArrived());

		landed.add(SHIRT_MODEL);
		landed.add(LEGS_MODEL);
		assertTrue("the tick sees them land", service.partsArrived());
		rebuild(dressed());
		assertEquals("and the same look built again has them",
			"[" + HAT_MODEL + ", " + SHIRT_MODEL + ", " + LEGS_MODEL + "]", drawn.get(1));

		int before = asks;
		assertFalse("nothing is left to watch for", service.partsArrived());
		rebuild(dressed());
		assertEquals("and the whole look is reused as before", 3, drawn.size());
		assertEquals("without asking the client for anything", before, asks);
	}

	@Test
	public void aModelThatNeverLandsIsGivenUpOnAfterAMinute()
	{
		landed.add(HAT_MODEL);
		landed.add(LEGS_MODEL);
		rebuild(dressed());
		for (int tick = 0; tick < AppearanceService.WAIT_TICKS; tick++)
		{
			assertFalse(service.partsArrived());
		}

		int before = asks;
		assertFalse("a minute on, it stops watching", service.partsArrived());
		assertEquals("and stops asking", before, asks);

		// An emote's end, say: the same look built again does not start the wait over.
		rebuild(dressed());
		before = asks;
		assertFalse(service.partsArrived());
		assertEquals(before, asks);
		assertEquals("each build had what there was", 2, drawn.size());
	}

	@Test
	public void anotherLookIsWatchedForAfresh()
	{
		landed.add(HAT_MODEL);
		rebuild(dressed());
		for (int tick = 0; tick <= AppearanceService.WAIT_TICKS; tick++)
		{
			service.partsArrived();
		}

		Outfit bareHeaded = dressed();
		bareHeaded.clear(KitType.HEAD);
		rebuild(bareHeaded);
		landed.add(SHIRT_MODEL);
		assertTrue("a new look is a new wait", service.partsArrived());

		// So is an outfit edit or a login, which clear the cache, of the same look.
		service.invalidate();
		rebuild(dressed());
		for (int tick = 0; tick <= AppearanceService.WAIT_TICKS; tick++)
		{
			service.partsArrived();
		}
		service.invalidate();
		rebuild(dressed());
		landed.add(LEGS_MODEL);
		assertTrue(service.partsArrived());
	}

	@Test
	public void aLookWithNothingLandedYetWaitsRatherThanFailing()
	{
		// Every part new: the build has nothing to draw. It is not a failed
		// build, which would say so and take the follower away.
		rebuild(dressed());
		assertEquals("the follower is left as it was", 0, drawn.size());

		landed.add(SHIRT_MODEL);
		assertTrue(service.partsArrived());
		rebuild(dressed());
		assertEquals("[" + SHIRT_MODEL + "]", drawn.get(0));
	}

	/**
	 * The tick's part is glue no harness drives, so it is read out of the
	 * source, as ParkRememberedTest reads the spawns.
	 */
	@Test
	public void theTickWatchesWhileTheFollowerIsShownAndBeforeItsRespawn() throws IOException
	{
		String source = new String(Files.readAllBytes(
			Paths.get("src/main/java/com/follower/FollowerPlugin.java")), StandardCharsets.UTF_8);
		String tick = source.substring(source.indexOf("if (rebuildQueued)"));
		int hide = tick.indexOf("if (shouldHide())");
		int watch = tick.indexOf("else if (appearanceService.partsArrived())");
		assertTrue("not while it is hidden, which would only take it away again",
			hide >= 0 && hide < watch);
		assertTrue("and ahead of the bare respawn, which would bring back the unfinished look",
			watch < tick.indexOf("spawnFollower(appearanceService.getCurrent(), local, false);"));
	}
}

package com.follower;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarPlayerID;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The moments, driven tick by tick: a level clapped or walked over for,
 * the pet visited, the second wind, the stranger peered at - and, for each,
 * the feet handed back afterwards, the seat excused and retaken, and
 * nothing at all when the company is switched off.
 */
public class MomentsTest
{
	/** Records what the follower was asked to do; does none of it. */
	private static final class RecordingFollower extends FollowerEntity
	{
		boolean spawned = true;
		WorldPoint stayingAt;
		WorldPoint facing;
		boolean following = true;
		int poseOverride;
		int movedToFront;
		boolean moving;
		boolean agility;
		final List<Integer> animations = new ArrayList<>();
		final List<WorldPoint> stays = new ArrayList<>();
		final List<WorldPoint> glances = new ArrayList<>();

		RecordingFollower()
		{
			super(null, null);
		}

		@Override
		public boolean isSpawned()
		{
			return spawned;
		}

		@Override
		public boolean isSettled()
		{
			return true;
		}

		@Override
		public boolean isMoving()
		{
			return moving;
		}

		@Override
		public boolean isDoingAgility()
		{
			return agility;
		}

		@Override
		public boolean isStaying()
		{
			return stayingAt != null;
		}

		@Override
		public WorldPoint getWorldLocation()
		{
			return stayingAt != null ? stayingAt : new WorldPoint(49, 49, 0);
		}

		/** Every tile is ground here; no test in this class blocks any. */
		@Override
		boolean standable(WorldPoint at)
		{
			return at != null;
		}

		@Override
		public boolean stayAt(WorldPoint target)
		{
			if (target == null)
			{
				return false;
			}
			stayingAt = target;
			following = false;
			stays.add(target);
			return true;
		}

		@Override
		public WorldPoint getStayTile()
		{
			return stayingAt;
		}

		/** Every walk arrives here, as stayAt does. */
		@Override
		public boolean arrivesAt(WorldPoint target)
		{
			return target != null;
		}

		@Override
		public int getPoseOverride()
		{
			return poseOverride;
		}

		@Override
		public void stayHere()
		{
			stayingAt = getWorldLocation();
			following = false;
		}

		@Override
		public void resumeFollowing()
		{
			stayingAt = null;
			facing = null;
			following = true;
		}

		@Override
		public void setStayFaceTile(WorldPoint tile)
		{
			facing = tile;
		}

		@Override
		public void playAnimation(int id)
		{
			animations.add(id);
		}

		@Override
		public void playAnimations(int[] ids)
		{
			for (int id : ids)
			{
				animations.add(id);
			}
		}

		@Override
		public void setPoseOverride(int id)
		{
			poseOverride = id;
		}

		@Override
		public void clearPoseOverride(int id)
		{
			if (poseOverride == id)
			{
				poseOverride = 0;
			}
		}

		@Override
		public void glanceAt(WorldPoint at, int ms)
		{
			glances.add(at);
		}

		@Override
		public boolean moveToFront(net.runelite.api.Player local)
		{
			movedToFront++;
			stayingAt = null;
			return true;
		}
	}

	private static final WorldPoint PLAYER = new WorldPoint(50, 50, 0);
	private static final WorldPoint TREE = new WorldPoint(53, 50, 0);

	/** HUMAN_WOODCUTTING_BRONZE_AXE. */
	private static final int CHOP = 879;

	private FakeGame game;
	private RecordingFollower follower;
	private SkillingController skilling;
	private Moments moments;
	private boolean inCombat;
	private boolean feetTaken;
	private boolean parked;
	private boolean keepsCompany = true;
	private int daysKnown = 30;
	private int tick;
	private PropFlourish flourish;
	private int held;

	/** The left hand's thing of a pair, the quill, or 0. */
	private int heldLeft;
	private boolean grateful;

	@Before
	public void setUp()
	{
		game = new FakeGame().at(PLAYER.getX(), PLAYER.getY(), 0);
		follower = new RecordingFollower();
		FollowerConfig config = new FollowerConfig()
		{
			@Override
			public boolean keepsCompany()
			{
				return keepsCompany;
			}

			@Override
			public boolean borrowsTools()
			{
				return false;
			}
		};
		skilling = new SkillingController(game.client, follower, config,
			new ErrandController.Hands()
			{
				@Override
				public void hold(int itemId)
				{
				}

				@Override
				public void release()
				{
				}
			}, event -> { }, () -> inCombat, () -> feetTaken, () -> false);
		ErrandController.Hands hands = new ErrandController.Hands()
		{
			@Override
			public void hold(int itemId)
			{
				held = itemId;
				heldLeft = 0;
			}

			@Override
			public void hold(int leftItemId, int rightItemId)
			{
				held = rightItemId;
				heldLeft = leftItemId;
			}

			@Override
			public void release()
			{
				held = 0;
				heldLeft = 0;
			}

			@Override
			public boolean isHolding()
			{
				return held != 0;
			}
		};
		flourish = new PropFlourish(follower, hands);
		moments = new Moments(game.client, follower, skilling,
			() -> feetTaken, () -> inCombat, () -> daysKnown, flourish, () -> grateful, () -> parked);
	}

	private void tick(int count)
	{
		for (int i = 0; i < count; i++)
		{
			game.tick(++tick);
			skilling.tick();
			flourish.tick();
			moments.tick();
		}
	}

	/** A woodcutting session with the seat taken. */
	private void takeTheSeat()
	{
		skilling.noteClick("Chop down", "Tree", 1276, TREE, null, null);
		game.animating(CHOP);
		tick(1 + SkillingController.SEAT_AFTER_TICKS);
		assertNotNull("the seat was never taken", skilling.getSeat());
		assertEquals(skilling.getSeat(), follower.stayingAt);
	}

	// --------------------------------------------------------------- level up

	@Test
	public void twoLevelsClapInPlaceAndTheThirdIsWalkedOverFor()
	{
		tick(1);
		moments.levelUp(41);
		moments.levelUp(42);
		assertEquals(Arrays.asList(Moments.CLAP, Moments.CLAP), follower.animations);
		assertEquals("in place", 0, follower.movedToFront);
		assertEquals("facing the player for it", 2, follower.glances.size());
		assertFalse("a clap in place holds nothing", moments.holdsTheFeet());

		follower.animations.clear();
		moments.levelUp(43);
		assertEquals(1, follower.movedToFront);
		assertTrue("the walk is a moment of its own", moments.holdsTheFeet());
		assertTrue("the clap waits for the arrival", follower.animations.isEmpty());

		tick(3);
		assertEquals("clapped on arrival", Collections.singletonList(Moments.CLAP),
			follower.animations);
		tick(4);
		assertFalse("and the feet are handed back after it", moments.holdsTheFeet());
	}

	@Test
	public void aLevelGainedOnTheMoveStopsToClap()
	{
		// QA, 15 Oct: a level gained mid-course had its clap cancelled on the
		// first frame, since moving drops an emote. It stops, then claps.
		tick(1);
		follower.moving = true;
		moments.levelUp(41);
		assertTrue("planted", moments.holdsTheFeet());
		assertFalse(follower.following);
		assertTrue("not on the move: the clap would be dropped", follower.animations.isEmpty());

		follower.moving = false;
		tick(1);
		assertEquals("clapped once stopped", Collections.singletonList(Moments.CLAP), follower.animations);
		assertEquals("in place, no walk", 0, follower.movedToFront);
		tick(3);
		assertFalse("and the feet handed back after it", moments.holdsTheFeet());
		assertTrue(follower.following);
	}

	/**
	 * An Agility level lands as the player finishes an obstacle, with the
	 * follower still on it a couple of ticks behind. The crossing would
	 * cancel the clap on its first frame, so it is owed, and clapped once
	 * the crossing is done (QA4 #10).
	 */
	@Test
	public void aLevelGainedOnAnObstacleIsClappedOnceTheFollowerIsOffIt()
	{
		tick(1);
		follower.agility = true;
		feetTaken = true;
		moments.levelUp(41);
		tick(3);
		assertTrue("nothing played into the crossing", follower.animations.isEmpty());

		follower.agility = false;
		feetTaken = false;
		tick(2);
		assertEquals("clapped once off it", Collections.singletonList(Moments.CLAP), follower.animations);
		tick(3);
		assertFalse("and the feet handed back after it", moments.holdsTheFeet());
		assertTrue(follower.following);
	}

	@Test
	public void anOwedClapIsLetGoAfterTenSeconds()
	{
		tick(1);
		follower.agility = true;
		feetTaken = true;
		moments.levelUp(41);
		tick(Moments.OWED_TICKS + 1);
		follower.agility = false;
		feetTaken = false;
		tick(5);
		assertTrue("the moment has gone", follower.animations.isEmpty());
		assertFalse(moments.holdsTheFeet());
	}

	@Test
	public void theFormalEraBowsInstead()
	{
		daysKnown = 1;
		tick(1);
		moments.levelUp(20);
		assertEquals(Collections.singletonList(Moments.BOW), follower.animations);

		daysKnown = 3;
		follower.animations.clear();
		moments.levelUp(21);
		assertEquals(Collections.singletonList(Moments.CLAP), follower.animations);
	}

	@Test
	public void ninetyNineGetsTheSendOffABossDoes()
	{
		tick(1);
		moments.levelUp(99);
		assertEquals(Arrays.asList(862, 866, 2109), follower.animations);
	}

	@Test
	public void theWalkIsSkippedWhenSomebodyElseHasTheFeet()
	{
		tick(1);
		feetTaken = true;
		moments.levelUp(10);
		moments.levelUp(11);
		moments.levelUp(12);
		assertEquals("the third claps in place instead", 0, follower.movedToFront);
		assertEquals(3, follower.animations.size());
		assertFalse(moments.holdsTheFeet());
	}

	@Test
	public void theSeatIsExcusedForTheWalkAndRetakenAfter()
	{
		takeTheSeat();
		WorldPoint seat = skilling.getSeat();
		int stays = follower.stays.size();

		moments.levelUp(50);
		moments.levelUp(51);
		moments.levelUp(52);
		assertEquals(1, follower.movedToFront);
		assertNull("off the seat", follower.stayingAt);
		tick(1);
		assertEquals("the seat is not retaken under the walk", stays, follower.stays.size());
		assertTrue("but it is still the company's, so no Stay line", skilling.holdsTheFeet());

		tick(6);
		assertFalse(moments.holdsTheFeet());
		tick(1);
		assertEquals("the seat is retaken", seat, follower.stayingAt);
		assertEquals(seat, follower.stays.get(follower.stays.size() - 1));
	}

	// -------------------------------------------------------------------- pet

	private void petDropped()
	{
		moments.noteChatMessage("You have a funny feeling like you're being followed.",
			ChatMessageType.GAMEMESSAGE);
	}

	private NPC petAt(int x, int y)
	{
		NPC pet = game.spawnNpc(6001, "Beaver", 0, true);
		game.moveNpc(pet, x, y, 0);
		moments.npcSpawned(pet);
		return pet;
	}

	@Test
	public void thePetGetsAVisitAndTheWanderKeepsCloseAfter()
	{
		tick(1);
		petDropped();
		NPC pet = petAt(52, 50);
		assertNotNull("walked over to it", follower.stayingAt);
		assertEquals("a tile beside it", 1, follower.stayingAt.distanceTo(new WorldPoint(52, 50, 0)));
		assertEquals("facing it", new WorldPoint(52, 50, 0), follower.facing);
		assertTrue(moments.holdsTheFeet());
		assertTrue(moments.keepsClose());

		tick(5);
		assertEquals("a bend to look at it", Collections.singletonList(Moments.BEND),
			follower.animations);
		tick(3);
		assertTrue("and back", follower.following);
		assertFalse(moments.holdsTheFeet());
		assertTrue(moments.keepsClose());
