	@Test
	public void aFollowerTooLateIsSomebodyElsesPet()
	{
		tick(1);
		petDropped();
		tick(Moments.PET_HUNT_TICKS + 1);
		petAt(52, 50);
		assertNull(follower.stayingAt);
		assertTrue(follower.following);
		assertFalse("no pet, no keeping close", moments.keepsClose());
