	@Test
	public void aStrangerDuringTheSeatExcusesItAndTheSeatComesBack()
	{
		takeTheSeat();
		WorldPoint seat = skilling.getSeat();
		NPC genie = strangerAt(48, 52, 0, false);
		game.npcFacingPlayer(genie);
