package com.follower;

import java.io.IOException;
import net.runelite.api.coords.WorldPoint;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The two things a mood does beyond choosing words, and the guard that keeps
 * the follower's opinion of a place about the place.
 *
 * <p>Both were found by a mutation sweep rather than by review: the sweep said
 * they were covered, and they were not - the run before each had left a compile
 * error behind, so the "failure" that looked like a catch was the build, not a
 * test. Hence these, which fail for the reason they claim to.
 */
public class MoodAndPlaceTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void aBadDayMakesTheFollowerSayLessRatherThanSaySadderThings()
	{
		long base = 3_000L;

		// The point of the feature: the gap is not the same in every mood.
		assertTrue("a low mood has to leave more room than an even one",
			SpeechEngine.gapForMood(base, "low") > SpeechEngine.gapForMood(base, "even"));
		assertTrue("a high mood has to leave less",
			SpeechEngine.gapForMood(base, "high") < SpeechEngine.gapForMood(base, "even"));

		// And it has to be monotonic across the bands, or the follower gets
		// chattier on the way DOWN through one of them.
		long low = SpeechEngine.gapForMood(base, "low");
		long down = SpeechEngine.gapForMood(base, "down");
		long even = SpeechEngine.gapForMood(base, "even");
		long good = SpeechEngine.gapForMood(base, "good");
		long high = SpeechEngine.gapForMood(base, "high");
		assertTrue("low > down > even > good > high",
			low > down && down > even && even > good && good > high);

		// An unknown band is the ordinary gap, not zero: a follower that talked
		// without pause because a band was renamed would be a bad way to find
		// out about the rename.
		assertEquals("an unrecognised band falls back to the plain gap",
			base, SpeechEngine.gapForMood(base, "nonsense"));
		assertEquals(base, SpeechEngine.gapForMood(base, null));
	}


	@Test
	public void aPlaceDoesNotRemindYouOfSomethingYouJustDid() throws IOException
	{
		// Found in a transcript: the follower set a personal best, filed the
		// spot, and five seconds later told the player "this is where you hit
		// harder than you ever had" - to somebody who had not moved. The value
		// of a place memory is entirely in the waiting.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"recall\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"happenedHere\"},"
				+ " \"say\": [\"this is where {here}\"]}]}");

		h.gameTicks(1);
		h.engine.getContext().notePlaceMemory("you hit a 73");
		h.gameTicks(5);
		assertTrue("standing where it happened is not being reminded of it",
			h.firedBy("recall").isEmpty());

		// Leave, come back, twenty minutes on: a minute on is still too fresh.
		h.game.at(2624, 3648, 0);
		h.gameTicks(TriggerContext.MEMORY_MIN_AGE_TICKS);
		h.game.at(3222, 3218, 0);
		h.gameTicks(2);
		assertFalse("coming back is what makes it worth saying",
			h.firedBy("recall").isEmpty());
	}

}

package com.follower;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The follower's mood: one number that gives the lines a state to be said from.
 *
 * <p>Nothing in the engine decides what moves it. Rules carry a nudge and the
 * engine applies it when they fire, which means the mood inherits every trigger
 * the rule format already understands - and a new influence is an edit to
 * phrases.json rather than to any of this.
 */
public class MoodTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/**
	 * Every band name, so a rule naming one that does not exist can be caught.
	 * Kept here, word for word as TriggerContext had it, since only the tests
	 * ever asked for the list.
	 */
	private static java.util.Set<String> moodBands()
	{
		return new java.util.LinkedHashSet<>(
			java.util.Arrays.asList("low", "down", "even", "good", "high"));
	}

	private static String rules(String... bodies)
	{
		return "{\"version\": 1, \"rules\": [" + String.join(",", bodies) + "]}";
	}

	// ---------------------------------------------------------------- the value

	@Test
	public void aSessionStartsEven() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		assertEquals(50, h.engine.getContext().getMood());
		assertEquals("even", h.engine.getContext().getMoodBand());
	}

	@Test
	public void theBandsCoverTheWholeRangeWithNoGaps()
	{
		TriggerContext context = new TriggerContext(new FakeGame().client);
		List<String> seen = new ArrayList<>();
		for (int value = 0; value <= 100; value++)
		{
			context.adjustMood(value - context.getMood());
			String band = context.getMoodBand();
			assertTrue("mood " + value + " is in no band at all",
				moodBands().contains(band));
			if (seen.isEmpty() || !seen.get(seen.size() - 1).equals(band))
			{
				seen.add(band);
			}
		}
		assertEquals("the bands should run low to high in order",
			new ArrayList<>(moodBands()), seen);
	}

	@Test
	public void moodCannotLeaveItsRange()
	{
		TriggerContext context = new TriggerContext(new FakeGame().client);

		context.adjustMood(10000);
		assertEquals("no amount of good news goes past the top", 100, context.getMood());

		context.adjustMood(-10000);
		assertEquals("nor past the bottom", 0, context.getMood());

		assertEquals("and a nudge of nothing changes nothing",
			0, context.adjustMood(0));
	}

	@Test
	public void moodDriftsBackTowardEvenSoNothingIsPermanent() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.engine.getContext().adjustMood(45);
		assertEquals(95, h.engine.getContext().getMood());

		h.gameTicks(600);
		int after = h.engine.getContext().getMood();

		assertTrue("a good stretch should fade, not stick: still at " + after,
			after < 95);
		assertTrue("but not overshoot past even: " + after, after >= 50);
	}

	@Test
	public void aFlatMoodClimbsBackUpTheSameWay() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		h.engine.getContext().adjustMood(-45);
		assertEquals(5, h.engine.getContext().getMood());

		h.gameTicks(600);
		int after = h.engine.getContext().getMood();

		assertTrue("a bad run has to be recoverable by carrying on: " + after,
			after > 5);
		assertTrue(after <= 50);
	}

	@Test
	public void anEvenMoodDoesNotDrift() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(2000);
		assertEquals(50, h.engine.getContext().getMood());
	}

	// --------------------------------------------------------------- the nudge

	@Test
	public void aRuleMovesTheMoodWhenItFires() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"good\", \"group\": \"t\", \"cooldownMs\": 0, \"mood\": 15,"
				+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"a\"]}"));

		h.gameTicks(1);
		h.dispatch(TriggerEvent.death());

		assertEquals(65, h.engine.getContext().getMood());
	}

	@Test
	public void aRuleHeldBackByItsCooldownDoesNotMoveTheMood() throws IOException
	{
		// The state and the words have to stay one story: a rule that said
		// nothing must not have quietly changed how the follower feels.
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"good\", \"group\": \"t\", \"cooldownMs\": 600000, \"mood\": 15,"
				+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"a\"]}"));

		h.gameTicks(1);
		for (int i = 0; i < 10; i++)
		{
			h.dispatch(TriggerEvent.death());
			h.gameTick();
		}

		assertEquals("ten deaths, one line, one nudge", 65, h.engine.getContext().getMood());
	}

	@Test
	public void aRuleInADisabledGroupDoesNotMoveTheMood() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"good\", \"group\": \"off\", \"cooldownMs\": 0, \"mood\": 15,"
				+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"a\"]}"));
		h.engine.setDisabledGroups(java.util.Collections.singleton("off"));

		h.gameTicks(1);
		h.dispatch(TriggerEvent.death());

		assertEquals("a silenced rule must not move the mood either",
			50, h.engine.getContext().getMood());
	}

	// ---------------------------------------------------------------- the gate

	@Test
	public void aRuleCanRequireABand() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"gloomy\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"mood\", \"is\": \"low\"}, \"say\": [\"a\"]}"));

		h.gameTicks(2);
		assertTrue("even is not low", h.firedBy("gloomy").isEmpty());

		h.engine.getContext().adjustMood(-40);
		h.gameTicks(2);
		assertFalse("ten out of a hundred is low", h.firedBy("gloomy").isEmpty());
	}

	@Test
	public void aRuleCanRequireARange() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), rules(
			"{\"id\": \"narrow\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"mood\", \"minimum\": 70, \"maximum\": 75},"
				+ " \"say\": [\"a\"]}"));

		h.engine.getContext().adjustMood(20);
		h.gameTicks(2);
		assertFalse("seventy is inside seventy to seventy-five",
			h.firedBy("narrow").isEmpty());

		h.clear();
		h.engine.getContext().adjustMood(20);
		h.gameTicks(2);
		assertTrue("ninety is outside it", h.firedBy("narrow").isEmpty());
	}

	// ------------------------------------------------------------ the rule set

	@Test
	public void theShippedNudgesAreSignedTheWayTheEventReads() throws IOException
	{
		// A boss kill must not lower the mood and a death must not raise it.
		// Getting a sign backwards would be invisible except as a follower that
		// cheers up when you die.
		Harness h = new Harness(folder.newFolder().toPath());
		java.util.Map<String, Boolean> shouldBePositive = new java.util.HashMap<>();
		shouldBePositive.put("kill-boss-celebrate", true);
		shouldBePositive.put("loot-big", true);
		shouldBePositive.put("loot-nice", true);
		shouldBePositive.put("level-up", true);
		shouldBePositive.put("kill-cheer", true);
		shouldBePositive.put("death-moment", false);
		shouldBePositive.put("death", false);

		for (java.util.Map.Entry<String, Boolean> entry : shouldBePositive.entrySet())
		{
			SpeechRule rule = h.rule(entry.getKey());
			assertTrue(entry.getKey() + " carries no nudge at all", rule.mood != null);
			assertEquals(entry.getKey() + " has the wrong sign",
				entry.getValue(), rule.mood > 0);
		}
	}

	@Test
	public void everyMoodBandNamedByARuleExists() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		List<String> unknown = new ArrayList<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			collectBands(rule, rule.when, unknown);
		}
		assertTrue("rules naming a mood band that does not exist, so they can"
			+ " never fire: " + unknown, unknown.isEmpty());
	}

	private void collectBands(SpeechRule rule, Condition condition,
		List<String> unknown)
	{
		if (condition == null)
		{
			return;
		}
		if ("mood".equalsIgnoreCase(condition.type) && condition.is != null
			&& !moodBands().contains(condition.is))
		{
			unknown.add(rule.id + ": \"" + condition.is + "\"");
		}
		if (condition.conditions != null)
		{
			for (Condition child : condition.conditions)
			{
				collectBands(rule, child, unknown);
			}
		}
	}

	// ------------------------------------------------------------- a session

	@Test
	public void aGoodRunLiftsItAndABadOneDoesNot() throws IOException
	{
		// End to end through the shipped rules: the mood should follow the
		// shape of the session without anything else being told about it.
		Harness good = new Harness(folder.newFolder().toPath());
		good.gameTicks(1);
		for (int i = 0; i < 6; i++)
		{
			good.dispatch(TriggerEvent.kill(2, "Zulrah", 725));
			good.gameTicks(40);
		}
		assertTrue("six boss kills should have cheered it up, mood is "
			+ good.engine.getContext().getMood(),
			good.engine.getContext().getMood() > 55);

		Harness bad = new Harness(folder.newFolder().toPath());
		bad.gameTicks(1);
		for (int i = 0; i < 4; i++)
		{
			bad.dispatch(TriggerEvent.death());
			bad.gameTicks(120);
		}
		assertTrue("four deaths should have flattened it, mood is "
			+ bad.engine.getContext().getMood(),
			bad.engine.getContext().getMood() < 45);
	}

	@Test
	public void everyMoodBandHasAPostureToShowItIn() throws IOException
	{
		// The mood is meant to be READ off the follower, and an idle posture is
		// how that happens without a word. A band with no fidget of its own is
		// a mood that can be reached and never seen.
		Harness h = new Harness(folder.newFolder().toPath());
		java.util.Set<String> covered = new java.util.HashSet<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			if (rule.animation == null || rule.when == null)
			{
				continue;
			}
			for (String band : moodBands())
			{
				if (namesBand(rule.when, band))
				{
					covered.add(band);
				}
			}
		}
		assertEquals("moods with no idle posture: "
				+ new java.util.TreeSet<>(subtract(moodBands(), covered)),
			moodBands().size(), covered.size());
	}

	private static java.util.Set<String> subtract(java.util.Set<String> all,
		java.util.Set<String> covered)
	{
		java.util.Set<String> missing = new java.util.HashSet<>(all);
		missing.removeAll(covered);
		return missing;
	}

	private boolean namesBand(Condition condition, String band)
	{
		if (condition == null)
		{
			return false;
		}
		if ("mood".equalsIgnoreCase(condition.type) && band.equals(condition.is))
		{
			return true;
		}
		if (condition.conditions != null)
		{
			for (Condition child : condition.conditions)
			{
				if (namesBand(child, band))
				{
					return true;
				}
			}
		}
		return false;
	}

	@Test
	public void theLowLinesOnlyTurnUpWhenThingsAreActuallyBad() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(200);
		assertTrue("the gloomy lines must not appear in an ordinary session",
			h.firedBy("mood-low-idle").isEmpty());

		h.engine.getContext().adjustMood(-40);
		h.gameTicks(200);
		assertFalse("and they should appear once it is",
			h.firedBy("mood-low-idle").isEmpty());
	}
}

package com.follower;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Deque;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Mining in a Motherlode tunnel, against the REAL {@link FollowerEntity}.
 *
 * <p>The play report: "while im mining in motherlode mine the follower will
 * walk back and fourth between the tile to my side and the tile behind me".
 * The tunnels are two tiles wide and the veins are in their walls, so the
 * miner's seat - two back and one to the side - is rock. The real pathing
 * does not refuse rock: closest approach stops beside it and reports
 * success. The seat was written down on the rock, found not to be ground
 * on the next tick, dropped, and taken again on the one after, for as long
 * as the player mined. The recording fake in {@link SkillingSessionTest}
 * refuses a blocked tile outright, which is how that loop got past it; this
 * drives the real stay, path and releases, the way {@link FireLineTest} does.
 */
public class MotherlodeSeatTest
{
	/** The tunnel runs north and south, two tiles wide: x 51 and 52. */
	private static final int WEST = 51;
	private static final int EAST = 52;

	/** The vein, in the east wall, and the tile it is worked from. */
	private static final WorldPoint VEIN = new WorldPoint(53, 52, 0);
	private static final WorldPoint WORK = new WorldPoint(52, 52, 0);

	/** HUMAN_MINING_RUNE_PICKAXE_WALL. */
	private static final int MINE_THE_WALL = 6752;

	private final FakeGame game = new FakeGame().withCollision();
	private final FollowerEntity follower = new FollowerEntity(game.client, null);
	private final int[] held = new int[1];

	@Test
	public void theMinersCompanyTakesOneSeatAndStaysOnIt()
	{
		tunnel();

		// Walked up the tunnel to the vein, the follower a tile behind.
		walkIn(new WorldPoint(EAST, 49, 0), new WorldPoint(EAST, 50, 0), new WorldPoint(EAST, 51, 0));
		SkillingController skilling = startMining();
		int[] ticks = {1};
		WorldPoint seat = settle(skilling, ticks);
		int tick = ticks[0];

		// And for as long as the player mines, not a step.
		for (int t = 0; t < 40; t++)
		{
			game.tick(++tick);
			skilling.tick();
			frame();
			assertTrue("still working, tick " + tick, skilling.isWorking());
			assertEquals("the seat never changes, tick " + tick, seat, skilling.getSeat());
			assertEquals("nor the stay, tick " + tick, seat, follower.getStayTile());
			assertEquals("nor where it stands, tick " + tick, seat, tile());
		}
	}

	/**
	 * Two veins side by side in the wall, worked turn about: a step along the
	 * wall to the next vein used to cost the follower a step too, and back
	 * again on the way back, one each time the player switched.
	 */
	@Test
	public void switchingBetweenNeighbouringVeinsIsNoReasonToGetUp()
	{
		tunnel();
		walkIn(new WorldPoint(EAST, 49, 0), new WorldPoint(EAST, 50, 0), new WorldPoint(EAST, 51, 0));
		SkillingController skilling = startMining();
		int[] tick = {1};
		WorldPoint seat = settle(skilling, tick);

		WorldPoint[] veins = {new WorldPoint(53, 53, 0), VEIN, new WorldPoint(53, 53, 0), VEIN};
		for (WorldPoint vein : veins)
		{
			WorldPoint work = new WorldPoint(vein.getX() - 1, vein.getY(), 0);
			skilling.noteClick("Mine", "Ore vein", 26661, vein, vein, null);
			game.at(work.getX(), work.getY(), 0);
			watchPlayer();
			for (int t = 0; t < SkillingController.SEAT_AFTER_TICKS + 4; t++)
			{
				game.tick(++tick[0]);
				skilling.tick();
				frame();
				assertEquals("not a step at " + vein + ", tick " + tick[0], seat, tile());
			}
			assertEquals("the same seat for " + vein, seat, skilling.getSeat());
		}
	}

	/**
	 * Every seat good ground but fenced in, so the pathing only ever gets
	 * beside one. Walking to each to find that out, and letting go when
	 * none arrived, left the last walk queued: out to it and back every
	 * ten ticks, the same shuffle slower. The walk is asked about first.
	 */
	@Test
	public void seatsThatCanOnlyBeApproachedAreNotWalkedTo()
	{
		game.blockTile(VEIN.getX(), VEIN.getY());
		for (WorldPoint c : SkillingController.seatCandidates(WORK, VEIN, VEIN,
			java.util.Collections.emptyList(), "mining"))
		{
			int x = c.getX();
			int y = c.getY();
			game.wallAt(x, y, CollisionDataFlag.BLOCK_MOVEMENT_NORTH
				| CollisionDataFlag.BLOCK_MOVEMENT_EAST | CollisionDataFlag.BLOCK_MOVEMENT_SOUTH
				| CollisionDataFlag.BLOCK_MOVEMENT_WEST);
			game.wallAt(x, y + 1, CollisionDataFlag.BLOCK_MOVEMENT_SOUTH);
			game.wallAt(x + 1, y, CollisionDataFlag.BLOCK_MOVEMENT_WEST);
			game.wallAt(x, y - 1, CollisionDataFlag.BLOCK_MOVEMENT_NORTH);
			game.wallAt(x - 1, y, CollisionDataFlag.BLOCK_MOVEMENT_EAST);
		}

		// Walked in from the west, the follower a tile behind.
		walkIn(new WorldPoint(49, 52, 0), new WorldPoint(50, 52, 0), new WorldPoint(51, 52, 0));
		SkillingController skilling = startMining();
		int tick = 1;
		for (int t = 0; t < 5; t++)
		{
			game.tick(++tick);
			skilling.tick();
			frame();
		}
		WorldPoint stood = tile();

		for (int t = 0; t < 60; t++)
		{
			game.tick(++tick);
			skilling.tick();
			frame();
			assertTrue("still working, tick " + tick, skilling.isWorking());
			assertEquals("not a step, tick " + tick, stood, tile());
		}
		assertTrue("no seat to be had", skilling.getSeat() == null);
	}

	private static final String[] MINE = {"Mine", null, null, null, "Examine"};
	private static final String[] NOTHING = {null, null, null, null, "Examine"};

	/**
	 * The mine as the game has it: veins in the tunnel's east wall, each worked
	 * from the tile across it, which carries the vein's own edge.
	 */
	private void veins(int... ys)
	{
		tunnel();
		game.animation(MINE_THE_WALL, 74);
		for (int y : ys)
		{
			game.placeWall(26661, "Ore vein", MINE, VEIN.getX(), y, 0, 1);
			game.wallAt(EAST, y, CollisionDataFlag.BLOCK_MOVEMENT_EAST);
		}
	}

	private void tickOnce(SkillingController skilling, int[] tick)
	{
		game.tick(++tick[0]);
		skilling.tick();
		frame();
	}

	/**
	 * Play request: "if im in motherloade mine then i would want them to look
	 * like they are harvesting some other ore vein". The player's vein has no
	 * room - its one work tile is theirs - so the company mines the next one
	 * along, from across its wall, facing it, with the pickaxe.
	 */
	@Test
	public void withNoRoomAtItsVeinTheCompanyMinesTheNextOneAlong()
	{
		veins(VEIN.getY(), 54);
		walkIn(new WorldPoint(EAST, 49, 0), new WorldPoint(EAST, 50, 0), new WorldPoint(EAST, 51, 0));
		SkillingController skilling = startMining();
		int[] tick = {1};
		WorldPoint seat = settle(skilling, tick);
		assertEquals("across the next vein's wall", new WorldPoint(EAST, 54, 0), seat);
		assertEquals("facing it", new WorldPoint(53, 54, 0), get("stayFaceTile"));

		tickOnce(skilling, tick);
		assertEquals("mining it", MINE_THE_WALL, follower.getPoseOverride());
		assertEquals("with the pickaxe", 1265, held[0]);
		for (int t = 0; t < 30; t++)
		{
			tickOnce(skilling, tick);
			assertEquals("not a step, tick " + tick[0], seat, tile());
		}
	}

	@Test
	public void whenItsVeinEmptiesItStopsThenMinesAnotherLiveOne()
	{
		veins(VEIN.getY(), 54, 57);
		walkIn(new WorldPoint(EAST, 49, 0), new WorldPoint(EAST, 50, 0), new WorldPoint(EAST, 51, 0));
		SkillingController skilling = startMining();
		int[] tick = {1};
		settle(skilling, tick);
		tickOnce(skilling, tick);
		assertEquals(MINE_THE_WALL, follower.getPoseOverride());

		game.placeWall(26665, "Depleted vein", NOTHING, VEIN.getX(), 54, 0, 1);
		tickOnce(skilling, tick);
		assertEquals("the swing stops with the vein", 0, follower.getPoseOverride());

		WorldPoint next = new WorldPoint(EAST, 57, 0);
		for (int t = 0; t < 20 && !(next.equals(tile()) && follower.getPoseOverride() == MINE_THE_WALL); t++)
		{
			tickOnce(skilling, tick);
		}
		assertEquals("over to the next live vein", next, tile());
		assertEquals("never the emptied one", new WorldPoint(53, 57, 0), get("stayFaceTile"));
		assertEquals("and at it", MINE_THE_WALL, follower.getPoseOverride());
	}

	@Test
	public void thePlayerTakingItsVeinSendsItToAnother()
	{
		veins(VEIN.getY(), 54);
		walkIn(new WorldPoint(EAST, 49, 0), new WorldPoint(EAST, 50, 0), new WorldPoint(EAST, 51, 0));
		SkillingController skilling = startMining();
		int[] tick = {1};
		WorldPoint seat = settle(skilling, tick);
		assertEquals(new WorldPoint(EAST, 54, 0), seat);

		// The player clicks the follower's vein and steps along to work it.
		skilling.noteClick("Mine", "Ore vein", 26661, new WorldPoint(53, 54, 0),
			new WorldPoint(53, 54, 0), null);
		game.at(EAST, 53, 0);
		watchPlayer();
		tickOnce(skilling, tick);
		game.at(EAST, 54, 0);
		watchPlayer();
		for (int t = 0; t < 20 && !(new WorldPoint(EAST, 52, 0).equals(tile())
			&& follower.getPoseOverride() == MINE_THE_WALL); t++)
		{
			tickOnce(skilling, tick);
		}
		assertEquals("to the vein the player left", new WorldPoint(EAST, 52, 0), tile());
		assertEquals(VEIN, get("stayFaceTile"));
		assertEquals(MINE_THE_WALL, follower.getPoseOverride());
	}

	/** Rock all round but for the tunnel, two tiles wide. */
	private void tunnel()
	{
		for (int x = 40; x <= 64; x++)
		{
			for (int y = 40; y <= 64; y++)
			{
				if (x != WEST && x != EAST)
				{
					game.blockTile(x, y);
				}
			}
		}
	}

	/** Seated, and walked there; the seat. */
	private WorldPoint settle(SkillingController skilling, int[] tick)
	{
		WorldPoint seat = null;
		for (int t = 0; t < 20 && (seat == null || !seat.equals(tile())); t++)
		{
			game.tick(++tick[0]);
			skilling.tick();
			frame();
			seat = skilling.getSeat();
		}
		assertTrue("never settled on a seat it stands on: a seat on rock is dropped and"
			+ " taken again every tick", seat != null && seat.equals(tile()));
		assertTrue("on ground, not rock", follower.goodGround(seat));
		return seat;
	}

	/** The player walks in over three tiles to the work, the follower starting where given. */
	private void walkIn(WorldPoint followerAt, WorldPoint first, WorldPoint second)
	{
		game.at(first.getX(), first.getY(), 0);
		set("spawned", true);
		standOn(followerAt);
		set("simTile", followerAt);
		watchPlayer();
		game.at(second.getX(), second.getY(), 0);
		watchPlayer();
		game.at(WORK.getX(), WORK.getY(), 0);
		watchPlayer();
		for (int i = 0; i < 3; i++)
		{
			frame();
		}
	}

	/** The controller, and the click and first swing at the vein. */
	private SkillingController startMining()
	{
		SkillingController skilling = new SkillingController(game.client, follower,
			new FollowerConfig()
			{
			}, new ErrandController.Hands()
			{
				@Override
				public void hold(int itemId)
				{
					held[0] = itemId;
				}

				@Override
				public void release()
				{
					held[0] = 0;
				}

				@Override
				public boolean isHolding()
				{
					return held[0] != 0;
				}

				@Override
				public void wear(int itemId)
				{
				}

				@Override
				public void takeOff()
				{
				}

				@Override
				public boolean isWearing()
				{
					return false;
				}
			}, event -> { }, () -> false, () -> false, () -> false);
		game.tick(1);
		skilling.noteClick("Mine", "Ore vein", 26661, VEIN, VEIN, null);
		game.animating(MINE_THE_WALL);
		return skilling;
	}

	// ---------------------------------------------------------- plumbing

	private Object get(String name)
	{
		try
		{
			Field field = FollowerEntity.class.getDeclaredField(name);
			field.setAccessible(true);
			return field.get(follower);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(name, e);
		}
	}

	private void set(String name, Object value)
	{
		try
		{
			Field field = FollowerEntity.class.getDeclaredField(name);
			field.setAccessible(true);
			field.set(follower, value);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(name, e);
		}
	}

	private Object invoke(String name, Class<?>[] types, Object... args)
	{
		try
		{
			Method method = FollowerEntity.class.getDeclaredMethod(name, types);
			method.setAccessible(true);
			return method.invoke(follower, args);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(name, e);
		}
	}

	private void standOn(WorldPoint at)
	{
		set("tile", at);
		set("fineWX", at.getX() * 128L + 64);
		set("fineWY", at.getY() * 128L + 64);
	}

	private WorldPoint tile()
	{
		return (WorldPoint) get("tile");
	}

	private WorldPoint player()
	{
		return game.client.getLocalPlayer().getWorldLocation();
	}

	private void watchPlayer()
	{
		invoke("watchPlayer", new Class<?>[]{Player.class}, game.client.getLocalPlayer());
	}

	@SuppressWarnings("unchecked")
	private Deque<WorldPoint> path(String name)
	{
		return (Deque<WorldPoint>) get(name);
	}

	/** One tick of updateFrame's feet, in its order, with the player still. */
	private void frame()
	{
		WorldPoint stay = (WorldPoint) get("stayTile");
		WorldPoint follow = (WorldPoint) get("playerFollowTile");
		WorldPoint sim = (WorldPoint) get("simTile");
		if (stay != null)
		{
			if (!stay.equals(tile()) && path("route").isEmpty() && path("serverPath").isEmpty())
			{
				invoke("extendPathBfs", new Class<?>[]{WorldPoint.class, WorldPoint.class}, stay, player());
			}
		}
		else if (path("serverPath").isEmpty() && path("route").isEmpty() && follow != null
			&& !follow.equals(sim))
		{
			invoke("extendPathBfs", new Class<?>[]{WorldPoint.class, WorldPoint.class}, follow,
				follow.equals(player()) ? follow : null);
		}
		if (!path("serverPath").isEmpty())
		{
			invoke("releaseSteps", new Class<?>[]{});
		}
		Deque<WorldPoint> route = path("route");
		@SuppressWarnings("unchecked")
		Deque<Boolean> run = (Deque<Boolean>) get("routeRun");
		while (!route.isEmpty())
		{
			standOn(route.pollFirst());
			run.pollFirst();
		}
	}
}

package com.follower;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * What survives of a typed follower name.
 *
 * <p>The chatbox validator refuses bad characters as they are typed, but
 * pasted text does not go through it, and everything downstream - the menu
 * target, the dialog header, the chat echo - trusts the stored name to hold
 * no tags and no surprises. This is the one gate.
 */
public class NamePromptTest
{
	@Test
	public void ordinaryNamesPassThrough()
	{
		assertEquals("Pip", FollowerPlugin.cleanFollowerName("Pip"));
		assertEquals("Old Bob", FollowerPlugin.cleanFollowerName("Old Bob"));
		assertEquals("D'arcy-Jones", FollowerPlugin.cleanFollowerName("D'arcy-Jones"));
	}

	@Test
	public void whitespaceIsTidiedNotTrusted()
	{
		assertEquals("Pip", FollowerPlugin.cleanFollowerName("  Pip  "));
		assertEquals("Old Bob", FollowerPlugin.cleanFollowerName("Old    Bob"));
	}

	@Test
	public void tagsAndMarkupCannotSurvive()
	{
		// The menu target wraps the name in colour tags; a name carrying its
		// own would break out of them. Whatever comes in, no angle bracket,
		// equals sign or slash comes out.
		String cleaned = FollowerPlugin.cleanFollowerName("Bob<col=ff0000>");
		assertEquals("Bobcolff0000", cleaned);
		assertEquals("img1Pip", FollowerPlugin.cleanFollowerName("<img=1/>Pip"));
	}

	@Test
	public void onlyLettersTheGameCanDrawAreKept()
	{
		// QA, 15 Oct: the game's fonts stop at Latin-1, and a Cyrillic name
		// drew as blanks over the follower's head. Accented Latin is fine.
		assertEquals("Zo\u00eb", FollowerPlugin.cleanFollowerName("Zo\u00eb"));
		assertEquals("Pip", FollowerPlugin.cleanFollowerName("Pip\u0414\u043c\u03b1\u4e00"));
		assertEquals("", FollowerPlugin.cleanFollowerName("\u0414\u043c\u0438\u0442\u0440\u0438\u0439"));
		assertTrue(FollowerPlugin.nameChar('\u00e9'));
		assertFalse(FollowerPlugin.nameChar('\u0414'));
	}

	@Test
	public void lengthIsCappedAtTwenty()
	{
		assertEquals(20,
			FollowerPlugin.cleanFollowerName("Abcdefghijklmnopqrstuvwxyz").length());
	}

	@Test
	public void nothingUsableMeansEmptyWhichMeansSkip()
	{
		assertEquals("", FollowerPlugin.cleanFollowerName(null));
		assertEquals("", FollowerPlugin.cleanFollowerName("   "));
		assertEquals("", FollowerPlugin.cleanFollowerName("<<<>>>"));
	}

	/**
	 * QA, 15 Oct: a name typed in the settings box never went through this
	 * gate. A blank one gave "[] " in chat, options with no target, and a
	 * menu strip that took every other plugin's entries with it.
	 */
	@Test
	public void theSettingsBoxNameIsCleanedAndNeverBlank()
	{
		assertEquals("Pip", FollowerPlugin.displayName(" Pip "));
		assertEquals("Bobcolff0000", FollowerPlugin.displayName("Bob<col=ff0000>"));
		assertEquals("Follower", FollowerPlugin.displayName(""));
		assertEquals("Follower", FollowerPlugin.displayName("   "));
		assertEquals("Follower", FollowerPlugin.displayName("<>"));
		assertEquals("Follower", FollowerPlugin.displayName(null));
	}

	@Test
	public void everyUseOfTheNameGoesThroughTheCleanOne() throws java.io.IOException
	{
		java.nio.file.Path plugin = java.nio.file.Paths.get("src/main/java/com/follower/FollowerPlugin.java");
		String source = PublicMarkers.strip(new String(java.nio.file.Files.readAllBytes(plugin),
			java.nio.charset.StandardCharsets.UTF_8));
		int uses = source.split("config\\.followerName\\(\\)", -1).length - 1;
		org.junit.Assert.assertEquals("the raw setting is read in one place only", 1, uses);
		org.junit.Assert.assertTrue("the plugin's own menu entries are found by their exact target",
			source.contains("!followerTarget().equals(entry.getTarget())"));
		org.junit.Assert.assertFalse("never by a name contained in a target",
			source.contains("getTarget().contains("));
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;

/**
 * Names as the middle of a sentence has them. Text QA5: "the wording of this
 * Statue", "One more Crate", and the bosses' articles uneven: "your death to
 * the Dagannoth Rex", "That's a Kraken."
 */
public class NamesMidSentenceTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private Harness harness() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		return h;
	}

	@Test
	public void aLandmarkIsACommonNounAfterThis() throws IOException
	{
		Harness h = harness();
		assertEquals("Hold on. I want the wording of this statue exactly.",
			h.engine.spokenText("Hold on. I want the wording of this {thing} exactly.",
				TriggerEvent.noticed("landmark", "Statue")));
		assertEquals("an item keeps the game's spelling", "Look at this Abyssal whip.",
			h.engine.spokenText("Look at this {thing}.", TriggerEvent.noticed("valuable", "Abyssal whip")));
	}

	@Test
	public void aThingInTheSceneIsACommonNounToo() throws IOException
	{
		Harness h = harness();
		assertEquals("One more crate and it's going in the notebook.",
			h.engine.spokenText("One more {target} and it's going in the notebook.",
				TriggerEvent.examinedCreature("Crate")));
		assertEquals("Everything on this monument is in the book now.",
			h.engine.spokenText("Everything on this {target} is in the book now.",
				TriggerEvent.examinedCreature("Monument")));
		assertEquals("an item examined keeps its capital", "One more Abyssal whip and it's going in the notebook.",
			h.engine.spokenText("One more {target} and it's going in the notebook.",
				TriggerEvent.examinedThing("Abyssal whip")));
	}

	@Test
	public void theDagannothKingsAreSomebody() throws IOException
	{
		Harness h = harness();
		h.engine.getContext().restoreIncident("the-death", "your death to Dagannoth Rex", 1, 0,
			System.currentTimeMillis() - 2 * 24 * 3_600_000L, "Dagannoth Rex");
		assertEquals("That's Dagannoth Rex. I'd know it anywhere.",
			h.engine.spokenText("That's a {memoryWho}. I'd know it anywhere.", TriggerEvent.tick()));
	}

	@Test
	public void theMemorysOwnBossIsTheOneThereIs() throws IOException
	{
		Harness h = harness();
		h.engine.getContext().restoreIncident("the-boss", "the Kraken going down", 1, 0,
			System.currentTimeMillis() - 2 * 24 * 3_600_000L, "Kraken");
		assertEquals("That's the Kraken. I'd know it anywhere.",
			h.engine.spokenText("That's a {memoryWho}. I'd know it anywhere.", TriggerEvent.tick()));
		assertEquals("The Kraken. That shape's on a page I keep rereading.",
			h.engine.spokenText("A {memoryWho}. That shape's on a page I keep rereading.", TriggerEvent.tick()));

		h.engine.getContext().restoreIncident("the-death", "your death to the Hill Giant", 1, 0,
			System.currentTimeMillis() - 2 * 24 * 3_600_000L, "Hill Giant");
		assertEquals("one of many keeps its a", "That's a Hill Giant. I'd know it anywhere.",
			h.engine.spokenText("That's a {memoryWho}. I'd know it anywhere.", TriggerEvent.tick()));
	}
}

package com.follower;

import java.util.AbstractMap;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.NPC;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * What the follower notices that the player has not: only things that are
 * still there and close enough to be seen, each once, each kind on its own
 * clock, and one line for each.
 */
public class NoticingTest
{
	private static final WorldPoint PLAYER = new WorldPoint(50, 50, 0);
	private static final WorldPoint FOLLOWER = new WorldPoint(49, 49, 0);
	/** Where the drop lands: at the player's feet, as a kill's does. */
	private static final WorldPoint DROP = new WorldPoint(50, 50, 0);

	/** Records every look asked for; says it is looking until told otherwise. */
	private static final class RecordingLooker implements Noticing.Looker
	{
		final List<WorldPoint> looks = new ArrayList<>();
		final List<Boolean> writes = new ArrayList<>();
		boolean looking;
		boolean refuses;

		@Override
		public boolean goAndLook(WorldPoint at, int steps, boolean write, int holdTicks)
		{
			if (refuses)
			{
				return false;
			}
			looks.add(at);
			writes.add(write);
			looking = true;
			return true;
		}

		@Override
		public boolean isLooking()
		{
			return looking;
		}
	}

	private static final class StandingFollower extends FollowerEntity
	{
		StandingFollower()
		{
			super(null, null);
		}

		@Override
		public boolean isSpawned()
		{
			return true;
		}

		@Override
		public WorldPoint getWorldLocation()
		{
			return FOLLOWER;
		}
	}

	private FakeGame game;
	private RecordingLooker looker;
	private Noticing noticing;
	private final List<TriggerEvent> events = new ArrayList<>();
	private boolean busy;
	private int idle;
	private boolean notices = true;
	private boolean keepsCompany = true;
	private List<Map.Entry<String, WorldPoint>> landmarks = Collections.emptyList();
	private int tick;

	@Before
	public void setUp()
	{
		game = new FakeGame().at(PLAYER.getX(), PLAYER.getY(), 0);
		looker = new RecordingLooker();
		FollowerConfig config = new FollowerConfig()
		{
			@Override
			public boolean noticesThings()
			{
				return notices;
			}

			@Override
			public boolean keepsCompany()
			{
				return keepsCompany;
			}
		};
		noticing = new Noticing(game.client, new StandingFollower(), config, looker,
			events::add, () -> busy, () -> idle, () -> landmarks);
	}

	private void tick(int count)
	{
		for (int i = 0; i < count; i++)
		{
			game.tick(++tick);
			noticing.tick();
		}
	}

	/** A ground item with an id and an owner; nothing else about it is asked. */
	private static TileItem item(int id, int ownership)
	{
		return (TileItem) java.lang.reflect.Proxy.newProxyInstance(
			TileItem.class.getClassLoader(), new Class<?>[]{TileItem.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getId":
						return id;
					case "getOwnership":
						return ownership;
					case "getQuantity":
						return 1;
					case "hashCode":
						return id;
					case "equals":
						return proxy == args[0];
					case "toString":
						return "item " + id;
					default:
						return method.getReturnType() == boolean.class ? false
							: method.getReturnType().isPrimitive() ? 0 : null;
				}
			});
	}

	private void walkAway()
	{
		game.at(PLAYER.getX() + Noticing.WALKED_AWAY_TILES, PLAYER.getY(), 0);
	}

	// -------------------------------------------------------------- the drop

	@Test
	public void aDropOfYoursWalkedAwayFromIsLookedAtOnceAndSaidOnce()
	{
		tick(1);
		noticing.itemSpawned(item(4151, TileItem.OWNERSHIP_SELF), DROP, "Abyssal whip", 1_500_000);
		tick(Noticing.LEFT_AFTER_TICKS + 1);
		assertTrue("still beside it: looting takes a moment", looker.looks.isEmpty());

		walkAway();
		tick(1);
		assertEquals(Collections.singletonList(DROP), looker.looks);
		assertEquals(false, looker.writes.get(0));
		assertEquals(1, events.size());
		assertEquals("valuable", events.get(0).getPlaceholders().get("kind"));
		assertEquals("Abyssal whip", events.get(0).getPlaceholders().get("thing"));

		looker.looking = false;
		tick(Noticing.Kind.VALUABLE.cooldownTicks + 5);
		assertEquals("each thing once", 1, looker.looks.size());
	}

	@Test
	public void itNoticesWithWorksBesideYouOff()
	{
		// QA3: Notices things also needed Works beside you when skilling,
		// a setting in another section that says nothing of it.
		keepsCompany = false;
		tick(1);
		noticing.itemSpawned(item(4151, TileItem.OWNERSHIP_SELF), DROP, "Abyssal whip", 1_500_000);
		tick(Noticing.LEFT_AFTER_TICKS + 1);
		walkAway();
		tick(1);
		assertEquals(Collections.singletonList(DROP), looker.looks);
	}

	@Test
	public void aSecondDropWaitsOutTheKindsClock()
	{
		// A good kill leaves two piles. Each is a thing of its own and gets
		// its look, but not one straight after the other: a pile of drops in
		// a good hour is one remark, not a commentary.
		tick(1);
		noticing.itemSpawned(item(4151, TileItem.OWNERSHIP_SELF), DROP, "Abyssal whip", 1_500_000);
		noticing.itemSpawned(item(11840, TileItem.OWNERSHIP_SELF), new WorldPoint(50, 52, 0),
			"Dragon boots", 200_000);
		walkAway();
		tick(Noticing.LEFT_AFTER_TICKS + 1);
		assertEquals(1, looker.looks.size());

		looker.looking = false;
		tick(Noticing.Kind.VALUABLE.cooldownTicks - 5);
		assertEquals("the kind's clock holds the second", 1, looker.looks.size());
		tick(10);
		assertEquals("and lets it go once it has run", 2, looker.looks.size());
	}

	@Test
	public void somebodyElsesDropAndACheapOneAreNotYourBusiness()
	{
		tick(1);
		noticing.itemSpawned(item(4151, TileItem.OWNERSHIP_OTHER), DROP, "Abyssal whip", 1_500_000);
		noticing.itemSpawned(item(526, TileItem.OWNERSHIP_SELF), DROP, "Bones", 50);
		walkAway();
		tick(Noticing.LEFT_AFTER_TICKS + 2);
		assertTrue(looker.looks.isEmpty());
	}

	@Test
	public void aDropPickedUpBeforeTheWalkIsNotThereToLookAt()
	{
		tick(1);
		TileItem whip = item(4151, TileItem.OWNERSHIP_SELF);
		noticing.itemSpawned(whip, DROP, "Abyssal whip", 1_500_000);
		noticing.itemDespawned(whip, DROP);
		walkAway();
		tick(Noticing.LEFT_AFTER_TICKS + 2);
		assertTrue("gone: nothing to call out", looker.looks.isEmpty());
	}

	@Test
	public void aNestIsWorthALookWhoeverItBelongsTo()
	{
		tick(1);
		noticing.itemSpawned(item(5070, TileItem.OWNERSHIP_NONE), DROP, "Bird nest", 300);
		walkAway();
		tick(Noticing.LEFT_AFTER_TICKS + 2);
		assertEquals(Collections.singletonList(DROP), looker.looks);
		assertEquals("nest", events.get(0).getPlaceholders().get("kind"));
	}

	@Test
	public void aDropTooFarToBeOnScreenIsLeftAlone()
	{
		tick(1);
		WorldPoint far = new WorldPoint(FOLLOWER.getX() + Noticing.VISIBLE_TILES + 1, 50, 0);
		noticing.itemSpawned(item(4151, TileItem.OWNERSHIP_SELF), far, "Abyssal whip", 1_500_000);
		game.at(30, 50, 0);
		tick(Noticing.LEFT_AFTER_TICKS + 2);
		assertTrue(looker.looks.isEmpty());
	}

	// ----------------------------------------------------------- the impling

	@Test
	public void anImplingInSightIsSteppedToward()
	{
		NPC impling = game.spawnNpc(1635, "Dragon impling", 0);
		game.moveNpc(impling, 54, 52, 0);
		tick(Noticing.SCAN_EVERY_TICKS + 1);
		assertEquals(Collections.singletonList(new WorldPoint(54, 52, 0)), looker.looks);
		assertEquals("impling", events.get(0).getPlaceholders().get("kind"));
		assertEquals("Dragon impling", events.get(0).getPlaceholders().get("thing"));
	}

	@Test
	public void anImplingThePlayerIsAlreadyOnIsNotNews()
	{
		NPC impling = game.spawnNpc(1635, "Dragon impling", 0);
		game.moveNpc(impling, 54, 52, 0);
		game.facing(impling);
		tick(Noticing.SCAN_EVERY_TICKS + 1);
		assertTrue(looker.looks.isEmpty());
	}

	// -------------------------------------------------------------- the star

	@Test
	public void aStarIsWalkedOverToAndWrittenUp()
	{
		noticing.objectSpawned("Crashed star", new WorldPoint(55, 55, 0));
		tick(Noticing.SCAN_EVERY_TICKS + 1);
		assertEquals(Collections.singletonList(new WorldPoint(55, 55, 0)), looker.looks);
		assertTrue("the notes come out for a star", looker.writes.get(0));
		assertEquals("star", events.get(0).getPlaceholders().get("kind"));

		looker.looking = false;
		noticing.objectDespawned("Crashed star", new WorldPoint(55, 55, 0));
		noticing.objectSpawned("Crashed star", new WorldPoint(56, 55, 0));
		tick(Noticing.SCAN_EVERY_TICKS + 1);
		assertEquals("the kind's cooldown holds the next", 1, looker.looks.size());
	}

	@Test
	public void aSceneLeftBehindTakesItsDropsAndStarsWithIt()
	{
		// No despawn comes for a scene thrown away at a hop or a logout, so
		// the reset is all that stops the follower walking to empty ground in
		// the next world and naming what was there.
		tick(1);
		noticing.itemSpawned(item(4151, TileItem.OWNERSHIP_SELF), DROP, "Abyssal whip", 1_500_000);
		noticing.objectSpawned("Crashed star", new WorldPoint(55, 55, 0));
		noticing.reset();
		walkAway();
		tick(Noticing.LEFT_AFTER_TICKS + Noticing.SCAN_EVERY_TICKS + 2);
		assertTrue("nothing from the last scene is looked at", looker.looks.isEmpty());
	}

	// ---------------------------------------------------------- the landmark

	@Test
	public void aSignpostThePlayerStopsBesideIsRead()
	{
		landmarks = Collections.singletonList(
			new AbstractMap.SimpleImmutableEntry<>("Signpost", new WorldPoint(51, 50, 0)));
		idle = Noticing.LANDMARK_AFTER_IDLE_TICKS - 1;
		tick(Noticing.SCAN_EVERY_TICKS + 1);
		assertTrue("not until they have stood a while", looker.looks.isEmpty());

		idle = Noticing.LANDMARK_AFTER_IDLE_TICKS;
		tick(Noticing.SCAN_EVERY_TICKS + 1);
		assertEquals(Collections.singletonList(new WorldPoint(51, 50, 0)), looker.looks);
		assertTrue("read with the notes out", looker.writes.get(0));
		assertEquals("landmark", events.get(0).getPlaceholders().get("kind"));
		assertEquals("Signpost", events.get(0).getPlaceholders().get("thing"));

		looker.looking = false;
		tick(Noticing.Kind.LANDMARK.cooldownTicks + Noticing.SCAN_EVERY_TICKS + 1);
		assertEquals("the same sign is not read twice", 1, looker.looks.size());
	}

	@Test
	public void aLandmarkOutOfReachIsNotWalkedTo()
	{
		landmarks = Collections.singletonList(
			new AbstractMap.SimpleImmutableEntry<>("Statue", new WorldPoint(56, 50, 0)));
		idle = 100;
		tick(Noticing.SCAN_EVERY_TICKS + 1);
		assertTrue(looker.looks.isEmpty());
	}

	@Test
	public void theLandmarkListIsTheOneTheScanUses()
	{
		assertTrue(Noticing.isLandmark("Signpost"));
		assertTrue(Noticing.isLandmark("statue"));
		assertFalse(Noticing.isLandmark("Tree"));
		assertFalse(Noticing.isLandmark(null));
	}

	// ----------------------------------------------------------- the gates

	@Test
	public void nothingWhileBusyOrLookingOrSwitchedOff()
	{
		NPC impling = game.spawnNpc(1635, "Dragon impling", 0);
		game.moveNpc(impling, 54, 52, 0);
		busy = true;
		tick(Noticing.SCAN_EVERY_TICKS + 1);
		assertTrue(looker.looks.isEmpty());

		busy = false;
		looker.looking = true;
		tick(Noticing.SCAN_EVERY_TICKS + 1);
		assertTrue("one look at a time", looker.looks.isEmpty());

		looker.looking = false;
		notices = false;
		tick(Noticing.SCAN_EVERY_TICKS + 1);
		assertTrue(looker.looks.isEmpty());
	}

	@Test
	public void aLookTheFeetRefuseLeavesTheThingForLater()
	{
		NPC impling = game.spawnNpc(1635, "Dragon impling", 0);
		game.moveNpc(impling, 54, 52, 0);
		looker.refuses = true;
		tick(Noticing.SCAN_EVERY_TICKS + 1);
		assertTrue(events.isEmpty());
		looker.refuses = false;
		tick(Noticing.SCAN_EVERY_TICKS + 1);
		assertEquals("not memoised as a refusal", 1, looker.looks.size());
	}
}

package com.follower;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The npcNearby scan asks the cheap question first. Each of the shipped
 * npcNearby conditions scans the whole loaded scene once a tick, and its
 * predicate is a name match per pattern; asked of every NPC in a crowd that
 * was milliseconds a tick (perf audit, Oct 2026, #17). Distance rules out
 * almost all of them for nothing.
 */
public class NpcNearbyScanTest
{
	@Test
	public void onlyTheNpcsInRangeAreAskedAboutByName()
	{
		FakeGame game = new FakeGame().at(3222, 3218, 0);
		for (int i = 0; i < 50; i++)
		{
			game.moveNpc(game.spawnNpc(3000 + i, "Man", 2), 3222 + 30, 3218 + i % 10, 0);
		}
		game.moveNpc(game.spawnNpc(3100, "Goblin", 5), 3224, 3218, 0);
		TriggerContext context = new TriggerContext(game.client);
		context.refresh();

		int[] asked = {0};
		assertFalse(context.isNpcNearby(npc ->
		{
			asked[0]++;
			return false;
		}, 5));
		assertEquals("only the one in range", 1, asked[0]);

		// And the answer is the same as before.
		assertTrue(context.isNpcNearby(npc -> "Goblin".equals(npc.getName()), 5));
		assertFalse(context.isNpcNearby(npc -> "Man".equals(npc.getName()), 5));
		assertTrue(context.isNpcNearby(npc -> "Man".equals(npc.getName()), 30));
	}
}

package com.follower;

import net.runelite.api.CollisionDataFlag;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * A callout must be at something the player can actually see.
 *
 * <p>"That thing is very large and very close" invites the player to look. If
 * what is large and close is a kalphite behind a wall, the line is worse than
 * silence: one bad callout teaches the player that the follower's callouts
 * are not worth checking, which spends the credibility every good one earned.
 * Distance was the whole test before this - a wall three tiles away did not
 * exist as far as npcNearby was concerned.
 *
 * <p>The sight check is the game's own: {@code WorldArea.hasLineOfSightTo}
 * reads the scene's sight-blocking collision flags, so what the follower can
 * "see" and what the game would let an archer shoot agree by construction.
 */
public class NpcVisibilityTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** One rule that requires sight, one that does not, same NPC. */
	private static final String RULES = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"callout\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"npcNearby\", \"minimum\": 250, \"within\": 8,"
		+ " \"visible\": true},"
		+ " \"say\": [\"look at that\"]},"
		+ "{\"id\": \"sense\", \"group\": \"t\", \"cooldownMs\": 0, \"priority\": 10,"
		+ " \"when\": {\"type\": \"npcNearby\", \"minimum\": 250, \"within\": 8},"
		+ " \"say\": [\"something is about\"]}]}";

	/**
	 * The fake's collision map is scene-sized with a base of zero, so world
	 * coordinates must stay inside the 104-tile scene. Out-of-scene
	 * coordinates do not merely miss - the LOS lookup throws, the engine's
	 * guard disables the throwing rule, and the test fails by silence, which
	 * took some finding.
	 */
	private Harness harness() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.game.withCollision();
		h.game.at(50, 50, 0);
		return h;
	}

	@Test
	public void aVisibleGiantGetsTheCallout() throws IOException
	{
		Harness h = harness();
		h.game.moveNpc(h.game.spawnNpc(494, "Kalphite Queen", 333), 54, 50, 0);
		h.gameTicks(3);

		assertEquals("open ground: the callout fires", 1, h.firedBy("callout").size());
	}

	@Test
	public void aGiantBehindAWallIsNotACallout() throws IOException
	{
		Harness h = harness();
		h.game.moveNpc(h.game.spawnNpc(494, "Kalphite Queen", 333), 54, 50, 0);
		// A sight-blocking wall between the player and it.
		h.game.wallAt(52, 50, CollisionDataFlag.BLOCK_LINE_OF_SIGHT_FULL);
		h.gameTicks(3);

		assertTrue("a callout at a wall teaches the player to stop checking",
			h.firedBy("callout").isEmpty());
		assertEquals("but a rule that only senses, without pointing, still may",
			1, h.firedBy("sense").size());
	}

	@Test
	public void noCollisionDataReadsAsVisible() throws IOException
	{
		// During loading there is nothing to consult, and refusing to mention
		// a boss because the map has not finished arriving is the wrong kind
		// of caution. The harness without withCollision() is exactly the
		// no-data world.
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.game.at(50, 50, 0);
		h.game.moveNpc(h.game.spawnNpc(494, "Kalphite Queen", 333), 54, 50, 0);
		h.gameTicks(3);

		assertEquals("benefit of the doubt with no map", 1, h.firedBy("callout").size());
	}

	@Test
	public void theShippedLookableRulesAllRequireSight() throws IOException
	{
		// The audit itself, pinned: every rule whose lines invite the player
		// to look at an NPC carries the visible requirement. If a new
		// pointing rule arrives without it, this list is where the argument
		// happens.
		Harness h = new Harness(folder.newFolder().toPath());
		for (String id : new String[]{"something-big-nearby", "cats-and-pets", "boss-while-low"})
		{
			SpeechRule rule = h.rule(id);
			assertTrue(id + " points at an NPC and must require sight of it",
				requiresSight(rule.when));
		}
	}

	private static boolean requiresSight(Condition condition)
	{
		if (condition == null)
		{
			return false;
		}
		if ("npcNearby".equalsIgnoreCase(condition.type)
			&& Boolean.TRUE.equals(condition.visible))
		{
			return true;
		}
		if (condition.conditions != null)
		{
			for (Condition child : condition.conditions)
			{
				if (requiresSight(child))
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.follower;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * An occasion waits at most eight seconds for the gap after another line.
 * Quests QA, 16 Oct: at Minimal (45 s, the user's own setting) every quest
 * moment waited the full gap behind any line, the sketch prompt included,
 * and landed a stage late, out of order or after the reward scroll. The
 * user's call: the moments break through; ordinary lines keep the gap.
 */
public class OccasionGapTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private final long[] ms = {1_700_000_000_000L};

	private final List<String> held = new ArrayList<>();

	private static final String CHATTY = "{\"id\": \"chatty\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"levelUp\", \"names\": [\"*\"]}, \"say\": [\"Nice.\"]}";

	private static final String QUEST = "{\"id\": \"quest\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"occasion\": true, \"when\": {\"type\": \"questComplete\"}, \"say\": [\"Done and witnessed.\"]}";

	private static final String PERSON = "{\"id\": \"fred\", \"group\": \"quest\", \"cooldownMs\": 0,"
		+ " \"waits\": true, \"when\": {\"type\": \"npcNearby\", \"within\": 5, \"names\": [\"Fred the Farmer\"]},"
		+ " \"say\": [\"Fred the Farmer.\"]}";

	private static final String WAITS = "{\"id\": \"heeded\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"waits\": true, \"when\": {\"type\": \"heeded\"}, \"say\": [\"Good.\"]}";

	private Harness harness() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": [" + CHATTY + "," + QUEST + "," + PERSON + "]}");
		h.engine.setClock(() -> ms[0]);
		h.engine.setGlobalCooldownMs(45_000L);
		h.engine.setOnSuppressed((rule, why) -> held.add(rule.describe() + ":" + why));
		h.gameTicks(1);
		return h;
	}

	private void ticks(Harness h, int count)
	{
		for (int i = 0; i < count; i++)
		{
			ms[0] += 600;
			h.gameTick();
		}
	}

	@Test
	public void atMinimalAnOccasionWaitsEightSecondsNotTheGap() throws IOException
	{
		Harness h = harness();
		// The sketch prompt: a remark of the follower's own.
		h.engine.remark("Hold still a moment.");
		ticks(h, 1);
		h.dispatch(TriggerEvent.questComplete("Rune Mysteries"));
		ticks(h, 12);
		assertTrue("not inside eight seconds", h.firedBy("quest").isEmpty());
		ticks(h, 2);
		assertEquals("said once eight seconds are out", 1, h.firedBy("quest").size());
	}

	@Test
	public void chatterInAConversationIsHeldBackAndCostsNoGap() throws IOException
	{
		// QA3 #10: an idle line hushed in a quest's long conversation still
		// charged the gap, and the scroll's line waited behind it.
		Harness h = harness();
		h.engine.getContext().setDialogueOpen(true);
		ticks(h, 5);
		h.dispatch(TriggerEvent.levelUp("Attack", 30));
		assertTrue("not handed over to be hushed", h.spoken.isEmpty());
		assertEquals("chatty:dialogue", held.get(0));
		ticks(h, 5);
		h.engine.getContext().setDialogueOpen(false);
		h.dispatch(TriggerEvent.questComplete("Children of the Sun"));
		assertEquals("no gap to wait out", 1, h.firedBy("quest").size());
	}

	@Test
	public void ordinaryLinesStillKeepTheWholeGap() throws IOException
	{
		Harness h = harness();
		h.dispatch(TriggerEvent.questComplete("Rune Mysteries"));
		assertEquals(1, h.firedBy("quest").size());
		ticks(h, 20);
		h.dispatch(TriggerEvent.levelUp("Attack", 30));
		assertTrue("12 s after a line, at Minimal", h.firedBy("chatty").isEmpty());
		assertEquals("chatty:gap", held.get(0));
		ticks(h, 60);
		h.dispatch(TriggerEvent.levelUp("Attack", 31));
		assertEquals("48 s after it", 1, h.firedBy("chatty").size());
	}

	@Test
	public void atMinimalAQuestPersonIsNamedWhileStillNear() throws IOException
	{
		// Quests QA4 #31 and text QA4 #55: the 45 s gap outlasted the first
		// talk, and the line came at the hand-in or not at all. A quest
		// person's line now keeps an occasion's eight seconds.
		Harness h = harness();
		h.engine.remark("Hold still a moment.");
		ticks(h, 1);
		h.game.moveNpc(h.game.spawnNpc(9001, "Fred the Farmer", 0), 3224, 3218, 0);
		ticks(h, 11);
		assertTrue("not inside eight seconds", h.firedBy("fred").isEmpty());
		ticks(h, 3);
		assertEquals("said once eight seconds are out", 1, h.firedBy("fred").size());
	}

}

package com.follower;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;

/**
 * The one promise the director makes: an occasion always gets through.
 *
 * <p>That promise was broken within hours of being written, and in a way no
 * amount of reading would have caught. The relax check exempted occasions; the
 * settling check, added at the same time and four lines below it, did not - so
 * enter-wilderness, which is group "area" and therefore counts as scenery,
 * could be swallowed for a player who was new. A follower is only settling in
 * because the player is new, so the two conditions peak together.
 *
 * <p>The fix was to state the exemption once at the top of the method. The
 * guard against it happening again cannot be another reading of that method,
 * because the failure was one damper forgetting what the one above it knew.
 * This asserts the PROPERTY over every shipped occasion and every state the
 * director can be in, so a third damper added later has to keep the promise
 * without anyone remembering to ask it to.
 */
public class OccasionGuaranteeTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final long GAP = 3_000L;
	private static final long NOW = 1_700_000_000_000L;

	/** Every state the director can be in, with a name for the failure message. */
	private static List<Object[]> everyDirectorState()
	{
		List<Object[]> states = new ArrayList<>();

		SpeechRule filler = new SpeechRule();
		filler.id = "filler";
		filler.group = "area";           // counts as lore, so it arms both dampers

		for (int sessions : new int[]{1, 2, 3, 40})
		{
			for (boolean resting : new boolean[]{false, true})
			{
				SpeechDirector director = new SpeechDirector();
				director.setBaseGapMs(GAP);
				director.setSessionCount(sessions);
				director.noteSpoke(filler, NOW);     // arms the settling damper
				if (resting)
				{
					for (int i = 0; i < 4; i++)
					{
						director.noteSpoke(filler, NOW);
					}
				}
				states.add(new Object[]{
					"session " + sessions + (resting ? ", resting" : ", listening"),
					director});
			}
		}
		return states;
	}

	@Test
	public void noOccasionCanBeHeldByAnyDamperInAnyState() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());

		List<String> broken = new ArrayList<>();
		int checked = 0;
		for (SpeechRule rule : h.loader.getRules())
		{
			if (!rule.isOccasion())
			{
				continue;
			}
			checked++;
			for (Object[] state : everyDirectorState())
			{
				String held = ((SpeechDirector) state[1]).blocks(rule, NOW);
				if (held != null)
				{
					broken.add(rule.id + " held by \"" + held + "\" (" + state[0] + ")");
				}
			}
		}

		assertTrue("the shipped set should have plenty of occasions", checked > 50);
		assertTrue("an occasion is a line the follower must never be too busy to"
			+ " say, and these were held:\n  " + String.join("\n  ", broken),
			broken.isEmpty());
	}

	@Test
	public void theGuaranteeHoldsForAGroupTheDamperThins() throws IOException
	{
		// The specific shape of the original bug, kept as its own case because
		// it is the only shipped occasion living in a scenery group and would
		// be easy to move without noticing what it was protecting.
		Harness h = new Harness(folder.newFolder().toPath());
		SpeechRule wilderness = h.rule("enter-wilderness");

		assertTrue("enter-wilderness has to stay an occasion; it is the whole"
			+ " reason the flag exists", wilderness.isOccasion());
		assertTrue("and it is still in a group the settling damper thins, which"
			+ " is exactly why the guarantee has to be unconditional",
			SpeechDirector.isLore(wilderness));

		for (Object[] state : everyDirectorState())
		{
			assertTrue("enter-wilderness held (" + state[0] + ")",
				((SpeechDirector) state[1]).blocks(wilderness, NOW) == null);
		}
	}

	@Test
	public void everyHealthWarningIsAnOccasion() throws IOException
	{
		// The content half of the same promise. A warning the player never
		// hears is worse than one they hear twice, so anything that tells them
		// to eat, cure, pray or run has to be exempt.
		Harness h = new Harness(folder.newFolder().toPath());

		// Deliberately not the whole group: "Ouch. {damage}." and "Out of
		// breath already?" are remarks about what happened, not instructions
		// about what to do, and holding those back costs nobody anything.
		List<String> mustCarry = java.util.Arrays.asList(
			"critical-hp", "low-hp", "low-prayer", "status-poisoned",
			"status-venomed", "status-skulled", "boss-while-low",
			"enter-wilderness");

		List<String> missing = new ArrayList<>();
		for (String id : mustCarry)
		{
			if (!h.rule(id).isOccasion())
			{
				missing.add(id);
			}
		}
		assertTrue("these tell the player to do something about a danger and"
			+ " must never be held: " + missing, missing.isEmpty());
	}

	@Test
	public void everyBossIdentificationIsAnOccasion() throws IOException
	{
		// Walking into a boss is the clearest case in the file: the advice is
		// only any use before the fight starts, and a player who missed it
		// because the follower was resting has been failed by the exact feature
		// meant to make them listen.
		Harness h = new Harness(folder.newFolder().toPath());

		List<String> missing = new ArrayList<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			if ("boss".equals(rule.group) && rule.priority >= 90 && !rule.isOccasion())
			{
				missing.add(rule.id);
			}
		}
		assertTrue("boss advice that could be held back: " + missing, missing.isEmpty());
	}

	@Test
	public void aTrackUnlockedInACutsceneIsSaidAfterIt() throws IOException
	{
		// Play test, 9 Oct: Children of the Sun unlocks its track as the
		// delegation's scene opens, and the scene's quiet dropped the line.
		// An occasion waits the quiet out instead.
		Harness h = new Harness(folder.newFolder().toPath());
		assertTrue(h.rule("music-unlock").isOccasion());
	}
}

package com.follower;

/**
 * The everyday Talk-to script and the day summary as FollowerPlugin built
 * them in Java before talk.json, copied verbatim (its public markers included), so
 * TalkScriptEquivalenceTest can prove the file builds the same conversation.
 * Three things differ, none in what is built: the joke method reference names
 * this class, the pool is package-private for the test, and the three
 * per-visit nodes are made as says().dynamic(pages), which is what the
 * removed Node.saysDynamic(pages) did.
 */
final class OldTalk
{
	private OldTalk()
	{
	}

	private static FollowerDialog.Node says(String... pages)
	{
		return FollowerDialog.Node.says(pages);
	}

	private static FollowerDialog.Node you(String... pages)
	{
		return FollowerDialog.Node.you(pages);
	}

	static String[] daySummary(int minutes, int kills, int levels, int deaths,
		String moodBand, String incident)
	{
		java.util.List<String> parts = new java.util.ArrayList<>();

		if (minutes >= 1)
		{
			// A scribe does not round 95 minutes down to "1 hour" - the
			// half hour happened and it was there for it.
			int hours = minutes / 60;
			int rest = minutes % 60;
			parts.add(hours == 0
				? minutes + (minutes == 1 ? " minute" : " minutes")
				: hours + (hours == 1 ? " hour" : " hours")
					+ (rest == 0 ? "" : " and " + rest
						+ (rest == 1 ? " minute" : " minutes")));
		}

		if (kills > 0)
		{
			parts.add(kills + (kills == 1 ? " thing killed" : " things killed"));
		}
		if (levels > 0)
		{
			parts.add(levels + (levels == 1 ? " level" : " levels"));
		}
		if (deaths > 0)
		{
			parts.add(deaths + (deaths == 1 ? " death" : " deaths"));
		}

		java.util.List<String> pages = new java.util.ArrayList<>();
		if (parts.isEmpty())
		{
			pages.add("Today's page is blank. Restful, I call that.");
		}
		else
		{
			pages.add("Today's page: " + join(parts) + ".");
		}

		// The mood is the follower's own verdict on all that, which is a
		// different thing from the figures and worth saying separately.
		switch (moodBand == null ? "" : moodBand)
		{
			case "low":
				pages.add("I've had better days, if I'm honest.");
				break;
			case "down":
				pages.add("Not our finest, but we're still walking.");
				break;
			case "good":
				pages.add("A good day, that. I'd take another like it.");
				break;
			case "high":
				pages.add("One of the good ones. I mean that.");
				break;
			default:
				pages.add("An ordinary day. There's nothing wrong with those.");
				break;
		}

		// And the one thing it has not let go of.
		if (incident != null && !incident.isEmpty())
		{
			pages.add("I'm still thinking about " + incident + ".");
		}
		return pages.toArray(new String[0]);
	}

	private static String join(java.util.List<String> parts)
	{
		if (parts.size() == 1)
		{
			return parts.get(0);
		}
		return String.join(", ", parts.subList(0, parts.size() - 1))
			+ " and " + parts.get(parts.size() - 1);
	}

	static final String[][] JOKES = {
		{"Why did the Wise Old Man rob the bank of Draynor?",
			"Because that's where the money was."},
		{"What do you call an adventurer who takes their whole bank into the Wilderness?",
			"A benefactor."},
		{"Why did the chicken cross the road?",
			"In Lumbridge? It never got the chance."},
		{"I tried talking to a camel in Al Kharid once.",
			"Apparently you need a special amulet. He made his opinion clear without one."},
	};

	private static int lastJoke = -1;

	private static String[] nextJoke()
	{
		int pick;
		do
		{
			pick = java.util.concurrent.ThreadLocalRandom.current().nextInt(JOKES.length);
		}
		while (pick == lastJoke && JOKES.length > 1);
		lastJoke = pick;
		return JOKES[pick];
	}

	static java.util.Map<String, FollowerDialog.Node> talkScript(
		java.util.function.Supplier<String[]> summary,
		java.util.function.Consumer<String> onAnswer,
		String moodBand)
	{
		java.util.Map<String, FollowerDialog.Node> script =
			new java.util.LinkedHashMap<>();

		// When the follower is not itself, "How have you been?" sharpens into
		// "You all right?" - same slot, same spirit, pointed by state. The
		// research calls this answering its mood, and it is the one thing a
		// player can DO about a low band besides witness it.
		boolean lowish = "low".equals(moodBand) || "down".equals(moodBand);
		String howLabel = lowish ? "You all right?" : "How have you been?";
		String howTarget = lowish ? "allright-q" : "how-q";

		// While a wish is open the five-slot box retires who-are-you, not the
		// small talk: who-a stays reachable from the returning hub later, but
		// the jokes and advice are the perishable first-hour charm, and a
		// 45-minute wish window used to wall them off from the opening screen.
		script.put("start", says("Yes?").choices(
				"Who are you, exactly?", "who-q",
				"What is it you actually do?", "do-q",
				howLabel, howTarget,
				"Let's just talk.", "chat-q",
				"Never mind.", "bye-q"));

		// The returning hub, without the greeting. Five options is the most
		// the box has measured spacing for, so while a wish is open the hub
		// retires who-are-you to make room - somebody coming BACK
		// mid-conversation knows who it is.
		script.put("menu", says().choices(
				"Who are you, exactly?", "who-q",
				"What is it you actually do?", "do-q",
				howLabel, howTarget,
				"Let's just talk.", "chat-q",
				"That's all for now.", "done-q"));

		// ------------------------------------------------ answering its mood
		// Asking is itself the kindness: reaching the answer node is what
		// counts (latched on arrival, like every answer), so closing the box
		// early still asked. The lift arrives from the comforted rule; the
		// pages differ by band because "not the best day" and "middling" are
		// different admissions. Either way the usual how-menu follows - a low
		// day does not lock away the notebook.
		if (lowish)
		{
			script.put("allright-q", you("You all right?").then("allright-a"));
			script.put("allright-a", "low".equals(moodBand)
				? says(
					"Honestly? Not the best day in the ledger.",
					"But you noticed. That's worth an entry of its own.")
					.onFinish(() -> onAnswer.accept("comforted"))
					.then("how-menu")
				: says(
					"Middling. The ink's been thicker.",
					"Asking helps. Don't tell anyone I said that.")
					.onFinish(() -> onAnswer.accept("comforted"))
					.then("how-menu"));
		}

		// Shared closings. Both are spoken, like every other option.
		script.put("bye-q", you("Never mind.").then("bye"));
		script.put("done-q", you("That's all for now.").then("bye"));
		script.put("back-q", you("Back to business.").then("menu"));
		script.put("bye", says("Right you are. One step behind."));

		// ------------------------------------------------ who are you
			script.put("who-q", you("Who are you, exactly?").then("who-a"));
			script.put("who-a", says(
				"Now there's a question.",
				"A scribe. Somebody has to write all this down.")
				.then("who-b"));
			script.put("who-b", says(
				"You dress me, I walk behind you, and I keep quiet about your bank.")
				.choices(
					"Writing what, exactly?", "who-me-q",
					"Do you have a name?", "who-name-q",
					"Don't you get tired of following me?", "who-tired-q",
					"Back to business.", "back-q"));

			script.put("who-menu", says()
				.choices(
					"Writing what, exactly?", "who-me-q",
					"Do you have a name?", "who-name-q",
					"Don't you get tired of following me?", "who-tired-q",
					"Back to business.", "back-q"));

			script.put("who-me-q", you("Writing what, exactly?").then("who-me-a"));
			script.put("who-me-a", says(
				"Everything. Roads, rulers, prices, what lives under things.",
				"It's a long project. Nobody's asked to read it.")
				.then("who-menu"));

			script.put("who-name-q", you("Do you have a name?").then("who-name-a"));
			script.put("who-name-a", says(
				"Whatever you've been calling me. I'd have picked my own, but nobody asked.",
				"It's grown on me.")
				.then("who-menu"));

			script.put("who-tired-q", you("Don't you get tired of following me?").then("who-tired-a"));
			script.put("who-tired-a", says(
				"Tired? I once watched you stand at a furnace for three hours.",
				"Nothing has tired me since.")
				.then("who-menu"));

		// ------------------------------------------------ what do you do
		script.put("do-q", you("What is it you actually do?").then("do-a"));
		script.put("do-a", says("Walk behind you. It's more involved than it sounds.")
			.then("do-menu"));
		script.put("do-menu", says()
			.choices(
				"Tell me about the walking.", "do-follow-q",
				"What do you do when I'm fighting?", "do-fight-q",
				"And when I'm working?", "do-work-q",
				"Can you dance?", "do-emote-q",
				"That's all I needed.", "do-done-q"));
		script.put("do-done-q", you("That's all I needed.").then("menu"));

		script.put("do-follow-q", you("Tell me about the walking.").then("do-follow-a"));
		script.put("do-follow-a", says(
			"One tile behind. Corners, doorways, stairs, running: I keep up.",
			"Where you go I go, teleports included. Same swirl, half a step later.")
			.then("do-follow-b"));
		script.put("do-follow-b", says(
			"Tell me to Stay and I'll hold the spot until you want me back.",
			"Or hold Shift, right-click a tile and pick Send. I'll walk there myself.")
			.then("do-menu"));

		script.put("do-fight-q", you("What do you do when I'm fighting?").then("do-fight-a"));
		script.put("do-fight-a", says(
			"Get out of the way, mainly. Then watch.",
			"If something enormous is near, I mention it first. For all the good that does.")
			.then("do-fight-b"));
		script.put("do-fight-b", says(
			"And when it goes down I make a fuss. You've usually earned it by then.")
			.choices(
				"What about my thralls?", "do-thrall-q",
				"Good to know.", "do-fight-done-q"));
		script.put("do-fight-done-q", you("Good to know.").then("do-menu"));

		// The thrall styles are measured, not guessed: zombie ids are melee,
		// skeleton ranged, ghost magic, and each has its own outfit profile in
		// the settings. Worth saying out loud - the follower turning up to a
		// mage fight in melee gear is the one thing about this that looks
		// broken rather than deliberate.
		script.put("do-thrall-q", you("What about my thralls?").then("do-thrall-a"));
		script.put("do-thrall-a", says(
			"Raise one of those Arceuus things and I'll take its place.",
			"Same walking, same swinging, far better dressed.")
			.then("do-thrall-b"));
		script.put("do-thrall-b", says(
			"Three sorts, mind. Zombie, skeleton and ghost, for melee, ranged and magic.")
			.then("do-thrall-c"));
		script.put("do-thrall-c", says(
			"Set me an outfit for each in the settings.",
			"Otherwise I turn up to a mage fight holding a greataxe and we both look foolish.")
			.then("do-menu"));

		script.put("do-work-q", you("And when I'm working?").then("do-work-a"));
		script.put("do-work-a", says(
			"Depends what you're at.",
			"If it's pockets, I give you room and watch the street until you're done.")
			.then("do-work-b"));
		script.put("do-work-b", says(
			"Trees, rocks, fishing spots. I set up beside you and do a bit myself.",
			"Now and then I wander off on an errand of my own. I always come back.")
			.then("do-menu"));

		script.put("do-emote-q", you("Can you dance?").then("do-emote-a"));
		script.put("do-emote-a", says(
			"Ask and find out. Right-click me for a wave or a dance, whatever the moment wants.",
			"Or do one yourself and I'll join in a beat behind. I'm not a mirror. I have timing.")
			.then("do-menu"));

		// ------------------------------------------------ the inner life
		// The everyday entrance; on a lowish day allright-q replaces it (and
		// leads to the same menu), so it is only built when reachable.
		if (!lowish)
		{
			script.put("how-q", you("How have you been?").then("how-a"));
			script.put("how-a", says(
				"That depends on the day. You've given me some days.")
				.then("how-menu"));
		}
		script.put("how-menu", says()
			.choices(
				"How did today go?", "how-today-q",
				"You keep track of things?", "how-count-q",
				"You have moods?", "how-mood-q",
				"Anywhere you'd rather be?", "how-place-q",
				"Back to business.", "back-q"));

		// The one page in the script that is different every time it is read.
		// Everything in it is already counted - the tallies exist for the
		// milestone lines - so this is the same memory said as a sentence
		// rather than as a number, which is what makes it sound like somebody
		// who was there rather than a scoreboard.
		script.put("how-today-q", you("How did today go?").then("how-today-a"));
		script.put("how-today-a", FollowerDialog.Node
			.says().dynamic(summary)
			.then("how-menu"));

		script.put("how-count-q", you("You keep track of things?").then("how-count-a"));
		script.put("how-count-a", says(
			"It's the job. Every rat, every level, every time you've gone down in front of me.",
			"It isn't judgement. Somebody should, that's all.")
			.then("how-count-b"));
		script.put("how-count-b", says(
			"I remember it between days, too. You come back and the number's still there.")
			.then("how-menu"));

		script.put("how-mood-q", you("You have moods?").then("how-mood-a"));
		script.put("how-mood-a", says(
			"I do. You'd know if you looked up.",
			"When it's gone well I stand one way. When it hasn't, I stand another.")
			.then("how-mood-b"));
		script.put("how-mood-b", says(
			"It passes. Everything does, if you keep walking.")
			.then("how-menu"));

		script.put("how-place-q", you("Anywhere you'd rather be?").then("how-place-b"));
		script.put("how-place-b", says(
			"If I ever ask you to take me somewhere, come and talk to me and I'll say where.",
			"I won't ask twice. It's not that sort of arrangement.")
			.then("how-menu"));

		// ------------------------------------------------ small talk
		script.put("chat-q", you("Let's just talk.").then("chat-a"));
		script.put("chat-a", says("My favourite duty.").then("chat-menu"));
		script.put("chat-menu", says()
			.choices(
				"Seen anything interesting?", "chat-seen-q",
				"What do you think of my outfit?", "chat-outfit-q",
				"Any advice?", "advice-q",
				"Tell me a joke.", "chat-joke-q",
				"Back to business.", "back-q"));

		script.put("chat-seen-q", you("Seen anything interesting?").then("chat-seen-a"));
		script.put("chat-seen-a", says(
			"Mostly the back of your head.",
			"It's a fine head. It could carry a better hat.")
			.then("chat-menu"));

		script.put("chat-outfit-q", you("What do you think of my outfit?").then("chat-outfit-a"));
		script.put("chat-outfit-a", says(
			"Anyone who dresses their follower this well has taste.",
			"The rest of your wardrobe I couldn't comment on.")
			.then("chat-menu"));

		// Every visit re-rolls from the pool (never the same joke twice in a
		// row), and the loop lets you keep asking. Both loop options get their
		// own spoken node so the label and the line stay identical.
		script.put("chat-joke-q", you("Tell me a joke.").then("chat-joke-a"));
		script.put("chat-joke-a", FollowerDialog.Node
			.says().dynamic(OldTalk::nextJoke)
			.choices(
				"Heh. Got another one?", "chat-joke2-q",
				"That's terrible.", "chat-groan-q"));

		script.put("chat-joke2-q", you("Heh. Got another one?").then("chat-joke2-a"));
		script.put("chat-joke2-a", FollowerDialog.Node
			.says().dynamic(OldTalk::nextJoke)
			.choices(
				"Another!", "chat-joke3-q",
				"That's terrible.", "chat-groan-q"));

		script.put("chat-joke3-q", you("Another!").then("chat-joke2-a"));

		script.put("chat-groan-q", you("That's terrible.").then("chat-groan-a"));
		script.put("chat-groan-a", says(
			"I've been saving that one since Lumbridge.",
			"There's more where it came from. Choose your next question carefully.")
			.then("chat-menu"));

		// ------------------------------------------------ advice
		script.put("advice-q", you("Any advice?").then("advice-a"));
		script.put("advice-a", says(
			"Don't take the detour for the cabbage. It is never worth it.")
			.then("advice-b"));
		script.put("advice-b", says(
			"A stranger offering to trim your armour is no barber.")
			.then("advice-c"));
		script.put("advice-c", says(
			"And bank before you think you need to. A gravestone is not storage.")
			.then("advice-d"));
		script.put("advice-d", says(
			"That's the lot. The rest I've learned to keep to myself.")
			.then("chat-menu"));

		return script;
	}
}

package com.follower;

import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

/**
 * The writing pose (Write with a quill, 13302) is authored to play once, with
 * no restart frame, and the scroll errands hold it as a pose override for many
 * seconds at a time. A pose's controller hands every finished pass to
 * loopSafely, which has to start such a clip again from its first frame: the
 * client's own loop steps back by a frame step of -1, which is past the end,
 * and a controller left there drops its clip and freezes the model mid-stroke.
 */
public class OnceClipHeldAsAPoseTest
{
	private static final int[] FRAME_LENGTHS = {4, 4, 4};

	@Test
	public void aClipWithNoRestartFrameStartsAgainFromItsFirstFrame() throws ReflectiveOperationException
	{
		// The duration as a count of frames, and as a count of cycles: the
		// client's loop lands back on the first frame for the one and leaves
		// the frame out of range for the other, and either way it plays on.
		for (int duration : new int[]{FRAME_LENGTHS.length, 12})
		{
			Animation once = once(duration);
			AnimationController controller = held(once);

			controller.tick(13);
			assertSame("still playing after its first pass", once, controller.getAnimation());
			assertEquals("from its first frame again", 0, controller.getFrame());

			controller.tick(12);
			assertSame("and after its second", once, controller.getAnimation());
			assertEquals(0, controller.getFrame());
		}
	}

	/** A controller as FollowerEntity.applyPose sets one up for a held pose. */
	private static AnimationController held(Animation animation) throws ReflectiveOperationException
	{
		Method loopSafely = FollowerEntity.class.getDeclaredMethod("loopSafely", AnimationController.class);
		loopSafely.setAccessible(true);
		AnimationController controller = new AnimationController(null, animation);
		controller.setOnFinished(finished ->
		{
			try
			{
				loopSafely.invoke(null, finished);
			}
			catch (IllegalAccessException | InvocationTargetException e)
			{
				throw new AssertionError(e);
			}
		});
		return controller;
	}

	private static Animation once(int duration)
	{
		return (Animation) Proxy.newProxyInstance(Animation.class.getClassLoader(), new Class<?>[]{Animation.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "isMayaAnim":
						return false;
					case "getFrameLengths":
						return FRAME_LENGTHS.clone();
					case "getFrameStep":
						return -1;
					case "getDuration":
						return duration;
					case "getId":
						return ErrandController.WRITE_SCROLL_POSE;
					default:
						throw new UnsupportedOperationException(method.getName());
				}
			});
	}
}

package com.follower;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Lines the follower says once, ever.
 *
 * <p>A line that only has to hold up on a single hearing can be specific in a
 * way no repeating line can afford to be: it can name the moment, admit
 * something, or land a joke that would be unbearable the fourth time. That
 * makes it the highest value per word in the file - and the easiest to ruin, by
 * saying it twice.
 */
public class OnceOnlyTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final String RULES =
		"{\"version\": 1, \"rules\": ["
			+ "{\"id\": \"hello-first\", \"group\": \"t\", \"cooldownMs\": 0, \"once\": true,"
			+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"we have not met\"]},"
			+ "{\"id\": \"hello-again\", \"group\": \"t\", \"cooldownMs\": 0, \"priority\": 10,"
			+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"back again\"]}]}";

	private Harness harness() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.gameTicks(1);
		return h;
	}

	/** The trigger, twice, with a tick between so the edge can fall. */
	private static void examineTwice(Harness h)
	{
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
	}

	@Test
	public void aFirstIsOnlyEverAFirst() throws IOException
	{
		Harness h = harness();
		examineTwice(h);

		assertEquals("said once", 1, h.firedBy("hello-first").size());
		assertEquals("and the lower-priority everyday line takes over after",
			1, h.firedBy("hello-again").size());
	}

	@Test
	public void whatWasSaidIsRememberedByTheFollowerNotTheRule() throws IOException
	{
		// The rule file reloads whenever it changes on disk, throwing every rule
		// object away. A flag on the object would un-say the introduction every
		// time a phrase was edited, which is the single most likely moment for
		// it to happen.
		Harness h = harness();
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertEquals(1, h.firedBy("hello-first").size());

		Path file = h.getScratch().resolve(RuleLoader.FILE_NAME);
		Files.write(file, RULES.replace("we have not met", "we have not met, you and I")
			.getBytes(StandardCharsets.UTF_8));
		// The loader compares the modified time, which has a second's resolution
		// on some filesystems.
		Files.setLastModifiedTime(file,
			java.nio.file.attribute.FileTime.fromMillis(System.currentTimeMillis() + 5_000L));
		assertTrue("the edited file should have been picked up", h.loader.reloadIfChanged());

		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertEquals("editing the file must not un-say it",
			1, h.firedBy("hello-first").size());
	}

	@Test
	public void aLineNobodyHeardIsNotSpent() throws IOException
	{
		// The worst possible place to be strict. Muted, the follower said
		// nothing; burning the one chance it had would lose the line for good
		// on behalf of a player who never got it.
		Harness h = harness();
		h.engine.setMuted(true);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertTrue(h.firedBy("hello-first").isEmpty());
		assertFalse(h.engine.getContext().hasSaidOnce("hello-first"));

		h.engine.setMuted(false);
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertEquals("still owed, and still paid", 1, h.firedBy("hello-first").size());
	}

	@Test
	public void sayingItIsWorthWritingDown() throws IOException
	{
		// Nothing is saved unless something says it needs saving, so a first
		// that did not mark the blob dirty would be forgotten by the next
		// restart - and said a second time.
		Harness h = harness();
		h.engine.getContext().clearCountersDirty();

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertTrue("a spent first has to reach the disk",
			h.engine.getContext().isCountersDirty());
		assertTrue(h.engine.getContext().getSpokenOnce().contains("hello-first"));
	}

	@Test
	public void whatWasSaidLastTimeStaysSaid() throws IOException
	{
		Harness h = harness();
		h.engine.getContext().restoreSpokenOnce(
			java.util.Collections.singletonList("hello-first"), null);

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertTrue("a restored session must not repeat the introduction",
			h.firedBy("hello-first").isEmpty());
		assertEquals("and the everyday line is there to take its place",
			1, h.firedBy("hello-again").size());
	}
}

package com.follower;

import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;

/**
 * One remembered thing brought up at a time. Text QA4, 16 Oct: "It's quiet.
 * My mind goes back to the guard with the very large bag." and, 16 s later,
 * "The notes on the guard with the very large bag start here." Each rule
 * had its own cooldown and nothing kept them apart.
 */
public class OneMemoryAtATimeTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private final long[] ms = {1_700_000_000_000L};

	private static String rule(String id, String skill, long cooldownMs, String line)
	{
		return "{\"id\": \"" + id + "\", \"group\": \"t\", \"cooldownMs\": " + cooldownMs + ","
			+ " \"when\": {\"type\": \"levelUp\", \"names\": [\"" + skill + "\"]}, \"say\": [\"" + line + "\"]}";
	}

	@Test
	public void aMemoryBroughtUpRestsTheOthersTenMinutes() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), "{\"version\": 1, \"rules\": ["
			+ rule("recall-idle", "Attack", 900_000L, "My mind goes back to {memory}.") + ","
			+ rule("recall-here", "Strength", 1_800_000L, "The notes on {memory} start here.") + ","
			+ rule("chatty", "Defence", 0L, "Nice.") + "]}");
		h.engine.setClock(() -> ms[0]);
		h.gameTicks(1);
		// From an earlier session: a memory filed just now is too fresh to bring up.
		h.engine.getContext().restoreIncident("bag", "the guard with the very large bag", 1, 0, 0L, "");

		h.dispatch(TriggerEvent.levelUp("Attack", 30));
		assertEquals(1, h.firedBy("recall-idle").size());
		ms[0] += 16_000L;
		h.dispatch(TriggerEvent.levelUp("Strength", 30));
		h.dispatch(TriggerEvent.levelUp("Defence", 30));
		assertEquals("not the same memory 16 s on", 0, h.firedBy("recall-here").size());
		assertEquals("other lines are not held", 1, h.firedBy("chatty").size());

		ms[0] += 600_000L;
		h.dispatch(TriggerEvent.levelUp("Strength", 31));
		assertEquals("ten minutes on", 1, h.firedBy("recall-here").size());
	}

	@Test
	public void whatAPlaceHoldsIsAMemoryToo() throws IOException
	{
		// Text QA5, 17 Oct: arriving where the player died, "This is where I
		// wrote down the time you died, yesterday." and, 6 s later, "Same
		// spot. This is where it went wrong for you." The spot of the last
		// death counts as well.
		Harness h = new Harness(folder.newFolder().toPath(), "{\"version\": 1, \"rules\": ["
			+ rule("recall-here", "Attack", 1_800_000L, "The notes on {memory} start here.") + ","
			+ rule("place-remembers", "Strength", 1_200_000L, "Same spot. This is where {here}.") + ","
			+ "{\"id\": \"death-spot\", \"group\": \"t\", \"cooldownMs\": 600000, \"when\": {\"type\": \"all\","
			+ " \"conditions\": [{\"type\": \"levelUp\", \"names\": [\"Defence\"]}, {\"type\": \"nearDeathSpot\"}]},"
			+ " \"say\": [\"This is where it happened.\"]}]}");
		h.engine.setClock(() -> ms[0]);
		h.game.at(3222, 3218, 0);
		h.gameTicks(1);
		h.engine.getContext().restoreIncident("the-death", "your death to the Hill Giant", 1, 0, 0L, "");
		h.engine.getContext().restorePlaces(
			java.util.Collections.singletonMap(h.engine.getContext().getRegionId(), "you died to the Hill Giant"));
		h.engine.getContext().restoreDeathSpot(new net.runelite.api.coords.WorldPoint(3222, 3218, 0));

		h.dispatch(TriggerEvent.levelUp("Attack", 30));
		assertEquals(1, h.firedBy("recall-here").size());
		ms[0] += 6_000L;
		h.gameTicks(1);
		h.dispatch(TriggerEvent.levelUp("Strength", 30));
		h.dispatch(TriggerEvent.levelUp("Defence", 30));
		assertEquals("not the place's memory 6 s on", 0, h.firedBy("place-remembers").size());
		assertEquals("nor the death spot", 0, h.firedBy("death-spot").size());

		ms[0] += 600_000L;
		h.gameTicks(1);
		h.dispatch(TriggerEvent.levelUp("Strength", 31));
		assertEquals("ten minutes on", 1, h.firedBy("place-remembers").size());
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * When the follower's body is in the scene and when it is not (QA, 16 Oct):
 * what a despawn cut off does not follow it into the next body, and a
 * sketch's frame is drawn without it.
 */
public class OutOfSightTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final int IDLE = 808;
	private static final int WAVE = 863;
	private static final int HOME = 4847;

	private FakeGame game;
	/** What the client has in its scene: a RuneLiteObject is active while it is in here. */
	private final Set<Object> inScene = new HashSet<>();
	private final List<Boolean> emoteStates = new ArrayList<>();
	private FollowerEntity follower;

	@Before
	public void setUp() throws IOException
	{
		game = new FakeGame().at(50, 50, 0).animation(IDLE, 0).animation(WAVE, -1).animation(HOME, -1);
		Client[] client = new Client[1];
		client[0] = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "createRuneLiteObject":
						// Placed nowhere: there are no tile heights to stand it on.
						return new RuneLiteObject(client[0])
						{
							@Override
							public void setLocation(LocalPoint point, int plane)
							{
							}
						};
					case "registerRuneLiteObject":
						inScene.add(args[0]);
						return null;
					case "removeRuneLiteObject":
						inScene.remove(args[0]);
						return null;
					case "isRuneLiteObjectRegistered":
						return inScene.contains(args[0]);
					default:
						Object answer = forward(game.client, method, args);
						return answer instanceof WorldView ? flat((WorldView) answer) : answer;
				}
			});
		StanceLibrary stances = new StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		stances.load(folder.newFolder().toPath());
		follower = new FollowerEntity(client[0], stances);
		follower.setOnEmoteStateChanged(emoteStates::add);
	}

	private static Object forward(Object to, java.lang.reflect.Method method, Object[] args) throws Throwable
	{
		try
		{
			return method.invoke(to, args);
		}
		catch (InvocationTargetException e)
		{
			throw e.getCause();
		}
	}

	private static final byte[][][] FLAT_SETTINGS = new byte[4][104][104];
	private static final int[][][] FLAT_HEIGHTS = new int[4][105][105];

	/** The game's view on level ground, so the follower can be stood in it. */
	private static WorldView flat(WorldView view)
	{
		byte[][][] settings = FLAT_SETTINGS;
		int[][][] heights = FLAT_HEIGHTS;
		return (WorldView) Proxy.newProxyInstance(WorldView.class.getClassLoader(),
			new Class<?>[]{WorldView.class}, (proxy, method, args) ->
				method.getName().equals("getTileSettings") ? settings
					: method.getName().equals("getTileHeights") ? heights
					: forward(view, method, args));
	}

	/** Spawned beside the player as the plugin does it, with no spawn animation. */
	private void spawn()
	{
		spawnAt(new WorldPoint(49, 50, 0));
	}

	private void spawnAt(WorldPoint at)
	{
		Model model = (Model) Proxy.newProxyInstance(Model.class.getClassLoader(),
			new Class<?>[]{Model.class}, (proxy, method, args) ->
			{
				Class<?> type = method.getReturnType();
				return type == boolean.class ? false : type == int.class ? 0 : null;
			});
		follower.setSpawnAnimation(new int[0]);
		follower.spawn(new ComposedAppearance(model, new Outfit()),
			at, null, 0);
	}

	private RuneLiteObject body() throws ReflectiveOperationException
	{
		Field field = FollowerEntity.class.getDeclaredField("object");
		field.setAccessible(true);
		return (RuneLiteObject) field.get(follower);
	}

	@Test
	public void aFollowerOutOfSightIsNotShown() throws ReflectiveOperationException
	{
		spawn();
		follower.updateFrame();
		assertTrue("in the scene", follower.isShown());

		// A home teleport that ran to its end: the follower goes with it.
		follower.startSlavedChain(new int[]{HOME}, null);
		follower.vanishAfterEmote();
		follower.slavedPlayerStopped();
		follower.updateFrame();
		assertFalse("gone through the teleport", follower.isShown());

		follower.despawn();
		assertFalse(follower.isShown());
	}

	@Test
	public void anEmoteCutOffByADespawnDoesNotHoldTheNextBody() throws ReflectiveOperationException
	{
		spawn();
		follower.updateFrame();
		follower.playAnimation(WAVE);
		assertTrue(follower.isEmotePlaying());
		emoteStates.clear();

		// A logout, a hop or a hide mid-wave, and back with no spawn animation.
		follower.despawn();
		spawn();
		assertFalse("the wave went with the old body", follower.isEmotePlaying());
		assertEquals("and the plugin was told, so the weapon comes back",
			java.util.Collections.singletonList(false), emoteStates);

		follower.updateFrame();
		AnimationController playing = body().getAnimationController();
		assertNotNull("the new body is given its idle on its first frame", playing);
		assertTrue("and is in the scene", follower.isShown());
	}

	@Test
	public void aTeleportsVanishDoesNotOutliveADespawn()
	{
		spawn();
		follower.updateFrame();
		follower.startSlavedChain(new int[]{HOME}, null);
		follower.vanishAfterEmote();
		follower.slavedPlayerStopped();
		follower.despawn();

		spawn();
		follower.updateFrame();
		assertTrue("the new body is not waiting on the old one's landing", follower.isShown());
	}
}

package com.follower;

import java.lang.reflect.Proxy;
import java.util.Random;
import net.runelite.api.PlayerComposition;
import net.runelite.api.kit.KitType;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * {@link Outfit} against the class it replaced (kept in
 * {@code appearance.before}): random outfits built the same way through both
 * - items, kits, props, cleared slots, colours of every length, both genders,
 * and outfits read from a composition - must write the same text, agree on
 * emptiness and on equality with each other and with their copies, and fill
 * in the same default body. Lombok's hash is not the hand-written one, so
 * only its contract is held: equal outfits hash alike. Nothing keys a map by
 * an outfit.
 */
public class OutfitDiffTest
{
	/** Random outfit pairs; {@code -Doutfitdiff.outfits=N} for a longer run. */
	private static final int OUTFITS = Integer.getInteger("outfitdiff.outfits", 50_000);

	private static PlayerComposition composition(int[] ids, int[] colours, int gender)
	{
		return (PlayerComposition) Proxy.newProxyInstance(PlayerComposition.class.getClassLoader(),
			new Class<?>[]{PlayerComposition.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getEquipmentIds":
						return ids;
					case "getColors":
						return colours;
					case "getGender":
						return gender;
					default:
						return null;
				}
			});
	}

	@Test
	public void everyOutfitBehavesTheSame()
	{
		Random random = new Random(5);
		KitType[] slots = KitType.values();
		for (int i = 0; i < OUTFITS; i++)
		{
			Outfit now = new Outfit();
			Outfit now2 = new Outfit();
			BeforeOutfit before = new BeforeOutfit();
			BeforeOutfit before2 = new BeforeOutfit();
			for (int pass = 0; pass < 2; pass++)
			{
				Outfit n = pass == 0 ? now : now2;
				BeforeOutfit o = pass == 0 ? before : before2;
				for (KitType slot : slots)
				{
					int kind = random.nextInt(5);
					int id = random.nextInt(3) == 0 ? random.nextInt(3) - 1 : random.nextInt(30000);
					if (kind == 0)
					{
						n.setItem(slot, id);
						o.setItem(slot, id);
					}
					else if (kind == 1)
					{
						n.setKit(slot, id);
						o.setKit(slot, id);
					}
					else if (kind == 2 && random.nextInt(6) == 0)
					{
						n.setProp(slot, id);
						o.setProp(slot, id);
					}
				}
				int[] colours = new int[random.nextInt(7)];
				for (int j = 0; j < colours.length; j++)
				{
					colours[j] = random.nextInt(3) == 0 ? 0 : random.nextInt(30);
				}
				if (random.nextBoolean())
				{
					n.setColors(colours);
					o.setColors(colours);
				}
				int gender = random.nextInt(3);
				n.setGender(gender);
				o.setGender(gender);
				if (random.nextInt(4) == 0)
				{
					for (KitType slot : slots)
					{
						if (random.nextBoolean())
						{
							n.clear(slot);
							o.clear(slot);
						}
					}
				}
			}
			String what = "outfit " + i + ": " + before;
			assertEquals(what, before.toString(), now.toString());
			assertEquals(what, before.isEmpty(), now.isEmpty());
			assertEquals(what, before.equals(before2), now.equals(now2));
			assertEquals(what, before.withDefaultBody().toString(), now.withDefaultBody().toString());
			assertEquals(what, before.withDefaultBody().equals(before), now.withDefaultBody().equals(now));
			Outfit copy = new Outfit(now);
			assertTrue(what, copy.equals(now) && now.equals(copy));
			assertEquals(what, now.hashCode(), copy.hashCode());
			assertEquals(what, before.toString(), copy.toString());
			if (now.equals(now2))
			{
				assertEquals(what, now.hashCode(), now2.hashCode());
			}
			assertTrue(what, !now.equals(null) && !now.equals(before) && now.equals(now));
		}
	}

	@Test
	public void outfitsReadFromACompositionAreTheSame()
	{
		Random random = new Random(6);
		for (int i = 0; i < OUTFITS / 5; i++)
		{
			int[] ids = random.nextInt(20) == 0 ? null : new int[random.nextInt(16)];
			for (int j = 0; ids != null && j < ids.length; j++)
			{
				int kind = random.nextInt(4);
				ids[j] = kind == 0 ? 0 : kind == 1 ? 256 + random.nextInt(2000) : kind == 2 ? 2048 + random.nextInt(30000)
					: random.nextInt(4000) - 100;
			}
			int[] colours = random.nextInt(10) == 0 ? null : new int[random.nextInt(7)];
			for (int j = 0; colours != null && j < colours.length; j++)
			{
				colours[j] = random.nextInt(30);
			}
			PlayerComposition composition = random.nextInt(30) == 0 ? null : composition(ids, colours, random.nextInt(3));
			Outfit now = Outfit.from(composition);
			BeforeOutfit before = BeforeOutfit.from(composition);
			assertEquals("composition " + i, before.toString(), now.toString());
			assertEquals("composition " + i, before.isEmpty(), now.isEmpty());
			for (KitType slot : KitType.values())
			{
				assertEquals("composition " + i + " " + slot, before.getRaw(slot), now.getRaw(slot));
			}
		}
	}

	@Test
	public void outfitsParsedAlikeAreEqualAndHashAlike()
	{
		Outfit x = OutfitParser.parse("HEAD=item:1149,gender=female,colors=1/2/3/4/5");
		Outfit y = OutfitParser.parse("HEAD=item:1149,gender=female,colors=1/2/3/4/5");
		assertTrue(x != y && x.equals(y));
		assertEquals(x.hashCode(), y.hashCode());
	}
}

package com.follower;

import com.google.gson.Gson;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ChatColorConfig;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.util.Text;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * QA3: New profile... named Melee, Ranged, Magic or Default follower wrote
 * the outfit worn over that look, and nothing restores a changed one; and
 * the list is written from both the event thread and the client thread.
 */
public class OutfitProfileGuardTest
{
	@Test
	public void aThrallLookIsNotWrittenOverByNewProfile() throws Exception
	{
		OutfitProfileStore store = new OutfitProfileStore(new Gson());
		store.load(null);
		String melee = store.get("Melee");
		String bare = store.get("Default follower");

		Constructor<ChatMessageManager> made = ChatMessageManager.class.getDeclaredConstructor(
			Client.class, ChatColorConfig.class, ClientThread.class, EventBus.class);
		made.setAccessible(true);
		ChatMessageManager chat = made.newInstance(null, null, null, new EventBus());

		FollowerPlugin plugin = new FollowerPlugin();
		set(plugin, "config", new FollowerConfig()
		{
			@Override
			public String customOutfit()
			{
				return "HEAD=item:1153";
			}
		});
		set(plugin, "chatMessageManager", chat);
		set(plugin, "profileStore", store);
		Method save = FollowerPlugin.class.getDeclaredMethod("saveOutfitProfile", String.class);
		save.setAccessible(true);
		save.invoke(plugin, "Melee");
		save.invoke(plugin, " Default follower ");

		assertEquals(melee, store.get("Melee"));
		assertEquals(bare, store.get("Default follower"));
		Field queue = ChatMessageManager.class.getDeclaredField("queuedMessages");
		queue.setAccessible(true);
		List<String> said = new ArrayList<>();
		for (Object message : (Collection<?>) queue.get(chat))
		{
			said.add(Text.unescapeJagex(((QueuedMessage) message).getRuneLiteFormattedMessage()));
		}
		assertEquals("one refusal each: " + said, 2, said.size());
		assertTrue(said.toString(), said.get(0).contains("'Melee'") && !said.get(0).contains("created"));
	}

	@Test
	public void twoThreadsSavingAtOnceLoseNoProfile() throws Exception
	{
		OutfitProfileStore store = new OutfitProfileStore(new Gson());
		store.load(null);
		int each = 500;
		Thread[] savers = new Thread[2];
		for (int t = 0; t < savers.length; t++)
		{
			String prefix = "t" + t + "-";
			savers[t] = new Thread(() ->
			{
				for (int i = 0; i < each; i++)
				{
					store.put(prefix + i, "");
				}
			});
		}
		for (Thread t : savers)
		{
			t.start();
		}
		for (Thread t : savers)
		{
			t.join();
		}
		assertEquals("the four built-in looks and every one saved", 4 + 2 * each, store.names().size());
	}

	private static void set(Object owner, String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(owner, value);
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Each RuneLite profile keeps its own outfit profiles.
 *
 * <p>Release play test, 29 Sep (and GitHub issue #1): one list in
 * outfit-profiles.json was shared by every RuneLite profile, every outfit
 * change saved into the selected name, and a profile switch reloaded that
 * name. Two profiles on "Default follower" wrote over each other, so
 * switching back put the other profile's outfit on this one.
 */
public class OutfitProfilesPerProfileTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final String SHARED = "{\"Default follower\": \"TORSO=item:23336,SHIELD=item:10352\"}";

	/** One RuneLite profile: its own settings, as a string the store reads and writes. */
	private static final class Profile
	{
		final AtomicReference<String> kept = new AtomicReference<>("");
		final OutfitProfileStore store = new OutfitProfileStore(new Gson());

		Profile load(Path dir, String active, String worn)
		{
			store.load(dir, kept.get(), active, worn, kept::set);
			return this;
		}
	}

	private Path sharedDir() throws IOException
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve("outfit-profiles.json"), SHARED.getBytes(StandardCharsets.UTF_8));
		return dir;
	}

	@Test
	public void anOutfitChangedOnOneProfileLeavesTheOtherAlone() throws IOException
	{
		Path dir = sharedDir();
		Profile a = new Profile().load(dir, "Default follower", "TORSO=item:23336,SHIELD=item:10352");
		Profile b = new Profile().load(dir, "Default follower", "TORSO=item:23336,SHIELD=item:10352");

		b.store.put("Default follower", "HEAD=item:25322");

		a.load(dir, "Default follower", "TORSO=item:23336,SHIELD=item:10352");
		assertEquals("switching back to A finds A's own",
			"TORSO=item:23336,SHIELD=item:10352", a.store.get("Default follower"));
		b.load(dir, "Default follower", "HEAD=item:25322");
		assertEquals("and B still has its edit", "HEAD=item:25322", b.store.get("Default follower"));
	}

	@Test
	public void aProfilesFirstLoadStartsFromTheSharedListWhichIsNeverWrittenAgain() throws IOException
	{
		Path dir = sharedDir();
		byte[] before = Files.readAllBytes(dir.resolve("outfit-profiles.json"));

		// A profile the old version ran: it had an outfit selected.
		Profile a = new Profile().load(dir, "Default follower", "TORSO=item:23336,SHIELD=item:10352");
		assertEquals("its list starts as the shared one",
			"TORSO=item:23336,SHIELD=item:10352", a.store.get("Default follower"));
		assertFalse("and is kept with the profile at once", a.kept.get().isEmpty());

		a.store.put("My costume", "WEAPON=item:4151");
		assertArrayEquals("the shared file is only read now",
			before, Files.readAllBytes(dir.resolve("outfit-profiles.json")));
	}

	@Test
	public void aProfilesFirstLoadKeepsTheOutfitItIsWearing() throws IOException
	{
		// Before this version another profile may already have written over
		// the shared entry; what this profile is wearing is the truer record.
		Path dir = sharedDir();
		Profile a = new Profile().load(dir, "Default follower", "HEAD=item:25322,TORSO=item:23336");

		assertEquals("HEAD=item:25322,TORSO=item:23336", a.store.get("Default follower"));
	}

	@Test
	public void aProfileWithItsOwnListIgnoresTheSharedFile() throws IOException
	{
		Path dir = sharedDir();
		Profile a = new Profile().load(dir, null, null);
		a.store.put("Default follower", "HEAD=item:1");

		Files.write(dir.resolve("outfit-profiles.json"),
			"{\"Default follower\": \"HEAD=item:2\"}".getBytes(StandardCharsets.UTF_8));
		a.load(dir, null, null);

		assertEquals("HEAD=item:1", a.store.get("Default follower"));
	}

	/**
	 * Review, 29 Sep: RuneLite's Reset clears the hidden list with the rest,
	 * and a profile made after the upgrade never had one. Neither ran the old
	 * version, so neither starts from the shared list as it stood on the day
	 * of the upgrade: both start from the defaults.
	 */
	@Test
	public void aProfileTheOldVersionNeverRanStartsFromTheDefaults() throws IOException
	{
		Path dir = sharedDir();
		Profile reset = new Profile().load(dir, "", "");

		assertEquals("the bare body, not the shared entry", "", reset.store.get("Default follower"));
	}

	@Test
	public void aNewProfileStillHasTheThrallStyles() throws IOException
	{
		Profile a = new Profile().load(folder.newFolder().toPath(), null, null);
		for (String name : new String[]{"Melee", "Ranged", "Magic", OutfitProfileStore.DEFAULT_PROFILE})
		{
			assertTrue(name, a.store.get(name) != null);
		}
	}

	/**
	 * The switch is glue no harness drives, so it is read out of the source:
	 * the new profile's list has to be read before its outfit is restored
	 * from it, or the switch restores from the last profile's list.
	 */
	@Test
	public void aSwitchReadsTheNewProfilesListBeforeRestoringItsOutfit() throws IOException
	{
		String source = PublicMarkers.strip(new String(Files.readAllBytes(
			Paths.get("src/main/java/com/follower/FollowerPlugin.java")), StandardCharsets.UTF_8));
		int handler = source.indexOf("void onProfileChanged(");
		int end = source.indexOf("\n\t}", handler);
		String body = source.substring(handler, end);
		int load = body.indexOf("loadOutfitProfiles();");
		int restore = body.indexOf("restoreActiveProfile();");
		assertTrue("the switch reads the new profile's list", load >= 0);
		assertTrue("before it restores the outfit from it", restore > load);
	}
}

package com.follower;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import net.runelite.api.kit.KitType;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * An outfit written out and read back must be the same outfit.
 *
 * <p>This is the format users copy between profiles and paste to each other, so
 * anything that drops on the way through is a bug someone hits by sharing a
 * costume. The round trip is checked exhaustively over every slot and then
 * fuzzed, because the failure would be one slot in twelve rather than the
 * whole string.
 */
public class OutfitRoundTripTest
{
	private static Outfit reparse(Outfit outfit)
	{
		return OutfitParser.parse(outfit.toString());
	}

	// ------------------------------------------------------------ round trip

	@Test
	public void anEmptyOutfitSurvives()
	{
		Outfit empty = new Outfit();
		assertTrue(empty.isEmpty());
		assertEquals(empty, reparse(empty));
	}

	@Test
	public void everySlotSurvivesAsAnItem()
	{
		for (KitType slot : KitType.values())
		{
			Outfit outfit = new Outfit();
			outfit.setItem(slot, 4151);
			Outfit back = reparse(outfit);

			assertTrue(slot + " should still hold an item", back.isItem(slot));
			assertEquals(slot + " lost its item id", 4151, back.itemId(slot));
			assertEquals("round trip changed " + slot, outfit, back);
		}
	}

	@Test
	public void everySlotSurvivesAsAKit()
	{
		for (KitType slot : KitType.values())
		{
			Outfit outfit = new Outfit();
			outfit.setKit(slot, 42);
			Outfit back = reparse(outfit);

			assertTrue(slot + " should still hold a kit", back.isKit(slot));
			assertEquals(slot + " lost its kit id", 42, back.kitId(slot));
			assertEquals("round trip changed " + slot, outfit, back);
		}
	}

	@Test
	public void kitZeroIsAKitNotAnEmptySlot()
	{
		// The parser treats a bare "0" as "clear this slot", so a kit whose id
		// really is zero has to survive as "kit:0" rather than being erased.
		Outfit outfit = new Outfit();
		outfit.setKit(KitType.HAIR, 0);
		Outfit back = reparse(outfit);

		assertTrue("kit 0 was read as an empty slot", back.isKit(KitType.HAIR));
		assertEquals(0, back.kitId(KitType.HAIR));
	}

	@Test
	public void genderSurvivesBothWays()
	{
		Outfit female = new Outfit();
		female.setGender(1);
		assertEquals(1, reparse(female).getGender());

		Outfit male = new Outfit();
		male.setGender(0);
		assertEquals(0, reparse(male).getGender());
	}

	@Test
	public void bodyColoursSurvive()
	{
		Outfit outfit = new Outfit();
		outfit.setColors(new int[]{3, 0, 7, 1, 5});
		Outfit back = reparse(outfit);

		assertArrayEquals("the panel's colour choices were lost on save",
			new int[]{3, 0, 7, 1, 5}, back.getColors());
	}

	@Test
	public void aFullyDressedOutfitSurvives()
	{
		Outfit outfit = new Outfit();
		outfit.setItem(KitType.WEAPON, 4151);
		outfit.setItem(KitType.SHIELD, 8850);
		outfit.setItem(KitType.HEAD, 11832);
		outfit.setItem(KitType.TORSO, 11834);
		outfit.setItem(KitType.LEGS, 11836);
		outfit.setKit(KitType.HAIR, 3);
		outfit.setKit(KitType.JAW, 10);
		outfit.setGender(1);
		outfit.setColors(new int[]{1, 2, 3, 4, 5});

		assertEquals(outfit, reparse(outfit));
	}

	@Test
	public void randomOutfitsAlwaysSurvive()
	{
		Random random = new Random(20260808L);
		for (int i = 0; i < 3000; i++)
		{
			Outfit outfit = new Outfit();
			for (KitType slot : KitType.values())
			{
				switch (random.nextInt(3))
				{
					case 0:
						outfit.setItem(slot, random.nextInt(30000));
						break;
					case 1:
						outfit.setKit(slot, random.nextInt(600));
						break;
					default:
						break;
				}
			}
			outfit.setGender(random.nextInt(2));
			outfit.setColors(new int[]{
				random.nextInt(30), random.nextInt(30), random.nextInt(30),
				random.nextInt(30), random.nextInt(30)});

			Outfit back = reparse(outfit);
			assertEquals("lost on round trip: " + outfit, outfit, back);
		}
	}

	// ------------------------------------------------------------ the parser

	@Test
	public void theParserAcceptsWhatPeopleActuallyType()
	{
		Outfit outfit = OutfitParser.parse(
			"  WEAPON = item:4151 ,\n"
				+ "# a comment line\n"
				+ "// another\n"
				+ "hair=kit:3,\n"
				+ "GENDER=Female,\n"
				+ "colours = 1/2/3/4/5\n");

		assertEquals(4151, outfit.itemId(KitType.WEAPON));
		assertEquals(3, outfit.kitId(KitType.HAIR));
		assertEquals(1, outfit.getGender());
		assertArrayEquals(new int[]{1, 2, 3, 4, 5}, outfit.getColors());
	}

	@Test
	public void aBareNumberIsAnItemBecauseThatIsWhatPeopleMean()
	{
		assertEquals(4151, OutfitParser.parse("weapon=4151").itemId(KitType.WEAPON));
	}

	@Test
	public void clearingASlotHasThreeSpellings()
	{
		for (String spelling : new String[]{"none", "-1", "0"})
		{
			Outfit outfit = OutfitParser.parse("weapon=item:4151,weapon=" + spelling);
			assertEquals("'" + spelling + "' should empty the slot",
				0, outfit.getRaw(KitType.WEAPON));
		}
	}

	@Test
	public void badInputIsReportedRatherThanSilentlyDropped()
	{
		// One of each mistake, checked by what it says rather than by counting,
		// so the test explains which report went missing.
		assertReports("weapon", "Missing '='");
		assertReports("hat=item:1", "Unknown slot");
		assertReports("weapon=item:abc", "is not a number");
		assertReports("weapon=hat:5", "Expected 'item' or 'kit'");
		assertReports("colors=a/b", "Bad colour index");
	}

	private static void assertReports(String text, String expected)
	{
		List<String> errors = new ArrayList<>();
		OutfitParser.parse(text, errors);
		for (String error : errors)
		{
			if (error.contains(expected))
			{
				return;
			}
		}
		throw new AssertionError("'" + text + "' should have reported \""
			+ expected + "\", said " + errors);
	}

	@Test
	public void aGoodOutfitReportsNothing()
	{
		List<String> errors = new ArrayList<>();
		OutfitParser.parse("weapon=item:4151,hair=kit:3,gender=female,colors=1/2/3/4/5",
			errors);
		assertTrue("a valid outfit should not warn: " + errors, errors.isEmpty());
	}

	@Test
	public void nonsenseNeverThrows()
	{
		String[] nonsense = {
			null, "", "   ", ",,,,", "=", "=5", "weapon=", "weapon=item:",
			"weapon=item:99999999999999999999", "weapon=kit:-5",
			"colors=", "colors=a/b/c", "colors=1/2/3/4/5/6/7/8/9",
			"gender=", "gender=banana", "\n\n\n", "#only a comment",
		};
		for (String text : nonsense)
		{
			Outfit outfit = OutfitParser.parse(text);
			// Whatever it made of it, it must still be usable.
			outfit.toString();
			outfit.withDefaultBody();
		}
	}

	@Test
	public void moreColoursThanTheGameHasAreIgnoredNotOverflowed()
	{
		Outfit outfit = OutfitParser.parse("colors=1/2/3/4/5/6/7/8");
		assertArrayEquals("only the five the game has should be taken",
			new int[]{1, 2, 3, 4, 5}, outfit.getColors());
	}

	// ------------------------------------------------------- the default body

	@Test
	public void theDefaultBodyFillsEmptyPartsAndLeavesGearAlone()
	{
		Outfit outfit = new Outfit();
		outfit.setItem(KitType.TORSO, 11834);
		outfit.setKit(KitType.HAIR, 99);

		Outfit dressed = outfit.withDefaultBody();

		assertEquals("gear must win over a default kit",
			11834, dressed.itemId(KitType.TORSO));
		assertEquals("a chosen kit must not be replaced", 99, dressed.kitId(KitType.HAIR));
		assertFalse("the empty parts should have been filled", dressed.isEmpty());
	}

	@Test
	public void theDefaultBodyDoesNotModifyTheOutfitItWasBuiltFrom()
	{
		Outfit outfit = new Outfit();
		outfit.withDefaultBody();
		assertTrue("withDefaultBody must return a copy, not dress in place",
			outfit.isEmpty());
	}

	@Test
	public void bothGendersHaveADefaultBody()
	{
		for (int gender : new int[]{0, 1})
		{
			Outfit outfit = new Outfit();
			outfit.setGender(gender);
			assertFalse("gender " + gender + " has no default body at all",
				outfit.withDefaultBody().isEmpty());
		}
	}

	// -------------------------------------------------------------- equality

	@Test
	public void equalityCoversEverythingThatCanDiffer()
	{
		Outfit base = new Outfit();
		base.setItem(KitType.WEAPON, 4151);
		base.setGender(0);
		base.setColors(new int[]{1, 1, 1, 1, 1});

		Outfit copy = new Outfit(base);
		assertEquals(base, copy);
		assertEquals(base.hashCode(), copy.hashCode());

		Outfit differentGender = new Outfit(base);
		differentGender.setGender(1);
		assertFalse("gender must count", base.equals(differentGender));

		Outfit differentColour = new Outfit(base);
		differentColour.setColors(new int[]{2, 1, 1, 1, 1});
		assertFalse("colours must count", base.equals(differentColour));

		Outfit differentItem = new Outfit(base);
		differentItem.setItem(KitType.WEAPON, 1234);
		assertFalse("gear must count", base.equals(differentItem));
	}

	@Test
	public void aCopyIsIndependentOfItsOriginal()
	{
		Outfit base = new Outfit();
		base.setItem(KitType.WEAPON, 4151);

		Outfit copy = new Outfit(base);
		copy.setItem(KitType.WEAPON, 1234);
		copy.setColors(new int[]{9, 9, 9, 9, 9});

		assertEquals("editing a copy changed the original", 4151, base.itemId(KitType.WEAPON));
		assertArrayEquals(new int[]{0, 0, 0, 0, 0}, base.getColors());
	}

	@Test
	public void getColorsHandsOutACopyNotTheInternals()
	{
		Outfit outfit = new Outfit();
		int[] colours = outfit.getColors();
		colours[0] = 99;
		assertEquals("getColors leaked the internal array", 0, outfit.getColors()[0]);
	}
}

package com.follower;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;

import static com.follower.OutfitProfileStore.DEFAULT_PROFILE;
import static org.junit.Assert.assertEquals;

/**
 * outfits.tsv holds the ready-made outfit profiles a first install starts
 * with, so a slip in it must fail here. The profiles as the code wrote them
 * before they moved there are kept below as they stood: the same names and
 * outfits, in the same order.
 */
public class OutfitsFileTest
{
	@Test
	public void theFileGivesTheProfilesTheCodeGave() throws Exception
	{
		Map<String, String> before = new LinkedHashMap<>();
		// An empty outfit is the plain default body with no clothing.
		before.put(DEFAULT_PROFILE, "");
		before.put("Melee",
			"HEAD=item:1149,WEAPON=item:21009,TORSO=item:3140,SHIELD=item:21895,ARMS=kit:26,"
				+ "LEGS=item:4087,HAIR=kit:0,HANDS=kit:33,BOOTS=kit:42,JAW=kit:10");
		before.put("Ranged",
			"HEAD=item:2581,WEAPON=item:841,TORSO=item:12596,ARMS=kit:98,LEGS=item:23249,"
				+ "HAIR=kit:128,HANDS=kit:69,BOOTS=kit:79,JAW=kit:296,gender=female");
		before.put("Magic",
			"HEAD=item:7394,AMULET=item:10366,WEAPON=item:1383,TORSO=item:7390,SHIELD=item:6889,"
				+ "ARMS=kit:98,LEGS=item:7386,HAIR=kit:143,HANDS=kit:69,BOOTS=item:2579,"
				+ "JAW=kit:296,gender=female");

		Field field = OutfitProfileStore.class.getDeclaredField("DEFAULTS");
