	private static void collectButtons(java.awt.Container root, List<javax.swing.AbstractButton> out)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof javax.swing.AbstractButton)
			{
				out.add((javax.swing.AbstractButton) c);
			}
			else if (c instanceof java.awt.Container)
			{
				collectButtons((java.awt.Container) c, out);
			}
		}
	}

	/** The look the window was built under, put back afterwards. */
	private LookAndFeel before;

	@After
	public void restoreTheLook() throws Exception
	{
		if (before != null)
		{
			LookAndFeel look = before;
			SwingUtilities.invokeAndWait(() ->
			{
				try
				{
					UIManager.setLookAndFeel(look);
				}
				catch (Exception e)
				{
					throw new IllegalStateException(e);
				}
			});
		}
	}

	private PhrasesDialog dialog(boolean open) throws Exception
	{
		return dialog(open, CATEGORIES);
	}

	private PhrasesDialog dialog(boolean open, List<PhrasesDialog.Category> categories) throws Exception
	{
		// The client's own look: its text areas' carets are what scrolled.
		before = UIManager.getLookAndFeel();
		SwingUtilities.invokeAndWait(RuneLiteLAF::setup);
		Path file = folder.newFile("phrases.json").toPath();
		Files.copy(Paths.get("src/main/resources/com/follower/default-phrases.json"), file,
			java.nio.file.StandardCopyOption.REPLACE_EXISTING);
		PhrasesDialog[] made = new PhrasesDialog[1];
		SwingUtilities.invokeAndWait(() ->
		{
			made[0] = new PhrasesDialog(new Gson(), file, categories, () -> 12850)
			{
				@Override
				public void setVisible(boolean b)
				{
					// Laid out and measured, never put on screen.
				}
			};
			if (open)
			{
				made[0].open();
			}
		});
		return made[0];
	}

	/** Runs what the window queued, a few rounds deep, then lays it out. */
	private static void settle(PhrasesDialog dialog) throws Exception
	{
		for (int i = 0; i < 4; i++)
		{
			SwingUtilities.invokeAndWait(() -> { });
		}
		SwingUtilities.invokeAndWait(dialog::validate);
		for (int i = 0; i < 4; i++)
		{
			SwingUtilities.invokeAndWait(() -> { });
		}
	}

	private static Object field(Object owner, String name) throws Exception
	{
		// Fields the two file editors share live on their base class.
		Field f;
		try
		{
			f = PhrasesDialog.class.getDeclaredField(name);
		}
		catch (NoSuchFieldException e)
		{
			f = EditorDialog.class.getDeclaredField(name);
		}
		f.setAccessible(true);
		return f.get(owner);
	}

	private static JsonObject rule(String json)
	{
		return new Gson().fromJson(json, JsonObject.class);
	}
}

package com.follower;

import java.io.IOException;
import java.util.Collections;
import net.runelite.api.NPC;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * What a place holds names the moment, as a memory does. Text QA5, 17 Oct:
 * "Same spot. This is where it went wrong for you." and "You may not
 * remember. This is where it went wrong for you." told the player nothing.
 *
 * <p>The forms here are written to try the machinery; the last test holds
 * the shipped rules to the same.
 */
public class PlaceMemoryNamesTheMomentTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final String DEATH = "{\"id\": \"death-moment\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"markHere\": \"you died to the {foe}\", \"markHereOr\": [\"you died\"],"
		+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"Get up!\"]}";

	private Harness harness(String rules) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), "{\"version\": 1, \"rules\": [" + rules + "]}");
		h.game.at(3090, 3490, 0);
		h.gameTicks(1);
		return h;
	}

	private static String held(Harness h)
	{
		TriggerContext c = h.engine.getContext();
		return c.getPlaceMemories().get(c.getRegionId());
	}

	@Test
	public void thePlaceIsMarkedWithWhatHappened() throws IOException
	{
		Harness h = harness(DEATH);
		NPC giant = h.game.spawnNpc(2098, "Hill Giant", 28);
		h.game.fighting(giant);
		h.gameTicks(3);
		h.dispatch(TriggerEvent.death());
		assertEquals("you died to the Hill Giant", held(h));
	}

	@Test
	public void withNothingKnownAPlainerFormIsFiled() throws IOException
	{
		Harness h = harness(DEATH);
		h.dispatch(TriggerEvent.death());
		assertEquals("you died", held(h));
	}

	@Test
	public void theOldMarksAreNeverSaid() throws IOException
	{
		Harness h = harness("");
		TriggerContext c = h.engine.getContext();
		for (String old : new String[]{"it went wrong for you", "you got that drop", "you put that thing down",
			"you hit harder than you ever had"})
		{
			c.restorePlaces(Collections.singletonMap(c.getRegionId(), old));
			assertFalse(old, c.hasPlaceMemory());
		}
		c.restorePlaces(Collections.singletonMap(c.getRegionId(), "you died"));
		assertTrue(c.hasPlaceMemory());
	}

	@Test
	public void aLineFilledTooLongGivesWayToOneThatFits() throws IOException
	{
		Harness h = harness("{\"id\": \"place-remembers\", \"group\": \"t\", \"cooldownMs\": 0,"
			+ " \"when\": {\"type\": \"levelUp\", \"names\": [\"Attack\"]},"
			+ " \"say\": [\"You may not remember. This is where {here}.\", \"Here. {here}.\"]}");
		TriggerContext c = h.engine.getContext();
		c.restorePlaces(Collections.singletonMap(c.getRegionId(),
			"the Twisted ancestral colour kit dropped off the Great Olm"));
		for (int i = 0; i < 6; i++)
		{
			h.dispatch(TriggerEvent.levelUp("Attack", 30 + i));
			h.gameTicks(1);
		}
		assertEquals(6, h.firedBy("place-remembers").size());
		for (Harness.Spoken said : h.firedBy("place-remembers"))
		{
			assertTrue(said.text, said.text.length() <= SpeechEngine.OVERHEAD_MAX_CHARS);
		}
	}

	/**
	 * The shipped marks name the moment, so place-remembers, quiet while the
	 * old words were all it had, has something to say again.
	 */
	@Test
	public void theShippedMarksAreOnesThePlaceSays() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.at(3090, 3490, 0);
		h.gameTicks(1);
		int marks = 0;
		for (SpeechRule rule : h.loader.getRules())
		{
			if (rule.markHere == null)
			{
				continue;
			}
			marks++;
			assertFalse(rule.id, TriggerContext.isVague(rule.markHere));
			for (String form : rule.markHereOr == null ? Collections.<String>emptyList() : rule.markHereOr)
			{
				assertFalse(rule.id, TriggerContext.isVague(form));
			}
		}
		assertTrue("the marking rules were found", marks >= 4);

		NPC giant = h.game.spawnNpc(2098, "Hill Giant", 28);
		h.game.fighting(giant);
		h.gameTicks(3);
		h.dispatch(TriggerEvent.death());
		assertEquals("you died to the Hill Giant", held(h));

		TriggerContext c = h.engine.getContext();
		h.game.at(3222, 3218, 0);
		h.gameTicks(TriggerContext.MEMORY_MIN_AGE_TICKS);
		h.game.at(3090, 3490, 0);
		h.gameTicks(2);
		assertTrue("back after twenty minutes, the place holds it", c.hasPlaceMemory());
	}
}

package com.follower;

import java.lang.reflect.Method;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The follower gives way to another player standing on its tile, as it does
 * to an NPC. Play test, 16 Oct: "make it so the follower disappears when
 * they stop on the same tile as another player".
 */
public class PlayerOverlapTest
{
	private final FakeGame game = new FakeGame().at(50, 50, 0);
	private final FollowerEntity follower = new FollowerEntity(game.client, null);

	@Test
	public void anotherPlayerStandingThereHidesIt()
	{
		game.spawnPlayer(2, 0);
		assertTrue("stopped on the follower's tile", playerOn(new WorldPoint(52, 50, 0)));
		assertFalse("and nobody on the next one", playerOn(new WorldPoint(53, 50, 0)));
	}

	@Test
	public void oneWalkingThroughDoesNot()
	{
		Player passing = game.spawnPlayer(2, 0);
		game.otherWalking(passing);
		assertFalse("a moment, not worth a blink", playerOn(new WorldPoint(52, 50, 0)));
	}

	@Test
	public void theLocalPlayerDoesNot()
	{
		assertFalse("the follower keeps off them by itself", playerOn(new WorldPoint(50, 50, 0)));
	}

	@Test
	public void theDrawHidesForAPlayerAsForAnNpc() throws java.io.IOException
	{
		String source = PublicMarkers.strip(new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(
			"src/main/java/com/follower/FollowerEntity.java")), java.nio.charset.StandardCharsets.UTF_8));
		assertTrue(source.contains("hiddenForNpcOverlap = isSettled() && (npcOnTile(tile) || playerOnTile(tile));"));
	}

	private boolean playerOn(WorldPoint where)
	{
		try
		{
			Method on = FollowerEntity.class.getDeclaredMethod("playerOnTile", WorldPoint.class);
			on.setAccessible(true);
			return (Boolean) on.invoke(follower, where);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError("FollowerEntity.playerOnTile has moved", e);
		}
	}
}

package com.follower;

import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * A follower left waiting comes back to its post after a relog, rather than
 * being drawn back beside the player as every other arrival is.
 *
 * <p>Review, 29 Sep: the spawn put every tile through the two-step landing
 * search, so a post further than two steps from the player was swapped for a
 * tile beside them, and the next tick saved that over the post. The post is
 * taken as given only where the follower could stand and walk to it from the
 * player within its leash; anywhere else it lands beside them as before.
 */
public class PostArrivalTest
{
	private static final WorldPoint PLAYER = new WorldPoint(10, 10, 0);
	private static final WorldPoint POST = new WorldPoint(20, 14, 0);

	private static FollowerEntity followerOn(FakeGame game)
	{
		return new FollowerEntity(game.client, null);
	}

	@Test
	public void aPostItCouldWalkToIsWhereItArrives()
	{
		FollowerEntity follower = followerOn(new FakeGame().withCollision());

		assertEquals(POST, follower.arrivalTile(POST, PLAYER, true));
		assertNotEquals("an ordinary arrival still lands beside the player",
			POST, follower.arrivalTile(POST, PLAYER, false));
	}

	@Test
	public void aPostItCannotStandOnIsNot()
	{
		FakeGame game = new FakeGame().withCollision().blockTile(POST.getX(), POST.getY());

		assertTrue("beside the player instead",
			followerOn(game).arrivalTile(POST, PLAYER, true).distanceTo(PLAYER) <= 2);
	}

	@Test
	public void aPostOnFireIsNot()
	{
		FollowerEntity follower = followerOn(new FakeGame().withCollision());
		follower.setHotGround(POST::equals);

		assertTrue(follower.arrivalTile(POST, PLAYER, true).distanceTo(PLAYER) <= 2);
	}

	/**
	 * A bank booth the map calls open floor: a post kept there from before
	 * the feet refused one would put it back inside at every login.
	 */
	@Test
	public void aPostInABoothIsNot()
	{
		FakeGame game = new FakeGame().withCollision().furniture(POST.getX(), POST.getY(), 0, 10, 0, 224);

		assertTrue(followerOn(game).arrivalTile(POST, PLAYER, true).distanceTo(PLAYER) <= 2);
	}

	@Test
	public void aPostWalledOffFromThePlayerIsNot()
	{
		FakeGame game = new FakeGame().withCollision();
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (dx != 0 || dy != 0)
				{
					game.blockTile(POST.getX() + dx, POST.getY() + dy);
				}
			}
		}

		assertTrue("standable, but nothing walks there",
			followerOn(game).arrivalTile(POST, PLAYER, true).distanceTo(PLAYER) <= 2);
	}

	@Test
	public void aPostPastItsLeashIsNot()
	{
		FollowerEntity follower = followerOn(new FakeGame().withCollision());
		WorldPoint edge = new WorldPoint(PLAYER.getX() + FollowerEntity.STAY_LEASH - 2, PLAYER.getY(), 0);
		WorldPoint past = new WorldPoint(edge.getX() + 1, edge.getY(), 0);

		assertEquals("at the edge of its reach it still comes back", edge, follower.arrivalTile(edge, PLAYER, true));
		assertTrue(follower.arrivalTile(past, PLAYER, true).distanceTo(PLAYER) <= 2);
	}
}

package com.follower;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.SwingUtilities;
import javax.swing.event.ListDataEvent;
import javax.swing.event.ListDataListener;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The side panel's outfit profiles. New profile... over a name already in
 * the list asks first, and the plugin's setters reach the dropdowns and the
 * Mute box on the event thread whichever thread calls them (QA3).
 */
public class ProfilePanelTest
{
	private static final List<String> NAMES =
		Arrays.asList("Default follower", "Melee", "Ranged", "Magic", "Fishing");

	private final List<String> saved = new ArrayList<>();
	private final List<String> asked = new ArrayList<>();
	private boolean answer;

	@Test
	public void aNameAlreadyTakenIsReplacedOnlyWhenThePlayerSaysSo() throws Exception
	{
		FollowerPanel panel = panel();
		SwingUtilities.invokeAndWait(() ->
		{
			panel.newProfile("Mining");
			assertEquals("a new name asks nothing", Arrays.asList("Mining"), saved);
			assertTrue(asked.isEmpty());

			answer = false;
			panel.newProfile(" Fishing ");
			assertEquals("asked about the profile it would write over", Arrays.asList("Fishing"), asked);
			assertEquals("and No keeps it", Arrays.asList("Mining"), saved);

			answer = true;
			panel.newProfile("Fishing");
			assertEquals("Yes replaces it", Arrays.asList("Mining", "Fishing"), saved);

			// A thrall look is not offered for replacing; the plugin refuses it.
			asked.clear();
			panel.newProfile("Melee");
			assertTrue("not asked about", asked.isEmpty());
			assertEquals("Melee", saved.get(saved.size() - 1));

			saved.clear();
			panel.newProfile("   ");
			panel.newProfile(null);
			assertTrue("blank or cancelled is nothing", saved.isEmpty());
		});
	}

	@Test
	public void theDropdownsAndMuteAreChangedOnlyOnTheEventThread() throws Exception
	{
		FollowerPanel panel = panel();
		List<String> offThread = new ArrayList<>();
		SwingUtilities.invokeAndWait(() ->
		{
			for (java.awt.Component c : all(panel))
			{
				if (c instanceof JComboBox && ((JComboBox<?>) c).getModel() instanceof javax.swing.DefaultComboBoxModel)
				{
					((JComboBox<?>) c).getModel().addListDataListener(new ListDataListener()
					{
						@Override
						public void intervalAdded(ListDataEvent e)
						{
							note(offThread, "combo add");
						}

						@Override
						public void intervalRemoved(ListDataEvent e)
						{
							note(offThread, "combo remove");
						}

						@Override
						public void contentsChanged(ListDataEvent e)
						{
							note(offThread, "combo select");
						}
					});
				}
				if (c instanceof JCheckBox)
				{
					((JCheckBox) c).getModel().addChangeListener(e -> note(offThread, "box"));
				}
			}
		});

		// As a profile switch does: from a thread that is not Swing's.
		panel.setProfileNames(Arrays.asList("Default follower", "Melee", "Woodcutting"), "Woodcutting");
		panel.setSetting("muted", true);
		SwingUtilities.invokeAndWait(() -> { });

		assertTrue("Swing touched off its thread: " + offThread, offThread.isEmpty());
		SwingUtilities.invokeAndWait(() -> assertEquals("and still applied", "Woodcutting",
			profileCombo(panel).getSelectedItem()));
	}

	private static void note(List<String> offThread, String what)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			synchronized (offThread)
			{
				offThread.add(what + " on " + Thread.currentThread().getName());
			}
		}
	}

	private FollowerPanel panel() throws Exception
	{
		FollowerPanel[] made = new FollowerPanel[1];
		SwingUtilities.invokeAndWait(() ->
		{
			made[0] = new FollowerPanel(null, new ModelRepository(new Gson()),
				(a, b) -> { }, k -> { }, () -> { }, () -> { }, g -> { }, (k, d) -> { }, (c, p) -> { },
				"outfit")
			{
				@Override
				boolean confirmReplace(String name)
				{
					asked.add(name);
					return answer;
				}
			};
			made[0].setOnProfileSave(saved::add);
			made[0].setProfileProtected(n -> Arrays.asList("Default follower", "Melee", "Ranged", "Magic").contains(n));
		});
		made[0].setProfileNames(NAMES, "Fishing");
		SwingUtilities.invokeAndWait(() -> { });
		return made[0];
	}

	private static JComboBox<?> profileCombo(FollowerPanel panel)
	{
		try
		{
			java.lang.reflect.Field f = FollowerPanel.class.getDeclaredField("profileCombo");
			f.setAccessible(true);
			return (JComboBox<?>) f.get(panel);
		}
		catch (ReflectiveOperationException e)
		{
			throw new IllegalStateException(e);
		}
	}

	private static List<java.awt.Component> all(java.awt.Container root)
	{
		List<java.awt.Component> out = new ArrayList<>();
		for (java.awt.Component c : root.getComponents())
		{
			out.add(c);
			if (c instanceof java.awt.Container)
			{
				out.addAll(all((java.awt.Container) c));
			}
		}
		return out;
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.ProfileChanged;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * A RuneLite profile switch: the old profile's session goes, and the new
 * one's memory is read. What the switch does to the engine, and when it
 * must do nothing at all.
 */
public class ProfileSwitchTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final String LOGIN_RULES = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"greet\", \"group\": \"t\", \"cooldownMs\": 0, \"delayTicks\": 3,"
		+ " \"when\": {\"type\": \"login\"}, \"say\": [\"there you are\"]},"
		+ "{\"id\": \"update\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"gameUpdated\"}, \"say\": [\"the world moved\"]}]}";

	/** Stands in for the gear worn and the place stood in: true all along. */
	private static final String WORLD_RULES = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"gear\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"always\"}, \"say\": [\"nice hat\"]}]}";

	private Harness harness(String rules) throws IOException
	{
		return new Harness(folder.newFolder().toPath(), rules);
	}

	/** The engine's half of the switch, in the plugin's order. */
	private static void switchProfile(Harness h, boolean loginComing)
	{
		h.engine.reset();
		if (FollowerPlugin.switchTakesTheBaseline(loginComing))
		{
			h.engine.primeEdgesOnNextTick();
		}
	}

	@Test
	public void aSwitchAtTheLoginScreenLeavesTheBaselineToTheLogin() throws IOException
	{
		// Primed at the login screen, the window had no ticks to run it
		// down there, and was still open when the login said hello: the
		// greeting was discarded with everything else, and so was the week's
		// update line, which is marked as told straight after.
		Harness h = harness(LOGIN_RULES);
		h.engine.reset();
		switchProfile(h, true);

		// The login, as the plugin does it: the hello, the news, then the
		// login's own baseline.
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.GAME_UPDATE));
		h.engine.primeEdgesOnNextTick();
		h.gameTicks(8);

		assertEquals("the login after the switch is greeted", 1, h.firedBy("greet").size());
		assertEquals("and told the game changed", 1, h.firedBy("update").size());
	}

	@Test
	public void aSwitchInTheWorldTakesTheBaselineItself() throws IOException
	{
		// No login is coming to do it. The reset clears every edge, and
		// without the window the gear worn all along rose as news.
		Harness h = harness(WORLD_RULES);
		h.gameTicks(3);
		assertEquals("the stand-in speaks once, when first seen", 1, h.firedBy("gear").size());
		h.clear();

		switchProfile(h, false);
		h.gameTicks(6);

		assertTrue("nothing that was true before the switch is news after it",
			h.firedBy("gear").isEmpty());
	}

	@Test
	public void aSwitchAtTheLoginScreenIsNotReadAgainByTheLogin()
	{
		// The switch reads the new profile's memory in, and nothing between
		// it and the login lets it go. The login read it again on top, and
		// the tallies and the line wear merge by adding: every count doubled
		// and was saved that way at once, and again at every switch made at
		// the login screen after it.
		Gson gson = new Gson();
		TriggerContext kept = new TriggerContext(new FakeGame().client);
		for (int i = 0; i < 40; i++)
		{
			kept.tally("kill:goblin");
		}
		kept.noteLineSaid("A line said once.");
		String stored = FollowerPlugin.snapshotMemory(kept, 0, gson);
		long profile = 7L;

		// Logged out: the memory is blank and nobody's.
		TriggerContext context = new TriggerContext(new FakeGame().client);
		long readFrom = -1L;
		assertTrue("a login after a logout reads it",
			FollowerPlugin.loginReadsTheMemory(readFrom, profile));

		// The switch at the login screen reads this profile's.
		FollowerPlugin.restoreMemory(context, stored, gson, 0);
		readFrom = profile;

		// Then the login, in the plugin's order.
		if (FollowerPlugin.loginReadsTheMemory(readFrom, profile))
		{
			FollowerPlugin.restoreMemory(context, stored, gson, 0);
		}
		assertEquals("counted once", 40, context.getTally("kill:goblin"));
		assertEquals("and worn once", 1, context.lineWear("A line said once."));
		assertEquals("so what the login saves is what was stored",
			stored, FollowerPlugin.snapshotMemory(context, 0, gson));
	}

	@Test
	public void aSwitchThatReachesAStoppedPluginDoesNothing() throws Exception
	{
		// Switched to a profile where the plugin is off, RuneLite stops it on
		// the Swing thread while the switch's own work waits on the client
		// thread, and the stop can come first. The work then read the new
		// profile's memory into the engine the stop had just cleared, and the
		// next start read its own on top: two memories added together, and
		// saved that way. This plugin was never started and nothing else in
		// it is filled in, so a switch that goes ahead falls over on the
		// first thing it needs.
		Harness h = harness(LOGIN_RULES);
		FollowerPlugin plugin = new FollowerPlugin();
		set(plugin, "clientThread", onTheClientThread());
		set(plugin, "speechEngine", h.engine);
		Object before = h.engine.getContext();

		plugin.onProfileChanged(new ProfileChanged());

		assertSame("the engine is left as the stop left it", before, h.engine.getContext());
	}

	/** A client thread that runs what it is given at once, as on the client thread itself. */
	private static ClientThread onTheClientThread() throws ReflectiveOperationException
	{
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class},
			(proxy, method, args) -> method.getName().equals("isClientThread") ? Boolean.TRUE : null);
		ClientThread thread = new ClientThread();
		Field field = ClientThread.class.getDeclaredField("client");
		field.setAccessible(true);
		field.set(thread, client);
		return thread;
	}

	private static void set(Object target, String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(target, value);
	}
}

package com.follower;

import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The rule-sized writing gesture: stop, scroll out, pose, everything back.
 *
 * <p>Same lifecycle promises as the errand's scroll handling, tested the same
 * way: the prop leads the pose by the settle ticks, the cleanup runs whole
 * from both the finish and the abort, and a second request mid-gesture is
 * dropped rather than queued.
 */
public class PropFlourishTest
{
	/** Records what it was asked; does none of it. */
	private static final class RecordingFollower extends FollowerEntity
	{
		boolean staying;
		boolean following = true;
		int poseOverride;

		RecordingFollower()
		{
			super(null, null);
		}

		@Override
		public void stayHere()
		{
			staying = true;
			following = false;
		}

		@Override
		public void resumeFollowing()
		{
			staying = false;
			following = true;
		}

		@Override
		public void setPoseOverride(int id)
		{
			poseOverride = id;
		}

		@Override
		public void clearPoseOverride(int id)
		{
			if (poseOverride == id)
			{
				poseOverride = 0;
			}
		}

		@Override
		public WorldPoint getWorldLocation()
		{
			return new WorldPoint(3222, 3218, 0);
		}
	}

	private static final int QUILL = ErrandController.QUILL_PROP;
	private static final int SCROLL = ErrandController.SCROLL_PROP;
	private static final int WRITE = ErrandController.WRITE_SCROLL_POSE;

	private RecordingFollower follower;
	private PropFlourish flourish;
	private int held;
	private int heldLeft;

	@Before
	public void setUp()
	{
		follower = new RecordingFollower();
		flourish = new PropFlourish(follower, new ErrandController.Hands()
		{
			@Override
			public void hold(int itemId)
			{
				held = itemId;
			}

			@Override
			public void hold(int leftItemId, int rightItemId)
			{
				heldLeft = leftItemId;
				held = rightItemId;
			}

			@Override
			public void release()
			{
				held = 0;
				heldLeft = 0;
			}
		});
	}

	@Test
	public void theScrollAndThePoseArriveTogether()
	{
		// On the same tick, and so the same rendered frame. The first version
		// held the pose back two "settle" ticks out of caution about a rebuild
		// delay the dump path does not have - and those ticks were exactly the
		// window in which the follower stood in its idle pose holding a
		// scroll, which the eye reads as wrong immediately.
		assertTrue(flourish.start(QUILL, SCROLL, WRITE, 5));
		assertTrue(flourish.isActive());
		assertTrue("it should stop to write", follower.staying);
		assertEquals("the scroll is out", SCROLL, held);
		assertEquals("and the quill with it", QUILL, heldLeft);
		assertEquals("and the pose is already playing", WRITE, follower.poseOverride);
	}

	@Test
	public void aFlourishWithNothingForTheOtherHandHoldsTheOneProp()
	{
		heldLeft = -1;
		assertTrue(flourish.start(0, 10485, 5354, 5));
		assertEquals("the one prop, through the one-handed hold", 10485, held);
		assertEquals("and the other hand never asked", -1, heldLeft);
	}

	@Test
	public void everythingGoesBackWhenTheMomentPasses()
	{
		flourish.start(QUILL, SCROLL, WRITE, 3);
		for (int i = 0; i < 10; i++)
		{
			flourish.tick();
		}

		assertFalse(flourish.isActive());
		assertEquals("the pose released", 0, follower.poseOverride);
		assertEquals("the scroll went away", 0, held);
		assertEquals("and the quill", 0, heldLeft);
		assertTrue("and the follower walks again", follower.following);
	}

	@Test
	public void anAbortPutsEverythingBackToo()
	{
		flourish.start(QUILL, SCROLL, WRITE, 20);
		flourish.tick();
		flourish.tick();
		assertEquals(WRITE, follower.poseOverride);

		flourish.abort();

		assertFalse(flourish.isActive());
		assertEquals(0, follower.poseOverride);
		assertEquals(0, held);
		assertEquals(0, heldLeft);
		assertTrue(follower.following);
	}

	/**
	 * QA, 16 Oct: the end of the gesture took off whatever pose was on, so
	 * a rest that sat it down meanwhile was stood up under it, and the
	 * rest's own stand-up never came.
	 */
	@Test
	public void aPoseSomethingElsePutOnMeanwhileStays()
	{
		// The rest's sit, the default Rest pose.
		final int sit = 10061;
		flourish.start(QUILL, SCROLL, WRITE, 3);
		follower.setPoseOverride(sit);
		for (int i = 0; i < 10; i++)
		{
			flourish.tick();
		}
		assertFalse(flourish.isActive());
		assertEquals("the sit is the rest's to take off", sit, follower.poseOverride);
		assertEquals("the scroll still went away", 0, held);
	}

	@Test
	public void aSecondGestureMidGestureIsDroppedNotQueued()
	{
		assertTrue(flourish.start(QUILL, SCROLL, WRITE, 10));
		assertFalse("a backlog of gestures stops reading as spontaneous",
			flourish.start(QUILL, SCROLL, WRITE, 10));
	}

	@Test
	public void nonsenseNeverStarts()
	{
		assertFalse(flourish.start(QUILL, 0, WRITE, 10));
		assertFalse(flourish.start(QUILL, SCROLL, 0, 10));
		assertFalse("and nothing was touched", follower.staying);
		assertEquals(0, held);
	}
}

package com.follower;

import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import net.runelite.client.util.ReflectUtil;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Reads every setting the way the client does.
 *
 * <p>RuneLite never implements FollowerConfig with a class of ours: ConfigManager
 * makes it a java.lang.reflect.Proxy, a class the JDK defines in a package of its
 * own, and runs each item's default method through a MethodHandle
 * (ConfigInvocationHandler.callDefaultMethod). The proxy casts what comes back to
 * the item's declared type, so a type that package cannot see - a package-private
 * enum, say - throws IllegalAccessError on every read, and javac does not mind.
 * The other tests build FollowerConfig as anonymous classes in this package, which
 * see everything, so this is the one that would notice. The public build's export
 * rewrites take "public" off what one package no longer needs; this checks they
 * keep it on every type a setting names.
 */
public class ProxyCheckTest
{
	@Test
	public void everySettingReadsThroughTheClientsProxy() throws Exception
	{
		FollowerConfig config = (FollowerConfig) Proxy.newProxyInstance(FollowerConfig.class.getClassLoader(),
			new Class<?>[]{FollowerConfig.class}, (proxy, method, args) ->
			{
				if (!method.isDefault())
				{
					return null;
				}
				Class<?> declaring = method.getDeclaringClass();
				return ReflectUtil.privateLookupIn(declaring).unreflectSpecial(method, declaring)
					.bindTo(proxy).invokeWithArguments(args);
			});
		List<String> failed = new ArrayList<>();
		int read = 0;
		for (Method item : FollowerConfig.class.getMethods())
		{
			if (!item.isDefault() || item.getParameterCount() != 0)
			{
				continue;
			}
			try
			{
				item.invoke(config);
				read++;
			}
			catch (InvocationTargetException e)
			{
				failed.add(item.getName() + ": " + e.getCause());
			}
		}
		assertEquals("settings the client cannot read: " + failed, 0, failed.size());
		assertTrue("read " + read + " settings", read > 50);
	}
}

package com.follower;

/**
 * The source as javac reads it, for the tests that read it as text: the
 * public build's markers are comments, so they are taken out before a test
 * looks for a line of code. Lines that only hold a marker go, and so does a
 * marker at the end of a line of code.
 */
public final class PublicMarkers
{
	private PublicMarkers()
	{
	}

	public static String strip(String source)
	{
		return source
			.replaceAll("(?m)^[ \\t]*// public:(cut|end|else|file)\\b.*\\n", "")
			.replaceAll("[ \\t]*// public:cut [a-z0-9,-]+(?=\\r?\\n)", "");
	}
}

package com.follower;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Quest;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Quests QA5, 20 Oct: the quest findings, walked on QuestSim at Occasional
 * (6 s) and Minimal (45 s) with the people where the game has them. The
 * walks are QA5's (QaNew5Test), stage values from Quest Helper (BSD),
 * master 06da90f.
 */
public class QaFiveQuestsTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final long[] GAPS = {6000, 45000};

	private static final BelowIceMountainWalksTest.Style WALKER = BelowIceMountainWalksTest.WALKER;
	private static final BelowIceMountainWalksTest.Style RUNNER = BelowIceMountainWalksTest.RUNNER;
	private static final BelowIceMountainWalksTest.Style CHAIN =
		new BelowIceMountainWalksTest.Style("chain-clicker", 2, 1, 0.0);
	private static final BelowIceMountainWalksTest.Style[] STYLES = {WALKER, RUNNER, CHAIN};

	private QuestSim sim(long gap) throws Exception
	{
		return new QuestSim(folder.newFolder().toPath(), gap);
	}

	private static void pause(QuestSim s, BelowIceMountainWalksTest.Style p, int ticks)
	{
		s.ticks(Math.max(1, (int) Math.round(ticks * p.idle)));
	}

	private static final Pattern SAYS = Pattern.compile("^t\\d+\\s+([\\d.]+)s\\s+SAYS \\[");

	/** When each heard line was said, in seconds, read off the transcript. */
	private static List<Double> heardAt(QuestSim s)
	{
		List<Double> at = new ArrayList<>();
		for (String line : s.transcript().split("\\R"))
		{
			Matcher m = SAYS.matcher(line);
			if (m.find())
			{
				at.add(Double.parseDouble(m.group(1)));
			}
		}
		return at;
	}

	// ------------------------------------------------------------ Enter the Abyss

	/** The mine on its map region, or an instance copy of it, as it is in play. */
	private QuestSim abyss(BelowIceMountainWalksTest.Style p, long gap, boolean runeMysteriesSeen, boolean instanced)
		throws Exception
	{
		QuestSim s = sim(gap);
		if (runeMysteriesSeen)
		{
			s.witnessed(Quest.RUNE_MYSTERIES);
		}
		else
		{
			s.done(Quest.RUNE_MYSTERIES);
		}
		s.started(Quest.ENTER_THE_ABYSS);
		int mineTicks = p == WALKER ? 20 : p == RUNNER ? 10 : 6;
		int mx = instanced ? 11456 + 30 : 2911;
		int my = instanced ? 5056 + 30 : 4832;
		s.at(3094, 3520, 0);
		s.ticks(3);
		s.npc("Mage of Zamorak", 3104, 3558, 0);
		s.walkTo(3103, 3556, 0, p.speed);
		s.ticks(p.lag);
		s.talk("Mage of Zamorak", 8, () -> s.varp(492, 1));
		pause(s, p, 10);
		s.removeNpc("Mage of Zamorak");
		// Varrock: the chaos temple, Aubury 18 tiles north.
		s.at(3240, 3420, 0);
		s.ticks(3);
		s.npc("Aubury", 3253, 3401, 0);
		s.npc("Mage of Zamorak", 3259, 3385, 0);
		s.walkTo(3258, 3384, 0, p.speed);
		s.ticks(p.lag);
		s.talk("Mage of Zamorak", 40, () ->
		{
			s.varp(492, 2);
			s.bag(5519);
		});
		pause(s, p, 4);
		s.walkTo(3253, 3399, 0, p.speed);
		s.ticks(p.lag);
		s.talk("Aubury", 6, null);
		s.at(mx, my, 0);
		s.varbit(2315, 1);
		s.ticks(mineTicks);
		s.at(3104, 9565, 0);
		s.npc("Archmage Sedridor", 3104, 9571, 0);
		s.walkTo(3104, 9569, 0, p.speed);
		s.ticks(p.lag);
		s.talk("Archmage Sedridor", 6, null);
		s.at(mx, my, 0);
		s.varbit(2314, 1);
		s.ticks(mineTicks);
		s.at(2662, 3305, 0);
		s.npc("Wizard Cromperty", 2684, 3323, 0);
		s.walkTo(2683, 3321, 0, p.speed);
		s.ticks(p.lag);
		s.talk("Wizard Cromperty", 6, null);
		s.at(mx, my, 0);
		s.varbit(2316, 1);
		s.bag(5518);
		s.ticks(mineTicks);
		s.at(3253, 3399, 0);
		s.ticks(3);
		s.walkTo(3258, 3384, 0, p.speed);
		s.ticks(p.lag);
		s.dialogue("Mage of Zamorak");
		s.ticks(20);
		s.varp(492, 3);
		s.bag();
		s.ticks(20);
		s.varp(492, 4);
		s.miniquestComplete(Quest.ENTER_THE_ABYSS, "Enter the Abyss");
		s.ticks(2);
		s.dialogue(false);
		s.ticks(150);
		s.summary();
		return s;
	}

	/**
	 * QA5 #14: the essence mine is an instance, which reports its own
	 * region, so a moment kept to 11595 was never said (19 Oct, three trips).
	 * The full orb at varp 492 = 2 is only true from the third teleport.
	 */
	@Test
	public void theOrbFillsInTheInstancedMine() throws Exception
	{
		for (long gap : GAPS)
		{
			for (BelowIceMountainWalksTest.Style p : STYLES)
			{
				QuestSim s = abyss(p, gap, false, true);
				assertTrue(p.name + "\n" + s.transcript(), s.heardIds.contains("qm-enter-the-abyss-the-orb-full"));
				assertTrue(s.transcript(), s.lost.isEmpty());
			}
		}
	}

	/**
	 * QA5 #57: at Minimal the Wilderness start was four lines in 28 s, the
	 * mage's own introduction after the moment about him. On the errand,
	 * varp 492 1-3, the moments carry him; met before he is spoken to, he is
	 * introduced then.
	 */
	@Test
	public void theMageIsNotIntroducedOverTheMomentAboutHim() throws Exception
	{
		for (long gap : GAPS)
		{
			for (BelowIceMountainWalksTest.Style p : STYLES)
			{
				QuestSim s = abyss(p, gap, false, false);
				String walk = s.transcript();
				int from = walk.indexOf("varp 492 = 1");
				int to = walk.indexOf("varp 492 = 4");
				assertTrue(walk, from > 0 && to > from
					&& walk.substring(from, to).contains("SAYS [qm-enter-the-abyss-not-here]"));
