		Harness next = harness(moment("the-orb", varbit(5619, 4, 4), NOT_IN_DIALOGUE));
		next.engine.getContext().restoreSpokenOnce(h.engine.getContext().getSpokenOnce(), null);
		next.game.varbit(5619, 4);
