		{
			h.game.at(1600, 3700, 0);
			ticks(h, 3);
			h.game.at(1696, 3880, 0);
			ticks(h, 3);
		}
		h.engine.setSceneQuiet(false);
		ticks(h, 60);
		assertEquals(1, h.firedBy("dark-altar").size());
