package com.follower;

import java.nio.file.Path;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.NPC;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.coords.WorldPoint;

/**
 * A quest walked stage by stage: the shipped rules in the Harness, with the
 * plugin's side of the speech path modelled as FollowerPlugin does it: the
 * overhead queue (3 deep, 15.4 s stale), reading time (17 cps, 4 s floor, 12 s
 * cap), the NPC-dialogue hush in speakNow, a line that waits its turn kept in
 * the queue through a conversation (keptForTheBox), the cutscene clearing the queue and
 * re-saying a once or waiting line cut before it could be read (2 s at least) unless its quest
 * step has moved on, the 25-tick quiet
 * after a scene, and the dialogue reading that stays "open" 2 ticks after
 * the box goes. Pacing is ON (Occasional, 6 s) unless set otherwise.
 *
 * <p>And what the plugin does at the scroll (QA3 #35): the follower is
 * witness to the quest from that moment, and the quest's page is written
 * then, its news waiting for the floor as FollowerPlugin.nextPageNews has it
 * - held through a conversation or a scene's quiet, lapsing after
 * {@link FollowerPlugin#pageNewsTicks} of the gap. MINUTES_TAKEN can be
 * raised as the plugin does when a minuted conversation closes.
 */
public final class QuestSim
{
	public final Harness h;
	public final long[] ms = {1_700_000_000_000L};
	public int tick;
	public final StringBuilder log = new StringBuilder();
	public final List<String> heard = new ArrayList<>();
	public final List<String> heardIds = new ArrayList<>();
	public final List<String> lost = new ArrayList<>();

	// world
	public boolean npcDialog;
	/** Who is talking in the box, as the plugin reads it off CHAT_LEFT's name; null for nobody named. */
	public String speaker;
	public boolean cutscene;
	private int goneTicks = 99;
	private boolean sceneOn;
	private int sceneGone = 99;
	private int quietUntil;
	private int region = -1;
	private final Map<String, NPC> npcs = new HashMap<>();

	// plugin speech side
	private static final class U
	{
		final String text;
		final SpeechRule rule;
		final int anim;
		final Runnable onSaid;
		long queuedAt;

		U(String text, SpeechRule rule, int anim, Runnable onSaid, long queuedAt)
		{
			this.text = text;
			this.rule = rule;
			this.anim = anim;
			this.onSaid = onSaid;
			this.queuedAt = queuedAt;
		}
	}

	private final ArrayDeque<U> queue = new ArrayDeque<>();
	private long speakingUntil;
	private U onScreen;
	private long onScreenSince;
	private U cut;
	private int cutHeld;

	public QuestSim(Path dir, long gapMs) throws java.io.IOException
	{
		h = new Harness(dir);
		h.engine.setClock(() -> ms[0]);
		h.engine.setGlobalCooldownMs(gapMs);
		h.engine.setSink((text, output, rule, anim, onSaid) -> pluginSpeak(text, rule, anim, onSaid));
		h.engine.setOnSuppressed((rule, why) -> note("   held back: " + rule.id + " (" + why + ")"));
		h.game.at(3222, 3218, 0);
		ticks(3);
	}

	public void note(String s)
	{
		log.append(String.format("t%-5d %6.1fs  %s%n", tick, (ms[0] - 1_700_000_000_000L) / 1000.0, s));
	}

	// ------------------------------------------------------------ plugin side

	private long readingTime(String text)
	{
		long needed = text.length() * 1000L / 17;
		return Math.min(12_000L, Math.max(4_000L, needed));
	}

	private void pluginSpeak(String text, SpeechRule rule, int anim, Runnable onSaid)
	{
		if (text.isEmpty())
		{
			speakNow(new U(text, rule, anim, onSaid, ms[0]));
			return;
		}
		if (ms[0] < speakingUntil || keptForTheBox(rule))
		{
			if (queue.size() < 3)
			{
				queue.addLast(new U(text, rule, anim, onSaid, ms[0]));
				note("   queued: " + id(rule));
			}
			else
			{
				note("   QUEUE FULL, dropped: " + id(rule));
				lost.add(id(rule) + " (queue full)");
			}
			return;
		}
		speakNow(new U(text, rule, anim, onSaid, ms[0]));
	}

	private void speakNow(U u)
	{
		boolean hushed = !u.text.isEmpty() && npcDialog;
		if (hushed)
		{
			note("   HUSHED by NPC dialogue (words dropped): " + id(u.rule) + " \"" + u.text + "\"");
			lost.add(id(u.rule) + " (hushed by dialogue)");
			return;
		}
		u.onSaid.run();
		if (!u.text.isEmpty())
		{
			onScreen = u;
			onScreenSince = ms[0];
			speakingUntil = ms[0] + readingTime(u.text) + 400;
			heard.add(u.text);
			heardIds.add(id(u.rule));
			note("SAYS [" + id(u.rule) + "] \"" + u.text + "\"" + (u.anim > 0 ? " anim=" + u.anim : "")
				+ (u.rule != null && u.rule.mood != null ? " mood=" + u.rule.mood : "")
				+ (u.rule != null && u.rule.remember != null ? " remembers='" + u.rule.remember.as + "'" : ""));
		}
	}

	private static String id(SpeechRule r)
	{
		return r == null ? "(direct)" : r.id;
	}

	private void noticeTheScene()
	{
		sceneGone = cutscene ? 0 : Math.min(sceneGone + 1, 1000);
		boolean on = cutscene || (sceneOn && sceneGone <= 2);
		if (on != sceneOn)
		{
			sceneOn = on;
			if (on)
			{
				cut = onScreen != null && ms[0] < speakingUntil && onScreen.rule != null
					&& (onScreen.rule.isOnce() || onScreen.rule.waitsItsTurn())
					&& ms[0] - onScreenSince < Math.max(2000, onScreen.text.length() * 1000L / 17) ? onScreen : null;
				if (onScreen != null && ms[0] < speakingUntil)
				{
					note("   scene starts: overhead cleared mid-line (" + id(onScreen.rule) + ")"
						+ (cut != null ? ", will be re-said" : ""));
				}
				if (!queue.isEmpty())
				{
					for (U q : queue)
					{
						note("   scene starts: queued line cleared (" + id(q.rule) + ")");
						lost.add(id(q.rule) + " (queue cleared by cutscene)");
					}
				}
				cutHeld = 0;
				queue.clear();
				onScreen = null;
				speakingUntil = 0;
			}
			else
			{
				quietUntil = tick + 25;
			}
		}
		boolean quiet = sceneOn || tick < quietUntil;
		h.engine.setSceneQuiet(quiet);
		h.engine.setInCutscene(sceneOn);
		if (cut != null && (quiet || npcDialog || goneTicks <= 2))
		{
			if (++cutHeld > 500)
			{
				cut = null;
			}
		}
		else if (cut != null)
		{
			if (cut.rule.when.questStepHolds(h.engine.getContext(), TriggerEvent.tick()))
			{
				note("   re-says the line the scene cut:");
				h.engine.remark(cut.text);
			}
			else
			{
				note("   the line the scene cut is about a step since moved on: not said again");
			}
			cut = null;
		}
	}

	/** FollowerPlugin.keptForTheBox, on the dialogue as the rules read it. */
	private boolean keptForTheBox(SpeechRule rule)
	{
		return (npcDialog || goneTicks <= 2) && rule != null && rule.waitsItsTurn();
	}

	private void drain()
	{
		for (U kept : queue)
		{
			if (keptForTheBox(kept.rule))
			{
				kept.queuedAt = ms[0];
			}
		}
		if (!queue.isEmpty() && keptForTheBox(queue.peekFirst().rule))
		{
			return;
		}
		while (!queue.isEmpty() && ms[0] - queue.peekFirst().queuedAt > 15_400L)
		{
			U stale = queue.removeFirst();
			note("   STALE in queue, dropped: " + id(stale.rule));
			lost.add(id(stale.rule) + " (stale in queue)");
		}
		if (queue.isEmpty() || ms[0] < speakingUntil)
		{
			return;
		}
		U line = queue.removeFirst();
		if (line.rule != null && !line.rule.when.standingHolds(h.engine.getContext(), TriggerEvent.tick()))
		{
			note("   kept in the queue, its moment passed: " + line.rule.id);
			return;
		}
		speakNow(line);
	}

	// ------------------------------------------------------------ the world

	public void ticks(int n)
	{
		for (int i = 0; i < n; i++)
		{
			tick();
		}
	}

	public void tick()
	{
		ms[0] += 600;
		tick++;
		if (tick % 3 == 0)
		{
			h.game.cameraMoved();
		}
		noticeTheScene();
		drain();
		goneTicks = npcDialog ? 0 : Math.min(goneTicks + 1, 1000);
		h.engine.getContext().setDialogueOpen(npcDialog || goneTicks <= 2);
		if (npcDialog && speaker != null && !sceneOn)
		{
			h.engine.getContext().noteSpeaker(speaker);
		}
		h.gameTick();
		int now = regionOf(h.engine.getContext().getRegionId());
		if (now != region)
		{
			int old = region;
			region = now;
			if (old != -1)
			{
				note("   (region " + old + " -> " + now + ")");
				h.dispatch(TriggerEvent.regionChange(now, old));
			}
		}
	}

	private int regionOf(int r)
	{
		return r;
	}

	public void at(int x, int y, int plane)
	{
		h.game.at(x, y, plane);
	}

	/** Walks (or runs, 2 tiles a tick) in a straight line, a tick per step. */
	public void walkTo(int x, int y, int plane, int tilesPerTick)
	{
		WorldPoint p = h.game.player.getWorldLocation();
		int cx = p.getX();
		int cy = p.getY();
		while (cx != x || cy != y)
		{
			for (int s = 0; s < tilesPerTick && (cx != x || cy != y); s++)
			{
				cx += Integer.signum(x - cx);
				cy += Integer.signum(y - cy);
			}
			h.game.at(cx, cy, plane);
			tick();
		}
	}

	public NPC npc(String name, int x, int y, int plane)
	{
		NPC n = npcs.get(name);
		if (n == null)
		{
			n = h.game.spawnNpc(9000 + npcs.size(), name, 10);
			npcs.put(name, n);
		}
		h.game.moveNpc(n, x, y, plane);
		return n;
	}

	public void removeNpc(String name)
	{
		NPC n = npcs.remove(name);
		if (n != null)
		{
			h.game.moveNpc(n, 0, 0, 3);
		}
	}

	public void dialogue(boolean open)
	{
		npcDialog = open;
		if (!open)
		{
			speaker = null;
		}
		note(open ? "-- NPC dialogue opens" : "-- NPC dialogue closes");
	}

	/** A dialogue opening with this person talking in it. */
	public void dialogue(String with)
	{
		dialogue(true);
		speaker = with;
	}

	public void scene(boolean on)
	{
		cutscene = on;
		note(on ? "== cutscene starts" : "== cutscene ends");
	}

	/** A conversation of the given length, with any var changes run at its end, still inside it. */
	public void talk(int lengthTicks, Runnable atEnd)
	{
		talk(null, lengthTicks, atEnd);
	}

	/** The same, with this person talking in the box. */
	public void talk(String with, int lengthTicks, Runnable atEnd)
	{
		dialogue(true);
		speaker = with;
		ticks(lengthTicks);
		if (atEnd != null)
		{
			atEnd.run();
		}
		tick();
		dialogue(false);
	}

	public void varp(int id, int v)
	{
		h.game.varp(id, v);
		note("   varp " + id + " = " + v);
	}

	public void varbit(int id, int v)
	{
		h.game.varbit(id, v);
		note("   varbit " + id + " = " + v);
	}

	public void done(Quest q)
	{
		h.game.quest(q, QuestState.FINISHED);
	}

	private final java.util.Map<String, Long> seenFinished = new java.util.HashMap<>();

	/** Finished with the follower there to see it, some days ago: what the callbacks need. */
	public void witnessed(Quest q)
	{
		done(q);
		seenFinished.put(q.name(), java.time.LocalDate.now().toEpochDay() - 30);
		h.engine.setQuestWitness(seenFinished::get);
	}

	public void started(Quest q)
	{
		h.game.quest(q, QuestState.IN_PROGRESS);
	}

	public void chat(String message)
	{
		note("   game message: " + message);
		h.dispatch(TriggerEvent.chat(message, net.runelite.api.ChatMessageType.GAMEMESSAGE.getType(), ""));
	}

	/**
	 * The scroll: the follower saw it finish, and the quest's page is
	 * written, with any other pages the quest opens: their news is "quest"
	 * news too, as the plugin raises it for a page a quest wrote.
	 */
	public void questComplete(Quest q, String name, String... morePages)
	{
		done(q);
		note("   quest scroll: " + name);
		seenFinished.put(q.name(), java.time.LocalDate.now().toEpochDay());
		h.engine.setQuestWitness(seenFinished::get);
		h.engine.getContext().tally("quests");
		h.dispatch(TriggerEvent.questComplete(name));
	}

	/**
	 * A miniquest finished: no scroll, so no quest-complete. The plugin sees
	 * it only as its page is written, which dates the page (the witness) and
	 * raises the page's news.
	 */
	public void miniquestComplete(Quest q, String name)
	{
		done(q);
		note("   finished, no scroll: " + name);
		seenFinished.put(q.name(), java.time.LocalDate.now().toEpochDay());
		h.engine.setQuestWitness(seenFinished::get);
	}

	/** MINUTES_TAKEN, as the plugin raises it when a conversation the follower minuted closes. */
	public void minutes()
	{
		note("   event: minutes taken");
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.MINUTES_TAKEN));
	}

	public void event(TriggerEvent e, String desc)
	{
		note("   event: " + desc);
		h.dispatch(e);
	}

	public void bag(int... ids)
	{
		h.game.inventoryContaining(ids);
	}

	public void summary()
	{
		note("HEARD, in order: " + heardIds);
		note("LOST: " + lost);
	}

	/** The scroll's line as heard, or empty: when it names the quest, the quest's page news goes. */
	public String scrollLine()
	{
		int at = heardIds.indexOf("quest-complete");
		return at < 0 ? "" : heard.get(at);
	}

	public String transcript()
	{
		return log.toString();
	}
}

package com.follower;

import net.runelite.api.Quest;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The quest walker itself, as quests QA4 (#33) found it: a direct line
 * queued behind another threw, and a logout lost every witness.
 */
public class QuestSimTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void aDirectLineQueuedBehindAnotherIsNoted() throws Exception
	{
		QuestSim s = new QuestSim(folder.newFolder().toPath(), 0L);
		s.h.engine.force("idle-chatter");
		// The sketch prompt, said straight through the engine with no rule.
		s.h.engine.say("Hold still a moment.", SpeechOutput.OVERHEAD);
		s.ticks(20);
		assertTrue(s.transcript(), s.transcript().contains("queued: (direct)"));
		assertTrue(s.transcript(), s.heard.contains("Hold still a moment."));
	}

	@Test
	public void theWitnessOutlastsALogout() throws Exception
	{
		// The plugin hands the book to the engine, not to one context; the
		// walker does the same, so a logout's reset keeps it.
		QuestSim s = new QuestSim(folder.newFolder().toPath(), 6000L);
		s.witnessed(Quest.COOKS_ASSISTANT);
		s.h.engine.reset();
		assertNotNull(s.h.engine.getContext().questWitnessedOn("COOKS_ASSISTANT"));

		QuestSim t = new QuestSim(folder.newFolder().toPath(), 6000L);
		t.questComplete(Quest.RUNE_MYSTERIES, "Rune Mysteries");
		t.h.engine.reset();
		assertNotNull(t.h.engine.getContext().questWitnessedOn("RUNE_MYSTERIES"));
	}
}

package com.follower;

import net.runelite.api.Quest;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Quest moments on the shipped rules, at the steps QA found them lost
 * (15 Oct). Stage values from Quest Helper (BSD): PriestInPeril.java
 * steps.put 4-8, RuneMysteries.java steps.put 3-5.
 */
public class QuestStepWalksTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private QuestSim sim() throws Exception
	{
		return new QuestSim(folder.newFolder().toPath(), 6000);
	}

	/**
	 * The current Priest in Peril has Drezel met first (302 goes 4 to 5) and
	 * the hooded monk killed for the key after, as the wiki's quick guide
	 * has it; Quest Helper's killMonk is a step at both 4 and 5.
	 */
	@Test
	public void theMonksKeyIsMarkedWhenDrezelIsMetFirst() throws Exception
	{
		QuestSim s = sim();
		s.started(Quest.PRIEST_IN_PERIL);
		s.varp(302, 4);
		s.at(3416, 3490, 2);
		s.ticks(4);
		s.talk(40, () -> s.varp(302, 5));
		s.ticks(6);
		s.at(3410, 3488, 0);
		s.ticks(3);
		s.event(TriggerEvent.combat(TriggerEvent.Type.COMBAT_START, "Monk of Zamorak"), "fight hooded monk");
		s.ticks(20);
		s.event(TriggerEvent.kill(528, "Monk of Zamorak", 30), "kill hooded monk");
		s.ticks(2);
		s.bag(1925, 2944);
		s.ticks(20);
		s.summary();
		assertTrue(s.transcript(), s.heardIds.contains("qm-priest-in-peril-the-monk-falls"));
	}

	/** The water poured, and Drezel clicked at once: the coffin's line is said after him. */
	@Test
	public void theCoffinIsMarkedWhenDrezelIsClickedAtOnce() throws Exception
	{
		QuestSim s = sim();
		s.started(Quest.PRIEST_IN_PERIL);
		s.varp(302, 6);
		s.at(3416, 3490, 2);
		s.ticks(10);
		s.varp(302, 7);
		s.ticks(1);
		s.talk(15, () -> s.varp(302, 8));
		s.ticks(20);
		s.summary();
		assertTrue(s.transcript(), s.heardIds.contains("qm-priest-in-peril-the-coffin-sealed"));
		assertTrue(s.transcript(), s.lost.isEmpty());
	}

	/**
	 * Rune Mysteries, with the mugger outside only as Aubury's conversation
	 * ends: the notes are in hand, and the mugger's line is about the
	 * package. It took the pass and the notes were never mentioned.
	 */
	@Test
	public void theNotesAreMarkedWithTheMuggerOutside() throws Exception
	{
		QuestSim s = sim();
		s.started(Quest.RUNE_MYSTERIES);
		s.varp(63, 3);
		s.at(3240, 3400, 0);
		s.ticks(4);
		s.walkTo(3252, 3401, 0, 2);
		s.npc("Aubury", 3253, 3402, 0);
		s.ticks(1);
		s.talk(30, () -> s.varp(63, 4));
		s.talk(15, () ->
		{
			s.varp(63, 5);
			s.varbit(13725, 1);
		});
		s.npc("Mugger", 3255, 3397, 0);
		s.ticks(10);
		s.walkTo(3256, 3398, 0, 1);
		s.ticks(10);
		s.summary();
		assertTrue(s.transcript(), s.heardIds.contains("qm-rune-mysteries-notes-in-hand"));
		assertFalse(s.transcript(), s.heardIds.contains("qm-rune-mysteries-mugger-street"));
	}

	/** On the way in with the package, the mugger is still marked. */
	@Test
	public void theMuggerIsMarkedOnThePackagesWayIn() throws Exception
	{
		QuestSim s = sim();
		s.started(Quest.RUNE_MYSTERIES);
		s.varp(63, 3);
		s.at(3240, 3400, 0);
		s.ticks(4);
		s.npc("Mugger", 3255, 3397, 0);
		s.walkTo(3253, 3399, 0, 1);
		s.ticks(10);
		s.summary();
		assertTrue(s.transcript(), s.heardIds.contains("qm-rune-mysteries-mugger-street"));
	}

	/** The line a rule was said with, from the transcript. */
	private static String saidLine(QuestSim s, String id)
	{
		for (String line : s.transcript().split("\n"))
		{
			if (line.contains("SAYS [" + id + "]"))
			{
				return line;
			}
		}
		return "";
	}

	/**
	 * Flour left in the mill's bin from before the quest: the moment waits
	 * for the mill, rather than going off in the castle kitchen as the cook
	 * starts the quest (QA pass 2). Quest Helper's CooksAssistant.java (BSD)
	 * millSecond and millThird zones, 3162-3171 by 3302-3311.
	 */
	@Test
	public void flourLeftInTheBinIsMarkedAtTheMillNotInTheKitchen() throws Exception
	{
		QuestSim s = sim();
		s.varbit(4920, 3);
		s.at(3208, 3214, 0);
		s.ticks(4);
		s.started(Quest.COOKS_ASSISTANT);
		s.talk(10, () -> s.varp(29, 1));
		s.ticks(20);
		assertFalse("not in the kitchen\n" + s.transcript(),
			s.heardIds.contains("qm-cooks-assistant-flour-in-bin"));
		s.at(3166, 3306, 0);
		s.ticks(10);
		s.summary();
		assertTrue(s.transcript(), s.heardIds.contains("qm-cooks-assistant-flour-in-bin"));

		// And the usual way: the lever pulled on the top floor.
		QuestSim lever = sim();
		lever.started(Quest.COOKS_ASSISTANT);
		lever.varp(29, 1);
		lever.at(3166, 3306, 2);
		lever.ticks(20);
		lever.varbit(4920, 1);
		lever.ticks(10);
		lever.summary();
		assertTrue(lever.transcript(), lever.heardIds.contains("qm-cooks-assistant-flour-in-bin"));
	}

	/**
	 * Children of the Sun at 16 but on the ground, at the palace gate: the
	 * roof moment waits for the roof, Quest Helper's castleF2 zone
	 * (ChildrenOfTheSun.java, BSD). It had all of region 12854 at any
	 * plane (QA pass 2). The callback winces rather than looks pleased.
	 */
	@Test
	public void theRoofMomentWaitsForTheRoof() throws Exception
	{
		for (boolean priestInPeril : new boolean[]{false, true})
		{
			QuestSim s = sim();
			if (priestInPeril)
			{
				s.witnessed(Quest.PRIEST_IN_PERIL);
			}
			String id = priestInPeril
				? "qm-children-of-the-sun-the-roof-after-priest-in-peril" : "qm-children-of-the-sun-the-roof";
			s.started(Quest.CHILDREN_OF_THE_SUN);
			s.varbit(9632, 16);
			s.at(3212, 3466, 0);
			s.ticks(15);
			assertFalse("not at the gate\n" + s.transcript(), s.heardIds.contains(id));
			s.at(3205, 3471, 2);
			s.ticks(10);
			s.summary();
			assertTrue(s.transcript(), s.heardIds.contains(id));
			if (priestInPeril)
			{
				assertTrue(saidLine(s, id), saidLine(s, id).contains("anim=13994"));
				assertFalse(saidLine(s, id), saidLine(s, id).contains("mood="));
			}
		}
	}

	/**
	 * X Marks the Spot dug through stages 3-6 as Quest Helper's
	 * XMarksTheSpot.java (BSD) has them. Four moments in about two minutes
	 * was the densest stretch of any quest (QA pass 2): the orb, a short
	 * walk after hole one, is left out. The casket is uneasy, not pleased.
	 */
	@Test
	public void xMarksTheSpotKeepsItsHolesAndUneasyCasket() throws Exception
	{
		QuestSim s = sim();
		s.started(Quest.X_MARKS_THE_SPOT);
		s.at(3230, 3210, 0);
		for (int stage = 3; stage <= 6; stage++)
		{
			s.varbit(8063, stage);
			s.ticks(30);
		}
		s.summary();
		assertTrue(s.transcript(), s.heardIds.contains("qm-x-marks-the-spot-first-hole"));
		assertFalse(s.transcript(), s.heardIds.contains("qm-x-marks-the-spot-the-orb"));
		assertTrue(s.transcript(), s.heardIds.contains("qm-x-marks-the-spot-the-cipher"));
		String casket = saidLine(s, "qm-x-marks-the-spot-the-casket");
		assertTrue(s.transcript(), casket.contains("anim=13994"));
		assertFalse(casket, casket.contains("mood="));
	}
}

package com.follower;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * A callback that remembers a quest done together is said only when the
 * follower was there for it.
 *
 * <p>A finished quest is not enough: most players did the early quests years
 * before the follower existed, and "Ned did get us to Crandor" is a memory it
 * cannot have (QA pass 2, #31). The book already tells the two apart, a quest
 * page found finished at the first look being "before I kept dates". The
 * follower was there when it saw the quest's reward scroll, or wrote the
 * quest's page as it finished.
 */
public class QuestWitnessedTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private int tick;

	/** The shipped rules named, and the chronicle wired to them as the plugin wires it. */
	private final class World
	{
		final Harness h;

		World(String... ids) throws IOException
		{
			h = harnessWith(Arrays.asList(ids));
			h.engine.setQuestWitness(quest ->
			{
				Long seen = h.engine.getContext().questSeenFinishedOn(quest);
				return seen == null || seen == -1L ? null : seen;
			});
		}

		World ticks(int count)
		{
			for (int i = 0; i < count; i++)
			{
				h.gameTick();
			}
			return this;
		}
	}

	private Harness harnessWith(List<String> ids) throws IOException
	{
		JsonArray rules;
		try (InputStream in = getClass().getResourceAsStream("/com/follower/default-phrases.json"))
		{
			rules = new JsonParser().parse(new InputStreamReader(in, StandardCharsets.UTF_8))
				.getAsJsonObject().getAsJsonArray("rules");
		}
		Set<String> wanted = new HashSet<>(ids);
		JsonArray kept = new JsonArray();
		for (JsonElement rule : rules)
		{
			if (wanted.contains(rule.getAsJsonObject().get("id").getAsString()))
			{
				kept.add(rule);
			}
		}
		assertEquals("every rule named is shipped", ids.size(), kept.size());
		JsonObject file = new JsonObject();
		file.addProperty("version", 1);
		file.add("rules", kept);
		return new Harness(folder.newFolder().toPath(), file.toString());
	}

	private static List<String> said(Harness h)
	{
		List<String> out = new ArrayList<>();
		for (Harness.Spoken s : h.spoken)
		{
			out.add(s.rule.id);
		}
		return out;
	}

	// ----------------------------------------------------------- the people

	@Test
	public void aVeteranMeetingNedHearsTheBaseLineNotAMemoryOfCrandor() throws IOException
	{
		World w = new World("quest-ned", "fun-ned-after-dragon-slayer");
		w.h.game.quest(Quest.DRAGON_SLAYER_I, QuestState.FINISHED);
		w.ticks(2);
		w.h.game.spawnNpc(3308, "Ned", 0);
		w.ticks(4);
		assertEquals(Arrays.asList("quest-ned"), said(w.h));
	}

	@Test
	public void aFollowerThatSawDragonSlayerFinishRemembersIt() throws IOException
	{
		World w = new World("quest-ned", "fun-ned-after-dragon-slayer");
		w.h.game.quest(Quest.DRAGON_SLAYER_I, QuestState.IN_PROGRESS);
		w.ticks(2);
		w.h.game.quest(Quest.DRAGON_SLAYER_I, QuestState.FINISHED);
		w.h.engine.getContext().noteQuestSeenFinished("DRAGON_SLAYER_I", java.time.LocalDate.now().toEpochDay());
		w.ticks(2);
		w.h.game.spawnNpc(3308, "Ned", 0);
		w.ticks(4);
		assertEquals(Arrays.asList("fun-ned-after-dragon-slayer"), said(w.h));
	}

	@Test
	public void theBookIsStillAskedAfterTheEngineIsReset() throws IOException
	{
		// A logout, a profile switch and a Forget each reset the engine, which
		// builds a new context. The lookup went with the old one, so every
		// callback fell silent after the first logout (QA pass 3, #4).
		World w = new World("quest-ned", "fun-ned-after-dragon-slayer");
		w.h.game.quest(Quest.DRAGON_SLAYER_I, QuestState.FINISHED);
		w.h.engine.getContext().noteQuestSeenFinished("DRAGON_SLAYER_I", java.time.LocalDate.now().toEpochDay());
		Gson gson = new Gson();
		String stored = FollowerPlugin.snapshotMemory(w.h.engine.getContext(), 0, gson);
		w.h.engine.reset();
		// The login that follows reads the memory back into the new context.
		FollowerPlugin.restoreMemory(w.h.engine.getContext(), stored, gson, 0);
		w.ticks(2);
		w.h.game.spawnNpc(3308, "Ned", 0);
		w.ticks(4);
		assertEquals(Arrays.asList("fun-ned-after-dragon-slayer"), said(w.h));
	}

	@Test
	public void thePluginHandsTheBookToTheEngineNotToOneContext() throws IOException
	{
		String plugin = PublicMarkers.strip(new String(java.nio.file.Files.readAllBytes(
			java.nio.file.Paths.get("src/main/java/com/follower/FollowerPlugin.java")), StandardCharsets.UTF_8));
		assertTrue("the plugin wires the book to the engine",
			plugin.contains("speechEngine.setQuestWitness(quest ->"));
		assertTrue("a context's lookup is gone at the next reset",
			!plugin.contains("getContext().setQuestWitness(") && !plugin.contains("context().setQuestWitness("));
	}

	@Test
	public void aQuestFinishedWithTheFollowerParkedElsewhereWasNotWitnessed() throws IOException
	{
		// Chronicle QA4, 16 Oct: a quest finished with the follower on a
		// Stay, a Send or Follow me off still counted, scroll and page
		// alike, and the callbacks said "we" about it. The owner's call:
		// witnessed only with the follower there.
		World w = new World("quest-duke-horacio", "fun-duke-horacio-after-cooks-assistant");
		w.h.game.quest(Quest.COOKS_ASSISTANT, QuestState.IN_PROGRESS);
		w.ticks(2);
		w.h.game.quest(Quest.COOKS_ASSISTANT, QuestState.FINISHED);
		w.ticks(2);
		w.h.game.spawnNpc(815, "Duke Horacio", 0);
		w.ticks(4);
		assertEquals(Arrays.asList("quest-duke-horacio"), said(w.h));

		String scroll = PublicMarkers.strip(new String(java.nio.file.Files.readAllBytes(
			java.nio.file.Paths.get("src/main/java/com/follower/FollowerPlugin.java")), StandardCharsets.UTF_8)
			.replace("\r\n", "\n"));
		assertTrue("the scroll asks whether the player parked it", scroll.contains(
			"noteQuestFinish(quest, isStaying() ? QUEST_NOT_SEEN"));
	}

	@Test
	public void tobynOnTheRoofIsRememberedTheDayAfterAndNotAsTheQuestEnds() throws IOException
	{
		// Alina and Noah are gone from the square once Children of the Sun is
		// under way, so a callback on them could never be heard (QA pass 2,
		// #13). Tobyn stays on the roof, and is beside you as the quest ends.
		World today = new World("quest-sergeant-tobyn", "fun-sergeant-tobyn-after-children-of-the-sun");
		today.h.game.spawnNpc(12648, "Sergeant Tobyn", 0);
		today.h.game.quest(Quest.CHILDREN_OF_THE_SUN, QuestState.FINISHED);
		today.h.engine.getContext().noteQuestSeenFinished("CHILDREN_OF_THE_SUN", java.time.LocalDate.now().toEpochDay());
		today.ticks(4);
		assertEquals("not a 'still' on the day itself", Arrays.asList("quest-sergeant-tobyn"), said(today.h));

		World later = new World("quest-sergeant-tobyn", "fun-sergeant-tobyn-after-children-of-the-sun");
		later.h.game.quest(Quest.CHILDREN_OF_THE_SUN, QuestState.FINISHED);
		later.h.engine.getContext().noteQuestSeenFinished("CHILDREN_OF_THE_SUN",
			java.time.LocalDate.now().toEpochDay() - 3);
		later.ticks(2);
		later.h.game.spawnNpc(12648, "Sergeant Tobyn", 0);
		later.ticks(4);
		assertEquals(Arrays.asList("fun-sergeant-tobyn-after-children-of-the-sun"), said(later.h));

		World veteran = new World("quest-sergeant-tobyn", "fun-sergeant-tobyn-after-children-of-the-sun");
		veteran.h.game.quest(Quest.CHILDREN_OF_THE_SUN, QuestState.FINISHED);
		veteran.ticks(2);
		veteran.h.game.spawnNpc(12648, "Sergeant Tobyn", 0);
		veteran.ticks(4);
		assertEquals(Arrays.asList("quest-sergeant-tobyn"), said(veteran.h));
	}

	@Test
	public void noCallbackWaitsOnAlinaOrNoahAfterChildrenOfTheSun() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		for (SpeechRule rule : h.loader.getRules())
		{
			if (uses(rule.when, "questWitnessed") || uses(rule.when, "questDone"))
			{
				assertTrue(rule.id + " waits for Alina or Noah, who are gone once the quest is done",
					!names(rule.when).contains("Alina") && !names(rule.when).contains("Noah"));
			}
		}
	}

	private static Set<String> names(Condition c)
	{
		Set<String> out = new HashSet<>();
		if (c != null)
		{
			if (c.names != null)
			{
				out.addAll(c.names);
			}
			if (c.conditions != null)
			{
				for (Condition child : c.conditions)
				{
					out.addAll(names(child));
				}
			}
		}
		return out;
	}

	// ----------------------------------------------------------- the moments

	@Test
	public void aVeteranAtTheCipherHearsTheBaseMomentNotTheJailbreak() throws IOException
	{
		World w = new World("qm-x-marks-the-spot-the-cipher",
			"qm-x-marks-the-spot-the-cipher-after-prince-ali-rescue");
		w.h.game.quest(Quest.PRINCE_ALI_RESCUE, QuestState.FINISHED);
		w.ticks(2);
		w.h.game.varbit(8063, 5);
		w.ticks(4);
		assertEquals(Arrays.asList("qm-x-marks-the-spot-the-cipher"), said(w.h));

		World there = new World("qm-x-marks-the-spot-the-cipher",
			"qm-x-marks-the-spot-the-cipher-after-prince-ali-rescue");
		there.h.game.quest(Quest.PRINCE_ALI_RESCUE, QuestState.FINISHED);
		there.h.engine.getContext().noteQuestSeenFinished("PRINCE_ALI_RESCUE", java.time.LocalDate.now().toEpochDay());
		there.ticks(2);
		there.h.game.varbit(8063, 5);
		there.ticks(4);
		assertEquals(Arrays.asList("qm-x-marks-the-spot-the-cipher-after-prince-ali-rescue"),
			said(there.h));
	}

	// ----------------------------------------------------------- the rule set

	@Test
	public void noShippedCallbackClaimsAMemoryOnAFinishedQuestAlone() throws IOException
	{
		// Every fun-*-after-* callback speaks as one who was there. The quest
		// moments that do are listed; the rest only know of the quest.
		Set<String> sharedMemory = new HashSet<>(Arrays.asList(
			"qm-cooks-assistant-egg-coop-after-sheep-shearer",
			"qm-rune-mysteries-tower-arrival-after-cooks-assistant",
			"qm-rune-mysteries-mugger-street-after-children-of-the-sun",
			"qm-priest-in-peril-the-kings-verdict-after-children-of-the-sun",
			"qm-priest-in-peril-the-coffin-sealed-after-vampyre-slayer",
			"qm-waterfall-quest-golries-pebble-after-tree-gnome-village",
			"qm-children-of-the-sun-the-roof-after-priest-in-peril",
			"qm-x-marks-the-spot-the-cipher-after-prince-ali-rescue",
			"qm-client-of-kourend-dark-altar-after-priest-in-peril"));
		Harness h = new Harness(folder.newFolder().toPath());
		List<String> bad = new ArrayList<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			boolean memory = (rule.id.startsWith("fun-") && rule.id.contains("-after-"))
				|| sharedMemory.contains(rule.id);
			if (memory && (uses(rule.when, "questDone") || !uses(rule.when, "questWitnessed")))
			{
				bad.add(rule.id);
			}
		}
		assertTrue("callbacks remembering a quest the follower may not have seen: " + bad,
			bad.isEmpty());
	}

	private static boolean uses(Condition c, String type)
	{
		if (c == null)
		{
			return false;
		}
		if (type.equalsIgnoreCase(c.type))
		{
			return true;
		}
		if (c.conditions != null)
		{
			for (Condition child : c.conditions)
			{
				if (uses(child, type))
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.follower;

import java.util.Arrays;
import java.util.Random;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

/**
 * {@link GouraudRasterizer} against the client's three-case port it replaced
 * (kept in {@code ui.before}), pixel for pixel.
 *
 * <p>The new walker rotates the vertices into the client's first case, so
 * the risk is in the corners the rotation could treat differently: exact ties
 * of rows and slopes, rows that only tie once clipped, and triangles hanging
 * off any edge. The small range covers every one of those exhaustively: every
 * triangle with every coordinate in -3..11 on an 8x8 canvas. Random triangles
 * then cover every size, huge coordinates, forced ties, colours over the
 * whole int range and canvases of several shapes. The buffers carry a guard
 * band, so a write past the canvas would have to land in the same place too.
 */
public class RasterDiffTest
{
	/** Random triangles per canvas shape; {@code -Drasterdiff.random=N} for a longer run. */
	private static final int RANDOM = Integer.getInteger("rasterdiff.random", 100_000);

	private static final int GUARD = 512;

	private long checked;

	private void check(int width, int height, int[] t, int[] oldPixels, int[] newPixels,
		BeforeGouraudRasterizer before, GouraudRasterizer after)
	{
		Arrays.fill(oldPixels, 0);
		Arrays.fill(newPixels, 0);
		String oldThrew = null;
		String newThrew = null;
		try
		{
			before.gouraudTriangle(t[0], t[1], t[2], t[3], t[4], t[5], t[6], t[7], t[8]);
		}
		catch (RuntimeException e)
		{
			oldThrew = e.toString();
		}
		try
		{
			after.gouraudTriangle(t[0], t[1], t[2], t[3], t[4], t[5], t[6], t[7], t[8]);
		}
		catch (RuntimeException e)
		{
			newThrew = e.toString();
		}
		String what = width + "x" + height + " " + Arrays.toString(t);
		assertEquals("exception for " + what, oldThrew, newThrew);
		assertArrayEquals("pixels for " + what, oldPixels, newPixels);
		checked++;
	}

	@Test
	public void everySmallTriangleFillsTheSamePixels()
	{
		int width = 8;
		int height = 8;
		int[] oldPixels = new int[width * height + GUARD];
		int[] newPixels = new int[width * height + GUARD];
		BeforeGouraudRasterizer before = new BeforeGouraudRasterizer(oldPixels, width, height);
		GouraudRasterizer after = new GouraudRasterizer(newPixels, width, height);
		int[] colours = {8000, 9000, 10000, 0, 0xFFFF, 123, 40000, 7, 65000};
		int[] t = new int[9];
		for (int xa = -3; xa <= 11; xa++)
		{
			for (int xb = -3; xb <= 11; xb++)
			{
				for (int xc = -3; xc <= 11; xc++)
				{
					for (int ya = -3; ya <= 11; ya++)
					{
						for (int yb = -3; yb <= 11; yb++)
						{
							for (int yc = -3; yc <= 11; yc++)
							{
								int k = (xa * 7 + xb * 3 + xc + ya * 5 + yb * 11 + yc) & 3;
								t[0] = xa;
								t[1] = xb;
								t[2] = xc;
								t[3] = ya;
								t[4] = yb;
								t[5] = yc;
								t[6] = colours[k];
								t[7] = colours[k + 1];
								t[8] = colours[k + 2];
								check(width, height, t, oldPixels, newPixels, before, after);
							}
						}
					}
				}
			}
		}
		assertEquals(15L * 15 * 15 * 15 * 15 * 15, checked);
	}

	@Test
	public void randomTrianglesFillTheSamePixels()
	{
		Random random = new Random(42);
		int[][] sizes = {{64, 64}, {1, 1}, {64, 1}, {1, 64}, {150, 120}, {7, 300}, {32, 48}};
		int[] t = new int[9];
		for (int[] size : sizes)
		{
			int[] oldPixels = new int[size[0] * size[1] + GUARD];
			int[] newPixels = new int[size[0] * size[1] + GUARD];
			BeforeGouraudRasterizer before = new BeforeGouraudRasterizer(oldPixels, size[0], size[1]);
			GouraudRasterizer after = new GouraudRasterizer(newPixels, size[0], size[1]);
			for (int i = 0; i < RANDOM; i++)
			{
				if (i % 2 == 0)
				{
					// Every size, from a few pixels to far off every edge.
					int range = i % 8 == 0 ? 4000 : i % 8 == 2 ? 400 : i % 8 == 4 ? 40 : 1 << 20;
					for (int j = 0; j < 6; j++)
					{
						t[j] = random.nextInt(range) - range / 2;
					}
				}
				else
				{
					// Coordinates of 4 to 25 bits, the y's sometimes pushed further up.
					int bits = 4 + random.nextInt(22);
					for (int j = 0; j < 6; j++)
					{
						t[j] = random.nextInt(1 << bits) - (1 << (bits - 1))
							+ (j >= 3 && random.nextInt(3) == 0 ? -random.nextInt(1 << bits) : 0);
					}
				}
				// Rows that tie, before or after clipping.
				int tie = random.nextInt(8);
				if (tie == 0)
				{
					t[4] = t[3];
				}
				else if (tie == 1)
				{
					t[5] = t[4];
				}
				else if (tie == 2)
				{
					t[5] = t[3];
				}
				else if (tie == 3)
				{
					t[4] = t[3];
					t[5] = t[3];
				}
				for (int j = 6; j < 9; j++)
				{
					t[j] = random.nextInt(4) == 0 ? random.nextInt() : random.nextInt(0x10000);
				}
				check(size[0], size[1], t, oldPixels, newPixels, before, after);
			}
		}

		// The unit test's extreme cases.
		int[][] extremes = {
			{Integer.MIN_VALUE / 4, Integer.MAX_VALUE / 4, 0, -10, 10, 0},
			{0, 0, 0, Integer.MIN_VALUE / 4, Integer.MAX_VALUE / 4, 0},
			{-1000, 1000, 0, -1000, 1000, 0},
		};
		int[] oldPixels = new int[64 * 64 + GUARD];
		int[] newPixels = new int[64 * 64 + GUARD];
		for (int[] extreme : extremes)
		{
			System.arraycopy(extreme, 0, t, 0, 6);
			t[6] = Integer.MAX_VALUE / 2;
			t[7] = 0;
			t[8] = Integer.MIN_VALUE / 2;
			check(64, 64, t, oldPixels, newPixels,
				new BeforeGouraudRasterizer(oldPixels, 64, 64), new GouraudRasterizer(newPixels, 64, 64));
		}
		assertEquals(sizes.length * (long) RANDOM + extremes.length, checked);
	}
}

package com.follower;

import java.io.IOException;
import java.util.HashSet;
import java.util.Set;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;

/**
 * The number the shuffle bag was built to move, taken off the shipped rules.
 *
 * <p>Variant counts are the one quality figure in this project that can be
 * gamed by writing more without anything getting better. What matters is how
 * many the player HEARS before one comes round again, and under uniform
 * selection those two numbers are wildly different: thirty written, eight
 * heard. This asserts they are now the same number.
 */
public class RepetitionMeasureTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void everyShippedRuleSpendsAllOfItsWritingBeforeRepeating() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());

		int checked = 0;
		StringBuilder worst = new StringBuilder();
		for (SpeechRule rule : h.loader.getRules())
		{
			if (rule.say == null || rule.say.size() < 2)
			{
				continue;
			}
			checked++;

			// Two full cycles, so the refill is included: the seam between one
			// bag and the next is where a naive implementation repeats.
			int size = rule.say.size();
			Set<String> first = new HashSet<>();
			for (int i = 0; i < size; i++)
			{
				if (!first.add(rule.pickPhrase(java.util.Collections.<String>emptySet())))
				{
					worst.append("\n  ").append(rule.id)
						.append(": repeated after ").append(i)
						.append(" of ").append(size);
					break;
				}
			}
			Set<String> second = new HashSet<>();
			for (int i = 0; i < size; i++)
			{
				if (!second.add(rule.pickPhrase(java.util.Collections.<String>emptySet())))
				{
					worst.append("\n  ").append(rule.id)
						.append(": second bag repeated after ").append(i)
						.append(" of ").append(size);
					break;
				}
			}
		}

		assertTrue("rules that repeat before spending their variants:" + worst,
			worst.length() == 0);
		assertTrue("expected the shipped set to have plenty of multi-line rules",
			checked > 300);
	}

	@Test
	public void theBiggestRuleInTheFileIsHeardInFull() throws IOException
	{
		// idle-chatter is the most-written rule and the most-heard, which is
		// the combination that made uniform selection expensive. Thirty
		// variants, and the player used to meet a repeat after about eight.
		Harness h = new Harness(folder.newFolder().toPath());
		SpeechRule rule = h.rule("idle-chatter");
		assertTrue("idle-chatter should still be the big one",
			rule.say.size() >= 25);

		Set<String> heard = new HashSet<>();
		for (int i = 0; i < rule.say.size(); i++)
		{
			heard.add(rule.pickPhrase(java.util.Collections.<String>emptySet()));
		}
		assertTrue("all " + rule.say.size() + " should come out before any repeats,"
			+ " but only " + heard.size() + " did",
			heard.size() == rule.say.size());
	}
}

package com.follower;

import java.io.IOException;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.Client;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Where a rule's gesture goes once its line is said (QA, 15 Oct). Said on
 * the move, it waits for the follower to stand, or the walk drops it on its
 * first frame. Said while the follower rests on its sit, the body stays
 * seated: the gesture would pop it up with no stand-up and sit it down again.
 *
 * <p>The plugin's glue, which no harness drives, so through a bare plugin as
 * StayHoldsTest does it.
 */
public class RuleGestureTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** Records the gestures asked for; plays none of them. */
	private static final class Body extends FollowerEntity
	{
		final List<Integer> now = new ArrayList<>();
		final List<Integer> whenStill = new ArrayList<>();
		boolean planted;

		Body()
		{
			super(null, null);
		}

		@Override
		public void playAnimation(int id)
		{
			now.add(id);
		}

		@Override
		public void playAnimations(int[] ids)
		{
			for (int id : ids)
			{
				now.add(id);
			}
		}

		@Override
		public void playWhenStill(int id, int ticks)
		{
			assertEquals("a few ticks at most", FollowerPlugin.EMOTE_WAIT_TICKS, ticks);
			whenStill.add(id);
		}

		@Override
		public void stayHere()
		{
			planted = true;
		}
	}

	private FollowerPlugin plugin;
	private Body body;

	@Before
	public void setUp() throws IOException, ReflectiveOperationException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		plugin = new FollowerPlugin();
		body = new Body();
		set("client", h.game.client);
		set("config", new FollowerConfig()
		{
		});
		set("follower", body);
		set("speechEngine", h.engine);
		set("dialog", new FollowerDialog(null, null, null, null, null, null, null, null));
		set("clientThread", onTheClientThread());
	}

	private static SpeechRule gesture(int animation)
	{
		SpeechRule rule = new SpeechRule();
		rule.id = "greet-back";
		rule.animation = animation;
		return rule;
	}

	@Test
	public void aRulesGestureWaitsForTheFollowerToStand() throws ReflectiveOperationException
	{
		speak(gesture(863), 863);
		assertEquals(Collections.singletonList(863), body.whenStill);
		assertTrue(body.now.isEmpty());
	}

	@Test
	public void aPlantedGesturePlaysAtOnceSinceTheFeetAreAlreadyStopped() throws ReflectiveOperationException
	{
		SpeechRule rule = gesture(862);
		rule.holdStill = true;
		speak(rule, 862);
		assertTrue(body.planted);
		assertEquals(Collections.singletonList(862), body.now);
		assertTrue(body.whenStill.isEmpty());
	}

	@Test
	public void aGestureOnTheRestLeavesTheFollowerSeated() throws ReflectiveOperationException
	{
		set("resting", true);
		SpeechRule rule = gesture(4278);
		rule.holdStill = true;
		speak(rule, 4278);
		assertTrue("no gesture from the sit", body.now.isEmpty() && body.whenStill.isEmpty());
		assertFalse("and no plant", body.planted);
	}

	@Test
	public void aWritingFlourishIsNotTakenOutOnTheRestEither() throws IOException
	{
		// The flourish would put the writing pose over the sit: the same pop.
		String source = PublicMarkers.strip(new String(Files.readAllBytes(Paths.get("src/main/java/com/follower/FollowerPlugin.java")),
			StandardCharsets.UTF_8).replace("\r\n", "\n"));
		int flourish = source.indexOf("if (rule != null && rule.prop != null && flourish != null");
		assertTrue("the flourish has moved", flourish > 0);
		assertTrue(source.substring(flourish, source.indexOf("{", flourish)).contains("!seated"));
	}

	@Test
	public void theReachComesFirstAndThePropAtTheBottomOfIt() throws IOException
	{
		// QA, 15 Oct: the prop was put in the hand and then the reach played,
		// so the follower bent to the floor already holding it. And the
		// writing pair takes no reach: 13302 lifts them from the waist itself.
		String source = PublicMarkers.strip(new String(Files.readAllBytes(Paths.get("src/main/java/com/follower/FollowerPlugin.java")),
			StandardCharsets.UTF_8).replace("\r\n", "\n"));
		int pair = source.indexOf("public void hold(int leftItemId, int rightItemId)");
		int single = source.indexOf("public void hold(int itemId)");
		assertTrue(pair > 0 && single > 0);
		assertTrue("a single tool reaches",
			source.substring(single, source.indexOf("\n\t\t\t\t}\n", single)).contains("takeOut(true);"));
		assertTrue("the quill and scroll do not",
			source.substring(pair, source.indexOf("\n\t\t\t\t}\n", pair)).contains("takeOut(false);"));
		int takeOut = source.indexOf("void takeOut(boolean reach)");
		String body = source.substring(takeOut, source.indexOf("\n\t\t\t\t}\n", takeOut));
		int reach = body.indexOf("follower.playAnimations(clip);");
		assertTrue("the reach plays", reach > 0);
		assertTrue("the prop waits behind it", body.lastIndexOf("propBehindReach = true;", reach) > 0);
		assertTrue("and comes in partway",
			body.indexOf("follower.atEmoteFraction(REACH_BOTTOM", reach) > reach);
		String rebuild = source.substring(source.indexOf("void rebuildFollower()"));
		assertTrue("the model leaves out a prop behind its reach",
			rebuild.substring(0, rebuild.indexOf("\n\t}\n")).contains("!propBehindReach"));
	}

	private void speak(SpeechRule rule, int animationId) throws ReflectiveOperationException
	{
		Class<?> utterance = Class.forName("com.follower.FollowerPlugin$Utterance");
		Constructor<?> line = utterance.getDeclaredConstructor(String.class, SpeechOutput.class,
			SpeechRule.class, int.class, Runnable.class);
		line.setAccessible(true);
		Method speakNow = FollowerPlugin.class.getDeclaredMethod("speakNow", utterance);
		speakNow.setAccessible(true);
		speakNow.invoke(plugin, line.newInstance("", SpeechOutput.CHATBOX, rule, animationId, null));
	}

	/** A client thread that runs what it is given at once, as on the client thread itself. */
	private static Object onTheClientThread() throws ReflectiveOperationException
	{
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) -> method.getName().equals("isClientThread") ? Boolean.TRUE : null);
		net.runelite.client.callback.ClientThread thread = new net.runelite.client.callback.ClientThread();
		Field field = thread.getClass().getDeclaredField("client");
		field.setAccessible(true);
		field.set(thread, client);
		return thread;
	}

	private void set(String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(plugin, value);
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * What the loader does with a file a person edited by hand.
 *
 * <p>phrases.json is meant to be opened in a text editor, so every kind of
 * mistake will eventually be made in it. None of them may throw, and none may
 * leave the follower mute when the previous rules were fine - losing a whole
 * personality to a trailing comma is worse than running slightly stale rules.
 */
public class RuleLoaderRobustnessTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private Path dir() throws IOException
	{
		return folder.newFolder().toPath();
	}

	private RuleLoader loadedWith(Path dir, String contents) throws IOException
	{
		Files.write(dir.resolve(RuleLoader.FILE_NAME),
			contents.getBytes(StandardCharsets.UTF_8));
		RuleLoader loader = new RuleLoader(new Gson());
