				+ " \"when\": {\"type\": \"always\"}, \"say\": [\"y\"]}]}")
				.getBytes(StandardCharsets.UTF_8));
		assertTrue(loader.reloadIfChanged());
		assertEquals("the repaired file should load", 2, loader.getRules().size());
	}

