	@Test
	public void anUnchangedFileIsNotReloaded() throws IOException
	{
		Path dir = dir();
		RuleLoader loader = loadedWith(dir,
			"{\"version\": 1, \"rules\": [{\"id\": \"x\", \"group\": \"t\","
				+ " \"when\": {\"type\": \"always\"}, \"say\": [\"a\"]}]}");

