	/**
	 * Every tally a rule wagers on, is nicknamed after, or gates itself on has
	 * to be a counter some code path actually increments.
	 *
	 * <p>The kill challenge and the "local menace" nickname both named a
	 * lifetime key nothing ever wrote. The wager failed on its deadline however
	 * well the player did, and the name could never be earned. Nothing could
	 * see it: the key is perfectly legal, it is simply always zero. The written
	 * set is read back out of the source rather than listed here, because a
	 * list is a thing that drifts out of date silently - which is the failure
	 * this is here to end, not to repeat.
	 */
	@Test
	public void everyTallyTheRulesNameIsOneTheCodeWrites() throws IOException
	{
		Set<String> written = new TreeSet<>();
		Set<String> prefixes = new TreeSet<>();
		for (String source : new String[]{
			"src/main/java/com/follower/FollowerPlugin.java",
			"src/main/java/com/follower/SpeechEngine.java"})
		{
			java.nio.file.Path path = java.nio.file.Paths.get(source);
			assertTrue("cannot read " + source, java.nio.file.Files.isRegularFile(path));
			collectTalliedKeys(PublicMarkers.strip(new String(
				java.nio.file.Files.readAllBytes(path), StandardCharsets.UTF_8)),
				written, prefixes);
		}
		assertFalse("no tally calls found at all - the scan broke, not the rules",
			written.isEmpty() && prefixes.isEmpty());

		JsonObject file = bundled("/com/follower/default-phrases.json");
		List<String> problems = new ArrayList<>();

		if (file.has("nicknames"))
		{
			for (java.util.Map.Entry<String, JsonElement> nickname
				: file.getAsJsonObject("nicknames").entrySet())
			{
				if (!isWritten(nickname.getKey(), written, prefixes))
				{
					problems.add("the nickname '" + nickname.getValue().getAsString()
						+ "' is earned on tally '" + nickname.getKey()
						+ "', which nothing writes");
				}
			}
		}

		for (JsonElement element : file.getAsJsonArray("rules"))
		{
			JsonObject rule = element.getAsJsonObject();
			String id = rule.has("id") ? rule.get("id").getAsString() : "?";
			if (rule.has("challenge") && rule.get("challenge").isJsonObject())
			{
				JsonObject challenge = rule.getAsJsonObject("challenge");
				if (challenge.has("tally")
					&& !isWritten(challenge.get("tally").getAsString(), written, prefixes))
				{
					problems.add(id + " wagers on tally '"
						+ challenge.get("tally").getAsString() + "', which nothing writes");
				}
			}
			for (String of : tallyKeysIn(rule.get("when")))
			{
				if (!isWritten(of, written, prefixes))
				{
					problems.add(id + " gates on tally '" + of + "', which nothing writes");
				}
			}
		}

		assertTrue("tallies named by rules that no code path increments:\n  "
			+ String.join("\n  ", problems), problems.isEmpty());
	}

	/** The {@code of} of every tally condition in a when-block, however nested. */
	private static List<String> tallyKeysIn(JsonElement when)
	{
		List<String> keys = new ArrayList<>();
		if (when == null || !when.isJsonObject())
		{
			return keys;
		}
		JsonObject block = when.getAsJsonObject();
		if (block.has("type")
			&& "tally".equalsIgnoreCase(block.get("type").getAsString())
			&& block.has("of"))
		{
			keys.add(block.get("of").getAsString());
		}
		if (block.has("conditions") && block.get("conditions").isJsonArray())
		{
			for (JsonElement child : block.getAsJsonArray("conditions"))
			{
				keys.addAll(tallyKeysIn(child));
			}
		}
		return keys;
	}

	/**
	 * Every string literal handed to a tally call in the given source, split
	 * by what it actually produces.
	 *
	 * <p>The split is the whole point. A literal that IS the argument writes
	 * that key exactly; a literal glued to something else ({@code "kill:" +
	 * name}, {@code "kills" + TODAY}) only ever writes keys LONGER than
	 * itself, and reading it as a whole key is precisely the mistake that let
	 * a challenge wager on a counter that was never written.
	 */
	private static void collectTalliedKeys(String source,
		Set<String> exact, Set<String> prefixes)
	{
		// Case matters: this must not match getTally(), which only READS.
		java.util.regex.Matcher call = java.util.regex.Pattern
			.compile("tallyBoth\\(|tally\\(").matcher(source);
		while (call.find())
		{
			int open = call.end() - 1;
			int depth = 0;
			int end = open;
			while (end < source.length())
			{
				char c = source.charAt(end);
				if (c == '(')
				{
					depth++;
				}
				else if (c == ')' && --depth == 0)
				{
					break;
				}
				end++;
			}

			String argument = source.substring(open, Math.min(end + 1, source.length()));
			java.util.regex.Matcher literal = java.util.regex.Pattern
				.compile("\"([^\"]+)\"").matcher(argument);
			while (literal.find())
			{
				int after = literal.end();
				while (after < argument.length()
					&& Character.isWhitespace(argument.charAt(after)))
				{
					after++;
				}
				boolean glued = after < argument.length() && argument.charAt(after) == '+';
				(glued ? prefixes : exact).add(literal.group(1));
			}
		}
	}

	/**
	 * Whether a key is one the code writes: exactly, as today's half of a
	 * lifetime pair, or as something longer than a prefix the code builds on.
	 */
	private static boolean isWritten(String key, Set<String> exact, Set<String> prefixes)
	{
		if (exact.contains(key))
		{
			return true;
		}
		String base = key.endsWith(":today")
			? key.substring(0, key.length() - ":today".length()) : key;
		if (exact.contains(base))
		{
			return true;
		}
		for (String prefix : prefixes)
		{
			// Strictly longer: a prefix is only ever half of the key it makes.
			if (key.length() > prefix.length() && key.startsWith(prefix))
			{
				return true;
			}
		}
		return false;
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import net.runelite.api.Skill;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;

/**
 * Rules that load cleanly and can still never fire.
 *
 * <p>The loader only rejects a rule with no {@code when} block or nothing to
 * say. Everything past that is accepted and then quietly fails at runtime: a
 * condition whose list of things to look for is empty matches nothing, a regex
 * that will not compile throws on first evaluation and takes its rule out of
 * service, and a level-up rule naming a skill that does not exist waits for an
 * event that never comes.
 *
 * <p>None of those announce themselves. They look exactly like a trigger that
 * has not happened yet, which is the same trap that hid "Gypsy Aris" - a name
 * the wiki uses and the game does not.
 */
public class RuleTriggerSanityTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private List<SpeechRule> shippedRules() throws IOException
	{
		return new Harness(folder.newFolder().toPath()).loader.getRules();
	}

	/** Walks a condition tree, handing every node to the caller. */
	private static void walk(Condition condition, java.util.function.Consumer<Condition> visit)
	{
		if (condition == null)
		{
			return;
		}
		visit.accept(condition);
		if (condition.conditions != null)
		{
			for (Condition child : condition.conditions)
			{
				walk(child, visit);
			}
		}
	}

	private static String type(Condition condition)
	{
		return condition.type == null ? "" : condition.type.toLowerCase(Locale.ROOT);
	}

	// ------------------------------------------------------- dead conditions

	/**
	 * Event-gated condition types: the ones that are only true while a
	 * particular event is being dispatched. Two rules can only compete for the
	 * same moment if they answer the same event.
	 */
	private static final Set<String> EVENT_TYPES = new HashSet<>(Arrays.asList(
		"npcspawn", "npcdespawn", "chatmessage", "varbitchanged", "animationself",
		"levelup", "damagetaken", "playerdeath", "lootworth", "returnvisit",
		"combatstart", "combatend", "npckill", "login", "thrallstart",
		"thrallswitch", "thrallend", "errandstart", "errandend", "thievingstart",
		"thievingend", "personalbest", "sessioncount", "answered", "examined",
		"wantfulfilled", "wantexpired", "regionenter"));

	@Test
	public void noRuleIsOutrankedByOneThatMatchesWheneverItDoes() throws IOException
	{
		// One winner per event, highest priority takes it. So a rule whose
		// conditions are a STRICT SUPERSET of a higher-priority rule's can
		// never win: every time the specific one is true, the general one is
		// true as well, and outranks it. The specific rule then only ever
		// fires inside the general one's cooldown gap, which for anything with
		// a real cooldown means never.
		//
		// This has been found and fixed by hand four times - deaths-many under
		// death-moment, a fear rule under three low-HP rules, the flinch under
		// big-hit-taken, and mood-recovering under the boss celebration. It is
		// invisible by inspection: both rules read perfectly sensibly, and the
		// only symptom is a line nobody ever hears.
		List<SpeechRule> rules = shippedRules();
		List<String> dead = new ArrayList<>();

		for (SpeechRule lower : rules)
		{
			List<Condition> lowerFlat = conjunction(lower.when);
			if (lowerFlat == null || eventsIn(lowerFlat).isEmpty())
			{
				continue;
			}
			Set<String> lowerSigs = signatures(lowerFlat);

			for (SpeechRule higher : rules)
			{
				if (higher == lower || higher.priority <= lower.priority)
				{
					continue;
				}
				List<Condition> higherFlat = conjunction(higher.when);
				if (higherFlat == null)
				{
					continue;
				}
				Set<String> higherEvents = eventsIn(higherFlat);
				if (higherEvents.isEmpty()
					|| java.util.Collections.disjoint(higherEvents, eventsIn(lowerFlat)))
				{
					continue;
				}
				Set<String> higherSigs = signatures(higherFlat);
				if (!higherSigs.isEmpty() && lowerSigs.containsAll(higherSigs)
					&& higherSigs.size() < lowerSigs.size())
				{
					dead.add(lower.id + " (p" + lower.priority + ") can never beat "
						+ higher.id + " (p" + higher.priority + ")");
				}
			}
		}
		assertTrue("rules that can never win, because a higher-priority rule"
			+ " matches whenever they do:\n  " + String.join("\n  ", dead),
			dead.isEmpty());
	}

	/**
	 * The condition list when AND is the whole story, or null. A tree with any
	 * or none in it cannot be compared this way - "not X" and "X" do not
	 * subset each other - so those are left alone rather than guessed at.
	 */
	private static List<Condition> conjunction(Condition when)
	{
		if (when == null)
		{
			return null;
		}
		String kind = type(when);
		if ("any".equals(kind) || "none".equals(kind))
		{
			return null;
		}
		if (!"all".equals(kind))
		{
			return java.util.Collections.singletonList(when);
		}
		if (when.conditions == null)
		{
			return null;
		}
		for (Condition child : when.conditions)
		{
			String childKind = type(child);
			if ("all".equals(childKind) || "any".equals(childKind) || "none".equals(childKind))
			{
				return null;
			}
		}
		return when.conditions;
	}

	private static Set<String> eventsIn(List<Condition> conditions)
	{
		Set<String> found = new HashSet<>();
		for (Condition condition : conditions)
		{
			if (EVENT_TYPES.contains(type(condition)))
			{
				found.add(type(condition));
			}
		}
		return found;
	}

	/** A condition as a comparable key: its type plus every field it sets. */
	private static Set<String> signatures(List<Condition> conditions)
	{
		Set<String> found = new HashSet<>();
		for (Condition condition : conditions)
		{
			found.add(new Gson().toJson(condition));
		}
		return found;
	}

	@Test
	public void noRuleAsksForTwoThingsThatCannotBothBeTrue() throws IOException
	{
		// phrases.json is edited by hand and through the panel, and the shape
		// most of it is in is an "all" of thresholds. Nothing rejects a pair
		// that cannot both hold - the rule loads, evaluates, and is false
		// forever. The idle window is the one to watch: every fidget in the
		// file is an idle/idleBelow pair, and widening the first past the
		// second closes it completely.
		List<String> impossible = new ArrayList<>();
		for (SpeechRule rule : shippedRules())
		{
			List<Condition> conditions = conjunction(rule.when);
			if (conditions == null)
			{
				continue;
			}

			int idleFrom = Integer.MIN_VALUE;
			int idleTo = Integer.MAX_VALUE;
			int healthBelow = Integer.MAX_VALUE;
			int healthAbove = Integer.MIN_VALUE;
			java.util.Map<String, Integer> minimums = new java.util.HashMap<>();
			java.util.Map<String, Integer> maximums = new java.util.HashMap<>();

			for (Condition condition : conditions)
			{
				String kind = type(condition);
				if ("idle".equals(kind))
				{
					idleFrom = Math.max(idleFrom,
						condition.ticks == null ? 50 : condition.ticks);
				}
				if ("idlebelow".equals(kind))
				{
					idleTo = Math.min(idleTo,
						condition.ticks == null ? 500 : condition.ticks);
				}
				if ("healthbelow".equals(kind))
				{
					healthBelow = Math.min(healthBelow,
						condition.percent == null ? 50 : condition.percent);
				}
				if ("healthabove".equals(kind))
				{
					healthAbove = Math.max(healthAbove,
						condition.percent == null ? 50 : condition.percent);
				}
				// timeOfDay is a window on a CLOCK: 23 to 5 is five hours,
				// not an empty range, and the evaluator wraps deliberately.
				if ("timeofday".equals(kind))
				{
					return;
				}
				// Two tally conditions in one rule are usually counting two
				// different things - "asked three times, taken nowhere" is one
				// rule with a minimum on one tally and a maximum on another.
				// Keyed on the type alone they read as one contradictory range.
				String counted = condition.of == null ? kind : kind + ":" + condition.of;
				if (condition.minimum != null)
				{
					minimums.merge(counted, condition.minimum, Math::max);
				}
				if (condition.maximum != null)
				{
					maximums.merge(counted, condition.maximum, Math::min);
				}
			}

			if (idleFrom != Integer.MIN_VALUE && idleTo != Integer.MAX_VALUE
				&& idleFrom >= idleTo)
			{
				impossible.add(rule.id + ": idle >= " + idleFrom + " and idleBelow "
					+ idleTo + " is an empty window");
			}
			if (healthBelow != Integer.MAX_VALUE && healthAbove != Integer.MIN_VALUE
				&& healthAbove >= healthBelow)
			{
				impossible.add(rule.id + ": health above " + healthAbove
					+ " and below " + healthBelow + " at the same time");
			}
			for (java.util.Map.Entry<String, Integer> entry : minimums.entrySet())
			{
				Integer max = maximums.get(entry.getKey());
				if (max != null && entry.getValue() > max)
				{
					impossible.add(rule.id + ": " + entry.getKey() + " wants minimum "
						+ entry.getValue() + " and maximum " + max);
				}
			}
		}
		assertTrue("rules asking for two things that cannot both be true, so they"
			+ " evaluate false forever:\n  " + String.join("\n  ", impossible),
			impossible.isEmpty());
	}

	@Test
	public void nothingScansTheSceneBeforeAChanceThrowsTheAnswerAway() throws IOException
	{
		// These four walk a list of actors or the whole inventory every time
		// they are asked; everything else in the language is a field read or a
		// set lookup. Inside an "all", a chance roll placed AFTER one of them
		// means the scan happens every tick and the roll discards it - at a
		// busy bank that is a couple of hundred world-point allocations a tick
		// to answer a question that mattered eight percent of the time.
		//
		// The fix is free: "all" is a conjunction, so the order changes nothing
		// but which condition gets to short-circuit.
		Set<String> scans = new HashSet<>(Arrays.asList(
			"npcnearby", "petnearby", "playersnearby", "inventoryfree"));

		List<String> wasteful = new ArrayList<>();
		for (SpeechRule rule : shippedRules())
		{
			walk(rule.when, condition ->
			{
				if (!"all".equals(type(condition)) || condition.conditions == null)
				{
					return;
				}
				int firstScan = -1;
				for (int i = 0; i < condition.conditions.size(); i++)
				{
					String kind = type(condition.conditions.get(i));
					if (firstScan < 0 && scans.contains(kind))
					{
						firstScan = i;
					}
					if (firstScan >= 0 && i > firstScan && "chance".equals(kind))
					{
						wasteful.add(rule.id + ": "
							+ type(condition.conditions.get(firstScan))
							+ " is scanned before the chance that discards it");
						return;
					}
				}
			});
		}
		assertTrue("scene scans that run more often than they need to:\n  "
			+ String.join("\n  ", wasteful), wasteful.isEmpty());
	}

	@Test
	public void noConditionLooksForSomethingWithoutSayingWhat() throws IOException
	{
		// These types match by a list. With the list absent or empty they can
		// never be true, and the rule is dead on arrival.
		Set<String> needsNames = new HashSet<>(Arrays.asList(
			"npcspawn", "npcdespawn", "npcnearby"));
		Set<String> needsIds = new HashSet<>(Arrays.asList(
			"itemequipped", "animationself"));

		List<String> dead = new ArrayList<>();
		for (SpeechRule rule : shippedRules())
		{
			walk(rule.when, condition ->
			{
				String type = type(condition);
				boolean noNames = condition.names == null || condition.names.isEmpty();
				boolean noIds = condition.ids == null || condition.ids.isEmpty();

				// npcNearby is the exception: a combat-level bracket on its own
				// is a complete test, and a deliberate one - it matches every
				// large thing in the game, including the ones added after this
				// was written, which no list of names can manage.
				boolean bracketed = "npcnearby".equals(type)
					&& (condition.minimum != null || condition.maximum != null);

				if (needsNames.contains(type) && noNames && noIds && !bracketed)
				{
					dead.add(rule.id + ": " + type + " with neither names nor ids");
				}
				if (needsIds.contains(type) && noIds)
				{
					dead.add(rule.id + ": " + type + " with no ids");
				}
				if (type.equals("inregion")
					&& (condition.regions == null || condition.regions.isEmpty()))
				{
					dead.add(rule.id + ": inRegion with no regions");
				}
				if (type.equals("regionenter")
					&& (condition.regions == null || condition.regions.isEmpty()))
				{
					dead.add(rule.id + ": regionEnter with no regions");
				}
				if (type.equals("varbitequals") && condition.varbit == null)
				{
					dead.add(rule.id + ": varbitEquals with no varbit");
				}
				if (type.equals("varbitchanged") && condition.varbit == null)
				{
					dead.add(rule.id + ": varbitChanged with no varbit");
				}
				if (type.equals("questvar") && condition.varbit == null && condition.varp == null)
				{
					dead.add(rule.id + ": questVar with neither varbit nor varp");
				}
				if (type.equals("inarea")
					&& (condition.x1 == null || condition.y1 == null
					|| condition.x2 == null || condition.y2 == null))
				{
					dead.add(rule.id + ": inArea missing a corner");
				}
				if (type.equals("chatmessage")
					&& condition.contains == null && condition.regex == null && noNames)
				{
					dead.add(rule.id + ": chatMessage with nothing to match");
				}
			});
		}

		assertTrue("rules that load fine and can never fire:\n  "
			+ String.join("\n  ", dead), dead.isEmpty());
	}

	@Test
	public void noNameToMatchIsBlank() throws IOException
	{
		List<String> problems = new ArrayList<>();
		for (SpeechRule rule : shippedRules())
		{
			walk(rule.when, condition ->
			{
				if (condition.names == null)
				{
					return;
				}
				for (String name : condition.names)
				{
					if (name == null || name.trim().isEmpty())
					{
						problems.add(rule.id + ": a blank name in " + type(condition));
					}
					else if (!name.equals(name.trim()))
					{
						// Matching trims the candidate, not the pattern, so a
						// stray space here never matches anything.
						problems.add(rule.id + ": \"" + name + "\" has padding");
					}
				}
			});
		}
		assertTrue(String.join("\n  ", problems), problems.isEmpty());
	}

	// -------------------------------------------------------------- patterns

	@Test
	public void everyRegexCompiles() throws IOException
	{
		// A regex that will not compile throws from inside matches(), and the
		// engine's response is to disable that rule for the session.
		List<String> broken = new ArrayList<>();
		for (SpeechRule rule : shippedRules())
		{
			walk(rule.when, condition ->
			{
				if (condition.regex == null)
				{
					return;
				}
				try
				{
					Pattern.compile(condition.regex, Pattern.CASE_INSENSITIVE);
				}
				catch (PatternSyntaxException e)
				{
					broken.add(rule.id + ": " + condition.regex + " - " + e.getDescription());
				}
			});
		}
		assertTrue("regexes that would disable their own rule:\n  "
			+ String.join("\n  ", broken), broken.isEmpty());
	}

	@Test
	public void everyWildcardNameCompiles() throws IOException
	{
		// Names become patterns too, by quoting the literals around each *.
		List<String> broken = new ArrayList<>();
		for (SpeechRule rule : shippedRules())
		{
			walk(rule.when, condition ->
			{
				if (condition.names == null)
				{
					return;
				}
				for (String name : condition.names)
				{
					StringBuilder pattern = new StringBuilder();
					for (String literal : name.split("\\*", -1))
					{
						if (pattern.length() > 0)
						{
							pattern.append(".*");
						}
						pattern.append(Pattern.quote(literal));
					}
					try
					{
						Pattern.compile(pattern.toString(), Pattern.CASE_INSENSITIVE);
					}
					catch (PatternSyntaxException e)
					{
						broken.add(rule.id + ": " + name);
					}
				}
			});
		}
		assertTrue(String.join("\n  ", broken), broken.isEmpty());
	}

	// ---------------------------------------------------------------- values

	@Test
	public void everyLevelUpNamesARealSkill() throws IOException
	{
		Set<String> skills = new HashSet<>();
		for (Skill skill : Skill.values())
		{
			skills.add(skill.getName().toLowerCase(Locale.ROOT));
		}

		List<String> problems = new ArrayList<>();
		for (SpeechRule rule : shippedRules())
		{
			walk(rule.when, condition ->
			{
				if (!type(condition).equals("levelup") || condition.names == null)
				{
					return;
				}
				for (String name : condition.names)
				{
					String plain = name.replace("*", "").trim().toLowerCase(Locale.ROOT);
					if (!plain.isEmpty() && !skills.contains(plain))
					{
						problems.add(rule.id + ": \"" + name + "\" is not a skill");
					}
				}
			});
		}
		assertTrue("level-up rules waiting on a skill that does not exist:\n  "
			+ String.join("\n  ", problems), problems.isEmpty());
	}

	@Test
	public void percentagesAreInRange() throws IOException
	{
		List<String> problems = new ArrayList<>();
		for (SpeechRule rule : shippedRules())
		{
			walk(rule.when, condition ->
			{
				if (condition.percent == null)
				{
					return;
				}
				int percent = condition.percent;
				if (percent < 0 || percent > 100)
				{
					problems.add(rule.id + ": " + type(condition) + " at " + percent + "%");
				}
			});
		}
		assertTrue("a percentage outside 0-100 either never fires or always"
			+ " does:\n  " + String.join("\n  ", problems), problems.isEmpty());
	}

	@Test
	public void distancesAndCountsArePositive() throws IOException
	{
		List<String> problems = new ArrayList<>();
		for (SpeechRule rule : shippedRules())
		{
			walk(rule.when, condition ->
			{
				if (condition.within != null && condition.within <= 0)
				{
					problems.add(rule.id + ": within " + condition.within);
				}
				if (condition.ticks != null && condition.ticks < 0)
				{
					problems.add(rule.id + ": ticks " + condition.ticks);
				}
				if (condition.minimum != null && condition.maximum != null
					&& condition.maximum < condition.minimum
					&& !"timeofday".equalsIgnoreCase(condition.type))
				{
					problems.add(rule.id + ": minimum " + condition.minimum
						+ " above maximum " + condition.maximum);
				}
			});
		}
		assertTrue(String.join("\n  ", problems), problems.isEmpty());
	}

	@Test
	public void cooldownsAndPrioritiesAreSane() throws IOException
	{
		List<String> problems = new ArrayList<>();
		for (SpeechRule rule : shippedRules())
		{
			if (rule.cooldownMs < 0)
			{
				problems.add(rule.id + ": negative cooldown");
			}
			// A cooldown longer than a very long session means one firing ever.
			if (rule.cooldownMs > 6L * 60 * 60 * 1000)
			{
				problems.add(rule.id + ": cooldown of " + rule.cooldownMs + "ms");
			}
			if (rule.delayTicks != null && rule.delayTicks < 0)
			{
				problems.add(rule.id + ": negative delay");
			}
		}
		assertTrue(String.join("\n  ", problems), problems.isEmpty());
	}

	@Test
	public void aNearbyRadiusIsWithinWhatTheSceneCanSee() throws IOException
	{
		// The scene is 104 tiles; a radius past that is asking about NPCs the
		// client cannot see, so the rule quietly behaves as a smaller one.
		List<String> problems = new ArrayList<>();
		for (SpeechRule rule : shippedRules())
		{
			walk(rule.when, condition ->
			{
				String type = type(condition);
				if ((type.equals("npcnearby") || type.equals("petnearby"))
					&& condition.within != null && condition.within > 52)
