	}
}

package com.follower;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * A line a starting cutscene cuts off. QA, 15 Oct: the scene clears the
 * overhead on its first tick, and a once line (every quest-moment draft)
 * that had been up a tick or two was spent without being read. Such a line
 * is now said again after the scene and its quiet.
 */
public class SceneCutTest
{
	private static SpeechRule rule(Boolean once, Boolean occasion)
	{
		SpeechRule rule = new SpeechRule();
		rule.id = "probe";
		rule.once = once;
		rule.occasion = occasion;
		return rule;
	}

	@Test
	public void aOnceLineOrAnOccasionJustUpIsSaidAgain()
	{
		assertTrue(FollowerPlugin.saysAgainAfterTheScene(rule(true, null), 600, 1_000));
		assertTrue(FollowerPlugin.saysAgainAfterTheScene(rule(null, true), 1_900, 1_000));
	}

	/** Behaviour QA, 16 Oct: a bet's payoff, a line that waits, cut 1.2 s in and lost. */
	@Test
	public void aLineThatWaitsIsSaidAgainToo()
	{
		SpeechRule waits = rule(null, null);
		waits.waits = true;
		assertTrue(FollowerPlugin.saysAgainAfterTheScene(waits, 1_200, 3_000));
	}

	/**
	 * Behaviour QA, 16 Oct (probe P10): the hideout line was said again after
	 * the scene that moved its step on, with the next step's moment 6 s
	 * behind it. The re-say checks the step, as the engine does.
	 */
	@Test
	public void aCutLineWhoseStepMovedOnIsNotSaidAgain() throws IOException
	{
		String src = PublicMarkers.strip(new String(Files.readAllBytes(
			Paths.get("src/main/java/com/follower/FollowerPlugin.java")), StandardCharsets.UTF_8));
		assertTrue(src.contains(
			"if (cutByTheScene.rule.when.questStepHolds(context(), TriggerEvent.tick()))"));
	}

	/**
	 * QA pass 2: the window's scene cut the hideout line 2.4 s into the
	 * 3.5 s it takes to read, and it was spent half read. A line cut before
	 * it could be read is said again; a short one read by then is not.
	 */
	@Test
	public void aLineCutBeforeItCouldBeReadIsSaidAgain()
	{
		assertTrue(FollowerPlugin.saysAgainAfterTheScene(rule(true, true), 2_400, 3_529));
		assertFalse("read by then",
			FollowerPlugin.saysAgainAfterTheScene(rule(true, true), 2_400, 1_176));
	}

	@Test
	public void anOrdinaryLineOrOneAlreadyReadIsLetGo()
	{
		assertFalse("comes round again", FollowerPlugin.saysAgainAfterTheScene(rule(null, null), 600, 1_000));
		assertFalse("up long enough to read",
			FollowerPlugin.saysAgainAfterTheScene(rule(true, null), FollowerPlugin.SCENE_CUT_GRACE_MS, 1_000));
		assertFalse("the player's own line", FollowerPlugin.saysAgainAfterTheScene(null, 600, 1_000));
	}

	/**
	 * The plugin judges the cut on the line's own reading time, and keeps
	 * the line through a conversation after the quiet rather than saying it
	 * into the box, where the words are dropped (QA pass 2: a runner reaches
	 * Sergeant Tobyn inside the quiet after the window's scene).
	 */
	@Test
	public void thePluginJudgesOnReadingTimeAndKeepsTheLineThroughAConversation() throws IOException
	{
		String src = PublicMarkers.strip(new String(Files.readAllBytes(
			Paths.get("src/main/java/com/follower/FollowerPlugin.java")), StandardCharsets.UTF_8));
		assertTrue(src.contains("timeToReadMs(onScreen.text)) ? onScreen : null;"));
		assertTrue(src.contains("if (cutByTheScene != null && (sceneQuiet() || inConversation()))"));
	}

	/**
	 * Wherever the plugin empties the line queue for a reason other than the
	 * scene itself (a logout, a hop, a film, a profile switch), the line held
	 * over a scene goes with it.
	 */
	@Test
	public void everyQueueResetDropsTheHeldLine() throws IOException
	{
		String[] lines = PublicMarkers.strip(new String(Files.readAllBytes(
			Paths.get("src/main/java/com/follower/FollowerPlugin.java")), StandardCharsets.UTF_8))
			.split("\r?\n");
		int clears = 0;
		int dropped = 0;
		for (int i = 0; i < lines.length; i++)
		{
			if (!lines[i].trim().equals("speechQueue.clear();"))
			{
				continue;
			}
			clears++;
			if (lines[i + 1].trim().equals("cutByTheScene = null;"))
			{
				dropped++;
			}
		}
		// The two that keep it: the scene's own start, and the sketch's
		// reshuffle, which puts the queue straight back.
		assertEquals(clears - 1, dropped);
	}
}

package com.follower;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Deque;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The follower as an extra in a cutscene: it holds the tile it stands on,
 * steps across the way of an actor that comes onto it, and walks over to the
 * player once after the scene has put them down somewhere else.
 *
 * <p>Play test, 9 Oct, Children of the Sun: "The follower was walking around
 * a bit too much and was at some points standing inside of an npc."
 *
 * <p>Driven against the real {@link FollowerEntity}. The frame loop needs a
 * RuneLiteObject the fake client cannot make, so its state is set by
 * reflection, as FireLineTest and MotherlodeSeatTest do, and the scene's
 * keeping is called a tick at a time.
 */
public class SceneExtraTest
{
	private static final WorldPoint MARK = new WorldPoint(50, 50, 0);

	private final FakeGame game = new FakeGame().withCollision();
	private final FollowerEntity follower = new FollowerEntity(game.client, null);
	private int tick;

	@Before
	public void setUp()
	{
		game.at(52, 52, 0);
		set("spawned", true);
		standOn(MARK);
	}

	@Test
	public void itHoldsWhereItStands()
	{
		keep();
		assertEquals("its own tile is its mark", MARK, follower.getStayTile());
		assertTrue("and nothing is walked", path("serverPath").isEmpty());
	}

	@Test
	public void anActorArrivingIsGivenWayAcrossItsPath()
	{
		keep();
		NPC guard = game.spawnNpc(100, "Guard", 21);
		game.moveNpc(guard, 50, 50, 0).npcTurned(guard, 1536);
		keep();
		WorldPoint step = follower.getStayTile();
		assertTrue("across an eastbound guard's way, not along it: " + step,
			step.equals(new WorldPoint(50, 51, 0)) || step.equals(new WorldPoint(50, 49, 0)));
	}

	@Test
	public void aGiantsWholeFootprintCounts()
	{
		keep();
		NPC giant = game.spawnNpc(2098, "Hill Giant", 28);
		game.moveNpc(giant, 49, 49, 0).npcSize(giant, 2);
		keep();
		WorldPoint step = follower.getStayTile();
		assertNotEquals("off the giant's north-east tile", MARK, step);
		assertFalse("and outside all four of its tiles: " + step,
			step.getX() >= 49 && step.getX() <= 50 && step.getY() >= 49 && step.getY() <= 50);
	}

	@Test
	public void neverOntoAnotherNpcOrThePlayer()
	{
		game.at(50, 49, 0);
		keep();
		NPC guard = game.spawnNpc(100, "Guard", 21);
		game.moveNpc(guard, 50, 50, 0).npcTurned(guard, 1536);
		NPC noah = game.spawnNpc(12647, "Noah", 0);
		game.moveNpc(noah, 50, 51, 0);
		keep();
		WorldPoint step = follower.getStayTile();
		assertNotEquals("not onto Noah", new WorldPoint(50, 51, 0), step);
		assertNotEquals("not onto the player", new WorldPoint(50, 49, 0), step);
		assertEquals("a free diagonal instead", 1, Math.abs(step.getX() - 50));
		assertEquals(1, Math.abs(step.getY() - 50));
	}

	@Test
	public void boxedInItKeepsItsTile()
	{
		keep();
		NPC guard = game.spawnNpc(100, "Guard", 21);
		game.moveNpc(guard, 50, 50, 0);
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (dx != 0 || dy != 0)
				{
					game.moveNpc(game.spawnNpc(3000, "Bandit", 0), 50 + dx, 50 + dy, 0);
				}
			}
		}
		keep();
		assertEquals("nowhere to go, so the tile is kept", MARK, follower.getStayTile());
	}

	@Test
	public void itHoldsWhileThePlayerIsWalkedAndWalksOverOnceTheyStop()
	{
		game.at(51, 50, 0);
		keep();
		for (int x = 52; x <= 57; x++)
		{
			game.at(x, 50, 0);
			keep();
			assertEquals("still on its mark while the scene walks the player", MARK, follower.getStayTile());
		}
		keep();
		assertEquals("one still tick is not stopped", MARK, follower.getStayTile());
		keep();
		assertNull("stopped seven tiles off: let go to walk over", follower.getStayTile());
		assertTrue((Boolean) get("catchingUp"));

		WorldPoint beside = new WorldPoint(56, 50, 0);
		standOn(beside);
		keep();
		assertEquals("held again once there", beside, follower.getStayTile());
		assertFalse((Boolean) get("catchingUp"));
	}

	@Test
	public void oneLookATick()
	{
		keep();
		NPC guard = game.spawnNpc(100, "Guard", 21);
		game.moveNpc(guard, 50, 50, 0);
		invoke();
		assertEquals("the same tick is not looked at twice", MARK, follower.getStayTile());
		keep();
		assertNotEquals("the next one is", MARK, follower.getStayTile());
	}

	/**
	 * Play test, 15 Oct (Children of the Sun): the player turned and the
	 * follower went on facing them. The hold's own facing ran ahead of the
	 * frame's turn and pointed it back at the player every frame.
	 */
	@Test
	public void theHoldLooksWhereThePlayerLooks()
	{
		keep();
		set("watchingWithThePlayer", true);
		for (int jau : new int[]{1536, 512, 0})
		{
			game.turned(jau);
			faceTheHold();
			assertEquals("turned the way the player is", jau, get("dstYaw"));
		}
		set("watchingWithThePlayer", false);
		set("lastRenderedLocation", net.runelite.api.coords.LocalPoint.fromWorld(game.client, MARK));
		faceTheHold();
		assertNotEquals("out of a scene, a stay faces the player again", 0, get("dstYaw"));
	}

	/**
	 * Both of the frame's facings of a held follower go through the scene's
	 * look (the order inside it: WallPathingTest). A third caller of the
	 * stay's own facing is how the scene's look was lost.
	 */
	@Test
	public void theFrameFacesTheHoldOnlyThroughTheScenesLook() throws java.io.IOException
	{
		String source = PublicMarkers.strip(new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(
			"src/main/java/com/follower/FollowerEntity.java")), java.nio.charset.StandardCharsets.UTF_8));
		int calls = 0;
		for (int at = source.indexOf("faceStayAnchor();"); at >= 0; at = source.indexOf("faceStayAnchor();", at + 1))
		{
			calls++;
		}
		assertEquals("faceTheHold, and faceAnchor while the feet move", 2, calls);
	}

	// ---------------------------------------------------------------- helpers

	private void faceTheHold()
	{
		try
		{
			Method face = FollowerEntity.class.getDeclaredMethod("faceTheHold", net.runelite.api.Player.class);
			face.setAccessible(true);
			face.invoke(follower, game.client.getLocalPlayer());
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError("FollowerEntity.faceTheHold has moved", e);
		}
	}

	/** The next tick's keeping of the scene, with the player where they are. */
	private void keep()
	{
		game.tick(++tick);
		invoke();
	}

	private void invoke()
	{
		try
		{
			Method keep = FollowerEntity.class.getDeclaredMethod("keepToTheScene", WorldPoint.class);
			keep.setAccessible(true);
			keep.invoke(follower, game.client.getLocalPlayer().getWorldLocation());
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError("FollowerEntity.keepToTheScene has moved", e);
		}
	}

	/** Spawned and at rest on a tile, its walk there over. */
	private void standOn(WorldPoint at)
	{
		set("tile", at);
		set("simTile", at);
		set("fineWX", at.getX() * 128L + 64);
		set("fineWY", at.getY() * 128L + 64);
		path("serverPath").clear();
		path("route").clear();
	}

	@SuppressWarnings("unchecked")
	private Deque<WorldPoint> path(String name)
	{
		return (Deque<WorldPoint>) get(name);
	}

	private void set(String name, Object value)
	{
		try
		{
			Field field = FollowerEntity.class.getDeclaredField(name);
			field.setAccessible(true);
			field.set(follower, value);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(name, e);
		}
	}

	private Object get(String name)
	{
		try
		{
			Field field = FollowerEntity.class.getDeclaredField(name);
			field.setAccessible(true);
			return field.get(follower);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(name, e);
		}
	}
}

package com.follower;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Nothing said in a cutscene, or for a little while after one. Play test,
 * 9 Oct: a line was said over the opening of Children of the Sun's first
 * cutscene, and the player asked for the follower to keep quiet for a bit
 * once a scene is over too.
 *
 * <p>Chatter is dropped there, as under the mute. An occasion - a quest's
 * end, a boss, a pet - is the one line the moment has, so it waits the
 * scene out and is said after, within reason.
 */
public class SceneQuietTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** Game time: 600 ms a tick, so the gap between two lines can pass. */
	private final long[] ms = {1_000_000L};

	private final List<String> held = new ArrayList<>();

	private Harness harness(String... bodies) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": [" + String.join(",", bodies) + "]}");
		h.engine.setClock(() -> ms[0]);
		h.engine.setGlobalCooldownMs(3000L);
		h.engine.setOnSuppressed((rule, why) -> held.add(rule.describe() + ":" + why));
		h.gameTicks(1);
		return h;
	}

	private static final String CHATTY = "{\"id\": \"chatty\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"healthBelow\", \"percent\": 50}, \"say\": [\"ouch\"]}";

	private static final String QUEST = "{\"id\": \"quest\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"occasion\": true, \"when\": {\"type\": \"questComplete\"}, \"say\": [\"Done and witnessed.\"]}";

	private static final String LEVEL = "{\"id\": \"level\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"occasion\": true, \"when\": {\"type\": \"levelUp\", \"names\": [\"*\"]}, \"say\": [\"Attack 30.\"]}";

	private void ticks(Harness h, int count)
	{
		for (int i = 0; i < count; i++)
		{
			ms[0] += 600;
			h.gameTick();
		}
	}

	@Test
	public void chatterInTheQuietIsDroppedForTheScene() throws IOException
	{
		Harness h = harness(CHATTY);
		h.engine.setSceneQuiet(true);
		h.game.hitpoints(10, 99);
		ticks(h, 2);
		assertTrue("nothing said in the quiet", h.firedBy("chatty").isEmpty());
		assertEquals("and the transcript says why", "chatty:scene", held.get(0));

		h.engine.setSceneQuiet(false);
		ticks(h, 20);
		assertTrue("dropped, not kept for after", h.firedBy("chatty").isEmpty());
	}

	@Test
	public void theMuteStillSaysMuted() throws IOException
	{
		Harness h = harness(CHATTY);
		h.engine.setMuted(true);
		h.engine.setSceneQuiet(true);
		h.game.hitpoints(10, 99);
		ticks(h, 2);
		assertEquals("the setting is the reason first", "chatty:muted", held.get(0));
	}

	@Test
	public void theRuleHoldingTheFloorIsHeldToo() throws IOException
	{
		// The holder speaks through its own hush; a scene silences it as well.
		Harness h = harness("{\"id\": \"floor\", \"group\": \"t\", \"cooldownMs\": 0, \"hushMs\": 10000,"
			+ " \"when\": {\"type\": \"healthBelow\", \"percent\": 50}, \"say\": [\"ouch\"]}");
		h.engine.setSceneQuiet(true);
		h.game.hitpoints(10, 99);
		ticks(h, 2);
		assertTrue(h.firedBy("floor").isEmpty());
		assertEquals("floor:scene", held.get(0));
	}

	@Test
	public void anOccasionInASceneIsSaidAfterTheQuietAndNotBefore() throws IOException
	{
		Harness h = harness(QUEST);
		h.engine.setSceneQuiet(true);
		h.dispatch(TriggerEvent.questComplete("Children of the Sun"));
		ticks(h, 100);
		assertTrue("not over the scene", h.firedBy("quest").isEmpty());

		h.engine.setSceneQuiet(false);
		ticks(h, 1);
		assertEquals("said once it is over", 1, h.firedBy("quest").size());
		ticks(h, 20);
		assertEquals("and only once", 1, h.firedBy("quest").size());
	}

	@Test
	public void twoOccasionsInOneSceneAreBothSaidAfterIt() throws IOException
	{
		// The scene's wait is counted apart from the gap's, so the second
		// still has its gap to wait out after the first is said.
		Harness h = harness(QUEST, LEVEL);
		h.engine.setSceneQuiet(true);
		h.dispatch(TriggerEvent.questComplete("Children of the Sun"));
		h.dispatch(TriggerEvent.levelUp("Attack", 30));
		ticks(h, 50);
		assertTrue(h.spoken.isEmpty());

		h.engine.setSceneQuiet(false);
		ticks(h, 1);
		assertEquals("one at a time", 1, h.spoken.size());
		ticks(h, 15);
		assertEquals("both said", 1, h.firedBy("quest").size());
		assertEquals(1, h.firedBy("level").size());
	}

	/**
