		h.dispatch(TriggerEvent.levelUp("Attack", 30));
		ticks(h, 50);

		h.engine.setSceneQuiet(false);
		ticks(h, 1);
		assertEquals("one at a time", 1, h.spoken.size());
		ticks(h, 100);
		assertEquals("both said", 2, h.spoken.size());
		assertTrue("nothing dropped", held.isEmpty());
	}

