		Harness h = harness(QUEST, LEVEL, "{\"id\": \"floor\", \"group\": \"t\", \"cooldownMs\": 0,"
			+ " \"hushMs\": 10000, \"when\": {\"type\": \"healthBelow\", \"percent\": 50}, \"say\": [\"ouch\"]}");
