		ticks(h, 1);
		assertEquals(1, h.spoken.size());
		h.game.hitpoints(10, 99);
		ticks(h, 40);
		assertEquals("both occasions said", 1, h.firedBy("quest").size());
		assertEquals(1, h.firedBy("level").size());
	}

