	@Test
	public void everyToolAndHatAnswersAsItDid()
	{
		Set<Integer> animations = new HashSet<>(Arrays.asList(-1, 0, 1, 618, 619, 620, 621, 622,
			623, 1193, 88, 5108, 7401, 7402, 8336, 8784, 6932, 8188, 8189, 8190, 8191, 8192, 8193,
			9350, 829, 99999));
		animations.addAll(FARMING_TOOLS.keySet());
		List<Set<Integer>> worns = new ArrayList<>();
		worns.add(null);
		worns.add(new HashSet<>());
		Set<Integer> everyTool = new HashSet<>();
		for (int[] tiers : new int[][]{AXES, PICKAXES, HARPOONS, RODS})
		{
			for (int id : tiers)
			{
				worns.add(new HashSet<>(Arrays.asList(id)));
				everyTool.add(id);
			}
		}
		worns.add(everyTool);
		worns.add(new HashSet<>(Arrays.asList(1359, 1275, 23864, 22842)));
		for (int[] outfit : OUTFITS)
		{
			Set<Integer> full = new HashSet<>();
			for (int piece : outfit)
			{
				full.add(piece);
			}
			worns.add(full);
			Set<Integer> partial = new HashSet<>(full);
			partial.remove(outfit[3]);
			worns.add(partial);
			Set<Integer> withAxe = new HashSet<>(full);
			withAxe.add(1359);
			worns.add(withAxe);
		}
		String[][] weapons = {
			{"0", null}, {"1359", "Rune axe"}, {"1275", "Rune pickaxe"}, {"21028", "Dragon harpoon"},
			{"7639", "Rod of ivandis (10)"}, {"307", "Fishing rod"}, {"11323", "Barbarian rod"},
			{"1377", "Dragon battleaxe"}, {"4151", "Abyssal whip"}, {"311", "Harpoon"},
			{"1359", null}, {"-1", "Rune axe"},
		};
		int compared = 0;
		for (String activity : ACTIVITIES)
		{
			for (Set<Integer> worn : worns)
			{
				assertEquals(activity, oldHatFor(activity, worn), Borrow.hatFor(activity, worn));
				for (int animation : animations)
				{
					assertEquals(activity + "/" + animation + "/" + worn,
						oldToolFor(activity, animation, worn), Borrow.toolFor(activity, animation, worn));
					for (String[] weapon : weapons)
					{
						int id = Integer.parseInt(weapon[0]);
						assertEquals(activity + "/" + animation + "/" + weapon[1],
							oldToolFor(activity, animation, worn, id, weapon[1]),
							Borrow.toolFor(activity, animation, worn, id, weapon[1]));
						compared++;
					}
				}
			}
		}
		assertTrue(compared > 1_000_000);
	}

	@Test
	public void everyAnimationPicksTheSameTool()
	{
		List<Set<Integer>> worns = Arrays.asList(null, new HashSet<>(),
			new HashSet<>(Arrays.asList(1359, 1275, 23864, 22842)), new HashSet<>(Arrays.asList(30352, 11721)));
		for (int animation = -1; animation <= 12_000; animation++)
		{
			assertEquals(oldFarmingWork(animation), Borrow.farmingWork(animation));
			assertEquals(oldFarmingTool(animation), Borrow.farmingTool(animation));
			for (String activity : ACTIVITIES)
			{
				for (Set<Integer> worn : worns)
				{
					assertEquals(activity + "/" + animation, oldToolFor(activity, animation, worn),
						Borrow.toolFor(activity, animation, worn));
				}
			}
		}
	}
}

package com.follower;

import java.io.IOException;
import net.runelite.api.ChatMessageType;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The skilling company's rules: the four pieces of it that are pure rules
 * in the shipped file rather than code. The head shake at a run of burnt
 * food and the nod at a batch of bows are gated on the session, so the
 * company's switch governs them; the two mirrors sit in the mimic group,
 * so the mimicry switch does.
 */
public class SkillingRulesTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static TriggerEvent burn()
	{
		return TriggerEvent.chat("You accidentally burn the shrimps.",
			ChatMessageType.GAMEMESSAGE.getType(), "");
	}

	@Test
	public void everyThirdBurnWhileCookingIsAShakeOfTheHead() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		for (int i = 0; i < 6; i++)
		{
			h.dispatch(burn());
		}
		assertTrue("no session, no head shake", h.firedBy("burnt").isEmpty());

		h.engine.getContext().setWork(true, "cooking", "Fire", null, 10, 0, Integer.MAX_VALUE);
		h.gameTicks(1);
		h.dispatch(burn());
		h.dispatch(burn());
		assertTrue("two burns is not a run", h.firedBy("burnt").isEmpty());
		h.dispatch(burn());
		assertEquals("the third", 1, h.firedBy("burnt").size());
		assertEquals("EMOTE_NO, and no words", 856, h.firedBy("burnt").get(0).animationId);
		assertEquals("", h.firedBy("burnt").get(0).text);
	}

	@Test
	public void everyFifthBowWhileFletchingIsANod() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().setWork(true, "fletching", "", null, 10, 0, Integer.MAX_VALUE);
		h.gameTicks(1);
		for (int i = 0; i < 4; i++)
		{
			h.dispatch(TriggerEvent.animation(1248));
		}
		assertTrue("four is not a batch", h.firedBy("counting-batches").isEmpty());
		h.dispatch(TriggerEvent.animation(1248));
		assertEquals(1, h.firedBy("counting-batches").size());
		assertEquals(855, h.firedBy("counting-batches").get(0).animationId);
		assertEquals("a reaction, not a mirror: the Mimicry toggle must not govern it",
			"reactions", h.rule("counting-batches").group);

		Harness idle = new Harness(folder.newFolder().toPath());
		idle.gameTicks(1);
		for (int i = 0; i < 10; i++)
		{
			idle.dispatch(TriggerEvent.animation(1248));
		}
		assertTrue("no session, no count", idle.firedBy("counting-batches").isEmpty());
	}

	@Test
	public void theTwoMirrorsAreMimicRulesOnTheRightAnimations() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		SpeechRule bury = h.rule("bury-along");
		assertEquals("mimic", bury.group);
		assertEquals(Boolean.TRUE, bury.mirrorAnimation);
		assertTrue(bury.when.conditions.get(0).ids.contains(827));

		SpeechRule casting = h.rule("casting-along");
		assertEquals("mimic", casting.group);
		assertEquals(Boolean.TRUE, casting.mirrorAnimation);
		assertEquals("a minute between", 60000L, casting.cooldownMs);
		for (int id : new int[]{712, 713, 719, 720, 721, 725, 726})
		{
			assertTrue("cast " + id, casting.when.conditions.get(0).ids.contains(id));
		}
		assertEquals(Integer.valueOf(5), casting.when.conditions.get(1).percent);
	}
}

package com.follower;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The skilling company, driven tick by tick with nothing running: a click
 * that becomes a session once the work is proven, a seat off the flank six
 * ticks in, the tool borrowed, and every way the session lets go again.
 *
 * <p>Most of what matters here is refusal and release. A seat on the line to
 * the tree, on the tree, or on the next tree is worse than no seat; a seat
 * held after the player has walked off is a stuck follower; a tool held after
 * a fight starts is a follower swinging an axe at a goblin.
 */
public class SkillingSessionTest
{
	/** Records what the follower was asked to do; does none of it. */
	private static final class RecordingFollower extends FollowerEntity
	{
		boolean spawned = true;
		WorldPoint stayingAt;
		WorldPoint facing;
		boolean following = true;
		int stayAttempts;
		int poseOverride;
		final List<Integer> animations = new ArrayList<>();

		/** Every tile it was sent to, in order, and every glance. */
		final List<WorldPoint> stays = new ArrayList<>();
		final List<WorldPoint> glances = new ArrayList<>();

		/** Tiles the ground refuses; null means everywhere is standable. */
		java.util.function.Predicate<WorldPoint> walled;

		/** Asked for one tile, closest approach stops on another: these. */
		final java.util.Map<WorldPoint, WorldPoint> shortOf = new java.util.HashMap<>();

		/** False while it is still coming round to face where it was told. */
		boolean turned = true;

		/** Tiles with a fence along the edge toward the work. */
		final java.util.Set<WorldPoint> fenced = new java.util.HashSet<>();

		/**
		 * Rock, as the real pathing sees it: not ground to stand on, and yet
		 * a walk to it "arrives" - closest approach stops beside it, on
		 * {@link #shortOf}, and reports success. Unlike {@link #walled}.
		 */
		final java.util.Set<WorldPoint> solid = new java.util.HashSet<>();

		@Override
		boolean walledToward(WorldPoint at, int dx, int dy)
		{
			return fenced.contains(at);
		}

		/** The far corner of a footprint it was told to face the middle of, or null. */
		WorldPoint facingMax;

		/**
		 * Tiles with a lit fire on them. Walkable by the map and refused by
		 * the follower, which is what a fire actually is - so these are NOT
		 * walls, and a test that makes one a wall is testing something else.
		 */
		final java.util.Set<WorldPoint> fires = new java.util.HashSet<>();

		RecordingFollower()
		{
			super(null, null);
			// Wired as FollowerPlugin wires the real one.
			setHotGround(fires::contains);
		}

		@Override
		public boolean isSpawned()
		{
			return spawned;
		}

		/** False while the follower is taken to be still catching up. */
		boolean settled = true;

		@Override
		public boolean isSettled()
		{
			return settled;
		}

		@Override
		public boolean isStaying()
		{
			return stayingAt != null;
		}

		@Override
		public WorldPoint getWorldLocation()
		{
			return stayingAt != null ? stayingAt : new WorldPoint(49, 49, 0);
		}

		@Override
		boolean standable(WorldPoint at)
		{
			return at != null && (walled == null || !walled.test(at)) && !solid.contains(at);
		}

		@Override
		public boolean stayAt(WorldPoint target)
		{
			stayAttempts++;
			if (target == null || (walled != null && walled.test(target)))
			{
				return false;
			}
			stayingAt = shortOf.getOrDefault(target, target);
			following = false;
			stays.add(target);
			return true;
		}

		@Override
		public WorldPoint getStayTile()
		{
			return stayingAt;
		}

		@Override
		public boolean arrivesAt(WorldPoint target)
		{
			return target != null && (walled == null || !walled.test(target))
				&& !shortOf.containsKey(target);
		}

		@Override
		public int stepsTo(WorldPoint target)
		{
			return arrivesAt(target) ? getWorldLocation().distanceTo(target) : -1;
		}

		@Override
		public void clearPoseOverride(int id)
		{
			if (poseOverride == id)
			{
				poseOverride = 0;
			}
		}

		@Override
		public int getPoseOverride()
		{
			return poseOverride;
		}

		@Override
		public boolean isTurned()
		{
			return turned;
		}

		@Override
		public void stayHere()
		{
			stayingAt = getWorldLocation();
			following = false;
		}

		@Override
		public void resumeFollowing()
		{
			stayingAt = null;
			facing = null;
			following = true;
		}

		@Override
		public void setStayFaceTile(WorldPoint tile)
		{
			facing = tile;
			facingMax = null;
		}

		@Override
		public void setStayFaceArea(WorldPoint min, WorldPoint max)
		{
			facing = min;
			facingMax = max;
		}

		@Override
		public void playAnimation(int id)
		{
			animations.add(id);
		}

		@Override
		public void playAnimations(int[] ids)
		{
			for (int id : ids)
			{
				animations.add(id);
			}
		}

		@Override
		public void setPoseOverride(int id)
		{
			poseOverride = id;
		}

		@Override
		public void glanceAt(WorldPoint at, int ms)
		{
			glances.add(at);
		}

		/** Whether it was ever called to the front of the player; the stay goes with it. */
		boolean movedToFront;

		@Override
		public boolean moveToFront(net.runelite.api.Player local)
		{
			movedToFront = true;
			stayingAt = null;
			return true;
		}
	}

