		WorldPoint seat = follower.stayingAt;
		assertNotNull("standing off the trap", seat);
		assertEquals(SkillingController.TRAP_WATCH_TILES, seat.distanceTo(PLAYER));
		assertEquals("facing it", PLAYER, follower.facing);
