	@Test
	public void aMomentaryWobbleDoesNotEndTheSpell()
	{
		fight("Zulrah", 725);
		tick(6);
		int poseWhileChannelling = follower.poseOverride;
		assertTrue(poseWhileChannelling != 0);

		follower.settled = false;
		tick(1);
		follower.settled = true;
		tick(2);

		assertTrue("one unsettled tick should not have dropped the ward",
			follower.poseOverride != 0);
	}

	@Test
	public void theWardIsRenewedSoItDoesNotBlinkOut()
	{
		fight("Zulrah", 725);
		tick(3);
		int afterSummon = follower.spotAnims.size();

		tick(12);

		assertTrue("the channelled effect should be renewed as it fades,"
				+ " not left to lapse",
			follower.spotAnims.size() >= afterSummon);
	}

	@Test
	public void switchingItOffMidFightPutsEverythingBack()
	{
		FollowerConfig off = new FollowerConfig()
		{
			@Override
			public boolean spectateCombat()
			{
				return false;
			}
		};
		SpectateController disabled = new SpectateController(game.client, follower,
			off, () -> context, new SpotAnimRepository(new Gson()), spoken::add, disarms::add);

		fight("Zulrah", 725);
		for (int i = 0; i < 10; i++)
		{
			game.tick(++tick);
			context.refresh();
			follower.advance();
			disabled.tick(false, false);
		}

		assertFalse("the setting is off", disabled.isSpectating());
		assertTrue("nothing should have been taken away", disarms.isEmpty());
	}

	@Test
	public void aLongFightDoesNotAccumulateAnything()
	{
		fight("Zulrah", 725);
		tick(400);

		assertTrue("still spectating a fight that is still going",
			spectate.isSpectating());
		// One summon, and no repeats of it: the chain is raised once.
		assertTrue("the ward was raised " + follower.chains.size() + " times over"
				+ " one fight", follower.chains.size() <= 2);
	}
}

package com.follower;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The small pieces that show up in what the follower actually says: where a
 * line is sent, and how an amount of gold is written.
 */
public class SpeechDetailsTest
{
	// ----------------------------------------------------------------- output

	@Test
	public void outputModesParseHoweverTheyAreWritten()
	{
		assertEquals(SpeechOutput.OVERHEAD, SpeechOutput.parse("overhead", SpeechOutput.BOTH));
		assertEquals(SpeechOutput.OVERHEAD, SpeechOutput.parse("OVERHEAD", SpeechOutput.BOTH));
		assertEquals(SpeechOutput.CHATBOX, SpeechOutput.parse("  ChatBox  ", SpeechOutput.BOTH));
		assertEquals(SpeechOutput.BOTH, SpeechOutput.parse("both", SpeechOutput.OVERHEAD));
	}

	@Test
	public void anUnknownOutputFallsBackRatherThanFailing()
	{
		assertEquals(SpeechOutput.BOTH, SpeechOutput.parse(null, SpeechOutput.BOTH));
		assertEquals(SpeechOutput.BOTH, SpeechOutput.parse("", SpeechOutput.BOTH));
		assertEquals(SpeechOutput.BOTH, SpeechOutput.parse("shouting", SpeechOutput.BOTH));
	}

	@Test
	public void eachModeGoesWhereItsNameSays()
	{
		assertTrue(SpeechOutput.OVERHEAD.showsOverhead());
		assertFalse(SpeechOutput.OVERHEAD.showsChatbox());

		assertFalse(SpeechOutput.CHATBOX.showsOverhead());
		assertTrue(SpeechOutput.CHATBOX.showsChatbox());

		assertTrue(SpeechOutput.BOTH.showsOverhead());
		assertTrue(SpeechOutput.BOTH.showsChatbox());
	}

	// ------------------------------------------------------------------- gold

	/** The {value} placeholder in a loot line, written the way a player says it. */
	private static String gp(int amount)
	{
		return TriggerEvent.loot(amount, "thing").getPlaceholders().get("value");
	}

	@Test
	public void goldIsWrittenTheWayAPlayerSaysIt()
	{
		assertEquals("0", gp(0));
		assertEquals("950", gp(950));
		assertEquals("9999", gp(9999));
		assertEquals("10K", gp(10_000));
		assertEquals("214K", gp(214_500));
		assertEquals("999K", gp(999_999));
		assertEquals("1M", gp(1_000_000));
		assertEquals("1.2M", gp(1_234_567));
		assertEquals("2.4M", gp(2_350_000));
		assertEquals("10M", gp(10_000_000));
		assertEquals("999.9M", gp(999_900_000));
	}

	@Test
	public void aHugeDropDoesNotOverflowIntoNonsense()
	{
		// QA, 15 Oct: "1500.0M! I'd better count the noughts again."
		assertEquals("1B", gp(999_960_000));
		assertEquals("1.5B", gp(1_500_000_000));
		assertEquals("2.1B", gp(Integer.MAX_VALUE));
	}

	@Test
	public void aLootEventCarriesTheItemAndTheAmount()
	{
		TriggerEvent event = TriggerEvent.loot(1_500_000, "Twisted bow");
		assertEquals("Twisted bow", event.getPlaceholders().get("item"));
		assertEquals("1.5M", event.getPlaceholders().get("value"));
		assertEquals("the raw value is what lootWorth compares against",
			1_500_000, event.getValue());
	}

	@Test
	public void aLootEventWithNoNamedItemIsStillUsable()
	{
		TriggerEvent event = TriggerEvent.loot(100, null);
		assertEquals("", event.getPlaceholders().get("item"));
	}

	// ------------------------------------------------------------- kill event

	@Test
	public void aKillCarriesEverythingAKillLineCouldWant()
	{
		TriggerEvent event = TriggerEvent.kill(2042, "Zulrah", 725);
		assertEquals("Zulrah", event.getPlaceholders().get("npc"));
		assertEquals("2042", event.getPlaceholders().get("npcId"));
		assertEquals("725", event.getPlaceholders().get("level"));
		assertEquals("the combat level is what npcKill brackets on",
			725, event.getValue());
	}

	@Test
	public void aKillWithNoNameDoesNotCarryANull()
	{
		TriggerEvent event = TriggerEvent.kill(1, null, 3);
		assertEquals("", event.getPlaceholders().get("npc"));
	}

	// --------------------------------------------------------------- phrases

	@Test
	public void aSinglePhraseRuleAlwaysSaysIt()
	{
		SpeechRule rule = new SpeechRule();
		rule.say = java.util.Collections.singletonList("only line");
		for (int i = 0; i < 20; i++)
		{
			assertEquals("only line", rule.pickPhrase(java.util.Collections.<String>emptySet()));
		}
	}

	@Test
	public void aRuleWithNoLinesSaysNothingRatherThanFailing()
	{
		assertEquals("", new SpeechRule().pickPhrase(java.util.Collections.<String>emptySet()));

		SpeechRule empty = new SpeechRule();
		empty.say = new java.util.ArrayList<>();
		assertEquals("", empty.pickPhrase(java.util.Collections.<String>emptySet()));
	}

	@Test
	public void aPhraseIsNeverRepeatedBackToBack()
	{
		SpeechRule rule = new SpeechRule();
		rule.say = java.util.Arrays.asList("a", "b", "c");

		String previous = null;
		for (int i = 0; i < 500; i++)
		{
			String picked = rule.pickPhrase(java.util.Collections.<String>emptySet());
			assertFalse("said '" + picked + "' twice in a row", picked.equals(previous));
			previous = picked;
		}
	}

	@Test
	public void twoPhrasesAlternateRatherThanHanging()
	{
		// The no-repeat draw loops until it gets a different index; with only
		// two lines that leaves exactly one choice each time. The liveness half
		// of this is that it returns at all - a draw that could not satisfy
		// itself would spin forever on the game thread.
		//
		// The name also claims they ALTERNATE, which nothing here checked: the
		// case passed just as well against a draw that returned "a" a hundred
		// times. Now it says both.
		SpeechRule rule = new SpeechRule();
		rule.say = java.util.Arrays.asList("a", "b");

		String previous = null;
		java.util.Set<String> seen = new java.util.HashSet<>();
		for (int i = 0; i < 100; i++)
		{
			String picked = rule.pickPhrase(java.util.Collections.<String>emptySet());
			seen.add(picked);
			if (previous != null)
			{
				assertNotEquals("with two lines every draw has to swap", previous, picked);
			}
			previous = picked;
		}
		assertEquals("both lines have to come up", 2, seen.size());
	}
}

package com.follower;

import java.io.IOException;
import java.util.HashSet;
import java.util.Set;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * How much the follower says across a stretch of time, as opposed to how close
 * together two lines may fall.
 *
 * <p>The gap was always a floor and never a budget: at three seconds apart, a
 * follower with plenty to react to talks for as long as things keep happening,
 * and every line lands in the same flat stream as the one before. The director
 * makes it possible for the follower to have said enough for now.
 *
 * <p>Everything here takes the clock as an argument rather than reading it, so
 * these tests walk minutes without spending any.
 */
public class SpeechDirectorTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final long GAP = 3_000L;

	private static SpeechDirector paced()
	{
		SpeechDirector director = new SpeechDirector();
		director.setBaseGapMs(GAP);
		return director;
	}

	private static SpeechRule ordinary()
	{
		SpeechRule rule = new SpeechRule();
		rule.id = "ordinary";
		rule.group = "reactions";
		return rule;
	}

	private static SpeechRule occasion()
	{
		SpeechRule rule = ordinary();
		rule.id = "occasion";
		rule.occasion = Boolean.TRUE;
		return rule;
	}

	private static SpeechRule lore()
	{
		SpeechRule rule = ordinary();
		rule.id = "lore";
		rule.group = "area";
		return rule;
	}

	// -------------------------------------------------------------- the peak

	@Test
	public void aBurstBuysSomeQuiet()
	{
		SpeechDirector director = paced();
		long now = 10_000L;

		director.noteSpoke(ordinary(), now);
		assertNull("one line is not a burst", director.blocks(ordinary(), now));
		director.noteSpoke(ordinary(), now += GAP);
		assertNull("two is still a conversation", director.blocks(ordinary(), now));

		director.noteSpoke(ordinary(), now += GAP);
		assertEquals("three in ten seconds is enough for now",
			"relax", director.blocks(ordinary(), now));
	}

	@Test
	public void theQuietEndsOnItsOwn()
	{
		SpeechDirector director = paced();
		long now = 10_000L;
		for (int i = 0; i < 3; i++)
		{
			director.noteSpoke(ordinary(), now += GAP);
		}
		assertTrue(director.isRelaxing(now));

		// The longest a peak can buy, and a second past it.
		assertNull("the follower does not sulk forever",
			director.blocks(ordinary(), now + 46_000L));
	}

	@Test
	public void theQuietIsNeverTheSameLengthTwice()
	{
		// A constant is a metronome. A player who notices the follower goes
		// quiet for exactly thirty seconds has found the machinery, and hears a
		// timer from then on rather than someone choosing not to speak.
		Set<Long> lengths = new HashSet<>();
		for (int attempt = 0; attempt < 200; attempt++)
		{
			SpeechDirector director = paced();
			long now = 10_000L;
			for (int i = 0; i < 3; i++)
			{
				director.noteSpoke(ordinary(), now += GAP);
			}
			long remaining = director.relaxRemainingMs(now);
			assertTrue("a peak bought " + remaining + "ms, which is outside the range",
				remaining >= 30_000L && remaining <= 45_000L);
			lengths.add(remaining);
		}
		assertTrue("every peak bought exactly the same silence", lengths.size() > 1);
	}

	@Test
	public void talkingSlowlyNeverPeaks()
	{
		// The whole point of a decay: a follower saying one thing every couple
		// of minutes is not bursting, however long you leave it running.
		SpeechDirector director = paced();
		long now = 10_000L;
		for (int i = 0; i < 50; i++)
		{
			now += 120_000L;
			director.noteSpoke(ordinary(), now);
			assertNull("a line every two minutes should never trip the peak",
				director.blocks(ordinary(), now));
		}
	}

	@Test
	public void theDecayScalesWithTheChattinessSetting()
	{
		// Expressed in gaps rather than seconds, so a player who asked for quiet
		// is not then told to be quieter. Three lines at one gap apart burst at
		// any setting; three lines spread over five gaps burst at none.
		for (long gap : new long[]{1_500L, 3_000L, 6_000L, 12_000L})
		{
			SpeechDirector tight = new SpeechDirector();
			tight.setBaseGapMs(gap);
			SpeechDirector loose = new SpeechDirector();
			loose.setBaseGapMs(gap);

			long now = 10_000L;
			for (int i = 0; i < 3; i++)
			{
				tight.noteSpoke(ordinary(), now + i * gap);
				loose.noteSpoke(ordinary(), now + i * gap * 6);
			}
			assertNotNull("gap " + gap + ": back to back should peak",
				tight.blocks(ordinary(), now + 3 * gap));
			assertNull("gap " + gap + ": well spread should not",
				loose.blocks(ordinary(), now + 18 * gap));
		}
	}

	// ----------------------------------------------------------- the occasion

	@Test
	public void anOccasionIsWhatTheQuietWasFor()
	{
		SpeechDirector director = paced();
		long now = 10_000L;
		for (int i = 0; i < 3; i++)
		{
			director.noteSpoke(ordinary(), now += GAP);
		}

		assertEquals("relax", director.blocks(ordinary(), now));
		assertNull("an occasion is exactly what the follower stopped talking for",
			director.blocks(occasion(), now));
	}

	@Test
	public void anOccasionCostsNothing()
	{
		// Letting the one line worth saying build towards the next silence
		// would have the follower punish itself for saying it.
		SpeechDirector director = paced();
		long now = 10_000L;
		for (int i = 0; i < 10; i++)
		{
			director.noteSpoke(occasion(), now += GAP);
		}
		assertFalse("occasions should not spend the budget", director.isRelaxing(now));
		assertEquals(0.0, director.getIntensity(), 0.0001);
	}

	// ---------------------------------------------------------- settling in

	@Test
	public void aNewFollowerThinsOutTheScenery()
	{
		SpeechDirector director = paced();
		director.setSessionCount(1);
		assertTrue(director.isSettlingIn());

		long now = 10_000L;
		director.noteSpoke(lore(), now);

		assertEquals("a second area line straight after the first",
			"settling", director.blocks(lore(), now + GAP));
		assertNull("but the follower can still react to what just happened",
			director.blocks(ordinary(), now + GAP));
		assertNull("and the scenery comes back round soon enough",
			director.blocks(lore(), now + GAP * 4));
	}

	@Test
	public void anOccasionIsExemptFromTheSettlingDamperToo()
	{
		// The bug this exists for. The relax check exempted occasions and the
		// settling check did not, which handed the damper the power to swallow
		// enter-wilderness - group "area", so it counts as scenery, and an
		// occasion precisely because it must reach a player who has never seen
		// the place. A follower is only settling in because the player is new,
		// so the two conditions peak at exactly the same moment.
		SpeechDirector director = paced();
		director.setSessionCount(1);

		SpeechRule warning = lore();
		warning.id = "enter-wilderness";
		warning.occasion = Boolean.TRUE;

		long now = 10_000L;
		director.noteSpoke(lore(), now);

		assertEquals("ordinary scenery is thinned, as intended",
			"settling", director.blocks(lore(), now + GAP));
		assertNull("but a warning is not scenery, whatever group it lives in",
			director.blocks(warning, now + GAP));
	}

	@Test
	public void aFollowerThatKnowsYouTalksAboutTheSceneryFreely()
	{
		SpeechDirector director = paced();
		director.setSessionCount(3);
		assertFalse(director.isSettlingIn());

		long now = 10_000L;
		director.noteSpoke(lore(), now);
		assertNull("past the first couple of sessions the damper is gone",
			director.blocks(lore(), now + 1L));
	}

	@Test
	public void anUnansweredSessionCountIsNotEvidenceOfAnything()
	{
		// Zero means nobody has said. Defaulting the other way would have every
		// fresh engine start out quiet about the scenery until something got
		// round to correcting it - including, at one point, the test harness.
		SpeechDirector director = paced();
		assertFalse(director.isSettlingIn());
		director.noteSpoke(lore(), 10_000L);
		assertNull(director.blocks(lore(), 10_001L));
	}

	@Test
	public void noGapMeansNoPacingAtAll()
	{
		// Falls out of the model rather than being bolted on: every window here
		// is a multiple of the gap, so a gap of nothing makes all of them
		// nothing. The chattiness setting has no such level; the harness does.
		SpeechDirector director = new SpeechDirector();
		director.setBaseGapMs(0L);
		director.setSessionCount(1);
		assertFalse(director.isPacing());

		for (int i = 0; i < 20; i++)
		{
			director.noteSpoke(ordinary(), 10_000L);
			director.noteSpoke(lore(), 10_000L);
		}
		assertNull(director.blocks(ordinary(), 10_000L));
		assertNull(director.blocks(lore(), 10_000L));
	}

	// ------------------------------------------------------- through the engine

	@Test
	public void theEngineHonoursTheDirectorAndSaysSo() throws IOException
	{
		// The peak arithmetic is settled above, on a clock this test can move.
		// What is worth checking here is the wiring: that the reason reaches
		// the transcript, that ordinary chatter is held, and that an occasion
		// is not.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"chatter\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"again\"]},"
				+ "{\"id\": \"big\", \"group\": \"t\", \"cooldownMs\": 0, \"occasion\": true,"
				+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"that mattered\"]}]}");
		h.engine.setGlobalCooldownMs(GAP);

		java.util.List<String> reasons = new java.util.ArrayList<>();
		h.engine.setOnSuppressed((rule, why) -> reasons.add(rule.id + ":" + why));

		long now = System.currentTimeMillis();
		for (int i = 0; i < 3; i++)
		{
			h.engine.getDirector().noteSpoke(ordinary(), now);
		}
		assertTrue("the burst should have bought some quiet",
			h.engine.getDirector().isRelaxing(now));

		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertTrue("ordinary chatter is held, and the transcript is told why",
			reasons.contains("chatter:relax"));
		assertTrue("and it stayed held", h.firedBy("chatter").isEmpty());

		h.dispatch(TriggerEvent.death());
		assertEquals("the occasion is what the quiet was being kept for",
			1, h.firedBy("big").size());
	}
}

package com.follower;

import java.io.IOException;
import java.nio.file.Path;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Drives the speech engine against a game that is not running, to check the
 * behaviours the rule format promises: rising edges, cooldowns, priority,
 * delays, and the throttles that apply to speech but not to animation.
 */
public class SpeechEngineSimulationTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private Path scratch() throws IOException
	{
		return folder.newFolder().toPath();
	}

	private static String rules(String... bodies)
	{
		return "{\"version\": 1, \"rules\": [" + String.join(",", bodies) + "]}";
	}

	// ------------------------------------------------------------ rising edge

	@Test
	public void aConditionThatStaysTrueFiresOnceNotEveryTick() throws IOException
	{
		Harness h = new Harness(scratch(), rules(
			"{\"id\": \"hurt\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"healthBelow\", \"percent\": 50},"
				+ " \"say\": [\"ouch\"]}"));

		h.game.hitpoints(10, 99);
		h.gameTicks(5);

		assertEquals("low health is one crossing, not five ticks of it",
			1, h.firedBy("hurt").size());
	}

	@Test
	public void theConditionGoingFalseRearmsIt() throws IOException
	{
		Harness h = new Harness(scratch(), rules(
			"{\"id\": \"hurt\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"healthBelow\", \"percent\": 50},"
				+ " \"say\": [\"ouch\"]}"));

		h.game.hitpoints(10, 99);
		h.gameTicks(2);
		h.game.hitpoints(99, 99);
		h.gameTicks(2);
		h.game.hitpoints(10, 99);
		h.gameTicks(2);

		assertEquals("healing and dropping again is a second crossing",
			2, h.firedBy("hurt").size());
	}

	// --------------------------------------------------------------- cooldown

	@Test
	public void aRuleWillNotRefireInsideItsOwnCooldown() throws IOException
	{
		Harness h = new Harness(scratch(), rules(
			"{\"id\": \"hurt\", \"group\": \"t\", \"cooldownMs\": 600000,"
				+ " \"when\": {\"type\": \"healthBelow\", \"percent\": 50},"
				+ " \"say\": [\"ouch\"]}"));

		for (int i = 0; i < 4; i++)
		{
			h.game.hitpoints(10, 99);
			h.gameTicks(2);
			h.game.hitpoints(99, 99);
			h.gameTicks(2);
		}

		assertEquals("four crossings inside a ten minute cooldown is still one line",
			1, h.firedBy("hurt").size());
	}

	// --------------------------------------------------------------- priority

	@Test
	public void theHighestPriorityRuleWinsWhenSeveralMatchAtOnce() throws IOException
	{
		Harness h = new Harness(scratch(), rules(
			"{\"id\": \"quiet\", \"group\": \"t\", \"priority\": 10, \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"healthBelow\", \"percent\": 50}, \"say\": [\"a\"]}",
			"{\"id\": \"loud\", \"group\": \"t\", \"priority\": 90, \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"healthBelow\", \"percent\": 50}, \"say\": [\"b\"]}"));

		h.game.hitpoints(10, 99);
		h.gameTicks(2);

		assertEquals(1, h.spoken.size());
		assertEquals("loud", h.spoken.get(0).rule.id);
	}

	@Test
	public void theLoserStillTracksItsEdgeAndDoesNotFireLater() throws IOException
	{
		Harness h = new Harness(scratch(), rules(
			"{\"id\": \"quiet\", \"group\": \"t\", \"priority\": 10, \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"healthBelow\", \"percent\": 50}, \"say\": [\"a\"]}",
			"{\"id\": \"loud\", \"group\": \"t\", \"priority\": 90, \"cooldownMs\": 600000,"
				+ " \"when\": {\"type\": \"healthBelow\", \"percent\": 50}, \"say\": [\"b\"]}"));

		h.game.hitpoints(10, 99);
		h.gameTicks(5);

		assertTrue("the losing rule must not fire on the next tick from a stale edge",
			h.firedBy("quiet").isEmpty());
	}

	// ------------------------------------------------------------------ delay

	@Test
	public void aDelayedRuleSpeaksLaterAndOnlyOnce() throws IOException
	{
		Harness h = new Harness(scratch(), rules(
			"{\"id\": \"slow\", \"group\": \"t\", \"cooldownMs\": 600000, \"delayTicks\": 4,"
				+ " \"when\": {\"type\": \"healthBelow\", \"percent\": 50}, \"say\": [\"ouch\"]}"));

		h.game.hitpoints(10, 99);
		h.gameTicks(1);
		assertTrue("nothing on the tick it won", h.firedBy("slow").isEmpty());

		h.gameTicks(3);
		assertTrue("still nothing before the delay is up", h.firedBy("slow").isEmpty());

		h.gameTicks(1);
		assertEquals("speaks once the delay expires", 1, h.firedBy("slow").size());

		h.gameTicks(20);
		assertEquals("and only once", 1, h.firedBy("slow").size());
	}

	@Test
	public void aRangedDelayStaysInsideItsBoundsAcrossManyDraws() throws IOException
	{
		SpeechRule rule = new SpeechRule();
		rule.delayTicks = 2;
		rule.delayTicksMax = 6;

		boolean sawMin = false;
		boolean sawMax = false;
		for (int i = 0; i < 2000; i++)
		{
			int drawn = rule.rollDelayTicks();
			assertTrue("drew " + drawn + ", below the floor", drawn >= 2);
			assertTrue("drew " + drawn + ", above the ceiling", drawn <= 6);
			sawMin |= drawn == 2;
			sawMax |= drawn == 6;
		}
		assertTrue("both bounds should be reachable", sawMin && sawMax);
	}

