	{
		Harness h = new Harness(scratch(), rules(
			"{\"id\": \"slow\", \"group\": \"t\", \"cooldownMs\": 0, \"delayTicks\": 5,"
				+ " \"when\": {\"type\": \"healthBelow\", \"percent\": 50}, \"say\": [\"a\"]}"));

		h.game.hitpoints(10, 99);
		h.gameTicks(1);

		h.engine.reset();
		// Back to full health, or the rule simply wins again on its own merits
		// and the test proves nothing about the queue.
		h.game.hitpoints(99, 99);
		h.gameTicks(10);

		assertTrue("a line queued before a logout must not surface after it",
			h.firedBy("slow").isEmpty());
	}

	@Test
	public void aRuleThatThrowsIsDisabledRatherThanKillingTheDispatch() throws IOException
	{
		// A regex that cannot compile throws from inside matches().
		Harness h = new Harness(scratch(), rules(
			"{\"id\": \"broken\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"chatMessage\", \"regex\": \"[unclosed\"},"
				+ " \"say\": [\"a\"]}",
			"{\"id\": \"fine\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"healthBelow\", \"percent\": 50}, \"say\": [\"b\"]}"));

		h.gameTicks(1);
		h.dispatch(TriggerEvent.chat("anything", 0, ""));

		h.game.hitpoints(10, 99);
		h.gameTicks(2);

		assertEquals("one bad rule must not stop the rest of the set",
			1, h.firedBy("fine").size());
		assertFalse("and it should take itself out of service",
			h.rule("broken").isEnabled());
	}

	// ------------------------------------------- the two switches everything uses

	@Test
	public void theHighestPriorityRuleWinsAndTheRestStayQuiet() throws IOException
	{
		// Priority decides which of three hundred rules gets the moment, and
		// nothing checked that the engine honours it at all. Every rule-ordering
		// bug fixed this week - four of them - assumed a mechanism no test had
		// ever exercised.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"quiet\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"priority\": 10, \"when\": {\"type\": \"examined\"},"
				+ " \"say\": [\"the loser\"]},"
				+ "{\"id\": \"loud\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"priority\": 90, \"when\": {\"type\": \"examined\"},"
				+ " \"say\": [\"the winner\"]}]}");
		h.gameTicks(1);

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));

		assertFalse("the higher priority rule has to win", h.firedBy("loud").isEmpty());
		assertTrue("and only one rule may speak per event",
			h.firedBy("quiet").isEmpty());
	}

	@Test
	public void theLoserSpeaksOnceTheWinnerIsOnCooldown() throws IOException
	{
		// The other half: losing is not being disabled. A rule under a busy one
		// still gets the moments the winner cannot take, which is the whole
		// reason a cooldown and a priority are different things.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"quiet\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"priority\": 10, \"when\": {\"type\": \"examined\"},"
				+ " \"say\": [\"the loser\"]},"
				+ "{\"id\": \"loud\", \"group\": \"t\", \"cooldownMs\": 600000,"
				+ " \"priority\": 90, \"when\": {\"type\": \"examined\"},"
				+ " \"say\": [\"the winner\"]}]}");
		h.gameTicks(1);

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertFalse(h.firedBy("loud").isEmpty());

		// The edge has to fall and rise again, or nothing fires a second time.
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));

		assertFalse("with the winner on cooldown the next rule down gets its turn",
			h.firedBy("quiet").isEmpty());
	}

	@Test
	public void aDisabledGroupSaysNothing() throws IOException
	{
		// Every group toggle in the settings runs through this. If it stopped
		// working, every "off" switch in the panel would silently do nothing -
		// and nothing would have noticed.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"chatty\", \"group\": \"idle\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"hello\"]}]}");
		h.gameTicks(1);

		h.engine.setDisabledGroups(
			new java.util.HashSet<>(java.util.Collections.singletonList("idle")));
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertTrue("a switched-off group must not speak", h.firedBy("chatty").isEmpty());

		h.gameTicks(1);
		h.engine.setDisabledGroups(java.util.Collections.emptySet());
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertFalse("and must come back when switched on again",
			h.firedBy("chatty").isEmpty());
	}

	@Test
	public void asingleRuleCanBeSilencedByIdWithoutItsWholeGroup() throws IOException
	{
		// The disabled set matches rule ids too, which is how one line is muted
		// without losing the twenty others in its group.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"one\", \"group\": \"idle\", \"cooldownMs\": 0,"
				+ " \"priority\": 50, \"when\": {\"type\": \"examined\"},"
				+ " \"say\": [\"first\"]},"
				+ "{\"id\": \"two\", \"group\": \"idle\", \"cooldownMs\": 0,"
				+ " \"priority\": 40, \"when\": {\"type\": \"examined\"},"
				+ " \"say\": [\"second\"]}]}");
		h.gameTicks(1);

		h.engine.setDisabledGroups(
			new java.util.HashSet<>(java.util.Collections.singletonList("one")));
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));

		assertTrue("the silenced rule stays silent", h.firedBy("one").isEmpty());
		assertFalse("its group-mate carries on", h.firedBy("two").isEmpty());
	}

	/**
	 * A line of the follower's own that no rule wrote - the remark after a
	 * sketch - went straight to the overhead, past the mute and the output
	 * setting.
	 */
	@Test
	public void aLineNoRuleWroteKeepsTheMuteAndGoesWhereSpeechGoes() throws IOException
	{
		Harness h = new Harness(scratch(), "{\"version\": 1, \"rules\": []}");
		h.engine.setDefaultOutput(SpeechOutput.CHATBOX);
		h.engine.remark("Sketched. The light did most of the work.");
		assertEquals(1, h.spoken.size());
		assertEquals("where the settings put speech", SpeechOutput.CHATBOX, h.spoken.get(0).output);

		h.spoken.clear();
		h.engine.setMuted(true);
		h.engine.remark("Sketched. The light did most of the work.");
		assertTrue("and not at all under the mute", h.spoken.isEmpty());
	}

	@Test
	public void aChatMessageBeforeTheGameLoadsDisablesNothing() throws IOException
	{
		// At client start a plugin's chat message is dispatched before the
		// game has loaded its varbits. A condition that throws then is
		// disabled for the whole session - the Wilderness rules were.
		Harness h = new Harness(scratch());
		h.game.starting();
		h.dispatch(TriggerEvent.chat("Plugin started.",
			net.runelite.api.ChatMessageType.GAMEMESSAGE.getType(), ""));

		assertTrue(h.rule("enter-wilderness").isEnabled());
		for (SpeechRule rule : h.loader.getRules())
		{
			assertTrue("rule '" + rule.id + "' was disabled at client start", rule.isEnabled());
		}
	}
}

package com.follower;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;

/**
 * The queue has to outlast the line it is queued behind.
 *
 * <p>Two constants that had nothing to do with each other were made to collide
 * by the reading-time change. A line may hold the overhead for up to
 * MAX_SPEECH_MS plus a breath; a queued line is discarded once it has waited
 * SPEECH_STALE_MS. Both were twelve seconds, which meant a line queued behind a
 * maximum-length one aged out fractionally before the floor it was waiting for
 * ever freed - so it was never spoken at all.
 *
 * <p>That was reachable from the settings panel alone. The minimum display time
 * went up to fifteen seconds, reading time clamps to twelve, and every line
 * therefore held the floor for the full twelve: with the minimum turned up, the
 * speech queue stopped delivering anything, ever. Two rules firing at once is
 * the entire case the queue exists for.
 *
 * <p>Read by reflection rather than by making the constants visible. They are
 * private implementation detail and the relationship between them is the only
 * thing worth asserting from outside.
 */
public class SpeechQueueTimingTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static long constant(String name) throws Exception
	{
		Field field = FollowerPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		return ((Number) field.get(null)).longValue();
	}

	@Test
	public void aQueuedLineOutlastsTheLongestPossibleLineInFrontOfIt() throws Exception
	{
		long longestHold = constant("MAX_SPEECH_MS") + constant("SPEECH_GAP_MS");
		long stale = constant("SPEECH_STALE_MS");

		assertTrue("a line may hold the overhead for " + longestHold + "ms but the"
			+ " queue throws work away after " + stale + "ms, so anything queued"
			+ " behind the longest line is dropped before it can ever be said",
			stale > longestHold);
	}

	@Test
	public void aGuardWaitsAsLongAsALineCanStillLand() throws Exception
	{
		// A rule reading a state a queued line will set waits for that line,
		// and stops waiting once the line is too old to land. Shorter than the
		// queue's own wait, a line could land after the guard let go, and the
		// dare would open over the advice after all.
		Field field = SpeechEngine.class.getDeclaredField("LONGEST_WAIT_MS");
		field.setAccessible(true);
		long waited = ((Number) field.get(null)).longValue();
		long stale = constant("SPEECH_STALE_MS");

		assertTrue("the engine stops waiting on a line after " + waited + "ms, but the"
			+ " queue can still say it at " + stale + "ms", waited > stale);
	}

	@Test
	public void aFirstWaitingInTheQueueCannotBeHandedOverAgain() throws Exception
	{
		// A first is spent when it lands, not when the engine hands it over,
		// so a copy still waiting in the queue has not spent it yet. Only the
		// rule's cooldown stops it winning a second time meanwhile, so the
		// cooldown has to outlast the longest a line can wait.
		long stale = constant("SPEECH_STALE_MS");
		Harness h = new Harness(folder.newFolder().toPath());
		List<String> problems = new ArrayList<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			if (rule.isOnce() && rule.cooldownMs <= stale)
			{
				problems.add(rule.id + " cools down in " + rule.cooldownMs + "ms");
			}
		}
		assertTrue("a first could be queued twice and said twice, since a queued"
			+ " line may wait " + stale + "ms: " + problems, problems.isEmpty());
		assertTrue("no firsts found at all - the scan broke, not the rules",
			h.loader.getRules().stream().anyMatch(SpeechRule::isOnce));
	}

	@Test
	public void theMinimumDisplayTimeCannotBeSetAboveTheMaximum() throws Exception
	{
		// The setting used to offer fifteen seconds while the code clamped at
		// twelve, so the top three seconds of the slider did nothing at all.
		net.runelite.client.config.Range range = FollowerConfig.class
			.getMethod("speechDurationMs")
			.getAnnotation(net.runelite.client.config.Range.class);

		assertTrue("the config has no range at all", range != null);
		assertTrue("the box offers " + range.max() + "ms but nothing is ever shown"
			+ " for longer than " + constant("MAX_SPEECH_MS") + "ms",
			range.max() <= constant("MAX_SPEECH_MS"));
	}
}

package com.follower;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

/**
 * A running bit starts at its opener. Text QA, 15 Oct: the openers rolled
 * the same small chance a tick as the stages after them, so about half of
 * players heard the fence book's middle before "I've started reading a
 * history of fences", and four in ten "Go easy on Gerald" before "Every mine
 * has a Gerald". The opener now has no roll: it is true on the first tick it
 * can be, and outranks the stages on that tick.
 */
public class SpeechRunningBitOrderTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** The shipped rules whose ids start with the prefix, and nothing else. */
	private static String shipped(String prefix) throws IOException
	{
		String all = new String(Files.readAllBytes(
			Paths.get("src/main/resources/com/follower/default-phrases.json")), StandardCharsets.UTF_8);
		JsonArray kept = new JsonArray();
		for (JsonElement rule : new JsonParser().parse(all).getAsJsonObject().getAsJsonArray("rules"))
		{
			if (rule.getAsJsonObject().get("id").getAsString().startsWith(prefix))
			{
				kept.add(rule);
			}
		}
		JsonObject file = new JsonObject();
		file.addProperty("version", 1);
		file.add("rules", kept);
		return file.toString();
	}

	@Test
	public void theFenceBookStartsAtTheStart() throws IOException
	{
		String rules = shipped("fun-fence-book-");
		for (int daysKnown : new int[]{5, 50})
		{
			for (int trial = 0; trial < 60; trial++)
			{
				Harness h = new Harness(folder.newFolder().toPath(), rules);
				h.engine.getContext().setMetOnDay(java.time.LocalDate.now().toEpochDay() - daysKnown);
				h.gameTicks(700);
				assertFalse("something said, day " + daysKnown, h.spoken.isEmpty());
				assertEquals("day " + daysKnown, "fun-fence-book-start", h.spoken.get(0).rule.id);
			}
		}
	}

	@Test
	public void geraldIsIntroducedFirst() throws IOException
	{
		String rules = shipped("fun-gerald-");
		for (int trial = 0; trial < 60; trial++)
		{
			Harness h = new Harness(folder.newFolder().toPath(), rules);
			h.engine.getContext().setMetOnDay(java.time.LocalDate.now().toEpochDay() - 5);
			h.engine.getContext().setWork(true, "mining", "Iron rocks", null, 0, 0, 0);
			h.gameTicks(400);
			assertFalse(h.spoken.isEmpty());
			assertEquals("fun-gerald-first", h.spoken.get(0).rule.id);
		}
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * How a weapon nobody has been seen holding gets an animation anyway.
 *
 * <p>This is the plugin's most consequential guesswork, and its failure mode is
 * silent: a wrong borrow gives a weapon somebody else's swing, which reads as a
 * bug in the follower rather than in a lookup table. The rules it follows were
 * measured, and each one is pinned here - including the refusals, which are the
 * half that stops the borrowing going too far.
 */
public class StanceInheritanceTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** A model repository that knows only the names this test gives it. */
	private static final class Names extends ModelRepository
	{
		private final Map<Integer, String> names = new HashMap<>();

		Names()
		{
			super(new Gson());
		}

		Names name(int id, String name)
		{
			names.put(id, name);
			return this;
		}

		@Override
		public String itemName(int itemId)
		{
			return names.get(itemId);
		}
	}

	private Names names;
	private StanceLibrary library;

	/**
	 * Two invented pose classes and an item id range the game does not use.
	 *
	 * <p>{@link StanceLibrary#load} always reads the SHIPPED library first, so
	 * a test naming a real weapon is really testing the stances that come
	 * with the plugin. Worse, real pose ids overlap the unarmed set, which
	 * would make "borrowed correctly" and "fell back to unarmed" look identical.
	 * Made-up numbers keep the question being asked an honest one.
	 */
	private static final int[] SCIMITAR = {900001, 900002, 900003};
	private static final int[] STAFF = {910001, 910002, 910003};

	/** Item ids well past anything the shipped library holds. */
	private static final int BASE = 800000;

	@Before
	public void setUp() throws IOException
	{
		names = new Names();
		library = new StanceLibrary(new Gson(), names);
		Path dir = folder.newFolder().toPath();
		library.load(dir);
	}

	private void observe(int itemId, String name, int[] poses, int attack)
	{
		names.name(itemId, name);
		library.setManual(itemId, poses[0], poses[1], poses[2], attack);
	}

	// --------------------------------------------------------- attack styles

	@Test
	public void theStyleTheWeaponWasSwungInWinsOverTheGenericSwing()
	{
		// Everyone in the scene teaches the generic swing; only the local
		// player can teach a styled one, because which style anyone else has
		// selected is not readable. So a weapon ends up with both, and the
		// styled slot is the better answer when there is one.
		observe(BASE + 40, "Dragon scimitar", SCIMITAR, 390);
		library.forWeapon(BASE + 40).attackByStyle = new int[]{0, 386, 0, 0};

		assertEquals("with no style asked for, the generic swing",
			390, library.attackFor(BASE + 40));
		assertEquals("the animation this weapon really uses in that style",
			386, library.attackFor(BASE + 40, 1, -1));
		assertEquals("a style it has never been swung in falls back",
			390, library.attackFor(BASE + 40, 2, -1));
	}

	@Test
	public void aStyleSlotIsNeverBorrowedFromAnotherWeapon()
	{
		// The generic swing borrows across a stance class; a styled one must
		// not. A style NUMBER means different things on different weapon
		// types, so another weapon's slot 1 is not this weapon's slot 1 - even
		// when the two are close enough to share a carry class and a swing.
		observe(BASE + 41, "Rune scimitar", SCIMITAR, 390);
		library.forWeapon(BASE + 41).attackByStyle = new int[]{0, 386, 0, 0};
		observe(BASE + 42, "Rune longsword", SCIMITAR, 390);

		assertEquals("it took the neighbour's styled animation",
			390, library.attackFor(BASE + 42, 1, -1));
	}

	// -------------------------------------------------------------- variants

	@Test
	public void aTrimmedWeaponInheritsFromThePlainOne()
	{
		observe(BASE + 1, "Abyssal whip", SCIMITAR, 1658);
		names.name(BASE + 2, "Abyssal whip (or)");

		StanceLibrary.Stance inherited = library.forWeapon(BASE + 2);
		assertEquals("the ornamented whip should walk like the plain one",
			SCIMITAR[0], inherited.idle);
		assertTrue(library.knows(BASE + 2));
	}

	@Test
	public void aPoisonedDaggerInheritsFromThePlainOne()
	{
		observe(BASE + 3, "Dragon dagger", SCIMITAR, 376);
		names.name(BASE + 4, "Dragon dagger(p++)");
		assertEquals(SCIMITAR[0], library.forWeapon(BASE + 4).idle);
	}

	@Test
	public void aDegradedBarrowsWeaponInheritsFromTheFullOne()
	{
		observe(BASE + 5, "Dharok's greataxe", STAFF, 2067);
		names.name(BASE + 6, "Dharok's greataxe 25");
		assertEquals(STAFF[0], library.forWeapon(BASE + 6).idle);
	}

	@Test
	public void aWeaponWithTwoMarkersStillFindsItsPlainForm()
	{
		observe(BASE + 7, "Rune scimitar", SCIMITAR, 390);
		names.name(BASE + 8, "Rune scimitar (bh)(p++)");
		assertEquals(SCIMITAR[0], library.forWeapon(BASE + 8).idle);
	}

	// ------------------------------------------------------------ metal tiers

	@Test
	public void aDifferentMetalOfTheSameWeaponInherits()
	{
		observe(BASE + 9, "Black longsword", SCIMITAR, 390);
		names.name(BASE + 10, "Adamant longsword");
		assertEquals("adamant should walk like black", SCIMITAR[0],
			library.forWeapon(BASE + 10).idle);
	}

	/**
	 * Measured before it was adopted: the Dragon longsword animates at 809
	 * where the Black one animates at 808, so the ornamental tiers are excluded
	 * on purpose. A dragon weapon must fall back rather than borrow.
	 */
	@Test
	public void anOrnamentalTierDoesNotBorrowFromAPlainMetal()
	{
		observe(BASE + 9, "Black longsword", SCIMITAR, 390);
		names.name(BASE + 11, "Dragon longsword");

		StanceLibrary.Stance stance = library.forWeapon(BASE + 11);
		assertEquals("dragon must fall back to unarmed, not borrow from black",
			library.forWeapon(0).idle, stance.idle);
	}

	// ----------------------------------------------------------- the refusals

	@Test
	public void aDeadmanCorruptedWeaponInheritsFromThePlainOne()
	{
		// "Corrupted" is a prefix, so no bracket stripping ever reached it.
		observe(BASE + 30, "Dragon claws", SCIMITAR, 7514);
		names.name(BASE + 31, "Corrupted dragon claws");
		assertEquals("the Deadman cosmetic should walk like the plain claws",
			SCIMITAR[0], library.forWeapon(BASE + 31).idle);
	}

	@Test
	public void aCorruptedWeaponWithNoPlainFormFallsBack()
	{
		// The Gauntlet's sceptre: nothing called plain "Sceptre" to borrow from.
		observe(BASE + 32, "Dragon claws", SCIMITAR, 7514);
		names.name(BASE + 33, "Corrupted sceptre");
		assertEquals(library.forWeapon(0).idle, library.forWeapon(BASE + 33).idle);
	}

	@Test
	public void aCorruptedWeaponThatIsKnownByItsOwnNameKeepsIt()
	{
		observe(BASE + 34, "Staff", SCIMITAR, 393);
		observe(BASE + 35, "Corrupted staff (perfected)", STAFF, 393);
		names.name(BASE + 36, "Corrupted staff (attuned)");
		assertEquals("the Gauntlet's own staff, not the plain one",
			STAFF[0], library.forWeapon(BASE + 36).idle);
	}

	@Test
	public void aDifferentWeaponSharingAWordDoesNotInherit()
	{
		observe(BASE + 12, "Dragon axe", SCIMITAR, 401);
		names.name(BASE + 13, "Dragon felling axe");

		assertEquals("a felling axe is not an axe with a marker on it",
			library.forWeapon(0).idle, library.forWeapon(BASE + 13).idle);
	}

	@Test
	public void aWeaponWithNoNameAtAllFallsBackQuietly()
	{
		StanceLibrary.Stance stance = library.forWeapon(999999);
		assertNotNull("an unknown weapon must still get something to walk with", stance);
		assertEquals(library.forWeapon(0).idle, stance.idle);
	}

	@Test
	public void unarmedIsAlwaysKnown()
	{
		assertTrue(library.knows(0));
		assertTrue("a negative id is unarmed too", library.knows(-1));
		assertNotNull(library.forWeapon(-1));
	}

	// -------------------------------------------------------- attack borrowing

	private StanceLibrary.StyleSource styles(Map<Integer, Integer> usage)
	{
		return itemId -> usage.getOrDefault(itemId, StanceLibrary.StyleSource.UNKNOWN);
	}

	@Test
	public void anUnseenWeaponBorrowsTheAttackItsClassAgreesOn()
	{
		Map<Integer, Integer> usage = new HashMap<>();
		int melee = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.MELEE, false);

		// Three scimitars seen swinging: two share the generic swing, one has a
		// signature of its own.
		observe(BASE + 14, "Steel scimitar", SCIMITAR, 390);
		observe(BASE + 15, "Mithril scimitar", SCIMITAR, 390);
		observe(BASE + 16, "Dragon scimitar", SCIMITAR, 12031);
		for (int id : new int[]{BASE + 14, BASE + 15, BASE + 16})
		{
			usage.put(id, melee);
		}

		// A fourth, never seen used, but in the same class and style.
		names.name(BASE + 17, "Adamant scimitar");
		library.setManual(BASE + 17, SCIMITAR[0], SCIMITAR[1], SCIMITAR[2], 0);
		usage.put(BASE + 17, melee);
		library.setStyleSource(styles(usage));

		assertEquals("the attack the most of its class agree on", 390,
			library.attackFor(BASE + 17));
	}

	@Test
	public void aTieGoesToTheLowerItemIdSoItIsTheSameEverySession()
	{
		Map<Integer, Integer> usage = new HashMap<>();
		int melee = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.MELEE, false);

		// One vote each, so only the item id can separate them. The LOWER id is
		// the one that must win, whichever order they were entered in.
		int lower = BASE + 18;
		int higher = BASE + 19;
		observe(higher, "Alpha blade", SCIMITAR, 555);
		observe(lower, "Beta blade", SCIMITAR, 111);
		usage.put(higher, melee);
		usage.put(lower, melee);

		names.name(BASE + 20, "Gamma blade");
		library.setManual(BASE + 20, SCIMITAR[0], SCIMITAR[1], SCIMITAR[2], 0);
		usage.put(BASE + 20, melee);
		library.setStyleSource(styles(usage));

		// The lower donor id breaks the tie, so the answer cannot depend on
		// hash order and change between sessions.
		int first = library.attackFor(BASE + 20);
		assertEquals(111, first);
		for (int i = 0; i < 20; i++)
		{
			assertEquals("the tie-break must be stable", first, library.attackFor(BASE + 20));
		}
	}

	@Test
	public void aBorrowNeverCrossesCombatStyles()
	{
		Map<Integer, Integer> usage = new HashMap<>();
		int melee = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.MELEE, false);
		int ranged = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.RANGED, false);

		// A harpoon and a bow can be CARRIED alike; they are not swung alike.
		observe(BASE + 21, "Harpoon", SCIMITAR, 390);
		usage.put(BASE + 21, melee);

		names.name(BASE + 22, "Shortbow");
		library.setManual(BASE + 22, SCIMITAR[0], SCIMITAR[1], SCIMITAR[2], 0);
		usage.put(BASE + 22, ranged);
		library.setStyleSource(styles(usage));

		assertEquals("a bow must not borrow a melee swing", 0, library.attackFor(BASE + 22));
	}

	@Test
	public void aBorrowNeverCrossesHandedness()
	{
		Map<Integer, Integer> usage = new HashMap<>();
		int oneHanded = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.RANGED, false);
		int twoHanded = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.RANGED, true);

		observe(BASE + 23, "Bronze dart", SCIMITAR, 806);
		usage.put(BASE + 23, oneHanded);

		names.name(BASE + 22, "Shortbow");
		library.setManual(BASE + 22, SCIMITAR[0], SCIMITAR[1], SCIMITAR[2], 0);
		usage.put(BASE + 22, twoHanded);
		library.setStyleSource(styles(usage));

		assertEquals("a thrown dart and a drawn bow are not the same motion",
			0, library.attackFor(BASE + 22));
	}

	@Test
	public void withNoStyleSourceNothingIsBorrowed()
	{
		observe(BASE + 14, "Steel scimitar", SCIMITAR, 390);
		// Not another metal's scimitar: that would inherit the swing by name,
		// which needs no style, and this is about the class borrow.
		names.name(BASE + 17, "Brine sabre");
		library.setManual(BASE + 17, SCIMITAR[0], SCIMITAR[1], SCIMITAR[2], 0);

		assertEquals("without knowing the style, refuse rather than guess",
			0, library.attackFor(BASE + 17));
	}

	@Test
	public void aWeaponSeenCarriedButNeverSwungStillSwingsAsItsOtherMetalDoes()
	{
		// Before it was seen it inherited the Steel scimitar's swing by metal;
		// seeing it carried gave it a record of its own with no swing in it.
		observe(BASE + 14, "Steel scimitar", SCIMITAR, 390);
		observe(BASE + 17, "Adamant scimitar", SCIMITAR, 0);

		assertEquals(390, library.attackFor(BASE + 17));
	}

	@Test
	public void aWeaponWithItsOwnAttackKeepsIt()
	{
		Map<Integer, Integer> usage = new HashMap<>();
		int melee = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.MELEE, false);
		observe(BASE + 14, "Steel scimitar", SCIMITAR, 390);
		observe(BASE + 16, "Dragon scimitar", SCIMITAR, 12031);
		usage.put(BASE + 14, melee);
		usage.put(BASE + 16, melee);
		library.setStyleSource(styles(usage));

		assertEquals("an observed attack always wins over a borrowed one",
			12031, library.attackFor(BASE + 16));
	}

	// ------------------------------------------------------------ persistence

	@Test
	public void whatIsLearnedSurvivesASaveAndReload() throws IOException
	{
		Path dir = folder.newFolder().toPath();
		StanceLibrary first = new StanceLibrary(new Gson(), names);
		first.load(dir);
		names.name(BASE + 1, "Abyssal whip");
		first.setManual(4151, 808, 819, 824, 1658);
		first.save();

		StanceLibrary second = new StanceLibrary(new Gson(), names);
		second.load(dir);

		StanceLibrary.Stance stance = second.describe(4151);
		assertNotNull("the observation did not survive the round trip", stance);
		assertEquals(808, stance.idle);
		assertEquals(819, stance.walk);
		assertEquals(824, stance.run);
		assertEquals(1658, stance.attack);
	}

	@Test
	public void savingWithNothingLearnedDoesNotFail() throws IOException
	{
		StanceLibrary fresh = new StanceLibrary(new Gson(), names);
		fresh.load(folder.newFolder().toPath());
		fresh.save();
		fresh.save();
	}

	@Test
	public void theBundledLibraryLoadsAndCoversARealWeapon() throws IOException
	{
		// The shipped stances.json is what a new install starts from; if it
		// stopped loading, every weapon would quietly fall back to unarmed.
		StanceLibrary shipped = new StanceLibrary(new Gson(), names);
		shipped.load(folder.newFolder().toPath());
		assertTrue("the bundled library should hold hundreds of weapons",
			shipped.size() > 100);
	}
}

package com.follower;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * The two name reductions that decide which weapons may inherit an animation
 * from which.
 *
 * <p>Both are deliberately narrow, and the narrowness is the point: over-eager
 * matching hands a weapon the wrong stance, which looks worse than having no
 * stance at all. These cases are the ones that drove the current shape - the
 * markers the old whitelist missed, and the pairs that must NOT collapse.
 */
public class StanceNamingTest
{
	// -------------------------------------------------------------- baseName

	@Test
	public void ornamentAndPoisonMarkersAreStripped()
	{
		assertEquals("abyssal whip", StanceLibrary.baseName("Abyssal whip (or)"));
		assertEquals("dragon dagger", StanceLibrary.baseName("Dragon dagger(p++)"));
		assertEquals("dragon spear", StanceLibrary.baseName("Dragon spear(kp)"));
		assertEquals("granite maul", StanceLibrary.baseName("Granite maul (or)"));
	}

	@Test
	public void twoMarkersOnOneNameBothGo()
	{
		assertEquals("rune scimitar", StanceLibrary.baseName("Rune scimitar (bh)(p++)"));
	}

	@Test
	public void wearAndChargeCountsAreStripped()
	{
		assertEquals("dharok's greataxe", StanceLibrary.baseName("Dharok's greataxe 25"));
		assertEquals("dharok's greataxe", StanceLibrary.baseName("Dharok's greataxe 100"));
		assertEquals("enchanted lyre", StanceLibrary.baseName("Enchanted lyre(2)"));
	}

	@Test
	public void differentWeaponsThatMerelyShareAWordStayApart()
	{
		// The reason the match stays exact on what is left: these two are not
		// the same weapon and must never share a stance.
		assertEquals("toxic staff", StanceLibrary.baseName("Toxic staff (uncharged)"));
		assertEquals("toxic staff of the dead",
			StanceLibrary.baseName("Toxic staff of the dead"));
	}

	@Test
	public void junkNamesReduceToNothingRatherThanToAKey()
	{
		assertNull(StanceLibrary.baseName(null));
		assertNull(StanceLibrary.baseName(""));
		assertNull(StanceLibrary.baseName("null"));
		assertNull("a name that is only a marker must not become a group",
			StanceLibrary.baseName("(or)"));
	}

	// ---------------------------------------------------------- tierBaseName

	@Test
	public void plainMetalTiersCollapseTogether()
	{
		assertEquals("longsword", StanceLibrary.tierBaseName("Adamant longsword"));
		assertEquals("longsword", StanceLibrary.tierBaseName("Black longsword"));
		assertEquals("longsword", StanceLibrary.tierBaseName("Rune longsword"));
		assertEquals("scimitar", StanceLibrary.tierBaseName("Mithril scimitar"));
	}

	@Test
	public void tierStrippingRunsAfterMarkerStripping()
	{
		assertEquals("scimitar", StanceLibrary.tierBaseName("Rune scimitar (bh)"));
	}

	/**
	 * Measured, not assumed: the Dragon longsword animates at 809 where the
	 * Black longsword animates at 808, so the ornamental tiers are excluded on
	 * purpose. If this test ever goes green, the exclusion has been lost.
	 */
	@Test
	public void ornamentalTiersAreNotTreatedAsPlainMetal()
	{
		assertNull(StanceLibrary.tierBaseName("Dragon longsword"));
		assertNull(StanceLibrary.tierBaseName("Crystal halberd"));
		assertNull(StanceLibrary.tierBaseName("Gilded scimitar"));
		assertNull(StanceLibrary.tierBaseName("3rd age longsword"));
	}

	@Test
	public void anUntieredWeaponNeverJoinsATierGroup()
	{
		assertNull("nothing to strip means no group at all",
			StanceLibrary.tierBaseName("Abyssal whip"));
		assertNull(StanceLibrary.tierBaseName("Toktz-xil-ak"));
	}

	@Test
	public void aTierWordOnItsOwnIsNotAWeapon()
	{
		assertNull(StanceLibrary.tierBaseName("Rune"));
		assertNull(StanceLibrary.tierBaseName("Bronze "));
	}

	@Test
	public void aTierWordInsideANameIsNotAPrefix()
	{
		// "Black" here is part of the noun, and the pattern is anchored so it
		// cannot be mistaken for a tier.
		assertEquals("mask", StanceLibrary.tierBaseName("Black mask"));
		assertNull(StanceLibrary.tierBaseName("Ancient staff"));
	}
}

package com.follower;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.lang.reflect.Proxy;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.AnimationID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;

/**
 * Where a weapon's stance and swing come from, now that what ships and what
 * was learned are kept apart.
 *
 * <p>Poses: learned, then shipped, then a weapon of the same name, then
 * unarmed. Swings: the shipped one for the kind of blow, the learned one for
 * the style unless it was really a block or a spell, the shipped one, the
 * learned one unless it was a block, then the weapon class - and never the
 * unarmed punch for a real weapon.
 */
public class StanceSourcesTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** A model repository that knows only the names this test gives it. */
	private static final class Names extends ModelRepository
	{
		private final Map<Integer, String> names = new HashMap<>();

		Names()
		{
			super(new Gson());
		}

		Names name(int id, String name)
		{
			names.put(id, name);
			return this;
		}

		@Override
		public String itemName(int itemId)
		{
			return names.get(itemId);
		}
	}

	/** Invented poses, so a learned stance cannot be mistaken for a shipped one. */
	private static final int[] INVENTED = {900001, 900002, 900003};

	/** Item ids well past anything the shipped library holds. */
	private static final int BASE = 800000;

	private static final int WHIP = 4151;
	private static final int DRAGON_DAGGER = 1215;
	private static final int STAFF_OF_AIR = 1381;
	private static final int TRIDENT = 11905;
	private static final int SULPHUR_BLADES = 29084;

	private Names names;
	private Path dir;
	private StanceLibrary library;

	@Before
	public void setUp() throws IOException
	{
		names = new Names();
		dir = folder.newFolder().toPath();
		library = load();
	}

	private StanceLibrary load()
	{
		StanceLibrary fresh = new StanceLibrary(new Gson(), names);
		fresh.load(dir);
		return fresh;
	}

	private void writeLearned(String json) throws IOException
	{
		Files.write(dir.resolve(StanceLibrary.FILE_NAME), json.getBytes(StandardCharsets.UTF_8));
	}

	private JsonObject savedFile() throws IOException
	{
		return new Gson().fromJson(new String(
			Files.readAllBytes(dir.resolve(StanceLibrary.FILE_NAME)), StandardCharsets.UTF_8),
			JsonObject.class);
	}

	// ----------------------------------------------------------------- poses

	@Test
	public void aLearnedStanceBeatsTheShippedOne()
	{
		library.setManual(WHIP, INVENTED[0], INVENTED[1], INVENTED[2], 0);
		assertEquals(INVENTED[1], library.forWeapon(WHIP).walk);
	}

	@Test
	public void aShippedStanceBeatsOneLearnedForAWeaponOfTheSameName()
	{
		// The lowest id of a name is the one its variants inherit from, so the
		// learned weapon has to sit below the whip to be its donor at all.
		names.name(WHIP, "Abyssal whip");
		names.name(1, "Abyssal whip (or)");
		names.name(BASE + 1, "Abyssal whip (t)");
		library.setManual(1, INVENTED[0], INVENTED[1], INVENTED[2], 0);
		assertEquals("the learned weapon is the name's donor", INVENTED[1],
			library.forWeapon(BASE + 1).walk);

		assertEquals("the whip's own shipped walk", 1660, library.forWeapon(WHIP).walk);
	}

	// ------------------------------------------------------------ the swings

	@Test
	public void aWeaponNothingIsKnownAboutNeverPunches()
	{
		// It stands and walks unarmed, and used to fight unarmed too.
		library.setStyleSource(id -> StanceLibrary.StyleSource.packed(
			StanceLibrary.StyleSource.MELEE, true));
		assertEquals(0, library.attackFor(999999));
		assertEquals(0, library.attackFor(999999, 0, StanceLibrary.CRUSH));
	}

	@Test
	public void aLearnedPunchOnARealWeaponIsNotUsed()
	{
		library.setManual(BASE + 2, INVENTED[0], INVENTED[1], INVENTED[2], 422);
		assertEquals(0, library.attackFor(BASE + 2));
	}

	@Test
	public void theShippedSwingForTheKindOfBlowComesFirst()
	{
		library.setManual(DRAGON_DAGGER, 808, 819, 824, 0);
		library.forWeapon(DRAGON_DAGGER).attackByStyle = new int[]{0, 386, 0, 0};

		assertEquals("community data over a learned style", 376,
			library.attackFor(DRAGON_DAGGER, 1, StanceLibrary.STAB));
		assertEquals("the learned style when the kind is not known", 386,
			library.attackFor(DRAGON_DAGGER, 1, -1));
		assertEquals("the shipped swing when neither is", 376,
			library.attackFor(DRAGON_DAGGER, -1, -1));
	}

	@Test
	public void aKindTheWeaponDoesNotDealFallsBackToItsSwing()
	{
		// The whip only slashes; a stab from the player's dagger gets the lash.
		assertEquals(1658, library.attackFor(WHIP, 0, StanceLibrary.STAB));
	}

	@Test
	public void theShippedSwingBeatsALearnedOne()
	{
		library.setManual(WHIP, 808, 1660, 1661, 390);
		assertEquals(1658, library.attackFor(WHIP));
	}

	@Test
	public void blocksAndSpecialsLearnedAsSwingsArePassedOver()
	{
		// Steel pickaxe 397 HUMAN_AXE_BLOCK, Zombie axe 1156 HUMAN_SHIELD_DEFENCE:
		// both were learned as attacks. Neither weapon class lends a swing here.
		library.setManual(BASE + 3, INVENTED[0], INVENTED[1], INVENTED[2], 397);
		library.setManual(BASE + 4, INVENTED[0], INVENTED[1], INVENTED[2], 1156);
		assertEquals(0, library.attackFor(BASE + 3));
		assertEquals(0, library.attackFor(BASE + 4));
	}

	@Test
	public void theGodswordsSecondSlashIsNotMistakenForABlock()
	{
		// DH_SWORD_UPDATE_BLOCK by name, a real godsword swing by use.
		library.setManual(BASE + 5, INVENTED[0], INVENTED[1], INVENTED[2], 7055);
		assertEquals(7055, library.attackFor(BASE + 5));
	}

	@Test
	public void theSulphurBladesSwingTheirOwnSlashOnceSeen()
	{
		// 10990 SULPHUR_BLADE_SLASH: Weapon Animation Replacer files it as the
		// Dual Macauhuitl's special, which must not make it a banned swing.
		Player player = player(SULPHUR_BLADES, new int[]{808, 819, 824, 820, 821, 822, 823, 823}, true);
		library.learnAttack(player, 10990, -1);

		assertEquals(10990, library.attackFor(SULPHUR_BLADES));
	}

	@Test
	public void aLearnedStyleThatWasABlockOrASpellIsPassedOver()
	{
		library.setManual(BASE + 6, INVENTED[0], INVENTED[1], INVENTED[2], 0);
		library.forWeapon(BASE + 6).attackByStyle = new int[]{397, 1162, 390, 0};

		assertEquals("a block", 0, library.attackFor(BASE + 6, 0, -1));
		assertEquals("a spell cast at the target", 0, library.attackFor(BASE + 6, 1, -1));
		assertEquals("a real swing", 390, library.attackFor(BASE + 6, 2, -1));
	}

	@Test
	public void thePlainHumanClassLendsNoSwing()
	{
		// Unarmed, swords, maces, daggers and bows all stand, walk and run this
		// way, so agreement inside it says nothing about the weapon.
		Map<Integer, Integer> usage = new HashMap<>();
		int melee = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.MELEE, false);
		for (int i = 10; i < 13; i++)
		{
			library.setManual(BASE + i, 808, 819, 824, 390);
			usage.put(BASE + i, melee);
		}
		library.setManual(BASE + 13, 808, 819, 824, 0);
		usage.put(BASE + 13, melee);
		library.setStyleSource(id -> usage.getOrDefault(id, StanceLibrary.StyleSource.UNKNOWN));

		assertEquals(0, library.attackFor(BASE + 13));
	}

	@Test
	public void aClassNamedForItsWeaponStillLends()
	{
		// SLAYER_ABYSSAL_WHIP_WALK: the walk alone names the weapon.
		Map<Integer, Integer> usage = new HashMap<>();
		int melee = StanceLibrary.StyleSource.packed(StanceLibrary.StyleSource.MELEE, false);
		library.setManual(BASE + 20, 808, 1660, 1661, 1658);
		library.setManual(BASE + 21, 808, 1660, 1661, 0);
		usage.put(BASE + 20, melee);
		usage.put(BASE + 21, melee);
		library.setStyleSource(id -> usage.getOrDefault(id, StanceLibrary.StyleSource.UNKNOWN));

		assertEquals(1658, library.attackFor(BASE + 21));
	}

	@Test
	public void seeingAWeaponThatInheritsItsSwingByNameKeepsTheSwing()
	{
		// Not shipped, so its stance and swings come from the plain dagger;
		// seen once, it has a record of its own that knows no swing.
		names.name(DRAGON_DAGGER, "Dragon dagger");
		names.name(BASE + 50, "Dragon dagger (cr)");
		assertEquals(376, library.attackFor(BASE + 50, 0, StanceLibrary.STAB));

		library.observe(client(player(BASE + 50, new int[]{808, 819, 824, 820, 821, 822, 823, 823}, false)));

		assertEquals("seen carried, it now has a record of its own", 819,
			library.describe(BASE + 50).walk);
		assertEquals(376, library.attackFor(BASE + 50, 0, StanceLibrary.STAB));
		assertEquals(377, library.attackFor(BASE + 50, 2, StanceLibrary.SLASH));
		assertEquals(376, library.attackFor(BASE + 50));
	}

	@Test
	public void aWeaponThatInheritsByNameCastsAsItsPlainVersionDoes()
	{
		names.name(TRIDENT, "Trident of the seas (full)");
		names.name(BASE + 51, "Trident of the seas (e)");
		library.setManual(BASE + 51, INVENTED[0], INVENTED[1], INVENTED[2], 0);

		assertEquals(AnimationID.HUMAN_CASTWAVE_STAFF, library.castFor(BASE + 51));
	}

	@Test
	public void aWeaponNothingIsKnownAboutTakesNoCastFromUnarmed()
	{
		library.setManual(StanceLibrary.UNARMED, 808, 819, 824, 1162);
		assertEquals(0, library.castFor(999999));
	}

	@Test
	public void aLearnedCastIsWhatACasterUses()
	{
		library.setManual(1381, 813, 1205, 1210, 11423);
		assertEquals(11423, library.castFor(1381));
		assertEquals("and the staff still bashes for anyone else", 419, library.attackFor(1381));
	}

	// ----------------------------------------------------- what gets written

	@Test
	public void onlyWhatWasLearnedIsSaved() throws IOException
	{
		library.setManual(BASE + 30, INVENTED[0], INVENTED[1], INVENTED[2], 0);
		library.save();

		JsonObject saved = savedFile();
		assertEquals("the shipped stances were written out too: " + saved.keySet(),
			Collections.singleton(Integer.toString(BASE + 30)), saved.keySet());
	}

	@Test
	public void copiesOfTheShippedStancesAreDroppedOnLoad() throws IOException
	{
		writeLearned("{"
			// Exactly as an older save wrote the shipped whip.
			+ "\"4151\":{\"idle\":808,\"walk\":1660,\"run\":1661,\"walkBack\":1660,\"walkLeft\":1660,"
			+ "\"walkRight\":1660,\"turnLeft\":823,\"turnRight\":823,\"attack\":1658},"
			// An older bundle's copy, before it knew the turns.
			+ "\"1215\":{\"idle\":808,\"walk\":819,\"run\":824,\"walkBack\":0,\"walkLeft\":0,"
			+ "\"walkRight\":0,\"turnLeft\":0,\"turnRight\":0,\"attack\":0},"
			// A real observation the shipped data does not have.
			+ "\"" + (BASE + 31) + "\":{\"idle\":900001,\"walk\":900002,\"run\":900003}"
			+ "}");

		StanceLibrary reloaded = load();
		assertEquals("the shipped turns are no longer hidden", 820,
			reloaded.forWeapon(DRAGON_DAGGER).walkBack);

		reloaded.save();
		assertEquals(Collections.singleton(Integer.toString(BASE + 31)), savedFile().keySet());
	}

	@Test
	public void aLearnedRecordWithSomethingOfItsOwnIsKept() throws IOException
	{
		writeLearned("{\"4151\":{\"idle\":808,\"walk\":1660,\"run\":1661,\"attack\":390}}");

		StanceLibrary reloaded = load();
		assertEquals("the shipped swing is still swung", 1658, reloaded.attackFor(WHIP));

		reloaded.save();
		JsonObject whip = savedFile().getAsJsonObject(Integer.toString(WHIP));
		assertEquals("its own attack survives", 390, whip.get("attack").getAsInt());
		assertEquals("the copied poses do not", 0, whip.get("idle").getAsInt());
	}

	@Test
	public void aFixToTheShippedPosesShowsThroughASwingLearnedOnAnOldCopy() throws IOException
	{
		// An older bundle's Staff of air, before it knew the turns, saved with
		// a cast this install saw on top.
		writeLearned("{\"1381\":{\"idle\":813,\"walk\":1205,\"run\":1210,\"walkBack\":0,"
			+ "\"walkLeft\":0,\"walkRight\":0,\"turnLeft\":0,\"turnRight\":0,\"attack\":1162}}");

		StanceLibrary reloaded = load();
		assertEquals("the shipped turns are no longer hidden", 1206, reloaded.forWeapon(STAFF_OF_AIR).walkBack);
		assertEquals("the cast it learned is kept", 1162, reloaded.castFor(STAFF_OF_AIR));
	}

	@Test
	public void theLearnedFileIsBackedUpOnceBeforeItIsFirstTrimmed() throws IOException
	{
		String before = "{\"1215\":{\"idle\":808,\"walk\":819,\"run\":824}}";
		writeLearned(before);
		load().save();

		Path backup = dir.resolve(StanceLibrary.BACKUP_NAME);
		assertEquals(before, new String(Files.readAllBytes(backup), StandardCharsets.UTF_8));

		// A later trim leaves the first backup alone.
		writeLearned("{\"4151\":{\"idle\":808,\"walk\":1660,\"run\":1661}}");
		load().save();
		assertEquals(before, new String(Files.readAllBytes(backup), StandardCharsets.UTF_8));
	}

	@Test
	public void nothingToTrimWritesNoBackup() throws IOException
	{
