	// ------------------------------------------------- a player on an obstacle

	/** HUMAN_WALK_LOGBALANCE_READY and HUMAN_WALK_LOGBALANCE: the set the game swaps in for a log. */
	private static final int[] ON_A_LOG = {763, 762, 762, 762, 762, 762, 763, 763};

	/**
	 * The game does a log or a ledge by swapping the player's base set, so
	 * a player seen on one shows the balance where their weapon's stand and
	 * walk would be (QA4 #5). Unarmed is shipped and never learned, and a set
	 * whose stand, walk or run empties a hand is no weapon's: every real
	 * stance keeps both, every obstacle set empties both.
	 */
	@Test
	public void aPlayerOnALogTeachesNoStance()
	{
		Client client = client(player(-1, ON_A_LOG, false));
		library.observe(client);
		assertEquals("empty-handed: still the follower's own walk", 819, library.forWeapon(-1).walk);
		assertEquals(808, library.forWeapon(-1).idle);

		int before = library.forWeapon(STAFF_OF_AIR).walk;
		library.observe(client(player(STAFF_OF_AIR, ON_A_LOG, false)));
		assertEquals("nor a weapon's", before, library.forWeapon(STAFF_OF_AIR).walk);

		library.observe(client(player(WHIP, new int[]{808, 762, 824, 820, 821, 822, 823, 823}, false)));
		assertEquals("nor a walk alone swapped", 1660, library.forWeapon(WHIP).walk);
	}

	/** One an older build learned is taken out of the file on the first tick, its swing kept. */
	@Test
	public void anObstacleSetLearnedBeforeIsForgotten() throws IOException
	{
		writeLearned("{\"0\":{\"idle\":763,\"walk\":762,\"run\":762,\"attack\":423},"
			+ "\"" + STAFF_OF_AIR + "\":{\"idle\":763,\"walk\":762,\"run\":762},"
			+ "\"" + (BASE + 7) + "\":{\"idle\":900001,\"walk\":900002,\"run\":900003}}");
		library = load();
		library.observe(client());
		library.save();

		JsonObject saved = savedFile();
		assertEquals("the unarmed swing stays", 423, saved.getAsJsonObject("0").get("attack").getAsInt());
		assertEquals("its balance goes", 0, saved.getAsJsonObject("0").get("walk").getAsInt());
		assertFalse(saved.has(Integer.toString(STAFF_OF_AIR)));
		assertEquals("a real one stays", 900002,
			saved.getAsJsonObject(Integer.toString(BASE + 7)).get("walk").getAsInt());
		assertEquals(819, library.forWeapon(-1).walk);
	}

	private static final int RUNE_2H = 1319;

	/**
	 * A two-hander seen on its own stand but the plain walk and run is
	 * mid-swap, and teaches nothing: one sighting used to carry it like a
	 * one-handed sword for good (qa5 #31).
	 */
	@Test
	public void aShippedStandWithAnotherWalkTeachesNothing() throws IOException
	{
		library.observe(client(player(RUNE_2H, new int[]{2561, 819, 824, 820, 821, 822, 823, 823}, false)));
		library.save();

		StanceLibrary reloaded = load();
		assertEquals(2562, reloaded.forWeapon(RUNE_2H).walk);
		assertEquals(2563, reloaded.forWeapon(RUNE_2H).run);
	}

	/** Such a set learned before is taken out on the first tick, its swing kept. */
	@Test
	public void aPassingSwapLearnedBeforeIsForgotten() throws IOException
	{
		writeLearned("{\"" + RUNE_2H + "\":{\"idle\":2561,\"walk\":819,\"run\":824,\"attack\":7045},"
			+ "\"20368\":{\"idle\":7053,\"walk\":819,\"run\":824}}");
		library = load();
		library.observe(client());
		library.save();

		JsonObject saved = savedFile();
		assertEquals("its swing stays", 7045, saved.getAsJsonObject(Integer.toString(RUNE_2H)).get("attack").getAsInt());
		assertEquals("its walk goes", 0, saved.getAsJsonObject(Integer.toString(RUNE_2H)).get("walk").getAsInt());
		assertFalse(saved.has("20368"));
		assertEquals(2562, library.forWeapon(RUNE_2H).walk);
		assertEquals(7052, library.forWeapon(20368).walk);
	}

	// ------------------------------------------------------------- doubles

	private static Player player(int weapon, int[] poses, boolean fighting)
	{
		Map<String, Object> composition = new HashMap<>();
		composition.put("getEquipmentId", weapon);
		Map<String, Object> answers = new HashMap<>();
		answers.put("getPlayerComposition", proxy(PlayerComposition.class, composition));
		answers.put("getIdlePoseAnimation", poses[0]);
		answers.put("getWalkAnimation", poses[1]);
		answers.put("getRunAnimation", poses[2]);
		answers.put("getWalkRotate180", poses[3]);
		answers.put("getWalkRotateLeft", poses[4]);
		answers.put("getWalkRotateRight", poses[5]);
		answers.put("getIdleRotateLeft", poses[6]);
		answers.put("getIdleRotateRight", poses[7]);
		if (fighting)
		{
			answers.put("getInteracting", proxy(NPC.class, new HashMap<>()));
		}
		return proxy(Player.class, answers);
	}

	private static Client client(Player... seen)
	{
		List<Player> players = java.util.Arrays.asList(seen);
		IndexedObjectSet<Player> set = new IndexedObjectSet<Player>()
		{
			@Override
			public Player byIndex(int index)
			{
				return index < players.size() ? players.get(index) : null;
			}

			@Override
			public Iterator<Player> iterator()
			{
				return players.iterator();
			}
		};
		Map<String, Object> view = new HashMap<>();
		view.put("players", set);
		Map<String, Object> client = new HashMap<>();
		client.put("getTopLevelWorldView", proxy(WorldView.class, view));
		// The log balance empties both hands, as every obstacle set does.
		net.runelite.api.Animation keeps = proxy(net.runelite.api.Animation.class,
			Map.of("getLeftHandItem", -1, "getRightHandItem", -1));
		net.runelite.api.Animation empties = proxy(net.runelite.api.Animation.class,
			Map.of("getLeftHandItem", -512, "getRightHandItem", -512));
		Client plain = proxy(Client.class, client);
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(self, method, args) -> method.getName().equals("loadAnimation")
				? ((Integer) args[0] == 762 || (Integer) args[0] == 763 ? empties : keeps)
				: method.invoke(plain, args));
	}

	@SuppressWarnings("unchecked")
	private static <T> T proxy(Class<T> type, Map<String, Object> answers)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type},
			(self, method, args) ->
			{
				if (answers.containsKey(method.getName()))
				{
					return answers.get(method.getName());
				}
				if (method.getName().equals("hashCode"))
				{
					return System.identityHashCode(self);
				}
				if (method.getName().equals("equals"))
				{
					return self == args[0];
				}
				Class<?> returns = method.getReturnType();
				return returns == int.class ? (Object) 0 : returns == boolean.class ? (Object) false : null;
			});
	}
}

package com.follower;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.RuneLiteObject;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertSame;

/**
 * The stand-up is the second half of the Sit emote, 10053. QA, 15 Oct: the
 * emote starts standing, sits, holds and stands, and played whole from a sit
 * it popped the follower up, sat it back down and stood it again, 2.8 seconds
 * of up-down-up where a second's stand-up was meant. Cache measurement: frames
 * 9-16 are the seated pose, 17-25 the rise from it, 50 client cycles.
 */
public class StandUpHalfTest
{
	private final List<Integer> loaded = new ArrayList<>();
	private final Animation sitEmote = animation();

	private static Animation animation()
	{
		return (Animation) Proxy.newProxyInstance(Animation.class.getClassLoader(),
			new Class<?>[]{Animation.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "isMayaAnim":
						return false;
					case "getFrameLengths":
						return new int[26];
					case "getDuration":
						return 26;
					case "getFrameStep":
						return -1;
					case "hashCode":
						return System.identityHashCode(proxy);
					case "equals":
						return proxy == args[0];
					default:
						Class<?> type = method.getReturnType();
						return type == boolean.class ? false : type == int.class ? 0 : null;
				}
			});
	}

	private FollowerEntity follower() throws ReflectiveOperationException
	{
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				if ("loadAnimation".equals(method.getName()))
				{
					loaded.add((Integer) args[0]);
					return (Integer) args[0] == FollowerEntity.SIT_EMOTE ? sitEmote : null;
				}
				Class<?> type = method.getReturnType();
				return type == boolean.class ? false : type == int.class ? 0 : type == long.class ? 0L : null;
			});
		FollowerEntity follower = new FollowerEntity(client, null);
		set(follower, "object", new RuneLiteObject(client));
		set(follower, "animatable", true);
		return follower;
	}

	private static void set(FollowerEntity follower, String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerEntity.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(follower, value);
	}

	private static AnimationController playing(FollowerEntity follower) throws ReflectiveOperationException
	{
		Field field = FollowerEntity.class.getDeclaredField("object");
		field.setAccessible(true);
		return ((RuneLiteObject) field.get(follower)).getAnimationController();
	}

	@Test
	public void theStandUpIsTheSitEmoteFromTheSeatedPose() throws ReflectiveOperationException
	{
		FollowerEntity follower = follower();
		follower.playAnimation(FollowerEntity.STAND_UP);
		assertEquals("the clip is the Sit emote", java.util.Collections.singletonList(10053), loaded);
		AnimationController controller = playing(follower);
		assertSame(sitEmote, controller.getAnimation());
		assertEquals("from its stand-up half", 17, controller.getFrame());
	}

	@Test
	public void aGestureFromTheSeatStandsUpFirstTheSameWay() throws ReflectiveOperationException
	{
		FollowerEntity follower = follower();
		follower.playAnimations(new int[]{KeepingCompany.STAND_UP, 863});
		assertEquals(17, playing(follower).getFrame());
	}

	@Test
	public void theSitEmoteItselfStillPlaysWhole() throws ReflectiveOperationException
	{
		// Copying a player's Sit is the emote, not a stand-up.
		FollowerEntity follower = follower();
		follower.playAnimation(10053);
		assertEquals(0, playing(follower).getFrame());
	}

	@Test
	public void everyStandUpIsTheHalfAndFitsItsWait() throws ReflectiveOperationException
	{
		assertEquals("the seat's stand-up", FollowerEntity.STAND_UP, KeepingCompany.STAND_UP);
		Field rest = FollowerPlugin.class.getDeclaredField("REST_STAND_UP");
		rest.setAccessible(true);
		assertEquals("the rest's stand-up", FollowerEntity.STAND_UP, rest.getInt(null));
		assertNotEquals("an id of its own, so 10053 stays the emote", 10053, FollowerEntity.STAND_UP);
		// Frames 17-25 are 50 client cycles of 20 ms: a second, inside two ticks.
		assertEquals(2, KeepingCompany.STAND_UP_TICKS);
	}
}

package com.follower;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The rest lets go a tick after whatever ended it, and an errand with no
 * trip can start on the seated follower in that tick: the scroll and the
 * reading pose for field notes, the bend for a bootlace. Letting go used to
 * clear whatever pose was on and play the sit's stand-up over anything, so
 * the notes were written standing idle with the scroll out and the bend was
 * cut off a tick in.
 */
public class StandingUpFromRestTest
{
	/** The Rest pose setting's default, the game's own sit emote. */
	private static final int SIT = new FollowerConfig()
	{
	}.restAnimation();

	private boolean emoting;
	private final List<Integer> played = new ArrayList<>();

	private final FollowerEntity follower = new FollowerEntity(null, null)
	{
		@Override
		public boolean isEmotePlaying()
		{
			return emoting;
		}

		@Override
		public void playAnimation(int animationId)
		{
			played.add(animationId);
		}
	};

	@Test
	public void fromTheSitItStandsUp()
	{
		follower.setPoseOverride(SIT);
		FollowerPlugin.letGoOfTheSit(follower, SIT);
		assertEquals(0, follower.getPoseOverride());
		assertEquals("the sit's own stand-up", Collections.singletonList(FollowerPlugin.REST_STAND_UP), played);
	}

	/** Sits down through the plugin's own rest, then stands with the setting now at the given pose. */
	private void sitThenStandWithTheSettingAt(int restAnimation) throws ReflectiveOperationException
	{
		FollowerPlugin plugin = new FollowerPlugin();
		Field field = FollowerPlugin.class.getDeclaredField("follower");
		field.setAccessible(true);
		field.set(plugin, follower);
		plugin.sitOrStand(true, SIT);
		plugin.sitOrStand(false, restAnimation);
	}

	@Test
	public void aRestPoseTurnedOffMidSitStillLetsGoOfTheSit() throws ReflectiveOperationException
	{
		// Turning the setting off is itself what ends the rest.
		sitThenStandWithTheSettingAt(0);
		assertEquals("the old sit is gone", 0, follower.getPoseOverride());
		assertEquals("and stood up from", Collections.singletonList(FollowerPlugin.REST_STAND_UP), played);
	}

	@Test
	public void aRestPoseChangedMidSitStillLetsGoOfTheOldSit() throws ReflectiveOperationException
	{
		// Another pose does not end the rest by itself; the player moving does.
		sitThenStandWithTheSettingAt(SIT + 1);
		assertEquals("the old sit is gone", 0, follower.getPoseOverride());
		assertEquals("and stood up from", Collections.singletonList(FollowerPlugin.REST_STAND_UP), played);
	}

	@Test
	public void fieldNotesStartedOnTheSitKeepTheirReadingPose()
	{
		follower.setPoseOverride(SIT);
		// The errand's first tick, before the rest has noticed it.
		follower.setPoseOverride(ErrandController.WRITE_SCROLL_POSE);
		FollowerPlugin.letGoOfTheSit(follower, SIT);
		assertEquals("still reading", ErrandController.WRITE_SCROLL_POSE, follower.getPoseOverride());
		assertTrue("and no stand-up over it", played.isEmpty());
	}

	@Test
	public void aBendStartedOnTheSitIsNotCutOff()
	{
		follower.setPoseOverride(SIT);
		emoting = true;
		FollowerPlugin.letGoOfTheSit(follower, SIT);
		assertTrue("the bend plays on", played.isEmpty());
		assertEquals("with the sit gone from under it", 0, follower.getPoseOverride());
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertTrue;

/**
 * What the plugin pays before it can show anything.
 *
 * <p>Every one of these loads inside {@code startUp}, on the thread that
 * enables the plugin. That is a real freeze for the user, and it happens again
 * on every toggle, so it is worth knowing which file costs what rather than
 * guessing. As with the dispatch cost, this is a tripwire and a place to read
 * the numbers from, not a benchmark to tune against.
 */
public class StartupCostTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static long millis(Runnable work)
	{
		long start = System.nanoTime();
		work.run();
		return (System.nanoTime() - start) / 1_000_000;
	}

	@Test
	public void aFreshInstallStartsInAReasonableTime() throws IOException
	{
		Path dir = folder.newFolder().toPath();
		Gson gson = new Gson();

		long fonts = millis(() -> new GameFontRepository(gson).load());
		long rules = millis(() -> new RuleLoader(gson).initialise(dir));
		long stances = millis(() ->
			new StanceLibrary(gson, new ModelRepository(gson)).load(dir));
		long spotAnims = 0;
		long profiles = millis(() -> new OutfitProfileStore(gson).load(dir));
		long models = 0;

		long total = fonts + rules + stances + spotAnims + profiles + models;

		System.out.printf("%n  a fresh install's startUp:%n"
				+ "    fonts.json       %4d ms%n"
				+ "    phrases.json     %4d ms%n"
				+ "    stances.json     %4d ms%n"
				+ "    spotanims.json   %4d ms%n"
				+ "    profiles         %4d ms%n"
				+ "    equipment models %4d ms%n"
				+ "    ----------------------%n"
				+ "    total            %4d ms%n%n",
			fonts, rules, stances, spotAnims, profiles, models, total);

		// Enabling a plugin should not read as a hang. This is deliberately
		// loose - it is here to catch something going badly wrong, like a
		// resource being parsed once per rule.
		assertTrue("startUp's file loading took " + total + "ms", total < 5000);
	}

	@Test
	public void loadingIsNotQuadraticInTheRuleCount() throws IOException
	{
		// The shape that matters: doubling the rules should roughly double the
		// load, not square it. A per-rule scan of the whole file would not show
		// up at 260 rules and would be crippling at 2000.
		long small = millis(() -> loadRules(250));
		long large = millis(() -> loadRules(4000));

		System.out.printf("  250 rules %d ms, 4000 rules %d ms%n", small, large);

		// 16x the rules; anything past a few hundred times the work is a
		// different complexity class, not just a slower machine.
		assertTrue("250 rules took " + small + "ms and 4000 took " + large
			+ "ms, which is not linear", large < Math.max(small, 1) * 300 + 3000);
	}

	private void loadRules(int count)
	{
		try
		{
			Path dir = folder.newFolder().toPath();
			StringBuilder out = new StringBuilder("{\"version\": 1, \"rules\": [");
			for (int i = 0; i < count; i++)
			{
				if (i > 0)
				{
					out.append(',');
				}
				out.append("{\"id\": \"r").append(i).append("\", \"group\": \"t\","
					+ " \"when\": {\"type\": \"inRegion\", \"regions\": [").append(i)
					.append("]}, \"say\": [\"line\"]}");
			}
			out.append("]}");
			Files.write(dir.resolve(RuleLoader.FILE_NAME),
				out.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));

			RuleLoader loader = new RuleLoader(new Gson());
			loader.initialise(dir);
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}

	@Test
	public void theBundledResourcesAreReadOnceNotPerLookup() throws IOException
	{
		// A repository that re-read its file on every get would be invisible in
		// a unit test and ruinous in the render loop.
		Path dir = folder.newFolder().toPath();
		GameFontRepository fonts = new GameFontRepository(new Gson());
		fonts.load();

		long lookups = millis(() ->
		{
			for (int i = 0; i < 200000; i++)
			{
				fonts.get(497);
				fonts.getByName("b12_full");
			}
		});

		System.out.printf("  400,000 font lookups in %d ms%n", lookups);
		assertTrue("font lookups cost " + lookups + "ms, which suggests they are"
			+ " doing more than a map read", lookups < 2000);
	}
}

package com.follower;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * What the plugin says in chat, and when. QA, 15 Oct (chat and menus). The
 * handlers need a client, so, as in {@link LifecycleGlueTest}, what can only
 * be read from the source is kept as a lint.
 */
public class StatusLinesTest
{
	private static final Path PLUGIN = Paths.get("src/main/java/com/follower/FollowerPlugin.java");

	private static String source() throws IOException
	{
		assertTrue("cannot read " + PLUGIN, Files.isRegularFile(PLUGIN));
		return PublicMarkers.strip(new String(Files.readAllBytes(PLUGIN), StandardCharsets.UTF_8).replace("\r\n", "\n"));
	}

	private static String method(String signature) throws IOException
	{
		String source = source();
		int start = source.indexOf(signature);
		assertTrue("the plugin has no " + signature + " - the lint has lost its place", start >= 0);
		return source.substring(start, source.indexOf("\n\t}\n", start));
	}

	/**
	 * "Wearing outfit profile 'Default follower'" was said on every start,
	 * plugin enable and profile switch, and was the first thing a new player
	 * ever heard from the plugin. The restore is quiet; a pick still answers.
	 */
	@Test
	public void restoringTheSessionsOutfitIsQuiet() throws IOException
	{
