			method("void sendStatus(String message)").contains(".type(ChatMessageType.CONSOLE)"));
		String chat = method("void onChatMessage(ChatMessage event)");
		int skip = chat.indexOf("if (event.getType() == ChatMessageType.CONSOLE)");
