package com.follower;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The states that OPEN something must not open on a line nobody saw.
 *
 * <p>The plugin queues lines behind the overhead box, and a queued line can
 * still be dropped: aged out as stale, displaced by a full queue, or cleared
 * with the scene. The engine used to latch the question, the want and the
 * wish the moment it handed the line over, so a dropped ask left its state
 * open anyway - which is how a gift option turned up in the Talk-to box for
 * a soft clay nobody ever heard wished for. The sink now owns the moment of
 * saying, and these three latch only when it reports the line landed. So does
 * everything else a line leaves behind: a first spent, a souvenir, a bet, a
 * dare, advice and a granted wish.
 */
public class SwallowedLineTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final String RULES = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"wisher\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"wish\": {\"what\": \"soft clay\", \"minutes\": 5, \"items\": [1761]},"
		+ " \"when\": {\"type\": \"login\"}, \"say\": [\"some soft clay, if you find any\"]},"
		+ "{\"id\": \"asker\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"asks\": \"want-outing\","
		+ " \"when\": {\"type\": \"levelUp\"}, \"say\": [\"talk to me a minute?\"]},"
		+ "{\"id\": \"wanter\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"want\": {\"region\": 10553, \"label\": \"the guild\", \"minutes\": 5},"
		+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"can we go?\"]}]}";

	/**
	 * One of each line that leaves something behind once said: a first, a
	 * souvenir, a bet, a challenge, a piece of advice and a thank-you.
	 */
	private static final String LATCHES = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"first\", \"group\": \"t\", \"cooldownMs\": 0, \"once\": true,"
		+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"we have not met\"]},"
		+ "{\"id\": \"keeper\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"pickUp\": {\"what\": \"a flat rock\", \"minutes\": 20},"
		+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"I'm keeping this rock\"]},"
		+ "{\"id\": \"better\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"bet\": {\"rich\": true, \"threshold\": 1000, \"minutes\": 5},"
		+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"a thousand says the next one's good\"]},"
		+ "{\"id\": \"darer\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"challenge\": {\"about\": \"ten kills\", \"tally\": \"kills\", \"target\": 10, \"minutes\": 5},"
		+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"ten kills in five minutes?\"]},"
		+ "{\"id\": \"adviser\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"advise\": {\"about\": \"food\", \"ids\": [829], \"minutes\": 1},"
		+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"eat something\"]},"
		+ "{\"id\": \"thanker\", \"group\": \"t\", \"cooldownMs\": 0, \"grantsWish\": true,"
		+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"thank you for the clay\"]}]}";

	private static final String[] LATCHING = {"first", "keeper", "better", "darer", "adviser", "thanker"};

	/**
	 * Advice and a rock, and the rules that read them: a dare that will not
	 * talk over advice still outstanding, a gift pocketed only while the
	 * hands are empty, and a word about the rock once it is carried.
	 */
	private static final String GUARDS = "{\"version\": 1, \"rules\": ["
		+ "{\"id\": \"adviser\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"advise\": {\"about\": \"food\", \"ids\": [829], \"minutes\": 1},"
		+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"eat something\"]},"
		+ "{\"id\": \"keeper\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"pickUp\": {\"what\": \"a flat rock\", \"minutes\": 20},"
		+ " \"when\": {\"type\": \"login\"}, \"say\": [\"I'm keeping this rock\"]},"
		+ "{\"id\": \"darer\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"challenge\": {\"about\": \"ten kills\", \"tally\": \"kills\", \"target\": 10, \"minutes\": 5},"
		+ " \"when\": {\"type\": \"all\", \"conditions\": [{\"type\": \"examined\"},"
		+ " {\"type\": \"none\", \"conditions\": [{\"type\": \"advising\"}]}]},"
		+ " \"say\": [\"ten kills in five minutes?\"]},"
		+ "{\"id\": \"pocketer\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"pickUp\": {\"what\": \"the clay you found me\", \"minutes\": 20},"
		+ " \"when\": {\"type\": \"all\", \"conditions\": [{\"type\": \"underfoot\"},"
		+ " {\"type\": \"none\", \"conditions\": [{\"type\": \"carrying\"}]}]},"
		+ " \"say\": [\"the clay goes in the good pocket\"]},"
		+ "{\"id\": \"mentioner\", \"group\": \"t\", \"cooldownMs\": 0,"
		+ " \"when\": {\"type\": \"all\", \"conditions\": [{\"type\": \"notesEdited\"},"
		+ " {\"type\": \"carrying\"}]}, \"say\": [\"still got the rock\"]}]}";

	@Test
	public void aDroppedLineSpendsNothing() throws IOException
	{
		// The queue and the dialogue hush both drop lines the engine already
		// handed over. A first nobody heard is still owed, a souvenir nobody
		// was told about is not carried, and a bet, a dare or advice nobody
		// heard is not open to be settled. The gift is the exception: it was
		// confirmed in the Talk-to box, so it is spent though the thank-you
		// was dropped, and the gift option does not come back for an item
		// already handed over.
		Harness h = new Harness(folder.newFolder().toPath(), LATCHES);
		h.gameTicks(1);

		h.engine.setSink((text, output, rule, animationId, onSaid) -> { });
		for (String id : LATCHING)
		{
			h.engine.force(id);
		}

		assertFalse("a first nobody heard is not spent",
			h.engine.getContext().hasSaidOnce("first"));

		// Still owed, so the next time it rises it is said, and spent then.
		h.engine.setSink((text, output, rule, animationId, onSaid) -> onSaid.run());
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertTrue(h.engine.getContext().hasSaidOnce("first"));
	}

	@Test
	public void aQueuedLineSpendsItsLatchesWhenItLands() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), LATCHES);
		h.gameTicks(1);

		List<Runnable> held = new ArrayList<>();
		h.engine.setSink((text, output, rule, animationId, onSaid) -> held.add(onSaid));
		for (String id : LATCHING)
		{
			h.engine.force(id);
		}
		assertFalse("waiting its turn is not yet said",
			h.engine.getContext().hasSaidOnce("first"));

		held.forEach(Runnable::run);
		assertTrue("the moment it lands, the first is spent",
			h.engine.getContext().hasSaidOnce("first"));
	}

	@Test
	public void aDroppedLineOpensNothing() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.gameTicks(1);

		// A sink that swallows everything, the way a cleared or overfull
		// queue does: the line is accepted and never said. Each opener is
		// FORCED, because back-to-back dispatches pace each other out and a
		// rule that never fired proves nothing about its latch - the first
		// version of this test only ever fired the wisher, and a mutation
		// latching the question at hand-off sailed through the other two.
		h.engine.setSink((text, output, rule, animationId, onSaid) -> { });
		h.engine.force("wisher");
		h.engine.force("asker");
		h.engine.force("wanter");

		assertEquals("nor a question", "", h.engine.getContext().getAskedTree());
		assertFalse("nor a want", h.engine.getContext().isWanting());
	}

	@Test
	public void aDroppedLineWearsNothingOut() throws IOException
	{
		// The wear ledger (R17) counts what was heard. A line the queue
		// swallowed has not worn out its welcome - and if drops counted,
		// a noisy scene could retire lines the player never got to read.
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.gameTicks(1);

		// force() rather than a second LOGIN: the director's pacing would
		// otherwise hold the second firing, and this test is about the sink.
		h.engine.setSink((text, output, rule, animationId, onSaid) -> { });
		h.engine.force("wisher");
		assertEquals("swallowed, so unworn", 0,
			h.engine.getContext().lineWear("some soft clay, if you find any"));

		h.engine.setSink((text, output, rule, animationId, onSaid) -> onSaid.run());
		h.engine.force("wisher");
		assertEquals("said, so worn by one", 1,
			h.engine.getContext().lineWear("some soft clay, if you find any"));
	}

	@Test
	public void aQueuedLineOpensWhenItFinallyLands() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath(), RULES);
		h.gameTicks(1);

		// A sink that holds its lines the way the plugin's queue does, and
		// says them later. All three openers, for the same reason as above.
		List<Runnable> held = new ArrayList<>();
		h.engine.setSink((text, output, rule, animationId, onSaid) -> held.add(onSaid));
		h.engine.force("wisher");
		h.engine.force("asker");
		h.engine.force("wanter");

		assertEquals("", h.engine.getContext().getAskedTree());
		assertFalse(h.engine.getContext().isWanting());

		held.forEach(Runnable::run);
		assertEquals("and the question", "want-outing",
			h.engine.getContext().getAskedTree());
		assertTrue("and the want", h.engine.getContext().isWanting());
	}



	@Test
	public void aProfileSwitchTakesTheQueuedLinesWithIt() throws IOException
	{
		// What a line leaves behind is spent in the memory that is current
		// when it lands. A switch reads the new profile's memory in, so a
		// first still queued from the old one was spent in the new one and
		// owed in the old one for good. The switch is plugin glue the harness
		// cannot reach, so its source is read instead.
		String source = PublicMarkers.strip(new String(java.nio.file.Files.readAllBytes(
			java.nio.file.Paths.get("src/main/java/com/follower/FollowerPlugin.java")),
			java.nio.charset.StandardCharsets.UTF_8));
		int start = source.indexOf("void onProfileChanged(ProfileChanged event)");
		assertTrue("the switch handler was not found", start >= 0);
		String switched = source.substring(start, source.indexOf("\n\t}", start));
		assertTrue("the old profile's queued lines go with it",
			switched.contains("speechQueue.clear();"));
		assertTrue("and the floor they were waiting for",
			switched.contains("speakingUntilMs = 0;"));
	}
}

package com.follower;

import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Where the recently-added systems touch each other.
 *
 * <p>The director, the shuffle bag, the corpus window, the one-time lines and
 * the delayed-speech queue were each built and tested on their own. Every one
 * of them intercepts the same moment - a rule has won and is about to speak -
 * and the order they run in is load-bearing in ways none of their own tests
 * can see.
 */
public class SystemsTogetherTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final long GAP = 3_000L;

	/**
	 * Puts the engine's own director into a relax period, deterministically.
	 *
	 * <p>Sets the gap itself rather than trusting the caller: the harness
	 * deliberately runs unpaced, and a director with no gap has no windows at
	 * all - so without this the helper silently does nothing and every test
	 * built on it passes for the wrong reason.
	 */
	private static void makeItRest(Harness h)
	{
		h.engine.setGlobalCooldownMs(GAP);

		SpeechRule ordinary = new SpeechRule();
		ordinary.id = "filler";
		ordinary.group = "reactions";
		long now = System.currentTimeMillis();
		for (int i = 0; i < 4; i++)
		{
			h.engine.getDirector().noteSpoke(ordinary, now);
		}
		assertTrue("the director should be resting",
			h.engine.getDirector().isRelaxing(now));
	}

	// ------------------------------------------- suppression against the bag

	@Test
	public void aLineNobodyHeardDoesNotSpendItsTurnInTheBag() throws IOException
	{
		// The bag's promise is that all N come out before any repeats. If a
		// suppressed firing drew from it anyway, the player would hear N minus
		// however many were swallowed - and the more the director held back,
		// the less variety it would leave behind. The two systems would fight.
		SpeechRule rule = new SpeechRule();
		rule.id = "t";
		rule.group = "reactions";
		rule.say = java.util.Arrays.asList("a", "b", "c", "d");

		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"t\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"examined\"},"
				+ " \"say\": [\"a\", \"b\", \"c\", \"d\"]}]}");
		h.engine.setGlobalCooldownMs(GAP);
		h.gameTicks(1);

		makeItRest(h);

		// Six firings that all get held.
		for (int i = 0; i < 6; i++)
		{
			h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
			h.gameTicks(1);
		}
		assertTrue("everything should have been held", h.spoken.isEmpty());

		// Now let it talk, with no gap in the way, and the bag should still be
		// whole: four distinct lines before any comes round again.
		h.engine.getDirector().reset();
		h.engine.setGlobalCooldownMs(0L);
		Set<String> heard = new HashSet<>();
		for (int i = 0; i < 4; i++)
		{
			h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
			h.gameTicks(1);
		}
		for (Harness.Spoken s : h.spoken)
		{
			heard.add(s.text);
		}
		assertEquals("suppression ate part of the bag", 4, heard.size());
	}

	// ------------------------------------------ the queue against the director

	@Test
	public void aDelayedOccasionSurvivesTheQuietAndOrdinaryChatterDoesNot()
		throws IOException
	{
		// A delayed line is judged when it LANDS, not when it won, so the
		// director gets a second look at something already decided. That is
		// correct - the world moved on in the meantime - but it means a line
		// with delayTicks is the one most likely to be swallowed, and every
		// arrival-arc line has a delay.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"slow-big\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"occasion\": true, \"delayTicks\": 3,"
				+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"this mattered\"]},"
				+ "{\"id\": \"slow-small\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"delayTicks\": 3,"
				+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"just chatter\"]}]}");
		h.engine.setGlobalCooldownMs(GAP);
		h.gameTicks(1);
		makeItRest(h);

		h.dispatch(TriggerEvent.death());
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		h.gameTicks(5);

		assertEquals("a delayed occasion has to land", 1, h.firedBy("slow-big").size());
		assertTrue("delayed chatter should be held like any other",
			h.firedBy("slow-small").isEmpty());
	}

	// ------------------------------------------ one-time lines against the rest

	@Test
	public void aOneTimeLineHeldByTheDirectorIsNotSpent() throws IOException
	{
		// The worst possible interaction in the whole set. A once-line has
		// exactly one chance; if the director eats it, the player never hears
		// it and never can. The arrival arc is all four of them.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"only-once\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"once\": true,"
				+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"we have not met\"]}]}");
		h.engine.setGlobalCooldownMs(GAP);
		h.gameTicks(1);
		makeItRest(h);

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertTrue("held, as an ordinary line would be", h.firedBy("only-once").isEmpty());
		assertFalse("but it must NOT have been spent",
			h.engine.getContext().hasSaidOnce("only-once"));

		h.engine.getDirector().reset();
		h.engine.setGlobalCooldownMs(0L);
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertEquals("still owed, and still paid", 1, h.firedBy("only-once").size());
		assertTrue(h.engine.getContext().hasSaidOnce("only-once"));
	}

	@Test
	public void everyArrivalLineIsBuiltToSurviveTheDirector() throws IOException
	{
		// The shipped version of the test above. These four are the only lines
		// in the file a player can miss permanently, and three of the systems
		// added this week can each swallow a line on its way out.
		Harness h = new Harness(folder.newFolder().toPath());
		long now = System.currentTimeMillis();
		makeItRest(h);

		for (String id : new String[]{"first-meeting", "first-page", "first-hour", "first-return"})
		{
			SpeechRule rule = h.rule(id);
			assertNull(id + " would be swallowed by a relax period",
				h.engine.getDirector().blocks(rule, now));

			// And the settling damper, which is live for exactly the sessions
			// these lines are written for.
			h.engine.getDirector().setSessionCount(1);
			assertNull(id + " would be swallowed while the follower settles in",
				h.engine.getDirector().blocks(rule, now));
		}
	}

	@Test
	public void theSettlingDamperCannotReachTheArrivalArc() throws IOException
	{
		// Belt and braces on the above, from the other end: the damper only
		// knows about groups, and every arrival line is misc rather than area
		// or gear. If one were ever moved into a scenery group it would fall
		// under the damper during the exact sessions it exists for.
		Harness h = new Harness(folder.newFolder().toPath());
		for (String id : new String[]{"first-meeting", "first-page", "first-hour", "first-return"})
		{
			assertFalse(id + " must not live in a group the damper thins",
				SpeechDirector.isLore(h.rule(id)));
		}
	}

	// ----------------------------------------- the window against the occasion

	@Test
	public void theCorpusWindowNeverSilencesAnUrgentLine() throws IOException
	{
		// The window prefers something unheard and falls back to the draw. A
		// single-variant warning has nothing to fall back TO, which is the case
		// worth pinning: "TELEPORT. NOW." said twice beats it not being said.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"urgent\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"occasion\": true,"
				+ " \"when\": {\"type\": \"examined\"}, \"say\": [\"MOVE\"]}]}");
		h.gameTicks(1);

		for (int i = 0; i < 8; i++)
		{
			h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
			h.gameTicks(1);
		}
		assertEquals("a warning with one line must say it every time",
			8, h.firedBy("urgent").size());
	}

	// --------------------------------------------- reading time and the queue

	@Test
	public void aLongLineDoesNotStretchTheQuiet() throws IOException
	{
		// Reading time gates the speech QUEUE and the director runs on the wall
		// clock, so a twelve-second line and a thirty-second rest are measured
		// from the same instant rather than stacking. Worth pinning because the
		// obvious wrong implementation - resting from the moment the line
		// finishes - would have long lines quietly buy longer silences.
		Harness h = new Harness(folder.newFolder().toPath());
		long now = System.currentTimeMillis();
		makeItRest(h);
		long shortLine = h.engine.getDirector().relaxRemainingMs(now);

		h.engine.getDirector().reset();
		SpeechRule wordy = new SpeechRule();
		wordy.id = "wordy";
		wordy.group = "reactions";
		for (int i = 0; i < 4; i++)
		{
			h.engine.getDirector().noteSpoke(wordy, now);
		}
		long longLine = h.engine.getDirector().relaxRemainingMs(now);

		assertTrue("the rest is drawn from a range, not from the line",
			shortLine >= 30_000L && shortLine <= 45_000L);
		assertTrue(longLine >= 30_000L && longLine <= 45_000L);
	}

	// ------------------------------------------------ everything, at real size

	@Test
	public void theShippedRulesStillSpeakWithEverySystemLive() throws IOException
	{
		// The integration smoke test. All the machinery on, the real rule set,
		// a few minutes of ticks - the follower has to still be a follower.
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.setGlobalCooldownMs(GAP);
		h.engine.getContext().setSessionCount(1);
		h.gameTicks(2);

		List<String> said = new ArrayList<>();
		for (int i = 0; i < 400; i++)
		{
			h.gameTick();
			h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
			if (i % 40 == 0)
			{
				h.dispatch(TriggerEvent.death());
			}
		}
		for (Harness.Spoken s : h.spoken)
		{
			if (!s.text.isEmpty())
			{
				said.add(s.text);
			}
		}

		assertFalse("the follower went completely silent", said.isEmpty());
		for (int i = 1; i < said.size(); i++)
		{
			assertFalse("said \"" + said.get(i) + "\" twice running",
				said.get(i).equals(said.get(i - 1)));
		}
	}
}

package com.follower;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * talk.json builds exactly the conversation the Java in {@link OldTalk} did,
 * for every input that shapes it - the mood band, the wish and the bag - and
 * the day summary says what it said, for every band.
 */
public class TalkScriptEquivalenceTest
{
	private static final String[] BANDS = {null, "", "low", "down", "even", "good", "high", "neutral"};

	@Test
	public void theFileBuildsTheSameScriptAsTheJava()
	{
		FollowerPlugin.Talk talk = TalkScriptTest.talk();
		assertEquals("the joke pool", OldTalk.JOKES.length, talk.jokes.size());
		for (int i = 0; i < OldTalk.JOKES.length; i++)
		{
			assertEquals("joke " + i, Arrays.asList(OldTalk.JOKES[i]), Arrays.asList(talk.jokes.get(i)));
		}
		Supplier<String[]> summary = () -> new String[]{"one page", "and another"};
		int variants = 0;
		for (String band : BANDS)
		{
					List<String> oldAnswers = new ArrayList<>();
					List<String> newAnswers = new ArrayList<>();
					Map<String, FollowerDialog.Node> was = OldTalk.talkScript(summary, oldAnswers::add,
						band);
					Map<String, FollowerDialog.Node> now = FollowerPlugin.talkScript(talk, summary, newAnswers::add,
						band);
					String where = band;
					assertEquals(where + " nodes, in order", new ArrayList<>(was.keySet()), new ArrayList<>(now.keySet()));
					for (String id : was.keySet())
					{
						FollowerDialog.Node a = was.get(id);
						FollowerDialog.Node b = now.get(id);
						String at = where + " " + id;
						assertEquals(at + " speaker", a.isPlayerSpeaking(), b.isPlayerSpeaking());
						assertEquals(at + " options", a.getOptionLabels(), b.getOptionLabels());
						assertEquals(at + " option targets", a.getOptionTargets(), b.getOptionTargets());
						assertEquals(at + " targets", a.getTargets(), b.getTargets());
						if (id.startsWith("chat-joke") && id.endsWith("-a"))
						{
							// Drawn from the pool on every visit, never the same one twice running.
							List<String> first = b.getPages();
							List<String> second = b.getPages();
							assertTrue(at + " tells a joke from the pool", isJoke(talk, first) && isJoke(talk, second));
							assertNotEquals(at + " twice the same", first, second);
							assertTrue(at + " the old one did too", isJoke(talk, a.getPages()));
						}
						else
						{
							assertEquals(at + " pages", a.getPages(), b.getPages());
							assertEquals(at + " lines", a.getLines(), b.getLines());
						}
						a.runFinish();
						b.runFinish();
						assertEquals(at + " answers", oldAnswers, newAnswers);
					}
					variants++;
		}
		assertEquals(BANDS.length, variants);
	}

	@Test
	public void theDaySummaryReadsTheSameFromTheFile()
	{
		FollowerPlugin.Talk talk = TalkScriptTest.talk();
		int[] counts = {0, 1, 2, 12};
		int checked = 0;
		for (String band : new String[]{null, "", "low", "down", "even", "good", "high", "neutral", "ordinary"})
		{
			for (int minutes : new int[]{0, 1, 2, 59, 60, 61, 95, 120, 121, 480, 999})
			{
				for (int kills : counts)
				{
					for (int other : counts)
					{
						for (String incident : new String[]{null, "", "that chicken"})
						{
							String[] was = OldTalk.daySummary(minutes, kills, other, kills ^ other, band, incident);
							String[] now = FollowerPlugin.daySummary(talk, minutes, kills, other, kills ^ other, band, incident);
							assertEquals(band + "/" + minutes + "/" + kills + "/" + other + "/" + incident,
								Arrays.asList(was), Arrays.asList(now));
							checked++;
						}
					}
				}
			}
		}
		assertEquals(9 * 11 * 4 * 4 * 3, checked);
	}

	private static boolean isJoke(FollowerPlugin.Talk talk, List<String> pages)
	{
		return talk.jokes.stream().anyMatch(joke -> Arrays.asList(joke).equals(pages));
	}
}

package com.follower;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The everyday Talk-to conversation.
 *
 * <p>It is the only speech in the plugin that does not live in phrases.json,
 * and until now it was the only speech nothing checked. Every failure the rule
 * file is guarded against applies here too, and worse: a branch pointing at a
 * node that does not exist shuts the box in the player's face mid-sentence,
 * and a character the game has no glyph for renders as a different character
 * entirely rather than as nothing.
 */
public class TalkScriptTest
{
	private static Map<String, FollowerDialog.Node> script()
	{
		// The day-summary branch is built fresh each visit from figures only the
		// running plugin has. A stand-in keeps the structural checks honest
		// (the node is reachable, its pages are readable, it ends where it says
		// it does); the wording itself is walked branch by branch below.
		// Built WITH a wish open and the thing in the bag, so the gift branch
		// exists and every structural check walks it too; the other variants
		// are checked in their own tests below.
		return FollowerPlugin.talkScript(talk(),
			() -> FollowerPlugin.daySummary(talk(), 95, 12, 2, 1, "good", "that chicken"),
			answer -> { }, "even");
	}

	/** Every node id something points at, via {@code then} or a choice. */
	private static Set<String> targets(Map<String, FollowerDialog.Node> script)
	{
		Set<String> found = new TreeSet<>();
		for (FollowerDialog.Node node : script.values())
		{
			found.addAll(node.getTargets());
		}
		return found;
	}

	@Test
	public void pickingAnOptionSaysExactlyThatOption()
	{
		// The option IS the sentence you are about to speak, not a summary of
		// it - that is how the game works and how players read it. An option
		// whose node says something slightly different reads as a bug, because
		// it is one; and one that jumps straight to a menu without saying
		// anything reads as the click having gone astray.
		Map<String, FollowerDialog.Node> script = script();
		List<String> problems = new ArrayList<>();

		for (Map.Entry<String, FollowerDialog.Node> entry : script.entrySet())
		{
			FollowerDialog.Node node = entry.getValue();
			List<String> labels = node.getOptionLabels();
			List<String> targets = node.getOptionTargets();

			for (int i = 0; i < labels.size(); i++)
			{
				String label = labels.get(i);
				FollowerDialog.Node landed = script.get(targets.get(i));
				if (landed == null)
				{
					continue;
				}
				if (!landed.isPlayerSpeaking() || landed.getPages().isEmpty())
				{
					problems.add(entry.getKey() + ": \"" + label
						+ "\" is picked but never said");
					continue;
				}
				String spoken = landed.getPages().get(0);
				if (!label.equals(spoken))
				{
					problems.add(entry.getKey() + ": picked \"" + label
						+ "\" but said \"" + spoken + "\"");
				}
			}
		}
		assertTrue("options that do not match what the player says:\n  "
			+ String.join("\n  ", problems), problems.isEmpty());
	}


	@Test
	public void aLowDaySharpensTheQuestion()
	{
		// "How have you been?" becomes "You all right?" when the band is low
		// or down - same slot, same spirit, pointed by state - and asking is
		// itself the kindness: the answer node latches "comforted" on arrival.
		java.util.List<String> answers = new java.util.ArrayList<>();

		Map<String, FollowerDialog.Node> low = FollowerPlugin.talkScript(talk(),
			() -> new String[]{""}, answers::add, "low");
		assertTrue("the sharpened option leads somewhere real",
			low.containsKey("allright-q"));
		assertTrue("and the hub offers it",
			low.get("start").getOptionLabels().contains("You all right?"));
		assertTrue("while the everyday entrance rests",
			!low.get("start").getOptionLabels().contains("How have you been?"));
		low.get("allright-a").runFinish();
		assertTrue("asking is the kindness", answers.contains("comforted"));

		// "down" is lowish too - the sharpened question covers the whole
		// bottom of the mood range, not just its floor. (Only "low" was
		// tested at first; the strategy's mutation analysis caught it.)
		Map<String, FollowerDialog.Node> down = FollowerPlugin.talkScript(talk(),
			() -> new String[]{""}, answers::add, "down");
		assertTrue("a down day sharpens the question too",
			down.get("start").getOptionLabels().contains("You all right?"));

		Map<String, FollowerDialog.Node> fine = FollowerPlugin.talkScript(talk(),
			() -> new String[]{""}, answers::add, "good");
		assertTrue("on a fine day the everyday question is back",
			fine.get("start").getOptionLabels().contains("How have you been?"));
		assertTrue("and nobody asks a cheerful follower if it is all right",
			!fine.containsKey("allright-q"));
	}

	@Test
	public void theCombatBranchExplainsTheThrallOutfits()
	{
		// Thrall mode is the one feature where getting it wrong looks broken
		// rather than deliberate: an unset outfit puts the follower in a mage
		// fight holding a greataxe. The dialogue is the only place a player is
		// told that the three styles want three outfits.
		String text = allText();
		assertTrue("nothing about standing in for a thrall", text.contains("thrall"));
		for (String style : new String[]{"zombie", "skeleton", "ghost",
			"melee", "ranged", "magic"})
		{
			assertTrue("the thrall talk never mentions " + style, text.contains(style));
		}
		assertTrue("never says to set an outfit for each", text.contains("outfit for each"));
	}

	/**
	 * Every structurally distinct build of the script: the two question
	 * shapes (lowish and everyday) crossed with the three wish states. The
	 * structural checks walk ALL of them, because a dead end that only
	 * exists in the low-band variant is exactly the kind nobody meets until
	 * a bad day - which is the worst possible day to have the box shut in
	 * your face. (The first version of these checks walked one variant; the
	 * third deep-testing pass caught the gap.)
	 */
	private static Map<String, Map<String, FollowerDialog.Node>> allVariants()
	{
		Map<String, Map<String, FollowerDialog.Node>> variants =
			new java.util.LinkedHashMap<>();
		for (String band : new String[]{"low", "even"})
		{
			variants.put(band + "/no-wish", FollowerPlugin.talkScript(talk(),
				() -> FollowerPlugin.daySummary(talk(), 95, 12, 2, 1, "good", "that chicken"),
				answer -> { }, band));
		}
		return variants;
	}

	@Test
	public void everyBranchLeadsToANodeThatExists()
	{
		for (Map.Entry<String, Map<String, FollowerDialog.Node>> variant
			: allVariants().entrySet())
		{
			Set<String> missing = new TreeSet<>(targets(variant.getValue()));
			missing.removeAll(variant.getValue().keySet());
			assertTrue(variant.getKey() + ": branches pointing at nodes that do"
				+ " not exist, which shut the box mid-conversation: " + missing,
				missing.isEmpty());
		}
	}

	@Test
	public void everyNodeCanBeReached()
	{
		// An unreachable node is dialogue nobody will ever read. Usually it
		// means a branch was repointed and its old destination left behind.
		for (Map.Entry<String, Map<String, FollowerDialog.Node>> variant
			: allVariants().entrySet())
		{
			Map<String, FollowerDialog.Node> script = variant.getValue();
			Set<String> reachable = new HashSet<>(targets(script));
			reachable.add("start");

			Set<String> orphans = new TreeSet<>(script.keySet());
			orphans.removeAll(reachable);
			assertTrue(variant.getKey() + ": nodes nothing leads to: " + orphans,
				orphans.isEmpty());
		}
	}

	@Test
	public void everyLineHasAGlyphInBothGameFonts() throws IOException
	{
		// Same check the rule file gets, and for the same reason: GameFont
		// maps anything above U+00FF through cp1252, to a '?' or a glyph not
		// every font has. The line does not come out blank, it comes out
		// wrong, and nothing reports it.
		JsonObject fonts = bundled("/com/follower/fonts.json");
		JsonObject overhead = fontById(fonts, 496);
		JsonObject dialog = fontById(fonts, 497);

		List<String> problems = new ArrayList<>();
		for (Map.Entry<String, Map<String, FollowerDialog.Node>> variant
			: allVariants().entrySet())
		{
			for (Map.Entry<String, FollowerDialog.Node> entry : variant.getValue().entrySet())
			{
				for (String line : entry.getValue().getLines())
				{
					for (char c : line.toCharArray())
					{
						if (c == ' ')
						{
							continue;
						}
						if (!hasGlyph(overhead, c) || !hasGlyph(dialog, c))
						{
							problems.add(String.format("%s %s: '%c' (U+%04X) in %s",
								variant.getKey(), entry.getKey(), c, (int) c, line));
						}
					}
				}
			}
		}
		assertTrue("lines the game cannot draw:\n  "
			+ String.join("\n  ", problems), problems.isEmpty());
	}

	@Test
	public void everyDaySummaryReadsLikeASentence()
	{
		// The one branch of the conversation whose wording is assembled at run
		// time rather than written out, so it is the one branch the checks
		// above cannot see. Sixteen combinations of what happened today, times
		// five moods, and each has to be a sentence the player can read.
		List<String> problems = new ArrayList<>();
		String[] moods = {"low", "down", "neutral", "good", "high"};
		int[][] figures = {
			{0, 0, 0, 0}, {1, 1, 1, 1}, {59, 0, 0, 0}, {60, 0, 0, 0},
			{61, 0, 0, 0}, {95, 12, 2, 1}, {480, 999, 9, 40},
			{0, 3, 0, 0}, {0, 0, 0, 2},
		};

		for (String mood : moods)
		{
			for (int[] f : figures)
			{
				for (String incident : new String[]{null, "that chicken"})
				{
					String[] pages = FollowerPlugin.daySummary(talk(),
						f[0], f[1], f[2], f[3], mood, incident);
					String where = mood + " " + java.util.Arrays.toString(f);

					if (pages.length == 0)
					{
						problems.add(where + ": said nothing at all");
						continue;
					}
					for (String page : pages)
					{
						if (page.trim().isEmpty())
						{
							problems.add(where + ": blank page");
						}
						else if (page.length() > 110)
						{
							problems.add(where + " (" + page.length() + "): " + page);
						}
						else if (!page.endsWith(".") && !page.endsWith("!")
							&& !page.endsWith("?"))
						{
							problems.add(where + ": unfinished - " + page);
						}
						// A plural agreement slip is the tell that the numbers
						// were pasted in rather than spoken.
						if (page.contains("1 things") || page.contains("1 levels")
							|| page.contains("1 deaths") || page.contains("1 minutes")
							|| page.contains("1 hours"))
						{
							problems.add(where + ": plural on one - " + page);
						}
					}
				}
			}
		}
		assertTrue("day summaries that do not read:\n  "
			+ String.join("\n  ", problems), problems.isEmpty());
	}

	@Test
	public void anHourAndAHalfIsNotRoundedDownToAnHour()
	{
		// 95 minutes used to read "1 hour" - the diary of somebody who was
		// not really keeping one.
		String[] pages = FollowerPlugin.daySummary(talk(), 95, 0, 0, 0, "neutral", null);
		assertTrue("the extra minutes went missing: " + pages[0],
			pages[0].contains("1 hour and 35 minutes"));
	}

	@Test
	public void aQuietDaySaysSoRatherThanReportingZeroes()
	{
		// The reason the branch exists at all. A follower that answers "0
		// kills, 0 levels, 0 deaths" has read the tallies out; one that says
		// nothing happened has understood them.
		String[] pages = FollowerPlugin.daySummary(talk(), 0, 0, 0, 0, "neutral", null);
		String first = pages[0];
		assertFalse("reported a zero: " + first, first.contains("0 "));
		assertFalse("reported a zero: " + first, first.startsWith("So far:"));
	}

	@Test
	public void nothingRunsOnTooLongToRead()
	{
		// The dialog body is a 380px column of three lines. A page much past
		// this is either cut off or crushes the whole conversation into a wall,
		// and a follower that monologues stops sounding like an NPC.
		List<String> tooLong = new ArrayList<>();
		for (Map.Entry<String, Map<String, FollowerDialog.Node>> variant
			: allVariants().entrySet())
		{
			for (Map.Entry<String, FollowerDialog.Node> entry : variant.getValue().entrySet())
			{
				for (String line : entry.getValue().getLines())
				{
					if (line.length() > 110)
					{
						tooLong.add(variant.getKey() + " " + entry.getKey()
							+ " (" + line.length() + "): " + line);
					}
				}
			}
		}
		assertTrue("pages too long for the box:\n  "
			+ String.join("\n  ", tooLong), tooLong.isEmpty());
	}

	@Test
	public void theConversationCanAlwaysBeEndedFromAnywhere()
	{
		// The property that actually matters is not that every menu has a
		// "back" on it - the joke loop escapes two hops away, through the
		// groan - but that no node strands the player. From anywhere, some
		// sequence of clicks has to reach an ending.
		for (Map.Entry<String, Map<String, FollowerDialog.Node>> variant
			: allVariants().entrySet())
		{
			Map<String, FollowerDialog.Node> script = variant.getValue();
			List<String> trapped = new ArrayList<>();
			for (String from : script.keySet())
			{
				if (!canEnd(script, from))
				{
					trapped.add(from);
				}
			}
			assertTrue(variant.getKey() + ": nodes the player cannot get out of: "
				+ trapped, trapped.isEmpty());
		}
	}

	/** Whether any path from here reaches a node that closes the box. */
	private static boolean canEnd(Map<String, FollowerDialog.Node> script, String from)
	{
		Set<String> seen = new HashSet<>();
		java.util.Deque<String> queue = new java.util.ArrayDeque<>();
		queue.add(from);
		while (!queue.isEmpty())
		{
			String id = queue.poll();
			if (!seen.add(id))
			{
				continue;
			}
			FollowerDialog.Node node = script.get(id);
			if (node == null)
			{
				continue;
			}
			List<String> next = node.getTargets();
			if (next.isEmpty())
			{
				// Nothing to continue to: the pages run out and the box shuts.
				return true;
			}
			queue.addAll(next);
		}
		return false;
	}

	@Test
	public void theFollowerTalksAboutWhatItCanActuallyDo()
	{
		// The script drifted a whole feature set behind once already: it still
		// described a follower that only walked, stayed and danced, long after
		// it had a memory, a mood, tastes and things it wanted. Nothing catches
		// that automatically - this at least catches it going backwards.
		String text = allText();

		// Matched on the player's own question rather than on the follower's
		// answer: the answer is characterisation and gets reworded, the
		// question is the capability and does not.
		assertTrue("nothing about counting or remembering", text.contains("keep track"));
		assertTrue("nothing about having moods", text.contains("mood"));
		assertFalse("places it likes, in a build without them", text.contains("places i like"));
		assertTrue("nothing about asking to be taken somewhere",
			text.contains("take me somewhere"));
		assertTrue("nothing about giving you room while thieving",
			text.contains("pockets"));
		assertFalse("the old Whitman line is not how an NPC talks",
			text.contains("contain multitudes"));
	}

	// ------------------------------------------------------------- plumbing

	/** talk.json, read as the plugin reads it. */
	static FollowerPlugin.Talk talk()
	{
		try (java.io.Reader in = new InputStreamReader(
			TalkScriptTest.class.getResourceAsStream("/com/follower/talk.json"), StandardCharsets.UTF_8))
		{
			return new com.google.gson.Gson().fromJson(in, FollowerPlugin.Talk.class);
		}
		catch (IOException e)
		{
			throw new java.io.UncheckedIOException(e);
		}
	}

	/** Every line the script can put on screen, lowercased. */
	private static String allText()
	{
		StringBuilder all = new StringBuilder();
		for (FollowerDialog.Node node : script().values())
		{
			for (String line : node.getLines())
			{
				all.append(line).append(' ');
			}
		}
		return all.toString().toLowerCase(java.util.Locale.ROOT);
	}

	private static JsonObject bundled(String resource) throws IOException
	{
		try (InputStream in = TalkScriptTest.class.getResourceAsStream(resource))
		{
			assertTrue("missing bundled resource " + resource, in != null);
			return new JsonParser().parse(
				new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
		}
	}

	private static JsonObject fontById(JsonObject fonts, int id)
	{
		for (com.google.gson.JsonElement element : fonts.getAsJsonArray("fonts"))
		{
			JsonObject font = element.getAsJsonObject();
			if (font.get("id").getAsInt() == id)
			{
				return font;
			}
		}
		throw new AssertionError("no font " + id + " in the bundled dump");
	}

	private static boolean hasGlyph(JsonObject font, char c)
	{
		// Anything past Latin-1 would be truncated to a different character.
		if (c > 0xFF)
		{
			return false;
		}
		// Exactly what GameFont.drawTop does to choose a glyph.
		JsonObject glyph = font.getAsJsonArray("glyphs").get(c & 0xFF).getAsJsonObject();
		com.google.gson.JsonElement mask = glyph.get("mask");
		return glyph.get("w").getAsInt() > 0
			&& mask != null && !mask.isJsonNull() && !mask.getAsString().isEmpty();
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.Arrays;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The teleport's hold on the follower (QA, 15 Oct): it stays planted for the
 * whole cast, whatever else lets go of it meanwhile, and only a cast that
 * reached its last stage takes the follower with it.
 */
public class TeleportHoldTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final int[] HOME = {4847, 4850, 4853, 4855, 4857};
	private static final WorldPoint HERE = new WorldPoint(3222, 3218, 0);

	private FollowerEntity follower;
	private PropFlourish flourish;

	@Before
	public void setUp() throws IOException, ReflectiveOperationException
	{
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
				method.getName().equals("loadAnimation") ? animation((Integer) args[0])
					: zero(method.getReturnType()));
		StanceLibrary stances = new StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		stances.load(folder.newFolder().toPath());
		follower = new FollowerEntity(client, stances);
		set("object", new RuneLiteObject(client));
		set("animatable", true);
		set("spawned", true);
		set("tile", HERE);
		flourish = new PropFlourish(follower, new ErrandController.Hands()
		{
			@Override
			public void hold(int itemId)
			{
			}

			@Override
			public void release()
			{
			}
		});
	}

	private static Animation animation(int id)
	{
		return (Animation) Proxy.newProxyInstance(Animation.class.getClassLoader(),
			new Class<?>[]{Animation.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getId":
						return id;
					case "getFrameLengths":
						int[] lengths = new int[10];
						Arrays.fill(lengths, 5);
						return lengths;
					case "getFrameStep":
						return -1;
					case "hashCode":
						return System.identityHashCode(proxy);
					case "equals":
						return proxy == args[0];
					default:
						return zero(method.getReturnType());
				}
			});
	}

	private static Object zero(Class<?> type)
	{
		if (type == boolean.class)
		{
			return false;
		}
		if (type == int.class)
		{
			return 0;
		}
		if (type == long.class)
		{
			return 0L;
		}
		return null;
	}

	private void set(String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerEntity.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(follower, value);
	}

	private Object get(String name) throws ReflectiveOperationException
	{
		Field field = FollowerEntity.class.getDeclaredField(name);
		field.setAccessible(true);
		return field.get(follower);
	}

	private boolean vanished() throws ReflectiveOperationException
	{
		return (Boolean) get("vanished");
	}

	/** What mirror-home-teleport does: plant, start the slaved chain, arm the vanish. */
	private void homeTeleport()
	{
		follower.stayHere();
		follower.startSlavedChain(HOME, null);
		follower.vanishAfterEmote();
	}

	/** The player steps on through this many stages. */
	private void toStage(int stages)
	{
		for (int i = 0; i < stages; i++)
		{
			follower.advanceSlavedChain();
		}
	}

	@Test
	public void aHomeTeleportCutShortKeepsTheFollower() throws Exception
	{
		homeTeleport();
		toStage(1);
		// The player clicks away mid-cast: their animation goes to -1.
		follower.slavedPlayerStopped();
		assertFalse("cut short, it stays", vanished());
		assertFalse(follower.isSlavedChainActive());
		assertFalse(follower.isEmotePlaying());
	}

	@Test
	public void aCutShortCastArmsNoLaterVanish() throws Exception
	{
		homeTeleport();
		toStage(2);
		follower.slavedPlayerStopped();
		// The next emote ending must not take the disarmed vanish with it.
		follower.playAnimation(863);
		follower.cancelEmote();
		assertFalse(vanished());
	}

	@Test
	public void aCompletedHomeTeleportVanishes() throws Exception
	{
		homeTeleport();
		toStage(HOME.length - 1);
		follower.slavedPlayerStopped();
		assertTrue("the last stage done, it leaves with the player", vanished());
		assertFalse(follower.isSlavedChainActive());
	}

	@Test
	public void aCosmeticWithMoreStagesHoldsTheLastOneUntilThePlayerLeaves() throws Exception
	{
		// Leagues 6: eight player stages to the follower's five.
		homeTeleport();
		toStage(7);
		assertFalse("still with the player on their last stage", vanished());
		assertTrue(follower.isSlavedChainActive());
		follower.slavedPlayerStopped();
		assertTrue("and gone with them", vanished());
	}

	@Test
	public void aStageThatRunsOutHoldsItsFinalFrame() throws Exception
	{
		homeTeleport();
		toStage(HOME.length - 1);
		AnimationController clip = ((RuneLiteObject) get("object")).getAnimationController();
		// Ten frames of five ticks, run well past their end.
		clip.tick(70);
		assertEquals("held on its last frame, not started again", 9, clip.getFrame());
		assertTrue("and still playing it", clip.getAnimation() != null);
	}

	@Test
	public void aFlourishEndingMidCastDoesNotLetGo() throws Exception
	{
		assertTrue(flourish.start(0, ErrandController.SCROLL_PROP, ErrandController.WRITE_SCROLL_POSE, 2));
		homeTeleport();
		toStage(1);
		flourish.tick();
		flourish.tick();
		assertFalse("the flourish is over", flourish.isActive());
		assertEquals("still planted for the cast", HERE, get("stayTile"));
		assertTrue("so the cast plays on", follower.isSlavedChainActive());

		// The release it asked for comes with the cast's end.
		toStage(HOME.length - 2);
		assertEquals(HERE, get("stayTile"));
		follower.slavedPlayerStopped();
		assertTrue(vanished());
		assertNull("let go once the cast is over", get("stayTile"));
	}

	@Test
	public void aReleaseMidCastIsCarriedOutWhenTheCastIsCutShort() throws Exception
	{
		homeTeleport();
		toStage(2);
		// A work session or an errand ending mid-cast.
		follower.resumeFollowing();
		assertEquals(HERE, get("stayTile"));
		follower.slavedPlayerStopped();
		assertFalse(vanished());
		assertNull("cut short, it follows again", get("stayTile"));
	}

	@Test
	public void aOneShotTeleportHoldsTooAndReleasesAsItVanishes() throws Exception
	{
		// mirror-teleport: a one-shot cast with the vanish armed.
		follower.stayHere();
		follower.playAnimation(714);
		follower.vanishAfterEmote();
		follower.resumeFollowing();
		assertEquals("planted while the cast plays", HERE, get("stayTile"));
		follower.cancelEmote();
		assertNull("the cast cut short lets go", get("stayTile"));
		assertFalse(vanished());
	}

	@Test
	public void eachClipThatGoesOnIsReportedForItsHands()
	{
		java.util.List<Integer> clips = new java.util.ArrayList<>();
		follower.setOnEmoteClip(clips::add);
		homeTeleport();
		toStage(1);
		assertEquals("the chalk stick's stage, then the next", Arrays.asList(4847, 4850), clips);
		follower.cancelEmote();
		follower.playAnimation(3864);
		assertEquals(Integer.valueOf(3864), clips.get(clips.size() - 1));
	}

	@Test
	public void aCastThatNeverStartedHoldsNothingBack() throws Exception
	{
		set("animatable", false);
		follower.stayHere();
		follower.playAnimation(714);
		follower.vanishAfterEmote();
		follower.resumeFollowing();
		assertNull(get("stayTile"));
	}

	@Test
	public void aReleaseOutsideACastIsImmediate() throws Exception
	{
		follower.stayHere();
		follower.resumeFollowing();
		assertNull(get("stayTile"));
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.lang.reflect.Field;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * A teleport whose clip outlasts its cast (QA, 15 Oct). The Lunar
 * teleports' HUMAN_TELEPORT_OTHER_IMPACT (1816) runs 2064 client cycles, 41
 * seconds, most of it a held last frame, so the follower's copy was still
 * playing long after the player had landed, and its vanish never came. The
 * player landing is the cast's end too: the follower lands with them.
 */
public class TeleportLandingTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final int LUNAR = 1816;
	private static final WorldPoint CAST_FROM = new WorldPoint(3222, 3218, 0);

	private FakeGame game;
	private FollowerEntity follower;
	private int snaps;

	@Before
	public void setUp() throws IOException, ReflectiveOperationException
	{
		game = new FakeGame().withCollision().animation(LUNAR, -1);
		StanceLibrary stances = new StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		stances.load(folder.newFolder().toPath());
		follower = new FollowerEntity(game.client, stances);
		follower.setOnSnapped(() -> snaps++);
		set("object", new RuneLiteObject(game.client));
		set("animatable", true);
		set("spawned", true);
		set("tile", new WorldPoint(3221, 3218, 0));
		follower.updateFrame();

		// mirror-teleport: planted, the copy of the cast, the vanish armed.
		follower.stayHere();
		follower.playAnimation(LUNAR);
		follower.vanishAfterEmote();
		follower.updateFrame();
		assertTrue(follower.isEmotePlaying());
	}

	private Object get(String name) throws ReflectiveOperationException
	{
		Field field = FollowerEntity.class.getDeclaredField(name);
		field.setAccessible(true);
		return field.get(follower);
	}

	private void set(String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerEntity.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(follower, value);
	}

	private void landsBesideThePlayer(WorldPoint landing) throws ReflectiveOperationException
	{
		game.at(landing.getX(), landing.getY(), landing.getPlane());
		follower.updateFrame();
		assertFalse("the copy ends with the cast", follower.isEmotePlaying());
		assertFalse((Boolean) get("vanished"));
		assertNull("and its hold with it", get("stayTile"));
		assertTrue("beside the player: " + follower.getWorldLocation(),
			follower.getWorldLocation().distanceTo(landing) <= 2);
		assertEquals("told, so an errand or the minutes end in the same frame", 1, snaps);
	}

	@Test
	public void aLongTeleportLandsTheFollowerWithThePlayer() throws ReflectiveOperationException
	{
		landsBesideThePlayer(new WorldPoint(2100, 3900, 0));
	}

	@Test
	public void soDoesOneInsideTheStayLeash() throws ReflectiveOperationException
	{
		// Twelve tiles: no snap of the leash's own would come for this.
		landsBesideThePlayer(new WorldPoint(CAST_FROM.getX() + 12, CAST_FROM.getY(), 0));
	}

	/** Gone with the cast, and back beside the player where they land. */
	@Test
	public void theReappearanceAfterAVanishIsASnapToo() throws ReflectiveOperationException
	{
		follower.cancelEmote();
		set("vanished", true);
		set("vanishPlayerTile", CAST_FROM);
		game.at(2100, 3900, 0);
		follower.updateFrame();
		assertFalse((Boolean) get("vanished"));
		assertEquals(1, snaps);
	}

	@Test
	public void aStepIsNotALanding() throws ReflectiveOperationException
	{
		game.at(CAST_FROM.getX() + 1, CAST_FROM.getY(), 0);
		follower.updateFrame();
		assertTrue("a step is not a teleport", follower.isEmotePlaying());
		assertEquals(0, snaps);
	}
}

package com.follower;

import java.io.IOException;
import java.util.List;
import net.runelite.api.gameval.AnimationID;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Every spellbook's teleport is copied, not only the Standard and Ancient
 * ones (QA, 15 Oct). The ids are gameval's, on the player skeleton in the
 * cache; which one each spellbook plays is to be watched in game.
 */
public class TeleportTriggersTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private Harness copying(int animation, String... silenced) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.setDisabledGroups(new java.util.HashSet<>(java.util.Arrays.asList(silenced)));
		h.gameTicks(2);
		h.dispatch(TriggerEvent.animation(animation));
		h.gameTicks(2);
		return h;
	}

	@Test
	public void theLunarArceuusAndTabletTeleportsAreCopied() throws IOException
	{
		for (int cast : new int[]{AnimationID.HUMAN_TELEPORT_OTHER_IMPACT,
			AnimationID.HUMAN_SPELLCAST_ARCEUUS_TELEPORT, AnimationID.POH_ABSORB_TABLET_TELEPORT})
		{
			List<Harness.Spoken> copied = copying(cast).firedBy("mirror-teleport");
			assertEquals("teleport " + cast, 1, copied.size());
			assertEquals(cast, copied.get(0).animationId);
		}
	}

	/**
	 * QA3: the copies were in Reactions, so unticking Reactions to quiet the
	 * death and level remarks stopped them, and Mimicry, which governs the
	 * other copies, did not.
	 */
	@Test
	public void mimicryGovernsTheTeleportCopiesAndReactionsDoesNot() throws IOException
	{
		int cast = AnimationID.HUMAN_SPELLCAST_ARCEUUS_TELEPORT;
		int home = AnimationID.LEAGUE03_HOME_TELEPORT_HUMAN_1;
		assertEquals(1, copying(cast, "reactions").firedBy("mirror-teleport").size());
		assertEquals(1, copying(home, "reactions").firedBy("mirror-home-teleport").size());
		assertTrue(copying(cast, "mimic").firedBy("mirror-teleport").isEmpty());
		assertTrue(copying(home, "mimic").firedBy("mirror-home-teleport").isEmpty());
	}

	@Test
	public void breakingATabletIsNotATeleport() throws IOException
	{
		// The smash is the same for every tablet, bones to bananas and the
		// enchantments too: only the teleport's own absorb is copied.
		assertTrue(copying(AnimationID.POH_SMASH_MAGIC_TABLET).firedBy("mirror-teleport").isEmpty());
	}

	/**
	 * QA, 16 Oct: two cosmetic home teleports' first stages, beside the
	 * Trailblazer and League 3 ones in gameval and the cache, were missing,
	 * and with them the copy. COW_HOME_TELEPORT_1 in RuneLite's own legacy
	 * constants is 1696, so that one stays though gameval names it a dodge.
	 */
	@Test
	public void everyHomeTeleportsFirstStageStartsTheCopy() throws IOException
	{
		for (int start : new int[]{AnimationID.AIDE_DRAWING_CHALK_CIRCLE,
			AnimationID.LEAGUES_6_HOME_TELEPORT_PLAYER_01, AnimationID.LEAGUE_TRAILBLAZER_HOME_TELEPORT_HUMAN_1,
			AnimationID.LEAGUE03_HOME_TELEPORT_HUMAN_1, AnimationID.HUMAN_DODGE_RF_A,
			AnimationID.HOME_TELEPORT_HUMAN_FIRE_1, AnimationID.HOME_TELEPORT_HUMAN_ECHOES_1})
		{
			assertEquals("home teleport " + start, 1, copying(start).firedBy("mirror-home-teleport").size());
		}
	}
}

package com.follower;

import net.runelite.api.NPC;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Pickpocketing, which looks exactly like a fight from inside the plugin.
 *
 * <p>Both of the signals combat is read from are true while thieving: the
 * target is an NPC with a combat level, and a failed attempt lands a hitsplat
 * on the player. A run of failures therefore had the follower stepping clear,
 * announcing a fight, coming back, and doing it again every few seconds.
 *
 * <p>The animation settles it. 881 is the pickpocket and 1054 the stun that
 * follows getting it wrong, both the player's own, so neither depends on
 * knowing which NPC is being robbed.
 */
public class ThievingTest
{
	private static final int PICKPOCKET = 881;
	private static final int STUN = 1054;

	private static final class Sim
	{
		final FakeGame game = new FakeGame();
		final TriggerContext ctx = new TriggerContext(game.client);
		int tick;

		void tick(int count)
		{
			for (int i = 0; i < count; i++)
			{
				game.tick(++tick);
				ctx.refresh();
			}
		}
	}

	@Test
	public void pickpocketingIsNoticed()
	{
		Sim sim = new Sim();
		sim.tick(2);
		assertFalse(sim.ctx.isThieving());

		sim.game.animating(PICKPOCKET);
		sim.tick(1);
		assertTrue(sim.ctx.isThieving());
	}

	@Test
	public void theStunFromAFailedAttemptCountsToo()
	{
		Sim sim = new Sim();
		sim.game.animating(STUN);
		sim.tick(1);
		assertTrue("the stun is part of the same session", sim.ctx.isThieving());
	}

	@Test
	public void robbingSomethingThatCanFightBackIsNotAFight()
	{
		// A guard has a combat level, so interaction alone reads as combat.
		Sim sim = new Sim();
		NPC guard = sim.game.spawnNpc(3269, "Guard", 21);
		sim.game.fighting(guard);
		sim.game.animating(PICKPOCKET);
		sim.tick(3);

		assertTrue(sim.ctx.isThieving());
		assertFalse("interacting with a guard while robbing it is not combat",
			sim.ctx.isInCombat());
	}

	@Test
	public void theHitFromAFailedPocketIsNotAFightEither()
	{
		Sim sim = new Sim();
		sim.game.animating(PICKPOCKET);
		sim.tick(2);

		// Exactly what the plugin does on a hitsplat.
		sim.ctx.noteDamageTaken();

		assertFalse("the damage IS the failure, not an attack",
			sim.ctx.isInCombat());
	}

	@Test
	public void aRunOfFailuresDoesNotFlicker()
	{
		// The complaint: in and out of combat every few seconds across a run.
		Sim sim = new Sim();
		NPC guard = sim.game.spawnNpc(3269, "Guard", 21);
		sim.game.fighting(guard);

		for (int attempt = 0; attempt < 12; attempt++)
		{
			sim.game.animating(PICKPOCKET);
			sim.tick(3);
			sim.ctx.noteDamageTaken();
			sim.game.animating(STUN);
			sim.tick(8);
			// The pause between attempts, animation back to nothing.
			sim.game.animating(-1);
			sim.tick(4);

			assertFalse("combat read as true on attempt " + attempt,
				sim.ctx.isInCombat());
			assertTrue("thieving lapsed between attempts on " + attempt,
				sim.ctx.isThieving());
		}
	}

	@Test
	public void everyStunTheGameCanApplyIsRecognised()
	{
		// There is not one stun animation. Recognising only STUNNED_THIEVING
		// covered one case in seven, and the rest is why the follower came
		// back early against some targets and not others.
		int[] stuns = {1054, 1874, 848, 14422, 14423, 14424, 10087, 10088};
		for (int stun : stuns)
		{
			Sim sim = new Sim();
			sim.game.animating(stun);
			sim.tick(1);
			assertTrue("stun " + stun + " was not recognised as thieving",
				sim.ctx.isThieving());
		}
	}

	// ---------------------------------------------------------------- session

	@Test
	public void theSessionOutlastsAGapTheAttemptWindowWouldNot()
	{
		// The complaint: back too early. A pause to eat, or a slow re-click,
		// is longer than the window that suppresses combat.
		Sim sim = new Sim();
		sim.game.animating(PICKPOCKET);
		sim.tick(2);

		sim.game.animating(-1);
		sim.tick(40);

		assertFalse("the attempt window is only for holding the session open",
			sim.ctx.isThieving());
		assertTrue("the session is what everything else asks about",
			sim.ctx.isInThievingSession());
		assertFalse("and it keeps combat suppressed across the gap",
			sim.ctx.isInCombat());
	}

	@Test
	public void walkingOffEndsTheSessionAtOnce()
	{
		// What a person actually does when they are done, and it should not
		// have to wait out any clock.
		Sim sim = new Sim();
		sim.game.animating(PICKPOCKET);
		sim.tick(2);
		assertTrue(sim.ctx.isInThievingSession());

		sim.game.animating(-1);
		sim.game.at(3222 + 20, 3218, 0);
		sim.tick(1);

		assertFalse("walking away is the signal to come back",
			sim.ctx.isInThievingSession());
	}

	@Test
	public void everyWayTheGameOffersATheftCounts()
	{
		// The silence has to hold for anything the player is robbing, not just
		// for the one target that was tested. Matched on the words rather than
		// on an exact list, because an exact list is silently wrong about
		// everything it left out.
		for (String option : new String[]{
			"Pickpocket", "pickpocket", "Steal-from", "Steal from", "Steal",
			"<col=00ff00>Pickpocket</col>"})
		{
			assertTrue(option + " should read as thieving",
				FollowerPlugin.isThievingOption(option));
		}

		// And things that are not.
		for (String option : new String[]{
			"Attack", "Talk-to", "Trade", "Examine", "Walk here", "Bank", null, ""})
		{
			assertFalse(option + " should not read as thieving",
				FollowerPlugin.isThievingOption(option));
		}
	}

	@Test
	public void clickingPickpocketArmsItBeforeTheWalkOver()
	{
		// Reported from play: the FIRST attempt of a session announced a fight.
		// Clicking Pickpocket on an elf across the room sets the interaction
		// target at once and then the player walks over, and every tick of that
		// walk looked like combat - an NPC with a combat level and a health
		// bar - because the session only armed on the pickpocket animation,
		// which does not happen until the player arrives.
		Sim sim = new Sim();
		NPC elf = sim.game.spawnNpc(4993, "Elf", 108);

		sim.ctx.noteThievingIntent();
		sim.game.fighting(elf);
		sim.tick(4);

		assertTrue("intent arms the session", sim.ctx.isInThievingSession());
		assertFalse("walking over to rob someone is not a fight",
			sim.ctx.isInCombat());
	}

	@Test
	public void withoutTheIntentTheWalkOverStillReadsAsAFight()
	{
		// The other half, so the test above cannot pass for the wrong reason:
		// the same setup with no click IS how a real approach looks.
		Sim sim = new Sim();
		NPC elf = sim.game.spawnNpc(4993, "Elf", 108);

		sim.game.fighting(elf);
		sim.tick(4);

		assertTrue("an NPC target with no stated intent is still a fight",
			sim.ctx.isInCombat());
	}

	@Test
	public void clickingAttackEndsTheTheftAtOnce()
	{
		// The session outlives the gaps between attempts on purpose, and the
		// cost is a window where a genuine fight goes unnoticed. Saying Attack
		// is the one unambiguous signal that closes it now.
		Sim sim = new Sim();
		sim.game.animating(PICKPOCKET);
		sim.tick(2);
		assertTrue(sim.ctx.isInThievingSession());

		sim.ctx.noteFightIntent();
		NPC goblin = sim.game.spawnNpc(3029, "Goblin", 5);
		sim.game.animating(-1);
		sim.game.fighting(goblin);
		sim.tick(2);

		assertFalse("attacking ends the theft", sim.ctx.isInThievingSession());
		assertTrue("and the fight registers immediately", sim.ctx.isInCombat());
	}

	@Test
	public void followingAMarkThatWandersDoesNotEndTheSession()
	{
		// Found in a transcript. The radius was sized for a stall - a fixed
		// point you stand at - and elves wander, so following one across a few
		// tiles ended the session several times a minute. The follower
		// announced the end of a theft that was still going on, and then
		// cheered on the "fight" the next failed attempt looked like.
		Sim sim = new Sim();
		sim.game.animating(PICKPOCKET);
		sim.tick(2);
		assertTrue(sim.ctx.isInThievingSession());

		sim.game.animating(-1);
		sim.game.at(3222 + 8, 3218 + 4, 0);
		sim.tick(3);

		assertTrue("chasing the mark is still working the mark",
			sim.ctx.isInThievingSession());
	}

	@Test
	public void aBreakToOpenCoinPouchesDoesNotEndTheSession()
	{
		// The other half of the same transcript: the ninety-second window ran
		// out while the player emptied pouches or drank a dose, which ended the
		// session mid-run for the same reason.
		Sim sim = new Sim();
		sim.game.animating(PICKPOCKET);
		sim.tick(2);

		sim.game.animating(-1);
		sim.tick(160);

		assertTrue("a two-minute pause is a pause, not an ending",
			sim.ctx.isInThievingSession());
	}

	@Test
	public void shufflingAboutDoesNotEndTheSession()
	{
		Sim sim = new Sim();
		sim.game.animating(PICKPOCKET);
		sim.tick(2);

		sim.game.animating(-1);
		sim.game.at(3222 + 2, 3218 + 1, 0);
		sim.tick(3);

		assertTrue("a step or two is still the same spot",
			sim.ctx.isInThievingSession());
	}

	@Test
	public void aChangeOfFloorEndsTheSession()
	{
		Sim sim = new Sim();
		sim.game.animating(PICKPOCKET);
		sim.tick(2);

		sim.game.animating(-1);
		sim.game.at(3222, 3218, 1);
		sim.tick(1);

		assertFalse(sim.ctx.isInThievingSession());
	}

	@Test
	public void standingThereDoingNothingEventuallyEndsIt()
	{
		Sim sim = new Sim();
		sim.game.animating(PICKPOCKET);
		sim.tick(2);

		sim.game.animating(-1);
		sim.tick(300);

		assertFalse("it cannot stand back forever on one attempt",
			sim.ctx.isInThievingSession());
	}

	@Test
	public void aLongRunOfAttemptsKeepsTheSessionAlive()
	{
		Sim sim = new Sim();
		for (int attempt = 0; attempt < 20; attempt++)
		{
			sim.game.animating(PICKPOCKET);
			sim.tick(3);
			sim.game.animating(1054);
			sim.tick(8);
			sim.game.animating(-1);
			sim.tick(10);

			assertTrue("the session lapsed during attempt " + attempt,
				sim.ctx.isInThievingSession());
		}
	}

	@Test
	public void aRealFightAfterThievingIsStillAFight()
	{
		// The cost of this is a few ticks where a genuine attack is missed.
		// It must not be more than a few.
		Sim sim = new Sim();
		sim.game.animating(PICKPOCKET);
		sim.tick(2);

		// Walking off is what ends a session, so that is how a fight becomes
		// visible again - and being attacked is one of the few things that
		// actually makes a player move.
		sim.game.animating(-1);
		sim.game.at(3222 + 20, 3218, 0);
		sim.tick(2);

		NPC goblin = sim.game.spawnNpc(3029, "Goblin", 5);
		sim.game.fighting(goblin);
		sim.tick(2);

		assertTrue("a fight starting after thieving lapses must register",
			sim.ctx.isInCombat());
	}

	@Test
	public void aFightAlreadyRunningIsNotForgottenByOnePickpocket()
	{
		// Combat has its own grace window, and this must not shorten it.
		Sim sim = new Sim();
		NPC goblin = sim.game.spawnNpc(3029, "Goblin", 5);
		sim.game.fighting(goblin);
		sim.tick(2);
		assertTrue(sim.ctx.isInCombat());

		sim.game.animating(PICKPOCKET);
		sim.tick(2);

		assertTrue("combat should still be running its own grace out",
			sim.ctx.isInCombat());
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;
import net.runelite.api.NPC;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.ConfigChanged;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Thrall only: the follower exists while a thrall has it, in any way, and
 * not otherwise. The rule itself is pinned beside the setting's default;
 * what this pins is "in any way", which is the plugin's to decide and which
 * no truth table of the rule can see. The phase-out after the thrall goes
 * and a scene load mid-thrall both still count - hidden on either, the exit
 * is never seen, and a load in the middle of a fight loses the thrall.
 */
public class ThrallOnlyTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static FollowerPlugin plugin(boolean thrallOnly) throws ReflectiveOperationException
	{
		FollowerPlugin plugin = new FollowerPlugin();
		set(plugin, "client", new FakeGame().client);
		set(plugin, "config", new FollowerConfig()
		{
			@Override
			public boolean thrallOnly()
			{
				return thrallOnly;
			}
		});
		return plugin;
	}

	private static boolean hidden(FollowerPlugin plugin) throws ReflectiveOperationException
	{
		Method shouldHide = FollowerPlugin.class.getDeclaredMethod("shouldHide");
		shouldHide.setAccessible(true);
		return (Boolean) shouldHide.invoke(plugin);
	}

	private static void set(Object target, String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(target, value);
	}

	@Test
	public void theReplaceThrallsHintNamesThrallOnlyWhileItIsTicked() throws Exception
	{
		// QA3: "Untick Replace thralls" does nothing with Thrall only on, so
		// with it ticked the hint names both switches (QA4, approved wording).
		String source = PublicMarkers.strip(new String(Files.readAllBytes(
			Paths.get("src/main/java/com/follower/FollowerPlugin.java")), StandardCharsets.UTF_8)
			.replace("\r\n", "\n"));
		int at = source.indexOf("void maybeSendThrallHint()");
		assertTrue("the lint has lost its place", at >= 0);
		String body = source.substring(at, source.indexOf("\n\t}", at));
		assertTrue(body, body.contains("config.thrallOnly()\n\t\t\t? \"Untick Thrall only and Replace thralls"
			+ " in settings to keep your own.\""));
		assertTrue(body, body.contains(": \"Untick Replace thralls in settings to keep your own.\""));
	}

	@Test
	public void absentUntilAThrallHasIt() throws ReflectiveOperationException
	{
		assertTrue("no thrall, no follower", hidden(plugin(true)));

		FollowerPlugin summoned = plugin(true);
		NPC thrall = new FakeGame().spawnNpc(10886, "Greater Zombified Spawn", 0);
		set(summoned, "thrallNpc", thrall);
		assertFalse("a thrall has it", hidden(summoned));

		assertFalse("and the everyday follower is never hidden by the mode", hidden(plugin(false)));
	}

	@Test
	public void thePhaseOutAndASceneLoadStillCountAsTheThrallsBusiness()
		throws ReflectiveOperationException
	{
		FollowerPlugin leaving = plugin(true);
		set(leaving, "thrallExitTicks", 4);
		assertFalse("the phase-out plays where it stands before it goes", hidden(leaving));

		FollowerPlugin waiting = plugin(true);
		set(waiting, "thrallExitPendingTicks", 3);
		assertFalse("a vanished thrall might be a resummon: held a beat", hidden(waiting));

		FollowerPlugin loading = plugin(true);
		set(loading, "thrallLimbo", true);
		assertFalse("a scene load drops the thrall NPC, not the thrall", hidden(loading));
	}

	@Test
	public void turningItOffBuildsTheFollowerAfreshInItsOwnOutfit() throws Exception
	{
		// The mode's login builds no model at all, and its exit leaves the
		// thrall's behind. Turned off, the follower has to come back now, not
		// at the next loading screen, and in its own outfit, not the thrall's.
		FollowerPlugin plugin = plugin(false);
		set(plugin, "speechEngine", new Harness(folder.newFolder().toPath()).engine);
		set(plugin, "follower", new FollowerEntity(null, null));
		set(plugin, "clientThread", new ClientThread()
		{
			@Override
			public void invoke(Runnable r)
			{
				r.run();
			}
		});
		List<Outfit> asked = new ArrayList<>();
		set(plugin, "appearanceService", new AppearanceService(null)
		{
			@Override
			public void invalidate()
			{
				// No capture runs here to abort.
			}

			@Override
			public void request(Outfit outfit, Consumer<ComposedAppearance> onReady)
			{
				asked.add(outfit);
			}
		});

		ConfigChanged changed = new ConfigChanged();
		changed.setGroup(FollowerConfig.GROUP);
		changed.setKey("thrallOnly");
		plugin.onConfigChanged(changed);

		Outfit own = OutfitParser.parse(new FollowerConfig()
		{
		}.customOutfit());
		assertEquals("a model is asked for, in its own outfit",
			Collections.singletonList(own), asked);
	}

	/**
	 * A thrall-only plugin in a game with a thrall beside the player,
	 * speaking through the harness's engine.
	 */
	private static FollowerPlugin summoning(FakeGame game, Harness h, boolean replaceThralls)
		throws ReflectiveOperationException
	{
		FollowerPlugin plugin = new FollowerPlugin();
		set(plugin, "client", game.client);
		set(plugin, "config", new FollowerConfig()
		{
			@Override
			public boolean thrallMode()
			{
				return replaceThralls;
			}

			@Override
			public boolean thrallOnly()
			{
				return true;
			}

			// The one-time Replace thralls hint goes to the chat, which this
			// plugin has none of; it is told already.
			@Override
			public boolean thrallHintShown()
			{
				return true;
			}
		});
		set(plugin, "speechEngine", h.engine);
		set(plugin, "ruleLoader", h.loader);
		set(plugin, "profileStore", new OutfitProfileStore(new Gson()));
		// The body's part runs on the client thread; only the taking is asked about.
		set(plugin, "clientThread", new ClientThread()
		{
			@Override
			public void invoke(Runnable r)
			{
			}
		});
		return plugin;
	}

	private static void adopt(FollowerPlugin plugin, NPC thrall) throws ReflectiveOperationException
	{
		Method adopt = FollowerPlugin.class.getDeclaredMethod("maybeAdoptThrall", NPC.class);
		adopt.setAccessible(true);
		adopt.invoke(plugin, thrall);
	}

	@Test
	public void thrallOnlyTakesTheThrallEvenWithReplaceThrallsOff() throws Exception
	{
		// Thrall only is the replacement and nothing else, so it brings the
		// replacement with it. With Replace thralls off as well, no summon was
		// ever taken, and the follower was hidden for good with no word why.
		FakeGame game = new FakeGame().varbit(12290, 1);
		NPC thrall = game.spawnNpc(10886, "Greater Zombified Spawn", 0);
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(2);

		FollowerPlugin plugin = summoning(game, h, false);
		assertTrue(hidden(plugin));

		adopt(plugin, thrall);
		assertFalse("the summon brings it", hidden(plugin));

		assertFalse("and with both off no thrall is ever taken", FollowerPlugin.replacesThralls(false, false));
	}

	@Test
	public void theVarbitTakesTheThrallEvenWithReplaceThrallsOff() throws Exception
	{
		// A thrall that spawns before the varbit rises is turned away at the
		// spawn, and only the varbit's path can take it. That path asked
		// Replace thralls alone too.
		FakeGame game = new FakeGame();
		game.spawnNpc(10886, "Greater Zombified Spawn", 0);
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(2);

		FollowerPlugin plugin = summoning(game, h, false);
		assertTrue(hidden(plugin));

		game.varbit(12290, 1);
		VarbitChanged risen = new VarbitChanged();
		risen.setVarbitId(12290);
		risen.setValue(1);
		plugin.onVarbitChanged(risen);
		assertFalse("the varbit brings it", hidden(plugin));
	}

	/**
	 * Summons a thrall into thrall-only mode's absence, on an engine the
	 * absent ticks left muted; what was said.
	 */
	private List<Harness.Spoken> summonedFromAbsence(boolean thieving) throws Exception
	{
		FakeGame game = new FakeGame().varbit(12290, 1);
		NPC thrall = game.spawnNpc(10886, "Greater Zombified Spawn", 0);
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(2);
		h.engine.setMuted(true);

		FollowerPlugin plugin = summoning(game, h, true);
		set(plugin, "wasThieving", thieving);
		adopt(plugin, thrall);
		return h.firedBy("thrall-start");
	}

	/** A thrall-mode plugin, Thrall only or not, with Mute the thrall as given. */
	private static FollowerPlugin thrallMode(FakeGame game, Harness h, boolean thrallOnly, boolean muteThrall)
		throws ReflectiveOperationException
	{
		FollowerPlugin plugin = summoning(game, h, true);
		set(plugin, "config", new FollowerConfig()
		{
			@Override
			public boolean thrallOnly()
			{
				return thrallOnly;
			}

			@Override
			public boolean muteThrall()
			{
				return muteThrall;
			}

			// No chat here for the one-time Replace thralls hint.
			@Override
			public boolean thrallHintShown()
			{
				return true;
			}
		});
		return plugin;
	}

	/** Summons, then lets the thrall go ten seconds later; what each end said. */
	private int[] helloAndGoodbye(boolean thrallOnly, boolean muteThrall) throws Exception
	{
		long[] now = {1_000_000L};
		FakeGame game = new FakeGame().varbit(12290, 1);
		NPC thrall = game.spawnNpc(10886, "Greater Zombified Spawn", 0);
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.setClock(() -> now[0]);
		h.gameTicks(2);
		// Thrall only's absent ticks leave the engine muted; the everyday
		// follower's leave it talking.
		h.engine.setMuted(thrallOnly);

		FollowerPlugin plugin = thrallMode(game, h, thrallOnly, muteThrall);
		adopt(plugin, thrall);
		now[0] += 10_000L;
		Method exit = FollowerPlugin.class.getDeclaredMethod("performThrallExit", String.class);
		exit.setAccessible(true);
		exit.invoke(plugin, "melee");
		return new int[]{h.firedBy("thrall-start").size(), h.firedBy("thrall-end").size()};
	}

	@Test
	public void theThrallTalksWheneverTheFollowerMay() throws Exception
	{
		assertArrayEquals("Replace thralls: hello and goodbye", new int[]{1, 1}, helloAndGoodbye(false, false));
		assertArrayEquals("Thrall only: the same", new int[]{1, 1}, helloAndGoodbye(true, false));
	}

	@Test
	public void muteTheThrallKeepsItQuietFromHelloToGoodbye() throws Exception
	{
		assertArrayEquals("Replace thralls, muted: neither end", new int[]{0, 0}, helloAndGoodbye(false, true));
		assertArrayEquals("Thrall only, muted: neither end", new int[]{0, 0}, helloAndGoodbye(true, true));

		// And only as the thrall: the rest of the time it talks as usual.
		assertTrue(FollowerPlugin.thrallKeepsQuiet(true, true));
		assertFalse(FollowerPlugin.thrallKeepsQuiet(true, false));
		assertFalse(FollowerPlugin.thrallKeepsQuiet(false, true));
	}

	@Test
	public void theTickKeepsTheThrallQuietBetweenItsEnds() throws IOException
	{
		// What the thrall says while it fights goes through the tick's mute,
		// glue no harness drives; the tick has to ask, as the thieving lift
		// that says the thieving lines does.
		String source = PublicMarkers.strip(new String(Files.readAllBytes(
			Paths.get("src/main/java/com/follower/FollowerPlugin.java")), StandardCharsets.UTF_8));
		assertTrue("the tick's mute asks",
			source.contains("speechEngine.setMuted(config.muted() || thievingNow || absentNow || thrallQuiet()"));
		assertTrue("and so does the thieving lift",
			source.contains("speechEngine.setMuted(config.muted() || thrallQuiet());"));
	}

	@Test
	public void theSummonIsGreetedAlthoughTheAbsenceMutedTheEngine() throws Exception
	{
		// The summon arrives between ticks, while the mute the last absent
		// tick set is still on. Said under that mute, the hello was lost on
		// every summon and only the goodbye was ever heard.
		assertEquals("the summon ends the absence, and the hello is said",
			1, summonedFromAbsence(false).size());
		assertTrue("but a pocket being worked keeps its silence",
			summonedFromAbsence(true).isEmpty());
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;

/**
 * What a possessed thrall's follower plays when it attacks.
 *
 * <p>The shipped stances now know every staff's melee bash, which is right for
 * a melee follower holding one and wrong for a caster: a magic thrall must keep
 * casting rather than club its target with the staff.
 */
public class ThrallSwingTest
{
	private static final int STAFF_BASH = 419;
	private static final int LEARNED_CAST = 11423;
	private static final int STRIKE = 1162;

	/** The combat tab's weapon categories, as VarbitID.COMBAT_WEAPON_CATEGORY holds them. */
	private static final int SPEAR = 15;
	private static final int STAB_SWORD = 17;
	private static final int STAFF = 18;

	private static final int STAFF_OF_AIR = 1381;
	private static final int DRAGON_DAGGER = 1215;
	private static final int ZAMORAKIAN_HASTA = 11889;

	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void aMagicThrallCastsEvenWhenTheStaffHasABash()
	{
		assertEquals(STRIKE, FollowerPlugin.thrallSwing("magic", 0, STAFF_BASH));
	}

	@Test
	public void aMagicThrallUsesTheCastLearnedWithItsStaff()
	{
		assertEquals(LEARNED_CAST, FollowerPlugin.thrallSwing("magic", LEARNED_CAST, STAFF_BASH));
	}

	@Test
	public void meleeAndRangedUseTheWeaponsSwing()
	{
		assertEquals(STAFF_BASH, FollowerPlugin.thrallSwing("melee", LEARNED_CAST, STAFF_BASH));
		assertEquals(7552, FollowerPlugin.thrallSwing("ranged", 0, 7552));
	}

	@Test
	public void withNoSwingKnownEachStyleHasAPlainOne()
	{
		assertEquals(390, FollowerPlugin.thrallSwing("melee", 0, 0));
		assertEquals(426, FollowerPlugin.thrallSwing("ranged", 0, 0));
	}

	// ----------------------------------------- with the shipped stance library

	private StanceLibrary shipped() throws IOException
	{
		StanceLibrary library = new StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		library.load(folder.newFolder().toPath());
		return library;
	}

	@Test
	public void theFollowerThrowsTheKindOfBlowThePlayersStyleDeals() throws IOException
	{
		// The player's stab, lunge, slash, block on a stab sword: the third
		// button slashes, and the dagger's slash is its own.
		assertEquals(377, FollowerPlugin.thrallSwing(shipped(), "melee", DRAGON_DAGGER, STAB_SWORD, 2, false));
		assertEquals(376, FollowerPlugin.thrallSwing(shipped(), "melee", DRAGON_DAGGER, STAB_SWORD, 0, false));
	}

	@Test
	public void aStaffIsSwungOneHandedWhenTheFollowerHoldsAShield() throws IOException
	{
		StanceLibrary library = shipped();
		assertEquals(STAFF_BASH, FollowerPlugin.thrallSwing(library, "melee", STAFF_OF_AIR, STAFF, 0, false));
		assertEquals(393, FollowerPlugin.thrallSwing(library, "melee", STAFF_OF_AIR, STAFF, 0, true));
	}

	@Test
	public void theHastasCrushIsTwoHandedWithoutAShield() throws IOException
	{
		StanceLibrary library = shipped();
		assertEquals(STAFF_BASH, FollowerPlugin.thrallSwing(library, "melee", ZAMORAKIAN_HASTA, SPEAR, 2, false));
		assertEquals(393, FollowerPlugin.thrallSwing(library, "melee", ZAMORAKIAN_HASTA, SPEAR, 2, true));
	}

	@Test
	public void aCasterWithAStaffAndAShieldStillCasts() throws IOException
	{
		assertEquals(STRIKE, FollowerPlugin.thrallSwing(shipped(), "magic", STAFF_OF_AIR, STAFF, 0, true));
	}
}

package com.follower;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * Which thread the plugin does things on, read from its source: the wiring
 * needs a panel, a client thread, an executor and a config manager, which
 * the harness cannot run (QA pass 4, threading audit).
 */
public class ThreadingGlueTest
{
	private static final Path PLUGIN = Paths.get("src/main/java/com/follower/FollowerPlugin.java");

	private static String source() throws IOException
	{
		assertTrue("cannot read " + PLUGIN, Files.isRegularFile(PLUGIN));
		return PublicMarkers.strip(new String(Files.readAllBytes(PLUGIN), StandardCharsets.UTF_8).replace("\r\n", "\n"));
	}

	private static String method(String signature) throws IOException
	{
		String source = source();
		int start = source.indexOf(signature);
		assertTrue("the plugin has no " + signature + " - the lint has lost its place", start >= 0);
		return source.substring(start, source.indexOf("\n\t}\n", start));
	}

	@Test
	public void aProfileWornByCommandIsTheOneTheDropdownShows() throws IOException
