package com.follower;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * An update has to reach the people who already have the plugin.
 *
 * <p>The old merge only appended rules the file had never seen, so a change to
 * an existing rule reached nobody: retuning the examine echo and writing twenty
 * lines for it changed nothing whatsoever for anyone who already had the
 * plugin. The work shipped and stayed invisible, and the only way to see it was
 * to delete your file.
 *
 * <p>Copying more across is not the fix, because two things look identical from
 * the user's file alone - a line the update ADDED, and a line the player
 * DELETED. Both are lines the bundled file has and theirs does not. So the
 * defaults are kept as they were at the last merge and the question becomes
 * answerable.
 *
 * <p>These tests are built against the REAL bundled rules rather than a toy
 * pair, with the base reconstructed as the previous version genuinely was, so
 * what they prove is what a player's next start actually does.
 */
public class ThreeWayMergeTest
{
	private static final Gson GSON = new Gson();

	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static JsonObject shipped()
	{
		try (InputStream in = RuleLoader.class
			.getResourceAsStream("/com/follower/default-phrases.json"))
		{
			return GSON.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8),
				JsonObject.class);
		}
		catch (Exception e)
		{
			throw new AssertionError(e);
		}
	}

	/**
	 * A rule 1.4.0 shipped exactly as it ships now, with a cooldown, for the
	 * tests that need one nobody has touched. Found rather than named: two
	 * named ones were reworded later and broke these tests each time.
	 */
	private static String unchangedSince140()
	{
		JsonObject now = shipped();
		for (JsonElement e : freshFrom140().getAsJsonArray("rules"))
		{
			JsonObject was = e.getAsJsonObject();
			String id = was.get("id").getAsString();
			if (was.equals(rule(now, id)) && was.has("cooldownMs") && was.has("say")
				&& (!was.has("enabled") || was.get("enabled").getAsBoolean()))
			{
				return id;
			}
		}
		throw new AssertionError("no rule is the same as in 1.4.0");
	}

	private static JsonObject rule(JsonObject file, String id)
	{
		for (JsonElement e : file.getAsJsonArray("rules"))
		{
			if (id.equals(e.getAsJsonObject().get("id").getAsString()))
			{
				return e.getAsJsonObject();
			}
		}
		return null;
	}

	private static List<String> say(JsonObject file, String id)
	{
		List<String> out = new ArrayList<>();
		for (JsonElement line : rule(file, id).getAsJsonArray("say"))
		{
			out.add(line.getAsString());
		}
		return out;
	}

	private static void setSay(JsonObject file, String id, List<String> lines)
	{
		JsonArray say = new JsonArray();
		lines.forEach(say::add);
		rule(file, id).add("say", say);
	}

	private static int chance(JsonObject file, String id)
	{
		for (JsonElement c : rule(file, id).getAsJsonObject("when").getAsJsonArray("conditions"))
		{
			if ("chance".equals(c.getAsJsonObject().get("type").getAsString()))
			{
				return c.getAsJsonObject().get("percent").getAsInt();
			}
		}
		return -1;
	}

	private static void setChance(JsonObject file, String id, int percent)
	{
		for (JsonElement c : rule(file, id).getAsJsonObject("when").getAsJsonArray("conditions"))
		{
			if ("chance".equals(c.getAsJsonObject().get("type").getAsString()))
			{
				c.getAsJsonObject().addProperty("percent", percent);
			}
		}
	}

	/**
	 * The examine echo as it shipped before today: four lines, thirty percent,
	 * once every three minutes. Built from the current file so the rest of it
	 * is exactly what a previous version really held.
	 */
	private static JsonObject previousVersion()
	{
		JsonObject old = shipped();
		setSay(old, "examine-echo", say(old, "examine-echo").subList(0, 4));
		setChance(old, "examine-echo", 30);
		rule(old, "examine-echo").addProperty("cooldownMs", 180000);
		return old;
	}

	/** Runs the merge the way startup does, and hands back the merged file. */
	private JsonObject merge(JsonObject theirs, JsonObject base) throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve(RuleLoader.FILE_NAME),
			GSON.toJson(theirs).getBytes(StandardCharsets.UTF_8));
		if (base != null)
		{
			Files.write(dir.resolve(RuleLoader.BASE_FILE),
				GSON.toJson(base).getBytes(StandardCharsets.UTF_8));
		}
		new RuleLoader(GSON).initialise(dir, true);
		return GSON.fromJson(new String(
			Files.readAllBytes(dir.resolve(RuleLoader.FILE_NAME)), StandardCharsets.UTF_8),
			JsonObject.class);
	}

	@Test
	public void anUpdatedRuleReachesSomebodyWhoAlreadyHasThePlugin() throws Exception
	{
		JsonObject merged = merge(previousVersion(), previousVersion());

		assertEquals("the twenty new lines arrive", 24, say(merged, "examine-echo").size());
		assertEquals("and the retune with them", 70, chance(merged, "examine-echo"));
		assertEquals(30000L,
			rule(merged, "examine-echo").get("cooldownMs").getAsLong());
	}

	@Test
	public void aLineThePlayerDeletedStaysDeleted() throws Exception
	{
		JsonObject base = previousVersion();
		JsonObject theirs = previousVersion();
		List<String> without = new ArrayList<>(say(theirs, "examine-echo"));
		String removed = without.remove(0);
		setSay(theirs, "examine-echo", without);

		JsonObject merged = merge(theirs, base);

		assertFalse("a deletion is a decision, not a stale copy",
			say(merged, "examine-echo").contains(removed));
		assertEquals("while the new lines still arrive", 23,
			say(merged, "examine-echo").size());
	}

	@Test
	public void thePlayersOwnLinesSurviveAndTheNewOnesJoinThem() throws Exception
	{
		JsonObject base = previousVersion();
		JsonObject theirs = previousVersion();
		List<String> plus = new ArrayList<>(say(theirs, "examine-echo"));
		plus.add("A line of my own.");
		setSay(theirs, "examine-echo", plus);

		JsonObject merged = merge(theirs, base);

		assertTrue("their line is still there",
			say(merged, "examine-echo").contains("A line of my own."));
		assertEquals("theirs plus the twenty", 25, say(merged, "examine-echo").size());
	}

	@Test
	public void aValueThePlayerTunedIsTheirsToKeep() throws Exception
	{
		JsonObject base = previousVersion();
		JsonObject theirs = previousVersion();
		rule(theirs, "examine-echo").addProperty("cooldownMs", 600000);
		setChance(theirs, "examine-echo", 5);

		JsonObject merged = merge(theirs, base);

		assertEquals("their cooldown stands", 600000L,
			rule(merged, "examine-echo").get("cooldownMs").getAsLong());
		assertEquals("and their chance", 5, chance(merged, "examine-echo"));
		assertEquals("but the lines are not a setting, and still arrive",
			24, say(merged, "examine-echo").size());
	}

	@Test
	public void aRuleSwitchedOffStaysOff() throws Exception
	{
		JsonObject base = previousVersion();
		JsonObject theirs = previousVersion();
		rule(theirs, "examine-echo").addProperty("enabled", false);

		JsonObject merged = merge(theirs, base);

		assertFalse("silencing a rule is a decision",
			rule(merged, "examine-echo").get("enabled").getAsBoolean());
	}

	@Test
	public void aLineDroppedUpstreamGoes() throws Exception
	{
		// Base holds a line the current bundled file does not: an update
		// removed it, and the player never touched it.
		JsonObject base = previousVersion();
		JsonObject theirs = previousVersion();
		for (JsonObject file : new JsonObject[]{base, theirs})
		{
			List<String> plus = new ArrayList<>(say(file, "examine-echo"));
			plus.add("A line the next version drops.");
			setSay(file, "examine-echo", plus);
		}

		JsonObject merged = merge(theirs, base);

		assertFalse("what an update removes, goes",
			say(merged, "examine-echo").contains("A line the next version drops."));
	}

	@Test
	public void mergingTwiceChangesNothingTheSecondTime() throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve(RuleLoader.FILE_NAME),
			GSON.toJson(previousVersion()).getBytes(StandardCharsets.UTF_8));
		Files.write(dir.resolve(RuleLoader.BASE_FILE),
			GSON.toJson(previousVersion()).getBytes(StandardCharsets.UTF_8));

		new RuleLoader(GSON).initialise(dir, true);
		String once = new String(Files.readAllBytes(dir.resolve(RuleLoader.FILE_NAME)),
			StandardCharsets.UTF_8);
		new RuleLoader(GSON).initialise(dir, true);
		String twice = new String(Files.readAllBytes(dir.resolve(RuleLoader.FILE_NAME)),
			StandardCharsets.UTF_8);

		assertEquals("a merge with nothing to do must do nothing", once, twice);
	}

	// ------------------------------------------------------- the first run

	/**
	 * The rules exactly as 1.4.0 wrote them on a fresh install. Up to 1.4.0 a
	 * fresh install recorded nothing, so its first update had no base.
	 */
	private static JsonObject freshFrom140()
	{
		try (InputStream in = RuleLoader.class
			.getResourceAsStream("/com/follower/seen/1.4.0-phrases.json"))
		{
			return GSON.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8),
				JsonObject.class);
		}
		catch (Exception e)
		{
			throw new AssertionError(e);
		}
	}

	/**
	 * Play test, 28 Sep: a fresh 1.4.0 install with one line deleted from the
	 * axe rule and one harpoon line rewritten. The upgrade had no base and put
	 * the deleted axe line back, because a rule holding only shipped lines
	 * looked untouched.
	 */
	@Test
	public void aFreshInstallFrom140KeepsTheLinesItDeletedAndTheOnesItWrote() throws Exception
	{
		JsonObject theirs = freshFrom140();
		List<String> axe = new ArrayList<>(say(theirs, "gear-axe"));
		String deleted = axe.remove(1);
		setSay(theirs, "gear-axe", axe);
		List<String> harpoon = new ArrayList<>(say(theirs, "gear-harpoon"));
		String rewritten = harpoon.set(1, "TEST!");
		setSay(theirs, "gear-harpoon", harpoon);

		JsonObject merged = merge(theirs, null);

		assertFalse("the deleted line stays deleted", say(merged, "gear-axe").contains(deleted));
		assertTrue(say(merged, "gear-harpoon").contains("TEST!"));
		assertFalse("and the line it replaced stays gone", say(merged, "gear-harpoon").contains(rewritten));
	}

	@Test
	public void aFreshInstallFrom140ThatNobodyEditedBecomesTheNewDefaults() throws Exception
	{
		JsonObject merged = merge(freshFrom140(), null);

		for (JsonElement e : shipped().getAsJsonArray("rules"))
		{
			String id = e.getAsJsonObject().get("id").getAsString();
			// New lines join the end of the old ones; a line is picked at
			// random, so only which lines there are matters.
			assertEquals("every rule's lines as it ships now: " + id,
				String.valueOf(lines(e.getAsJsonObject())), String.valueOf(lines(rule(merged, id))));
			JsonObject want = e.getAsJsonObject().deepCopy();
			JsonObject got = rule(merged, id).deepCopy();
			want.remove("say");
			got.remove("say");
			assertEquals("and everything else: " + id, want, got);
		}
	}

	/** A rule's lines as a sorted set, or null for a rule that says nothing of its own. */
	private static java.util.TreeSet<String> lines(JsonObject rule)
	{
		if (!rule.has("say") || rule.getAsJsonArray("say").size() == 0)
		{
			return null;
		}
		java.util.TreeSet<String> out = new java.util.TreeSet<>();
		rule.getAsJsonArray("say").forEach(line -> out.add(line.getAsString()));
		return out;
	}

	@Test
	public void aRuleSwitchedOffOnAFreshInstallFrom140StaysOff() throws Exception
	{
		String id = unchangedSince140();
		JsonObject theirs = freshFrom140();
		rule(theirs, id).addProperty("enabled", false);

		JsonObject merged = merge(theirs, null);

		assertFalse(rule(merged, id).get("enabled").getAsBoolean());
		assertEquals("brought up to date in every other respect",
			say(shipped(), id), say(merged, id));
	}

	/**
	 * A rule 1.4.0 never shipped has no record to be judged against, so it is
	 * judged by its lines, as every rule once was: one the player wrote into
	 * is theirs.
	 */
	@Test
	public void aRuleTheRecordNeverHadIsLeftAloneOnceWrittenInto() throws Exception
	{
		JsonObject theirs = freshFrom140();
		JsonObject newer = null;
		for (JsonElement e : shipped().getAsJsonArray("rules"))
		{
			if (rule(theirs, e.getAsJsonObject().get("id").getAsString()) == null)
			{
				newer = e.getAsJsonObject().deepCopy();
				break;
			}
		}
		assertTrue("the current defaults have rules 1.4.0 did not", newer != null);
		String id = newer.get("id").getAsString();
		theirs.getAsJsonArray("rules").add(newer);
		List<String> plus = new ArrayList<>(say(theirs, id));
		plus.add("A line of my own.");
		setSay(theirs, id, plus);

		JsonObject merged = merge(theirs, null);

		assertEquals(plus, say(merged, id));
	}

	/**
	 * Review, 28 Sep: a file older than 1.4.0 must not be judged against 1.4.0,
	 * or everything 1.3.0 and 1.4.0 added to its untouched rules looks like
	 * the player deleted it, and never arrives. A 1.2.0 file lacks rules 1.4.0
	 * added, so it is still brought up to date by its lines, as before.
	 */
	@Test
	public void aFileOlderThan130IsStillBroughtUpToDate() throws Exception
	{
		// As 1.2.0 was: without a rule 1.3.0 added, and with fewer lines in a
		// rule 1.3.0 wrote more for without retuning it (eight such rules).
		JsonObject theirs = freshFrom140();
		JsonArray older = new JsonArray();
		for (JsonElement e : theirs.getAsJsonArray("rules"))
		{
			if (!"boss-brutus".equals(e.getAsJsonObject().get("id").getAsString()))
			{
				older.add(e);
			}
		}
		theirs.add("rules", older);
		setSay(theirs, "gear-axe", say(theirs, "gear-axe").subList(0, 1));

		JsonObject merged = merge(theirs, null);

		assertEquals("the lines written since arrive",
			say(shipped(), "gear-axe"), say(merged, "gear-axe"));
	}

	/**
	 * 1.3.0 shipped the same rules as 1.4.0, and 1.4.0 retuned two of them. A
	 * 1.3.0 copy of such a rule no longer matches 1.4.0 outside its lines, so
	 * it is brought up to date by its lines rather than judged as tuned.
	 */
	@Test
	public void aRuleRetunedSince130StillArrives() throws Exception
	{
		String id = unchangedSince140();
		JsonObject theirs = freshFrom140();
		rule(theirs, id).addProperty("cooldownMs", 123456);

		JsonObject merged = merge(theirs, null);

		assertEquals(rule(shipped(), id).get("cooldownMs"),
			rule(merged, id).get("cooldownMs"));
	}

	/** From this version on a fresh install records what it wrote, so there is never a first run to guess on. */
	@Test
	public void aFreshInstallRecordsWhatItWrote() throws Exception
	{
		Path dir = folder.newFolder().toPath();
		new RuleLoader(GSON).initialise(dir, true);

		assertEquals(shipped(), GSON.fromJson(new String(
			Files.readAllBytes(dir.resolve(RuleLoader.BASE_FILE)), StandardCharsets.UTF_8),
			JsonObject.class));

		JsonObject theirs = GSON.fromJson(new String(
			Files.readAllBytes(dir.resolve(RuleLoader.FILE_NAME)), StandardCharsets.UTF_8),
			JsonObject.class);
		List<String> axe = new ArrayList<>(say(theirs, "gear-axe"));
		String deleted = axe.remove(1);
		setSay(theirs, "gear-axe", axe);
		Files.write(dir.resolve(RuleLoader.FILE_NAME),
			GSON.toJson(theirs).getBytes(StandardCharsets.UTF_8));

		new RuleLoader(GSON).initialise(dir, true);

		JsonObject after = GSON.fromJson(new String(
			Files.readAllBytes(dir.resolve(RuleLoader.FILE_NAME)), StandardCharsets.UTF_8),
			JsonObject.class);
		assertFalse(say(after, "gear-axe").contains(deleted));
	}

	@Test
	public void theBaseIsRecordedSoTheGuessworkHappensOnlyOnce() throws Exception
	{
		Path dir = folder.newFolder().toPath();
		Files.write(dir.resolve(RuleLoader.FILE_NAME),
			GSON.toJson(previousVersion()).getBytes(StandardCharsets.UTF_8));
		assertFalse(Files.exists(dir.resolve(RuleLoader.BASE_FILE)));

		new RuleLoader(GSON).initialise(dir, true);

		assertTrue("the defaults are recorded on the way out",
			Files.exists(dir.resolve(RuleLoader.BASE_FILE)));
		JsonObject base = GSON.fromJson(new String(
			Files.readAllBytes(dir.resolve(RuleLoader.BASE_FILE)), StandardCharsets.UTF_8),
			JsonObject.class);
		assertEquals("and they are the ones that just shipped",
			24, say(base, "examine-echo").size());

		// Now a deletion must stick, which it could not have before.
		JsonObject theirs = GSON.fromJson(new String(
			Files.readAllBytes(dir.resolve(RuleLoader.FILE_NAME)), StandardCharsets.UTF_8),
			JsonObject.class);
		List<String> without = new ArrayList<>(say(theirs, "examine-echo"));
		String removed = without.remove(0);
		setSay(theirs, "examine-echo", without);
		Files.write(dir.resolve(RuleLoader.FILE_NAME),
			GSON.toJson(theirs).getBytes(StandardCharsets.UTF_8));

		new RuleLoader(GSON).initialise(dir, true);

		JsonObject after = GSON.fromJson(new String(
			Files.readAllBytes(dir.resolve(RuleLoader.FILE_NAME)), StandardCharsets.UTF_8),
			JsonObject.class);
		assertFalse("with a base, the deletion holds",
			say(after, "examine-echo").contains(removed));
	}

	@Test
	public void aWhollyNewRuleStillArrivesTheWayItAlwaysDid() throws Exception
	{
		JsonObject theirs = previousVersion();
		JsonArray kept = new JsonArray();
		for (JsonElement e : theirs.getAsJsonArray("rules"))
		{
			if (!"boss-brutus".equals(e.getAsJsonObject().get("id").getAsString()))
			{
				kept.add(e);
			}
		}
		theirs.add("rules", kept);

		JsonObject merged = merge(theirs, previousVersion());

		assertTrue("a new rule is still appended",
			rule(merged, "boss-brutus") != null);
	}

	/**
	 * Upgrade test, 21 Oct: a 1.4.1 file kept wilderness-crossing, a rule 1.5.0
	 * dropped (its lines went to enter-wilderness). It could never be heard, but
	 * it sat in the Messages window. A rule an update drops goes, as a dropped
	 * line does, whether the base was recorded or has to be told from 1.4.0.
	 */
	@Test
	public void aRuleDroppedUpstreamGoes() throws Exception
	{
		assertTrue("1.4.0 had it", rule(freshFrom140(), "wilderness-crossing") != null);
		assertTrue("1.5.0 does not", rule(shipped(), "wilderness-crossing") == null);

		assertTrue("gone with no record of the base",
			rule(merge(freshFrom140(), null), "wilderness-crossing") == null);
		assertTrue("and gone with one",
			rule(merge(freshFrom140(), freshFrom140()), "wilderness-crossing") == null);
	}

	/** One the player changed is theirs now, and so is one they wrote. */
	@Test
	public void aDroppedRuleThePlayerChangedOrWroteStays() throws Exception
	{
		JsonObject theirs = freshFrom140();
		List<String> plus = new ArrayList<>(say(theirs, "wilderness-crossing"));
		plus.add("A line of my own.");
		setSay(theirs, "wilderness-crossing", plus);
		JsonObject mine = rule(theirs, "wilderness-crossing").deepCopy();
		mine.addProperty("id", "my-own-rule");
		theirs.getAsJsonArray("rules").add(mine);

		JsonObject merged = merge(theirs, freshFrom140());

		assertTrue("the changed one stays", rule(merged, "wilderness-crossing") != null);
		assertTrue("and their own rule", rule(merged, "my-own-rule") != null);
	}
}

package com.follower;

import java.io.IOException;
import java.time.LocalDate;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The hello after an absence. The away lines and last-time all sit on the
 * login event, and one event has one winner: while the everyday greeting
 * matched every login at a higher priority they lost every pass and never
 * said a word.
 */
public class TimeAwayIsGreetedTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** A login after minutesAway, daysAgo days in, past the arrival arc and off the milestones. */
	private Harness login(int daysAgo, long minutesAway, String lastTime) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().setSessionCount(20);
		h.engine.getContext().setMetOnDay(LocalDate.now().toEpochDay() - daysAgo);
		h.engine.getContext().setMinutesAway(minutesAway);
		h.engine.getContext().restoreLastThing(lastTime);
		h.gameTicks(1);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		h.gameTicks(12);      // the slowest of them rides ten delay ticks
		return h;
	}

	private static int hellos(Harness h)
	{
		int n = 0;
		for (String id : new String[]{"login-greeting", "away-a-while", "last-time",
			"away-a-day", "away-a-long-time"})
		{
			n += h.firedBy(id).size();
		}
		return n;
	}

	@Test
	public void aFewHoursAwayIsSaidInsteadOfTheHello() throws IOException
	{
		Harness h = login(10, 300, "");
		assertEquals(1, h.firedBy("away-a-while").size());
		assertTrue(h.firedBy("login-greeting").isEmpty());
	}

	@Test
	public void aDayAwayAndAWeekAwayHaveTheirOwn() throws IOException
	{
		assertEquals(1, login(10, 2000, "").firedBy("away-a-day").size());
		assertEquals(1, login(10, 20000, "").firedBy("away-a-long-time").size());
	}

	@Test
	public void lastTimeGetsItsShare() throws IOException
	{
		// The rule rolls a chance, so give it a fair number of logins.
		boolean heard = false;
		for (int i = 0; i < 30 && !heard; i++)
		{
			heard = !login(10, 300, "the woodcutting").firedBy("last-time").isEmpty();
		}
		assertTrue("last time is remembered some of the time", heard);
	}

	/**
	 * QA, 15 Oct: at 71, last-time lost every absence of a day or more to
	 * away-a-day (74) and away-a-long-time (78). It sits over them now, and
	 * its own chance roll is what leaves them their share.
	 */
	@Test
	public void lastTimeIsAlsoRememberedAfterDaysAway() throws IOException
	{
		for (long away : new long[]{2000, 20000})
		{
			boolean heard = false;
			boolean plain = false;
			for (int i = 0; i < 40 && !(heard && plain); i++)
			{
				Harness h = login(10, away, "the woodcutting");
				heard |= !h.firedBy("last-time").isEmpty();
				plain |= !h.firedBy(away < 10080 ? "away-a-day" : "away-a-long-time").isEmpty();
			}
			assertTrue("away " + away + ": last time is remembered some of the time", heard);
			assertTrue("away " + away + ": and the away line keeps a share", plain);
		}
	}

	/**
	 * QA, 15 Oct (MikeS: yes): an hour to three away belonged to the everyday
	 * hello, which outranks last-time, so last-time never had them. With
	 * something to remember, last-time has every one of them now.
	 */
	@Test
	public void anHourOrTwoAwayIsRememberedEveryTime() throws IOException
	{
		for (int i = 0; i < 10; i++)
		{
			Harness h = login(10, 90, "the woodcutting");
			assertEquals("last time, every time", 1, h.firedBy("last-time").size());
			assertTrue("instead of the hello", h.firedBy("login-greeting").isEmpty());
		}
		assertEquals("with nothing to remember, the hello",
			1, login(10, 90, "").firedBy("login-greeting").size());
	}

	@Test
	public void aShortBreakOrNoRecordStillGetsTheHello() throws IOException
	{
		assertEquals(1, login(10, 30, "").firedBy("login-greeting").size());
		assertEquals(1, login(10, -1, "").firedBy("login-greeting").size());
	}

	@Test
	public void theFirstWeekKeepsItsOwnVoice() throws IOException
	{
		assertEquals(1, login(1, 300, "").firedBy("login-greeting-new").size());
		assertEquals(1, login(4, 300, "").firedBy("login-greeting-settling").size());
	}

	@Test
	public void oneHelloNotTwo() throws IOException
	{
		for (long away : new long[]{-1, 30, 90, 300, 2000, 20000})
		{
			assertEquals("away " + away, 1, hellos(login(10, away, "the woodcutting")));
		}
	}
	/**
	 * The login as the plugin raises it: the prime armed first, and LOGIN
	 * held until it has taken its baseline. QA, 15 Oct: raised before the
	 * prime, logging in poisoned or in the Wilderness had that standing state
	 * rise on the login pass and take it from the greeting.
	 */
	private Harness loginAsThePluginDoes(java.util.function.Consumer<Harness> standing) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		h.engine.getContext().setSessionCount(20);
		h.engine.getContext().setMetOnDay(LocalDate.now().toEpochDay() - 40);
		h.engine.getContext().setMinutesAway(30);
		standing.accept(h);
		h.engine.primeEdgesOnNextTick();
		h.engine.dispatchAfterPriming(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		h.gameTicks(20);
		return h;
	}

	@Test
	public void standingStateDoesNotTakeTheHello() throws IOException
	{
		Harness wildy = loginAsThePluginDoes(h -> h.game.varbit(5963, 1));
		assertEquals(1, wildy.firedBy("login-greeting").size());
		assertTrue(wildy.firedBy("enter-wilderness").isEmpty());

		Harness poisoned = loginAsThePluginDoes(
			h -> h.game.varp(net.runelite.api.gameval.VarPlayerID.POISON, 5));
		assertEquals(1, poisoned.firedBy("login-greeting").size());
		assertTrue(poisoned.firedBy("status-poisoned").isEmpty());
	}

	/** The plugin arms the prime before it raises LOGIN, and raises it through the wait. */
	@Test
	public void thePluginRaisesLoginAfterThePrime() throws IOException
	{
		String source = PublicMarkers.strip(new String(java.nio.file.Files.readAllBytes(
			java.nio.file.Paths.get("src/main/java/com/follower/FollowerPlugin.java")),
			java.nio.charset.StandardCharsets.UTF_8));
		String login = "TriggerEvent.simple(LOGIN)";
		int at = source.indexOf(login);
		assertTrue("the plugin raises LOGIN", at >= 0);
		assertEquals("once", at, source.lastIndexOf(login));
		String before = source.substring(Math.max(0, at - 1500), at);
		assertTrue("through dispatchAfterPriming",
			before.trim().endsWith("speechEngine.dispatchAfterPriming("));
		assertTrue("after the prime is armed", before.contains("speechEngine.primeEdgesOnNextTick();"));
	}
}

package com.follower;

import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Exercises the per-tick state snapshot against a game that is not running.
 *
 * <p>Everything here is a reading the rules depend on being right: a fight that
 * flickers, an idle counter that never climbs or a run-energy figure that lies
 * all show up as rules firing at the wrong moment, which is very hard to
 * diagnose from inside the game.
 */
public class TriggerContextSimulationTest
{
	private static final class Sim
	{
		final FakeGame game = new FakeGame();
		final TriggerContext ctx = new TriggerContext(game.client);
		int tick;

		void tick(int count)
		{
			for (int i = 0; i < count; i++)
			{
				game.tick(++tick);
				ctx.refresh();
			}
		}
	}

	// ----------------------------------------------------------------- energy

	@Test
	public void runEnergyIsReportedAsARealPercentage()
	{
		Sim sim = new Sim();

		sim.game.energy(10000);
		sim.tick(1);
		assertEquals("full energy is 100 percent", 100, sim.ctx.getEnergyPercent());

		sim.game.energy(5000);
		sim.tick(1);
		assertEquals(50, sim.ctx.getEnergyPercent());

		sim.game.energy(1900);
		sim.tick(1);
		assertEquals(19, sim.ctx.getEnergyPercent());
	}

	/**
	 * The client counts run energy in hundredths of a percent, so anything at or
	 * below 100 is the player almost out of breath - not almost full.
	 */
	@Test
	public void nearlyExhaustedEnergyIsNotReportedAsFull()
	{
		Sim sim = new Sim();

		sim.game.energy(100);
		sim.tick(1);
		assertEquals("one percent of energy left", 1, sim.ctx.getEnergyPercent());

		sim.game.energy(50);
		sim.tick(1);
		assertEquals("half a percent rounds down to nothing", 0, sim.ctx.getEnergyPercent());

		sim.game.energy(0);
		sim.tick(1);
		assertEquals(0, sim.ctx.getEnergyPercent());
	}

	// ----------------------------------------------------------------- combat

	@Test
	public void walkingUpToTalkToSomebodyIsNotAFight()
	{
		// Interacting with a levelled NPC used to be the whole test for
		// combat, and that is also what approaching a guard for directions
		// looks like, and trading, and robbing. The follower announced a
		// battle every time.
		Sim sim = new Sim();
		NPC guard = sim.game.spawnNpc(3269, "Guard", 21);

		sim.game.facing(guard);
		sim.tick(6);

		assertFalse("looking at someone is not fighting them",
			sim.ctx.isInCombat());
	}

	@Test
	public void theFirstBlowStartsTheFightEvenIfNobodyIsFacingBack()
	{
		// The player swings first at something that dies before it can turn
		// round, or cannot reach them at all. Facing plus a landed hit is a
		// fight even without the other side squaring up.
		Sim sim = new Sim();
		NPC goblin = sim.game.spawnNpc(3029, "Goblin", 5);

		sim.game.facing(goblin);
		sim.tick(2);
		assertFalse("no blows yet", sim.ctx.isInCombat());

		sim.ctx.noteDamageDealt();
		sim.tick(1);
		assertTrue("landing one starts it", sim.ctx.isInCombat());
		assertEquals("and the target is named", "Goblin", sim.ctx.getCombatTarget());
	}

	@Test
	public void beingSquaredUpAtIsAFightWithoutAnyDamageYet()
	{
		// The other arming path: both sides facing each other, before either
		// has landed anything.
		Sim sim = new Sim();
		NPC goblin = sim.game.spawnNpc(3029, "Goblin", 5);

		sim.game.fighting(goblin);
		sim.tick(1);

		assertTrue("two sides squared up is a fight", sim.ctx.isInCombat());
	}

	@Test
	public void aFightSurvivesTheGapBetweenTargets()
	{
		Sim sim = new Sim();
		NPC goblin = sim.game.spawnNpc(3029, "Goblin", 5);

		sim.game.fighting(goblin);
		sim.tick(1);
		assertTrue(sim.ctx.isInCombat());
		assertEquals("Goblin", sim.ctx.getCombatTarget());

		// Target dies, nothing is being clicked for a few ticks.
		sim.game.fighting(null);
		sim.tick(5);
		assertTrue("a short gap between targets is still the same fight",
			sim.ctx.isInCombat());

		sim.tick(6);
		assertFalse("but it does end eventually", sim.ctx.isInCombat());
	}

	@Test
	public void beingHitWhileRunningPastIsNotAFight()
	{
		// This test used to assert the opposite - "taking damage is a fight
		// whether or not you joined in" - and a night's transcript at 57%
		// combat, mostly the player getting hit running through aggressive
		// areas, is what that premise sounds like. Every combat line is
		// written for the player's OWN fight, so a hit taken while engaged
		// with nothing is not one.
		Sim sim = new Sim();
		sim.tick(1);
		assertFalse(sim.ctx.isInCombat());

		sim.ctx.noteDamageTaken();
		assertFalse("a hit taken while engaged with nothing is being chased, not fighting",
			sim.ctx.isInCombat());
	}

	@Test
	public void beingHitWhileEngagedIsAFightAtOnce()
	{
		// The other half: facing a levelled NPC and taking a hit from it is
		// two-way by definition, and the fight starts on the first blow rather
		// than waiting for the NPC to turn round - which a boss between phases
		// or an archer at range may never visibly do.
		Sim sim = new Sim();
		NPC goblin = sim.game.spawnNpc(3029, "Goblin", 5);
		sim.game.facing(goblin);
		sim.tick(1);
		assertFalse("facing alone is not a fight yet", sim.ctx.isInCombat());

		sim.ctx.noteDamageTaken();
		assertTrue("a hit while squared up is the fight starting",
			sim.ctx.isInCombat());
	}

	@Test
	public void talkingToSomeoneHarmlessIsNotAFight()
	{
		Sim sim = new Sim();
		NPC banker = sim.game.spawnNpc(1613, "Banker", 0);

		sim.game.fighting(banker);
		sim.tick(2);

		assertFalse("a zero combat level cannot fight back", sim.ctx.isInCombat());
	}

	@Test
	public void aBossIsToldApartFromAnOrdinaryMonster()
	{
		Sim ordinary = new Sim();
		ordinary.game.fighting(ordinary.game.spawnNpc(3029, "Goblin", 5));
		ordinary.tick(1);
		assertFalse(ordinary.ctx.isBossFight());

		Sim boss = new Sim();
		boss.game.fighting(boss.game.spawnNpc(2042, "Zulrah", 725));
		boss.tick(1);
		assertTrue(boss.ctx.isBossFight());
	}

	// ------------------------------------------------------------------- idle

	@Test
	public void standingStillClimbsTheIdleCounterAndMovingResetsIt()
	{
		Sim sim = new Sim();
		sim.tick(5);
		assertTrue("standing still should accumulate", sim.ctx.getIdleTicks() >= 3);

		sim.game.at(3225, 3218, 0);
		sim.tick(1);
		assertEquals("a step resets it", 0, sim.ctx.getIdleTicks());
	}

	@Test
	public void animatingCountsAsBusyEvenWithoutMoving()
	{
		Sim sim = new Sim();
		sim.tick(5);
		assertTrue(sim.ctx.getIdleTicks() > 0);

		sim.game.animating(899);
		sim.tick(1);
		assertEquals("mining on the spot is not idling", 0, sim.ctx.getIdleTicks());
	}

	// ----------------------------------------------------------------- memory

	@Test
	public void pacingAcrossARegionBoundaryIsNotASeriesOfVisits()
	{
		Sim sim = new Sim();
		// Two tiles either side of a region edge, stepped over repeatedly.
		WorldPoint a = new WorldPoint(3200, 3200, 0);
		WorldPoint b = new WorldPoint(3264, 3200, 0);
		assertTrue("test needs two different regions",
			a.getRegionID() != b.getRegionID());

		sim.game.at(a.getX(), a.getY(), 0);
		sim.tick(1);
		for (int i = 0; i < 10; i++)
		{
			sim.game.at(b.getX(), b.getY(), 0);
			sim.tick(1);
			sim.game.at(a.getX(), a.getY(), 0);
			sim.tick(1);
		}

		assertEquals("ten crossings is still one visit to this region",
			1, sim.ctx.getRegionVisits());
	}

	@Test
	public void theDeathSpotStaysQuietUntilWellAfterTheDeath()
	{
		Sim sim = new Sim();
		sim.tick(1);
		sim.ctx.noteDeath(new WorldPoint(3222, 3218, 0));

		sim.tick(5);
		assertFalse("the first person standing at the spot is the one who died",
			sim.ctx.isNearDeathSpot(5));

		sim.tick(250);
		assertTrue("coming back much later is a return", sim.ctx.isNearDeathSpot(5));
	}

	@Test
	public void aDeathOnAnotherFloorIsNotThisSpot()
	{
		Sim sim = new Sim();
		sim.tick(1);
		sim.ctx.noteDeath(new WorldPoint(3222, 3218, 2));
		sim.tick(250);
		assertFalse(sim.ctx.isNearDeathSpot(5));
	}

	// -------------------------------------------------------------- equipment

	@Test
	public void wornItemsAreReadableAndBodyKitsAreNotMistakenForThem()
	{
		Sim sim = new Sim();
		sim.game.wearing(4151, 11832);
		sim.tick(1);

		assertTrue(sim.ctx.isEquipped(4151));
		assertTrue(sim.ctx.isEquipped(11832));
		assertFalse("nothing else should read as worn", sim.ctx.isEquipped(1038));
	}

	// --------------------------------------------------------------- lifecycle

	@Test
	public void refreshingWithNoPlayerIsHarmless()
	{
		FakeGame game = new FakeGame();
		TriggerContext ctx = new TriggerContext(game.client);
		// Logged out: the client has no local player at all.
		game.loggedOut();
		ctx.refresh();

		assertFalse("nothing should have been read", ctx.isPlayerReady());
		assertEquals(100, ctx.getHitpointsPercent());
	}
}

package com.follower;

import java.io.IOException;
import java.time.LocalDate;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * R16: the voice grows familiar with time known.
 *
 * <p>The recurring touchpoints - the login hello and the level-up - carry
 * era-gated siblings: formal on days nought to two, thawing through the
 * first week, and the familiar register from day seven. The formality is in
 * the grammar rather than announced, so what these tests can hold is the
 * gating: the right era answers, and only that one.
 */
public class VoiceGrowsFamiliarTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** The bundled rules, met daysAgo days ago, past the arrival arc. */
	private Harness known(int daysAgo) throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		// Enough sessions that the one-time arrival arc stays out of the way;
		// the eras run on days known, not on session count.
		h.engine.getContext().setSessionCount(5);
		h.engine.getContext().setMetOnDay(LocalDate.now().toEpochDay() - daysAgo);
		h.gameTicks(1);
		return h;
	}

	private void expectGreeting(int daysAgo, String expected) throws IOException
	{
		Harness h = known(daysAgo);
		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.LOGIN));
		h.gameTicks(12);      // the hello rides eight delay ticks

		for (String era : new String[]{
			"login-greeting-new", "login-greeting-settling", "login-greeting"})
		{
			if (era.equals(expected))
			{
				assertEquals(daysAgo + " days in, the hello should be " + era,
					1, h.firedBy(era).size());
			}
			else
			{
				assertTrue(daysAgo + " days in, " + era + " is not this era's voice",
					h.firedBy(era).isEmpty());
			}
		}
	}

	@Test
	public void aBrandNewFollowerIsPolite() throws IOException
	{
		expectGreeting(0, "login-greeting-new");
	}

	@Test
	public void theThawSetsInMidWeek() throws IOException
	{
		expectGreeting(4, "login-greeting-settling");
	}

	@Test
	public void aWeekInTheHelloIsFamiliar() throws IOException
	{
		expectGreeting(10, "login-greeting");
	}

	@Test
	public void congratulationsGrowFamiliarTheSameWay() throws IOException
	{
		Harness young = known(0);
		young.dispatch(TriggerEvent.levelUp("Cooking", 34));
		young.gameTicks(3);
		assertEquals("day nought congratulates formally",
			1, young.firedBy("level-up-new").size());
		assertTrue(young.firedBy("level-up").isEmpty());

		Harness old = known(10);
		old.dispatch(TriggerEvent.levelUp("Cooking", 34));
		old.gameTicks(3);
		assertEquals("ten days in it talks like itself",
			1, old.firedBy("level-up").size());
		assertTrue(old.firedBy("level-up-new").isEmpty());
	}
}

package com.follower;

import java.lang.reflect.Field;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * On a long run over open ground the follower draws level and walks at
 * the player's shoulder; the moment the ground narrows it drops back
 * behind. Only the choice of follow tile is tested here - the path model
 * under it is the one the trace sessions verified and is left alone.
 */
public class WalkingBesideTest
{
	/** Every tile is ground except the ones blocked by name. */
	private static final class OpenGroundFollower extends FollowerEntity
	{
		final Set<WorldPoint> blocked = new HashSet<>();

		OpenGroundFollower()
		{
			super(null, null);
		}

		@Override
		boolean standable(WorldPoint at)
		{
			return at != null && !blocked.contains(at);
		}

		@Override
		boolean canStep(WorldPoint from, int dx, int dy)
		{
			return (dx != 0 || dy != 0)
				&& !blocked.contains(new WorldPoint(from.getX() + dx, from.getY() + dy, from.getPlane()));
		}

		@Override
		public boolean furnished(WorldPoint at)
		{
			return false;
		}
	}

	private OpenGroundFollower follower;
	private long now = 10_000;

	@Before
	public void setUp()
	{
		follower = new OpenGroundFollower();
		follower.setWalksBeside(true);
	}

	/** One step north per observation, and what the follower was told to follow to. */
	private WorldPoint stepNorth(int y)
	{
		WorldPoint previous = new WorldPoint(3200, y - 1, 0);
		WorldPoint current = new WorldPoint(3200, y, 0);
		now += 600;
		return follower.followTileFor(previous, current, previous, 1, now);
	}

	@Test
	public void itTrailsForTheFirstStepsAndThenDrawsLevel()
	{
		for (int i = 1; i < FollowerEntity.BESIDE_AFTER_STEPS; i++)
		{
			assertEquals("behind, step " + i, new WorldPoint(3200, 3400 + i - 1, 0), stepNorth(3400 + i));
			assertFalse(follower.isWalkingBeside());
		}
		WorldPoint at = stepNorth(3400 + FollowerEntity.BESIDE_AFTER_STEPS);
		assertTrue(follower.isWalkingBeside());
		assertEquals("level with them", 3400 + FollowerEntity.BESIDE_AFTER_STEPS, at.getY());
		assertEquals("one to the side", 1, Math.abs(at.getX() - 3200));
	}

	/** The entity's own state, which the stubs here have no other way to set. */
	private void set(String name, Object value)
	{
		try
		{
			Field field = FollowerEntity.class.getDeclaredField(name);
			field.setAccessible(true);
			field.set(follower, value);
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(name, e);
		}
	}

	@Test
	public void itDrawsLevelOnWhicheverSideItIsAlreadyOn()
	{
		// Walking north with the follower a tile east of the line: the right
		// shoulder. Crossing behind the player to reach the left one is the
		// hop the side choice is there to spare it.
		set("tile", new WorldPoint(3201, 3400, 0));
		WorldPoint at = null;
		for (int i = 1; i <= FollowerEntity.BESIDE_AFTER_STEPS; i++)
		{
			at = stepNorth(3400 + i);
		}
		assertTrue(follower.isWalkingBeside());
		assertEquals("the east shoulder", 3201, at.getX());
	}

	@Test
	public void aStayOrAGoalKeepsItBehindHoweverLongTheRun()
	{
		// Only the follow tile changes, and only while nothing else has the
		// feet: a stay or a goal owns them, and the shoulder must not pull
		// against either.
		set("stayTile", new WorldPoint(3200, 3390, 0));
		for (int i = 1; i <= 3 * FollowerEntity.BESIDE_AFTER_STEPS; i++)
		{
			assertEquals("a stay, step " + i, 3200, stepNorth(3400 + i).getX());
		}
		assertFalse(follower.isWalkingBeside());

		set("stayTile", null);
		set("goalTile", new WorldPoint(3205, 3460, 0));
		for (int i = 1; i <= 3 * FollowerEntity.BESIDE_AFTER_STEPS; i++)
		{
			assertEquals("a goal, step " + i, 3200, stepNorth(3430 + i).getX());
		}
		assertFalse(follower.isWalkingBeside());

		// Let go, and the run was long enough all along.
		set("goalTile", null);
		assertEquals(1, Math.abs(stepNorth(3461).getX() - 3200));
		assertTrue(follower.isWalkingBeside());
	}

	@Test
	public void aPauseInTheRunStartsTheCountAgain()
	{
		for (int i = 1; i <= FollowerEntity.BESIDE_AFTER_STEPS; i++)
		{
			stepNorth(3400 + i);
		}
		assertTrue(follower.isWalkingBeside());
		now += FollowerEntity.BESIDE_PAUSE_MS + 1;
		WorldPoint at = stepNorth(3400 + FollowerEntity.BESIDE_AFTER_STEPS + 1);
		assertFalse("they stopped: back behind", follower.isWalkingBeside());
		assertEquals(3200, at.getX());
	}

	@Test
	public void aHedgeDropsItBackBehindAndItWaitsBeforeTryingAgain()
	{
		for (int i = 1; i <= FollowerEntity.BESIDE_AFTER_STEPS; i++)
		{
			stepNorth(3400 + i);
		}
		assertTrue(follower.isWalkingBeside());
		int y = 3400 + FollowerEntity.BESIDE_AFTER_STEPS;
		// A hedge along both flanks for a stretch.
		for (int i = 1; i <= 6; i++)
		{
			follower.blocked.add(new WorldPoint(3199, y + i, 0));
			follower.blocked.add(new WorldPoint(3201, y + i, 0));
		}
		WorldPoint first = stepNorth(y + 1);
		assertEquals("one miss is forgiven", 3200, first.getX());
		assertTrue(follower.isWalkingBeside());
		stepNorth(y + 2);
		assertFalse("two in a row and it drops back", follower.isWalkingBeside());

		int retried = 0;
		for (int i = 3; i <= 6 + FollowerEntity.BESIDE_RETRY_STEPS; i++)
		{
			WorldPoint at = stepNorth(y + i);
			if (at.getX() != 3200)
			{
				retried = i;
				break;
			}
		}
		assertTrue("it tries again once the ground opens, after a few steps: " + retried,
			retried > 6 && retried <= 6 + FollowerEntity.BESIDE_RETRY_STEPS);
	}

	@Test
	public void switchedOffItTrailsHoweverLongTheRun()
	{
		follower.setWalksBeside(false);
		for (int i = 1; i <= 3 * FollowerEntity.BESIDE_AFTER_STEPS; i++)
		{
			assertEquals(3200, stepNorth(3400 + i).getX());
		}
		assertFalse(follower.isWalkingBeside());
	}

	@Test
	public void theFlankIsOneStepToTheSideOfTheLineOfTravel()
	{
		WorldPoint previous = new WorldPoint(10, 10, 0);
		assertEquals("north, left is west", new WorldPoint(9, 11, 0),
			FollowerEntity.flankTile(previous, new WorldPoint(10, 11, 0), 1));
		assertEquals("north, right is east", new WorldPoint(11, 11, 0),
			FollowerEntity.flankTile(previous, new WorldPoint(10, 11, 0), -1));
		assertEquals("east, left is north", new WorldPoint(11, 11, 0),
			FollowerEntity.flankTile(previous, new WorldPoint(11, 10, 0), 1));
		assertEquals("a diagonal run has a diagonal flank", new WorldPoint(10, 12, 0),
			FollowerEntity.flankTile(previous, new WorldPoint(11, 11, 0), 1));
		assertNull(FollowerEntity.flankTile(previous, previous, 1));

		assertEquals("already on the right", -1,
			FollowerEntity.sideOf(previous, new WorldPoint(10, 11, 0), new WorldPoint(11, 9, 0)));
		assertEquals("already on the left", 1,
			FollowerEntity.sideOf(previous, new WorldPoint(10, 11, 0), new WorldPoint(9, 9, 0)));
		assertEquals("on the line: left", 1,
			FollowerEntity.sideOf(previous, new WorldPoint(10, 11, 0), new WorldPoint(10, 9, 0)));
	}
}

package com.follower;

import net.runelite.api.CollisionDataFlag;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The follower must never walk through a wall.
 *
 * <p>Everything else about it is an illusion held up by obeying the same rules
 * as everything else in the world. A model sliding through stone does not look
 * like a bug in the pathing, it looks like the whole thing is fake - which it
 * is, and the point is that you should not be able to tell.
 *
 * <p>The greedy stepper used to end with a raw step "so missing collision data
 * never freezes the follower". But no data already reads as open, so that
 * branch only ever fired when collision was PRESENT and said no. Indoors, where
 * the player is often two tiles away through a partition, it fired constantly.
 */
public class WallPathingTest
{
	private FollowerEntity followerOn(FakeGame game)
	{
		return new FollowerEntity(game.client, null);
	}

	@Test
	public void aWallStopsTheGreedyStepper()
	{
		// Standing at (10,10) wanting (12,10), with a wall on the east edge of
		// (10,10). There is no legal step east, so there is no step at all.
		FakeGame game = new FakeGame().withCollision();
		game.wallAt(10, 10, CollisionDataFlag.BLOCK_MOVEMENT_EAST);
		FollowerEntity follower = followerOn(game);

		WorldPoint from = new WorldPoint(10, 10, 0);
		assertFalse("the wall has to be readable at all",
			follower.canStep(from, 1, 0));
		assertNull("the follower must not step through it",
			follower.stepToward(from, new WorldPoint(12, 10, 0), false));
	}

	@Test
	public void itStepsRoundTheWallWhenThereIsAWayRound()
	{
		// The same wall, but the target is up and to the right, so the stepper
		// has a legal diagonal-turned-cardinal to take instead of giving up.
		FakeGame game = new FakeGame().withCollision();
		game.wallAt(10, 10, CollisionDataFlag.BLOCK_MOVEMENT_EAST);
		FollowerEntity follower = followerOn(game);

		WorldPoint step = follower.stepToward(
			new WorldPoint(10, 10, 0), new WorldPoint(12, 14, 0), false);
		assertNotNull("blocked one way is not blocked every way", step);
		assertTrue("and whatever it picked has to be legal",
			follower.canStep(new WorldPoint(10, 10, 0),
				step.getX() - 10, step.getY() - 10));
	}

	@Test
	public void retracingThePlayersOwnPathMayStepAnyway()
	{
		// The one place the raw step survives. These tiles were walked by the
		// player a moment ago, so a collision reading that disagrees is the
		// reading that is wrong, and refusing would leave the follow tile
		// unknown - which is worse than trusting the footprints.
		FakeGame game = new FakeGame().withCollision();
		game.wallAt(10, 10, CollisionDataFlag.BLOCK_MOVEMENT_EAST);
		FollowerEntity follower = followerOn(game);

		assertNotNull("the player's own path is always walkable",
			follower.stepToward(new WorldPoint(10, 10, 0),
				new WorldPoint(12, 10, 0), true));
	}

	@Test
	public void aFullyBlockedTileIsNeverSteppedOnto()
	{
		FakeGame game = new FakeGame().withCollision();
		game.blockTile(11, 10);
		FollowerEntity follower = followerOn(game);

		WorldPoint from = new WorldPoint(10, 10, 0);
		assertFalse(follower.canStep(from, 1, 0));
		assertNull("a solid tile is not a step",
			follower.stepToward(from, new WorldPoint(11, 10, 0), false));
	}

	@Test
	public void noCollisionDataStillReadsAsOpen()
	{
		// An instance edge, or a scene that has not loaded. Refusing here would
		// freeze the follower for a reason that is not a wall - which is what
		// the raw fallback was originally defending against, and it is already
		// handled without it.
		FakeGame game = new FakeGame();
		FollowerEntity follower = followerOn(game);

		WorldPoint from = new WorldPoint(10, 10, 0);
		assertTrue("no data means no obstacle", follower.canStep(from, 1, 0));
		assertNotNull("so the follower still moves",
			follower.stepToward(from, new WorldPoint(12, 10, 0), false));
	}

	@Test
	public void aWallIsSeenFromBothSides()
	{
		// The game stores a wall on one tile's edge; the tile on the other side
		// carries the opposite bit for the same edge. Checking only the near
		// side would let the follower through half of every wall in the game.
		FakeGame game = new FakeGame().withCollision();
		game.wallAt(11, 10, CollisionDataFlag.BLOCK_MOVEMENT_WEST);
		FollowerEntity follower = followerOn(game);

		assertFalse("approaching from the west",
			follower.canStep(new WorldPoint(10, 10, 0), 1, 0));
		assertFalse("and from the east",
			follower.canStep(new WorldPoint(11, 10, 0), -1, 0));
	}

	@Test
	public void aDiagonalCannotSlipPastACornerPost()
	{
		// Cutting a corner diagonally past two walls that meet is the classic
		// way through a building, and it is exactly what the game forbids.
		FakeGame game = new FakeGame().withCollision();
		game.wallAt(10, 10, CollisionDataFlag.BLOCK_MOVEMENT_EAST);
		game.wallAt(10, 10, CollisionDataFlag.BLOCK_MOVEMENT_NORTH);
		FollowerEntity follower = followerOn(game);

		assertFalse("the corner is shut",
			follower.canStep(new WorldPoint(10, 10, 0), 1, 1));
	}

	// ------------------------------------------------------------- teleports

	/**
	 * Walking obeys the walls; snapping used to ignore them entirely.
	 *
	 * <p>Every teleport, plane change and scene recovery put the follower one
	 * step west of the player by arithmetic alone, and arithmetic does not
	 * know about stone. Play report: the follower teleporting onto tiles it
	 * could not stand on.
	 */
	@Test
	public void aSnapNeverLandsSomewhereItCouldNotWalkTo()
	{
		FakeGame game = new FakeGame().withCollision();
		// The tile a snap wants - one west of the player - is solid.
		game.wallAt(9, 10, CollisionDataFlag.BLOCK_MOVEMENT_FULL);
		FollowerEntity follower = followerOn(game);

		WorldPoint player = new WorldPoint(10, 10, 0);
		WorldPoint wanted = new WorldPoint(9, 10, 0);
		WorldPoint landing = follower.landingTile(wanted, player);

		assertFalse("it landed inside the scenery it was told to land in",
			wanted.equals(landing));
		// Not necessarily adjacent - going round the blocked tile can cost two
		// steps - but it must be somewhere connected to the player rather than
		// a hole on the far side of a wall.
		assertNotNull("whatever it chose has to be walkable ground",
			follower.stepToward(landing, player, false));
	}

	@Test
	public void aTileAThrallCanStandOnIsNotAlwaysOneTheFollowerCan()
	{
		// The gap that outlives possession. A thrall stands behind counters,
		// over water and inside scenery quite legally, and while possessed the
		// follower copies it exactly - correctly, because it IS the thrall.
		// The moment that ends, the same tile is just somewhere it cannot be,
		// so ending the hold there had to stop being unconditional.
		FakeGame game = new FakeGame().withCollision();
		game.wallAt(12, 12, CollisionDataFlag.BLOCK_MOVEMENT_FULL);
		FollowerEntity follower = followerOn(game);

		assertFalse("a solid tile is not somewhere to be left standing",
			follower.standable(new WorldPoint(12, 12, 0)));
		assertTrue("and open ground still is",
			follower.standable(new WorldPoint(10, 10, 0)));
	}

	@Test
	public void aPlayerBoxedInGetsTheirOwnTileShared()
	{
		// Nowhere legal at all: standing on top of the player for a moment is
		// a far smaller lie than standing inside a wall, and their tile is
		// standable by definition because they are standing on it.
		FakeGame game = new FakeGame().withCollision();
		for (int dx = -2; dx <= 2; dx++)
		{
			for (int dy = -2; dy <= 2; dy++)
			{
				if (dx == 0 && dy == 0)
				{
					continue;
				}
				game.wallAt(10 + dx, 10 + dy, CollisionDataFlag.BLOCK_MOVEMENT_FULL);
			}
		}
		FollowerEntity follower = followerOn(game);

		WorldPoint player = new WorldPoint(10, 10, 0);
		assertEquals("with nowhere else to go it must share the player's tile",
			player,
			follower.landingTile(new WorldPoint(9, 10, 0), player));
	}

	/**
	 * Play test, 9 Oct: entering the instance of a Children of the Sun scene
	 * snapped the follower to the tile west of the player, where the scene's
	 * Alina stood. No landing goes inside an NPC, a giant's outer tiles
	 * included.
	 */
	@Test
	public void aLandingIsNeverInsideAnNpc()
	{
		FakeGame game = new FakeGame().withCollision().at(10, 10, 0);
		game.moveNpc(game.spawnNpc(12645, "Alina", 0), 9, 10, 0);
		net.runelite.api.NPC giant = game.spawnNpc(2098, "Hill Giant", 28);
		game.moveNpc(giant, 10, 11, 0).npcSize(giant, 2);
		FollowerEntity follower = followerOn(game);

		WorldPoint player = new WorldPoint(10, 10, 0);
		WorldPoint landing = follower.landingTile(new WorldPoint(9, 10, 0), player);
		assertFalse("not in Alina", new WorldPoint(9, 10, 0).equals(landing));
		assertFalse("not in the giant: " + landing,
			landing.getX() >= 10 && landing.getX() <= 11 && landing.getY() >= 11 && landing.getY() <= 12);
		assertFalse("nor on the player", player.equals(landing));
		assertTrue(follower.standable(landing));
	}

	@Test
	public void aCrowdOnEveryTileStillLands()
	{
		// Unless that is all there is, as with furniture: a crowd round the
		// player still gets the follower beside them, not on top of them.
		FakeGame game = new FakeGame().withCollision().at(10, 10, 0);
		for (int dx = -2; dx <= 2; dx++)
		{
			for (int dy = -2; dy <= 2; dy++)
			{
				if (dx != 0 || dy != 0)
				{
					game.moveNpc(game.spawnNpc(3000, "Bandit", 0), 10 + dx, 10 + dy, 0);
				}
			}
		}
		FollowerEntity follower = followerOn(game);

		WorldPoint player = new WorldPoint(10, 10, 0);
		WorldPoint landing = follower.landingTile(new WorldPoint(9, 10, 0), player);
		assertFalse("not on the player", player.equals(landing));
		assertTrue(follower.standable(landing));
	}

	/**
	 * Aboard a boat the player is in a sub-world laid over the sea, with its
	 * own collision map, and that map is padded: the client stores scene
	 * (x, y) at [x + 1][y + 1]. Read unshifted, every tile answers for its
	 * neighbour, which on a real deck made the facilities read open and the
	 * walkway between them read blocked - so the follower walked the
	 * facilities. The sea's map underneath says nothing about the deck at all.
	 */
	@Test
	public void aboardABoatItReadsTheDecksMapNotTheSeas()
	{
		FakeGame game = new FakeGame().withCollision().aboardBoat();
		game.boatBlocksTile(4, 8);
		FollowerEntity follower = followerOn(game);

		WorldPoint from = new WorldPoint(3, 8, 0);
		assertFalse("the sea's map is open here; the deck's is not, and the deck's is the one that counts",
			follower.canStep(from, 1, 0));
		assertFalse("nor is it a place to stand",
			follower.standable(new WorldPoint(4, 8, 0)));
		assertTrue("the tile next to it is fine, which an unshifted read would deny",
			follower.standable(new WorldPoint(3, 7, 0)));
		assertTrue("and so is the one on the other side",
			follower.standable(new WorldPoint(5, 8, 0)));
	}

	/**
	 * Aboard, the boat is the whole world. The sea beside the hull resolves to
	 * the top-level view, whose map may well read open there - or be missing
	 * altogether, which the follower otherwise treats as open. Neither is a
	 * licence to stand in the water.
	 */
	@Test
	public void aboardABoatTheSeaBesideTheHullIsNotAPlaceToStand()
	{
		FakeGame game = new FakeGame().withCollision().aboardBoat();
		FollowerEntity follower = followerOn(game);

		assertFalse("just past the hull, open on the sea's map",
			follower.standable(new WorldPoint(FakeGame.BOAT_WIDTH, 8, 0)));
		assertFalse("and no stepping off the deck onto it",
			follower.canStep(new WorldPoint(FakeGame.BOAT_WIDTH - 1, 8, 0), 1, 0));
		assertTrue("the deck itself is still fine",
			follower.standable(new WorldPoint(FakeGame.BOAT_WIDTH - 1, 8, 0)));

		FollowerEntity unmapped = followerOn(new FakeGame().withCollision().aboardBoat().seaUnmapped());
		assertFalse("nor where the sea has no map at all",
			unmapped.standable(new WorldPoint(FakeGame.BOAT_WIDTH, 8, 0)));
		assertTrue(unmapped.standable(new WorldPoint(FakeGame.BOAT_WIDTH - 1, 8, 0)));
	}

	/**
	 * Boarding is a jump into a world whose map is still filling in. The
	 * follower lands the instant the player's coordinates change, and the
	 * deck's facilities reach the map over the ticks after, so the tile it
	 * landed on can turn into a cannon underneath it. Aboard, that is a
	 * reason to move. So it is on land (play test, 7 Oct: a bank booth).
	 */
	@Test
	public void aboardABoatAFacilityArrivingUnderfootIsAReasonToMove()
	{
		FakeGame game = new FakeGame().withCollision().aboardBoat();
		FollowerEntity follower = followerOn(game);
		WorldPoint landed = new WorldPoint(3, 8, 0);

		assertFalse("an open deck tile is fine to stand on",
			follower.blockedUnderfoot(landed, game.player));
		game.boatBlocksTile(3, 8);
		assertTrue("until the facility arrives on it",
			follower.blockedUnderfoot(landed, game.player));
	}

	/**
	 * Play test, 7 Oct: the follower was found standing in a bank booth,
	 * twice. Placed while the area was still loading, it read a map that did
	 * not show the booth, and on land nothing ever looked at its own tile
	 * again.
	 */
	@Test
	public void aFollowerLeftInABankBoothIsMovedOut()
	{
		FakeGame game = new FakeGame().withCollision().at(10, 10, 0);
		for (int y = 7; y <= 13; y++)
		{
			// The row of booths, west of the player.
			game.wallAt(9, y, CollisionDataFlag.BLOCK_MOVEMENT_OBJECT);
		}
		FollowerEntity follower = followerOn(game);
		WorldPoint player = new WorldPoint(10, 10, 0);
		WorldPoint booth = new WorldPoint(9, 10, 0);

		assertFalse("a booth is not floor", follower.standable(booth));
		assertTrue("so standing in one is a reason to move", follower.blockedUnderfoot(booth, game.player));
		WorldPoint out = follower.landingTile(booth, player);
		assertTrue("and where it moves to is floor: " + out, follower.standable(out));

		game.gameState(GameState.LOADING);
		assertFalse("but not judged from a map still loading", follower.blockedUnderfoot(booth, game.player));
		game.gameState(GameState.LOGGED_IN);
		game.wallAt(10, 10, CollisionDataFlag.BLOCK_MOVEMENT_OBJECT);
		assertFalse("and never moved off the player's own tile", follower.blockedUnderfoot(player, game.player));
	}

	/**
	 * The placements made from the frame callback, which runs while an area
	 * is still loading too, wait for it to load: then the map is the new
	 * area's, and a booth beside the player reads as a booth. The frame loop
	 * needs a live client, so the guards are read out of the source.
	 */
	@Test
	public void noPlacementIsMadeFromAMapStillLoading() throws java.io.IOException
	{
		String source = PublicMarkers.strip(new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(
			"src/main/java/com/follower/FollowerEntity.java")),
			java.nio.charset.StandardCharsets.UTF_8).replace("\r\n", "\n"));
		assertTrue("logged in means the game state says so",
			source.contains("return client.getGameState() == GameState.LOGGED_IN;"));
		assertTrue("the teleport landing waits for the area to load",
			source.contains("if (loggedIn() && (landed || now - vanishedAtMs > 8000))"));
		assertTrue("so does the leash and plane snap",
			source.contains("if (!loggedIn())\n\t\t\t\t// Snapped from real data once the area has loaded.\n\t\t\t\treturn;"));
		assertTrue("and the hidden-object watchdog, through the recovery's own guard",
			source.contains("if (!object.isActive() && !hiddenForNpcOverlap)\n\t\t\trecoverPosition(")
				&& source.contains("if (!loggedIn() || playerTile != null && snapBeside(playerTile"));
	}

	/**
	 * A cutscene's hold is a stay, and a stay faces the player: asked second,
	 * the follower stared at the player all scene instead of looking where
	 * they look. The facing needs a live client, so the order is read. Both
	 * of the frame's facings of a hold now ask through faceTheHold
	 * (SceneExtraTest).
	 */
	@Test
	public void aSceneIsLookedAtBeforeAStayIsFaced() throws java.io.IOException
	{
		String source = PublicMarkers.strip(new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(
			"src/main/java/com/follower/FollowerEntity.java")),
			java.nio.charset.StandardCharsets.UTF_8).replace("\r\n", "\n"));
		int start = source.indexOf("void faceTheHold(");
		int scene = source.indexOf("if (watchingWithThePlayer)", start);
		int stay = source.indexOf("faceStayAnchor();", start);
		assertTrue("the lint has lost its place", start >= 0 && scene >= 0 && stay >= 0);
		assertTrue("the scene is asked first", scene < stay);
	}

	/** The two open booths of the Lumbridge row; see {@link #lumbridgeBank}. */
	private static final java.util.List<WorldPoint> BOOTHS = java.util.Arrays.asList(
		new WorldPoint(9, 11, 0), new WorldPoint(10, 11, 0));

	/**
	 * The top-floor bank of Lumbridge castle, laid out as the dump found it,
	 * on one floor here: the player at (10,10) south of the row, the closed
	 * booths at either end solid, the two open ones between them, and the
	 * floor behind the row blocked.
	 */
	private static FakeGame lumbridgeBank()
	{
		FakeGame game = new FakeGame().withCollision().at(10, 10, 0);
		game.blockTile(8, 11).blockTile(11, 11);
		for (int x = 8; x <= 11; x++)
		{
			game.blockTile(x, 12);
		}
		// The Bank booth and its neighbour: placed as type 10, 224 tall.
		return game.furniture(9, 11, 0, 10, 0, 224).furniture(10, 11, 0, 10, 0, 224);
	}

	/**
	 * Play test, 8 Oct: logging in at the top-floor bank of Lumbridge castle
	 * put the follower inside a bank booth, on a fully loaded map. Two booths
	 * in that row ignore collision and the floor under them is not blocked,
	 * so the map reads them open while the booth's model fills the tile.
	 */
	@Test
	public void aBoothTheMapCallsOpenIsStillNoPlaceToBePut()
	{
		FakeGame game = lumbridgeBank();
		FollowerEntity follower = followerOn(game);
		WorldPoint player = new WorldPoint(10, 10, 0);

		assertTrue("the map really does call the booth open", follower.standable(BOOTHS.get(1)));

		// Facing south, as after a login, behind is the booth straight north;
		// facing south-east it is the other one.
		for (int jau : new int[]{0, 1792})
		{
			WorldPoint behind = follower.restingTileBehind(game.turned(jau).player, 2);
			assertNotNull(behind);
			assertFalse("facing " + jau + " it was put in a booth: " + behind, BOOTHS.contains(behind));
			assertTrue(follower.standable(behind));
		}

		for (WorldPoint booth : BOOTHS)
		{
			WorldPoint landing = follower.landingTile(booth, player);
			assertFalse("told to land in a booth, it landed in one: " + landing, BOOTHS.contains(landing));
			assertTrue(follower.standable(landing));
			assertFalse("and not on the player", player.equals(landing));
		}
	}

	/**
	 * Play test, 8 Oct, the same bank: with the placement kept out of the
	 * booth, the follower wandered into it. Everything that picks somewhere
	 * for it to stand ends in a stay - the wander and its drift over to the
	 * banker behind the counter, the seats, the errands, the moments - and
	 * the look over the shoulder and the welfare check walk to the tile in
	 * front of the player, which at a bank is the booth they face.
	 */
	@Test
	public void nothingTheFollowerPicksForItselfEndsInTheBooth()
	{
		FakeGame game = lumbridgeBank();
		FollowerEntity follower = followerOn(game);
		// Following, at rest beside the player.
		standOn(follower, new WorldPoint(11, 9, 0));

		// Every tile a wander or a drift could aim at: the drift goes beside
		// something within six tiles, and the wander six at the most. A stay
		// is planned, not walked, so each starts from the same place.
		for (int x = 10 - 7; x <= 10 + 7; x++)
		{
			for (int y = 10 - 7; y <= 10 + 7; y++)
			{
				WorldPoint target = new WorldPoint(x, y, 0);
				if (follower.stayAt(target))
				{
					assertFalse("sent to " + target + ", it came to rest in the booth at "
						+ follower.getStayTile(), BOOTHS.contains(follower.getStayTile()));
				}
			}
		}
		for (WorldPoint booth : BOOTHS)
		{
			assertFalse("a seat chosen by the steps it takes", follower.arrivesAt(booth));
		}

		assertFalse("facing the booth, in front of them is no place to stand",
			follower.moveToFront(game.turned(1024).player));
	}

	/**
	 * A Send at the booth is the player's own choice, and their rule is the
	 * same: they mean over there, not into that, so it lands beside the
	 * booth as it does beside a fire, rather than being refused.
	 */
	@Test
	public void aSendAtTheBoothLandsBesideIt()
	{
		FakeGame game = lumbridgeBank();
		FollowerEntity follower = followerOn(game);
		standOn(follower, new WorldPoint(11, 9, 0));
		Will will = new Will(game.client, follower, event -> { }, () -> true);

		for (WorldPoint booth : BOOTHS)
		{
			assertTrue("sent at the booth at " + booth + ", it goes", will.send(booth));
			assertFalse("but not into it: " + follower.getStayTile(),
				BOOTHS.contains(follower.getStayTile()));
		}
	}

	/**
	 * Crops count as furniture, and a field is nothing else. Sent from among
	 * them to the field's edge, the tiles round the spot nearest the follower
	 * are crops too; it is the open ground past them that it lands on.
	 */
	@Test
	public void aSendToTheEdgeOfAFieldLandsClearOfTheCrops()
	{
		FakeGame game = new FakeGame().withCollision().at(10, 10, 0);
		for (int x = 12; x <= 16; x++)
		{
			for (int y = 8; y <= 12; y++)
			{
				game.furniture(x, y, 0, 10, 0, 90);
			}
		}
		FollowerEntity follower = followerOn(game);
		standOn(follower, new WorldPoint(14, 10, 0));
		Will will = new Will(game.client, follower, event -> { }, () -> true);

		assertTrue("sent to the field's edge, it goes", will.send(new WorldPoint(16, 10, 0)));
		assertFalse("and stops out of the crops: " + follower.getStayTile(),
			follower.furnished(follower.getStayTile()));
	}

	/**
	 * The bank errand walks to the booth itself, and closest approach stops
	 * it in front. A booth the map calls open is walked into instead, which
	 * the feet refuse, and the errand was lost at that bank; it stands in
	 * front of the booth there too.
	 */
	@Test
	public void theBankErrandStandsInFrontOfABoothTheMapCallsOpen()
	{
		FakeGame game = lumbridgeBank().placeObject(9030, "Bank booth", 9, 11, 0);
