package com.follower;

import java.io.IOException;
import java.util.HashSet;
import java.util.Set;
import java.util.TreeSet;
import net.runelite.api.coords.WorldPoint;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The follower asking for something, and what happens either way.
 *
 * <p>Everything else in the rule set runs one direction: something happened,
 * and a line remarks on it. A want runs the other way, which is why it gets its
 * own tests - the failure modes are different. A want that can never be
 * fulfilled (a region no rule has heard of) is silent rather than broken, and a
 * want whose label names a different place from its region is worse than
 * silent, because it fires and lies.
 */
public class WantsTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private Set<Integer> regionsOf(Condition condition)
	{
		Set<Integer> found = new TreeSet<>();
		if (condition != null)
		{
			if (condition.regions != null)
			{
				condition.regions.stream().filter(java.util.Objects::nonNull).forEach(found::add);
			}
			if (condition.conditions != null)
			{
				condition.conditions.forEach(child -> found.addAll(regionsOf(child)));
			}
		}
		return found;
	}

	@Test
	public void everyWantPointsAtAPlaceTheRuleSetKnows() throws IOException
	{
		// A want naming a region no area rule claims is a want that can only
		// ever expire - it would look like the follower asking for somewhere
		// imaginary and then sulking about not being taken there.
		Harness h = new Harness(folder.newFolder().toPath());

		Set<Integer> claimed = new HashSet<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			if ("area".equals(rule.group))
			{
				claimed.addAll(regionsOf(rule.when));
			}
		}

		for (SpeechRule rule : h.loader.getRules())
		{
			if (rule.want == null)
			{
				continue;
			}
			assertTrue(rule.id + " wants region " + rule.want.region
					+ ", which no area rule has ever heard of",
				claimed.contains(rule.want.region));
			assertTrue(rule.id + " must say where it is asking to go",
				rule.want.label != null && !rule.want.label.isEmpty());
			assertTrue(rule.id + " must give the player time to get there",
				rule.want.minutes != null && rule.want.minutes >= 5);
		}
	}

	@Test
	public void askingAndBeingTakenThereIsTheWholeLoop() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		// Somewhere that is not one of the places it can ask for. The default
		// tile is region 12850, which IS Lumbridge - and a want for where you
		// already are is refused, so from there the ask sometimes goes nowhere.
		h.game.at(3000, 3000, 0);
		h.gameTicks(1);

		// The question, then the answer, then the ask. Which place it names is
		// a chance roll between three rules, so this may take a couple of goes.
		for (int i = 0; i < 20 && !h.engine.getContext().isWanting(); i++)
		{
			h.engine.getContext().noteQuestion("want-outing");
			h.answers("yes", "want-outing");
			h.gameTicks(5);
		}
		assertTrue("saying yes should get the follower to name somewhere",
			h.engine.getContext().isWanting());
		String asked = h.engine.getContext().getWantLabel();
		assertFalse("and it has to be somewhere in particular", asked.isEmpty());

		// Lumbridge, the Grand Exchange or the Fishing Guild, whichever won.
		SpeechRule winner = null;
		for (SpeechRule rule : h.loader.getRules())
		{
			if (rule.want != null && asked.equals(rule.want.label))
			{
				winner = rule;
			}
		}
		assertFalse("the label has to belong to a real want rule", winner == null);

		int region = winner.want.region;
		h.game.at((region >> 8) << 6, (region & 0xFF) << 6, 0);
		assertEquals("the test tile has to be inside the wanted region", region,
			new WorldPoint((region >> 8) << 6, (region & 0xFF) << 6, 0).getRegionID());

		h.clear();
		// want-fulfilled rolls a two-to-five tick delay, so four ticks leaves it
		// pending a quarter of the time. Comfortably past the longest roll.
		h.gameTicks(10);
		// Either the place-specific arrival or the generic fallback: which one
		// depends on whether that place has a line of its own, and both are a
		// correct answer to having been taken there.
		assertFalse("going where it asked is the whole point",
			h.firedBy("want-fulfilled").isEmpty()
				&& h.firedBy("want-fulfilled-" + winner.id.substring("want-".length())).isEmpty());
		assertTrue("and the want is spent", !h.engine.getContext().isWanting());
	}

	@Test
	public void beingTakenThereIsTheBiggestMoodSwingInTheFile() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		int before = h.engine.getContext().getMood();

		int best = 0;
		for (SpeechRule rule : h.loader.getRules())
		{
			if (rule.mood != null && rule.mood > best)
			{
				best = rule.mood;
			}
		}
		SpeechRule fulfilled = h.rule("want-fulfilled");
		assertEquals("nothing should please the follower more than being listened to",
			best, (int) fulfilled.mood);
		// Mood bands are twenty points wide, so a swing smaller than that could
		// leave the follower in the same band it was already in - delighted in
		// a way nothing about it actually showed.
		assertTrue("the lift has to be big enough to change the band it is in",
			fulfilled.mood >= 20);
		assertTrue("and it starts somewhere it can climb from", before < 100);
	}

	@Test
	public void aWantThatLapsesIsADisappointmentNotASulk() throws IOException
	{
		Harness h = new Harness(folder.newFolder().toPath());
		SpeechRule expired = h.rule("want-expired");
		SpeechRule fulfilled = h.rule("want-fulfilled");

		assertTrue("the drop for being ignored has to be survivable",
			expired.mood != null && expired.mood > -15);
		assertTrue("and smaller than the lift for being listened to",
			Math.abs(expired.mood) < fulfilled.mood);
	}

	@Test
	public void takingTheFloorKeepsEverythingElseQuietForAWhile() throws IOException
	{
		// The engine mechanism on its own. The harness runs with no global
		// speech gap, so without the floor the second line would come straight
		// out - which is what makes this bite.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"important\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"hushMs\": 5000, \"when\": {\"type\": \"examined\"},"
				+ " \"say\": [\"listen to me\"]},"
				+ "{\"id\": \"chatter\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"unrelated\"]}]}");
		h.gameTicks(1);

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertFalse("the rule taking the floor says its line",
			h.firedBy("important").isEmpty());

		h.dispatch(TriggerEvent.death());
		assertTrue("and nothing else gets a word in while it holds it",
			h.firedBy("chatter").isEmpty());
	}

	@Test
	public void theRuleTakingTheFloorIsNotHeldBackByWhatSpokeBeforeIt() throws IOException
	{
		// The same failure from the other end, and the one that actually bit:
		// an area line a second earlier would drop the arrival line entirely on
		// the global speech gap, so the moment worth having was the one lost.
		Harness h = new Harness(folder.newFolder().toPath(),
			"{\"version\": 1, \"rules\": ["
				+ "{\"id\": \"important\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"hushMs\": 5000, \"when\": {\"type\": \"examined\"},"
				+ " \"say\": [\"listen to me\"]},"
				+ "{\"id\": \"chatter\", \"group\": \"t\", \"cooldownMs\": 0,"
				+ " \"when\": {\"type\": \"playerDeath\"}, \"say\": [\"unrelated\"]}]}");
		h.engine.setGlobalCooldownMs(3000L);
		h.gameTicks(1);

		h.dispatch(TriggerEvent.death());
		assertFalse("something ordinary speaks first", h.firedBy("chatter").isEmpty());

		h.dispatch(TriggerEvent.simple(TriggerEvent.Type.EXAMINED));
		assertFalse("the important line must not be eaten by the gap",
			h.firedBy("important").isEmpty());
	}

	@Test
	public void arrivingWhereItAskedIsOneThoughtAndNotTwo() throws IOException
	{
		// Walking into the wanted region makes the arrival rule and the area
		// rule true on the same pass. Only one can win, and both are evaluated
		// in the WANT_FULFILLED dispatch, so the area rule's rising edge is
		// consumed there without firing - it is not that it loses later, it is
		// that its one chance was spent on a dispatch it did not win.
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.at(3000, 3000, 0);
		h.gameTicks(2);
		h.engine.getContext().setWant(12850, "Lumbridge", 20);

		// Into Lumbridge: region 12850, which area-lumbridge also watches.
		h.game.at(12850 >> 8 << 6, (12850 & 0xFF) << 6, 0);
		assertEquals("the test tile has to be Lumbridge", 12850,
			new WorldPoint(12850 >> 8 << 6, (12850 & 0xFF) << 6, 0).getRegionID());
		h.clear();
		h.gameTicks(12);

		assertFalse("the arrival it asked for has to survive the region change",
			h.firedBy("want-fulfilled-lumbridge").isEmpty());
		assertTrue("and the area line must not talk over it",
			h.firedBy("area-lumbridge").isEmpty());
	}

	@Test
	public void theArrivalLineSaysWhyRatherThanOnlyThankYou() throws IOException
	{
		// A place-specific line for every place a want can ask for. Thanking
		// you for going somewhere is politeness; saying why THAT place is a
		// preference, and a preference is the thing that reads as a mind.
		Harness h = new Harness(folder.newFolder().toPath());
		for (SpeechRule rule : h.loader.getRules())
		{
			if (rule.want == null)
			{
				continue;
			}
			String expected = "want-fulfilled-" + rule.id.substring("want-".length());
			SpeechRule arrival = h.rule(expected);
			assertTrue(expected + " must beat the generic want-fulfilled",
				arrival.priority > h.rule("want-fulfilled").priority);
			assertTrue(expected + " must take the floor like the generic one does",
				arrival.hushMs != null && arrival.hushMs > 0);
		}
	}

	@Test
	public void holdingTheFloorDoesNotSilenceTheOneHoldingIt() throws IOException
	{
		// The obvious way to get this wrong: a rule caught by its own hush,
		// which would make the feature silence exactly the line it exists for.
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);

		assertTrue(h.engine.force("want-fulfilled-lumbridge"));
		assertFalse("the rule holding the floor still speaks",
			h.firedBy("want-fulfilled-lumbridge").isEmpty());

		// And an animation-only rule is movement rather than chatter, so the
		// hush is not meant to stop it. A 20-29 hit is the band nothing is said
		// about, so flinch-big-hit is the only rule in the running.
		h.clear();
		h.dispatch(TriggerEvent.damageTaken(25));
		h.gameTicks(2);
		assertFalse("the flinch is not speech and must not be hushed",
			h.firedBy("flinch-big-hit").isEmpty());
	}

	@Test
	public void forcingARuleRunsTheWholeRuleAndNotJustTheWords() throws IOException
	{
		// ::follower fire exists because several rules only happen on a small
		// roll after a minute of standing still. It is worth nothing if it
		// only says the line: the point of forcing ask-outing is to get the
		// question WINDOW open so the answer can be tested.
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.at(3000, 3000, 0);
		h.gameTicks(1);

		assertFalse("nothing has been asked", h.engine.getContext().isAwaitingAnswer());
		assertTrue("the rule has to exist to be forced", h.engine.force("ask-outing"));
		assertTrue("forcing a rule marked asks must open the window",
			h.engine.getContext().isAwaitingAnswer());
		assertEquals("and must arm the tree that answers it",
			"want-outing", h.engine.getContext().getAskedTree());
		assertFalse("and it must actually have said something",
			h.firedBy("ask-outing").isEmpty());

		assertFalse("a rule that does not exist reports as much",
			h.engine.force("no-such-rule"));
	}

	@Test
	public void forcingIgnoresTheCooldownThatWouldNormallyHoldItBack() throws IOException
	{
		// ask-outing has a fifteen minute cooldown. A test tool that respected
		// it would be useless the second time you reached for it.
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.at(3000, 3000, 0);
		h.gameTicks(1);

		h.engine.force("examined");
		h.engine.force("examined");
		assertTrue("forcing twice in a row has to work twice",
			h.firedBy("examined").size() >= 2);
	}

	@Test
	public void aWorldHopDoesNotThrowAwayWhatTheFollowerKnows() throws IOException
	{
		// Hopping shared a branch with logging out, so it nulled the whole
		// state snapshot. That cost a want every time somebody changed worlds
		// on the way somewhere - which, going to the Grand Exchange, is most
		// of the time - and counted the hop as another session together.
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.at(3000, 3000, 0);
		h.gameTicks(2);

		h.engine.getContext().setWant(12850, "Lumbridge", 20);
		h.engine.getContext().adjustMood(30);
		h.engine.getContext().tally("kill:rat");
		h.engine.getContext().setSessionCount(7);

		h.engine.resetForNewScene();

		assertTrue("a hop must not lose the want", h.engine.getContext().isWanting());
		assertEquals("nor where it was for", "Lumbridge",
			h.engine.getContext().getWantLabel());
		assertEquals("nor the mood", 80, h.engine.getContext().getMood());
		assertEquals("nor the tallies", 1, h.engine.getContext().getTally("kill:rat"));
		assertEquals("nor how many days you have done this",
			7, h.engine.getContext().getSessionCount());

		// And the want still resolves afterwards, which is the whole point.
		h.game.at(12850 >> 8 << 6, (12850 & 0xFF) << 6, 0);
		h.gameTicks(10);
		assertFalse("the want has to survive intact enough to fulfil",
			h.firedBy("want-fulfilled-lumbridge").isEmpty());
	}

	@Test
	public void loggingOutDoesThrowItAway() throws IOException
	{
		// The other half. A follower still holding you to a promise from
		// yesterday, made in a session it cannot remember, would be strange.
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.at(3000, 3000, 0);
		h.gameTicks(2);
		h.engine.getContext().setWant(12850, "Lumbridge", 20);

		h.engine.reset();
		assertFalse("a real session end clears the want",
			h.engine.getContext().isWanting());
	}

	@Test
	public void itDoesNotAskToBeTakenWhereItAlreadyIs() throws IOException
	{
		// Being delighted about arriving somewhere you never left is not a wish.
		Harness h = new Harness(folder.newFolder().toPath());
		h.gameTicks(1);
		int here = h.engine.getContext().getRegionId();

		h.engine.getContext().setWant(here, "right here", 20);
		assertFalse("a want for where we are standing must be refused",
			h.engine.getContext().isWanting());

		h.engine.getContext().setWant(here + 1, "somewhere else", 20);
		assertTrue("somewhere we are not is a real want",
			h.engine.getContext().isWanting());
	}

	@Test
	public void goingSomewhereElseDoesNotCountAsGoingWhereItAsked() throws IOException
	{
		// The whole value of a want is that it names ONE place. A fulfilment
		// that fires on any region change would make the follower delighted
		// with wherever you were already heading, which is flattery rather
		// than being listened to - and it would look identical from outside
		// until you noticed it was never wrong.
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.at(3000, 3000, 0);
		h.gameTicks(1);
		h.engine.getContext().setWant(12850, "Lumbridge", 20);

		// Region 12598, which is not 12850.
		h.game.at(12598 >> 8 << 6, (12598 & 0xFF) << 6, 0);
		h.gameTicks(10);

		assertTrue("the wrong town must not satisfy it",
			h.firedBy("want-fulfilled").isEmpty());
		assertTrue("and the want has to still be open",
			h.engine.getContext().isWanting());
	}

	@Test
	public void onlyOneThingCanBeWantedAtATime() throws IOException
	{
		// Two open wants would make going anywhere satisfy something, which is
		// the same as satisfying nothing.
		Harness h = new Harness(folder.newFolder().toPath());
		h.game.at(3000, 3000, 0);
		h.gameTicks(1);
		h.engine.getContext().setWant(12850, "Lumbridge", 20);
		h.engine.getContext().setWant(12598, "the Grand Exchange", 20);

		assertEquals("the second ask must not quietly replace the first",
			"Lumbridge", h.engine.getContext().getWantLabel());
	}

	@Test
	public void thereAreEnoughPlacesToRollATasteFrom() throws IOException
	{
		// The trait roll draws liked and disliked regions from the regions the
		// rule set already has opinions about. Too small a pool and the roll
		// silently never happens, so no follower ever has a taste.
		Harness h = new Harness(folder.newFolder().toPath());
		Set<Integer> pool = new TreeSet<>();
		for (SpeechRule rule : h.loader.getRules())
		{
			pool.addAll(regionsOf(rule.when));
		}
		assertTrue("a taste rolled from " + pool.size() + " places would barely differ"
			+ " between two followers", pool.size() >= 20);
	}
}

package com.follower;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The beat before yes: a Send with a misgiving in it stops at the edge and
 * looks back first, and a parked follower walked straight at steps aside
 * at the last tick, not before.
 */
public class WillTest
{
	/** Records stays; every tile is ground, every step legal. */
	private static final class ParkedFollower extends FollowerEntity
	{
		WorldPoint tile = new WorldPoint(3200, 3400, 0);
		WorldPoint stayingAt;
		WorldPoint facing;
		final List<WorldPoint> stays = new ArrayList<>();
		boolean settled = true;

		ParkedFollower()
		{
			super(null, null);
		}

		@Override
		public boolean isSpawned()
		{
			return true;
		}

		@Override
		public WorldPoint getWorldLocation()
		{
			return tile;
		}

		@Override
		public boolean isStaying()
		{
			return stayingAt != null;
		}

		@Override
		public WorldPoint getStayTile()
		{
			return stayingAt;
		}

		@Override
		public boolean isSettled()
		{
			return settled;
		}

		@Override
		boolean standable(WorldPoint at)
		{
			return at != null;
		}

		@Override
		boolean canStep(WorldPoint from, int dx, int dy)
		{
			return dx != 0 || dy != 0;
		}

		@Override
		public boolean furnished(WorldPoint at)
		{
			return false;
		}

		@Override
		public boolean stayAt(WorldPoint target)
		{
			if (target == null)
			{
				return false;
			}
			stayingAt = target;
			tile = target;
			stays.add(target);
			return true;
		}

		@Override
		public void setStayFaceTile(WorldPoint at)
		{
			facing = at;
		}

		@Override
		public void resumeFollowing()
		{
			stayingAt = null;
		}
	}

	private FakeGame game;
	private ParkedFollower follower;
	private Will will;
	private final List<TriggerEvent> events = new ArrayList<>();
	private boolean plainlyParked = true;
	private int tick;

	@Before
	public void setUp()
	{
		game = new FakeGame().at(3200, 3401, 0);
		follower = new ParkedFollower();
		will = new Will(game.client, follower, events::add, () -> plainlyParked);
	}

	private void tick(int count)
	{
		for (int i = 0; i < count; i++)
		{
			game.tick(++tick);
			will.tick();
		}
	}

	// -------------------------------------------------------------- the send

	@Test
	public void aPlainSendSimplyGoes()
	{
		WorldPoint there = new WorldPoint(3205, 3405, 0);
		assertTrue(will.send(there));
		assertEquals(there, follower.stayingAt);
		assertFalse(will.isHesitating());
		assertTrue(events.isEmpty());
	}

	@Test
	public void aSendAcrossTheDitchStopsAtTheEdgeAndStaysThere()
	{
		game.at(3200, 3515, 0);
		follower.tile = new WorldPoint(3200, 3514, 0);
		WorldPoint over = new WorldPoint(3200, 3530, 0);
		tick(1);
		assertTrue(will.send(over));
		assertEquals("the row south of the ditch", new WorldPoint(3200, Will.DITCH_SOUTH_Y, 0),
			follower.stayingAt);
		assertEquals("turned to the player", new WorldPoint(3200, 3515, 0), follower.facing);
		assertTrue(will.isHesitating());
		assertEquals(1, events.size());
		assertEquals("wilderness", events.get(0).getPlaceholders().get("misgiving"));
		assertEquals("the Wilderness", events.get(0).getPlaceholders().get("thing"));

		tick(Will.HESITATE_TICKS + 8);
		assertFalse(will.isHesitating());
		assertEquals("no going on across the ditch", 1, follower.stays.size());
		assertNull("and the face tile is let go", follower.facing);
	}

	@Test
	public void fromInsideTheWildernessThereIsNoEdgeToStopAt()
	{
		game.at(3200, 3540, 0);
		follower.tile = new WorldPoint(3200, 3539, 0);
		WorldPoint deeper = new WorldPoint(3200, 3560, 0);
		assertTrue(will.send(deeper));
		assertEquals(deeper, follower.stayingAt);
		assertTrue(events.isEmpty());
	}

	@Test
	public void aSendBesideSomethingThatOutclassesThePlayerPausesThenGoes()
	{
		NPC giant = game.spawnNpc(2098, "Hill Giant", 28);
		game.moveNpc(giant, 3210, 3401, 0);
		WorldPoint beside = new WorldPoint(3209, 3401, 0);
		tick(1);
		assertTrue(will.send(beside));
		assertEquals("three short of it, on the follower's side",
			new WorldPoint(3206, 3400, 0), follower.stayingAt);
		assertTrue(will.isHesitating());
		assertEquals("monster", events.get(0).getPlaceholders().get("misgiving"));
		assertEquals("Hill Giant", events.get(0).getPlaceholders().get("thing"));

		tick(6 + Will.HESITATE_TICKS + 1);
		assertFalse(will.isHesitating());
		assertEquals("then it goes", beside, follower.stayingAt);

		// The same monster does not earn a second pause.
		events.clear();
		assertTrue(will.send(new WorldPoint(3211, 3401, 0)));
		assertTrue(events.isEmpty());
		assertEquals(new WorldPoint(3211, 3401, 0), follower.stayingAt);
	}

	@Test
	public void theMonsterAlreadyBeingFoughtIsNoMisgiving()
	{
		// Sent beside the thing the player is fighting: that fight is on
		// already, and a beat of reluctance about it now is a follower
		// dithering in the middle of it.
		NPC giant = game.spawnNpc(2098, "Hill Giant", 28);
		game.moveNpc(giant, 3210, 3401, 0);
		game.fighting(giant);
		tick(1);
		WorldPoint beside = new WorldPoint(3209, 3401, 0);
		assertTrue(will.send(beside));
		assertFalse(will.isHesitating());
		assertTrue(events.isEmpty());
		assertEquals("straight there", beside, follower.stayingAt);
	}

	@Test
	public void aMonsterWithNoNameIsNoMisgiving()
	{
		// QA, 15 Oct: a nameless monster filled the line with "that" -
		// "Next to the that?" With nothing to name, it simply goes.
		NPC nameless = game.spawnNpc(2098, null, 28);
		game.moveNpc(nameless, 3210, 3401, 0);
		tick(1);
		WorldPoint beside = new WorldPoint(3209, 3401, 0);
		assertTrue(will.send(beside));
		assertFalse(will.isHesitating());
		assertTrue(events.isEmpty());
		assertEquals("straight there", beside, follower.stayingAt);
	}

	@Test
	public void somethingThePlayerCanHandleIsNoMisgiving()
	{
		NPC goblin = game.spawnNpc(3029, "Goblin", 2);
		game.moveNpc(goblin, 3210, 3401, 0);
		assertTrue(will.send(new WorldPoint(3209, 3401, 0)));
		assertFalse(will.isHesitating());
		assertTrue(events.isEmpty());
	}

	@Test
	public void aFollowReleasesThePause()
	{
		NPC giant = game.spawnNpc(2098, "Hill Giant", 28);
		game.moveNpc(giant, 3210, 3401, 0);
		tick(1);
		will.send(new WorldPoint(3209, 3401, 0));
		follower.resumeFollowing();
		tick(2);
		assertFalse(will.isHesitating());
		assertEquals("and it does not set off again on its own", 1, follower.stays.size());
	}

	@Test
	public void aSendEndsPastAMonsterButAtTheDitch()
	{
		// What a park taken again after something else let go walks to. The
		// pause short of a monster is only a pause; the edge of the ditch is
		// where that Send ends, and nothing may walk it on across.
		WorldPoint there = new WorldPoint(3205, 3405, 0);
		assertTrue(will.send(there));
		assertEquals("a plain Send ends where it went", there, will.endsAt());

		NPC giant = game.spawnNpc(2098, "Hill Giant", 28);
		game.moveNpc(giant, 3210, 3401, 0);
		tick(1);
		WorldPoint beside = new WorldPoint(3209, 3401, 0);
		assertTrue(will.send(beside));
		assertTrue(will.isHesitating());
		assertEquals("past the pause", beside, will.endsAt());

		game.at(3200, 3515, 0);
		follower.tile = new WorldPoint(3200, 3514, 0);
		assertTrue(will.send(new WorldPoint(3200, 3530, 0)));
		assertTrue(will.isHesitating());
		assertEquals("at the edge", new WorldPoint(3200, Will.DITCH_SOUTH_Y, 0), will.endsAt());
	}

	@Test
	public void theWildernessIsTheSurfaceNorthOfTheDitch()
	{
		assertTrue(Will.isWilderness(new WorldPoint(3100, 3600, 0)));
		assertFalse(Will.isWilderness(new WorldPoint(3100, 3519, 0)));
		assertFalse(Will.isWilderness(new WorldPoint(3100, 3600, 1)));
		assertFalse(Will.isWilderness(new WorldPoint(2000, 3600, 0)));
		assertNull(Will.edgeShortOf(new WorldPoint(10, 10, 0), new WorldPoint(12, 10, 0), 3));
		assertEquals(new WorldPoint(7, 13, 0),
			Will.edgeShortOf(new WorldPoint(10, 10, 0), new WorldPoint(0, 20, 0), 3));
	}

	// -------------------------------------------------------- the step aside

	private void parkAt(int x, int y)
	{
		follower.tile = new WorldPoint(x, y, 0);
		follower.stayingAt = follower.tile;
		follower.stays.clear();
	}

	@Test
	public void walkedStraightAtItStepsAsideAtTheLastTickWithAWord()
	{
		parkAt(3200, 3404);
		game.at(3200, 3400, 0);
		tick(1);
		game.at(3200, 3401, 0);
		tick(1);
		game.at(3200, 3402, 0);
		tick(1);
		assertTrue("two tiles off is not the last tick", follower.stays.isEmpty());
		game.at(3200, 3403, 0);
		tick(1);
		assertEquals("one to the side of the line", 1, follower.stays.size());
		WorldPoint aside = follower.stays.get(0);
		assertEquals(3404, aside.getY());
		assertEquals(1, Math.abs(aside.getX() - 3200));
		assertEquals(1, events.size());
		assertEquals(TriggerEvent.Type.STEPPED_ASIDE, events.get(0).getType());
	}

	@Test
	public void aRunnerIsSeenTwoTilesOut()
	{
		parkAt(3200, 3406);
		game.at(3200, 3400, 0);
		tick(1);
		game.at(3200, 3402, 0);
		tick(1);
		game.at(3200, 3404, 0);
		tick(1);
		assertEquals("their next run step lands on it", 1, follower.stays.size());
	}

	@Test
	public void walkingPastIsNotWalkingAt()
	{
		parkAt(3201, 3404);
		game.at(3200, 3400, 0);
		tick(1);
		for (int y = 3401; y <= 3408; y++)
		{
			game.at(3200, y, 0);
			tick(1);
		}
		assertTrue("the line beside it is not the line through it", follower.stays.isEmpty());
	}

	@Test
	public void aSeatOrAMomentIsNotSteppedOutOf()
	{
		plainlyParked = false;
		parkAt(3200, 3404);
		game.at(3200, 3402, 0);
		tick(1);
		game.at(3200, 3403, 0);
		tick(1);
		assertTrue(follower.stays.isEmpty());
	}

	@Test
	public void notTwiceInAStretch()
	{
		parkAt(3200, 3404);
		game.at(3200, 3402, 0);
		tick(1);
		game.at(3200, 3403, 0);
		tick(1);
		assertEquals(1, follower.stays.size());
		// Parked on the new tile, walked at again straight away.
		WorldPoint aside = follower.stays.get(0);
		game.at(aside.getX(), aside.getY() - 2, 0);
		tick(1);
		game.at(aside.getX(), aside.getY() - 1, 0);
		tick(1);
		assertEquals("the cooldown holds", 1, follower.stays.size());
	}}

package com.follower;

import com.google.gson.Gson;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.GraphicsEnvironment;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.FontManager;
import org.junit.Assume;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * QA3: Messages, Conversations and Sounds could be dragged narrower than
 * their fixed-width text, Conversations opened taller than a 720 work area,
 * and in Messages a long title was cut along with its id. Laid out and
 * measured; no window is put on screen.
 */
public class WindowSizesTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void theThreeEditorsCannotBeDraggedNarrowerThanTheirText() throws Exception
	{
		Assume.assumeFalse(GraphicsEnvironment.isHeadless());
		Path phrases = folder.newFile("phrases.json").toPath();
		Files.copy(Paths.get("src/main/resources/com/follower/default-phrases.json"), phrases,
			java.nio.file.StandardCopyOption.REPLACE_EXISTING);
		SwingUtilities.invokeAndWait(() ->
		{
			PhrasesDialog messages = new PhrasesDialog(new Gson(), phrases, Arrays.asList(
				new PhrasesDialog.Category("Quest NPCs", "quest", "Said.", false)), () -> 0);
			assertEquals(new Dimension(620, 400), messages.getMinimumSize());
			messages.dispose();

		});
	}

	@Test
	public void aLongTitleIsShownWholeAndOnlyTheIdGivesWay() throws Exception
	{
		Assume.assumeFalse(GraphicsEnvironment.isHeadless());
		Path phrases = folder.newFile("phrases.json").toPath();
		Files.copy(Paths.get("src/main/resources/com/follower/default-phrases.json"), phrases,
			java.nio.file.StandardCopyOption.REPLACE_EXISTING);
		List<PhrasesDialog.Category> categories = Arrays.asList(
			new PhrasesDialog.Category("Quest NPCs", "quest", "Said.", false),
			new PhrasesDialog.Category("Locations", "area", "Said.", true));
		PhrasesDialog[] made = new PhrasesDialog[1];
		SwingUtilities.invokeAndWait(() ->
		{
			made[0] = new PhrasesDialog(new Gson(), phrases, categories, () -> 0)
			{
				@Override
				public void setVisible(boolean b)
				{
				}
			};
			made[0].open();
		});
		PhrasesDialog dialog = made[0];
		JComboBox<?> picker = (JComboBox<?>) field(dialog, "categoryPicker");
		List<String> cut = new ArrayList<>();
		int[] measured = {0};
		for (int i = 0; i < categories.size(); i++)
		{
			int at = i;
			SwingUtilities.invokeAndWait(() -> picker.setSelectedIndex(at));
			for (int k = 0; k < 4; k++)
			{
				SwingUtilities.invokeAndWait(() -> { });
			}
			SwingUtilities.invokeAndWait(dialog::validate);
			SwingUtilities.invokeAndWait(() ->
			{
				for (JLabel title : titles(dialog.getContentPane()))
				{
					measured[0]++;
					if (title.getWidth() < title.getPreferredSize().width)
					{
						cut.add(title.getText() + " (" + title.getWidth() + " of "
							+ title.getPreferredSize().width + ")");
					}
				}
			});
		}
		SwingUtilities.invokeAndWait(dialog::dispose);
		assertTrue("titles measured", measured[0] > 100);
		assertTrue("titles cut at the opening size: " + cut, cut.isEmpty());
	}

	/** The rows' titles: the bold labels in a row's title-and-id line. */
	private static List<JLabel> titles(Container root)
	{
		List<JLabel> out = new ArrayList<>();
		for (Component c : root.getComponents())
		{
			if (c instanceof JLabel && ((JLabel) c).getFont() == FontManager.getRunescapeBoldFont()
				&& root.getLayout() instanceof javax.swing.BoxLayout)
			{
				out.add((JLabel) c);
			}
			else if (c instanceof Container)
			{
				out.addAll(titles((Container) c));
			}
		}
		return out;
	}

	private static Object field(Object owner, String name) throws Exception
	{
		// Fields the two file editors share live on their base class.
		java.lang.reflect.Field f;
		try
		{
			f = PhrasesDialog.class.getDeclaredField(name);
		}
		catch (NoSuchFieldException e)
		{
			f = EditorDialog.class.getDeclaredField(name);
		}
		f.setAccessible(true);
		return f.get(owner);
	}
}

package com.follower;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Numbers and stretches of time in words: the difference between a counter
 * with a face and somebody keeping count.
 */
public class WordsTest
{
	@Test
	public void numbersInWordsUpToWhereWordsStopReadingNaturally()
	{
		assertEquals("one", Words.number(1));
		assertEquals("eleven", Words.number(11));
		assertEquals("twenty", Words.number(20));
		assertEquals("forty-one", Words.number(41));
		assertEquals("ninety-nine", Words.number(99));
		assertEquals("100", Words.number(100));
		assertEquals("1500", Words.number(1500));
	}

	@Test
	public void ordinalsTheWayTheyAreSaid()
	{
		assertEquals("first", Words.ordinal(1));
		assertEquals("third", Words.ordinal(3));
		assertEquals("twelfth", Words.ordinal(12));
		assertEquals("twentieth", Words.ordinal(20));
		assertEquals("forty-first", Words.ordinal(41));
		assertEquals("fifty-second", Words.ordinal(52));
		assertEquals("ninety-ninth", Words.ordinal(99));
		assertEquals("hundredth", Words.ordinal(100));
		assertEquals("101st", Words.ordinal(101));
		assertEquals("111th", Words.ordinal(111));
		assertEquals("112th", Words.ordinal(112));
		assertEquals("122nd", Words.ordinal(122));
		assertEquals("203rd", Words.ordinal(203));
		assertEquals("thousandth", Words.ordinal(1000));
		assertEquals("1001st", Words.ordinal(1001));
	}

	@Test
	public void durationsPickOneUnitAndStopThere()
	{
		long minute = 60_000L;
		assertEquals("a minute", Words.duration(0));
		assertEquals("a minute", Words.duration(90_000L));
		assertEquals("forty minutes", Words.duration(40 * minute));
		assertEquals("an hour", Words.duration(75 * minute));
		assertEquals("three hours", Words.duration(3 * 60 * minute + 12 * minute));
		assertEquals("a day", Words.duration(40 * 60 * minute));
		assertEquals("eleven days", Words.duration(11 * 24 * 60 * minute + 4 * 60 * minute));
		assertEquals("three weeks", Words.duration(23 * 24 * 60 * minute));
		assertEquals("six weeks", Words.duration(45 * 24 * 60 * minute));
		assertEquals("a month", Words.duration(58 * 24 * 60 * minute));
		assertEquals("four months", Words.duration(130 * 24 * 60 * minute));
		assertEquals("a year", Words.duration(400L * 24 * 60 * minute));
		assertEquals("two years", Words.duration(800L * 24 * 60 * minute));
	}

	@Test
	public void theArticleGoesBySoundNotSpelling()
	{
		assertEquals("an", Words.article("Eclectic impling"));
		assertEquals("an", Words.article("Earth impling"));
		assertEquals("an", Words.article("Essence impling"));
		assertEquals("a", Words.article("Young impling"));
		assertEquals("a", Words.article("Dwarf"));
		assertEquals("an", Words.article("Agility"));
		assertEquals("an", Words.article("Uncut onyx"));
		assertEquals("a", Words.article("Unicorn"));
		assertEquals("a", Words.article("One-eyed rat"));
		assertEquals("an", Words.article("hour"));
		assertEquals("an", Words.article("8"));
		assertEquals("an", Words.article("80"));
		assertEquals("an", Words.article("11"));
		assertEquals("an", Words.article("18"));
		assertEquals("a", Words.article("31"));
		assertEquals("a", Words.article("110"));
	}

	@Test
	public void pluralsHeapsAndTheNamedTakeNoArticle()
	{
		assertTrue(Words.takesNoArticle("Coins"));
		assertTrue(Words.takesNoArticle("Dragon bones"));
		assertTrue(Words.takesNoArticle("Onyx bolts (e)"));
		assertTrue(Words.takesNoArticle("Soft clay"));
		assertTrue(Words.takesNoArticle("charcoal"));
		assertTrue(Words.takesNoArticle("Hanging meat"));
		assertTrue(Words.takesNoArticle("The Leviathan"));
		assertFalse(Words.takesNoArticle("Cerberus"));
		assertFalse(Words.takesNoArticle("Scurrius"));
		assertFalse(Words.takesNoArticle("Venenatis"));
		assertFalse(Words.takesNoArticle("Tempoross"));
		assertFalse(Words.takesNoArticle("Jar of souls"));
		assertFalse(Words.takesNoArticle("ball of wool"));
		assertFalse(Words.takesNoArticle("Clue scroll (elite)"));
		assertFalse(Words.takesNoArticle("Eclectic impling"));
		assertFalse(Words.takesNoArticle("80"));
		// Review: one of a kind despite the s, and glass had by the piece.
		assertFalse(Words.takesNoArticle("Cyclops"));
		assertFalse(Words.takesNoArticle("Nylocas Ischyros"));
		assertFalse(Words.takesNoArticle("Nylocas Vasilias"));
		assertFalse(Words.takesNoArticle("Lantern lens"));
		assertFalse(Words.takesNoArticle("Beer glass"));
		assertFalse(Words.takesNoArticle("Magnifying glass"));
	}

	@Test
	public void aPlainNameBecomesACommonNounAndANameInItsOwnRightDoesNot()
	{
		assertEquals("guard", Words.asCommonNoun("Guard"));
		assertEquals("monk of Zamorak", Words.asCommonNoun("Monk of Zamorak"));
		assertEquals("thermonuclear smoke devil", Words.asCommonNoun("Thermonuclear smoke devil"));
		assertEquals("goblin (level-2)", Words.asCommonNoun("Goblin (level-2)"));
		assertEquals("Hill Giant", Words.asCommonNoun("Hill Giant"));
		assertEquals("King Black Dragon", Words.asCommonNoun("King Black Dragon"));
		assertEquals("TzHaar-Ket", Words.asCommonNoun("TzHaar-Ket"));
		assertEquals("guard", Words.asCommonNoun("guard"));
	}
}

package com.follower;

import java.lang.reflect.Proxy;
import java.util.Arrays;
import java.util.function.BiFunction;
import java.util.function.IntPredicate;
import java.util.function.IntSupplier;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.Model;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Where the loop-wrap lerp writes its blend.
 *
 * <p>The client hands every animated frame to the renderer in one shared
 * per-frame temp, and the base controller returns that temp, so the lerp writes
 * into it the same way. But a frame with no transform can come back as the
 * follower's base model itself, or as a model sharing its vertex arrays, and a
 * write there would bend the base for good. These pin both halves: the blend
 * lands in the temp, and the base is never written. Nor is a temp posed from a
 * model the snapshotted endpoints no longer fit.
 */
public class WrapLerpControllerTest
{
	private static final int FRAMES = 3;
	private static final int FRAME_LENGTH = 4;
	private static final int VERTICES = 5;

	private static final float BASE = 1f;
	private static final float LAST_POSE = 10f;
	private static final float LOOP_POSE = 20f;
	private static final float OTHER_POSE = 30f;

	private Model base;
	/** The client's shared per-frame temp: one set of arrays, reposed every call. */
	private Model temp;
	/** How many vertices the temp holds: as many as the model last posed into it. */
	private int tempCount;
	/** What the render-time call hands back instead of the temp, or null for the temp. */
	private Model renderReturns;

	private Client client;
	private Animation animation;

	@Before
	public void setUp()
	{
		base = model(filled(BASE), filled(BASE), filled(BASE));
		temp = model(new float[VERTICES], new float[VERTICES], new float[VERTICES], () -> tempCount);
		client = fake(Client.class, (name, args) ->
		{
			switch (name)
			{
				case "getAnimationInterpolationFilter":
					return (IntPredicate) id -> true;
				case "applyTransformations":
					return transform((Model) args[0], (int) args[2]);
				default:
					throw new UnsupportedOperationException(name);
			}
		});
		animation = fake(Animation.class, (name, args) ->
		{
			switch (name)
			{
				case "getId":
					return 808;
				case "isMayaAnim":
					return false;
				case "getFrameLengths":
					int[] lengths = new int[FRAMES];
					Arrays.fill(lengths, FRAME_LENGTH);
					return lengths;
				case "getFrameStep":
					return -1;
				case "getDuration":
					return FRAMES;
				default:
					throw new UnsupportedOperationException(name);
			}
		});
	}

	@Test
	public void blendLandsInTheRenderTemp()
	{
		WrapLerpController controller = onFinalFrame();
		Model drawn = controller.animate(base, null);

		assertSame("the lerp returns the client's own temp", temp, drawn);
		float halfway = (LAST_POSE + LOOP_POSE) / 2;
		assertArrayEquals(filled(halfway), drawn.getVerticesX(), 0f);
		assertArrayEquals(filled(halfway), drawn.getVerticesY(), 0f);
		assertArrayEquals(filled(halfway), drawn.getVerticesZ(), 0f);
		assertBaseUntouched();
		assertFalse(controller.isDisabled());
	}

	@Test
	public void neverWritesTheBaseWhenTheTempIsTheBase()
	{
		renderReturns = base;
		WrapLerpController controller = onFinalFrame();

		assertSame(base, controller.animate(base, null));
		assertBaseUntouched();
		assertTrue("the measured wrap trim takes over", controller.isDisabled());
	}

	@Test
	public void neverWritesTheBaseThroughSharedArrays()
	{
		Model alias = model(base.getVerticesX(), base.getVerticesY(), base.getVerticesZ());
		renderReturns = alias;
		WrapLerpController controller = onFinalFrame();

		assertSame(alias, controller.animate(base, null));
		assertBaseUntouched();
		assertTrue("the measured wrap trim takes over", controller.isDisabled());
	}

	@Test
	public void aModelThatNoLongerMatchesTheEndpointsSwitchesTheLerpOff()
	{
		WrapLerpController controller = onFinalFrame();
		controller.animate(base, null);

		// A different model under the same animation: the endpoints were taken from
		// the base, and blending them into this one would scramble it.
		Model smaller = model(new float[2], new float[2], new float[2]);
		Model drawn = controller.animate(smaller, null);

		assertSame(temp, drawn);
		assertEquals("posed by the client, not blended", LAST_POSE, drawn.getVerticesX()[0], 0f);
		assertBaseUntouched();
		assertTrue("the measured wrap trim takes over", controller.isDisabled());
	}

	/** Halfway through the final frame, so the blend differs from both endpoints. */
	private WrapLerpController onFinalFrame()
	{
		WrapLerpController controller = new WrapLerpController(client, animation);
		controller.setFrame(FRAMES - 1);
		controller.tick(FRAME_LENGTH / 2);
		return controller;
	}

	/**
	 * Stands in for Client#applyTransformations. The endpoint snapshots ask with a
	 * plain frame index; the render call arrives packed (high bit set while
	 * smoothing accepts the animation), which is where a test swaps in the base or
	 * an alias of it.
	 */
	private Model transform(Model posed, int frame)
	{
		if (frame < 0 && renderReturns != null)
		{
			return renderReturns;
		}
		int index = frame & 0xFFFF;
		float pose = index == FRAMES - 1 ? LAST_POSE : index == 0 ? LOOP_POSE : OTHER_POSE;
		tempCount = posed.getVerticesCount();
		Arrays.fill(temp.getVerticesX(), 0, tempCount, pose);
		Arrays.fill(temp.getVerticesY(), 0, tempCount, pose);
		Arrays.fill(temp.getVerticesZ(), 0, tempCount, pose);
		return temp;
	}

	private void assertBaseUntouched()
	{
		assertArrayEquals("base x", filled(BASE), base.getVerticesX(), 0f);
		assertArrayEquals("base y", filled(BASE), base.getVerticesY(), 0f);
		assertArrayEquals("base z", filled(BASE), base.getVerticesZ(), 0f);
	}

	private static float[] filled(float value)
	{
		float[] out = new float[VERTICES];
		Arrays.fill(out, value);
		return out;
	}

	private static Model model(float[] x, float[] y, float[] z)
	{
		return model(x, y, z, () -> x.length);
	}

	private static Model model(float[] x, float[] y, float[] z, IntSupplier count)
	{
		return fake(Model.class, (name, args) ->
		{
			switch (name)
			{
				case "getVerticesCount":
					return count.getAsInt();
				case "getVerticesX":
					return x;
				case "getVerticesY":
					return y;
				case "getVerticesZ":
					return z;
				default:
					throw new UnsupportedOperationException(name);
			}
		});
	}

	/** Answers only what the lerp should ask; anything else fails loudly. */
	@SuppressWarnings("unchecked")
	private static <T> T fake(Class<T> type, BiFunction<String, Object[], Object> answers)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "equals":
						return proxy == args[0];
					case "hashCode":
						return System.identityHashCode(proxy);
					case "toString":
						return type.getSimpleName() + "@fake";
					default:
						return answers.apply(method.getName(), args);
				}
			});
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The wrap trims, and the file they live in.
 *
 * <p>A trim is how many frames to cut off the end of a looping animation, so
 * the follower's loop wraps where the player's does. They are MEASURED over a
 * session and written out, which means the file is the only thing keeping work
 * the plugin did once - and it was the last of the plugin's stores with no test.
 *
 * <p>Two kinds live in it and the difference matters: measured values the
 * plugin worked out, and manual ones somebody set by hand with
 * {@code ::follower wrapearly}. Merging them the wrong way round would have a
 * measurement quietly overwrite a deliberate override.
 */
public class WrapTrimStoreTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	/** The entity only has to hold two maps here; nothing touches a client. */
	private static FollowerEntity bareFollower()
	{
		return new FollowerEntity(null, null);
	}

	@Test
	public void trimsSurviveASaveAndLoad()
	{
		Path dir = folderPath();
		FollowerEntity saved = bareFollower();

		Map<Integer, Integer> manual = new HashMap<>();
		manual.put(808, 3);
		Map<Integer, Integer> measured = new HashMap<>();
		measured.put(819, 5);
		measured.put(824, 1);
		saved.restoreTrims(manual, measured);

		WrapTrimStore store = new WrapTrimStore(new Gson());
		store.load(dir, saved);
		store.save(saved);

		FollowerEntity reloaded = bareFollower();
		new WrapTrimStore(new Gson()).load(dir, reloaded);

		assertEquals("the hand-set trim came back", Integer.valueOf(3),
			reloaded.getWrapTrims().get(808));
		assertEquals("and both measured ones", Integer.valueOf(5),
			reloaded.getMeasuredTrims().get(819));
		assertEquals(Integer.valueOf(1), reloaded.getMeasuredTrims().get(824));
	}

	@Test
	public void aMeasurementNeverOverwritesAHandSetTrim()
	{
		// The two maps are separate for exactly this reason: a manual trim is
		// somebody deciding, a measurement is the plugin guessing. Round-trip
		// them together and the manual one has to still be manual.
		Path dir = folderPath();
		FollowerEntity follower = bareFollower();

		Map<Integer, Integer> manual = new HashMap<>();
		manual.put(808, 3);
		Map<Integer, Integer> measured = new HashMap<>();
		measured.put(808, 9);
		follower.restoreTrims(manual, measured);

		WrapTrimStore store = new WrapTrimStore(new Gson());
		store.load(dir, follower);
		store.save(follower);

		FollowerEntity reloaded = bareFollower();
		new WrapTrimStore(new Gson()).load(dir, reloaded);

		assertEquals("the same animation is in both maps and they must not merge",
			Integer.valueOf(3), reloaded.getWrapTrims().get(808));
		assertEquals(Integer.valueOf(9), reloaded.getMeasuredTrims().get(808));
	}

	@Test
	public void nothingLearnedWritesNoFileAtAll()
	{
		// A fresh install should not litter the data directory with an empty
		// object, and an empty file is one more thing the loader has to
		// survive on the next start.
		Path dir = folderPath();
		WrapTrimStore store = new WrapTrimStore(new Gson());
		FollowerEntity follower = bareFollower();

		store.load(dir, follower);
		store.save(follower);

		assertFalse("an empty store wrote a file anyway",
			Files.exists(dir.resolve(WrapTrimStore.FILE_NAME)));
	}

	@Test
	public void aMissingFileIsAFreshStartRatherThanAFailure()
	{
		FollowerEntity follower = bareFollower();
		new WrapTrimStore(new Gson()).load(folderPath(), follower);

		assertTrue("nothing to load is not an error", follower.getWrapTrims().isEmpty());
		assertTrue(follower.getMeasuredTrims().isEmpty());
	}

	@Test
	public void aCorruptFileLeavesTheFollowerUsableRatherThanThrowing()
	{
		// This runs during startup. Throwing here would take the plugin down
		// over a file whose only job is to save re-measuring some animations.
		Path dir = folderPath();
		write(dir.resolve(WrapTrimStore.FILE_NAME), "{ this is not json");

		FollowerEntity follower = bareFollower();
		new WrapTrimStore(new Gson()).load(dir, follower);

		assertTrue("a bad file must leave empty trims, not half-read ones",
			follower.getWrapTrims().isEmpty());
	}

	@Test
	public void anEmptyFileIsSurvivedToo()
	{
		Path dir = folderPath();
		write(dir.resolve(WrapTrimStore.FILE_NAME), "");

		FollowerEntity follower = bareFollower();
		new WrapTrimStore(new Gson()).load(dir, follower);

		assertTrue(follower.getWrapTrims().isEmpty());
	}

	@Test
	public void savingWithoutLoadingFirstDoesNothing()
	{
		// save() has nowhere to write until load() has told it where the data
		// directory is. Guessing would put the file somewhere unexpected.
		FollowerEntity follower = bareFollower();
		Map<Integer, Integer> manual = new HashMap<>();
		manual.put(808, 3);
		follower.restoreTrims(manual, null);

		new WrapTrimStore(new Gson()).save(follower);
		// The assertion is that this returned quietly rather than throwing at
		// a null path; there is nowhere to look for a file it never named.
	}

	// ------------------------------------------------------------- plumbing

	private Path folderPath()
	{
		try
		{
			return folder.newFolder().toPath();
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}

	private static void write(Path file, String contents)
	{
		try
		{
			Files.createDirectories(file.getParent());
			Files.write(file, contents.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}
}

package com.follower;

import com.google.gson.Gson;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.RuneLiteObject;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * How the follower's body handles the clips that were authored for something
 * other than the way it plays them (QA, 15 Oct): the writing pose held for
 * minutes when it was made to play once, the mood stances played as emotes,
 * and a gesture asked for while it walks.
 *
 * <p>Cache measurements behind the numbers: 13302 is 22 frames, a lift over
 * frames 0-3, writing to 17 and a lowering over 18-21; frame 16 is frame 9
 * exactly. The mood clips start and end 63-104 units from the idle.
 */
public class WritingPoseTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static final int WRITE = ErrandController.WRITE_SCROLL_POSE;

	private int tickCount;
	private final List<Integer> loaded = new ArrayList<>();

	private static Animation animation(int id, int frames)
	{
		return (Animation) Proxy.newProxyInstance(Animation.class.getClassLoader(),
			new Class<?>[]{Animation.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getId":
						return id;
					case "isMayaAnim":
						return false;
					case "getFrameLengths":
						int[] lengths = new int[frames];
						java.util.Arrays.fill(lengths, 8);
						return lengths;
					case "getDuration":
						return frames;
					case "getFrameStep":
						return -1;
					case "hashCode":
						return System.identityHashCode(proxy);
					case "equals":
						return proxy == args[0];
					default:
						Class<?> type = method.getReturnType();
						return type == boolean.class ? false : type == int.class ? 0 : null;
				}
			});
	}

	private FollowerEntity follower() throws IOException, ReflectiveOperationException
	{
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "loadAnimation":
						int id = (Integer) args[0];
						loaded.add(id);
						return animation(id, id == WRITE ? 22 : 10);
					case "getTickCount":
						return tickCount;
					default:
						Class<?> type = method.getReturnType();
						return type == boolean.class ? false : type == int.class ? 0
							: type == long.class ? 0L : null;
				}
			});
		StanceLibrary stances = new StanceLibrary(new Gson(), new ModelRepository(new Gson()));
		stances.load(folder.newFolder().toPath());
		FollowerEntity follower = new FollowerEntity(client, stances);
		set(follower, "object", new RuneLiteObject(client));
		set(follower, "animatable", true);
		return follower;
	}

	private static void set(FollowerEntity follower, String name, Object value) throws ReflectiveOperationException
	{
		Field field = FollowerEntity.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(follower, value);
	}

	private static Object call(FollowerEntity follower, String name, Object... args) throws ReflectiveOperationException
	{
		for (Method method : FollowerEntity.class.getDeclaredMethods())
		{
			if (method.getName().equals(name) && method.getParameterCount() == args.length)
			{
				method.setAccessible(true);
				return method.invoke(follower, args);
			}
		}
		throw new AssertionError("FollowerEntity." + name + " has moved");
	}

	private static AnimationController playing(FollowerEntity follower) throws ReflectiveOperationException
	{
		Field field = FollowerEntity.class.getDeclaredField("object");
		field.setAccessible(true);
		return ((RuneLiteObject) field.get(follower)).getAnimationController();
	}

	/** The writing pose put on and shown, as a frame of the update does. */
	private FollowerEntity writing(int frame) throws IOException, ReflectiveOperationException
	{
		FollowerEntity follower = follower();
		follower.setPoseOverride(WRITE);
		call(follower, "applyPose", WRITE, true);
		playing(follower).setFrame(frame);
		return follower;
	}

	// ------------------------------------------------------------ the hold

	@Test
	public void aHeldWritingPoseWritesOnRatherThanLoweringAndLiftingTheScroll()
		throws IOException, ReflectiveOperationException
	{
		FollowerEntity follower = writing(15);
		call(follower, "holdTheWriting");
		assertEquals("still writing", 15, playing(follower).getFrame());

		playing(follower).setFrame(FollowerEntity.WRITE_LOOP_END);
		call(follower, "holdTheWriting");
		assertEquals("back to the frame 16 is a copy of, not on to the lowering",
			FollowerEntity.WRITE_LOOP_START, playing(follower).getFrame());
		assertEquals(9, FollowerEntity.WRITE_LOOP_START);
		assertEquals(16, FollowerEntity.WRITE_LOOP_END);
	}

	@Test
	public void anyOtherPoseLoopsWhole() throws IOException, ReflectiveOperationException
	{
		FollowerEntity follower = follower();
		call(follower, "applyPose", 5354, true);
		playing(follower).setFrame(FollowerEntity.WRITE_LOOP_END);
		call(follower, "holdTheWriting");
		assertEquals(FollowerEntity.WRITE_LOOP_END, playing(follower).getFrame());
	}

	// -------------------------------------------------------- the put-away

	@Test
	public void lettingGoOfTheWritingLowersTheScrollFirst() throws IOException, ReflectiveOperationException
	{
		FollowerEntity follower = writing(12);
		follower.setPoseOverride(0);
		assertTrue("the lowering plays", follower.isPuttingAway());
		assertTrue(follower.isEmotePlaying());
		AnimationController controller = playing(follower);
		assertEquals(WRITE, controller.getAnimation().getId());
		assertEquals("from the top of the lowering", FollowerEntity.WRITE_PUT_AWAY_FRAME, controller.getFrame());
	}

	@Test
	public void anotherPoseOverTheWritingLowersItToo() throws IOException, ReflectiveOperationException
	{
		FollowerEntity follower = writing(10);
		follower.setPoseOverride(10061);
		assertTrue(follower.isPuttingAway());
		assertEquals("and the new pose is waiting", 10061, follower.getPoseOverride());
	}

	@Test
	public void noLoweringWhileStillLiftingOrOnTheMove() throws IOException, ReflectiveOperationException
	{
		FollowerEntity lifting = writing(2);
		lifting.setPoseOverride(0);
		assertFalse("caught in the lift, nothing to lower", lifting.isEmotePlaying());

		FollowerEntity walking = writing(12);
		set(walking, "onTheMove", true);
		walking.setPoseOverride(0);
		assertFalse("walking, the writing was never shown", walking.isEmotePlaying());
	}

	@Test
	public void whatWaitsOnTheLoweringRunsWhenItEndsHoweverItEnds() throws IOException, ReflectiveOperationException
	{
		FollowerEntity follower = writing(12);
		follower.setPoseOverride(0);
		List<String> ran = new ArrayList<>();
		follower.atEmoteFraction(1, () -> ran.add("props away"));
		call(follower, "passEmoteMilestones", false);
		assertTrue("not at the top of the lowering", ran.isEmpty());

		follower.cancelEmote();
		assertEquals("cut short by a walk, the props still go", 1, ran.size());
		assertFalse(follower.isPuttingAway());

		List<String> now = new ArrayList<>();
		follower.atEmoteFraction(1, () -> now.add("at once"));
		assertEquals("with nothing playing, at once", 1, now.size());
	}

	@Test
	public void anotherClipTakingOverEndsTheWait() throws IOException, ReflectiveOperationException
	{
		FollowerEntity follower = writing(12);
		follower.setPoseOverride(0);
		List<String> ran = new ArrayList<>();
		follower.atEmoteFraction(1, () -> ran.add("props away"));
		follower.playAnimation(714);
		assertEquals("the teleport home does not carry the scroll", 1, ran.size());
		assertFalse(follower.isPuttingAway());
	}

	@Test
	public void theReachHandsThePropOverAtTheBottomOfTheBend() throws IOException, ReflectiveOperationException
	{
		FollowerEntity follower = follower();
		follower.playAnimation(827);
		List<String> ran = new ArrayList<>();
		follower.atEmoteFraction(0.5, () -> ran.add("prop in hand"));
		playing(follower).setFrame(4);
		call(follower, "passEmoteMilestones", false);
		assertTrue("still going down", ran.isEmpty());
		playing(follower).setFrame(5);
		call(follower, "passEmoteMilestones", false);
		assertEquals(1, ran.size());
	}

	// ------------------------------------------------- a gesture on the move

	@Test
	public void aGestureAskedForOnTheMoveWaitsForTheFollowerToStand()
		throws IOException, ReflectiveOperationException
	{
		FollowerEntity follower = follower();
		set(follower, "onTheMove", true);
		follower.playWhenStill(863, 3);
		assertFalse("not dropped on its first frame by the walk", follower.isEmotePlaying());

		tickCount = 2;
		call(follower, "playWhatWaitedForStill");
		assertFalse("still walking", follower.isEmotePlaying());

		set(follower, "onTheMove", false);
		call(follower, "playWhatWaitedForStill");
		assertTrue("stood, so it waves", follower.isEmotePlaying());
		assertEquals(863, playing(follower).getAnimation().getId());
	}

	@Test
	public void aGestureThatWaitedTooLongIsDropped() throws IOException, ReflectiveOperationException
	{
		FollowerEntity follower = follower();
		set(follower, "onTheMove", true);
		follower.playWhenStill(863, 3);
		tickCount = 4;
		set(follower, "onTheMove", false);
		call(follower, "playWhatWaitedForStill");
		assertFalse("a wave four ticks after the line is a wave at nothing", follower.isEmotePlaying());
	}

	@Test
	public void aGestureAskedForStandingPlaysAtOnce() throws IOException, ReflectiveOperationException
	{
		FollowerEntity follower = follower();
		follower.playWhenStill(863, 3);
		assertTrue(follower.isEmotePlaying());
	}

	// ------------------------------------------------------ the mood stances

	@Test
	public void aMoodStanceIsEasedInFromStandingAndBackOut() throws IOException, ReflectiveOperationException
	{
		FollowerEntity follower = follower();
		follower.playAnimation(14001);
		assertTrue("HUMAN_CONFUSED_IDLE, 104 units from the idle at its first frame",
			playing(follower) instanceof EaseInOutController);

		follower.playAnimation(857);
		assertFalse("a real emote starts on the idle and is left alone",
			playing(follower) instanceof EaseInOutController);

		for (int mood : new int[]{13994, 13995, 13997, 13999, 14000, 14001})
		{
			assertTrue(mood + " is eased", FollowerEntity.EASED_STANCES.contains(mood));
		}
	}

	@Test
	public void theEaseIsStandingAtBothEndsAndTheClipBetween()
	{
		int duration = 252;
		assertEquals(0f, EaseInOutController.weight(0, duration), 0f);
		assertEquals(0.5f, EaseInOutController.weight(EaseInOutController.EASE_CYCLES / 2, duration), 0.01f);
		assertEquals(1f, EaseInOutController.weight(100, duration), 0f);
		assertEquals(0.5f, EaseInOutController.weight(duration - EaseInOutController.EASE_CYCLES / 2, duration), 0.01f);
		assertEquals("ends where the idle begins", 0f, EaseInOutController.weight(duration, duration), 0f);
	}

	@Test
	public void theTwoHalvesAreTheirClipsFromTheirFrames()
	{
		assertEquals(WRITE, FollowerEntity.clipOf(FollowerEntity.WRITE_PUT_AWAY));
		assertEquals(17, FollowerEntity.firstFrameOf(FollowerEntity.WRITE_PUT_AWAY));
		assertEquals(WRITE, FollowerEntity.clipOf(WRITE));
		assertEquals(0, FollowerEntity.firstFrameOf(WRITE));
		assertEquals(FollowerEntity.SIT_EMOTE, FollowerEntity.clipOf(FollowerEntity.STAND_UP));
		// The held prayer kneel is 645's frame 8 exactly; 9-11 rise from it.
		assertEquals(645, FollowerEntity.clipOf(FollowerEntity.PRAY_STAND_UP));
		assertEquals(8, FollowerEntity.firstFrameOf(FollowerEntity.PRAY_STAND_UP));
	}
}

package com.follower.tools;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.NpcDefinition;
import net.runelite.cache.definitions.SequenceDefinition;
import net.runelite.cache.definitions.loaders.NpcLoader;
import net.runelite.cache.definitions.loaders.SequenceLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Checks every portrait in the chronicle against the cache: the NPC id is a
 * real NPC, and the plate's {@code idle} is that NPC's own standing
 * animation, which exists. The plugin cannot ask an NPC id for its standing
 * animation at runtime, so the id is written into the page, and a wrong one
 * would play some other creature's idle, or nothing, without a word.
 *
 * <p>Prints one line per portrait with what the cache says, so a new plate's
 * {@code idle} can be copied from here.
 *
 *   gradlew runChronicleAudit
 *   gradlew runChronicleAudit --args="<chronicle.json> [cacheDir]"
 */
public class ChronicleAudit
{
	public static void main(String[] args) throws Exception
	{
		Path chronicle = args.length > 0
			? Paths.get(args[0])
			: Paths.get("..", "..", "src", "main", "resources", "com", "follower", "default-chronicle.json");
		Path cacheDir = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"), ".runelite", "jagexcache", "oldschool", "LIVE");

		JsonObject root;
		try (Reader in = Files.newBufferedReader(chronicle, StandardCharsets.UTF_8))
		{
			root = JsonParser.parseReader(in).getAsJsonObject();
		}

		int portraits = 0;
		int problems = 0;
		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index configs = store.getIndex(IndexType.CONFIGS);
			Archive npcArchive = configs.getArchive(ConfigType.NPC.getId());
			ArchiveFiles npcs = npcArchive.getFiles(storage.loadArchive(npcArchive));
			Archive seqArchive = configs.getArchive(ConfigType.SEQUENCE.getId());
			ArchiveFiles seqs = seqArchive.getFiles(storage.loadArchive(seqArchive));
			NpcLoader npcLoader = new NpcLoader();
			SequenceLoader seqLoader = new SequenceLoader();

			for (JsonElement e : root.getAsJsonArray("entries"))
			{
				JsonObject entry = e.getAsJsonObject();
				String page = entry.get("id").getAsString();
				if (!entry.has("plates"))
				{
					continue;
				}
				for (JsonElement p : entry.getAsJsonArray("plates"))
				{
					JsonObject plate = p.getAsJsonObject();
					if (!plate.has("npc"))
					{
						continue;
					}
					portraits++;
					int id = plate.get("npc").getAsInt();
					Integer idle = plate.has("idle") ? plate.get("idle").getAsInt() : null;
					FSFile file = npcs.findFile(id);
					if (file == null)
					{
						System.out.printf("  %-34s npc %-6d NO SUCH NPC%n", page, id);
						problems++;
						continue;
					}
					NpcDefinition npc = npcLoader.load(id, file.getContents());
					int stand = npc.standingAnimation;
					String verdict;
					if (stand == -1)
					{
						// The integrity test wants an idle on every portrait, so
						// an NPC that never stands in one cannot be a portrait.
						verdict = "WRONG: it has no standing animation; choose an NPC id that has one";
					}
					else if (idle == null)
					{
						verdict = "MISSING: idle should be " + stand;
					}
					else if (idle != stand)
					{
						verdict = "WRONG: idle is " + idle + ", its standing animation is " + stand;
					}
					else
					{
						FSFile seq = seqs.findFile(stand);
						if (seq == null)
						{
							verdict = "WRONG: animation " + stand + " does not exist";
						}
						else
						{
							SequenceDefinition def = seqLoader.load(stand, seq.getContents());
							verdict = "ok, " + (def.animMayaID != -1
								? "a newer animation"
								: (def.frameIDs == null ? 0 : def.frameIDs.length) + " frames");
						}
					}
					if (!verdict.startsWith("ok"))
					{
						problems++;
					}
					System.out.printf("  %-34s npc %-6d %-24s stand %-6d %s%n", page, id,
						"\"" + npc.name + "\"", stand, verdict);
				}
			}
		}
		System.out.println();
		System.out.println(portraits + " portraits checked, " + problems + " to fix");
	}
}

package com.follower.tools;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.io.File;
import java.io.IOException;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.ItemManager;
import net.runelite.cache.definitions.ItemDefinition;
import net.runelite.cache.definitions.KitDefinition;
import net.runelite.cache.definitions.SpotAnimDefinition;
import net.runelite.cache.definitions.loaders.KitLoader;
import net.runelite.cache.definitions.loaders.SpotAnimLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Writes equipment-models.json for the Follower Buddy plugin.
 *
 * <p>Run once, and again after a game update that adds gear you care about:
 *
 * <pre>
 *   gradlew run --args="&lt;cacheDir&gt; &lt;outputFile&gt;"
 * </pre>
 *
 * Both arguments are optional; the defaults are RuneLite's own cache directory
 * and {@code ~/.runelite/follower/equipment-models.json}.
 *
 * <p>Only items with at least one worn model are emitted — roughly 4,000 of the
 * 30,000-odd item definitions — which keeps the output a few megabytes rather
 * than tens.
 */
public class EquipmentDumper
{
	private static final int FORMAT_VERSION = 1;

	/** Mirrors com.follower.appearance.ModelRepository.Entry. */
	static class Entry
	{
		/** Item name, so the plugin's outfit picker has a searchable catalogue. */
		String n;
		/** Kits only: KitDefinition.bodyPartId - identifies part AND gender. */
		Integer bp;
		/**
		 * Vertical offsets the client applies to a worn model before merging it.
		 * Without them every piece sits at its raw origin and neighbouring pieces
		 * clip into one another.
		 */
		Integer mo;
		Integer fo;
		/**
		 * Equipment slots this item occupies. wp1 is the slot it goes in; wp2 and wp3
		 * are further slots it HIDES - a platebody hides the arms kit, a full helm
		 * hides hair and jaw. They index the same 12-slot array as KitType.
		 */
		Integer wp1;
		Integer wp2;
		Integer wp3;
		int[] m;
		int[] f;
		short[] cf;
		short[] cr;
		short[] tf;
		short[] tr;
		/**
		 * Chathead models: for items, the male/female dialogue head variants; for
		 * kits, KitDefinition.chatheadModels. These are what real dialogs animate -
		 * separate models with their own talk-animation skeletons.
		 */
		int[] hm;
		int[] hf;
		int[] ch;
	}

	static class Dump
	{
		int version = FORMAT_VERSION;
		String cacheRevision;
		Map<String, Entry> items = new LinkedHashMap<>();
		Map<String, Entry> kits = new LinkedHashMap<>();
	}

	/** Mirrors com.follower.appearance.SpotAnimRepository.Entry. */
	static class SpotAnimEntry
	{
		int m;
		int a;
		Integer rx;
		Integer ry;
		Integer rot;
		Integer am;
		Integer co;
		short[] cf;
		short[] cr;
		short[] tf;
		short[] tr;
	}

	static class SpotAnimDump
	{
		int version = FORMAT_VERSION;
		String cacheRevision;
		Map<String, SpotAnimEntry> spotanims = new LinkedHashMap<>();
	}

	public static void main(String[] args) throws IOException
	{
		Path cacheDir = args.length > 0
			? Paths.get(args[0])
			: defaultCacheDir();

		Path output = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"), ".runelite", "follower", "equipment-models.json");

		if (!Files.isDirectory(cacheDir))
		{
			System.err.println("Cache directory not found: " + cacheDir);
			System.err.println("Pass it explicitly: gradlew run --args=\"C:/path/to/cache out.json\"");
			System.exit(1);
		}

		System.out.println("Reading cache from " + cacheDir);

		Dump dump = new Dump();
		dump.cacheRevision = LocalDate.now().toString();

		SpotAnimDump spotAnims = new SpotAnimDump();
		spotAnims.cacheRevision = dump.cacheRevision;
		FontDump fontDump = new FontDump();
		fontDump.cacheRevision = dump.cacheRevision;

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			dumpItems(store, dump);
			dumpKits(store, dump);
			dumpSpotAnims(store, spotAnims);
			dumpFonts(store, fontDump);
		}

		Files.createDirectories(output.getParent());
		Gson gson = new GsonBuilder().create();
		try (Writer writer = Files.newBufferedWriter(output, StandardCharsets.UTF_8))
		{
			gson.toJson(dump, writer);
		}

		Path spotAnimOutput = output.resolveSibling("spotanims.json");
		try (Writer writer = Files.newBufferedWriter(spotAnimOutput, StandardCharsets.UTF_8))
		{
			gson.toJson(spotAnims, writer);
		}

		Path fontOutput = output.resolveSibling("fonts.json");
		try (Writer writer = Files.newBufferedWriter(fontOutput, StandardCharsets.UTF_8))
		{
			gson.toJson(fontDump, writer);
		}
		System.out.printf("Wrote %d fonts to %s (%.1f KB)%n",
			fontDump.fonts.size(), fontOutput, Files.size(fontOutput) / 1024.0);

		System.out.printf("Wrote %d items and %d kits to %s (%.1f MB)%n",
			dump.items.size(), dump.kits.size(), output, Files.size(output) / 1024.0 / 1024.0);
		System.out.printf("Wrote %d spotanims to %s (%.1f KB)%n",
			spotAnims.spotanims.size(), spotAnimOutput, Files.size(spotAnimOutput) / 1024.0);
	}

	private static void dumpItems(Store store, Dump dump) throws IOException
	{
		ItemManager itemManager = new ItemManager(store);
		itemManager.load();

		for (ItemDefinition item : itemManager.getItems())
		{
			if (item == null)
			{
				continue;
			}

			boolean wearable = item.maleModel0 != -1 || item.femaleModel0 != -1;
			if (!wearable)
			{
				continue;
			}

			Entry entry = new Entry();
			entry.n = item.name;
			entry.mo = item.maleOffset;
			entry.fo = item.femaleOffset;
			entry.wp1 = item.wearPos1;
			entry.wp2 = item.wearPos2;
			entry.wp3 = item.wearPos3;
			entry.m = new int[]{item.maleModel0, item.maleModel1, item.maleModel2};
			entry.f = new int[]{item.femaleModel0, item.femaleModel1, item.femaleModel2};
			if (item.maleHeadModel != -1 || item.maleHeadModel2 != -1)
			{
				entry.hm = new int[]{item.maleHeadModel, item.maleHeadModel2};
			}
			if (item.femaleHeadModel != -1 || item.femaleHeadModel2 != -1)
			{
				entry.hf = new int[]{item.femaleHeadModel, item.femaleHeadModel2};
			}
			entry.cf = item.colorFind;
			entry.cr = item.colorReplace;
			entry.tf = item.textureFind;
			entry.tr = item.textureReplace;

			dump.items.put(Integer.toString(item.id), entry);
		}
	}

	private static void dumpKits(Store store, Dump dump) throws IOException
	{
		Storage storage = store.getStorage();
		Index index = store.getIndex(IndexType.CONFIGS);
		Archive archive = index.getArchive(ConfigType.IDENTKIT.getId());

		byte[] archiveData = storage.loadArchive(archive);
		ArchiveFiles files = archive.getFiles(archiveData);
		KitLoader loader = new KitLoader();

		for (FSFile file : files.getFiles())
		{
			KitDefinition kit = loader.load(file.getFileId(), file.getContents());
			if (kit == null || kit.models == null || kit.models.length == 0)
			{
				continue;
			}

			Entry entry = new Entry();
			entry.bp = kit.bodyPartId;
			// Kits are gender-specific by id, so both genders map to the same models.
			entry.m = kit.models;
			entry.f = kit.models;
			boolean anyHead = false;
			for (int headModel : kit.chatheadModels)
			{
				anyHead |= headModel != -1;
			}
			if (anyHead)
			{
				entry.ch = kit.chatheadModels;
			}
			entry.cf = kit.recolorToFind;
			entry.cr = kit.recolorToReplace;
			entry.tf = kit.retextureToFind;
			entry.tr = kit.retextureToReplace;

			dump.kits.put(Integer.toString(file.getFileId()), entry);
		}
	}

	/** Mirrors com.follower.ui.GameFontRepository's expected format. */
	static class GlyphEntry
	{
		int w;
		int h;
		int ox;
		int oy;
		/** Base64 of one byte per pixel, row-major: 0 = off, nonzero = on. */
		String mask;
	}

	static class FontEntry
	{
		/** The sprite archive id - the same id widgets report as getFontId(). */
		int id;
		/** Resolved archive name (p12_full, b12_full, ...) or null if unknown. */
		String name;
		int ascent;
		int[] advances;
		java.util.List<GlyphEntry> glyphs = new java.util.ArrayList<>();
	}

	/** Candidate font archive names, resolved against name hashes. */
	private static final String[] FONT_NAMES = {
		"p11_full", "p12_full", "b12_full", "q8_full",
		"quill_oblique_large", "quill_caps_large", "lunar_alphabet", "lunar_alphabet_lrg",
		"barbassault_font", "surok_font", "verdana_11pt_regular", "verdana_11pt_bold",
		"verdana_13pt_regular", "verdana_13pt_bold", "verdana_15pt_regular",
	};

	static class FontDump
	{
		int version = FORMAT_VERSION;
		String cacheRevision;
		java.util.List<FontEntry> fonts = new java.util.ArrayList<>();
	}

	/**
	 * The game's text is GLYPH BITMAPS from the cache, not a TTF - no system
	 * font rasterizer reproduces it exactly. Metrics (per-char advances,
	 * ascent) live in the FONTS index keyed by name hash; the glyph images are
	 * the sprite archive with the SAME name hash, and that sprite archive's id
	 * is precisely the id widgets report from {@code getFontId()}.
	 */
	private static void dumpFonts(Store store, FontDump dump) throws IOException
	{
		Storage storage = store.getStorage();
		Index fontIndex = store.getIndex(IndexType.FONTS);
		Index spriteIndex = store.getIndex(IndexType.SPRITES);
		net.runelite.cache.definitions.loaders.FontLoader fontLoader =
			new net.runelite.cache.definitions.loaders.FontLoader();
		net.runelite.cache.definitions.loaders.SpriteLoader spriteLoader =
			new net.runelite.cache.definitions.loaders.SpriteLoader();

		for (Archive fontArchive : fontIndex.getArchives())
		{
			byte[] metricData = storage.loadArchive(fontArchive);
			FSFile metricFile = fontArchive.getFiles(metricData).findFile(0);
			net.runelite.cache.definitions.FontDefinition metrics =
				fontLoader.load(metricFile.getContents());

			Archive glyphArchive = null;
			for (Archive candidate : spriteIndex.getArchives())
			{
				if (candidate.getNameHash() == fontArchive.getNameHash())
				{
					glyphArchive = candidate;
					break;
				}
			}
			if (glyphArchive == null)
			{
				System.out.printf("Font archive %d has no matching glyph sprites%n",
					fontArchive.getArchiveId());
				continue;
			}

			FSFile glyphFile = glyphArchive.getFiles(storage.loadArchive(glyphArchive)).findFile(0);
			net.runelite.cache.definitions.SpriteDefinition[] glyphs =
				spriteLoader.load(glyphArchive.getArchiveId(), glyphFile.getContents());

			FontEntry entry = new FontEntry();
			entry.id = glyphArchive.getArchiveId();
			entry.ascent = metrics.getAscent();
			entry.advances = metrics.getAdvances();
			for (String candidate : FONT_NAMES)
			{
				if (net.runelite.cache.util.Djb2.hash(candidate) == fontArchive.getNameHash())
				{
					entry.name = candidate;
					break;
				}
			}

			for (net.runelite.cache.definitions.SpriteDefinition glyph : glyphs)
			{
				GlyphEntry g = new GlyphEntry();
				g.w = glyph.getWidth();
				g.h = glyph.getHeight();
				g.ox = glyph.getOffsetX();
				g.oy = glyph.getOffsetY();
				int[] pixels = glyph.getPixels();
				byte[] mask = new byte[g.w * g.h];
				for (int i = 0; i < mask.length && pixels != null && i < pixels.length; i++)
				{
					mask[i] = (byte) (pixels[i] != 0 ? 1 : 0);
				}
				g.mask = java.util.Base64.getEncoder().encodeToString(mask);
				entry.glyphs.add(g);
			}

			dump.fonts.add(entry);
			System.out.printf("Font id=%d name=%s: %d glyphs, %d advances, ascent %d%n",
				entry.id, entry.name, entry.glyphs.size(),
				entry.advances == null ? 0 : entry.advances.length, entry.ascent);
		}
	}

	/**
	 * Spotanims are the game's "graphics": teleport swirls, spell impacts, the
	 * home teleport's rune circle. Each maps a graphic id to a model, the
	 * animation that plays it, scaling, rotation, recolours and lighting tweaks.
	 * The live client API exposes none of this, which is why it is dumped.
	 */
	private static void dumpSpotAnims(Store store, SpotAnimDump dump) throws IOException
	{
		Storage storage = store.getStorage();
		Index index = store.getIndex(IndexType.CONFIGS);
		Archive archive = index.getArchive(ConfigType.SPOTANIM.getId());

		byte[] archiveData = storage.loadArchive(archive);
		ArchiveFiles files = archive.getFiles(archiveData);
		SpotAnimLoader loader = new SpotAnimLoader();

		for (FSFile file : files.getFiles())
		{
			SpotAnimDefinition def = loader.load(file.getFileId(), file.getContents());
			if (def == null || def.modelId <= 0)
			{
				continue;
			}

			SpotAnimEntry entry = new SpotAnimEntry();
			entry.m = def.modelId;
			entry.a = def.animationId;
			// Defaults are omitted so the file stays small: 128 scale is 100%,
			// rotation 0, ambient/contrast 0.
			entry.rx = def.resizeX == 128 ? null : def.resizeX;
			entry.ry = def.resizeY == 128 ? null : def.resizeY;
			entry.rot = def.rotaton == 0 ? null : def.rotaton;
			entry.am = def.ambient == 0 ? null : def.ambient;
			entry.co = def.contrast == 0 ? null : def.contrast;
			entry.cf = def.recolorToFind;
			entry.cr = def.recolorToReplace;
			entry.tf = def.textureToFind;
			entry.tr = def.textureToReplace;

			dump.spotanims.put(Integer.toString(file.getFileId()), entry);
		}
	}

	private static Path defaultCacheDir()
	{
		Path runeliteCache = Paths.get(System.getProperty("user.home"),
			".runelite", "jagexcache", "oldschool", "LIVE");
		if (Files.isDirectory(runeliteCache))
		{
			return runeliteCache;
		}

		// Fall back to the standalone client's cache.
		return Paths.get(System.getProperty("user.home"), "jagexcache", "oldschool", "LIVE");
	}
}

package com.follower.tools;

import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.ObjectDefinition;
import net.runelite.cache.definitions.loaders.ObjectLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Every object in the game a player can set light to, and what
 * {@code HotGround} would make of it.
 *
 * <p>The hot-ground set is matched by NAME, and a name-based match fails
 * silently: the follower simply walks into the thing, with no log line and
 * nothing to tell it apart from a fire nobody lit. The list was written from
 * memory the first time. This is the audit it should have had.
 *
 * <pre>
 *   gradlew runFireAudit
 * </pre>
 */
public class FireAudit
{
	/** The names HotGround.NAMES holds, kept in step by hand. */
	private static final List<String> MATCHED = Arrays.asList(
		"fire", "campfire", "forester's campfire", "bonfire");

	/** Anything whose name contains one of these is worth a look. */
	private static final String[] LOOK_FOR = {
		"fire", "flame", "brazier", "embers", "burning", "pyre", "furnace",
	};

	public static void main(String[] args) throws IOException
	{
		Path cacheDir = args.length > 0
			? Paths.get(args[0])
			: Paths.get(System.getProperty("user.home"),
				".runelite", "jagexcache", "oldschool", "LIVE");

		List<ObjectDefinition> candidates = new ArrayList<>();
		int named = 0;

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index configs = store.getIndex(IndexType.CONFIGS);
			Archive archive = configs.getArchive(ConfigType.OBJECT.getId());
			ArchiveFiles files = archive.getFiles(storage.loadArchive(archive));
			ObjectLoader loader = new ObjectLoader();

			for (FSFile file : files.getFiles())
			{
				ObjectDefinition object = loader.load(file.getFileId(), file.getContents());
				String name = object.getName();
				if (name == null || "null".equals(name))
				{
					continue;
				}
				named++;
				String lower = name.toLowerCase(Locale.ROOT);
				for (String look : LOOK_FOR)
				{
					if (lower.contains(look))
					{
						candidates.add(object);
						break;
					}
				}
			}
		}

		System.out.printf("%d named objects in the cache, %d look like fire%n%n",
			named, candidates.size());

		candidates.sort((a, b) -> a.getName().compareToIgnoreCase(b.getName()));

		System.out.printf("%-8s %-34s %-5s %-8s %-6s %s%n",
			"id", "name", "size", "matched", "solid", "actions");
		List<String> missed = new ArrayList<>();
		for (ObjectDefinition object : candidates)
		{
			String name = object.getName();
			boolean matched = MATCHED.contains(name.toLowerCase(Locale.ROOT));
			String actions = actionsOf(object);
			System.out.printf("%-8d %-34s %dx%-2d %-8s %-6s %s%n",
				object.getId(), name, object.getSizeX(), object.getSizeY(),
				matched ? "HOT" : "-",
				object.getInteractType() == 0 ? "no" : "yes",
				actions);
			// A thing you can light, or cook on, that the follower would walk
			// straight into.
			if (!matched && (actions.contains("Light") || actions.contains("Cook")
				|| actions.contains("Add logs") || actions.contains("Feed")))
			{
				missed.add(object.getId() + " " + name + " " + actions);
			}
		}

		System.out.println();
		if (missed.isEmpty())
		{
			System.out.println("nothing lightable or cookable is missing from the hot list");
		}
		else
		{
			System.out.println("LIGHTABLE OR COOKABLE AND NOT IN THE HOT LIST:");
			for (String line : missed)
			{
				System.out.println("  " + line);
			}
		}

		System.out.println("\nthe names HotGround matches, and what carries them:");
		for (String wanted : MATCHED)
		{
			List<String> carriers = new ArrayList<>();
			for (ObjectDefinition object : candidates)
			{
				if (object.getName().toLowerCase(Locale.ROOT).equals(wanted))
				{
					carriers.add(String.valueOf(object.getId()));
				}
			}
			System.out.printf("  %-24s %s%n", wanted,
				carriers.isEmpty() ? "NOTHING IN THE GAME IS CALLED THIS" : carriers);
		}
	}

	private static String actionsOf(ObjectDefinition object)
	{
		net.runelite.cache.EntityOpsDefinition ops = object.getOps();
		if (ops == null || ops.getOps() == null)
		{
			return "";
		}
		StringBuilder out = new StringBuilder();
		for (net.runelite.cache.EntityOpsDefinition.Op op : ops.getOps())
		{
			if (op != null && op.text != null && !"null".equals(op.text))
			{
				if (out.length() > 0)
				{
					out.append(", ");
				}
				out.append(op.text);
			}
		}
		return out.toString();
	}
}

