		{4957, "SKILLCAPES_WOODCUTTING_PLAYER_ANIM", 822, "SKILLCAPES_WOODCUTTING_SPOTANIM"},
		{5158, "SKILLCAPES_HUMAN_HUNTING", 907, "SKILLCAPES_HUNTING"},
		{13074, "SKILLCAPES_SAILING_PLAYER_ANIM", 3473, "SKILLCAPES_SAILING_SPOTANIM"},
		{13077, "HUMAN_SKILLCAPE_SAILING", 3560, "SKILLCAPE_SAILING_EMOTE_SPOTANIM"},
		{7121, "MAX_CAPE_PLAYER_ANIM", 1286, "MAX_CAPE"},
		{2709, "DIARY_EMOTE_PLAYERANIM", 323, "SKILLCAPE_DIARY_SPOTANIM"},
	};

	/**
	 * The pairs above that rest on the cache rather than the names: the
	 * graphic's own animation is the one numbered just after the pose. EMOTE_TRICK
	 * is 10503, and the bats' HW23_EMOTE_BAT_SPOTANIM plays 10504.
	 */
	static final List<Integer> CACHE_PAIRED = Arrays.asList(10503);

	private static final String HEADER = "# The Advanced posing window's poses, built by tools/cache-dumper"
		+ " (gradlew runPoseCatalog) from the game cache and RuneLite's gameval names.\n"
		+ "# Every id moves the player's skeleton. play: hold loops until let go, once plays through."
		+ " left/right: what the pose shows in that hand, keep (its own), empty, or an item id.\n"
		+ "# graphic: a spotanim Jagex's names or the cache pair with it, or 0. tier: A named by hand, B named from"
		+ " the game's names, C shown under Show all. restart: the cache's frame step, -1 for none."
		+ " last: the last frame's length in client cycles.\n";

	static final String COLUMNS = "id\tname\tgroup\tplay\tleft\tright\tgraphic\ttier\trestart\tlast";

	private Path cacheDir = Paths.get(System.getProperty("user.home"),
		".runelite", "jagexcache", "oldschool", "LIVE");
	private final Path namesFile = Paths.get("tools/cache-dumper/poses/names.tsv");
	private final Path wordsFile = Paths.get("tools/cache-dumper/poses/words.tsv");
	private final Path outFile = Paths.get("src/main/resources/com/follower/poses.tsv");

	/** What the cache says of one animation. */
	static final class Seq
	{
		int skeleton = -1;
		int restart;
		int last;
		/** As stored: -1 keeps the hand, 0 empties it, 512 and up is an item plus 512. */
		int left;
		int right;
	}

	/** One line of the list. */
	static final class Row
	{
		int id;
		String name;
		String group;
		boolean hold;
		String left;
		String right;
		int graphic;
		char tier;
		int restart;
		int last;
		/** The gameval name the row was named from, or null. */
		String gameval;
		/** The name with its metal, gender and technical words left out, for merging. */
		String key;
	}

	/** A word of a Jagex name: how it reads, and what kind of word it is. */
	static final class Word
	{
		final String kind;
		final String text;

		Word(String kind, String text)
		{
			this.kind = kind;
			this.text = text;
		}
	}

	private final Map<Integer, Seq> seqs = new TreeMap<>();
	private final Map<Integer, ItemDefinition> items = new HashMap<>();
	private final Map<Integer, SpotAnimDefinition> spotanims = new HashMap<>();
	private final Map<Integer, List<String>> animNames = gameval(net.runelite.api.gameval.AnimationID.class);
	private final Map<Integer, List<String>> spotNames = gameval(net.runelite.api.gameval.SpotanimID.class);
	private final Map<String, Word> words = new HashMap<>();

	public static void main(String[] args) throws IOException
	{
		PoseCatalog catalog = new PoseCatalog();
		boolean check = false;
		for (int i = 0; i < args.length; i++)
		{
			switch (args[i])
			{
				case "--check":
					check = true;
					break;
				case "--cache":
					catalog.cacheDir = Paths.get(args[++i]);
					break;
				default:
					throw new IllegalArgumentException("Unknown option " + args[i]);
			}
		}
		catalog.loadCache();
		if (check)
		{
			List<String> problems = catalog.check(Files.readAllLines(catalog.outFile, StandardCharsets.UTF_8));
			problems.forEach(System.out::println);
			System.out.println(problems.isEmpty() ? "poses.tsv agrees with the cache" : problems.size() + " problems");
			System.exit(problems.isEmpty() ? 0 : 1);
		}
		catalog.loadWords();
		List<Row> rows = catalog.build();
		catalog.write(rows);
		catalog.summarise(rows);
	}

	// ------------------------------------------------------------------ cache

	void loadCache() throws IOException
	{
		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index configs = store.getIndex(IndexType.CONFIGS);

			Archive itemArchive = configs.getArchive(ConfigType.ITEM.getId());
			ItemLoader itemLoader = new ItemLoader();
			for (FSFile file : itemArchive.getFiles(storage.loadArchive(itemArchive)).getFiles())
			{
				items.put(file.getFileId(), itemLoader.load(file.getFileId(), file.getContents()));
			}

			Archive spotArchive = configs.getArchive(ConfigType.SPOTANIM.getId());
			SpotAnimLoader spotLoader = new SpotAnimLoader();
			for (FSFile file : spotArchive.getFiles(storage.loadArchive(spotArchive)).getFiles())
			{
				spotanims.put(file.getFileId(), spotLoader.load(file.getFileId(), file.getContents()));
			}

			// The skeleton an animation moves is named at the head of its first
			// frame's archive. A maya animation has no frames of that kind and
			// is left out with the rest that are not the player's.
			Archive seqArchive = configs.getArchive(ConfigType.SEQUENCE.getId());
			SequenceLoader seqLoader = new SequenceLoader().configureForRevision(seqArchive.getRevision());
			Index frames = store.getIndex(IndexType.ANIMATIONS);
			Map<Integer, Integer> archiveSkeleton = new HashMap<>();
			for (FSFile file : seqArchive.getFiles(storage.loadArchive(seqArchive)).getFiles())
			{
				SequenceDefinition def;
				try
				{
					def = seqLoader.load(file.getFileId(), file.getContents());
				}
				catch (RuntimeException unreadable)
				{
					continue;
				}
				Seq seq = new Seq();
				if (def.animMayaID < 0 && def.frameIDs != null && def.frameIDs.length > 0)
				{
					int frameArchive = def.frameIDs[0] >>> 16;
					Integer known = archiveSkeleton.get(frameArchive);
					if (known == null)
					{
						Archive archive = frames.getArchive(frameArchive);
						known = -1;
						if (archive != null)
						{
							byte[] head = archive.getFiles(storage.loadArchive(archive))
								.getFiles().iterator().next().getContents();
							known = ((head[0] & 0xff) << 8) | (head[1] & 0xff);
						}
						archiveSkeleton.put(frameArchive, known);
					}
					seq.skeleton = known;
				}
				seq.restart = def.frameStep;
				int[] lengths = def.frameLengths;
				seq.last = lengths == null || lengths.length == 0 ? 0 : lengths[lengths.length - 1];
				seq.left = def.leftHandItem;
				seq.right = def.rightHandItem;
				seqs.put(file.getFileId(), seq);
			}
		}
	}

	private static Map<Integer, List<String>> gameval(Class<?> type)
	{
		Map<Integer, List<String>> out = new HashMap<>();
		for (Field field : type.getFields())
		{
			if (Modifier.isStatic(field.getModifiers()) && field.getType() == int.class)
			{
				try
				{
					out.computeIfAbsent(field.getInt(null), id -> new ArrayList<>()).add(field.getName());
				}
				catch (IllegalAccessException ignored)
				{
					// Public constants only.
				}
			}
		}
		return out;
	}

	private boolean onPlayerSkeleton(int id)
	{
		Seq seq = seqs.get(id);
		return seq != null && seq.skeleton == PLAYER_SKELETON;
	}

	/** Whether the game loops it, as a loop or as a standing pose. */
	static boolean holds(int restart, int last, List<String> names)
	{
		if (last >= LONG_LAST_FRAME)
		{
			return false;
		}
		if (restart >= 0)
		{
			return true;
		}
		for (String name : names)
		{
			if (isTransition(name))
			{
				continue;
			}
			for (String word : name.split("_"))
			{
				if (word.equals("READY") || word.equals("IDLE"))
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * A clip from one stance into another, named for the move rather than the
	 * stance: a START or an INTO, or a TO that leaves a stance or arrives at
	 * one. A TO that does both is a round trip (READY_TO_CRAWL ... CRAWL_TO_READY)
	 * and ends where it began, and a TO between two other words is no move at
	 * all (BENT_TO_LISTEN_AT_DOOR_IDLE).
	 */
	static boolean isTransition(String name)
	{
		String[] words = name.split("_");
		boolean leaves = false;
		boolean arrives = false;
		for (int i = 0; i < words.length; i++)
		{
			if (words[i].equals("START") || words[i].equals("INTO"))
			{
				return true;
			}
			if (words[i].equals("TO"))
			{
				leaves |= i > 0 && isStanceWord(words[i - 1]);
				arrives |= i + 1 < words.length && isStanceWord(words[i + 1]);
			}
		}
		return leaves != arrives;
	}

	private static boolean isStanceWord(String word)
	{
		return word.equals("READY") || word.equals("IDLE");
	}

	/**
	 * A hand as the window shows it. An item the game has no worn model for is
	 * drawn as nothing, so it is written as an empty hand.
	 */
	private String hand(int stored)
	{
		if (stored < 0)
		{
			return "keep";
		}
		if (stored < 512)
		{
			return "empty";
		}
		ItemDefinition item = items.get(stored - 512);
		return item != null && (item.maleModel0 >= 0 || item.femaleModel0 >= 0)
			? String.valueOf(stored - 512) : "empty";
	}

	// ------------------------------------------------------------------ names

	private void loadWords() throws IOException
	{
		for (String line : Files.readAllLines(wordsFile, StandardCharsets.UTF_8))
		{
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			String[] cells = line.split("\t", -1);
			words.put(cells[0], new Word(cells[1], cells.length > 2 ? cells[2] : ""));
		}
	}

	private Word word(String token)
	{
		return words.get(token);
	}

	/** The gameval name to read: a tier B one when there is one. */
	private String gamevalName(int id)
	{
		List<String> names = animNames.get(id);
		if (names == null || names.isEmpty())
		{
			return null;
		}
		for (String name : names)
		{
			if (TIER_B.matcher(name).find())
			{
				return name;
			}
		}
		return names.get(0);
	}

	/**
	 * The words of a Jagex name, each as long as the dictionary knows it:
	 * GET_UP is one word, as is WALK_F. A token the dictionary does not know
	 * is split at its letter and digit boundaries, so CHAIR1 is a chair and a
	 * 1, and SLOW01 is slow and a 1.
	 */
	private List<String> units(String gameval)
	{
		List<String> tokens = new ArrayList<>();
		for (String token : gameval.split("_"))
		{
			if (token.isEmpty())
			{
				continue;
			}
			if (words.containsKey(token) || !token.matches(".*[A-Z].*\\d.*|.*\\d.*[A-Z].*"))
			{
				tokens.add(token);
				continue;
			}
			tokens.addAll(Arrays.asList(token.split("(?<=[A-Z])(?=\\d)|(?<=\\d)(?=[A-Z])")));
		}
		List<String> out = new ArrayList<>();
		for (int i = 0; i < tokens.size(); )
		{
			int length = Math.min(3, tokens.size() - i);
			while (length > 1 && !words.containsKey(String.join("_", tokens.subList(i, i + length))))
			{
				length--;
			}
			out.add(String.join("_", tokens.subList(i, i + length)));
			i += length;
		}
		return out;
	}

	/**
	 * The name with its metals, genders and technical words left out, so the
	 * bronze and the dragon axe's chop, or a man's and a woman's read, are one.
	 */
	private String key(String gameval)
	{
		StringBuilder key = new StringBuilder();
		for (String unit : units(gameval))
		{
			Word word = word(unit);
			if (word != null && (word.kind.equals("metal") || word.kind.equals("gender")
				|| word.kind.equals("drop")))
			{
				continue;
			}
			key.append(unit).append('_');
		}
		return key.toString();
	}

	/**
	 * A Jagex name in plain words. A verb word leads, as in "Chop a tree", and
	 * the rest follow it in brackets; without one the words are read in
	 * order. A pose word - idle - is only said when there is no verb, since
	 * "Sit" says it already. A quest's or an area's code goes in brackets at
	 * the end.
	 *
	 * @param merged whether the row speaks for its metal and gender copies too,
	 *               and so leaves those words out
	 */
	String readable(String gameval, boolean merged)
	{
		String verb = null;
		List<String> rest = new ArrayList<>();
		List<String> poses = new ArrayList<>();
		List<String> places = new ArrayList<>();
		for (String unit : units(gameval))
		{
			Word word = word(unit);
			if (word == null)
			{
				// A version number - the 01 of SLOW01 - says nothing; two rows
				// it told apart are numbered at the end.
				if (!unit.matches("0\\d+"))
				{
					rest.add(unit.toLowerCase(Locale.ROOT).replace('_', ' '));
				}
				continue;
			}
			switch (word.kind)
			{
				case "drop":
					break;
				case "metal":
				case "gender":
					if (!merged && !word.text.isEmpty())
					{
						rest.add(word.text);
					}
					break;
				case "verb":
					if (verb == null)
					{
						verb = word.text;
					}
					else
					{
						rest.add(word.text.toLowerCase(Locale.ROOT));
					}
					break;
				case "pose":
					poses.add(word.text);
					rest.add(word.text);
					break;
				case "place":
					places.add(word.text);
					break;
				default:
					if (!word.text.isEmpty())
					{
						rest.add(word.text);
					}
					break;
			}
		}
		String text;
		if (verb != null)
		{
			rest.removeAll(poses);
			text = verb + (rest.isEmpty() ? "" : " (" + String.join(" ", rest) + ")");
		}
		else
		{
			text = String.join(" ", rest);
		}
		if (!places.isEmpty())
		{
			text = text + " (" + String.join(", ", places) + ")";
		}
		text = text.trim().replaceAll(" +", " ");
		return text.isEmpty() ? "" : Character.toUpperCase(text.charAt(0)) + text.substring(1);
	}

	static String group(String gameval)
	{
		if (gameval == null)
		{
			return "Other";
		}
		for (String[] pattern : GROUP_PATTERNS)
		{
			if (Pattern.compile(pattern[1]).matcher(gameval).find())
			{
				return pattern[0];
			}
		}
		return "Other";
	}

	// ------------------------------------------------------------------ build

	private List<Row> build() throws IOException
	{
		Map<Integer, Integer> graphics = graphics();

		// Tier A, in the order it is written.
		List<Row> tierA = new ArrayList<>();
		Map<Integer, Row> byId = new LinkedHashMap<>();
		for (String line : Files.readAllLines(namesFile, StandardCharsets.UTF_8))
		{
			if (line.isEmpty() || line.startsWith("#") || line.startsWith("id\t"))
			{
				continue;
			}
			String[] cells = line.split("\t", -1);
			int id = Integer.parseInt(cells[0]);
			if (!onPlayerSkeleton(id))
			{
				throw new IllegalStateException("Tier A " + id + " " + cells[1] + " is not on the player skeleton");
			}
			if (byId.containsKey(id))
			{
				throw new IllegalStateException("Tier A lists " + id + " twice");
			}
			if (Arrays.asList(GROUPS).indexOf(cells[2]) < 0)
			{
				throw new IllegalStateException("Tier A " + id + " has an unknown group " + cells[2]);
			}
			Row row = row(id, 'A', graphics);
			row.name = cells[1];
			row.group = cells[2];
			tierA.add(row);
			byId.put(id, row);
		}

		// Tier B: one row for each move, the first id standing for its copies;
		// a move tier A already has is not offered twice.
		Map<String, Row> moves = new LinkedHashMap<>();
		for (Row row : tierA)
		{
			if (row.gameval != null)
			{
				moves.put(row.hold + "|" + row.key, row);
			}
		}
		List<Row> tierB = new ArrayList<>();
		List<Row> tierC = new ArrayList<>();
		Map<Row, Integer> copies = new HashMap<>();
		for (int id : seqs.keySet())
		{
			if (!onPlayerSkeleton(id) || byId.containsKey(id))
			{
				continue;
			}
			Row row = row(id, 'C', graphics);
			row.group = group(row.gameval);
			if (row.gameval != null && TIER_B.matcher(row.gameval).find())
			{
				String move = row.hold + "|" + row.key;
				Row first = moves.get(move);
				if (first == null)
				{
					row.tier = 'B';
					moves.put(move, row);
					tierB.add(row);
					continue;
				}
				copies.merge(first, 1, Integer::sum);
			}
			tierC.add(row);
		}
		for (Row row : tierB)
		{
			row.name = readable(row.gameval, copies.containsKey(row));
		}
		for (Row row : tierC)
		{
			row.name = row.gameval == null ? "Animation " + row.id : readable(row.gameval, false);
			if (row.name.isEmpty())
			{
				row.name = "Animation " + row.id;
			}
		}

		Comparator<Row> order = Comparator.<Row>comparingInt(row -> Arrays.asList(GROUPS).indexOf(row.group))
			.thenComparing(row -> row.name.toLowerCase(Locale.ROOT))
			.thenComparingInt(row -> row.id);
		tierB.sort(order);
		tierC.sort(order);
		List<Row> out = new ArrayList<>(tierA);
		out.addAll(tierB);
		out.addAll(tierC);
		number(out);
		for (Row row : out)
		{
			for (char c : row.name.toCharArray())
			{
				if (c < 0x20 || c > 0x7e)
				{
					throw new IllegalStateException(row.id + " has a name the game font cannot draw: " + row.name);
				}
			}
		}
		return out;
	}

	/**
	 * Two rows that read the same in the window are told apart by a number,
	 * whatever their tiers: Show all lists them side by side, and so does the
	 * plain list when a tier B move has the name of a tier A one. The first,
	 * which is the named one, keeps its name. A name that already ends in a
	 * number, as HUMAN_STAKE2 reads "Stake (2)", is numbered on from its stem
	 * rather than given a second number.
	 */
	static void number(List<Row> rows)
	{
		Set<String> used = new HashSet<>();
		for (Row row : rows)
		{
			String name = row.name;
			String stem = name.replaceFirst(" \\(\\d+\\)$", "");
			for (int count = 2; !used.add(row.hold + "|" + name.toLowerCase(Locale.ROOT)); count++)
			{
				name = stem + " (" + count + ")";
			}
			row.name = name;
		}
	}

	private Row row(int id, char tier, Map<Integer, Integer> graphics)
	{
		Seq seq = seqs.get(id);
		Row row = new Row();
		row.id = id;
		row.tier = tier;
		row.gameval = gamevalName(id);
		row.key = row.gameval == null ? "#" + id : key(row.gameval);
		List<String> names = animNames.getOrDefault(id, new ArrayList<>());
		row.hold = holds(seq.restart, seq.last, names);
		row.left = hand(seq.left);
		row.right = hand(seq.right);
		row.graphic = graphics.getOrDefault(id, 0);
		row.restart = seq.restart;
		row.last = seq.last;
		return row;
	}

	/**
	 * The paired graphics, each checked by both its names against the
	 * gameval, and a pair the cache makes by the graphic's own animation too.
	 */
	private Map<Integer, Integer> graphics()
	{
		Map<Integer, Integer> out = new HashMap<>();
		for (Object[] pair : GRAPHICS)
		{
			int anim = (Integer) pair[0];
			int spot = (Integer) pair[2];
			if (!animNames.getOrDefault(anim, new ArrayList<>()).contains((String) pair[1])
				|| !spotNames.getOrDefault(spot, new ArrayList<>()).contains((String) pair[3]))
			{
				throw new IllegalStateException("The names no longer pair " + anim + " with graphic " + spot);
			}
			if (!onPlayerSkeleton(anim) || !spotanims.containsKey(spot))
			{
				throw new IllegalStateException("Graphic pair " + anim + "/" + spot + " is not in the cache");
			}
			if (CACHE_PAIRED.contains(anim) && spotanims.get(spot).animationId != anim + 1)
			{
				throw new IllegalStateException("The cache no longer pairs " + anim + " with graphic " + spot);
			}
			out.put(anim, spot);
		}
		return out;
	}

	private void write(List<Row> rows) throws IOException
	{
		StringBuilder out = new StringBuilder(HEADER).append(COLUMNS).append('\n');
		for (Row row : rows)
		{
			out.append(row.id).append('\t').append(row.name).append('\t').append(row.group).append('\t')
				.append(row.hold ? "hold" : "once").append('\t').append(row.left).append('\t')
				.append(row.right).append('\t').append(row.graphic).append('\t').append(row.tier).append('\t')
				.append(row.restart).append('\t').append(row.last).append('\n');
		}
		Files.write(outFile, out.toString().getBytes(StandardCharsets.UTF_8));
	}

	private void summarise(List<Row> rows)
	{
		Map<String, int[]> counts = new LinkedHashMap<>();
		for (String group : GROUPS)
		{
			counts.put(group, new int[3]);
		}
		int holds = 0;
		int props = 0;
		int lying = 0;
		for (Row row : rows)
		{
			counts.get(row.group)[row.tier - 'A']++;
			holds += row.hold ? 1 : 0;
			props += row.left.matches("\\d+") || row.right.matches("\\d+") ? 1 : 0;
			lying += row.last >= LONG_LAST_FRAME ? 1 : 0;
		}
		System.out.println("rows " + rows.size() + ", held " + holds + ", holding an item " + props
			+ ", lying still past a minute " + lying);
		System.out.printf("%-22s %5s %5s %5s%n", "group", "A", "B", "C");
		int[] total = new int[3];
		for (Map.Entry<String, int[]> entry : counts.entrySet())
		{
			int[] c = entry.getValue();
			System.out.printf("%-22s %5d %5d %5d%n", entry.getKey(), c[0], c[1], c[2]);
			for (int i = 0; i < 3; i++)
			{
				total[i] += c[i];
			}
		}
		System.out.printf("%-22s %5d %5d %5d%n", "total", total[0], total[1], total[2]);
	}

	// ------------------------------------------------------------------ check

	/** Every row of a shipped list against the cache, as the game is now. */
	List<String> check(List<String> lines)
	{
		List<String> problems = new ArrayList<>();
		for (String line : lines)
		{
			if (line.isEmpty() || line.startsWith("#") || line.startsWith("id\t"))
			{
				continue;
			}
			String[] cells = line.split("\t", -1);
			int id = Integer.parseInt(cells[0]);
			Seq seq = seqs.get(id);
			if (seq == null)
			{
				problems.add(id + " " + cells[1] + ": not in the cache");
				continue;
			}
			if (seq.skeleton != PLAYER_SKELETON)
			{
				problems.add(id + " " + cells[1] + ": not on the player skeleton");
			}
			if (!hand(seq.left).equals(cells[4]) || !hand(seq.right).equals(cells[5]))
			{
				problems.add(id + " " + cells[1] + ": now holds " + hand(seq.left) + "/" + hand(seq.right));
			}
			if (seq.restart != Integer.parseInt(cells[8]) || seq.last != Integer.parseInt(cells[9]))
			{
				problems.add(id + " " + cells[1] + ": its loop or last frame has changed");
			}
			int graphic = Integer.parseInt(cells[6]);
			if (graphic > 0 && !spotanims.containsKey(graphic))
			{
				problems.add(id + " " + cells[1] + ": graphic " + graphic + " is gone");
			}
		}
		return problems;
	}
}

package com.follower.tools;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import net.runelite.cache.AreaManager;
import net.runelite.cache.WorldMapManager;
import net.runelite.cache.definitions.AreaDefinition;
import net.runelite.cache.definitions.WorldMapElementDefinition;
import net.runelite.cache.fs.Store;
import net.runelite.cache.region.Position;

/**
 * Audits the location rules in phrases.json against the game's own world map.
 *
 * <p>The area rules were written with region ids computed from documented
 * coordinates, which is a guess wherever the documentation is loose. The cache
 * settles it: the world map's labels are {@link AreaDefinition}s carrying the
 * text the game draws ("Lumbridge", "Prifddinas"), and each is PLACED by a
 * {@link WorldMapElementDefinition} at a world position. Name plus position
 * gives the true region id for every named place in the game, with no walking
 * and nothing assumed.
 *
 * <pre>
 *   gradlew runAudit --args="&lt;phrases.json&gt; [cacheDir]"
 * </pre>
 *
 * <p>For each rule it prints the regions the game says that place occupies,
 * and flags any rule whose ids do not include them.
 */
public class RegionAudit
{
	/** Region id from world coordinates, exactly as the client computes it. */
	private static int regionOf(int x, int y)
	{
		return (x >> 6) * 256 + (y >> 6);
	}

	public static void main(String[] args) throws IOException
	{
		Path phrases = args.length > 0
			? Paths.get(args[0])
			: Paths.get(System.getProperty("user.home"), ".runelite", "follower", "phrases.json");
		Path cacheDir = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"), ".runelite", "jagexcache", "oldschool", "LIVE");

		if (!Files.isRegularFile(phrases))
		{
			System.err.println("phrases.json not found: " + phrases);
			System.exit(1);
		}

		// name (lowercased) -> every region the map labels with it
		Map<String, TreeSet<Integer>> mapRegions = new HashMap<>();
		Map<String, TreeSet<String>> mapCoords = new HashMap<>();
		// the reverse: region -> every label the map draws inside it
		Map<Integer, TreeSet<String>> labelsByRegion = new HashMap<>();

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();

			AreaManager areas = new AreaManager(store);
			areas.load();
			Map<Integer, AreaDefinition> byId = new HashMap<>();
			for (AreaDefinition area : areas.getAreas())
			{
				byId.put(area.getId(), area);
			}

			WorldMapManager worldMap = new WorldMapManager(store);
			worldMap.load();

			for (WorldMapElementDefinition element : worldMap.getElements())
			{
				AreaDefinition area = byId.get(element.getAreaDefinitionId());
				Position at = element.getWorldPosition();
				if (area == null || area.getName() == null || at == null)
				{
					continue;
				}
				String key = normalise(area.getName());
				int region = regionOf(at.getX(), at.getY());
				mapRegions.computeIfAbsent(key, k -> new TreeSet<>()).add(region);
				mapCoords.computeIfAbsent(key, k -> new TreeSet<>())
					.add(at.getX() + "," + at.getY());
				labelsByRegion.computeIfAbsent(region, k -> new TreeSet<>()).add(key);
			}
		}

		System.out.printf("World map carries %d distinct labelled place names%n", mapRegions.size());

		JsonObject root;
		try (Reader reader = Files.newBufferedReader(phrases, StandardCharsets.UTF_8))
		{
			root = new Gson().fromJson(reader, JsonObject.class);
		}

		int checked = 0;
		int confirmed = 0;
		List<String> problems = new ArrayList<>();

		for (JsonElement element : root.getAsJsonArray("rules"))
		{
			JsonObject rule = element.getAsJsonObject();
			if (!"area".equals(optString(rule, "group")))
			{
				continue;
			}
			JsonObject when = rule.getAsJsonObject("when");
			if (when == null || !when.has("regions"))
			{
				continue;
			}

			String id = optString(rule, "id");
			List<Integer> ruleRegions = new ArrayList<>();
			for (JsonElement r : when.getAsJsonArray("regions"))
			{
				ruleRegions.add(r.getAsInt());
			}

			// "area-tree-gnome-stronghold" -> "tree gnome stronghold"
			String place = normalise(id.startsWith("area-") ? id.substring(5).replace('-', ' ') : id);
			String label = matchLabel(mapRegions.keySet(), place);
			checked++;

			if (label == null)
			{
				problems.add(String.format("%-24s NO MAP LABEL%s%s",
					id, suggest(mapRegions, place), inside(labelsByRegion, ruleRegions)));
				continue;
			}

			TreeSet<Integer> truth = mapRegions.get(label);
			// A label marks where the map draws its TEXT, near the middle of
			// the place - a town spans several regions, so a rule region one
			// region away is the same town, not an error. Only a rule that
			// lands well clear of every label is actually suspect.
			int best = Integer.MAX_VALUE;
			for (int region : ruleRegions)
			{
				for (int labelled : truth)
				{
					best = Math.min(best, regionDistance(region, labelled));
				}
			}

			if (best == 0)
			{
				confirmed++;
			}
			else if (best <= 1)
			{
				confirmed++;
				System.out.printf("  %-24s adjacent to \"%s\" %s - same place, fine%n",
					id, label, truth);
			}
			else
			{
				problems.add(String.format("%-24s rule %s is %d regions from \"%s\" %s at %s%s",
					id, ruleRegions, best, label, truth, mapCoords.get(label),
					inside(labelsByRegion, ruleRegions)));
			}
		}

		System.out.printf("%n%d location rules checked, %d confirmed against the map%n",
			checked, confirmed);
		if (problems.isEmpty())
		{
			System.out.println("No mismatches.");
			return;
		}
		System.out.printf("%n%d need attention:%n", problems.size());
		for (String problem : problems)
		{
			System.out.println("  " + problem);
		}
	}

	/**
	 * Map labels are drawn text: they carry {@code <br>} line breaks and
	 * punctuation ("Seers'<br>Village"). Flatten to bare lowercase words so a
	 * rule id can be compared to them.
	 */
	private static String normalise(String text)
	{
		return text.toLowerCase()
			.replace("<br>", " ")
			.replaceAll("[^a-z0-9]+", " ")
			.trim();
	}

	/**
	 * What the map actually labels INSIDE the rule's own regions - the
	 * decisive check for underground places, whose surface entrance label
	 * sits regions away from the area the player is standing in.
	 */
	private static String inside(Map<Integer, TreeSet<String>> labelsByRegion, List<Integer> regions)
	{
		TreeSet<String> found = new TreeSet<>();
		for (int region : regions)
		{
			TreeSet<String> here = labelsByRegion.get(region);
			if (here != null)
			{
				found.addAll(here);
			}
		}
		return found.isEmpty()
			? "\n" + " ".repeat(29) + "nothing labelled inside the rule's own regions"
			: "\n" + " ".repeat(29) + "INSIDE those regions the map labels: " + found;
	}

	/** Labels sharing the place's first word, to steer a manual check. */
	private static String suggest(Map<String, TreeSet<Integer>> mapRegions, String place)
	{
		String first = place.split(" ")[0];
		List<String> near = new ArrayList<>();
		for (Map.Entry<String, TreeSet<Integer>> entry : mapRegions.entrySet())
		{
			if (entry.getKey().contains(first))
			{
				near.add("\"" + entry.getKey() + "\" " + entry.getValue());
			}
			if (near.size() == 3)
			{
				break;
			}
		}
		return near.isEmpty() ? " - verify this one in game" : " - map has " + String.join(", ", near);
	}

	/** Chebyshev distance in regions: 0 same, 1 touching, more is far apart. */
	private static int regionDistance(int a, int b)
	{
		int dx = Math.abs((a / 256) - (b / 256));
		int dy = Math.abs((a % 256) - (b % 256));
		return Math.max(dx, dy);
	}

	/**
	 * The map label that best names a rule's place: exact first, then the
	 * most specific label containing the whole place name, then the longest
	 * label the place name contains ("east ardougne" -> "Ardougne").
	 *
	 * <p>Short labels are excluded from that last case. The map has one and
	 * two character labels, and letting those match by containment matched
	 * nearly every rule to the same stray marker.
	 */
	private static String matchLabel(java.util.Set<String> labels, String place)
	{
		if (labels.contains(place))
		{
			return place;
		}
		String best = null;
		for (String label : labels)
		{
			if (label.contains(place) && (best == null || label.length() < best.length()))
			{
				best = label;
			}
		}
		if (best != null)
		{
			return best;
		}
		for (String label : labels)
		{
			if (label.length() >= 5 && place.contains(label)
				&& (best == null || label.length() > best.length()))
			{
				best = label;
			}
		}
		return best;
	}

	private static String optString(JsonObject object, String key)
	{
		return object.has(key) && object.get(key).isJsonPrimitive()
			? object.get(key).getAsString() : null;
	}
}

package com.follower.tools;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.ItemDefinition;
import net.runelite.cache.definitions.NpcDefinition;
import net.runelite.cache.definitions.ObjectDefinition;
import net.runelite.cache.definitions.loaders.ItemLoader;
import net.runelite.cache.definitions.loaders.NpcLoader;
import net.runelite.cache.definitions.loaders.ObjectLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Checks that every NPC name and item id the rules key on exists in the game.
 *
 * <p>These two are the silent failures of the rule file. A rule that watches
 * for an NPC called "Hans " with a trailing space, or "Guard" where the game
 * says "Guard dog", never fires and never says why - it is indistinguishable
 * from a rule whose trigger simply has not happened yet. The same holds for an
 * itemEquipped id that is one digit out.
 *
 * <p>Names are matched the way the plugin matches them: case-insensitively,
 * whole, with {@code *} as a wildcard. So this asks exactly the question the
 * plugin will ask at runtime, against the same cache it will ask it of.
 *
 * <p>The plugin's own Java keeps name lists with the same risk - the superior
 * slayer monsters, the stall guards, the bank, the landmarks - and some of
 * them match exactly, capitals and all, so a name one capital out is just as
 * dead. Those are read from the plugin's source, not copied here, so this
 * checks the list that ships. Each is matched the way its call site matches.
 *
 * <pre>
 *   gradlew runTargetAudit --args="&lt;phrases.json&gt; [cacheDir]"
 * </pre>
 */
public class RuleTargetAudit
{
	public static void main(String[] args) throws IOException
	{
		if (args.length < 1)
		{
			System.out.println("usage: runTargetAudit --args=\"<phrases.json> [cacheDir]\"");
			return;
		}
		Path phrases = Paths.get(args[0]);
		Path cacheDir = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"),
				".runelite", "jagexcache", "oldschool", "LIVE");

		Set<String> npcNames = new HashSet<>();
		Map<Integer, String> items = new TreeMap<>();
		Set<Integer> npcIds = new HashSet<>();
		Map<String, List<Integer>> npcsByName = new TreeMap<>();
		Map<String, List<ObjectDefinition>> objectsByName = new TreeMap<>();

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index configs = store.getIndex(IndexType.CONFIGS);

			Archive npcArchive = configs.getArchive(ConfigType.NPC.getId());
			ArchiveFiles npcFiles = npcArchive.getFiles(storage.loadArchive(npcArchive));
			NpcLoader npcLoader = new NpcLoader();
			for (FSFile file : npcFiles.getFiles())
			{
				NpcDefinition npc = npcLoader.load(file.getFileId(), file.getContents());
				if (npc.name != null && !"null".equals(npc.name))
				{
					npcNames.add(normalise(npc.name));
					npcIds.add(npc.id);
					npcsByName.computeIfAbsent(npc.name, key -> new ArrayList<>()).add(npc.id);
				}
			}

			Archive objectArchive = configs.getArchive(ConfigType.OBJECT.getId());
			ArchiveFiles objectFiles = objectArchive.getFiles(storage.loadArchive(objectArchive));
			ObjectLoader objectLoader = new ObjectLoader();
			for (FSFile file : objectFiles.getFiles())
			{
				ObjectDefinition object = objectLoader.load(file.getFileId(), file.getContents());
				if (object.getName() != null && !"null".equals(object.getName()))
				{
					objectsByName.computeIfAbsent(object.getName(), key -> new ArrayList<>())
						.add(object);
				}
			}

			Archive itemArchive = configs.getArchive(ConfigType.ITEM.getId());
			ArchiveFiles itemFiles = itemArchive.getFiles(storage.loadArchive(itemArchive));
			ItemLoader itemLoader = new ItemLoader();
			for (FSFile file : itemFiles.getFiles())
			{
				ItemDefinition item = itemLoader.load(file.getFileId(), file.getContents());
				if (item.name != null && !"null".equals(item.name))
				{
					items.put(item.id, item.name);
				}
			}
		}

		System.out.printf("cache holds %d named NPCs and %d named items%n%n",
			npcNames.size(), items.size());

		JsonObject file;
		try (Reader reader = Files.newBufferedReader(phrases, StandardCharsets.UTF_8))
		{
			file = new Gson().fromJson(reader, JsonObject.class);
		}

		Map<String, List<String>> namesByRule = new LinkedHashMap<>();
		Map<String, List<Integer>> idsByRule = new LinkedHashMap<>();
		Map<String, List<Integer>> npcIdsByRule = new LinkedHashMap<>();
		for (JsonElement element : file.getAsJsonArray("rules"))
		{
			JsonObject rule = element.getAsJsonObject();
			collect(rule.get("id").getAsString(), rule.getAsJsonObject("when"),
				namesByRule, idsByRule, npcIdsByRule);
		}

		int checkedNames = 0;
		List<String> deadNames = new ArrayList<>();
		for (Map.Entry<String, List<String>> entry : namesByRule.entrySet())
		{
			for (String name : entry.getValue())
			{
				checkedNames++;
				if (!matchesAny(name, npcNames))
				{
					deadNames.add(String.format("%-28s \"%s\"", entry.getKey(), name));
				}
			}
		}

		int checkedItems = 0;
		List<String> deadItems = new ArrayList<>();
		for (Map.Entry<String, List<Integer>> entry : idsByRule.entrySet())
		{
			for (int id : entry.getValue())
			{
				checkedItems++;
				if (!items.containsKey(id))
				{
					deadItems.add(String.format("%-28s item %d", entry.getKey(), id));
				}
			}
		}

		int checkedNpcIds = 0;
		List<String> deadNpcIds = new ArrayList<>();
		for (Map.Entry<String, List<Integer>> entry : npcIdsByRule.entrySet())
		{
			for (int id : entry.getValue())
			{
				checkedNpcIds++;
				if (!npcIds.contains(id))
				{
					deadNpcIds.add(String.format("%-28s npc %d", entry.getKey(), id));
				}
			}
		}

		report("NPC names", checkedNames, deadNames,
			"these rules watch for an NPC the game does not have, so they can never fire");
		report("item ids", checkedItems, deadItems,
			"these rules watch for an item that does not exist");
		report("NPC ids", checkedNpcIds, deadNpcIds,
			"these rules watch for an NPC id that does not exist");

		String source = System.getProperty("follower.source");
		if (source == null)
		{
			System.out.println("the plugin's own lists were NOT audited: run this through"
				+ " gradlew runTargetAudit, which says where the plugin source is");
			return;
		}
		// Each list is matched as its call site matches it: SpectateController
		// isSuperior and SkillingController's stall guard (nearestNpc) exactly, BANK_NAMES
		// and Noticing.isLandmark in any case. Change one, change both.
		Path java = Paths.get(source, "com", "follower", "follower");
		List<String> deadLists = new ArrayList<>();
		int checkedLists = 0;
		checkedLists += auditNpcs("SpectateController.SUPERIOR_NAMES",
			literals(java.resolve("SpectateController.java"), "SUPERIOR_NAMES"),
			npcsByName, deadLists);
		checkedLists += auditNpcs("SkillingController.GUARD_NAMES",
			literals(java.resolve("SkillingController.java"), "GUARD_NAMES"),
			npcsByName, deadLists);
		checkedLists += auditObjects("SkillingController.BANK_NAMES",
			literals(java.resolve("SkillingController.java"), "BANK_NAMES"),
			objectsByName, deadLists);
		checkedLists += auditObjects("Noticing.LANDMARKS",
			literals(java.resolve("Noticing.java"), "LANDMARKS"),
			objectsByName, deadLists);
		report("plugin list names", checkedLists, deadLists,
			"the plugin looks for these and can never find them");
	}

	/**
	 * The quoted names in one field's declaration in the plugin source, up to
	 * its semicolon. Finding none is an error, never an empty pass.
	 */
	private static List<String> literals(Path source, String field) throws IOException
	{
		String text = new String(Files.readAllBytes(source), StandardCharsets.UTF_8);
		int start = text.indexOf(field + " =");
		if (start < 0)
		{
			throw new IllegalStateException(field + " is no longer declared in " + source);
		}
		List<String> names = new ArrayList<>();
		Matcher quoted = Pattern.compile("\"([^\"]*)\"")
			.matcher(text.substring(start, text.indexOf(';', start)));
		while (quoted.find())
		{
			names.add(quoted.group(1));
		}
		if (names.isEmpty())
		{
			throw new IllegalStateException(field + " holds no quoted names in " + source);
		}
		return names;
	}

	/**
	 * Names the plugin compares with equals against NPC.getName(): exact,
	 * capitals and all. The game does not always capitalise one name the same
	 * way twice, so the other spellings the list does not carry are shown:
	 * those NPCs are missed, which may or may not be wanted.
	 */
	private static int auditNpcs(String list, List<String> names,
		Map<String, List<Integer>> npcsByName, List<String> dead)
	{
		System.out.println(list + " (NPC names, exact case):");
		for (String name : names)
		{
			List<String> others = new ArrayList<>();
			for (Map.Entry<String, List<Integer>> entry : npcsByName.entrySet())
			{
				if (entry.getKey().equalsIgnoreCase(name) && !names.contains(entry.getKey()))
				{
					others.add("\"" + entry.getKey() + "\" " + ids(entry.getValue()));
				}
			}
			String unmatched = others.isEmpty() ? "" : "; not matched: " + String.join(", ", others);
			List<Integer> found = npcsByName.get(name);
			if (found != null)
			{
				System.out.printf("  %-32s found %s%s%n", name, ids(found), unmatched);
				continue;
			}
			System.out.printf("  %-32s NOT IN THE GAME%s%n", name, unmatched);
			dead.add(String.format("%-36s \"%s\"", list, name));
		}
		System.out.println();
		return names.size();
	}

	private static String ids(List<Integer> ids)
	{
		return ids.size() <= 8 ? ids.toString() : "(" + ids.size() + " ids)";
	}

	/**
	 * Names the plugin compares against a scene object's name in any case.
	 * Both scans read only the tile's game objects, so a name the cache only
	 * models as a wall, a wall decoration or a ground decoration is never seen
	 * by them either.
	 */
	private static int auditObjects(String list, List<String> names,
		Map<String, List<ObjectDefinition>> objectsByName, List<String> dead)
	{
		System.out.println(list + " (object names, any case, game objects only):");
		for (String name : names)
		{
			int matched = 0;
			int gameObjects = 0;
			Set<String> shapes = new TreeSet<>();
			Set<String> near = new TreeSet<>();
			for (Map.Entry<String, List<ObjectDefinition>> entry : objectsByName.entrySet())
			{
				String candidate = entry.getKey();
				if (!candidate.equalsIgnoreCase(name))
				{
					if (candidate.toLowerCase(Locale.ROOT).contains(name.toLowerCase(Locale.ROOT)))
					{
						near.add("\"" + candidate + "\"");
					}
					continue;
				}
				for (ObjectDefinition object : entry.getValue())
				{
					String shape = shape(object.getObjectTypes());
					matched++;
					shapes.add(shape);
					if (shape.contains("game object"))
					{
						gameObjects++;
					}
				}
			}
			if (gameObjects > 0)
			{
				System.out.printf("  %-32s found, %d of %d as game objects%n",
					name, gameObjects, matched);
				continue;
			}
			if (matched > 0)
			{
				System.out.printf("  %-32s NEVER SEEN BY THE SCAN: %d modelled only as %s%n",
					name, matched, String.join(", ", shapes));
			}
			else
			{
				List<String> some = new ArrayList<>(near).subList(0, Math.min(8, near.size()));
				System.out.printf("  %-32s NOT IN THE GAME%s%n", name, near.isEmpty() ? ""
					: ", nearest " + String.join(", ", some) + (near.size() > 8 ? " ..." : ""));
			}
			dead.add(String.format("%-36s \"%s\"", list, name));
		}
		System.out.println();
		return names.size();
	}

	/**
	 * Where an object can stand, from the shapes the cache has models for. No
	 * shape list means the one default model, a centrepiece's. Walls are 0-3,
	 * wall decorations 4-8 (all drawn from shape 4), game objects 9-21, ground
	 * decorations 22.
	 */
	private static String shape(int[] types)
	{
		if (types == null)
		{
			return "game object";
		}
		Set<String> kinds = new TreeSet<>();
		for (int type : types)
		{
			kinds.add(type <= 3 ? "wall" : type <= 8 ? "wall decoration"
				: type <= 21 ? "game object" : "ground decoration");
		}
		return String.join("/", kinds);
	}

	private static void report(String what, int checked, List<String> dead, String why)
	{
		System.out.printf("%d %s checked, %d dead%n", checked, what, dead.size());
		if (dead.isEmpty())
		{
			System.out.println("  all resolve\n");
			return;
		}
		System.out.println("  " + why + ":");
		for (String line : dead)
		{
			System.out.println("    " + line);
		}
		System.out.println();
	}

	private static void collect(String ruleId, JsonObject condition,
		Map<String, List<String>> names, Map<String, List<Integer>> items,
		Map<String, List<Integer>> npcIds)
	{
		if (condition == null)
		{
			return;
		}
		JsonElement typeElement = condition.get("type");
		String type = typeElement == null ? "" : typeElement.getAsString().toLowerCase(Locale.ROOT);

		if (type.equals("npcspawn") || type.equals("npcdespawn") || type.equals("npcnearby")
			|| type.equals("npckill"))
		{
			JsonArray list = condition.getAsJsonArray("names");
			if (list != null)
			{
				for (JsonElement name : list)
				{
					names.computeIfAbsent(ruleId, key -> new ArrayList<>())
						.add(name.getAsString());
				}
			}
			JsonArray ids = condition.getAsJsonArray("ids");
			if (ids != null)
			{
				for (JsonElement id : ids)
				{
					npcIds.computeIfAbsent(ruleId, key -> new ArrayList<>())
						.add(id.getAsInt());
				}
			}
		}
		if (type.equals("itemequipped"))
		{
			JsonArray ids = condition.getAsJsonArray("ids");
			if (ids != null)
			{
				for (JsonElement id : ids)
				{
					items.computeIfAbsent(ruleId, key -> new ArrayList<>())
						.add(id.getAsInt());
				}
			}
		}

		JsonArray children = condition.getAsJsonArray("conditions");
		if (children != null)
		{
			for (JsonElement child : children)
			{
				collect(ruleId, child.getAsJsonObject(), names, items, npcIds);
			}
		}
	}

	/** The plugin's own matching: whole-name, case-insensitive, {@code *} wildcards. */
	private static boolean matchesAny(String name, Set<String> known)
	{
		String normalised = normalise(name);
		if (normalised.indexOf('*') < 0)
		{
			return known.contains(normalised);
		}
		StringBuilder pattern = new StringBuilder();
		for (String literal : normalised.split("\\*", -1))
		{
			if (pattern.length() > 0)
			{
				pattern.append(".*");
			}
			pattern.append(Pattern.quote(literal));
		}
		Pattern compiled = Pattern.compile(pattern.toString());
		for (String candidate : known)
		{
			if (compiled.matcher(candidate).matches())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The game pads some names with non-breaking spaces; the plugin strips them,
	 * so this has to as well or the comparison is not the one that will run.
	 * Written as a code point: the literal does not survive being carried
	 * through tooling, which is how it arrived here broken the first time.
	 */
	private static String normalise(String name)
	{
		return name.replace((char) 0x00A0, ' ').trim().toLowerCase(Locale.ROOT);
	}
}

package com.follower.tools;

import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.TreeSet;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.NpcDefinition;
import net.runelite.cache.definitions.ObjectDefinition;
import net.runelite.cache.definitions.SequenceDefinition;
import net.runelite.cache.definitions.loaders.NpcLoader;
import net.runelite.cache.definitions.loaders.ObjectLoader;
import net.runelite.cache.definitions.loaders.SequenceLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Checks the names and ids hardcoded in the PLUGIN's own Java against the game.
 *
 * <p>{@link com.follower.tools.RuleTargetAudit} covers the rule file; this
 * covers the other half, which is just as able to fail silently. The errand
 * controller looks for scene objects by name - "Bank booth", "Forester's
 * Campfire" - and an errand whose name matches nothing simply never happens.
 * There is no error, no log line, and nothing to distinguish it from an errand
 * that has not been rolled yet.
 *
 * <p>The pose constants have the same shape of risk one level down: a pose id
 * that is not a sequence in the cache leaves the follower standing still, or
 * sliding along in its idle animation.
 *
 * <pre>
 *   gradlew runSceneAudit
 * </pre>
 */
public class SceneNameAudit
{
	/** Object names ErrandController searches the scene for. */
	private static final String[] OBJECT_NAMES = {
		"Altar", "Bank booth", "Bank chest", "Grand Exchange booth",
		"Fire", "Campfire", "Forester's Campfire",
	};

	/** NPC names it searches for. */
	private static final String[] NPC_NAMES = {
		"Banker", "Grand Exchange Clerk", "Cat", "Kitten", "Stray dog",
	};

	/** PlayerPose, the standard unarmed set every fallback leans on. */
	private static final int[][] POSES = {
		{808, 0}, {819, 0}, {824, 0}, {820, 0}, {821, 0}, {822, 0}, {823, 0},
	};

	private static final String[] POSE_NAMES = {
		"IDLE", "WALK", "RUN", "TURN_180", "SIDESTEP_LEFT", "SIDESTEP_RIGHT", "IDLE_TURN",
	};

	public static void main(String[] args) throws IOException
	{
		Path cacheDir = args.length > 0
			? Paths.get(args[0])
			: Paths.get(System.getProperty("user.home"),
				".runelite", "jagexcache", "oldschool", "LIVE");

		Set<String> objects = new HashSet<>();
		Set<String> npcs = new HashSet<>();
		Set<Integer> sequences = new HashSet<>();

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index configs = store.getIndex(IndexType.CONFIGS);

			Archive objectArchive = configs.getArchive(ConfigType.OBJECT.getId());
			ArchiveFiles objectFiles = objectArchive.getFiles(storage.loadArchive(objectArchive));
			ObjectLoader objectLoader = new ObjectLoader();
			for (FSFile file : objectFiles.getFiles())
			{
				ObjectDefinition object = objectLoader.load(file.getFileId(), file.getContents());
				if (object.getName() != null && !"null".equals(object.getName()))
				{
					objects.add(normalise(object.getName()));
				}
			}

			Archive npcArchive = configs.getArchive(ConfigType.NPC.getId());
			ArchiveFiles npcFiles = npcArchive.getFiles(storage.loadArchive(npcArchive));
			NpcLoader npcLoader = new NpcLoader();
			for (FSFile file : npcFiles.getFiles())
			{
				NpcDefinition npc = npcLoader.load(file.getFileId(), file.getContents());
				if (npc.name != null && !"null".equals(npc.name))
				{
					npcs.add(normalise(npc.name));
				}
			}

			Archive seqArchive = configs.getArchive(ConfigType.SEQUENCE.getId());
			ArchiveFiles seqFiles = seqArchive.getFiles(storage.loadArchive(seqArchive));
			SequenceLoader seqLoader = new SequenceLoader();
			for (FSFile file : seqFiles.getFiles())
			{
				SequenceDefinition sequence = seqLoader.load(file.getFileId(), file.getContents());
				if (sequence != null)
				{
					sequences.add(file.getFileId());
				}
			}
		}

		System.out.printf("cache holds %d named objects, %d named NPCs, %d sequences%n%n",
			objects.size(), npcs.size(), sequences.size());

		List<String> dead = new ArrayList<>();

		System.out.println("errand scene objects:");
		for (String name : OBJECT_NAMES)
		{
			boolean found = objects.contains(normalise(name));
			System.out.printf("  %-24s %s%n", name, found ? "found" : "NOT IN THE GAME");
			if (!found)
			{
				dead.add("object \"" + name + "\"");
			}
		}

		System.out.println("\nerrand NPCs:");
		for (String name : NPC_NAMES)
		{
			boolean found = npcs.contains(normalise(name));
			System.out.printf("  %-24s %s%n", name, found ? "found" : "NOT IN THE GAME");
			if (!found)
			{
				dead.add("npc \"" + name + "\"");
			}
		}

		System.out.println("\nPlayerPose constants:");
		for (int i = 0; i < POSES.length; i++)
		{
			int id = POSES[i][0];
			boolean found = sequences.contains(id);
			System.out.printf("  %-16s %-6d %s%n", POSE_NAMES[i], id,
				found ? "found" : "NOT A SEQUENCE");
			if (!found)
			{
				dead.add("pose " + POSE_NAMES[i] + " (" + id + ")");
			}
		}

		System.out.println();
		if (dead.isEmpty())
		{
			System.out.println("everything the plugin hardcodes resolves against the cache");
		}
		else
		{
			System.out.println("THESE CANNOT EVER MATCH:");
			for (String line : dead)
			{
				System.out.println("  " + line);
			}
		}

		// A near-miss list is what actually helps when something is wrong.
		if (!dead.isEmpty())
		{
			System.out.println("\nnear misses in the cache:");
			for (String line : dead)
			{
				int quote = line.indexOf('"');
				if (quote < 0)
				{
					continue;
				}
				String wanted = normalise(line.substring(quote + 1, line.lastIndexOf('"')));
				String head = wanted.split(" ")[0];
				Set<String> pool = line.startsWith("object") ? objects : npcs;
				Set<String> near = new TreeSet<>();
				for (String candidate : pool)
				{
					if (candidate.contains(head))
					{
						near.add(candidate);
					}
				}
				System.out.printf("  %s -> %s%n", wanted,
					near.isEmpty() ? "(nothing similar)" : near);
			}
		}
	}

	private static String normalise(String name)
	{
		return name.replace((char) 0x00A0, ' ').trim().toLowerCase(Locale.ROOT);
	}
}

package com.follower.tools;

import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.SequenceDefinition;
import net.runelite.cache.definitions.loaders.SequenceLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Prints what an animation id actually IS, so a number taken from anywhere
 * outside the game can be checked before it is trusted.
 *
 * <p>Weapon stances cannot be read from the cache, so ids sometimes have to
 * come from elsewhere. The animation itself still lives in the cache though:
 * an id that does not exist there is simply wrong, and the frame count and
 * duration say whether what does exist is the right shape for the job.
 *
 * <pre>
 *   gradlew runSeqInfo --args="7508 7509 7510 7511"
 * </pre>
 */
public class SequenceInfo
{
	public static void main(String[] args) throws IOException
	{
		Path cacheDir = Paths.get(System.getProperty("user.home"),
			".runelite", "jagexcache", "oldschool", "LIVE");

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index configs = store.getIndex(IndexType.CONFIGS);
			Archive archive = configs.getArchive(ConfigType.SEQUENCE.getId());
			ArchiveFiles files = archive.getFiles(storage.loadArchive(archive));
			SequenceLoader loader = new SequenceLoader();

			for (String arg : args)
			{
				int id;
				try
				{
					id = Integer.parseInt(arg.trim());
				}
				catch (NumberFormatException e)
				{
					continue;
				}

				FSFile file = files.findFile(id);
				if (file == null)
				{
					System.out.printf("%-6d DOES NOT EXIST - the id is wrong%n", id);
					continue;
				}

				SequenceDefinition def = loader.load(id, file.getContents());
				int frames = def.frameIDs == null ? 0 : def.frameIDs.length;
				int ticks = 0;
				if (def.frameLengths != null)
				{
					for (int length : def.frameLengths)
					{
						ticks += length;
					}
				}
				// frameStep is NOT a stance/attack discriminator: pose
				// animations carry -1 just as attacks do, which is why the
				// follower has to loop them defensively. What this tool
				// actually proves is that an id EXISTS and how long it runs.
				System.out.printf("%-6d %2d frames, %3d client ticks (%.2fs), frameStep %d%n",
					id, frames, ticks, ticks * 0.02, def.frameStep);
			}
		}
	}
}

package com.follower.tools;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import javax.imageio.ImageIO;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.SpriteDefinition;
import net.runelite.cache.definitions.loaders.SpriteLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * The pixel size of the interface sprites a window is built from, and a PNG
 * of each, straight from the cache.
 *
 * <p>The API names the sprites but not their sizes, and a frame drawn a pixel
 * off looks wrong in a way that is hard to put a finger on. This prints every
 * frame of every id asked for and writes it out so it can be looked at.
 *
 * <pre>
 *   gradlew runSpriteProbe --args="310 311 312 313 314 315"
 *   gradlew runSpriteProbe --args="--out C:/some/dir 310 311"
 * </pre>
 */
public class SpriteProbe
{
	public static void main(String[] args) throws IOException
	{
		Path cacheDir = Paths.get(System.getProperty("user.home"),
			".runelite", "jagexcache", "oldschool", "LIVE");
		Path out = null;
		java.util.List<Integer> ids = new java.util.ArrayList<>();
		for (int i = 0; i < args.length; i++)
		{
			if ("--out".equals(args[i]) && i + 1 < args.length)
			{
				out = Paths.get(args[++i]);
			}
			else if ("--cache".equals(args[i]) && i + 1 < args.length)
			{
				cacheDir = Paths.get(args[++i]);
			}
			else
			{
				ids.add(Integer.parseInt(args[i]));
			}
		}
		if (out != null)
		{
			Files.createDirectories(out);
		}

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index sprites = store.getIndex(IndexType.SPRITES);
			SpriteLoader loader = new SpriteLoader();

			System.out.printf("%-6s %-5s %-5s %-5s %-6s %-6s %-4s %-4s%n",
				"id", "frame", "w", "h", "maxW", "maxH", "offX", "offY");
			for (int id : ids)
			{
				Archive archive = sprites.getArchive(id);
				if (archive == null)
				{
					System.out.printf("%-6d (no such sprite)%n", id);
					continue;
				}
				FSFile file = archive.getFiles(storage.loadArchive(archive)).findFile(0);
				SpriteDefinition[] frames = loader.load(id, file.getContents());
				for (SpriteDefinition frame : frames)
				{
					System.out.printf("%-6d %-5d %-5d %-5d %-6d %-6d %-4d %-4d%n",
						id, frame.getFrame(), frame.getWidth(), frame.getHeight(),
						frame.getMaxWidth(), frame.getMaxHeight(),
						frame.getOffsetX(), frame.getOffsetY());
					if (out != null && frame.getWidth() > 0 && frame.getHeight() > 0)
					{
						BufferedImage image = new BufferedImage(frame.getWidth(),
							frame.getHeight(), BufferedImage.TYPE_INT_ARGB);
						int[] pixels = frame.getPixels();
						for (int y = 0; y < frame.getHeight(); y++)
						{
							for (int x = 0; x < frame.getWidth(); x++)
							{
								int argb = pixels[y * frame.getWidth() + x];
								// The loader hands back 0 for the transparent colour.
								image.setRGB(x, y, argb == 0 ? 0 : 0xFF000000 | argb);
							}
						}
						ImageIO.write(image, "png",
							out.resolve(id + "_" + frame.getFrame() + ".png").toFile());
					}
				}
			}
		}
	}
}

package com.follower.tools;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import net.runelite.cache.IndexType;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * The last and broadest search for weapon stance data: item params, item
 * category and structs were all ruled out, but the cache library only names
 * the config archives it happens to know about. The pose table could sit in an
 * archive nobody has named.
 *
 * <p>So this looks everywhere, without assuming a format. Every archive of
 * every index, every file, scanned for 16-bit values matching the pose ids the
 * plugin has genuinely observed. A file holding two or more of them is a
 * stance record - the numbers are far too specific to co-occur by chance.
 *
 * <pre>
 *   gradlew runArchiveProbe --args="&lt;stances.json&gt;"
 * </pre>
 */
public class StanceArchiveProbe
{
	public static void main(String[] args) throws IOException
	{
		Path stancesFile = args.length > 0
			? Paths.get(args[0])
			: Paths.get(System.getProperty("user.home"), ".runelite", "follower", "stances.json");
		Path cacheDir = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"), ".runelite", "jagexcache", "oldschool", "LIVE");

		JsonObject stances;
		try (Reader reader = Files.newBufferedReader(stancesFile, StandardCharsets.UTF_8))
		{
			stances = new Gson().fromJson(reader, JsonObject.class);
		}

		// Pose ids we have actually seen, and the triples they came in.
		Set<Integer> poseIds = new TreeSet<>();
		Map<String, String> tripleOwner = new TreeMap<>();
		for (Map.Entry<String, JsonElement> entry : stances.entrySet())
		{
			JsonObject stance = entry.getValue().getAsJsonObject();
			int idle = stance.get("idle").getAsInt();
			int walk = stance.get("walk").getAsInt();
			int run = stance.get("run").getAsInt();
			if (idle > 0 && walk > 0)
			{
				poseIds.add(idle);
				poseIds.add(walk);
				poseIds.add(run);
				tripleOwner.put(idle + "/" + walk + "/" + run, entry.getKey());
			}
		}
		System.out.printf("looking for %d observed pose ids from %d stance classes%n",
			poseIds.size(), tripleOwner.size());

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();

			int filesScanned = 0;
			Map<String, Integer> hitsByArchive = new TreeMap<>();
			int reported = 0;

			for (Index index : store.getIndexes())
			{
				// Maps and models are megabytes of geometry; a 16-bit scan
				// there is all false positives and no signal.
				if (index.getId() == IndexType.MAPS.getNumber()
					|| index.getId() == IndexType.MODELS.getNumber()
					|| index.getId() == IndexType.SPRITES.getNumber()
					|| index.getId() == IndexType.MUSIC_TRACKS.getNumber())
				{
					continue;
				}

				for (Archive archive : index.getArchives())
				{
					byte[] raw;
					try
					{
						raw = storage.loadArchive(archive);
						if (raw == null)
						{
							continue;
						}
						ArchiveFiles files = archive.getFiles(raw);
						for (FSFile file : files.getFiles())
						{
							byte[] data = file.getContents();
							if (data == null || data.length < 4)
							{
								continue;
							}
							filesScanned++;
							Set<Integer> found = scan(data, poseIds);
							if (found.size() >= 2)
							{
								String key = "index " + index.getId() + " archive " + archive.getArchiveId();
								hitsByArchive.merge(key, 1, Integer::sum);
								if (reported++ < 12)
								{
									System.out.printf("  %s file %d holds %s%n",
										key, file.getFileId(), new TreeSet<>(found));
								}
							}
						}
					}
					catch (RuntimeException e)
					{
						// Encrypted or unreadable archive; nothing to learn here.
					}
				}
			}

			System.out.printf("%n%d files scanned%n", filesScanned);
			if (hitsByArchive.isEmpty())
			{
				System.out.println();
				System.out.println("Nothing anywhere in the cache pairs these pose ids.");
				System.out.println("Weapon stances are assembled by the client at runtime, not");
				System.out.println("stored as a table - observation really is the only source.");
			}
			else
			{
				System.out.println();
				System.out.println("archives holding paired pose ids:");
				for (Map.Entry<String, Integer> hit : hitsByArchive.entrySet())
				{
					System.out.printf("  %-28s %d files%n", hit.getKey(), hit.getValue());
				}
			}
		}
	}

	/** Every observed pose id appearing as a 16-bit big-endian value. */
	private static Set<Integer> scan(byte[] data, Set<Integer> poseIds)
	{
		Set<Integer> found = new HashSet<>();
		for (int i = 0; i + 1 < data.length; i++)
		{
			int value = ((data[i] & 0xFF) << 8) | (data[i + 1] & 0xFF);
			if (poseIds.contains(value))
			{
				found.add(value);
			}
		}
		return found;
	}
}

package com.follower.tools;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.EnumDefinition;
import net.runelite.cache.definitions.loaders.EnumLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;

/**
 * Chases the one lead the broad archive sweep left standing: 41 ENUM files
 * hold two or more real pose ids. Enums are how the game keys tables off item
 * ids, so if a weapon's stance is data anywhere, it is here.
 *
 * <p>This decodes every enum properly rather than scanning bytes, and reports
 * any whose values include observed pose ids - with its key type, so we can
 * see whether it is keyed BY ITEM (which would give a direct weapon to stance
 * mapping) or by something else.
 *
 * <pre>
 *   gradlew runEnumProbe --args="&lt;stances.json&gt;"
 * </pre>
 */
public class StanceEnumProbe
{
	public static void main(String[] args) throws IOException
	{
		Path stancesFile = args.length > 0
			? Paths.get(args[0])
			: Paths.get(System.getProperty("user.home"), ".runelite", "follower", "stances.json");
		Path cacheDir = args.length > 1
			? Paths.get(args[1])
			: Paths.get(System.getProperty("user.home"), ".runelite", "jagexcache", "oldschool", "LIVE");

		JsonObject stances;
		try (Reader reader = Files.newBufferedReader(stancesFile, StandardCharsets.UTF_8))
		{
			stances = new Gson().fromJson(reader, JsonObject.class);
		}

		Set<Integer> poseIds = new TreeSet<>();
		Map<Integer, String> weaponStance = new HashMap<>();
		for (Map.Entry<String, JsonElement> entry : stances.entrySet())
		{
			JsonObject stance = entry.getValue().getAsJsonObject();
			int idle = stance.get("idle").getAsInt();
			int walk = stance.get("walk").getAsInt();
			int run = stance.get("run").getAsInt();
			if (idle <= 0 || walk <= 0)
			{
				continue;
			}
			poseIds.add(idle);
			poseIds.add(walk);
			poseIds.add(run);
			try
			{
				weaponStance.put(Integer.parseInt(entry.getKey()), idle + "/" + walk + "/" + run);
			}
			catch (NumberFormatException ignored)
			{
				// not an item id
			}
		}

		try (Store store = new Store(cacheDir.toFile()))
		{
			store.load();
			Storage storage = store.getStorage();
			Index configs = store.getIndex(IndexType.CONFIGS);
			Archive archive = configs.getArchive(ConfigType.ENUM.getId());
			ArchiveFiles files = archive.getFiles(storage.loadArchive(archive));
			EnumLoader loader = new EnumLoader();

			int total = 0;
			int interesting = 0;

			for (FSFile file : files.getFiles())
			{
				total++;
				EnumDefinition def = loader.load(file.getFileId(), file.getContents());
				if (def == null)
				{
					continue;
				}
				int[] vals = def.getIntVals();
				int[] keys = def.getKeys();
				if (vals == null || keys == null)
				{
					continue;
				}

				Set<Integer> found = new HashSet<>();
				for (int value : vals)
				{
					if (poseIds.contains(value))
					{
						found.add(value);
					}
				}
				if (found.size() < 2)
				{
					continue;
				}
				interesting++;

				// The decisive question: are the KEYS weapons we know? If an
				// enum keyed by item id maps our weapons to their real pose
				// ids, every weapon in the game resolves without observation.
				int keyedWeapons = 0;
				int agreeing = 0;
				for (int i = 0; i < keys.length && i < vals.length; i++)
				{
					String known = weaponStance.get(keys[i]);
					if (known != null)
					{
						keyedWeapons++;
						if (known.startsWith(vals[i] + "/") || known.contains("/" + vals[i]))
						{
							agreeing++;
						}
					}
				}

				System.out.printf("enum %-6d key=%-12s val=%-12s size=%-5d pose ids %s%n",
					def.getId(), def.getKeyType(), def.getValType(), def.getSize(),
					new TreeSet<>(found));
				if (keyedWeapons > 0)
				{
					System.out.printf("        keys include %d weapons we know, %d agree%s%n",
						keyedWeapons, agreeing,
						agreeing == keyedWeapons ? "   <-- THIS MAPS WEAPONS TO POSES" : "");
				}
			}

			System.out.printf("%n%d enums, %d hold two or more real pose ids%n", total, interesting);
		}
	}
}

package com.follower.tools;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
